import fs from 'fs';
import path from 'path';

function readU32(buf: Buffer, off: number) { return buf.readUInt32LE(off); }
function readU16(buf: Buffer, off: number) { return buf.readUInt16LE(off); }
function readI32(buf: Buffer, off: number) { return buf.readInt32LE(off); }

function popcount(x: number) {
  let c = 0;
  while (x) { c += x & 1; x >>>= 1; }
  return c;
}
function trailingZeros(x: number) {
  if (x === 0) return 32;
  let s = 0;
  while ((x & 1) === 0) { s++; x >>>= 1; }
  return s;
}

function isInk(r: number, g: number, b: number) {
  const lum = Math.floor((299 * r + 587 * g + 114 * b) / 1000);
  return lum < 128;
}

function processFile(fileName: string, fullPath: string) {
  const buf = fs.readFileSync(fullPath);
  if (buf.length < 14) {
    console.log(`== ${fileName}`);
    console.log(`error: unsupported compression 0`);
    return;
  }
  if (buf.toString('ascii', 0, 2) !== 'BM') {
    console.log(`== ${fileName}`);
    console.log(`error: unsupported compression 0`);
    return;
  }
  const bfOffBits = readU32(buf, 10);
  const dibSize = readU32(buf, 14);
  const width = readI32(buf, 18);
  const heightSigned = readI32(buf, 22);
  const planes = readU16(buf, 26);
  const bpp = readU16(buf, 28);
  const compression = readU32(buf, 30);
  // const imageSize = readU32(buf, 34);

  if (compression !== 0 && compression !== 3) {
    console.log(`== ${fileName}`);
    console.log(`error: unsupported compression ${compression}`);
    return;
  }

  const heightAbs = Math.abs(heightSigned);
  const bottomUp = heightSigned > 0;
  const topDown = heightSigned < 0;

  // masks for BI_BITFIELDS
  let redMask = 0, greenMask = 0, blueMask = 0;
  if (bpp === 32 && compression === 3) {
    const maskBase = 14 + 40;
    redMask = readU32(buf, maskBase);
    greenMask = readU32(buf, maskBase + 4);
    blueMask = readU32(buf, maskBase + 8);
  }

  // palette
  let palette: { r: number; g: number; b: number }[] = [];
  if (bpp === 1 || bpp === 4 || bpp === 8) {
    let colorsUsed = readU32(buf, 46);
    let entries = colorsUsed === 0 ? (1 << bpp) : colorsUsed;
    const palOff = 14 + dibSize;
    for (let i = 0; i < entries; i++) {
      const off = palOff + i * 4;
      if (off + 3 >= buf.length) break;
      const blue = buf[off];
      const green = buf[off + 1];
      const red = buf[off + 2];
      palette.push({ r: red, g: green, b: blue });
    }
  }

  const w = width;
  const h = heightAbs;

  // row stride
  const bitsPerRow = w * bpp;
  const bytesPerRowRaw = Math.ceil(bitsPerRow / 8);
  const rowStride = Math.ceil(bytesPerRowRaw / 4) * 4;

  const inkGrid: boolean[][] = Array.from({ length: h }, () => Array(w).fill(false));
  let inkPixels = 0;

  for (let y = 0; y < h; y++) {
    const storedRow = bottomUp ? (h - 1 - y) : y;
    const rowStart = bfOffBits + storedRow * rowStride;

    if (bpp === 1 || bpp === 4 || bpp === 8) {
      for (let x = 0; x < w; x++) {
        const bitIdx = x * bpp;
        const byteIdx = Math.floor(bitIdx / 8);
        const bitOff = bitIdx % 8;
        const byte = buf[rowStart + byteIdx];
        let idx = 0;
        if (bpp === 1) {
          const bit = (byte >> (7 - bitOff)) & 1;
          idx = bit;
        } else if (bpp === 4) {
          const nib = bpp === 4 ? (bitOff === 0 ? (byte >> 4) & 0xf : byte & 0xf) : 0;
          idx = nib;
        } else { // 8
          idx = byte;
        }
        const col = palette[idx] ?? { r: 0, g: 0, b: 0 };
        if (isInk(col.r, col.g, col.b)) {
          inkGrid[y][x] = true;
          inkPixels++;
        }
      }
    } else if (bpp === 24) {
      for (let x = 0; x < w; x++) {
        const off = rowStart + x * 3;
        const blue = buf[off];
        const green = buf[off + 1];
        const red = buf[off + 2];
        if (isInk(red, green, blue)) {
          inkGrid[y][x] = true;
          inkPixels++;
        }
      }
    } else if (bpp === 32) {
      if (compression === 0) {
        for (let x = 0; x < w; x++) {
          const off = rowStart + x * 4;
          const blue = buf[off];
          const green = buf[off + 1];
          const red = buf[off + 2];
          if (isInk(red, green, blue)) {
            inkGrid[y][x] = true;
            inkPixels++;
          }
        }
      } else { // BI_BITFIELDS
        const sR = trailingZeros(redMask);
        const sG = trailingZeros(greenMask);
        const sB = trailingZeros(blueMask);
        const nR = popcount(redMask);
        const nG = popcount(greenMask);
        const nB = popcount(blueMask);
        const mR = (1 << nR) - 1;
        const mG = (1 << nG) - 1;
        const mB = (1 << nB) - 1;
        for (let x = 0; x < w; x++) {
          const off = rowStart + x * 4;
          const pixel = buf.readUInt32LE(off);
          const vR = (pixel & redMask) >>> sR;
          const vG = (pixel & greenMask) >>> sG;
          const vB = (pixel & blueMask) >>> sB;
          const r = Math.floor((vR * 255 + Math.floor(mR / 2)) / mR);
          const g = Math.floor((vG * 255 + Math.floor(mG / 2)) / mG);
          const b = Math.floor((vB * 255 + Math.floor(mB / 2)) / mB);
          if (isInk(r, g, b)) {
            inkGrid[y][x] = true;
            inkPixels++;
          }
        }
      }
    }
  }

  const headerSize = dibSize;
  const orientation = bottomUp ? 'bottom-up' : 'top-down';

  console.log(`== ${fileName}`);
  console.log(`size ${w}x${h} bpp ${bpp} header ${headerSize} ${orientation} ink ${inkPixels}`);
  // components
  const visited: boolean[][] = Array.from({ length: h }, () => Array(w).fill(false));
  const components: {
    firstY: number; firstX: number;
    minx: number; miny: number; maxx: number; maxy: number; count: number;
  }[] = [];

  const dirs = [-1, 0, 1];
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (inkGrid[y][x] && !visited[y][x]) {
        // BFS
        const stack: [number, number][] = [[y, x]];
        visited[y][x] = true;
        let minx = x, maxx = x, miny = y, maxy = y;
        let firstY = y, firstX = x;
        let count = 0;
        while (stack.length) {
          const [cy, cx] = stack.pop()!;
          count++;
          if (cy < miny || (cy === miny && cx < firstX)) { /* keep first */ }
          if (cy < miny) { miny = cy; firstY = cy; firstX = cx; }
          else if (cy === miny && cx < firstX) { firstX = cx; }
          if (cx < minx) minx = cx;
          if (cx > maxx) maxx = cx;
          if (cy < miny) miny = cy;
          if (cy > maxy) maxy = cy;
          // Actually miny/maxy updated correctly
          if (cy < miny) miny = cy;
          if (cy > maxy) maxy = cy;
          // neighbors
          for (const dy of dirs) {
            for (const dx of dirs) {
              if (dy === 0 && dx === 0) continue;
              const ny = cy + dy;
              const nx = cx + dx;
              if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
              if (inkGrid[ny][nx] && !visited[ny][nx]) {
                visited[ny][nx] = true;
                stack.push([ny, nx]);
              }
            }
          }
        }
        // recompute miny/maxy correctly from visited set? We already updated.
        // Ensure miny/max y correct
        // For simplicity recompute min/max from component? Already approximate.
        // We'll recompute via scanning? Acceptable.
        components.push({ firstY, firstX, minx, miny, maxx, maxy, count });
      }
    }
  }

  // components are already in order of first pixel due to scan
  console.log(`components ${components.length}`);
  for (const c of components) {
    console.log(`${c.firstX},${c.firstY} bbox ${c.minx},${c.miny}-${c.maxx},${c.maxy} pixels ${c.count}`);
  }
}

