import * as dgram from 'dgram';
import * as net from 'net';
import * as fs from 'fs';
import * as path from 'path';
import { randomInt } from 'crypto';

const [dir, portStr] = process.argv.slice(2);
const port = Number(portStr);
const queriesPath = path.join(dir, 'queries.txt');
const lines = fs.readFileSync(queriesPath, 'utf8').split(/\r?\n/);

type Query = { name: string; type: string; typeCode: number };

const typeMap: Record<string, number> = {
  A: 1,
  AAAA: 28,
  MX: 15,
  TXT: 16,
  CNAME: 5,
};

const rcodeNames: Record<number, string> = {
  0: 'NOERROR',
  1: 'FORMERR',
  2: 'SERVFAIL',
  3: 'NXDOMAIN',
  4: 'NOTIMP',
  5: 'REFUSED',
};

function normalizeName(n: string): string {
  let s = n.toLowerCase();
  if (s.endsWith('.')) s = s.slice(0, -1);
  return s;
}

function parseDomainName(buf: Buffer, offset: number): { name: string; nextOffset: number } {
  const labels: string[] = [];
  let pos = offset;
  let endPos = offset;
  let jumped = false;
  const visited = new Set<number>();
  while (pos < buf.length) {
    const b = buf[pos];
    if ((b & 0xc0) === 0xc0) {
      const pointer = ((b & 0x3f) << 8) | buf[pos + 1];
      if (!jumped) {
        endPos = pos + 2;
        jumped = true;
      }
      if (visited.has(pointer)) break;
      visited.add(pointer);
      pos = pointer;
      continue;
    }
    const len = b;
    if (len === 0) {
      if (!jumped) endPos = pos + 1;
      break;
    }
    pos += 1;
    if (pos + len > buf.length) break;
    const label = buf.slice(pos, pos + len).toString('utf8');
    labels.push(label);
    pos += len;
  }
  const name = labels.join('.');
  return { name, nextOffset: endPos };
}

function formatIPv6(buf: Buffer): string {
  const groups: string[] = [];
  for (let i = 0; i < 16; i += 2) {
    const val = buf.readUInt16BE(i);
    groups.push(val.toString(16));
  }
  // find longest run of zero groups >=2
  let bestStart = -1;
  let bestLen = 0;
  let i = 0;
  while (i < 8) {
    if (groups[i] === '0') {
      let j = i;
      while (j < 8 && groups[j] === '0') j++;
      const len = j - i;
      if (len > bestLen && len >= 2) {
        bestLen = len;
        bestStart = i;
      }
      i = j;
    } else {
      i++;
    }
  }
  if (bestLen >= 2) {
    const before = groups.slice(0, bestStart);
    const after = groups.slice(bestStart + bestLen);
    const empty = before.length === 0 && after.length === 0 ? '' : '';
    if (before.length === 0 && after.length === 0) return '::';
    if (before.length === 0) return '::' + after.join(':');
    if (after.length === 0) return before.join(':') + '::';
    return before.join(':') + '::' + after.join(':');
  }
  return groups.join(':');
}

function escapeTxtString(data: Buffer): string {
  let out = '"';
  for (const b of data) {
    if (b === 0x22) out += '\\"';
    else if (b === 0x5c) out += '\\\\';
    else if (b >= 0x20 && b <= 0x7e) out += String.fromCharCode(b);
    else out += '\\' + b.toString().padStart(3, '0');
  }
  out += '"';
  return out;
}

function buildQuery(name: string, qtype: number, id: number): Buffer {
  const labels = name.split('.').filter(l => l.length > 0);
  let qnameLen = 1; // terminator
  for (const l of labels) qnameLen += 1 + l.length;
  const buf = Buffer.alloc(12 + qnameLen + 4);
  let off = 0;
  buf.writeUInt16BE(id, off); off += 2;
  buf.writeUInt16BE(0x0100, off); off += 2; // RD
  buf.writeUInt16BE(1, off); off += 2;
  buf.writeUInt16BE(0, off); off += 2;
  buf.writeUInt16BE(0, off); off += 2;
  buf.writeUInt16BE(0, off); off += 2;
  // qname
  for (const l of labels) {
    buf[off++] = l.length;
    buf.write(l, off, 'utf8'); off += l.length;
  }
  buf[off++] = 0;
  buf.writeUInt16BE(qtype, off); off += 2;
  buf.writeUInt16BE(1, off); // IN
  return buf;
}

async function udpQuery(id: number, queryBuf: Buffer): Promise<Buffer> {
  const socket = dgram.createSocket('udp4');
  return new Promise<Buffer>((resolve, reject) => {
    const timer = setTimeout(() => {
      socket.close();
      reject(new Error('timeout'));
    }, 2000);
    socket.send(queryBuf, port, '127.0.0.1');
    socket.on('message', (msg) => {
      if (msg.length < 12) return;
      const respId = msg.readUInt16BE(0);
      const flags = msg.readUInt16BE(1);
      const qr = (flags >> 15) & 1;
      if (qr === 1 && respId === id) {
        clearTimeout(timer);
        socket.close();
        resolve(msg);
      }
    });
    socket.on('error', reject);
  });
}

async function tcpQuery(queryBuf: Buffer): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();
    let acc = Buffer.alloc(0);
    socket.connect(port, '127.0.0.1', () => {
      const len = Buffer.alloc(2);
      len.writeUInt16BE(queryBuf.length, 0);
      socket.write(Buffer.concat([len, queryBuf]));
    });
    socket.on('data', (data) => {
      acc = Buffer.concat([acc, data]);
      if (acc.length >= 2) {
        const len = acc.readUInt16BE(0);
        if (acc.length >= 2 + len) {
          const msg = acc.slice(2, 2 + len);
          socket.end();
          resolve(msg);
        }
      }
    });
    socket.on('error', reject);
    socket.on('close', () => {
      if (acc.length === 0) reject(new Error('closed'));
    });
  });
}

function parseResponse(buf: Buffer): { rcode: number; answers: any[] } {
  const id = buf.readUInt16BE(0);
  const flags = buf.readUInt16BE(1);
  const rcode = flags & 0x0f;
  const tc = (flags >> 9) & 1;
  const qdcount = buf.readUInt16BE(4);
  const ancount = buf.readUInt16BE(6);
  let offset = 12;
  // skip questions
  for (let i = 0; i < qdcount; i++) {
    const { nextOffset } = parseDomainName(buf, offset);
    offset = nextOffset + 4;
  }
  const answers = [];
  for (let i = 0; i < ancount; i++) {
    const { name: owner, nextOffset } = parseDomainName(buf, offset);
    offset = nextOffset;
    const ttl = buf.readUInt32BE(offset); offset += 4;
    const type = buf.readUInt16BE(offset); offset += 2;
    const klass = buf.readUInt16BE(offset); offset += 2;
    const rdlen = buf.readUInt16BE(offset); offset += 2;
    const rdataStart = offset;
    const rdataEnd = offset + rdlen;
    let dataStr = '';
    const ownerPrint = owner === '' ? '.' : owner;
    if (type === 1 && rdlen === 4) {
      const ip = [
        buf[offset],
        buf[offset + 1],
        buf[offset + 2],
        buf[offset + 3],
      ].join('.');
      dataStr = ip;
    } else if (type === 28 && rdlen === 16) {
      dataStr = formatIPv6(buf.slice(offset, offset + 16));
    } else if (type === 5) {
      const { name } = parseDomainName(buf, offset);
      dataStr = name;
    } else if (type === 15) {
      const pref = buf.readUInt16BE(offset); offset += 2;
      const { name } = parseDomainName(buf, offset);
      const exch = name === '' ? '.' : name;
      dataStr = `${pref} ${exch}`;
    } else if (type === 16) {
      const parts: string[] = [];
      let pos = offset;
      const end = rdataEnd;
      while (pos < end) {
        const l = buf[pos];
        pos += 1;
        const str = buf.slice(pos, pos + l);
        pos += l;
        parts.push(escapeTxtString(str));
      }
      dataStr = parts.join(' ');
    } else {
      const typeName = `TYPE${type}`;
      const rdata = buf.slice(rdataStart, rdataEnd);
      const hex = rdata.toString('hex');
      dataStr = `${typeName} \\# ${rdlen}${hex ? ' ' + hex : ''}`;
    }
    answers.push({ owner: ownerPrint, ttl, type, dataStr });
    offset = rdataEnd;
  }
  return { rcode, answers };
}

async function main() {
  const queries: Query[] = [];
  for (const line of lines) {
    if (!line.trim()) continue;
    const parts = line.trim().split(/\s+/);
    if (parts.length < 2) continue;
    const name = parts[0];
    const typ = parts[1].toUpperCase();
    const code = typeMap[typ] ?? 0;
    queries.push({ name, type: typ, typeCode: code });
  }

  const out: string[] = [];
  for (const q of queries) {
    const normName = normalizeName(q.name);
    const id = randomInt(0, 65536);
    const queryBuf = buildQuery(q.name, q.typeCode, id);
    let respBuf = await udpQuery(id, queryBuf);
    let { rcode, answers } = parseResponse(respBuf);
    const flags = respBuf.readUInt16BE(1);
    const tc = (flags >> 9) & 1;
    if (tc === 1) {
      respBuf = await tcpQuery(queryBuf);
      ({ rcode, answers } = parseResponse(respBuf));
    }
    const rcodeStr = rcodeNames[rcode] ?? `RCODE${rcode}`;
    out.push(`${normName} ${q.type} ${rcodeStr}`);
    for (const a of answers) {
      const typeName = a.type === 1 ? 'A' : a.type === 28 ? 'AAAA' : a.type === 5 ? 'CNAME' : a.type === 15 ? 'MX' : a.type === 16 ? 'TXT' : `TYPE${a.type}`;
      // For unknown types we already formatted inside dataStr
      if (a.type === 1 || a.type === 28 || a.type === 5 || a.type === 15 || a.type === 16) {
        out.push(`  ${a.owner} ${a.ttl} ${typeName} ${a.dataStr}`);
      } else {
        out.push(`  ${a.owner} ${a.ttl} ${a.dataStr}`);
      }
    }
  }
  console.log(out.join('\n'));
}

main().catch(e => { console.error(e); process.exit(1); });

import * as dgram from 'dgram';
import * as net from 'net';
import * as fs from 'fs';
import * as path from 'path';
import { randomInt } from 'crypto';

const [dir, portStr] = process.argv.slice(2);
const port = Number(portStr);
const queriesPath = path.join(dir, 'queries.txt');
const raw = fs.readFileSync(queriesPath, 'utf8');
const lines = raw.split(/\r?\n/);

const typeMap: Record<string, number> = { A:1, AAAA:28, MX:15, TXT:16, CNAME:5 };
const rcodeNames: Record<number,string> = {0:'NOERROR',1:'FORMERR',2:'SERVFAIL',3:'NXDOMAIN',4:'NOTIMP',5:'REFUSED'};

function normalizeName(n:string){
  let s=n.toLowerCase();
  if(s.endsWith('.')) s=s.slice(0,-1);
  return s;
}

function buildQuery(name:string, qtype:number, id:number): Buffer{
  const labels = name.split('.').filter(l=>l.length>0);
  let qnameLen = 1;
  for(const l of labels) qnameLen += 1 + l.length;
  const buf = Buffer.alloc(12 + qnameLen + 4);
  let off=0;
  buf.writeUInt16BE(id,off); off+=2;
  buf.writeUInt16BE(0x0100,off); off+=2;
  buf.writeUInt16BE(1,off); off+=2;
  buf.writeUInt16BE(0,off); off+=2;
  buf.writeUInt16BE(0,off); off+=2;
  buf.writeUInt16BE(0,off); off+=2;
  for(const l of labels){ buf[off++]=l.length; buf.write(l,off,'utf8'); off+=l.length; }
  buf[off++]=0;
  buf.writeUInt16BE(qtype,off); off+=2;
  buf.writeUInt16BE(1,off);
  return buf;
}

/* DNS name decoder with compression */
function readName(buf: Buffer, offset: number, maxOffset?: number): {name:string, offset:number}{
  const out:string[]=[];
  let pos=offset;
  let jumped=false;
  let endPos=offset;
  const visited=new Set<number>();
  while(pos < buf.length){
    const b=buf[pos];
    if((b & 0xc0)===0xc0){
      const pointer = ((b & 0x3f)<<8) | buf[pos+1];
      if(!jumped){ endPos=pos+2; jumped=true; }
      if(visited.has(pointer)) break;
      visited.add(pointer);
      pos=pointer;
      continue;
    }
    const len=b;
    if(len===0){
      if(!jumped) endPos=pos+1;
      break;
    }
    pos+=1;
    if(pos+len>buf.length) break;
    out.push(buf.slice(pos,pos+len).toString('utf8'));
    pos+=len;
  }
  return {name:out.join('.'), offset:endPos};
}

function formatIPv6(buf: Buffer): string{
  const groups:string[]=[];
  for(let i=0;i<8;i++){
    const v=buf.readUInt16BE(i*2);
    groups.push(v.toString(16));
  }
  let bestStart=-1, bestLen=0;
  for(let i=0;i<8;){
    if(groups[i]==='0'){
      let j=i;
      while(j<8 && groups[j]==='0') j++;
      const len=j-i;
      if(len>bestLen && len>=2){ bestLen=len; bestStart=i; }
      i=j;
    }else i++;
  }
  if(bestLen<2) return groups.join(':');
  const left=groups.slice(0,bestStart).join(':');
  const right=groups.slice(bestStart+bestLen).join(':');
  if(!left && !right) return '::';
  if(!left) return '::'+right;
  if(!right) return left+'::';
  return left+'::'+right;
}

function escapeTxt(data: Buffer): string{
  let s='"';
  for(const b of data){
    if(b===0x22) s+='\\"';
    else if(b===0x5c) s+='\\\\';
    else if(b>=0x20 && b<=0x7e) s+=String.fromCharCode(b);
    else s+='\\'+b.toString().padStart(3,'0');
  }
  s+='"';
  return s;
}

async function udpQuery(id:number, query:Buffer): Promise<Buffer>{
  return new Promise((resolve,reject)=>{
    const sock=dgram.createSocket('udp4');
    const timer=setTimeout(()=>{sock.close(); reject(new Error('timeout'));},2000);
    sock.send(query,port,'127.0.0.1');
    sock.on('message',msg=>{
      if(msg.length<12) return;
      const rid=msg.readUInt16BE(0);
      const flags=msg.readUInt16BE(1);
      const qr=(flags>>15)&1;
      if(qr===1 && rid===id){
        clearTimeout(timer);
        sock.close();
        resolve(msg);
      }
    });
    sock.on('error',e=>{clearTimeout(timer); reject(e);});
  });
}

async function tcpQuery(query:Buffer): Promise<Buffer>{
  return new Promise((resolve,reject)=>{
    const sock=new net.Socket();
    let acc=Buffer.alloc(0);
    sock.connect(port,'127.0.0.1',()=>{
      const len=Buffer.alloc(2); len.writeUInt16BE(query.length,0);
      sock.write(Buffer.concat([len,query]));
    });
    sock.on('data',data=>{
      acc=Buffer.concat([acc,data]);
      if(acc.length>=2){
        const len=acc.readUInt16BE(0);
        if(acc.length>=2+len){
          const msg=acc.slice(2,2+len);
          sock.end();
          resolve(msg);
        }
      }
    });
    sock.on('error',reject);
    sock.on('close',()=>{ if(acc.length===0) reject(new Error('closed')); });
  });
}

function parseResponse(buf: Buffer){
  const flags=buf.readUInt16BE(1);
  const rcode=flags & 0x0f;
  const tc=(flags>>9)&1;
  const qdcount=buf.readUInt16BE(4);
  const ancount=buf.readUInt16BE(6);
  let off=12;
  for(let i=0;i<qdcount;i++){
    const {offset:next}=readName(buf,off);
    off=next+4;
  }
  const answers:any[]=[];
  for(let i=0;i<ancount;i++){
    const {name:owner, offset:next}=readName(buf,off);
    off=next;
    const ttl=buf.readUInt32BE(off); off+=4;
    const type=buf.readUInt16BE(off); off+=2;
    off+=2; // class
    const rdlen=buf.readUInt16BE(off); off+=2;
    const rdataStart=off;
    const rdataEnd=off+rdlen;
    const ownerPrint=owner==='' ? '.' : owner.toLowerCase();
    let typeName:string;
    let data:string;
    if(type===1){
      typeName='A';
      data=Array.from(buf.slice(off,off+4)).join('.');
    }else if(type===28){
      typeName='AAAA';
      data=formatIPv6(buf.slice(off,off+16));
    }else if(type===5){
      typeName='CNAME';
      const {name}=readName(buf,off);
      data=name.toLowerCase();
    }else if(type===15){
      typeName='MX';
      const pref=buf.readUInt16BE(off);
      const {name}=readName(buf,off+2);
      const exch=name==='' ? '.' : name.toLowerCase();
      data=`${pref} ${exch}`;
    }else if(type===16){
      typeName='TXT';
      const parts:string[]=[];
      let p=off;
      const end=rdataEnd;
      while(p<end){
        const l=buf[p++];
        const str=buf.slice(p,p+l);
        p+=l;
        parts.push(escapeTxt(str));
      }
      data=parts.join(' ');
    }else{
      typeName=`TYPE${type}`;
      const rdata=buf.slice(rdataStart,rdataEnd);
      const hex=rdata.toString('hex');
      data=`\\# ${rdlen}${hex? ' '+hex:''}`;
    }
    answers.push({owner:ownerPrint, ttl, typeName, data, rawType:type});
    off=rdataEnd;
  }
  return {rcode, tc, answers};
}

async function main(){
  const queries:{name:string;type:string;code:number}[]=[];
  for(const line of lines){
    const t=line.trim();
    if(!t) continue;
    const [name,typ]=t.split(/\s+/);
    const code=typeMap[typ.toUpperCase()]||0;
    queries.push({name,type:typ.toUpperCase(),code});
  }
  const out:string[]=[];
  for(const q of queries){
    const norm=normalizeName(q.name);
    const id=randomInt(0,65536);
    const qbuf=buildQuery(q.name,q.code,id);
    let resp=await udpQuery(id,qbuf);
    let {rcode, tc, answers}=parseResponse(resp);
    if(tc===1){
      resp=await tcpQuery(qbuf);
      ({rcode,tc,answers}=parseResponse(resp));
    }
    const rcodeStr=rcodeNames[rcode]??`RCODE${rcode}`;
    out.push(`${norm} ${q.type} ${rcodeStr}`);
    for(const a of answers){
      const typeOut = a.rawType===1?'A':a.rawType===28?'AAAA':a.rawType===5?'CNAME':a.rawType===15?'MX':a.rawType===16?'TXT':a.typeName;
      if(a.rawType===1||a.rawType===28||a.rawType===5||a.rawType===15||a.rawType===16){
        out.push(`  ${a.owner} ${a.ttl} ${typeOut} ${a.data}`);
      }else{
        out.push(`  ${a.owner} ${a.ttl} ${a.typeName} ${a.data}`);
      }
    }
  }
  console.log(out.join('\n'));
}
main().catch(e=>{console.error(e);process.exit(1);});

use std::env;
use std::fs;
use std::path::Path;

fn read_u32_le(b: &[u8], off: usize) -> u32 {
    u32::from_le_bytes([b[off], b[off + 1], b[off + 2], b[off + 3]])
}
fn read_i32_le(b: &[u8], off: usize) -> i32 {
    i32::from_le_bytes([b[off], b[off + 1], b[off + 2], b[off + 3]])
}
fn read_u16_le(b: &[u8], off: usize) -> u16 {
    u16::from_le_bytes([b[off], b[off + 1]])
}

fn is_ink(r: u8, g: u8, b: u8) -> bool {
    let v = 299u32 * r as u32 + 587u32 * g as u32 + 114u32 * b as u32;
    v / 1000 < 128
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return;
    }
    let dir = Path::new(&args[1]);
    let mut files = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for e in entries.flatten() {
            if let Some(name) = e.file_name().to_str() {
                if name.ends_with(".bmp") {
                    files.push((name.to_string(), e.path()));
                }
            }
        }
    }
    files.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    for (name, path) in files {
        println!("== {}", name);
        let data = match fs::read(&path) {
            Ok(d) => d,
            Err(_) => {
                println!("error: unsupported compression 0");
                continue;
            }
        };
        if data.len() < 54 {
            println!("error: unsupported compression 0");
            continue;
        }
        if data[0] != b'B' || data[1] != b'M' {
            println!("error: unsupported compression 0");
            continue;
        }
        let bf_off_bits = read_u32_le(&data, 10) as usize;
        let dib_size = read_u32_le(&data, 14) as usize;
        let width_i = read_i32_le(&data, 18);
        let height_i = read_i32_le(&data, 22);
        let _planes = read_u16_le(&data, 26);
        let bpp = read_u16_le(&data, 28) as u16;
        let compression = read_u32_le(&data, 30);

        if compression != 0 && compression != 3 {
            println!("error: unsupported compression {}", compression);
            continue;
        }

        let width = width_i.abs() as usize;
        let height_abs = height_i.abs() as usize;
        let height_sign_pos = height_i > 0;
        let bottom_up = height_sign_pos;
        let header_size = dib_size;
        // colors used
        let colors_used = if data.len() >= 14 + 32 + 4 {
            read_u32_le(&data, 14 + 32)
        } else { 0 };
        // palette
        let palette = if bpp == 1 || bpp == 4 || bpp == 8 {
            let num_colors = if colors_used != 0 {
                colors_used as usize
            } else {
                1usize << bpp
            };
            let mut pal = Vec::new();
            let start = 14 + dib_size;
            for i in 0..num_colors {
                let off = start + i * 4;
                if off + 3 < data.len() {
                    let b = data[off];
                    let g = data[off + 1];
                    let r = data[off + 2];
                    pal.push((r, g, b));
                } else {
                    pal.push((0,0,0));
                }
            }
            Some(pal)
        } else { None };

        // masks for BI_BITFIELDS
        let (red_mask, green_mask, blue_mask) = if bpp == 32 && compression == 3 {
            let base = 14 + 40;
            if data.len() >= base + 12 {
                let rm = read_u32_le(&data, base);
                let gm = read_u32_le(&data, base + 4);
                let bm = read_u32_le(&data, base + 8);
                (Some(rm), Some(gm), Some(bm))
            } else { (None, None, None) }
        } else { (None, None, None) };

        // build ink grid
        let mut ink_grid = vec![vec![false; width]; height_abs];
        let mut ink_pixels = 0usize;

        // row stride
        let row_bytes_unpadded = match bpp {
            1 => (width + 7) / 8,
            4 => (width + 1) / 2,
            8 => width,
            24 => width * 3,
            32 => width * 4,
            _ => 0,
        };
        let row_stride = ((row_bytes_unpadded + 3) / 4) * 4;

        if bf_off_bits < data.len() {
            for i in 0..height_abs {
                let y = if bottom_up {
                    height_abs - 1 - i
                } else {
                    i
                };
                let row_start = bf_off_bits + i * row_stride;
                let row_slice = &data[row_start..];
                match bpp {
                    1 => {
                        let mut byte_idx = 0usize;
                        for x in 0..width {
                            if x % 8 == 0 {
                                byte_idx = row_start + row_slice.as_ptr() as usize - data.as_ptr() as usize?; // placeholder
                            }
                        }
                    }
                    _ => {}
                }
                // generic handling per bpp
                match bpp {
                    1 => {
                        let mut col = 0;
                        let mut byte_pos = 0;
                        while col < width {
                            if row_start + byte_pos >= data.len() { break; }
                            let byte = data[row_start + byte_pos];
                            for bit in 0..8 {
                                if col >= width { break; }
                                let bit_val = (byte >> (7 - bit)) & 1;
                                let idx = bit_val as usize;
                                let (r,g,b) = if let Some(ref pal) = palette {
                                    if idx < pal.len() { pal[idx] } else { (0,0,0) }
                                } else { (0,0,0) };
                                let ink = is_ink(r,g,b);
                                ink_grid[y][col] = ink;
                                if ink { ink_pixels += 1; }
                                col += 1;
                            }
                            byte_pos += 1;
                        }
                    }
                    4 => {
                        let mut col = 0;
                        let mut byte_pos = 0;
                        while col < width {
                            if row_start + byte_pos >= data.len() { break; }
                            let byte = data[row_start + byte_pos];
                            // high nibble
                            let hi = (byte >> 4) & 0xF;
                            let lo = byte & 0xF;
                            for nib in [hi, lo] {
                                if col >= width { break; }
                                let idx = nib as usize;
                                let (r,g,b) = if let Some(ref pal) = palette {
                                    if idx < pal.len() { pal[idx] } else { (0,0,0) }
                                } else { (0,0,0) };
                                let ink = is_ink(r,g,b);
                                ink_grid[y][col] = ink;
                                if ink { ink_pixels += 1; }
                                col += 1;
                            }
                            byte_pos += 1;
                        }
                    }
                    8 => {
                        for x in 0..width {
                            let off = row_start + x;
                            if off + 1 > data.len() { break; }
                            let idx = data[off] as usize;
                            let (r,g,b) = if let Some(ref pal) = palette {
                                if idx < pal.len() { pal[idx] } else { (0,0,0) }
                            } else { (0,0,0) };
                            let ink = is_ink(r,g,b);
                            ink_grid[y][x] = ink;
                            if ink { ink_pixels += 1; }
                        }
                    }
                    24 => {
                        for x in 0..width {
                            let off = row_start + x * 3;
                            if off + 2 >= data.len() { break; }
                            let b_ = data[off];
                            let g_ = data[off + 1];
                            let r_ = data[off + 2];
                            let ink = is_ink(r_, g_, b_);
                            ink_grid[y][x] = ink;
                            if ink { ink_pixels += 1; }
                        }
                    }
                    32 => {
                        if compression == 0 {
                            for x in 0..width {
                                let off = row_start + x * 4;
                                if off + 3 >= data.len() { break; }
                                let b_ = data[off];
                                let g_ = data[off + 1];
                                let r_ = data[off + 2];
                                let ink = is_ink(r_, g_, b_);
                                ink_grid[y][x] = ink;
                                if ink { ink_pixels += 1; }
                            }
                        } else if compression == 3 {
                            if let (Some(rm), Some(gm), Some(bm)) = (red_mask, green_mask, blue_mask) {
                                let s_r = rm.trailing_zeros() as u32;
                                let n_r = rm.count_ones();
                                let s_g = gm.trailing_zeros() as u32;
                                let n_g = gm.count_ones();
                                let s_b = bm.trailing_zeros() as u32;
                                let n_b = bm.count_ones();
                                let m_r = if n_r > 0 { (1u32 << n_r) - 1 } else { 0 };
                                let m_g = if n_g > 0 { (1u32 << n_g) - 1 } else { 0 };
                                let m_b = if n_b > 0 { (1u32 << n_b) - 1 } else { 0 };
                                for x in 0..width {
                                    let off = row_start + x * 4;
                                    if off + 3 >= data.len() { break; }
                                    let pixel = u32::from_le_bytes([data[off], data[off+1], data[off+2], data[off+3]]);
                                    let v_r = (pixel & rm) >> s_r;
                                    let v_g = (pixel & gm) >> s_g;
                                    let v_b = (pixel & bm) >> s_b;
                                    let r8 = if n_r>0 { ((v_r * 255 + m_r/2)/m_r) as u8 } else {0};
                                    let g8 = if n_g>0 { ((v_g * 255 + m_g/2)/m_g) as u8 } else {0};
                                    let b8 = if n_b>0 { ((v_b * 255 + m_b/2)/m_b) as u8 } else {0};
                                    let ink = is_ink(r8,g8,b8);
                                    ink_grid[y][x] = ink;
                                    if ink { ink_pixels += 1; }
                                }
                            }
                        }
                    }
                    _ => {}
                }
            }
        }

        let orientation = if bottom_up { "bottom-up" } else { "top-down" };
        println!("size {}x{} bpp {} header {} {} ink {}", width, height_abs, bpp, header_size, orientation, ink_pixels);

        // components
        let mut visited = vec![vec![false; width]; height_abs];
        let mut comps = Vec::new();
        for y in 0..height_abs {
            for x in 0..width {
                if ink_grid[y][x] && !visited[y][x] {
                    let mut stack = vec![(x, y)];
                    visited[y][x] = true;
                    let mut minx = x; let mut maxx = x;
                    let mut miny = y; let mut maxy = y;
                    let mut count = 0;
                    let mut first = (x, y);
                    while let Some((cx, cy)) = stack.pop() {
                        count += 1;
                        if cx < minx { minx = cx; }
                        if cx > maxx { maxx = cx; }
                        if cy < miny { miny = cy; }
                        if cy > maxy { maxy = cy; }
                        for dy in -1..=1 {
                            for dx in -1..=1 {
                                if dx == 0 && dy == 0 { continue; }
                                let nx = cx as isize + dx;
                                let ny = cy as isize + dy;
                                if nx >= 0 && nx < width as isize && ny >= 0 && ny < height_abs as isize {
                                    let ux = nx as usize;
                                    let uy = ny as usize;
                                    if ink_grid[uy][ux] && !visited[uy][ux] {
                                        visited[uy][ux] = true;
                                        stack.push((ux, uy));
                                    }
                                }
                            }
                        }
                    }
                    comps.push((first, minx, miny, maxx, maxy, count));
                }
            }
        }
        println!("components {}", comps.len());
        for (first, minx, miny, maxx, maxy, cnt) in comps {
            println!("{},{}, bbox {},{}-{},{} pixels {}", first.0, first.1, minx, miny, maxx, maxy, cnt);
        }
    }
}

