                                let m_r = if n_r > 0 { (1u32 << n_r) - 1 } else { 0 };
                                let m_g = if n_g > 0 { (1u32 << n_g) - 1 } else { 0 };
                                let m_b = if n_b > 0 { (1u32 << n_b) - 1 } else { 0 };
                                for x in 0..width {
                                    let off = row_start + x * 4;
                                    if off + 3 >= data.len() { break; }
                                    let pixel = u32::from_le_bytes([data[off], data[off+1], data[off+2], data[off+3]]);
                                    let v_r = (pixel & rm) >> s_r;
                                    let v_g = (pixel & gm) >> s_g;
                                    let v_b = (pixel & bm) >> s_b;
                                    let r8 = if n_r > 0 { ((v_r * 255 + m_r/2)/m_r) as u8 } else {0};
                                    let g8 = if n_g > 0 { ((v_g * 255 + m_g/2)/m_g) as u8 } else {0};
                                    let b8 = if n_b > 0 { ((v_b * 255 + m_b/2)/m_b) as u8 } else {0};
                                    let ink = is_ink(r8,g8,b8);
                                    ink_grid[y][x] = ink;
                                    if ink { ink_pixels += 1; }
                                }
                            }
                        }
                    }
                    _ => {}
                }
            }
        }

        println!("size {}x{} bpp {} header {} {} ink {}", width, height_abs, bpp, dib_size, orientation, ink_pixels);

        let mut visited = vec![vec![false; width]; height_abs];
        let mut comps = Vec::new();
        for y in 0..height_abs {
            for x in 0..width {
                if ink_grid[y][x] && !visited[y][x] {
                    let mut stack = vec![(x, y)];
                    visited[y][x] = true;
                    let mut minx = x; let mut maxx = x;
                    let mut miny = y; let mut maxy = y;
                    let mut count = 0;
                    let first = (x, y);
                    while let Some((cx, cy)) = stack.pop() {
                        count += 1;
                        if cx < minx { minx = cx; }
                        if cx > maxx { maxx = cx; }
                        if cy < miny { miny = cy; }
                        if cy > maxy { maxy = cy; }
                        for dy in -1..=1 {
                            for dx in -1..=1 {
                                if dx == 0 && dy == 0 { continue; }
                                let nx = cx as isize + dx;
                                let ny = cy as isize + dy;
                                if nx >= 0 && nx < width as isize && ny >= 0 && ny < height_abs as isize {
                                    let ux = nx as usize;
                                    let uy = ny as usize;
                                    if ink_grid[uy][ux] && !visited[uy][ux] {
                                        visited[uy][ux] = true;
                                        stack.push((ux, uy));
                                    }
                                }
                            }
                        }
                    }
                    comps.push((first, minx, miny, maxx, maxy, count));
                }
            }
        }
        println!("components {}", comps.len());
        for (first, minx, miny, maxx, maxy, cnt) in comps {
            println!("{},{}, bbox {},{}-{},{} pixels {}", first.0, first.1, minx, miny, maxx, maxy, cnt);
        }
    }
}

import Foundation

func readU16(_ data: Data, _ off: Int) -> UInt16 {
    guard off + 1 < data.count else { return 0 }
    let b0 = UInt16(data[off])
    let b1 = UInt16(data[off + 1])
    return b0 | (b1 << 8)
}
func readU32(_ data: Data, _ off: Int) -> UInt32 {
    guard off + 3 < data.count else { return 0 }
    let b0 = UInt32(data[off])
    let b1 = UInt32(data[off + 1])
    let b2 = UInt32(data[off + 2])
    let b3 = UInt32(data[off + 3])
    return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24)
}
func readI32(_ data: Data, _ off: Int) -> Int32 {
    return Int32(bitPattern: readU32(data, off))
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dir = args[1]

let fm = FileManager.default
guard let contents = try? fm.contentsOfDirectory(atPath: dir) else { exit(0) }
let files = contents.filter { $0.hasSuffix(".bmp") }.sorted()

for name in files {
    let path = dir + "/" + name
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: path)) else { continue }
    print("== \(name)")

    // minimal header check
    if data.count < 54 {
        print("error: unsupported compression 0")
        continue
    }
    guard data[0] == 0x42 && data[1] == 0x4D else {
        print("error: unsupported compression 0")
        continue
    }
    let bfOffBits = Int(readU32(data, 10))
    let dibStart = 14
    let dibSize = Int(readU32(data, dibStart))
    let width = Int(readI32(data, dibStart + 4))
    let heightRaw = Int(readI32(data, dibStart + 8))
    let bpp = Int(readU16(data, dibStart + 14))
    let compression = Int(readU32(data, dibStart + 16))
    let coloursUsed = Int(readU32(data, dibStart + 32))

    if compression != 0 && compression != 3 {
        print("error: unsupported compression \(compression)")
        continue
    }
    if compression == 3 && bpp != 32 {
        print("error: unsupported compression \(compression)")
        continue
    }
    let heightAbs = abs(heightRaw)
    let isBottomUp = heightRaw > 0
    let headerSize = dibSize

    // masks for BI_BITFIELDS
    var redMask: UInt32 = 0
    var greenMask: UInt32 = 0
    var blueMask: UInt32 = 0
    if compression == 3 {
        if dibSize == 40 {
            let mOff = dibStart + 40
            if mOff + 12 <= data.count {
                redMask = readU32(data, mOff)
                greenMask = readU32(data, mOff + 4)
                blueMask = readU32(data, mOff + 8)
            }
        } else {
            let mOff = dibStart + 40
            if mOff + 12 <= data.count {
                redMask = readU32(data, mOff)
                greenMask = readU32(data, mOff + 4)
                blueMask = readU32(data, mOff + 8)
            }
        }
    }

    // palette
    var palette: [(r: UInt8, g: UInt8, b: UInt8)] = []
    if bpp == 1 || bpp == 4 || bpp == 8 {
        let paletteStart = dibStart + dibSize
        let entries = coloursUsed != 0 ? coloursUsed : (1 << bpp)
        let need = paletteStart + entries * 4
        if need <= data.count {
            for i in 0..<entries {
                let off = paletteStart + i * 4
                let b = UInt8(data[off])
                let g = UInt8(data[off + 1])
                let r = UInt8(data[off + 2])
                palette.append((r, g, b))
            }
        }
    }

    // row stride
    var bytesPerRowUnpadded: Int
    switch bpp {
    case 1: bytesPerRowUnpadded = (width + 7) / 8
    case 4: bytesPerRowUnpadded = (width + 1) / 2
    case 8: bytesPerRowUnpadded = width
    case 24: bytesPerRowUnpadded = width * 3
    case 32: bytesPerRowUnpadded = width * 4
    default: bytesPerRowUnpadded = 0
    }
    let rowStride = ((bytesPerRowUnpadded + 3) / 4) * 4

    let totalPixels = width * heightAbs
    var isInk = [Bool](repeating: false, count: totalPixels)
    var inkCount = 0

    func luminance(_ r: UInt8, _ g: UInt8, _ b: UInt8) -> Bool {
        let v = Int(r) * 299 + Int(g) * 587 + Int(b) * 114
        return v / 1000 < 128
    }

    for fileRow in 0..<heightAbs {
        let y = isBottomUp ? heightAbs - 1 - fileRow : fileRow
        let rowBase = bfOffBits + fileRow * rowStride
        if rowBase >= data.count { continue }
        for x in 0..<width {
            var r: UInt8 = 0, g: UInt8 = 0, b: UInt8 = 0
            switch bpp {
            case 1:
                let byteIdx = rowBase + x / 8
                if byteIdx < data.count {
                    let byte = data[byteIdx]
                    let bit = 7 - (x % 8)
                    let idx = (byte >> bit) & 1
                    if idx < palette.count {
                        let c = palette[Int(idx)]
                        r = c.r; g = c.g; b = c.b
                    }
                }
            case 4:
                let byteIdx = rowBase + x / 2
                if byteIdx < data.count {
                    let byte = data[byteIdx]
                    let nibble: UInt8 = (x % 2 == 0) ? (byte >> 4) & 0x0F : byte & 0x0F
                    let idx = Int(nibble)
                    if idx < palette.count {
                        let c = palette[idx]
                        r = c.r; g = c.g; b = c.b
                    }
                }
            case 8:
                let byteIdx = rowBase + x
                if byteIdx < data.count {
                    let idx = Int(data[byteIdx])
                    if idx < palette.count {
                        let c = palette[idx]
                        r = c.r; g = c.g; b = c.b
                    }
                }
            case 24:
                let byteIdx = rowBase + x * 3
                if byteIdx + 2 < data.count {
                    b = data[byteIdx]
                    g = data[byteIdx + 1]
                    r = data[byteIdx + 2]
                }
            case 32:
                let byteIdx = rowBase + x * 4
                if byteIdx + 3 < data.count {
                    if compression == 3 {
                        let pixel = readU32(data, byteIdx)
                        func channel(_ mask: UInt32) -> UInt8 {
                            guard mask != 0 else { return 0 }
                            let s = mask.trailingZeroBitCount
                            let v = UInt32((pixel & mask) >> s)
                            let n = mask.nonzeroBitCount
                            let m = (1 << n) - 1
                            let scaled = (Int(v) * 255 + Int(m)/2) / Int(m)
                            return UInt8(max(0, min(255, scaled)))
                        }
                        r = channel(redMask)
                        g = channel(greenMask)
                        b = channel(blueMask)
                    } else {
                        b = data[byteIdx]
                        g = data[byteIdx + 1]
                        r = data[byteIdx + 2]
                    }
                }
            default:
                break
            }
            let idxPix = y * width + x
            if luminance(r, g, b) {
                isInk[idxPix] = true
                inkCount += 1
            }
        }
    }

    print("size \(width)x\(heightAbs) bpp \(bpp) header \(headerSize) \(isBottomUp ? "bottom-up" : "top-down") ink \(inkCount)")

    var visited = [Bool](repeating: false, count: totalPixels)
    struct Comp {
        var firstY: Int
        var firstX: Int
        var minX: Int
        var minY: Int
        var maxX: Int
        var maxY: Int
        var count: Int
    }
    var comps: [Comp] = []

    for y in 0..<heightAbs {
        for x in 0..<width {
            let idx = y * width + x
            if isInk[idx] && !visited[idx] {
                var stack = [(Int,Int)]()
                stack.append((x,y))
                visited[idx] = true
                var minX = x, maxX = x, minY = y, maxY = y
                var cnt = 0
                var firstY = y, firstX = x
                while !stack.isEmpty {
                    let (cx, cy) = stack.removeLast()
                    cnt += 1
                    if cx < minX { minX = cx }
                    if cx > maxX { maxX = cx }
                    if cy < minY { minY = cy }
                    if cy > maxY { maxY = cy }
                    for dy in -1...1 {
                        for dx in -1...1 {
                            if dx == 0 && dy == 0 { continue }
                            let nx = cx + dx
                            let ny = cy + dy
                            if nx < 0 || nx >= width || ny < 0 || ny >= heightAbs { continue }
                            let nIdx = ny * width + nx
                            if isInk[nIdx] && !visited[nIdx] {
                                visited[nIdx] = true
                                stack.append((nx, ny))
                            }
                        }
                    }
                }
                comps.append(Comp(firstY: firstY, firstX: firstX, minX: minX, minY: minY, maxX: maxX, maxY: maxY, count: cnt))
            }
        }
    }

    print("components \(comps.count)")
    for c in comps {
        print("\(c.firstX),\(c.firstY) bbox \(c.minX),\(c.minY)-\(c.maxX),\(c.maxY) pixels \(c.count)")
    }
}

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    public static void main(String[] args) throws IOException {
        if (args.length == 0) return;
        File dir = new File(args[0]);
        File[] files = dir.listFiles();
        if (files == null) return;
        List<File> bmps = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().toLowerCase().endsWith(".bmp")) {
                bmps.add(f);
            }
        }
        bmps.sort((a, b) -> a.getName().compareTo(b.getName()));
        for (File f : bmps) {
            processFile(f);
        }
    }

    private static void processFile(File f) throws IOException {
        String name = f.getName();
        System.out.println("== " + name);
        byte[] data = Files.readAllBytes(f.toPath());
        if (data.length < 54) {
            System.out.println("error: unsupported compression 0");
            return;
        }
        if (data[0] != 'B' || data[1] != 'M') {
            System.out.println("error: unsupported compression 0");
            return;
        }
        int bfOffBits = readU32(data, 10);
        int dibSize = readU32(data, 14);
        int width = readI32(data, 18);
        int heightSigned = readI32(data, 22);
        int planes = readU16(data, 26);
        int bpp = readU16(data, 28);
        int compression = readU32(data, 32);
        if (compression != 0 && compression != 3) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }
        int height = Math.abs(heightSigned);
        boolean bottomUp = heightSigned > 0;
        int headerSize = dibSize;
        // masks for BI_BITFIELDS
        int redMask = 0, greenMask = 0, blueMask = 0;
        if (compression == 3 && bpp == 32) {
            redMask = readU32(data, 14 + 40);
            greenMask = readU32(data, 14 + 44);
            blueMask = readU32(data, 14 + 48);
        }

        // palette
        int[][] palette = null;
        int paletteCount = 0;
        if (bpp <= 8) {
            int colorsUsed = readU32(data, 46);
            if (colorsUsed == 0) colorsUsed = 1 << bpp;
            paletteCount = colorsUsed;
            palette = new int[paletteCount][3];
            int palOff = 14 + dibSize;
            for (int i = 0; i < paletteCount && palOff + 3 < data.length; i++) {
                int b = data[palOff] & 0xFF;
                int g = data[palOff + 1] & 0xFF;
                int r = data[palOff + 2] & 0xFF;
                palette[i][0] = r;
                palette[i][1] = g;
                palette[i][2] = b;
                palOff += 4;
            }
        }

        boolean[][] ink = new boolean[height][width];
        long inkPixels = 0;

        int rawRow = 0;
        if (bpp == 1 || bpp == 4 || bpp == 8) {
            rawRow = (width * bpp + 7) / 8;
        } else if (bpp == 24) {
            rawRow = width * 3;
        } else if (bpp == 32) {
            rawRow = width * 4;
        }
        int rowStride = ((rawRow + 3) / 4) * 4;

        for (int y = 0; y < height; y++) {
            int fileRowIdx = bottomUp ? height - 1 - y : y;
            int rowStart = bfOffBits + fileRowIdx * rowStride;
            for (int x = 0; x < width; x++) {
                int r = 0, g = 0, b = 0;
                if (bpp == 1) {
                    int byteIdx = x / 8;
                    int bitPos = 7 - (x % 8);
                    int byteVal = data[rowStart + byteIdx] & 0xFF;
                    int idx = (byteVal >> bitPos) & 1;
                    if (palette != null && idx < paletteCount) {
                        r = palette[idx][0];
                        g = palette[idx][1];
                        b = palette[idx][2];
                    }
                } else if (bpp == 4) {
                    int byteIdx = x / 2;
                    int byteVal = data[rowStart + byteIdx] & 0xFF;
                    int idx = (x % 2 == 0) ? (byteVal >> 4) & 0xF : byteVal & 0xF;
                    if (palette != null && idx < paletteCount) {
                        r = palette[idx][0];
                        g = palette[idx][1];
                        b = palette[idx][2];
                    }
                } else if (bpp == 8) {
                    int idx = data[rowStart + x] & 0xFF;
                    if (palette != null && idx < paletteCount) {
                        r = palette[idx][0];
                        g = palette[idx][1];
                        b = palette[idx][2];
                    }
                } else if (bpp == 24) {
                    int off = rowStart + x * 3;
                    b = data[off] & 0xFF;
                    g = data[off + 1] & 0xFF;
                    r = data[off + 2] & 0xFF;
                } else if (bpp == 32) {
                    int off = rowStart + x * 4;
                    if (compression == 0) {
                        b = data[off] & 0xFF;
                        g = data[off + 1] & 0xFF;
                        r = data[off + 2] & 0xFF;
                    } else {
                        long pixel = ((data[off] & 0xFFL))
                                | ((data[off + 1] & 0xFFL) << 8)
                                | ((data[off + 2] & 0xFFL) << 16)
                                | ((data[off + 3] & 0xFFL) << 24);
                        r = extractChannel(pixel, redMask);
                        g = extractChannel(pixel, greenMask);
                        b = extractChannel(pixel, blueMask);
                    }
                }
                int lum = (299 * r + 587 * g + 114 * b) / 1000;
                boolean isInk = lum < 128;
                ink[y][x] = isInk;
                if (isInk) inkPixels++;
            }
        }

        System.out.println("size " + width + "x" + height + " bpp " + bpp + " header " + headerSize + " " + (bottomUp ? "bottom-up" : "top-down") + " ink " + inkPixels);
        // components
        boolean[][] visited = new boolean[height][width];
        List<Comp> comps = new ArrayList<>();
        int[] dx = {-1,0,1,-1,1,-1,0,1};
        int[] dy = {-1,-1,-1,0,0,1,1,1};
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                if (ink[y][x] && !visited[y][x]) {
                    int firstX = x, firstY = y;
                    int minx = x, maxx = x, miny = y, maxy = y;
                    int count = 0;
                    ArrayDeque<int[]> q = new ArrayDeque<>();
                    q.add(new int[]{x, y});
                    visited[y][x] = true;
                    while (!q.isEmpty()) {
                        int[] p = q.poll();
                        int cx = p[0], cy = p[1];
                        count++;
                        if (cx < minx) minx = cx;
                        if (cx > maxx) maxx = cx;
                        if (cy < miny) miny = cy;
                        if (cy > maxy) maxy = cy;
                        for (int k = 0; k < 8; k++) {
                            int nx = cx + dx[k];
                            int ny = cy + dy[k];
                            if (nx >= 0 && nx < width && ny >= 0 && ny < height && ink[ny][nx] && !visited[ny][nx]) {
                                visited[ny][nx] = true;
                                q.add(new int[]{nx, ny});
                            }
                        }
                    }
                    comps.add(new Comp(firstX, firstY, minx, miny, maxx, maxy, count));
                }
            }
        }
        System.out.println("components " + comps.size());
        for (Comp c : comps) {
            System.out.println(c.firstX + "," + c.firstY + " bbox " + c.minx + "," + c.miny + "-" + c.maxx + "," + c.maxy + " pixels " + c.count);
        }
    }

    private static int extractChannel(long pixel, int mask) {
        if (mask == 0) return 0;
        int s = Integer.numberOfTrailingZeros(mask);
        int n = Integer.bitCount(mask);
        long v = (pixel & 0xFFFFFFFFL & mask) >>> s;
        int m = (1 << n) - 1;
        return (int) ((v * 255 + m / 2) / m);
    }

    private static int readU16(byte[] d, int o) {
        return (d[o] & 0xFF) | ((d[o + 1] & 0xFF) << 8);
    }
    private static int readU32(byte[] d, int o) {
        return (d[o] & 0xFF) | ((d[o + 1] & 0xFF) << 8) | ((d[o + 2] & 0xFF) << 16) | ((d[o + 3] & 0xFF) << 24);
    }
    private static int readI32(byte[] d, int o) {
        return readU32(d, o);
    }

    private static class Comp {
        int firstX, firstY, minx, miny, maxx, maxy, count;
        Comp(int fx, int fy, int mnx, int mny, int mxx, int mxy, int c) {
            firstX = fx; firstY = fy; minx = mnx; miny = mny; maxx = mxx; maxy = mxy; count = c;
        }
    }
}

