                    int byteIdx = x / 2;
                    int byteVal = data[rowStart + byteIdx] & 0xFF;
                    int idx = (x % 2 == 0) ? (byteVal >> 4) & 0xF : byteVal & 0xF;
                    if (palette != null && idx < paletteCount) {
                        r = palette[idx][0];
                        g = palette[idx][1];
                        b = palette[idx][2];
                    }
                } else if (bpp == 8) {
                    int idx = data[rowStart + x] & 0xFF;
                    if (palette != null && idx < paletteCount) {
                        r = palette[idx][0];
                        g = palette[idx][1];
                        b = palette[idx][2];
                    }
                } else if (bpp == 24) {
                    int off = rowStart + x * 3;
                    b = data[off] & 0xFF;
                    g = data[off + 1] & 0xFF;
                    r = data[off + 2] & 0xFF;
                } else if (bpp == 32) {
                    int off = rowStart + x * 4;
                    if (compression == 0) {
                        b = data[off] & 0xFF;
                        g = data[off + 1] & 0xFF;
                        r = data[off + 2] & 0xFF;
                    } else {
                        long pixel = ((data[off] & 0xFFL))
                                | ((data[off + 1] & 0xFFL) << 8)
                                | ((data[off + 2] & 0xFFL) << 16)
                                | ((data[off + 3] & 0xFFL) << 24);
                        r = extractChannel(pixel, redMask);
                        g = extractChannel(pixel, greenMask);
                        b = extractChannel(pixel, blueMask);
                    }
                }
                int lum = (299 * r + 587 * g + 114 * b) / 1000;
                boolean isInk = lum < 128;
                ink[y][x] = isInk;
                if (isInk) inkPixels++;
            }
        }

        System.out.println("size " + width + "x" + height + " bpp " + bpp + " header " + headerSize + " " + (bottomUp ? "bottom-up" : "top-down") + " ink " + inkPixels);
        boolean[][] visited = new boolean[height][width];
        List<Comp> comps = new ArrayList<>();
        int[] dx = {-1,0,1,-1,1,-1,0,1};
        int[] dy = {-1,-1,-1,0,0,1,1,1};
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                if (ink[y][x] && !visited[y][x]) {
                    int firstX = x, firstY = y;
                    int minx = x, maxx = x, miny = y, maxy = y;
                    int count = 0;
                    ArrayDeque<int[]> q = new ArrayDeque<>();
                    q.add(new int[]{x, y});
                    visited[y][x] = true;
                    while (!q.isEmpty()) {
                        int[] p = q.poll();
                        int cx = p[0], cy = p[1];
                        count++;
                        if (cx < minx) minx = cx;
                        if (cx > maxx) maxx = cx;
                        if (cy < miny) miny = cy;
                        if (cy > maxy) maxy = cy;
                        for (int k = 0; k < 8; k++) {
                            int nx = cx + dx[k];
                            int ny = cy + dy[k];
                            if (nx >= 0 && nx < width && ny >= 0 && ny < height && ink[ny][nx] && !visited[ny][nx]) {
                                visited[ny][nx] = true;
                                q.add(new int[]{nx, ny});
                            }
                        }
                    }
                    comps.add(new Comp(firstX, firstY, minx, miny, maxx, maxy, count));
                }
            }
        }
        System.out.println("components " + comps.size());
        for (Comp c : comps) {
            System.out.println(c.firstX + "," + c.firstY + " bbox " + c.minx + "," + c.miny + "-" + c.maxx + "," + c.maxy + " pixels " + c.count);
        }
    }

    private static int extractChannel(long pixel, int mask) {
        if (mask == 0) return 0;
        int s = Integer.numberOfTrailingZeros(mask);
        int n = Integer.bitCount(mask);
        long v = (pixel & 0xFFFFFFFFL & mask) >>> s;
        int m = (1 << n) - 1;
        return (int) ((v * 255 + m / 2) / m);
    }

    private static int readU16(byte[] d, int o) {
        return (d[o] & 0xFF) | ((d[o + 1] & 0xFF) << 8);
    }
    private static int readU32(byte[] d, int o) {
        return (d[o] & 0xFF) | ((d[o + 1] & 0xFF) << 8) | ((d[o + 2] & 0xFF) << 16) | ((d[o + 3] & 0xFF) << 24);
    }
    private static int readI32(byte[] d, int o) {
        return readU32(d, o);
    }

    private static class Comp {
        int firstX, firstY, minx, miny, maxx, maxy, count;
        Comp(int fx, int fy, int mnx, int mny, int mxx, int mxy, int c) {
            firstX = fx; firstY = fy; minx = mnx; miny = mny; maxx = mxx; maxy = mxy; count = c;
        }
    }
}

import Foundation
import Darwin

func htons(_ v: UInt16) -> UInt16 { return v.bigEndian }

func decodeName(at start: Int, buffer: [UInt8]) -> (String, Int) {
    var labels: [String] = []
    var cur = start
    var next = start
    var jumped = false
    var visited = Set<Int>()
    while true {
        guard cur < buffer.count else { break }
        let len = Int(buffer[cur])
        if len & 0xC0 == 0xC0 {
            let b1 = len & 0x3F
            let b2 = Int(buffer[cur+1])
            let ptr = (b1 << 8) | b2
            if !jumped { next = cur + 2 }
            cur = ptr
            jumped = true
            if visited.contains(cur) { break }
            visited.insert(cur)
            continue
        } else if len == 0 {
            if !jumped { next = cur + 1 }
            break
        } else {
            let startLabel = cur + 1
            let endLabel = startLabel + len
            if endLabel <= buffer.count {
                let bytes = buffer[startLabel..<endLabel]
                if let s = String(bytes: bytes, encoding: .utf8) {
                    labels.append(s)
                }
            }
            cur = endLabel
            if !jumped { next = cur }
            continue
        }
    }
    let name = labels.joined(separator: ".")
    return (name, next)
}

func readUInt16(_ b: [UInt8], off: Int) -> UInt16 {
    return (UInt16(b[off]) << 8) | UInt16(b[off+1])
}
func readUInt32(_ b: [UInt8], off: Int) -> UInt32 {
    return (UInt32(b[off]) << 24) | (UInt32(b[off+1]) << 16) | (UInt32(b[off+2]) << 8) | UInt32(b[off+3])
}

func formatAAAA(_ bytes: [UInt8]) -> String {
    precondition(bytes.count == 16)
    var groups: [UInt16] = []
    for i in stride(from: 0, to: 16, by: 2) {
        let v = (UInt16(bytes[i]) << 8) | UInt16(bytes[i+1])
        groups.append(v)
    }
    let strs = groups.map { String(format: "%x", $0) }
    var bestStart = -1
    var bestLen = 0
    var i = 0
    while i < 8 {
        if strs[i] == "0" {
            var j = i
            while j < 8 && strs[j] == "0" { j += 1 }
            let len = j - i
            if len > bestLen && len >= 2 {
                bestLen = len
                bestStart = i
            }
            i = j
        } else {
            i += 1
        }
    }
    if bestLen >= 2 {
        let prefix = bestStart > 0 ? strs[0..<bestStart].joined(separator: ":") : ""
        let suffixStart = bestStart + bestLen
        let suffix = suffixStart < 8 ? strs[suffixStart..<8].joined(separator: ":") : ""
        if prefix.isEmpty && suffix.isEmpty { return "::" }
        if prefix.isEmpty { return "::" + suffix }
        if suffix.isEmpty { return prefix + "::" }
        return prefix + "::" + suffix
    } else {
        return strs.joined(separator: ":")
    }
}

func escapeTXT(_ data: [UInt8]) -> String {
    var out = ""
    for b in data {
        if b == 0x22 {
            out += "\\\""
        } else if b == 0x5C {
            out += "\\\\"
        } else if b >= 0x20 && b <= 0x7E {
            out.append(Character(UnicodeScalar(b)))
        } else {
            out += "\\\(b)"
        }
    }
    return out
}

let args = CommandLine.arguments
guard args.count >= 3 else { exit(0) }
let dir = args[1]
let port = Int(args[2]) ?? 0
let queryPath = URL(fileURLWithPath: dir).appendingPathComponent("queries.txt").path
guard let content = try? String(contentsOfFile: queryPath, encoding: .utf8) else { exit(0) }

var queries: [(name: String, typeStr: String, typeCode: UInt16)] = []
for line in content.split(separator: "\n", omittingEmptySubsequences: false) {
    let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.isEmpty { continue }
    let parts = trimmed.split(separator: " ", maxSplits: 1, omittingEmptySubsequences: true)
    guard parts.count == 2 else { continue }
    let name = String(parts[0])
    let tStr = String(parts[1]).uppercased()
    let code: UInt16
    switch tStr {
    case "A": code = 1
    case "CNAME": code = 5
    case "MX": code = 15
    case "TXT": code = 16
    case "AAAA": code = 28
    default: code = 0
    }
    queries.append((name, tStr, code))
}

func buildQuery(id: UInt16, name: String, qtype: UInt16) -> [UInt8] {
    var msg: [UInt8] = []
    msg.append(contentsOf: [UInt8(id>>8), UInt8(id&0xff)])
    msg.append(contentsOf: [0x01, 0x00]) // flags
    msg.append(contentsOf: [0,0,0,0,0,0,0,0]) // counts
    // QNAME
    var nameOnly = name
    if nameOnly.hasSuffix(".") { nameOnly.removeLast() }
    let labels = nameOnly.split(separator: ".")
    for lab in labels {
        let bytes = Array(lab.utf8)
        msg.append(UInt8(bytes.count))
        msg.append(contentsOf: bytes)
    }
    msg.append(0)
    msg.append(UInt8(qtype>>8)); msg.append(UInt8(qtype&0xff))
    msg.append(0x00); msg.append(0x01)
    return msg
}

func udpQuery(id: UInt16, query: [UInt8], port: Int) -> [UInt8]? {
    let fd = socket(AF_INET, SOCK_DGRAM, 0)
    guard fd >= 0 else { return nil }
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = htons(UInt16(port))
    addr.sin_addr = in_addr(s_addr: inet_addr("127.0.0.1"))
    addr.sin_len = 0
    withUnsafePointer(to: &addr) { ptr in
        _ = sendto(fd, query, query.count, 0, ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { $0 }, socklen_t(MemoryLayout<sockaddr_in>.size))
    }
    var buf = [UInt8](repeating: 0, count: 4096)
    var from = sockaddr_in()
    var fromlen = socklen_t(MemoryLayout<sockaddr_in>.size)
    while true {
        let n = recvfrom(fd, &buf, buf.count, 0, withUnsafeMutablePointer(to: &from) { $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { $0 } }, &fromlen)
        if n <= 0 { close(fd); return nil }
        let data = Array(buf[0..<n])
        if data.count >= 12 {
            let respId = (UInt16(data[0]) << 8) | UInt16(data[1])
            let flags = (UInt16(data[2]) << 8) | UInt16(data[3])
            let qr = (flags & 0x8000) != 0
            if qr && respId == id {
                close(fd)
                return data
            }
        }
        // continue loop
    }
}

func tcpQuery(id: UInt16, query: [UInt8], port: Int) -> [UInt8]? {
    let fd = socket(AF_INET, SOCK_STREAM, 0)
    guard fd >= 0 else { return nil }
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = htons(UInt16(port))
    addr.sin_addr = in_addr(s_addr: inet_addr("127.0.0.1"))
    withUnsafePointer(to: &addr) { ptr in
        _ = connect(fd, ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { $0 }, socklen_t(MemoryLayout<sockaddr_in>.size))
    }
    var out = [UInt8]()
    out.append(UInt8(query.count>>8)); out.append(UInt8(query.count&0xff))
    out.append(contentsOf: query)
    _ = out.withUnsafeBytes { send(fd, $0.baseAddress!, out.count, 0) }
    var lenBuf = [UInt8](repeating: 0, count: 2)
    var received = 0
    while received < 2 {
        let r = recv(fd, &lenBuf[received], 2-received, 0)
        if r <= 0 { close(fd); return nil }
        received += r
    }
    let msgLen = Int(lenBuf[0])<<8 | Int(lenBuf[1])
    var msg = [UInt8](repeating: 0, count: msgLen)
    received = 0
    while received < msgLen {
        let r = recv(fd, &msg[received], msgLen-received, 0)
        if r <= 0 { close(fd); return nil }
        received += r
    }
    close(fd)
    return msg
}

var outLines: [String] = []

for q in queries {
    let id = UInt16(Int.random(in: 1...65535))
    let queryMsg = buildQuery(id: id, name: q.name, qtype: q.typeCode)
    var resp = udpQuery(id: id, query: queryMsg, port: port)
    var usedTCP = false
    if let r = resp, r.count >= 12 {
        let flags = (UInt16(r[2]) << 8) | UInt16(r[3])
        let tc = (flags & 0x0200) != 0
        if tc {
            if let tcpResp = tcpQuery(id: id, query: queryMsg, port: port) {
                resp = tcpResp
                usedTCP = true
            }
        }
    }
    guard let data = resp, data.count >= 12 else {
        let outName = q.name.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))
        outLines.append("\(outName) \(q.typeStr) FORMERR")
        continue
    }
    let respId = (UInt16(data[0]) << 8) | UInt16(data[1])
    let flags = (UInt16(data[2]) << 8) | UInt16(data[3])
    let rcode = Int(flags & 0x000F)
    let outName = q.name.lowercased()
        .trimmingCharacters(in: CharacterSet(charactersIn: "."))
        .isEmpty ? "." : q.name.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))
    let rcodeStr: String
    switch rcode {
    case 0: rcodeStr = "NOERROR"
    case 1: rcodeStr = "FORMERR"
    case 2: rcodeStr = "SERVFAIL"
    case 3: rcodeStr = "NXDOMAIN"
    case 4: rcodeStr = "NOTIMP"
    case 5: rcodeStr = "REFUSED"
    default: rcodeStr = "RCODE\(rcode)"
    }
    outLines.append("\(outName) \(q.typeStr) \(rcodeStr)")
    // parse
    var offset = 12
    let qdcount = Int(readUInt16(data, off: 4))
    for _ in 0..<qdcount {
        let (_, next) = decodeName(at: offset, buffer: data)
        offset = next + 4
    }
    let ancount = Int(readUInt16(data, off: 6))
    var cur = offset
    for _ in 0..<ancount {
        let (owner, nextOff) = decodeName(at: cur, buffer: data)
        cur = nextOff
        guard cur + 10 <= data.count else { break }
        let ttl = readUInt32(data, off: cur)
        cur += 4
        let cls = readUInt16(data, off: cur); cur += 2
        let typ = readUInt16(data, off: cur); cur += 2
        let rdlen = Int(readUInt16(data, off: cur)); cur += 2
        guard cur + rdlen <= data.count else { break }
        let rdata = Array(data[cur..<(cur+rdlen)])
        cur += rdlen
        let ownerPrint = owner.isEmpty ? "." : owner.lowercased()
        let typePrint: String
        let dataPrint: String
        switch typ {
        case 1:
            typePrint = "A"
            if rdata.count >= 4 {
                let ip = "\(rdata[0]).\(rdata[1]).\(rdata[2]).\(rdata[3])"
                dataPrint = ip
            } else { dataPrint = "" }
        case 28:
            typePrint = "AAAA"
            if rdata.count >= 16 {
                dataPrint = formatAAAA(rdata)
            } else { dataPrint = "" }
        case 5:
            typePrint = "CNAME"
            let (target, _) = decodeName(at: cur - rdlen, buffer: data) // need proper offset? Simpler: parse from rdata bytes
            // decode name from rdata
            let nameBytes = rdata
            // quick decode using same function on a synthetic buffer
            let (tname, _) = decodeName(at: 0, buffer: nameBytes + [0])
            // Actually use helper on data slice
            // For simplicity, reuse decode on a copy
            let tmpBuf = nameBytes + [0]
            let (tname2, _) = decodeName(at: 0, buffer: tmpBuf)
            let t = tname2.isEmpty ? "." : tname2.lowercased()
            dataPrint = t
        default:
            break
        }
        // handle cases properly
        var finalType = ""
        var finalData = ""
        switch typ {
        case 1:
            finalType = "A"
            if rdata.count >= 4 {
                finalData = "\(rdata[0]).\(rdata[1]).\(rdata[2]).\(rdata[3])"
            }
        case 28:
            finalType = "AAAA"
            if rdata.count >= 16 {
                finalData = formatAAAA(rdata)
            }
        case 5:
            finalType = "CNAME"
            // decode target from rdata
            var ptr = 0
            var tlabels: [String] = []
            var tcur = 0
            var tjumped = false
            var tnext = 0
            // reuse decodeName on a temporary buffer referencing rdata
            let tmp = rdata
            // simple decode
            var tpos = 0
            var tlabels2: [String] = []
            var tcurPos = 0
            while tcurPos < tmp.count {
                let l = Int(tmp[tcurPos])
                if l & 0xC0 == 0xC0 { break }
                if l == 0 { break }
                let start = tcurPos + 1
                let end = start + l
                if end <= tmp.count {
                    let lab = String(bytes: tmp[start..<end], encoding: .utf8) ?? ""
                    tlabels2.append(lab)
                }
                tcurPos = end
            }
            let tname = tlabels2.joined(separator: ".")
            finalData = tname.isEmpty ? "." : tname.lowercased()
        case 15:
            finalType = "MX"
            if rdata.count >= 2 {
                let pref = (UInt16(rdata[0]) << 8) | UInt16(rdata[1])
                let rest = Array(rdata.dropFirst(2))
                // decode name from rest
                var restLabels: [String] = []
                var rp = 0
                while rp < rest.count {
                    let l = Int(rest[rp])
                    if l == 0 { break }
                    if l & 0xC0 == 0xC0 { break }
                    let start = rp + 1
                    let end = start + l
                    if end <= rest.count {
                        let lab = String(bytes: rest[start..<end], encoding: .utf8) ?? ""
                        restLabels.append(lab)
                    }
                    rp = end
                }
                let exch = restLabels.joined(separator: ".")
                let exchPrint = exch.isEmpty ? "." : exch.lowercased()
                finalData = "\(pref) \(exchPrint)"
            }
        case 16:
            finalType = "TXT"
            var parts: [String] = []
            var p = 0
            while p < rdata.count {
                let l = Int(rdata[p])
                p += 1
                if p + l > rdata.count { break }
                let slice = Array(rdata[p..<(p+l)])
                let esc = escapeTXT(slice)
                parts.append("\"\(esc)\"")
                p += l
            }
            finalData = parts.joined(separator: " ")
        default:
            finalType = "TYPE\(typ)"
            let hex = rdata.map { String(format: "%02x", $0) }.joined()
            finalData = "# \(rdlen) \(hex)"
        }
        outLines.append("  \(ownerPrint) \(ttl) \(finalType) \(finalData)")
    }
}

