import java.io.*;
import java.math.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Currency {
        int minor;
        Currency(int minor) { this.minor = minor; }
    }
    static class Account {
        String code;
        BigInteger balance; // in minor units
        BigInteger limit;   // in minor units
        int minor;
        Account(String code, int minor, BigInteger limit) {
            this.code = code;
            this.minor = minor;
            this.balance = BigInteger.ZERO;
            this.limit = limit;
        }
    }

    static Map<String, Currency> currencies = new HashMap<>();
    static Map<String, Account> accounts = new HashMap<>();

    static List<String> rejections = new ArrayList<>();

    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        Path p = Paths.get(args[0], "ledger.txt");
        List<String> lines = Files.readAllLines(p);
        int lineNo = 0;
        for (String raw : lines) {
            lineNo++;
            String trimmed = raw.trim();
            if (trimmed.isEmpty()) continue;
            if (trimmed.startsWith("#")) continue;
            processLine(raw, lineNo);
        }
        // output
        for (String r : rejections) System.out.println(r);
        System.out.println();
        List<Account> accList = new ArrayList<>(accounts.values());
        accList.sort(Comparator.comparing(a -> {
            // need name, we don't have name in Account. Use separate map.
            return "";
        }));
        // we need name -> account mapping, so sort by name
        List<Map.Entry<String, Account>> entries = new ArrayList<>(accounts.entrySet());
        entries.sort(Map.Entry.comparingByKey());
        for (Map.Entry<String, Account> e : entries) {
            String name = e.getKey();
            Account acc = e.getValue();
            System.out.println(name + " " + acc.code + " " + formatBalance(acc.balance, acc.minor));
        }
        System.out.println();
        // totals per currency
        Map<String, List<Account>> byCur = new HashMap<>();
        for (Map.Entry<String, Account> e : accounts.entrySet()) {
            byCur.computeIfAbsent(e.getValue().code, k -> new ArrayList<>()).add(e.getValue());
        }
        List<String> curCodes = new ArrayList<>(byCur.keySet());
        Collections.sort(curCodes);
        for (String code : curCodes) {
            List<Account> list = byCur.get(code);
            BigInteger sum = BigInteger.ZERO;
            for (Account a : list) sum = sum.add(a.balance);
            // all accounts of same currency have same minor
            int minor = list.get(0).minor;
            System.out.println("total " + code + " " + formatBalance(sum, minor) + " (" + list.size() + " accounts)");
        }
    }

    static void processLine(String raw, int lineNo) {
        String[] tok = raw.trim().split("\\s+");
        if (tok.length == 0) return;
        String cmd = tok[0];
        try {
            switch (cmd) {
                case "currency": {
                    String code = tok[1];
                    int minor = Integer.parseInt(tok[2]);
                    currencies.put(code, new Currency(minor));
                    break;
                }
                case "open": {
                    String name = tok[1];
                    String code = tok[2];
                    if (accounts.containsKey(name)) {
                        rejections.add("line " + lineNo + ": REJECT account exists " + name);
                        return;
                    }
                    Currency cur = currencies.get(code);
                    if (cur == null) return; // assume valid
                    BigInteger limit = BigInteger.ZERO;
                    if (tok.length > 3) {
                        limit = roundToMinor(tok[3], cur.minor).abs(); // limit is positive?
                        // limit is amount, we keep absolute?
                        // spec says limit rounded, default 0. Assume non-negative.
                    }
                    Account acc = new Account(code, cur.minor, limit);
                    accounts.put(name, acc);
                    break;
                }
                case "deposit": {
                    String name = tok[1];
                    if (!accounts.containsKey(name)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + name);
                        return;
                    }
                    Account acc = accounts.get(name);
                    BigInteger amt = roundToMinor(tok[2], acc.minor);
                    if (amt.signum() <= 0) {
                        rejections.add("line " + lineNo + ": REJECT non-positive amount");
                        return;
                    }
                    acc.balance = acc.balance.add(amt);
                    break;
                }
                case "withdraw": {
                    String name = tok[1];
                    if (!accounts.containsKey(name)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + name);
                        return;
                    }
                    Account acc = accounts.get(name);
                    BigInteger amt = roundToMinor(tok[2], acc.minor);
                    if (amt.signum() <= 0) {
                        rejections.add("line " + lineNo + ": REJECT non-positive amount");
                        return;
                    }
                    if (acc.balance.subtract(amt).compareTo(acc.limit.negate()) < 0) {
                        rejections.add("line " + lineNo + ": REJECT insufficient funds " + name);
                        return;
                    }
                    acc.balance = acc.balance.subtract(amt);
                    break;
                }
                case "transfer": {
                    String from = tok[1];
                    String to = tok[2];
                    if (!accounts.containsKey(from)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + from);
                        return;
                    }
                    if (!accounts.containsKey(to)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + to);
                        return;
                    }
                    Account aFrom = accounts.get(from);
                    Account aTo = accounts.get(to);
                    if (!aFrom.code.equals(aTo.code)) {
                        rejections.add("line " + lineNo + ": REJECT currency mismatch");
                        return;
                    }
                    BigInteger amt = roundToMinor(tok[3], aFrom.minor);
                    if (amt.signum() <= 0) {
                        rejections.add("line " + lineNo + ": REJECT non-positive amount");
                        return;
                    }
                    if (aFrom.balance.subtract(amt).compareTo(aFrom.limit.negate()) < 0) {
                        rejections.add("line " + lineNo + ": REJECT insufficient funds " + from);
                        return;
                    }
                    aFrom.balance = aFrom.balance.subtract(amt);
                    aTo.balance = aTo.balance.add(amt);
                    break;
                }
                case "convert": {
                    String from = tok[1];
                    String to = tok[2];
                    if (!accounts.containsKey(from)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + from);
                        return;
                    }
                    if (!accounts.containsKey(to)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + to);
                        return;
                    }
                    Account aFrom = accounts.get(from);
                    Account aTo = accounts.get(to);
                    BigInteger amtFrom = roundToMinor(tok[3], aFrom.minor);
                    if (amtFrom.signum() <= 0) {
                        rejections.add("line " + lineNo + ": REJECT non-positive amount");
                        return;
                    }
                    if (aFrom.balance.subtract(amtFrom).compareTo(aFrom.limit.negate()) < 0) {
                        rejections.add("line " + lineNo + ": REJECT insufficient funds " + from);
                        return;
                    }
                    // compute conversion
                    BigDecimal amountVal = new BigDecimal(amtFrom).movePointLeft(aFrom.minor);
                    BigDecimal rate = new BigDecimal(tok[4]);
                    BigDecimal convertedVal = amountVal.multiply(rate);
                    BigDecimal convertedRounded = convertedVal.setScale(aTo.minor, RoundingMode.HALF_EVEN);
                    BigInteger amtTo = convertedRounded.unscaledValue();
                    aFrom.balance = aFrom.balance.subtract(amtFrom);
                    aTo.balance = aTo.balance.add(amtTo);
                    break;
                }
                case "interest": {
                    String name = tok[1];
                    if (!accounts.containsKey(name)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + name);
                        return;
                    }
                    Account acc = accounts.get(name);
                    BigDecimal rate = new BigDecimal(tok[2]);
                    BigDecimal balVal = new BigDecimal(acc.balance).movePointLeft(acc.minor);
                    BigDecimal newVal = balVal.multiply(BigDecimal.ONE.add(rate));
                    BigDecimal newRounded = newVal.setScale(acc.minor, RoundingMode.HALF_EVEN);
                    BigInteger newBal = newRounded.unscaledValue();
                    BigInteger newBalSigned = newBal; // already signed via BigDecimal
                    // check limit
                    if (newBalSigned.compareTo(acc.limit.negate()) < 0) {
                        rejections.add("line " + lineNo + ": REJECT insufficient funds " + name);
                        return;
                    }
                    acc.balance = newBalSigned;
                    break;
                }
                case "split": {
                    String from = tok[1];
                    if (!accounts.containsKey(from)) {
                        rejections.add("line " + lineNo + ": REJECT unknown account " + from);
                        return;
                    }
                    Account aFrom = accounts.get(from);
                    // collect targets in order
                    List<String> targetNames = new ArrayList<>();
                    List<BigInteger> weights = new ArrayList<>();
                    for (int i = 3; i < tok.length; i++) {
                        String[] parts = tok[i].split(":");
                        if (parts.length != 2) continue;
                        String tName = parts[0];
                        String wStr = parts[1];
                        targetNames.add(tName);
                        weights.add(new BigInteger(wStr));
                        if (!accounts.containsKey(tName)) {
                            rejections.add("line " + lineNo + ": REJECT unknown account " + tName);
                            return;
                        }
                    }
                    // currency mismatch
                    for (String tName : targetNames) {
                        Account aT = accounts.get(tName);
                        if (!aT.code.equals(aFrom.code)) {
                            rejections.add("line " + lineNo + ": REJECT currency mismatch");
                            return;
                        }
                    }
                    BigInteger A = roundToMinor(tok[2], aFrom.minor);
                    if (A.signum() <= 0) {
                        rejections.add("line " + lineNo + ": REJECT non-positive amount");
                        return;
                    }
                    if (aFrom.balance.subtract(A).compareTo(aFrom.limit.negate()) < 0) {
                        rejections.add("line " + lineNo + ": REJECT insufficient funds " + from);
                        return;
                    }
                    // distribution
                    BigInteger W = BigInteger.ZERO;
                    for (BigInteger w : weights) W = W.add(w);
                    int n = targetNames.size();
                    BigInteger[] floors = new BigInteger[n];
                    BigInteger[] rems = new BigInteger[n];
                    BigInteger sumFloors = BigInteger.ZERO;
                    for (int i = 0; i < n; i++) {
                        BigInteger total = A.multiply(weights.get(i));
                        BigInteger floor = total.divide(W);
                        BigInteger rem = total.mod(W);
                        floors[i] = floor;
                        rems[i] = rem;
                        sumFloors = sumFloors.add(floor);
                    }
                    BigInteger leftover = A.subtract(sumFloors);
                    Integer[] idx = new Integer[n];
                    for (int i = 0; i < n; i++) idx[i] = i;
                    Arrays.sort(idx, (i, j) -> {
                        int cmp = rems[j].compareTo(rems[i]); // descending
                        if (cmp != 0) return cmp;
                        return Integer.compare(i, j);
                    });
                    BigInteger[] alloc = floors.clone();
                    for (int k = 0; k < leftover.intValue(); k++) {
                        int i = idx[k];
                        alloc[i] = alloc[i].add(BigInteger.ONE);
                    }
                    // apply
                    aFrom.balance = aFrom.balance.subtract(A);
                    for (int i = 0; i < n; i++) {
                        Account aT = accounts.get(targetNames.get(i));
                        aT.balance = aT.balance.add(alloc[i]);
                    }
                    break;
                }
            }
        } catch (Exception e) {
            // ignore malformed? assume input valid
        }
    }

    static BigInteger roundToMinor(String s, int minor) {
        BigDecimal bd = new BigDecimal(s);
        bd = bd.setScale(minor, RoundingMode.HALF_EVEN);
        return bd.unscaledValue();
    }

    static String formatBalance(BigInteger minorUnits, int minor) {
        if (minorUnits.signum() == 0) {
            if (minor == 0) return "0";
            return "0." + "0".repeat(minor);
        }
        boolean neg = minorUnits.signum() < 0;
        BigInteger abs = minorUnits.abs();
        BigInteger pow = BigInteger.TEN.pow(minor);
        BigInteger intPart = abs.divide(pow);
        BigInteger fracPart = abs.mod(pow);
        String intStr = insertCommas(intPart.toString());
        String out;
        if (minor == 0) {
            out = intStr;
        } else {
            String fracStr = String.format("%0" + minor + "d", fracPart);
            out = intStr + "." + fracStr;
        }
        if (neg) out = "-" + out;
        return out;
    }

    static String insertCommas(String s) {
        StringBuilder sb = new StringBuilder();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            sb.append(s.charAt(i));
            int pos = len - i - 1;
            if (pos > 0 && pos % 3 == 0) sb.append(',');
        }
        return sb.toString();
    }
}

