import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 2) return;
        String dir = args[0];
        int port = Integer.parseInt(args[1]);
        File f = new File(dir, "queries.txt");
        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(f))) {
            String l;
            while ((l = br.readLine()) != null) {
                if (l.trim().isEmpty()) continue;
                lines.add(l.trim());
            }
        }
        InetAddress addr = InetAddress.getByName("127.0.0.1");
        int idx = 0;
        for (String line : lines) {
            String[] parts = line.split("\\s+");
            if (parts.length < 2) continue;
            String qnameRaw = parts[0];
            String qtypeStr = parts[1];
            int qtype = typeToInt(qtypeStr);
            String nameOut = normalizeName(qnameRaw);
            // build query
            byte[] query = buildQuery(qnameRaw, qtype);
            int id = ((query[0] & 0xFF) << 8) | (query[1] & 0xFF);
            byte[] response = sendUdp(addr, port, query);
            int flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
            int respId = ((response[0] & 0xFF) << 8) | (response[1] & 0xFF);
            // if different id or QR !=1, try again (simple loop)
            // In practice we already filtered by id
            if (respId != id || ((flags >> 15) & 1) == 0) {
                // try again quickly
                response = sendUdp(addr, port, query);
                flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
            }
            boolean tc = ((flags >> 1) & 1) == 1;
            if (tc) {
                response = sendTcp(addr, port, query);
                // strip length prefix
                if (response.length >= 2) {
                    int len = ((response[0] & 0xFF) << 8) | (response[1] & 0xFF);
                    byte[] msg = Arrays.copyOfRange(response, 2, 2 + len);
                    response = msg;
                }
            }
            int rcode = flags & 0xF;
            String rcodeStr = rcodeName(rcode);
            System.out.println(nameOut + " " + qtypeStr.toUpperCase() + " " + rcodeStr);
            // parse
            ParsedResponse pr = parseResponse(response);
            for (Record rec : pr.records) {
                String owner = rec.owner.isEmpty() ? "." : rec.owner;
                System.out.println("  " + owner + " " + rec.ttl + " " + rec.typeName + " " + rec.data);
            }
        }
    }

    private static String normalizeName(String raw) {
        String s = raw;
        if (s.endsWith(".")) s = s.substring(0, s.length() - 1);
        s = s.toLowerCase(Locale.ROOT);
        if (s.isEmpty()) return ".";
        return s;
    }

    private static int typeToInt(String t) {
        switch (t.toUpperCase()) {
            case "A": return 1;
            case "AAAA": return 28;
            case "MX": return 15;
            case "TXT": return 16;
            case "CNAME": return 5;
            default: return 1;
        }
    }

    private static byte[] buildQuery(String qnameRaw, int qtype) {
        Random rnd = new Random();
        int id = rnd.nextInt(65536);
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        baos.write(id >> 8); baos.write(id & 0xFF);
        baos.write(0x01); baos.write(0x00); // flags 0x0100
        baos.write(0); baos.write(1); // QDCOUNT
        baos.write(0); baos.write(0);
        baos.write(0); baos.write(0);
        baos.write(0); baos.write(0);
        // QNAME
        String name = qnameRaw;
        if (name.endsWith(".")) name = name.substring(0, name.length() - 1);
        if (!name.isEmpty()) {
            String[] labels = name.split("\\.");
            for (String lab : labels) {
                byte[] lb = lab.getBytes(StandardCharsets.US_ASCII);
                baos.write(lb.length);
                baos.write(lb, 0, lb.length);
            }
        }
        baos.write(0);
        baos.write(qtype >> 8); baos.write(qtype & 0xFF);
        baos.write(0); baos.write(1); // CLASS IN
        return baos.toByteArray();
    }

    private static byte[] sendUdp(InetAddress addr, int port, byte[] query) throws IOException {
        DatagramSocket ds = new DatagramSocket();
        ds.setSoTimeout(2000);
        DatagramPacket sendP = new DatagramPacket(query, query.length, addr, port);
        ds.send(sendP);
        int id = ((query[0] & 0xFF) << 8) | (query[1] & 0xFF);
        byte[] buf = new byte[4096];
        DatagramPacket recvP = new DatagramPacket(buf, buf.length);
        while (true) {
            ds.receive(recvP);
            byte[] data = Arrays.copyOfRange(recvP.getData(), recvP.getOffset(), recvP.getOffset() + recvP.getLength());
            int respId = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
            if (respId != id) continue;
            int flags = ((data[2] & 0xFF) << 8) | (data[3] & 0xFF);
            int qr = (flags >> 15) & 1;
            if (qr == 1) {
                ds.close();
                return data;
            }
        }
    }

    private static byte[] sendTcp(InetAddress addr, int port, byte[] query) throws IOException {
        Socket s = new Socket(addr, port);
        OutputStream os = s.getOutputStream();
        os.write((query.length >> 8) & 0xFF);
        os.write(query.length & 0xFF);
        os.write(query);
        os.flush();
        InputStream is = s.getInputStream();
        byte[] lenBuf = new byte[2];
        readFully(is, lenBuf);
        int len = ((lenBuf[0] & 0xFF) << 8) | (lenBuf[1] & 0xFF);
        byte[] data = new byte[len + 2];
        data[0] = lenBuf[0];
        data[1] = lenBuf[1];
        readFully(is, data, 2, len);
        s.close();
        return data;
    }

    private static void readFully(InputStream is, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int r = is.read(buf, off, buf.length - off);
            if (r == -1) throw new EOFException();
            off += r;
        }
    }
    private static void readFully(InputStream is, byte[] buf, int off, int len) throws IOException {
        int read = 0;
        while (read < len) {
            int r = is.read(buf, off + read, len - read);
            if (r == -1) throw new EOFException();
            read += r;
        }
    }

    private static String rcodeName(int r) {
        switch (r) {
            case 0: return "NOERROR";
            case 1: return "FORMERR";
            case 2: return "SERVFAIL";
            case 3: return "NXDOMAIN";
            case 4: return "NOTIMP";
            case 5: return "REFUSED";
            default: return "RCODE" + r;
        }
    }

    private static ParsedResponse parseResponse(byte[] data) {
        int pos = 12;
        int qdcount = ((data[4] & 0xFF) << 8) | (data[5] & 0xFF);
        int ancount = ((data[6] & 0xFF) << 8) | (data[7] & 0xFF);
        for (int i = 0; i < qdcount; i++) {
            pos = skipName(data, pos);
            pos += 4;
        }
        List<Record> recs = new ArrayList<>();
        for (int i = 0; i < ancount; i++) {
            int ownerPos = pos;
            String owner = resolveName(data, ownerPos).toLowerCase(Locale.ROOT);
            pos = skipName(data, pos);
            int type = ((data[pos] & 0xFF) << 8) | (data[pos + 1] & 0xFF);
            pos += 2;
            pos += 2; // class
            int ttl = ((data[pos] & 0xFF) << 24) | ((data[pos + 1] & 0xFF) << 16) | ((data[pos + 2] & 0xFF) << 8) | (data[pos + 3] & 0xFF);
            pos += 4;
            int rdlen = ((data[pos] & 0xFF) << 8) | (data[pos + 1] & 0xFF);
            pos += 2;
            int rdataPos = pos;
            String typeName;
            String dataStr;
            if (type == 1) {
                typeName = "A";
                dataStr = ipv4ToString(data, rdataPos);
            } else if (type == 28) {
                typeName = "AAAA";
                dataStr = ipv6ToString(data, rdataPos);
            } else if (type == 5) {
                typeName = "CNAME";
                String target = resolveName(data, rdataPos).toLowerCase(Locale.ROOT);
                dataStr = target;
            } else if (type == 15) {
                typeName = "MX";
                int pref = ((data[rdataPos] & 0xFF) << 8) | (data[rdataPos + 1] & 0xFF);
                String exch = resolveName(data, rdataPos + 2).toLowerCase(Locale.ROOT);
                dataStr = pref + " " + exch;
            } else if (type == 16) {
                typeName = "TXT";
                dataStr = txtToString(data, rdataPos, rdlen);
            } else {
                typeName = "TYPE" + type;
                StringBuilder sb = new StringBuilder();
                sb.append("\\# ").append(rdlen);
                if (rdlen > 0) {
                    sb.append(' ');
                    for (int j = 0; j < rdlen; j++) {
                        sb.append(String.format("%02x", data[rdataPos + j] & 0xFF));
                    }
                }
                dataStr = sb.toString();
            }
            recs.add(new Record(owner, ttl, typeName, dataStr));
            pos += rdlen;
        }
        return new ParsedResponse(recs);
    }

    private static int skipName(byte[] data, int pos) {
        while (true) {
            int len = data[pos] & 0xFF;
            if ((len & 0xC0) == 0xC0) {
                pos += 2;
                break;
            }
            if (len == 0) {
                pos += 1;
                break;
            }
            pos += 1 + len;
        }
        return pos;
    }

    private static String resolveName(byte[] data, int pos) {
        if (pos >= data.length) return "";
        int len = data[pos] & 0xFF;
        if ((len & 0xC0) == 0xC0) {
            int pointer = ((len & 0x3F) << 8) | (data[pos + 1] & 0xFF);
            return resolveName(data, pointer);
        }
        if (len == 0) return "";
        String label = new String(data, pos + 1, len, StandardCharsets.US_ASCII);
        int next = pos + 1 + len;
        if (next >= data.length) return label;
        int nextLen = data[next] & 0xFF;
        if (nextLen == 0) return label;
        if ((nextLen & 0xC0) == 0xC0) {
            String rest = resolveName(data, next);
            return label + "." + rest;
        } else {
            String rest = resolveName(data, next);
            return label + "." + rest;
        }
    }

    private static String ipv4ToString(byte[] data, int pos) {
        return (data[pos] & 0xFF) + "." + (data[pos + 1] & 0xFF) + "." + (data[pos + 2] & 0xFF) + "." + (data[pos + 3] & 0xFF);
    }

    private static String ipv6ToString(byte[] data, int pos) {
        int[] g = new int[8];
        for (int i = 0; i < 8; i++) {
            int hi = data[pos + 2 * i] & 0xFF;
            int lo = data[pos + 2 * i + 1] & 0xFF;
            g[i] = (hi << 8) | lo;
        }
        String[] hex = new String[8];
        for (int i = 0; i < 8; i++) {
            hex[i] = Integer.toHexString(g[i]);
        }
        // find longest zero run >=2
        int bestStart = -1, bestLen = 0;
        int curStart = -1, curLen = 0;
        for (int i = 0; i < 8; i++) {
            if (g[i] == 0) {
                if (curStart == -1) { curStart = i; curLen = 1; }
                else curLen++;
            } else {
                if (curLen >= 2 && curLen > bestLen) { bestLen = curLen; bestStart = curStart; }
                curStart = -1; curLen = 0;
            }
        }
        if (curLen >= 2 && curLen > bestLen) { bestLen = curLen; bestStart = curStart; }
        if (bestLen < 2) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                if (i > 0) sb.append(':');
                sb.append(hex[i]);
            }
            return sb.toString();
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 8; i++) {
            if (i == bestStart) {
                sb.append("::");
                i += bestLen - 1;
                continue;
            }
            if (sb.length() > 0 && sb.charAt(sb.length() - 1) != ':') sb.append(':');
            if (i < bestStart || i >= bestStart + bestLen) {
                sb.append(hex[i]);
            }
        }
        // handle edge cases where :: at start/end
        String out = sb.toString();
        if (out.startsWith("::")) {
            // ok
        }
        if (out.endsWith("::")) {
            // ok
        }
        // normalize double colon
        return out.replace(":::", "::").replace(":::", "::");
    }

    private static String txtToString(byte[] data, int pos, int rdlen) {
        StringBuilder out = new StringBuilder();
        int p = pos;
        int end = pos + rdlen;
        boolean first = true;
        while (p < end) {
            int len = data[p] & 0xFF;
            p++;
            byte[] str = Arrays.copyOfRange(data, p, p + len);
            p += len;
            String esc = escapeTxt(str);
            if (!first) out.append(' ');
            out.append('"').append(esc).append('"');
            first = false;
        }
        if (out.length() == 0) out.append("\"\"");
        return out.toString();
    }

    private static String escapeTxt(byte[] s) {
        StringBuilder sb = new StringBuilder();
        for (byte b : s) {
            int v = b & 0xFF;
            if (v == '"') sb.append("\\\"");
            else if (v == '\\') sb.append("\\\\");
            else if (v >= 0x20 && v <= 0x7E) sb.append((char) v);
            else sb.append('\\').append(String.format("%03d", v));
        }
        return sb.toString();
    }

    static class Record {
        String owner, typeName, data;
        int ttl;
        Record(String o, int t, String tn, String d) { owner = o; ttl = t; typeName = tn; data = d; }
    }
    static class ParsedResponse {
        List<Record> records;
        ParsedResponse(List<Record> r) { records = r; }
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 2) return;
        String dir = args[0];
        int port = Integer.parseInt(args[1]);
        File f = new File(dir, "queries.txt");
        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(f))) {
            String l;
            while ((l = br.readLine()) != null) {
                if (l.trim().isEmpty()) continue;
                lines.add(l.trim());
            }
        }
        InetAddress addr = InetAddress.getByName("127.0.0.1");
        Random rnd = new Random();
        for (String line : lines) {
            String[] parts = line.split("\\s+");
            if (parts.length < 2) continue;
            String qnameRaw = parts[0];
            String qtypeStr = parts[1].toUpperCase();
            int qtype = typeToInt(qtypeStr);
            String nameOut = normalizeName(qnameRaw);
            byte[] query = buildQuery(qnameRaw, qtype, rnd);
            int id = ((query[0] & 0xFF) << 8) | (query[1] & 0xFF);
            byte[] response = sendUdp(addr, port, query, id);
            int flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
            boolean tc = (flags & 0x0200) != 0;
            if (tc) {
                byte[] tcpResp = sendTcp(addr, port, query);
                response = tcpResp;
                flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
            }
            int rcode = flags & 0xF;
            String rcodeStr = rcodeName(rcode);
            System.out.println(nameOut + " " + qtypeStr + " " + rcodeStr);
            ParsedResponse pr = parseResponse(response);
            for (Record rec : pr.records) {
                String owner = rec.owner.isEmpty() ? "." : rec.owner;
                System.out.println("  " + owner + " " + rec.ttl + " " + rec.typeName + " " + rec.data);
            }
        }
    }

    private static String normalizeName(String raw) {
        String s = raw;
        if (s.endsWith(".")) s = s.substring(0, s.length() - 1);
        s = s.toLowerCase(Locale.ROOT);
        if (s.isEmpty()) return ".";
        return s;
    }

    private static int typeToInt(String t) {
        switch (t) {
            case "A": return 1;
            case "AAAA": return 28;
            case "MX": return 15;
            case "TXT": return 16;
            case "CNAME": return 5;
            default: return 1;
        }
    }

    private static byte[] buildQuery(String qnameRaw, int qtype, Random rnd) {
        int id = rnd.nextInt(65536);
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        baos.write(id >> 8); baos.write(id & 0xFF);
        baos.write(0x01); baos.write(0x00); // flags 0x0100
        baos.write(0); baos.write(1); // QDCOUNT
        baos.write(0); baos.write(0); // ANCOUNT
        baos.write(0); baos.write(0); // NSCOUNT
        baos.write(0); baos.write(0); // ARCOUNT
        String name = qnameRaw;
        if (name.endsWith(".")) name = name.substring(0, name.length() - 1);
        if (!name.isEmpty()) {
            String[] labels = name.split("\\.");
            for (String lab : labels) {
                byte[] lb = lab.getBytes(StandardCharsets.US_ASCII);
                baos.write(lb.length);
                baos.write(lb, 0, lb.length);
            }
        }
        baos.write(0);
        baos.write(qtype >> 8); baos.write(qtype & 0xFF);
        baos.write(0); baos.write(1);
        return baos.toByteArray();
    }

    private static byte[] sendUdp(InetAddress addr, int port, byte[] query, int id) throws IOException {
        DatagramSocket ds = new DatagramSocket();
        ds.setSoTimeout(2000);
        DatagramPacket sendP = new DatagramPacket(query, query.length, addr, port);
        ds.send(sendP);
        byte[] buf = new byte[4096];
        DatagramPacket recvP = new DatagramPacket(buf, buf.length);
        while (true) {
            ds.receive(recvP);
            byte[] data = Arrays.copyOfRange(recvP.getData(), recvP.getOffset(), recvP.getOffset() + recvP.getLength());
            int respId = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
            if (respId != id) continue;
            int flags = ((data[2] & 0xFF) << 8) | (data[3] & 0xFF);
            int qr = (flags >> 15) & 1;
            if (qr == 1) {
                ds.close();
                return data;
            }
        }
    }

    private static byte[] sendTcp(InetAddress addr, int port, byte[] query) throws IOException {
        Socket s = new Socket(addr, port);
        OutputStream os = s.getOutputStream();
        os.write((query.length >> 8) & 0xFF);
        os.write(query.length & 0xFF);
        os.write(query);
        os.flush();
        InputStream is = s.getInputStream();
        byte[] lenBuf = new byte[2];
        readFully(is, lenBuf);
        int len = ((lenBuf[0] & 0xFF) << 8) | (lenBuf[1] & 0xFF);
        byte[] data = new byte[len];
        readFully(is, data);
        s.close();
        return data;
    }

    private static void readFully(InputStream is, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int r = is.read(buf, off, buf.length - off);
            if (r == -1) throw new EOFException();
            off += r;
        }
    }

