    private static String decodeName(byte[] data, int offset) {
        StringBuilder sb = new StringBuilder();
        int pos = offset;
        Set<Integer> seen = new HashSet<>();
        boolean first = true;
        while (true) {
            if (pos >= data.length) break;
            if (seen.contains(pos)) break;
            seen.add(pos);
            int len = data[pos] & 0xFF;
            if ((len & 0xC0) == 0xC0) {
                int pointer = ((len & 0x3F) << 8) | (data[pos + 1] & 0xFF);
                pos = pointer;
                continue;
            }
            if (len == 0) {
                break;
            }
            pos++;
            if (pos + len > data.length) break;
            String label = new String(data, pos, len, StandardCharsets.US_ASCII);
            if (!first) sb.append('.');
            sb.append(label.toLowerCase(Locale.ROOT));
            first = false;
            pos += len;
        }
        return sb.toString();
    }

    private static String ipv4ToString(byte[] data, int pos) {
