    }

    private static String ipv6ToString(byte[] data, int pos) {
        int[] g = new int[8];
        for (int i = 0; i < 8; i++) {
            int hi = data[pos + 2 * i] & 0xFF;
            int lo = data[pos + 2 * i + 1] & 0xFF;
            g[i] = (hi << 8) | lo;
        }
        String[] hex = new String[8];
        for (int i = 0; i < 8; i++) hex[i] = Integer.toHexString(g[i]);
        int bestStart = -1, bestLen = 0;
        int i = 0;
        while (i < 8) {
            if (g[i] == 0) {
                int start = i;
                int len = 0;
                while (i < 8 && g[i] == 0) { len++; i++; }
                if (len >= 2 && len > bestLen) { bestLen = len; bestStart = start; }
            } else i++;
        }
        if (bestLen < 2) {
            StringBuilder sb = new StringBuilder();
            for (int k = 0; k < 8; k++) {
                if (k > 0) sb.append(':');
                sb.append(hex[k]);
            }
            return sb.toString();
        }
        StringBuilder left = new StringBuilder();
        for (int k = 0; k < bestStart; k++) {
            if (k > 0) left.append(':');
            left.append(hex[k]);
        }
        StringBuilder right = new StringBuilder();
        for (int k = bestStart + bestLen; k < 8; k++) {
            if (right.length() > 0) right.append(':');
            right.append(hex[k]);
        }
        String leftStr = left.toString();
        String rightStr = right.toString();
        if (leftStr.isEmpty() && rightStr.isEmpty()) return "::";
        if (leftStr.isEmpty()) return "::" + rightStr;
        if (rightStr.isEmpty()) return leftStr + "::";
        return leftStr + "::" + rightStr;
    }

    private static String txtToString(byte[] data, int pos, int rdlen) {
        StringBuilder out = new StringBuilder();
        int p = pos;
        int end = pos + rdlen;
        boolean first = true;
        while (p < end) {
            int len = data[p] & 0xFF;
            p++;
            if (p + len > end) len = end - p;
            byte[] str = Arrays.copyOfRange(data, p, p + len);
            p += len;
            String esc = escapeTxt(str);
            if (!first) out.append(' ');
            out.append('"').append(esc).append('"');
            first = false;
        }
        if (out.length() == 0) out.append("\"\"");
        return out.toString();
    }

    private static String escapeTxt(byte[] s) {
