import sys
import os
import socket
import random
import struct

TYPE_MAP = {
    'A': 1,
    'AAAA': 28,
    'CNAME': 5,
    'MX': 15,
    'TXT': 16,
}
TYPE_NAME = {1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA'}

def build_query(name_raw, qtype_num):
    nid = random.randint(0, 65535)
    flags = 0x0100
    header = struct.pack('>HHHHHH', nid, flags, 1, 0, 0, 0)
    name_stripped = name_raw.rstrip('.')
    if name_stripped == '':
        labels = []
    else:
        labels = name_stripped.split('.')
    qname = b''
    for lab in labels:
        lab_b = lab.encode('ascii', errors='ignore')
        if len(lab_b) > 63:
            lab_b = lab_b[:63]
        qname += struct.pack('B', len(lab_b)) + lab_b
    qname += b'\x00'
    qrest = struct.pack('>HH', qtype_num, 1)
    return nid, header + qname + qrest

def read_name(data, offset):
    labels = []
    pos = offset
    end_offset = offset
    jumped = False
    visited = set()
    while True:
        if pos >= len(data) or pos in visited:
            break
        visited.add(pos)
        if pos + 1 > len(data):
            break
        length = data[pos]
        if (length & 0xC0) == 0xC0:
            if not jumped:
                end_offset = pos + 2
                jumped = True
            pointer = ((length & 0x3F) << 8) | data[pos + 1]
            pos = pointer
            continue
        if length == 0:
            pos += 1
            if not jumped:
                end_offset = pos
            break
        pos += 1
        if pos + length > len(data):
            break
        label_bytes = data[pos:pos + length]
        try:
            label = label_bytes.decode('ascii')
        except:
            label = label_bytes.decode('latin-1')
        labels.append(label)
        pos += length
    if labels:
        name = '.'.join(labels).lower()
    else:
        name = ''
    return name, end_offset

def format_ipv6(data_bytes):
    groups = []
    for i in range(8):
        val = int.from_bytes(data_bytes[i*2:(i+1)*2], 'big')
        groups.append(val)
    best_start = -1
    best_len = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            start = i
            while i < 8 and groups[i] == 0:
                i += 1
            run_len = i - start
            if run_len >= 2 and run_len > best_len:
                best_len = run_len
                best_start = start
        else:
            i += 1
    if best_len < 2:
        return ':'.join(format(g, 'x') for g in groups)
    if best_start == 0 and best_len == 8:
        return '::'
    before = groups[:best_start]
    after = groups[best_start + best_len:]
    before_str = ':'.join(format(g, 'x') for g in before) if before else ''
    after_str = ':'.join(format(g, 'x') for g in after) if after else ''
    if not before_str:
        return '::' + after_str
    if not after_str:
        return before_str + '::'
    return before_str + '::' + after_str

def escape_txt(s_bytes):
    out = []
    for b in s_bytes:
        if b == 0x22:
            out.append('\\"')
        elif b == 0x5c:
            out.append('\\\\')
        elif 0x20 <= b <= 0x7e:
            out.append(chr(b))
        else:
            out.append(f'\\{b:03d}')
    return ''.join(out)

def parse_response(data):
    if len(data) < 12:
        return None
    flags = struct.unpack('>H', data[2:4])[0]
    rcode = flags & 0x0F
    qdcount = struct.unpack('>H', data[4:6])[0]
    ancount = struct.unpack('>H', data[6:8])[0]
    offset = 12
    for _ in range(qdcount):
        _, offset = read_name(data, offset)
        offset += 4
    answers = []
    for _ in range(ancount):
        owner, offset = read_name(data, offset)
        if offset + 10 > len(data):
            break
        rtype = struct.unpack('>H', data[offset:offset+2])[0]
        offset += 2
        offset += 2  # class
        ttl = struct.unpack('>I', data[offset:offset+4])[0]
        offset += 4
        rdlen = struct.unpack('>H', data[offset:offset+2])[0]
        offset += 2
        rdata_start = offset
        if rtype == 1:
            if rdlen >= 4:
                ip = '.'.join(str(b) for b in data[rdata_start:rdata_start+4])
                data_str = ip
            else:
                data_str = ''
            offset = rdata_start + rdlen
        elif rtype == 28:
            if rdlen >= 16:
                data_str = format_ipv6(data[rdata_start:rdata_start+16])
            else:
                data_str = ''
            offset = rdata_start + rdlen
        elif rtype == 5:
            target, new_off = read_name(data, rdata_start)
            data_str = target if target else '.'
            offset = new_off
        elif rtype == 15:
            if rdlen >= 2:
                pref = struct.unpack('>H', data[rdata_start:rdata_start+2])[0]
                target, new_off = read_name(data, rdata_start+2)
                exchange = target if target else '.'
                data_str = f'{pref} {exchange}'
                offset = new_off
            else:
                data_str = ''
                offset = rdata_start + rdlen
        elif rtype == 16:
            pos = rdata_start
            end = rdata_start + rdlen
            parts = []
            while pos < end:
                if pos >= len(data):
                    break
                l = data[pos]
                pos += 1
                if pos + l > end:
                    s = data[pos:end]
                    pos = end
                else:
                    s = data[pos:pos+l]
                    pos += l
                esc = escape_txt(s)
                parts.append(f'"{esc}"')
            data_str = ' '.join(parts)
            offset = rdata_start + rdlen
        else:
            rdata_bytes = data[rdata_start:rdata_start+rdlen]
            hex_str = ''.join(f'{b:02x}' for b in rdata_bytes)
            data_str = f'\\# {rdlen}' + (f' {hex_str}' if rdlen else '')
            offset = rdata_start + rdlen
        answers.append((owner, ttl, rtype, data_str))
    return rcode, answers

def send_udp_query(port, nid, packet):
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(2.0)
    s.sendto(packet, ('127.0.0.1', port))
    while True:
        try:
            data, _ = s.recvfrom(4096)
        except socket.timeout:
            return None
        if len(data) < 12:
            continue
        resp_id = struct.unpack('>H', data[0:2])[0]
        if resp_id != nid:
            continue
        flags = struct.unpack('>H', data[2:4])[0]
        if ((flags >> 15) & 1) != 1:
            continue
        return data

def send_tcp_query(port, packet):
    s = socket.create_connection(('127.0.0.1', port), timeout=2)
    s.sendall(struct.pack('>H', len(packet)) + packet)
    buf = b''
    while len(buf) < 2:
        chunk = s.recv(2 - len(buf))
        if not chunk:
            s.close()
            return None
        buf += chunk
    length = struct.unpack('>H', buf)[0]
    data = b''
    while len(data) < length:
        chunk = s.recv(length - len(data))
        if not chunk:
            break
        data += chunk
    s.close()
    return data

def normalize_name(name):
    name = name.lower().rstrip('.')
    return '.' if name == '' else name

def main():
    if len(sys.argv) != 3:
        return
    directory = sys.argv[1]
    port = int(sys.argv[2])
    queries_path = os.path.join(directory, 'queries.txt')
    with open(queries_path, 'r', encoding='utf-8', errors='ignore') as f:
        lines = f.readlines()
    out = []
    rcode_map = {0:'NOERROR',1:'FORMERR',2:'SERVFAIL',3:'NXDOMAIN',4:'NOTIMP',5:'REFUSED'}
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        qname_raw = parts[0]
        qtype_str = parts[1].upper()
        qtype_num = TYPE_MAP.get(qtype_str, 1)
        nid, packet = build_query(qname_raw, qtype_num)
        resp_data = send_udp_query(port, nid, packet)
        if resp_data:
            flags = struct.unpack('>H', resp_data[2:4])[0]
            tc = (flags >> 9) & 1
            if tc == 1:
                resp_data = send_tcp_query(port, packet)
        if not resp_data:
            name_out = normalize_name(qname_raw)
            out.append(f'{name_out} {qtype_str} SERVFAIL')
            continue
        parsed_rcode, answers = parse_response(resp_data)
        if parsed_rcode is None:
            parsed_rcode = 2
            answers = []
        name_out = normalize_name(qname_raw)
        rcode_str = rcode_map.get(parsed_rcode, f'RCODE{parsed_rcode}')
        out.append(f'{name_out} {qtype_str} {rcode_str}')
        for owner, ttl, rtype, data_str in answers:
            owner_out = owner if owner else '.'
            if rtype in TYPE_NAME:
                type_name = TYPE_NAME[rtype]
            else:
                type_name = f'TYPE{rtype}'
                # data_str already contains \# ...
            out.append(f'  {owner_out} {ttl} {type_name} {data_str}')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Main {
    static class KeyInfo {
        String kid;
        String alg;
        byte[] secret;
    }

    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        Path dir = Paths.get(args[0]);
        String configJson = Files.readString(dir.resolve("config.json"), StandardCharsets.UTF_8);
        String tokensText = Files.readString(dir.resolve("tokens.txt"), StandardCharsets.UTF_8);

        Config cfg = parseConfig(configJson);
        Map<String, KeyInfo> keyMap = new HashMap<>();
        for (KeyInfo k : cfg.keys) keyMap.put(k.kid, k);

        String[] lines = tokensText.split("\\r?\\n");
        int lineNo = 0;
        int validCount = 0;
        int invalidCount = 0;
        StringBuilder out = new StringBuilder();

        for (String raw : lines) {
            String t = raw.trim();
            if (t.isEmpty()) continue;
            lineNo++;
            Result r = verify(t, cfg, keyMap);
            if (r.valid) {
                validCount++;
                out.append(lineNo).append(": VALID sub=").append(r.sub)
                   .append(" scope=").append(r.scopes).append("\n");
            } else {
                invalidCount++;
                out.append(lineNo).append(": ").append(r.reason).append("\n");
            }
        }
        out.append("\nvalid=").append(validCount).append(" invalid=").append(invalidCount).append("\n");
        System.out.print(out.toString());
    }

    static class Config {
        double now;
        double leeway;
        String issuer;
        String audience;
        List<KeyInfo> keys = new ArrayList<>();
    }

    static class Result {
        boolean valid;
        String reason;
        String sub = "";
        String scopes = "";
    }

    static Config parseConfig(String json) throws Exception {
        Object root = new JsonParser(json).parseValue();
        @SuppressWarnings("unchecked")
        Map<String,Object> obj = (Map<String,Object>) root;
        Config cfg = new Config();
        cfg.now = ((Number) obj.get("now")).doubleValue();
        cfg.leeway = ((Number) obj.get("leeway")).doubleValue();
        cfg.issuer = (String) obj.get("issuer");
        cfg.audience = (String) obj.get("audience");
        @SuppressWarnings("unchecked")
        List<Object> keysArr = (List<Object>) obj.get("keys");
        for (Object o : keysArr) {
            @SuppressWarnings("unchecked")
            Map<String,Object> m = (Map<String,Object>) o;
            KeyInfo ki = new KeyInfo();
            ki.kid = (String) m.get("kid");
            ki.alg = (String) m.get("alg");
            String kB64 = (String) m.get("k");
            ki.secret = decodeBase64Url(kB64);
            cfg.keys.add(ki);
        }
        return cfg;
    }

    static Result verify(String token, Config cfg, Map<String,KeyInfo> keyMap) {
        Result res = new Result();
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) {
            res.reason = "MALFORMED";
            return res;
        }
        String headerSeg = parts[0];
        String payloadSeg = parts[1];
        String sigSeg = parts[2];
        String[] segs = {headerSeg, payloadSeg, sigSeg};
        for (String s : segs) {
            if (s.isEmpty() || !isBase64UrlValid(s)) {
                res.reason = "MALFORMED";
                return res;
            }
        }
        byte[] headerBytes, payloadBytes, sigBytes;
        try {
            headerBytes = decodeBase64UrlRaw(headerSeg);
            payloadBytes = decodeBase64UrlRaw(payloadSeg);
            sigBytes = decodeBase64UrlRaw(sigSeg);
        } catch (Exception e) {
            res.reason = "MALFORMED";
            return res;
        }
        String headerStr, payloadStr;
        try {
            headerStr = new String(headerBytes, StandardCharsets.UTF_8);
            payloadStr = new String(payloadBytes, StandardCharsets.UTF_8);
        } catch (Exception e) {
            res.reason = "MALFORMED";
            return res;
        }
        Object hObjRaw, pObjRaw;
        try {
            hObjRaw = new JsonParser(headerStr).parseValue();
            pObjRaw = new JsonParser(payloadStr).parseValue();
        } catch (Exception e) {
            res.reason = "MALFORMED";
            return res;
        }
        if (!(hObjRaw instanceof Map) || !(pObjRaw instanceof Map)) {
            res.reason = "MALFORMED";
            return res;
        }
        @SuppressWarnings("unchecked")
        Map<String,Object> header = (Map<String,Object>) hObjRaw;
        @SuppressWarnings("unchecked")
        Map<String,Object> payload = (Map<String,Object>) pObjRaw;

        Object algObj = header.get("alg");
        if (!(algObj instanceof String)) {
            res.reason = "UNSUPPORTED_ALG";
            return res;
        }
        String alg = (String) algObj;
        if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) {
            res.reason = "UNSUPPORTED_ALG";
            return res;
        }

        Object kidObj = header.get("kid");
        if (!(kidObj instanceof String)) {
            res.reason = "UNKNOWN_KEY";
            return res;
        }
        String kid = (String) kidObj;
        KeyInfo key = keyMap.get(kid);
        if (key == null) {
            res.reason = "UNKNOWN_KEY";
            return res;
        }
        if (!key.alg.equals(alg)) {
            res.reason = "ALG_MISMATCH";
            return res;
        }

        String signingInput = headerSeg + "." + payloadSeg;
        byte[] mac;
        try {
            mac = hmac(signingInput.getBytes(StandardCharsets.US_ASCII), key.secret, alg);
        } catch (Exception e) {
            res.reason = "BAD_SIGNATURE";
            return res;
        }
        if (!Arrays.equals(mac, sigBytes)) {
            res.reason = "BAD_SIGNATURE";
            return res;
        }

        if (payload.containsKey("exp")) {
            Object expObj = payload.get("exp");
            if (expObj instanceof Number) {
                double exp = ((Number) expObj).doubleValue();
                if (cfg.now >= exp + cfg.leeway) {
                    res.reason = "EXPIRED";
                    return res;
                }
            }
        }
        if (payload.containsKey("nbf")) {
            Object nbfObj = payload.get("nbf");
            if (nbfObj instanceof Number) {
                double nbf = ((Number) nbfObj).doubleValue();
                if (cfg.now + cfg.leeway < nbf) {
                    res.reason = "NOT_YET_VALID";
                    return res;
                }
            }
        }
        Object issObj = payload.get("iss");
        if (!(issObj instanceof String) || !cfg.issuer.equals(issObj)) {
            res.reason = "BAD_ISSUER";
            return res;
        }
        if (!audienceOk(payload.get("aud"), cfg.audience)) {
            res.reason = "BAD_AUDIENCE";
            return res;
        }

        // VALID
        res.valid = true;
        Object subObj = payload.get("sub");
        res.sub = (subObj instanceof String) ? (String) subObj : "";
        Object scopeObj = payload.get("scope");
        String scopeStr = "";
        if (scopeObj instanceof String) {
            scopeStr = (String) scopeObj;
        }
        Set<String> uniq = new TreeSet<>();
        if (!scopeStr.isEmpty()) {
            String[] toks = scopeStr.trim().split("\\s+");
            for (String t : toks) if (!t.isEmpty()) uniq.add(t);
        }
        res.scopes = String.join(",", uniq);
        return res;
    }

    static boolean isBase64UrlValid(String s) {
        if (s.isEmpty()) return false;
        if (s.length() % 4 == 1) return false;
        for (char c : s.toCharArray()) {
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_')) {
                return false;
            }
        }
        return true;
    }

    static byte[] decodeBase64UrlRaw(String s) {
        String t = s.replace('-', '+').replace('_', '/');
        int pad = (4 - t.length() % 4) % 4;
        StringBuilder sb = new StringBuilder(t);
        for (int i = 0; i < pad; i++) sb.append('=');
        return java.util.Base64.getDecoder().decode(sb.toString());
    }

    static byte[] decodeBase64Url(String s) {
        return decodeBase64UrlRaw(s);
    }

    static byte[] hmac(byte[] data, byte[] key, String alg) throws NoSuchAlgorithmException, InvalidKeyException {
        String jca;
        switch (alg) {
            case "HS256": jca = "HmacSHA256"; break;
            case "HS384": jca = "HmacSHA384"; break;
            case "HS512": jca = "HmacSHA512"; break;
            default: throw new IllegalArgumentException();
        }
        Mac mac = Mac.getInstance(jca);
        mac.init(new SecretKeySpec(key, jca));
        return mac.doFinal(data);
    }

    static boolean audienceOk(Object aud, String expected) {
        if (aud == null) return false;
        if (aud instanceof String) {
            return expected.equals(aud);
        }
        if (aud instanceof List) {
            for (Object o : (List<?>) aud) {
                if (o instanceof String && expected.equals(o)) return true;
            }
            return false;
        }
        return false;
    }

    // Minimal JSON parser
    static class JsonParser {
        private final String s;
        private int pos = 0;
        JsonParser(String s) { this.s = s; }
        Object parseValue() throws Exception {
            skipWs();
            if (pos >= s.length()) throw new Exception("eof");
            char c = s.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f' || c == 'n') return parseLiteral();
            if (c == '-' || Character.isDigit(c)) return parseNumber();
            throw new Exception("bad");
        }
        Map<String,Object> parseObject() throws Exception {
            expect('{');
            Map<String,Object> map = new LinkedHashMap<>();
            skipWs();
            if (peek() == '}') { pos++; return map; }
            while (true) {
                skipWs();
                String key = parseString();
                skipWs(); expect(':');
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                char c = peek();
                if (c == '}') { pos++; break; }
                if (c == ',') { pos++; continue; }
                throw new Exception("bad obj");
            }
            return map;
        }
        List<Object> parseArray() throws Exception {
            expect('[');
            List<Object> list = new ArrayList<>();
            skipWs();
            if (peek() == ']') { pos++; return list; }
            while (true) {
                Object v = parseValue();
                list.add(v);
                skipWs();
                char c = peek();
                if (c == ']') { pos++; break; }
                if (c == ',') { pos++; continue; }
                throw new Exception("bad arr");
            }
            return list;
        }
        String parseString() throws Exception {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (pos < s.length()) {
                char c = s.charAt(pos++);
                if (c == '"') break;
                if (c == '\\') {
                    if (pos >= s.length()) throw new Exception("bad esc");
                    char e = s.charAt(pos++);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 > s.length()) throw new Exception("bad uni");
                            String hex = s.substring(pos, pos + 4);
                            pos += 4;
                            sb.append((char) Integer.parseInt(hex, 16));
                            break;
                        default: sb.append(e);
                    }
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }
        Object parseLiteral() throws Exception {
            if (s.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
            if (s.startsWith("false", pos)) { pos += 5; return Boolean.FALSE; }
            if (s.startsWith("null", pos)) { pos += 4; return null; }
            throw new Exception("bad lit");
        }
        Number parseNumber() throws Exception {
            int start = pos;
            if (s.charAt(pos) == '-') pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            if (pos < s.length() && s.charAt(pos) == '.') { pos++; while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++; }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                pos++;
                if (s.charAt(pos) == '+' || s.charAt(pos) == '-') pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            }
            String num = s.substring(start, pos);
            try { return Double.parseDouble(num); } catch (Exception e) { throw new Exception("bad num"); }
        }
        void skipWs() { while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++; }
        char peek() { return pos < s.length() ? s.charAt(pos) : 0; }
        void expect(char c) throws Exception { skipWs(); if (pos >= s.length() || s.charAt(pos) != c) throw new Exception("exp " + c); pos++; }
    }
}

