static void strtolower(char *s){ for(;*s; s++) *s = tolower((unsigned char)*s); }

static int type_name_to_num(const char *t){
 if(strcmp(t,"A")==0) return 1;
 if(strcmp(t,"CNAME")==0) return 5;
 if(strcmp(t,"MX")==0) return 15;
 if(strcmp(t,"TXT")==0) return 16;
 if(strcmp(t,"AAAA")==0) return 28;
 return -1;
}
static const char *type_num_to_name(int t){
 switch(t){
  case 1: return "A";
  case 5: return "CNAME";
  case 15: return "MX";
  case 16: return "TXT";
  case 28: return "AAAA";
 }
 return NULL;
}

/* DNS name decoding with compression */
static int dns_name_decode(const unsigned char *msg, size_t msg_len, size_t pos,
                           char *out, size_t out_len, size_t *next_pos)
{
    size_t cur = pos;
    size_t consumed = 0;
    size_t out_idx = 0;
    int jumped = 0;
    size_t jump_pos = 0;
    size_t orig = pos;
    /* stack for pointers */
    size_t stack[16];
    int sp = 0;
    while (1) {
        if (cur >= msg_len) return -1;
        unsigned char len = msg[cur];
        if ((len & 0xC0) == 0xC0) {
            if (cur + 1 >= msg_len) return -1;
            unsigned short ptr = ((len & 0x3F) << 8) | msg[cur+1];
            if (!jumped) {
                consumed += 2;
                jump_pos = cur + 2;
            }
            if (ptr >= msg_len) return -1;
            cur = ptr;
            jumped = 1;
            if (sp < 16) stack[sp++] = cur;
            continue;
        }
        if (len == 0) {
            consumed += 1;
            if (!jumped) {
                *next_pos = orig + consumed;
            } else {
                *next_pos = jump_pos;
            }
            out[out_idx] = '\0';
            return 0;
        }
        /* label */
        if (!jumped) consumed += 1 + len;
        if (out_idx > 0) {
            if (out_idx + 1 >= out_len) return -1;
            out[out_idx++] = '.';
        }
        if (out_idx + len >= out_len) return -1;
        memcpy(out + out_idx, msg + cur + 1, len);
        out_idx += len;
        cur += 1 + len;
        if (!jumped) {
            /* continue */
        }
    }
}

/* advance over a name encoding, return bytes consumed */
static size_t dns_name_skip(const unsigned char *msg, size_t msg_len, size_t pos){
    size_t cur = pos;
    while (cur < msg_len) {
        unsigned char b = msg[cur];
        if ((b & 0xC0) == 0xC0) {
            return cur - pos + 2;
        }
        if (b == 0) {
            return cur - pos + 1;
        }
        cur += 1 + b;
    }
    return cur - pos;
}

/* AAAA formatting */
static void format_aaaa(const unsigned char *data, char *out, size_t out_len){
    uint16_t g[8];
    for(int i=0;i<8;i++) g[i] = (data[2*i]<<8)|data[2*i+1];
    char gs[8][5];
    for(int i=0;i<8;i++){
        if(g[i]==0) strcpy(gs[i],"0");
        else {
            char tmp[5];
            snprintf(tmp,sizeof(tmp),"%x",g[i]);
            strcpy(gs[i],tmp);
        }
    }
    int best_start=-1,best_len=0;
    for(int i=0;i<8;){
        if(g[i]==0){
            int j=i;
            while(j<8 && g[j]==0) j++;
            int len=j-i;
            if(len>=2 && len>best_len){
                best_len=len; best_start=i;
            }
            i=j;
        }else i++;
    }
    if(best_start==-1){
        char *p=out;
        for(int i=0;i<8;i++){
            p+=sprintf(p,"%s",gs[i]);
            if(i<7) *p++=':';
        }
        *p='\0';
        return;
    }
    char *p=out;
    int i=0;
    while(i<8){
        if(i>=best_start && i<best_start+best_len){
            if(i==best_start){
                *p++=':'; *p++=':';
                i=best_start+best_len;
                if(i>0 && i<8) { /* already have ::, continue */ }
                continue;
            }else{
                i++;
                continue;
            }
        }
        p+=sprintf(p,"%s",gs[i]);
        if(i+1<8 && !(i+1>=best_start && i+1<best_start+best_len)) *p++=':';
        i++;
    }
    *p='\0';
}

/* build query packet */
static unsigned char *build_query(const char *name, int qtype, uint16_t id, size_t *out_len){
    unsigned char buf[512];
    size_t off=0;
    buf[off++]=id>>8; buf[off++]=id&0xff;
    buf[off++]=0x01; buf[off++]=0x00;
    buf[off++]=0x00; buf[off++]=0x01;
    buf[off++]=0x00; buf[off++]=0x00;
    buf[off++]=0x00; buf[off++]=0x00;
    buf[off++]=0x00; buf[off++]=0x00;
    /* QNAME */
    char tmp[256];
    strncpy(tmp,name,sizeof(tmp)-1);
    tmp[255]=0;
    size_t len=strlen(tmp);
    if(len>0 && tmp[len-1]=='.') tmp[len-1]=0;
    char *p=tmp;
    while(*p){
        char *dot=strchr(p,'.');
        size_t lablen;
        if(dot) lablen=dot-p; else lablen=strlen(p);
        if(lablen>63) lablen=63;
        buf[off++]= (unsigned char)lablen;
        memcpy(buf+off,p,lablen);
        off+=lablen;
        if(!dot) break;
        p=dot+1;
    }
    buf[off++]=0;
    buf[off++]=qtype>>8; buf[off++]=qtype&0xff;
    buf[off++]=0x00; buf[off++]=0x01;
    *out_len=off;
    unsigned char *res=malloc(off);
    memcpy(res,buf,off);
    return res;
}

/* send UDP and receive */
static int udp_query(const char *host,int port,unsigned char *q,size_t qlen,unsigned char *resp_buf,size_t resp_buf_len,uint16_t *out_id,int *out_tc){
    int s=socket(AF_INET,SOCK_DGRAM,0);
    struct sockaddr_in sa={0};
    sa.sin_family=AF_INET;
    sa.sin_port=htons(port);
    inet_pton(AF_INET,"127.0.0.1",&sa.sin_addr);
    sendto(s,q,qlen,0,(struct sockaddr*)&sa,sizeof(sa));
    fd_set rf;
    struct timeval tv={2,0};
    while(1){
        FD_ZERO(&rf); FD_SET(s,&rf);
        int r=select(s+1,&rf,NULL,NULL,&tv);
        if(r<=0) { close(s); return -1; }
        ssize_t n=recvfrom(s,resp_buf,resp_buf_len,0,NULL,NULL);
        if(n<12) continue;
        uint16_t id=(resp_buf[0]<<8)|resp_buf[1];
        if(id!= (q[0]<<8|q[1])) continue;
        uint16_t flags=(resp_buf[2]<<8)|resp_buf[3];
        int qr=(flags>>15)&1;
        if(!qr) continue;
        *out_id=id;
        *out_tc=(flags>>9)&1;
        close(s);
        return (int)n;
    }
}

static int tcp_query(int port,unsigned char *q,size_t qlen,unsigned char *resp_buf,size_t resp_buf_len){
    int s=socket(AF_INET,SOCK_STREAM,0);
    struct sockaddr_in sa={0};
    sa.sin_family=AF_INET;
    sa.sin_port=htons(port);
    inet_pton(AF_INET,"127.0.0.1",&sa.sin_addr);
    if(connect(s,(struct sockaddr*)&sa,sizeof(sa))<0){ close(s); return -1; }
    unsigned char hdr[2];
    hdr[0]=qlen>>8; hdr[1]=qlen&0xff;
    send(s,hdr,2,0);
    send(s,q,qlen,0);
    /* read length */
    size_t got=0;
    while(got<2){
        ssize_t r=recv(s,((unsigned char*)hdr)+got,2-got,0);
        if(r<=0) { close(s); return -1; }
        got+=r;
    }
    size_t len=(hdr[0]<<8)|hdr[1];
    if(len>resp_buf_len-2){ close(s); return -1; }
    got=0;
    while(got<len){
        ssize_t r=recv(s,resp_buf+got,len-got,0);
        if(r<=0) { close(s); return -1; }
        got+=r;
    }
    close(s);
    return (int)len;
}

int main(int argc,char **argv){
    if(argc!=3){ fprintf(stderr,"usage\n"); return 1; }
    const char *dir=argv[1];
    int port=atoi(argv[2]);
    char path[1024];
    snprintf(path,sizeof(path),"%s/queries.txt",dir);
    FILE *f=fopen(path,"r");
    if(!f){ perror("open"); return 1; }
    char line[1024];
    while(fgets(line,sizeof(line),f)){
        char *nl=strchr(line,'\n'); if(nl) *nl=0;
        char *cr=strchr(line,'\r'); if(cr) *cr=0;
        if(line[0]==0) continue;
        char *sp=strchr(line,' ');
        if(!sp) continue;
        *sp=0;
        char *name=line;
        char *type_str=sp+1;
        while(*type_str && isspace((unsigned char)*type_str)) type_str++;
        int qtype=type_name_to_num(type_str);
        if(qtype==-1) continue;
        /* output name lower case */
        char name_out[256];
        strncpy(name_out,name,sizeof(name_out)-1);
        name_out[255]=0;
        strtolower(name_out);
        size_t nlen=strlen(name_out);
        if(nlen>0 && name_out[nlen-1]=='.') name_out[nlen-1]=0;
        uint16_t id=(uint16_t)arc4random_uniform(65536);
        size_t qlen;
        unsigned char *q=build_query(name,qtype,id,&qlen);
        unsigned char resp[4096];
        int tc=0;
        int n=udp_query("127.0.0.1",port,q,qlen,resp,sizeof(resp),&id,&tc);
        if(n<0 || tc){
            /* TCP */
            n=tcp_query(port,q,qlen,resp,sizeof(resp));
            tc=0;
        }
        free(q);
        if(n<=0){ /* no response */
            printf("%s %s FORMERR\n",name_out,type_str);
            continue;
        }
        uint16_t flags=(resp[2]<<8)|resp[3];
        int rcode=flags & 0xf;
        const char *rcname;
        switch(rcode){
            case 0: rcname="NOERROR"; break;
            case 1: rcname="FORMERR"; break;
            case 2: rcname="SERVFAIL"; break;
            case 3: rcname="NXDOMAIN"; break;
            case 4: rcname="NOTIMP"; break;
            case 5: rcname="REFUSED"; break;
            default: { static char buf[16]; snprintf(buf,sizeof(buf),"RCODE%d",rcode); rcname=buf; } break;
        }
        printf("%s %s %s\n",name_out,type_str,rcname);
        /* parse answers */
        size_t off=12;
        /* skip question */
        off += dns_name_skip(resp, n, off);
        /* question fields */
        if(off+4 <= (size_t)n) off+=4;
        uint16_t ancount=(resp[6]<<8)|resp[7];
        for(int i=0;i<ancount;i++){
            if(off>= (size_t)n) break;
            char owner[256];
            size_t next_off;
            if(dns_name_decode(resp,n,off,owner,sizeof(owner),&next_off)!=0) break;
            off=next_off;
            if(off+10 > (size_t)n) break;
            uint16_t typ=(resp[off]<<8)|resp[off+1]; off+=2;
            uint16_t clas=(resp[off]<<8)|resp[off+1]; off+=2;
            uint32_t ttl=(resp[off]<<24)|(resp[off+1]<<16)|(resp[off+2]<<8)|resp[off+3]; off+=4;
            uint16_t rdlen=(resp[off]<<8)|resp[off+1]; off+=2;
            if(off+rdlen > (size_t)n) break;
            char owner_lc[256];
            strcpy(owner_lc,owner);
            strtolower(owner_lc);
            if(strcmp(owner_lc,"") == 0) strcpy(owner_lc,".");
            const char *tname=type_num_to_name(typ);
            printf("  %s %u ",owner_lc,ttl);
            if(tname) printf("%s ",tname);
            else printf("TYPE%d ",typ);
            if(typ==1 && rdlen==4){
                printf("%u.%u.%u.%u\n",resp[off],resp[off+1],resp[off+2],resp[off+3]);
            }else if(typ==28 && rdlen==16){
                char aaaa[64];
                format_aaaa(resp+off,aaaa,sizeof(aaaa));
                printf("AAAA %s\n",aaaa);
            }else if(typ==5){
                char target[256];
                size_t dummy;
                dns_name_decode(resp,n,off,target,sizeof(target),&dummy);
                strtolower(target);
                printf("CNAME %s\n",target);
            }else if(typ==15){
                if(rdlen>=2){
                    uint16_t pref=(resp[off]<<8)|resp[off+1];
                    char exch[256];
                    size_t dummy;
                    dns_name_decode(resp,n,off+2,exch,sizeof(exch),&dummy);
                    strtolower(exch);
                    printf("MX %u %s\n",pref,exch);
                }else printf("\n");
            }else if(typ==16){
                size_t pos=off;
                size_t end=off+rdlen;
                int first_str=1;
                while(pos<end){
                    unsigned char l=resp[pos++];
                    if(pos+l>end) break;
                    printf("%s\"",first_str?"":" ");
                    first_str=0;
                    for(int k=0;k<l;k++){
                        unsigned char b=resp[pos+k];
                        if(b=='"') printf("\\\"");
                        else if(b=='\\') printf("\\\\");
                        else if(b>=0x20 && b<=0x7E) putchar(b);
                        else printf("\\%03d",(int)b);
                    }
                    printf("\"");
                }
                printf("\n");
            }else{
                printf("TYPE%d \\# %u ",typ,rdlen);
                if(rdlen>0){
                    for(int k=0;k<rdlen;k++) printf("%02x",resp[off+k]);
                }
                printf("\n");
            }
            off+=rdlen;
        }
    }
    fclose(f);
    return 0;
}

