static void strtolower(char *s){ for(;*s; s++) *s = tolower((unsigned char)*s); }

static int type_name_to_num(const char *t){
 if(strcmp(t,"A")==0) return 1;
 if(strcmp(t,"CNAME")==0) return 5;
 if(strcmp(t,"MX")==0) return 15;
 if(strcmp(t,"TXT")==0) return 16;
 if(strcmp(t,"AAAA")==0) return 28;
 return -1;
}
static const char *type_num_to_name(int t){
 switch(t){
  case 1: return "A";
  case 5: return "CNAME";
  case 15: return "MX";
  case 16: return "TXT";
  case 28: return "AAAA";
 }
 return NULL;
}

static size_t decode_name(const unsigned char *msg, size_t msg_len, size_t pos,
                          char *out, size_t out_len, size_t *next_pos)
{
    size_t cur = pos;
    size_t out_idx = 0;
    size_t jump_end = 0;
    int jumped = 0;
    size_t orig = pos;
    (void)orig;
    for(int steps=0; steps<256; steps++){
        if(cur >= msg_len) break;
        unsigned char c = msg[cur];
        if((c & 0xC0) == 0xC0){
            if(cur+1 >= msg_len) break;
            uint16_t ptr = ((c & 0x3F) << 8) | msg[cur+1];
            if(!jumped) jump_end = cur + 2;
            cur = ptr;
            jumped = 1;
            continue;
        }
        if(c == 0){
            if(!jumped) *next_pos = cur + 1;
            else *next_pos = jump_end;
            out[out_idx] = '\0';
            return out_idx;
        }
        size_t lablen = c;
        cur++;
        if(out_idx > 0){
            if(out_idx + 1 >= out_len) break;
            out[out_idx++] = '.';
        }
        if(cur + lablen > msg_len) break;
        if(out_idx + lablen >= out_len) break;
        memcpy(out + out_idx, msg + cur, lablen);
        out_idx += lablen;
        cur += lablen;
    }
    out[out_idx] = '\0';
    return out_idx;
}

static size_t name_skip(const unsigned char *msg, size_t msg_len, size_t pos){
    char tmp[256];
    size_t nxt;
    decode_name(msg, msg_len, pos, tmp, sizeof(tmp), &nxt);
    return nxt - pos;
}

static unsigned char *build_query(const char *name, int qtype, uint16_t id, size_t *out_len){
    unsigned char buf[512];
    size_t off = 0;
    buf[off++] = id >> 8; buf[off++] = id & 0xff;
    buf[off++] = 0x01; buf[off++] = 0x00;
    buf[off++] = 0x00; buf[off++] = 0x01;
    buf[off++] = 0x00; buf[off++] = 0x00;
    buf[off++] = 0x00; buf[off++] = 0x00;
    buf[off++] = 0x00; buf[off++] = 0x00;
    char tmp[256];
    strncpy(tmp, name, sizeof(tmp)-1); tmp[255]=0;
    size_t len = strlen(tmp);
    if(len>0 && tmp[len-1]=='.') tmp[len-1]=0;
    char *p = tmp;
    while(*p){
        char *dot = strchr(p, '.');
        size_t lablen = dot ? (size_t)(dot-p) : strlen(p);
        if(lablen>63) lablen=63;
        buf[off++] = (unsigned char)lablen;
        memcpy(buf+off, p, lablen); off+=lablen;
        if(!dot) break;
        p = dot+1;
    }
    buf[off++] = 0;
    buf[off++] = qtype >> 8; buf[off++] = qtype & 0xff;
    buf[off++] = 0x00; buf[off++] = 0x01;
    *out_len = off;
    unsigned char *res = malloc(off);
    memcpy(res, buf, off);
    return res;
}

static int udp_query(int port, unsigned char *q, size_t qlen, unsigned char *resp, size_t resp_len, uint16_t *out_id, int *out_tc){
    int s = socket(AF_INET, SOCK_DGRAM, 0);
