static int tcp_query(int port, unsigned char *q, size_t qlen, unsigned char *resp, size_t resp_len){
    int s = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in sa = {0};
    sa.sin_family = AF_INET;
    sa.sin_port = htons(port);
    inet_pton(AF_INET, "127.0.0.1", &sa.sin_addr);
    if(connect(s,(struct sockaddr*)&sa,sizeof(sa))<0){ close(s); return -1; }
    unsigned char hdr[2] = { qlen>>8, qlen&0xff };
    send(s, hdr, 2, 0);
    send(s, q, qlen, 0);
    unsigned char lenbuf[2];
    size_t got=0;
    while(got<2){
        ssize_t r = recv(s, lenbuf+got, 2-got, 0);
        if(r<=0){ close(s); return -1; }
        got+=r;
    }
    size_t len = (lenbuf[0]<<8)|lenbuf[1];
    if(len > resp_len){ close(s); return -1; }
    got=0;
    while(got<len){
        ssize_t r = recv(s, resp+got, len-got, 0);
        if(r<=0){ close(s); return -1; }
        got+=r;
    }
    close(s);
    return (int)len;
}

