use std::env;
use std::fs;
use std::net::{UdpSocket, TcpStream};
use std::io::{Read, Write};

fn normalize_name(s: &str) -> String {
    let t = s.trim();
    let t = t.strip_suffix('.').unwrap_or(t);
    t.to_ascii_lowercase()
}

fn name_to_wire(name: &str) -> Vec<u8> {
    let name = name.strip_suffix('.').unwrap_or(name);
    let mut out = Vec::new();
    for label in name.split('.') {
        if label.is_empty() { continue; }
        out.push(label.len() as u8);
        out.extend_from_slice(label.as_bytes());
    }
    out.push(0);
    out
}

fn parse_name(buf: &[u8], mut offset: usize) -> (String, usize) {
    let mut labels = Vec::new();
    let mut pos = offset;
    let mut jumped = false;
    let mut original_end = offset;
    let mut stack = Vec::new();
    stack.push(pos);
    loop {
        if pos >= buf.len() { break; }
        let len = buf[pos];
        if len == 0 {
            pos += 1;
            if !jumped { original_end = pos; }
            break;
        }
        if (len & 0xC0) == 0xC0 {
            let b2 = buf[pos + 1];
            let target = (((len & 0x3F) as usize) << 8) | (b2 as usize);
            if !jumped { original_end = pos + 2; }
            pos = target;
            jumped = true;
            continue;
        } else {
            let l = len as usize;
            pos += 1;
            if pos + l > buf.len() { break; }
            labels.push(String::from_utf8_lossy(&buf[pos..pos + l]).to_string());
            pos += l;
        }
    }
    let name = labels.join(".");
    (name, original_end)
}

