        1 => "A".to_string(),
        5 => "CNAME".to_string(),
        15 => "MX".to_string(),
        16 => "TXT".to_string(),
        28 => "AAAA".to_string(),
        _ => format!("TYPE{}", t),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 { return; }
    let dir = &args[1];
    let port: u16 = args[2].parse().unwrap();
    let path = format!("{}/queries.txt", dir);
    let content = fs::read_to_string(&path).unwrap();
    let mut queries = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let mut parts = line.split_whitespace();
        let name = parts.next().unwrap().to_string();
        let typ = parts.next().unwrap().to_string();
        queries.push((name, typ));
    }

    let mut id_counter: u16 = 1;
    for (name_orig, typ_str) in queries {
        let name_norm = normalize_name(&name_orig);
        let typ_up = typ_str.to_ascii_uppercase();
        let qtype = match typ_up.as_str() {
            "A" => 1,
            "AAAA" => 28,
            "CNAME" => 5,
            "MX" => 15,
            "TXT" => 16,
            _ => 1,
        };
        // build query
        let mut msg = Vec::new();
        msg.extend_from_slice(&id_counter.to_be_bytes());
        id_counter = id_counter.wrapping_add(1);
        msg.extend_from_slice(&0x0100u16.to_be_bytes());
        msg.extend_from_slice(&1u16.to_be_bytes());
        msg.extend_from_slice(&0u16.to_be_bytes());
        msg.extend_from_slice(&0u16.to_be_bytes());
        msg.extend_from_slice(&0u16.to_be_bytes());
        let qname_wire = name_to_wire(&name_orig);
        msg.extend_from_slice(&qname_wire);
        msg.extend_from_slice(&qtype.to_be_bytes());
        msg.extend_from_slice(&1u16.to_be_bytes());

        let addr = format!("127.0.0.1:{}", port);
        let mut response_bytes = Vec::new();
        let mut use_tcp = false;

        // UDP first
        let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
        socket.connect(&addr).unwrap();
        socket.send(&msg).unwrap();
        loop {
            let mut buf = [0u8; 4096];
            let n = socket.recv(&mut buf).unwrap();
            let data = &buf[..n];
            if data.len() < 12 { continue; }
            let resp_id = u16::from_be_bytes([data[0], data[1]]);
            if resp_id != id_counter.wrapping_sub(1) { continue; }
            let flags = u16::from_be_bytes([data[2], data[3]]);
            let qr = (flags >> 15) & 1;
            if qr == 0 { continue; }
            let tc = (flags >> 9) & 1;
            if tc == 1 {
                use_tcp = true;
                break;
            } else {
                response_bytes = data.to_vec();
                break;
            }
        }

        if use_tcp {
            let mut stream = TcpStream::connect(&addr).unwrap();
            let mut len_prefix = (msg.len() as u16).to_be_bytes();
            stream.write_all(&len_prefix).unwrap();
            stream.write_all(&msg).unwrap();
            // read length
            let mut len_buf = [0u8; 2];
            stream.read_exact(&mut len_buf).unwrap();
            let len = u16::from_be_bytes(len_buf) as usize;
            let mut resp_buf = vec![0u8; len];
            stream.read_exact(&mut resp_buf).unwrap();
            response_bytes = resp_buf;
        }

        // parse header
        let mut offset = 0;
        let resp_id = u16::from_be_bytes([response_bytes[0], response_bytes[1]]);
        let flags = u16::from_be_bytes([response_bytes[2], response_bytes[3]]);
        let rcode = (flags & 0x000F) as u8;
        let qdcount = u16::from_be_bytes([response_bytes[4], response_bytes[5]]) as usize;
        let ancount = u16::from_be_bytes([response_bytes[6], response_bytes[7]]) as usize;
        // skip questions
        let mut pos = 12;
        for _ in 0..qdcount {
            let (_, new_pos) = parse_name(&response_bytes, pos);
            pos = new_pos;
            if pos + 4 > response_bytes.len() { break; }
            pos += 4;
        }
        // output header line
        let rcode_str = match rcode {
            0 => "NOERROR",
            1 => "FORMERR",
            2 => "SERVFAIL",
            3 => "NXDOMAIN",
            4 => "NOTIMP",
            5 => "REFUSED",
            n => format!("RCODE{}", n).as_str(),
        };
        println!("{} {} {}", name_norm, typ_up, rcode_str);
        // parse answers
        let mut cur = pos;
        for _ in 0..ancount {
            if cur >= response_bytes.len() { break; }
            let (owner, new_pos) = parse_name(&response_bytes, cur);
            cur = new_pos;
            if cur + 10 > response_bytes.len() { break; }
            let rtype = u16::from_be_bytes([response_bytes[cur], response_bytes[cur+1]]);
            let rclass = u16::from_be_bytes([response_bytes[cur+2], response_bytes[cur+3]]);
            let ttl = u32::from_be_bytes([response_bytes[cur+4], response_bytes[cur+5], response_bytes[cur+6], response_bytes[cur+7]]);
            let rdlen = u16::from_be_bytes([response_bytes[cur+8], response_bytes[cur+9]]) as usize;
            cur += 10;
            if cur + rdlen > response_bytes.len() { break; }
            let rdata = &response_bytes[cur..cur+rdlen];
            cur += rdlen;

            let owner_out = if owner.is_empty() { ".".to_string() } else { owner.to_ascii_lowercase() };
            let type_out = type_name(rtype);
            let data_str = match rtype {
                1 => {
                    if rdlen >= 4 {
                        let ip = &rdata[..4];
                        format!("{}.{}.{}.{}", ip[0], ip[1], ip[2], ip[3])
                    } else { "".to_string() }
                }
                28 => {
                    if rdlen >= 16 {
                        format_aaaa_clean(&[
                            u16::from_be_bytes([rdata[0], rdata[1]]),
                            u16::from_be_bytes([rdata[2], rdata[3]]),
                            u16::from_be_bytes([rdata[4], rdata[5]]),
                            u16::from_be_bytes([rdata[6], rdata[7]]),
                            u16::from_be_bytes([rdata[8], rdata[9]]),
                            u16::from_be_bytes([rdata[10], rdata[11]]),
                            u16::from_be_bytes([rdata[12], rdata[13]]),
                            u16::from_be_bytes([rdata[14], rdata[15]]),
                        ])
                    } else { "".to_string() }
                }
                5 => {
                    let (target, _) = parse_name(rdata, 0);
                    let t = if target.is_empty() { ".".to_string() } else { target.to_ascii_lowercase() };
                    t
                }
                15 => {
                    if rdlen >= 2 {
                        let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                        let (exch, _) = parse_name(rdata, 2);
                        let ex = if exch.is_empty() { ".".to_string() } else { exch.to_ascii_lowercase() };
                        format!("{} {}", pref, ex)
                    } else { "".to_string() }
                }
                16 => {
                    let mut parts = Vec::new();
                    let mut i = 0;
                    while i < rdlen {
                        let l = rdata[i] as usize;
                        i += 1;
                        if i + l > rdlen { break; }
                        let s = &rdata[i..i+l];
                        let esc = escape_txt(s);
                        parts.push(format!("\"{}\"", esc));
                        i += l;
                    }
                    parts.join(" ")
                }
                _ => {
                    let hex = rdata.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                    if rdlen == 0 {
                        format!("\\# {}", rdlen)
                    } else {
                        format!("\\# {} {}", rdlen, hex)
                    }
                }
            };
            println!("  {} {} {} {}", owner_out, ttl, type_out, data_str);
        }
    }
}

