fn normalize_name(s: &str) -> String {
    let t = s.trim();
    let t = t.strip_suffix('.').unwrap_or(t);
    t.to_ascii_lowercase()
}

fn name_to_wire(name: &str) -> Vec<u8> {
    let name = name.strip_suffix('.').unwrap_or(name);
    let mut out = Vec::new();
    for label in name.split('.') {
        if label.is_empty() { continue; }
        out.push(label.len() as u8);
        out.extend_from_slice(label.as_bytes());
    }
    out.push(0);
    out
}

fn parse_name(buf: &[u8], mut pos: usize) -> (String, usize) {
    let mut labels = Vec::new();
    let mut end = pos;
    let mut jumped = false;
    loop {
        if pos >= buf.len() { break; }
        let len = buf[pos];
        if len == 0 {
            pos += 1;
            if !jumped { end = pos; }
            break;
        }
        if (len & 0xC0) == 0xC0 {
            let target = (((len & 0x3F) as usize) << 8) | (buf[pos + 1] as usize);
            if !jumped { end = pos + 2; jumped = true; }
            pos = target;
            continue;
        } else {
            let l = len as usize;
            pos += 1;
            if pos + l > buf.len() { break; }
            labels.push(String::from_utf8_lossy(&buf[pos..pos + l]).to_string());
            pos += l;
        }
    }
    (labels.join("."), end)
}

