            let resp_id = u16::from_be_bytes([data[0], data[1]]);
            if resp_id != id { continue; }
            let flags = u16::from_be_bytes([data[2], data[3]]);
            let qr = (flags >> 15) & 1;
            if qr == 0 { continue; }
            let tc = (flags >> 9) & 1;
            if tc == 1 {
                use_tcp = true;
                break;
            } else {
                response_bytes = data.to_vec();
                break;
            }
        }

        if use_tcp {
            let mut stream = TcpStream::connect(&addr).unwrap();
            let len_prefix = (msg.len() as u16).to_be_bytes();
            stream.write_all(&len_prefix).unwrap();
            stream.write_all(&msg).unwrap();
            let mut len_buf = [0u8; 2];
            stream.read_exact(&mut len_buf).unwrap();
            let len = u16::from_be_bytes(len_buf) as usize;
            let mut resp_buf = vec![0u8; len];
            stream.read_exact(&mut resp_buf).unwrap();
            response_bytes = resp_buf;
        }

        let flags = u16::from_be_bytes([response_bytes[2], response_bytes[3]]);
        let rcode = (flags & 0x000F) as u8;
        let qdcount = u16::from_be_bytes([response_bytes[4], response_bytes[5]]) as usize;
        let ancount = u16::from_be_bytes([response_bytes[6], response_bytes[7]]) as usize;

        let mut pos = 12;
        for _ in 0..qdcount {
            let (_, new_pos) = parse_name(&response_bytes, pos);
            pos = new_pos;
            if pos + 4 <= response_bytes.len() { pos += 4; }
        }

        println!("{} {} {}", name_norm, typ_up, rcode_str(rcode));

        let mut cur = pos;
        for _ in 0..ancount {
            if cur >= response_bytes.len() { break; }
            let (owner, new_pos) = parse_name(&response_bytes, cur);
            cur = new_pos;
            if cur + 10 > response_bytes.len() { break; }
            let rtype = u16::from_be_bytes([response_bytes[cur], response_bytes[cur+1]]);
            let ttl = u32::from_be_bytes([response_bytes[cur+4], response_bytes[cur+5], response_bytes[cur+6], response_bytes[cur+7]]);
            let rdlen = u16::from_be_bytes([response_bytes[cur+8], response_bytes[cur+9]]) as usize;
            cur += 10;
            if cur + rdlen > response_bytes.len() { break; }
            let rdata = &response_bytes[cur..cur+rdlen];
            cur += rdlen;

            let owner_out = if owner.is_empty() { ".".to_string() } else { owner.to_ascii_lowercase() };
            let type_out = type_name(rtype);
            let data_str = match rtype {
                1 => {
                    if rdlen >= 4 {
                        let ip = &rdata[..4];
                        format!("{}.{}.{}.{}", ip[0], ip[1], ip[2], ip[3])
                    } else { "".to_string() }
                }
                28 => {
                    if rdlen >= 16 { format_aaaa(&rdata[..16]) } else { "".to_string() }
                }
                5 => {
                    let (target, _) = parse_name(rdata, 0);
                    if target.is_empty() { ".".to_string() } else { target.to_ascii_lowercase() }
                }
                15 => {
                    if rdlen >= 2 {
                        let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                        let (exch, _) = parse_name(rdata, 2);
                        let ex = if exch.is_empty() { ".".to_string() } else { exch.to_ascii_lowercase() };
                        format!("{} {}", pref, ex)
                    } else { "".to_string() }
                }
                16 => {
                    let mut parts = Vec::new();
                    let mut i = 0;
                    while i < rdlen {
                        let l = rdata[i] as usize;
                        i += 1;
                        if i + l > rdlen { break; }
                        let s = &rdata[i..i+l];
                        let esc = escape_txt(s);
                        parts.push(format!("\"{}\"", esc));
                        i += l;
                    }
                    parts.join(" ")
                }
                _ => {
                    if rdlen == 0 {
                        format!("\\# {}", rdlen)
                    } else {
                        let hex = rdata.iter().map(|b| format!("{:02x}", b)).collect::<String>();
                        format!("\\# {} {}", rdlen, hex)
                    }
                }
            };
            println!("  {} {} {} {}", owner_out, ttl, type_out, data_str);
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

type Account = { code: string; balance: bigint; limit: bigint };

function pow10(n: number): bigint {
  let r = 1n;
  for (let i = 0; i < n; i++) r *= 10n;
  return r;
}

function parseDecimalString(str: string): { num: bigint; scale: number } {
  let s = str.trim();
  let sign = 1n;
  if (s.startsWith('-')) { sign = -1n; s = s.slice(1); }
  else if (s.startsWith('+')) { s = s.slice(1); }
  if (s.includes('.')) {
    const [intPart, fracPart] = s.split('.');
    const scale = fracPart.length;
    const combined = (intPart === '' ? '0' : intPart) + fracPart;
    const num = BigInt(combined || '0');
    return { num: sign * num, scale };
  } else {
    return { num: sign * BigInt(s || '0'), scale: 0 };
  }
}

function roundHalfEven(num: bigint, den: bigint): bigint {
  if (den < 0n) { num = -num; den = -den; }
  const sign = num < 0n ? -1n : 1n;
  let absNum = num < 0n ? -num : num;
  const q = absNum / den;
  const r = absNum % den;
  let result = q;
  if (r * 2n > den) result = q + 1n;
  else if (r * 2n === den && (q % 2n !== 0n)) result = q + 1n;
  return sign * result;
}

function roundToMinor(numScale: { num: bigint; scale: number }, m: number): bigint {
  const { num, scale } = numScale;
  if (scale <= m) {
    return num * pow10(m - scale);
  } else {
    const numerator = num * pow10(m);
    const denominator = pow10(scale);
    return roundHalfEven(numerator, denominator);
  }
}

function formatIntWithCommas(n: bigint): string {
  const s = n.toString();
  let res = '';
  let cnt = 0;
  for (let i = s.length - 1; i >= 0; i--) {
    res = s[i] + res;
    cnt++;
    if (cnt === 3 && i !== 0) { res = ',' + res; cnt = 0; }
  }
  return res;
}

function formatMoney(balance: bigint, m: number): string {
  if (balance === 0n) {
    if (m === 0) return '0';
    return '0.' + '0'.repeat(m);
  }
  const sign = balance < 0n ? '-' : '';
  const abs = balance < 0n ? -balance : balance;
  const divisor = pow10(m);
  const intPart = abs / divisor;
  const fracPart = abs % divisor;
  const intStr = formatIntWithCommas(intPart);
  if (m === 0) return sign + intStr;
  const fracStr = fracPart.toString().padStart(m, '0');
  return sign + intStr + '.' + fracStr;
}

function main() {
  const dir = process.argv[2];
  if (!dir) return;
  const file = path.join(dir, 'ledger.txt');
  const content = fs.readFileSync(file, 'utf-8');
  const lines = content.split(/\r?\n/);

  const currencies = new Map<string, number>();
  const accounts = new Map<string, Account>();
  const rejects: { line: number; reason: string }[] = [];

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const lineNum = i + 1;
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const parts = raw.trim().split(/\s+/);
    const cmd = parts[0];

    if (cmd === 'currency') {
      const code = parts[1];
      const minor = parseInt(parts[2], 10);
      currencies.set(code, minor);
      continue;
    }

    if (cmd === 'open') {
      const name = parts[1];
      const code = parts[2];
      const limitStr = parts[3] ?? '0';
      if (accounts.has(name)) {
        rejects.push({ line: lineNum, reason: `REJECT account exists ${name}` });
        continue;
      }
      const m = currencies.get(code) ?? 0;
      const limitMinor = roundToMinor(parseDecimalString(limitStr), m);
      accounts.set(name, { code, balance: 0n, limit: limitMinor >= 0n ? limitMinor : 0n });
      continue;
    }

    // helper to get minor units
    const getMinor = (code: string) => currencies.get(code) ?? 0;

    if (cmd === 'deposit') {
      const name = parts[1];
      const amtStr = parts[2];
      if (!accounts.has(name)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${name}` }); continue; }
      const acc = accounts.get(name)!;
      const m = getMinor(acc.code);
      const amt = roundToMinor(parseDecimalString(amtStr), m);
      if (amt <= 0n) { rejects.push({ line: lineNum, reason: `REJECT non-positive amount` }); continue; }
      acc.balance += amt;
      continue;
    }

    if (cmd === 'withdraw') {
      const name = parts[1];
      const amtStr = parts[2];
      if (!accounts.has(name)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${name}` }); continue; }
      const acc = accounts.get(name)!;
      const m = getMinor(acc.code);
      const amt = roundToMinor(parseDecimalString(amtStr), m);
      if (amt <= 0n) { rejects.push({ line: lineNum, reason: `REJECT non-positive amount` }); continue; }
      if (acc.balance - amt < -acc.limit) { rejects.push({ line: lineNum, reason: `REJECT insufficient funds ${name}` }); continue; }
      acc.balance -= amt;
      continue;
    }

    if (cmd === 'transfer') {
      const from = parts[1];
      const to = parts[2];
      const amtStr = parts[3];
      if (!accounts.has(from)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${from}` }); continue; }
      if (!accounts.has(to)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${to}` }); continue; }
      const accFrom = accounts.get(from)!;
      const accTo = accounts.get(to)!;
      if (accFrom.code !== accTo.code) { rejects.push({ line: lineNum, reason: `REJECT currency mismatch` }); continue; }
      const m = getMinor(accFrom.code);
      const amt = roundToMinor(parseDecimalString(amtStr), m);
      if (amt <= 0n) { rejects.push({ line: lineNum, reason: `REJECT non-positive amount` }); continue; }
      if (accFrom.balance - amt < -accFrom.limit) { rejects.push({ line: lineNum, reason: `REJECT insufficient funds ${from}` }); continue; }
      accFrom.balance -= amt;
      accTo.balance += amt;
      continue;
    }

    if (cmd === 'convert') {
      const from = parts[1];
      const to = parts[2];
      const amtStr = parts[3];
      const rateStr = parts[4];
      if (!accounts.has(from)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${from}` }); continue; }
      if (!accounts.has(to)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${to}` }); continue; }
      const accFrom = accounts.get(from)!;
      const accTo = accounts.get(to)!;
      const mFrom = getMinor(accFrom.code);
      const amt = roundToMinor(parseDecimalString(amtStr), mFrom);
      if (amt <= 0n) { rejects.push({ line: lineNum, reason: `REJECT non-positive amount` }); continue; }
      if (accFrom.balance - amt < -accFrom.limit) { rejects.push({ line: lineNum, reason: `REJECT insufficient funds ${from}` }); continue; }
      const rate = parseDecimalString(rateStr);
      const mTo = getMinor(accTo.code);
      const num = amt * rate.num;
      const den = pow10(mFrom + rate.scale);
      const received = roundHalfEven(num * pow10(mTo), den);
      accFrom.balance -= amt;
      accTo.balance += received;
      continue;
    }

    if (cmd === 'interest') {
      const name = parts[1];
      const rateStr = parts[2];
      if (!accounts.has(name)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${name}` }); continue; }
      const acc = accounts.get(name)!;
      const rate = parseDecimalString(rateStr);
      const delta = roundHalfEven(acc.balance * rate.num, pow10(rate.scale));
      acc.balance += delta;
      continue;
    }

    if (cmd === 'split') {
      const from = parts[1];
      const amtStr = parts[2];
      const targetTokens = parts.slice(3);
      if (!accounts.has(from)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${from}` }); continue; }
      const accFrom = accounts.get(from)!;
      const targets: { name: string; weight: bigint; idx: number }[] = [];
      for (let j = 0; j < targetTokens.length; j++) {
        const [name, wStr] = targetTokens[j].split(':');
        if (!accounts.has(name)) { rejects.push({ line: lineNum, reason: `REJECT unknown account ${name}` }); continue; }
        targets.push({ name, weight: BigInt(wStr), idx: j });
      }
      // currency mismatch
      let mismatch = false;
      for (const t of targets) {
        const accT = accounts.get(t.name)!;
        if (accT.code !== accFrom.code) { mismatch = true; break; }
      }
      if (mismatch) { rejects.push({ line: lineNum, reason: `REJECT currency mismatch` }); continue; }
      const m = getMinor(accFrom.code);
      const A = roundToMinor(parseDecimalString(amtStr), m);
      if (A <= 0n) { rejects.push({ line: lineNum, reason: `REJECT non-positive amount` }); continue; }
      if (accFrom.balance - A < -accFrom.limit) { rejects.push({ line: lineNum, reason: `REJECT insufficient funds ${from}` }); continue; }
      // distribution
      const W = targets.reduce((s, t) => s + t.weight, 0n);
      const infos = targets.map(t => {
        const num = A * t.weight;
        const q = num / W;
        const r = num % W;
        return { name: t.name, q, r, idx: t.idx };
      });
      const sumQ = infos.reduce((s, i) => s + i.q, 0n);
      let leftover = A - sumQ;
      infos.sort((a, b) => {
        if (a.r !== b.r) return a.r > b.r ? -1 : 1;
        return a.idx - b.idx;
      });
      for (let k = 0; k < infos.length && leftover > 0n; k++) {
        infos[k].q += 1n;
        leftover -= 1n;
      }
      accFrom.balance -= A;
      for (const info of infos) {
        const accT = accounts.get(info.name)!;
        accT.balance += info.q;
      }
      continue;
    }
  }

  const out: string[] = [];
  for (const r of rejects) out.push(`line ${r.line}: ${r.reason}`);
  if (rejects.length > 0) out.push('');
  const sortedAccounts = Array.from(accounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  for (const [name, acc] of sortedAccounts) {
    const m = currencies.get(acc.code) ?? 0;
    out.push(`${name} ${acc.code} ${formatMoney(acc.balance, m)}`);
  }
  out.push('');
  const totalsMap = new Map<string, { sum: bigint; count: number; minor: number }>();
  for (const acc of accounts.values()) {
    const m = currencies.get(acc.code) ?? 0;
    const entry = totalsMap.get(acc.code);
    if (entry) { entry.sum += acc.balance; entry.count++; }
    else totalsMap.set(acc.code, { sum: acc.balance, count: 1, minor: m });
  }
  const totalsSorted = Array.from(totalsMap.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  for (const [code, v] of totalsSorted) {
    out.push(`total ${code} ${formatMoney(v.sum, v.minor)} (${v.count} accounts)`);
  }
  console.log(out.join('\n'));
}

main();

