        if (accT.code !== accFrom.code) { mismatch = true; break; }
      }
      if (mismatch) { rejects.push({ line: lineNum, reason: `REJECT currency mismatch` }); continue; }
      const m = getMinor(accFrom.code);
      const A = roundToMinor(parseDecimalString(amtStr), m);
      if (A <= 0n) { rejects.push({ line: lineNum, reason: `REJECT non-positive amount` }); continue; }
      if (accFrom.balance - A < -accFrom.limit) { rejects.push({ line: lineNum, reason: `REJECT insufficient funds ${from}` }); continue; }
      const W = targets.reduce((s, t) => s + t.weight, 0n);
      const infos = targets.map(t => {
        const num = A * t.weight;
        const q = num / W;
        const r = num % W;
        return { name: t.name, q, r, idx: t.idx };
      });
      const sumQ = infos.reduce((s, i) => s + i.q, 0n);
      let leftover = A - sumQ;
      infos.sort((a, b) => {
        if (a.r !== b.r) return a.r > b.r ? -1 : 1;
        return a.idx - b.idx;
      });
      for (let k = 0; k < infos.length && leftover > 0n; k++) {
        infos[k].q += 1n;
        leftover -= 1n;
      }
      accFrom.balance -= A;
      for (const info of infos) {
        const accT = accounts.get(info.name)!;
        accT.balance += info.q;
      }
      continue;
    }
  }

  const out: string[] = [];
  for (const r of rejects) out.push(`line ${r.line}: ${r.reason}`);
  if (rejects.length > 0) out.push('');
  const sortedAccounts = Array.from(accounts.entries()).sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0);
  for (const [name, acc] of sortedAccounts) {
    const m = currencies.get(acc.code) ?? 0;
    out.push(`${name} ${acc.code} ${formatMoney(acc.balance, m)}`);
  }
  out.push('');
  const totalsMap = new Map<string, { sum: bigint; count: number; minor: number }>();
  for (const acc of accounts.values()) {
    const m = currencies.get(acc.code) ?? 0;
    const entry = totalsMap.get(acc.code);
    if (entry) { entry.sum += acc.balance; entry.count++; }
    else totalsMap.set(acc.code, { sum: acc.balance, count: 1, minor: m });
  }
  const totalsSorted = Array.from(totalsMap.entries()).sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0);
  for (const [code, v] of totalsSorted) {
    out.push(`total ${code} ${formatMoney(v.sum, v.minor)} (${v.count} accounts)`);
  }
  console.log(out.join('\n'));
}

main();

import sys
import os
import json
import base64
import re
import hmac
import hashlib

def b64url_decode_str(s):
    if not isinstance(s, str) or s == '':
        raise ValueError()
    if not re.fullmatch(r'[A-Za-z0-9_-]+', s):
        raise ValueError()
    if len(s) % 4 == 1:
        raise ValueError()
    pad = '=' * (-len(s) % 4)
    try:
        data = base64.urlsafe_b64decode(s + pad)
    except Exception:
        raise ValueError()
    return data

def parse_json_object(b):
    try:
        text = b.decode('utf-8')
    except Exception:
        raise ValueError()
    def dup_hook(pairs):
        seen = set()
        for k, _ in pairs:
            if k in seen:
                raise ValueError('duplicate key')
            seen.add(k)
        return dict(pairs)
    try:
        obj = json.loads(text, object_pairs_hook=dup_hook)
    except Exception:
        raise ValueError()
    if not isinstance(obj, dict):
        raise ValueError()
    return obj

def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]
    config_path = os.path.join(directory, 'config.json')
    tokens_path = os.path.join(directory, 'tokens.txt')

    with open(config_path, 'r', encoding='utf-8') as f:
        cfg = json.load(f)

    now = cfg.get('now', 0)
    leeway = cfg.get('leeway', 0)
    issuer_cfg = cfg.get('issuer')
    audience_cfg = cfg.get('audience')

    keys_by_kid = {}
    for k in cfg.get('keys', []):
        kid = k.get('kid')
        if not isinstance(kid, str):
            continue
        try:
            secret = b64url_decode_str(k['k'])
        except Exception:
            secret = b''
        keys_by_kid[kid] = {
            'alg': k.get('alg'),
            'secret': secret,
        }

    valid_count = 0
    invalid_count = 0
    out_lines = []

    with open(tokens_path, 'r', encoding='utf-8') as f:
        raw_lines = f.readlines()

    line_num = 0
    for raw in raw_lines:
        token_str = raw.strip(' \t\r\n')
        if token_str == '':
            continue
        line_num += 1

        parts = token_str.split('.')
        malformed = False
        header_obj = None
        payload_obj = None
        header_b64 = payload_b64 = sig_b64 = None

        if len(parts) != 3 or any(p == '' for p in parts):
            malformed = True
        else:
            header_b64, payload_b64, sig_b64 = parts
            try:
                header_bytes = b64url_decode_str(header_b64)
                payload_bytes = b64url_decode_str(payload_b64)
                _ = b64url_decode_str(sig_b64)
                header_obj = parse_json_object(header_bytes)
                payload_obj = parse_json_object(payload_bytes)
            except Exception:
                malformed = True

        if malformed:
            out_lines.append(f"{line_num}: MALFORMED")
            invalid_count += 1
            continue

        alg = header_obj.get('alg')
        if not isinstance(alg, str) or alg not in ('HS256', 'HS384', 'HS512'):
            out_lines.append(f"{line_num}: UNSUPPORTED_ALG")
            invalid_count += 1
            continue

        kid = header_obj.get('kid')
        if not isinstance(kid, str) or kid not in keys_by_kid:
            out_lines.append(f"{line_num}: UNKNOWN_KEY")
            invalid_count += 1
            continue

        keyinfo = keys_by_kid[kid]
        if keyinfo.get('alg') != alg:
            out_lines.append(f"{line_num}: ALG_MISMATCH")
            invalid_count += 1
            continue

        secret = keyinfo['secret']
        signing_input = f"{header_b64}.{payload_b64}"
        hash_ctor = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}[alg]
        expected_sig = hmac.new(secret, signing_input.encode('ascii'), hash_ctor).digest()
        try:
            sig_bytes = b64url_decode_str(sig_b64)
        except Exception:
            out_lines.append(f"{line_num}: BAD_SIGNATURE")
            invalid_count += 1
            continue
        if not hmac.compare_digest(sig_bytes, expected_sig):
            out_lines.append(f"{line_num}: BAD_SIGNATURE")
            invalid_count += 1
            continue

        exp = payload_obj.get('exp')
        if exp is not None:
            try:
                exp_num = float(exp)
                if now >= exp_num + leeway:
                    out_lines.append(f"{line_num}: EXPIRED")
                    invalid_count += 1
                    continue
            except Exception:
                pass

        nbf = payload_obj.get('nbf')
        if nbf is not None:
            try:
                nbf_num = float(nbf)
                if now + leeway < nbf_num:
                    out_lines.append(f"{line_num}: NOT_YET_VALID")
                    invalid_count += 1
                    continue
            except Exception:
                pass

        iss = payload_obj.get('iss')
        if not isinstance(iss, str) or iss != issuer_cfg:
            out_lines.append(f"{line_num}: BAD_ISSUER")
            invalid_count += 1
            continue

        aud = payload_obj.get('aud')
        aud_ok = False
        if isinstance(aud, str):
            if aud == audience_cfg:
                aud_ok = True
        elif isinstance(aud, list):
            if any(isinstance(x, str) and x == audience_cfg for x in aud):
                aud_ok = True
        if not aud_ok:
            out_lines.append(f"{line_num}: BAD_AUDIENCE")
            invalid_count += 1
            continue

        sub_raw = payload_obj.get('sub', '')
        sub = str(sub_raw) if isinstance(sub_raw, str) else ''
        scope_raw = payload_obj.get('scope', '')
        if isinstance(scope_raw, str):
            pieces = [p for p in scope_raw.split(' ') if p]
            uniq = sorted(set(pieces))
            scopes_joined = ','.join(uniq)
        else:
            scopes_joined = ''
        out_lines.append(f"{line_num}: VALID sub={sub} scope={scopes_joined}")
        valid_count += 1

    out_lines.append('')
    out_lines.append(f"valid={valid_count} invalid={invalid_count}")
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    main()

import { readFileSync, readdirSync } from 'fs';
import { resolve } from 'path';
import * as crypto from 'crypto';

function base64urlToBuffer(s: string): Buffer | null {
  if (!/^[A-Za-z0-9_-]+$/.test(s)) return null;
  if (s.length === 0) return null;
  if (s.length % 4 === 1) return null;
  try {
    let b64 = s.replace(/-/g, '+').replace(/_/g, '/');
    const pad = (4 - (b64.length % 4)) % 4;
    b64 += '='.repeat(pad);
    const buf = Buffer.from(b64, 'base64');
    // re-encode to check unused bits / canonical form
    const re = base64urlEncode(buf);
    if (re !== s) return null;
    return buf;
  } catch {
    return null;
  }
}

function base64urlEncode(buf: Buffer): string {
  return buf.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function isObject(v: any): v is Record<string, unknown> {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function hasDuplicateKeys(jsonStr: string): boolean {
  const re = /"([^"\\]*)"\s*:/g;
  const seen = new Set<string>();
  let m: RegExpExecArray | null;
  while ((m = re.exec(jsonStr)) !== null) {
    const key = m[1];
    if (seen.has(key)) return true;
    seen.add(key);
  }
  return false;
}

function parseJsonObject(s: string): Record<string, unknown> | null {
  if (!s.startsWith('{') || !s.endsWith('}')) return null;
  if (hasDuplicateKeys(s)) return null;
  try {
    const v = JSON.parse(s);
    if (!isObject(v)) return null;
    return v;
  } catch {
    return null;
  }
}

function main() {
  const dir = process.argv[2];
  if (!dir) process.exit(0);
  const base = resolve(dir);
  const configRaw = readFileSync(resolve(base, 'config.json'), 'utf-8');
  const cfg = JSON.parse(configRaw);
  const now: number = cfg.now;
  const leeway: number = cfg.leeway;
  const issuer: string = cfg.issuer;
  const audience: string = cfg.audience;
  const keys = (cfg.keys || []).map((k: any) => ({
    kid: k.kid,
    alg: k.alg,
    secret: base64urlToBuffer(k.k) ?? Buffer.alloc(0),
  }));

  const tokensRaw = readFileSync(resolve(base, 'tokens.txt'), 'utf-8');
  const lines = tokensRaw.split(/\r?\n/);
  const tokens: { idx: number; raw: string }[] = [];
  let cnt = 0;
  for (const l of lines) {
    const t = l.replace(/^[ \t]+|[ \t]+$/g, '');
    if (t === '') continue;
    cnt++;
    tokens.push({ idx: cnt, raw: t });
  }

  const allowedAlgs = new Set(['HS256', 'HS384', 'HS512']);
  let validCount = 0;
  let invalidCount = 0;
  const out: string[] = [];

  for (const { idx, raw } of tokens) {
    const parts = raw.split('.');
    let result = '';
    let sub = '';
    let scopes = '';

    // 1 MALFORMED
    if (parts.length !== 3 || parts.some(p => p.length === 0)) {
      result = 'MALFORMED';
    } else {
      const [headerSeg, payloadSeg, sigSeg] = parts;
      const headerBuf = base64urlToBuffer(headerSeg);
      const payloadBuf = base64urlToBuffer(payloadSeg);
      const sigBuf = base64urlToBuffer(sigSeg);
      if (!headerBuf || !payloadBuf || !sigBuf) {
        result = 'MALFORMED';
      } else {
        const headerStr = headerBuf.toString('utf-8');
        const payloadStr = payloadBuf.toString('utf-8');
        const headerObj = parseJsonObject(headerStr);
        const payloadObj = parseJsonObject(payloadStr);
        if (!headerObj || !payloadObj) {
          result = 'MALFORMED';
        } else {
          // 2 UNSUPPORTED_ALG
          const alg = headerObj.alg;
          if (typeof alg !== 'string' || !allowedAlgs.has(alg)) {
            result = 'UNSUPPORTED_ALG';
          } else {
            // 3 UNKNOWN_KEY
            const kid = headerObj.kid;
            if (typeof kid !== 'string') {
              result = 'UNKNOWN_KEY';
            } else {
              const key = keys.find(k => k.kid === kid);
              if (!key) {
                result = 'UNKNOWN_KEY';
              } else {
                // 4 ALG_MISMATCH
                if (key.alg !== alg) {
                  result = 'ALG_MISMATCH';
                } else {
                  // 5 BAD_SIGNATURE
                  const signingInput = `${headerSeg}.${payloadSeg}`;
                  const hmac = crypto.createHmac(alg.replace('HS', ''), key.secret);
                  hmac.update(signingInput);
                  const expectedSig = base64urlEncode(hmac.digest());
                  if (expectedSig !== sigSeg) {
                    result = 'BAD_SIGNATURE';
                  } else {
                    // 6 EXPIRED
                    const exp = payloadObj.exp;
                    if (typeof exp === 'number' && now >= (exp + leeway)) {
                      result = 'EXPIRED';
                    } else {
                      // 7 NOT_YET_VALID
                      const nbf = payloadObj.nbf;
                      if (typeof nbf === 'number' && now + leeway < nbf) {
                        result = 'NOT_YET_VALID';
                      } else {
                        // 8 BAD_ISSUER
                        const iss = payloadObj.iss;
                        if (typeof iss !== 'string' || iss !== issuer) {
                          result = 'BAD_ISSUER';
                        } else {
                          // 9 BAD_AUDIENCE
                          const aud = payloadObj.aud;
                          let audOk = false;
                          if (typeof aud === 'string') {
                            audOk = aud === audience;
                          } else if (Array.isArray(aud)) {
                            audOk = aud.includes(audience);
                          }
                          if (!audOk) {
                            result = 'BAD_AUDIENCE';
                          } else {
                            // VALID
                            result = 'VALID';
                            const subVal = payloadObj.sub;
                            sub = typeof subVal === 'string' ? subVal : '';
                            const scopeRaw = payloadObj.scope;
                            if (typeof scopeRaw === 'string') {
                              const pieces = scopeRaw.split(/\s+/).filter(Boolean);
                              const uniq = Array.from(new Set(pieces));
                              uniq.sort();
                              scopes = uniq.join(',');
                            }
                            validCount++;
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }

    if (result === 'VALID') {
      out.push(`${idx}: VALID sub=${sub} scope=${scopes}`);
    } else {
      out.push(`${idx}: ${result}`);
      invalidCount++;
    }
  }

  console.log(out.join('\n'));
  console.log('');
  console.log(`valid=${validCount} invalid=${invalidCount}`);
}

