import json
import os
import sys

def encode_token(tok: str) -> str:
    return tok.replace('~', '~0').replace('/', '~1')

def decode_token(tok: str) -> str:
    return tok.replace('~1', '/').replace('~0', '~')

def resolve_pointer(ptr_str, root):
    if ptr_str == '#' or ptr_str == '':
        return root
    if not ptr_str.startswith('#'):
        return None
    path = ptr_str[1:]
    if path == '' or path == '/':
        return root
    parts = path.split('/')
    cur = root
    # parts[0] is empty
    for tok in parts[1:]:
        tok = decode_token(tok)
        if isinstance(cur, dict):
            cur = cur.get(tok)
        elif isinstance(cur, list):
            try:
                idx = int(tok)
                cur = cur[idx]
            except Exception:
                return None
        else:
            return None
        if cur is None:
            return None
    return cur

def json_type_of(v):
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'boolean'
    if isinstance(v, int) and not isinstance(v, bool):
        return 'number'
    if isinstance(v, float):
        return 'number'
    if isinstance(v, str):
        return 'string'
    if isinstance(v, list):
        return 'array'
    if isinstance(v, dict):
        return 'object'
    return None

def is_number(v):
    return json_type_of(v) == 'number'

def is_integer_number(v):
    if not is_number(v):
        return False
    try:
        return float(v).is_integer()
    except Exception:
        return False

def matches_type(value, type_name):
    if type_name == 'null':
        return value is None
    if type_name == 'boolean':
        return isinstance(value, bool)
    if type_name == 'object':
        return isinstance(value, dict)
    if type_name == 'array':
        return isinstance(value, list)
    if type_name == 'number':
        return is_number(value)
    if type_name == 'string':
        return isinstance(value, str)
    if type_name == 'integer':
        return is_integer_number(value)
    return False

def deep_equal(a, b):
    if type(a) is type(b) and a is b:
        return True
    ta = json_type_of(a)
    tb = json_type_of(b)
    if ta != tb:
        # numbers allow int/float mix
        if ta == 'number' and tb == 'number':
            try:
                return float(a) == float(b)
            except Exception:
                return False
        return False
    if ta in ('null', 'boolean'):
        return a == b
    if ta == 'number':
        try:
            return float(a) == float(b)
        except Exception:
            return False
    if ta == 'string':
        return a == b
    if ta == 'array':
        if len(a) != len(b):
            return False
        return all(deep_equal(x, y) for x, y in zip(a, b))
    if ta == 'object':
        if set(a.keys()) != set(b.keys()):
            return False
        return all(deep_equal(a[k], b[k]) for k in a)
    return False

def validate_value(value, inst_ptr, schema_node, schema_ptr, schema_root):
    if schema_node is True:
        return set()
    if schema_node is False:
        return {(inst_ptr, schema_ptr)}
    if not isinstance(schema_node, dict):
        return set()

    errors = set()

    # $ref
    if '$ref' in schema_node:
        ref_ptr_str = schema_node['$ref']
        ref_node = resolve_pointer(ref_ptr_str, schema_root)
        if ref_node is not None:
            ref_errors = validate_value(value, inst_ptr, ref_node, ref_ptr_str, schema_root)
            errors.update(ref_errors)

    # type
    if 'type' in schema_node:
        t = schema_node['type']
        types = t if isinstance(t, list) else [t]
        if not any(matches_type(value, tn) for tn in types):
            errors.add((inst_ptr, schema_ptr + '/type'))

    # enum
    if 'enum' in schema_node:
        enum_vals = schema_node['enum']
        if not any(deep_equal(value, ev) for ev in enum_vals):
            errors.add((inst_ptr, schema_ptr + '/enum'))

    # const
    if 'const' in schema_node:
        if not deep_equal(value, schema_node['const']):
            errors.add((inst_ptr, schema_ptr + '/const'))

    # numbers
    if is_number(value):
        if 'minimum' in schema_node:
            if value < schema_node['minimum']:
                errors.add((inst_ptr, schema_ptr + '/minimum'))
        if 'maximum' in schema_node:
            if value > schema_node['maximum']:
                errors.add((inst_ptr, schema_ptr + '/maximum'))
        if 'exclusiveMinimum' in schema_node:
            if not (value > schema_node['exclusiveMinimum']):
                errors.add((inst_ptr, schema_ptr + '/exclusiveMinimum'))
        if 'exclusiveMaximum' in schema_node:
            if not (value < schema_node['exclusiveMaximum']):
                errors.add((inst_ptr, schema_ptr + '/exclusiveMaximum'))

    # strings
    if isinstance(value, str):
        l = len(value)
        if 'minLength' in schema_node:
            if l < schema_node['minLength']:
                errors.add((inst_ptr, schema_ptr + '/minLength'))
        if 'maxLength' in schema_node:
            if l > schema_node['maxLength']:
                errors.add((inst_ptr, schema_ptr + '/maxLength'))

    # arrays
    if isinstance(value, list):
        cnt = len(value)
        if 'minItems' in schema_node:
            if cnt < schema_node['minItems']:
                errors.add((inst_ptr, schema_ptr + '/minItems'))
        if 'maxItems' in schema_node:
            if cnt > schema_node['maxItems']:
                errors.add((inst_ptr, schema_ptr + '/maxItems'))
        if schema_node.get('uniqueItems') is True:
            dup = False
            n = len(value)
            for i in range(n):
                for j in range(i + 1, n):
                    if deep_equal(value[i], value[j]):
                        dup = True
                        break
                if dup:
                    break
            if dup:
                errors.add((inst_ptr, schema_ptr + '/uniqueItems'))
        # prefixItems
        if 'prefixItems' in schema_node:
            prefix = schema_node['prefixItems']
            if isinstance(prefix, list):
                for i, sub_schema in enumerate(prefix):
                    if i < len(value):
                        sub_inst = inst_ptr + '/' + str(i)
                        sub_ptr = schema_ptr + '/prefixItems/' + str(i)
                        errors.update(validate_value(value[i], sub_inst, sub_schema, sub_ptr, schema_root))
        # items
        if 'items' in schema_node:
            items_schema = schema_node['items']
            start = len(schema_node.get('prefixItems', [])) if 'prefixItems' in schema_node else 0
            for i in range(start, len(value)):
                sub_inst = inst_ptr + '/' + str(i)
                sub_ptr = schema_ptr + '/items'
                errors.update(validate_value(value[i], sub_inst, items_schema, sub_ptr, schema_root))

    # objects
    if isinstance(value, dict):
        # properties
        if 'properties' in schema_node:
            props = schema_node['properties']
            for name, sub_schema in props.items():
                if name in value:
                    sub_inst = inst_ptr + '/' + encode_token(name)
                    sub_ptr = schema_ptr + '/properties/' + encode_token(name)
                    errors.update(validate_value(value[name], sub_inst, sub_schema, sub_ptr, schema_root))
        # required
        if 'required' in schema_node:
            req = schema_node['required']
            for j, name in enumerate(req):
                if name not in value:
                    errors.add((inst_ptr, schema_ptr + '/required/' + str(j)))
        # additionalProperties
        if 'additionalProperties' in schema_node:
            add_schema = schema_node['additionalProperties']
            prop_names = set(schema_node.get('properties', {}).keys())
            for name in value:
                if name not in prop_names:
                    sub_inst = inst_ptr + '/' + encode_token(name)
                    sub_ptr = schema_ptr + '/additionalProperties'
                    errors.update(validate_value(value[name], sub_inst, add_schema, sub_ptr, schema_root))
        # min/max properties
        cnt = len(value)
        if 'minProperties' in schema_node:
            if cnt < schema_node['minProperties']:
                errors.add((inst_ptr, schema_ptr + '/minProperties'))
        if 'maxProperties' in schema_node:
            if cnt > schema_node['maxProperties']:
                errors.add((inst_ptr, schema_ptr + '/maxProperties'))

    # allOf
    if 'allOf' in schema_node:
        for i, sub_schema in enumerate(schema_node['allOf']):
            sub_ptr = schema_ptr + '/allOf/' + str(i)
            errors.update(validate_value(value, inst_ptr, sub_schema, sub_ptr, schema_root))

    # anyOf
    if 'anyOf' in schema_node:
        subs = schema_node['anyOf']
        accepts = False
        for i, sub_schema in enumerate(subs):
            sub_ptr = schema_ptr + '/anyOf/' + str(i)
            sub_err = validate_value(value, inst_ptr, sub_schema, sub_ptr, schema_root)
            if not sub_err:
                accepts = True
                break
        if not accepts:
            errors.add((inst_ptr, schema_ptr + '/anyOf'))

    # oneOf
    if 'oneOf' in schema_node:
        subs = schema_node['oneOf']
        cnt_accept = 0
        for i, sub_schema in enumerate(subs):
            sub_ptr = schema_ptr + '/oneOf/' + str(i)
            sub_err = validate_value(value, inst_ptr, sub_schema, sub_ptr, schema_root)
            if not sub_err:
                cnt_accept += 1
        if cnt_accept != 1:
            errors.add((inst_ptr, schema_ptr + '/oneOf'))

    # not
    if 'not' in schema_node:
        sub_schema = schema_node['not']
        sub_ptr = schema_ptr + '/not'
        sub_err = validate_value(value, inst_ptr, sub_schema, sub_ptr, schema_root)
        if not sub_err:
            errors.add((inst_ptr, schema_ptr + '/not'))

    # if/then/else
    if 'if' in schema_node:
        if_schema = schema_node['if']
        if_ptr = schema_ptr + '/if'
        if_err = validate_value(value, inst_ptr, if_schema, if_ptr, schema_root)
        if not if_err:
            if 'then' in schema_node:
                then_schema = schema_node['then']
                then_ptr = schema_ptr + '/then'
                errors.update(validate_value(value, inst_ptr, then_schema, then_ptr, schema_root))
        else:
            if 'else' in schema_node:
                else_schema = schema_node['else']
                else_ptr = schema_ptr + '/else'
                errors.update(validate_value(value, inst_ptr, else_schema, else_ptr, schema_root))

    return errors

def main():
    if len(sys.argv) < 2:
        print('Usage: python3 main.py <dir>')
        sys.exit(1)
    d = sys.argv[1]
    schema_path = os.path.join(d, 'schema.json')
    instances_path = os.path.join(d, 'instances.json')
    with open(schema_path, 'r', encoding='utf-8') as f:
        schema_root = json.load(f)
    with open(instances_path, 'r', encoding='utf-8') as f:
        instances = json.load(f)

    valid_cnt = 0
    invalid_cnt = 0
    out_lines = []
    for idx, inst in enumerate(instances):
        errs = validate_value(inst, '#', schema_root, '#', schema_root)
        if not errs:
            out_lines.append(f'{idx}: valid')
            valid_cnt += 1
        else:
            # sort
            sorted_errs = sorted(errs, key=lambda x: (x[0], x[1]))
            out_lines.append(f'{idx}: invalid ({len(sorted_errs)})')
            for inst_loc, schema_loc in sorted_errs:
                out_lines.append(f'  {inst_loc} {schema_loc}')
            invalid_cnt += 1
    out_lines.append(f'valid={valid_cnt} invalid={invalid_cnt}')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    main()

import Foundation
import CryptoKit

struct KeyInfo {
    let kid: String
    let alg: String
    let secret: Data
}

func base64urlDecode(_ s: String) -> Data? {
    var b64 = s.replacingOccurrences(of: "-", with: "+")
    b64 = b64.replacingOccurrences(of: "_", with: "/")
    let pad = (4 - b64.count % 4) % 4
    if pad > 0 {
        b64 += String(repeating: "=", count: pad)
    }
    return Data(base64Encoded: b64, options: .ignoreUnknownCharacters)
}

func base64urlEncode(_ data: Data) -> String {
    var s = data.base64EncodedString()
    s = s.replacingOccurrences(of: "+", with: "-")
    s = s.replacingOccurrences(of: "/", with: "_")
    s = s.replacingOccurrences(of: "=", with: "")
    return s
}

func isBase64urlValid(_ s: String) -> Bool {
    if s.isEmpty { return false }
    let allowed = CharacterSet(charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_")
    if s.rangeOfCharacter(from: allowed.inverted) != nil { return false }
    if s.contains("=") { return false }
    if s.count % 4 == 1 { return false }
    return true
}

