                    }
                    if !audOk {
                        output = "BAD_AUDIENCE"
                        results.append((lineNum, output))
                        invalidCount += 1
                        continue
                    }
                    let sub = (payloadDict!["sub"] as? String) ?? ""
                    var scopesStr = ""
                    if let scopeRaw = payloadDict!["scope"] as? String {
                        let partsScope = scopeRaw.split(separator: " ").map(String.init)
                        let uniq = Array(Set(partsScope.filter { !$0.isEmpty })).sorted()
                        scopesStr = uniq.joined(separator: ",")
                    }
                    output = "VALID sub=\(sub) scope=\(scopesStr)"
                    results.append((lineNum, output))
                    validCount += 1
                    continue
                }
            }
        }
    }
    if malformed || output.isEmpty {
        output = "MALFORMED"
        results.append((lineNum, output))
        invalidCount += 1
    }
}

for (n, out) in results {
    print("\(n): \(out)")
}
print("")
print("valid=\(validCount) invalid=\(invalidCount)")

import sys
import json

TOOLS = [
    {
        "name": "kv_set",
        "title": "Set a value",
        "description": "Store a string value under a key, replacing any previous value.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "key": {"type": "string", "minLength": 1},
                "value": {"type": "string"}
            },
            "required": ["key", "value"],
            "additionalProperties": False
        }
    },
    {
        "name": "kv_get",
        "title": "Get a value",
        "description": "Return the value stored under a key.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "key": {"type": "string", "minLength": 1}
            },
            "required": ["key"],
            "additionalProperties": False
        }
    },
    {
        "name": "kv_list",
        "title": "List keys",
        "description": "List the stored keys that start with a prefix, sorted by Unicode code point.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "prefix": {"type": "string"}
            },
            "additionalProperties": False
        },
        "outputSchema": {
            "type": "object",
            "properties": {
                "keys": {"type": "array", "items": {"type": "string"}},
                "count": {"type": "integer"}
            },
            "required": ["keys", "count"]
        }
    },
    {
        "name": "sum",
        "title": "Sum integers",
        "description": "Add up a non-empty list of integers.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "numbers": {"type": "array", "items": {"type": "integer"}, "minItems": 1}
            },
            "required": ["numbers"],
            "additionalProperties": False
        },
        "outputSchema": {
            "type": "object",
            "properties": {
                "sum": {"type": "integer"},
                "count": {"type": "integer"}
            },
            "required": ["sum", "count"]
        },
        "annotations": {"readOnlyHint": True, "idempotentHint": True}
    },
    {
        "name": "text_stats",
        "title": "Text statistics",
        "description": "Count the words, Unicode code points and UTF-8 bytes of a text.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "text": {"type": "string"}
            },
            "required": ["text"],
            "additionalProperties": False
        },
        "outputSchema": {
            "type": "object",
            "properties": {
                "words": {"type": "integer"},
                "codepoints": {"type": "integer"},
                "utf8_bytes": {"type": "integer"}
            },
            "required": ["words", "codepoints", "utf8_bytes"]
        },
        "annotations": {"readOnlyHint": True}
    }
]

TOOL_MAP = {t["name"]: t for t in TOOLS}

ALLOWED_VERSIONS = {"2025-06-18", "2025-03-26", "2024-11-05"}
DEFAULT_VERSION = "2025-06-18"

def is_valid_id(v):
    if isinstance(v, str):
        return True
    if isinstance(v, int) and not isinstance(v, bool):
        return True
    return False

def json_rpc_error(out_id, code, message):
    return {"jsonrpc": "2.0", "id": out_id, "error": {"code": code, "message": message}}

def json_rpc_result(out_id, result):
    return {"jsonrpc": "2.0", "id": out_id, "result": result}

def tool_result(content_text, is_error=False, structured=None):
    obj = {"content": [{"type": "text", "text": content_text}], "isError": is_error}
    if structured is not None:
        obj["structuredContent"] = structured
    return obj

def validate_integer(v):
    return isinstance(v, int) and not isinstance(v, bool)

def main():
    initialized = False
    store = {}
    out_lines = []

    for raw in sys.stdin:
        line = raw.rstrip("\r\n")
        if line.strip(" \t\r") == "":
            continue
        # parse
        try:
            msg = json.loads(line)
        except Exception:
            out_lines.append(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}}))
            continue

        if not isinstance(msg, dict):
            out_lines.append(json.dumps({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}}))
            continue

        # response from client ?
        if "method" not in msg and ("result" in msg or "error" in msg):
            continue

        # invalid request checks
        jsonrpc_ok = msg.get("jsonrpc") == "2.0"
        method_ok = isinstance(msg.get("method"), str)
        id_present = "id" in msg
        id_valid = is_valid_id(msg.get("id")) if id_present else True
        # if id present and invalid
        id_invalid = id_present and not is_valid_id(msg.get("id"))

        if (not jsonrpc_ok) or (not method_ok) or id_invalid:
            # determine id to echo
            raw_id = msg.get("id") if id_present else None
            out_id = raw_id if is_valid_id(raw_id) else None
            out_lines.append(json.dumps(json_rpc_error(out_id, -32600, "Invalid Request")))
            continue

        # notification
        if "id" not in msg:
            continue

        out_id = msg["id"]
        method = msg["method"]
        params = msg.get("params")

        # method check
        allowed_methods = {"initialize", "ping", "tools/list", "tools/call"}
        if method not in allowed_methods:
            out_lines.append(json.dumps(json_rpc_error(out_id, -32601, "Method not found")))
            continue

        # params object check
        if "params" in msg and not isinstance(params, dict):
            out_lines.append(json.dumps(json_rpc_error(out_id, -32602, "Invalid params")))
            continue

        # server not initialized
        if not initialized and method not in ("initialize", "ping"):
            out_lines.append(json.dumps(json_rpc_error(out_id, -32002, "Server not initialized")))
            continue

        # dispatch
        if method == "initialize":
            if initialized:
                out_lines.append(json.dumps(json_rpc_error(out_id, -32600, "Already initialized")))
                continue
            # validate params
            if not isinstance(params, dict) or "protocolVersion" not in params or not isinstance(params["protocolVersion"], str):
                out_lines.append(json.dumps(json_rpc_error(out_id, -32602, "Invalid params")))
                continue
            client_ver = params["protocolVersion"]
            version = client_ver if client_ver in ALLOWED_VERSIONS else DEFAULT_VERSION
            initialized = True
            result = {
                "protocolVersion": version,
                "capabilities": {"tools": {"listChanged": False}},
                "serverInfo": {"name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"}
            }
            out_lines.append(json.dumps(json_rpc_result(out_id, result)))
            continue

        if method == "ping":
            out_lines.append(json.dumps(json_rpc_result(out_id, {})))
            continue

        if method == "tools/list":
            out_lines.append(json.dumps(json_rpc_result(out_id, {"tools": TOOLS})))
            continue

        if method == "tools/call":
            if not isinstance(params, dict):
                out_lines.append(json.dumps(json_rpc_error(out_id, -32602, "Invalid params")))
                continue
            name = params.get("name")
            if not isinstance(name, str):
                out_lines.append(json.dumps(json_rpc_error(out_id, -32602, "Invalid params")))
                continue
            if name not in TOOL_MAP:
                out_lines.append(json.dumps(json_rpc_error(out_id, -32602, f"Unknown tool: {name}")))
                continue

            tool = TOOL_MAP[name]
            schema = tool["inputSchema"]
            props = schema.get("properties", {})
            required = set(schema.get("required", []))

            arguments = params.get("arguments", {})
            # arguments may be absent -> {}
            if "arguments" in params and not isinstance(params["arguments"], dict):
                # tool failure
                res = tool_result("arguments must be an object", is_error=True)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            # ensure dict
            if not isinstance(arguments, dict):
                arguments = {}

            # unknown arguments
            known_names = set(props.keys())
            unknown = [k for k in arguments.keys() if k not in known_names]
            if unknown:
                bad = min(unknown)
                res = tool_result(f"unknown argument: {bad}", is_error=True)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            # validate each property in order
            # order from schema properties dict insertion order
            error_msg = None
            for pname, pschema in props.items():
                if pname in required and pname not in arguments:
                    error_msg = f"missing required argument: {pname}"
                    break
                if pname in arguments:
                    val = arguments[pname]
                    ptype = pschema.get("type")
                    if ptype == "string":
                        if not isinstance(val, str):
                            error_msg = f"argument {pname} must be a string"
                            break
                        if "minLength" in pschema and len(val) < pschema["minLength"]:
                            error_msg = f"argument {pname} must not be empty"
                            break
                    elif ptype == "array":
                        if not isinstance(val, list):
                            error_msg = f"argument {pname} must be an array of integers"
                            break
                        if "minItems" in pschema and len(val) < pschema["minItems"]:
                            error_msg = f"argument {pname} must not be empty"
                            break
                        # check integers
                        bad_elem = False
                        for el in val:
                            if not validate_integer(el):
                                bad_elem = True
                                break
                        if bad_elem:
                            error_msg = f"argument {pname} must be an array of integers"
                            break
                    else:
                        # other types not used
                        pass
            if error_msg:
                res = tool_result(error_msg, is_error=True)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            # execute tool
            if name == "kv_set":
                key = arguments["key"]
                value = arguments["value"]
                existed = key in store
                store[key] = value
                text = f"updated {key}" if existed else f"created {key}"
                res = tool_result(text, is_error=False)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            if name == "kv_get":
                key = arguments["key"]
                if key not in store:
                    res = tool_result(f"key not found: {key}", is_error=True)
                    out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                    continue
                val = store[key]
                res = tool_result(val, is_error=False)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            if name == "kv_list":
                prefix = arguments.get("prefix", "")
                if prefix is None:
                    prefix = ""
                if not isinstance(prefix, str):
                    prefix = ""
                keys = [k for k in store.keys() if k.startswith(prefix)]
                keys.sort()
                s = {"keys": keys, "count": len(keys)}
                text = json.dumps(s, separators=(",", ":"))
                res = tool_result(text, is_error=False, structured=s)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            if name == "sum":
                nums = arguments["numbers"]
                total = sum(nums)
                cnt = len(nums)
                s = {"sum": total, "count": cnt}
                text = json.dumps(s, separators=(",", ":"))
                res = tool_result(text, is_error=False, structured=s)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

            if name == "text_stats":
                txt = arguments["text"]
                # words
                parts = []
                cur = []
                for ch in txt:
                    if ch in " \t\r\n":
                        if cur:
                            parts.append("".join(cur))
                            cur = []
                    else:
                        cur.append(ch)
                if cur:
                    parts.append("".join(cur))
                w = len(parts)
                c = len(txt)
                b = len(txt.encode("utf-8"))
                s = {"words": w, "codepoints": c, "utf8_bytes": b}
                text = json.dumps(s, separators=(",", ":"))
                res = tool_result(text, is_error=False, structured=s)
                out_lines.append(json.dumps(json_rpc_result(out_id, res)))
                continue

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()

import * as fs from 'fs';
import * as path from 'path';

function encodeToken(t: string): string {
  return t.replace(/~/g, '~0').replace(/\//g, '~1');
}
function decodeToken(t: string): string {
  return t.replace(/~1/g, '/').replace(/~0/g, '~');
}
function pointerToTokens(ptr: string): string[] {
  if (ptr === '' || ptr === '#') return [];
  const raw = ptr.startsWith('#') ? ptr.slice(1) : ptr;
  if (!raw) return [];
  return raw.split('/').slice(1).map(decodeToken);
}
function tokensToPointer(tokens: string[]): string {
  if (tokens.length === 0) return '#';
  return '#' + tokens.map(t => '/' + encodeToken(t)).join('');
}

function getNodeByPointer(root: any, ptr: string): any {
  const tokens = pointerToTokens(ptr);
  let cur = root;
  for (const tok of tokens) {
    if (cur == null || typeof cur !== 'object') return undefined;
    cur = cur[tok];
  }
  return cur;
}

function isObject(v: any): boolean {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function deepEqual(a: any, b: any): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (typeof a === 'number' && typeof b === 'number') return a === b;
  if (typeof a === 'string') return a === b;
  if (typeof a === 'boolean' || a === null) return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!deepEqual(a[i], b[i])) return false;
    return true;
  }
  if (isObject(a) && isObject(b)) {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    for (const k of ka) if (!deepEqual(a[k], b[k])) return false;
    return true;
  }
  return false;
}

function codePoints(s: string): number[] {
  const out: number[] = [];
  for (const ch of s) out.push(ch.codePointAt(0)!);
  return out;
}
function cmpStrings(a: string, b: string): number {
  const ca = codePoints(a);
  const cb = codePoints(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i++) {
    if (ca[i] !== cb[i]) return ca[i] - cb[i];
  }
  return ca.length - cb.length;
}

function matchType(inst: any, typeName: string): boolean {
  switch (typeName) {
    case 'null': return inst === null;
    case 'boolean': return typeof inst === 'boolean';
    case 'object': return isObject(inst);
    case 'array': return Array.isArray(inst);
    case 'number': return typeof inst === 'number';
    case 'string': return typeof inst === 'string';
    case 'integer': return typeof inst === 'number' && Number.isInteger(inst);
  }
  return false;
}

type ErrorPair = [string, string];

function validateNode(
  inst: any,
  instPtr: string,
  schemaNode: any,
  schemaPtr: string,
  schemaRoot: any
): ErrorPair[] {
  const errors: ErrorPair[] = [];

  if (schemaNode === true) return [];
  if (schemaNode === false) {
    errors.push([instPtr, schemaPtr]);
    return errors;
  }
  if (typeof schemaNode !== 'object' || schemaNode === null) return errors;

  // type
  if ('type' in schemaNode) {
    const t = schemaNode.type;
    let ok = false;
    if (Array.isArray(t)) {
      for (const tn of t) if (matchType(inst, tn)) { ok = true; break; }
    } else {
      ok = matchType(inst, t);
    }
    if (!ok) errors.push([instPtr, schemaPtr + '/type']);
  }

  // enum
  if ('enum' in schemaNode) {
    const arr = schemaNode.enum;
    if (!Array.isArray(arr) || !arr.some(v => deepEqual(inst, v))) {
      errors.push([instPtr, schemaPtr + '/enum']);
    }
  }

  // const
  if ('const' in schemaNode) {
    if (!deepEqual(inst, schemaNode.const)) {
      errors.push([instPtr, schemaPtr + '/const']);
    }
  }

  // numeric
  if (typeof inst === 'number') {
    if ('minimum' in schemaNode && inst < (schemaNode.minimum as number)) {
      errors.push([instPtr, schemaPtr + '/minimum']);
    }
    if ('maximum' in schemaNode && inst > (schemaNode.maximum as number)) {
      errors.push([instPtr, schemaPtr + '/maximum']);
    }
    if ('exclusiveMinimum' in schemaNode && inst <= (schemaNode.exclusiveMinimum as number)) {
      errors.push([instPtr, schemaPtr + '/exclusiveMinimum']);
    }
    if ('exclusiveMaximum' in schemaNode && inst >= (schemaNode.exclusiveMaximum as number)) {
      errors.push([instPtr, schemaPtr + '/exclusiveMaximum']);
    }
  }

  // string
  if (typeof inst === 'string') {
    const len = Array.from(inst).length;
    if ('minLength' in schemaNode && len < (schemaNode.minLength as number)) {
      errors.push([instPtr, schemaPtr + '/minLength']);
    }
    if ('maxLength' in schemaNode && len > (schemaNode.maxLength as number)) {
      errors.push([instPtr, schemaPtr + '/maxLength']);
    }
  }

  // array
  if (Array.isArray(inst)) {
    if ('minItems' in schemaNode && inst.length < (schemaNode.minItems as number)) {
      errors.push([instPtr, schemaPtr + '/minItems']);
    }
    if ('maxItems' in schemaNode && inst.length > (schemaNode.maxItems as number)) {
      errors.push([instPtr, schemaPtr + '/maxItems']);
    }
    if (schemaNode.uniqueItems === true) {
      for (let i = 0; i < inst.length; i++) {
        for (let j = i + 1; j < inst.length; j++) {
          if (deepEqual(inst[i], inst[j])) {
            errors.push([instPtr, schemaPtr + '/uniqueItems']);
            i = inst.length;
            break;
          }
        }
      }
    }
    // prefixItems
    if ('prefixItems' in schemaNode && Array.isArray(schemaNode.prefixItems)) {
      const pref = schemaNode.prefixItems as any[];
      for (let i = 0; i < Math.min(inst.length, pref.length); i++) {
        const childPtr = instPtr + '/' + i;
        const childSchemaPtr = schemaPtr + '/prefixItems/' + i;
        errors.push(...validateNode(inst[i], childPtr, pref[i], childSchemaPtr, schemaRoot));
      }
    }
    // items
    if ('items' in schemaNode) {
      const prefLen = Array.isArray(schemaNode.prefixItems) ? schemaNode.prefixItems.length : 0;
      for (let i = prefLen; i < inst.length; i++) {
        const childPtr = instPtr + '/' + i;
        const childSchemaPtr = schemaPtr + '/items';
        errors.push(...validateNode(inst[i], childPtr, schemaNode.items, childSchemaPtr, schemaRoot));
      }
    }
  }

  // object
  if (isObject(inst)) {
    const props = schemaNode.properties as Record<string, any> | undefined;
    const propNames = props ? Object.keys(props) : [];
    const propSet = new Set(propNames);

    // properties
    for (const name of propNames) {
      if (name in inst) {
        const childPtr = instPtr + '/' + encodeToken(name);
        const childSchemaPtr = schemaPtr + '/properties/' + encodeToken(name);
        errors.push(...validateNode(inst[name], childPtr, props[name], childSchemaPtr, schemaRoot));
      }
    }

    // required
    if ('required' in schemaNode && Array.isArray(schemaNode.required)) {
      const req = schemaNode.required as string[];
      req.forEach((name, idx) => {
        if (!(name in inst)) {
          errors.push([instPtr, schemaPtr + '/required/' + idx]);
        }
      });
    }

    // additionalProperties
    if ('additionalProperties' in schemaNode) {
      const addSchema = schemaNode.additionalProperties;
      for (const name of Object.keys(inst)) {
        if (!propSet.has(name)) {
          const childPtr = instPtr + '/' + encodeToken(name);
          const childSchemaPtr = schemaPtr + '/additionalProperties';
          errors.push(...validateNode(inst[name], childPtr, addSchema, childSchemaPtr, schemaRoot));
        }
      }
    }

    if ('minProperties' in schemaNode) {
      const cnt = Object.keys(inst).length;
      if (cnt < (schemaNode.minProperties as number)) errors.push([instPtr, schemaPtr + '/minProperties']);
    }
    if ('maxProperties' in schemaNode) {
      const cnt = Object.keys(inst).length;
      if (cnt > (schemaNode.maxProperties as number)) errors.push([instPtr, schemaPtr + '/maxProperties']);
    }
  }

  // $ref
  if ('$ref' in schemaNode) {
    const ref = schemaNode['$ref'] as string;
    const refPtr = ref.startsWith('#') ? ref : '#' + ref;
    const refNode = getNodeByPointer(schemaRoot, refPtr);
    if (refNode !== undefined) {
      const refSchemaPtr = refPtr;
      errors.push(...validateNode(inst, instPtr, refNode, refSchemaPtr, schemaRoot));
    }
  }

  // allOf
  if ('allOf' in schemaNode && Array.isArray(schemaNode.allOf)) {
    schemaNode.allOf.forEach((sub, i) => {
      const childSchemaPtr = schemaPtr + '/allOf/' + i;
      errors.push(...validateNode(inst, instPtr, sub, childSchemaPtr, schemaRoot));
    });
  }

  // anyOf
  if ('anyOf' in schemaNode && Array.isArray(schemaNode.anyOf)) {
    const subs = schemaNode.anyOf as any[];
    let anyAccepts = false;
    for (const sub of subs) {
      const subErr = validateNode(inst, instPtr, sub, schemaPtr, schemaRoot);
      if (subErr.length === 0) { anyAccepts = true; break; }
    }
    if (!anyAccepts) errors.push([instPtr, schemaPtr + '/anyOf']);
  }

  // oneOf
  if ('oneOf' in schemaNode && Array.isArray(schemaNode.oneOf)) {
    const subs = schemaNode.oneOf as any[];
    let acceptCount = 0;
    for (const sub of subs) {
      const subErr = validateNode(inst, instPtr, sub, schemaPtr, schemaRoot);
      if (subErr.length === 0) acceptCount++;
    }
    if (acceptCount !== 1) errors.push([instPtr, schemaPtr + '/oneOf']);
  }

  // not
  if ('not' in schemaNode) {
    const subErr = validateNode(inst, instPtr, schemaNode.not, schemaPtr, schemaRoot);
    if (subErr.length === 0) errors.push([instPtr, schemaPtr + '/not']);
  }

  // if / then / else
  if ('if' in schemaNode) {
    const ifErr = validateNode(inst, instPtr, schemaNode.if, schemaPtr, schemaRoot);
    const accepts = ifErr.length === 0;
    if (accepts && 'then' in schemaNode) {
      errors.push(...validateNode(inst, instPtr, schemaNode.then, schemaPtr, schemaRoot));
    } else if (!accepts && 'else' in schemaNode) {
      errors.push(...validateNode(inst, instPtr, schemaNode.else, schemaPtr, schemaRoot));
    }
  }

  return errors;
}

function main() {
  const dir = process.argv[2];
  if (!dir) { console.error('missing dir'); process.exit(1); }
  const schemaPath = path.join(dir, 'schema.json');
  const instancesPath = path.join(dir, 'instances.json');
  const schemaRoot = JSON.parse(fs.readFileSync(schemaPath, 'utf8'));
  const instances: any[] = JSON.parse(fs.readFileSync(instancesPath, 'utf8'));

  let validCount = 0;
  let invalidCount = 0;

  for (let i = 0; i < instances.length; i++) {
    const inst = instances[i];
    const errs = validateNode(inst, '#', schemaRoot, '#', schemaRoot);
    const uniq = Array.from(new Set(errs.map(e => e[0] + '\u0000' + e[1]))).map(s => {
      const [a, b] = s.split('\u0000');
      return [a, b] as ErrorPair;
    });
    if (uniq.length === 0) {
      console.log(`${i}: valid`);
      validCount++;
    } else {
      uniq.sort((a, b) => {
        const c = cmpStrings(a[0], b[0]);
        if (c !== 0) return c;
