                }
                if(obj.containsKey("exclusiveMaximum")){
                    BigDecimal em=getNum(obj.get("exclusiveMaximum"));
                    if(val.compareTo(em)>=0) out.add(new Error(instPtr, schPtr+"/exclusiveMaximum"));
                }
            }
            // string
            if(inst.kind==Kind.STRING){
                int len=inst.strVal.codePointCount(0,inst.strVal.length());
                if(obj.containsKey("minLength")){
                    int ml=(int)obj.get("minLength").numVal.longValue();
                    if(len<ml) out.add(new Error(instPtr, schPtr+"/minLength"));
                }
                if(obj.containsKey("maxLength")){
                    int ml=(int)obj.get("maxLength").numVal.longValue();
                    if(len>ml) out.add(new Error(instPtr, schPtr+"/maxLength"));
                }
            }
            // array
            if(inst.kind==Kind.ARRAY){
                int sz=inst.arrVal.size();
                if(obj.containsKey("minItems")){
                    int mi=(int)obj.get("minItems").numVal.longValue();
                    if(sz<mi) out.add(new Error(instPtr, schPtr+"/minItems"));
                }
                if(obj.containsKey("maxItems")){
                    int ma=(int)obj.get("maxItems").numVal.longValue();
                    if(sz>ma) out.add(new Error(instPtr, schPtr+"/maxItems"));
                }
                if(obj.containsKey("uniqueItems")){
                    JsonValue ui=obj.get("uniqueItems");
                    if(ui.kind==Kind.BOOL && ui.boolVal){
                        boolean dup=false;
                        for(int i=0;i<sz && !dup;i++) for(int j=i+1;j<sz;j++) if(deepEquals(inst.arrVal.get(i), inst.arrVal.get(j))){ dup=true; break; }
                        if(dup) out.add(new Error(instPtr, schPtr+"/uniqueItems"));
                    }
                }
                // prefixItems
                if(obj.containsKey("prefixItems")){
                    JsonValue piv=obj.get("prefixItems");
                    if(piv.kind==Kind.ARRAY){
                        List<JsonValue> schemas=piv.arrVal;
                        int limit=Math.min(sz, schemas.size());
                        for(int i=0;i<limit;i++){
                            validate(inst.arrVal.get(i), schemas.get(i), instPtr+"/"+i, schPtr+"/prefixItems/"+i, out);
                        }
                    }
                }
                // items
                if(obj.containsKey("items")){
                    JsonValue itemsSch=obj.get("items");
                    int start=0;
                    if(obj.containsKey("prefixItems")){
                        JsonValue piv=obj.get("prefixItems");
                        if(piv.kind==Kind.ARRAY) start=piv.arrVal.size();
                    }
                    for(int i=start;i<sz;i++){
                        validate(inst.arrVal.get(i), itemsSch, instPtr+"/"+i, schPtr+"/items", out);
                    }
                }
            }
            // object
            if(inst.kind==Kind.OBJECT){
                Map<String,JsonValue> imap=inst.objVal;
                int pc=imap.size();
                if(obj.containsKey("minProperties")){
                    int mp=(int)obj.get("minProperties").numVal.longValue();
                    if(pc<mp) out.add(new Error(instPtr, schPtr+"/minProperties"));
                }
                if(obj.containsKey("maxProperties")){
                    int mp=(int)obj.get("maxProperties").numVal.longValue();
                    if(pc>mp) out.add(new Error(instPtr, schPtr+"/maxProperties"));
                }
                // required
                if(obj.containsKey("required")){
                    JsonValue rv=obj.get("required");
                    if(rv.kind==Kind.ARRAY){
                        List<JsonValue> req=rv.arrVal;
                        for(int i=0;i<req.size();i++){
                            String name=req.get(i).strVal;
                            if(!imap.containsKey(name)){
                                out.add(new Error(instPtr, schPtr+"/required/"+i));
                            }
                        }
                    }
                }
                // properties
                Map<String,JsonValue> props=null;
                if(obj.containsKey("properties")){
                    JsonValue pv=obj.get("properties");
                    if(pv.kind==Kind.OBJECT) props=pv.objVal;
                }
                if(props!=null){
                    for(String k:props.keySet()){
                        if(imap.containsKey(k)){
                            validate(imap.get(k), props.get(k), instPtr+"/"+encodeToken(k), schPtr+"/properties/"+encodeToken(k), out);
                        }
                    }
                }
                // additionalProperties
                if(obj.containsKey("additionalProperties")){
                    JsonValue apSch=obj.get("additionalProperties");
                    Set<String> propKeys = (props!=null)?props.keySet():Collections.emptySet();
                    for(String k:imap.keySet()){
                        if(!propKeys.contains(k)){
                            validate(imap.get(k), apSch, instPtr+"/"+encodeToken(k), schPtr+"/additionalProperties", out);
                        }
                    }
                }
            }
            // allOf
            if(obj.containsKey("allOf")){
                JsonValue av=obj.get("allOf");
                if(av.kind==Kind.ARRAY){
                    List<JsonValue> subs=av.arrVal;
                    for(int i=0;i<subs.size();i++){
                        validate(inst, subs.get(i), instPtr, schPtr+"/allOf/"+i, out);
                    }
                }
            }
            // anyOf
            if(obj.containsKey("anyOf")){
                JsonValue av=obj.get("anyOf");
                if(av.kind==Kind.ARRAY){
                    boolean anyAccept=true;
                    List<JsonValue> subs=av.arrVal;
                    boolean hasAccept=false;
                    for(JsonValue sub: subs){
                        Set<Error> tmp=new HashSet<>();
                        validate(inst, sub, instPtr, schPtr+"/anyOf/0", tmp); // pointer not used for acceptance
                        if(tmp.isEmpty()){ hasAccept=true; break; }
                    }
                    if(!hasAccept){
                        out.add(new Error(instPtr, schPtr+"/anyOf"));
                    }
                }
            }
            // oneOf
            if(obj.containsKey("oneOf")){
                JsonValue ov=obj.get("oneOf");
                if(ov.kind==Kind.ARRAY){
                    int acceptCount=0;
                    for(JsonValue sub: ov.arrVal){
                        Set<Error> tmp=new HashSet<>();
                        validate(inst, sub, instPtr, schPtr+"/oneOf/0", tmp);
                        if(tmp.isEmpty()) acceptCount++;
                    }
                    if(acceptCount!=1){
                        out.add(new Error(instPtr, schPtr+"/oneOf"));
                    }
                }
            }
            // not
            if(obj.containsKey("not")){
                JsonValue nv=obj.get("not");
                Set<Error> tmp=new HashSet<>();
                validate(inst, nv, instPtr, schPtr+"/not", tmp);
                if(tmp.isEmpty()){
                    out.add(new Error(instPtr, schPtr+"/not"));
                }
            }
            // if/then/else
            if(obj.containsKey("if")){
                JsonValue ifSch=obj.get("if");
                Set<Error> tmp=new HashSet<>();
                validate(inst, ifSch, instPtr, schPtr+"/if", tmp);
                boolean accepts=tmp.isEmpty();
                if(accepts && obj.containsKey("then")){
                    validate(inst, obj.get("then"), instPtr, schPtr+"/then", out);
                }else if(!accepts && obj.containsKey("else")){
                    validate(inst, obj.get("else"), instPtr, schPtr+"/else", out);
                }
            }
        }

        boolean typeMatches(JsonValue inst, JsonValue tv){
            Set<String> allowed=new HashSet<>();
            if(tv.kind==Kind.STRING) allowed.add(tv.strVal);
            else if(tv.kind==Kind.ARRAY){
                for(JsonValue v: tv.arrVal) if(v.kind==Kind.STRING) allowed.add(v.strVal);
            }
            for(String t: allowed){
                if(matchesType(inst, t)) return true;
            }
            return false;
        }
        boolean matchesType(JsonValue inst, String t){
            switch(t){
                case "null": return inst.kind==Kind.NULL;
                case "boolean": return inst.kind==Kind.BOOL;
                case "object": return inst.kind==Kind.OBJECT;
                case "array": return inst.kind==Kind.ARRAY;
                case "string": return inst.kind==Kind.STRING;
                case "number": return inst.kind==Kind.NUMBER;
                case "integer": return inst.kind==Kind.NUMBER && isIntegerNumber(inst);
            }
            return false;
        }
        BigDecimal getNum(JsonValue v){ return v.numVal; }
    }

    // ---------- Main ----------
    public static void main(String[] args) throws Exception {
        if(args.length==0){ System.err.println("need dir"); return; }
        File dir=new File(args[0]);
        JsonValue schemaRoot=parseFile(new File(dir,"schema.json"));
        JsonValue instancesRoot=parseFile(new File(dir,"instances.json"));
        if(instancesRoot.kind!=Kind.ARRAY) throw new RuntimeException("instances not array");
        List<JsonValue> instances=instancesRoot.arrVal;
        Validator validator=new Validator(schemaRoot);
        int valid=0, invalid=0;
        for(int i=0;i<instances.size();i++){
            Set<Error> errs=new HashSet<>();
            validator.validate(instances.get(i), schemaRoot, "#", "#", errs);
            if(errs.isEmpty()){
                System.out.println(i+": valid");
                valid++;
            }else{
                List<Error> list=new ArrayList<>(errs);
                Collections.sort(list);
                System.out.println(i+": invalid ("+list.size()+")");
                for(Error e:list){
                    System.out.println("  "+e.instPtr+" "+e.schPtr);
                }
                invalid++;
            }
        }
        System.out.println("valid="+valid+" invalid="+invalid);
    }
}

import java.io.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;

public class Main {

    // ---------- JSON model ----------
    enum Kind { NULL, BOOL, NUMBER, STRING, ARRAY, OBJECT }

    static class JsonValue {
        Kind kind;
        Boolean boolVal;
        BigDecimal numVal;
        String strVal;
        List<JsonValue> arrVal;
        Map<String, JsonValue> objVal;
        JsonValue(Kind k) { kind = k; }
        static JsonValue nul() { return new JsonValue(Kind.NULL); }
        static JsonValue bool(boolean b) { JsonValue v = new JsonValue(Kind.BOOL); v.boolVal = b; return v; }
        static JsonValue num(BigDecimal d) { JsonValue v = new JsonValue(Kind.NUMBER); v.numVal = d; return v; }
        static JsonValue str(String s) { JsonValue v = new JsonValue(Kind.STRING); v.strVal = s; return v; }
        static JsonValue arr(List<JsonValue> a) { JsonValue v = new JsonValue(Kind.ARRAY); v.arrVal = a; return v; }
        static JsonValue obj(Map<String, JsonValue> o) { JsonValue v = new JsonValue(Kind.OBJECT); v.objVal = o; return v; }
    }

    // ---------- Parser ----------
    static class Parser {
        String s; int p;
        Parser(String s){ this.s=s; p=0; }
        void skipWs(){ while(p<s.length() && Character.isWhitespace(s.charAt(p))) p++; }
        JsonValue parseValue(){
            skipWs();
            if(p>=s.length()) throw new RuntimeException("eof");
            char c=s.charAt(p);
            if(c=='{') return parseObj();
            if(c=='[') return parseArr();
            if(c=='"') return parseStr();
            if(s.startsWith("true",p)){p+=4; return JsonValue.bool(true);}
            if(s.startsWith("false",p)){p+=4; return JsonValue.bool(false);}
            if(s.startsWith("null",p)){p+=4; return JsonValue.nul();}
            if(c=='-'||Character.isDigit(c)) return parseNum();
            throw new RuntimeException("bad json");
        }
        JsonValue parseObj(){
            p++; skipWs();
            Map<String,JsonValue> map=new LinkedHashMap<>();
            if(p<s.length() && s.charAt(p)=='}'){p++; return JsonValue.obj(map);}
            while(true){
                JsonValue key=parseStr();
                skipWs(); if(p>=s.length()||s.charAt(p)!=':') throw new RuntimeException(":");
                p++; skipWs();
                JsonValue val=parseValue();
                map.put(key.strVal,val);
                skipWs();
                if(p>=s.length()) throw new RuntimeException("eof");
                char c=s.charAt(p);
                if(c=='}'){p++; break;}
                if(c!=',') throw new RuntimeException("comma");
                p++; skipWs();
            }
            return JsonValue.obj(map);
        }
        JsonValue parseArr(){
            p++; skipWs();
            List<JsonValue> list=new ArrayList<>();
            if(p<s.length() && s.charAt(p)==']'){p++; return JsonValue.arr(list);}
            while(true){
                list.add(parseValue());
                skipWs();
                if(p>=s.length()) throw new RuntimeException("eof");
                char c=s.charAt(p);
                if(c==']'){p++; break;}
                if(c!=',') throw new RuntimeException("comma");
                p++; skipWs();
            }
            return JsonValue.arr(list);
        }
        JsonValue parseStr(){
            p++; // opening "
            StringBuilder sb=new StringBuilder();
            while(true){
                if(p>=s.length()) throw new RuntimeException("unterminated");
                char c=s.charAt(p++);
                if(c=='"') break;
                if(c=='\\'){
                    if(p>=s.length()) throw new RuntimeException("bad escape");
                    char e=s.charAt(p++);
                    switch(e){
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if(p+4>s.length()) throw new RuntimeException("bad u");
                            int code=Integer.parseInt(s.substring(p,p+4),16);
                            p+=4;
                            sb.append((char)code);
                            break;
                        default: sb.append(e);
                    }
                }else sb.append(c);
            }
            return JsonValue.str(sb.toString());
        }
        JsonValue parseNum(){
            int start=p;
            if(s.charAt(p)=='-') p++;
            while(p<s.length() && Character.isDigit(s.charAt(p))) p++;
            if(p<s.length() && s.charAt(p)=='.'){p++; while(p<s.length() && Character.isDigit(s.charAt(p))) p++;}
            if(p<s.length() && (s.charAt(p)=='e'||s.charAt(p)=='E')){p++; if(p<s.length() && (s.charAt(p)=='+'||s.charAt(p)=='-')) p++; while(p<s.length() && Character.isDigit(s.charAt(p))) p++;}
            String numStr=s.substring(start,p);
            return JsonValue.num(new BigDecimal(numStr));
        }
    }

    static JsonValue parseFile(File f) throws IOException {
        String txt=new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
        return new Parser(txt).parseValue();
    }

    // ---------- Helpers ----------
    static String encodeToken(String t){ return t.replace("~","~0").replace("/","~1"); }
    static String decodeToken(String t){ return t.replace("~1","/").replace("~0","~"); }

    static JsonValue getNodeByPointer(JsonValue root, String pointer){
        if(pointer.equals("#")||pointer.isEmpty()) return root;
        String p=pointer.startsWith("#")?pointer.substring(1):pointer;
        if(p.startsWith("/")) p=p.substring(1);
        if(p.isEmpty()) return root;
        String[] parts=p.split("/",-1);
        JsonValue cur=root;
        for(String tok:parts){
            if(tok.isEmpty()) continue;
            String dec=decodeToken(tok);
            if(cur.kind==Kind.OBJECT){
                cur=cur.objVal.get(dec);
            }else if(cur.kind==Kind.ARRAY){
                int idx=Integer.parseInt(dec);
                cur=cur.arrVal.get(idx);
            }else return null;
            if(cur==null) return null;
        }
        return cur;
    }

    static boolean deepEquals(JsonValue a, JsonValue b){
        if(a.kind!=b.kind) return false;
        switch(a.kind){
            case NULL: return true;
            case BOOL: return a.boolVal.equals(b.boolVal);
            case NUMBER: return a.numVal.compareTo(b.numVal)==0;
            case STRING: return a.strVal.equals(b.strVal);
            case ARRAY:
                if(a.arrVal.size()!=b.arrVal.size()) return false;
                for(int i=0;i<a.arrVal.size();i++) if(!deepEquals(a.arrVal.get(i), b.arrVal.get(i))) return false;
                return true;
            case OBJECT:
                if(a.objVal.size()!=b.objVal.size()) return false;
                for(String k:a.objVal.keySet()){
                    if(!b.objVal.containsKey(k)) return false;
                    if(!deepEquals(a.objVal.get(k), b.objVal.get(k))) return false;
                }
                return true;
        }
        return false;
    }

    static boolean isIntegerNumber(JsonValue v){
        if(v.kind!=Kind.NUMBER) return false;
        return isIntegerValue(v.numVal);
    }
    static boolean isIntegerValue(BigDecimal d){
        return d.stripTrailingZeros().scale() <= 0;
    }

    static class Error implements Comparable<Error>{
        String instPtr, schPtr;
        Error(String i,String s){instPtr=i; schPtr=s;}
        public int compareTo(Error o){
            int c=instPtr.compareTo(o.instPtr);
            if(c!=0) return c;
            return schPtr.compareTo(o.schPtr);
        }
        public boolean equals(Object o){ if(!(o instanceof Error)) return false; Error e=(Error)o; return instPtr.equals(e.instPtr)&&schPtr.equals(e.schPtr); }
        public int hashCode(){ return Objects.hash(instPtr,schPtr); }
    }

    // ---------- Validator ----------
    static class Validator {
        JsonValue schemaRoot;
        Validator(JsonValue root){ schemaRoot=root; }

        void validate(JsonValue inst, JsonValue sch, String instPtr, String schPtr, Set<Error> out){
            if(sch.kind==Kind.BOOL){
                if(!sch.boolVal) out.add(new Error(instPtr, schPtr));
                return;
            }
            if(sch.kind!=Kind.OBJECT) return;
            Map<String,JsonValue> obj=sch.objVal;

            if(obj.containsKey("$ref")){
                JsonValue refVal=obj.get("$ref");
                if(refVal.kind==Kind.STRING){
                    JsonValue target=getNodeByPointer(schemaRoot, refVal.strVal);
                    if(target!=null) validate(inst, target, instPtr, refVal.strVal, out);
                }
            }

            if(obj.containsKey("type")){
                if(!typeMatches(inst, obj.get("type"))) out.add(new Error(instPtr, schPtr+"/type"));
            }
            if(obj.containsKey("enum")){
                JsonValue ev=obj.get("enum");
                if(ev.kind==Kind.ARRAY){
                    boolean ok=false;
                    for(JsonValue e: ev.arrVal) if(deepEquals(inst,e)){ ok=true; break; }
                    if(!ok) out.add(new Error(instPtr, schPtr+"/enum"));
                }
            }
            if(obj.containsKey("const")){
                if(!deepEquals(inst, obj.get("const"))) out.add(new Error(instPtr, schPtr+"/const"));
            }
            if(inst.kind==Kind.NUMBER){
                BigDecimal val=inst.numVal;
                if(obj.containsKey("minimum")){
                    if(val.compareTo(obj.get("minimum").numVal)<0) out.add(new Error(instPtr, schPtr+"/minimum"));
                }
                if(obj.containsKey("maximum")){
                    if(val.compareTo(obj.get("maximum").numVal)>0) out.add(new Error(instPtr, schPtr+"/maximum"));
                }
                if(obj.containsKey("exclusiveMinimum")){
                    if(val.compareTo(obj.get("exclusiveMinimum").numVal)<=0) out.add(new Error(instPtr, schPtr+"/exclusiveMinimum"));
                }
                if(obj.containsKey("exclusiveMaximum")){
                    if(val.compareTo(obj.get("exclusiveMaximum").numVal)>=0) out.add(new Error(instPtr, schPtr+"/exclusiveMaximum"));
                }
            }
            if(inst.kind==Kind.STRING){
                int len=inst.strVal.codePointCount(0,inst.strVal.length());
                if(obj.containsKey("minLength")){
                    int ml=obj.get("minLength").numVal.intValue();
                    if(len<ml) out.add(new Error(instPtr, schPtr+"/minLength"));
                }
                if(obj.containsKey("maxLength")){
                    int ml=obj.get("maxLength").numVal.intValue();
                    if(len>ml) out.add(new Error(instPtr, schPtr+"/maxLength"));
                }
            }
            if(inst.kind==Kind.ARRAY){
                int sz=inst.arrVal.size();
                if(obj.containsKey("minItems")){
                    int mi=obj.get("minItems").numVal.intValue();
                    if(sz<mi) out.add(new Error(instPtr, schPtr+"/minItems"));
                }
                if(obj.containsKey("maxItems")){
                    int ma=obj.get("maxItems").numVal.intValue();
                    if(sz>ma) out.add(new Error(instPtr, schPtr+"/maxItems"));
                }
                if(obj.containsKey("uniqueItems")){
                    JsonValue ui=obj.get("uniqueItems");
                    if(ui.kind==Kind.BOOL && ui.boolVal){
                        boolean dup=false;
                        for(int i=0;i<sz && !dup;i++) for(int j=i+1;j<sz;j++) if(deepEquals(inst.arrVal.get(i), inst.arrVal.get(j))){ dup=true; break; }
                        if(dup) out.add(new Error(instPtr, schPtr+"/uniqueItems"));
                    }
                }
                if(obj.containsKey("prefixItems")){
                    JsonValue piv=obj.get("prefixItems");
                    if(piv.kind==Kind.ARRAY){
                        List<JsonValue> schemas=piv.arrVal;
                        int limit=Math.min(sz, schemas.size());
                        for(int i=0;i<limit;i++){
                            validate(inst.arrVal.get(i), schemas.get(i), instPtr+"/"+i, schPtr+"/prefixItems/"+i, out);
                        }
                    }
                }
                if(obj.containsKey("items")){
                    JsonValue itemsSch=obj.get("items");
                    int start=0;
                    if(obj.containsKey("prefixItems")){
                        JsonValue piv=obj.get("prefixItems");
                        if(piv.kind==Kind.ARRAY) start=piv.arrVal.size();
                    }
                    for(int i=start;i<sz;i++){
                        validate(inst.arrVal.get(i), itemsSch, instPtr+"/"+i, schPtr+"/items", out);
                    }
                }
            }
            if(inst.kind==Kind.OBJECT){
                Map<String,JsonValue> imap=inst.objVal;
                int pc=imap.size();
                if(obj.containsKey("minProperties")){
                    int mp=obj.get("minProperties").numVal.intValue();
                    if(pc<mp) out.add(new Error(instPtr, schPtr+"/minProperties"));
                }
                if(obj.containsKey("maxProperties")){
                    int mp=obj.get("maxProperties").numVal.intValue();
                    if(pc>mp) out.add(new Error(instPtr, schPtr+"/maxProperties"));
                }
                if(obj.containsKey("required")){
                    JsonValue rv=obj.get("required");
                    if(rv.kind==Kind.ARRAY){
                        List<JsonValue> req=rv.arrVal;
                        for(int i=0;i<req.size();i++){
                            String name=req.get(i).strVal;
                            if(!imap.containsKey(name)) out.add(new Error(instPtr, schPtr+"/required/"+i));
                        }
                    }
                }
                Map<String,JsonValue> props=null;
                if(obj.containsKey("properties")){
                    JsonValue pv=obj.get("properties");
                    if(pv.kind==Kind.OBJECT) props=pv.objVal;
                }
                if(props!=null){
                    for(String k:props.keySet()){
                        if(imap.containsKey(k)){
                            validate(imap.get(k), props.get(k), instPtr+"/"+encodeToken(k), schPtr+"/properties/"+encodeToken(k), out);
                        }
                    }
                }
                if(obj.containsKey("additionalProperties")){
                    JsonValue apSch=obj.get("additionalProperties");
                    Set<String> propKeys = (props!=null)?props.keySet():Collections.emptySet();
                    for(String k:imap.keySet()){
                        if(!propKeys.contains(k)){
                            validate(imap.get(k), apSch, instPtr+"/"+encodeToken(k), schPtr+"/additionalProperties", out);
                        }
                    }
                }
            }
            if(obj.containsKey("allOf")){
                JsonValue av=obj.get("allOf");
                if(av.kind==Kind.ARRAY){
                    List<JsonValue> subs=av.arrVal;
                    for(int i=0;i<subs.size();i++) validate(inst, subs.get(i), instPtr, schPtr+"/allOf/"+i, out);
                }
            }
            if(obj.containsKey("anyOf")){
                JsonValue av=obj.get("anyOf");
                if(av.kind==Kind.ARRAY){
                    boolean hasAccept=false;
                    for(JsonValue sub: av.arrVal){
                        Set<Error> tmp=new HashSet<>();
                        validate(inst, sub, instPtr, schPtr+"/anyOf/0", tmp);
                        if(tmp.isEmpty()){ hasAccept=true; break; }
                    }
                    if(!hasAccept) out.add(new Error(instPtr, schPtr+"/anyOf"));
                }
            }
            if(obj.containsKey("oneOf")){
                JsonValue ov=obj.get("oneOf");
                if(ov.kind==Kind.ARRAY){
                    int acceptCount=0;
                    for(JsonValue sub: ov.arrVal){
                        Set<Error> tmp=new HashSet<>();
                        validate(inst, sub, instPtr, schPtr+"/oneOf/0", tmp);
                        if(tmp.isEmpty()) acceptCount++;
                    }
                    if(acceptCount!=1) out.add(new Error(instPtr, schPtr+"/oneOf"));
                }
            }
            if(obj.containsKey("not")){
                JsonValue nv=obj.get("not");
                Set<Error> tmp=new HashSet<>();
                validate(inst, nv, instPtr, schPtr+"/not", tmp);
                if(tmp.isEmpty()) out.add(new Error(instPtr, schPtr+"/not"));
            }
            if(obj.containsKey("if")){
                JsonValue ifSch=obj.get("if");
