function isValidIdToken(token: string): boolean {
  const t = token.trim();
  if (t.startsWith('"') && t.endsWith('"')) return true;
  return /^-?(0|[1-9]\d*)$/.test(t);
}

function getIdToken(line: string): string | null {
  const m = line.match(/"id"\s*:\s*([^,\}\]]+)/);
  if (!m) return null;
  return m[1];
}

function compareCodePoints(a: string, b: string): number {
  const aArr = [...a];
  const bArr = [...b];
  const len = Math.min(aArr.length, bArr.length);
  for (let i = 0; i < len; i++) {
    const ca = aArr[i].codePointAt(0)!;
    const cb = bArr[i].codePointAt(0)!;
    if (ca !== cb) return ca - cb;
  }
  return aArr.length - bArr.length;
}

