func jsonOutput(_ obj: Any) -> String {
    if let data = try? JSONSerialization.data(withJSONObject: obj, options: []) {
        return String(data: data, encoding: .utf8) ?? ""
    }
    return ""
}

func isValidId(_ any: Any) -> Bool {
    if any is String { return true }
    if let num = any as? NSNumber {
        let d = num.doubleValue
        return d == floor(d)
    }
    return false
}

func idIsValidNumber(_ any: Any) -> Bool {
    if let num = any as? NSNumber { return num.doubleValue == floor(num.doubleValue) }
    return false
}

