import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static class JsonNode {
        enum Type {OBJECT, ARRAY, STRING, NUMBER, BOOLEAN, NULL}
        Type type;
        Map<String, JsonNode> obj;
        List<JsonNode> arr;
        String str;
        String numRaw;
        double numVal;
        boolean bool;
        JsonNode(Type t){type=t;}
    }

    static class Parser {
        final String s;
        int i=0;
        Parser(String s){this.s=s;}
        void skipWs(){while(i<s.length() && Character.isWhitespace(s.charAt(i))) i++;}
        JsonNode parseValue(){
            skipWs();
            if(i>=s.length()) return null;
            char c=s.charAt(i);
            if(c=='{') return parseObject();
            if(c=='[') return parseArray();
            if(c=='"') return parseString();
            if(c=='t'||c=='f'||c=='n') return parseLiteral();
            if(c=='-'||Character.isDigit(c)) return parseNumber();
            return null;
        }
        JsonNode parseObject(){
            i++; // {
            JsonNode node=new JsonNode(JsonNode.Type.OBJECT);
            node.obj=new LinkedHashMap<>();
            skipWs();
            if(i<s.length() && s.charAt(i)=='}'){i++;return node;}
            while(true){
                skipWs();
                if(i>=s.length()||s.charAt(i)!='"') return null;
                JsonNode keyNode=parseString();
                String key=keyNode.str;
                skipWs();
                if(i>=s.length()||s.charAt(i)!=':') return null;
                i++;
                JsonNode val=parseValue();
                if(val==null) return null;
                node.obj.put(key,val);
                skipWs();
                if(i>=s.length()) return null;
                char c=s.charAt(i);
                if(c=='}'){i++;break;}
                if(c!=',') return null;
                i++;
            }
            return node;
        }
        JsonNode parseArray(){
            i++; // [
            JsonNode node=new JsonNode(JsonNode.Type.ARRAY);
            node.arr=new ArrayList<>();
            skipWs();
            if(i<s.length() && s.charAt(i)==']'){i++;return node;}
            while(true){
                JsonNode v=parseValue();
                if(v==null) return null;
                node.arr.add(v);
                skipWs();
                if(i>=s.length()) return null;
                char c=s.charAt(i);
                if(c==']'){i++;break;}
                if(c!=',') return null;
                i++;
            }
            return node;
        }
        JsonNode parseString(){
            i++; // "
            StringBuilder sb=new StringBuilder();
            while(i<s.length()){
                char c=s.charAt(i++);
                if(c=='"') break;
                if(c=='\\'){
                    if(i>=s.length()) return null;
                    char e=s.charAt(i++);
                    switch(e){
                        case '"': sb.append('"');break;
                        case '\\': sb.append('\\');break;
                        case '/': sb.append('/');break;
                        case 'b': sb.append('\b');break;
                        case 'f': sb.append('\f');break;
                        case 'n': sb.append('\n');break;
                        case 'r': sb.append('\r');break;
                        case 't': sb.append('\t');break;
                        case 'u':
                            if(i+4>s.length()) return null;
                            String hex=s.substring(i,i+4);
                            i+=4;
                            try{
                                int code=Integer.parseInt(hex,16);
                                sb.append((char)code);
                            }catch(Exception ex){return null;}
                            break;
                        default: return null;
                    }
                }else{
                    sb.append(c);
                }
            }
            JsonNode n=new JsonNode(JsonNode.Type.STRING);
            n.str=sb.toString();
            return n;
        }
        JsonNode parseLiteral(){
            if(s.startsWith("true",i)){i+=4;JsonNode n=new JsonNode(JsonNode.Type.BOOLEAN);n.bool=true;return n;}
            if(s.startsWith("false",i)){i+=5;JsonNode n=new JsonNode(JsonNode.Type.BOOLEAN);n.bool=false;return n;}
            if(s.startsWith("null",i)){i+=4;return new JsonNode(JsonNode.Type.NULL);}
            return null;
        }
        JsonNode parseNumber(){
            int start=i;
            if(s.charAt(i)=='-') i++;
            if(i>=s.length()||!Character.isDigit(s.charAt(i))) return null;
            while(i<s.length() && Character.isDigit(s.charAt(i))) i++;
            if(i<s.length() && s.charAt(i)=='.'){i++; if(i>=s.length()||!Character.isDigit(s.charAt(i))) return null; while(i<s.length() && Character.isDigit(s.charAt(i))) i++;}
            if(i<s.length() && (s.charAt(i)=='e'||s.charAt(i)=='E')){i++; if(i<s.length() && (s.charAt(i)=='+'||s.charAt(i)=='-')) i++; if(i>=s.length()||!Character.isDigit(s.charAt(i))) return null; while(i<s.length() && Character.isDigit(s.charAt(i))) i++;}
            String raw=s.substring(start,i);
            JsonNode n=new JsonNode(JsonNode.Type.NUMBER);
            n.numRaw=raw;
            try{n.numVal=Double.parseDouble(raw);}catch(Exception e){return null;}
            return n;
        }
    }

    static boolean isValidId(JsonNode n){
        if(n==null) return false;
        if(n.type==JsonNode.Type.STRING) return true;
        if(n.type==JsonNode.Type.NUMBER){
            String r=n.numRaw;
            return r.matches("-?\\d+");
        }
        return false;
    }
    static String idToJson(JsonNode n){
        if(n==null) return "null";
        if(n.type==JsonNode.Type.STRING) return jsonString(n.str);
        if(n.type==JsonNode.Type.NUMBER) return n.numRaw;
        return "null";
    }

    static String jsonString(String s){
        StringBuilder sb=new StringBuilder();
        sb.append('"');
        for(char c:s.toCharArray()){
            switch(c){
                case '"': sb.append("\\\"");break;
                case '\\': sb.append("\\\\");break;
                case '\b': sb.append("\\b");break;
                case '\f': sb.append("\\f");break;
                case '\n': sb.append("\\n");break;
                case '\r': sb.append("\\r");break;
                case '\t': sb.append("\\t");break;
                default:
                    if(c<0x20){sb.append(String.format("\\u%04x",(int)c));}
                    else sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    static String mapToJson(Map<String,Object> m){
        StringBuilder sb=new StringBuilder("{");
        boolean first=true;
        for(Map.Entry<String,Object> e:m.entrySet()){
            if(!first) sb.append(',');
            first=false;
            sb.append(jsonString(e.getKey()));
            sb.append(':');
            sb.append(valueToJson(e.getValue()));
        }
        sb.append('}');
        return sb.toString();
    }
    static String valueToJson(Object v){
        if(v==null) return "null";
        if(v instanceof String) return jsonString((String)v);
        if(v instanceof Number) return v.toString();
        if(v instanceof Boolean) return v.toString();
        if(v instanceof Map) return mapToJson((Map<String,Object>)v);
        if(v instanceof List){
            StringBuilder sb=new StringBuilder("[");
            List<?> l=(List<?>)v;
            for(int i=0;i<l.size();i++){
                if(i>0) sb.append(',');
                sb.append(valueToJson(l.get(i)));
            }
            sb.append(']');
            return sb.toString();
        }
        return "null";
    }

    static boolean isObject(JsonNode n){return n!=null && n.type==JsonNode.Type.OBJECT;}
    static JsonNode getObj(JsonNode n,String k){return n.obj.get(k);}
    static boolean hasKey(JsonNode n,String k){return n.obj.containsKey(k);}

    static boolean initialized=false;
    static Map<String,String> kv=new TreeMap<>();

    public static void main(String[] args) throws IOException{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8));
        String line;
        List<String> out=new ArrayList<>();
        while((line=br.readLine())!=null){
            String trimmed=line.trim();
            if(trimmed.isEmpty()) continue;
            // remove trailing CR
            if(line.endsWith("\r")) line=line.substring(0,line.length()-1);
            String raw=line;
            Parser p=new Parser(raw);
            JsonNode root=p.parseValue();
            p.skipWs();
            if(root==null || p.i!=raw.length()){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",null,"error",Map.of("code",-32700,"message","Parse error"))));
                continue;
            }
            if(root.type!=JsonNode.Type.OBJECT){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",null,"error",Map.of("code",-32600,"message","Invalid Request"))));
                continue;
            }
            // response from client?
            if(!hasKey(root,"method") && (hasKey(root,"result")||hasKey(root,"error"))){
                continue;
            }
            JsonNode jsonrpcNode=getObj(root,"jsonrpc");
            String jsonrpc = (jsonrpcNode!=null && jsonrpcNode.type==JsonNode.Type.STRING)? jsonrpcNode.str:null;
            JsonNode methodNode=getObj(root,"method");
            String method = (methodNode!=null && methodNode.type==JsonNode.Type.STRING)? methodNode.str:null;
            JsonNode idNode=getObj(root,"id");
            boolean idValid=isValidId(idNode);
            boolean methodMissing = methodNode==null || methodNode.type!=JsonNode.Type.STRING;
            boolean jsonrpcBad = !"2.0".equals(jsonrpc);
            if(jsonrpcBad || methodMissing || !idValid){
                Object outId = idValid? idNode : null;
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",outId,"error",Map.of("code",-32600,"message","Invalid Request"))));
                continue;
            }
            // notification
            if(idNode==null){
                continue;
            }
            // valid request
            JsonNode paramsNode=getObj(root,"params");
            boolean paramsIsObject = paramsNode==null || paramsNode.type==JsonNode.Type.OBJECT;
            if(!paramsIsObject){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                continue;
            }
            if(!initialized && !method.equals("initialize") && !method.equals("ping")){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32002,"message","Server not initialized"))));
                continue;
            }
            switch(method){
                case "initialize": {
                    if(initialized){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32600,"message","Already initialized"))));
                        break;
                    }
                    if(paramsNode==null || !hasKey(paramsNode,"protocolVersion")){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    JsonNode pv=getObj(paramsNode,"protocolVersion");
                    if(pv==null || pv.type!=JsonNode.Type.STRING){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    String ver=pv.str;
                    String chosen;
                    if(ver.equals("2025-06-18")||ver.equals("2025-03-26")||ver.equals("2024-11-05")) chosen=ver;
                    else chosen="2025-06-18";
                    initialized=true;
                    Map<String,Object> caps=new LinkedHashMap<>();
                    Map<String,Object> toolsCap=new LinkedHashMap<>();
                    toolsCap.put("listChanged",false);
                    caps.put("tools",toolsCap);
                    Map<String,Object> serverInfo=new LinkedHashMap<>();
                    serverInfo.put("name","cb2-kv");
                    serverInfo.put("title","CB2 key-value server");
                    serverInfo.put("version","1.4.2");
                    Map<String,Object> res=new LinkedHashMap<>();
                    res.put("protocolVersion",chosen);
                    res.put("capabilities",caps);
                    res.put("serverInfo",serverInfo);
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",res)));
                    break;
                }
                case "ping": {
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",new LinkedHashMap<>())));
                    break;
                }
                case "tools/list": {
                    List<Map<String,Object>> tools=new ArrayList<>();
                    // kv_set
                    Map<String,Object> t1=new LinkedHashMap<>();
                    t1.put("name","kv_set"); t1.put("title","Set a value"); t1.put("description","Store a string value under a key, replacing any previous value.");
                    Map<String,Object> is1=new LinkedHashMap<>();
                    Map<String,Object> props1=new LinkedHashMap<>();
                    Map<String,Object> pkey=new LinkedHashMap<>(); pkey.put("type","string"); pkey.put("minLength",1);
                    props1.put("key",pkey);
                    Map<String,Object> pval=new LinkedHashMap<>(); pval.put("type","string");
                    props1.put("value",pval);
                    is1.put("type","object"); is1.put("properties",props1); is1.put("required",List.of("key","value")); is1.put("additionalProperties",false);
                    t1.put("inputSchema",is1);
                    tools.add(t1);
                    // kv_get
                    Map<String,Object> t2=new LinkedHashMap<>();
                    t2.put("name","kv_get"); t2.put("title","Get a value"); t2.put("description","Return the value stored under a key.");
                    Map<String,Object> is2=new LinkedHashMap<>();
                    Map<String,Object> props2=new LinkedHashMap<>();
                    Map<String,Object> pkey2=new LinkedHashMap<>(); pkey2.put("type","string"); pkey2.put("minLength",1);
                    props2.put("key",pkey2);
                    is2.put("type","object"); is2.put("properties",props2); is2.put("required",List.of("key")); is2.put("additionalProperties",false);
                    t2.put("inputSchema",is2);
                    tools.add(t2);
                    // kv_list
                    Map<String,Object> t3=new LinkedHashMap<>();
                    t3.put("name","kv_list"); t3.put("title","List keys"); t3.put("description","List the stored keys that start with a prefix, sorted by Unicode code point.");
                    Map<String,Object> is3=new LinkedHashMap<>();
                    Map<String,Object> props3=new LinkedHashMap<>();
                    Map<String,Object> ppref=new LinkedHashMap<>(); ppref.put("type","string");
                    props3.put("prefix",ppref);
                    is3.put("type","object"); is3.put("properties",props3); is3.put("additionalProperties",false);
                    t3.put("inputSchema",is3);
                    Map<String,Object> os3=new LinkedHashMap<>();
                    Map<String,Object> osp3=new LinkedHashMap<>();
                    Map<String,Object> keysProp=new LinkedHashMap<>(); Map<String,Object> ki=new LinkedHashMap<>(); ki.put("type","string"); keysProp.put("type","array"); keysProp.put("items",ki);
                    osp3.put("keys",keysProp);
                    Map<String,Object> cntProp=new LinkedHashMap<>(); cntProp.put("type","integer");
                    osp3.put("count",cntProp);
                    os3.put("type","object"); os3.put("properties",osp3); os3.put("required",List.of("keys","count"));
                    t3.put("outputSchema",os3);
                    tools.add(t3);
                    // sum
                    Map<String,Object> t4=new LinkedHashMap<>();
                    t4.put("name","sum"); t4.put("title","Sum integers"); t4.put("description","Add up a non-empty list of integers.");
                    Map<String,Object> is4=new LinkedHashMap<>();
                    Map<String,Object> props4=new LinkedHashMap<>();
                    Map<String,Object> numsProp=new LinkedHashMap<>(); Map<String,Object> ni=new LinkedHashMap<>(); ni.put("type","integer"); numsProp.put("type","array"); numsProp.put("items",ni); numsProp.put("minItems",1);
                    props4.put("numbers",numsProp);
                    is4.put("type","object"); is4.put("properties",props4); is4.put("required",List.of("numbers")); is4.put("additionalProperties",false);
                    t4.put("inputSchema",is4);
                    Map<String,Object> os4=new LinkedHashMap<>();
                    Map<String,Object> osp4=new LinkedHashMap<>();
                    Map<String,Object> sumProp=new LinkedHashMap<>(); sumProp.put("type","integer"); osp4.put("sum",sumProp);
                    Map<String,Object> cnt4=new LinkedHashMap<>(); cnt4.put("type","integer"); osp4.put("count",cnt4);
                    os4.put("type","object"); os4.put("properties",osp4); os4.put("required",List.of("sum","count"));
                    t4.put("outputSchema",os4);
                    Map<String,Object> ann4=new LinkedHashMap<>(); ann4.put("readOnlyHint",true); ann4.put("idempotentHint",true);
                    t4.put("annotations",ann4);
                    tools.add(t4);
                    // text_stats
                    Map<String,Object> t5=new LinkedHashMap<>();
                    t5.put("name","text_stats"); t5.put("title","Text statistics"); t5.put("description","Count the words, Unicode code points and UTF-8 bytes of a text.");
                    Map<String,Object> is5=new LinkedHashMap<>();
                    Map<String,Object> props5=new LinkedHashMap<>();
                    Map<String,Object> txtProp=new LinkedHashMap<>(); txtProp.put("type","string");
                    props5.put("text",txtProp);
                    is5.put("type","object"); is5.put("properties",props5); is5.put("required",List.of("text")); is5.put("additionalProperties",false);
                    t5.put("inputSchema",is5);
                    Map<String,Object> os5=new LinkedHashMap<>();
                    Map<String,Object> osp5=new LinkedHashMap<>();
                    Map<String,Object> wProp=new LinkedHashMap<>(); wProp.put("type","integer"); osp5.put("words",wProp);
                    Map<String,Object> cProp=new LinkedHashMap<>(); cProp.put("type","integer"); osp5.put("codepoints",cProp);
                    Map<String,Object> bProp=new LinkedHashMap<>(); bProp.put("type","integer"); osp5.put("utf8_bytes",bProp);
                    os5.put("type","object"); os5.put("properties",osp5); os5.put("required",List.of("words","codepoints","utf8_bytes"));
                    t5.put("outputSchema",os5);
                    Map<String,Object> ann5=new LinkedHashMap<>(); ann5.put("readOnlyHint",true);
                    t5.put("annotations",ann5);
                    tools.add(t5);
                    Map<String,Object> resList=new LinkedHashMap<>();
                    resList.put("tools",tools);
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",resList)));
                    break;
                }
                case "tools/call": {
                    if(paramsNode==null || !hasKey(paramsNode,"name")){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    JsonNode nameNode=getObj(paramsNode,"name");
                    if(nameNode==null || nameNode.type!=JsonNode.Type.STRING){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    String tname=nameNode.str;
                    if(!List.of("kv_set","kv_get","kv_list","sum","text_stats").contains(tname)){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Unknown tool: "+tname))));
                        break;
                    }
                    JsonNode argsNode=getObj(paramsNode,"arguments");
                    // validation
                    String failMsg=null;
                    Map<String,Object> argMap=null;
                    if(argsNode!=null && argsNode.type!=JsonNode.Type.OBJECT){
                        failMsg="arguments must be an object";
                    }else{
                        argMap = argsNode==null? new LinkedHashMap<>() : argsNode.obj;
                        // unknown args
                        Set<String> allowed = Set.of();
                        switch(tname){
                            case "kv_set": allowed = Set.of("key","value"); break;
                            case "kv_get": allowed = Set.of("key"); break;
                            case "kv_list": allowed = Set.of("prefix"); break;
                            case "sum": allowed = Set.of("numbers"); break;
                            case "text_stats": allowed = Set.of("text"); break;
                        }
                        List<String> unknown = new ArrayList<>();
                        for(String k: argMap.keySet()){
                            if(!allowed.contains(k)) unknown.add(k);
                        }
                        if(!unknown.isEmpty()){
                            Collections.sort(unknown);
                            failMsg="unknown argument: "+unknown.get(0);
                        }else{
                            // order check
                            List<String> order;
                            switch(tname){
                                case "kv_set": order=List.of("key","value"); break;
                                case "kv_get": order=List.of("key"); break;
                                case "kv_list": order=List.of("prefix"); break;
                                case "sum": order=List.of("numbers"); break;
                                case "text_stats": order=List.of("text"); break;
                                default: order=List.of();
                            }
                            for(String prop: order){
                                if(argMap.containsKey(prop)){
                                    JsonNode v=argMap.get(prop);
                                    if(tname.equals("kv_set") && prop.equals("key")){
                                        if(v.type!=JsonNode.Type.STRING) failMsg="argument key must be a string";
                                        else if(v.str.length()<1) failMsg="argument key must not be empty";
                                    }else if(tname.equals("kv_set") && prop.equals("value")){
                                        if(v.type!=JsonNode.Type.STRING) failMsg="argument value must be a string";
                                    }else if(tname.equals("kv_get") && prop.equals("key")){
                                        if(v.type!=JsonNode.Type.STRING) failMsg="argument key must be a string";
                                        else if(v.str.length()<1) failMsg="argument key must not be empty";
                                    }else if(tname.equals("kv_list") && prop.equals("prefix")){
                                        if(v.type!=JsonNode.Type.STRING) failMsg="argument prefix must be a string";
                                    }else if(tname.equals("sum") && prop.equals("numbers")){
                                        if(v.type!=JsonNode.Type.ARRAY) failMsg="argument numbers must be an array of integers";
                                        else{
                                            boolean ok=true;
                                            for(JsonNode e:v.arr){
                                                if(e.type!=JsonNode.Type.NUMBER || !e.numRaw.matches("-?\\d+")){ok=false;break;}
                                            }
                                            if(!ok) failMsg="argument numbers must be an array of integers";
                                            else if(v.arr.size()<1) failMsg="argument numbers must not be empty";
                                        }
                                    }else if(tname.equals("text_stats") && prop.equals("text")){
                                        if(v.type!=JsonNode.Type.STRING) failMsg="argument text must be a string";
                                    }
                                }else{
                                    // missing required?
                                    boolean required=false;
                                    if(tname.equals("kv_set")) required=true;
                                    if(tname.equals("kv_get")) required=true;
                                    if(tname.equals("sum")) required=true;
                                    if(tname.equals("text_stats")) required=true;
                                    if(required){
                                        failMsg="missing required argument: "+prop;
                                    }
                                }
                                if(failMsg!=null) break;
                            }
                        }
                    }
                    if(failMsg!=null){
                        Map<String,Object> content=new LinkedHashMap<>();
                        content.put("type","text");
                        content.put("text",failMsg);
                        Map<String,Object> resTool=new LinkedHashMap<>();
                        resTool.put("content",List.of(content));
                        resTool.put("isError",true);
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",resTool)));
                        break;
                    }
                    // execute
                    Map<String,Object> toolResult=new LinkedHashMap<>();
                    toolResult.put("isError",false);
                    List<Map<String,Object>> contentList=new ArrayList<>();
                    Map<String,Object> contentMap=new LinkedHashMap<>();
                    contentMap.put("type","text");
                    String textOut="";
                    Map<String,Object> structured=null;
                    switch(tname){
                        case "kv_set": {
                            String key = argMap.getOrDefault("key", new JsonNode(JsonNode.Type.STRING)).str;
                            String val = argMap.getOrDefault("value", new JsonNode(JsonNode.Type.STRING)).str;
                            boolean existed = kv.containsKey(key);
                            kv.put(key,val);
                            textOut = (existed?"updated ":"created ")+key;
                            break;
                        }
                        case "kv_get": {
                            String key = argMap.get("key").str;
                            if(!kv.containsKey(key)){
                                textOut="key not found: "+key;
                                toolResult.put("isError",true);
                            }else{
                                textOut=kv.get(key);
                            }
                            break;
                        }
                        case "kv_list": {
                            String prefix = "";
                            if(argMap.containsKey("prefix")){
                                prefix = argMap.get("prefix").str;
                            }
                            List<String> keys=new ArrayList<>();
                            for(String k: kv.keySet()){
                                if(k.startsWith(prefix)) keys.add(k);
                            }
                            Collections.sort(keys);
                            Map<String,Object> s=new LinkedHashMap<>();
                            s.put("keys",keys);
                            s.put("count",keys.size());
                            textOut = valueToJson(s);
                            structured = s;
                            break;
                        }
                        case "sum": {
                            JsonNode arrNode = argMap.get("numbers");
                            long sum=0;
                            int cnt=0;
                            for(JsonNode e: arrNode.arr){
                                sum += Long.parseLong(e.numRaw);
                                cnt++;
                            }
                            Map<String,Object> s=new LinkedHashMap<>();
                            s.put("sum",sum);
                            s.put("count",cnt);
                            textOut = valueToJson(s);
                            structured = s;
                            break;
                        }
                        case "text_stats": {
                            String txt = argMap.get("text").str;
                            int words=0;
                            boolean inWord=false;
                            for(int i=0;i<txt.length();){
                                int cp=txt.codePointAt(i);
                                boolean sep = cp==' '||cp=='\t'||cp=='\n'||cp=='\r';
                                if(!sep){
                                    if(!inWord){words++;inWord=true;}
                                }else{
                                    inWord=false;
                                }
                                i+=Character.charCount(cp);
                            }
                            int codepoints=txt.codePointCount(0,txt.length());
                            int utf8bytes=txt.getBytes(StandardCharsets.UTF_8).length;
                            Map<String,Object> s=new LinkedHashMap<>();
                            s.put("words",words);
                            s.put("codepoints",codepoints);
                            s.put("utf8_bytes",utf8bytes);
                            textOut = valueToJson(s);
                            structured = s;
                            break;
                        }
                    }
                    contentMap.put("text",textOut);
                    contentList.add(contentMap);
                    toolResult.put("content",contentList);
                    if(structured!=null) toolResult.put("structuredContent",structured);
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",toolResult)));
                    break;
                }
                default: {
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32601,"message","Method not found"))));
                }
            }
        }
        BufferedWriter bw=new BufferedWriter(new OutputStreamWriter(System.out,StandardCharsets.UTF_8));
        for(String s:out){bw.write(s);bw.newLine();}
        bw.flush();
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static class JsonNode {
        enum Type {OBJECT, ARRAY, STRING, NUMBER, BOOLEAN, NULL}
        Type type;
        Map<String, JsonNode> obj;
        List<JsonNode> arr;
        String str;
        String numRaw;
        double numVal;
        boolean bool;
        JsonNode(Type t){type=t;}
    }

    static class Parser {
        final String s; int i=0;
        Parser(String s){this.s=s;}
        void skipWs(){while(i<s.length() && Character.isWhitespace(s.charAt(i))) i++;}
        JsonNode parseValue(){
            skipWs();
            if(i>=s.length()) return null;
            char c=s.charAt(i);
            if(c=='{') return parseObject();
            if(c=='[') return parseArray();
            if(c=='"') return parseString();
            if(c=='t'||c=='f'||c=='n') return parseLiteral();
            if(c=='-'||Character.isDigit(c)) return parseNumber();
            return null;
        }
        JsonNode parseObject(){
            i++;
            JsonNode n=new JsonNode(JsonNode.Type.OBJECT);
            n.obj=new LinkedHashMap<>();
            skipWs();
            if(i<s.length() && s.charAt(i)=='}'){i++;return n;}
            while(true){
                skipWs();
                if(i>=s.length()||s.charAt(i)!='"') return null;
                JsonNode k=parseString(); if(k==null) return null;
                String key=k.str;
                skipWs();
                if(i>=s.length()||s.charAt(i)!=':') return null;
                i++;
                JsonNode v=parseValue(); if(v==null) return null;
                n.obj.put(key,v);
                skipWs();
                if(i>=s.length()) return null;
                char c=s.charAt(i);
                if(c=='}'){i++;break;}
                if(c!=',') return null;
                i++;
            }
            return n;
        }
        JsonNode parseArray(){
            i++;
            JsonNode n=new JsonNode(JsonNode.Type.ARRAY);
            n.arr=new ArrayList<>();
            skipWs();
            if(i<s.length() && s.charAt(i)==']'){i++;return n;}
            while(true){
                JsonNode v=parseValue(); if(v==null) return null;
                n.arr.add(v);
                skipWs();
                if(i>=s.length()) return null;
                char c=s.charAt(i);
                if(c==']'){i++;return n;}
                if(c!=',') return null;
                i++;
            }
        }
        JsonNode parseString(){
            i++;
            StringBuilder sb=new StringBuilder();
            while(i<s.length()){
                char c=s.charAt(i++);
                if(c=='"') break;
                if(c=='\\'){
                    if(i>=s.length()) return null;
                    char e=s.charAt(i++);
                    switch(e){
                        case '"': sb.append('"');break;
                        case '\\': sb.append('\\');break;
                        case '/': sb.append('/');break;
                        case 'b': sb.append('\b');break;
                        case 'f': sb.append('\f');break;
                        case 'n': sb.append('\n');break;
                        case 'r': sb.append('\r');break;
                        case 't': sb.append('\t');break;
                        case 'u':
                            if(i+4>s.length()) return null;
                            String hex=s.substring(i,i+4); i+=4;
                            try{int code=Integer.parseInt(hex,16); sb.append((char)code);}catch(Exception ex){return null;}
                            break;
                        default: return null;
                    }
                }else sb.append(c);
            }
            JsonNode n=new JsonNode(JsonNode.Type.STRING); n.str=sb.toString(); return n;
        }
        JsonNode parseLiteral(){
            if(s.startsWith("true",i)){i+=4; JsonNode n=new JsonNode(JsonNode.Type.BOOLEAN); n.bool=true; return n;}
            if(s.startsWith("false",i)){i+=5; JsonNode n=new JsonNode(JsonNode.Type.BOOLEAN); n.bool=false; return n;}
            if(s.startsWith("null",i)){i+=4; return new JsonNode(JsonNode.Type.NULL);}
            return null;
        }
        JsonNode parseNumber(){
            int start=i;
            if(s.charAt(i)=='-') i++;
            if(i>=s.length()||!Character.isDigit(s.charAt(i))) return null;
            while(i<s.length() && Character.isDigit(s.charAt(i))) i++;
            if(i<s.length() && s.charAt(i)=='.'){i++; if(i>=s.length()||!Character.isDigit(s.charAt(i))) return null; while(i<s.length() && Character.isDigit(s.charAt(i))) i++;}
            if(i<s.length() && (s.charAt(i)=='e'||s.charAt(i)=='E')){i++; if(i<s.length() && (s.charAt(i)=='+'||s.charAt(i)=='-')) i++; if(i>=s.length()||!Character.isDigit(s.charAt(i))) return null; while(i<s.length() && Character.isDigit(s.charAt(i))) i++;}
            String raw=s.substring(start,i);
            JsonNode n=new JsonNode(JsonNode.Type.NUMBER); n.numRaw=raw;
            try{n.numVal=Double.parseDouble(raw);}catch(Exception e){return null;}
            return n;
        }
    }

    static boolean isValidId(JsonNode n){
        if(n==null) return false;
        if(n.type==JsonNode.Type.STRING) return true;
        if(n.type==JsonNode.Type.NUMBER) return n.numRaw.matches("-?\\d+");
        return false;
    }
    static String jsonString(String s){
        StringBuilder sb=new StringBuilder(); sb.append('"');
        for(char c:s.toCharArray()){
            switch(c){
                case '"': sb.append("\\\"");break;
                case '\\': sb.append("\\\\");break;
                case '\b': sb.append("\\b");break;
                case '\f': sb.append("\\f");break;
                case '\n': sb.append("\\n");break;
                case '\r': sb.append("\\r");break;
                case '\t': sb.append("\\t");break;
                default:
                    if(c<0x20) sb.append(String.format("\\u%04x",(int)c));
                    else sb.append(c);
            }
        }
        sb.append('"'); return sb.toString();
    }
    static String valueToJson(Object v){
        if(v==null) return "null";
        if(v instanceof String) return jsonString((String)v);
        if(v instanceof Number) return v.toString();
        if(v instanceof Boolean) return v.toString();
        if(v instanceof Map) return mapToJson((Map<String,Object>)v);
        if(v instanceof List){
            StringBuilder sb=new StringBuilder("[");
            List<?> l=(List<?>)v;
            for(int i=0;i<l.size();i++){
                if(i>0) sb.append(',');
                sb.append(valueToJson(l.get(i)));
            }
            sb.append(']'); return sb.toString();
        }
        return "null";
    }
    static String mapToJson(Map<String,Object> m){
        StringBuilder sb=new StringBuilder("{");
        boolean first=true;
        for(Map.Entry<String,Object> e:m.entrySet()){
            if(!first) sb.append(',');
            first=false;
            sb.append(jsonString(e.getKey()));
            sb.append(':');
            sb.append(valueToJson(e.getValue()));
        }
        sb.append('}'); return sb.toString();
    }
    static String idToJson(JsonNode n){
        if(n==null) return "null";
        if(n.type==JsonNode.Type.STRING) return jsonString(n.str);
        if(n.type==JsonNode.Type.NUMBER) return n.numRaw;
        return "null";
    }

    static boolean initialized=false;
    static Map<String,String> kv=new TreeMap<>();

    public static void main(String[] args) throws IOException{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8));
        List<String> out=new ArrayList<>();
        String line;
        while((line=br.readLine())!=null){
            if(line.trim().isEmpty()) continue;
            Parser p=new Parser(line);
            JsonNode root=p.parseValue();
            p.skipWs();
            if(root==null || p.i!=line.length()){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",null,"error",Map.of("code",-32700,"message","Parse error"))));
                continue;
            }
            if(root.type!=JsonNode.Type.OBJECT){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",null,"error",Map.of("code",-32600,"message","Invalid Request"))));
                continue;
            }
            boolean hasMethod=root.obj.containsKey("method");
            boolean hasResult=root.obj.containsKey("result");
            boolean hasError=root.obj.containsKey("error");
            if(!hasMethod && (hasResult||hasError)) continue;

            JsonNode jsonrpcNode=root.obj.get("jsonrpc");
            String jsonrpc = (jsonrpcNode!=null && jsonrpcNode.type==JsonNode.Type.STRING)? jsonrpcNode.str:null;
            JsonNode methodNode=root.obj.get("method");
            String method = (methodNode!=null && methodNode.type==JsonNode.Type.STRING)? methodNode.str:null;
            JsonNode idNode=root.obj.get("id");
            boolean idValid=isValidId(idNode);
            boolean methodBad = methodNode==null || methodNode.type!=JsonNode.Type.STRING;
            boolean jsonrpcBad = !"2.0".equals(jsonrpc);
            boolean idMemberInvalid = root.obj.containsKey("id") && !idValid;
            if(jsonrpcBad || methodBad || idMemberInvalid){
                Object outId = idValid? idNode : null;
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",outId,"error",Map.of("code",-32600,"message","Invalid Request"))));
                continue;
            }
            if(idNode==null){
                continue;
            }
            JsonNode paramsNode=root.obj.get("params");
            boolean paramsIsObject = paramsNode==null || paramsNode.type==JsonNode.Type.OBJECT;
            if(!paramsIsObject){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                continue;
            }
            if(!initialized && !method.equals("initialize") && !method.equals("ping")){
                out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32002,"message","Server not initialized"))));
                continue;
            }
            switch(method){
                case "initialize": {
                    if(initialized){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32600,"message","Already initialized"))));
                        break;
                    }
                    if(paramsNode==null || !paramsNode.obj.containsKey("protocolVersion")){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    JsonNode pv=paramsNode.obj.get("protocolVersion");
                    if(pv==null || pv.type!=JsonNode.Type.STRING){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    String ver=pv.str;
                    String chosen = ver.equals("2025-06-18")||ver.equals("2025-03-26")||ver.equals("2024-11-05")? ver : "2025-06-18";
                    initialized=true;
                    Map<String,Object> caps=new LinkedHashMap<>();
                    Map<String,Object> toolsCap=new LinkedHashMap<>();
                    toolsCap.put("listChanged",false);
                    caps.put("tools",toolsCap);
                    Map<String,Object> serverInfo=new LinkedHashMap<>();
                    serverInfo.put("name","cb2-kv");
                    serverInfo.put("title","CB2 key-value server");
                    serverInfo.put("version","1.4.2");
                    Map<String,Object> res=new LinkedHashMap<>();
                    res.put("protocolVersion",chosen);
                    res.put("capabilities",caps);
                    res.put("serverInfo",serverInfo);
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",res)));
                    break;
                }
                case "ping": {
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",new LinkedHashMap<>())));
                    break;
                }
                case "tools/list": {
                    List<Map<String,Object>> tools=new ArrayList<>();
                    tools.add(makeTool("kv_set","Set a value","Store a string value under a key, replacing any previous value.",Map.of("key",Map.of("type","string","minLength",1),"value",Map.of("type","string")),List.of("key","value"),false,null,null));
                    tools.add(makeTool("kv_get","Get a value","Return the value stored under a key.",Map.of("key",Map.of("type","string","minLength",1)),List.of("key"),false,null,null));
                    tools.add(makeTool("kv_list","List keys","List the stored keys that start with a prefix, sorted by Unicode code point.",Map.of("prefix",Map.of("type","string")),null,false,Map.of("keys",Map.of("type","array","items",Map.of("type","string")),"count",Map.of("type","integer")),List.of("keys","count")));
                    tools.add(makeTool("sum","Sum integers","Add up a non-empty list of integers.",Map.of("numbers",Map.of("type","array","items",Map.of("type","integer"),"minItems",1)),List.of("numbers"),false,Map.of("sum",Map.of("type","integer"),"count",Map.of("type","integer")),List.of("sum","count")));
                    Map<String,Object> ann4=new LinkedHashMap<>(); ann4.put("readOnlyHint",true); ann4.put("idempotentHint",true);
                    tools.set(3, makeToolWithAnn("sum","Sum integers","Add up a non-empty list of integers.",Map.of("numbers",Map.of("type","array","items",Map.of("type","integer"),"minItems",1)),List.of("numbers"),false,Map.of("sum",Map.of("type","integer"),"count",Map.of("type","integer")),List.of("sum","count"),ann4));
                    tools.add(makeTool("text_stats","Text statistics","Count the words, Unicode code points and UTF-8 bytes of a text.",Map.of("text",Map.of("type","string")),List.of("text"),false,Map.of("words",Map.of("type","integer"),"codepoints",Map.of("type","integer"),"utf8_bytes",Map.of("type","integer")),List.of("words","codepoints","utf8_bytes")));
                    Map<String,Object> ann5=new LinkedHashMap<>(); ann5.put("readOnlyHint",true);
                    tools.set(4, makeToolWithAnn("text_stats","Text statistics","Count the words, Unicode code points and UTF-8 bytes of a text.",Map.of("text",Map.of("type","string")),List.of("text"),false,Map.of("words",Map.of("type","integer"),"codepoints",Map.of("type","integer"),"utf8_bytes",Map.of("type","integer")),List.of("words","codepoints","utf8_bytes"),ann5));
                    Map<String,Object> resList=new LinkedHashMap<>();
                    resList.put("tools",tools);
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",resList)));
                    break;
                }
                case "tools/call": {
                    if(paramsNode==null || !paramsNode.obj.containsKey("name")){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    JsonNode nameNode=paramsNode.obj.get("name");
                    if(nameNode==null || nameNode.type!=JsonNode.Type.STRING){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Invalid params"))));
                        break;
                    }
                    String tname=nameNode.str;
                    if(!Set.of("kv_set","kv_get","kv_list","sum","text_stats").contains(tname)){
                        out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32602,"message","Unknown tool: "+tname))));
                        break;
                    }
                    JsonNode argsNode=paramsNode.obj.get("arguments");
                    Map<String,JsonNode> argMap;
                    if(argsNode!=null && argsNode.type!=JsonNode.Type.OBJECT){
                        argMap=null;
                    }else{
                        argMap = argsNode==null? new LinkedHashMap<>() : argsNode.obj;
                    }
                    String failMsg=null;
                    if(argsNode!=null && argsNode.type!=JsonNode.Type.OBJECT){
                        failMsg="arguments must be an object";
                    }else{
                        Set<String> allowed=setAllowed(tname);
                        List<String> unknown=new ArrayList<>();
                        for(String k:argMap.keySet()) if(!allowed.contains(k)) unknown.add(k);
                        if(!unknown.isEmpty()){
                            Collections.sort(unknown);
                            failMsg="unknown argument: "+unknown.get(0);
                        }else{
                            failMsg=validateTool(tname,argMap);
                        }
                    }
                    Map<String,Object> toolResult=new LinkedHashMap<>();
                    toolResult.put("isError", failMsg!=null);
                    List<Map<String,Object>> contentList=new ArrayList<>();
                    Map<String,Object> contentMap=new LinkedHashMap<>();
                    contentMap.put("type","text");
                    String textOut="";
                    Map<String,Object> structured=null;
                    if(failMsg!=null){
                        textOut=failMsg;
                    }else{
                        switch(tname){
                            case "kv_set": {
                                String key=getStr(argMap,"key");
                                String val=getStr(argMap,"value");
                                boolean existed=kv.containsKey(key);
                                kv.put(key,val);
                                textOut=(existed?"updated ":"created ")+key;
                                break;
                            }
                            case "kv_get": {
                                String key=getStr(argMap,"key");
                                if(!kv.containsKey(key)){
                                    textOut="key not found: "+key;
                                    toolResult.put("isError",true);
                                }else{
                                    textOut=kv.get(key);
                                }
                                break;
                            }
                            case "kv_list": {
                                String prefix=argMap.containsKey("prefix")? argMap.get("prefix").str : "";
                                List<String> keys=new ArrayList<>();
                                for(String k:kv.keySet()) if(k.startsWith(prefix)) keys.add(k);
                                Collections.sort(keys);
                                Map<String,Object> s=new LinkedHashMap<>();
                                s.put("keys",keys);
                                s.put("count",keys.size());
                                textOut=valueToJson(s);
                                structured=s;
                                break;
                            }
                            case "sum": {
                                JsonNode arr=argMap.get("numbers");
                                long sum=0;
                                for(JsonNode e:arr.arr){ sum+=Long.parseLong(e.numRaw); }
                                Map<String,Object> s=new LinkedHashMap<>();
                                s.put("sum",sum);
                                s.put("count",arr.arr.size());
                                textOut=valueToJson(s);
                                structured=s;
                                break;
                            }
                            case "text_stats": {
                                String txt=getStr(argMap,"text");
                                int words=0; boolean inWord=false;
                                for(int i=0;i<txt.length();){
                                    int cp=txt.codePointAt(i);
                                    boolean sep=cp==' '||cp=='\t'||cp=='\n'||cp=='\r';
                                    if(!sep){ if(!inWord){words++;inWord=true;} } else {inWord=false;}
                                    i+=Character.charCount(cp);
                                }
                                int codepoints=txt.codePointCount(0,txt.length());
                                int utf8bytes=txt.getBytes(StandardCharsets.UTF_8).length;
                                Map<String,Object> s=new LinkedHashMap<>();
                                s.put("words",words);
                                s.put("codepoints",codepoints);
                                s.put("utf8_bytes",utf8bytes);
                                textOut=valueToJson(s);
                                structured=s;
                                break;
                            }
                        }
                    }
                    contentMap.put("text",textOut);
                    contentList.add(contentMap);
                    toolResult.put("content",contentList);
                    if(structured!=null) toolResult.put("structuredContent",structured);
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"result",toolResult)));
                    break;
                }
                default: {
                    out.add(mapToJson(Map.of("jsonrpc","2.0","id",idNode,"error",Map.of("code",-32601,"message","Method not found"))));
                }
            }
        }
        BufferedWriter bw=new BufferedWriter(new OutputStreamWriter(System.out,StandardCharsets.UTF_8));
        for(String s:out){bw.write(s);bw.newLine();}
        bw.flush();
    }

    static Set<String> setAllowed(String t){
        return switch(t){
            case "kv_set" -> Set.of("key","value");
            case "kv_get" -> Set.of("key");
            case "kv_list" -> Set.of("prefix");
            case "sum" -> Set.of("numbers");
            case "text_stats" -> Set.of("text");
            default -> Set.of();
        };
    }
    static String getStr(Map<String,JsonNode> m,String k){ JsonNode n=m.get(k); return n!=null && n.type==JsonNode.Type.STRING? n.str:""; }

    static String validateTool(String tname, Map<String,JsonNode> args){
        List<String> order;
        boolean required;
        switch(tname){
            case "kv_set": order=List.of("key","value"); required=true; break;
            case "kv_get": order=List.of("key"); required=true; break;
            case "kv_list": order=List.of("prefix"); required=false; break;
            case "sum": order=List.of("numbers"); required=true; break;
            case "text_stats": order=List.of("text"); required=true; break;
            default: return null;
        }
        for(String prop:order){
            boolean present=args.containsKey(prop);
            if(!present){
                if(required) return "missing required argument: "+prop;
                continue;
            }
            JsonNode v=args.get(prop);
            if(tname.equals("kv_set") && prop.equals("key")){
                if(v.type!=JsonNode.Type.STRING) return "argument key must be a string";
                if(v.str.length()<1) return "argument key must not be empty";
            }else if(tname.equals("kv_set") && prop.equals("value")){
                if(v.type!=JsonNode.Type.STRING) return "argument value must be a string";
            }else if(tname.equals("kv_get") && prop.equals("key")){
                if(v.type!=JsonNode.Type.STRING) return "argument key must be a string";
                if(v.str.length()<1) return "argument key must not be empty";
            }else if(tname.equals("kv_list") && prop.equals("prefix")){
                if(v.type!=JsonNode.Type.STRING) return "argument prefix must be a string";
            }else if(tname.equals("sum") && prop.equals("numbers")){
                if(v.type!=JsonNode.Type.ARRAY) return "argument numbers must be an array of integers";
                if(v.arr.isEmpty()) return "argument numbers must not be empty";
                for(JsonNode e:v.arr){ if(e.type!=JsonNode.Type.NUMBER || !e.numRaw.matches("-?\\d+")) return "argument numbers must be an array of integers"; }
            }else if(tname.equals("text_stats") && prop.equals("text")){
                if(v.type!=JsonNode.Type.STRING) return "argument text must be a string";
            }
        }
        return null;
    }

    static Map<String,Object> makeTool(String name,String title,String desc,Map<String,Object> props,List<String> required,boolean addProps,Map<String,Object> outProps,List<String> outRequired){
        Map<String,Object> t=new LinkedHashMap<>();
        t.put("name",name); t.put("title",title); t.put("description",desc);
        Map<String,Object> is=new LinkedHashMap<>();
        Map<String,Object> p=new LinkedHashMap<>();
        p.putAll(props);
        is.put("type","object"); is.put("properties",p);
        if(required!=null) is.put("required",required);
        is.put("additionalProperties",false);
        t.put("inputSchema",is);
        if(outProps!=null){
            Map<String,Object> os=new LinkedHashMap<>();
            Map<String,Object> osp=new LinkedHashMap<>();
            osp.putAll(outProps);
            os.put("type","object"); os.put("properties",osp); os.put("required",outRequired);
            t.put("outputSchema",os);
        }
        return t;
    }
    static Map<String,Object> makeToolWithAnn(String name,String title,String desc,Map<String,Object> props,List<String> required,boolean addProps,Map<String,Object> outProps,List<String> outRequired,Map<String,Object> ann){
        Map<String,Object> t=makeTool(name,title,desc,props,required,addProps,outProps,outRequired);
        t.put("annotations",ann);
        return t;
    }
}

