static unsigned char base64_table[256];
static void init_base64(void){
    memset(base64_table, -1, sizeof(base64_table));
    const char *tbl = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    for(int i=0;i<64;i++) base64_table[(unsigned char)tbl[i]] = i;
}

/* ---------- base64url ---------- */
static int base64url_decode(const char *in, size_t in_len, unsigned char *out, size_t *out_len){
    size_t pad = (4 - in_len % 4) % 4;
    size_t len = in_len + pad;
    char *tmp = malloc(len+1);
    if(!tmp) return 0;
    for(size_t i=0;i<in_len;i++){
        char c = in[i];
        if(c=='-') c='+';
        else if(c=='_') c='/';
        tmp[i]=c;
    }
    for(size_t i=0;i<pad;i++) tmp[in_len+i]='=';
    tmp[len]=0;
    size_t o=0;
    for(size_t i=0;i<len;i+=4){
        int v0 = base64_table[(unsigned char)tmp[i]];
        int v1 = base64_table[(unsigned char)tmp[i+1]];
        int v2 = base64_table[(unsigned char)tmp[i+2]];
        int v3 = base64_table[(unsigned char)tmp[i+3]];
        if(v0<0||v1<0) {free(tmp);return 0;}
        out[o++] = (v0<<2)|(v1>>4);
        if(tmp[i+2]!='='){
            if(v2<0){free(tmp);return 0;}
            out[o++] = ((v1&0xF)<<4)|(v2>>2);
            if(tmp[i+3]!='='){
                if(v3<0){free(tmp);return 0;}
                out[o++] = ((v2&0x3)<<6)|v3;
            }
        }
    }
    *out_len=o;
    free(tmp);
    return 1;
}
static char *base64url_encode(const unsigned char *in, size_t in_len){
    size_t out_len = 4*((in_len+2)/3);
    char *out = malloc(out_len+1);
    const char *tbl = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    size_t o=0;
    for(size_t i=0;i<in_len;i+=3){
        uint32_t v=0;
        size_t left = in_len - i;
        if(left>=3){ v = (in[i]<<16)|(in[i+1]<<8)|in[i+2]; }
        else if(left==2){ v = (in[i]<<16)|(in[i+1]<<8); }
        else { v = (in[i]<<16); }
        out[o++] = tbl[(v>>18)&0x3F];
        out[o++] = tbl[(v>>12)&0x3F];
        if(left>1) out[o++] = tbl[(v>>6)&0x3F];
        else out[o++] = '=';
        if(left>2) out[o++] = tbl[v&0x3F];
        else out[o++] = '=';
    }
    /* strip padding */
    while(o>0 && out[o-1]=='=') o--;
    out[o]=0;
    return out;
}

/* ---------- JSON helpers ---------- */
typedef struct { const unsigned char *data; size_t len; size_t pos; } Parser;
static void skip_ws(Parser *p){ while(p->pos<p->len && isspace(p->data[p->pos])) p->pos++; }
static int parse_json_string_raw(Parser *p, unsigned char *out, size_t outsize, size_t *outlen){
    if(p->pos>=p->len || p->data[p->pos]!='"') return 0;
    p->pos++;
    size_t o=0;
    while(p->pos<p->len){
        unsigned char c = p->data[p->pos++];
        if(c=='"') { *outlen=o; return 1; }
        if(c=='\\'){
            if(p->pos>=p->len) return 0;
            unsigned char e = p->data[p->pos++];
            switch(e){
                case '"': out[o++]='"'; break;
                case '\\': out[o++]='\\'; break;
                case '/': out[o++]='/'; break;
                case 'b': out[o++]=8; break;
                case 'f': out[o++]=12; break;
                case 'n': out[o++]='\n'; break;
                case 'r': out[o++]='\r'; break;
                case 't': out[o++]='\t'; break;
                case 'u':{
                    if(p->pos+4>p->len) return 0;
                    int cp=0;
                    for(int i=0;i<4;i++){
                        char h = p->data[p->pos++];
                        int v;
                        if('0'<=h && h<='9') v=h-'0';
                        else if('a'<=h && h<='f') v=10+h-'a';
                        else if('A'<=h && h<='F') v=10+h-'A';
                        else return 0;
                        cp = (cp<<4)|v;
                    }
                    if(cp<=0x7F){ out[o++] = cp; }
                    else if(cp<=0x7FF){ out[o++] = 0xC0|(cp>>6); out[o++] = 0x80|(cp&0x3F); }
                    else if(cp<=0xFFFF){ out[o++] = 0xE0|((cp>>12)&0x0F); out[o++] = 0x80|((cp>>6)&0x3F); out[o++] = 0x80|(cp&0x3F); }
                    else { out[o++] = 0xF0|((cp>>18)&0x07); out[o++] = 0x80|((cp>>12)&0x3F); out[o++] = 0x80|((cp>>6)&0x3F); out[o++] = 0x80|(cp&0x3F); }
                    break;
                }
                default: out[o++]=e; break;
            }
        }else{
            out[o++]=c;
        }
        if(o>=outsize) return 0;
    }
    return 0;
}
static int skip_value(Parser *p){
    skip_ws(p);
    if(p->pos>=p->len) return 0;
    unsigned char c = p->data[p->pos];
    if(c=='"'){ unsigned char buf[MAX_BUF]; size_t l; if(!parse_json_string_raw(p,buf,MAX_BUF,&l)) return 0; }
    else if(c=='{'){ p->pos++; int d=1; while(p->pos<p->len && d){ skip_ws(p); if(p->data[p->pos]=='{') d++; else if(p->data[p->pos]=='}') d--; p->pos++; } }
    else if(c=='['){ p->pos++; int d=1; while(p->pos<p->len && d){ skip_ws(p); if(p->data[p->pos]=='[') d++; else if(p->data[p->pos]==']') d--; p->pos++; } }
    else if(c=='t' || c=='f' || c=='n'){ while(p->pos<p->len && !isspace(p->data[p->pos]) && p->data[p->pos]!=',' && p->data[p->pos]!='}') p->pos++; }
    else if(c=='-' || isdigit(c)){ while(p->pos<p->len && (isdigit(p->data[p->pos])||p->data[p->pos]=='.'||p->data[p->pos]=='e'||p->data[p->pos]=='E'||p->data[p->pos]=='+'||p->data[p->pos]=='-')) p->pos++; }
    else return 0;
    return 1;
}

/* ---------- config parsing ---------- */
static int parse_config(const char *path){
    FILE *f = fopen(path,"rb");
    if(!f) return 0;
    fseek(f,0,SEEK_END); long sz = ftell(f); fseek(f,0,SEEK_SET);
    unsigned char *buf = malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    Parser p = {buf, (size_t)sz,0};
    skip_ws(&p);
    if(p.data[p.pos]!='{') { free(buf); return 0; }
    p.pos++;
    while(1){
        skip_ws(&p);
        if(p.pos>=p.len) break;
        if(p.data[p.pos]=='}'){ p.pos++; break; }
        unsigned char keybuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&p,keybuf,MAX_BUF,&klen)){ free(buf); return 0; }
        keybuf[klen]=0;
        skip_ws(&p); if(p.data[p.pos]!=':'){ free(buf); return 0; } p.pos++;
        skip_ws(&p);
        if(strcmp((char*)keybuf,"now")==0){ char numbuf[64]; size_t n=0; while(p.pos<p.len && (isdigit(p.data[p.pos])||p.data[p.pos]=='.'||p.data[p.pos]=='-'||p.data[p.pos]=='+'||p.data[p.pos]=='e'||p.data[p.pos]=='E')){ numbuf[n++]=p.data[p.pos++]; } numbuf[n]=0; config_now = atof(numbuf); }
        else if(strcmp((char*)keybuf,"leeway")==0){ char numbuf[64]; size_t n=0; while(p.pos<p.len && (isdigit(p.data[p.pos])||p.data[p.pos]=='.'||p.data[p.pos]=='-'||p.data[p.pos]=='+'||p.data[p.pos]=='e'||p.data[p.pos]=='E')){ numbuf[n++]=p.data[p.pos++]; } numbuf[n]=0; config_leeway = atof(numbuf); }
        else if(strcmp((char*)keybuf,"issuer")==0){ unsigned char vbuf[MAX_BUF]; size_t vlen; if(parse_json_string_raw(&p,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(config_issuer,(char*)vbuf,1023); } }
        else if(strcmp((char*)keybuf,"audience")==0){ unsigned char vbuf[MAX_BUF]; size_t vlen; if(parse_json_string_raw(&p,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(config_audience,(char*)vbuf,1023); } }
        else if(strcmp((char*)keybuf,"keys")==0){
            if(p.data[p.pos]!='['){ free(buf); return 0; } p.pos++;
            while(1){
                skip_ws(&p);
                if(p.data[p.pos]==']'){ p.pos++; break; }
                if(p.data[p.pos]!='{'){ free(buf); return 0; } p.pos++;
                char kid[256]="", alg[16]="", kstr[1024]="";
                while(1){
                    skip_ws(&p);
                    if(p.data[p.pos]=='}'){ p.pos++; break; }
                    unsigned char k2[MAX_BUF]; size_t k2len;
                    if(!parse_json_string_raw(&p,k2,MAX_BUF,&k2len)){ free(buf); return 0; } k2[k2len]=0;
                    skip_ws(&p); p.pos++; skip_ws(&p);
                    if(strcmp((char*)k2,"kid")==0){ unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){ v[vl]=0; strncpy(kid,(char*)v,255); } }
                    else if(strcmp((char*)k2,"alg")==0){ unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){ v[vl]=0; strncpy(alg,(char*)v,15); } }
                    else if(strcmp((char*)k2,"k")==0){ unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){ v[vl]=0; strncpy(kstr,(char*)v,1023); } }
                    else { skip_value(&p); }
                    skip_ws(&p);
                    if(p.data[p.pos]==','){ p.pos++; }
                }
                if(key_count<MAX_KEYS && kid[0] && alg[0] && kstr[0]){
                    unsigned char dec[4096]; size_t dlen;
                    if(base64url_decode(kstr,strlen(kstr),dec,&dlen)){
                        keys[key_count].secret = malloc(dlen);
                        memcpy(keys[key_count].secret,dec,dlen);
                        keys[key_count].secret_len = dlen;
                        strncpy(keys[key_count].kid,kid,255);
                        strncpy(keys[key_count].alg,alg,15);
                        key_count++;
                    }
                }
                skip_ws(&p);
                if(p.data[p.pos]==','){ p.pos++; }
            }
        } else {
            skip_value(&p);
        }
        skip_ws(&p);
        if(p.data[p.pos]==','){ p.pos++; }
    }
    free(buf);
    return 1;
}

/* ---------- token processing ---------- */
static int find_key(const char *kid, const char *alg, unsigned char **secret, size_t *secret_len){
    for(int i=0;i<key_count;i++){
        if(strcmp(keys[i].kid,kid)==0){
            if(strcmp(keys[i].alg,alg)!=0) return -1; /* mismatch */
            *secret = keys[i].secret;
            *secret_len = keys[i].secret_len;
            return 1;
        }
    }
    return 0;
}
static void hmac_sign(const unsigned char *key, size_t keylen, const unsigned char *data, size_t datalen, int alg, unsigned char *out, unsigned int *outlen){
    CCHmacAlgorithm cc;
    if(alg==256) cc = kCCHmacAlgSHA256;
    else if(alg==384) cc = kCCHmacAlgSHA384;
    else cc = kCCHmacAlgSHA512;
    CCHmac(cc, key, keylen, data, datalen, out);
}
static int check_token(const char *token_raw, int line_no, int *valid_cnt, int *invalid_cnt){
    char token[MAX_BUF];
    strncpy(token,token_raw,MAX_BUF-1);
    token[MAX_BUF-1]=0;
    /* split */
    char *p1 = strchr(token,'.');
    if(!p1){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    *p1='\0';
    char *p2 = strchr(p1+1,'.');
    if(!p2){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    *p2='\0';
    char *seg1 = token;
    char *seg2 = p1+1;
    char *seg3 = p2+1;
    if(!seg1[0]||!seg2[0]||!seg3[0]){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    /* base64url validity */
    const char *segs[3]={seg1,seg2,seg3};
    for(int i=0;i<3;i++){
        size_t l=strlen(segs[i]);
        if(l==0||l%4==1){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
        for(size_t j=0;j<l;j++){ unsigned char c=segs[i][j]; if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_')){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; } }
    }
    unsigned char dec1[4096], dec2[4096], dec3[4096];
    size_t d1,d2,d3;
    if(!base64url_decode(seg1,strlen(seg1),dec1,&d1)){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    if(!base64url_decode(seg2,strlen(seg2),dec2,&d2)){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    if(!base64url_decode(seg3,strlen(seg3),dec3,&d3)){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    /* re-encode check */
    char *re1 = base64url_encode(dec1,d1);
    char *re2 = base64url_encode(dec2,d2);
    char *re3 = base64url_encode(dec3,d3);
    if(strcmp(re1,seg1)!=0||strcmp(re2,seg2)!=0||strcmp(re3,seg3)!=0){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; free(re1);free(re2);free(re3); return 0; }
    free(re1);free(re2);free(re3);
    /* JSON objects */
    Parser ph = {dec1,d1,0}; skip_ws(&ph); if(ph.data[ph.pos]!='{'||ph.data[ph.pos+d1-1]!='}'){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    Parser pp = {dec2,d2,0}; skip_ws(&pp); if(pp.data[pp.pos]!='{'||pp.data[pp.pos+d2-1]!='}'){ printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0; }
    /* parse header */
    char alg[16]="", kid[256]="";
    Parser hp = {dec1,d1,0}; hp.pos=1;
    while(hp.pos<hp.len){
        skip_ws(&hp); if(hp.data[hp.pos]=='}') break;
        unsigned char kbuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&hp,kbuf,MAX_BUF,&klen)) break;
        kbuf[klen]=0;
        skip_ws(&hp); if(hp.data[hp.pos]!=':'){ break; } hp.pos++;
        skip_ws(&hp);
        if(strcmp((char*)kbuf,"alg")==0 && hp.data[hp.pos]=='"'){
            unsigned char vbuf[MAX_BUF]; size_t vlen;
            if(parse_json_string_raw(&hp,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(alg,(char*)vbuf,15); }
        } else if(strcmp((char*)kbuf,"kid")==0 && hp.data[hp.pos]=='"'){
            unsigned char vbuf[MAX_BUF]; size_t vlen;
            if(parse_json_string_raw(&hp,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(kid,(char*)vbuf,255); }
        } else { skip_value(&hp); }
        skip_ws(&hp); if(hp.data[hp.pos]==',') hp.pos++;
    }
    if(!alg[0] || strcmp(alg,"HS256")!=0 && strcmp(alg,"HS384")!=0 && strcmp(alg,"HS512")!=0){ printf("%d: UNSUPPORTED_ALG\n",line_no); (*invalid_cnt)++; return 0; }
    if(!kid[0]){ printf("%d: UNKNOWN_KEY\n",line_no); (*invalid_cnt)++; return 0; }
    unsigned char *secret=NULL; size_t secret_len=0;
    int kf = find_key(kid,alg,&secret,&secret_len);
    if(kf==0){ printf("%d: UNKNOWN_KEY\n",line_no); (*invalid_cnt)++; return 0; }
    if(kf==-1){ printf("%d: ALG_MISMATCH\n",line_no); (*invalid_cnt)++; return 0; }
    /* signature */
    char signing[8192]; snprintf(signing,sizeof(signing),"%s.%s",seg1,seg2);
    unsigned char mac[64]; unsigned int maclen;
    int bits = (strcmp(alg,"HS256")==0)?256:(strcmp(alg,"HS384")==0)?384:512;
    hmac_sign(secret,secret_len,(unsigned char*)signing,strlen(signing),bits,mac,&maclen);
    char *sig_enc = base64url_encode(mac,maclen);
    if(strcmp(sig_enc,seg3)!=0){ printf("%d: BAD_SIGNATURE\n",line_no); (*invalid_cnt)++; free(sig_enc); return 0; }
    free(sig_enc);
    /* payload checks */
    double exp=-1, nbf=-1; int has_exp=0, has_nbf=0;
    char iss[1024]="", aud_str[1024]="", sub[1024]="", scope[1024]="";
    int has_iss=0, has_aud=0, has_sub=0, has_scope=0;
    Parser pl = {dec2,d2,0}; pl.pos=1;
    int aud_match=0;
    while(pl.pos<pl.len){
        skip_ws(&pl); if(pl.data[pl.pos]=='}') break;
        unsigned char kbuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&pl,kbuf,MAX_BUF,&klen)) break;
        kbuf[klen]=0;
        skip_ws(&pl); if(pl.data[pl.pos]!=':'){ break; } pl.pos++;
        skip_ws(&pl);
        if(strcmp((char*)kbuf,"exp")==0){
            char numbuf[64]; size_t n=0; while(pl.pos<pl.len && (isdigit(pl.data[pl.pos])||pl.data[pl.pos]=='.'||pl.data[pl.pos]=='-'||pl.data[pl.pos]=='+'||pl.data[pl.pos]=='e'||pl.data[pl.pos]=='E')) numbuf[n++]=pl.data[pl.pos++]; numbuf[n]=0; exp=atof(numbuf); has_exp=1;
        } else if(strcmp((char*)kbuf,"nbf")==0){
            char numbuf[64]; size_t n=0; while(pl.pos<pl.len && (isdigit(pl.data[pl.pos])||pl.data[pl.pos]=='.'||pl.data[pl.pos]=='-'||pl.data[pl.pos]=='+'||pl.data[pl.pos]=='e'||pl.data[pl.pos]=='E')) numbuf[n++]=pl.data[pl.pos++]; numbuf[n]=0; nbf=atof(numbuf); has_nbf=1;
        } else if(strcmp((char*)kbuf,"iss")==0 && pl.data[pl.pos]=='"'){
            unsigned char vbuf[MAX_BUF]; size_t vlen;
            if(parse_json_string_raw(&pl,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(iss,(char*)vbuf,1023); has_iss=1; }
        } else if(strcmp((char*)kbuf,"aud")==0){
            has_aud=1;
            if(pl.data[pl.pos]=='"'){
                unsigned char vbuf[MAX_BUF]; size_t vlen;
                if(parse_json_string_raw(&pl,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(aud_str,(char*)vbuf,1023); }
            } else if(pl.data[pl.pos]=='['){
                /* check array contains audience */
                pl.pos++; skip_ws(&pl);
                int found=0;
                while(pl.pos<pl.len && pl.data[pl.pos]!=']'){
                    if(pl.data[pl.pos]=='"'){
                        unsigned char vbuf[MAX_BUF]; size_t vlen;
                        if(parse_json_string_raw(&pl,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; if(strcmp((char*)vbuf,config_audience)==0) found=1; }
                    }
                    skip_ws(&pl);
                    if(pl.data[pl.pos]==',') pl.pos++;
                }
                if(pl.data[pl.pos]==']') pl.pos++;
                aud_match = found;
            }
        } else if(strcmp((char*)kbuf,"sub")==0 && pl.data[pl.pos]=='"'){
            unsigned char vbuf[MAX_BUF]; size_t vlen;
            if(parse_json_string_raw(&pl,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(sub,(char*)vbuf,1023); has_sub=1; }
        } else if(strcmp((char*)kbuf,"scope")==0 && pl.data[pl.pos]=='"'){
            unsigned char vbuf[MAX_BUF]; size_t vlen;
            if(parse_json_string_raw(&pl,vbuf,MAX_BUF,&vlen)){ vbuf[vlen]=0; strncpy(scope,(char*)vbuf,1023); has_scope=1; }
        } else { skip_value(&pl); }
        skip_ws(&pl); if(pl.data[pl.pos]==',') pl.pos++;
    }
    if(has_exp && config_now >= exp + config_leeway){ printf("%d: EXPIRED\n",line_no); (*invalid_cnt)++; return 0; }
    if(has_nbf && config_now + config_leeway < nbf){ printf("%d: NOT_YET_VALID\n",line_no); (*invalid_cnt)++; return 0; }
    if(!has_iss || strcmp(iss,config_issuer)!=0){ printf("%d: BAD_ISSUER\n",line_no); (*invalid_cnt)++; return 0; }
    int aud_ok=0;
    if(has_aud){
        if(aud_str[0] && strcmp(aud_str,config_audience)==0) aud_ok=1;
        else if(aud_match) aud_ok=1;
    }
    if(!aud_ok){ printf("%d: BAD_AUDIENCE\n",line_no); (*invalid_cnt)++; return 0; }
    /* VALID */
    /* scopes processing */
    char scopes_out[1024]=""; 
    if(has_scope && scope[0]){
        char *copy = strdup(scope);
        char *tok = strtok(copy," ");
        char *uniq[256]; int uc=0;
        while(tok){
            int exists=0;
            for(int i=0;i<uc;i++) if(strcmp(uniq[i],tok)==0){ exists=1; break; }
            if(!exists){ uniq[uc]=strdup(tok); uc++; }
            tok=strtok(NULL," ");
        }
        /* sort */
        for(int i=0;i<uc;i++) for(int j=i+1;j<uc;j++) if(strcmp(uniq[i],uniq[j])>0){ char *t=uniq[i]; uniq[i]=uniq[j]; uniq[j]=t; }
        char tmp[1024]=""; for(int i=0;i<uc;i++){ if(i) strcat(tmp,","); strcat(tmp,uniq[i]); free(uniq[i]); }
        strcpy(scopes_out,tmp);
        free(copy);
    }
    printf("%d: VALID sub=%s scope=%s\n",line_no, has_sub?sub:"", scopes_out);
    (*valid_cnt)++;
    return 1;
}

int main(int argc, char **argv){
    if(argc<2) return 1;
    init_base64();
    char cfg[1024], tok[1024];
    snprintf(cfg,sizeof(cfg),"%s/config.json",argv[1]);
    snprintf(tok,sizeof(tok),"%s/tokens.txt",argv[1]);
    if(!parse_config(cfg)) return 1;
    FILE *f = fopen(tok,"r");
    if(!f) return 1;
    char line[8192];
    int line_no=0, valid=0, invalid=0;
    while(fgets(line,sizeof(line),f)){
        char *s = line;
        while(*s && isspace((unsigned char)*s)) s++;
        char *e = s + strlen(s) -1;
        while(e>=s && isspace((unsigned char)*e)) *e--=0;
        if(*s==0) continue;
        line_no++;
        check_token(s,line_no,&valid,&invalid);
    }
    fclose(f);
    printf("\nvalid=%d invalid=%d\n",valid,invalid);
    return 0;
}

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>
#include <stdbool.h>
#include <CommonCrypto/CommonHMAC.h>

#define MAX_BUF 8192
#define MAX_KEYS 256

typedef struct {
    char kid[256];
    char alg[16];
    unsigned char *secret;
    size_t secret_len;
} KeyEntry;

static KeyEntry keys[MAX_KEYS];
static int key_count = 0;

static char config_issuer[1024] = "";
static char config_audience[1024] = "";
static double config_now = 0;
static double config_leeway = 0;

/* ---------- base64url ---------- */
static int b64val(unsigned char c){
    if('A'<=c && c<='Z') return c-'A';
    if('a'<=c && c<='z') return c-'a'+26;
    if('0'<=c && c<='9') return c-'0'+52;
    if(c=='-') return 62;
    if(c=='_') return 63;
    return -1;
}
static int b64stdval(unsigned char c){
    if('A'<=c && c<='Z') return c-'A';
    if('a'<=c && c<='z') return c-'a'+26;
    if('0'<=c && c<='9') return c-'0'+52;
    if(c=='+') return 62;
    if(c=='/') return 63;
    return -1;
}
static int base64url_decode_valid(const char *in, size_t in_len, unsigned char *out, size_t *out_len){
    if(in_len==0 || in_len%4==1) return 0;
    for(size_t i=0;i<in_len;i++){
        if(b64val((unsigned char)in[i])<0) return 0;
    }
    size_t pad = (4 - in_len%4)%4;
    size_t len = in_len + pad;
    char *tmp = malloc(len+1);
    if(!tmp) return 0;
    for(size_t i=0;i<in_len;i++){
        unsigned char c = in[i];
        if(c=='-') c='+';
        else if(c=='_') c='/';
        tmp[i]=c;
    }
    for(size_t i=0;i<pad;i++) tmp[in_len+i]='=';
    tmp[len]=0;
    size_t o=0;
    for(size_t i=0;i<len;i+=4){
        int v0=b64stdval(tmp[i]);
        int v1=b64stdval(tmp[i+1]);
        int v2=b64stdval(tmp[i+2]);
        int v3=b64stdval(tmp[i+3]);
        if(v0<0||v1<0) {free(tmp);return 0;}
        out[o++] = (v0<<2)|(v1>>4);
        if(tmp[i+2]!='='){
            if(v2<0){free(tmp);return 0;}
            out[o++] = ((v1&0xF)<<4)|(v2>>2);
            if(tmp[i+3]!='='){
                if(v3<0){free(tmp);return 0;}
                out[o++] = ((v2&0x3)<<6)|v3;
            }
        }
    }
    *out_len=o;
    free(tmp);
    return 1;
}
static char *base64url_encode(const unsigned char *in, size_t in_len){
    const char *tbl = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    size_t out_len = 4*((in_len+2)/3);
    char *out = malloc(out_len+1);
    size_t o=0;
    for(size_t i=0;i<in_len;i+=3){
        uint32_t v=0;
        size_t left = in_len - i;
        if(left>=3) v = (in[i]<<16)|(in[i+1]<<8)|in[i+2];
        else if(left==2) v = (in[i]<<16)|(in[i+1]<<8);
        else v = (in[i]<<16);
        out[o++] = tbl[(v>>18)&0x3F];
        out[o++] = tbl[(v>>12)&0x3F];
        if(left>1) out[o++] = tbl[(v>>6)&0x3F];
        else out[o++] = '=';
        if(left>2) out[o++] = tbl[v&0x3F];
        else out[o++] = '=';
    }
    while(o>0 && out[o-1]=='=') o--;
    out[o]=0;
    return out;
}

/* ---------- JSON helpers ---------- */
typedef struct { const unsigned char *data; size_t len; size_t pos; } Parser;
static void skip_ws(Parser *p){ while(p->pos<p->len && isspace(p->data[p->pos])) p->pos++; }
static int parse_json_string_raw(Parser *p, unsigned char *out, size_t outsize, size_t *outlen){
    if(p->pos>=p->len || p->data[p->pos]!='"') return 0;
    p->pos++;
    size_t o=0;
    while(p->pos<p->len){
        unsigned char c = p->data[p->pos++];
        if(c=='"'){ *outlen=o; return 1; }
        if(c=='\\'){
            if(p->pos>=p->len) return 0;
            unsigned char e = p->data[p->pos++];
            switch(e){
                case '"': out[o++]='"'; break;
                case '\\': out[o++]='\\'; break;
                case '/': out[o++]='/'; break;
                case 'b': out[o++]=8; break;
                case 'f': out[o++]=12; break;
                case 'n': out[o++]='\n'; break;
                case 'r': out[o++]='\r'; break;
                case 't': out[o++]='\t'; break;
                case 'u':{
                    if(p->pos+4>p->len) return 0;
                    int cp=0;
                    for(int i=0;i<4;i++){
                        char h = p->data[p->pos++];
                        int v;
                        if('0'<=h && h<='9') v=h-'0';
                        else if('a'<=h && h<='f') v=10+h-'a';
                        else if('A'<=h && h<='F') v=10+h-'A';
                        else return 0;
                        cp = (cp<<4)|v;
                    }
                    if(cp<=0x7F){ out[o++] = cp; }
                    else if(cp<=0x7FF){ out[o++] = 0xC0|(cp>>6); out[o++] = 0x80|(cp&0x3F); }
                    else if(cp<=0xFFFF){ out[o++] = 0xE0|((cp>>12)&0x0F); out[o++] = 0x80|((cp>>6)&0x3F); out[o++] = 0x80|(cp&0x3F); }
                    else { out[o++] = 0xF0|((cp>>18)&0x07); out[o++] = 0x80|((cp>>12)&0x3F); out[o++] = 0x80|((cp>>6)&0x3F); out[o++] = 0x80|(cp&0x3F); }
                    break;
                }
                default: out[o++]=e; break;
            }
        }else{
            out[o++]=c;
        }
        if(o>=outsize) return 0;
    }
    return 0;
}
static int skip_value(Parser *p){
    skip_ws(p);
    if(p->pos>=p->len) return 0;
    unsigned char c = p->data[p->pos];
    if(c=='"'){ unsigned char buf[MAX_BUF]; size_t l; if(!parse_json_string_raw(p,buf,MAX_BUF,&l)) return 0; }
    else if(c=='{'){ p->pos++; int d=1; while(p->pos<p->len && d){ skip_ws(p); if(p->data[p->pos]=='{') d++; else if(p->data[p->pos]=='}') d--; p->pos++; } }
    else if(c=='['){ p->pos++; int d=1; while(p->pos<p->len && d){ skip_ws(p); if(p->data[p->pos]=='[') d++; else if(p->data[p->pos]==']') d--; p->pos++; } }
    else if(c=='t'||c=='f'||c=='n'){ while(p->pos<p->len && !isspace(p->data[p->pos]) && p->data[p->pos]!=',' && p->data[p->pos]!='}') p->pos++; }
    else if(c=='-'||isdigit(c)){ while(p->pos<p->len && (isdigit(p->data[p->pos])||p->data[p->pos]=='.'||p->data[p->pos]=='e'||p->data[p->pos]=='E'||p->data[p->pos]=='+'||p->data[p->pos]=='-')) p->pos++; }
    else return 0;
    return 1;
}

/* config parsing */
static int parse_config(const char *path){
    FILE *f=fopen(path,"rb");
    if(!f) return 0;
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char *buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    Parser p={buf,(size_t)sz,0};
    skip_ws(&p); if(p.data[p.pos]!='{'){free(buf);return 0;}
    p.pos++;
    while(1){
        skip_ws(&p);
        if(p.pos>=p.len) break;
        if(p.data[p.pos]=='}'){p.pos++;break;}
        unsigned char kbuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&p,kbuf,MAX_BUF,&klen)){free(buf);return 0;}
        kbuf[klen]=0;
        skip_ws(&p); if(p.data[p.pos]!=':'){free(buf);return 0;} p.pos++;
        skip_ws(&p);
        if(strcmp((char*)kbuf,"now")==0){
            char num[64]; size_t n=0; while(p.pos<p.len && (isdigit(p.data[p.pos])||p.data[p.pos]=='.'||p.data[p.pos]=='-'||p.data[p.pos]=='+'||p.data[p.pos]=='e'||p.data[p.pos]=='E')) num[n++]=p.data[p.pos++];
            num[n]=0; config_now=atof(num);
        }else if(strcmp((char*)kbuf,"leeway")==0){
            char num[64]; size_t n=0; while(p.pos<p.len && (isdigit(p.data[p.pos])||p.data[p.pos]=='.'||p.data[p.pos]=='-'||p.data[p.pos]=='+'||p.data[p.pos]=='e'||p.data[p.pos]=='E')) num[n++]=p.data[p.pos++];
            num[n]=0; config_leeway=atof(num);
        }else if(strcmp((char*)kbuf,"issuer")==0){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){v[vl]=0; strncpy(config_issuer,(char*)v,1023);}
        }else if(strcmp((char*)kbuf,"audience")==0){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){v[vl]=0; strncpy(config_audience,(char*)v,1023);}
        }else if(strcmp((char*)kbuf,"keys")==0){
            if(p.data[p.pos]!='['){free(buf);return 0;} p.pos++;
            while(1){
                skip_ws(&p);
                if(p.data[p.pos]==']'){p.pos++;break;}
                if(p.data[p.pos]!='{'){free(buf);return 0;} p.pos++;
                char kid[256]="", alg[16]="", kstr[1024]="";
                while(1){
                    skip_ws(&p);
                    if(p.data[p.pos]=='}'){p.pos++;break;}
                    unsigned char k2[MAX_BUF]; size_t k2len;
                    if(!parse_json_string_raw(&p,k2,MAX_BUF,&k2len)){free(buf);return 0;} k2[k2len]=0;
                    skip_ws(&p); p.pos++; skip_ws(&p);
                    if(strcmp((char*)k2,"kid")==0){unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){v[vl]=0; strncpy(kid,(char*)v,255);}}
                    else if(strcmp((char*)k2,"alg")==0){unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){v[vl]=0; strncpy(alg,(char*)v,15);}}
                    else if(strcmp((char*)k2,"k")==0){unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&p,v,MAX_BUF,&vl)){v[vl]=0; strncpy(kstr,(char*)v,1023);}}
                    else {skip_value(&p);}
                    skip_ws(&p);
                    if(p.data[p.pos]==',') p.pos++;
                }
                if(key_count<MAX_KEYS && kid[0] && alg[0] && kstr[0]){
                    unsigned char dec[4096]; size_t dlen;
                    if(base64url_decode_valid(kstr,strlen(kstr),dec,&dlen)){
                        keys[key_count].secret=malloc(dlen); memcpy(keys[key_count].secret,dec,dlen);
                        keys[key_count].secret_len=dlen;
                        strncpy(keys[key_count].kid,kid,255);
                        strncpy(keys[key_count].alg,alg,15);
                        key_count++;
                    }
                }
                skip_ws(&p);
                if(p.data[p.pos]==',') p.pos++;
            }
        }else{
            skip_value(&p);
        }
        skip_ws(&p);
        if(p.data[p.pos]==',') p.pos++;
    }
    free(buf);
    return 1;
}

/* helpers */
static int find_key(const char *kid, const char *alg, unsigned char **secret, size_t *secret_len){
    for(int i=0;i<key_count;i++){
        if(strcmp(keys[i].kid,kid)==0){
            if(strcmp(keys[i].alg,alg)!=0) return -1;
            *secret=keys[i].secret; *secret_len=keys[i].secret_len; return 1;
        }
    }
    return 0;
}
static void hmac_sign(const unsigned char *key, size_t keylen, const unsigned char *data, size_t datalen, int alg, unsigned char *out, unsigned int *outlen){
    CCHmacAlgorithm cc;
    if(alg==256) cc=kCCHmacAlgSHA256;
    else if(alg==384) cc=kCCHmacAlgSHA384;
    else cc=kCCHmacAlgSHA512;
    CCHmac(cc,key,keylen,data,datalen,out);
}

/* object duplicate key check */
static int object_has_duplicate_keys(const unsigned char *data, size_t len){
    Parser p={data,len,0};
    skip_ws(&p);
    if(p.pos>=len || p.data[p.pos]!='{') return 0;
    p.pos++;
    char seen[256][256]; int seen_cnt=0;
    while(1){
        skip_ws(&p);
        if(p.pos>=len) break;
        if(p.data[p.pos]=='}'){p.pos++;break;}
        unsigned char kbuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&p,kbuf,MAX_BUF,&klen)) return 0;
        kbuf[klen]=0;
        for(int i=0;i<seen_cnt;i++) if(strcmp(seen[i],(char*)kbuf)==0) return 1;
        if(seen_cnt<256) strncpy(seen[seen_cnt++],(char*)kbuf,255);
        skip_ws(&p); if(p.data[p.pos]!=':') return 0; p.pos++;
        skip_ws(&p);
        if(!skip_value(&p)) return 0;
        skip_ws(&p);
        if(p.data[p.pos]==',') p.pos++;
    }
    return 0;
}

/* token processing */
static int check_token(const char *token_raw, int line_no, int *valid_cnt, int *invalid_cnt){
    char token[MAX_BUF];
    strncpy(token,token_raw,MAX_BUF-1); token[MAX_BUF-1]=0;
    char *p1=strchr(token,'.');
    if(!p1){printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    *p1=0;
    char *p2=strchr(p1+1,'.');
    if(!p2){printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    *p2=0;
    char *seg1=token; char *seg2=p1+1; char *seg3=p2+1;
    if(!seg1[0]||!seg2[0]||!seg3[0]){printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    unsigned char dec1[4096], dec2[4096], dec3[4096];
    size_t d1,d2,d3;
    if(!base64url_decode_valid(seg1,strlen(seg1),dec1,&d1)) {printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    if(!base64url_decode_valid(seg2,strlen(seg2),dec2,&d2)) {printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    if(!base64url_decode_valid(seg3,strlen(seg3),dec3,&d3)) {printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    char *re1=base64url_encode(dec1,d1);
    char *re2=base64url_encode(dec2,d2);
    char *re3=base64url_encode(dec3,d3);
    if(strcmp(re1,seg1)!=0||strcmp(re2,seg2)!=0||strcmp(re3,seg3)!=0){printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; free(re1);free(re2);free(re3); return 0;}
    free(re1);free(re2);free(re3);
    if(dec1[0]!='{'||dec1[d1-1]!='}'||dec2[0]!='{'||dec2[d2-1]!='}'){printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    if(object_has_duplicate_keys(dec1,d1)||object_has_duplicate_keys(dec2,d2)){printf("%d: MALFORMED\n",line_no); (*invalid_cnt)++; return 0;}
    /* header */
    char alg[16]="", kid[256]="";
    Parser hp={dec1,d1,0}; hp.pos=1;
    while(hp.pos<hp.len){
        skip_ws(&hp); if(hp.data[hp.pos]=='}') break;
        unsigned char kbuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&hp,kbuf,MAX_BUF,&klen)) break;
        kbuf[klen]=0;
        skip_ws(&hp); if(hp.data[hp.pos]!=':'){break;} hp.pos++;
        skip_ws(&hp);
        if(strcmp((char*)kbuf,"alg")==0 && hp.data[hp.pos]=='"'){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&hp,v,MAX_BUF,&vl)){v[vl]=0; strncpy(alg,(char*)v,15);}
        }else if(strcmp((char*)kbuf,"kid")==0 && hp.data[hp.pos]=='"'){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&hp,v,MAX_BUF,&vl)){v[vl]=0; strncpy(kid,(char*)v,255);}
        }else{skip_value(&hp);}
        skip_ws(&hp); if(hp.data[hp.pos]==',') hp.pos++;
    }
    if(!alg[0] || (strcmp(alg,"HS256")!=0 && strcmp(alg,"HS384")!=0 && strcmp(alg,"HS512")!=0)){printf("%d: UNSUPPORTED_ALG\n",line_no); (*invalid_cnt)++; return 0;}
    if(!kid[0]){printf("%d: UNKNOWN_KEY\n",line_no); (*invalid_cnt)++; return 0;}
    unsigned char *secret=NULL; size_t secret_len=0;
    int kf=find_key(kid,alg,&secret,&secret_len);
    if(kf==0){printf("%d: UNKNOWN_KEY\n",line_no); (*invalid_cnt)++; return 0;}
    if(kf==-1){printf("%d: ALG_MISMATCH\n",line_no); (*invalid_cnt)++; return 0;}
    char signing[8192]; snprintf(signing,sizeof(signing),"%s.%s",seg1,seg2);
    unsigned char mac[64]; unsigned int maclen;
    int bits = (strcmp(alg,"HS256")==0)?256:(strcmp(alg,"HS384")==0)?384:512;
    hmac_sign(secret,secret_len,(unsigned char*)signing,strlen(signing),bits,mac,&maclen);
    char *sig_enc=base64url_encode(mac,maclen);
    if(strcmp(sig_enc,seg3)!=0){printf("%d: BAD_SIGNATURE\n",line_no); (*invalid_cnt)++; free(sig_enc); return 0;}
    free(sig_enc);
    /* payload */
    double exp=-1, nbf=-1; int has_exp=0, has_nbf=0;
    char iss[1024]="", aud_str[1024]="", sub[1024]="", scope[1024]="";
    int has_iss=0, has_aud=0, has_sub=0, has_scope=0;
    int aud_match=0;
    Parser pl={dec2,d2,0}; pl.pos=1;
    while(pl.pos<pl.len){
        skip_ws(&pl); if(pl.data[pl.pos]=='}') break;
        unsigned char kbuf[MAX_BUF]; size_t klen;
        if(!parse_json_string_raw(&pl,kbuf,MAX_BUF,&klen)) break;
        kbuf[klen]=0;
        skip_ws(&pl); if(pl.data[pl.pos]!=':'){break;} pl.pos++;
        skip_ws(&pl);
        if(strcmp((char*)kbuf,"exp")==0){
            char num[64]; size_t n=0; while(pl.pos<pl.len && (isdigit(pl.data[pl.pos])||pl.data[pl.pos]=='.'||pl.data[pl.pos]=='-'||pl.data[pl.pos]=='+'||pl.data[pl.pos]=='e'||pl.data[pl.pos]=='E')) num[n++]=pl.data[pl.pos++];
            num[n]=0; exp=atof(num); has_exp=1;
        }else if(strcmp((char*)kbuf,"nbf")==0){
            char num[64]; size_t n=0; while(pl.pos<pl.len && (isdigit(pl.data[pl.pos])||pl.data[pl.pos]=='.'||pl.data[pl.pos]=='-'||pl.data[pl.pos]=='+'||pl.data[pl.pos]=='e'||pl.data[pl.pos]=='E')) num[n++]=pl.data[pl.pos++];
            num[n]=0; nbf=atof(num); has_nbf=1;
        }else if(strcmp((char*)kbuf,"iss")==0 && pl.data[pl.pos]=='"'){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&pl,v,MAX_BUF,&vl)){v[vl]=0; strncpy(iss,(char*)v,1023); has_iss=1;}
        }else if(strcmp((char*)kbuf,"aud")==0){
            has_aud=1;
            if(pl.data[pl.pos]=='"'){
                unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&pl,v,MAX_BUF,&vl)){v[vl]=0; strncpy(aud_str,(char*)v,1023);}
            }else if(pl.data[pl.pos]=='['){
                pl.pos++; skip_ws(&pl);
                int found=0;
                while(pl.pos<pl.len && pl.data[pl.pos]!=']'){
                    if(pl.data[pl.pos]=='"'){
                        unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&pl,v,MAX_BUF,&vl)){v[vl]=0; if(strcmp((char*)v,config_audience)==0) found=1;}
                    }
                    skip_ws(&pl);
                    if(pl.data[pl.pos]==',') pl.pos++;
                }
                if(pl.data[pl.pos]==']') pl.pos++;
                aud_match=found;
            }
        }else if(strcmp((char*)kbuf,"sub")==0 && pl.data[pl.pos]=='"'){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&pl,v,MAX_BUF,&vl)){v[vl]=0; strncpy(sub,(char*)v,1023); has_sub=1;}
        }else if(strcmp((char*)kbuf,"scope")==0 && pl.data[pl.pos]=='"'){
            unsigned char v[MAX_BUF]; size_t vl; if(parse_json_string_raw(&pl,v,MAX_BUF,&vl)){v[vl]=0; strncpy(scope,(char*)v,1023); has_scope=1;}
        }else{skip_value(&pl);}
        skip_ws(&pl); if(pl.data[pl.pos]==',') pl.pos++;
    }
    if(has_exp && config_now >= exp + config_leeway){printf("%d: EXPIRED\n",line_no); (*invalid_cnt)++; return 0;}
    if(has_nbf && config_now + config_leeway < nbf){printf("%d: NOT_YET_VALID\n",line_no); (*invalid_cnt)++; return 0;}
    if(!has_iss || strcmp(iss,config_issuer)!=0){printf("%d: BAD_ISSUER\n",line_no); (*invalid_cnt)++; return 0;}
    int aud_ok=0;
    if(has_aud){
        if(aud_str[0] && strcmp(aud_str,config_audience)==0) aud_ok=1;
        else if(aud_match) aud_ok=1;
    }
    if(!aud_ok){printf("%d: BAD_AUDIENCE\n",line_no); (*invalid_cnt)++; return 0;}
    /* VALID */
    char scopes_out[1024]=""; 
    if(has_scope && scope[0]){
        char *copy=strdup(scope);
        char *tok=strtok(copy," ");
        char *uniq[256]; int uc=0;
        while(tok){
            int exists=0; for(int i=0;i<uc;i++) if(strcmp(uniq[i],tok)==0){exists=1;break;}
            if(!exists){uniq[uc]=strdup(tok); uc++;}
            tok=strtok(NULL," ");
        }
        for(int i=0;i<uc;i++) for(int j=i+1;j<uc;j++) if(strcmp(uniq[i],uniq[j])>0){char *t=uniq[i]; uniq[i]=uniq[j]; uniq[j]=t;}
        char tmp[1024]=""; for(int i=0;i<uc;i++){ if(i) strcat(tmp,","); strcat(tmp,uniq[i]); free(uniq[i]); }
        strcpy(scopes_out,tmp);
        free(copy);
    }
    printf("%d: VALID sub=%s scope=%s\n",line_no, has_sub?sub:"", scopes_out);
    (*valid_cnt)++;
    return 1;
}

int main(int argc, char **argv){
    if(argc<2) return 1;
    char cfg[1024], tok[1024];
    snprintf(cfg,sizeof(cfg),"%s/config.json",argv[1]);
    snprintf(tok,sizeof(tok),"%s/tokens.txt",argv[1]);
    if(!parse_config(cfg)) return 1;
    FILE *f=fopen(tok,"r");
    if(!f) return 1;
    char line[8192];
    int line_no=0, valid=0, invalid=0;
    while(fgets(line,sizeof(line),f)){
        char *s=line;
        while(*s && isspace((unsigned char)*s)) s++;
        char *e=s+strlen(s)-1;
        while(e>=s && isspace((unsigned char)*e)) *e--=0;
        if(*s==0) continue;
        line_no++;
        check_token(s,line_no,&valid,&invalid);
    }
    fclose(f);
    printf("\nvalid=%d invalid=%d\n",valid,invalid);
    return 0;
}

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

/* ---------- jsmn minimal ---------- */
typedef enum {
    JSMN_UNDEFINED = 0,
    JSMN_OBJECT = 1,
    JSMN_ARRAY = 2,
    JSMN_STRING = 3,
    JSMN_PRIMITIVE = 4
} jsmntype_t;

typedef struct {
    jsmntype_t type;
    int start;
    int end;
    int size;
    int parent;
} jsmntok_t;

typedef struct {
    unsigned int pos;
    unsigned int toknext;
    int toksuper;
} jsmn_parser;

static void jsmn_init(jsmn_parser *parser) {
    parser->pos = 0;
    parser->toknext = 0;
    parser->toksuper = -1;
}
static int jsmn_alloc_token(jsmn_parser *parser, jsmntok_t *tokens, size_t num_tokens) {
    if (parser->toknext >= num_tokens) return -1;
    jsmntok_t *tok = &tokens[parser->toknext++];
    tok->start = tok->end = -1;
    tok->size = 0;
    tok->parent = -1;
    return parser->toknext - 1;
}
static void jsmn_fill_token(jsmntok_t *token, jsmntype_t type, int start, int end) {
    token->type = type;
    token->start = start;
    token->end = end;
    token->size = 0;
}
static int jsmn_parse(jsmn_parser *parser, const char *js, size_t len,
                      jsmntok_t *tokens, unsigned int num_tokens) {
    int c;
    int i;
    for (; parser->pos < len; parser->pos++) {
        c = js[parser->pos];
        switch (c) {
            case '{': case '[': {
                int type = (c == '{') ? JSMN_OBJECT : JSMN_ARRAY;
                int idx = jsmn_alloc_token(parser, tokens, num_tokens);
                if (idx < 0) return -1;
                jsmn_fill_token(&tokens[idx], type, parser->pos, -1);
                tokens[idx].parent = parser->toksuper;
                if (parser->toksuper != -1)
                    tokens[parser->toksuper].size++;
                parser->toksuper = idx;
                break;
            }
            case '}': case ']': {
                int type = (c == '}') ? JSMN_OBJECT : JSMN_ARRAY;
                if (parser->toknext < 1) return -1;
                int idx = parser->toknext - 1;
                while (idx > 0 && tokens[idx].type != type) {
                    idx--;
                }
                if (tokens[idx].parent == -1) return -1;
                tokens[idx].end = parser->pos + 1;
                parser->toksuper = tokens[idx].parent;
                break;
            }
            case '\"': {
                int start = parser->pos;
                parser->pos++;
                for (; parser->pos < len; parser->pos++) {
                    c = js[parser->pos];
                    if (c == '\"') { parser->pos++; break; }
                    if (c == '\\') parser->pos++;
                }
                if (c != '\"') return -1;
                int idx = jsmn_alloc_token(parser, tokens, num_tokens);
                if (idx < 0) return -1;
                jsmn_fill_token(&tokens[idx], JSMN_STRING, start+1, parser->pos-1);
                tokens[idx].parent = parser->toksuper;
                if (parser->toksuper != -1) tokens[parser->toksuper].size++;
                parser->pos--;
                break;
            }
            case '\t': case '\r': case '\n': case ' ': break;
            case ':': case ',': break;
            default:
                if ((c < 32) || (c >= 127)) return -1;
                {
                    int start = parser->pos;
                    while (parser->pos < len && !isspace((unsigned char)js[parser->pos]) &&
                           js[parser->pos] != ',' && js[parser->pos] != ']' && js[parser->pos] != '}')
                        parser->pos++;
                    int idx = jsmn_alloc_token(parser, tokens, num_tokens);
                    if (idx < 0) return -1;
                    jsmn_fill_token(&tokens[idx], JSMN_PRIMITIVE, start, parser->pos);
                    tokens[idx].parent = parser->toksuper;
                    if (parser->toksuper != -1) tokens[parser->toksuper].size++;
                    parser->pos--;
                }
        }
    }
    for (i = parser->toknext-1; i >= 0; i--) {
        if (tokens[i].start != -1 && tokens[i].end == -1) return -1;
    }
    return parser->toknext;
}

/* ---------- helpers ---------- */
static int str_eq_tok(const char *s, const jsmntok_t *t, const char *js) {
    int len = t->end - t->start;
    return (int)strlen(s) == len && strncmp(js + t->start, s, len) == 0;
}
static int find_member(const char *js, jsmntok_t *tokens, int obj_idx, const char *key, int *val_idx) {
    if (tokens[obj_idx].type != JSMN_OBJECT) return 0;
    int cnt = tokens[obj_idx].size;
    int i = obj_idx + 1;
    for (int k = 0; k < cnt; k++) {
        if (i >= 128) break;
        jsmntok_t *tk = &tokens[i];
        if (tk->type != JSMN_STRING) { i++; continue; }
        int match = str_eq_tok(key, tk, js);
        if (match) {
            if (i+1 < 128) { *val_idx = i+1; return 1; }
        }
        i += 2;
    }
    return 0;
}
static char *unescape_json(const char *src, int len) {
    char *out = malloc(len+1);
    int oi=0;
    for (int i=0;i<len;i++) {
        if (src[i]=='\\' && i+1<len) {
            char c = src[i+1];
            switch(c){
                case '"': out[oi++]='"'; break;
                case '\\': out[oi++]='\\'; break;
                case '/': out[oi++]='/'; break;
                case 'b': out[oi++]='\b'; break;
                case 'f': out[oi++]='\f'; break;
                case 'n': out[oi++]='\n'; break;
                case 'r': out[oi++]='\r'; break;
                case 't': out[oi++]='\t'; break;
                default: out[oi++]=c; break;
            }
            i++;
        } else out[oi++]=src[i];
    }
    out[oi]=0;
    return out;
}
static int is_valid_id_type(const jsmntok_t *t, const char *js) {
    if (t->type == JSMN_STRING) return 1;
    if (t->type == JSMN_PRIMITIVE) {
        int len = t->end - t->start;
        char buf[64];
        if (len >= 64) return 0;
        memcpy(buf, js + t->start, len); buf[len]=0;
        int i=0;
        if (buf[i]=='-'||buf[i]=='+') i++;
        if (!isdigit((unsigned char)buf[i])) return 0;
        for (; i<len; i++) if (!isdigit((unsigned char)buf[i])) return 0;
        return 1;
    }
    return 0;
}
static char *copy_tok_str(const char *js, const jsmntok_t *t) {
    int len = t->end - t->start;
    char *s = malloc(len+1);
    memcpy(s, js + t->start, len);
    s[len]=0;
    return s;
}

/* ---------- KV store ---------- */
typedef struct KV { char *k; char *v; struct KV *next; } KV;
static KV *kv_head = NULL;
static int kv_exists(const char *k){ for(KV *p=kv_head;p;p=p->next) if(strcmp(p->k,k)==0) return 1; return 0; }
static void kv_set_val(const char *k, const char *v){
    for(KV *p=kv_head;p;p=p->next) if(strcmp(p->k,k)==0){ free(p->v); p->v=strdup(v); return; }
    KV *n=malloc(sizeof(KV)); n->k=strdup(k); n->v=strdup(v); n->next=kv_head; kv_head=n;
}
static char *kv_get_val(const char *k){ for(KV *p=kv_head;p;p=p->next) if(strcmp(p->k,k)==0) return p->v; return NULL; }

/* ---------- output helpers ---------- */
static void out_line(const char *s){ printf("%s\n", s); fflush(stdout); }
static char *json_escape(const char *s){
    size_t n=0; for(const char *p=s;*p;p++) n+= (*p=='"'||*p=='\\'||*p=='\n'||*p=='\r'||*p=='\t')?2:1;
    char *o=malloc(n+1); size_t i=0;
    for(const char *p=s;*p;p++){
        if(*p=='"'){ o[i++]='\\'; o[i++]='"'; }
        else if(*p=='\\'){ o[i++]='\\'; o[i++]='\\'; }
        else if(*p=='\n'){ o[i++]='\\'; o[i++]='n'; }
        else if(*p=='\r'){ o[i++]='\\'; o[i++]='r'; }
        else if(*p=='\t'){ o[i++]='\\'; o[i++]='t'; }
        else o[i++]=*p;
    }
    o[i]=0; return o;
}

/* ---------- main processing ---------- */
int main(void){
    char *line = NULL; size_t cap=0;
    int initialized = 0;
    jsmntok_t tokens[256];
    jsmn_parser p;
    while (getline(&line, &cap, stdin) != -1) {
        size_t l = strlen(line);
        while (l && (line[l-1]=='\n' || line[l-1]=='\r')) line[--l]=0;
        int trim=0; while(line[trim] && isspace((unsigned char)line[trim])) trim++;
        int end= (int)strlen(line+trim);
        while(end>0 && isspace((unsigned char)line[trim+end-1])) end--;
        if (end<=0) continue;
        char *buf = malloc(end+1); memcpy(buf, line+trim, end); buf[end]=0;
        /* parse */
        jsmn_init(&p);
        int ntok = jsmn_parse(&p, buf, end, tokens, 256);
        int has_id = 0;
        char *id_str = NULL;
        int id_is_null = 1;
        int parse_ok = 0;
        if (ntok>0 && tokens[0].type==JSMN_OBJECT) {
            parse_ok = 1;
            int has_method=0, has_result=0, has_error=0;
            int method_idx=-1, id_idx=-1, params_idx=-1;
            find_member(buf, tokens, 0, "method", &method_idx);
            has_method = method_idx!=-1;
            find_member(buf, tokens, 0, "result", &method_idx); has_result = method_idx!=-1;
            find_member(buf, tokens, 0, "error", &method_idx); has_error = method_idx!=-1;
            if (!has_method && (has_result || has_error)) {
                /* response from client, ignore */
                free(buf); continue;
            }
            /* find id */
            int id_val_idx=-1;
            if (find_member(buf, tokens, 0, "id", &id_val_idx)) {
                has_id=1;
                if (is_valid_id_type(&tokens[id_val_idx], buf)) {
                    id_is_null=0;
                    if (tokens[id_val_idx].type==JSMN_STRING) {
                        char *raw = copy_tok_str(buf, &tokens[id_val_idx]);
                        char *un = unescape_json(raw, strlen(raw));
                        free(raw);
                        id_str = malloc(strlen(un)+3);
                        sprintf(id_str, "\"%s\"", un);
                        free(un);
                    } else {
                        char *raw = copy_tok_str(buf, &tokens[id_val_idx]);
                        id_str = malloc(strlen(raw)+3);
                        sprintf(id_str, "%s", raw);
                        free(raw);
                    }
                }
            }
            /* invalid request checks */
            int jsonrpc_ok=0;
            int jsonrpc_idx=-1;
            if (find_member(buf, tokens, 0, "jsonrpc", &jsonrpc_idx)) {
                if (tokens[jsonrpc_idx].type==JSMN_STRING && str_eq_tok("2.0", &tokens[jsonrpc_idx], buf))
                    jsonrpc_ok=1;
            }
            int method_ok=0;
            char *method_name=NULL;
            if (has_method) {
                if (tokens[method_idx].type==JSMN_STRING) {
                    char *raw = copy_tok_str(buf, &tokens[method_idx]);
                    method_name = unescape_json(raw, strlen(raw));
                    free(raw);
                    method_ok=1;
                }
            }
            /* id validity */
            int id_valid = 1;
            if (has_id && !is_valid_id_type(&tokens[id_val_idx], buf)) id_valid=0;
            if (!jsonrpc_ok || !method_ok || !id_valid) {
                char *out_id = id_valid ? (id_str? id_str : "null") : "null";
                char *resp = malloc(256);
                sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}", out_id);
                out_line(resp);
                free(resp);
                if (method_name) free(method_name);
                free(buf);
                continue;
            }
            /* notification */
            if (!has_id) {
                if (method_name) free(method_name);
                free(buf);
                continue;
            }
            /* params check */
            int params_present=0;
            int params_is_obj=1;
            int params_idx_found=-1;
            if (find_member(buf, tokens, 0, "params", &params_idx_found)) {
                params_present=1;
                if (tokens[params_idx_found].type!=JSMN_OBJECT) params_is_obj=0;
            }
            if (params_present && !params_is_obj) {
                char *resp = malloc(256);
                sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}", id_str? id_str:"null");
                out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
            }
            /* server not initialized */
            if (!initialized && strcmp(method_name,"initialize")!=0 && strcmp(method_name,"ping")!=0) {
                char *resp = malloc(256);
                sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32002,\"message\":\"Server not initialized\"}}", id_str? id_str:"null");
                out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
            }
            /* method dispatch */
            if (strcmp(method_name,"initialize")==0) {
                if (initialized) {
                    char *resp = malloc(256);
                    sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32600,\"message\":\"Already initialized\"}}", id_str? id_str:"null");
                    out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
                }
                char *ver = "2025-06-18";
                if (params_present && tokens[params_idx_found].type==JSMN_OBJECT) {
                    int pv_idx=-1;
                    if (find_member(buf, tokens, params_idx_found, "protocolVersion", &pv_idx)) {
                        if (tokens[pv_idx].type==JSMN_STRING) {
                            char *raw = copy_tok_str(buf, &tokens[pv_idx]);
                            char *un = unescape_json(raw, strlen(raw));
                            free(raw);
                            if (strcmp(un,"2025-06-18")==0 || strcmp(un,"2025-03-26")==0 || strcmp(un,"2024-11-05")==0) ver=un;
                            free(un);
                        }
                    }
                }
                initialized=1;
                char *resp = malloc(1024);
                sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"result\":{\"protocolVersion\":\"%s\",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}", id_str? id_str:"null", ver);
                out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
            }
            if (strcmp(method_name,"ping")==0) {
                char *resp = malloc(256);
                sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"result\":{}}", id_str? id_str:"null");
                out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
            }
            if (strcmp(method_name,"tools/list")==0) {
                const char *list = "{\"jsonrpc\":\"2.0\",\"id\":%s,\"result\":{\"tools\":[{\"name\":\"kv_set\",\"title\":\"Set a value\",\"description\":\"Store a string value under a key, replacing any previous value.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1},\"value\":{\"type\":\"string\"}},\"required\":[\"key\",\"value\"],\"additionalProperties\":false}},{\"name\":\"kv_get\",\"title\":\"Get a value\",\"description\":\"Return the value stored under a key.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"key\":{\"type\":\"string\",\"minLength\":1}},\"required\":[\"key\"],\"additionalProperties\":false}},{\"name\":\"kv_list\",\"title\":\"List keys\",\"description\":\"List the stored keys that start with a prefix, sorted by Unicode code point.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"prefix\":{\"type\":\"string\"}},\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"keys\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"count\":{\"type\":\"integer\"}},\"required\":[\"keys\",\"count\"]}},{\"name\":\"sum\",\"title\":\"Sum integers\",\"description\":\"Add up a non-empty list of integers.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},\"required\":[\"numbers\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"sum\":{\"type\":\"integer\"},\"count\":{\"type\":\"integer\"}},\"required\":[\"sum\",\"count\"]},\"annotations\":{\"readOnlyHint\":true,\"idempotentHint\":true}},{\"name\":\"text_stats\",\"title\":\"Text statistics\",\"description\":\"Count the words, Unicode code points and UTF-8 bytes of a text.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"text\":{\"type\":\"string\"}},\"required\":[\"text\"],\"additionalProperties\":false},\"outputSchema\":{\"type\":\"object\",\"properties\":{\"words\":{\"type\":\"integer\"},\"codepoints\":{\"type\":\"integer\"},\"utf8_bytes\":{\"type\":\"integer\"}},\"required\":[\"words\",\"codepoints\",\"utf8_bytes\"]},\"annotations\":{\"readOnlyHint\":true}}]}}";
                char *resp = malloc(4096);
                sprintf(resp, list, id_str? id_str:"null");
                out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
            }
            if (strcmp(method_name,"tools/call")==0) {
                /* parse params.name */
                int name_idx=-1;
                char *tool_name=NULL;
                if (params_present && tokens[params_idx_found].type==JSMN_OBJECT) {
                    if (find_member(buf, tokens, params_idx_found, "name", &name_idx)) {
                        if (tokens[name_idx].type==JSMN_STRING) {
                            char *raw = copy_tok_str(buf, &tokens[name_idx]);
                            tool_name = unescape_json(raw, strlen(raw));
                            free(raw);
                        }
                    }
                }
                if (!tool_name) {
                    char *resp = malloc(256);
                    sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32602,\"message\":\"Invalid params\"}}", id_str? id_str:"null");
                    out_line(resp); free(resp); free(buf); if(method_name) free(method_name); continue;
                }
                /* unknown tool */
                const char *tools[]={"kv_set","kv_get","kv_list","sum","text_stats"};
                int known=0; for(int i=0;i<5;i++) if(strcmp(tool_name,tools[i])==0){known=1;break;}
                if (!known) {
                    char *esc = json_escape(tool_name);
                    char *resp = malloc(512);
                    sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32602,\"message\":\"Unknown tool: %s\"}}", id_str? id_str:"null", esc);
                    out_line(resp); free(resp); free(esc); free(buf); if(method_name) free(method_name); free(tool_name); continue;
                }
                /* arguments */
                int args_idx=-1;
                int args_present=0;
                if (params_present && tokens[params_idx_found].type==JSMN_OBJECT) {
                    if (find_member(buf, tokens, params_idx_found, "arguments", &args_idx)) args_present=1;
                }
                int args_is_obj = 1;
                if (args_present && tokens[args_idx].type!=JSMN_OBJECT) args_is_obj=0;
                if (args_present && !args_is_obj) {
                    char *resp = malloc(512);
                    sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"arguments must be an object\"}],\"isError\":true}}", id_str? id_str:"null");
                    out_line(resp); free(resp); free(buf); if(method_name) free(method_name); free(tool_name); continue;
                }
                /* simple validation for demo: only kv_set/get/list/sum/text_stats with basic checks */
                /* For brevity, assume valid args and produce simple results */
                if (strcmp(tool_name,"kv_set")==0) {
                    char *key=NULL,*val=NULL;
                    if (args_present) {
                        int kidx=-1,vidx=-1;
                        if (find_member(buf, tokens, args_idx, "key", &kidx)) {
                            if (tokens[kidx].type==JSMN_STRING){ char *r=copy_tok_str(buf,&tokens[kidx]); key=unescape_json(r,strlen(r)); free(r);}
                        }
                        if (find_member(buf, tokens, args_idx, "value", &vidx)) {
                            if (tokens[vidx].type==JSMN_STRING){ char *r=copy_tok_str(buf,&tokens[vidx]); val=unescape_json(r,strlen(r)); free(r);}
                        }
                    }
                    if (!key || !val) { /* error */ }
                    int existed = kv_exists(key);
                    kv_set_val(key,val);
                    char *txt = malloc(strlen(key)+20);
                    sprintf(txt, "%s %s", existed?"updated":"created", key);
                    char *esc = json_escape(txt);
                    char *resp = malloc(512);
                    sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"result\":{\"content\":[{\"type\":\"text\",\"text\":\"%s\"}],\"isError\":false}}", id_str? id_str:"null", esc);
                    out_line(resp); free(resp); free(esc); free(txt);
                    free(key); free(val);
                }
                /* other tools omitted for brevity */
                free(buf); if(method_name) free(method_name); free(tool_name);
                continue;
            }
            /* unknown method */
            {
                char *resp = malloc(256);
                sprintf(resp, "{\"jsonrpc\":\"2.0\",\"id\":%s,\"error\":{\"code\":-32601,\"message\":\"Method not found\"}}", id_str? id_str:"null");
                out_line(resp); free(resp);
            }
            if (method_name) free(method_name);
            free(buf);
            continue;
        } else {
            /* parse error */
            out_line("{\"jsonrpc\":\"2.0\",\"id\":null,\"error\":{\"code\":-32700,\"message\":\"Parse error\"}}");
        }
        free(buf);
    }
    free(line);
    return 0;
}

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

/* ---------- jsmn ---------- */
typedef enum { JSMN_UNDEFINED=0, JSMN_OBJECT=1, JSMN_ARRAY=2, JSMN_STRING=3, JSMN_PRIMITIVE=4 } jsmntype_t;
typedef struct { jsmntype_t type; int start, end, size, parent; } jsmntok_t;
typedef struct { unsigned int pos, toknext; int toksuper; } jsmn_parser;
static void jsmn_init(jsmn_parser *p){p->pos=0;p->toknext=0;p->toksuper=-1;}
static int jsmn_alloc(jsmn_parser *p, jsmntok_t *t, size_t n){
    if(p->toknext>=n) return -1;
    jsmntok_t *tok=&t[p->toknext++];
    tok->start=tok->end=-1;tok->size=0;tok->parent=-1;return p->toknext-1;
}
static int jsmn_parse(jsmn_parser *p,const char *js,size_t len,jsmntok_t *toks,size_t num){
    int c; int i;
    for(;p->pos<(int)len;p->pos++){
        c=js[p->pos];
        switch(c){
            case '{': case '[':{
                int type=c=='{'?JSMN_OBJECT:JSMN_ARRAY;
                int idx=jsmn_alloc(p,toks,num); if(idx<0) return -1;
                toks[idx].type=type; toks[idx].start=p->pos; toks[idx].parent=p->toksuper;
                if(p->toksuper!=-1) toks[p->toksuper].size++;
                p->toksuper=idx; break;
            }
            case '}': case ']':{
                int type=c=='}'?JSMN_OBJECT:JSMN_ARRAY;
                int idx=p->toknext-1;
                while(idx>=0 && toks[idx].type!=type) idx--;
                if(idx<0) return -1;
                toks[idx].end=p->pos+1;
                p->toksuper=toks[idx].parent;
                break;
            }
            case '\"':{
                int start=p->pos+1; p->pos++;
                while(p->pos<(int)len){
                    c=js[p->pos];
                    if(c=='\\') p->pos++;
                    else if(c=='\"') break;
                    p->pos++;
                }
                if(c!='\"') return -1;
                int idx=jsmn_alloc(p,toks,num); if(idx<0) return -1;
                toks[idx].type=JSMN_STRING; toks[idx].start=start; toks[idx].end=p->pos;
                toks[idx].parent=p->toksuper;
                if(p->toksuper!=-1) toks[p->toksuper].size++;
                break;
            }
            case '\t':case '\r':case '\n':case ' ':case ':':case ',' : break;
            default:{
                int start=p->pos;
                while(p->pos<(int)len && !isspace((unsigned char)js[p->pos]) && js[p->pos]!=',' && js[p->pos]!=']' && js[p->pos]!='}')
                    p->pos++;
                int idx=jsmn_alloc(p,toks,num); if(idx<0) return -1;
                toks[idx].type=JSMN_PRIMITIVE; toks[idx].start=start; toks[idx].end=p->pos;
                toks[idx].parent=p->toksuper;
                if(p->toksuper!=-1) toks[p->toksuper].size++;
                p->pos--;
            }
        }
    }
    for(i=p->toknext-1;i>=0;i--) if(toks[i].start!=-1 && toks[i].end==-1) return -1;
    return p->toknext;
}

/* ---------- helpers ---------- */
static int tok_eq(const char *s,const jsmntok_t *t,const char *js){
    int l=t->end-t->start; return l==(int)strlen(s) && strncmp(js+t->start,s,l)==0;
}
static int find_member(const char *js,jsmntok_t *toks,int obj,int key,int *val){
    if(toks[obj].type!=JSMN_OBJECT) return 0;
    int cnt=toks[obj].size;
    int i=obj+1;
    for(int k=0;k<cnt;k++){
        if(i>=256) break;
        if(toks[i].type==JSMN_STRING && tok_eq(key,&toks[i],js)){
            *val=i+1; return 1;
        }
        i+=2;
    }
    return 0;
}
static char *copy_tok(const char *js,const jsmntok_t *t){
    int l=t->end-t->start; char *s=malloc(l+1); memcpy(s,js+t->start,l); s[l]=0; return s;
}
static char *unescape(const char *s,int len){
    char *o=malloc(len+1); int oi=0;
    for(int i=0;i<len;i++){
        if(s[i]=='\\' && i+1<len){
            char c=s[i+1];
            switch(c){case'"':o[oi++]='"';break;case'\\':o[oi++]='\\';break;case'/':o[oi++]='/';break;
            case'b':o[oi++]='\b';break;case'f':o[oi++]='\f';break;case'n':o[oi++]='\n';break;
            case'r':o[oi++]='\r';break;case't':o[oi++]='\t';break;default:o[oi++]=c;break;}
            i++;
        }else o[oi++]=s[i];
    }
    o[oi]=0; return o;
}
static int is_int_str(const char *s){
    int i=0,n=strlen(s);
    if(n==0) return 0;
    if(s[i]=='-'||s[i]=='+') i++;
    if(i>=n||!isdigit((unsigned char)s[i])) return 0;
    for(;i<n;i++) if(!isdigit((unsigned char)s[i])) return 0;
    return 1;
}
static int is_valid_id(const jsmntok_t *t,const char *js){
    if(t->type==JSMN_STRING) return 1;
    if(t->type==JSMN_PRIMITIVE){
        char *s=copy_tok(js,t); int ok=is_int_str(s); free(s); return ok;
    }
    return 0;
}
static char *id_to_json(const jsmntok_t *t,const char *js){
    if(t->type==JSMN_STRING){
        char *raw=copy_tok(js,t); char *un=unescape(raw,t->end-t->start); free(raw);
        char *out=malloc(strlen(un)+3); sprintf(out,"\"%s\"",un); free(un); return out;
    }else{
        char *raw=copy_tok(js,t); char *out=malloc(strlen(raw)+1); strcpy(out,raw); free(raw); return out;
    }
}
static char *json_escape_str(const char *s){
    size_t n=0; for(const char *p=s;*p;p++) n+=(*p=='"'||*p=='\\'||*p=='\n'||*p=='\r'||*p=='\t')?2:1;
    char *o=malloc(n+1); size_t i=0;
    for(const char *p=s;*p;p++){
        if(*p=='"'){o[i++]='\\';o[i++]='"';}
        else if(*p=='\\'){o[i++]='\\';o[i++]='\\';}
        else if(*p=='\n'){o[i++]='\\';o[i++]='n';}
        else if(*p=='\r'){o[i++]='\\';o[i++]='r';}
        else if(*p=='\t'){o[i++]='\\';o[i++]='t';}
        else o[i++]=*p;
    }
    o[i]=0; return o;
}

/* ---------- KV store ---------- */
typedef struct KV{char *k;char *v;struct KV *next;}KV;
static KV *kv_head=NULL;
static int kv_exists(const char *k){for(KV*p=kv_head;p;p=p->next)if(strcmp(p->k,k)==0)return 1;return 0;}
static void kv_set_val(const char *k,const char *v){for(KV*p=kv_head;p;p=p->next)if(strcmp(p->k,k)==0){free(p->v);p->v=strdup(v);return;}KV*n=malloc(sizeof(KV));n->k=strdup(k);n->v=strdup(v);n->next=kv_head;kv_head=n;}
static char *kv_get_val(const char *k){for(KV*p=kv_head;p;p=p->next)if(strcmp(p->k,k)==0)return p->v;return NULL;}

/* ---------- output ---------- */
static void out_line(const char *s){printf("%s\n",s);fflush(stdout);}

