use serde_json::{Value, json};
use std::collections::HashMap;
use std::io::{self, BufRead};

struct Server {
    initialized: bool,
    kv: HashMap<String, String>,
}

impl Server {
    fn new() -> Self {
        Self {
            initialized: false,
            kv: HashMap::new(),
        }
    }
}

fn is_valid_id(v: &Value) -> bool {
    match v {
        Value::String(_) => true,
        Value::Number(n) => n.is_i64().unwrap_or(false) || n.is_u64().unwrap_or(false),
        _ => false,
    }
}

