fn main() {
    let stdin = io::stdin();
    let mut server = Server::new();
    let mut out = Vec::new();

    for line in stdin.lock().lines() {
        let line = line.unwrap_or_default();
        let line = line.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        if let Some(resp) = handle_line(&line, &mut server) {
            out.push(serde_json::to_string(&resp).unwrap());
        }
    }
    for s in out {
        println!("{}", s);
    }
}

fn handle_line(line: &str, server: &mut Server) -> Option<Value> {
    let parsed = serde_json::from_str::<Value>(line);
    let id_for_error = |v: &Value| -> Value {
        if let Some(id) = v.get("id") {
            if is_valid_id(id) { id.clone() } else { Value::Null }
        } else { Value::Null }
    };

    let val = match parsed {
        Ok(v) => v,
        Err(_) => {
            return Some(json!({"jsonrpc":"2.0","id":null,"error":{"code":-32700,"message":"Parse error"}}));
        }
    };

    if !val.is_object() {
        return Some(json!({"jsonrpc":"2.0","id":null,"error":{"code":-32600,"message":"Invalid Request"}}));
    }
    let obj = val.as_object().unwrap().clone();

    if !obj.contains_key("method") && (obj.contains_key("result") || obj.contains_key("error")) {
        return None;
    }

    let jsonrpc_ok = obj.get("jsonrpc").and_then(|v| v.as_str()) == Some("2.0");
    let method_ok = obj.get("method").and_then(|v| v.as_str()).is_some();
    let id_val = obj.get("id");
    let id_invalid = id_val.map_or(false, |v| !is_valid_id(v));

    if !jsonrpc_ok || !method_ok || id_invalid {
        let id_out = if let Some(id) = id_val {
            if is_valid_id(id) { id.clone() } else { Value::Null }
        } else { Value::Null };
        return Some(json!({"jsonrpc":"2.0","id":id_out,"error":{"code":-32600,"message":"Invalid Request"}}));
    }

    let id = obj.get("id").cloned().unwrap_or(Value::Null);
    if id.is_null() {
        return None;
    }

    let method = obj.get("method").unwrap().as_str().unwrap().to_string();
    let params = obj.get("params");

    if params.is_some() && !params.unwrap().is_object() {
        return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32602,"message":"Invalid params"}}));
    }

    if !server.initialized && method != "initialize" && method != "ping" {
        return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32002,"message":"Server not initialized"}}));
    }

    match method.as_str() {
        "initialize" => {
            if server.initialized {
                return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32600,"message":"Already initialized"}}));
            }
            let params_obj = match params {
                Some(Value::Object(m)) => m,
                _ => {
                    return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32602,"message":"Invalid params"}}));
                }
            };
            let version = match params_obj.get("protocolVersion").and_then(|v| v.as_str()) {
                Some(v) => {
                    if ["2025-06-18","2025-03-26","2024-11-05"].contains(&v) { v.to_string() } else { "2025-06-18".to_string() }
                }
                None => {
                    return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32602,"message":"Invalid params"}}));
                }
            };
            server.initialized = true;
            let result = json!({
                "protocolVersion": version,
                "capabilities": {"tools": {"listChanged": false}},
                "serverInfo": {"name":"cb2-kv","title":"CB2 key-value server","version":"1.4.2"}
            });
            return Some(json!({"jsonrpc":"2.0","id":id,"result":result}));
        }
        "ping" => {
            return Some(json!({"jsonrpc":"2.0","id":id,"result":{}}));
        }
        "tools/list" => {
            let result = json!({"tools": tools_list()});
            return Some(json!({"jsonrpc":"2.0","id":id,"result":result}));
        }
        "tools/call" => {
            let params_obj = match params {
                Some(Value::Object(m)) => m,
                _ => {
                    return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32602,"message":"Invalid params"}}));
                }
            };
            let name = match params_obj.get("name").and_then(|v| v.as_str()) {
                Some(n) => n.to_string(),
                None => {
                    return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32602,"message":"Invalid params"}}));
                }
            };
            let allowed = ["kv_set","kv_get","kv_list","sum","text_stats"];
            if !allowed.contains(&name.as_str()) {
                return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32602,"message":format!("Unknown tool: {}", name)}}));
            }
            let args = params_obj.get("arguments").cloned().unwrap_or(Value::Object(Default::default()));
            if !args.is_object() {
                let res = json!({"content":[{"type":"text","text":"arguments must be an object"}],"isError":true});
                return Some(json!({"jsonrpc":"2.0","id":id,"result":res}));
            }
            let args_obj = args.as_object().unwrap();
            // validation
            if let Some(err_msg) = validate_tool(&name, args_obj) {
                let res = json!({"content":[{"type":"text","text":err_msg}],"isError":true});
                return Some(json!({"jsonrpc":"2.0","id":id,"result":res}));
            }
            let (text, structured) = match name.as_str() {
                "kv_set" => {
                    let key = args_obj.get("key").unwrap().as_str().unwrap();
                    let value = args_obj.get("value").unwrap().as_str().unwrap();
                    let created = !server.kv.contains_key(key);
                    server.kv.insert(key.to_string(), value.to_string());
                    let txt = if created { format!("created {}", key) } else { format!("updated {}", key) };
                    (txt, None)
                }
                "kv_get" => {
                    let key = args_obj.get("key").unwrap().as_str().unwrap();
                    match server.kv.get(key) {
                        Some(v) => (v.clone(), None),
                        None => {
                            let res = json!({"content":[{"type":"text","text":format!("key not found: {}", key)}],"isError":true});
                            return Some(json!({"jsonrpc":"2.0","id":id,"result":res}));
                        }
                    }
                }
                "kv_list" => {
                    let prefix = args_obj.get("prefix").and_then(|v| v.as_str()).unwrap_or("");
                    let mut keys: Vec<String> = server.kv.keys().filter(|k| k.starts_with(prefix)).cloned().collect();
                    keys.sort();
                    let cnt = keys.len();
                    let s = json!({"keys":keys,"count":cnt});
                    let txt = serde_json::to_string(&s).unwrap();
                    (txt, Some(s))
                }
                "sum" => {
                    let arr = args_obj.get("numbers").unwrap().as_array().unwrap();
                    let mut sum: i64 = 0;
                    for v in arr { sum += v.as_i64().unwrap(); }
                    let s = json!({"sum":sum,"count":arr.len()});
                    let txt = serde_json::to_string(&s).unwrap();
                    (txt, Some(s))
                }
                "text_stats" => {
                    let text_str = args_obj.get("text").unwrap().as_str().unwrap();
                    let codepoints = text_str.chars().count();
                    let utf8_bytes = text_str.len();
                    let words = text_str.split(|c| c==' '||c=='\t'||c=='\n'||c=='\r').filter(|s| !s.is_empty()).count();
                    let s = json!({"words":words,"codepoints":codepoints,"utf8_bytes":utf8_bytes});
                    let txt = serde_json::to_string(&s).unwrap();
                    (txt, Some(s))
                }
                _ => unreachable!()
            };
            let mut res = json!({"content":[{"type":"text","text":text}],"isError":false});
            if let Some(sc) = structured {
                if let Some(map) = res.as_object_mut() {
                    map.insert("structuredContent".to_string(), sc);
                }
            }
            return Some(json!({"jsonrpc":"2.0","id":id,"result":res}));
        }
        _ => {
            return Some(json!({"jsonrpc":"2.0","id":id,"error":{"code":-32601,"message":"Method not found"}}));
        }
    }
}

fn validate_tool(name: &str, args: &serde_json::Map<String, Value>) -> Option<String> {
    let props = match name {
        "kv_set" => vec![("key", true, "string", false), ("value", true, "string", false)],
        "kv_get" => vec![("key", true, "string", false)],
        "kv_list" => vec![("prefix", false, "string", false)],
        "sum" => vec![("numbers", true, "array_int", true)],
        "text_stats" => vec![("text", true, "string", false)],
        _ => return None,
    };
    // unknown args
    let allowed: std::collections::HashSet<_> = props.iter().map(|(n,_,_,_)| *n).collect();
    let mut unknown: Vec<&str> = args.keys().iter().filter(|k| !allowed.contains(k.as_str())).map(|s| s.as_str()).collect();
    if !unknown.is_empty() {
        unknown.sort();
        return Some(format!("unknown argument: {}", unknown[0]));
    }
    for (pname, required, typ, min) in &props {
        if let Some(v) = args.get(*pname) {
            match *typ {
                "string" => {
                    if !v.is_string() {
                        return Some(format!("argument {} must be a string", pname));
                    }
                    if v.as_str().unwrap().is_empty() {
                        return Some(format!("argument {} must not be empty", pname));
                    }
                }
                "array_int" => {
                    if !v.is_array() {
                        return Some(format!("argument {} must be an array of integers", pname));
                    }
                    let arr = v.as_array().unwrap();
                    if arr.is_empty() {
                        return Some(format!("argument {} must not be empty", pname));
                    }
                    for e in arr {
                        if !e.is_number() || e.as_i64().is_none() {
                            return Some(format!("argument {} must be an array of integers", pname));
                        }
                    }
                }
                _ => {}
            }
        } else if *required {
            return Some(format!("missing required argument: {}", pname));
        }
    }
    None
}

use std::collections::HashMap;
use std::io::{self, BufRead};

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<JsonValue>),
    Obj(Vec<(String, JsonValue)>),
}

fn skip_ws(s: &str, i: &mut usize) {
    while *i < s.len() {
        let c = s.as_bytes()[*i] as char;
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            *i += 1;
        } else {
            break;
        }
    }
}

fn parse_string(s: &str, i: &mut usize) -> Result<String, ()> {
    if s.as_bytes()[*i] as char != '"' {
        return Err(());
    }
    *i += 1;
    let mut out = String::new();
    while *i < s.len() {
        let c = s.as_bytes()[*i] as char;
        if c == '"' {
            *i += 1;
            return Ok(out);
        }
        if c == '\\' {
            *i += 1;
            if *i >= s.len() { return Err(()); }
            let esc = s.as_bytes()[*i] as char;
            match esc {
                '"' => out.push('"'),
                '\\' => out.push('\\'),
                '/' => out.push('/'),
                'b' => out.push('\x08'),
                'f' => out.push('\x0c'),
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                'u' => {
                    let mut hex = String::new();
                    for _ in 0..4 {
                        *i += 1;
                        if *i >= s.len() { return Err(()); }
                        hex.push(s.as_bytes()[*i] as char);
                    }
                    if let Ok(code) = u16::from_str_radix(&hex, 16) {
                        if let Some(ch) = std::char::from_u32(code as u32) {
                            out.push(ch);
                        }
                    }
                }
                _ => return Err(()),
            }
            *i += 1;
            continue;
        }
        out.push(c);
        *i += 1;
    }
    Err(())
}

fn parse_number(s: &str, i: &mut usize) -> Result<String, ()> {
    let start = *i;
    let bytes = s.as_bytes();
    if bytes[*i] as char == '-' { *i += 1; }
    let mut has_digit = false;
    while *i < s.len() {
        let c = bytes[*i] as char;
        if c.is_ascii_digit() { has_digit = true; *i += 1; }
        else { break; }
    }
    if !has_digit { return Err(()); }
    while *i < s.len() {
        let c = bytes[*i] as char;
        if c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
            *i += 1;
        } else { break; }
    }
    if *i > start { Ok(s[start..*i].to_string()) } else { Err(()) }
}

fn parse_value(s: &str, i: &mut usize) -> Result<JsonValue, ()> {
    skip_ws(s, i);
    if *i >= s.len() { return Err(()); }
    match s.as_bytes()[*i] as char {
        '{' => parse_object(s, i),
        '[' => parse_array(s, i),
        '"' => {
            let st = parse_string(s, i)?;
            Ok(JsonValue::Str(st))
        }
        't' => { if &s[*i..*i+4] == "true" { *i+=4; Ok(JsonValue::Bool(true)) } else { Err(()) } }
        'f' => { if &s[*i..*i+5] == "false" { *i+=5; Ok(JsonValue::Bool(false)) } else { Err(()) } }
        'n' => { if &s[*i..*i+4] == "null" { *i+=4; Ok(JsonValue::Null) } else { Err(()) } }
        '-' | '0'..='9' => {
            let num = parse_number(s, i)?;
            Ok(JsonValue::Num(num))
        }
        _ => Err(()),
    }
}

fn parse_object(s: &str, i: &mut usize) -> Result<JsonValue, ()> {
    *i += 1;
    skip_ws(s, i);
    let mut fields = Vec::new();
    if *i < s.len() && s.as_bytes()[*i] as char == '}' {
        *i += 1;
        return Ok(JsonValue::Obj(fields));
    }
    loop {
        skip_ws(s, i);
        let key = parse_string(s, i)?;
        skip_ws(s, i);
        if *i >= s.len() || s.as_bytes()[*i] as char != ':' { return Err(()); }
        *i += 1;
        let val = parse_value(s, i)?;
        fields.push((key, val));
        skip_ws(s, i);
        if *i >= s.len() { return Err(()); }
        match s.as_bytes()[*i] as char {
            ',' => { *i += 1; continue; }
            '}' => { *i += 1; break; }
            _ => return Err(()),
        }
    }
    Ok(JsonValue::Obj(fields))
}

fn parse_array(s: &str, i: &mut usize) -> Result<JsonValue, ()> {
    *i += 1;
    skip_ws(s, i);
    let mut items = Vec::new();
    if *i < s.len() && s.as_bytes()[*i] as char == ']' {
        *i += 1;
        return Ok(JsonValue::Arr(items));
    }
    loop {
        let v = parse_value(s, i)?;
        items.push(v);
        skip_ws(s, i);
        if *i >= s.len() { return Err(()); }
        match s.as_bytes()[*i] as char {
            ',' => { *i += 1; continue; }
            ']' => { *i += 1; break; }
            _ => return Err(()),
        }
    }
    Ok(JsonValue::Arr(items))
}

fn parse_json(s: &str) -> Option<JsonValue> {
    let mut i = 0;
    let v = parse_value(s, &mut i).ok()?;
    skip_ws(s, &mut i);
    if i == s.len() { Some(v) } else { None }
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < ' ' => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

fn serialize(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Num(s) => s.clone(),
        JsonValue::Str(s) => json_escape(s),
        JsonValue::Arr(a) => {
            let mut s = String::from("[");
            for (i, v) in a.iter().enumerate() {
                if i > 0 { s.push(','); }
                s.push_str(&serialize(v));
            }
            s.push(']');
            s
        }
        JsonValue::Obj(o) => {
            let mut s = String::from("{");
            for (i, (k, v)) in o.iter().enumerate() {
                if i > 0 { s.push(','); }
                s.push_str(&json_escape(k));
                s.push(':');
                s.push_str(&serialize(v));
            }
            s.push('}');
            s
        }
    }
}

fn get_field(obj: &JsonValue, key: &str) -> Option<&JsonValue> {
    if let JsonValue::Obj(fields) = obj {
        for (k, v) in fields {
            if k == key { return Some(v); }
        }
    }
    None
}

fn is_valid_id(v: &JsonValue) -> bool {
    match v {
        JsonValue::Str(_) => true,
        JsonValue::Num(s) => {
            let t = s.trim_start_matches('-');
            !t.is_empty() && t.chars().all(|c| c.is_ascii_digit())
        }
        _ => false,
    }
}

