fn make_error(id: JsonValue, code: i64, message: &str) -> JsonValue {
    JsonValue::Obj(vec![
        ("jsonrpc", JsonValue::Str("2.0".into())),
        ("id", id),
        ("error", JsonValue::Obj(vec![
            ("code", JsonValue::Num(code.to_string())),
            ("message", JsonValue::Str(message.into())),
        ])),
    ])
}
fn make_result(id: JsonValue, result: JsonValue) -> JsonValue {
    JsonValue::Obj(vec![
        ("jsonrpc", JsonValue::Str("2.0".into())),
        ("id", id),
        ("result", result),
    ])
}

fn main() {
    let stdin = io::stdin();
    let mut server = Server::new();
    let mut out_lines = Vec::new();

    for line in stdin.lock().lines() {
        let line = line.unwrap_or_default();
        let line = line.trim_end_matches('\r');
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        if let Some(resp) = handle_line(trimmed, &mut server) {
            out_lines.push(serialize(&resp));
        }
    }
    for s in out_lines { println!("{}", s); }
}

fn handle_line(line: &str, server: &mut Server) -> Option<JsonValue> {
    let parsed = parse_json(line);
    let parsed = match parsed {
        Some(v) => v,
        None => return Some(make_error(JsonValue::Null, -32700, "Parse error")),
    };
    if !matches!(parsed, JsonValue::Obj(_)) {
        return Some(make_error(JsonValue::Null, -32600, "Invalid Request"));
    }
    let obj = parsed;
    if get_field(&obj, "method").is_none() && (get_field(&obj, "result").is_some() || get_field(&obj, "error").is_some()) {
        return None;
    }
    let jsonrpc_ok = matches!(get_field(&obj, "jsonrpc"), Some(JsonValue::Str(s)) if s == "2.0");
    let method_val = get_field(&obj, "method");
    let method_ok = matches!(method_val, Some(JsonValue::Str(_)));
    let id_val = get_field(&obj, "id");
    let id_invalid = id_val.map_or(false, |v| !is_valid_id(v));
    if !jsonrpc_ok || !method_ok || id_invalid {
        let id_out = if let Some(id) = id_val { if is_valid_id(id) { id.clone() } else { JsonValue::Null } } else { JsonValue::Null };
        return Some(make_error(id_out, -32600, "Invalid Request"));
    }
    let id = id_val.cloned().unwrap_or(JsonValue::Null);
    if matches!(id, JsonValue::Null) {
        return None;
    }
    let method = if let JsonValue::Str(s) = method_val.unwrap() { s } else { String::new() };
    let params = get_field(&obj, "params");
    if params.is_some() && !matches!(params, Some(JsonValue::Obj(_))) {
        return Some(make_error(id, -32602, "Invalid params"));
    }
    if !server.initialized && method != "initialize" && method != "ping" {
        return Some(make_error(id, -32002, "Server not initialized"));
    }
    match method.as_str() {
        "initialize" => {
            if server.initialized {
                return Some(make_error(id, -32600, "Already initialized"));
            }
            let params_obj = match params {
                Some(JsonValue::Obj(_)) => params.unwrap(),
                _ => return Some(make_error(id, -32602, "Invalid params")),
            };
            let version_str = match get_field(&params_obj, "protocolVersion") {
                Some(JsonValue::Str(v)) => v.clone(),
                _ => return Some(make_error(id, -32602, "Invalid params")),
            };
            let version = if ["2025-06-18","2025-03-26","2024-11-05"].contains(&version_str.as_str()) { version_str } else { "2025-06-18".to_string() };
            server.initialized = true;
            let result = JsonValue::Obj(vec![
                ("protocolVersion", JsonValue::Str(version)),
                ("capabilities", JsonValue::Obj(vec![
                    ("tools", JsonValue::Obj(vec![("listChanged", JsonValue::Bool(false))]))
                ])),
                ("serverInfo", JsonValue::Obj(vec![
                    ("name", JsonValue::Str("cb2-kv".into())),
                    ("title", JsonValue::Str("CB2 key-value server".into())),
                    ("version", JsonValue::Str("1.4.2".into())),
                ])),
            ]);
            Some(make_result(id, result))
        }
        "ping" => Some(make_result(id, JsonValue::Obj(vec![]))),
        "tools/list" => {
            let result = JsonValue::Obj(vec![("tools", tools_list())]);
            Some(make_result(id, result))
        }
        "tools/call" => {
            let params_obj = match params {
                Some(JsonValue::Obj(_)) => params.unwrap(),
                _ => return Some(make_error(id, -32602, "Invalid params")),
            };
            let name = match get_field(&params_obj, "name") {
                Some(JsonValue::Str(s)) => s.clone(),
                _ => return Some(make_error(id, -32602, "Invalid params")),
            };
            let allowed = ["kv_set","kv_get","kv_list","sum","text_stats"];
            if !allowed.contains(&name.as_str()) {
                return Some(make_error(id, -32602, &format!("Unknown tool: {}", name)));
            }
            let args_val = get_field(&params_obj, "arguments").cloned().unwrap_or(JsonValue::Obj(vec![]));
            if !matches!(args_val, JsonValue::Obj(_)) {
                let res = JsonValue::Obj(vec![
                    ("content", JsonValue::Arr(vec![JsonValue::Obj(vec![
                        ("type", JsonValue::Str("text".into())),
                        ("text", JsonValue::Str("arguments must be an object".into())),
                    ])])),
                    ("isError", JsonValue::Bool(true)),
                ]);
                return Some(make_result(id, res));
            }
            let args_obj = if let JsonValue::Obj(f) = args_val { f } else { vec![] };
            let args_map = args_obj.into_iter().collect::<HashMap<_,_>>();
            // validation
            if let Some(err) = validate_tool(&name, &args_map) {
                let res = JsonValue::Obj(vec![
                    ("content", JsonValue::Arr(vec![JsonValue::Obj(vec![
                        ("type", JsonValue::Str("text".into())),
                        ("text", JsonValue::Str(err)),
                    ])])),
                    ("isError", JsonValue::Bool(true)),
                ]);
                return Some(make_result(id, res));
            }
            let (text, structured) = match name.as_str() {
                "kv_set" => {
                    let key = args_map.get("key").and_then(|v| if let JsonValue::Str(s)=v {Some(s.clone())} else {None}).unwrap();
                    let value = args_map.get("value").and_then(|v| if let JsonValue::Str(s)=v {Some(s.clone())} else {None}).unwrap();
                    let created = !server.kv.contains_key(&key);
                    server.kv.insert(key.clone(), value);
                    let txt = if created { format!("created {}", key) } else { format!("updated {}", key) };
                    (txt, None)
                }
                "kv_get" => {
                    let key = args_map.get("key").and_then(|v| if let JsonValue::Str(s)=v {Some(s.clone())} else {None}).unwrap();
                    match server.kv.get(&key) {
                        Some(v) => (v.clone(), None),
                        None => {
                            let res = JsonValue::Obj(vec![
                                ("content", JsonValue::Arr(vec![JsonValue::Obj(vec![
                                    ("type", JsonValue::Str("text".into())),
                                    ("text", JsonValue::Str(format!("key not found: {}", key))),
                                ])])),
                                ("isError", JsonValue::Bool(true)),
                            ]);
                            return Some(make_result(id, res));
                        }
                    }
                }
                "kv_list" => {
                    let prefix = args_map.get("prefix").and_then(|v| if let JsonValue::Str(s)=v {Some(s.clone())} else {None}).unwrap_or_default();
                    let mut keys: Vec<String> = server.kv.keys().filter(|k| k.starts_with(&prefix)).cloned().collect();
                    keys.sort();
                    let cnt = keys.len();
                    let s_val = JsonValue::Obj(vec![
                        ("keys", JsonValue::Arr(keys.into_iter().map(JsonValue::Str).collect())),
                        ("count", JsonValue::Num(cnt.to_string())),
                    ]);
                    let txt = serialize(&s_val);
                    (txt, Some(s_val))
                }
                "sum" => {
                    let arr = args_map.get("numbers").and_then(|v| if let JsonValue::Arr(a)=v {Some(a.clone())} else {None}).unwrap();
                    let mut sum: i64 = 0;
                    for v in &arr {
                        if let JsonValue::Num(s) = v {
                            if let Ok(n) = s.parse::<i64>() { sum += n; }
                        }
                    }
                    let s_val = JsonValue::Obj(vec![
                        ("sum", JsonValue::Num(sum.to_string())),
                        ("count", JsonValue::Num(arr.len().to_string())),
                    ]);
                    let txt = serialize(&s_val);
                    (txt, Some(s_val))
                }
                "text_stats" => {
                    let text_str = args_map.get("text").and_then(|v| if let JsonValue::Str(s)=v {Some(s.clone())} else {None}).unwrap();
                    let codepoints = text_str.chars().count();
                    let utf8_bytes = text_str.len();
                    let words = text_str.split(|c| c==' '||c=='\t'||c=='\n'||c=='\r').filter(|s| !s.is_empty()).count();
                    let s_val = JsonValue::Obj(vec![
                        ("words", JsonValue::Num(words.to_string())),
                        ("codepoints", JsonValue::Num(codepoints.to_string())),
                        ("utf8_bytes", JsonValue::Num(utf8_bytes.to_string())),
                    ]);
                    let txt = serialize(&s_val);
                    (txt, Some(s_val))
                }
                _ => unreachable!(),
            };
            let mut res = JsonValue::Obj(vec![
                ("content", JsonValue::Arr(vec![JsonValue::Obj(vec![
                    ("type", JsonValue::Str("text".into())),
                    ("text", JsonValue::Str(text)),
                ])])),
                ("isError", JsonValue::Bool(false)),
            ]);
            if let Some(sc) = structured {
                if let JsonValue::Obj(map) = &mut res {
                    map.push(("structuredContent".to_string(), sc));
                }
            }
            Some(make_result(id, res))
        }
        _ => Some(make_error(id, -32601, "Method not found")),
    }
}

fn validate_tool(name: &str, args: &HashMap<String, JsonValue>) -> Option<String> {
    let props = match name {
        "kv_set" => vec![("key", true, "string", false), ("value", true, "string", false)],
        "kv_get" => vec![("key", true, "string", false)],
        "kv_list" => vec![("prefix", false, "string", false)],
        "sum" => vec![("numbers", true, "array_int", true)],
        "text_stats" => vec![("text", true, "string", false)],
        _ => return None,
    };
    let allowed: std::collections::HashSet<&str> = props.iter().map(|(n,_,_,_)| *n).collect();
    let mut unknown: Vec<&str> = args.keys().filter(|k| !allowed.contains(k.as_str())).map(|s| s.as_str()).collect();
    if !unknown.is_empty() {
        unknown.sort();
        return Some(format!("unknown argument: {}", unknown[0]));
    }
    for (pname, required, typ, min) in &props {
        if let Some(v) = args.get(*pname) {
            match *typ {
                "string" => {
                    if !matches!(v, JsonValue::Str(_)) {
                        return Some(format!("argument {} must be a string", pname));
                    }
                    if let JsonValue::Str(s) = v {
                        if s.is_empty() {
                            return Some(format!("argument {} must not be empty", pname));
                        }
                    }
                }
                "array_int" => {
                    if !matches!(v, JsonValue::Arr(_)) {
                        return Some(format!("argument {} must be an array of integers", pname));
                    }
                    if let JsonValue::Arr(a) = v {
                        if a.is_empty() { return Some(format!("argument {} must not be empty", pname)); }
                        for e in a {
                            if let JsonValue::Num(s) = e {
                                if !s.chars().all(|c| c.is_ascii_digit() || c=='-' ) { return Some(format!("argument {} must be an array of integers", pname)); }
                            } else { return Some(format!("argument {} must be an array of integers", pname)); }
                        }
                    }
                }
                _ => {}
            }
        } else if *required {
            return Some(format!("missing required argument: {}", pname));
        }
    }
    None
}

import * as fs from 'fs';
import * as path from 'path';

type Line = { text: string; hasNewline: boolean };
type Hunk = {
  a: number;
  b: number;
  c: number;
  d: number;
  oldLines: Line[];
  newLines: Line[];
  malformed: boolean;
};
type Section = {
  path: string;
  kind: 'create' | 'delete' | 'modify';
  hunks: Hunk[];
};

function fileToLines(s: string): Line[] {
  if (s.length === 0) return [];
  const lines: Line[] = [];
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\n') {
      lines.push({ text: s.slice(start, i), hasNewline: true });
      start = i + 1;
    }
  }
  if (start < s.length) {
    lines.push({ text: s.slice(start), hasNewline: false });
  }
  return lines;
}

function linesToString(lines: Line[]): string {
  let out = '';
  for (const l of lines) {
    out += l.text;
    if (l.hasNewline) out += '\n';
  }
  return out;
}

/* CRC32 */
const CRC_TABLE: number[] = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let k = 0; k < 8; k++) {
    c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
  }
  CRC_TABLE[i] = c >>> 0;
}
function crc32(buf: Buffer): number {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buf[i]) & 0xff];
  }
  return (~crc) >>> 0;
}

/* parsing */
function parseDiff(diffText: string): Section[] {
  const lines = diffText.split('\n');
  const sections: Section[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.startsWith('diff --git a/')) {
      const m = line.match(/^diff --git a\/(.+?) b\/(.+)$/);
      if (!m) { i++; continue; }
      const pathName = m[1];
      i++;
      const sectionLines: string[] = [];
      while (i < lines.length && !lines[i].startsWith('diff --git a/')) {
        sectionLines.push(lines[i]);
        i++;
      }
      let kind: 'create' | 'delete' | 'modify' = 'modify';
      for (const l of sectionLines) {
        if (l.startsWith('new file mode ')) kind = 'create';
        else if (l.startsWith('deleted file mode ')) kind = 'delete';
      }
      const hunks: Hunk[] = [];
      let j = 0;
      while (j < sectionLines.length) {
        const l = sectionLines[j];
        if (l.startsWith('@@ ')) {
          const hm = l.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
          if (hm) {
            const a = parseInt(hm[1], 10);
            const b = hm[2] ? parseInt(hm[2], 10) : 1;
            const c = parseInt(hm[3], 10);
            const d = hm[4] ? parseInt(hm[4], 10) : 1;
            const bodyLines: string[] = [];
            j++;
            while (j < sectionLines.length && !sectionLines[j].startsWith('@@ ')) {
              bodyLines.push(sectionLines[j]);
              j++;
            }
            const oldLines: Line[] = [];
            const newLines: Line[] = [];
            let lastMarker: string | null = null;
            let lastOldIdx = -1;
            let lastNewIdx = -1;
            for (const bl of bodyLines) {
              if (bl === '\\ No newline at end of file') {
                if (lastMarker === ' ') {
                  if (lastOldIdx >= 0) oldLines[lastOldIdx].hasNewline = false;
                  if (lastNewIdx >= 0) newLines[lastNewIdx].hasNewline = false;
                } else if (lastMarker === '-') {
                  if (lastOldIdx >= 0) oldLines[lastOldIdx].hasNewline = false;
                } else if (lastMarker === '+') {
                  if (lastNewIdx >= 0) newLines[lastNewIdx].hasNewline = false;
                }
                continue;
              }
              const marker = bl[0];
              const content = bl.slice(1);
              if (marker === ' ') {
                const entry: Line = { text: content, hasNewline: true };
                oldLines.push({ text: entry.text, hasNewline: entry.hasNewline });
                newLines.push({ text: entry.text, hasNewline: entry.hasNewline });
                lastMarker = ' ';
                lastOldIdx = oldLines.length - 1;
                lastNewIdx = newLines.length - 1;
              } else if (marker === '-') {
                oldLines.push({ text: content, hasNewline: true });
                lastMarker = '-';
                lastOldIdx = oldLines.length - 1;
              } else if (marker === '+') {
                newLines.push({ text: content, hasNewline: true });
                lastMarker = '+';
                lastNewIdx = newLines.length - 1;
              }
            }
            const malformed = oldLines.length !== b || newLines.length !== d;
            hunks.push({ a, b, c, d, oldLines, newLines, malformed });
          } else {
            j++;
          }
        } else {
          j++;
        }
      }
      sections.push({ path: pathName, kind, hunks });
    } else {
      i++;
    }
  }
  return sections;
}

function main() {
  const base = process.argv[2];
  if (!base) process.exit(0);
  const diffPath = path.join(base, 'changes.diff');
  const treeDir = path.join(base, 'tree');
  const diffText = fs.readFileSync(diffPath, 'utf8');
  const sections = parseDiff(diffText);
  sections.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));

  const out: string[] = [];
  for (const sec of sections) {
    out.push(`${sec.path}: ${sec.kind}`);
    const filePath = path.join(treeDir, sec.path);
    const exists = fs.existsSync(filePath);
    if (sec.kind === 'create') {
      if (exists) {
        out.push('  error: already exists');
        continue;
      }
    } else {
      if (!exists) {
        out.push('  error: not found');
        continue;
      }
    }

    let contentLines: Line[] = [];
    if (sec.kind !== 'create') {
      const txt = fs.readFileSync(filePath, 'utf8');
      contentLines = fileToLines(txt);
    }

    let delta = 0;
    let allApplied = true;
    let deleteOk = true;
    for (let idx = 0; idx < sec.hunks.length; idx++) {
      const h = sec.hunks[idx];
      const n = idx + 1;
      if (h.malformed) {
        out.push(`  hunk ${n}: malformed`);
        allApplied = false;
        deleteOk = false;
        continue;
      }
      const b = h.oldLines.length;
      const d = h.newLines.length;
      const P = h.a + delta;
      if (b === 0) {
        const lineCount = contentLines.length;
        if (P >= 0 && P <= lineCount) {
          const insertIdx = P;
          contentLines.splice(insertIdx, 0, ...h.newLines);
          delta += d - b;
          out.push(`  hunk ${n}: applied at ${P} (offset 0)`);
        } else {
          out.push(`  hunk ${n}: rejected`);
          allApplied = false;
          deleteOk = false;
        }
      } else {
        const lineCount = contentLines.length;
        let found = false;
        let bestP = -1;
        let bestOffset = 0;
        for (let dist = 0; ; dist++) {
          const candidates: number[] = [];
          if (dist === 0) candidates.push(P);
          else {
            candidates.push(P - dist);
            candidates.push(P + dist);
          }
          for (const p of candidates) {
            if (p < 1 || p + b - 1 > lineCount) continue;
            let ok = true;
            for (let k = 0; k < b; k++) {
              const ol = h.oldLines[k];
              const cl = contentLines[p - 1 + k];
              if (ol.text !== cl.text || ol.hasNewline !== cl.hasNewline) { ok = false; break; }
            }
            if (ok) {
              found = true;
              bestP = p;
              bestOffset = p - P;
              break;
            }
          }
          if (found) break;
          if (dist > lineCount + 1000) break;
        }
        if (found) {
          const startIdx = bestP - 1;
          contentLines.splice(startIdx, b, ...h.newLines);
          delta += d - b;
          const offStr = bestOffset === 0 ? '0' : (bestOffset > 0 ? `+${bestOffset}` : `${bestOffset}`);
          out.push(`  hunk ${n}: applied at ${bestP} (offset ${offStr})`);
        } else {
          out.push(`  hunk ${n}: rejected`);
          allApplied = false;
          deleteOk = false;
        }
      }
    }

    if (sec.kind === 'delete') {
      if (allApplied && contentLines.length === 0) {
        out.push('  result: deleted');
      } else {
        const s = linesToString(contentLines);
        const c = crc32(Buffer.from(s, 'utf8')).toString(16).padStart(8, '0');
        out.push(`  result: ${contentLines.length} lines, crc32 ${c}`);
      }
    } else {
      const s = linesToString(contentLines);
      const c = crc32(Buffer.from(s, 'utf8')).toString(16).padStart(8, '0');
      out.push(`  result: ${contentLines.length} lines, crc32 ${c}`);
    }
  }
  console.log(out.join('\n'));
}

main();

import Foundation
import CoreGraphics
import ImageIO
import UniformTypeIdentifiers

struct ShapeInfo {
    let type: String
    let rectX: Int?
    let rectY: Int?
    let rectW: Int?
    let rectH: Int?
    let circCx: Int?
    let circCy: Int?
    let circR: Int?
    let triPoints: [(Int,Int)]?
    let lineX1: Int?
    let lineY1: Int?
    let lineX2: Int?
    let lineY2: Int?
    let lineR: Int?
    let color: (r:Int,g:Int,b:Int,a:Int)
}

func loadScene(at dir: String) -> (width:Int,height:Int,background:[UInt8],shapes:[ShapeInfo]) {
    let url = URL(fileURLWithPath: dir + "/scene.json")
    let data = try! Data(contentsOf: url)
    let obj = try! JSONSerialization.jsonObject(with: data) as! [String:Any]
    let width = obj["width"] as! Int
    let height = obj["height"] as! Int
    let bgArr = obj["background"] as! [Int]
    let background = [UInt8(bgArr[0]), UInt8(bgArr[1]), UInt8(bgArr[2])]
    var shapes: [ShapeInfo] = []
    let shapesArr = obj["shapes"] as! [[String:Any]]
    for s in shapesArr {
        let type = s["type"] as! String
        var colArr = s["color"] as! [Int]
        let r = colArr[0], g = colArr[1], b = colArr[2]
        let a = colArr.count > 3 ? colArr[3] : 255
        var info = ShapeInfo(
            type: type,
            rectX: nil, rectY: nil, rectW: nil, rectH: nil,
            circCx: nil, circCy: nil, circR: nil,
            triPoints: nil,
            lineX1: nil, lineY1: nil, lineX2: nil, lineY2: nil, lineR: nil,
            color: (r,g,b,a)
        )
        switch type {
        case "rect":
            info = ShapeInfo(type: type,
                rectX: s["x"] as! Int, rectY: s["y"] as! Int,
                rectW: s["w"] as! Int, rectH: s["h"] as! Int,
                circCx: nil, circCy: nil, circR: nil,
                triPoints: nil,
                lineX1: nil, lineY1: nil, lineX2: nil, lineY2: nil, lineR: nil,
                color: (r,g,b,a))
        case "circle":
            info = ShapeInfo(type: type,
                rectX: nil, rectY: nil, rectW: nil, rectH: nil,
                circCx: s["cx"] as! Int, circCy: s["cy"] as! Int, circR: s["r"] as! Int,
                triPoints: nil,
                lineX1: nil, lineY1: nil, lineX2: nil, lineY2: nil, lineR: nil,
                color: (r,g,b,a))
        case "triangle":
            let pts = s["points"] as! [[Int]]
            let points = pts.map { ( $0[0], $0[1]) }
            info = ShapeInfo(type: type,
                rectX: nil, rectY: nil, rectW: nil, rectH: nil,
                circCx: nil, circCy: nil, circR: nil,
                triPoints: points,
                lineX1: nil, lineY1: nil, lineX2: nil, lineY2: nil, lineR: nil,
                color: (r,g,b,a))
        case "line":
            info = ShapeInfo(type: type,
                rectX: nil, rectY: nil, rectW: nil, rectH: nil,
                circCx: nil, circCy: nil, circR: nil,
                triPoints: nil,
                lineX1: s["x1"] as! Int, lineY1: s["y1"] as! Int,
                lineX2: s["x2"] as! Int, lineY2: s["y2"] as! Int,
                lineR: s["r"] as! Int,
                color: (r,g,b,a))
        default: break
        }
        shapes.append(info)
    }
    return (width,height,background,shapes)
}

func covers(_ x:Int,_ y:Int,_ shape:ShapeInfo)->Bool {
    switch shape.type {
    case "rect":
        guard let rx = shape.rectX, let ry = shape.rectY,
              let w = shape.rectW, let h = shape.rectH else { return false }
        if w <= 0 || h <= 0 { return false }
        return x >= rx && x < rx + w && y >= ry && y < ry + h
    case "circle":
        guard let cx = shape.circCx, let cy = shape.circCy, let r = shape.circR else { return false }
        let dx = Int64(x - cx); let dy = Int64(y - cy)
        return dx*dx + dy*dy <= Int64(r)*Int64(r)
    case "triangle":
        guard let pts = shape.triPoints, pts.count == 3 else { return false }
        var es = [Int64]()
        for i in 0..<3 {
            let (x1,y1) = pts[i]
            let (x2,y2) = pts[(i+1)%3]
            let e = Int64(x2 - x1)*Int64(y - y1) - Int64(y2 - y1)*Int64(x - x1)
            es.append(e)
        }
        let allPos = es.allSatisfy { $0 >= 0 }
        let allNeg = es.allSatisfy { $0 <= 0 }
