              let r = shape.lineR else { return false }
        let dx = Int64(x2 - x1); let dy = Int64(y2 - y1)
        let L = dx*dx + dy*dy
        let t = Int64(x - x1)*dx + Int64(y - y1)*dy
        if L == 0 {
            let ddx = Int64(x - x1); let ddy = Int64(y - y1)
            return ddx*ddx + ddy*ddy <= Int64(r)*Int64(r)
        }
        if t <= 0 {
            let ddx = Int64(x - x1); let ddy = Int64(y - y1)
            return ddx*ddx + ddy*ddy <= Int64(r)*Int64(r)
        }
        if t >= L {
            let ddx = Int64(x - x2); let ddy = Int64(y - y2)
            return ddx*ddx + ddy*ddy <= Int64(r)*Int64(r)
        }
        let c = Int64(x - x1)*dy - Int64(y - y1)*dx
        return c*c <= Int64(r)*Int64(r)*L
    default:
        return false
    }
