import Foundation

struct Line { let data: Data }

struct Hunk {
    let a: Int
    let b: Int
    let d: Int
    let oldLines: [Line]
    let newLines: [Line]
    let isMalformed: Bool
}

enum Kind { case create, delete, modify }

struct SectionInfo {
    let path: String
    let kind: Kind
    let hunks: [Hunk]
}

func linesFromData(_ data: Data) -> [Line] {
    guard !data.isEmpty else { return [] }
    var lines: [Line] = []
    var start = 0
    let bytes = [UInt8](data)
    for i in 0..<bytes.count {
        if bytes[i] == 0x0A {
            let slice = data[start...i]
            lines.append(Line(data: Data(slice)))
            start = i + 1
        }
    }
    if start < data.count {
        let slice = data[start..<data.count]
        lines.append(Line(data: Data(slice)))
    }
    return lines
}

func dataFromLines(_ lines: [Line]) -> Data {
    var d = Data()
    for l in lines { d.append(l.data) }
    return d
}

func crc32(_ data: Data) -> UInt32 {
    var crc: UInt32 = 0xffffffff
    for b in data {
        crc ^= UInt32(b)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xffffffff
}

func parseOldNew(_ token: Substring) -> (Int, Int) {
    let t = token.dropFirst()
    let parts = t.split(separator: ",")
    let first = Int(parts[0]) ?? 0
    let second = parts.count > 1 ? Int(parts[1]) ?? 1 : 1
    return (first, second)
}

