type RGB = [number, number, number];
type RGBA = [number, number, number, number];

interface Scene {
  width: number;
  height: number;
  background: RGB;
  shapes: Shape[];
}

type Shape =
  | { type: 'rect'; x: number; y: number; w: number; h: number; color: RGBA }
  | { type: 'circle'; cx: number; cy: number; r: number; color: RGBA }
  | { type: 'triangle'; points: [[number, number], [number, number], [number, number]]; color: RGBA }
  | { type: 'line'; x1: number; y1: number; x2: number; y2: number; r: number; color: RGBA };

function loadScene(dir: string): Scene {
  const txt = fs.readFileSync(path.join(dir, 'scene.json'), 'utf8');
  return JSON.parse(txt) as Scene;
}

/* CRC32 */
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) c = (c & 1) ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
    t[i] = c;
  }
  return t;
})();
function crc32(buf: Buffer): number {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = CRC_TABLE[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function blend(dR: number, dG: number, dB: number, sR: number, sG: number, sB: number, a: number) {
  const inv = 255 - a;
  const r = Math.floor((sR * a + dR * inv + 127) / 255);
  const g = Math.floor((sG * a + dG * inv + 127) / 255);
  const b = Math.floor((sB * a + dB * inv + 127) / 255);
  return [r, g, b];
}

