              const [r, g, b] = blend(pixels[i], pixels[i + 1], pixels[i + 2], sR, sG, sB, sA);
              pixels[i] = r; pixels[i + 1] = g; pixels[i + 2] = b;
            }
          }
        }
      }
    } else if (shape.type === 'circle') {
      const cx = shape.cx, cy = shape.cy, r = shape.r;
      const r2 = r * r;
      x0 = Math.max(0, cx - r);
      x1 = Math.min(w - 1, cx + r);
      y0 = Math.max(0, cy - r);
      y1 = Math.min(h - 1, cy + r);
      for (let y = y0; y <= y1; y++) {
        const dy = y - cy;
        const dy2 = dy * dy;
        for (let x = x0; x <= x1; x++) {
          const dx = x - cx;
          if (dx * dx + dy2 <= r2) {
            covered++;
            const i = (y * w + x) * 3;
            const [rC, gC, bC] = blend(pixels[i], pixels[i + 1], pixels[i + 2], sR, sG, sB, sA);
            pixels[i] = rC; pixels[i + 1] = gC; pixels[i + 2] = bC;
          }
        }
      }
    } else if (shape.type === 'triangle') {
      const pts = shape.points;
      const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]);
      const minX = Math.min(...xs), maxX = Math.max(...xs);
      const minY = Math.min(...ys), maxY = Math.max(...ys);
      x0 = Math.max(0, minX); x1 = Math.min(w - 1, maxX);
      y0 = Math.max(0, minY); y1 = Math.min(h - 1, maxY);
      for (let y = y0; y <= y1; y++) {
        for (let x = x0; x <= x1; x++) {
          let e0 = 0, e1 = 0, e2 = 0;
          for (let i = 0; i < 3; i++) {
            const [xi, yi] = pts[i];
            const [xj, yj] = pts[(i + 1) % 3];
            const e = (xj - xi) * (y - yi) - (yj - yi) * (x - xi);
            if (i === 0) e0 = e;
            else if (i === 1) e1 = e;
            else e2 = e;
          }
          const inside = (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
          if (inside) {
            covered++;
            const iIdx = (y * w + x) * 3;
            const [rC, gC, bC] = blend(pixels[iIdx], pixels[iIdx + 1], pixels[iIdx + 2], sR, sG, sB, sA);
            pixels[iIdx] = rC; pixels[iIdx + 1] = gC; pixels[iIdx + 2] = bC;
          }
        }
      }
    } else if (shape.type === 'line') {
      const x1s = shape.x1, y1s = shape.y1, x2s = shape.x2, y2s = shape.y2, r = shape.r;
      const dx = x2s - x1s, dy = y2s - y1s;
      const L = dx * dx + dy * dy;
      const r2 = r * r;
      const minX = Math.min(x1s, x2s) - r;
      const maxX = Math.max(x1s, x2s) + r;
      const minY = Math.min(y1s, y2s) - r;
      const maxY = Math.max(y1s, y2s) + r;
      x0 = Math.max(0, minX); x1 = Math.min(w - 1, maxX);
      y0 = Math.max(0, minY); y1 = Math.min(h - 1, maxY);
      for (let y = y0; y <= y1; y++) {
        for (let x = x0; x <= x1; x++) {
          let covers = false;
          if (L === 0) {
            const d2 = (x - x1s) * (x - x1s) + (y - y1s) * (y - y1s);
            covers = d2 <= r2;
          } else {
            const t = (x - x1s) * dx + (y - y1s) * dy;
            if (t <= 0) {
              const d2 = (x - x1s) * (x - x1s) + (y - y1s) * (y - y1s);
              covers = d2 <= r2;
            } else if (t >= L) {
              const d2 = (x - x2s) * (x - x2s) + (y - y2s) * (y - y2s);
              covers = d2 <= r2;
            } else {
              const c = (x - x1s) * dy - (y - y1s) * dx;
              covers = c * c <= r2 * L;
            }
          }
          if (covers) {
            covered++;
            const iIdx = (y * w + x) * 3;
            const [rC, gC, bC] = blend(pixels[iIdx], pixels[iIdx + 1], pixels[iIdx + 2], sR, sG, sB, sA);
            pixels[iIdx] = rC; pixels[iIdx + 1] = gC; pixels[iIdx + 2] = bC;
          }
        }
      }
    }
    counts.push(covered);
  }

  // output summary
  const outLines: string[] = [];
  scene.shapes.forEach((sh, idx) => {
    outLines.push(`${idx + 1} ${sh.type} ${counts[idx]}`);
  });
  const set = new Set<string>();
  for (let i = 0; i < pixels.length; i += 3) {
    set.add(`${pixels[i]},${pixels[i + 1]},${pixels[i + 2]}`);
  }
  outLines.push(`colors ${set.size}`);
  console.log(outLines.join('\n'));

  // PNG
  const rowBytes = w * 3 + 1;
  const raw = Buffer.alloc(h * rowBytes);
  let off = 0;
  for (let y = 0; y < h; y++) {
    raw[off++] = 0; // filter 0
    const base = y * w * 3;
    for (let x = 0; x < w; x++) {
      raw[off++] = pixels[base + x * 3];
      raw[off++] = pixels[base + x * 3 + 1];
      raw[off++] = pixels[base + x * 3 + 2];
    }
  }
  const idat = zlib.deflateSync(raw);

  const sig = Buffer.from([0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A]);
  const ihdrData = Buffer.alloc(13);
  ihdrData.writeUInt32BE(w, 0);
  ihdrData.writeUInt32BE(h, 4);
  ihdrData[8] = 8; ihdrData[9] = 2; ihdrData[10] = 0; ihdrData[11] = 0; ihdrData[12] = 0;

  function chunk(type: string, data: Buffer): Buffer {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length, 0);
    const typeBuf = Buffer.from(type, 'ascii');
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])), 0);
    return Buffer.concat([len, typeBuf, data, crc]);
  }

  const png = Buffer.concat([
    sig,
    chunk('IHDR', ihdrData),
    chunk('IDAT', idat),
    chunk('IEND', Buffer.alloc(0))
  ]);
  fs.writeFileSync('out.png', png);
}

