        List<Number> bgList = (List<Number>) scene.get("background");
        int bgR = bgList.get(0).intValue();
        int bgG = bgList.get(1).intValue();
        int bgB = bgList.get(2).intValue();

        @SuppressWarnings("unchecked")
        List<Object> shapesRaw = (List<Object>) scene.get("shapes");

        int[][][] pix = new int[height][width][3];
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                pix[y][x][0] = bgR;
                pix[y][x][1] = bgG;
                pix[y][x][2] = bgB;
            }
        }

        StringBuilder out = new StringBuilder();
        int shapeIdx = 1;
        for (Object o : shapesRaw) {
            @SuppressWarnings("unchecked")
            Map<String, Object> sh = (Map<String, Object>) o;
            String type = (String) sh.get("type");
            long covered = 0;

            int sR = 0, sG = 0, sB = 0, sA = 255;
            @SuppressWarnings("unchecked")
            List<Number> col = (List<Number>) sh.get("color");
            sR = col.get(0).intValue();
            sG = col.get(1).intValue();
            sB = col.get(2).intValue();
            sA = col.size() > 3 ? col.get(3).intValue() : 255;

            switch (type) {
                case "rect": {
                    int rx = ((Number) sh.get("x")).intValue();
                    int ry = ((Number) sh.get("y")).intValue();
                    int w = ((Number) sh.get("w")).intValue();
                    int h = ((Number) sh.get("h")).intValue();
                    for (int y = 0; y < height; y++) {
                        if (y < ry || y >= ry + h) continue;
                        for (int x = 0; x < width; x++) {
                            if (x >= rx && x < rx + w) {
                                covered++;
                                if (sA != 0) blend(pix[y][x], sR, sG, sB, sA);
                            }
                        }
                    }
                    break;
                }
                case "circle": {
                    int cx = ((Number) sh.get("cx")).intValue();
                    int cy = ((Number) sh.get("cy")).intValue();
                    int r = ((Number) sh.get("r")).intValue();
                    long r2 = 1L * r * r;
                    for (int y = 0; y < height; y++) {
                        long dy = y - cy;
                        long dy2 = dy * dy;
                        for (int x = 0; x < width; x++) {
                            long dx = x - cx;
                            if (dx * dx + dy2 <= r2) {
                                covered++;
                                if (sA != 0) blend(pix[y][x], sR, sG, sB, sA);
                            }
                        }
                    }
                    break;
                }
                case "triangle": {
                    @SuppressWarnings("unchecked")
                    List<Object> ptsRaw = (List<Object>) sh.get("points");
                    int[] xs = new int[3];
                    int[] ys = new int[3];
                    for (int i = 0; i < 3; i++) {
                        @SuppressWarnings("unchecked")
                        List<Number> p = (List<Number>) ptsRaw.get(i);
                        xs[i] = p.get(0).intValue();
                        ys[i] = p.get(1).intValue();
                    }
                    for (int y = 0; y < height; y++) {
                        for (int x = 0; x < width; x++) {
                            long e0 = (xs[1] - xs[0]) * (y - ys[0]) - (ys[1] - ys[0]) * (x - xs[0]);
                            long e1 = (xs[2] - xs[1]) * (y - ys[1]) - (ys[2] - ys[1]) * (x - xs[1]);
                            long e2 = (xs[0] - xs[2]) * (y - ys[2]) - (ys[0] - ys[2]) * (x - xs[2]);
                            boolean in = (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
                            if (in) {
                                covered++;
                                if (sA != 0) blend(pix[y][x], sR, sG, sB, sA);
                            }
                        }
                    }
                    break;
                }
                case "line": {
                    int x1 = ((Number) sh.get("x1")).intValue();
                    int y1 = ((Number) sh.get("y1")).intValue();
                    int x2 = ((Number) sh.get("x2")).intValue();
                    int y2 = ((Number) sh.get("y2")).intValue();
                    int r = ((Number) sh.get("r")).intValue();
                    long dx = x2 - x1;
                    long dy = y2 - y1;
                    long L = dx * dx + dy * dy;
                    long r2 = 1L * r * r;
                    for (int y = 0; y < height; y++) {
                        for (int x = 0; x < width; x++) {
                            boolean cover;
                            if (L == 0) {
                                long ddx = x - x1;
                                long ddy = y - y1;
                                cover = ddx * ddx + ddy * ddy <= r2;
                            } else {
                                long t = (x - x1) * dx + (y - y1) * dy;
                                if (t <= 0) {
                                    long ddx = x - x1;
                                    long ddy = y - y1;
                                    cover = ddx * ddx + ddy * ddy <= r2;
                                } else if (t >= L) {
                                    long ddx = x - x2;
                                    long ddy = y - y2;
                                    cover = ddx * ddx + ddy * ddy <= r2;
                                } else {
                                    long c = (x - x1) * dy - (y - y1) * dx;
                                    cover = c * c <= r2 * L;
                                }
                            }
                            if (cover) {
                                covered++;
                                if (sA != 0) blend(pix[y][x], sR, sG, sB, sA);
                            }
                        }
                    }
                    break;
                }
            }
            out.append(shapeIdx).append(' ').append(type).append(' ').append(covered).append('\n');
            shapeIdx++;
        }

        Set<Integer> colors = new HashSet<>();
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int rgb = (pix[y][x][0] << 16) | (pix[y][x][1] << 8) | pix[y][x][2];
                colors.add(rgb);
            }
        }
        out.append("colors ").append(colors.size()).append('\n');
        System.out.print(out.toString());

        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int rgb = (pix[y][x][0] << 16) | (pix[y][x][1] << 8) | pix[y][x][2];
                img.setRGB(x, y, rgb);
            }
        }
        ImageIO.write(img, "png", new File("out.png"));
    }

    private static void blend(int[] dst, int sR, int sG, int sB, int a) {
        int dR = dst[0], dG = dst[1], dB = dst[2];
        dst[0] = (sR * a + dR * (255 - a) + 127) / 255;
        dst[1] = (sG * a + dG * (255 - a) + 127) / 255;
        dst[2] = (sB * a + dB * (255 - a) + 127) / 255;
    }

    // Minimal JSON parser for the required subset
    static class JsonParser {
        private final String s;
        private int i = 0;
        JsonParser(String s) { this.s = s; }
        Object parseValue() { skipWs(); char c = s.charAt(i); if (c == '{') return parseObject(); if (c == '[') return parseArray(); if (c == '"') return parseString(); if (c == '-' || Character.isDigit(c)) return parseNumber(); throw new RuntimeException("Unexpected char " + c); }
        private void skipWs() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        private Map<String,Object> parseObject() {
            i++; // {
            Map<String,Object> map = new LinkedHashMap<>();
            skipWs();
            if (s.charAt(i) == '}') { i++; return map; }
            while (true) {
                String key = parseString();
                skipWs(); if (s.charAt(i) != ':') throw new RuntimeException("Expected :");
                i++;
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                char c = s.charAt(i);
                if (c == '}') { i++; break; }
                if (c == ',') { i++; skipWs(); }
            }
            return map;
        }
        private List<Object> parseArray() {
            i++; // [
            List<Object> list = new ArrayList<>();
            skipWs();
            if (s.charAt(i) == ']') { i++; return list; }
            while (true) {
                Object v = parseValue();
                list.add(v);
                skipWs();
                char c = s.charAt(i);
                if (c == ']') { i++; break; }
                if (c == ',') { i++; skipWs(); }
            }
            return list;
        }
        private String parseString() {
            i++; // "
            StringBuilder sb = new StringBuilder();
            while (i < s.length()) {
                char c = s.charAt(i);
                if (c == '"') { i++; break; }
                if (c == '\\') { i++; if (i < s.length()) sb.append(s.charAt(i++)); }
                else sb.append(c);
                i++;
            }
            return sb.toString();
        }
        private Number parseNumber() {
            int start = i;
            while (i < s.length() && (Character.isDigit(s.charAt(i)) || s.charAt(i) == '-' || s.charAt(i) == '+' || s.charAt(i) == '.')) i++;
            String num = s.substring(start, i);
            if (num.contains(".")) return Double.parseDouble(num);
            return Long.parseLong(num);
        }
    }
}

