        private int i = 0;
        JsonParser(String s) { this.s = s; }
        Object parseValue() { skipWs(); char c = s.charAt(i); if (c == '{') return parseObject(); if (c == '[') return parseArray(); if (c == '"') return parseString(); if (c == '-' || Character.isDigit(c)) return parseNumber(); throw new RuntimeException("Unexpected char " + c); }
        private void skipWs() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        private Map<String,Object> parseObject() {
            i++;
            Map<String,Object> map = new LinkedHashMap<>();
            skipWs();
            if (s.charAt(i) == '}') { i++; return map; }
            while (true) {
                String key = parseString();
                skipWs(); if (s.charAt(i) != ':') throw new RuntimeException("Expected :");
                i++;
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                char c = s.charAt(i);
                if (c == '}') { i++; break; }
                if (c == ',') { i++; skipWs(); }
            }
            return map;
        }
        private List<Object> parseArray() {
            i++;
            List<Object> list = new ArrayList<>();
            skipWs();
            if (s.charAt(i) == ']') { i++; return list; }
            while (true) {
                Object v = parseValue();
                list.add(v);
                skipWs();
                char c = s.charAt(i);
                if (c == ']') { i++; break; }
                if (c == ',') { i++; skipWs(); }
            }
            return list;
        }
        private String parseString() {
            i++;
            StringBuilder sb = new StringBuilder();
            while (i < s.length()) {
                char c = s.charAt(i);
                if (c == '"') { i++; break; }
                if (c == '\\') { i++; if (i < s.length()) sb.append(s.charAt(i++)); }
                else sb.append(c);
                i++;
            }
            return sb.toString();
        }
        private Number parseNumber() {
            int start = i;
            while (i < s.length() && (Character.isDigit(s.charAt(i)) || s.charAt(i) == '-' || s.charAt(i) == '+' || s.charAt(i) == '.')) i++;
            String num = s.substring(start, i);
            if (num.contains(".")) return Double.parseDouble(num);
            return Long.parseLong(num);
        }
    }
}

import sys
import os
import re
import zlib

def split_to_lines(data: bytes):
    if not data:
        return []
    lines = []
    start = 0
    for i in range(len(data)):
        if data[i:i+1] == b'\n':
            lines.append(data[start:i+1])
            start = i + 1
    if start < len(data):
        lines.append(data[start:])
    return lines

def reconstruct_bytes(lines):
    return b''.join(lines)

def parse_diff(base_dir):
    diff_path = os.path.join(base_dir, 'changes.diff')
    with open(diff_path, 'rb') as f:
        diff_bytes = f.read()
    diff_lines = diff_bytes.splitlines(keepends=True)

    sections_raw = []
    i = 0
    n = len(diff_lines)
    while i < n:
        line = diff_lines[i]
        if line.startswith(b'diff --git a/'):
            m = re.match(br'diff --git a/(.*?)\s+b/(.*)', line)
            if m:
                path = m.group(1).decode('utf-8')
            else:
                parts = line.split()
                path = parts[2][2:].decode('utf-8')
            j = i + 1
            while j < n and not diff_lines[j].startswith(b'diff --git a/'):
                j += 1
            sec_lines = diff_lines[i:j]
            sections_raw.append((path, sec_lines))
            i = j
        else:
            i += 1

    header_re = re.compile(br'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')
    parsed = []
    for path, sec_lines in sections_raw:
        kind = 'modify'
        for l in sec_lines[1:]:
            if l.startswith(b'new file mode'):
                kind = 'create'
                break
            if l.startswith(b'deleted file mode'):
                kind = 'delete'
                break
        hunks = []
        idx = 0
        L = len(sec_lines)
        while idx < L:
            line = sec_lines[idx]
            if line.startswith(b'@@ '):
                m = header_re.match(line)
                if not m:
                    idx += 1
                    continue
                a = int(m.group(1))
                b_cnt = int(m.group(2)) if m.group(2) is not None else 1
                c = int(m.group(3))  # unused
                d_cnt = int(m.group(4)) if m.group(4) is not None else 1

                old_lines = []
                new_lines = []
                last_marker = None
                j = idx + 1
                while j < L:
                    body = sec_lines[j]
                    if body.startswith(b'@@ ') or body.startswith(b'diff --git a/'):
                        break
                    if body.startswith(b'\\'):
                        if last_marker == b' ':
                            if old_lines:
                                old_lines[-1] = old_lines[-1].rstrip(b'\n')
                            if new_lines:
                                new_lines[-1] = new_lines[-1].rstrip(b'\n')
                        elif last_marker == b'-':
                            if old_lines:
                                old_lines[-1] = old_lines[-1].rstrip(b'\n')
                        elif last_marker == b'+':
                            if new_lines:
                                new_lines[-1] = new_lines[-1].rstrip(b'\n')
                        j += 1
                        continue
                    marker = body[0:1]
                    content = body[1:]
                    if marker == b' ':
                        old_lines.append(content)
                        new_lines.append(content)
                        last_marker = b' '
                    elif marker == b'-':
                        old_lines.append(content)
                        last_marker = b'-'
                    elif marker == b'+':
                        new_lines.append(content)
                        last_marker = b'+'
                    else:
                        last_marker = None
                    j += 1

                malformed = len(old_lines) != b_cnt or len(new_lines) != d_cnt
                hunks.append({
                    'a': a,
                    'b': b_cnt,
                    'd': d_cnt,
                    'old_lines': old_lines,
                    'new_lines': new_lines,
                    'malformed': malformed,
                })
                idx = j
            else:
                idx += 1
        parsed.append((path, kind, hunks))
    parsed.sort(key=lambda x: x[0])
    return parsed

def main():
    if len(sys.argv) < 2:
        return
    base_dir = sys.argv[1]
    tree_path = os.path.join(base_dir, 'tree')
    sections = parse_diff(base_dir)

    for path, kind, hunks in sections:
        out = [f"{path}: {kind}"]
        file_full = os.path.join(tree_path, path)
        error = False

        if kind == 'create':
            if os.path.isfile(file_full):
                out.append("  error: already exists")
                print('\n'.join(out))
                continue
            content_lines = []
            hunks_ok = True
        else:
            if not os.path.isfile(file_full):
                out.append("  error: not found")
                print('\n'.join(out))
                continue
            with open(file_full, 'rb') as f:
                data = f.read()
            content_lines = split_to_lines(data)
            hunks_ok = True

        delta = 0
        all_applied_ok = True

        for idx, h in enumerate(hunks, start=1):
            if h['malformed']:
                out.append(f"  hunk {idx}: malformed")
                all_applied_ok = False
                continue
            b_cnt = h['b']
            d_cnt = h['d']
            a = h['a']
            old_lines = h['old_lines']
            new_lines = h['new_lines']

            if b_cnt == 0:
                P = a + delta
                if 0 <= P <= len(content_lines):
                    content_lines[P:P] = new_lines
                    delta += d_cnt
                    out.append(f"  hunk {idx}: applied at {P} (offset 0)")
                else:
                    out.append(f"  hunk {idx}: rejected")
                    all_applied_ok = False
                continue

            P = a + delta
            best_p = None
            if len(content_lines) >= b_cnt:
                max_p = len(content_lines) - b_cnt + 1
                matches = []
                for p in range(1, max_p + 1):
                    ok = True
                    for k in range(b_cnt):
                        if content_lines[p - 1 + k] != old_lines[k]:
                            ok = False
                            break
                    if ok:
                        matches.append(p)
                if matches:
                    best_p = min(matches, key=lambda p: (abs(p - P), p))
                    offset = best_p - P
                    start_idx = best_p - 1
                    content_lines[start_idx:start_idx + b_cnt] = new_lines
                    delta += d_cnt - b_cnt
                    off_str = f"+{offset}" if offset > 0 else f"{offset}" if offset < 0 else "0"
                    out.append(f"  hunk {idx}: applied at {best_p} (offset {off_str})")
                else:
                    out.append(f"  hunk {idx}: rejected")
                    all_applied_ok = False
            else:
                out.append(f"  hunk {idx}: rejected")
                all_applied_ok = False

        if kind == 'delete':
            if all_applied_ok and len(content_lines) == 0:
                out.append("  result: deleted")
            else:
                nlines = len(content_lines)
                crc = zlib.crc32(reconstruct_bytes(content_lines)) & 0xffffffff
                out.append(f"  result: {nlines} lines, crc32 {crc:08x}")
        else:
            nlines = len(content_lines)
            crc = zlib.crc32(reconstruct_bytes(content_lines)) & 0xffffffff
            out.append(f"  result: {nlines} lines, crc32 {crc:08x}")

        print('\n'.join(out))

