import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.CRC32;

public class Main {

    static class Line {
        byte[] data;
        boolean hasNewline;
        Line(byte[] data, boolean hasNewline) {
            this.data = data;
            this.hasNewline = hasNewline;
        }
    }

    static class HunkResult {
        int number;
        boolean applied;
        boolean malformed;
        int appliedAt;
        int offset;
        HunkResult(int number) { this.number = number; }
    }

    static class SectionResult {
        String path;
        String kind;
        boolean error;
        String errorMsg;
        List<HunkResult> hunks = new ArrayList<>();
        int finalLines = 0;
        long crc = 0;
        boolean deleted = false;
    }

    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        Path base = Paths.get(args[0]);
        Path diffPath = base.resolve("changes.diff");
        Path treePath = base.resolve("tree");

        List<String> diffLines = Files.readAllLines(diffPath, StandardCharsets.UTF_8);
        List<SectionResult> sections = new ArrayList<>();

        int i = 0;
        Pattern diffPat = Pattern.compile("diff --git a/(.*) b/(.*)");
        while (i < diffLines.size()) {
            String line = diffLines.get(i);
            Matcher m = diffPat.matcher(line);
            if (!m.matches()) {
                i++;
                continue;
            }
            String path = m.group(1);
            // find section end
            int j = i + 1;
            while (j < diffLines.size() && !diffLines.get(j).startsWith("diff --git a/")) j++;
            // collect section lines
            List<String> secLines = new ArrayList<>();
            for (int k = i + 1; k < j; k++) secLines.add(diffLines.get(k));

            boolean isCreate = false;
            boolean isDelete = false;
            for (String s : secLines) {
                if (s.startsWith("new file mode ")) isCreate = true;
                if (s.startsWith("deleted file mode ")) isDelete = true;
            }
            String kind = isCreate ? "create" : isDelete ? "delete" : "modify";

            SectionResult secRes = new SectionResult();
            secRes.path = path;
            secRes.kind = kind;

            Path filePath = treePath.resolve(path);
            boolean fileExists = Files.exists(filePath);
            if (kind.equals("create")) {
                if (fileExists) {
                    secRes.error = true;
                    secRes.errorMsg = "already exists";
                } else {
                    processSection(secRes, secLines, filePath, true, treePath);
                }
            } else {
                if (!fileExists) {
                    secRes.error = true;
                    secRes.errorMsg = "not found";
                } else {
                    processSection(secRes, secLines, filePath, false, treePath);
                }
            }
            sections.add(secRes);
            i = j;
        }

        sections.sort(Comparator.comparing(s -> s.path));

        StringBuilder out = new StringBuilder();
        for (SectionResult s : sections) {
            out.append(s.path).append(": ").append(s.kind).append("\n");
            if (s.error) {
                out.append("  error: ").append(s.errorMsg).append("\n");
                continue;
            }
            int hn = 1;
            for (HunkResult hr : s.hunks) {
                if (hr.malformed) {
                    out.append("  hunk ").append(hr.number).append(": malformed\n");
                } else if (hr.applied) {
                    out.append("  hunk ").append(hr.number).append(": applied at ").append(hr.appliedAt)
                       .append(" (offset ").append(hr.offset >= 0 ? "+" : "").append(hr.offset).append(")\n");
                } else {
                    out.append("  hunk ").append(hr.number).append(": rejected\n");
                }
            }
            if (s.deleted) {
                out.append("  result: deleted\n");
            } else {
                out.append("  result: ").append(s.finalLines).append(" lines, crc32 ")
                   .append(String.format("%08x", s.crc)).append("\n");
            }
        }
        System.out.print(out.toString());
    }

    private static void processSection(SectionResult secRes, List<String> secLines, Path filePath, boolean isCreate, Path treePath) throws IOException {
        List<Line> cur;
        if (isCreate) {
            cur = new ArrayList<>();
        } else {
            cur = readFileLines(filePath);
        }
        int delta = 0;
        int hunkNum = 1;

        // find hunks
        int idx = 0;
        while (idx < secLines.size()) {
            String l = secLines.get(idx);
            if (l.startsWith("@@ ")) {
                // parse header
                Matcher hm = Pattern.compile("@@ -(\\d+)(?:,(\\d+))? \\+(\\d+)(?:,(\\d+))? @@").matcher(l);
                if (!hm.matches()) {
                    idx++;
                    continue;
                }
                int a = Integer.parseInt(hm.group(1));
                int b = hm.group(2) == null ? 1 : Integer.parseInt(hm.group(2));
                int c = Integer.parseInt(hm.group(3));
                int d = hm.group(4) == null ? 1 : Integer.parseInt(hm.group(4));

                // collect body lines
                List<String> body = new ArrayList<>();
                int j = idx + 1;
                while (j < secLines.size()) {
                    String bl = secLines.get(j);
                    if (bl.startsWith("@@ ")) break;
                    body.add(bl);
                    j++;
                }
                // parse body
                List<Line> oldLines = new ArrayList<>();
                List<Line> newLines = new ArrayList<>();
                int bi = 0;
                while (bi < body.size()) {
                    String bl = body.get(bi);
                    char marker = bl.charAt(0);
                    if (marker == '\\') {
                        bi++;
                        continue;
                    }
                    boolean hasNewline = true;
                    boolean skipNext = false;
                    if (bi + 1 < body.size() && body.get(bi + 1).startsWith("\\ ")) {
                        hasNewline = false;
                        skipNext = true;
                    }
                    String content = bl.substring(1);
                    byte[] data = content.getBytes(StandardCharsets.ISO_8859_1);
                    Line ln = new Line(data, hasNewline);
                    if (marker == ' ') {
                        oldLines.add(ln);
                        newLines.add(ln);
                    } else if (marker == '-') {
                        oldLines.add(ln);
                    } else if (marker == '+') {
                        newLines.add(ln);
                    }
                    bi++;
                    if (skipNext) bi++;
                }

                HunkResult hr = new HunkResult(hunkNum);
                if (oldLines.size() != b || newLines.size() != d) {
                    hr.malformed = true;
                } else {
                    if (b == 0) {
                        int P = a + delta;
                        if (P >= 0 && P <= cur.size()) {
                            // apply insertion
                            int insertPos = P;
                            cur.addAll(insertPos, newLines);
                            delta += d;
                            hr.applied = true;
                            hr.appliedAt = P;
                            hr.offset = 0;
                        } else {
                            hr.applied = false;
                        }
                    } else {
                        int P = a + delta;
                        int foundPos = -1;
                        int foundOffset = 0;
                        outer:
                        for (int dist = 0; ; dist++) {
                            int[] cand = {P - dist, P + dist};
                            for (int p : cand) {
                                if (dist == 0 && cand.length == 2 && p == P) {
                                    // only once
                                }
                                if (p < 1) continue;
                                if (p + b - 1 > cur.size()) continue;
                                boolean match = true;
                                for (int k = 0; k < b; k++) {
                                    Line cl = cur.get(p - 1 + k);
                                    Line ol = oldLines.get(k);
                                    if (!linesEqual(cl, ol)) { match = false; break; }
                                }
                                if (match) {
                                    foundPos = p;
                                    foundOffset = p - P;
                                    break outer;
                                }
                            }
                            // stop when both sides exhausted
                            if (P - dist < 1 && P + dist > cur.size()) break;
                        }
                        if (foundPos != -1) {
                            // replace
                            int startIdx = foundPos - 1;
                            for (int k = 0; k < b; k++) cur.remove(startIdx);
                            cur.addAll(startIdx, newLines);
                            delta += d - b;
                            hr.applied = true;
                            hr.appliedAt = foundPos;
                            hr.offset = foundOffset;
                        } else {
                            hr.applied = false;
                        }
                    }
                }
                secRes.hunks.add(hr);
                hunkNum++;
                idx = j;
            } else {
                idx++;
            }
        }

        // final result
        boolean allApplied = true;
        for (HunkResult hr : secRes.hunks) {
            if (!hr.malformed && !hr.applied) { allApplied = false; break; }
            if (hr.malformed) { allApplied = false; break; }
        }
        if (secRes.kind.equals("delete")) {
            if (allApplied && cur.size() == 0) {
                secRes.deleted = true;
            } else {
                secRes.finalLines = cur.size();
                secRes.crc = crc32OfLines(cur);
            }
        } else {
            secRes.finalLines = cur.size();
            secRes.crc = crc32OfLines(cur);
        }
    }

    private static List<Line> readFileLines(Path p) throws IOException {
        byte[] bytes = Files.readAllBytes(p);
        List<Line> lines = new ArrayList<>();
        if (bytes.length == 0) return lines;
        int start = 0;
        for (int i = 0; i < bytes.length; i++) {
            if (bytes[i] == '\n') {
                byte[] data = Arrays.copyOfRange(bytes, start, i);
                lines.add(new Line(data, true));
                start = i + 1;
            }
        }
        if (start < bytes.length) {
            byte[] data = Arrays.copyOfRange(bytes, start, bytes.length);
            lines.add(new Line(data, false));
        }
        return lines;
    }

    private static boolean linesEqual(Line a, Line b) {
        if (a.hasNewline != b.hasNewline) return false;
        return Arrays.equals(a.data, b.data);
    }

    private static long crc32OfLines(List<Line> lines) {
        CRC32 crc = new CRC32();
        for (Line l : lines) {
            crc.update(l.data);
            if (l.hasNewline) crc.update((byte) '\n');
        }
        return crc.getValue();
    }
}

