                body.add(bl);
                j++;
            }

            List<Line> oldLines = new ArrayList<>();
            List<Line> newLines = new ArrayList<>();
            int bi = 0;
            while (bi < body.size()) {
                String bl = body.get(bi);
                if (bl.isEmpty()) { bi++; continue; }
                char marker = bl.charAt(0);
                if (marker == '\\') { // \ No newline line
                    bi++;
                    continue;
                }
                boolean hasNewline = true;
                boolean skipNext = false;
                if (bi + 1 < body.size() && body.get(bi + 1).startsWith("\\ ")) {
                    hasNewline = false;
                    skipNext = true;
                }
                String content = bl.substring(1);
                byte[] data = content.getBytes(StandardCharsets.ISO_8859_1);
                Line ln = new Line(data, hasNewline);
                if (marker == ' ') {
                    oldLines.add(ln);
                    newLines.add(ln);
                } else if (marker == '-') {
                    oldLines.add(ln);
                } else if (marker == '+') {
                    newLines.add(ln);
                }
                bi++;
                if (skipNext) bi++;
            }

            HunkResult hr = new HunkResult(hunkNum);
            if (oldLines.size() != b || newLines.size() != d) {
                hr.malformed = true;
            } else {
                if (b == 0) {
                    int P = a + delta;
                    if (P >= 0 && P <= cur.size()) {
                        int insertPos = P;
                        cur.addAll(insertPos, newLines);
                        delta += d;
                        hr.applied = true;
                        hr.appliedAt = P;
                        hr.offset = 0;
                    } else {
                        hr.applied = false;
                    }
                } else {
                    int P = a + delta;
                    int foundPos = -1;
                    int foundOffset = 0;
                    outer:
                    for (int dist = 0; ; dist++) {
                        int[] cand = {P - dist, P + dist};
                        for (int p : cand) {
                            if (dist == 0 && p == P && cand.length == 2) {
                                // first time only
                            }
                            if (p < 1) continue;
                            if (p + b - 1 > cur.size()) continue;
                            boolean match = true;
                            for (int k = 0; k < b; k++) {
                                Line cl = cur.get(p - 1 + k);
                                Line ol = oldLines.get(k);
                                if (!linesEqual(cl, ol)) { match = false; break; }
                            }
                            if (match) {
                                foundPos = p;
                                foundOffset = p - P;
                                break outer;
                            }
                        }
                        if (P - dist < 1 && P + dist > cur.size()) break;
                    }
                    if (foundPos != -1) {
                        int startIdx = foundPos - 1;
                        for (int k = 0; k < b; k++) cur.remove(startIdx);
                        cur.addAll(startIdx, newLines);
                        delta += d - b;
                        hr.applied = true;
                        hr.appliedAt = foundPos;
                        hr.offset = foundOffset;
                    } else {
                        hr.applied = false;
                    }
                }
            }
            secRes.hunks.add(hr);
            hunkNum++;
            idx = j;
        }

        boolean allApplied = true;
        for (HunkResult hr : secRes.hunks) {
            if (hr.malformed) { allApplied = false; break; }
            if (!hr.applied) { allApplied = false; break; }
        }
        if (secRes.kind.equals("delete")) {
            if (allApplied && cur.size() == 0) {
                secRes.deleted = true;
            } else {
                secRes.finalLines = cur.size();
                secRes.crc = crc32OfLines(cur);
            }
        } else {
            secRes.finalLines = cur.size();
            secRes.crc = crc32OfLines(cur);
        }
    }

    private static List<Line> readFileLines(Path p) throws IOException {
        byte[] bytes = Files.readAllBytes(p);
        List<Line> lines = new ArrayList<>();
        if (bytes.length == 0) return lines;
        int start = 0;
        for (int i = 0; i < bytes.length; i++) {
            if (bytes[i] == '\n') {
                byte[] data = Arrays.copyOfRange(bytes, start, i);
                lines.add(new Line(data, true));
                start = i + 1;
            }
        }
        if (start < bytes.length) {
            byte[] data = Arrays.copyOfRange(bytes, start, bytes.length);
            lines.add(new Line(data, false));
        }
        return lines;
    }

    private static boolean linesEqual(Line a, Line b) {
        if (a.hasNewline != b.hasNewline) return false;
        return Arrays.equals(a.data, b.data);
    }

    private static long crc32OfLines(List<Line> lines) {
        CRC32 crc = new CRC32();
        for (Line l : lines) {
            crc.update(l.data);
            if (l.hasNewline) crc.update((byte) '\n');
        }
        return crc.getValue();
    }
}

