    if(s->type==0){
        get_int(obj,"x",&s->x);
        get_int(obj,"y",&s->y);
        get_int(obj,"w",&s->w);
        get_int(obj,"h",&s->h);
    }else if(s->type==1){
        get_int(obj,"cx",&s->cx);
        get_int(obj,"cy",&s->cy);
        get_int(obj,"r",&s->cr);
    }else if(s->type==2){
        const char *p=strstr(obj,"\"points\"");
        if(p){
            p=strchr(p,'[');
            if(p) sscanf(p,"[[%d,%d],[%d,%d],[%d,%d]]",
                &s->p0x,&s->p0y,&s->p1x,&s->p1y,&s->p2x,&s->p2y);
        }
    }else if(s->type==3){
        get_int(obj,"x1",&s->x1);
        get_int(obj,"y1",&s->y1);
        get_int(obj,"x2",&s->x2);
        get_int(obj,"y2",&s->y2);
        get_int(obj,"r",&s->lr);
    }
}

/* PNG helpers */
static uint32_t crc_table[256];
static void crc_init(){
    for(int i=0;i<256;i++){
        uint32_t c=i;
        for(int j=0;j<8;j++) c = (c&1)? (0xEDB88320U ^ (c>>1)) : (c>>1);
        crc_table[i]=c;
    }
}
static uint32_t crc32(const unsigned char *data, size_t len){
    uint32_t c=0xffffffffU;
    for(size_t i=0;i<len;i++) c = crc_table[(c ^ data[i]) & 0xff] ^ (c>>8);
    return c ^ 0xffffffffU;
}
static void write_be32(FILE *f, uint32_t v){
    unsigned char b[4]={v>>24,(v>>16)&0xff,(v>>8)&0xff,v&0xff};
    fwrite(b,1,4,f);
}
static uint32_t adler32(const unsigned char *data, size_t len){
    const uint32_t MOD=65521;
    uint32_t a=1,b=0;
    for(size_t i=0;i<len;i++){ a+=data[i]; if(a>=MOD) a-=MOD; b+=a; if(b>=MOD) b-=MOD; }
    return (b<<16)|a;
}

/* coverage */
static int covers_rect(const Shape *s,int x,int y){
    if(s->w<=0||s->h<=0) return 0;
    return x>=s->x && x < s->x + s->w && y>=s->y && y < s->y + s->h;
}
static int covers_circle(const Shape *s,int x,int y){
    long long dx=x-s->cx, dy=y-s->cy;
    long long r=s->cr;
    return dx*dx+dy*dy <= r*r;
}
static int covers_triangle(const Shape *s,int x,int y){
    long long x0=s->p0x,y0=s->p0y;
    long long x1=s->p1x,y1=s->p1y;
    long long x2=s->p2x,y2=s->p2y;
    long long e0=(x1-x0)*(y-y0)-(y1-y0)*(x-x0);
    long long e1=(x2-x1)*(y-y1)-(y2-y1)*(x-x1);
    long long e2=(x0-x2)*(y-y2)-(y0-y2)*(x-x2);
    return (e0>=0 && e1>=0 && e2>=0) || (e0<=0 && e1<=0 && e2<=0);
}
static int covers_line(const Shape *s,int x,int y){
    long long x1=s->x1,y1=s->y1,x2=s->x2,y2=s->y2;
    long long r=s->lr;
    long long dx=x2-x1, dy=y2-y1;
    long long L=dx*dx+dy*dy;
    long long t=(x-x1)*dx+(y-y1)*dy;
    if(L==0){
        long long d=(x-x1)*(x-x1)+(y-y1)*(y-y1);
        return d<=r*r;
    }
    if(t<=0){
        long long d=(x-x1)*(x-x1)+(y-y1)*(y-y1);
        return d<=r*r;
    }
    if(t>=L){
        long long d=(x-x2)*(x-x2)+(y-y2)*(y-y2);
        return d<=r*r;
    }
    long long c=(x-x1)*dy-(y-y1)*dx;
    return c*c <= r*r*L;
}

int main(int argc,char *argv[]){
    if(argc<2){fprintf(stderr,"usage\n");return 1;}
    char path[1024];
    snprintf(path,sizeof path,"%s/scene.json",argv[1]);
    FILE *f=fopen(path,"rb");
    if(!f){perror("open");return 1;}
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);

    char *p=buf;
    skip_ws(&p);
    if(*p!='{') return 1;
    p++;
    int width=0,height=0;
    uint8_t bg[3]={255,255,255};
    Shape shapes[100]; int nshapes=0;
    while(*p && *p!='}'){
        skip_ws(&p);
        char key[64];
        if(*p=='"'){p++; size_t i=0; while(*p && *p!='"' && i<sizeof key-1) key[i++]=*p++; key[i]=0; if(*p=='"')p++;}
        else {p++;continue;}
        skip_ws(&p); if(*p==':')p++;
        skip_ws(&p);
        if(strcmp(key,"width")==0){ width=parse_int_local(&p); }
        else if(strcmp(key,"height")==0){ height=parse_int_local(&p); }
        else if(strcmp(key,"background")==0){
            if(*p=='[')p++;
            bg[0]=(uint8_t)parse_int_local(&p); skip_ws(&p); if(*p==',')p++;
            bg[1]=(uint8_t)parse_int_local(&p); skip_ws(&p); if(*p==',')p++;
            bg[2]=(uint8_t)parse_int_local(&p); skip_ws(&p); if(*p==']')p++;
        }else if(strcmp(key,"shapes")==0){
            skip_ws(&p); if(*p=='[')p++;
            while(1){
                skip_ws(&p);
                if(*p==']'){p++;break;}
                if(*p=='{'){
                    char *obj_start=p;
                    int depth=0; char *q=p;
                    while(*q){ if(*q=='{')depth++; if(*q=='}'){depth--; if(depth==0){q++;break;}} q++; }
                    size_t len=q-obj_start;
                    char *obj_buf=malloc(len+1); memcpy(obj_buf,obj_start,len); obj_buf[len]=0;
                    Shape s; parse_shape_buf(obj_buf,&s);
                    shapes[nshapes++]=s;
                    free(obj_buf);
                    p=q;
                }else p++;
                skip_ws(&p); if(*p==',')p++;
            }
        }
        skip_ws(&p); if(*p==',')p++;
    }

    size_t pix = (size_t)width*height;
    uint8_t *canvas = malloc(pix*3);
    for(size_t i=0;i<pix;i++){ canvas[i*3+0]=bg[0]; canvas[i*3+1]=bg[1]; canvas[i*3+2]=bg[2]; }

    for(int i=0;i<nshapes;i++){
        Shape *s=&shapes[i];
        int cnt=0;
        for(int y=0;y<height;y++){
            for(int x=0;x<width;x++){
                int cov=0;
                if(s->type==0) cov=covers_rect(s,x,y);
                else if(s->type==1) cov=covers_circle(s,x,y);
                else if(s->type==2) cov=covers_triangle(s,x,y);
                else if(s->type==3) cov=covers_line(s,x,y);
                if(cov){
                    cnt++;
                    size_t idx=(size_t)(y*width+x)*3;
                    uint8_t dR=canvas[idx], dG=canvas[idx+1], dB=canvas[idx+2];
                    uint8_t a=s->ca_;
                    if(a!=0){
                        int nr = (s->cr_*a + dR*(255-a)+127)/255;
                        int ng = (s->cg_*a + dG*(255-a)+127)/255;
                        int nb = (s->cb_*a + dB*(255-a)+127)/255;
                        canvas[idx]= (uint8_t)nr;
                        canvas[idx+1]= (uint8_t)ng;
                        canvas[idx+2]= (uint8_t)nb;
                    }
                }
            }
        }
        s->cover=cnt;
        const char *tn="?";
        if(s->type==0) tn="rect";
        else if(s->type==1) tn="circle";
        else if(s->type==2) tn="triangle";
        else if(s->type==3) tn="line";
        printf("%d %s %d\n", i+1, tn, cnt);
    }

    uint32_t *cols=malloc(pix*sizeof(uint32_t));
    for(size_t i=0;i<pix;i++){
        uint32_t c = ((uint32_t)canvas[i*3]<<16)|((uint32_t)canvas[i*3+1]<<8)|canvas[i*3+2];
        cols[i]=c;
    }
    int cmp32(const void *a,const void *b){ uint32_t x=*(uint32_t*)a, y=*(uint32_t*)b; return (x>y)-(x<y); }
    qsort(cols,pix,sizeof(uint32_t),cmp32);
    int distinct=0;
    for(size_t i=0;i<pix;i++){ if(i==0 || cols[i]!=cols[i-1]) distinct++; }
    printf("colors %d\n", distinct);
    free(cols);

    /* PNG output */
    crc_init();
    FILE *out=fopen("out.png","wb");
    unsigned char sig[8]={0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A};
    fwrite(sig,1,8,out);

    /* IHDR */
    unsigned char ihdr[13];
    ihdr[0]=(width>>24)&0xff; ihdr[1]=(width>>16)&0xff; ihdr[2]=(width>>8)&0xff; ihdr[3]=width&0xff;
    ihdr[4]=(height>>24)&0xff; ihdr[5]=(height>>16)&0xff; ihdr[6]=(height>>8)&0xff; ihdr[7]=height&0xff;
    ihdr[8]=8; ihdr[9]=2; ihdr[10]=0; ihdr[11]=0; ihdr[12]=0;
    write_be32(out,13);
    fwrite("IHDR",1,4,out);
    fwrite(ihdr,1,13,out);
    {
        unsigned char tmp[17]; memcpy(tmp,"IHDR",4); memcpy(tmp+4,ihdr,13);
        write_be32(out,crc32(tmp,17));
    }

    /* raw scanlines */
    size_t rawlen = (size_t)height*(1+width*3);
    unsigned char *raw=malloc(rawlen);
    size_t off=0;
    for(int y=0;y<height;y++){
        raw[off++]=0;
        for(int x=0;x<width;x++){
            size_t idx=(size_t)(y*width+x)*3;
            raw[off++]=canvas[idx];
            raw[off++]=canvas[idx+1];
            raw[off++]=canvas[idx+2];
        }
    }

    /* build zlib stream */
    size_t max_zlib = 2 + rawlen + 12 + 4;
    unsigned char *zlib_buf=malloc(max_zlib);
    size_t zpos=0;
    zlib_buf[zpos++]=0x78; zlib_buf[zpos++]=0x01;
    size_t remaining=rawlen;
    size_t rpos=0;
    uint32_t adler=adler32(raw,rawlen);
    while(remaining>0){
        size_t chunk = remaining>65535?65535:remaining;
        unsigned char hdr = (remaining==chunk)?0x01:0x00;
        zlib_buf[zpos++]=hdr;
        zlib_buf[zpos++]=(unsigned char)(chunk & 0xff);
        zlib_buf[zpos++]=(unsigned char)((chunk>>8)&0xff);
        uint16_t nlen = ~((uint16_t)chunk);
        zlib_buf[zpos++]=(unsigned char)(nlen & 0xff);
        zlib_buf[zpos++]=(unsigned char)((nlen>>8)&0xff);
        memcpy(zlib_buf+zpos, raw+rpos, chunk);
        zpos+=chunk;
        rpos+=chunk; remaining-=chunk;
    }
    zlib_buf[zpos++]=(adler>>24)&0xff;
    zlib_buf[zpos++]=(adler>>16)&0xff;
    zlib_buf[zpos++]=(adler>>8)&0xff;
    zlib_buf[zpos++]=adler&0xff;
    size_t zlib_len=zpos;

    write_be32(out,(uint32_t)zlib_len);
    fwrite("IDAT",1,4,out);
    fwrite(zlib_buf,1,zlib_len,out);
    {
        unsigned char tmp[4+zlib_len];
        memcpy(tmp,"IDAT",4);
        memcpy(tmp+4,zlib_buf,zlib_len);
        write_be32(out,crc32(tmp,4+zlib_len));
    }

    /* IEND */
    write_be32(out,0);
    fwrite("IEND",1,4,out);
    {
        unsigned char tmp[4]; memcpy(tmp,"IEND",4);
        write_be32(out,crc32(tmp,4));
    }

    fclose(out);
    free(canvas); free(raw); free(zlib_buf); free(buf);
    return 0;
}

use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::io::{Write, Result as IoResult};

#[derive(Debug)]
enum Value {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<Value>),
    Object(HashMap<String, Value>),
}

struct Parser {
    s: Vec<u8>,
    pos: usize,
}
impl Parser {
    fn new(s: String) -> Self {
        Self { s: s.into_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            match self.s[self.pos] {
                b' ' | b'\n' | b'\r' | b'\t' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        if self.pos < self.s.len() { Some(self.s[self.pos]) } else { None }
    }
    fn consume(&mut self, b: u8) {
        assert_eq!(self.s[self.pos], b);
        self.pos += 1;
    }
    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(Value::String(self.parse_string()?)),
            Some(b'-') | Some(c) if c.is_ascii_digit() => Ok(Value::Number(self.parse_number()?)),
            _ => Err("unexpected token".into()),
        }
    }
    fn parse_object(&mut self) -> Result<Value, String> {
        self.consume(b'{');
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.consume(b'}'); return Ok(Value::Object(map)); }
        loop {
            let key = self.parse_string()?;
            self.skip_ws();
            self.consume(b':');
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.consume(b','); }
                Some(b'}') => { self.consume(b'}'); break; }
                _ => return Err("expected , or }".into()),
            }
        }
        Ok(Value::Object(map))
    }
    fn parse_array(&mut self) -> Result<Value, String> {
        self.consume(b'[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.consume(b']'); return Ok(Value::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.consume(b','); }
                Some(b']') => { self.consume(b']'); break; }
                _ => return Err("expected , or ]".into()),
            }
        }
        Ok(Value::Array(arr))
    }
    fn parse_string(&mut self) -> Result<String, String> {
        self.consume(b'"');
        let start = self.pos;
        while self.pos < self.s.len() {
            let b = self.s[self.pos];
            if b == b'"' {
                let s = String::from_utf8_lossy(&self.s[start..self.pos]).to_string();
                self.pos += 1;
                return Ok(s);
            }
            if b == b'\\' { self.pos += 2; } else { self.pos += 1; }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<i64, String> {
        let start = self.pos;
        if self.s[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.s.len() && self.s[self.pos].is_ascii_digit() { self.pos += 1; }
        let txt = String::from_utf8_lossy(&self.s[start..self.pos]).to_string();
        txt.parse::<i64>().map_err(|e| e.to_string())
    }
}

fn get_obj(v: &Value) -> Option<&HashMap<String, Value>> {
    if let Value::Object(m) = v { Some(m) } else { None }
}
fn get_arr(v: &Value) -> Option<&Vec<Value>> {
    if let Value::Array(a) = v { Some(a) } else { None }
}
fn get_num(v: &Value) -> Option<i64> {
    if let Value::Number(n) = v { Some(*n) } else { None }
}
fn get_str(v: &Value) -> Option<&String> {
    if let Value::String(s) = v { Some(s) } else { None }
}

#[derive(Debug)]
enum ShapeKind {
    Rect { x:i32, y:i32, w:i32, h:i32, col:[u8;4] },
    Circle { cx:i32, cy:i32, r:i32, col:[u8;4] },
    Triangle { p0:(i32,i32), p1:(i32,i32), p2:(i32,i32), col:[u8;4] },
    Line { x1:i32, y1:i32, x2:i32, y2:i32, r:i32, col:[u8;4] },
}

fn parse_color(arr: &Vec<Value>) -> [u8;4] {
    let mut c = [0u8;4];
    for (i, v) in arr.iter().take(4).enumerate() {
        if let Some(n) = get_num(v) { c[i] = n as u8; }
    }
    c
}

fn shape_from_value(v: &Value) -> Option<ShapeKind> {
    let obj = get_obj(v)?;
    let typ = get_str(&obj.get("type")?)? .as_str();
    match typ {
        "rect" => {
            let x = get_num(&obj.get("x")?)? as i32;
            let y = get_num(&obj.get("y")?)? as i32;
            let w = get_num(&obj.get("w")?)? as i32;
            let h = get_num(&obj.get("h")?)? as i32;
            let col = parse_color(get_arr(&obj.get("color")?).unwrap());
            Some(ShapeKind::Rect { x, y, w, h, col })
        }
        "circle" => {
            let cx = get_num(&obj.get("cx")?)? as i32;
            let cy = get_num(&obj.get("cy")?)? as i32;
            let r = get_num(&obj.get("r")?)? as i32;
            let col = parse_color(get_arr(&obj.get("color")?).unwrap());
            Some(ShapeKind::Circle { cx, cy, r, col })
        }
        "triangle" => {
            let pts = get_arr(&obj.get("points")?).unwrap();
            let mut ps = [(0,0);3];
            for (i, pv) in pts.iter().enumerate().take(3) {
                let a = get_arr(pv).unwrap();
                let x = get_num(&a[0])? as i32;
                let y = get_num(&a[1])? as i32;
                ps[i] = (x,y);
            }
            let col = parse_color(get_arr(&obj.get("color")?).unwrap());
            Some(ShapeKind::Triangle { p0:ps[0], p1:ps[1], p2:ps[2], col })
        }
        "line" => {
            let x1 = get_num(&obj.get("x1")?)? as i32;
            let y1 = get_num(&obj.get("y1")?)? as i32;
            let x2 = get_num(&obj.get("x2")?)? as i32;
            let y2 = get_num(&obj.get("y2")?)? as i32;
            let r = get_num(&obj.get("r")?)? as i32;
            let col = parse_color(get_arr(&obj.get("color")?).unwrap());
            Some(ShapeKind::Line { x1, y1, x2, y2, r, col })
        }
        _ => None
    }
}

fn covers(shape: &ShapeKind, x: i32, y: i32) -> bool {
    match shape {
        ShapeKind::Rect { x:rx, y:ry, w, h, .. } => {
            x >= *rx && x < *rx + *w && y >= *ry && y < *ry + *h
        }
        ShapeKind::Circle { cx, cy, r, .. } => {
            let dx = x - *cx; let dy = y - *cy;
            let d2 = (dx as i64)*(dx as i64) + (dy as i64)*(dy as i64);
            d2 <= (*r as i64)*(*r as i64)
        }
        ShapeKind::Triangle { p0, p1, p2, .. } => {
            let pts = [*p0, *p1, *p2];
            let mut es = Vec::new();
            for i in 0..3 {
                let (x1,y1) = pts[i];
                let (x2,y2) = pts[(i+1)%3];
                let e = (x2 - x1) as i64 * (y as i64 - y1 as i64) - (y2 - y1) as i64 * (x as i64 - x1 as i64);
                es.push(e);
            }
            let all_ge = es.iter().all(|&e| e >= 0);
            let all_le = es.iter().all(|&e| e <= 0);
            all_ge || all_le
        }
        ShapeKind::Line { x1, y1, x2, y2, r, .. } => {
            let dx = *x2 as i64 - *x1 as i64;
            let dy = *y2 as i64 - *y1 as i64;
            let l = dx*dx + dy*dy;
            let t = (x as i64 - *x1 as i64)*dx + (y as i64 - *y1 as i64)*dy;
            let r64 = *r as i64;
            if t <= 0 {
                let d2 = (x as i64 - *x1 as i64).pow(2) + (y as i64 - *y1 as i64).pow(2);
                d2 <= r64*r64
            } else if t >= l {
                let d2 = (x as i64 - *x2 as i64).pow(2) + (y as i64 - *y2 as i64).pow(2);
                d2 <= r64*r64
            } else {
                let c = (x as i64 - *x1 as i64)*dy - (y as i64 - *y1 as i64)*dx;
                c*c <= r64*r64 * l
            }
        }
    }
}

fn blend(dst: u8, src: u8, a: u8) -> u8 {
    let v = (src as u32 * a as u32 + dst as u32 * (255 - a as u32) + 127) / 255;
    v as u8
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320; } else { crc >>= 1; }
        }
    }
    crc ^ 0xffffffff
}

fn write_chunk<W: Write>(w: &mut W, typ: &[u8;4], data: &[u8]) -> IoResult<()> {
    let len = data.len() as u32;
    w.write_all(&len.to_be_bytes())?;
    w.write_all(typ)?;
    w.write_all(data)?;
    let crc = crc32(&[&typ[..], data].concat());
    w.write_all(&crc.to_be_bytes())?;
    Ok(())
}

fn adler32(data: &[u8]) -> u32 {
    const MOD: u32 = 65521;
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for &byte in data {
        a = (a + byte as u32) % MOD;
        b = (b + a) % MOD;
    }
    (b << 16) | a
}

fn main() -> IoResult<()> {
    let args: Vec<String> = env::args().collect();
    let dir = if args.len() > 1 { &args[1] } else { "." };
    let scene_path = std::path::Path::new(dir).join("scene.json");
    let txt = fs::read_to_string(scene_path).expect("read scene");
    let mut parser = Parser::new(txt);
    let root_val = parser.parse_value().expect("parse json");
    let root_obj = get_obj(&root_val).expect("root object");
    let width = get_num(&root_obj.get("width").unwrap()).unwrap() as usize;
    let height = get_num(&root_obj.get("height").unwrap()).unwrap() as usize;
    let bg_arr = get_arr(&root_obj.get("background").unwrap()).unwrap();
    let bg = [get_num(&bg_arr[0]).unwrap() as u8, get_num(&bg_arr[1]).unwrap() as u8, get_num(&bg_arr[2]).unwrap() as u8];
    let shapes_arr = get_arr(&root_obj.get("shapes").unwrap()).unwrap();
    let mut shapes = Vec::new();
    for v in shapes_arr {
        if let Some(s) = shape_from_value(v) { shapes.push(s); }
    }

    let mut canvas = vec![bg; width * height];
    let mut counts = Vec::new();

    for shape in &shapes {
        let mut cnt = 0usize;
        let typ_str = match shape {
            ShapeKind::Rect {..} => "rect",
            ShapeKind::Circle {..} => "circle",
            ShapeKind::Triangle {..} => "triangle",
            ShapeKind::Line {..} => "line",
        };
        // first pass for count and blend
        for y in 0..height {
            for x in 0..width {
                if covers(shape, x as i32, y as i32) {
                    cnt += 1;
                    let idx = y * width + x;
                    let (sr, sg, sb, a) = match shape {
                        ShapeKind::Rect { col, .. } => (col[0], col[1], col[2], col[3]),
                        ShapeKind::Circle { col, .. } => (col[0], col[1], col[2], col[3]),
                        ShapeKind::Triangle { col, .. } => (col[0], col[1], col[2], col[3]),
                        ShapeKind::Line { col, .. } => (col[0], col[1], col[2], col[3]),
                    };
                    let pix = &mut canvas[idx];
                    pix[0] = blend(pix[0], sr, a);
                    pix[1] = blend(pix[1], sg, a);
                    pix[2] = blend(pix[2], sb, a);
                }
            }
        }
        // store for output
        println!("{} {} {}", shapes.iter().position(|s| std::ptr::eq(s, shape)).unwrap() + 1, typ_str, cnt);
        counts.push((typ_str, cnt));
    }

    // distinct colors
    let mut set = HashSet::new();
    for p in &canvas { set.insert(*p); }
    println!("colors {}", set.len());

    // write PNG
    let mut file = fs::File::create("out.png")?;
    file.write_all(&[0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A])?;
    // IHDR
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&(width as u32).to_be_bytes());
    ihdr.extend_from_slice(&(height as u32).to_be_bytes());
    ihdr.push(8); ihdr.push(2); ihdr.push(0); ihdr.push(0); ihdr.push(0);
    write_chunk(&mut file, b"IHDR", &ihdr)?;

    // raw image data
    let mut raw = Vec::new();
    for y in 0..height {
        raw.push(0);
        for x in 0..width {
            let idx = y * width + x;
            raw.push(canvas[idx][0]);
            raw.push(canvas[idx][1]);
            raw.push(canvas[idx][2]);
        }
    }
    let adler = adler32(&raw);
    let mut zlib = vec![0x78, 0x9C];
    for (i, chunk) in raw.chunks((1 + width * 3).max(1)).enumerate() {
        let is_last = i == raw.len() / (1 + width * 3).max(1);
        // for simplicity, one block per row
        let row_len = if i == raw.len() / (1 + width * 3).max(1) { raw.len() - (i * (1 + width * 3)) } else { 1 + width * 3 };
        // Actually we already have raw built per row, easier: rebuild per row
    }
    // rebuild correctly per row
    let mut zlib2 = vec![0x78, 0x9C];
    let mut raw2 = Vec::new();
    for y in 0..height {
        raw2.push(0);
        for x in 0..width {
            let idx = y * width + x;
            raw2.push(canvas[idx][0]);
            raw2.push(canvas[idx][1]);
            raw2.push(canvas[idx][2]);
        }
        let row_data = &raw2[raw2.len() - (1 + width * 3)..];
        let is_last = y == height - 1;
        let header = if is_last { 0x01 } else { 0x00 };
        let len = (1 + width * 3) as u16;
        let nlen = !len;
        zlib2.push(header);
        zlib2.extend_from_slice(&len.to_le_bytes());
        zlib2.extend_from_slice(&nlen.to_le_bytes());
        zlib2.extend_from_slice(row_data);
    }
    zlib2.extend_from_slice(&adler.to_be_bytes());
    write_chunk(&mut file, b"IDAT", &zlib2)?;
    write_chunk(&mut file, b"IEND", &[])?;
    Ok(())
}

use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::io::{Write, Result as IoResult};

#[derive(Debug)]
enum Value {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<Value>),
    Object(HashMap<String, Value>),
}

struct Parser {
    s: Vec<u8>,
    pos: usize,
}
impl Parser {
    fn new(txt: String) -> Self {
        Self { s: txt.into_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            match self.s[self.pos] {
                b' ' | b'\n' | b'\r' | b'\t' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        self.s.get(self.pos).copied()
    }
    fn consume(&mut self, b: u8) {
        assert_eq!(self.s[self.pos], b);
        self.pos += 1;
    }
    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(Value::String(self.parse_string()?)),
            Some(b'-') => Ok(Value::Number(self.parse_number()?)),
            Some(c) if c.is_ascii_digit() => Ok(Value::Number(self.parse_number()?)),
            _ => Err("unexpected token".into()),
        }
    }
    fn parse_object(&mut self) -> Result<Value, String> {
        self.consume(b'{');
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.consume(b'}'); return Ok(Value::Object(map)); }
        loop {
            let key = self.parse_string()?;
            self.skip_ws();
            self.consume(b':');
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.consume(b','); }
                Some(b'}') => { self.consume(b'}'); break; }
                _ => return Err("expected , or }".into()),
            }
        }
        Ok(Value::Object(map))
    }
    fn parse_array(&mut self) -> Result<Value, String> {
        self.consume(b'[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.consume(b']'); return Ok(Value::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.consume(b','); }
                Some(b']') => { self.consume(b']'); break; }
                _ => return Err("expected , or ]".into()),
            }
        }
        Ok(Value::Array(arr))
    }
    fn parse_string(&mut self) -> Result<String, String> {
        self.consume(b'"');
        let mut out = Vec::new();
        while self.pos < self.s.len() {
            let b = self.s[self.pos];
            if b == b'"' { self.pos += 1; return String::from_utf8(out).map_err(|e| e.to_string()); }
            if b == b'\\' {
                self.pos += 1;
                if self.pos >= self.s.len() { return Err("bad escape".into()); }
                let esc = self.s[self.pos];
                out.push(match esc {
                    b'"' | b'\\' | b'/' => esc,
                    b'b' => b'\x08',
                    b'f' => b'\x0c',
                    b'n' => b'\n',
                    b'r' => b'\r',
                    b't' => b'\t',
                    _ => esc,
                });
                self.pos += 1;
            } else {
                out.push(b);
                self.pos += 1;
            }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<i64, String> {
        let start = self.pos;
        if self.s.get(self.pos) == Some(&b'-') { self.pos += 1; }
        while self.pos < self.s.len() && self.s[self.pos].is_ascii_digit() { self.pos += 1; }
        let txt = String::from_utf8_lossy(&self.s[start..self.pos]).to_string();
        txt.parse::<i64>().map_err(|e| e.to_string())
    }
}

fn as_object(v: &Value) -> Option<&HashMap<String, Value>> {
    if let Value::Object(m) = v { Some(m) } else { None }
}
fn as_array(v: &Value) -> Option<&Vec<Value>> {
    if let Value::Array(a) = v { Some(a) } else { None }
}
fn as_num(v: &Value) -> Option<i64> {
    if let Value::Number(n) = v { Some(*n) } else { None }
}
fn as_str(v: &Value) -> Option<&String> {
    if let Value::String(s) = v { Some(s) } else { None }
}

#[derive(Debug)]
enum ShapeKind {
    Rect { x:i32, y:i32, w:i32, h:i32, col:[u8;4] },
    Circle { cx:i32, cy:i32, r:i32, col:[u8;4] },
    Triangle { p0:(i32,i32), p1:(i32,i32), p2:(i32,i32), col:[u8;4] },
    Line { x1:i32, y1:i32, x2:i32, y2:i32, r:i32, col:[u8;4] },
}

fn parse_color(arr: &Vec<Value>) -> [u8;4] {
    let mut c = [0u8;4];
    for (i, v) in arr.iter().take(4).enumerate() {
        if let Some(n) = as_num(v) { c[i] = n as u8; }
    }
    c
}

fn shape_from_value(v: &Value) -> Option<ShapeKind> {
    let obj = as_object(v)?;
    let typ = as_str(obj.get("type")?)? .as_str();
    match typ {
        "rect" => {
            let x = as_num(obj.get("x")?)? as i32;
            let y = as_num(obj.get("y")?)? as i32;
            let w = as_num(obj.get("w")?)? as i32;
            let h = as_num(obj.get("h")?)? as i32;
            let col = parse_color(as_array(obj.get("color")?).unwrap());
            Some(ShapeKind::Rect { x, y, w, h, col })
        }
        "circle" => {
            let cx = as_num(obj.get("cx")?)? as i32;
            let cy = as_num(obj.get("cy")?)? as i32;
            let r = as_num(obj.get("r")?)? as i32;
            let col = parse_color(as_array(obj.get("color")?).unwrap());
            Some(ShapeKind::Circle { cx, cy, r, col })
        }
        "triangle" => {
            let pts = as_array(obj.get("points")?).unwrap();
            let mut ps = [(0,0);3];
            for (i, pv) in pts.iter().enumerate().take(3) {
                let a = as_array(pv).unwrap();
                let x = as_num(&a[0])? as i32;
                let y = as_num(&a[1])? as i32;
                ps[i] = (x,y);
            }
            let col = parse_color(as_array(obj.get("color")?).unwrap());
            Some(ShapeKind::Triangle { p0:ps[0], p1:ps[1], p2:ps[2], col })
        }
        "line" => {
            let x1 = as_num(obj.get("x1")?)? as i32;
            let y1 = as_num(obj.get("y1")?)? as i32;
            let x2 = as_num(obj.get("x2")?)? as i32;
            let y2 = as_num(obj.get("y2")?)? as i32;
            let r = as_num(obj.get("r")?)? as i32;
            let col = parse_color(as_array(obj.get("color")?).unwrap());
            Some(ShapeKind::Line { x1, y1, x2, y2, r, col })
        }
        _ => None
    }
}

fn covers(shape: &ShapeKind, x: i32, y: i32) -> bool {
    match shape {
        ShapeKind::Rect { x:rx, y:ry, w, h, .. } => {
            x >= *rx && x < *rx + *w && y >= *ry && y < *ry + *h
        }
        ShapeKind::Circle { cx, cy, r, .. } => {
            let dx = x - *cx; let dy = y - *cy;
            let d2 = (dx as i64)*(dx as i64) + (dy as i64)*(dy as i64);
            d2 <= (*r as i64)*(*r as i64)
        }
        ShapeKind::Triangle { p0, p1, p2, .. } => {
            let pts = [*p0, *p1, *p2];
            let mut es = [0i64;3];
            for i in 0..3 {
                let (x1,y1) = pts[i];
                let (x2,y2) = pts[(i+1)%3];
                let e = (x2 - x1) as i64 * (y as i64 - y1 as i64) - (y2 - y1) as i64 * (x as i64 - x1 as i64);
                es[i] = e;
            }
            let all_ge = es.iter().all(|&e| e >= 0);
            let all_le = es.iter().all(|&e| e <= 0);
            all_ge || all_le
        }
        ShapeKind::Line { x1, y1, x2, y2, r, .. } => {
            let dx = *x2 as i64 - *x1 as i64;
            let dy = *y2 as i64 - *y1 as i64;
            let l = dx*dx + dy*dy;
            let t = (x as i64 - *x1 as i64)*dx + (y as i64 - *y1 as i64)*dy;
            let r64 = *r as i64;
            if t <= 0 {
                let d2 = (x as i64 - *x1 as i64).pow(2) + (y as i64 - *y1 as i64).pow(2);
                d2 <= r64*r64
            } else if t >= l {
                let d2 = (x as i64 - *x2 as i64).pow(2) + (y as i64 - *y2 as i64).pow(2);
                d2 <= r64*r64
            } else {
                let c = (x as i64 - *x1 as i64)*dy - (y as i64 - *y1 as i64)*dx;
                c*c <= r64*r64 * l
            }
        }
    }
}

fn blend(dst: u8, src: u8, a: u8) -> u8 {
    let v = (src as u32 * a as u32 + dst as u32 * (255 - a as u32) + 127) / 255;
    v as u8
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320; } else { crc >>= 1; }
        }
    }
    crc ^ 0xffffffff
}

fn write_chunk<W: Write>(w: &mut W, typ: &[u8;4], data: &[u8]) -> IoResult<()> {
    let len = data.len() as u32;
    w.write_all(&len.to_be_bytes())?;
    w.write_all(typ)?;
    w.write_all(data)?;
    let crc = crc32(&[&typ[..], data].concat());
    w.write_all(&crc.to_be_bytes())?;
    Ok(())
}

fn adler32(data: &[u8]) -> u32 {
    const MOD: u32 = 65521;
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for &byte in data {
        a = (a + byte as u32) % MOD;
        b = (b + a) % MOD;
    }
    (b << 16) | a
}

fn main() -> IoResult<()> {
    let args: Vec<String> = env::args().collect();
    let dir = if args.len() > 1 { &args[1] } else { "." };
    let scene_path = std::path::Path::new(dir).join("scene.json");
