    let width = as_num(root_obj.get("width").unwrap()).unwrap() as usize;
    let height = as_num(root_obj.get("height").unwrap()).unwrap() as usize;
    let bg_arr = as_array(root_obj.get("background").unwrap()).unwrap();
    let bg = [as_num(&bg_arr[0]).unwrap() as u8, as_num(&bg_arr[1]).unwrap() as u8, as_num(&bg_arr[2]).unwrap() as u8];
    let shapes_arr = as_array(root_obj.get("shapes").unwrap()).unwrap();
    let mut shapes = Vec::new();
    for v in shapes_arr {
        if let Some(s) = shape_from_value(v) { shapes.push(s); }
    }

    let mut canvas = vec![bg; width * height];

    for (idx, shape) in shapes.iter().enumerate() {
        let typ_str = match shape {
            ShapeKind::Rect {..} => "rect",
            ShapeKind::Circle {..} => "circle",
            ShapeKind::Triangle {..} => "triangle",
            ShapeKind::Line {..} => "line",
        };
        let mut cnt = 0usize;
        let (sr, sg, sb, a) = match shape {
            ShapeKind::Rect { col, .. } => (col[0], col[1], col[2], col[3]),
            ShapeKind::Circle { col, .. } => (col[0], col[1], col[2], col[3]),
            ShapeKind::Triangle { col, .. } => (col[0], col[1], col[2], col[3]),
            ShapeKind::Line { col, .. } => (col[0], col[1], col[2], col[3]),
        };
        for y in 0..height {
            for x in 0..width {
                if covers(shape, x as i32, y as i32) {
                    cnt += 1;
                    let i = y * width + x;
                    let pix = &mut canvas[i];
                    pix[0] = blend(pix[0], sr, a);
                    pix[1] = blend(pix[1], sg, a);
                    pix[2] = blend(pix[2], sb, a);
                }
            }
        }
        println!("{} {} {}", idx + 1, typ_str, cnt);
    }

    let mut set = HashSet::new();
    for p in &canvas { set.insert(*p); }
    println!("colors {}", set.len());

    // PNG
    let mut file = fs::File::create("out.png")?;
    file.write_all(&[0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A])?;
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&(width as u32).to_be_bytes());
    ihdr.extend_from_slice(&(height as u32).to_be_bytes());
    ihdr.push(8); ihdr.push(2); ihdr.push(0); ihdr.push(0); ihdr.push(0);
    write_chunk(&mut file, b"IHDR", &ihdr)?;

    // raw image
    let mut raw = Vec::new();
    for y in 0..height {
        raw.push(0);
        for x in 0..width {
            let i = y * width + x;
            raw.push(canvas[i][0]);
            raw.push(canvas[i][1]);
            raw.push(canvas[i][2]);
        }
    }
    let adler = adler32(&raw);
    let mut zlib = vec![0x78, 0x9C];
    let row_bytes = 1 + width * 3;
    for y in 0..height {
        let is_last = y == height - 1;
        let header = if is_last { 0x01 } else { 0x00 };
        let len = row_bytes as u16;
        let nlen = !len;
        zlib.push(header);
        zlib.extend_from_slice(&len.to_le_bytes());
        zlib.extend_from_slice(&nlen.to_le_bytes());
        let start = y * row_bytes;
        let end = start + row_bytes;
        zlib.extend_from_slice(&raw[start..end]);
    }
    zlib.extend_from_slice(&adler.to_be_bytes());
    write_chunk(&mut file, b"IDAT", &zlib)?;
    write_chunk(&mut file, b"IEND", &[])?;
    Ok(())
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        File schemaFile = new File(dir, "schema.proto");
        File binFile = new File(dir, "messages.bin");
        String schema = readAll(schemaFile);
        ProtoSchema ps = new ProtoSchema(schema);
        ProtoMessage root = ps.root;
        byte[] bin = readAllBytes(binFile);
        Decoder dec = new Decoder(root, ps);
        int pos = 0;
        StringBuilder out = new StringBuilder();
        while (pos < bin.length) {
            int len = (int) readVarintUnsigned(bin, pos)[0];
            int lenSize = (int) readVarintUnsigned(bin, pos)[1];
            pos += lenSize;
            if (pos + len > bin.length) len = bin.length - pos;
            byte[] rec = Arrays.copyOfRange(bin, pos, pos + len);
            pos += len;
            DecodedMessage dm = dec.decodeMessage(rec, root);
            String json = dm.toJson(root, ps);
            out.append(json).append('\n');
        }
        System.out.print(out.toString());
    }

    private static String readAll(File f) throws IOException {
        return new String(java.nio.file.Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
    }
    private static byte[] readAllBytes(File f) throws IOException {
        return java.nio.file.Files.readAllBytes(f.toPath());
    }

    /* ---------- proto parsing ---------- */
    static class ProtoSchema {
        Map<String, ProtoMessage> messages = new HashMap<>();
        Map<String, ProtoEnum> enums = new HashMap<>();
        ProtoMessage root;
    }

    static class ProtoMessage {
        String name;
        Map<Integer, FieldDef> fieldsByNum = new TreeMap<>();
        Map<String, FieldDef> fieldsByName = new HashMap<>();
        Map<String, ProtoMessage> nestedMessages = new HashMap<>();
        Map<String, ProtoEnum> nestedEnums = new HashMap<>();
    }

    static class ProtoEnum {
        String name;
        Map<Integer, String> valToName = new HashMap<>();
        Map<String, Integer> nameToVal = new HashMap<>();
    }

    static class FieldDef {
        String name;
        String jsonName;
        String typeName;
        int number;
        boolean repeated;
        boolean optionalLabel;
        boolean isOneof;
        String oneofName;
        boolean isMap;
        String mapKeyType;
        String mapValueType;
        Kind kind;
    }

    enum Kind { VARINT, FIXED32, FIXED64, STRING, BYTES, MESSAGE, MAP, ENUM }

    static class ProtoSchemaParser {
        String s;
        int i;
        ProtoSchema schema = new ProtoSchema();
        ProtoMessage rootMsg = null;
        int msgCount = 0;

        ProtoSchemaParser(String src) {
            src = stripComments(src);
            this.s = src;
            this.i = 0;
        }
        ProtoSchema parse() {
            while (i < s.length()) skipWs();
            if (i >= s.length()) return schema;
            while (i < s.length()) {
                if (matchKeyword("syntax")) skipTo(';');
                else if (matchKeyword("package")) skipTo(';');
                else if (matchKeyword("option")) skipTo(';');
                else if (matchKeyword("message")) {
                    ProtoMessage m = parseMessage(null);
                    if (rootMsg == null) rootMsg = m;
                    msgCount++;
                } else if (matchKeyword("enum")) {
                    parseEnum(null);
                } else {
                    i++;
                }
                skipWs();
            }
            schema.root = rootMsg;
            return schema;
        }

        ProtoMessage parseMessage(ProtoMessage parent) {
            expectKeyword("message");
            String name = readIdent();
            expect('{');
            ProtoMessage msg = new ProtoMessage();
            msg.name = name;
            if (parent != null) parent.nestedMessages.put(name, msg);
            else schema.messages.put(name, msg);
            parseMessageBody(msg);
            return msg;
        }

        void parseMessageBody(ProtoMessage msg) {
            while (true) {
                skipWs();
                if (i >= s.length()) break;
                char c = s.charAt(i);
                if (c == '}') { i++; break; }
                if (matchKeyword("message")) {
                    ProtoMessage child = parseMessage(msg);
                    // already stored
                } else if (matchKeyword("enum")) {
                    ProtoEnum e = parseEnum(msg);
                } else if (matchKeyword("oneof")) {
                    parseOneof(msg);
                } else if (matchKeyword("reserved")) {
                    skipTo(';');
                } else if (matchKeyword("option")) {
                    skipTo(';');
                } else {
                    parseField(msg, null);
                }
            }
        }

        void parseOneof(ProtoMessage msg) {
            expectKeyword("oneof");
            String oneofName = readIdent();
            expect('{');
            while (true) {
                skipWs();
                if (i >= s.length()) break;
                if (s.charAt(i) == '}') { i++; break; }
                parseField(msg, oneofName);
            }
        }

        ProtoEnum parseEnum(ProtoMessage parent) {
            expectKeyword("enum");
            String name = readIdent();
            expect('{');
            ProtoEnum e = new ProtoEnum();
            e.name = name;
            if (parent != null) parent.nestedEnums.put(name, e);
            else schema.enums.put(name, e);
            while (true) {
                skipWs();
                if (i >= s.length()) break;
                if (s.charAt(i) == '}') { i++; break; }
                String valName = readIdent();
                skipWs();
                expect('=');
                int val = readInt();
                skipWs();
                expect(';');
                e.valToName.put(val, valName);
                e.nameToVal.put(valName, val);
            }
            return e;
