        void parseField(ProtoMessage msg, String oneofName) {
            boolean repeated = false;
            boolean optional = false;
            if (matchKeyword("repeated")) { repeated = true; skipWs(); }
            else if (matchKeyword("optional")) { optional = true; skipWs(); }

            String typeName;
            boolean isMap = false;
            String mapKey = null, mapVal = null;
            if (s.startsWith("map<")) {
                isMap = true;
                i += 4; // map<
                skipWs();
                mapKey = readIdent();
                skipWs();
                expect(',');
                skipWs();
                mapVal = readIdent();
                skipWs();
                expect('>');
                skipWs();
                typeName = "map";
            } else {
                typeName = readIdent();
            }
            skipWs();
            String fieldName = readIdent();
            skipWs();
            expect('=');
            int number = readInt();
            skipWs();
            if (i < s.length() && s.charAt(i) == '[') {
                int depth = 0;
                while (i < s.length()) {
                    char c = s.charAt(i);
                    if (c == '[') depth++;
                    if (c == ']') { depth--; if (depth == 0) { i++; break; } }
                    i++;
                }
            }
            skipWs();
            expect(';');

            FieldDef f = new FieldDef();
            f.name = fieldName;
            f.jsonName = toCamel(fieldName);
            f.typeName = typeName;
            f.number = number;
            f.repeated = repeated;
            f.optionalLabel = optional;
            f.isOneof = oneofName != null;
            f.oneofName = oneofName;
            f.isMap = isMap;
            f.mapKeyType = mapKey;
            f.mapValueType = mapVal;
            f.kind = deduceKind(typeName, isMap);
            msg.fieldsByNum.put(number, f);
            msg.fieldsByName.put(fieldName, f);
        }

        Kind deduceKind(String type, boolean isMap) {
            if (isMap) return Kind.MAP;
            switch (type) {
                case "int32": case "int64": case "uint32": case "uint64":
                case "sint32": case "sint64": case "bool":
                    return Kind.VARINT;
                case "fixed32": case "sfixed32":
                    return Kind.FIXED32;
                case "fixed64": case "sfixed64":
                    return Kind.FIXED64;
                case "string": return Kind.STRING;
                case "bytes": return Kind.BYTES;
                default:
