                    return Kind.MESSAGE;
            }
        }

        /* helpers */
        String stripComments(String src) {
            src = src.replaceAll("//.*", "");
            src = src.replaceAll("/\\*.*?\\*/", "");
            return src;
        }
        void skipWs() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        boolean matchKeyword(String kw) {
            skipWs();
            if (s.startsWith(kw, i) && (i + kw.length() == s.length() || !Character.isJavaIdentifierPart(s.charAt(i + kw.length())))) {
                i += kw.length();
