        void expect(char c) { skipWs(); if (i >= s.length() || s.charAt(i) != c) throw new RuntimeException("expected " + c); i++; }
        String readIdent() {
            skipWs();
            int start = i;
            while (i < s.length() && (Character.isLetterOrDigit(s.charAt(i)) || s.charAt(i) == '_' || s.charAt(i) == '.')) i++;
            return s.substring(start, i);
        }
        int readInt() {
            skipWs();
            int start = i;
            if (s.charAt(i) == '-') i++;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            return Integer.parseInt(s.substring(start, i));
        }
        void skipTo(char c) { while (i < s.length() && s.charAt(i) != c) i++; if (i < s.length()) i++; }
        String toCamel(String s) {
            StringBuilder sb = new StringBuilder();
            boolean up = false;
            for (int k = 0; k < s.length(); k++) {
                char ch = s.charAt(k);
                if (ch == '_') { up = true; continue; }
                if (up) { sb.append(Character.toUpperCase(ch)); up = false; }
                else sb.append(ch);
            }
            return sb.toString();
        }
    }

