public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 1) return;
        File dir = new File(args[0]);
        String schema = readAll(new File(dir, "schema.proto"));
        byte[] bin = readAllBytes(new File(dir, "messages.bin"));
        ProtoSchema ps = new ProtoSchema(schema);
        Decoder dec = new Decoder(ps);
        int pos = 0;
        StringBuilder out = new StringBuilder();
        while (pos < bin.length) {
            long len = readVarintUnsigned(bin, pos)[0];
            int lenSize = (int) readVarintUnsigned(bin, pos)[1];
            pos += lenSize;
            int l = (int) len;
            if (pos + l > bin.length) l = bin.length - pos;
            byte[] rec = Arrays.copyOfRange(bin, pos, pos + l);
            pos += l;
            DecodedMessage dm = dec.decodeRoot(rec);
            out.append(dm.toJson()).append('\n');
        }
        System.out.print(out.toString());
