    static long[] readVarintUnsigned(byte[] data, int pos) {
        long result = 0;
        int shift = 0;
        int i = pos;
        while (true) {
            int b = data[i++] & 0xFF;
            result |= ((long) (b & 0x7F)) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
        }
        return new long[]{result, i};
