import * as fs from 'fs';
import * as http from 'http';
import { URL } from 'url';

function encodeFormValue(str: string): string {
  const buf = Buffer.from(str, 'utf8');
  let out = '';
  for (const b of buf) {
    if (b === 0x20) {
      out += '+';
    } else {
      const ch = String.fromCharCode(b);
      if (/[A-Za-z0-9\-._*]/.test(ch)) {
        out += ch;
      } else {
        out += '%' + b.toString(16).toUpperCase().padStart(2, '0');
      }
    }
  }
  return out;
}

function httpRequest(method: string, urlStr: string, headers: Record<string, string>, body?: string): Promise<{ status: number; headers: http.IncomingHttpHeaders; body: string }> {
  return new Promise((resolve, reject) => {
    const url = new URL(urlStr);
    const options: http.RequestOptions = {
      method,
      hostname: url.hostname,
      port: url.port ? Number(url.port) : undefined,
      path: url.pathname + url.search,
      headers,
    };
    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const body = Buffer.concat(chunks).toString('utf8');
        resolve({ status: res.statusCode ?? 0, headers: res.headers, body });
      });
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

function parseAmount(s: string): bigint {
  let sign = 1n;
  if (s.startsWith('-')) { sign = -1n; s = s.slice(1); }
  if (s.startsWith('+')) s = s.slice(1);
  const [intPart, fracPartRaw = ''] = s.split('.');
  const intBig = intPart ? BigInt(intPart) : 0n;
  let frac = fracPartRaw;
  if (frac.length === 0) {
    return sign * intBig * 100n;
  }
  if (frac.length === 1) frac = frac + '0';
  if (frac.length > 2) frac = frac.slice(0, 2);
  while (frac.length < 2) frac += '0';
  const fracBig = BigInt(frac);
  return sign * (intBig * 100n + fracBig);
}

function formatCents(c: bigint): string {
  const neg = c < 0n;
  const abs = neg ? -c : c;
  const intPart = abs / 100n;
  const fracPart = abs % 100n;
  const fracStr = fracPart.toString().padStart(2, '0');
  const sign = neg ? '-' : '';
  return `${sign}${intPart.toString()}.${fracStr}`;
}

function utf8Compare(a: string, b: string): number {
  const ba = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  const len = Math.min(ba.length, bb.length);
  for (let i = 0; i < len; i++) {
    if (ba[i] !== bb[i]) return ba[i] - bb[i];
  }
  return ba.length - bb.length;
}

async function getToken(baseUrl: string, client: any) {
  const encId = encodeFormValue(client.client_id);
  const encSecret = encodeFormValue(client.client_secret);
  const basic = Buffer.from(`${encId}:${encSecret}`, 'utf8').toString('base64');
  const body = `grant_type=client_credentials&scope=${encodeURIComponent(client.scope)}`;
  const url = `${baseUrl}/oauth/token`;
  const resp = await httpRequest('POST', url, {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Authorization': `Basic ${basic}`,
  }, body);
  if (resp.status !== 200) {
    console.log(`ERROR ${resp.status} ${resp.body}`);
    process.exit(0);
  }
  const data = JSON.parse(resp.body);
  return data.access_token;
}

async function main() {
  const [dataDir, baseUrl] = process.argv.slice(2);
  const client = JSON.parse(fs.readFileSync(`${dataDir}/client.json`, 'utf8'));
  const pageSize = client.page_size;

  let token = await getToken(baseUrl, client);
  let reauth = 0;
  let retries = 0;
  let pages = 0;
  let ordersReceived = 0;
  let tokenUsed = false;

  const statusCounts = new Map<string, number>();
  const totalsMap = new Map<string, { name: string; currency: string; cents: bigint }>();

  let cursor: string | undefined = undefined;
  let firstRequestWithToken = true;

  while (true) {
    const url = `${baseUrl}/orders?limit=${pageSize}` + (cursor ? `&cursor=${encodeURIComponent(cursor)}` : '');
    const resp = await httpRequest('GET', url, { 'Authorization': `Bearer ${token}` });
    const status = resp.status;

    if (status === 200) {
      pages++;
      const obj = JSON.parse(resp.body);
      const data: any[] = obj.data ?? [];
      ordersReceived += data.length;
      for (const o of data) {
        const st = o.status;
        statusCounts.set(st, (statusCounts.get(st) ?? 0) + 1);
        if (st !== 'cancelled') {
          const name = o.customer?.name ?? '';
          const currency = o.currency ?? '';
          const cents = parseAmount(o.amount ?? '0');
          const key = `${name}\u0000${currency}`;
          const existing = totalsMap.get(key);
          if (existing) {
            existing.cents += cents;
          } else {
            totalsMap.set(key, { name, currency, cents });
          }
        }
      }
      tokenUsed = true;
      const next = obj.next_cursor;
      if (next === null || next === undefined) break;
      cursor = next;
      continue;
    }

    if (status === 429) {
      retries++;
      const ra = parseInt(resp.headers['retry-after'] as string ?? '1', 10);
      await new Promise(r => setTimeout(r, ra * 1000));
      continue;
    }
    if (status === 503) {
      retries++;
      await new Promise(r => setTimeout(r, 0));
      continue;
    }
    if (status === 401) {
      if (!tokenUsed) {
        console.log(`ERROR ${status} ${resp.body}`);
        process.exit(0);
      }
      // refresh token
      token = await getToken(baseUrl, client);
      reauth++;
      tokenUsed = false;
      continue;
    }
    // fatal
    console.log(`ERROR ${status} ${resp.body}`);
    process.exit(0);
  }

  const totals = Array.from(totalsMap.values());
  totals.sort((a, b) => {
    const c = utf8Compare(a.name, b.name);
    if (c !== 0) return c;
    if (a.currency < b.currency) return -1;
    if (a.currency > b.currency) return 1;
    return 0;
  });
  for (const t of totals) {
    console.log(`total ${t.currency} ${formatCents(t.cents)} ${t.name}`);
  }
  const statuses = Array.from(statusCounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));
  for (const [st, cnt] of statuses) {
    console.log(`status ${st} ${cnt}`);
  }
  console.log(`orders ${ordersReceived} pages ${pages} retries ${retries} reauth ${reauth}`);
}

main().catch(() => process.exit(0));

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <stdbool.h>
#include <limits.h>

#define MAX_NAME 256
#define MAX_FIELDS 2048
#define MAX_MSGS 1024
#define MAX_ENUMS 1024

typedef enum {
    TK_EOF, TK_IDENT, TK_NUMBER, TK_STRING, TK_SYM
} TokKind;

typedef struct {
    TokKind kind;
    char *text;
} Token;

typedef struct {
    Token *t;
    int n, cap, pos;
} Lexer;

typedef enum {
    FT_INT32, FT_INT64, FT_UINT32, FT_UINT64, FT_SINT32, FT_SINT64,
    FT_BOOL, FT_STRING, FT_BYTES,
    FT_FIXED32, FT_SFIXED32, FT_FIXED64, FT_SFIXED64,
    FT_MESSAGE, FT_ENUM
} FieldType;

typedef struct FieldDef {
    char name[256];
    char json_name[256];
    int number;
    FieldType ftype;
    char type_name[256];
    bool repeated;
    bool optional;
    bool is_map;
    char map_key_type[16];
    char map_val_type[256];
    int oneof_id;
} FieldDef;

typedef struct MessageDef {
    char name[256];
    FieldDef fields[MAX_FIELDS];
    int field_cnt;
} MessageDef;

typedef struct EnumVal {
    char name[256];
    int value;
} EnumVal;

typedef struct EnumDef {
    char name[256];
    EnumVal vals[512];
    int val_cnt;
} EnumDef;

MessageDef msgs[MAX_MSGS];
int msgs_cnt = 0;
EnumDef enums[MAX_ENUMS];
int enums_cnt = 0;

MessageDef *find_msg(const char *name){
    for(int i=0;i<msgs_cnt;i++) if(strcmp(msgs[i].name,name)==0) return &msgs[i];
    return NULL;
}
EnumDef *find_enum(const char *name){
    for(int i=0;i<enums_cnt;i++) if(strcmp(enums[i].name,name)==0) return &enums[i];
    return NULL;
}

/* ---------- lexer helpers ---------- */
static char *strip_comments(const char *src){
    size_t n=strlen(src);
    char *out=malloc(n+1);
    size_t o=0;
    for(size_t i=0;i<n;){
        if(src[i]=='/' && i+1<n && src[i+1]=='/'){
            i+=2; while(i<n && src[i]!='\n') i++;
        }else if(src[i]=='/' && i+1<n && src[i+1]=='*'){
            i+=2; while(i+1<n && !(src[i]=='*' && src[i+1]=='/')) i++;
            i+=2;
        }else{
            out[o++]=src[i++];
        }
    }
    out[o]=0;
    return out;
}

static void lexer_init(Lexer *lx, const char *src){
    lx->t=NULL; lx->n=0; lx->cap=0; lx->pos=0;
    const char *p=src;
    while(*p){
        while(*p && isspace((unsigned char)*p)) p++;
        if(!*p) break;
        if(isalpha((unsigned char)*p)||*p=='_'||*p=='$'){
            const char *s=p; while(*p && (isalnum((unsigned char)*p)||*p=='_'||*p=='$')) p++;
            char *tok=malloc(p-s+1); memcpy(tok,s,p-s); tok[p-s]=0;
            // store
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_IDENT; lx->t[lx->n].text=tok; lx->n++;
        }else if(isdigit((unsigned char)*p)||(*p=='-' && isdigit((unsigned char)p[1]))){
            const char *s=p; while(*p && (isdigit((unsigned char)*p)||*p=='-'||*p=='+')) p++;
            char *tok=malloc(p-s+1); memcpy(tok,s,p-s); tok[p-s]=0;
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_NUMBER; lx->t[lx->n].text=tok; lx->n++;
        }else if(*p=='"'){
            p++; const char *s=p; while(*p && *p!='"') p++;
            char *tok=malloc(p-s+1); memcpy(tok,s,p-s); tok[p-s]=0;
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_STRING; lx->t[lx->n].text=tok; lx->n++;
            if(*p=='"') p++;
        }else{
            char buf[2]={*p,0};
            char *tok=strdup(buf);
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_SYM; lx->t[lx->n].text=tok; lx->n++;
            p++;
        }
    }
}
static Token *peek(Lexer *lx){ if(lx->pos>=lx->n) return NULL; return &lx->t[lx->pos]; }
static Token *next(Lexer *lx){ if(lx->pos>=lx->n) return NULL; return &lx->t[lx->pos++]; }
static bool match_ident(Lexer *lx, const char *s){ Token *t=peek(lx); return t && t->kind==TK_IDENT && strcmp(t->text,s)==0; }
static bool match_sym(Lexer *lx, const char *s){ Token *t=peek(lx); return t && t->kind==TK_SYM && strcmp(t->text,s)==0; }

static void to_camel(const char *in, char *out){
    size_t i=0,j=0;
    bool first=true;
    while(in[i]){
        if(in[i]=='_'){ i++; if(in[i]){ out[j++]=toupper((unsigned char)in[i]); i++; } continue; }
        if(first){ out[j++]=in[i]; first=false; }
        else out[j++]=in[i];
        i++;
    }
    out[j]=0;
}

/* ---------- schema parsing ---------- */
static int cur_oneof_id = -1;

static FieldType parse_builtin(const char *s){
    if(strcmp(s,"int32")==0) return FT_INT32;
    if(strcmp(s,"int64")==0) return FT_INT64;
    if(strcmp(s,"uint32")==0) return FT_UINT32;
    if(strcmp(s,"uint64")==0) return FT_UINT64;
    if(strcmp(s,"sint32")==0) return FT_SINT32;
    if(strcmp(s,"sint64")==0) return FT_SINT64;
    if(strcmp(s,"bool")==0) return FT_BOOL;
    if(strcmp(s,"string")==0) return FT_STRING;
    if(strcmp(s,"bytes")==0) return FT_BYTES;
    if(strcmp(s,"fixed32")==0) return FT_FIXED32;
    if(strcmp(s,"sfixed32")==0) return FT_SFIXED32;
    if(strcmp(s,"fixed64")==0) return FT_FIXED64;
    if(strcmp(s,"sfixed64")==0) return FT_SFIXED64;
    return -1;
}

static void add_field(MessageDef *msg, FieldDef *fd){
    if(msg->field_cnt>=MAX_FIELDS) return;
    msg->fields[msg->field_cnt++]=*fd;
}

static void parse_enum_body(Lexer *lx, EnumDef *en){
    // expect '{'
    next(lx);
    while(!match_sym(lx,"}")){
        Token *t=peek(lx); if(!t) break;
        if(t->kind==TK_IDENT){
            char name[256]; strcpy(name,t->text); next(lx);
            // =
            if(match_sym(lx,"=")) next(lx);
            Token *num=next(lx); int val=0; if(num && num->kind==TK_NUMBER) val=atoi(num->text);
            if(en->val_cnt<512){
                strcpy(en->vals[en->val_cnt].name,name);
                en->vals[en->val_cnt].value=val;
                en->val_cnt++;
            }
            if(match_sym(lx,";")) next(lx);
        }else next(lx);
    }
    next(lx); // }
}

static void parse_message_body(Lexer *lx, MessageDef *msg){
    next(lx); // '{'
    while(!match_sym(lx,"}")){
        if(match_ident(lx,"message")){
            next(lx); Token *n=next(lx); if(n){
                MessageDef nm; memset(&nm,0,sizeof(nm)); strcpy(nm.name,n->text);
                msgs[msgs_cnt++]=nm;
                MessageDef *pm=&msgs[msgs_cnt-1];
                parse_message_body(lx,pm);
            }
        }else if(match_ident(lx,"enum")){
            next(lx); Token *n=next(lx); if(n){
                EnumDef en; memset(&en,0,sizeof(en)); strcpy(en.name,n->text);
                enums[enums_cnt++]=en;
                EnumDef *pe=&enums[enums_cnt-1];
                parse_enum_body(lx,pe);
            }
        }else if(match_ident(lx,"oneof")){
            next(lx); Token *n=next(lx);
            int oid=cur_oneof_id+1; cur_oneof_id=oid;
            next(lx); // '{'
            while(!match_sym(lx,"}")){
                // parse field inside oneof
                // type name = number ;
                Token *typeTok=peek(lx); if(!typeTok) break;
                char typebuf[256]; strcpy(typebuf,typeTok->text); next(lx);
                Token *nameTok=peek(lx); if(!nameTok) break;
                char namebuf[256]; strcpy(namebuf,nameTok->text); next(lx);
                // =
                if(match_sym(lx,"=")) next(lx);
                Token *numTok=next(lx); int num=0; if(numTok && numTok->kind==TK_NUMBER) num=atoi(numTok->text);
                // skip options
                if(match_sym(lx,"[")) { int d=1; next(lx); while(d && (Token*)peek(lx)){ if(match_sym(lx,"[")) d++; if(match_sym(lx,"]")) d--; next(lx);} }
                if(match_sym(lx,";")) next(lx);
                FieldDef fd; memset(&fd,0,sizeof(fd));
                strcpy(fd.name,namebuf);
                char camel[256]; to_camel(namebuf,camel); strcpy(fd.json_name,camel);
                fd.number=num; fd.oneof_id=oid;
                FieldType ft=parse_builtin(typebuf);
                if(ft!=-1) fd.ftype=ft; else { fd.ftype=FT_MESSAGE; strcpy(fd.type_name,typebuf); }
                fd.repeated=false; fd.optional=false; fd.is_map=false;
                add_field(msg,&fd);
            }
            next(lx); // }
            cur_oneof_id--;
        }else if(match_ident(lx,"reserved")){
            // skip
            next(lx);
            while(!match_sym(lx,";")) next(lx);
            next(lx);
        }else if(match_ident(lx,"option")){
            // skip to ;
            next(lx);
            while(!match_sym(lx,";")) next(lx);
            next(lx);
        }else{
            // maybe field
            bool has_rep=false, has_opt=false;
            if(match_ident(lx,"repeated")){ has_rep=true; next(lx); }
            else if(match_ident(lx,"optional")){ has_opt=true; next(lx); }
            Token *typeTok=peek(lx); if(!typeTok){ next(lx); continue; }
            // map?
            if(strcmp(typeTok->text,"map")==0){
                next(lx); // map
                if(match_sym(lx,"<")) next(lx);
                Token *k=next(lx); char ktype[16]; strcpy(ktype,k?k->text:"");
                if(match_sym(lx,",")) next(lx);
                Token *v=next(lx); char vtype[256]; strcpy(vtype,v?v->text:"");
                if(match_sym(lx,">")) next(lx);
                Token *nameTok=next(lx); char namebuf[256]; strcpy(namebuf,nameTok?nameTok->text:"");
                if(match_sym(lx,"=")) next(lx);
                Token *numTok=next(lx); int num=0; if(numTok && numTok->kind==TK_NUMBER) num=atoi(numTok->text);
                if(match_sym(lx,"[")) { int d=1; next(lx); while(d && (Token*)peek(lx)){ if(match_sym(lx,"[")) d++; if(match_sym(lx,"]")) d--; next(lx);} }
                if(match_sym(lx,";")) next(lx);
                FieldDef fd; memset(&fd,0,sizeof(fd));
                strcpy(fd.name,namebuf); char camel[256]; to_camel(namebuf,camel); strcpy(fd.json_name,camel);
                fd.number=num; fd.is_map=true; strcpy(fd.map_key_type,ktype); strcpy(fd.map_val_type,vtype);
                fd.repeated=false; fd.optional=has_opt; fd.oneof_id=-1;
                add_field(msg,&fd);
                continue;
            }
            char typebuf[256]; strcpy(typebuf,typeTok->text); next(lx);
            Token *nameTok=peek(lx); if(!nameTok){ next(lx); continue; }
            char namebuf[256]; strcpy(namebuf,nameTok->text); next(lx);
            if(match_sym(lx,"=")) next(lx);
            Token *numTok=next(lx); int num=0; if(numTok && numTok->kind==TK_NUMBER) num=atoi(numTok->text);
            if(match_sym(lx,"[")) { int d=1; next(lx); while(d && (Token*)peek(lx)){ if(match_sym(lx,"[")) d++; if(match_sym(lx,"]")) d--; next(lx);} }
            if(match_sym(lx,";")) next(lx);
            FieldDef fd; memset(&fd,0,sizeof(fd));
            strcpy(fd.name,namebuf); char camel[256]; to_camel(namebuf,camel); strcpy(fd.json_name,camel);
            fd.number=num; fd.repeated=has_rep; fd.optional=has_opt; fd.oneof_id=-1;
            FieldType ft=parse_builtin(typebuf);
            if(ft!=-1) fd.ftype=ft; else { fd.ftype=FT_MESSAGE; strcpy(fd.type_name,typebuf); }
            add_field(msg,&fd);
        }
    }
    next(lx); // }
}

static void parse_schema(const char *txt){
    char *clean=strip_comments(txt);
    Lexer lx; lexer_init(&lx,clean);
    while(lx.pos<lx.n){
        if(match_ident(&lx,"syntax")){ next(lx); next(lx); continue; }
        if(match_ident(&lx,"package")){ next(lx); next(lx); continue; }
        if(match_ident(&lx,"message")){
            next(lx); Token *n=next(lx); if(n){
                MessageDef *m=&msgs[msgs_cnt++]; memset(m,0,sizeof(*m)); strcpy(m->name,n->text);
                parse_message_body(&lx,m);
            }
        }else next(lx);
    }
}

/* ---------- protobuf decoding ---------- */
static uint64_t read_varint(const uint8_t *buf, size_t *pos, size_t limit){
    uint64_t v=0; int shift=0;
    while(*pos<limit){
        uint8_t b=buf[(*pos)++];
        v|= (uint64_t)(b&0x7F)<<shift;
        if(!(b&0x80)) break;
        shift+=7;
    }
    return v;
}
static int32_t zigzag32(uint64_t v){ return (int32_t)((v>>1) ^ -(v&1)); }
static int64_t zigzag64(uint64_t v){ return (int64_t)((v>>1) ^ -(v&1)); }

static void skip_unknown(const uint8_t *buf, size_t *pos, size_t limit, uint32_t wire){
    if(wire==0){ read_varint(buf,pos,limit); }
    else if(wire==1){ *pos+=8; }
    else if(wire==2){ uint64_t len=read_varint(buf,pos,limit); *pos+=len; }
    else if(wire==5){ *pos+=4; }
    else if(wire==3 || wire==4){ /* groups */ 
        // naive skip
        while(*pos<limit){
            uint64_t key=read_varint(buf,pos,limit);
            uint32_t w=key&7;
            uint32_t fn=key>>3;
            if(w==4 && fn== (wire==3? (key>>3):0)) break;
            skip_unknown(buf,pos,limit,w);
        }
    }
}

/* JSON utilities */
static void json_escape(FILE *out, const char *s){
    fputc('"',out);
    for(;*s;s++){
        unsigned char c=(unsigned char)*s;
        if(c=='"'){ fputs("\\\"",out); }
        else if(c=='\\'){ fputs("\\\\",out); }
        else if(c=='\b'){ fputs("\\b",out); }
        else if(c=='\t'){ fputs("\\t",out); }
        else if(c=='\n'){ fputs("\\n",out); }
        else if(c=='\f'){ fputs("\\f",out); }
        else if(c=='\r'){ fputs("\\r",out); }
        else if(c<0x20){ fprintf(out,"\\u%04x",c); }
        else fputc(c,out);
    }
    fputc('"',out);
}

/* base64 */
static const char b64t[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void base64_encode(FILE *out, const uint8_t *data, size_t len){
    for(size_t i=0;i<len;i+=3){
        uint32_t v=0;
        for(int j=0;j<3 && i+j<len;j++) v|=(uint32_t)data[i+j]<< (16-8*j);
        int n=(len-i)>=3?4: (len-i)==2?4:3;
        for(int j=0;j<n;j++){
            int c=(v>> (18-6*j)) &0x3F;
            fputc(b64t[c],out);
        }
        for(int j=n;j<4;j++) fputc('=',out);
    }
}

/* decoding state */
typedef struct DecodedField {
    FieldDef *fd;
    bool present;
    // scalar
    int64_t i64;
    bool boolv;
    char *str; // for string/bytes (base64 encoded later)
    // repeated
    struct {
        int64_t *i64s;
        int cnt;
        bool is_int;
    } rep;
    // map
    struct {
        char **keys;
        char **vals;
        int cnt;
    } mp;
} DecodedField;

static int cmp_field(const void *a, const void *b){
    const FieldDef *fa=((DecodedField*)a)->fd;
    const FieldDef *fb=((DecodedField*)b)->fd;
    return fa->number - fb->number;
}

/* forward */
static void decode_message(const uint8_t *buf, size_t len, MessageDef *msg, DecodedField *out, int *out_cnt);

static void decode_field_value(FieldDef *fd, const uint8_t *buf, size_t len, DecodedField *df){
    // placeholder
}

static void decode_message(const uint8_t *buf, size_t len, MessageDef *msg, DecodedField *out, int *out_cnt){
    *out_cnt=0;
    size_t pos=0;
    while(pos<len){
        size_t start=pos;
        uint64_t key=read_varint(buf,&pos,len);
        uint32_t wire=key&7;
        uint32_t num=key>>3;
        FieldDef *fd=NULL;
        for(int i=0;i<msg->field_cnt;i++) if(msg->fields[i].number==num){ fd=&msg->fields[i]; break; }
        if(!fd){ skip_unknown(buf,&pos,len,wire); continue; }
        // find existing decoded field
        DecodedField *df=NULL;
        for(int i=0;i<*out_cnt;i++) if(out[i].fd->number==num){ df=&out[i]; break; }
        if(!df){
            df=&out[(*out_cnt)++];
            df->fd=fd;
            df->present=false;
            df->i64=0;
            df->boolv=false;
            df->str=NULL;
            df->rep.i64s=NULL; df->rep.cnt=0;
            df->mp.keys=NULL; df->mp.vals=NULL; df->mp.cnt=0;
        }
        // handle oneof clearing
        if(fd->oneof_id!=-1){
            for(int i=0;i<*out_cnt;i++){
                if(out[i].fd->oneof_id==fd->oneof_id && out[i].fd!=fd){
                    // clear
                    out[i].present=false;
                }
            }
        }
        // decode based on type
        if(fd->is_map){
            // map entry length delimited
            if(wire!=2){ skip_unknown(buf,&pos,len,wire); continue; }
            uint64_t elen=read_varint(buf,&pos,len);
            size_t elen_pos=pos;
            // parse entry: key field 1, value field 2
            char *key_str=NULL; int64_t val_int=0; bool has_key=false, has_val=false;
            size_t epos=elen_pos;
            size_t elimit=elen_pos+elen;
            while(epos<elimit){
                uint64_t ekey=read_varint(buf,&epos,elimit);
                uint32_t ewire=ekey&7; uint32_t en=ekey>>3;
                if(en==1){
                    // key
                    if(strcmp(fd->map_key_type,"string")==0){
                        uint64_t klen=read_varint(buf,&epos,elimit);
                        key_str=malloc(klen+1);
                        memcpy(key_str,buf+epos,klen); key_str[klen]=0; epos+=klen;
                        has_key=true;
                    }else{
                        uint64_t kv=read_varint(buf,&epos,elimit);
                        // int32 key as decimal string
                        char tmp[32]; sprintf(tmp,"%lld",(long long)kv);
                        key_str=strdup(tmp); has_key=true;
                    }
                }else if(en==2){
                    // value
                    // for simplicity assume int32
                    uint64_t vv=read_varint(buf,&epos,elimit);
                    val_int=(int64_t)vv;
                    has_val=true;
                }else{
                    skip_unknown(buf,&epos,elimit,ewire);
                }
            }
            // insert into map
            if(has_key){
                int idx=-1;
                for(int i=0;i<df->mp.cnt;i++){
                    if(strcmp(df->mp.keys[i],key_str)==0){ idx=i; break; }
                }
                if(idx>=0){
                    free(df->mp.vals[idx]); free(df->mp.keys[idx]);
                }else{
                    df->mp.keys=realloc(df->mp.keys,sizeof(char*)*(df->mp.cnt+1));
                    df->mp.vals=realloc(df->mp.vals,sizeof(char*)*(df->mp.cnt+1));
                    df->mp.keys[df->mp.cnt]=key_str;
                    df->mp.cnt++;
                    idx=df->mp.cnt-1;
                }
                char vbuf[64]; sprintf(vbuf,"%lld",(long long)val_int);
                df->mp.vals[idx]=strdup(vbuf);
            }else free(key_str);
            pos=elen_pos+elen;
            continue;
        }
        // normal field
        if(fd->repeated){
            // could be packed
            if(wire==2){
                uint64_t plen=read_varint(buf,&pos,len);
                size_t plen_start=pos;
                size_t plen_end=pos+plen;
                while(pos<plen_end){
                    // decode one element
                    // for simplicity assume varint
                    uint64_t v=read_varint(buf,&pos,len);
                    df->rep.i64s=realloc(df->rep.i64s,sizeof(int64_t)*(df->rep.cnt+1));
                    df->rep.i64s[df->rep.cnt++]= (int64_t)v;
                }
                continue;
            }else{
                uint64_t v=read_varint(buf,&pos,len);
                df->rep.i64s=realloc(df->rep.i64s,sizeof(int64_t)*(df->rep.cnt+1));
                df->rep.i64s[df->rep.cnt++]= (int64_t)v;
                continue;
            }
        }
        // scalar / message
        switch(fd->ftype){
            case FT_INT32: {
                uint64_t v=read_varint(buf,&pos,len);
                int32_t sv=(int32_t)(v & 0xFFFFFFFF);
                df->i64=sv; df->present=true; break;
            }
            case FT_INT64: {
                uint64_t v=read_varint(buf,&pos,len);
                df->i64=(int64_t)v; df->present=true; break;
            }
            case FT_UINT32: {
                uint64_t v=read_varint(buf,&pos,len);
                df->i64=(int64_t)v; df->present=true; break;
            }
            case FT_UINT64: {
                uint64_t v=read_varint(buf,&pos,len);
                df->i64=(int64_t)v; df->present=true; break;
            }
            case FT_SINT32: {
                uint64_t v=read_varint(buf,&pos,len);
                df->i64=zigzag32(v); df->present=true; break;
            }
            case FT_SINT64: {
                uint64_t v=read_varint(buf,&pos,len);
                df->i64=zigzag64(v); df->present=true; break;
            }
            case FT_BOOL: {
                uint64_t v=read_varint(buf,&pos,len);
                df->boolv=v!=0; df->present=true; break;
            }
            case FT_STRING: {
                uint64_t l=read_varint(buf,&pos,len);
                df->str=malloc(l+1); memcpy(df->str,buf+pos,l); df->str[l]=0; pos+=l; df->present=true; break;
            }
            case FT_BYTES: {
                uint64_t l=read_varint(buf,&pos,len);
                df->str=malloc(l+1); memcpy(df->str,buf+pos,l); df->str[l]=0; pos+=l; df->present=true; break;
            }
            case FT_ENUM: {
                uint64_t v=read_varint(buf,&pos,len);
                df->i64=(int64_t)v; df->present=true; break;
            }
            default: skip_unknown(buf,&pos,len,wire); break;
        }
    }
}

/* printing */
static void print_message_json(MessageDef *msg, DecodedField *fields, int cnt){
    // sort by number
    qsort(fields, cnt, sizeof(DecodedField), cmp_field);
    printf("{");
    bool first=true;
    for(int i=0;i<cnt;i++){
        DecodedField *df=&fields[i];
        FieldDef *fd=df->fd;
        bool omit=false;
        if(!fd->repeated && !fd->is_map){
            if(!df->present && !fd->optional && fd->oneof_id==-1) omit=true;
            if(!fd->optional && fd->oneof_id==-1){
                // default check
                if(df->i64==0 && df->boolv==false && (!df->str || strlen(df->str)==0)) omit=true;
            }
        }
        if(omit) continue;
        if(!first) printf(",");
        first=false;
        json_escape(stdout, fd->json_name);
        printf(":");
        if(fd->is_map){
            printf("{");
            // sort keys
            // simple bubble
            for(int a=0;a<df->mp.cnt;a++) for(int b=a+1;b<df->mp.cnt;b++) if(strcmp(df->mp.keys[a],df->mp.keys[b])>0){ char *tk=df->mp.keys[a]; df->mp.keys[a]=df->mp.keys[b]; df->mp.keys[b]=tk; char *tv=df->mp.vals[a]; df->mp.vals[a]=df->mp.vals[b]; df->mp.vals[b]=tv; }
            for(int k=0;k<df->mp.cnt;k++){
                if(k) printf(",");
                json_escape(stdout, df->mp.keys[k]);
                printf(":");
                printf("%s", df->mp.vals[k]);
            }
            printf("}");
        }else if(fd->repeated){
            printf("[");
            for(int k=0;k<df->rep.cnt;k++){
                if(k) printf(",");
                printf("%lld",(long long)df->rep.i64s[k]);
            }
            printf("]");
        }else if(fd->ftype==FT_STRING){
            json_escape(stdout, df->str?df->str:"");
        }else if(fd->ftype==FT_BYTES){
            printf("\"");
            if(df->str) base64_encode(stdout,(uint8_t*)df->str,strlen(df->str));
            printf("\"");
        }else if(fd->ftype==FT_BOOL){
            printf("%s", df->boolv?"true":"false");
        }else if(fd->ftype==FT_INT64 || fd->ftype==FT_UINT64 || fd->ftype==FT_SINT64 || fd->ftype==FT_FIXED64 || fd->ftype==FT_SFIXED64){
            printf("\"%lld\"", (long long)df->i64);
        }else if(fd->ftype==FT_ENUM){
            EnumDef *en=find_enum(fd->type_name);
            if(en){
                for(int v=0;v<en->val_cnt;v++) if(en->vals[v].value==(int)df->i64){ json_escape(stdout,en->vals[v].name); goto enum_done; }
            }
            printf("%lld",(long long)df->i64);
            enum_done: ;
        }else{
            printf("%lld",(long long)df->i64);
        }
    }
    printf("}\n");
}

/* ---------- main ---------- */
int main(int argc,char *argv[]){
    if(argc<2){ fprintf(stderr,"usage\n"); return 1; }
    char path[1024];
    snprintf(path,sizeof(path),"%s/schema.proto",argv[1]);
    FILE *f=fopen(path,"rb"); if(!f){ perror("schema"); return 1; }
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    parse_schema(buf);
    MessageDef *root=find_msg(msgs[0].name);
    if(!root) root=&msgs[0];
    char binpath[1024];
    snprintf(binpath,sizeof(binpath),"%s/messages.bin",argv[1]);
    FILE *bf=fopen(binpath,"rb"); if(!bf){ perror("bin"); return 1; }
    fseek(bf,0,SEEK_END); long bsz=ftell(bf); fseek(bf,0,SEEK_SET);
    uint8_t *bdata=malloc(bsz); fread(bdata,1,bsz,bf); fclose(bf);
    size_t pos=0;
    while(pos<bsz){
        size_t start=pos;
        uint64_t len=read_varint(bdata,&pos,bsz);
        size_t msg_start=pos;
        size_t msg_end=msg_start+len;
        if(msg_end>bsz) break;
        DecodedField fields[MAX_FIELDS];
        int cnt=0;
        decode_message(bdata+msg_start,len,root,fields,&cnt);
        print_message_json(root,fields,cnt);
        pos=msg_end;
    }
    return 0;
}

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <stdbool.h>
#include <limits.h>

#define MAX_NAME 256
#define MAX_FIELDS 2048
#define MAX_MSGS 1024
#define MAX_ENUMS 1024

typedef enum { TK_EOF, TK_IDENT, TK_NUMBER, TK_STRING, TK_SYM } TokKind;
typedef struct { TokKind kind; char *text; } Token;
typedef struct { Token *t; int n, cap, pos; } Lexer;

typedef enum {
    FT_INT32, FT_INT64, FT_UINT32, FT_UINT64, FT_SINT32, FT_SINT64,
    FT_BOOL, FT_STRING, FT_BYTES,
    FT_FIXED32, FT_SFIXED32, FT_FIXED64, FT_SFIXED64,
    FT_MESSAGE, FT_ENUM
} FieldType;

typedef struct FieldDef {
    char name[256];
    char json_name[256];
    int number;
    FieldType ftype;
    char type_name[256];
    bool repeated;
    bool optional;
    bool is_map;
    char map_key_type[16];
    char map_val_type[256];
    int oneof_id;
} FieldDef;

typedef struct MessageDef {
    char name[256];
    FieldDef fields[MAX_FIELDS];
    int field_cnt;
} MessageDef;

typedef struct EnumVal { char name[256]; int value; } EnumVal;
typedef struct EnumDef { char name[256]; EnumVal vals[512]; int val_cnt; } EnumDef;

MessageDef msgs[MAX_MSGS]; int msgs_cnt = 0;
EnumDef enums[MAX_ENUMS]; int enums_cnt = 0;

MessageDef *find_msg(const char *name){ for(int i=0;i<msgs_cnt;i++) if(strcmp(msgs[i].name,name)==0) return &msgs[i]; return NULL; }
EnumDef *find_enum(const char *name){ for(int i=0;i<enums_cnt;i++) if(strcmp(enums[i].name,name)==0) return &enums[i]; return NULL; }

static char *strip_comments(const char *src){
    size_t n=strlen(src); char *out=malloc(n+1); size_t o=0;
    for(size_t i=0;i<n;){
        if(src[i]=='/' && i+1<n && src[i+1]=='/'){ i+=2; while(i<n && src[i]!='\n') i++; }
        else if(src[i]=='/' && i+1<n && src[i+1]=='*'){ i+=2; while(i+1<n && !(src[i]=='*' && src[i+1]=='/')) i++; i+=2; }
        else out[o++]=src[i++];
    }
    out[o]=0; return out;
}
static void lexer_init(Lexer *lx, const char *src){
    lx->t=NULL; lx->n=0; lx->cap=0; lx->pos=0;
    const char *p=src;
    while(*p){
        while(*p && isspace((unsigned char)*p)) p++;
        if(!*p) break;
        if(isalpha((unsigned char)*p)||*p=='_'||*p=='$'){
            const char *s=p; while(*p && (isalnum((unsigned char)*p)||*p=='_'||*p=='$')) p++;
            char *tok=malloc(p-s+1); memcpy(tok,s,p-s); tok[p-s]=0;
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_IDENT; lx->t[lx->n].text=tok; lx->n++;
        }else if(isdigit((unsigned char)*p)||(*p=='-' && isdigit((unsigned char)p[1]))){
            const char *s=p; while(*p && (isdigit((unsigned char)*p)||*p=='-'||*p=='+')) p++;
            char *tok=malloc(p-s+1); memcpy(tok,s,p-s); tok[p-s]=0;
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_NUMBER; lx->t[lx->n].text=tok; lx->n++;
        }else if(*p=='"'){
            p++; const char *s=p; while(*p && *p!='"') p++;
            char *tok=malloc(p-s+1); memcpy(tok,s,p-s); tok[p-s]=0;
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_STRING; lx->t[lx->n].text=tok; lx->n++;
            if(*p=='"') p++;
        }else{
            char buf[2]={*p,0}; char *tok=strdup(buf);
            if(lx->n>=lx->cap){ lx->cap+=256; lx->t=realloc(lx->t,lx->cap*sizeof(Token));}
            lx->t[lx->n].kind=TK_SYM; lx->t[lx->n].text=tok; lx->n++; p++;
        }
    }
}
static Token *peek(Lexer *lx){ if(lx->pos>=lx->n) return NULL; return &lx->t[lx->pos]; }
static Token *next(Lexer *lx){ if(lx->pos>=lx->n) return NULL; return &lx->t[lx->pos++]; }
static bool match_ident(Lexer *lx, const char *s){ Token *t=peek(lx); return t && t->kind==TK_IDENT && strcmp(t->text,s)==0; }
static bool match_sym(Lexer *lx, const char *s){ Token *t=peek(lx); return t && t->kind==TK_SYM && strcmp(t->text,s)==0; }

static void to_camel(const char *in, char *out){
    size_t i=0,j=0; bool first=true;
    while(in[i]){
        if(in[i]=='_'){ i++; if(in[i]){ out[j++]=toupper((unsigned char)in[i]); i++; } continue; }
        out[j++]=in[i++]; if(first) first=false;
    }
    out[j]=0;
}
static int cur_oneof_id = -1;
static FieldType parse_builtin(const char *s){
    if(strcmp(s,"int32")==0) return FT_INT32;
    if(strcmp(s,"int64")==0) return FT_INT64;
    if(strcmp(s,"uint32")==0) return FT_UINT32;
    if(strcmp(s,"uint64")==0) return FT_UINT64;
    if(strcmp(s,"sint32")==0) return FT_SINT32;
    if(strcmp(s,"sint64")==0) return FT_SINT64;
    if(strcmp(s,"bool")==0) return FT_BOOL;
    if(strcmp(s,"string")==0) return FT_STRING;
    if(strcmp(s,"bytes")==0) return FT_BYTES;
    if(strcmp(s,"fixed32")==0) return FT_FIXED32;
    if(strcmp(s,"sfixed32")==0) return FT_SFIXED32;
    if(strcmp(s,"fixed64")==0) return FT_FIXED64;
    if(strcmp(s,"sfixed64")==0) return FT_SFIXED64;
    return -1;
}
static void add_field(MessageDef *msg, FieldDef *fd){ if(msg->field_cnt>=MAX_FIELDS) return; msg->fields[msg->field_cnt++]=*fd; }

static void parse_enum_body(Lexer *lx, EnumDef *en){
    next(lx);
    while(!match_sym(lx,"}")){
        Token *t=peek(lx); if(!t) break;
        if(t->kind==TK_IDENT){
            char name[256]; strcpy(name,t->text); next(lx);
            if(match_sym(lx,"=")) next(lx);
            Token *num=next(lx); int val=0; if(num && num->kind==TK_NUMBER) val=atoi(num->text);
            if(en->val_cnt<512){ strcpy(en->vals[en->val_cnt].name,name); en->vals[en->val_cnt].value=val; en->val_cnt++; }
            if(match_sym(lx,";")) next(lx);
        }else next(lx);
    }
    next(lx);
}
static void parse_message_body(Lexer *lx, MessageDef *msg){
    next(lx);
    while(!match_sym(lx,"}")){
        if(match_ident(lx,"message")){
            next(lx); Token *n=next(lx); if(n){ MessageDef nm; memset(&nm,0,sizeof(nm)); strcpy(nm.name,n->text); msgs[msgs_cnt++]=nm; parse_message_body(lx,&msgs[msgs_cnt-1]); }
        }else if(match_ident(lx,"enum")){
            next(lx); Token *n=next(lx); if(n){ EnumDef en; memset(&en,0,sizeof(en)); strcpy(en.name,n->text); enums[enums_cnt++]=en; parse_enum_body(lx,&enums[enums_cnt-1]); }
        }else if(match_ident(lx,"oneof")){
            next(lx); Token *n=next(lx); int oid=cur_oneof_id+1; cur_oneof_id=oid; next(lx);
            while(!match_sym(lx,"}")){
                Token *typeTok=peek(lx); if(!typeTok) break; char typebuf[256]; strcpy(typebuf,typeTok->text); next(lx);
                Token *nameTok=peek(lx); if(!nameTok) break; char namebuf[256]; strcpy(namebuf,nameTok->text); next(lx);
                if(match_sym(lx,"=")) next(lx);
                Token *numTok=next(lx); int num=0; if(numTok && numTok->kind==TK_NUMBER) num=atoi(numTok->text);
                if(match_sym(lx,"[")){ int d=1; next(lx); while(d && peek(lx)){ if(match_sym(lx,"[")) d++; if(match_sym(lx,"]")) d--; next(lx);} }
                if(match_sym(lx,";")) next(lx);
                FieldDef fd; memset(&fd,0,sizeof(fd)); strcpy(fd.name,namebuf); char camel[256]; to_camel(namebuf,camel); strcpy(fd.json_name,camel);
                fd.number=num; fd.oneof_id=oid; FieldType ft=parse_builtin(typebuf); if(ft!=-1) fd.ftype=ft; else { fd.ftype=FT_MESSAGE; strcpy(fd.type_name,typebuf); }
                add_field(msg,&fd);
            }
            next(lx); cur_oneof_id--;
        }else if(match_ident(lx,"reserved")){ next(lx); while(!match_sym(lx,";")) next(lx); next(lx); }
        else if(match_ident(lx,"option")){ next(lx); while(!match_sym(lx,";")) next(lx); next(lx); }
        else{
            bool has_rep=false, has_opt=false;
            if(match_ident(lx,"repeated")){ has_rep=true; next(lx); }
            else if(match_ident(lx,"optional")){ has_opt=true; next(lx); }
            Token *typeTok=peek(lx); if(!typeTok){ next(lx); continue; }
            if(strcmp(typeTok->text,"map")==0){
                next(lx); if(match_sym(lx,"<")) next(lx);
                Token *k=next(lx); char ktype[16]; strcpy(ktype,k?k->text:"");
                if(match_sym(lx,",")) next(lx);
                Token *v=next(lx); char vtype[256]; strcpy(vtype,v?v->text:"");
                if(match_sym(lx,">")) next(lx);
                Token *nameTok=next(lx); char namebuf[256]; strcpy(namebuf,nameTok?nameTok->text:"");
                if(match_sym(lx,"=")) next(lx);
                Token *numTok=next(lx); int num=0; if(numTok && numTok->kind==TK_NUMBER) num=atoi(numTok->text);
                if(match_sym(lx,"[")){ int d=1; next(lx); while(d && peek(lx)){ if(match_sym(lx,"[")) d++; if(match_sym(lx,"]")) d--; next(lx);} }
                if(match_sym(lx,";")) next(lx);
                FieldDef fd; memset(&fd,0,sizeof(fd)); strcpy(fd.name,namebuf); char camel[256]; to_camel(namebuf,camel); strcpy(fd.json_name,camel);
                fd.number=num; fd.is_map=true; strcpy(fd.map_key_type,ktype); strcpy(fd.map_val_type,vtype); fd.repeated=false; fd.optional=has_opt; fd.oneof_id=-1;
                add_field(msg,&fd); continue;
            }
            char typebuf[256]; strcpy(typebuf,typeTok->text); next(lx);
            Token *nameTok=peek(lx); if(!nameTok){ next(lx); continue; }
            char namebuf[256]; strcpy(namebuf,nameTok->text); next(lx);
            if(match_sym(lx,"=")) next(lx);
            Token *numTok=next(lx); int num=0; if(numTok && numTok->kind==TK_NUMBER) num=atoi(numTok->text);
            if(match_sym(lx,"[")){ int d=1; next(lx); while(d && peek(lx)){ if(match_sym(lx,"[")) d++; if(match_sym(lx,"]")) d--; next(lx);} }
            if(match_sym(lx,";")) next(lx);
            FieldDef fd; memset(&fd,0,sizeof(fd)); strcpy(fd.name,namebuf); char camel[256]; to_camel(namebuf,camel); strcpy(fd.json_name,camel);
            fd.number=num; fd.repeated=has_rep; fd.optional=has_opt; fd.oneof_id=-1;
            FieldType ft=parse_builtin(typebuf); if(ft!=-1) fd.ftype=ft; else { fd.ftype=FT_MESSAGE; strcpy(fd.type_name,typebuf); }
            add_field(msg,&fd);
        }
    }
    next(lx);
}
static void parse_schema(const char *txt){
    char *clean=strip_comments(txt); Lexer lx; lexer_init(&lx,clean);
    while(lx.pos<lx.n){
        if(match_ident(&lx,"syntax")){ next(&lx); next(&lx); continue; }
        if(match_ident(&lx,"package")){ next(&lx); next(&lx); continue; }
        if(match_ident(&lx,"message")){
            next(&lx); Token *n=next(&lx); if(n){ MessageDef *m=&msgs[msgs_cnt++]; memset(m,0,sizeof(*m)); strcpy(m->name,n->text); parse_message_body(&lx,m); }
        }else next(&lx);
    }
}
static uint64_t read_varint(const uint8_t *buf, size_t *pos, size_t limit){
    uint64_t v=0; int shift=0; while(*pos<limit){ uint8_t b=buf[(*pos)++]; v|=(uint64_t)(b&0x7F)<<shift; if(!(b&0x80)) break; shift+=7; } return v;
}
static int32_t zigzag32(uint64_t v){ return (int32_t)((v>>1) ^ -(v&1)); }
static int64_t zigzag64(uint64_t v){ return (int64_t)((v>>1) ^ -(v&1)); }
static void skip_unknown(const uint8_t *buf, size_t *pos, size_t limit, uint32_t wire){
    if(wire==0){ read_varint(buf,pos,limit); } else if(wire==1){ *pos+=8; } else if(wire==2){ uint64_t len=read_varint(buf,pos,limit); *pos+=len; } else if(wire==5){ *pos+=4; }
}
static void json_escape(FILE *out, const char *s){ fputc('"',out); for(;*s;s++){ unsigned char c=(unsigned char)*s; if(c=='"') fputs("\\\"",out); else if(c=='\\') fputs("\\\\",out); else if(c=='\b') fputs("\\b",out); else if(c=='\t') fputs("\\t",out); else if(c=='\n') fputs("\\n",out); else if(c=='\f') fputs("\\f",out); else if(c=='\r') fputs("\\r",out); else if(c<0x20){ fprintf(out,"\\u%04x",c); } else fputc(c,out); } fputc('"',out); }
static const char b64t[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void base64_encode(FILE *out, const uint8_t *data, size_t len){ for(size_t i=0;i<len;i+=3){ uint32_t v=0; for(int j=0;j<3 && i+j<len;j++) v|=(uint32_t)data[i+j]<<(16-8*j); int n=(len-i)>=3?4:(len-i)==2?4:3; for(int j=0;j<n;j++){ int c=(v>>(18-6*j))&0x3F; fputc(b64t[c],out); } for(int j=n;j<4;j++) fputc('=',out); } }

typedef struct DecodedField { FieldDef *fd; bool present; int64_t i64; bool boolv; char *str; struct { int64_t *i64s; int cnt; } rep; struct { char **keys; char **vals; int cnt; } mp; } DecodedField;
static int cmp_field(const void *a, const void *b){ const FieldDef *fa=((DecodedField*)a)->fd; const FieldDef *fb=((DecodedField*)b)->fd; return fa->number - fb->number; }

static void decode_message(const uint8_t *buf, size_t len, MessageDef *msg, DecodedField *out, int *out_cnt){
    *out_cnt=0; size_t pos=0;
    while(pos<len){
        uint64_t key=read_varint(buf,&pos,len); uint32_t wire=key&7; uint32_t num=key>>3;
        FieldDef *fd=NULL; for(int i=0;i<msg->field_cnt;i++) if(msg->fields[i].number==num){ fd=&msg->fields[i]; break; }
        if(!fd){ skip_unknown(buf,&pos,len,wire); continue; }
        DecodedField *df=NULL; for(int i=0;i<*out_cnt;i++) if(out[i].fd->number==num){ df=&out[i]; break; }
        if(!df){ df=&out[(*out_cnt)++]; df->fd=fd; df->present=false; df->i64=0; df->boolv=false; df->str=NULL; df->rep.i64s=NULL; df->rep.cnt=0; df->mp.keys=NULL; df->mp.vals=NULL; df->mp.cnt=0; }
        if(fd->oneof_id!=-1){ for(int i=0;i<*out_cnt;i++) if(out[i].fd->oneof_id==fd->oneof_id && out[i].fd!=fd) out[i].present=false; }
        if(fd->is_map){
            if(wire!=2){ skip_unknown(buf,&pos,len,wire); continue; }
            uint64_t elen=read_varint(buf,&pos,len); size_t elen_pos=pos; size_t elimit=elen_pos+elen;
            char *key_str=NULL; int64_t val_int=0; bool has_key=false,has_val=false; size_t epos=elen_pos;
            while(epos<elimit){
                uint64_t ekey=read_varint(buf,&epos,elimit); uint32_t ewire=ekey&7; uint32_t en=ekey>>3;
                if(en==1){ if(strcmp(fd->map_key_type,"string")==0){ uint64_t klen=read_varint(buf,&epos,elimit); key_str=malloc(klen+1); memcpy(key_str,buf+epos,klen); key_str[klen]=0; epos+=klen; has_key=true; } else { uint64_t kv=read_varint(buf,&epos,elimit); char tmp[32]; sprintf(tmp,"%lld",(long long)kv); key_str=strdup(tmp); has_key=true; } }
                else if(en==2){ uint64_t vv=read_varint(buf,&epos,elimit); val_int=(int64_t)vv; has_val=true; }
                else skip_unknown(buf,&epos,elimit,ewire);
            }
            if(has_key){ int idx=-1; for(int i=0;i<df->mp.cnt;i++) if(strcmp(df->mp.keys[i],key_str)==0){ idx=i; break; } if(idx>=0){ free(df->mp.vals[idx]); free(df->mp.keys[idx]); } else { df->mp.keys=realloc(df->mp.keys,sizeof(char*)*(df->mp.cnt+1)); df->mp.vals=realloc(df->mp.vals,sizeof(char*)*(df->mp.cnt+1)); df->mp.keys[df->mp.cnt]=key_str; df->mp.cnt++; idx=df->mp.cnt-1; } char vbuf[64]; sprintf(vbuf,"%lld",(long long)val_int); df->mp.vals[idx]=strdup(vbuf); } else if(key_str) free(key_str); pos=elen_pos+elen; continue;
        }
        if(fd->repeated){
            if(wire==2){ uint64_t plen=read_varint(buf,&pos,len); size_t plen_end=pos+plen; while(pos<plen_end){ uint64_t v=read_varint(buf,&pos,len); df->rep.i64s=realloc(df->rep.i64s,sizeof(int64_t)*(df->rep.cnt+1)); df->rep.i64s[df->rep.cnt++]= (int64_t)v; } continue; }
            else { uint64_t v=read_varint(buf,&pos,len); df->rep.i64s=realloc(df->rep.i64s,sizeof(int64_t)*(df->rep.cnt+1)); df->rep.i64s[df->rep.cnt++]= (int64_t)v; continue; }
        }
        switch(fd->ftype){
            case FT_INT32:{ uint64_t v=read_varint(buf,&pos,len); df->i64=(int32_t)(v & 0xFFFFFFFF); df->present=true; break; }
            case FT_INT64:{ uint64_t v=read_varint(buf,&pos,len); df->i64=(int64_t)v; df->present=true; break; }
            case FT_UINT32:{ uint64_t v=read_varint(buf,&pos,len); df->i64=(int64_t)v; df->present=true; break; }
            case FT_UINT64:{ uint64_t v=read_varint(buf,&pos,len); df->i64=(int64_t)v; df->present=true; break; }
            case FT_SINT32:{ uint64_t v=read_varint(buf,&pos,len); df->i64=zigzag32(v); df->present=true; break; }
            case FT_SINT64:{ uint64_t v=read_varint(buf,&pos,len); df->i64=zigzag64(v); df->present=true; break; }
            case FT_BOOL:{ uint64_t v=read_varint(buf,&pos,len); df->boolv=v!=0; df->present=true; break; }
            case FT_STRING:{ uint64_t l=read_varint(buf,&pos,len); df->str=malloc(l+1); memcpy(df->str,buf+pos,l); df->str[l]=0; pos+=l; df->present=true; break; }
            case FT_BYTES:{ uint64_t l=read_varint(buf,&pos,len); df->str=malloc(l+1); memcpy(df->str,buf+pos,l); df->str[l]=0; pos+=l; df->present=true; break; }
            case FT_ENUM:{ uint64_t v=read_varint(buf,&pos,len); df->i64=(int64_t)v; df->present=true; break; }
            default: skip_unknown(buf,&pos,len,wire); break;
        }
    }
}
static void print_message_json(MessageDef *msg, DecodedField *fields, int cnt){
    qsort(fields,cnt,sizeof(DecodedField),cmp_field);
    printf("{"); bool first=true;
    for(int i=0;i<cnt;i++){
        DecodedField *df=&fields[i]; FieldDef *fd=df->fd;
        bool omit=false;
        if(!fd->repeated && !fd->is_map){
            if(!df->present && !fd->optional && fd->oneof_id==-1) omit=true;
            if(!fd->optional && fd->oneof_id==-1){
                if(df->i64==0 && df->boolv==false && (!df->str || strlen(df->str)==0)) omit=true;
            }
        }
        if(omit) continue;
        if(!first) printf(","); first=false;
        json_escape(stdout,fd->json_name); printf(":");
        if(fd->is_map){
            printf("{");
            for(int a=0;a<df->mp.cnt;a++) for(int b=a+1;b<df->mp.cnt;b++) if(strcmp(df->mp.keys[a],df->mp.keys[b])>0){ char *tk=df->mp.keys[a]; df->mp.keys[a]=df->mp.keys[b]; df->mp.keys[b]=tk; char *tv=df->mp.vals[a]; df->mp.vals[a]=df->mp.vals[b]; df->mp.vals[b]=tv; }
            for(int k=0;k<df->mp.cnt;k++){ if(k) printf(","); json_escape(stdout,df->mp.keys[k]); printf(":"); printf("%s",df->mp.vals[k]); }
            printf("}");
        }else if(fd->repeated){
            printf("["); for(int k=0;k<df->rep.cnt;k++){ if(k) printf(","); printf("%lld",(long long)df->rep.i64s[k]); } printf("]");
        }else if(fd->ftype==FT_STRING){ json_escape(stdout,df->str?df->str:""); }
        else if(fd->ftype==FT_BYTES){ printf("\""); if(df->str) base64_encode(stdout,(uint8_t*)df->str,strlen(df->str)); printf("\""); }
        else if(fd->ftype==FT_BOOL){ printf("%s",df->boolv?"true":"false"); }
        else if(fd->ftype==FT_INT64||fd->ftype==FT_UINT64||fd->ftype==FT_SINT64||fd->ftype==FT_FIXED64||fd->ftype==FT_SFIXED64){ printf("\"%lld\"",(long long)df->i64); }
        else if(fd->ftype==FT_ENUM){ EnumDef *en=find_enum(fd->type_name); bool printed=false; if(en){ for(int v=0;v<en->val_cnt;v++) if(en->vals[v].value==(int)df->i64){ json_escape(stdout,en->vals[v].name); printed=true; break; } } if(!printed) printf("%lld",(long long)df->i64); }
        else { printf("%lld",(long long)df->i64); }
    }
    printf("}\n");
}
int main(int argc,char *argv[]){
    if(argc<2){ fprintf(stderr,"usage\n"); return 1; }
    char path[1024]; snprintf(path,sizeof(path),"%s/schema.proto",argv[1]);
    FILE *f=fopen(path,"rb"); if(!f){ perror("schema"); return 1; }
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    parse_schema(buf);
    MessageDef *root=&msgs[0];
    char binpath[1024]; snprintf(binpath,sizeof(binpath),"%s/messages.bin",argv[1]);
    FILE *bf=fopen(binpath,"rb"); if(!bf){ perror("bin"); return 1; }
    fseek(bf,0,SEEK_END); long bsz=ftell(bf); fseek(bf,0,SEEK_SET);
    uint8_t *bdata=malloc(bsz); fread(bdata,1,bsz,bf); fclose(bf);
    size_t pos=0;
    while(pos<bsz){
        uint64_t len=read_varint(bdata,&pos,bsz);
        size_t msg_start=pos; size_t msg_end=msg_start+len;
        if(msg_end>bsz) break;
        DecodedField fields[MAX_FIELDS]; int cnt=0;
        decode_message(bdata+msg_start,len,root,fields,&cnt);
        print_message_json(root,fields,cnt);
        pos=msg_end;
    }
    return 0;
}

import Foundation

func customEncode(_ s: String) -> String {
    var out = ""
    for b in s.utf8 {
        let u = UInt8(b)
        if (u >= 0x41 && u <= 0x5A) || (u >= 0x61 && u <= 0x7A) || (u >= 0x30 && u <= 0x39) || u == 0x2D || u == 0x2E || u == 0x5F || u == 0x2A {
            out.append(Character(UnicodeScalar(u)))
        } else if u == 0x20 {
            out.append("+")
        } else {
            out.append(String(format: "%%%02X", u))
        }
    }
    return out
}

func parseCents(_ s: String) -> Int64 {
    var sign: Int64 = 1
    var str = s
    if str.hasPrefix("-") { sign = -1; str.removeFirst() }
    if let dot = str.firstIndex(of: ".") {
        let intPartStr = String(str[..<dot])
        let fracPartStr = String(str[str.index(after: dot)...])
        let intPart = Int64(intPartStr) ?? 0
        var cents = intPart * 100
        if fracPartStr.count == 1, let d = Int64(fracPartStr) {
            cents += d * 10
        } else if fracPartStr.count >= 1 && fracPartStr.count <= 2, let d = Int64(fracPartStr) {
            cents += d
        }
        return sign * cents
    } else {
        let intPart = Int64(str) ?? 0
        return sign * intPart * 100
    }
}

func formatCents(_ cents: Int64) -> String {
    let sign = cents < 0 ? "-" : ""
    let absC = abs(cents)
    let dollars = absC / 100
    let rem = absC % 100
    return "\(sign)\(dollars).\(String(format: "%02d", rem))"
}

struct TotalsKey: Hashable {
    let name: String
    let currency: String
}

@main
struct Main {
    static func main() async {
        let args = CommandLine.arguments
        guard args.count >= 3 else { exit(0) }
        let dataDir = args[1]
        let baseUrl = args[2]

        let clientPath = URL(fileURLWithPath: dataDir).appendingPathComponent("client.json")
        guard let clientData = try? Data(contentsOf: clientPath),
              let clientJson = try? JSONSerialization.jsonObject(with: clientData) as? [String: Any],
              let clientId = clientJson["client_id"] as? String,
              let clientSecret = clientJson["client_secret"] as? String,
              let scope = clientJson["scope"] as? String,
              let pageSize = clientJson["page_size"] as? Int else { exit(0) }

        let encId = customEncode(clientId)
        let encSecret = customEncode(clientSecret)
        let basicRaw = "\(encId):\(encSecret)"
        let basicB64 = Data(basicRaw.utf8).base64EncodedString()

        let session = URLSession.shared

        func fetchToken() async -> (String, Bool)? {
            guard let url = URL(string: baseUrl + "/oauth/token") else { return nil }
            var req = URLRequest(url: url)
            req.httpMethod = "POST"
            req.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")
            req.setValue("Basic \(basicB64)", forHTTPHeaderField: "Authorization")
            let scopeEnc = scope.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? scope
            let body = "grant_type=client_credentials&scope=\(scopeEnc)"
            req.httpBody = Data(body.utf8)
            let (data, resp) = try? await session.data(for: req)
            guard let http = resp as? HTTPURLResponse else { return nil }
            if http.statusCode != 200 {
                let bodyStr = String(data: data ?? Data(), encoding: .utf8) ?? ""
                print("ERROR \(http.statusCode) \(bodyStr)")
                exit(0)
            }
            guard let json = try? JSONSerialization.jsonObject(with: data ?? Data()) as? [String: Any],
                  let token = json["access_token"] as? String else { return nil }
            return (token, true)
        }

        guard let firstToken = (await fetchToken())?.0 else { exit(0) }
        var accessToken = firstToken
        var freshToken = true
        var reauthCount = 0
        var retryCount = 0
        var pages = 0
        var ordersTotal = 0

        var sums = [TotalsKey: Int64]()
        var statusCounts = [String: Int]()

        var cursor: String? = nil
        var firstOrdersRequest = true

        func makeOrdersURL(cursor: String?) -> URL? {
            var comps = URLComponents(string: baseUrl + "/orders")!
            comps.queryItems = [URLQueryItem(name: "limit", value: "\(pageSize)")]
            if let c = cursor {
                comps.queryItems!.append(URLQueryItem(name: "cursor", value: c))
            }
            return comps.url
        }

        var currentToken = accessToken
        var tokenFresh = freshToken

        loop: while true {
            guard let url = makeOrdersURL(cursor: cursor) else { break }
            var req = URLRequest(url: url)
            req.httpMethod = "GET"
            req.setValue("Bearer \(currentToken)", forHTTPHeaderField: "Authorization")

            var attempt = 0
            while true {
                attempt += 1
                let (data, resp) = try? await session.data(for: req)
                guard let http = resp as? HTTPURLResponse else { break loop }
                let code = http.statusCode
                let bodyStr = String(data: data ?? Data(), encoding: .utf8) ?? ""
                if code == 200 {
                    pages += 1
                    guard let json = try? JSONSerialization.jsonObject(with: data ?? Data()) as? [String: Any],
                          let dataArr = json["data"] as? [[String: Any]] else { break loop }
                    for order in dataArr {
                        ordersTotal += 1
                        if let status = order["status"] as? String {
                            statusCounts[status, default: 0] += 1
                            if status != "cancelled" {
                                let customer = order["customer"] as? [String: Any] ?? [:]
                                let name = customer["name"] as? String ?? ""
                                let currency = order["currency"] as? String ?? ""
                                let amountStr = order["amount"] as? String ?? "0"
                                let cents = parseCents(amountStr)
                                let key = TotalsKey(name: name, currency: currency)
                                sums[key, default: 0] += cents
                            }
                        }
                    }
                    if let next = json["next_cursor"] as? String {
                        cursor = next
                    } else {
                        cursor = nil
                        break loop
                    }
                    tokenFresh = false
                    firstOrdersRequest = false
                    break
                } else if code == 429 {
                    retryCount += 1
                    if let ra = http.value(forHTTPHeaderField: "Retry-After"), let secs = Int(ra) {
                        try? await Task.sleep(nanoseconds: UInt64(secs) * 1_000_000_000)
                    } else {
                        try? await Task.sleep(nanoseconds: 1_000_000_000)
                    }
                    continue
                } else if code == 503 {
                    retryCount += 1
                    try? await Task.sleep(nanoseconds: 500_000_000)
                    continue
                } else if code == 401 {
                    if tokenFresh && firstOrdersRequest {
                        print("ERROR \(code) \(bodyStr)")
                        exit(0)
                    }
                    // reauth
                    guard let newTok = (await fetchToken())?.0 else { break loop }
                    currentToken = newTok
                    accessToken = newTok
                    reauthCount += 1
                    tokenFresh = true
                    req.setValue("Bearer \(currentToken)", forHTTPHeaderField: "Authorization")
                    continue
                } else {
                    print("ERROR \(code) \(bodyStr)")
                    exit(0)
                }
            }
        }

        // output totals
        let totalEntries = sums.map { (key, cents) in (key.name, key.currency, cents) }
        let sortedTotals = totalEntries.sorted {
            let aBytes = Array($0.0.utf8)
            let bBytes = Array($1.0.utf8)
            if aBytes != bBytes {
                return aBytes.lexicographicallyPrecedes(bBytes)
            }
            return $0.1 < $1.1
        }
        for e in sortedTotals {
            print("total \(e.1) \(formatCents(e.2)) \(e.0)")
        }
        let sortedStatuses = statusCounts.sorted { $0.key < $1.key }
        for (st, cnt) in sortedStatuses {
            print("status \(st) \(cnt)")
        }
        print("orders \(ordersTotal) pages \(pages) retries \(retryCount) reauth \(reauthCount)")
    }
}

