                    }
                    tokenFirstUse = false
                    break
                } else if code == 429 {
                    retryCount += 1
                    if let ra = http.value(forHTTPHeaderField: "Retry-After"), let secs = Int(ra) {
                        try? await Task.sleep(nanoseconds: UInt64(secs) * 1_000_000_000)
                    } else {
                        try? await Task.sleep(nanoseconds: 1_000_000_000)
                    }
                    continue
                } else if code == 503 {
                    retryCount += 1
                    try? await Task.sleep(nanoseconds: 500_000_000)
                    continue
                } else if code == 401 {
                    if tokenFirstUse {
                        print("ERROR \(code) \(bodyStr)")
                        exit(0)
                    }
                    guard let newTok = await fetchToken() else { exit(0) }
                    currentToken = newTok
                    reauthCount += 1
                    tokenFirstUse = true
                    req.setValue("Bearer \(currentToken)", forHTTPHeaderField: "Authorization")
                    continue
                } else {
                    print("ERROR \(code) \(bodyStr)")
                    exit(0)
                }
            }
        }

        var totalEntries: [(name: String, currency: String, cents: Int64)] = []
        for (name, curMap) in sums {
            for (currency, cents) in curMap {
                totalEntries.append((name, currency, cents))
            }
        }
        let sortedTotals = totalEntries.sorted { a, b in
            let aBytes = Array(a.name.utf8)
            let bBytes = Array(b.name.utf8)
            if aBytes != bBytes {
                return aBytes.lexicographicallyPrecedes(bBytes)
            }
            return a.currency < b.currency
        }
        for e in sortedTotals {
            print("total \(e.currency) \(formatCents(e.cents)) \(e.name)")
        }
        let sortedStatuses = statusCounts.sorted { $0.key < $1.key }
        for (st, cnt) in sortedStatuses {
            print("status \(st) \(cnt)")
        }
        print("orders \(ordersTotal) pages \(pages) retries \(retryCount) reauth \(reauthCount)")
    }
}

import sys
import json
import os
import socket
from urllib.parse import urlparse

def escape_str(s: str) -> str:
    return s.replace('\\', '\\\\').replace('\n', '\\n').replace('\r', '\\r').replace('\t', '\\t')

def read_request_json(data_dir):
    with open(os.path.join(data_dir, 'request.json'), 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_url(base_url):
    u = urlparse(base_url)
    host = u.hostname
    port = u.port or (443 if u.scheme == 'https' else 80)
    path_prefix = u.path  # e.g. /c/0
    return host, port, path_prefix

def http_post(host, port, path, body_bytes, api_key):
    # raw socket HTTP/1.1
    sock = socket.create_connection((host, port), timeout=10)
    try:
        req_lines = [
            b'POST ' + path.encode() + b' HTTP/1.1',
            b'Host: ' + host.encode() + b':' + str(port).encode(),
            b'x-api-key: ' + api_key.encode(),
            b'anthropic-version: 2023-06-01',
            b'content-type: application/json',
            b'Content-Length: ' + str(len(body_bytes)).encode(),
            b'',
            b'',
        ]
        req = b'\r\n'.join(req_lines) + body_bytes
        sock.sendall(req)

        # status line
        resp = b''
        while not resp.endswith(b'\r\n'):
            chunk = sock.recv(1)
            if not chunk:
                raise ConnectionError('closed')
            resp += chunk
        # first line
        first_line = resp.split(b'\r\n', 1)[0]
        parts = first_line.split(b' ')
        status = int(parts[1])
        # headers
        headers = {}
        line = b''
        while True:
            c = sock.recv(1)
            if not c:
                break
            line += c
            if line.endswith(b'\r\n'):
                line = line.rstrip(b'\r\n')
                if line == b'':
                    break
                if b':' in line:
                    k, v = line.split(b':', 1)
                    headers[k.strip().lower().decode()] = v.strip().decode()
                line = b''
        # body
        body = bytearray()
        if status != 200:
            # Content-Length
            cl = int(headers.get('content-length', '0'))
            remaining = cl
            while remaining > 0:
                data = sock.recv(min(4096, remaining))
                if not data:
                    break
                body.extend(data)
                remaining -= len(data)
            return status, headers, bytes(body)
        # 200 -> chunked
        # read chunked body
        # we can just read raw chunks and collect
        # Transfer-Encoding chunked
        while True:
            # read chunk size line
            size_line = b''
            while True:
                c = sock.recv(1)
                if not c:
                    raise ConnectionError('closed')
                size_line += c
                if size_line.endswith(b'\r\n'):
                    break
            size_line = size_line.strip()
            if not size_line:
                continue
            size_str = size_line.split(b';')[0]
            try:
                size = int(size_str, 16)
            except ValueError:
                # malformed
                break
            if size == 0:
                # consume trailing CRLF
                # read until empty line
                # just break
                # consume remaining
                # read a bit
                # ignore trailers
                break
            # read size bytes
            remaining = size
            chunk_data = bytearray()
            while remaining > 0:
                data = sock.recv(min(4096, remaining))
                if not data:
                    break
                chunk_data.extend(data)
                remaining -= len(data)
            body.extend(chunk_data)
            # consume CRLF
            crlf = sock.recv(2)
            # continue
        return status, headers, bytes(body)
    finally:
        try:
            sock.close()
        except:
            pass

def parse_sse(text):
    events = []
    current_event = None
    data_parts = []
    for line in text.splitlines():
        # keep original line endings? splitlines removes them
        if line == '':
            if current_event is not None or data_parts:
                # finalize
                data_str = '\n'.join(data_parts)
                events.append((current_event, data_str))
                current_event = None
                data_parts = []
            continue
        if line.startswith(':'):
            continue
        if line.startswith('event:'):
            current_event = line[6:].lstrip()
        elif line.startswith('data:'):
            rest = line[5:]
            if rest.startswith(' '):
                rest = rest[1:]
            data_parts.append(rest)
        else:
            # ignore unknown
            pass
    # trailing
    if data_parts or current_event is not None:
        data_str = '\n'.join(data_parts)
        events.append((current_event, data_str))
    return events

def process_reply(events):
    # state
    input_tokens = 0
    cache_read = 0
    output_tokens = 0
    stop_reason = None
    blocks_by_index = {}
    # ensure order list
    indices_seen = []
    for ev_name, data_str in events:
        if not data_str.strip():
            continue
        try:
            obj = json.loads(data_str)
        except:
            continue
        if ev_name == 'message_start':
            msg = obj.get('message', {})
            usage = msg.get('usage', {})
            input_tokens = usage.get('input_tokens', 0)
            cache_read = usage.get('cache_read_input_tokens', 0)
        elif ev_name == 'content_block_start':
            idx = obj.get('index')
            cb = obj.get('content_block', {})
            typ = cb.get('type')
            block = {
                'index': idx,
                'type': typ,
                'thinking': '',
                'signature': '',
                'text': '',
                'id': '',
                'name': '',
                'input_parts': [],
            }
            if typ == 'thinking':
                block['thinking'] = ''
                block['signature'] = ''
            elif typ == 'text':
                block['text'] = ''
            elif typ == 'tool_use':
                block['id'] = cb.get('id', '')
                block['name'] = cb.get('name', '')
                block['input_parts'] = []
            blocks_by_index[idx] = block
            if idx not in indices_seen:
                indices_seen.append(idx)
        elif ev_name == 'content_block_delta':
            idx = obj.get('index')
            delta = obj.get('delta', {})
            block = blocks_by_index.get(idx)
            if not block:
                continue
            d_type = delta.get('type')
            if d_type == 'thinking_delta':
                block['thinking'] += delta.get('thinking', '')
            elif d_type == 'signature_delta':
                block['signature'] += delta.get('signature', '')
            elif d_type == 'text_delta':
                block['text'] += delta.get('text', '')
            elif d_type == 'input_json_delta':
                block['input_parts'].append(delta.get('partial_json', ''))
        elif ev_name == 'message_delta':
            delta = obj.get('delta', {})
            stop_reason = delta.get('stop_reason')
            usage = obj.get('usage', {})
            output_tokens = usage.get('output_tokens', 0)
        # ignore others
    # build ordered blocks
    ordered = []
    # indices may not be sorted, sort by index
    for idx in sorted(blocks_by_index.keys()):
        blk = blocks_by_index[idx]
        ordered.append(blk)
    return {
        'input_tokens': input_tokens,
        'cache_read': cache_read,
        'output_tokens': output_tokens,
        'stop_reason': stop_reason,
        'blocks': ordered,
    }

def run_tool(name, input_obj):
    if name == 'measure':
        text = input_obj.get('text', '')
        unit = input_obj.get('unit', '')
        try:
            if unit == 'code_points':
                length = len(text)
            elif unit == 'utf8_bytes':
                length = len(text.encode('utf-8'))
            elif unit == 'utf16_units':
                # count code units
                length = 0
                for ch in text:
                    cp = ord(ch)
                    if cp > 0xFFFF:
                        length += 2
                    else:
                        length += 1
            else:
                return False, f'unsupported unit: {unit}'
            return True, str(length)
        except Exception as e:
            return False, f'unsupported unit: {unit}'
    elif name == 'reverse':
        text = input_obj.get('text', '')
        return True, text[::-1]
    else:
        return False, f'unknown tool: {name}'

def main():
    if len(sys.argv) != 3:
        sys.exit(1)
    data_dir = sys.argv[1]
    base_url = sys.argv[2]
    req_json = read_request_json(data_dir)
    api_key = req_json['api_key']
    model = req_json['model']
    max_tokens = req_json['max_tokens']
    thinking_budget = req_json['thinking_budget']
    system = req_json['system']
    prompt = req_json['prompt']
    tools = req_json['tools']

    host, port, path_prefix = parse_url(base_url)
    path = path_prefix + '/v1/messages'

    # first request
    messages1 = [{"role": "user", "content": prompt}]
    body1 = {
        "model": model,
        "max_tokens": max_tokens,
        "stream": True,
        "thinking": {"type": "enabled", "budget_tokens": thinking_budget},
        "system": system,
        "tools": tools,
        "messages": messages1,
    }
    body1_bytes = json.dumps(body1, separators=(',', ':')).encode('utf-8')
    status, headers, body_bytes = http_post(host, port, path, body1_bytes, api_key)
    # parse
    print('request 1')
    if status != 200:
        # error handling
        try:
            err = json.loads(body_bytes.decode('utf-8'))
            e_type = err.get('error', {}).get('type', '')
            e_msg = err.get('error', {}).get('message', '')
            print(f'ERROR {status} {e_type}: {e_msg}')
        except:
            print(f'ERROR {status} unknown')
        sys.exit(0)
    # decode body as utf-8 with replacement for safety
    text = body_bytes.decode('utf-8', errors='replace')
    events = parse_sse(text)
    reply1 = process_reply(events)

    # print blocks
    for blk in reply1['blocks']:
        typ = blk['type']
        if typ == 'thinking':
            print(f'thinking {escape_str(blk["thinking"])}')
            print(f'signature {escape_str(blk["signature"])}')
        elif typ == 'text':
            print(f'text {escape_str(blk["text"])}')
        elif typ == 'tool_use':
            input_json = ''.join(blk['input_parts'])
            print(f'tool_use {blk["id"]} {blk["name"]} {escape_str(input_json)}')
    print(f'stop_reason {reply1["stop_reason"]}')

    # run tools
    tool_results = []
    for blk in reply1['blocks']:
        if blk['type'] != 'tool_use':
            continue
        input_json = ''.join(blk['input_parts'])
        try:
            input_obj = json.loads(input_json)
        except:
            input_obj = {}
        success, result = run_tool(blk['name'], input_obj)
        tool_results.append((blk['id'], success, result))

    for tid, success, res in tool_results:
        if success:
            print(f'result {tid} {escape_str(res)}')
        else:
            print(f'error {tid} {escape_str(res)}')

    # second request
    # build assistant message
    assistant_content = []
    for blk in reply1['blocks']:
        typ = blk['type']
        if typ == 'thinking':
            assistant_content.append({
                "type": "thinking",
                "thinking": blk['thinking'],
                "signature": blk['signature']
            })
        elif typ == 'text':
            assistant_content.append({
                "type": "text",
                "text": blk['text']
            })
        elif typ == 'tool_use':
            input_json = ''.join(blk['input_parts'])
            try:
                input_obj = json.loads(input_json)
            except:
                input_obj = {}
            assistant_content.append({
                "type": "tool_use",
                "id": blk['id'],
                "name": blk['name'],
                "input": input_obj
            })
    # tool result messages
    tool_result_blocks = []
    for blk in reply1['blocks']:
        if blk['type'] != 'tool_use':
            continue
        tid = blk['id']
        # find result
        success = None
        res = ''
        for rtid, s, r in tool_results:
            if rtid == tid:
                success = s
                res = r
                break
        block = {
            "type": "tool_result",
            "tool_use_id": tid,
            "content": res
        }
        if not success:
            block["is_error"] = True
        tool_result_blocks.append(block)

    messages2 = [
        {"role": "user", "content": prompt},
        {"role": "assistant", "content": assistant_content},
        {"role": "user", "content": tool_result_blocks}
    ]
    body2 = {
        "model": model,
        "max_tokens": max_tokens,
        "stream": True,
        "thinking": {"type": "enabled", "budget_tokens": thinking_budget},
        "system": system,
        "tools": tools,
        "messages": messages2,
    }
    body2_bytes = json.dumps(body2, separators=(',', ':')).encode('utf-8')
    status2, headers2, body_bytes2 = http_post(host, port, path, body2_bytes, api_key)
    print('request 2')
    if status2 != 200:
        try:
            err = json.loads(body_bytes2.decode('utf-8'))
            e_type = err.get('error', {}).get('type', '')
            e_msg = err.get('error', {}).get('message', '')
            print(f'ERROR {status2} {e_type}: {e_msg}')
        except:
            print(f'ERROR {status2} unknown')
        sys.exit(0)
    text2 = body_bytes2.decode('utf-8', errors='replace')
    events2 = parse_sse(text2)
    reply2 = process_reply(events2)

    for blk in reply2['blocks']:
        typ = blk['type']
        if typ == 'thinking':
            print(f'thinking {escape_str(blk["thinking"])}')
            print(f'signature {escape_str(blk["signature"])}')
        elif typ == 'text':
            print(f'text {escape_str(blk["text"])}')
        elif typ == 'tool_use':
            input_json = ''.join(blk['input_parts'])
            print(f'tool_use {blk["id"]} {blk["name"]} {escape_str(input_json)}')
    print(f'stop_reason {reply2["stop_reason"]}')

    total_input = reply1['input_tokens'] + reply2['input_tokens']
    total_output = reply1['output_tokens'] + reply2['output_tokens']
    total_cache = reply1['cache_read'] + reply2['cache_read']
    print(f'usage input={total_input} output={total_output} cache_read={total_cache}')

if __name__ == '__main__':
    main()

import sys
import os
import re
import sqlite3
import binascii
from decimal import Decimal, getcontext

def parse_columns(sql):
    # find the parentheses that contain column definitions
    m = re.search(r'CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?["\w]+\s*\(', sql, re.IGNORECASE)
    if not m:
        return []
    start = m.end() - 1  # '('
    depth = 0
    end = None
    for i in range(start, len(sql)):
        c = sql[i]
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth == 0:
                end = i
                break
    if end is None:
        return []
    inside = sql[start+1:end]
    # split by commas not inside parentheses
    parts = []
    cur = []
    d = 0
    for ch in inside:
        if ch == '(':
            d += 1
        elif ch == ')':
            d -= 1
        if ch == ',' and d == 0:
            parts.append(''.join(cur))
            cur = []
            continue
        cur.append(ch)
    if cur:
        parts.append(''.join(cur))

    cols = []
    for p in parts:
        p = p.strip()
        if not p:
            continue
        # first token is column name
        # quoted ?
        m2 = re.match(r'\s*("([^"]+)"|([A-Za-z_][A-Za-z0-9_]*))\s+', p)
        if not m2:
            continue
        name = m2.group(2) if m2.group(2) is not None else m2.group(3)
        cols.append(name)
    return cols

def escape_text(s: str) -> str:
    b = s.encode('utf-8')
    out = ['"']
    for byte in b:
        if byte == 0x5c:  # backslash
            out.append('\\\\')
        elif byte == 0x22:  # "
            out.append('\\"')
        elif byte == 0x0a:
            out.append('\\n')
        elif byte == 0x0d:
            out.append('\\r')
        elif byte == 0x09:
            out.append('\\t')
        elif 0x20 <= byte <= 0x7e:
            out.append(chr(byte))
        else:
            out.append('\\x%02X' % byte)
    out.append('"')
    return ''.join(out)

def crc32_hex(b: bytes) -> str:
    return format(binascii.crc32(b) & 0xffffffff, '08x')

def format_value(v):
    if v is None:
        return 'NULL'
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        getcontext().prec = 50
        d = Decimal.from_float(v)
        # plain representation
        s = format(d, 'f')
        # remove unnecessary trailing zeros? spec: trailing zeros removed but at least one digit
        if '.' in s:
            int_part, frac = s.split('.')
            frac = frac.rstrip('0')
            if frac == '':
                frac = '0'
            s = int_part + '.' + frac
        return s
    if isinstance(v, bytes):
        # BLOB
        if len(v) <= 100:
            hexs = v.hex().upper()
            return "X'%s'" % hexs
        else:
            return f"<BLOB len={len(v)} crc32={crc32_hex(v)}>"
    if isinstance(v, str):
        b = v.encode('utf-8')
        if len(b) <= 100:
            return escape_text(v)
        else:
            return f"<TEXT len={len(b)} crc32={crc32_hex(b)}>"
    # fallback
    return str(v)

def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]
    db_path = os.path.join(directory, 'db.sqlite')
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT name, sql FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name COLLATE BINARY")
    tables = cur.fetchall()

    out_lines = []
    first_table = True
    for row in tables:
        name = row['name']
        sql = row['sql'] or ''
        cols = parse_columns(sql)
        # query rows
        # use rowid
        try:
            cur.execute(f'SELECT rowid, * FROM "{name}" ORDER BY rowid')
        except Exception:
            # fallback without quotes
            cur.execute(f'SELECT rowid, * FROM {name} ORDER BY rowid')
        rows = cur.fetchall()
        # number of rows = len(rows)
        if not first_table:
            out_lines.append('')
        first_table = False
        out_lines.append(f'TABLE {name} rows={len(rows)}')
        out_lines.append('COLUMNS ' + ', '.join(cols))
        for r in rows:
            rowid = r[0]
            vals = []
            # columns start at index 1
            for i in range(1, len(r)):
                # if table has fewer columns than fetched? sqlite returns None for missing?
                vals.append(format_value(r[i]))
            out_lines.append(f'{rowid}: ' + ', '.join(vals))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    main()

import sys
import os
import sqlite3
import binascii
from decimal import Decimal, getcontext

def crc32_hex(b: bytes) -> str:
    return format(binascii.crc32(b) & 0xffffffff, '08x')

def format_real(f: float) -> str:
    getcontext().prec = 50
    d = Decimal.from_float(f)
    s = format(d, 'f')
    if '.' not in s:
        s += '.0'
    else:
        int_part, frac = s.split('.')
        frac = frac.rstrip('0')
        if frac == '':
            frac = '0'
        s = int_part + '.' + frac
    return s

def format_text(s: str) -> str:
    b = s.encode('utf-8')
    n = len(b)
    if n > 100:
        return f"<TEXT len={n} crc32={crc32_hex(b)}>"
    out = ['"']
    for ch in s:
        if ch == '\\':
            out.append('\\\\')
        elif ch == '"':
            out.append('\\"')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ord(ch) < 0x20 or ord(ch) == 0x7F:
            out.append('\\x%02X' % ord(ch))
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)

def format_blob(b: bytes) -> str:
    n = len(b)
    if n > 100:
        return f"<BLOB len={n} crc32={crc32_hex(b)}>"
    return "X'" + b.hex().upper() + "'"

def format_value(v):
    if v is None:
        return 'NULL'
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        return format_real(v)
    if isinstance(v, bytes):
        return format_blob(v)
    if isinstance(v, str):
        return format_text(v)
    return str(v)

def main():
    if len(sys.argv) < 2:
        return
    db_path = os.path.join(sys.argv[1], 'db.sqlite')
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    cur.execute(
        "SELECT name, sql FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name COLLATE BINARY"
    )
    tables = cur.fetchall()

    out = []
    first = True
    for name, sql in tables:
        # columns via pragma
        cur.execute(f'PRAGMA table_info("{name}")')
        info = cur.fetchall()
        cols = [row[1] for row in info]
        # fetch rows
        cur.execute(f'SELECT rowid, * FROM "{name}" ORDER BY rowid')
        rows = cur.fetchall()
        if not first:
            out.append('')
        first = False
        out.append(f'TABLE {name} rows={len(rows)}')
        out.append('COLUMNS ' + ', '.join(cols))
        for r in rows:
            rowid = r[0]
            vals = [format_value(v) for v in r[1:]]
            out.append(f'{rowid}: ' + ', '.join(vals))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

import { open } from 'node:sqlite';
import * as fs from 'node:fs';
