const dir = process.argv[2];
if (!dir) { process.exit(0); }
const dbPath = path.join(dir, 'db.sqlite');

const db = open(dbPath, 'readonly');

function crc32(buf: Uint8Array): number {
  const table = crc32.table ?? (crc32.table = (() => {
    const t = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[i] = c;
    }
    return t;
  })());
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function formatValue(v: unknown): string {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') {
    if (!Number.isFinite(v)) return 'NULL';
    // exact decimal without exponent
    let s = v.toString();
    if (s.includes('e') || s.includes('E')) {
      // expand
      const [mant, exp] = s.split(/[eE]/);
      const e = parseInt(exp, 10);
      const [intPart, frac = ''] = mant.split('.');
      if (e >= 0) {
        const combined = (intPart + frac).padEnd(intPart.length + frac.length + e, '0');
        const pos = intPart.length + frac.length;
        const out = combined.slice(0, pos + e) + combined.slice(pos + e);
        return out;
      } else {
        const zeros = '0'.repeat(-e - intPart.length);
        return '0.' + zeros + intPart + frac;
      }
    }
    // remove unnecessary trailing zeros
    if (s.includes('.')) {
      s = s.replace(/(\.\d*?)0+$/, '$1');
      if (s.endsWith('.')) s += '0';
    }
    return s;
  }
  if (typeof v === 'string') {
    const bytes = Buffer.from(v, 'utf8');
    if (bytes.length > 100) {
      return `<TEXT len=${bytes.length} crc32=${crc32(bytes).toString(16).padStart(8,'0')}>`;
    }
    // escape
    let out = '"';
    for (let i = 0; i < bytes.length; i++) {
      const b = bytes[i];
      if (b === 0x5c) out += '\\\\';
      else if (b === 0x22) out += '\\"';
      else if (b === 0x0a) out += '\\n';
      else if (b === 0x0d) out += '\\r';
      else if (b === 0x09) out += '\\t';
      else if (b < 0x20 || b > 0x7f) {
        out += '\\x' + b.toString(16).padStart(2,'0').toUpperCase();
      } else {
        out += String.fromCharCode(b);
      }
    }
    out += '"';
    return out;
  }
  if (v instanceof Uint8Array || Buffer.isBuffer(v)) {
    const buf = Buffer.from(v);
    if (buf.length > 100) {
      return `<BLOB len=${buf.length} crc32=${crc32(buf).toString(16).padStart(8,'0')}>`;
    }
    return "X'" + buf.toString('hex').toUpperCase() + "'";
  }
  return String(v);
}

