import { DatabaseSync } from 'node:sqlite';
import * as fs from 'node:fs';
import * as path from 'node:path';

const dir = process.argv[2];
if (!dir) process.exit(0);
const dbPath = path.join(dir, 'db.sqlite');

const db = new DatabaseSync(dbPath);

function crc32(buf: Uint8Array): number {
  const table = crc32.table ?? (crc32.table = (() => {
    const t = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[i] = c;
    }
    return t;
  })());
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function formatReal(v: number): string {
  let s = v.toString();
  if (s.includes('e') || s.includes('E')) {
    const [mant, expStr] = s.split(/[eE]/);
    const e = parseInt(expStr, 10);
    const [intPart, frac = ''] = mant.split('.');
    const combined = (intPart + frac);
    if (e >= 0) {
      const padded = combined.padEnd(combined.length + e, '0');
      const intLen = intPart.length;
      const fracLen = frac.length;
      const pos = intLen + fracLen;
      const out = padded.slice(0, pos + e);
      return out;
    } else {
      const negE = -e;
      if (negE <= intPart.length) {
        const cut = intPart.length - negE;
        const intNew = intPart.slice(0, cut);
        const fracNew = intPart.slice(cut) + frac;
        return intNew + '.' + fracNew;
      } else {
        const zeros = '0'.repeat(negE - intPart.length);
        return '0.' + zeros + intPart + frac;
      }
    }
  }
  if (s.includes('.')) {
    s = s.replace(/(\.\d*?)0+$/, '$1');
    if (s.endsWith('.')) s += '0';
  } else {
    s += '.0';
  }
  return s;
}

function escapeText(bytes: Uint8Array): string {
  let out = '"';
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (b === 0x5c) out += '\\\\';
    else if (b === 0x22) out += '\\"';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b === 0x09) out += '\\t';
    else if (b < 0x20 || b > 0x7f) {
      out += '\\x' + b.toString(16).padStart(2, '0').toUpperCase();
    } else {
      out += String.fromCharCode(b);
    }
  }
  out += '"';
  return out;
}

function formatValue(value: unknown, storage: string): string {
  if (value === null || value === undefined) return 'NULL';
  if (storage === 'integer') {
    return String(value);
  }
  if (storage === 'real') {
    const n = Number(value);
    return formatReal(n);
  }
  if (storage === 'text') {
    const str = String(value);
    const buf = Buffer.from(str, 'utf8');
    if (buf.length > 100) {
      return `<TEXT len=${buf.length} crc32=${crc32(buf).toString(16).padStart(8,'0')}>`;
    }
    return escapeText(buf);
  }
  if (storage === 'blob') {
    const buf = Buffer.from(value as Uint8Array);
    if (buf.length > 100) {
      return `<BLOB len=${buf.length} crc32=${crc32(buf).toString(16).padStart(8,'0')}>`;
    }
    return "X'" + buf.toString('hex').toUpperCase() + "'";
  }
  // fallback
  return String(value);
}

const tables = db.prepare(
  `SELECT name, sql FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name`
).all() as {name:string, sql:string}[];

let firstTable = true;
for (const t of tables) {
  const name = t.name;
  const info = db.prepare(`PRAGMA table_info(${JSON.stringify(name)})`).all() as {cid:number,name:string,type:string,pk:number}[];
  const cols = info.map(i => i.name);
  const rowCount = db.prepare(`SELECT COUNT(*) AS c FROM ${JSON.stringify(name)}`).get() as {c:number};
  if (!firstTable) console.log('');
  firstTable = false;
  console.log(`TABLE ${name} rows=${rowCount.c}`);
  console.log(`COLUMNS ${cols.join(', ')}`);

  if (rowCount.c === 0) continue;

  // build select with typeof
  const colList = cols.join(', ');
  const typeofList = cols.map((c,i)=>`typeof(${JSON.stringify(c)}) AS __type${i}`).join(', ');
  const sql = `SELECT rowid, ${colList}, ${typeofList} FROM ${JSON.stringify(name)} ORDER BY rowid`;
  const rows = db.prepare(sql).all() as any[];

  for (const r of rows) {
    const rowid = r.rowid;
    const values: string[] = [];
    for (let i = 0; i < cols.length; i++) {
      const val = r[i + 1];
      const storage = r[`__type${i}`] as string;
      values.push(formatValue(val, storage));
    }
    console.log(`${rowid}: ${values.join(', ')}`);
  }
}
db.close();

import java.io.*;
import java.math.BigInteger;
import java.net.URI;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    static class JsonParser {
        static Object parse(String s) { return new Parser(s).parseValue(); }
        static class Parser {
            char[] a; int p;
            Parser(String s){ a = s.toCharArray(); p=0; }
            void skipWs(){ while(p<a.length && Character.isWhitespace(a[p])) p++; }
            Object parseValue(){ skipWs(); if(p>=a.length) return null;
                char c=a[p];
                if(c=='{') return parseObject();
                if(c=='[') return parseArray();
                if(c=='"') return parseString();
                if(c=='t'){ p+=4; return Boolean.TRUE; }
                if(c=='f'){ p+=5; return Boolean.FALSE; }
                if(c=='n'){ p+=4; return null; }
                if(c=='-'||Character.isDigit(c)) return parseNumber();
                p++; return null;
            }
            Map<String,Object> parseObject(){
                p++; // {
                Map<String,Object> m=new LinkedHashMap<>();
                skipWs();
                if(p<a.length && a[p]=='}'){ p++; return m; }
                while(true){
                    skipWs();
                    String key=parseString();
                    skipWs(); p++; // :
                    Object val=parseValue();
                    m.put(key,val);
                    skipWs();
                    if(a[p]==','){ p++; continue; }
                    if(a[p]=='}'){ p++; break; }
                }
                return m;
            }
            List<Object> parseArray(){
                p++; // [
                List<Object> l=new ArrayList<>();
                skipWs();
                if(p<a.length && a[p]==']'){ p++; return l; }
                while(true){
                    Object v=parseValue();
                    l.add(v);
                    skipWs();
                    if(a[p]==','){ p++; continue; }
                    if(a[p]==']'){ p++; break; }
                }
                return l;
            }
            String parseString(){
                p++; // "
                StringBuilder sb=new StringBuilder();
                while(p<a.length){
                    char c=a[p++];
                    if(c=='"') break;
                    if(c=='\\'){
                        if(p>=a.length) break;
                        char e=a[p++];
                        switch(e){
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            case 'u':
                                if(p+4<=a.length){
                                    String hex=new String(a,p,4);
                                    int code=Integer.parseInt(hex,16);
                                    sb.append((char)code);
                                    p+=4;
                                }
                                break;
                        }
                    }else sb.append(c);
                }
                return sb.toString();
            }
            Number parseNumber(){
                int start=p;
                if(a[p]=='-') p++;
                while(p<a.length && Character.isDigit(a[p])) p++;
                if(p<a.length && a[p]=='.'){ p++; while(p<a.length && Character.isDigit(a[p])) p++; }
                String num=new String(a,start,p-start);
                try{ return Long.parseLong(num); }catch(Exception e){ return new BigInteger(num); }
            }
        }
    }

    static String formUrlEncode(String s){
        byte[] b=s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb=new StringBuilder();
        for(byte by:b){
            int ub=by & 0xFF;
            char c=(char)ub;
            if((ub>=0x30 && ub<=0x39) || (ub>=0x41 && ub<=0x5A) || (ub>=0x61 && ub<=0x7A)
               || ub==0x2D || ub==0x2E || ub==0x5F || ub==0x2A){
                sb.append(c);
            }else if(ub==0x20){
                sb.append('+');
            }else{
                sb.append(String.format("%%%02X", ub));
            }
        }
        return sb.toString();
    }

    static BigInteger amountToCents(String s){
        if(s==null) return BigInteger.ZERO;
        int sign=1;
        if(s.startsWith("-")){ sign=-1; s=s.substring(1); }
        if(s.contains(".")){
            String[] parts=s.split("\\.",2);
            BigInteger intPart=new BigInteger(parts[0].isEmpty()?"0":parts[0]);
            String frac=parts[1];
            if(frac.length()==1) frac=frac+"0";
            else if(frac.length()>2) frac=frac.substring(0,2);
            else if(frac.length()==0) frac="00";
            BigInteger cents=intPart.multiply(BigInteger.valueOf(100)).add(new BigInteger(frac));
            return sign==-1?cents.negate():cents;
        }else{
            BigInteger intPart=new BigInteger(s.isEmpty()?"0":s);
            return intPart.multiply(BigInteger.valueOf(100)).multiply(BigInteger.valueOf(sign));
        }
    }

    static String formatCents(BigInteger cents){
        if(cents.signum()==0) return "0.00";
        boolean neg=cents.signum()<0;
        BigInteger abs=cents.abs();
        BigInteger intPart=abs.divide(BigInteger.valueOf(100));
        BigInteger frac=abs.remainder(BigInteger.valueOf(100));
        String fracStr=frac.toString();
        if(fracStr.length()==1) fracStr="0"+fracStr;
        else if(fracStr.length()==0) fracStr="00";
        return (neg?"-":"")+intPart.toString()+"."+fracStr;
    }

    static int compareUtf8(String a,String b){
        byte[] ba=a.getBytes(StandardCharsets.UTF_8);
        byte[] bb=b.getBytes(StandardCharsets.UTF_8);
        int n=Math.min(ba.length,bb.length);
        for(int i=0;i<n;i++){
            int diff=(ba[i]&0xFF)-(bb[i]&0xFF);
            if(diff!=0) return diff;
        }
        return ba.length-bb.length;
    }

    public static void main(String[] args) throws Exception {
        if(args.length<2){ System.exit(0); }
        String dataDir=args[0];
        String baseUrl=args[1];
        String clientJson=Files.readString(Path.of(dataDir,"client.json"),StandardCharsets.UTF_8);
        // extract fields with regex
        Pattern p=Pattern.compile("\"client_id\"\\s*:\\s*\"([^\"]*)\"");
        Matcher m=p.matcher(clientJson); m.find(); String clientId=m.group(1);
        p=Pattern.compile("\"client_secret\"\\s*:\\s*\"([^\"]*)\"");
        m=p.matcher(clientJson); m.find(); String clientSecret=m.group(1);
        p=Pattern.compile("\"scope\"\\s*:\\s*\"([^\"]*)\"");
        m=p.matcher(clientJson); m.find(); String scope=m.group(1);
        p=Pattern.compile("\"page_size\"\\s*:\\s*(\\d+)");
        m=p.matcher(clientJson); m.find(); int pageSize=Integer.parseInt(m.group(1));

        String encId=formUrlEncode(clientId);
        String encSecret=formUrlEncode(clientSecret);
        String basicCred=encId+":"+encSecret;
        String basicB64=Base64.getEncoder().encodeToString(basicCred.getBytes(StandardCharsets.UTF_8));

        HttpClient http=HttpClient.newHttpClient();

        // token obtain
        String accessToken=getToken(http,baseUrl,basicB64,scope);
        int reauth=0;
        boolean tokenFresh=true;
        int retries=0;
        int pages=0;
        int ordersReceived=0;
        Map<String,BigInteger> totals=new TreeMap<>();
        Map<String,Long> statusCounts=new HashMap<>();
        Map<String,BigInteger> sumMap=new HashMap<>(); // key name|currency

        String cursor=null;
        boolean firstOrderRequest=true;
        while(true){
            String url=baseUrl+"/orders?limit="+pageSize;
            if(cursor!=null) url+="&cursor="+java.net.URLEncoder.encode(cursor,StandardCharsets.UTF_8);
            HttpRequest req=HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .header("Authorization","Bearer "+accessToken)
                    .GET()
                    .build();
            HttpResponse<String> resp;
            int attempt=0;
            while(true){
                resp=http.send(req,HttpResponse.BodyHandlers.ofString());
                int code=resp.statusCode();
                if(code==200){
                    pages++;
                    // process
                    String body=resp.body();
                    Object parsed=JsonParser.parse(body);
                    if(!(parsed instanceof Map)) break;
                    Map<String,Object> obj=(Map<String,Object>)parsed;
                    Object dataObj=obj.get("data");
                    Object nextCursorObj=obj.get("next_cursor");
                    List<Object> dataList=new ArrayList<>();
                    if(dataObj instanceof List) dataList=(List<Object>)dataObj;
                    for(Object o:dataList){
                        if(!(o instanceof Map)) continue;
                        Map<String,Object> order=(Map<String,Object>)o;
                        ordersReceived++;
                        String status=(String)order.get("status");
                        if(status!=null){
                            statusCounts.merge(status,1L,Long::sum);
                        }
                        if(!"cancelled".equals(status)){
                            Map<String,Object> cust=(Map<String,Object>)order.get("customer");
                            String name=null;
                            if(cust!=null) name=(String)cust.get("name");
                            String currency=(String)order.get("currency");
                            String amountStr=(String)order.get("amount");
                            if(name!=null && currency!=null && amountStr!=null){
                                BigInteger cents=amountToCents(amountStr);
                                String key=name+"\u0000"+currency;
                                sumMap.merge(key,cents,BigInteger::add);
                            }
                        }
                    }
                    tokenFresh=false;
                    if(nextCursorObj==null) cursor=null;
                    else if(nextCursorObj instanceof String) cursor=(String)nextCursorObj;
                    else cursor=null;
                    if(cursor==null) break;
                    // prepare next request
                    req=HttpRequest.newBuilder()
                            .uri(URI.create(baseUrl+"/orders?limit="+pageSize+"&cursor="+java.net.URLEncoder.encode(cursor,StandardCharsets.UTF_8)))
                            .header("Authorization","Bearer "+accessToken)
                            .GET()
                            .build();
                    firstOrderRequest=false;
                    break;
                }else if(code==429){
                    retries++;
                    String ra=resp.headers().firstValue("Retry-After").orElse("0");
                    try{ Thread.sleep(Long.parseLong(ra)*1000L); }catch(Exception e){}
                    // retry same req
                    continue;
                }else if(code==503){
                    retries++;
                    Thread.sleep(500);
                    continue;
                }else if(code==401){
                    if(tokenFresh){
                        // fatal
                        System.out.println("ERROR "+code+" "+resp.body());
                        return;
                    }else{
                        // reauth
                        accessToken=getToken(http,baseUrl,basicB64,scope);
                        reauth++;
                        tokenFresh=true;
                        // retry same request with new token
                        req=HttpRequest.newBuilder()
                                .uri(req.uri())
                                .header("Authorization","Bearer "+accessToken)
                                .GET()
                                .build();
                        continue;
                    }
                }else{
                    System.out.println("ERROR "+code+" "+resp.body());
                    return;
                }
            }
        }

        // output totals
        List<String> names=new ArrayList<>(sumMap.keySet());
        names.sort((a,b)->{
            String nameA=a.split("\u0000",2)[0];
            String nameB=b.split("\u0000",2)[0];
            int cmp=compareUtf8(nameA,nameB);
            if(cmp!=0) return cmp;
            String curA=a.split("\u0000",2)[1];
            String curB=b.split("\u0000",2)[1];
            return curA.compareTo(curB);
        });
        for(String key:names){
            String[] parts=key.split("\u0000",2);
            String name=parts[0];
            String currency=parts[1];
            BigInteger sum=sumMap.get(key);
            System.out.println("total "+currency+" "+formatCents(sum)+" "+name);
        }
        List<String> statuses=new ArrayList<>(statusCounts.keySet());
        Collections.sort(statuses);
        for(String st:statuses){
            System.out.println("status "+st+" "+statusCounts.get(st));
        }
        System.out.println("orders "+ordersReceived+" pages "+pages+" retries "+retries+" reauth "+reauth);
    }

    static String getToken(HttpClient http,String baseUrl,String basicB64,String scope) throws Exception{
        String encScope=formUrlEncode(scope);
        String body="grant_type=client_credentials&scope="+encScope;
        HttpRequest req=HttpRequest.newBuilder()
                .uri(URI.create(baseUrl+"/oauth/token"))
                .header("Content-Type","application/x-www-form-urlencoded")
                .header("Authorization","Basic "+basicB64)
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        HttpResponse<String> resp=http.send(req,HttpResponse.BodyHandlers.ofString());
        if(resp.statusCode()!=200){
            System.out.println("ERROR "+resp.statusCode()+" "+resp.body());
            System.exit(0);
        }
        Object parsed=JsonParser.parse(resp.body());
        if(parsed instanceof Map){
            Map<String,Object> m=(Map<String,Object>)parsed;
            return (String)m.get("access_token");
        }
        return "";
    }
}

import java.io.*;
import java.math.BigInteger;
import java.net.URI;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

public class Main {

    static String formUrlEncode(String s) {
        byte[] b = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte by : b) {
            int ub = by & 0xFF;
            if ((ub >= 0x30 && ub <= 0x39) || (ub >= 0x41 && ub <= 0x5A) || (ub >= 0x61 && ub <= 0x7A)
                    || ub == 0x2D || ub == 0x2E || ub == 0x5F || ub == 0x2A) {
                sb.append((char) ub);
            } else if (ub == 0x20) {
                sb.append('+');
            } else {
                sb.append(String.format("%%%02X", ub));
            }
        }
        return sb.toString();
    }

    static BigInteger amountToCents(String s) {
        if (s == null) return BigInteger.ZERO;
        int sign = 1;
        if (s.startsWith("-")) {
            sign = -1;
            s = s.substring(1);
        }
        if (s.contains(".")) {
            String[] parts = s.split("\\.", 2);
            BigInteger intPart = new BigInteger(parts[0].isEmpty() ? "0" : parts[0]);
            String frac = parts[1];
            if (frac.length() == 1) frac = frac + "0";
            else if (frac.length() > 2) frac = frac.substring(0, 2);
            else if (frac.length() == 0) frac = "00";
            BigInteger cents = intPart.multiply(BigInteger.valueOf(100)).add(new BigInteger(frac));
            return sign == -1 ? cents.negate() : cents;
        } else {
            BigInteger intPart = new BigInteger(s.isEmpty() ? "0" : s);
            return intPart.multiply(BigInteger.valueOf(100)).multiply(BigInteger.valueOf(sign));
        }
    }

    static String formatCents(BigInteger cents) {
        if (cents.signum() == 0) return "0.00";
        boolean neg = cents.signum() < 0;
        BigInteger abs = cents.abs();
        BigInteger intPart = abs.divide(BigInteger.valueOf(100));
        BigInteger frac = abs.remainder(BigInteger.valueOf(100));
        String fracStr = frac.toString();
        if (fracStr.length() == 1) fracStr = "0" + fracStr;
        return (neg ? "-" : "") + intPart.toString() + "." + fracStr;
    }

    static int compareUtf8(String a, String b) {
        byte[] ba = a.getBytes(StandardCharsets.UTF_8);
        byte[] bb = b.getBytes(StandardCharsets.UTF_8);
        int n = Math.min(ba.length, bb.length);
        for (int i = 0; i < n; i++) {
            int diff = (ba[i] & 0xFF) - (bb[i] & 0xFF);
            if (diff != 0) return diff;
        }
        return ba.length - bb.length;
    }

    /* minimal JSON parser for the needed structures */
    static class JsonParser {
        static Object parse(String s) { return new Parser(s).parseValue(); }
        static class Parser {
            char[] a; int p;
            Parser(String s){ a = s.toCharArray(); p=0; }
            void skipWs(){ while(p<a.length && Character.isWhitespace(a[p])) p++; }
            Object parseValue(){ skipWs(); if(p>=a.length) return null;
                char c=a[p];
                if(c=='{') return parseObject();
                if(c=='[') return parseArray();
                if(c=='"') return parseString();
                if(c=='t'){ p+=4; return Boolean.TRUE; }
                if(c=='f'){ p+=5; return Boolean.FALSE; }
                if(c=='n'){ p+=4; return null; }
                if(c=='-'||Character.isDigit(c)) return parseNumber();
                p++; return null;
            }
            Map<String,Object> parseObject(){
                p++;
                Map<String,Object> m=new LinkedHashMap<>();
                skipWs();
                if(p<a.length && a[p]=='}'){ p++; return m; }
                while(true){
                    skipWs();
                    String key=parseString();
                    skipWs(); p++;
                    Object val=parseValue();
                    m.put(key,val);
                    skipWs();
                    if(a[p]==','){ p++; continue; }
                    if(a[p]=='}'){ p++; break; }
                }
                return m;
            }
            List<Object> parseArray(){
                p++;
                List<Object> l=new ArrayList<>();
                skipWs();
                if(p<a.length && a[p]==']'){ p++; return l; }
                while(true){
                    Object v=parseValue();
                    l.add(v);
                    skipWs();
                    if(a[p]==','){ p++; continue; }
                    if(a[p]==']'){ p++; break; }
                }
                return l;
            }
            String parseString(){
                p++;
                StringBuilder sb=new StringBuilder();
                while(p<a.length){
                    char c=a[p++];
                    if(c=='"') break;
                    if(c=='\\'){
                        if(p>=a.length) break;
                        char e=a[p++];
                        switch(e){
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            case 'u':
                                if(p+4<=a.length){
                                    String hex=new String(a,p,4);
                                    int code=Integer.parseInt(hex,16);
                                    sb.append((char)code);
                                    p+=4;
                                }
                                break;
                        }
                    }else sb.append(c);
                }
                return sb.toString();
            }
            Number parseNumber(){
                int start=p;
                if(a[p]=='-') p++;
                while(p<a.length && Character.isDigit(a[p])) p++;
                if(p<a.length && a[p]=='.'){ p++; while(p<a.length && Character.isDigit(a[p])) p++; }
                String num=new String(a,start,p-start);
                try{ return Long.parseLong(num); }catch(Exception e){ return new BigInteger(num); }
            }
        }
    }

    static String getToken(HttpClient http, String baseUrl, String basicB64, String scope) throws Exception {
        String encScope = formUrlEncode(scope);
        String body = "grant_type=client_credentials&scope=" + encScope;
        HttpRequest req = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/oauth/token"))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .header("Authorization", "Basic " + basicB64)
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        HttpResponse<String> resp = http.send(req, HttpResponse.BodyHandlers.ofString());
        if (resp.statusCode() != 200) {
            System.out.println("ERROR " + resp.statusCode() + " " + resp.body());
            System.exit(0);
        }
        Object parsed = JsonParser.parse(resp.body());
        if (parsed instanceof Map) {
            Map<String,Object> m = (Map<String,Object>) parsed;
            return (String) m.get("access_token");
        }
        return "";
    }

