        keys.sort((a,b)->{
            String nameA = a.split("\u0000",2)[0];
            String nameB = b.split("\u0000",2)[0];
            int cmp = compareUtf8(nameA, nameB);
            if (cmp != 0) return cmp;
            String curA = a.split("\u0000",2)[1];
            String curB = b.split("\u0000",2)[1];
