        }
        System.out.println("orders " + ordersReceived + " pages " + pages + " retries " + retries + " reauth " + reauth);
    }
}

import Foundation

struct ContentBlock {
    let index: Int
    var type: String
    var thinkingText = ""
    var signature = ""
    var text = ""
    var toolId = ""
    var toolName = ""
    var inputPartial = ""
    var inputObject: [String:String]? = nil
}

func escapeForOutput(_ s: String) -> String {
    var out = ""
    for ch in s {
        switch ch {
        case "\\": out += "\\\\"
        case "\n": out += "\\n"
        case "\r": out += "\\r"
        case "\t": out += "\\t"
        default: out.append(ch)
        }
    }
    return out
}

func parseSSE(_ data: Data) -> (blocks: [ContentBlock], stopReason: String?, usageInput: Int, usageCacheRead: Int, usageOutput: Int) {
    guard let text = String(data: data, encoding: .utf8) else { return ([], nil, 0, 0, 0) }
    var lines = text.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    var eventName: String? = nil
    var dataLines: [String] = []
    var blocks: [ContentBlock] = []
    var stopReason: String? = nil
    var usageInput = 0
    var usageCacheRead = 0
    var usageOutput = 0

    func flushEvent() {
        guard let name = eventName else { return }
        let dataStr = dataLines.joined(separator: "\n")
        guard !dataStr.isEmpty, let jsonData = dataStr.data(using: .utf8) else { return }
        guard let obj = try? JSONSerialization.jsonObject(with: jsonData, options: []) as? [String:Any] else { return }
        switch name {
        case "message_start":
            if let message = obj["message"] as? [String:Any],
               let usage = message["usage"] as? [String:Any],
               let inTok = usage["input_tokens"] as? Int {
                usageInput += inTok
                if let cr = usage["cache_read_input_tokens"] as? Int { usageCacheRead += cr }
            }
        case "content_block_start":
            if let idx = obj["index"] as? Int,
               let cb = obj["content_block"] as? [String:Any],
               let t = cb["type"] as? String {
                var b = ContentBlock(index: idx, type: t)
                if t == "tool_use" {
                    b.toolId = cb["id"] as? String ?? ""
                    b.toolName = cb["name"] as? String ?? ""
                }
                if blocks.count <= idx { blocks.append(contentsOf: Array(repeating: ContentBlock(index: -1, type: ""), count: idx - blocks.count + 1)) }
                blocks[idx] = b
            }
        case "content_block_delta":
            if let idx = obj["index"] as? Int,
               let delta = obj["delta"] as? [String:Any],
               let dType = delta["type"] as? String,
               idx < blocks.count {
                var b = blocks[idx]
                switch dType {
                case "thinking_delta":
                    if let v = delta["thinking"] as? String { b.thinkingText += v }
                case "signature_delta":
                    if let v = delta["signature"] as? String { b.signature += v }
                case "text_delta":
                    if let v = delta["text"] as? String { b.text += v }
                case "input_json_delta":
                    if let v = delta["partial_json"] as? String { b.inputPartial += v }
                default: break
                }
                blocks[idx] = b
            }
        case "message_delta":
            if let delta = obj["delta"] as? [String:Any],
               let sr = delta["stop_reason"] as? String {
                stopReason = sr
            }
            if let usage = obj["usage"] as? [String:Any],
               let outTok = usage["output_tokens"] as? Int {
                usageOutput += outTok
            }
        default: break
        }
        eventName = nil
        dataLines.removeAll()
    }

    for line in lines {
        let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            flushEvent()
            continue
        }
        if trimmed.hasPrefix(":") { continue }
        if trimmed.hasPrefix("event:") {
            eventName = trimmed.dropFirst("event:".count).trimmingCharacters(in: .whitespaces)
        } else if trimmed.hasPrefix("data:") {
            var payload = trimmed.dropFirst("data:".count)
            if payload.hasPrefix(" ") { payload = payload.dropFirst() }
            dataLines.append(String(payload))
        }
    }
    flushEvent()
    return (blocks, stopReason, usageInput, usageCacheRead, usageOutput)
}

func makeRequestBody(model: String, maxTokens: Int, thinkingBudget: Int, system: String, tools: Any, messages: [[String:Any]]) -> Data {
    let body: [String:Any] = [
        "model": model,
        "max_tokens": maxTokens,
        "stream": true,
        "thinking": ["type":"enabled","budget_tokens":thinkingBudget],
        "system": system,
        "tools": tools,
        "messages": messages
    ]
    return try! JSONSerialization.data(withJSONObject: body, options: [])
}

@main
struct Main {
    static func main() async {
        let args = CommandLine.arguments
        guard args.count >= 3 else { exit(0) }
        let dataDir = args[1]
        let baseUrl = args[2]
        let reqPath = URL(fileURLWithPath: dataDir).appendingPathComponent("request.json")
        let reqData = try! Data(contentsOf: reqPath)
        guard let reqJson = try? JSONSerialization.jsonObject(with: reqData) as? [String:Any] else { exit(0) }
        let apiKey = reqJson["api_key"] as! String
        let model = reqJson["model"] as! String
        let maxTokens = reqJson["max_tokens"] as! Int
        let thinkingBudget = reqJson["thinking_budget"] as! Int
        let system = reqJson["system"] as! String
        let prompt = reqJson["prompt"] as! String
        let tools = reqJson["tools"]!

        let session = URLSession.shared
        func post(messages: [[String:Any]]) async -> (status:Int, data:Data?) {
            let url = URL(string: baseUrl + "/v1/messages")!
            var req = URLRequest(url: url)
            req.httpMethod = "POST"
            req.addValue("application/json", forHTTPHeaderField: "Content-Type")
            req.addValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
            req.addValue(apiKey, forHTTPHeaderField: "x-api-key")
            let body = makeRequestBody(model: model, maxTokens: maxTokens, thinkingBudget: thinkingBudget, system: system, tools: tools, messages: messages)
            req.httpBody = body
            req.addValue("\(body.count)", forHTTPHeaderField: "Content-Length")
            let (data, resp) = try! await session.data(for: req)
            let status = (resp as! HTTPURLResponse).statusCode
            return (status, data)
        }

        var totalInput = 0
        var totalOutput = 0
        var totalCache = 0
        var allBlocksFirst: [ContentBlock] = []
        var stopReasonFirst: String? = nil

        // request 1
        let msgs1: [[String:Any]] = [["role":"user","content":prompt]]
        let (s1, d1) = await post(messages: msgs1)
        if s1 != 200 {
            if let d = d1, let obj = try? JSONSerialization.jsonObject(with: d) as? [String:Any],
               let err = obj["error"] as? [String:Any],
               let et = err["type"] as? String,
               let em = err["message"] as? String {
                print("ERROR \(s1) \(et): \(em)")
                exit(0)
            }
        }
        let parsed1 = parseSSE(d1 ?? Data())
        allBlocksFirst = parsed1.blocks
        stopReasonFirst = parsed1.stopReason ?? ""
        totalInput += parsed1.usageInput
        totalOutput += parsed1.usageOutput
        totalCache += parsed1.usageCacheRead

        print("request 1")
        for b in allBlocksFirst {
            if b.type == "thinking" {
                print("thinking \(escapeForOutput(b.thinkingText))")
                print("signature \(escapeForOutput(b.signature))")
            } else if b.type == "text" {
                print("text \(escapeForOutput(b.text))")
            } else if b.type == "tool_use" {
                print("tool_use \(b.toolId) \(b.toolName) \(escapeForOutput(b.inputPartial))")
            }
        }
        print("stop_reason \(stopReasonFirst ?? "")")

        // run tools
        var toolResults: [(id:String, result:String, isError:Bool)] = []
        for b in allBlocksFirst where b.type == "tool_use" {
            let id = b.toolId
            let name = b.toolName
            var result = ""
            var isErr = false
            if let jsonObj = try? JSONSerialization.jsonObject(with: b.inputPartial.data(using: .utf8)!, options: []) as? [String:String] {
                switch name {
                case "measure":
                    if let txt = jsonObj["text"], let unit = jsonObj["unit"] {
                        var len = 0
                        switch unit {
                        case "code_points": len = txt.unicodeScalars.count
                        case "utf8_bytes": len = txt.utf8.count
                        case "utf16_units": len = txt.utf16.count
                        default:
                            result = "unsupported unit: \(unit)"
                            isErr = true
                            break
                        }
                        if !isErr { result = "\(len)" }
                    }
                case "reverse":
                    if let txt = jsonObj["text"] {
                        result = String(txt.reversed())
                    }
                default:
                    result = "unknown tool: \(name)"
                    isErr = true
                }
            } else {
                result = "unknown tool: \(name)"
                isErr = true
            }
            if isErr {
                print("error \(id) \(escapeForOutput(result))")
            } else {
                print("result \(id) \(escapeForOutput(result))")
            }
            toolResults.append((id, result, isErr))
        }

        // build request 2
        var assistantContent: [[String:Any]] = []
        for b in allBlocksFirst {
            if b.type == "thinking" {
                assistantContent.append(["type":"thinking","thinking":b.thinkingText,"signature":b.signature])
            } else if b.type == "text" {
                assistantContent.append(["type":"text","text":b.text])
            } else if b.type == "tool_use" {
                var dict: [String:Any] = ["type":"tool_use","id":b.toolId,"name":b.toolName]
                if let obj = try? JSONSerialization.jsonObject(with: b.inputPartial.data(using: .utf8)!, options: []) as? [String:String] {
                    dict["input"] = obj
                } else {
                    dict["input"] = [:]
                }
                assistantContent.append(dict)
            }
        }
        var toolResultBlocks: [[String:Any]] = []
        for (i, b) in allBlocksFirst.enumerated() where b.type == "tool_use" {
            let tr = toolResults[i]
            var blk: [String:Any] = ["type":"tool_result","tool_use_id":b.toolId,"content":tr.result]
            if tr.isError { blk["is_error"] = true }
            toolResultBlocks.append(blk)
        }
        let msgs2: [[String:Any]] = [
            ["role":"user","content":prompt],
            ["role":"assistant","content":assistantContent],
            ["role":"user","content":toolResultBlocks]
        ]
        let (s2, d2) = await post(messages: msgs2)
        if s2 != 200 {
            if let d = d2, let obj = try? JSONSerialization.jsonObject(with: d) as? [String:Any],
               let err = obj["error"] as? [String:Any],
               let et = err["type"] as? String,
               let em = err["message"] as? String {
                print("ERROR \(s2) \(et): \(em)")
                exit(0)
            }
        }
        let parsed2 = parseSSE(d2 ?? Data())
        totalInput += parsed2.usageInput
        totalOutput += parsed2.usageOutput
        totalCache += parsed2.usageCacheRead

        print("request 2")
        for b in parsed2.blocks {
            if b.type == "thinking" {
                print("thinking \(escapeForOutput(b.thinkingText))")
                print("signature \(escapeForOutput(b.signature))")
            } else if b.type == "text" {
                print("text \(escapeForOutput(b.text))")
            } else if b.type == "tool_use" {
                print("tool_use \(b.toolId) \(b.toolName) \(escapeForOutput(b.inputPartial))")
            }
        }
        print("stop_reason \(parsed2.stopReason ?? "")")
        print("usage input=\(totalInput) output=\(totalOutput) cache_read=\(totalCache)")
    }
}

