use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::thread::sleep;
use std::time::Duration;

#[derive(Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser {
    data: Vec<u8>,
    pos: usize,
}
impl JsonParser {
    fn new(s: &str) -> Self {
        Self { data: s.as_bytes().to_vec(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }
    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }
    fn consume(&mut self) -> Option<u8> {
        let b = self.data.get(self.pos).copied();
        if b.is_some() { self.pos += 1; }
        b
    }
    fn parse_value(&mut self) -> Option<JsonValue> {
        self.skip_ws();
        match self.peek()? {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string().map(JsonValue::String),
            b't' => { self.pos += 4; Some(JsonValue::Bool(true)) },
            b'f' => { self.pos += 5; Some(JsonValue::Bool(false)) },
            b'n' => { self.pos += 4; Some(JsonValue::Null) },
            b'-' | b'0'..=b'9' => self.parse_number(),
            _ => None,
        }
    }
    fn parse_object(&mut self) -> Option<JsonValue> {
        self.consume()?; // {
        let mut obj = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()? == b'}' { self.pos += 1; break; }
            let key = match self.parse_string() { Some(k) => k, None => return None };
            self.skip_ws();
            if self.consume()? != b':' { return None; }
            let val = self.parse_value()?;
            obj.push((key, val));
            self.skip_ws();
            match self.peek()? {
                b',' => { self.pos += 1; }
                b'}' => { self.pos += 1; break; }
                _ => return None,
            }
        }
        Some(JsonValue::Object(obj))
    }
    fn parse_array(&mut self) -> Option<JsonValue> {
        self.consume()?; // [
        let mut arr = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()? == b']' { self.pos += 1; break; }
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek()? {
                b',' => { self.pos += 1; }
                b']' => { self.pos += 1; break; }
                _ => return None,
            }
        }
        Some(JsonValue::Array(arr))
    }
    fn parse_string(&mut self) -> Option<String> {
        if self.consume()? != b'"' { return None; }
        let mut s = String::new();
        loop {
            let b = self.consume()?;
            if b == b'"' { break; }
            if b == b'\\' {
                let esc = self.consume()?;
                match esc {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0c'),
                    b'n' => s.push('\n'),
                    b'r' => s.push('\r'),
                    b't' => s.push('\t'),
                    b'u' => {
                        let mut hex = [0u8;4];
                        for i in 0..4 { hex[i]=self.consume()?; }
                        let code = u32::from_str_radix(std::str::from_utf8(&hex).ok()?,16).ok()?;
                        if (0xD800..=0xDBFF).contains(&code) {
                            // surrogate pair
                            if self.consume()? != b'\\' || self.consume()? != b'u' { /* ignore */ }
                            let mut hex2 = [0u8;4];
                            for i in 0..4 { hex2[i]=self.consume()?; }
                            let low = u32::from_str_radix(std::str::from_utf8(&hex2).ok()?,16).ok()?;
                            if (0xDC00..=0xDFFF).contains(&low) {
                                let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                if let Some(ch) = std::char::from_u32(cp) { s.push(ch); }
                            } else { s.push(std::char::from_u32(code)?); }
                        } else {
                            if let Some(ch) = std::char::from_u32(code) { s.push(ch); }
                        }
                    }
                    _ => {}
                }
            } else {
                s.push(b as char);
            }
        }
        Some(s)
    }
    fn parse_number(&mut self) -> Option<JsonValue> {
        let start = self.pos;
        while self.pos < self.data.len() {
            let b = self.data[self.pos];
            if b.is_ascii_digit() || b=='-'||b=='+'||b=='.'||b=='e'||b=='E' {
                self.pos+=1;
            } else { break; }
        }
        let num = String::from_utf8_lossy(&self.data[start..self.pos]).to_string();
        Some(JsonValue::Number(num))
    }
}

fn json_get_string(obj: &JsonValue, key: &str) -> Option<String> {
    if let JsonValue::Object(pairs) = obj {
        for (k,v) in pairs {
            if k==key {
                if let JsonValue::String(s)=v { return Some(s.clone()); }
            }
        }
    }
    None
}
fn json_get_number(obj: &JsonValue, key: &str) -> Option<i64> {
    if let JsonValue::Object(pairs) = obj {
        for (k,v) in pairs {
            if k==key {
                if let JsonValue::Number(s)=v { return s.parse().ok(); }
            }
        }
    }
    None
}

fn form_urlencode_part(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        if (b'A'..=b'Z').contains(&b) || (b'a'..=b'z').contains(&b) || (b'0'..=b'9').contains(&b)
            || b=='-' || b=='.' || b=='_' || b=='*' {
            out.push(b as char);
        } else if b == b' ' {
            out.push('+');
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

fn base64_encode(input: &[u8]) -> String {
    const T: &[u8;64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    let mut i=0;
    while i<input.len() {
        let b0 = input[i];
        let b1 = *input.get(i+1).unwrap_or(&0);
        let b2 = *input.get(i+2).unwrap_or(&0);
        let n = ((b0 as u32)<<16) | ((b1 as u32)<<8) | (b2 as u32);
        out.push(T[(n>>18 & 0x3F) as usize] as char);
        out.push(T[(n>>12 & 0x3F) as usize] as char);
        if i+1 < input.len() { out.push(T[(n>>6 & 0x3F) as usize] as char); } else { out.push('='); }
        if i+2 < input.len() { out.push(T[(n & 0x3F) as usize] as char); } else { out.push('='); }
        i+=3;
    }
    out
}

fn parse_base_url(url: &str) -> (String, String) {
    let without = url.strip_prefix("http://").unwrap_or(url);
    if let Some(idx)=without.find('/') {
        let host = &without[..idx];
        let path = &without[idx..];
        (host.to_string(), path.to_string())
    } else {
        (without.to_string(), "/".to_string())
    }
}

fn split_host_port(hostport: &str) -> (String, u16) {
    if let Some(colon)=hostport.rfind(':') {
        let host = &hostport[..colon];
        let port: u16 = hostport[colon+1..].parse().unwrap_or(80);
        (host.to_string(), port)
    } else {
        (hostport.to_string(), 80)
    }
}

fn send_request(host: &str, port: u16, method: &str, path: &str, headers: &[(String,String)], body: Option<&[u8]>) -> Result<(u16, HashMap<String,String>, Vec<u8>), String> {
    let addr = (host, port);
    let mut stream = TcpStream::connect(addr).map_err(|e| e.to_string())?;
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, hostport(host,port));
    for (k,v) in headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    req.push_str("Connection: close\r\n");
    req.push_str("\r\n");
    stream.write_all(req.as_bytes()).map_err(|e| e.to_string())?;
    if let Some(b)=body { stream.write_all(b).map_err(|e| e.to_string())?; }
    stream.flush().map_err(|e| e.to_string())?;
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).map_err(|e| e.to_string())?;
    // parse status line
    let resp_str = String::from_utf8_lossy(&resp);
    let mut lines = resp_str.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    let parts: Vec<&str> = status_line.split(' ').collect();
    let status = parts.get(1).and_then(|s| s.parse::<u16>().ok()).unwrap_or(0);
    let mut headers_map = HashMap::new();
    for line in lines {
        if line.is_empty() { break; }
        if let Some(col)=line.find(':') {
            let k = line[..col].trim().to_string();
            let v = line[col+1..].trim().to_string();
            headers_map.insert(k.to_lowercase(), v);
        }
    }
    // body
    let header_end = resp_str.find("\r\n\r\n").map(|i| i+4).unwrap_or(0);
    let body_bytes = if header_end < resp.len() { &resp[header_end..] } else { &[] };
    let body = if let Some(te)=headers_map.get("transfer-encoding") {
        if te.to_lowercase().contains("chunked") {
            parse_chunked(body_bytes)
        } else { body_bytes.to_vec() }
    } else {
        if let Some(cl)=headers_map.get("content-length") {
            if let Ok(n)=cl.parse::<usize>() { body_bytes[..n.min(body_bytes.len())].to_vec() } else { body_bytes.to_vec() }
        } else { body_bytes.to_vec() }
    };
    Ok((status, headers_map, body))
}
fn hostport(host:&str, port:u16)->String { format!("{}:{}", host, port) }
fn parse_chunked(data:&[u8])->Vec<u8> {
    let mut out=Vec::new();
    let mut pos=0;
    while pos<data.len() {
        let crlf = data[pos..].windows(2).position(|w| w==[b'\r',b'\n']).unwrap_or(0);
        let size_str = String::from_utf8_lossy(&data[pos..pos+crlf]);
        let size = usize::from_str_radix(size_str.trim(),16).unwrap_or(0);
        pos+=crlf+2;
        if size==0 { break; }
        out.extend_from_slice(&data[pos..pos+size]);
        pos+=size+2;
    }
    out
}

fn fatal_error(status: u16, body: &[u8]) {
    let body_str = String::from_utf8_lossy(body);
    println!("ERROR {} {}", status, body_str);
    std::process::exit(0);
}

fn amount_to_cents(s:&str)->i128 {
    let s=s.trim();
    let (neg, rest)= if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    if let Some(dot)=rest.find('.') {
        let int_part = &rest[..dot];
        let frac_part = &rest[dot+1..];
        let int_val: i128 = int_part.parse().unwrap_or(0);
        let frac_val: i128 = match frac_part.len() {
            0 => 0,
            1 => frac_part.parse::<i128>().unwrap_or(0)*10,
            _ => frac_part.parse::<i128>().unwrap_or(0),
        };
        let total = int_val*100 + frac_val;
        if neg { -total } else { total }
    } else {
        let int_val: i128 = rest.parse().unwrap_or(0);
        if neg { -int_val*100 } else { int_val*100 }
    }
}

fn format_cents(c:i128)->String {
    let neg = c<0;
    let abs = c.abs();
    let dollars = abs/100;
    let cents = abs%100;
    if neg { format!("- {}.{:02}", dollars, cents) } else { format!("{}.{:02}", dollars, cents) }
}

fn main() {
    let args: Vec<String>=env::args().collect();
    if args.len()!=3 { return; }
    let data_dir=args[1].clone();
    let base_url=args[2].clone();

    let client_path = format!("{}/client.json", data_dir);
    let client_content = fs::read_to_string(&client_path).expect("read client");
    let mut parser = JsonParser::new(&client_content);
    let client_val = parser.parse_value().expect("parse client");
    let client_id = json_get_string(&client_val,"client_id").expect("client_id");
    let client_secret = json_get_string(&client_val,"client_secret").expect("client_secret");
    let scope = json_get_string(&client_val,"scope").expect("scope");
    let page_size = json_get_number(&client_val,"page_size").expect("page_size") as usize;

    let (hostport_str, base_path)=parse_base_url(&base_url);
    let (host, port)=split_host_port(&hostport_str);

    let enc_id = form_urlencode_part(&client_id);
    let enc_secret = form_urlencode_part(&client_secret);
    let basic_raw = format!("{}:{}", enc_id, enc_secret);
    let basic_b64 = base64_encode(basic_raw.as_bytes());

    let scope_enc = form_urlencode_part(&scope);
    let token_body = format!("grant_type=client_credentials&scope={}", scope_enc);
    let token_path = format!("{}/oauth/token", base_path);
    let token_headers = vec![
        ("Content-Type".to_string(),"application/x-www-form-urlencoded".to_string()),
        ("Authorization".to_string(), format!("Basic {}", basic_b64)),
    ];
    let (status,_,body)=send_request(&host,port,"POST",&token_path,&token_headers,Some(token_body.as_bytes())).expect("token request");
    if status!=200 { fatal_error(status,&body); }
    let mut parser = JsonParser::new(&String::from_utf8_lossy(&body));
    let token_val = parser.parse_value().expect("parse token");
    let access_token = json_get_string(&token_val,"access_token").expect("access_token");

    let mut token_fetch_count=1;
    let mut just_refreshed=false;
    let mut current_cursor: Option<String>=None;
    let mut pages=0usize;
    let mut retries=0usize;
    let mut reauth=0usize;
    let mut orders_received=0usize;
    let mut sum_map: HashMap<(String,String), i128>=HashMap::new();
    let mut status_counts: HashMap<String, usize>=HashMap::new();

    loop {
        let mut path = format!("{}/orders?limit={}", base_path, page_size);
        if let Some(ref cur)=current_cursor {
            // percent encode cursor
            let enc_cur = cur.bytes().map(|b| match b {
                b'+'=>"%2B".to_string(),
                b'/'=>"%2F",
                b'='=>"%3D",
                _ if b.is_ascii_alphanumeric() || b=='-'||b=='.'||b=='_'||b=='~'=> (b as char).to_string(),
                _=>format!("%{:02X}",b),
            }).collect::<String>();
            path.push_str(&format!("&cursor={}", enc_cur));
        }
        let auth_header = format!("Bearer {}", access_token);
        let headers = vec![
            ("Authorization".to_string(), auth_header),
        ];
        let (status, headers_map, body)=match send_request(&host,port,"GET",&path,&headers,None) {
            Ok(r)=>r,
            Err(_)=> { fatal_error(0,&[]); unreachable!() }
        };
        if status==200 {
            pages+=1;
            just_refreshed=false;
            let body_str = String::from_utf8_lossy(&body);
            let mut parser = JsonParser::new(&body_str);
            let val = parser.parse_value().expect("parse orders");
            // next_cursor
            let next_cursor_opt = if let JsonValue::Object(pairs)=&val {
                for (k,v) in pairs {
                    if k=="next_cursor" {
                        match v {
                            JsonValue::String(s)=> Some(s.clone()),
                            JsonValue::Null=> None,
                            _=>None,
                        }
                    }
                }
                None
            } else { None };
            // extract data
            if let JsonValue::Object(pairs)=val {
                for (k,v) in pairs {
                    if k=="data" {
                        if let JsonValue::Array(arr)=v {
                            for order in arr {
                                orders_received+=1;
                                if let JsonValue::Object(o)=order {
                                    let mut name_opt=None;
                                    let mut currency_opt=None;
                                    let mut status_opt=None;
                                    let mut amount_opt=None;
                                    for (k2,v2) in o {
                                        match k2.as_str() {
                                            "customer"=> {
                                                if let JsonValue::Object(cust)=v2 {
                                                    for (ck,cv) in cust {
                                                        if ck=="name" {
                                                            if let JsonValue::String(s)=cv { name_opt=Some(s); }
                                                        }
                                                    }
                                                }
                                            }
                                            "currency"=> {
                                                if let JsonValue::String(s)=v2 { currency_opt=Some(s); }
                                            }
                                            "status"=> {
                                                if let JsonValue::String(s)=v2 { status_opt=Some(s.clone()); }
                                                if let Some(st)=status_opt.clone() {
                                                    *status_counts.entry(st).or_insert(0)+=1;
                                                }
                                            }
                                            "amount"=> {
                                                if let JsonValue::String(s)=v2 { amount_opt=Some(s); }
                                            }
                                            _=>{}
                                        }
                                    }
                                    if let (Some(name),Some(currency),Some(status),Some(amount))=(&name_opt,&currency_opt,&status_opt,&amount_opt) {
                                        if status!="cancelled" {
                                            let cents = amount_to_cents(amount);
                                            let key=(name.clone(),currency.clone());
                                            *sum_map.entry(key).or_insert(0)+=cents;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            // check next cursor
            // we need to extract next_cursor properly
            let next_cursor = {
                if let JsonValue::Object(pairs)=val {
                    for (k,v) in pairs {
                        if k=="next_cursor" {
                            match v {
                                JsonValue::String(s)=> Some(s),
                                JsonValue::Null=> None,
                                _=>None,
                            }
                        }
                    }
                    None
                } else { None }
            };
            if next_cursor.is_none() {
                break;
            } else {
                current_cursor = next_cursor;
                continue;
            }
        } else if status==429 {
            retries+=1;
            if let Some(ra)=headers_map.get("retry-after") {
                if let Ok(secs)=ra.parse::<u64>() { sleep(Duration::from_secs(secs)); }
            }
            continue;
        } else if status==503 {
            retries+=1;
            sleep(Duration::from_millis(500));
            continue;
        } else if status==401 {
            // check WWW-Authenticate
            if just_refreshed {
                fatal_error(status,&body);
            }
            // reauth
            reauth+=1;
            token_fetch_count+=1;
            // fetch new token
            let (status_t,_,body_t)=send_request(&host,port,"POST",&token_path,&token_headers,Some(token_body.as_bytes())).expect("token refresh");
            if status_t!=200 { fatal_error(status_t,&body_t); }
            let mut parser = JsonParser::new(&String::from_utf8_lossy(&body_t));
            let token_val = parser.parse_value().expect("parse token");
            access_token = json_get_string(&token_val,"access_token").expect("access_token");
            just_refreshed=true;
            continue;
        } else {
            fatal_error(status,&body);
        }
    }

    // output totals
    let mut totals: Vec<((String,String),i128)>=sum_map.into_iter().collect();
    totals.sort_by(|a,b| {
        let (n1,c1)=&a.0;
        let (n2,c2)=&b.0;
        n1.cmp(n2).then_with(|| c1.cmp(c2))
    });
    for ((name,currency),cents) in &totals {
        println!("total {} {} {}", currency, format_cents(*cents), name);
    }
    let mut statuses: Vec<(&String, &usize)>=status_counts.iter().collect();
    statuses.sort_by(|a,b| a.0.cmp(b.0));
    for (st,cnt) in statuses {
        println!("status {} {}", st, cnt);
    }
    println!("orders {} pages {} retries {} reauth {}", orders_received, pages, retries, reauth);
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::thread::sleep;
use std::time::Duration;

#[derive(Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    s: &'a str,
    pos: usize,
}
impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self { Self { s, pos: 0 } }
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            let c = self.s.as_bytes()[self.pos] as char;
            if c.is_ascii_whitespace() { self.pos += 1; } else { break; }
        }
    }
    fn peek(&self) -> Option<char> {
        self.s[self.pos..].chars().next()
    }
    fn next_char(&mut self) -> Option<char> {
        let ch = self.peek()?;
        self.pos += ch.len_utf8();
        Some(ch)
    }
    fn parse_value(&mut self) -> Option<JsonValue> {
        self.skip_ws();
        match self.peek()? {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(JsonValue::String),
            't' => { self.pos += 4; Some(JsonValue::Bool(true)) },
            'f' => { self.pos += 5; Some(JsonValue::Bool(false)) },
            'n' => { self.pos += 4; Some(JsonValue::Null) },
            '-' | '0'..='9' => self.parse_number(),
            _ => None,
        }
    }
    fn parse_object(&mut self) -> Option<JsonValue> {
        self.next_char()?; // {
        let mut obj = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()? == '}' { self.pos += 1; break; }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.next_char()? != ':' { return None; }
            let val = self.parse_value()?;
            obj.push((key, val));
            self.skip_ws();
            match self.peek()? {
                ',' => { self.pos += 1; }
                '}' => { self.pos += 1; break; }
                _ => return None,
            }
        }
        Some(JsonValue::Object(obj))
    }
    fn parse_array(&mut self) -> Option<JsonValue> {
        self.next_char()?; // [
        let mut arr = Vec::new();
        loop {
            self.skip_ws();
            if self.peek()? == ']' { self.pos += 1; break; }
            arr.push(self.parse_value()?);
            self.skip_ws();
            match self.peek()? {
                ',' => { self.pos += 1; }
                ']' => { self.pos += 1; break; }
                _ => return None,
            }
        }
        Some(JsonValue::Array(arr))
    }
    fn parse_string(&mut self) -> Option<String> {
        if self.next_char()? != '"' { return None; }
        let mut out = String::new();
        loop {
            let ch = self.next_char()?;
            if ch == '"' { break; }
            if ch == '\\' {
                let esc = self.next_char()?;
                match esc {
                    '"' => out.push('"'),
                    '\\' => out.push('\\'),
                    '/' => out.push('/'),
                    'b' => out.push('\x08'),
                    'f' => out.push('\x0c'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    't' => out.push('\t'),
                    'u' => {
                        let hex: String = (0..4).filter_map(|_| self.next_char()).collect();
                        let code = u32::from_str_radix(&hex, 16).ok()?;
                        if (0xD800..=0xDBFF).contains(&code) {
                            // surrogate pair
                            if self.next_char()? == '\\' && self.next_char()? == 'u' {
                                let hex2: String = (0..4).filter_map(|_| self.next_char()).collect();
                                let low = u32::from_str_radix(&hex2, 16).ok()?;
                                if (0xDC00..=0xDFFF).contains(&low) {
                                    let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                    if let Some(ch) = std::char::from_u32(cp) { out.push(ch); }
                                    continue;
                                }
                            }
                        }
                        if let Some(ch) = std::char::from_u32(code) { out.push(ch); }
                    }
                    _ => {}
                }
            } else {
                out.push(ch);
            }
        }
        Some(out)
    }
    fn parse_number(&mut self) -> Option<JsonValue> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || "-+eE.".contains(c) { self.pos += c.len_utf8(); } else { break; }
        }
        let num = &self.s[start..self.pos];
        Some(JsonValue::Number(num.to_string()))
    }
}

fn json_get(obj: &JsonValue, key: &str) -> Option<&JsonValue> {
    if let JsonValue::Object(pairs) = obj {
        for (k, v) in pairs { if k == key { return Some(v); } }
    }
    None
}

fn form_urlencode_part(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        if (b'A'..=b'Z').contains(&b) || (b'a'..=b'z').contains(&b) || (b'0'..=b'9').contains(&b)
            || b == b'-' || b == b'.' || b == b'_' || b == b'*' {
            out.push(b as char);
        } else if b == b' ' {
            out.push('+');
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

fn base64_encode(input: &[u8]) -> String {
    const T: &[u8;64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    let mut i = 0;
    while i < input.len() {
        let b0 = input[i];
        let b1 = *input.get(i+1).unwrap_or(&0);
        let b2 = *input.get(i+2).unwrap_or(&0);
        let n = ((b0 as u32) << 16) | ((b1 as u32) << 8) | (b2 as u32);
        out.push(T[(n >> 18 & 0x3F) as usize] as char);
        out.push(T[(n >> 12 & 0x3F) as usize] as char);
        if i + 1 < input.len() { out.push(T[(n >> 6 & 0x3F) as usize] as char); } else { out.push('='); }
        if i + 2 < input.len() { out.push(T[(n & 0x3F) as usize] as char); } else { out.push('='); }
        i += 3;
    }
    out
}

fn parse_base_url(url: &str) -> (String, String) {
    let without = url.strip_prefix("http://").unwrap_or(url);
    if let Some(idx) = without.find('/') {
        (without[..idx].to_string(), without[idx..].to_string())
    } else {
        (without.to_string(), "/".to_string())
    }
}
fn split_host_port(s: &str) -> (String, u16) {
    if let Some(colon) = s.rfind(':') {
        let host = &s[..colon];
        let port = s[colon+1..].parse().unwrap_or(80);
        (host.to_string(), port)
    } else { (s.to_string(), 80) }
}
fn hostport(host: &str, port: u16) -> String { format!("{}:{}", host, port) }

fn send_request(host: &str, port: u16, method: &str, path: &str, headers: &[(String,String)], body: Option<&[u8]>) -> Result<(u16, HashMap<String,String>, Vec<u8>), String> {
    let addr = (host, port);
    let mut stream = TcpStream::connect(addr).map_err(|e| e.to_string())?;
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, hostport(host,port));
    for (k,v) in headers { req.push_str(&format!("{}: {}\r\n", k, v)); }
    req.push_str("Connection: close\r\n\r\n");
    stream.write_all(req.as_bytes()).map_err(|e| e.to_string())?;
    if let Some(b) = body { stream.write_all(b).map_err(|e| e.to_string())?; }
    stream.flush().map_err(|e| e.to_string())?;
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).map_err(|e| e.to_string())?;
    let resp_str = String::from_utf8_lossy(&resp);
    let mut lines = resp_str.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    let status = status_line.split(' ').nth(1).and_then(|s| s.parse::<u16>().ok()).unwrap_or(0);
    let mut headers_map = HashMap::new();
    for line in lines {
        if line.is_empty() { break; }
        if let Some(col) = line.find(':') {
            let k = line[..col].trim().to_string();
            let v = line[col+1..].trim().to_string();
            headers_map.insert(k.to_lowercase(), v);
        }
    }
    let header_end = resp_str.find("\r\n\r\n").map(|i| i+4).unwrap_or(0);
    let body_bytes = if header_end < resp.len() { &resp[header_end..] } else { &[] };
    let body = if let Some(te) = headers_map.get("transfer-encoding") {
        if te.to_lowercase().contains("chunked") { parse_chunked(body_bytes) } else { body_bytes.to_vec() }
    } else {
        if let Some(cl) = headers_map.get("content-length") {
            if let Ok(n) = cl.parse::<usize>() { body_bytes[..n.min(body_bytes.len())].to_vec() } else { body_bytes.to_vec() }
        } else { body_bytes.to_vec() }
    };
    Ok((status, headers_map, body))
}
fn parse_chunked(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        let end = data[pos..].windows(2).position(|w| w == [b'\r', b'\n']).unwrap_or(0);
        let size_str = String::from_utf8_lossy(&data[pos..pos+end]);
        let size_hex = size_str.trim().split(';').next().unwrap_or("");
        let size = usize::from_str_radix(size_hex, 16).unwrap_or(0);
        pos += end + 2;
        if size == 0 { break; }
        out.extend_from_slice(&data[pos..pos+size]);
        pos += size + 2;
    }
    out
}
fn fatal_error(status: u16, body: &[u8]) {
    let s = String::from_utf8_lossy(body);
    println!("ERROR {} {}", status, s);
    std::process::exit(0);
}
fn amount_to_cents(s: &str) -> i128 {
    let s = s.trim();
    let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    if let Some(dot) = rest.find('.') {
        let int_part = &rest[..dot];
        let frac = &rest[dot+1..];
        let int_val: i128 = int_part.parse().unwrap_or(0);
        let frac_val: i128 = match frac.len() {
            0 => 0,
            1 => frac.parse::<i128>().unwrap_or(0) * 10,
            _ => frac.parse::<i128>().unwrap_or(0),
        };
        let total = int_val * 100 + frac_val;
        if neg { -total } else { total }
    } else {
        let int_val: i128 = rest.parse().unwrap_or(0);
        if neg { -int_val * 100 } else { int_val * 100 }
    }
}
fn format_cents(c: i128) -> String {
    let neg = c < 0;
    let abs = c.abs();
    let dollars = abs / 100;
    let cents = abs % 100;
    if neg { format!("- {}.{:02}", dollars, cents) } else { format!("{}.{:02}", dollars, cents) }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_content = fs::read_to_string(format!("{}/client.json", data_dir)).expect("read client");
    let mut p = JsonParser::new(&client_content);
    let client_val = p.parse_value().expect("parse client");
    let client_id = json_get(&client_val, "client_id").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap();
    let client_secret = json_get(&client_val, "client_secret").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap();
    let scope = json_get(&client_val, "scope").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap();
    let page_size = json_get(&client_val, "page_size").and_then(|v| if let JsonValue::Number(s)=v {s.parse::<usize>().ok()} else {None}).unwrap();

    let (hostport_str, base_path) = parse_base_url(base_url);
    let (host, port) = split_host_port(&hostport_str);

    let basic_raw = format!("{}:{}", form_urlencode_part(&client_id), form_urlencode_part(&client_secret));
    let basic_b64 = base64_encode(basic_raw.as_bytes());
    let scope_enc = form_urlencode_part(&scope);
    let token_body = format!("grant_type=client_credentials&scope={}", scope_enc);
    let token_path = format!("{}/oauth/token", base_path);
    let token_headers = vec![
        ("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()),
        ("Authorization".to_string(), format!("Basic {}", basic_b64)),
    ];

    let (status, _, body) = send_request(&host, port, "POST", &token_path, &token_headers, Some(token_body.as_bytes())).expect("token");
    if status != 200 { fatal_error(status, &body); }
    let mut p = JsonParser::new(&String::from_utf8_lossy(&body));
    let token_val = p.parse_value().expect("parse token");
    let access_token = json_get(&token_val, "access_token").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap();

    let mut current_token = access_token;
    let mut just_refreshed = false;
    let mut current_cursor: Option<String> = None;
    let mut pages = 0usize;
    let mut retries = 0usize;
    let mut reauth = 0usize;
    let mut orders_received = 0usize;
    let mut sum_map: HashMap<(String,String), i128> = HashMap::new();
    let mut status_counts: HashMap<String, usize> = HashMap::new();

    loop {
        let mut path = format!("{}/orders?limit={}", base_path, page_size);
        if let Some(ref cur) = current_cursor {
            let enc_cur = cur.bytes().map(|b| match b {
                b'+' => "%2B".to_string(),
                b'/' => "%2F".to_string(),
                b'=' => "%3D".to_string(),
                _ => (b as char).to_string(),
            }).collect::<String>();
            path.push_str(&format!("&cursor={}", enc_cur));
        }
        let headers = vec![("Authorization".to_string(), format!("Bearer {}", current_token))];
        let (status, headers_map, body) = send_request(&host, port, "GET", &path, &headers, None).expect("orders");
        if status == 200 {
            pages += 1;
            just_refreshed = false;
            let body_str = String::from_utf8_lossy(&body);
            let mut p = JsonParser::new(&body_str);
            let val = p.parse_value().expect("parse orders");
            // process data
            if let Some(data_val) = json_get(&val, "data") {
                if let JsonValue::Array(arr) = data_val {
                    for order in arr {
                        orders_received += 1;
                        if let JsonValue::Object(o) = order {
                            let mut name_opt = None;
                            let mut currency_opt = None;
                            let mut status_opt = None;
                            let mut amount_opt = None;
                            for (k, v) in o {
                                match k.as_str() {
                                    "customer" => {
                                        if let JsonValue::Object(cust) = v {
                                            for (ck, cv) in cust {
                                                if ck == "name" {
                                                    if let JsonValue::String(s) = cv { name_opt = Some(s); }
                                                }
                                            }
                                        }
                                    }
                                    "currency" => {
                                        if let JsonValue::String(s) = v { currency_opt = Some(s); }
                                    }
                                    "status" => {
                                        if let JsonValue::String(s) = v {
                                            status_opt = Some(s.clone());
                                            *status_counts.entry(s).or_insert(0) += 1;
                                        }
                                    }
                                    "amount" => {
                                        if let JsonValue::String(s) = v { amount_opt = Some(s); }
                                    }
                                    _ => {}
                                }
                            }
                            if let (Some(name), Some(currency), Some(status), Some(amount)) = (&name_opt, &currency_opt, &status_opt, &amount_opt) {
                                if status != "cancelled" {
                                    let cents = amount_to_cents(amount);
                                    let key = (name.clone(), currency.clone());
                                    *sum_map.entry(key).or_insert(0) += cents;
                                }
                            }
                        }
                    }
                }
            }
            // next cursor
            let next_cursor = if let Some(nc) = json_get(&val, "next_cursor") {
                match nc {
                    JsonValue::String(s) => Some(s.clone()),
                    JsonValue::Null => None,
                    _ => None,
                }
            } else { None };
            if next_cursor.is_none() { break; }
            current_cursor = next_cursor;
            continue;
        } else if status == 429 {
            retries += 1;
            if let Some(ra) = headers_map.get("retry-after") {
                if let Ok(secs) = ra.parse::<u64>() { sleep(Duration::from_secs(secs)); }
            }
            continue;
        } else if status == 503 {
            retries += 1;
            sleep(Duration::from_millis(500));
            continue;
        } else if status == 401 {
            if just_refreshed { fatal_error(status, &body); }
            reauth += 1;
            let (st, _, bdy) = send_request(&host, port, "POST", &token_path, &token_headers, Some(token_body.as_bytes())).expect("token refresh");
            if st != 200 { fatal_error(st, &bdy); }
            let mut p = JsonParser::new(&String::from_utf8_lossy(&bdy));
            let tv = p.parse_value().expect("parse token");
            current_token = json_get(&tv, "access_token").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap();
            just_refreshed = true;
            continue;
        } else {
            fatal_error(status, &body);
        }
    }

    let mut totals: Vec<((String,String), i128)> = sum_map.into_iter().collect();
    totals.sort_by(|a,b| {
        let (n1,c1) = &a.0;
        let (n2,c2) = &b.0;
        n1.cmp(n2).then_with(|| c1.cmp(c2))
    });
    for ((name, currency), cents) in &totals {
        println!("total {} {} {}", currency, format_cents(*cents), name);
    }
    let mut statuses: Vec<(&String, &usize)> = status_counts.iter().collect();
    statuses.sort_by(|a,b| a.0.cmp(b.0));
    for (st, cnt) in statuses {
        println!("status {} {}", st, cnt);
    }
    println!("orders {} pages {} retries {} reauth {}", orders_received, pages, retries, reauth);
}

import * as fs from 'fs';
import * as http from 'http';
import * as https from 'https';
import { URL } from 'url';

function escapeStr(s: string): string {
  return s.replace(/\\/g, '\\\\')
          .replace(/\n/g, '\\n')
          .replace(/\r/g, '\\r')
          .replace(/\t/g, '\\t');
}

type Block = {
  index: number;
  type: 'thinking' | 'text' | 'tool_use';
  thinking?: string;
  signature?: string;
  text?: string;
  id?: string;
  name?: string;
  inputPartial?: string;
};

function parseSSE(text: string) {
  const lines = text.split(/\r?\n/);
  let currentEvent = 'message';
  let dataLines: string[] = [];
  const blocks: Block[] = [];
  let usageInput = 0;
  let usageCacheRead = 0;
  let usageOutput = 0;
  let stopReason = '';

  const flush = () => {
    if (dataLines.length === 0) return;
    const dataStr = dataLines.join('\n');
    dataLines = [];
    let obj: any;
    try { obj = JSON.parse(dataStr); } catch { return; }
    processEvent(obj);
  };

  const processEvent = (obj: any) => {
    switch (currentEvent) {
      case 'message_start': {
        usageInput = obj.message?.usage?.input_tokens ?? 0;
        usageCacheRead = obj.message?.usage?.cache_read_input_tokens ?? 0;
        break;
      }
      case 'content_block_start': {
        const idx = obj.index;
        const cb = obj.content_block;
        const b: Block = { index: idx, type: cb.type };
        if (cb.type === 'thinking') {
          b.thinking = '';
          b.signature = '';
        } else if (cb.type === 'text') {
          b.text = '';
        } else if (cb.type === 'tool_use') {
          b.id = cb.id;
          b.name = cb.name;
          b.inputPartial = '';
        }
        blocks[idx] = b;
        break;
      }
      case 'content_block_delta': {
        const idx = obj.index;
        const delta = obj.delta;
        const b = blocks[idx];
        if (!b) break;
        if (delta.type === 'thinking_delta') b.thinking = (b.thinking ?? '') + (delta.thinking ?? '');
        if (delta.type === 'signature_delta') b.signature = (b.signature ?? '') + (delta.signature ?? '');
        if (delta.type === 'text_delta') b.text = (b.text ?? '') + (delta.text ?? '');
        if (delta.type === 'input_json_delta') b.inputPartial = (b.inputPartial ?? '') + (delta.partial_json ?? '');
        break;
      }
      case 'message_delta': {
        stopReason = obj.delta?.stop_reason ?? '';
        usageOutput = obj.usage?.output_tokens ?? 0;
        break;
      }
    }
  };

  for (let raw of lines) {
    const line = raw;
    if (line === '') {
      flush();
      currentEvent = 'message';
      continue;
    }
    if (line.startsWith(':')) continue;
    if (line.startsWith('event:')) {
      currentEvent = line.slice(6).trimStart();
      continue;
    }
    if (line.startsWith('data:')) {
      let payload = line.slice(5);
      if (payload.startsWith(' ')) payload = payload.slice(1);
      dataLines.push(payload);
      continue;
    }
  }
  flush();

  return { blocks, stopReason, usageInput, usageCacheRead, usageOutput };
}

function postMessages(baseUrl: string, body: any): Promise<{
  blocks: Block[];
  stopReason: string;
  usageInput: number;
  usageCacheRead: number;
  usageOutput: number;
}> {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(baseUrl + '/v1/messages');
    const isHttps = urlObj.protocol === 'https:';
    const data = JSON.stringify(body);
    const options = {
      hostname: urlObj.hostname,
      port: Number(urlObj.port) || (isHttps ? 443 : 80),
      path: urlObj.pathname + urlObj.search,
      method: 'POST',
      headers: {
        Host: urlObj.host,
        'Content-Length': Buffer.byteLength(data),
        'x-api-key': body._apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    };
    const req = (isHttps ? https : http).request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        if (res.statusCode !== 200) {
          const txt = Buffer.concat(chunks).toString('utf8');
          try {
            const err = JSON.parse(txt);
            console.log(`ERROR ${res.statusCode} ${err.error?.type}: ${err.error?.message}`);
          } catch {}
          process.exit(0);
        }
        const text = Buffer.concat(chunks).toString('utf8');
        const parsed = parseSSE(text);
        resolve(parsed);
      });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];
  const reqJson = JSON.parse(fs.readFileSync(`${dataDir}/request.json`, 'utf8'));

  const apiKey = reqJson.api_key;
  const model = reqJson.model;
  const max_tokens = reqJson.max_tokens;
  const thinking_budget = reqJson.thinking_budget;
  const system = reqJson.system;
  const prompt = reqJson.prompt;
  const tools = reqJson.tools;

  const baseBody = {
    model,
    max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: thinking_budget },
    system,
    tools,
  };

  const firstBody = {
    ...baseBody,
    messages: [{ role: 'user', content: prompt }],
    _apiKey: apiKey,
  };

  const first = await postMessages(baseUrl, firstBody);

  const outLines: string[] = [];
  outLines.push('request 1');
  const blocks1 = first.blocks.filter(Boolean).sort((a, b) => a.index - b.index);
  for (const b of blocks1) {
    if (b.type === 'thinking') {
      outLines.push(`thinking ${escapeStr(b.thinking ?? '')}`);
      outLines.push(`signature ${escapeStr(b.signature ?? '')}`);
    } else if (b.type === 'text') {
      outLines.push(`text ${escapeStr(b.text ?? '')}`);
    } else if (b.type === 'tool_use') {
      outLines.push(`tool_use ${b.id} ${b.name} ${escapeStr(b.inputPartial ?? '')}`);
    }
  }
  outLines.push(`stop_reason ${first.stopReason}`);

  const toolUses: { id: string; name: string; inputPartial: string; inputObj: any }[] = [];
  for (const b of blocks1) {
    if (b.type === 'tool_use') {
      let inputObj = {};
      try { inputObj = JSON.parse(b.inputPartial ?? '{}'); } catch {}
      toolUses.push({ id: b.id!, name: b.name!, inputPartial: b.inputPartial ?? '', inputObj });
    }
  }

  for (const tu of toolUses) {
    let result = '';
    let isError = false;
    if (tu.name === 'measure') {
      const text = (tu.inputObj.text ?? '') as string;
      const unit = (tu.inputObj.unit ?? '') as string;
      if (unit === 'code_points') result = String([...text].length);
      else if (unit === 'utf8_bytes') result = String(Buffer.byteLength(text, 'utf8'));
      else if (unit === 'utf16_units') result = String(text.length);
      else { result = `unsupported unit: ${unit}`; isError = true; }
    } else if (tu.name === 'reverse') {
      const text = (tu.inputObj.text ?? '') as string;
      result = [...text].reverse().join('');
    } else {
      result = `unknown tool: ${tu.name}`;
      isError = true;
    }
    outLines.push(`${isError ? 'error' : 'result'} ${tu.id} ${escapeStr(result)}`);
  }

  const assistantContent = blocks1.map(b => {
    if (b.type === 'thinking') return { type: 'thinking', thinking: b.thinking ?? '', signature: b.signature ?? '' };
    if (b.type === 'text') return { type: 'text', text: b.text ?? '' };
    if (b.type === 'tool_use') {
      let inputObj = {};
      try { inputObj = JSON.parse(b.inputPartial ?? '{}'); } catch {}
      return { type: 'tool_use', id: b.id, name: b.name, input: inputObj };
    }
    return {};
  });

  const toolResults = toolUses.map((tu, idx) => {
    const resLine = outLines[outLines.length - toolUses.length + idx];
    const isError = resLine.startsWith('error ');
    const resultVal = resLine.split(' ').slice(2).join(' ');
    // we need actual result string, recompute quickly
    let result = '';
    if (tu.name === 'measure') {
      const text = (tu.inputObj.text ?? '') as string;
      const unit = (tu.inputObj.unit ?? '') as string;
      if (unit === 'code_points') result = String([...text].length);
      else if (unit === 'utf8_bytes') result = String(Buffer.byteLength(text, 'utf8'));
      else if (unit === 'utf16_units') result = String(text.length);
      else result = `unsupported unit: ${unit}`;
    } else if (tu.name === 'reverse') {
      const text = (tu.inputObj.text ?? '') as string;
      result = [...text].reverse().join('');
    } else {
      result = `unknown tool: ${tu.name}`;
    }
    const obj: any = { type: 'tool_result', tool_use_id: tu.id, content: result };
    if (isError) obj.is_error = true;
    return obj;
  });

  const secondBody = {
    ...baseBody,
    messages: [
      { role: 'user', content: prompt },
      { role: 'assistant', content: assistantContent },
      { role: 'user', content: toolResults },
    ],
    _apiKey: apiKey,
  };

  const second = await postMessages(baseUrl, secondBody);

  outLines.push('request 2');
  const blocks2 = second.blocks.filter(Boolean).sort((a, b) => a.index - b.index);
  for (const b of blocks2) {
    if (b.type === 'thinking') {
      outLines.push(`thinking ${escapeStr(b.thinking ?? '')}`);
      outLines.push(`signature ${escapeStr(b.signature ?? '')}`);
    } else if (b.type === 'text') {
      outLines.push(`text ${escapeStr(b.text ?? '')}`);
    } else if (b.type === 'tool_use') {
      outLines.push(`tool_use ${b.id} ${b.name} ${escapeStr(b.inputPartial ?? '')}`);
    }
  }
  outLines.push(`stop_reason ${second.stopReason}`);

  const inputTotal = first.usageInput + second.usageInput;
  const outputTotal = first.usageOutput + second.usageOutput;
  const cacheTotal = first.usageCacheRead + second.usageCacheRead;
  outLines.push(`usage input=${inputTotal} output=${outputTotal} cache_read=${cacheTotal}`);

  console.log(outLines.join('\n'));
}

main();

