function postMessages(baseUrl: string, bodyObj: any, apiKey: string): Promise<{
  blocks: Block[];
  stopReason: string;
  usageInput: number;
  usageCacheRead: number;
  usageOutput: number;
}> {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(baseUrl + '/v1/messages');
