          } catch {}
          process.exit(0);
        }
        const parsed = parseSSE(Buffer.concat(chunks));
        resolve(parsed);
      });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

function measureText(text: string, unit: string): { result: string; isError: boolean } {
  if (unit === 'code_points') return { result: String([...text].length), isError: false };
  if (unit === 'utf8_bytes') return { result: String(Buffer.byteLength(text, 'utf8')), isError: false };
  if (unit === 'utf16_units') return { result: String(text.length), isError: false };
  return { result: `unsupported unit: ${unit}`, isError: true };
}

function reverseText(text: string): string {
  return [...text].reverse().join('');
}

