def load_task(data_dir):
    with open(os.path.join(data_dir, "task.json"), "r", encoding="utf-8") as f:
        return json.load(f)

def load_inventory(data_dir):
    path = os.path.join(data_dir, "inventory.csv")
    inventory = {}
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return inventory
        for row in reader:
            if not row:
                continue
            if len(row) < 5:
                row += [""] * (5 - len(row))
            sku = row[0]
            name = row[1]
            try:
                price_cents = int(row[2]) if row[2] else 0
            except ValueError:
                price_cents = 0
            currency = row[3]
            try:
                stock = int(row[4]) if row[4] else 0
            except ValueError:
                stock = 0
            inventory[sku] = {
                "sku": sku,
                "name": name,
                "price_cents": price_cents,
                "currency": currency,
                "stock": stock,
            }
    return inventory

def load_rates(data_dir):
    with open(os.path.join(data_dir, "rates.json"), "r", encoding="utf-8") as f:
        data = json.load(f)
    return data.get("rates", {})

def json_compact(obj):
    s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
    # forward slash escaping is not required by the spec
    s = s.replace('\\/', '/')
    return s

