/* ---------- utils ---------- */
static int is_unreserved_form(char c){
    if (isalnum((unsigned char)c)) return 1;
    if (c=='-'||c=='.'||c=='_'||c=='*' ) return 1;
    return 0;
}
static char *form_urlencode(const char *s){
    size_t n=0;
    for(const unsigned char *p=(const unsigned char*)s;*p;p++) n+= (*p==' ') ?1: (*p=='*'||isalnum(*p)||*p=='-'||*p=='.'||*p=='_')?1:3;
    char *out=malloc(n+1);
    char *o=out;
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if (*p==' ') {*o++='+';}
        else if (is_unreserved_form(*p)) {*o++=*p;}
        else {sprintf(o,"%%%02X",*p); o+=3;}
    }
    *o=0;
    return out;
}
static char *base64_encode(const unsigned char *in,size_t len){
    static const char tbl[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    size_t outlen=4*((len+2)/3);
    char *out=malloc(outlen+1);
    size_t i=0,j=0;
    while(i<len){
        uint32_t v=0;
        int n=0;
        for(int k=0;k<3;k++){v<<=8; if(i<len){v|=in[i++]; n++;} else v|=0;}
        out[j++]=tbl[(v>>18)&0x3F];
        out[j++]=tbl[(v>>12)&0x3F];
        out[j++]= (n>1)?tbl[(v>>6)&0x3F]:'=';
        out[j++]= (n>2)?tbl[v&0x3F]:'=';
    }
    out[outlen]=0;
    return out;
}

/* ---------- JSON string unescape ---------- */
static int hexval(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return 0;}
static void utf8_encode(uint32_t cp,char *out,int *len){
    if(cp<=0x7F){out[0]=cp;*len=1;}
    else if(cp<=0x7FF){out[0]=0xC0|(cp>>6);out[1]=0x80|(cp&0x3F);*len=2;}
    else if(cp<=0xFFFF){out[0]=0xE0|(cp>>12);out[1]=0x80|((cp>>6)&0x3F);out[2]=0x80|(cp&0x3F);*len=3;}
    else {out[0]=0xF0|(cp>>18);out[1]=0x80|((cp>>12)&0x3F);out[2]=0x80|((cp>>6)&0x3F);out[3]=0x80|(cp&0x3F);*len=4;}
}
static char *json_unescape(const char *src,size_t len){
    char *out=malloc(len*4+1);
    char *o=out;
    const char *p=src;
    const char *end=src+len;
    while(p<end){
        if(*p=='\\'){
            p++;
            if(p>=end) break;
            if(*p=='"'){*o++='"';p++;}
            else if(*p=='\\'){*o++='\\';p++;}
            else if(*p=='/'){*o++='/';p++;}
            else if(*p=='b'){*o++='\b';p++;}
            else if(*p=='f'){*o++='\f';p++;}
            else if(*p=='n'){*o++='\n';p++;}
            else if(*p=='r'){*o++='\r';p++;}
            else if(*p=='t'){*o++='\t';p++;}
            else if(*p=='u'){
                int hi=0;
                for(int i=0;i<4 && p+1<end;i++){hi=hi*16+hexval(*(p+1));p++;}
                uint32_t cp=hi;
                if(cp>=0xD800 && cp<=0xDBFF && p+6<end && p[1]=='\\' && p[2]=='u'){
                    int lo=0;
                    for(int i=0;i<4 && p+3<end;i++){lo=lo*16+hexval(*(p+3));p++;}
                    cp=0x10000 + ((cp-0xD800)<<10)+(lo-0xDC00);
                }
                char tmp[4]; int l; utf8_encode(cp,tmp,&l); memcpy(o,tmp,l); o+=l; p++;
            }else{*o++=*p;p++;}
        }else{*o++=*p;p++;}
    }
    *o=0;
    return out;
}

/* ---------- HTTP ---------- */
typedef struct {int status; char *body; size_t body_len;} HttpResp;

static char *url_read_all(int sock){
    size_t cap=8192, len=0;
    char *buf=malloc(cap);
    while(1){
        if(len+4096>cap){cap*=2; buf=realloc(buf,cap);}
        ssize_t r=recv(sock,buf+len,cap-len-1,0);
        if(r<=0) break;
        len+=r;
    }
    buf[len]=0;
    return buf;
}
static HttpResp http_request(const char *host,int port,const char *path,const char *method,const char *extra_hdr,const char *body){
    struct addrinfo hints={0},*res;
    char portstr[16]; sprintf(portstr,"%d",port);
    hints.ai_family=AF_UNSPEC; hints.ai_socktype=SOCK_STREAM;
    getaddrinfo(host,portstr,&hints,&res);
    int sock=-1;
    for(struct addrinfo *a=res;a;a=a->ai_next){sock=socket(a->ai_family,a->ai_socktype,a->ai_protocol); if(sock>=0 && connect(sock,a->ai_addr,a->ai_addrlen)==0) break; if(sock>=0) close(sock); sock=-1;}
    freeaddrinfo(res);
    if(sock<0) {HttpResp r={-1,NULL,0}; return r;}
    char req[8192];
    int n=snprintf(req,sizeof req,"%s %s HTTP/1.1\r\nHost: %s:%d\r\nConnection: close\r\n",method,path,host,port);
    if(extra_hdr){n+=snprintf(req+n,sizeof req-n,"%s\r\n",extra_hdr);}
    if(body){n+=snprintf(req+n,sizeof req-n,"Content-Length: %zu\r\n\r\n",strlen(body)); send(sock,req,n,0); send(sock,body,strlen(body),0);}
    else {n+=snprintf(req+n,sizeof req-n,"\r\n"); send(sock,req,n,0);}
    char *raw=url_read_all(sock);
    close(sock);
    /* parse status */
    int status=0;
    char *eol=strstr(raw,"\r\n");
    if(eol){char *sp=strchr(raw,' '); if(sp){status=atoi(sp);}}
    /* find headers end */
    char *hdr_end=strstr(raw,"\r\n\r\n");
    char *body_ptr = hdr_end?hdr_end+4:raw+strlen(raw);
    /* check transfer-encoding */
    int chunked=0;
    if(hdr_end){
        char *h=raw;
        while(h<hdr_end){
            char *nl=strstr(h,"\r\n"); if(!nl)break;
            if(strncasecmp(h,"Transfer-Encoding:",18)==0){char *v=h+18; while(isspace(*v))v++; if(strcasestr(v,"chunked")) chunked=1;}
            h=nl+2;
        }
    }
    char *body_decoded=NULL;
    size_t body_len=0;
    if(chunked){
        /* simple chunked decode */
        const char *p=body_ptr;
        size_t outcap=8192, outlen=0;
        char *out=malloc(outcap);
        while(p && *p){
            unsigned int sz=0;
            while(isxdigit(*p)){sz=sz*16+(isdigit(*p)?*p-'0':tolower(*p)-'a'+10); p++;}
            if(*p=='\r'){p++; if(*p=='\n')p++;}
            if(sz==0) break;
            if(outlen+sz>outcap){outcap*=2; out=realloc(out,outcap);}
            memcpy(out+outlen,p,sz); outlen+=sz; p+=sz;
            if(*p=='\r'){p++; if(*p=='\n')p++;}
        }
        body_decoded=out; body_len=outlen;
    }else{
        body_decoded=strdup(body_ptr);
        body_len=strlen(body_decoded);
    }
    HttpResp r={status,body_decoded,body_len};
    free(raw);
    return r;
}

/* ---------- JSON helpers ---------- */
static char *json_find_string_value(const char *json,const char *key){
    char pat[256]; snprintf(pat,sizeof pat,"\"%s\"",key);
    char *pos=strstr(json,pat);
    if(!pos) return NULL;
    char *colon=strchr(pos,':');
    if(!colon) return NULL;
    char *q=strchr(colon,'"');
    if(!q) return NULL;
    q++;
    char *q2=q;
    while(*q2 && !(*q2=='"' && (q2==q || *(q2-1)!='\\'))){if(*q2=='\\')q2++; q2++;}
    if(*q2!='"') return NULL;
    size_t len=q2-q;
    char *raw=malloc(len+1); memcpy(raw,q,len); raw[len]=0;
    char *un=json_unescape(raw,len); free(raw);
    return un;
}
static int json_find_next_cursor(const char *json,char **out){
    char *pos=strstr(json,"\"next_cursor\"");
    if(!pos) return 0;
    char *colon=strchr(pos,':'); if(!colon) return 0;
    char *p=colon+1; while(isspace(*p))p++;
    if(strncmp(p,"null",4)==0){*out=NULL; return 1;}
    if(*p=='"'){p++; char *q=p; while(*q && !(*q=='"' && *(q-1)!='\\')) q++; size_t len=q-p; char *raw=malloc(len+1); memcpy(raw,p,len); raw[len]=0; *out=json_unescape(raw,len); free(raw); return 1;}
    return 0;
}

/* ---------- amount parsing ---------- */
static __int128 parse_amount_cents(const char *s){
    __int128 sign=1; const char *p=s; if(*p=='-'){sign=-1;p++;} __int128 intpart=0; while(isdigit(*p)){intpart=intpart*10+(*p-'0');p++;} __int128 cents=intpart*100; if(*p=='.'){p++; int frac=0; int nd=0; while(isdigit(*p) && nd<2){frac=frac*10+(*p-'0'); nd++; p++;} if(nd==1) cents+=frac*10; else if(nd==2) cents+=frac; } return sign*cents;
}
static void int128_to_str(__int128 v,char *buf){ /* for cents */ int neg=0; if(v<0){neg=1;v=-v;} __int128 intpart=v/100; __int128 frac=v%100; char tmp[64]; int i=0; if(intpart==0){tmp[i++]='0';} else {char rev[64]; int r=0; __int128 t=intpart; while(t>0){rev[r++]='0'+t%10; t/=10;} while(r--) tmp[i++]=rev[r];} tmp[i++]='.'; tmp[i++]='0'+(int)(frac/10); tmp[i++]='0'+(int)(frac%10); tmp[i]=0; if(neg){char out[128]; out[0]='-'; strcpy(out+1,tmp); strcpy(buf,out);} else strcpy(buf,tmp);}

/* ---------- data structures ---------- */
typedef struct {char *name; char *currency; __int128 sum;} Pair;
typedef struct {char *status; long long cnt;} Stat;

static Pair *pairs=NULL; size_t pair_cnt=0, pair_cap=0;
static Stat *stats=NULL; size_t stat_cnt=0, stat_cap=0;

static Pair *find_pair(const char *name,const char *cur){
    for(size_t i=0;i<pair_cnt;i++) if(strcmp(pairs[i].name,name)==0 && strcmp(pairs[i].currency,cur)==0) return &pairs[i];
    if(pair_cnt==pair_cap){pair_cap+=64; pairs=realloc(pairs,pair_cap*sizeof(Pair));}
    pairs[pair_cnt].name=strdup(name); pairs[pair_cnt].currency=strdup(cur); pairs[pair_cnt].sum=0; return &pairs[pair_cnt++];
}
static Stat *find_stat(const char *st){
    for(size_t i=0;i<stat_cnt;i++) if(strcmp(stats[i].status,st)==0) return &stats[i];
    if(stat_cnt==stat_cap){stat_cap+=64; stats=realloc(stats,stat_cap*sizeof(Stat));}
    stats[stat_cnt].status=strdup(st); stats[stat_cnt].cnt=1; return &stats[stat_cnt++];
}
static int cmp_pair(const void *a,const void *b){ int r=strcmp(((Pair*)a)->name,((Pair*)b)->name); if(r) return r; return strcmp(((Pair*)a)->currency,((Pair*)b)->currency);}
static int cmp_stat(const void *a,const void *b){ return strcmp(((Stat*)a)->status,((Stat*)b)->status);}

/* ---------- order processing ---------- */
static void process_order_object(const char *obj){
    /* find name */
    char *name=NULL,*currency=NULL,*amount=NULL,*status=NULL;
    char *cpos=strstr(obj,"\"customer\"");
    if(cpos){char *npos=strstr(cpos,"\"name\""); if(npos){char *q=strchr(npos,'"'); if(q){q=strchr(q+1,'"'); if(q){/* parse */}}}
    }
    /* simpler: search for "name":" */
    char *p=strstr(obj,"\"name\"");
    if(p){char *colon=strchr(p,':'); if(colon){char *q=strchr(colon+1,'"'); if(q){char *q2=q+1; while(*q2 && !(*q2=='"' && *(q2-1)!='\\')) q2++; size_t l=q2-q-1; char *raw=malloc(l+1); memcpy(raw,q+1,l); raw[l]=0; name=json_unescape(raw,l); free(raw);}}}
    /* currency */
    p=strstr(obj,"\"currency\"");
    if(p){char *colon=strchr(p,':'); if(colon){char *q=strchr(colon+1,'"'); if(q){char *q2=q+1; while(*q2 && !(*q2=='"' && *(q2-1)!='\\')) q2++; size_t l=q2-q-1; char *raw=malloc(l+1); memcpy(raw,q+1,l); raw[l]=0; currency=json_unescape(raw,l); free(raw);}}}
    /* amount */
    p=strstr(obj,"\"amount\"");
    if(p){char *colon=strchr(p,':'); if(colon){char *q=strchr(colon+1,'"'); if(q){char *q2=q+1; while(*q2 && !(*q2=='"' && *(q2-1)!='\\')) q2++; size_t l=q2-q-1; char *raw=malloc(l+1); memcpy(raw,q+1,l); raw[l]=0; amount=raw;}}}
    /* status */
    p=strstr(obj,"\"status\"");
    if(p){char *colon=strchr(p,':'); if(colon){char *q=strchr(colon+1,'"'); if(q){char *q2=q+1; while(*q2 && !(*q2=='"' && *(q2-1)!='\\')) q2++; size_t l=q2-q-1; char *raw=malloc(l+1); memcpy(raw,q+1,l); raw[l]=0; status=json_unescape(raw,l);}}}
    if(status){Stat *st=find_stat(status); st->cnt++; if(strcmp(status,"cancelled")!=0){ if(name && currency && amount){ Pair *pr=find_pair(name,currency); __int128 c=parse_amount_cents(amount); pr->sum+=c; } } }
    free(name); free(currency); free(amount); free(status);
}

/* parse data array from json */
static void parse_page_data(const char *json,long long *orders_inc){
    char *data_pos=strstr(json,"\"data\"");
    if(!data_pos) return;
    char *bracket=strchr(data_pos,'[');
    if(!bracket) return;
    const char *p=bracket+1;
    while(*p){
        while(*p && (isspace(*p)||*p==',')) p++;
        if(*p==']' || *p==0) break;
        if(*p=='{'){
            const char *start=p;
            int depth=0; int in_str=0; int esc=0;
            const char *q=p;
            while(*q){
                if(in_str){ if(esc){esc=0;} else if(*q=='\\') esc=1; else if(*q=='"') in_str=0; }
                else { if(*q=='"') in_str=1; else if(*q=='{') depth++; else if(*q=='}'){depth--; if(depth==0){q++; break;}}}
                q++;
            }
            size_t len=q-start;
            char *obj=malloc(len+1); memcpy(obj,start,len); obj[len]=0;
            process_order_object(obj);
            (*orders_inc)++;
            free(obj);
            p=q;
        }else p++;
    }
}

/* ---------- main ---------- */
int main(int argc,char **argv){
    if(argc!=3){fprintf(stderr,"usage\n"); return 0;}
    const char *data_dir=argv[1];
    const char *base_url=argv[2];
    char client_path[1024]; snprintf(client_path,sizeof client_path,"%s/client.json",data_dir);
    FILE *f=fopen(client_path,"r"); if(!f){fprintf(stderr,"no client\n"); return 0;}
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET); char *buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    char *client_id=json_find_string_value(buf,"client_id");
    char *client_secret=json_find_string_value(buf,"client_secret");
    char *scope=json_find_string_value(buf,"scope");
    char *ps=strstr(buf,"\"page_size\""); int page_size=6; if(ps){ps=strchr(ps,':'); if(ps){page_size=atoi(ps+1);}}
    free(buf);
    /* encode for Basic */
    char *enc_id=form_urlencode(client_id); char *enc_sec=form_urlencode(client_secret);
    char tmp[1024]; snprintf(tmp,sizeof tmp,"%s:%s",enc_id,enc_sec); unsigned char *b64_in=(unsigned char*)tmp; char *b64=base64_encode(b64_in,strlen(tmp));
    char *scope_enc=form_urlencode(scope);
    char body[1024]; snprintf(body,sizeof body,"grant_type=client_credentials&scope=%s",scope_enc);
    /* parse base url */
    char *url_dup=strdup(base_url);
    char *p=strstr(url_dup,"://"); if(p) p+=3; else p=url_dup;
    char *slash=strchr(p,'/'); char hostport[256]; char pathpref[256];
    if(slash){*slash=0; strncpy(hostport,p,sizeof hostport); strncpy(pathpref,slash,sizeof pathpref);} else {strcpy(hostport,p); strcpy(pathpref,"/");}
    char *colon=strchr(hostport,':'); int port=80; char host[256]; if(colon){*colon=0; strncpy(host,hostport,sizeof host); port=atoi(colon+1);} else {strcpy(host,hostport);}
    char token_path[512]; snprintf(token_path,sizeof token_path,"%s/oauth/token",pathpref);
    char token_hdr[1024]; snprintf(token_hdr,sizeof token_hdr,"Content-Type: application/x-www-form-urlencoded\r\nAuthorization: Basic %s",b64);
    HttpResp tr=http_request(host,port,token_path,"POST",token_hdr,body);
    if(tr.status!=200){printf("ERROR %d %s\n",tr.status,tr.body); return 0;}
    char *access_token=json_find_string_value(tr.body,"access_token");
    free(tr.body);
    int reauth=0, retries=0, pages=0; long long orders_total=0; int token_fresh=1;
    char *cursor=NULL;
    while(1){
        char qpath[1024];
        if(cursor){ char *enc_cur=malloc(strlen(cursor)*3+1); char *o=enc_cur; for(const char *s=cursor;*s;s++){ if(*s=='+') {*o++='%';*o++='2';*o++='B';} else if(*s=='/'){*o++='%';*o++='2';*o++='F';} else if(*s=='='){*o++='%';*o++='3';*o++='D';} else *o++=*s;} *o=0; snprintf(qpath,sizeof qpath,"%s/orders?limit=%d&cursor=%s",pathpref,page_size,enc_cur); free(enc_cur);}
        else snprintf(qpath,sizeof qpath,"%s/orders?limit=%d",pathpref,page_size);
        char auth_hdr[512]; snprintf(auth_hdr,sizeof auth_hdr,"Authorization: Bearer %s",access_token);
        HttpResp rr=http_request(host,port,qpath,"GET",auth_hdr,NULL);
        if(rr.status==200){
            pages++;
            long long inc=0;
            parse_page_data(rr.body,&inc);
            orders_total+=inc;
            char *next=NULL;
            json_find_next_cursor(rr.body,&next);
            free(rr.body);
            if(next){ free(cursor); cursor=next; } else { free(cursor); cursor=NULL; break; }
            token_fresh=0;
        }else if(rr.status==429){
            retries++;
            /* parse Retry-After */
            int wait=1;
            free(rr.body);
            sleep(wait);
        }else if(rr.status==503){
            retries++;
            free(rr.body);
            usleep(500000);
        }else if(rr.status==401){
            free(rr.body);
            if(token_fresh){ printf("ERROR %d \n",401); return 0; }
            /* reauth */
            reauth++;
            token_fresh=1;
            /* get new token */
            HttpResp tr2=http_request(host,port,token_path,"POST",token_hdr,body);
            if(tr2.status!=200){printf("ERROR %d %s\n",tr2.status,tr2.body); return 0;}
            char *new_tok=json_find_string_value(tr2.body,"access_token");
            free(access_token); access_token=new_tok;
            free(tr2.body);
            /* retry same request */
        }else{
            printf("ERROR %d %s\n",rr.status,rr.body);
            free(rr.body);
            return 0;
        }
    }
    /* output */
    qsort(pairs,pair_cnt,sizeof(Pair),cmp_pair);
    qsort(stats,stat_cnt,sizeof(Stat),cmp_stat);
    for(size_t i=0;i<pair_cnt;i++){
        char amt[64]; int128_to_str(pairs[i].sum,amt);
        printf("total %s %s %s\n",pairs[i].currency,amt,pairs[i].name);
    }
    for(size_t i=0;i<stat_cnt;i++) printf("status %s %lld\n",stats[i].status,stats[i].cnt);
    printf("orders %lld pages %d retries %d reauth %d\n",orders_total,pages,retries,reauth);
    return 0;
}

