public class Main {
    static class ToolCall {
        String id;
        String name;
        String argumentsRaw; // raw escaped string as in JSON
        ToolCall(String id,String name,String argumentsRaw){this.id=id;this.name=name;this.argumentsRaw=argumentsRaw;}
    }
    static class Message {
        String role;
        String content; // null allowed
        List<ToolCall> toolCalls;
        Message(String role,String content){this.role=role;this.content=content;this.toolCalls=null;}
    }

    static String jsonEscape(String s){
        StringBuilder sb=new StringBuilder();
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            switch(c){
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if(c<0x20){
                        sb.append(String.format("\\u%04x",(int)c));
                    }else{
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    static String unescapeJson(String s){
        StringBuilder sb=new StringBuilder();
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(c=='\\' && i+1<s.length()){
                char n=s.charAt(i+1);
                switch(n){
                    case '"': sb.append('"'); i++; break;
                    case '\\': sb.append('\\'); i++; break;
                    case '/': sb.append('/'); i++; break;
                    case 'b': sb.append('\b'); i++; break;
                    case 'f': sb.append('\f'); i++; break;
                    case 'n': sb.append('\n'); i++; break;
                    case 'r': sb.append('\r'); i++; break;
                    case 't': sb.append('\t'); i++; break;
                    case 'u':
                        if(i+5<s.length()){
                            String hex=s.substring(i+2,i+6);
                            int code=Integer.parseInt(hex,16);
                            sb.append((char)code);
                            i+=5;
                        }
                        break;
                    default: sb.append(n); i++; break;
                }
            }else sb.append(c);
        }
        return sb.toString();
    }

    static Map<String,String> parseTaskJson(String json){
        Map<String,String> m=new HashMap<>();
        Matcher mm=Pattern.compile("\"api_key\"\\s*:\\s*\"([^\"]*)\"").matcher(json);
        if(mm.find()) m.put("api_key",unescapeJson(mm.group(1)));
        mm=Pattern.compile("\"model\"\\s*:\\s*\"([^\"]*)\"").matcher(json);
        if(mm.find()) m.put("model",unescapeJson(mm.group(1)));
        mm=Pattern.compile("\"system\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"").matcher(json);
        if(mm.find()) m.put("system",unescapeJson(mm.group(1)));
        mm=Pattern.compile("\"user\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"").matcher(json);
        if(mm.find()) m.put("user",unescapeJson(mm.group(1)));
        // tools raw
        int idx=json.indexOf("\"tools\"");
        if(idx!=-1){
            int start=json.indexOf('[',idx);
            int end=findMatchingBracket(json,start);
            if(start!=-1 && end!=-1) m.put("tools",json.substring(start,end+1));
        }
        return m;
    }

    static int findMatchingBracket(String s,int start){
        int depth=0;
        for(int i=start;i<s.length();i++){
            char c=s.charAt(i);
            if(c=='[') depth++;
            else if(c==']'){
                depth--;
                if(depth==0) return i;
            }
        }
        return -1;
