    static int findMatch(String s,int start,char open,char close){
        int depth=0;
        for(int i=start;i<s.length();i++){
            char c=s.charAt(i);
            if(c==open) depth++;
            else if(c==close){depth--; if(depth==0) return i;}
        }
        return -1;
