                        Matcher sm=Pattern.compile("\"sku\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"").matcher(argJson);
                        String sku="";
                        if(sm.find()) sku=unescapeJson(sm.group(1));
                        InventoryRow row=inventory.get(sku);
                        if(row==null) result="{\"error\":\"unknown sku: "+jsonEscape(sku)+"\"}";
                        else result="{\"sku\":\""+jsonEscape(row.sku)+"\",\"name\":\""+jsonEscape(row.name)+"\",\"price_cents\":"+row.price+",\"currency\":\""+jsonEscape(row.currency)+"\",\"stock\":"+row.stock+"}";
                    }else if("convert_currency".equals(tc.name)){
                        String argJson=unescapeJson(tc.argumentsRaw);
                        Matcher am=Pattern.compile("\"amount_cents\"\\s*:\\s*(\\d+)").matcher(argJson);
                        Matcher fm1=Pattern.compile("\"from\"\\s*:\\s*\"([^\"]+)\"").matcher(argJson);
                        Matcher tm=Pattern.compile("\"to\"\\s*:\\s*\"([^\"]+)\"").matcher(argJson);
                        long amount=0; String from="",to="";
                        if(am.find()) amount=Long.parseLong(am.group(1));
                        if(fm1.find()) from=fm1.group(1);
                        if(tm.find()) to=tm.group(1);
                        long rFrom=rates.map.getOrDefault(from,1000000L);
                        long rTo=rates.map.getOrDefault(to,1000000L);
                        long converted=(2*amount*rTo + rFrom)/(2*rFrom);
                        result="{\"amount_cents\":"+converted+",\"currency\":\""+jsonEscape(to)+"\"}";
                    }else{
                        result="{\"error\":\"unknown tool: "+jsonEscape(tc.name)+"\"}";
                    }
                    out.add("RESULT "+tc.id+" "+result);
                    ConvMessage toolMsg=new ConvMessage("tool",result);
                    toolMsg.toolCallId=tc.id;
                    conv.add(toolMsg);
                }
            }else if("stop".equals(finish)){
                String finalContent=content!=null?content:"";
                out.add("FINAL "+finalContent);
                break;
            }else{
                break;
            }
        }
        out.add("USAGE prompt="+sumPrompt+" completion="+sumComp+" total="+sumTotal+" requests="+requests);
        for(String l:out) System.out.println(l);
    }
}

import * as fs from 'fs';
import * as path from 'path';

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];
const DIGIT_MAP = [
  ['1','2','3','A'],
  ['4','5','6','B'],
  ['7','8','9','C'],
  ['*','0','#','D'],
];

function readU16LE(buf: Buffer, off: number) { return buf.readUInt16LE(off); }
function readU32LE(buf: Buffer, off: number) { return buf.readUInt32LE(off); }

function parseWav(filePath: string, name: string) {
  const buf = fs.readFileSync(filePath);
  if (buf.length < 12) return { unsupported: true };
  if (buf.toString('ascii',0,4) !== 'RIFF') return { unsupported: true };
  if (buf.toString('ascii',8,12) !== 'WAVE') return { unsupported: true };

  let fmtTag = -1, channels = 0, sampleRate = 0, bitsPerSample = 0;
  let dataOffset = -1, dataSize = 0;

  let off = 12;
  while (off + 8 <= buf.length) {
    const id = buf.toString('ascii', off, off+4);
    const size = readU32LE(buf, off+4);
    const bodyOff = off + 8;
    if (id === 'fmt ') {
      if (size >= 16) {
        const tag = readU16LE(buf, bodyOff);
        channels = readU16LE(buf, bodyOff+2);
        sampleRate = readU32LE(buf, bodyOff+4);
        bitsPerSample = readU16LE(buf, bodyOff+14);
        let effectiveTag = tag;
        if (tag === 0xFFFE && bodyOff + 26 <= buf.length) {
          effectiveTag = readU16LE(buf, bodyOff + 24);
        }
        fmtTag = effectiveTag;
      }
    } else if (id === 'data') {
      dataOffset = bodyOff;
      dataSize = size;
    }
    off = bodyOff + size + (size & 1 ? 1 : 0);
  }

  if (fmtTag !== 1 || bitsPerSample !== 16) {
    return { unsupported: true };
  }
  if (channels !== 1 && channels !== 2) return { unsupported: true };
  if (sampleRate !== 8000 && sampleRate !== 16000) return { unsupported: true };
  if (dataOffset < 0) return { unsupported: true };

  const frames = Math.floor(dataSize / (2 * channels));
  const N = sampleRate / 50;
  const blocks = Math.floor(frames / N);
  if (blocks <= 0) {
    // still output header with zero blocks
  }

  // extract left channel samples
  const samples: number[] = [];
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  for (let f = 0; f < frames; f++) {
    const idx = dataOffset + f * 2 * channels;
    const s = view.getInt16(idx, true);
    samples.push(s);
  }

  const labels: (string | null)[] = new Array(blocks).fill(null);
  const energyThreshold = 1_000_000 * N;

  for (let b = 0; b < blocks; b++) {
    const start = b * N;
    let E = 0;
    for (let i = 0; i < N; i++) {
      const x = samples[start + i];
      E += x * x;
    }
    if (E < energyThreshold) {
      labels[b] = null;
      continue;
    }
    let bestLowIdx = 0;
    let bestLowR = -1;
    let bestHighIdx = 0;
    let bestHighR = -1;

    for (let i = 0; i < LOW_FREQS.length; i++) {
      const f = LOW_FREQS[i];
      const c = 2 * Math.cos(2 * Math.PI * f / sampleRate);
      let s1 = 0, s2 = 0;
      for (let n = 0; n < N; n++) {
        const x = samples[start + n];
        const s = x + c * s1 - s2;
        s2 = s1;
        s1 = s;
      }
      const P = s1 * s1 + s2 * s2 - c * s1 * s2;
      const r = 2 * P / (N * E);
      if (r > bestLowR) { bestLowR = r; bestLowIdx = i; }
    }
    for (let i = 0; i < HIGH_FREQS.length; i++) {
      const f = HIGH_FREQS[i];
      const c = 2 * Math.cos(2 * Math.PI * f / sampleRate);
      let s1 = 0, s2 = 0;
      for (let n = 0; n < N; n++) {
        const x = samples[start + n];
        const s = x + c * s1 - s2;
        s2 = s1;
        s1 = s;
      }
      const P = s1 * s1 + s2 * s2 - c * s1 * s2;
      const r = 2 * P / (N * E);
      if (r > bestHighR) { bestHighR = r; bestHighIdx = i; }
    }
    if (bestLowR >= 0.1 && bestHighR >= 0.1 && bestLowR + bestHighR >= 0.6) {
      labels[b] = DIGIT_MAP[bestLowIdx][bestHighIdx];
    } else {
      labels[b] = null;
    }
  }

  // bridging
  const bridged = labels.slice();
  for (let i = 1; i < blocks - 1; i++) {
    if (labels[i] === null && labels[i-1] !== null && labels[i+1] !== null && labels[i-1] === labels[i+1]) {
      bridged[i] = labels[i-1];
    }
  }

  // runs
  const presses: { digit: string; start: number; end: number }[] = [];
  const digitsConcat: string[] = [];
  let i = 0;
  while (i < blocks) {
    if (bridged[i] === null) { i++; continue; }
    const digit = bridged[i];
    let j = i;
    while (j < blocks && bridged[j] === digit) j++;
    const runLen = j - i;
    if (runLen >= 2) {
      const startMs = 20 * i;
      const endMs = 20 * (j);
      presses.push({ digit, start: startMs, end: endMs });
      digitsConcat.push(digit);
    }
    i = j;
  }

  return {
    unsupported: false,
    rate: sampleRate,
    channels,
    blocks,
    presses,
    digits: digitsConcat.join(''),
  };
}

function main() {
  const dir = process.argv[2];
  if (!dir) return;
  const entries = fs.readdirSync(dir);
  const wavFiles = entries.filter(n => n.endsWith('.wav')).sort();
  const outputs: string[] = [];

  wavFiles.forEach((name, idx) => {
    const full = path.join(dir, name);
    const res = parseWav(full, name);
    let out = '';
    if (res.unsupported) {
      out += `${name}: unsupported`;
    } else {
      out += `${name}: ${res.rate} Hz, ${res.channels} ch, ${res.blocks} blocks`;
      for (const p of res.presses) {
        out += `\n${p.digit} ${p.start} ${p.end}`;
      }
      out += `\ndigits: ${res.digits}`;
    }
    outputs.push(out);
    if (idx !== wavFiles.length - 1) outputs.push(''); // blank line
  });

  console.log(outputs.filter(s => s !== '').join('\n\n') + (outputs.length ? '\n' : ''));
}

main();

import java.io.*;
import java.net.URI;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    static class JsonValue {
        enum Type { OBJECT, ARRAY, STRING, NUMBER, BOOLEAN, NULL }
        Type type;
        Map<String, JsonValue> obj;
        List<JsonValue> arr;
        String str;
        Number num;
        Boolean bool;
        JsonValue(Map<String, JsonValue> o){type=Type.OBJECT; obj=o;}
        JsonValue(List<JsonValue> a){type=Type.ARRAY; arr=a;}
        JsonValue(String s){type=Type.STRING; str=s;}
        JsonValue(Number n){type=Type.NUMBER; num=n;}
        JsonValue(Boolean b){type=Type.BOOLEAN; bool=b;}
        JsonValue(){type=Type.NULL;}
    }

    static class JsonParser {
        String s; int p;
        JsonParser(String s){ this.s=s; this.p=0; }
        void skipWs(){ while(p<s.length() && Character.isWhitespace(s.charAt(p))) p++; }
        JsonValue parse(){ skipWs(); JsonValue v=parseValue(); return v; }
        JsonValue parseValue(){ skipWs(); char c=s.charAt(p);
            if(c=='{'){ p++; return new JsonValue(parseObject()); }
            if(c=='['){ p++; return new JsonValue(parseArray()); }
            if(c=='"'){ p++; return new JsonValue(parseString()); }
            if(c=='t' || c=='f'){ return new JsonValue(parseBool()); }
            if(c=='n'){ p+=4; return new JsonValue(); }
            if(c=='-' || Character.isDigit(c)){ return new JsonValue(parseNumber()); }
            throw new RuntimeException("bad json");
        }
        Map<String,JsonValue> parseObject(){
            Map<String,JsonValue> m=new LinkedHashMap<>();
            skipWs();
            if(s.charAt(p)=='}'){ p++; return m; }
            while(true){
                skipWs(); String key=parseString();
                skipWs(); if(s.charAt(p)!=':') throw new RuntimeException(":");
                p++; skipWs();
                JsonValue v=parseValue();
                m.put(key,v);
                skipWs(); char c=s.charAt(p);
                if(c==','){ p++; continue; }
                if(c=='}'){ p++; break; }
            }
            return m;
        }
        List<JsonValue> parseArray(){
            List<JsonValue> l=new ArrayList<>();
            skipWs();
            if(s.charAt(p)==']'){ p++; return l; }
            while(true){
                l.add(parseValue());
                skipWs(); char c=s.charAt(p);
                if(c==','){ p++; continue; }
                if(c==']'){ p++; break; }
            }
            return l;
        }
        String parseString(){
            StringBuilder sb=new StringBuilder();
            while(p<s.length()){
                char c=s.charAt(p++);
                if(c=='"') break;
                if(c=='\\'){
                    char e=s.charAt(p++);
                    switch(e){
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            String hex=s.substring(p,p+4); p+=4;
                            int code=Integer.parseInt(hex,16);
                            sb.append((char)code);
                            break;
                        default: sb.append(e);
                    }
                }else sb.append(c);
            }
            return sb.toString();
        }
        Boolean parseBool(){
            if(s.startsWith("true",p)){ p+=4; return true; }
            if(s.startsWith("false",p)){ p+=4; return false; }
            throw new RuntimeException("bool");
        }
        Number parseNumber(){
            int start=p;
            if(s.charAt(p)=='-') p++;
            while(p<s.length() && Character.isDigit(s.charAt(p))) p++;
            if(p<s.length() && s.charAt(p)=='.'){ p++; while(p<s.length() && Character.isDigit(s.charAt(p))) p++; }
            String num=s.substring(start,p);
            if(num.contains(".")) return Double.parseDouble(num);
            try{ return Long.parseLong(num); }catch(Exception e){ return Double.parseDouble(num); }
        }
    }

    static String jsonEscape(String s){
        StringBuilder sb=new StringBuilder();
        for(char c:s.toCharArray()){
            switch(c){
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if(c<0x20){ sb.append(String.format("\\u%04x",(int)c)); }
                    else sb.append(c);
            }
        }
        return sb.toString();
    }
    static String jsonSerialize(JsonValue v){
        switch(v.type){
            case OBJECT:
                StringBuilder o=new StringBuilder("{");
                boolean first=true;
                for(Map.Entry<String,JsonValue> e:v.obj.entrySet()){
                    if(!first) o.append(',');
                    first=false;
                    o.append('"').append(jsonEscape(e.getKey())).append("\":").append(jsonSerialize(e.getValue()));
                }
                o.append('}'); return o.toString();
            case ARRAY:
                StringBuilder a=new StringBuilder("[");
                for(int i=0;i<v.arr.size();i++){
                    if(i>0) a.append(',');
                    a.append(jsonSerialize(v.arr.get(i)));
                }
                a.append(']'); return a.toString();
            case STRING: return '"'+jsonEscape(v.str)+'"';
            case NUMBER: return v.num.toString();
            case BOOLEAN: return v.bool.toString();
            case NULL: return "null";
        }
        return "";
    }
    static String escapePrint(String s){
        StringBuilder sb=new StringBuilder();
        for(char c:s.toCharArray()){
            if(c=='\\') sb.append("\\\\");
            else if(c=='\n') sb.append("\\n");
            else if(c=='\r') sb.append("\\r");
            else if(c=='\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.toString();
    }

    static class Block {
