        for(Block b:first.blocks){
            if("tool_use".equals(b.type)){
                toolBlocks.add(b);
            }
        }
        for(Block b:toolBlocks){
            String res = runTool(b.toolUseName, b.toolUseInputParsed);
            boolean failed = isToolFailed(b.toolUseName, b.toolUseInputParsed, res);
            if(failed) out.println("error " + b.toolUseId + " " + escapePrint(res));
            else out.println("result " + b.toolUseId + " " + escapePrint(res));
            toolResults.add(res);
            toolFailed.add(failed);
        }

        // build request 2
        Map<String,Object> req2 = new LinkedHashMap<>();
        req2.put("model", model);
        req2.put("max_tokens", maxTokens);
        req2.put("stream", true);
        req2.put("thinking", thinking);
        req2.put("system", system);
        req2.put("tools", toolsVal);
        List<Map<String,Object>> msgs2 = new ArrayList<>();
        Map<String,Object> u2 = new LinkedHashMap<>();
        u2.put("role","user");
        u2.put("content", prompt);
        msgs2.add(u2);
        Map<String,Object> assistantMsg = new LinkedHashMap<>();
        assistantMsg.put("role","assistant");
