                cb.put("thinking", b.thinkingText);
                cb.put("signature", b.signature);
            }else if("text".equals(b.type)){
                cb.put("text", b.text);
            }else if("tool_use".equals(b.type)){
                cb.put("id", b.toolUseId);
                cb.put("name", b.toolUseName);
                cb.put("input", b.toolUseInputParsed.obj);
            }
            assistantContent.add(cb);
        }
        assistantMsg.put("content", assistantContent);
        msgs2.add(assistantMsg);
        Map<String,Object> userTools = new LinkedHashMap<>();
        userTools.put("role","user");
        List<Object> toolResultsContent = new ArrayList<>();
        for(int i=0;i<toolBlocks.size();i++){
            Block b=toolBlocks.get(i);
            Map<String,Object> tr = new LinkedHashMap<>();
            tr.put("type","tool_result");
            tr.put("tool_use_id", b.toolUseId);
            tr.put("content", toolResults.get(i));
            if(toolFailed.get(i)) tr.put("is_error", true);
            toolResultsContent.add(tr);
        }
        userTools.put("content", toolResultsContent);
        msgs2.add(userTools);
        req2.put("messages", msgs2);
        String body2 = serializeRequest(req2);
        ReplyResult second = doRequest(client, baseUrl, apiKey, body2, false);

        out.println("request 2");
        printBlocks(out, second.blocks);
        out.println("stop_reason " + second.stopReason);
        long totalInput = first.inputTokens + second.inputTokens;
        long totalOutput = first.outputTokens + second.outputTokens;
        long totalCache = first.cacheRead + second.cacheRead;
        out.println("usage input=" + totalInput + " output=" + totalOutput + " cache_read=" + totalCache);
    }

    static String serializeRequest(Map<String,Object> req){
        // manual serialization to keep tools unchanged
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        boolean first=true;
        for(Map.Entry<String,Object> e:req.entrySet()){
            if(!first) sb.append(',');
            first=false;
            sb.append('"').append(jsonEscape(e.getKey())).append("\":");
            Object v=e.getValue();
            if(v instanceof String){
                sb.append('"').append(jsonEscape((String)v)).append('"');
            }else if(v instanceof Number){
                sb.append(v);
            }else if(v instanceof Boolean){
                sb.append(v);
            }else if(v instanceof Map){
                sb.append(serializeMap((Map<String,Object>)v));
            }else if(v instanceof List){
                sb.append(serializeList((List<?>)v));
            }else if(v instanceof JsonValue){
                sb.append(jsonSerialize((JsonValue)v));
            }else{
                sb.append("null");
            }
        }
        sb.append('}');
        return sb.toString();
    }
    static String serializeMap(Map<String,Object> m){
        StringBuilder sb=new StringBuilder("{");
        boolean first=true;
        for(Map.Entry<String,Object> e:m.entrySet()){
            if(!first) sb.append(',');
            first=false;
            sb.append('"').append(jsonEscape(e.getKey())).append("\":");
            Object v=e.getValue();
            if(v instanceof String) sb.append('"').append(jsonEscape((String)v)).append('"');
            else if(v instanceof Number) sb.append(v);
            else if(v instanceof Boolean) sb.append(v);
            else if(v instanceof Map) sb.append(serializeMap((Map<String,Object>)v));
            else if(v instanceof List) sb.append(serializeList((List<?>)v));
            else if(v instanceof JsonValue) sb.append(jsonSerialize((JsonValue)v));
            else sb.append("null");
        }
        sb.append('}');
        return sb.toString();
    }
    static String serializeList(List<?> l){
        StringBuilder sb=new StringBuilder("[");
        for(int i=0;i<l.size();i++){
            if(i>0) sb.append(',');
            Object v=l.get(i);
            if(v instanceof String) sb.append('"').append(jsonEscape((String)v)).append('"');
            else if(v instanceof Number) sb.append(v);
            else if(v instanceof Boolean) sb.append(v);
            else if(v instanceof Map) sb.append(serializeMap((Map<String,Object>)v));
            else if(v instanceof List) sb.append(serializeList((List<?>)v));
            else if(v instanceof JsonValue) sb.append(jsonSerialize((JsonValue)v));
            else sb.append("null");
        }
        sb.append(']');
        return sb.toString();
    }

    static ReplyResult doRequest(HttpClient client, String baseUrl, String apiKey, String body, boolean isFirst) throws Exception {
        HttpRequest req = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/v1/messages"))
                .header("x-api-key", apiKey)
                .header("anthropic-version", "2023-06-01")
                .header("content-type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        HttpResponse<InputStream> resp = client.send(req, HttpResponse.BodyHandlers.ofInputStream());
        int status = resp.statusCode();
        if(status!=200){
            // read error
            String errBody = new String(resp.body().readAllBytes(), StandardCharsets.UTF_8);
            // parse error
            try{
                JsonValue ev = new JsonParser(errBody).parse();
                Map<String,JsonValue> o = ev.obj;
                Map<String,JsonValue> err = o.get("error").obj;
                String type = err.get("type").str;
                String msg = err.get("message").str;
                System.out.println("ERROR " + status + " " + type + ": " + msg);
            }catch(Exception e){
                System.out.println("ERROR " + status + " unknown");
            }
            System.exit(0);
        }
        InputStream is = resp.body();
        BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8));
        ReplyResult rr = new ReplyResult();
        Map<Integer,Block> blocksMap = new HashMap<>();
        String line;
        String eventName = null;
        StringBuilder dataBuf = new StringBuilder();
        boolean firstData = true;
        while((line=br.readLine())!=null){
            if(line.isEmpty()){
                if(eventName!=null && dataBuf.length()>0){
                    processEvent(eventName, dataBuf.toString(), rr, blocksMap);
                }
                eventName=null;
                dataBuf.setLength(0);
                firstData=true;
                continue;
            }
            if(line.startsWith(":")) continue;
            if(line.startsWith("event:")){
                eventName = line.substring(6).trim();
                continue;
            }
            if(line.startsWith("data:")){
                String d = line.substring(5);
                if(d.startsWith(" ")) d = d.substring(1);
                if(!firstData) dataBuf.append('\n');
                firstData=false;
                dataBuf.append(d);
            }
        }
        // finalize
        // order blocks by index
        List<Block> ordered = new ArrayList<>(blocksMap.values());
        ordered.sort(Comparator.comparingInt(b->b.index));
        rr.blocks = ordered;
        return rr;
    }

    static void processEvent(String event, String data, ReplyResult rr, Map<Integer,Block> blocksMap){
        if("message_start".equals(event)){
            JsonValue v = new JsonParser(data).parse();
            Map<String,JsonValue> msg = v.obj.get("message").obj;
            Map<String,JsonValue> usage = msg.get("usage").obj;
            rr.inputTokens += usage.get("input_tokens").num.longValue();
            JsonValue cr = usage.get("cache_read_input_tokens");
            if(cr!=null) rr.cacheRead += cr.num.longValue();
        }else if("content_block_start".equals(event)){
            JsonValue v = new JsonParser(data).parse();
            Map<String,JsonValue> o = v.obj;
            int idx = o.get("index").num.intValue();
            Map<String,JsonValue> cb = o.get("content_block").obj;
            String type = cb.get("type").str;
            Block b = new Block();
            b.index = idx;
            b.type = type;
            if("tool_use".equals(type)){
                b.toolUseId = cb.get("id").str;
                b.toolUseName = cb.get("name").str;
            }
            blocksMap.put(idx,b);
        }else if("content_block_delta".equals(event)){
            JsonValue v = new JsonParser(data).parse();
            Map<String,JsonValue> o = v.obj;
            int idx = o.get("index").num.intValue();
            Map<String,JsonValue> delta = o.get("delta").obj;
            String dtype = delta.get("type").str;
            Block b = blocksMap.get(idx);
            if(b==null) return;
            if("thinking_delta".equals(dtype)){
                b.thinkingText += delta.get("thinking").str;
            }else if("signature_delta".equals(dtype)){
                b.signature += delta.get("signature").str;
            }else if("text_delta".equals(dtype)){
                b.text += delta.get("text").str;
            }else if("input_json_delta".equals(dtype)){
                String part = delta.get("partial_json").str;
                b.toolUseInputRaw += part;
                // try parse to update parsed object later
            }
        }else if("message_delta".equals(event)){
            JsonValue v = new JsonParser(data).parse();
            Map<String,JsonValue> o = v.obj;
            Map<String,JsonValue> delta = o.get("delta").obj;
            rr.stopReason = delta.get("stop_reason").str;
            Map<String,JsonValue> usage = o.get("usage").obj;
            JsonValue out = usage.get("output_tokens");
            if(out!=null) rr.outputTokens += out.num.longValue();
        }
    }

    static void printBlocks(PrintWriter out, List<Block> blocks){
        for(Block b:blocks){
            if("thinking".equals(b.type)){
                out.println("thinking " + escapePrint(b.thinkingText));
                out.println("signature " + escapePrint(b.signature));
            }else if("text".equals(b.type)){
                out.println("text " + escapePrint(b.text));
            }else if("tool_use".equals(b.type)){
                // parse input for later use
                // already have raw
                out.println("tool_use " + b.toolUseId + " " + b.toolUseName + " " + escapePrint(b.toolUseInputRaw));
            }
        }
    }

    static String runTool(String name, JsonValue inputParsed){
        if("measure".equals(name)){
            Map<String,JsonValue> obj = inputParsed.obj;
            String text = obj.get("text").str;
            String unit = obj.get("unit").str;
            switch(unit){
                case "code_points":
                    int cp = text.codePointCount(0, text.length());
                    return Integer.toString(cp);
                case "utf8_bytes":
                    int bytes = text.getBytes(StandardCharsets.UTF_8).length;
                    return Integer.toString(bytes);
                case "utf16_units":
                    return Integer.toString(text.length());
                default:
                    return "unsupported unit: " + unit;
            }
        }else if("reverse".equals(name)){
            String text = inputParsed.obj.get("text").str;
            int[] cps = text.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for(int i=cps.length-1;i>=0;i--) sb.appendCodePoint(cps[i]);
            return sb.toString();
        }else{
            return "unknown tool: " + name;
        }
    }
    static boolean isToolFailed(String name, JsonValue inputParsed, String result){
        if("measure".equals(name)){
            String unit = inputParsed.obj.get("unit").str;
            return !unit.equals("code_points") && !unit.equals("utf8_bytes") && !unit.equals("utf16_units");
        }
        if(!"reverse".equals(name)) return true;
        return false;
    }
}

