public class Main {

    static String jsonEscape(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x",(int)c));
                    else sb.append(c);
            }
        }
        return sb.toString();
    }

    static String unescapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                char e = s.charAt(++i);
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        if (i + 4 < s.length()) {
                            String hex = s.substring(i + 1, i + 5);
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 4;
                        }
                        break;
                    default: sb.append(e);
                }
            } else sb.append(c);
        }
        return sb.toString();
    }

    static String escapePrint(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '\\') sb.append("\\\\");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.toString();
    }

    static class Block {
        int index;
        String type = "";
        String thinkingText = "";
        String signature = "";
        String text = "";
        String toolUseId = "";
        String toolUseName = "";
        String toolUseInputRaw = "";
    }

    static class ReplyResult {
        List<Block> blocks = new ArrayList<>();
        String stopReason = "";
        long inputTokens = 0;
        long cacheRead = 0;
        long outputTokens = 0;
    }

    // minimal JSON parser for SSE events
    static class JsonParser {
        String s; int p;
        JsonParser(String s){ this.s=s; this.p=0; }
        void skipWs(){ while(p<s.length() && Character.isWhitespace(s.charAt(p))) p++; }
        Object parseValue(){ skipWs(); if(p>=s.length()) return null; char c=s.charAt(p);
            if(c=='{'){ p++; return parseObject(); }
            if(c=='['){ p++; return parseArray(); }
            if(c=='"'){ p++; return parseString(); }
            if(c=='t'||c=='f'){ return parseBool(); }
            if(c=='n'){ p+=4; return null; }
            if(c=='-'||Character.isDigit(c)){ return parseNumber(); }
            p++; return null;
        }
        Map<String,Object> parseObject(){
            Map<String,Object> m=new LinkedHashMap<>();
            skipWs();
            if(p<s.length() && s.charAt(p)=='}'){ p++; return m; }
            while(true){
                skipWs(); String key=parseString();
                skipWs(); if(p<s.length() && s.charAt(p)==':') p++; else break;
                skipWs(); Object v=parseValue();
                m.put(key,v);
                skipWs(); if(p<s.length() && s.charAt(p)==','){ p++; continue; }
                if(p<s.length() && s.charAt(p)=='}'){ p++; break; }
                break;
            }
            return m;
        }
        List<Object> parseArray(){
            List<Object> l=new ArrayList<>();
            skipWs();
            if(p<s.length() && s.charAt(p)==']'){ p++; return l; }
            while(true){
                l.add(parseValue());
                skipWs(); if(p<s.length() && s.charAt(p)==','){ p++; continue; }
                if(p<s.length() && s.charAt(p)==']'){ p++; break; }
                break;
            }
            return l;
        }
        String parseString(){
            StringBuilder sb=new StringBuilder();
            while(p<s.length()){
                char c=s.charAt(p++);
                if(c=='"') break;
                if(c=='\\' && p<s.length()){
                    char e=s.charAt(p++);
                    switch(e){
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if(p+4<=s.length()){
                                int code=Integer.parseInt(s.substring(p,p+4),16);
                                sb.append((char)code);
                                p+=4;
                            }
                            break;
                        default: sb.append(e);
                    }
                }else sb.append(c);
            }
            return sb.toString();
        }
        Boolean parseBool(){ if(s.startsWith("true",p)){p+=4;return true;} if(s.startsWith("false",p)){p+=5;return false;} return false; }
        Number parseNumber(){ int start=p; if(s.charAt(p)=='-') p++; while(p<s.length() && Character.isDigit(s.charAt(p))) p++; if(p<s.length() && s.charAt(p)=='.'){p++; while(p<s.length() && Character.isDigit(s.charAt(p))) p++;} String num=s.substring(start,p); try{return Long.parseLong(num);}catch(Exception e){return Double.parseDouble(num);} }
    }

    static String parseChunked(byte[] all){
        StringBuilder out=new StringBuilder();
        int pos=0;
        while(pos<all.length){
            int eol=pos;
            while(eol<all.length && !(all[eol]==13 && eol+1<all.length && all[eol+1]==10)) eol++;
            if(eol>=all.length) break;
            String sizeHex=new String(all,pos,eol-pos,StandardCharsets.US_ASCII).trim();
            int size;
            try{ size=Integer.parseInt(sizeHex,16); }catch(Exception ex){ break; }
            pos=eol+2;
            if(size==0) break;
            if(pos+size>all.length) break;
            out.append(new String(all,pos,size,StandardCharsets.UTF_8));
            pos+=size;
            if(pos+1<all.length && all[pos]==13 && all[pos+1]==10) pos+=2;
        }
        return out.toString();
    }

    static ReplyResult doRequest(HttpClient client,String baseUrl,String apiKey,String body) throws Exception {
        HttpRequest req=HttpRequest.newBuilder()
                .uri(URI.create(baseUrl+"/v1/messages"))
                .header("x-api-key",apiKey)
                .header("anthropic-version","2023-06-01")
                .header("content-type","application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        HttpResponse<InputStream> resp=client.send(req,HttpResponse.BodyHandlers.ofInputStream());
        int status=resp.statusCode();
        ByteArrayOutputStream baos=new ByteArrayOutputStream();
        try(InputStream is=resp.body()){ byte[] buf=new byte[8192]; int n; while((n=is.read(buf))!=-1) baos.write(buf,0,n); }
        byte[] all=baos.toByteArray();
        if(status!=200){
            String txt=new String(all,StandardCharsets.UTF_8);
            try{
                JsonParser jp=new JsonParser(txt);
                Object v=jp.parseValue();
                if(v instanceof Map){
                    Map<String,Object> o=(Map<String,Object>)v;
                    Map<String,Object> err=(Map<String,Object>)o.get("error");
                    String type=(String)err.get("type");
                    String msg=(String)err.get("message");
                    System.out.println("ERROR "+status+" "+type+": "+msg);
                }else System.out.println("ERROR "+status+" unknown");
            }catch(Exception e){ System.out.println("ERROR "+status+" unknown"); }
            System.exit(0);
        }
        String sse=parseChunked(all);
        ReplyResult rr=new ReplyResult();
        Map<Integer,Block> blocksMap=new HashMap<>();
        String eventName=null;
        StringBuilder dataBuf=new StringBuilder();
        boolean first=true;
        BufferedReader br=new BufferedReader(new StringReader(sse));
        String line;
        while((line=br.readLine())!=null){
            if(line.isEmpty()){
                if(eventName!=null && dataBuf.length()>0) processEvent(eventName,dataBuf.toString(),rr,blocksMap);
                eventName=null; dataBuf.setLength(0); first=true; continue;
            }
            if(line.startsWith(":")) continue;
            if(line.startsWith("event:")){ eventName=line.substring(6).trim(); continue; }
            if(line.startsWith("data:")){
                String d=line.substring(5);
                if(d.startsWith(" ")) d=d.substring(1);
                if(!first) dataBuf.append('\n');
                first=false;
                dataBuf.append(d);
            }
        }
        List<Block> ordered=new ArrayList<>(blocksMap.values());
        ordered.sort(Comparator.comparingInt(b->b.index));
        rr.blocks=ordered;
        return rr;
    }

    static void processEvent(String event,String data,ReplyResult rr,Map<Integer,Block> blocksMap){
        JsonParser jp=new JsonParser(data);
        Object v=jp.parseValue();
        if(!(v instanceof Map)) return;
        Map<String,Object> o=(Map<String,Object>)v;
        if("message_start".equals(event)){
            Map<String,Object> msg=(Map<String,Object>)o.get("message");
            Map<String,Object> usage=(Map<String,Object>)msg.get("usage");
            rr.inputTokens+= ((Number)usage.get("input_tokens")).longValue();
            Object cr=usage.get("cache_read_input_tokens");
            if(cr instanceof Number) rr.cacheRead+=((Number)cr).longValue();
        }else if("content_block_start".equals(event)){
            Map<String,Object> cb=(Map<String,Object>)o.get("content_block");
            int idx=((Number)o.get("index")).intValue();
            String type=(String)cb.get("type");
            Block b=new Block(); b.index=idx; b.type=type;
            if("tool_use".equals(type)){
                b.toolUseId=(String)cb.get("id");
                b.toolUseName=(String)cb.get("name");
            }
            blocksMap.put(idx,b);
        }else if("content_block_delta".equals(event)){
            int idx=((Number)o.get("index")).intValue();
            Block b=blocksMap.get(idx); if(b==null) return;
            Map<String,Object> delta=(Map<String,Object>)o.get("delta");
            String dtype=(String)delta.get("type");
            if("thinking_delta".equals(dtype)) b.thinkingText+= (String)delta.get("thinking");
            else if("signature_delta".equals(dtype)) b.signature+= (String)delta.get("signature");
            else if("text_delta".equals(dtype)) b.text+= (String)delta.get("text");
            else if("input_json_delta".equals(dtype)) b.toolUseInputRaw+= (String)delta.get("partial_json");
        }else if("message_delta".equals(event)){
            Map<String,Object> delta=(Map<String,Object>)o.get("delta");
            rr.stopReason=(String)delta.get("stop_reason");
            Map<String,Object> usage=(Map<String,Object>)o.get("usage");
            Object out=usage.get("output_tokens");
            if(out instanceof Number) rr.outputTokens+=((Number)out).longValue();
        }
    }

    static String runTool(String name, String rawInput){
        // rawInput is the concatenated partial_json text
        // we need to parse it as JSON object with string values
        try{
            JsonParser jp=new JsonParser(rawInput);
            Object v=jp.parseValue();
            if(!(v instanceof Map)) return "unknown tool: "+name;
            Map<String,Object> obj=(Map<String,Object>)v;
            if("measure".equals(name)){
                String text=(String)obj.get("text");
                String unit=(String)obj.get("unit");
                switch(unit){
                    case "code_points": return Integer.toString(text.codePointCount(0,text.length()));
                    case "utf8_bytes": return Integer.toString(text.getBytes(StandardCharsets.UTF_8).length);
                    case "utf16_units": return Integer.toString(text.length());
                    default: return "unsupported unit: "+unit;
                }
            }else if("reverse".equals(name)){
                String text=(String)obj.get("text");
                int[] cps=text.codePoints().toArray();
                StringBuilder sb=new StringBuilder();
                for(int i=cps.length-1;i>=0;i--) sb.appendCodePoint(cps[i]);
                return sb.toString();
            }else{
                return "unknown tool: "+name;
            }
        }catch(Exception e){
            return "unknown tool: "+name;
        }
    }

    public static void main(String[] args) throws Exception {
        if(args.length!=2) System.exit(0);
        String dataDir=args[0];
        String baseUrl=args[1];
        String content=Files.readString(Path.of(dataDir,"request.json"),StandardCharsets.UTF_8);
        Pattern pApi=Pattern.compile("\"api_key\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"");
        Pattern pModel=Pattern.compile("\"model\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"");
        Pattern pMax=Pattern.compile("\"max_tokens\"\\s*:\\s*(\\d+)");
        Pattern pBudget=Pattern.compile("\"thinking_budget\"\\s*:\\s*(\\d+)");
        Pattern pSys=Pattern.compile("\"system\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"");
        Pattern pPrompt=Pattern.compile("\"prompt\"\\s*:\\s*\"((?:\\\\.|[^\"\\\\])*)\"");
        String apiKey=extract(pApi,content);
        String model=extract(pModel,content);
        long maxTokens=Long.parseLong(extract(pMax,content));
        long thinkingBudget=Long.parseLong(extract(pBudget,content));
        String system=unescapeJson(extract(pSys,content));
        String prompt=unescapeJson(extract(pPrompt,content));
        // tools raw
        int idxTools=content.indexOf("\"tools\"");
        String toolsRaw="[]";
        if(idxTools!=-1){
            int colon=content.indexOf(':',idxTools);
            int start=content.indexOf('[',colon);
            int depth=0; int end=start;
            for(int i=start;i<content.length();i++){
                char c=content.charAt(i);
                if(c=='[') depth++;
                else if(c==']'){ depth--; if(depth==0){ end=i; break; } }
            }
            toolsRaw=content.substring(start,end+1);
        }
        HttpClient client=HttpClient.newHttpClient();

        String req1=buildReq1(model,maxTokens,thinkingBudget,system,toolsRaw,prompt);
        ReplyResult first=doRequest(client,baseUrl,apiKey,req1);
        PrintWriter out=new PrintWriter(System.out,true);
        out.println("request 1");
        for(Block b:first.blocks){
            if("thinking".equals(b.type)){
                out.println("thinking "+escapePrint(b.thinkingText));
                out.println("signature "+escapePrint(b.signature));
            }else if("text".equals(b.type)){
                out.println("text "+escapePrint(b.text));
            }else if("tool_use".equals(b.type)){
                out.println("tool_use "+b.toolUseId+" "+b.toolUseName+" "+escapePrint(b.toolUseInputRaw));
            }
        }
        out.println("stop_reason "+first.stopReason);

        List<Block> toolBlocks=new ArrayList<>();
        for(Block b:first.blocks) if("tool_use".equals(b.type)) toolBlocks.add(b);
        List<String> toolResults=new ArrayList<>();
        List<Boolean> toolFailed=new ArrayList<>();
        for(Block b:toolBlocks){
            String res=runTool(b.toolUseName,b.toolUseInputRaw);
            boolean failed=false;
            if("measure".equals(b.toolUseName)){
                // check unit
                try{
                    JsonParser jp=new JsonParser(b.toolUseInputRaw);
                    Map<String,Object> o=(Map<String,Object>)jp.parseValue();
                    String unit=(String)o.get("unit");
                    if(!unit.equals("code_points") && !unit.equals("utf8_bytes") && !unit.equals("utf16_units")) failed=true;
                }catch(Exception e){ failed=true; }
            }else if(!"reverse".equals(b.toolUseName)) failed=true;
            if(failed) out.println("error "+b.toolUseId+" "+escapePrint(res));
            else out.println("result "+b.toolUseId+" "+escapePrint(res));
            toolResults.add(res);
            toolFailed.add(failed);
        }

        // build request 2
        StringBuilder req2=new StringBuilder();
        req2.append('{');
        req2.append("\"model\":\"").append(jsonEscape(model)).append("\",");
        req2.append("\"max_tokens\":").append(maxTokens).append(",");
        req2.append("\"stream\":true,");
        req2.append("\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":").append(thinkingBudget).append("},");
        req2.append("\"system\":\"").append(jsonEscape(system)).append("\",");
        req2.append("\"tools\":").append(toolsRaw).append(",");
        req2.append("\"messages\":[");
        req2.append("{\"role\":\"user\",\"content\":\"").append(jsonEscape(prompt)).append("\"},");
        req2.append("{\"role\":\"assistant\",\"content\":[");
        for(int i=0;i<first.blocks.size();i++){
            Block b=first.blocks.get(i);
            req2.append("{\"type\":\"").append(b.type).append("\"");
            if("thinking".equals(b.type)){
                req2.append(",\"thinking\":\"").append(jsonEscape(b.thinkingText)).append("\",\"signature\":\"").append(jsonEscape(b.signature)).append("\"");
            }else if("text".equals(b.type)){
                req2.append(",\"text\":\"").append(jsonEscape(b.text)).append("\"");
            }else if("tool_use".equals(b.type)){
                // need parsed input object for request
                JsonParser jp=new JsonParser(b.toolUseInputRaw);
                Map<String,Object> inp=(Map<String,Object>)jp.parseValue();
                req2.append(",\"id\":\"").append(jsonEscape(b.toolUseId)).append("\",\"name\":\"").append(jsonEscape(b.toolUseName)).append("\",\"input\":");
                req2.append(mapToJson(inp));
            }
            req2.append('}');
            if(i+1<first.blocks.size()) req2.append(',');
        }
        req2.append("]},");
        req2.append("{\"role\":\"user\",\"content\":[");
        for(int i=0;i<toolBlocks.size();i++){
            Block b=toolBlocks.get(i);
            req2.append("{\"type\":\"tool_result\",\"tool_use_id\":\"").append(jsonEscape(b.toolUseId)).append("\",\"content\":\"").append(jsonEscape(toolResults.get(i))).append("\"");
            if(toolFailed.get(i)) req2.append(",\"is_error\":true");
            req2.append('}');
            if(i+1<toolBlocks.size()) req2.append(',');
        }
        req2.append("]}");
        req2.append("]}");
        ReplyResult second=doRequest(client,baseUrl,apiKey,req2.toString());
        out.println("request 2");
        for(Block b:second.blocks){
            if("thinking".equals(b.type)){
                out.println("thinking "+escapePrint(b.thinkingText));
                out.println("signature "+escapePrint(b.signature));
            }else if("text".equals(b.type)){
                out.println("text "+escapePrint(b.text));
            }else if("tool_use".equals(b.type)){
                out.println("tool_use "+b.toolUseId+" "+b.toolUseName+" "+escapePrint(b.toolUseInputRaw));
            }
        }
        out.println("stop_reason "+second.stopReason);
        long totalInput=first.inputTokens+second.inputTokens;
        long totalOutput=first.outputTokens+second.outputTokens;
        long totalCache=first.cacheRead+second.cacheRead;
        out.println("usage input="+totalInput+" output="+totalOutput+" cache_read="+totalCache);
