                                // compute powers
                                var bestLowIdx = 0
                                var bestLowR = -1.0
                                var lowRs = [Double]()
                                for (i, c) in cValsLow.enumerated() {
                                    var s1 = 0.0, s2 = 0.0
                                    for x in blockSamples {
                                        let s = Double(x) + c * s1 - s2
                                        s2 = s1
                                        s1 = s
                                    }
                                    let P = s1*s1 + s2*s2 - c * s1 * s2
                                    let r = 2.0 * P / (Double(N) * Double(E))
                                    lowRs.append(r)
                                    if r > bestLowR {
                                        bestLowR = r
                                        bestLowIdx = i
                                    }
                                }
                                var bestHighIdx = 0
                                var bestHighR = -1.0
                                for (i, c) in cValsHigh.enumerated() {
                                    var s1 = 0.0, s2 = 0.0
                                    for x in blockSamples {
                                        let s = Double(x) + c * s1 - s2
                                        s2 = s1
                                        s1 = s
                                    }
                                    let P = s1*s1 + s2*s2 - c * s1 * s2
                                    let r = 2.0 * P / (Double(N) * Double(E))
                                    if r > bestHighR {
                                        bestHighR = r
                                        bestHighIdx = i
                                    }
                                }
                                if bestLowR >= 0.1 && bestHighR >= 0.1 && bestLowR + bestHighR >= 0.6 {
                                    let digit = digitMap[bestLowIdx][bestHighIdx]
                                    originalLabels[b] = digit
                                } else {
                                    originalLabels[b] = nil
                                }
                            }
                            // bridging
                            var labels = originalLabels
                            for i in 1..<(blocksCount-1) {
                                if originalLabels[i] == nil,
                                   let left = originalLabels[i-1],
                                   let right = originalLabels[i+1],
                                   left == right {
                                    labels[i] = left
                                }
                            }
                            // runs
                            var curDigit: String? = nil
                            var runStart = 0
                            var runLen = 0
                            for i in 0..<blocksCount {
                                let d = labels[i]
                                if d == curDigit {
                                    runLen += 1
                                } else {
                                    if let cd = curDigit, runLen >= 2 {
                                        let startMs = 20 * runStart
                                        let endMs = 20 * (runStart + runLen)
                                        events.append((cd, startMs, endMs))
                                        digitsString += cd
                                    }
                                    curDigit = d
                                    if d != nil {
                                        runStart = i
                                        runLen = 1
                                    } else {
                                        runStart = i + 1
                                        runLen = 0
                                    }
                                }
                            }
                            if let cd = curDigit, runLen >= 2 {
                                let startMs = 20 * runStart
                                let endMs = 20 * (runStart + runLen)
                                events.append((cd, startMs, endMs))
                                digitsString += cd
                            }
                        }
                    }
                }
            }
        }
    }

    if !isSupportedFile {
        print("\(name): unsupported")
    } else {
        print("\(name): \(sampleRate) Hz, \(channels) ch, \(blocksCount) blocks")
        for ev in events {
            print("\(ev.0) \(ev.1) \(ev.2)")
        }
        print("digits: \(digitsString)")
    }
    if fileIdx < wavFiles.count - 1 {
        print("")
    }
}

import Foundation

func readU16LE(_ data: Data, offset: Int) -> UInt16 {
    let v = data.withUnsafeBytes { $0.load(fromByteOffset: offset, as: UInt16.self) }
    return UInt16(littleEndian: v)
}
func readU32LE(_ data: Data, offset: Int) -> UInt32 {
    let v = data.withUnsafeBytes { $0.load(fromByteOffset: offset, as: UInt32.self) }
    return UInt32(littleEndian: v)
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dirPath = args[1]
let fm = FileManager.default
guard let contents = try? fm.contentsOfDirectory(atPath: dirPath) else { exit(0) }
let wavFiles = contents.filter { $0.hasSuffix(".wav") }.sorted()

let lowFreqs = [697, 770, 852, 941]
let highFreqs = [1209, 1336, 1477, 1633]
let digitMap = [
    ["1","2","3","A"],
    ["4","5","6","B"],
    ["7","8","9","C"],
    ["*","0","#","D"]
]

for (fileIdx, name) in wavFiles.enumerated() {
    let fullPath = dirPath + "/" + name
    guard let fileData = try? Data(contentsOf: URL(fileURLWithPath: fullPath)) else { continue }

    var isSupported = false
    var sampleRate = 0
    var channels = 0
    var blocksCount = 0
    var events: [(String,Int,Int)] = []
    var digitsString = ""

    if fileData.count >= 12 {
        let riff = String(data: fileData.subdata(in: 0..<4), encoding: .ascii) ?? ""
        let wave = String(data: fileData.subdata(in: 8..<12), encoding: .ascii) ?? ""
        if riff == "RIFF" && wave == "WAVE" {
            var offset = 12
            var fmtFound = false
            var fmtFormatTag = 0
            var fmtBits = 0
            var fmtChannels = 0
            var fmtSampleRate = 0
            var fmtBodyLen = 0
            var fmtBodyData: Data? = nil
            var dataStart = 0
            var dataSize = 0

            while offset + 8 <= fileData.count {
                let id = String(data: fileData.subdata(in: offset..<offset+4), encoding: .ascii) ?? ""
                let size = Int(readU32LE(fileData, offset: offset+4))
                let bodyStart = offset + 8
                let bodyEnd = min(bodyStart + size, fileData.count)
                let body = fileData.subdata(in: bodyStart..<bodyEnd)
                if id == "fmt " {
                    fmtFound = true
                    fmtBodyData = body
                    fmtBodyLen = body.count
                    if body.count >= 16 {
                        fmtFormatTag = Int(readU16LE(body as Data, offset: 0))
                        fmtChannels = Int(readU16LE(body as Data, offset: 2))
                        fmtSampleRate = Int(readU32LE(body as Data, offset: 4))
                        fmtBits = Int(readU16LE(body as Data, offset: 14))
                    }
                }
                if id == "data" {
                    dataStart = bodyStart
                    dataSize = size
                }
                offset = bodyStart + size + (size % 2 == 1 ? 1 : 0)
            }

            if fmtFound && dataSize > 0 {
                var effectiveFormat = fmtFormatTag
                if fmtFormatTag == 0xFFFE && fmtBodyLen > 24, let fb = fmtBodyData {
                    let sub = readU16LE(fb, offset: 24)
                    effectiveFormat = Int(sub)
                }
                let fmtOk = effectiveFormat == 1 && fmtBits == 16
                let chOk = fmtChannels == 1 || fmtChannels == 2
                let srOk = fmtSampleRate == 8000 || fmtSampleRate == 16000
                if fmtOk && chOk && srOk {
                    isSupported = true
                    sampleRate = fmtSampleRate
                    channels = fmtChannels

                    let frameBytes = 2 * channels
                    let totalFrames = dataSize / frameBytes
                    let N = sampleRate / 50
                    if N > 0 && totalFrames > 0 {
                        blocksCount = totalFrames / N
                        // left channel samples
                        var leftSamples = [Int16]()
                        leftSamples.reserveCapacity(totalFrames)
                        let dataBytes = fileData.subdata(in: dataStart..<dataStart+dataSize)
                        var i = 0
                        while i + 2 <= dataBytes.count {
                            let raw = dataBytes.withUnsafeBytes { $0.load(fromByteOffset: i, as: UInt16.self) }
                            let v = UInt16(littleEndian: raw)
                            let s = Int16(bitPattern: v)
                            leftSamples.append(s)
                            i += frameBytes
                        }

                        let twoPiOverRate = 2.0 * Double.pi / Double(sampleRate)
                        var cValsLow = [Double]()
                        var cValsHigh = [Double]()
                        for f in lowFreqs { cValsLow.append(2.0 * cos(Double(f) * twoPiOverRate)) }
                        for f in highFreqs { cValsHigh.append(2.0 * cos(Double(f) * twoPiOverRate)) }

                        var originalLabels = [String?](repeating: nil, count: blocksCount)
                        for b in 0..<blocksCount {
                            let startIdx = b * N
                            let endIdx = startIdx + N
                            var E: Int64 = 0
                            for k in startIdx..<endIdx {
                                let x = Int32(leftSamples[k])
                                E += Int64(x * x)
                            }
                            if Int64(E) < 1_000_000 * Int64(N) {
                                originalLabels[b] = nil
                                continue
                            }
                            var bestLowIdx = 0
                            var bestLowR = -1.0
                            for (i,c) in cValsLow.enumerated() {
                                var s1 = 0.0, s2 = 0.0
                                var idx = startIdx
                                for _ in 0..<N {
                                    let x = Double(leftSamples[idx])
                                    let s = x + c * s1 - s2
                                    s2 = s1
                                    s1 = s
                                    idx += 1
                                }
                                let P = s1*s1 + s2*s2 - c * s1 * s2
                                let r = 2.0 * P / (Double(N) * Double(E))
                                if r > bestLowR {
                                    bestLowR = r
                                    bestLowIdx = i
                                }
                            }
                            var bestHighIdx = 0
                            var bestHighR = -1.0
                            for (i,c) in cValsHigh.enumerated() {
                                var s1 = 0.0, s2 = 0.0
                                var idx = startIdx
                                for _ in 0..<N {
                                    let x = Double(leftSamples[idx])
                                    let s = x + c * s1 - s2
                                    s2 = s1
                                    s1 = s
                                    idx += 1
                                }
                                let P = s1*s1 + s2*s2 - c * s1 * s2
                                let r = 2.0 * P / (Double(N) * Double(E))
                                if r > bestHighR {
                                    bestHighR = r
                                    bestHighIdx = i
                                }
                            }
                            if bestLowR >= 0.1 && bestHighR >= 0.1 && bestLowR + bestHighR >= 0.6 {
                                originalLabels[b] = digitMap[bestLowIdx][bestHighIdx]
                            } else {
                                originalLabels[b] = nil
                            }
                        }

                        // bridging
                        var labels = originalLabels
                        if blocksCount > 2 {
                            for i in 1..<(blocksCount-1) {
                                if originalLabels[i] == nil,
                                   let left = originalLabels[i-1],
                                   let right = originalLabels[i+1],
                                   left == right {
                                    labels[i] = left
                                }
                            }
                        }

                        // runs
                        var i = 0
                        while i < blocksCount {
                            guard let d = labels[i] else { i += 1; continue }
                            let startIdx = i
                            var j = i + 1
                            while j < blocksCount && labels[j] == d { j += 1 }
                            let len = j - startIdx
                            if len >= 2 {
                                let startMs = 20 * startIdx
                                let endMs = 20 * (startIdx + len)
                                events.append((d, startMs, endMs))
                                digitsString.append(d)
                            }
                            i = j
                        }
                    }
                }
            }
        }
    }

    if !isSupported {
        print("\(name): unsupported")
    } else {
        print("\(name): \(sampleRate) Hz, \(channels) ch, \(blocksCount) blocks")
        for ev in events {
            print("\(ev.0) \(ev.1) \(ev.2)")
        }
        print("digits: \(digitsString)")
    }
    if fileIdx < wavFiles.count - 1 {
        print("")
    }
}

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {

    private static final int[] LOW_FREQS = {697, 770, 852, 941};
    private static final int[] HIGH_FREQS = {1209, 1336, 1477, 1633};
    private static final char[][] MAP = {
            {'1', '2', '3', 'A'},
            {'4', '5', '6', 'B'},
            {'7', '8', '9', 'C'},
            {'*', '0', '#', 'D'}
    };

    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        File dir = new File(args[0]);
        File[] all = dir.listFiles();
        if (all == null) all = new File[0];
        List<File> wav = new ArrayList<>();
        for (File f : all) {
            if (f.isFile() && f.getName().endsWith(".wav")) {
                wav.add(f);
            }
        }
        wav.sort((a, b) -> a.getName().compareTo(b.getName()));

        boolean first = true;
        for (File f : wav) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    private static void processFile(File f) throws Exception {
        String name = f.getName();
        byte[] bytes = Files.readAllBytes(f.toPath());
        WavInfo info = parseWav(bytes);
        if (info == null || !info.supported) {
            System.out.println(name + ": unsupported");
            return;
        }
        int rate = info.sampleRate;
        int channels = info.channels;
        int dataPos = info.dataPos;
        int dataSize = info.dataSize;
        int numFrames = dataSize / (2 * channels);
        int N = rate / 50;
        int blocks = numFrames / N;

        int[] samples = new int[numFrames];
        for (int i = 0; i < numFrames; i++) {
            int off = dataPos + i * channels * 2;
            int lo = bytes[off] & 0xff;
            int hi = bytes[off + 1] & 0xff;
            int v = lo | (hi << 8);
            if (v >= 32768) v -= 65536;
            samples[i] = v;
        }

        // precompute c for each frequency
        double[] lowC = new double[LOW_FREQS.length];
        double[] highC = new double[HIGH_FREQS.length];
        for (int i = 0; i < LOW_FREQS.length; i++) lowC[i] = 2 * Math.cos(2 * Math.PI * LOW_FREQS[i] / rate);
        for (int i = 0; i < HIGH_FREQS.length; i++) highC[i] = 2 * Math.cos(2 * Math.PI * HIGH_FREQS[i] / rate);

        Character[] labels = new Character[blocks];
        for (int b = 0; b < blocks; b++) {
            int start = b * N;
            long E = 0;
            for (int n = 0; n < N; n++) {
                long v = samples[start + n];
                E += v * v;
            }
            if (E < 1_000_000L * N) {
                labels[b] = null;
                continue;
            }
            double bestLowR = -1;
            int bestLowIdx = -1;
            double[] lowR = new double[LOW_FREQS.length];
            for (int i = 0; i < LOW_FREQS.length; i++) {
                double s1 = 0, s2 = 0;
                double c = lowC[i];
                for (int n = 0; n < N; n++) {
                    double s = samples[start + n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                double r = 2 * P / (N * E);
                lowR[i] = r;
                if (r > bestLowR) {
                    bestLowR = r;
                    bestLowIdx = i;
                }
            }
            double bestHighR = -1;
            int bestHighIdx = -1;
            double[] highR = new double[HIGH_FREQS.length];
            for (int i = 0; i < HIGH_FREQS.length; i++) {
                double s1 = 0, s2 = 0;
                double c = highC[i];
                for (int n = 0; n < N; n++) {
                    double s = samples[start + n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                double r = 2 * P / (N * E);
                highR[i] = r;
                if (r > bestHighR) {
                    bestHighR = r;
                    bestHighIdx = i;
                }
            }
            if (bestLowR >= 0.1 && bestHighR >= 0.1 && bestLowR + bestHighR >= 0.6) {
                char digit = MAP[bestLowIdx][bestHighIdx];
                labels[b] = digit;
            } else {
                labels[b] = null;
            }
        }

        Character[] bridged = labels.clone();
        for (int i = 1; i < blocks - 1; i++) {
            if (labels[i] == null && labels[i - 1] != null && labels[i + 1] != null
                    && labels[i - 1].equals(labels[i + 1])) {
                bridged[i] = labels[i - 1];
            }
        }

        System.out.println(name + ": " + rate + " Hz, " + channels + " ch, " + blocks + " blocks");
        StringBuilder digitsBuilder = new StringBuilder();
        if (blocks > 0) {
            int i = 0;
            while (i < blocks) {
                if (bridged[i] != null) {
                    char d = bridged[i];
                    int startIdx = i;
                    int j = i;
                    while (j < blocks && bridged[j] != null && bridged[j] == d) j++;
                    int runLen = j - startIdx;
                    if (runLen >= 2) {
                        int startMs = 20 * startIdx;
                        int endMs = 20 * (j);
                        System.out.println(d + " " + startMs + " " + endMs);
                        for (int k = 0; k < runLen; k++) digitsBuilder.append(d);
                    }
                    i = j;
                } else {
                    i++;
                }
            }
        }
        System.out.println("digits: " + digitsBuilder.toString());
    }

    private static class WavInfo {
        int sampleRate;
        int channels;
        int bitsPerSample;
        int dataPos;
        int dataSize;
        boolean supported;
    }

    private static WavInfo parseWav(byte[] b) {
        if (b.length < 12) return null;
        if (!(b[0] == 'R' && b[1] == 'I' && b[2] == 'F' && b[3] == 'F')) return null;
        if (!(b[8] == 'W' && b[9] == 'A' && b[10] == 'V' && b[11] == 'E')) return null;
        int pos = 12;
        Integer fmtTag = null;
        Integer channels = null;
        Integer sampleRate = null;
        Integer bitsPerSample = null;
        Integer effectiveFormat = null;
        int dataPos = -1;
        int dataSize = -1;
        while (pos + 8 <= b.length) {
            String id = new String(b, pos, 4, StandardCharsets.US_ASCII);
            int size = leInt(b, pos + 4);
            int bodyPos = pos + 8;
            if (id.equals("fmt ")) {
                if (size >= 16) {
                    int tag = leShort(b, bodyPos);
                    int ch = leShort(b, bodyPos + 2);
                    int sr = leInt(b, bodyPos + 4);
                    int bps = leShort(b, bodyPos + 14);
                    fmtTag = tag;
                    channels = ch;
                    sampleRate = sr;
                    bitsPerSample = bps;
                    if (tag == 0xFFFE && size > 16) {
                        int sub = leShort(b, bodyPos + 24);
                        effectiveFormat = sub;
                    } else {
                        effectiveFormat = tag;
                    }
                }
            } else if (id.equals("data")) {
                dataPos = bodyPos;
                dataSize = size;
            }
            pos = bodyPos + size;
            if (size % 2 == 1) pos++;
            if (fmtTag != null && dataPos != -1) {
                // we could break early, but continue to be safe
            }
        }
        WavInfo info = new WavInfo();
        if (fmtTag == null || channels == null || sampleRate == null || bitsPerSample == null
                || effectiveFormat == null || dataPos == -1) {
            info.supported = false;
            return info;
        }
        boolean supported = effectiveFormat == 1 && bitsPerSample == 16
                && (channels == 1 || channels == 2)
                && (sampleRate == 8000 || sampleRate == 16000);
        info.supported = supported;
        if (!supported) return info;
        info.sampleRate = sampleRate;
        info.channels = channels;
        info.bitsPerSample = bitsPerSample;
        info.dataPos = dataPos;
        info.dataSize = dataSize;
        return info;
    }

    private static int leShort(byte[] b, int off) {
        return (b[off] & 0xff) | ((b[off + 1] & 0xff) << 8);
    }

    private static int leInt(byte[] b, int off) {
        return (b[off] & 0xff) | ((b[off + 1] & 0xff) << 8)
                | ((b[off + 2] & 0xff) << 16) | ((b[off + 3] & 0xff) << 24);
    }
}

