                if (bridged[i] != null) {
                    char d = bridged[i];
                    int startIdx = i;
                    int j = i;
                    while (j < blocks && bridged[j] != null && bridged[j] == d) j++;
                    int runLen = j - startIdx;
                    if (runLen >= 2) {
                        int startMs = 20 * startIdx;
                        int endMs = 20 * j;
                        System.out.println(d + " " + startMs + " " + endMs);
                        digitsBuilder.append(d);
                    }
                    i = j;
                } else {
                    i++;
                }
            }
        }
        System.out.println("digits: " + digitsBuilder.toString());
    }

    private static class WavInfo {
        int sampleRate;
        int channels;
        int bitsPerSample;
        int dataPos;
        int dataSize;
        boolean supported;
    }

    private static WavInfo parseWav(byte[] b) {
        if (b.length < 12) return null;
        if (!(b[0] == 'R' && b[1] == 'I' && b[2] == 'F' && b[3] == 'F')) return null;
        if (!(b[8] == 'W' && b[9] == 'A' && b[10] == 'V' && b[11] == 'E')) return null;
        int pos = 12;
        Integer fmtTag = null;
        Integer channels = null;
        Integer sampleRate = null;
        Integer bitsPerSample = null;
        Integer effectiveFormat = null;
        int dataPos = -1;
        int dataSize = -1;
        while (pos + 8 <= b.length) {
            String id = new String(b, pos, 4, StandardCharsets.US_ASCII);
            int size = leInt(b, pos + 4);
            int bodyPos = pos + 8;
            if (id.equals("fmt ")) {
                if (size >= 16) {
                    int tag = leShort(b, bodyPos);
                    int ch = leShort(b, bodyPos + 2);
                    int sr = leInt(b, bodyPos + 4);
                    int bps = leShort(b, bodyPos + 14);
                    fmtTag = tag;
                    channels = ch;
                    sampleRate = sr;
                    bitsPerSample = bps;
                    if (tag == 0xFFFE && size > 16) {
                        int sub = leShort(b, bodyPos + 24);
                        effectiveFormat = sub;
                    } else {
                        effectiveFormat = tag;
                    }
                }
            } else if (id.equals("data")) {
                dataPos = bodyPos;
                dataSize = size;
            }
            pos = bodyPos + size;
            if (size % 2 == 1) pos++;
        }
        WavInfo info = new WavInfo();
        if (fmtTag == null || channels == null || sampleRate == null || bitsPerSample == null
                || effectiveFormat == null || dataPos == -1) {
            info.supported = false;
            return info;
        }
        boolean supported = effectiveFormat == 1 && bitsPerSample == 16
                && (channels == 1 || channels == 2)
                && (sampleRate == 8000 || sampleRate == 16000);
        info.supported = supported;
        if (!supported) return info;
        info.sampleRate = sampleRate;
        info.channels = channels;
        info.bitsPerSample = bitsPerSample;
        info.dataPos = dataPos;
        info.dataSize = dataSize;
        return info;
    }

    private static int leShort(byte[] b, int off) {
        return (b[off] & 0xff) | ((b[off + 1] & 0xff) << 8);
    }

    private static int leInt(byte[] b, int off) {
        return (b[off] & 0xff) | ((b[off + 1] & 0xff) << 8)
                | ((b[off + 2] & 0xff) << 16) | ((b[off + 3] & 0xff) << 24);
    }
}

import sys
import os
import math
import struct
from array import array

LOW_FREQS = [697, 770, 852, 941]
HIGH_FREQS = [1209, 1336, 1477, 1633]
ALL_FREQS = LOW_FREQS + HIGH_FREQS

DIGIT_MAP = {
    (697, 1209): '1', (697, 1336): '2', (697, 1477): '3', (697, 1633): 'A',
    (770, 1209): '4', (770, 1336): '5', (770, 1477): '6', (770, 1633): 'B',
    (852, 1209): '7', (852, 1336): '8', (852, 1477): '9', (852, 1633): 'C',
    (941, 1209): '*', (941, 1336): '0', (941, 1477): '#', (941, 1633): 'D',
}

def parse_wav_info(path):
    try:
        with open(path, 'rb') as f:
            if f.read(4) != b'RIFF':
                return None
            f.read(4)  # size
            if f.read(4) != b'WAVE':
                return None

            fmt_channels = fmt_rate = fmt_bits = fmt_effective = None
            data_offset = data_size = None

            while True:
                chunk_id = f.read(4)
                if len(chunk_id) < 4:
                    break
                chunk_size = struct.unpack('<I', f.read(4))[0]

                if chunk_id == b'fmt ':
                    body = f.read(chunk_size)
                    if len(body) >= 16:
                        format_tag = struct.unpack('<H', body[0:2])[0]
                        channels = struct.unpack('<H', body[2:4])[0]
                        sample_rate = struct.unpack('<I', body[4:8])[0]
                        bits_per_sample = struct.unpack('<H', body[14:16])[0]
                        effective = format_tag
                        if format_tag == 0xFFFE and len(body) >= 26:
                            effective = struct.unpack('<H', body[24:26])[0]
                        fmt_channels = channels
                        fmt_rate = sample_rate
                        fmt_bits = bits_per_sample
                        fmt_effective = effective
                    if chunk_size % 2 == 1:
                        f.read(1)
                elif chunk_id == b'data':
                    data_offset = f.tell()
                    data_size = chunk_size
                    f.seek(chunk_size, 1)
                    if chunk_size % 2 == 1:
                        f.read(1)
                else:
                    f.seek(chunk_size, 1)
                    if chunk_size % 2 == 1:
                        f.read(1)
            if fmt_effective is None or data_offset is None:
                return None
            return {
                'channels': fmt_channels,
                'rate': fmt_rate,
                'bits': fmt_bits,
                'effective': fmt_effective,
                'data_offset': data_offset,
                'data_size': data_size,
            }
    except Exception:
        return None


def goertzel_power(samples, c):
    s1 = 0
    s2 = 0
    for x in samples:
        s = x + c * s1 - s2
        s2 = s1
        s1 = s
    return s1 * s1 + s2 * s2 - c * s1 * s2


def decode_file(filepath):
    info = parse_wav_info(filepath)
    if not info:
        return False
    if info['effective'] != 1 or info['bits'] != 16:
        return False
    channels = info['channels']
    rate = info['rate']
    if channels not in (1, 2) or rate not in (8000, 16000):
        return False

    N = rate // 50
    data_offset = info['data_offset']
    data_size = info['data_size']
    frames = data_size // (2 * channels)
    blocks = frames // N
    if blocks <= 0:
        blocks = 0

    with open(filepath, 'rb') as f:
        f.seek(data_offset)
        raw = f.read(data_size)
    arr = array('h')
    arr.frombytes(raw)
    if channels == 1:
        left = arr
    else:
        left = arr[0::channels]

    c_vals = {freq: 2.0 * math.cos(2.0 * math.pi * freq / rate) for freq in ALL_FREQS}

    labels = [None] * blocks
    thresh = 1_000_000 * N
    for i in range(blocks):
        start = i * N
        end = start + N
        if end > len(left):
            break
        block = left[start:end]
        E = 0
        for x in block:
            E += x * x
        if E < thresh:
            continue
        best_low_f = None
        best_low_r = -1.0
        for f in LOW_FREQS:
            P = goertzel_power(block, c_vals[f])
            r = 2.0 * P / (N * E)
            if r > best_low_r:
                best_low_r = r
                best_low_f = f
        best_high_f = None
        best_high_r = -1.0
        for f in HIGH_FREQS:
            P = goertzel_power(block, c_vals[f])
            r = 2.0 * P / (N * E)
            if r > best_high_r:
                best_high_r = r
                best_high_f = f
        if best_low_r >= 0.1 and best_high_r >= 0.1 and best_low_r + best_high_r >= 0.6:
            digit = DIGIT_MAP.get((best_low_f, best_high_f))
            if digit:
                labels[i] = digit

    # bridging based on original labels
    bridged = labels[:]
    for i in range(1, blocks - 1):
        if labels[i] is None and labels[i - 1] is not None and labels[i + 1] is not None and labels[i - 1] == labels[i + 1]:
            bridged[i] = labels[i - 1]

    presses = []
    digits_concat = []
    i = 0
    while i < blocks:
        if bridged[i] is None:
            i += 1
            continue
        digit = bridged[i]
        start_idx = i
        while i < blocks and bridged[i] == digit:
            i += 1
        end_idx = i - 1
        if end_idx - start_idx + 1 >= 2:
            start_ms = 20 * start_idx
            end_ms = 20 * (end_idx + 1)
            presses.append((digit, start_ms, end_ms))
            digits_concat.append(digit)

    return {
        'rate': rate,
        'channels': channels,
        'blocks': blocks,
        'presses': presses,
        'digits': ''.join(digits_concat),
    }


def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]
    entries = []
    try:
        for name in os.listdir(directory):
            if name.endswith('.wav'):
                full = os.path.join(directory, name)
                if os.path.isfile(full):
                    entries.append((name, full))
    except FileNotFoundError:
        return
    entries.sort(key=lambda x: x[0])

    out_blocks = []
    for name, full in entries:
        res = decode_file(full)
        if res is False:
            out_blocks.append(f"{name}: unsupported")
        else:
            lines = [f"{name}: {res['rate']} Hz, {res['channels']} ch, {res['blocks']} blocks"]
            for d, s, e in res['presses']:
                lines.append(f"{d} {s} {e}")
            lines.append(f"digits: {res['digits']}")
            out_blocks.append('\n'.join(lines))
    sys.stdout.write('\n\n'.join(out_blocks))


if __name__ == '__main__':
    main()

