char *read_file(const char *path, size_t *sz){
    FILE *f=fopen(path,"rb");
    if(!f) return NULL;
    fseek(f,0,SEEK_END); long l=ftell(f); rewind(f);
    char *buf=malloc(l+1);
    if(!buf){ fclose(f); return NULL;}
    fread(buf,1,l,f); buf[l]=0; fclose(f);
    if(sz) *sz=l;
    return buf;
}

/* very small JSON value extractor */
char *json_find_raw(const char *json,const char *key,int *out_len){
    char pat[256]; snprintf(pat,sizeof(pat),"\"%s\"",key);
    char *p=strstr(json,pat);
    if(!p) return NULL;
    p=strchr(p,':'); if(!p) return NULL; p++;
    while(*p && isspace((unsigned char)*p)) p++;
    if(*p=='"'){
        p++;
        char *start=p;
        char *q=start;
        while(*q){
            if(*q=='\\'){ q+=2; continue; }
            if(*q=='"') break;
            q++;
        }
        *out_len=q-start;
        char *res=malloc(*out_len+1);
        memcpy(res,start,*out_len); res[*out_len]=0;
        return res;
    }
    /* array/object */
    if(*p=='['||*p=='{'){
        char c=*p; int depth=0; char *s=p; char *q=p;
        while(*q){ if(*q==c) depth++; else if(*q==']'||*q=='}') depth--; if(depth==0) break; q++; }
        int len=q-s+1; char *res=malloc(len+1); memcpy(res,s,len); res[len]=0;
        *out_len=len; return res;
    }
    return NULL;
}

/* strip BOM */
void strip_bom(char *s){ if((unsigned char)s[0]==0xEF && (unsigned char)s[1]==0xBB && (unsigned char)s[2]==0xBF) memmove(s,s+3,strlen(s+3)+1); }

/* CSV very small parser, assumes first line header */
void parse_inventory(const char *path){
    char *buf=read_file(path,NULL);
    if(!buf) return;
    strip_bom(buf);
    char *p=buf;
    /* skip header */
    char *line=strtok(buf,"\r\n");
    while(line && *line){ line=strtok(NULL,"\r\n"); if(!line) break; }
    /* simple parse */
    while(line && n_items<MAX_ITEMS){
        char sku[256]={0}, name[4096]={0}, cur[8]={0};
        int price=0, stock=0;
        int col=0;
        char *field=line;
        char *tmp=strdup(line);
        char *tok=strtok(tmp,",");
        while(tok && col<5){
            /* crude unquote */
            if(tok[0]=='"'){
                char *end=strchr(tok+1,'"');
                if(end){ *end=0; tok++; }
            }
            if(col==0) strncpy(sku,tok,sizeof(sku)-1);
            else if(col==1) strncpy(name,tok,sizeof(name)-1);
            else if(col==2) price=atoi(tok);
            else if(col==3) strncpy(cur,tok,sizeof(cur)-1);
            else if(col==4) stock=atoi(tok);
            col++; tok=strtok(NULL,",");
        }
        free(tmp);
        if(col>=5){
            strncpy(items[n_items].sku,sku,sizeof(items[n_items].sku)-1);
            strncpy(items[n_items].name,name,sizeof(items[n_items].name)-1);
            items[n_items].price_cents=price;
            strncpy(items[n_items].currency,cur,sizeof(items[n_items].currency)-1);
            items[n_items].stock=stock;
            n_items++;
        }
        line=strtok(NULL,"\r\n");
    }
    free(buf);
}

/* rates */
