    char *r=strstr(buf,"\"rates\"");
    if(r){
        char *b=strchr(r,'{'); if(b){
            char *q=b+1;
            while(*q && *q!='}'){
                if(*q=='"'){
                    char cur[8]={0}; int i=0; q++; while(*q && *q!='"' && i<7){ cur[i++]=*q++; } cur[i]=0;
                    q++; while(isspace(*q)||*q==':') q++;
                    long long v=atoll(q);
                    strncpy(rates[n_rates].cur,cur,sizeof(rates[n_rates].cur)-1);
                    rates[n_rates].rate=v;
                    n_rates++;
                } else q++;
            }
        }
    }
    free(buf);
}

/* json escape for output */
char *json_escape(const char *s){
    size_t n=strlen(s); char *out=malloc(n*6+1); char *o=out;
    for(size_t i=0;i<n;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='"'){ *o++='\\'; *o++='"'; }
        else if(c=='\\'){ *o++='\\'; *o++='\\'; }
        else if(c=='\b'){ *o++='\\'; *o++='b'; }
        else if(c=='\f'){ *o++='\\'; *o++='f'; }
        else if(c=='\n'){ *o++='\\'; *o++='n'; }
        else if(c=='\r'){ *o++='\\'; *o++='r'; }
        else if(c=='\t'){ *o++='\\'; *o++='t'; }
        else if(c<0x20){ sprintf(o,"\\u%04x",c); o+=6; }
        else *o++=c;
    }
    *o=0; return out;
}

/* find rate */
long long find_rate(const char *cur){
    for(int i=0;i<n_rates;i++) if(strcmp(rates[i].cur,cur)==0) return rates[i].rate;
    return 1000000;
}

/* inventory lookup result */
