    return strdup(buf);
}

/* convert */
char *tool_convert(int amount_cents,const char *from,const char *to){
    long long rf=find_rate(from); long long rt=find_rate(to);
    __int128 num=( (__int128)2*amount_cents*rt + rf);
    __int128 den=( (__int128)2*rf);
    long long conv=(long long)(num/den);
    char buf[256]; snprintf(buf,sizeof(buf),"{\"amount_cents\":%lld,\"currency\":\"%s\"}",conv,to);
    return strdup(buf);
}

/* http */
int http_post(const char *host,int port,const char *path,const char *api_key,const char *body,char **resp_body,int *status){
    struct addrinfo hints={0},*res; hints.ai_family=AF_UNSPEC; hints.ai_socktype=SOCK_STREAM;
    char portstr[16]; snprintf(portstr,sizeof(portstr),"%d",port);
    if(getaddrinfo(host,portstr,&hints,&res)!=0) return -1;
    int s=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(connect(s,res->ai_addr,res->ai_addrlen)!=0){ close(s); freeaddrinfo(res); return -1; }
    char req[65536];
    int len=snprintf(req,sizeof(req),
        "POST %s HTTP/1.1\r\nHost: %s:%d\r\nAuthorization: Bearer %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
        path,host,port,api_key,strlen(body),body);
    send(s,req,len,0);
    char buf[MAX_BUF]; int off=0; int total=0;
    while(1){ int r=recv(s,buf+total,MAX_BUF-total-1,0); if(r<=0) break; total+=r; buf[total]=0; if(strstr(buf,"\r\n\r\n")) break; }
    close(s); freeaddrinfo(res);
    char *hdr_end=strstr(buf,"\r\n\r\n");
    if(!hdr_end){ return -1; }
    int body_start=hdr_end- buf +4;
    sscanf(buf,"HTTP/1.1 %d",status);
    char *cl=strstr(buf,"Content-Length:"); int clen=0; if(cl) sscanf(cl,"Content-Length: %d",&clen);
    int body_len=total-body_start; if(clen && clen< body_len) body_len=clen;
    *resp_body=malloc(body_len+1); memcpy(*resp_body,buf+body_start,body_len); (*resp_body)[body_len]=0;
    return 0;
}

