    return NULL;
}

/* unescape json string (basic) */
char *json_unescape(const char *s){
    char *out=malloc(strlen(s)+1); char *o=out; const char *p=s;
    while(*p){ if(*p=='\\'){ p++; if(*p) *o++=*p++; } else *o++=*p++; } *o=0; return out;
}

