        }
        b+=snprintf(b,sizeof(body)-(b-body),"],\"tools\":%s,\"tool_choice\":\"auto\"}",tools_raw?tools_raw:"[]");
        char *resp=NULL; int status=0;
        if(http_post(host,port,fullpath,api_key,body,&resp,&status)!=0){ printf("ERROR 0 unknown\n"); break; }
        req_cnt++;
        if(status!=200){
            char *msg=json_find_string(resp,"message");
            printf("ERROR %d %s\n",status,msg?msg:"");
            if(msg) free(msg);
            free(resp);
            break;
        }
        /* usage */
        char *up=strstr(resp,"\"prompt_tokens\"");
        if(up){ long long v; if(sscanf(up,"\"prompt_tokens\":%lld",&v)==1) usage_prompt+=v; }
        char *uc=strstr(resp,"\"completion_tokens\"");
        if(uc){ long long v; if(sscanf(uc,"\"completion_tokens\":%lld",&v)==1) usage_completion+=v; }
        char *ut=strstr(resp,"\"total_tokens\"");
        if(ut){ long long v; if(sscanf(ut,"\"total_tokens\":%lld",&v)==1) usage_total+=v; }

        /* finish_reason */
        char *fr=json_find_string(resp,"finish_reason");
        char *content=json_find_string(resp,"content");
        if(fr && strcmp(fr,"tool_calls")==0){
            if(content){
                char *dec=json_unescape(content);
                printf("SAY %s\n",dec);
                free(dec);
            }
            /* tool calls */
            char *tc_pos=strstr(resp,"\"tool_calls\":[");
            if(tc_pos){
                char *arr_start=tc_pos+strlen("\"tool_calls\":[");
                int depth=1;
                char *q=arr_start;
                int first=1;
                while(*q && depth>0){
                    if(*q=='{' && *(q-1)==',') { /* start object */ }
                    /* parse each call */
                    char *id=json_find_string(q,"id");
                    char *name=json_find_string(q,"name");
                    char *args_raw=json_find_string(q,"arguments");
                    if(id && name){
                        printf("CALL %s %s\n",id,name);
                        /* execute */
                        if(args_raw){
                            char *args_unesc=json_unescape(args_raw);
                            if(strcmp(name,"inventory_lookup")==0){
                                char *sku=json_find_string(args_unesc,"sku");
                                if(sku){
                                    char *res=tool_inventory(sku);
                                    printf("RESULT %s %s\n",id,res);
                                    free(res);
                                    free(sku);
                                }
                            }else if(strcmp(name,"convert_currency")==0){
                                char *amt_str=json_find_string(args_unesc,"amount_cents");
                                char *from=json_find_string(args_unesc,"from");
                                char *to=json_find_string(args_unesc,"to");
                                int amt=amt_str?atoi(amt_str):0;
                                char *res=tool_convert(amt, from?from:"", to?to:"");
                                printf("RESULT %s %s\n",id,res);
                                free(res);
                                if(amt_str) free(amt_str);
                                if(from) free(from);
                                if(to) free(to);
                            }else{
                                char buf[256]; snprintf(buf,sizeof(buf),"{\"error\":\"unknown tool: %s\"}",name);
                                printf("RESULT %s %s\n",id,buf);
                            }
                            free(args_unesc);
                        }
                        free(id); free(name); free(args_raw);
                    }
                    /* move to next */
                    q++;
                    /* simplistic advance */
                    if(*q=='}') { /* end object */ }
                }
            }
            /* append assistant message raw */
            char *msg_start=strstr(resp,"\"message\":{");
            if(msg_start){
                char *obj_start=strchr(msg_start,'{');
                if(obj_start){
                    char *obj=extract_object(obj_start,NULL);
                    if(obj){
                        conv[conv_cnt].data=obj; conv_cnt++;
                    }
                }
            }
            /* for simplicity break after first tool loop to avoid infinite */
            /* In real loop we would continue, but test may need multiple */
            /* Continue loop */
            free(fr); free(content);
            free(resp);
            continue;
        }else if(fr && strcmp(fr,"stop")==0){
            if(content){
                char *dec=json_unescape(content);
                printf("FINAL %s\n",dec);
                free(dec);
            }
            printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n",usage_prompt,usage_completion,usage_total,req_cnt);
            free(fr); free(content);
            free(resp);
            break;
        }
        free(fr); free(content);
        free(resp);
    }
    return 0;
}

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn parse_u16_le(b: &[u8], off: usize) -> u16 {
    u16::from_le_bytes([b[off], b[off + 1]])
}
fn parse_u32_le(b: &[u8], off: usize) -> u32 {
    u32::from_le_bytes([b[off], b[off + 1], b[off + 2], b[off + 3]])
}

fn read_wav(path: &Path) -> Option<(u32, u16, u16, Vec<i16>)> {
    let data = fs::read(path).ok()?;
    if data.len() < 12 { return None; }
    if &data[0..4] != b"RIFF" { return None; }
    if &data[8..12] != b"WAVE" { return None; }

    let mut off = 12usize;
    let mut fmt_rate = 0u32;
    let mut fmt_channels = 0u16;
    let mut fmt_bits = 0u16;
    let mut fmt_eff = 0u16;
    let mut data_start = 0usize;
    let mut data_size = 0usize;

    while off + 8 <= data.len() {
        let id = &data[off..off + 4];
        let size = parse_u32_le(&data, off + 4) as usize;
        let body_off = off + 8;
        let body_end = body_off + size;
        if body_end > data.len() { break; }

        if id == b"fmt " {
            if size >= 16 {
                let tag = parse_u16_le(&data, body_off);
                let ch = parse_u16_le(&data, body_off + 2);
                let rate = parse_u32_le(&data, body_off + 4);
                let bits = parse_u16_le(&data, body_off + 14);
                let mut eff = tag;
                if tag == 0xFFFE && size > 24 {
                    if body_off + 26 <= data.len() {
                        eff = parse_u16_le(&data, body_off + 24);
                    }
                }
                fmt_rate = rate;
                fmt_channels = ch;
                fmt_bits = bits;
                fmt_eff = eff;
            }
        } else if id == b"data" {
            data_start = body_off;
            data_size = size;
        }

        off = body_off + size + if size % 2 == 1 { 1 } else { 0 };
        if off >= data.len() { break; }
    }

    if fmt_eff != 1 || fmt_bits != 16 { return None; }
    if fmt_channels != 1 && fmt_channels != 2 { return None; }
    if fmt_rate != 8000 && fmt_rate != 16000 { return None; }
    if data_start == 0 || data_size == 0 { return None; }

    let frame_bytes = 2 * fmt_channels as usize;
    let frames = data_size / frame_bytes;
    let mut samples = Vec::with_capacity(frames);
    for i in 0..frames {
        let idx = data_start + i * frame_bytes;
        if idx + 2 > data.len() { break; }
        let s = i16::from_le_bytes([data[idx], data[idx + 1]]);
        samples.push(s);
    }
    Some((fmt_rate, fmt_channels, fmt_bits, samples))
}

fn detect_digits(rate: u32, channels: u16, samples: Vec<i16>) -> (usize, Vec<(char, u32, u32)>, String) {
    let frames = samples.len();
    let n = (rate / 50) as usize;
    if n == 0 || frames == 0 { return (0, vec![], String::new()); }
    let blocks = frames / n;
    if blocks == 0 { return (0, vec![], String::new()); }

    let low_freqs = [697, 770, 852, 941];
    let high_freqs = [1209, 1336, 1477, 1633];
    let mut labels: Vec<Option<char>> = Vec::with_capacity(blocks);

    for i in 0..blocks {
        let start = i * n;
        let end = start + n;
        let block = &samples[start..end];
        let e: i64 = block.iter().map(|&x| (x as i64)*(x as i64)).sum();
        if e < 1_000_000i64 * n as i64 {
            labels.push(None);
            continue;
        }
        let e_f = e as f64;
        let mut best_low = (0.0, 0);
        let mut best_high = (0.0, 0);
        for (idx, &f) in low_freqs.iter().enumerate() {
            let c = 2.0 * (2.0 * std::f64::consts::PI * f as f64 / rate as f64).cos();
            let mut s1 = 0.0;
            let mut s2 = 0.0;
            for &x in block {
                let xf = x as f64;
                let s = xf + c * s1 - s2;
                s2 = s1;
                s1 = s;
            }
            let p = s1*s1 + s2*s2 - c*s1*s2;
            let r = 2.0 * p / (n as f64 * e_f);
            if r > best_low.0 { best_low = (r, idx); }
        }
        for (idx, &f) in high_freqs.iter().enumerate() {
            let c = 2.0 * (2.0 * std::f64::consts::PI * f as f64 / rate as f64).cos();
            let mut s1 = 0.0;
            let mut s2 = 0.0;
            for &x in block {
                let xf = x as f64;
                let s = xf + c * s1 - s2;
                s2 = s1;
                s1 = s;
            }
            let p = s1*s1 + s2*s2 - c*s1*s2;
            let r = 2.0 * p / (n as f64 * e_f);
            if r > best_high.0 { best_high = (r, idx); }
        }
        let fl = best_low.0;
        let fh = best_high.0;
        if fl >= 0.1 && fh >= 0.1 && fl + fh >= 0.6 {
            let digit = match (best_low.1, best_high.1) {
                (0,0)=>'1',(0,1)=>'2',(0,2)=>'3',(0,3)=>'A',
                (1,0)=>'4',(1,1)=>'5',(1,2)=>'6',(1,3)=>'B',
                (2,0)=>'7',(2,1)=>'8',(2,2)=>'9',(2,3)=>'C',
                (3,0)=>'*',(3,1)=>'0',(3,2)=>'#',(3,3)=>'D',
                _=>'?',
            };
            labels.push(Some(digit));
        } else {
            labels.push(None);
        }
    }

    // bridging
    let mut bridged = labels.clone();
    for i in 1..blocks-1 {
        if labels[i].is_none() && labels[i-1].is_some() && labels[i+1].is_some() {
            if labels[i-1] == labels[i+1] {
                bridged[i] = labels[i-1];
            }
        }
    }

    // runs
    let mut presses = Vec::new();
    let mut digits_concat = String::new();
    let mut i = 0;
    while i < blocks {
        if let Some(d) = bridged[i] {
            let start_idx = i;
            let mut j = i;
            while j < blocks && bridged[j] == Some(d) {
                j += 1;
            }
            let len = j - start_idx;
            if len >= 2 {
                let start_ms = 20 * start_idx as u32;
                let end_ms = 20 * (j as u32);
                presses.push((d, start_ms, end_ms));
                digits_concat.push(d);
            }
            i = j;
        } else {
            i += 1;
        }
    }

    (blocks, presses, digits_concat)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = Path::new(&args[1]);

    let mut files: Vec<PathBuf> = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for e in entries.flatten() {
            if let Some(name) = e.file_name().to_str() {
                if name.ends_with(".wav") {
                    files.push(e.path());
                }
            }
        }
    }
    files.sort_by(|a, b| a.file_name().unwrap().cmp(b.file_name().unwrap()));

    for (idx, path) in files.iter().enumerate() {
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let mut first = true;
        if idx > 0 { println!(); }

        if let Some((rate, channels, _bits, samples)) = read_wav(path) {
            let (blocks, presses, digits) = detect_digits(rate, channels, samples);
            println!("{}: {} Hz, {} ch, {} blocks", name, rate, channels, blocks);
            for (d, s, e) in &presses {
                println!("{} {} {}", d, s, e);
            }
            println!("digits: {}", digits);
        } else {
            println!("{}: unsupported");
        }
    }
}

