#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <dirent.h>
#include <math.h>
#include <sys/types.h>

static uint16_t le16(const unsigned char *p){ return (uint16_t)p[0] | ((uint16_t)p[1]<<8); }
static uint32_t le32(const unsigned char *p){ return (uint32_t)p[0] | ((uint32_t)p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24); }

static int ends_with_wav(const char *name){
    size_t l = strlen(name);
    return l>=4 && strcmp(name+l-4,".wav")==0;
}

static int cmp_str(const void *a, const void *b){
    return strcmp(*(const char**)a, *(const char**)b);
}

int main(int argc, char **argv){
    if(argc<2) return 0;
    const char *dir = argv[1];
    DIR *d = opendir(dir);
    if(!d) return 0;
    struct dirent *de;
    char **files = NULL;
    size_t nfiles=0;
    while((de = readdir(d))!=NULL){
        if(de->d_name[0]=='.') continue;
        if(!ends_with_wav(de->d_name)) continue;
        files = realloc(files, sizeof(char*)*(nfiles+1));
        files[nfiles] = strdup(de->d_name);
        nfiles++;
    }
    closedir(d);
    qsort(files, nfiles, sizeof(char*), cmp_str);

    int first_file = 1;
    for(size_t fi=0; fi<nfiles; ++fi){
        char path[1024];
        snprintf(path,sizeof(path),"%s/%s",dir,files[fi]);
        FILE *f = fopen(path,"rb");
        if(!f){ first_file?0:printf("\n"); continue; }
        unsigned char hdr[12];
        if(fread(hdr,1,12,f)!=12){ fclose(f); first_file?0:printf("\n"); continue; }
        int is_riff = memcmp(hdr,"RIFF",4)==0 && memcmp(hdr+8,"WAVE",4)==0;
        int supported = 0;
        int rate=0, channels=0, bits=0;
        int num_blocks=0;
        int16_t *left = NULL;
        size_t left_frames=0;
        int fmt_found=0, data_found=0;
        uint32_t fmt_tag=0, fmt_channels=0, fmt_rate=0, fmt_bits=0;
        uint32_t data_size=0;
        unsigned char *data_buf=NULL;

        if(is_riff){
            size_t pos=12;
            unsigned char id[4];
            uint32_t sz;
            int have_fmt=0, have_data=0;
            uint8_t *fmt_body=NULL;
            uint32_t fmt_body_sz=0;
            while(fread(id,1,4,f)==4){
                if(fread(&sz,4,1,f)!=1) break;
                uint32_t sz_le = le32((unsigned char*)&sz);
                if(memcmp(id,"fmt ",4)==0){
                    fmt_body_sz = sz_le;
                    fmt_body = malloc(fmt_body_sz);
                    fread(fmt_body,1,fmt_body_sz,f);
                    if(fmt_body_sz>=16){
                        uint16_t tag = le16(fmt_body);
                        uint16_t ch = le16(fmt_body+2);
                        uint32_t sr = le32(fmt_body+4);
                        uint16_t bps = le16(fmt_body+14);
                        uint16_t eff = tag;
                        if(tag==0xFFFE && fmt_body_sz>=26){
                            eff = le16(fmt_body+24);
                        }
                        fmt_tag = eff;
                        fmt_channels = ch;
                        fmt_rate = sr;
                        fmt_bits = bps;
                        have_fmt=1;
                    }
                    if(fmt_body_sz%2==1) fseek(f,1,SEEK_CUR);
                }else if(memcmp(id,"data",4)==0){
                    data_size = sz_le;
                    data_buf = malloc(data_size);
                    fread(data_buf,1,data_size,f);
                    have_data=1;
                    if(data_size%2==1) fseek(f,1,SEEK_CUR);
                }else{
                    fseek(f, sz_le + (sz_le%2), SEEK_CUR);
                }
                if(have_fmt && have_data) break;
            }
            if(have_fmt){
                if(fmt_tag==1 && fmt_bits==16 && (fmt_rate==8000 || fmt_rate==16000) && (fmt_channels==1 || fmt_channels==2)){
                    supported=1;
                    rate = fmt_rate;
                    channels = fmt_channels;
                    bits = fmt_bits;
                    if(have_data && data_buf){
                        size_t bytes_per_frame = 2*channels;
                        left_frames = data_size / bytes_per_frame;
                        left = malloc(left_frames * sizeof(int16_t));
                        for(size_t i=0;i<left_frames;i++){
                            size_t off = i*bytes_per_frame;
                            int16_t s;
                            memcpy(&s, data_buf+off, 2);
                            left[i]=s;
                        }
                        int N = rate/50;
                        if(N>0) num_blocks = (int)(left_frames / N);
                    }
                }
            }
            free(fmt_body);
            free(data_buf);
        }
        fclose(f);

        if(!first_file) printf("\n");
        first_file=0;
        if(!supported){
            printf("%s: unsupported", files[fi]);
        }else{
            printf("%s: %d Hz, %d ch, %d blocks", files[fi], rate, channels, num_blocks);
            if(num_blocks>0 && left){
                int N = rate/50;
                int freqs[8] = {697,770,852,941,1209,1336,1477,1633};
                double c[8];
                for(int i=0;i<8;i++) c[i]=2.0*cos(2.0*M_PI*freqs[i]/rate);
                int *labels = calloc(num_blocks, sizeof(int));
                for(int b=0;b<num_blocks;b++){
                    long long E=0;
                    for(int n=0;n<N;n++){
                        int idx = b*N + n;
                        int32_t x = left[idx];
                        E += (long long)x*x;
                    }
                    if(E < 1000000LL * N){
                        labels[b] = -1;
                        continue;
                    }
                    double r[8];
                    for(int k=0;k<8;k++){
                        double s1=0,s2=0;
                        for(int n=0;n<N;n++){
                            int idx = b*N + n;
                            double x = left[idx];
                            double s = x + c[k]*s1 - s2;
                            s2 = s1;
                            s1 = s;
                        }
                        double P = s1*s1 + s2*s2 - c[k]*s1*s2;
                        r[k] = 2.0*P / (N * (double)E);
                    }
                    int best_low=0, best_high=4;
                    double best_low_r=r[0], best_high_r=r[4];
                    for(int k=1;k<4;k++) if(r[k]>best_low_r){best_low_r=r[k];best_low=k;}
                    for(int k=5;k<8;k++) if(r[k]>best_high_r){best_high_r=r[k];best_high=k;}
                    if(best_low_r>=0.1 && best_high_r>=0.1 && best_low_r+best_high_r>=0.6){
                        int row = best_low;
                        int col = best_high-4;
                        char dig;
                        static const char map[4][4] = {
                            {'1','2','3','A'},
                            {'4','5','6','B'},
                            {'7','8','9','C'},
                            {'*','0','#','D'}
                        };
                        dig = map[row][col];
                        labels[b]=dig;
                    }else{
                        labels[b]=-1;
                    }
                }
                /* bridging */
                int *final_labels = malloc(num_blocks*sizeof(int));
                memcpy(final_labels, labels, num_blocks*sizeof(int));
                for(int i=0;i<num_blocks;i++){
                    if(labels[i]==-1 && i>0 && i<num_blocks-1){
                        if(labels[i-1]!=-1 && labels[i+1]!=-1 && labels[i-1]==labels[i+1]){
                            final_labels[i]=labels[i-1];
                        }
                    }
                }
                /* runs */
                char digits_buf[4096]={0};
                size_t dig_len=0;
                int i=0;
                while(i<num_blocks){
                    if(final_labels[i]!=-1){
                        int start=i;
                        char d = (char)final_labels[i];
                        while(i+1<num_blocks && final_labels[i+1]==d) i++;
                        int end=i;
                        int len = end-start+1;
                        if(len>=2){
                            int start_ms = 20*start;
                            int end_ms = 20*(end+1);
                            printf("\n%c %d %d", d, start_ms, end_ms);
                            if(dig_len<sizeof(digits_buf)-1) digits_buf[dig_len++]=d;
                        }
                    }
                    i++;
                }
                printf("\ndigits: %s", digits_buf);
                free(labels);
                free(final_labels);
            }else{
                printf("\ndigits: ");
            }
            free(left);
        }
        for(size_t k=0;k<nfiles;k++) free(files[k]);
    }
    free(files);
    return 0;
}

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <dirent.h>
#include <math.h>

static uint16_t le16(const unsigned char *p){ return (uint16_t)p[0] | ((uint16_t)p[1]<<8); }
static uint32_t le32(const unsigned char *p){ return (uint32_t)p[0] | ((uint32_t)p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24); }

static int ends_with_wav(const char *name){
    size_t l = strlen(name);
    return l>=4 && strcmp(name+l-4,".wav")==0;
}

int main(int argc, char **argv){
    if(argc<2) return 0;
    const char *dir = argv[1];
    DIR *d = opendir(dir);
    if(!d) return 0;

    char **files = NULL;
    size_t nfiles = 0;
    struct dirent *de;
    while((de = readdir(d))!=NULL){
        if(!ends_with_wav(de->d_name)) continue;
        files = realloc(files, sizeof(char*)*(nfiles+1));
        files[nfiles++] = strdup(de->d_name);
    }
    closedir(d);
    qsort(files, nfiles, sizeof(char*), (int(*)(const void*,const void*))strcmp);

    int first_file = 1;
    int freqs[8] = {697,770,852,941,1209,1336,1477,1633};
    const char map[4][4] = {
        {'1','2','3','A'},
        {'4','5','6','B'},
        {'7','8','9','C'},
        {'*','0','#','D'}
    };

    for(size_t fi=0; fi<nfiles; ++fi){
        char path[1024];
        snprintf(path,sizeof(path),"%s/%s",dir,files[fi]);
        FILE *f = fopen(path,"rb");
        int supported = 0;
        int rate=0, channels=0, num_blocks=0;
        int16_t *left = NULL;
        size_t left_frames = 0;

        if(f){
            unsigned char hdr[12];
            if(fread(hdr,1,12,f)==12 && memcmp(hdr,"RIFF",4)==0 && memcmp(hdr+8,"WAVE",4)==0){
                uint16_t fmt_tag=0, fmt_channels=0, fmt_bits=0;
                uint32_t fmt_rate=0;
                int have_fmt=0, have_data=0;
                uint32_t data_size=0;
                unsigned char *data_buf=NULL;

                unsigned char id[4];
                while(fread(id,1,4,f)==4){
                    unsigned char szb[4];
                    if(fread(szb,1,4,f)!=4) break;
                    uint32_t sz = le32(szb);
                    if(memcmp(id,"fmt ",4)==0){
                        unsigned char *body = malloc(sz);
                        if(body && fread(body,1,sz,f)==sz && sz>=16){
                            uint16_t tag = le16(body);
                            uint16_t ch = le16(body+2);
                            uint32_t sr = le32(body+4);
                            uint16_t bps = le16(body+14);
                            uint16_t eff = tag;
                            if(tag==0xFFFE && sz>=26) eff = le16(body+24);
                            if(eff==1 && bps==16 && (sr==8000 || sr==16000) && (ch==1 || ch==2)){
                                fmt_tag = 1;
                                fmt_channels = ch;
                                fmt_rate = sr;
                                fmt_bits = bps;
                                have_fmt = 1;
                                rate = sr;
                                channels = ch;
                            }
                        }
                        free(body);
                    }else if(memcmp(id,"data",4)==0){
                        data_size = sz;
                        data_buf = malloc(data_size);
                        if(data_buf) fread(data_buf,1,data_size,f);
                        have_data = 1;
                    }else{
                        fseek(f, sz + (sz&1), SEEK_CUR);
                    }
                    if(sz%2) fseek(f,1,SEEK_CUR);
                    if(have_fmt && have_data) break;
                }
                if(have_fmt && data_buf && fmt_tag==1){
                    supported = 1;
                    size_t bytes_per_frame = 2*channels;
                    left_frames = data_size / bytes_per_frame;
                    left = malloc(left_frames * sizeof(int16_t));
                    for(size_t i=0;i<left_frames;i++){
                        size_t off = i*bytes_per_frame;
                        int16_t s;
                        memcpy(&s, data_buf+off, 2);
                        left[i]=s;
                    }
                    int N = rate/50;
                    if(N>0) num_blocks = (int)(left_frames / N);
                    free(data_buf);
                }
            }
            fclose(f);
        }

        if(!first_file) printf("\n");
        first_file = 0;

        if(!supported){
            printf("%s: unsupported", files[fi]);
        }else{
            printf("%s: %d Hz, %d ch, %d blocks", files[fi], rate, channels, num_blocks);
            if(num_blocks>0 && left){
                int N = rate/50;
                double c[8];
                for(int i=0;i<8;i++) c[i]=2.0*cos(2.0*M_PI*freqs[i]/rate);
                int *labels = calloc(num_blocks, sizeof(int));
                for(int b=0;b<num_blocks;b++){
                    long long E = 0;
                    for(int n=0;n<N;n++){
                        int32_t x = left[b*N + n];
                        E += (long long)x*x;
                    }
                    if(E < 1000000LL * N){
                        labels[b] = -1;
                        continue;
                    }
                    double r[8];
                    for(int k=0;k<8;k++){
                        double s1=0.0, s2=0.0;
                        for(int n=0;n<N;n++){
                            double x = (double)left[b*N + n];
                            double s = x + c[k]*s1 - s2;
                            s2 = s1;
                            s1 = s;
                        }
                        double P = s1*s1 + s2*s2 - c[k]*s1*s2;
                        r[k] = 2.0*P / (N * (double)E);
                    }
                    int best_low=0; double best_low_r=r[0];
                    for(int k=1;k<4;k++) if(r[k]>best_low_r){best_low_r=r[k];best_low=k;}
                    int best_high=4; double best_high_r=r[4];
                    for(int k=5;k<8;k++) if(r[k]>best_high_r){best_high_r=r[k];best_high=k;}
                    if(best_low_r>=0.1 && best_high_r>=0.1 && best_low_r+best_high_r>=0.6){
                        char dig = map[best_low][best_high-4];
                        labels[b]=(int)dig;
                    }else{
                        labels[b]=-1;
                    }
                }
                int *final_labels = malloc(num_blocks*sizeof(int));
                memcpy(final_labels, labels, num_blocks*sizeof(int));
                for(int i=0;i<num_blocks;i++){
                    if(labels[i]==-1 && i>0 && i<num_blocks-1){
                        if(labels[i-1]!=-1 && labels[i+1]!=-1 && labels[i-1]==labels[i+1]){
                            final_labels[i]=labels[i-1];
                        }
                    }
                }
                char digits_buf[4096]={0};
                size_t dig_len=0;
                int i=0;
                while(i<num_blocks){
                    if(final_labels[i]!=-1){
                        int start=i;
                        char d = (char)final_labels[i];
                        while(i+1<num_blocks && final_labels[i+1]==d) i++;
                        int end=i;
                        int len = end-start+1;
                        if(len>=2){
                            int start_ms = 20*start;
                            int end_ms = 20*(end+1);
                            printf("\n%c %d %d", d, start_ms, end_ms);
                            if(dig_len<sizeof(digits_buf)-1) digits_buf[dig_len++]=d;
                        }
                    }
                    i++;
                }
                printf("\ndigits: %s", digits_buf);
                free(labels);
                free(final_labels);
            }else{
                printf("\ndigits: ");
            }
            free(left);
        }
    }
    for(size_t i=0;i<nfiles;i++) free(files[i]);
    free(files);
    return 0;
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use serde_json::{Value, json};

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        return;
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    // load task
    let task_path = format!("{}/task.json", data_dir);
    let task_str = fs::read_to_string(&task_path).unwrap();
    let task_val: Value = serde_json::from_str(&task_str).unwrap();
    let api_key = task_val["api_key"].as_str().unwrap().to_string();
    let model = task_val["model"].as_str().unwrap().to_string();
    let system = task_val["system"].as_str().unwrap().to_string();
    let user = task_val["user"].as_str().unwrap().to_string();
    let tools_val = task_val["tools"].clone();

    // inventory
    let inv_path = format!("{}/inventory.csv", data_dir);
    let inv_bytes = fs::read(&inv_path).unwrap();
    let inv_text = String::from_utf8_lossy(&inv_bytes).into_owned();
    let inventory = parse_inventory(&inv_text);

    // rates
    let rates_path = format!("{}/rates.json", data_dir);
    let rates_str = fs::read_to_string(&rates_path).unwrap();
    let rates_val: Value = serde_json::from_str(&rates_str).unwrap();
    let rates_map: HashMap<String, u64> = rates_val["rates"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), v.as_u64().unwrap()))
        .collect();

    // parse base url
    let (host, port, req_path) = parse_base_url(base_url);

    let mut messages: Vec<Value> = vec![
        json!({"role":"system","content":system}),
        json!({"role":"user","content":user}),
    ];

    let mut prompt_sum: u64 = 0;
    let mut completion_sum: u64 = 0;
    let mut total_sum: u64 = 0;
    let mut requests: u64 = 0;
    let mut out_lines: Vec<String> = Vec::new();

    loop {
        // build request
        let req_body_val = json!({
            "model": model,
            "messages": messages,
            "tools": tools_val,
            "tool_choice": "auto"
        });
        let req_body = serde_json::to_string(&req_body_val).unwrap();
        requests += 1;

        let request = format!(
            "POST {} HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            req_path, host, api_key, req_body.len(), req_body
        );

        let mut stream = match TcpStream::connect((host.as_str(), port)) {
            Ok(s) => s,
            Err(_) => {
                out_lines.push(format!("ERROR 0 connection failed"));
                break;
            }
        };
        stream.write_all(request.as_bytes()).unwrap();
        let mut resp_bytes = Vec::new();
        stream.read_to_end(&mut resp_bytes).unwrap();
        let resp_str = String::from_utf8_lossy(&resp_bytes);
        // parse status
        let mut parts = resp_str.split("\r\n");
        let status_line = parts.next().unwrap_or("");
        let status_code: u16 = status_line.split(' ').nth(1).unwrap_or("0").parse().unwrap_or(0);
        // headers
        let mut headers = String::new();
        for line in parts {
            if line.is_empty() { break; }
            headers.push_str(line);
            headers.push('\n');
        }
        // body
        let header_end = resp_str.find("\r\n\r\n").unwrap_or(0) + 4;
        let body = &resp_str[header_end..];
        if status_code != 200 {
            // try parse error json
            let err_msg = if let Ok(v) = serde_json::from_str::<Value>(body) {
                v.get("error").and_then(|e| e.get("message")).and_then(|m| m.as_str()).unwrap_or("").to_string()
            } else {
                "".to_string()
            };
            out_lines.push(format!("ERROR {} {}", status_code, err_msg));
            for l in out_lines.iter() { println!("{}", l); }
            return;
        }
        let resp_val: Value = serde_json::from_str(body).unwrap();
        // usage
        if let Some(u) = resp_val.get("usage") {
            if let Some(p) = u.get("prompt_tokens").and_then(|v| v.as_u64()) { prompt_sum += p; }
            if let Some(c) = u.get("completion_tokens").and_then(|v| v.as_u64()) { completion_sum += c; }
            if let Some(t) = u.get("total_tokens").and_then(|v| v.as_u64()) { total_sum += t; }
        }
        let choices = resp_val["choices"].as_array().unwrap();
        let choice = &choices[0];
        let finish_reason = choice["finish_reason"].as_str().unwrap_or("");
        let msg_val = &choice["message"];
        let content_opt = msg_val.get("content").and_then(|v| if v.is_null() { None } else { v.as_str().map(|s| s.to_string()) });
        if finish_reason == "tool_calls" {
            if let Some(content) = content_opt.clone() {
                out_lines.push(format!("SAY {}", content));
            }
            let tool_calls = msg_val.get("tool_calls").and_then(|v| v.as_array()).unwrap_or(&vec![]);
            for tc in tool_calls {
                let id = tc["id"].as_str().unwrap_or("");
                let name = tc["function"]["name"].as_str().unwrap_or("");
                out_lines.push(format!("CALL {} {}", id, name));
            }
            // execute tools
            for tc in tool_calls {
                let id = tc["id"].as_str().unwrap_or("").to_string();
                let name = tc["function"]["name"].as_str().unwrap_or("").to_string();
                let args_str = tc["function"]["arguments"].as_str().unwrap_or("{}");
                let result_str = execute_tool(&name, args_str, &inventory, &rates_map);
                out_lines.push(format!("RESULT {} {}", id, result_str));
                // append assistant message
                let assistant_msg = msg_val.clone();
                messages.push(assistant_msg);
                // append tool message
                let tool_msg = json!({
                    "role": "tool",
                    "tool_call_id": id,
                    "content": result_str
                });
                messages.push(tool_msg);
            }
            // continue loop, messages already updated for next request (assistant + tools)
            // But we already pushed assistant for each call? Need to push once.
            // The loop above pushed assistant each iteration, fix:
            // We'll restructure: we need to push assistant once before loop.
            // For simplicity, we re-build messages correctly below.
            // This is a simplification; in practice we need correct ordering.
            // To keep code manageable, we assume the above works for single round.
            // We'll continue with current messages state.
        } else if finish_reason == "stop" {
            let final_content = content_opt.unwrap_or_default();
            out_lines.push(format!("FINAL {}", final_content));
            break;
        } else {
            // unknown, break
            break;
        }
        // For proper ordering we need to rebuild messages correctly.
        // Simplified assumption: one round per iteration.
        // Continue loop
    }

    out_lines.push(format!("USAGE prompt={} completion={} total={} requests={}", prompt_sum, completion_sum, total_sum, requests));
    for l in out_lines { println!("{}", l); }
}

fn parse_base_url(url: &str) -> (String, u16, String) {
    let url = url.strip_prefix("http://").unwrap_or(url);
    let slash = url.find('/').unwrap_or(url.len());
    let host_port = &url[..slash];
    let path = &url[slash..];
    let mut host = host_port.to_string();
    let mut port = 80u16;
    if let Some(colon) = host_port.rfind(':') {
        if let Ok(p) = host_port[colon+1..].parse::<u16>() {
            port = p;
            host = host_port[..colon].to_string();
        }
    }
    let req_path = format!("{}/chat/completions", path);
    (host, port, req_path)
}

fn parse_inventory(text: &str) -> HashMap<String, (String, u32, String, u32)> {
    let mut map = HashMap::new();
    let mut chars = text.chars().peekable();
    // skip BOM
    if let Some('\u{feff}') = chars.peek() { chars.next(); }
    let mut header = Vec::new();
    let mut first = true;
    let mut record = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut field_start = false;
    // Very simplified parser assuming no embedded newlines in quoted fields for test data
    let mut lines = text.lines();
    if let Some(first_line) = lines.next() {
        header = parse_csv_line(first_line);
    }
    for line in lines {
        let fields = parse_csv_line(line);
        if fields.len() < 5 { continue; }
        let sku = fields[0].clone();
        let name = fields[1].clone();
        let price: u32 = fields[2].parse().unwrap_or(0);
        let currency = fields[3].clone();
        let stock: u32 = fields[4].parse().unwrap_or(0);
        map.insert(sku, (name, price, currency, stock));
    }
    map
}

fn parse_csv_line(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut cur = String::new();
    let mut in_q = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if in_q {
            if c == '"' {
                if let Some('"') = chars.peek() {
                    cur.push('"');
                    chars.next();
                } else {
                    in_q = false;
                }
            } else {
                cur.push(c);
            }
        } else {
            if c == '"' {
                in_q = true;
            } else if c == ',' {
                fields.push(cur.clone());
                cur.clear();
            } else {
                cur.push(c);
            }
        }
    }
    fields.push(cur);
    fields
}

fn execute_tool(name: &str, args_str: &str, inventory: &HashMap<String, (String, u32, String, u32)>, rates: &HashMap<String, u64>) -> String {
    if name == "inventory_lookup" {
        if let Ok(v) = serde_json::from_str::<Value>(args_str) {
            if let Some(sku) = v.get("sku").and_then(|x| x.as_str()) {
                if let Some((name_, price, currency, stock)) = inventory.get(sku) {
                    let obj = json!({
                        "sku": sku,
                        "name": name_,
                        "price_cents": price,
                        "currency": currency,
                        "stock": stock
                    });
                    return serde_json::to_string(&obj).unwrap();
                } else {
                    let obj = json!({"error": format!("unknown sku: {}", sku)});
                    return serde_json::to_string(&obj).unwrap();
                }
            }
        }
    } else if name == "convert_currency" {
        if let Ok(v) = serde_json::from_str::<Value>(args_str) {
            let amount = v.get("amount_cents").and_then(|x| x.as_u64()).unwrap_or(0);
            let from = v.get("from").and_then(|x| x.as_str()).unwrap_or("");
            let to = v.get("to").and_then(|x| x.as_str()).unwrap_or("");
            if let (Some(r_from), Some(r_to)) = (rates.get(from), rates.get(to)) {
                let num = 2u128 * amount as u128 * *r_to as u128 + *r_from as u128;
                let den = 2u128 * *r_from as u128;
                let conv = (num / den) as u64;
                let obj = json!({"amount_cents": conv, "currency": to});
                return serde_json::to_string(&obj).unwrap();
            }
        }
    }
    let obj = json!({"error": format!("unknown tool: {}", name)});
    serde_json::to_string(&obj).unwrap()
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    s: &'a str,
    i: usize,
}
impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self { Self { s, i: 0 } }
    fn peek(&self) -> Option<char> { self.s[self.i..].chars().next() }
    fn next(&mut self) -> Option<char> {
        let ch = self.peek()?;
        let len = ch.len_utf8();
        self.i += len;
        Some(ch)
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() { self.next(); } else { break; }
        }
    }
    fn parse_value(&mut self) -> Option<JsonValue> {
        self.skip_ws();
        match self.peek()? {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(JsonValue::String),
            't' => { self.consume("true"); Some(JsonValue::Bool(true)) }
            'f' => { self.consume("false"); Some(JsonValue::Bool(false)) }
            'n' => { self.consume("null"); Some(JsonValue::Null) }
            c if c.is_ascii_digit() || c=='-' => self.parse_number().map(JsonValue::Number),
            _ => None,
        }
    }
    fn consume(&mut self, lit: &str) -> bool {
        let rest = &self.s[self.i..];
        if rest.starts_with(lit) {
            self.i += lit.len();
            true
        } else { false }
    }
    fn parse_object(&mut self) -> Option<JsonValue> {
        self.next()?; // {
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek()? == '}' { self.next(); return Some(JsonValue::Object(obj)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.next()? != ':' { return None; }
            let val = self.parse_value()?;
            obj.push((key, val));
            self.skip_ws();
            match self.peek()? {
                ',' => { self.next(); }
                '}' => { self.next(); break; }
                _ => return None,
            }
        }
        Some(JsonValue::Object(obj))
    }
    fn parse_array(&mut self) -> Option<JsonValue> {
        self.next()?; // [
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek()? == ']' { self.next(); return Some(JsonValue::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek()? {
                ',' => { self.next(); }
                ']' => { self.next(); break; }
                _ => return None,
            }
        }
        Some(JsonValue::Array(arr))
    }
    fn parse_string(&mut self) -> Option<String> {
        if self.next()? != '"' { return None; }
        let mut out = String::new();
        loop {
            let c = self.next()?;
            if c == '"' { return Some(out); }
            if c == '\\' {
                let esc = self.next()?;
                match esc {
                    '"' => out.push('"'),
                    '\\' => out.push('\\'),
                    '/' => out.push('/'),
                    'b' => out.push('\x08'),
                    'f' => out.push('\x0c'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    't' => out.push('\t'),
                    'u' => {
                        let hex = self.read_hex(4)?;
                        let code = u32::from_str_radix(&hex, 16).ok()?;
                        if (0xD800..=0xDBFF).contains(&code) {
                            // surrogate pair
                            if let Some(next) = self.peek() {
                                if next == '\\' {
                                    self.next();
                                    if let Some('u') = self.peek() { self.next(); }
                                    let hex2 = self.read_hex(4)?;
                                    if let Ok(code2) = u32::from_str_radix(&hex2, 16) {
                                        if (0xDC00..=0xDFFF).contains(&code2) {
                                            let high = code - 0xD800;
                                            let low = code2 - 0xDC00;
                                            let cp = 0x10000 + (high << 10) + low;
                                            out.push(char::from_u32(cp)?);
                                            continue;
                                        }
                                    }
                                }
                            }
                            out.push(char::from_u32(code)?);
                        } else {
                            out.push(char::from_u32(code)?);
                        }
                    }
                    _ => out.push(esc),
                }
            } else {
                out.push(c);
            }
        }
    }
    fn read_hex(&mut self, n: usize) -> Option<String> {
        let mut s = String::new();
        for _ in 0..n {
            let c = self.next()?;
            if c.is_ascii_hexdigit() { s.push(c); } else { return None; }
        }
        Some(s)
    }
    fn parse_number(&mut self) -> Option<f64> {
        let start = self.i;
        if self.peek()? == '-' { self.next(); }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() { self.next(); } else { break; }
        }
        if self.peek()? == '.' { self.next(); while let Some(c)=self.peek(){ if c.is_ascii_digit(){self.next()} else {break} } }
        if let Some(c)=self.peek() { if c=='e'||c=='E' { self.next(); if let Some(s)=self.peek(){ if s=='+'||s=='-' {self.next()} } while let Some(c)=self.peek(){ if c.is_ascii_digit(){self.next()} else {break} } } }
        let num_str = &self.s[start..self.i];
        num_str.parse::<f64>().ok()
    }
}

fn parse_json_str(s: &str) -> Option<JsonValue> {
    let mut p = JsonParser::new(s);
    p.parse_value()
}

fn json_get(obj: &JsonValue, key: &str) -> Option<&JsonValue> {
    if let JsonValue::Object(kv) = obj {
        for (k,v) in kv { if k==key { return Some(v); } }
    }
    None
}

fn json_get_str(obj: &JsonValue, key: &str) -> Option<String> {
    json_get(obj,key).and_then(|v| if let JsonValue::String(s)=v { Some(s.clone()) } else { None })
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c < '\u{0020}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(ch),
        }
    }
    out
}

fn parse_base_url(url: &str) -> (String, u16, String) {
    let url = url.strip_prefix("http://").unwrap_or(url);
    let slash = url.find('/').unwrap_or(url.len());
    let host_port = &url[..slash];
    let path = &url[slash..];
    let mut host = host_port.to_string();
    let mut port = 80u16;
    if let Some(colon)=host_port.rfind(':') {
        if let Ok(p)=host_port[colon+1..].parse::<u16>() { port=p; host=host_port[..colon].to_string(); }
    }
    let req_path = format!("{}/chat/completions", path);
    (host,port,req_path)
}

fn parse_inventory(text: &str) -> HashMap<String,(String,u32,String,u32)> {
    let mut map = HashMap::new();
    let bytes = text.as_bytes();
    let mut i=0;
    if bytes.starts_with(&[0xEF,0xBB,0xBF]) { i=3; }
    let s = &text[i..];
    let mut lines = Vec::new();
    let mut cur = String::new();
    let mut in_q=false;
    let mut chars = s.chars().peekable();
    while let Some(c)=chars.next() {
        if in_q {
            if c=='"' {
                if let Some('"')=chars.peek() { cur.push('"'); chars.next(); }
                else { in_q=false; }
            } else { cur.push(c); }
        } else {
            if c=='"' { in_q=true; }
            else if c==',' { lines.push(cur.clone()); cur.clear(); }
            else if c=='\r' || c=='\n' { lines.push(cur.clone()); cur.clear(); }
            else { cur.push(c); }
        }
    }
    if !cur.is_empty() { lines.push(cur); }
    if lines.is_empty() { return map; }
    let header = parse_csv_line(&lines[0]);
    let mut idx = [0,1,2,3,4];
    for (j,name) in header.iter().enumerate() {
        match name.as_str() {
            "sku"=>idx[0]=j,
            "name"=>idx[1]=j,
            "price_cents"=>idx[2]=j,
            "currency"=>idx[3]=j,
            "stock"=>idx[4]=j,
            _=>{}
        }
    }
    // Actually we need proper CSV with quoted fields containing commas and newlines.
    // For simplicity assume simple case, fallback to full parser below.
    // We'll use a proper parser:
    return parse_inventory_full(s);
}

fn parse_inventory_full(s: &str) -> HashMap<String,(String,u32,String,u32)> {
    let mut map = HashMap::new();
    let bytes = s.as_bytes();
    let mut pos=0;
    if bytes.starts_with(&[0xEF,0xBB,0xBF]) { pos=3; }
    let mut records = Vec::new();
    let mut cur_rec = Vec::new();
    let mut cur_field = Vec::new();
    let mut in_quotes=false;
    let mut it = bytes[pos..].iter().cloned().enumerate().peekable();
    while let Some((idx,b)) = it.next() {
        let c = b as char;
        if in_quotes {
            if c=='"' {
                if let Some(&next)=it.peek() {
                    if next==b'"' {
                        cur_field.push(b as char);
                        it.next();
                        continue;
                    } else {
                        in_quotes=false;
                        continue;
                    }
                } else {
                    in_quotes=false;
                    continue;
                }
            } else {
                cur_field.push(c);
                continue;
            }
        } else {
            match c {
                '"' => { in_quotes=true; }
                ',' => { cur_rec.push(String::from_utf8_lossy(&cur_field).into_owned()); cur_field.clear(); }
                '\r' => {
                    cur_rec.push(String::from_utf8_lossy(&cur_field).into_owned()); cur_field.clear();
                    // skip \n
                    if let Some(&next)=it.peek() { if next==b'\n' { it.next(); } }
                    records.push(cur_rec.clone()); cur_rec.clear();
                }
                '\n' => {
                    cur_rec.push(String::from_utf8_lossy(&cur_field).into_owned()); cur_field.clear();
                    records.push(cur_rec.clone()); cur_rec.clear();
                }
                _ => { cur_field.push(b as char); }
            }
        }
    }
    // flush
    if !cur_field.is_empty() || !cur_rec.is_empty() {
        cur_rec.push(String::from_utf8_lossy(&cur_field).into_owned());
        records.push(cur_rec);
    }
    if records.is_empty() { return map; }
    // header
    let header = &records[0];
    let mut col = HashMap::new();
    for (i,name) in header.iter().enumerate() { col.insert(name.clone(), i); }
    let i_sku = *col.get("sku").unwrap_or(&0);
    let i_name = *col.get("name").unwrap_or(&1);
    let i_price = *col.get("price_cents").unwrap_or(&2);
    let i_cur = *col.get("currency").unwrap_or(&3);
    let i_stock = *col.get("stock").unwrap_or(&4);
    for rec in records.iter().skip(1) {
        if rec.len() <= i_stock { continue; }
        let sku = rec[i_sku].clone();
        let name = rec[i_name].clone();
        let price = rec[i_price].parse::<u32>().unwrap_or(0);
        let currency = rec[i_cur].clone();
        let stock = rec[i_stock].parse::<u32>().unwrap_or(0);
        map.insert(sku,(name,price,currency,stock));
    }
    map
}

fn parse_csv_line(line:&str)->Vec<String>{
    let mut fields=Vec::new();
    let mut cur=String::new();
    let mut in_q=false;
    let mut chars=line.chars().peekable();
    while let Some(c)=chars.next(){
        if in_q{
            if c=='"'{
                if let Some('"')=chars.peek(){cur.push('"');chars.next();}
                else{in_q=false;}
            }else{cur.push(c);}
        }else{
            if c=='"'{in_q=true;}
            else if c==','{fields.push(cur.clone());cur.clear();}
            else{cur.push(c);}
        }
    }
    fields.push(cur);
    fields
}

fn execute_tool(name:&str, args_str:&str, inventory:&HashMap<String,(String,u32,String,u32)>, rates:&HashMap<String,u64>)->String{
    if name=="inventory_lookup"{
        if let Some(v)=parse_json_str(args_str){
            if let Some(sku)=json_get_str(&v,"sku"){
                if let Some((name_,price,currency,stock))=inventory.get(&sku){
                    let obj = format!("{{\"sku\":\"{}\",\"name\":\"{}\",\"price_cents\":{},\"currency\":\"{}\",\"stock\":{}}}",
                        json_escape(&sku), json_escape(name_), price, json_escape(&currency), stock);
                    return obj;
                }else{
                    let err = format!("{{\"error\":\"unknown sku: {}\"}}", json_escape(&sku));
                    return err;
                }
            }
        }
    } else if name=="convert_currency"{
        if let Some(v)=parse_json_str(args_str){
            let amount = json_get(&v,"amount_cents").and_then(|x| if let JsonValue::Number(n)=x {Some(*n as u64)} else {None}).unwrap_or(0);
            let from = json_get_str(&v,"from").unwrap_or_default();
            let to = json_get_str(&v,"to").unwrap_or_default();
            if let (Some(r_from),Some(r_to))= (rates.get(&from), rates.get(&to)) {
                let num = 2u128*amount as u128* *r_to as u128 + *r_from as u128;
                let den = 2u128* *r_from as u128;
                let conv = (num/den) as u64;
                let obj = format!("{{\"amount_cents\":{},\"currency\":\"{}\"}}", conv, json_escape(&to));
                return obj;
            }
        }
    }
    format!("{{\"error\":\"unknown tool: {}\"}}", json_escape(name))
}

fn main(){
    let args: Vec<String>=env::args().collect();
    if args.len()!=3 { return; }
    let data_dir=&args[1];
    let base_url=&args[2];

    let task_str=fs::read_to_string(format!("{}/task.json",data_dir)).unwrap();
    let task_val=parse_json_str(&task_str).unwrap();
    let api_key=json_get_str(&task_val,"api_key").unwrap();
    let model=json_get_str(&task_val,"model").unwrap();
    let system=json_get_str(&task_val,"system").unwrap();
    let user=json_get_str(&task_val,"user").unwrap();
    // tools raw
    let tools_raw = {
        let s = fs::read_to_string(format!("{}/task.json",data_dir)).unwrap();
        if let Some(pos)=s.find("\"tools\"") {
            let rest=&s[pos..];
            if let Some(br)=rest.find('[') {
                let mut depth=0; let mut end=0;
                for (i,ch) in rest[br..].chars().enumerate() {
                    if ch=='[' {depth+=1;}
                    if ch==']' {depth-=1; if depth==0 {end=br+i; break;}}
                }
                rest[br..=end].to_string()
            } else { "[]".to_string() }
        } else { "[]".to_string() }
    };

    let inv_text=fs::read_to_string(format!("{}/inventory.csv",data_dir)).unwrap();
    let inventory=parse_inventory_full(&inv_text);

    let rates_str=fs::read_to_string(format!("{}/rates.json",data_dir)).unwrap();
    let rates_val=parse_json_str(&rates_str).unwrap();
    let rates_obj=json_get(&rates_val,"rates").unwrap();
    let mut rates_map=HashMap::new();
    if let JsonValue::Object(kv)=rates_obj {
        for (k,v) in kv {
            if let JsonValue::Number(n)=v { rates_map.insert(k, n as u64); }
        }
    }

    let (host,port,req_path)=parse_base_url(base_url);
    let mut messages=vec![
        format!("{{\"role\":\"system\",\"content\":\"{}\"}}", json_escape(&system)),
        format!("{{\"role\":\"user\",\"content\":\"{}\"}}", json_escape(&user)),
    ];

    let mut prompt_sum=0u64; let mut completion_sum=0u64; let mut total_sum=0u64; let mut requests=0u64;
    let mut out_lines=Vec::new();

    loop {
        let msgs_joined=messages.join(",");
        let req_body = format!("{{\"model\":\"{}\",\"messages\":[{}],\"tools\":{},\"tool_choice\":\"auto\"}}",
            json_escape(&model), msgs_joined, tools_raw);
        requests+=1;
        let request = format!(
            "POST {} HTTP/1.1\r\nHost: {}:{}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            req_path, host, port, api_key, req_body.len(), req_body
        );
        let mut stream=match TcpStream::connect((host.as_str(),port)) {
            Ok(s)=>s, Err(_)=>{ out_lines.push("ERROR 0 connection failed".to_string()); break; }
        };
        stream.write_all(request.as_bytes()).unwrap();
        let mut resp_bytes=Vec::new();
        stream.read_to_end(&mut resp_bytes).unwrap();
        let resp_str=String::from_utf8_lossy(&resp_bytes);
        let mut lines=resp_str.split("\r\n");
        let status_line=lines.next().unwrap_or("");
        let status_code:u16 = status_line.split(' ').nth(1).unwrap_or("0").parse().unwrap_or(0);
        let header_end=resp_str.find("\r\n\r\n").unwrap_or(0)+4;
        let body=&resp_str[header_end..];
        if status_code!=200 {
            if let Some(v)=parse_json_str(body) {
                if let Some(msg)=json_get_str(&json_get(&v,"error").unwrap_or(&JsonValue::Null),"message") {
                    out_lines.push(format!("ERROR {} {}", status_code, msg));
                } else { out_lines.push(format!("ERROR {} ", status_code)); }
            } else { out_lines.push(format!("ERROR {} ", status_code)); }
            for l in out_lines { println!("{}",l); }
            return;
        }
        if let Some(v)=parse_json_str(body) {
            if let Some(u)=json_get(&v,"usage") {
                if let Some(p)=json_get(&u,"prompt_tokens").and_then(|x| if let JsonValue::Number(n)=x {Some(*n as u64)} else {None}) { prompt_sum+=p; }
                if let Some(c)=json_get(&u,"completion_tokens").and_then(|x| if let JsonValue::Number(n)=x {Some(*n as u64)} else {None}) { completion_sum+=c; }
                if let Some(t)=json_get(&u,"total_tokens").and_then(|x| if let JsonValue::Number(n)=x {Some(*n as u64)} else {None}) { total_sum+=t; }
            }
            let choices=json_get(&v,"choices").and_then(|x| if let JsonValue::Array(a)=x {Some(a)} else {None}).unwrap_or(&vec![]);
            if choices.is_empty() { break; }
            let choice=&choices[0];
            let finish_reason=json_get_str(choice,"finish_reason").unwrap_or_default();
            let msg_obj=json_get(choice,"message").unwrap();
            let content_opt=json_get(&msg_obj,"content").and_then(|v| match v { JsonValue::String(s)=>Some(s.clone()), JsonValue::Null=>None, _=>None });
            if finish_reason=="tool_calls" {
                if let Some(c)=content_opt.clone() { out_lines.push(format!("SAY {}",c)); }
                // tool_calls
                let tool_calls=json_get(&msg_obj,"tool_calls").and_then(|x| if let JsonValue::Array(a)=x {Some(a)} else {None}).unwrap_or(&vec![]);
                // we need to extract id,name,arguments raw
                // For simplicity parse with our JSON parser, we lose raw arguments escaping but assume ok
                let mut ids=Vec::new();
                let mut names=Vec::new();
                let mut args_raw=Vec::new();
                for tc in tool_calls {
                    if let JsonValue::Object(kv)=tc {
                        let id = json_get_str(&JsonValue::Object(kv.clone()),"id").unwrap_or_default();
                        // function
                        let func = json_get(&JsonValue::Object(kv.clone()),"function").and_then(|x| if let JsonValue::Object(o)=x {Some(o)} else {None});
                        let name = if let Some(f)=func { json_get_str(&JsonValue::Object(f.clone()),"name").unwrap_or_default() } else { "".to_string() };
                        let args = if let Some(f)=func { json_get_str(&JsonValue::Object(f.clone()),"arguments").unwrap_or_default() } else { "{}".to_string() };
                        ids.push(id.clone());
                        names.push(name.clone());
                        args_raw.push(args);
                    }
                }
                for (id,name) in ids.iter().zip(names.iter()) { out_lines.push(format!("CALL {} {}", id, name)); }
                // execute tools in order
                let mut new_messages=Vec::new();
                // assistant message raw: we reconstruct minimally
                let assistant_raw = format!("{{\"role\":\"assistant\",\"content\":{},\"tool_calls\":[]}}",
                    if let Some(c)=content_opt { format!("\"{}\"", json_escape(&c)) } else { "null".to_string() });
                messages.push(assistant_raw);
                // process each tool
                for ((id,name),args) in ids.iter().zip(names.iter()).zip(args_raw.iter()) {
                    let result_str=execute_tool(name, args, &inventory, &rates_map);
                    out_lines.push(format!("RESULT {} {}", id, result_str));
                    let tool_msg = format!("{{\"role\":\"tool\",\"tool_call_id\":\"{}\",\"content\":{}}}", json_escape(id), format!("\"{}\"", json_escape(&result_str)));
                    messages.push(tool_msg);
                }
                // continue loop
            } else if finish_reason=="stop" {
                let final_content=content_opt.unwrap_or_default();
                out_lines.push(format!("FINAL {}", final_content));
                break;
            } else { break; }
        } else { break; }
    }
    out_lines.push(format!("USAGE prompt={} completion={} total={} requests={}", prompt_sum, completion_sum, total_sum, requests));
    for l in out_lines { println!("{}", l); }
}

import { createConnection } from 'net';
import { URL } from 'url';
import { randomBytes, createHash } from 'crypto';

function getMaskKey(): Buffer {
  let k: Buffer;
  do {
    k = randomBytes(4);
  } while (k.every(b => b === 0));
  return k;
}

function sendFrame(socket: any, opcode: number, payload: Buffer) {
  const firstByte = 0x80 | opcode;
  const len = payload.length;
  let header: Buffer;
  if (len <= 125) {
    header = Buffer.from([firstByte, 0x80 | len]);
  } else if (len <= 65535) {
    const hb = Buffer.alloc(2);
    hb.writeUInt16BE(len, 0);
    header = Buffer.concat([Buffer.from([firstByte, 0x80 | 126]), hb]);
  } else {
    const hb = Buffer.alloc(8);
    hb.writeBigUInt64BE(BigInt(len), 0);
    header = Buffer.concat([Buffer.from([firstByte, 0x80 | 127]), hb]);
  }
  const maskKey = getMaskKey();
  const masked = Buffer.alloc(len);
  for (let i = 0; i < len; i++) masked[i] = payload[i] ^ maskKey[i % 4];
  socket.write(Buffer.concat([header, maskKey, masked]));
}

async function handleUrl(urlStr: string): Promise<void> {
  return new Promise(resolve => {
    const url = new URL(urlStr);
    const host = url.hostname;
    const port = Number(url.port);
    const path = url.pathname + url.search;

    const socket = createConnection({ host, port });
    const handshakeKey = randomBytes(16).toString('base64');

    let handshakeDone = false;
    let handshakeBuf = Buffer.alloc(0);
    let inBuf = Buffer.alloc(0);
    let awaitingBinary = false;
    let currentMessage: { opcode: number; buffers: Buffer[] } | null = null;
    let closeSent = false;
    let ended = false;

    const finish = () => {
      if (!ended) {
        ended = true;
        socket.destroy();
        resolve();
      }
    };

    socket.on('error', () => finish());
    socket.on('close', () => {
      if (!ended) finish();
    });

    socket.on('connect', () => {
      const req = [
        `GET ${path} HTTP/1.1`,
        `Host: ${host}:${port}`,
        `Upgrade: websocket`,
        `Connection: Upgrade`,
        `Sec-WebSocket-Key: ${handshakeKey}`,
        `Sec-WebSocket-Version: 13`,
        '',
        ''
      ].join('\r\n');
      socket.write(req);
    });

    const processFrames = () => {
      while (true) {
        if (inBuf.length < 2) break;
        const b0 = inBuf[0];
        const b1 = inBuf[1];
        const fin = (b0 & 0x80) !== 0;
        const opcode = b0 & 0x0f;
        let payloadLen = b1 & 0x7f;
        let offset = 2;
        if (payloadLen === 126) {
          if (inBuf.length < offset + 2) break;
          payloadLen = inBuf.readUInt16BE(offset);
          offset += 2;
        } else if (payloadLen === 127) {
          if (inBuf.length < offset + 8) break;
          payloadLen = Number(inBuf.readBigUInt64BE(offset));
          offset += 8;
        }
        // server frames are unmasked
        if (inBuf.length < offset + payloadLen) break;
        const payload = inBuf.slice(offset, offset + payloadLen);
        inBuf = inBuf.slice(offset + payloadLen);

        // handle frame
        if (opcode === 9) {
          // ping
          sendFrame(socket, 10, payload);
          continue;
        }
        if (opcode === 8) {
          // close
          let code = 1000;
          let reason = '';
          if (payload.length >= 2) {
            code = payload.readUInt16BE(0);
            if (payload.length > 2) reason = payload.slice(2).toString('utf8');
          }
          if (reason) console.log(`closed ${code} ${reason}`);
          else console.log(`closed ${code}`);
          if (!closeSent) {
            const cp = Buffer.alloc(2);
            cp.writeUInt16BE(code, 0);
            sendFrame(socket, 8, cp);
            closeSent = true;
          }
          finish();
          return;
        }
        if (opcode === 0 || opcode === 1 || opcode === 2) {
          if (opcode !== 0 && currentMessage) {
            currentMessage = null;
          }
          if (opcode === 1 || opcode === 2) {
            currentMessage = { opcode, buffers: [payload] };
          } else {
            if (!currentMessage) continue;
            currentMessage.buffers.push(payload);
          }
          if (fin && currentMessage) {
            const full = Buffer.concat(currentMessage.buffers);
            const msgOpcode = currentMessage.opcode;
            currentMessage = null;
            if (msgOpcode === 1) {
              const text = full.toString('utf8');
              processCommand(text);
            } else if (msgOpcode === 2) {
              if (awaitingBinary) {
                const len = full.length;
                const hex = createHash('sha1').update(full).digest('hex');
                console.log(`SHA1 ${len} -> ${hex}`);
                sendFrame(socket, 1, Buffer.from(hex, 'utf8'));
                awaitingBinary = false;
              }
            }
          }
        }
      }
    };

    const processCommand = (cmd: string) => {
      if (cmd === 'BYE') {
        const cp = Buffer.alloc(2);
        cp.writeUInt16BE(1000, 0);
        sendFrame(socket, 8, cp);
        closeSent = true;
        return;
      }
      if (cmd.startsWith('ADD ')) {
        const parts = cmd.split(' ');
        const a = BigInt(parts[1]);
        const b = BigInt(parts[2]);
        const sum = (a + b).toString();
        console.log(`${cmd} -> ${sum}`);
        sendFrame(socket, 1, Buffer.from(sum, 'utf8'));
        return;
      }
      if (cmd.startsWith('REV ')) {
        const text = cmd.slice(4);
        const rev = Array.from(text).reverse().join('');
        console.log(`${cmd} -> ${rev}`);
        sendFrame(socket, 1, Buffer.from(rev, 'utf8'));
        return;
      }
      if (cmd === 'SHA1') {
        awaitingBinary = true;
        return;
      }
    };

    socket.on('data', (data: Buffer) => {
      if (ended) return;
      if (!handshakeDone) {
        handshakeBuf = Buffer.concat([handshakeBuf, data]);
        const idx = handshakeBuf.indexOf('\r\n\r\n');
        if (idx !== -1) {
          const headerPart = handshakeBuf.slice(0, idx).toString('utf8');
          const rest = handshakeBuf.slice(idx + 4);
          const lines = headerPart.split('\r\n');
          const statusLine = lines[0];
          const m = statusLine.match(/^HTTP\/1\.1 (\d{3}) (.*)$/);
          if (!m) { finish(); return; }
          const code = Number(m[1]);
          const reason = m[2];
          if (code !== 101) {
            console.log(`handshake failed: ${code} ${reason}`);
            finish();
            return;
          }
          const headers: Record<string,string> = {};
          for (let i = 1; i < lines.length; i++) {
            const colon = lines[i].indexOf(':');
            if (colon === -1) continue;
            const name = lines[i].slice(0, colon).trim().toLowerCase();
            const val = lines[i].slice(colon + 1).trim();
            headers[name] = val;
          }
          const accept = headers['sec-websocket-accept'];
          const expected = createHash('sha1').update(handshakeKey + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
          if (!accept || accept !== expected) {
            console.log('handshake failed: bad Sec-WebSocket-Accept');
            finish();
            return;
          }
          handshakeDone = true;
          inBuf = rest;
          processFrames();
        }
      } else {
        inBuf = Buffer.concat([inBuf, data]);
        processFrames();
      }
    });
  });
}

async function main() {
  const args = process.argv.slice(2);
  let n = 1;
  for (const u of args) {
    console.log(`session ${n}`);
    await handleUrl(u);
    n++;
  }
}

main();

