          let port = url.port else { continue }

    let path = url.path + (url.query.map { "?\($0)" } ?? "")
    let requestTarget = path.isEmpty ? "/" : path

    // TCP connection
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    addr.sin_addr.s_addr = inet_addr(host)

    let sock = socket(AF_INET, SOCK_STREAM, 0)
    guard sock >= 0 else { continue }
    let connResult = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            connect(sock, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard connResult == 0 else {
        close(sock)
        continue
    }

    // handshake
    let keyBytes = Data((0..<16).map { _ in UInt8.random(in: 0...255) })
    let keyB64 = keyBytes.base64EncodedString()
    let handshake = """
    GET \(requestTarget) HTTP/1.1\r
    Host: \(host):\(port)\r
    Upgrade: websocket\r
    Connection: Upgrade\r
    Sec-WebSocket-Key: \(keyB64)\r
    Sec-WebSocket-Version: 13\r
    \r
    """
    let handshakeData = Data(handshake.utf8)
    _ = handshakeData.withUnsafeBytes { ptr in write(sock, ptr.baseAddress!, handshakeData.count) }

    // read headers
    var headerData = Data()
    var headerDone = false
    var responseStatus = ""
    var responseReason = ""
    var acceptHeader = ""
    var readBuf = [UInt8](repeating: 0, count: 4096)
    while !headerDone {
        let n = read(sock, &readBuf, readBuf.count)
        if n <= 0 { break }
        headerData.append(contentsOf: readBuf[0..<n])
        if let str = String(data: headerData, encoding: .isoLatin1),
           str.contains("\r\n\r\n") {
            headerDone = true
        }
    }
    // parse status line
    guard let headerStr = String(data: headerData, encoding: .isoLatin1) else {
        close(sock)
        continue
    }
    let headerLines = headerStr.components(separatedBy: "\r\n")
    guard let statusLine = headerLines.first else {
        close(sock)
        continue
    }
    let statusParts = statusLine.split(separator: " ", maxSplits: 2)
    let code = Int(statusParts.first ?? "") ?? 0
    if code != 101 {
        let reason = statusParts.count > 2 ? String(statusParts[2]) : (statusParts.count > 1 ? String(statusParts[1]) : "")
        print("handshake failed: \(code) \(reason)")
        close(sock)
        continue
    }
    // find Sec-WebSocket-Accept
    for line in headerLines.dropFirst() {
        let lower = line.lowercased()
        if lower.hasPrefix("sec-websocket-accept:") {
            acceptHeader = line.dropFirst("Sec-WebSocket-Accept:".count).trimmingCharacters(in: .whitespaces)
        }
    }
    // verify accept
    let magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    let acceptData = Data((keyB64 + magic).utf8)
    let hash = Insecure.SHA1.hash(data: acceptData)
    let expected = Data(hash).base64EncodedString()
    if acceptHeader != expected {
        print("handshake failed: bad Sec-WebSocket-Accept")
        close(sock)
        continue
    }

    // frame processing
    var leftover = headerData
    // remove header part
    if let idx = headerData.range(of: Data("\r\n\r\n".utf8)) {
        let after = headerData.subrange(after: idx.upperBound)
        leftover = Data(after)
    }

    var buffer = leftover
    var assemblingOpcode: UInt8? = nil
    var assemblingData = Data()
    var waitingForSha1 = false
    var sentClose = false
    var closeCodeSent = 0
    var finished = false

    func sendFrame(_ opcode: UInt8, payload: Data, mask: Bool = true) {
        var frame = Data()
        var b0: UInt8 = 0x80 | (opcode & 0x0F)
        frame.append(b0)
        var len = payload.count
        var b1: UInt8 = mask ? 0x80 : 0x00
        if len <= 125 {
            b1 |= UInt8(len)
            frame.append(b1)
        } else if len <= 65535 {
            b1 |= 126
            frame.append(b1)
            var len16 = UInt16(len).bigEndian
            withUnsafeBytes(of: &len16) { frame.append(contentsOf: $0) }
        } else {
            b1 |= 127
            frame.append(b1)
            var len64 = UInt64(len).bigEndian
            withUnsafeBytes(of: &len64) { frame.append(contentsOf: $0) }
        }
        if mask {
            var maskKey = [UInt8]()
            repeat {
                maskKey = (0..<4).map { _ in UInt8.random(in: 0...255) }
            } while maskKey.allSatisfy { $0 == maskKey[0] }
            frame.append(contentsOf: maskKey)
            var masked = Data()
            for i in 0..<payload.count {
                masked.append(payload[i] ^ maskKey[i % 4])
            }
            frame.append(masked)
        } else {
            frame.append(payload)
        }
        _ = frame.withUnsafeBytes { ptr in write(sock, ptr.baseAddress!, frame.count) }
    }

    func handleCompleteMessage(opcode: UInt8, data: Data) {
        if waitingForSha1 {
            // binary payload expected
            let hash = Insecure.SHA1.hash(data: data)
            let hex = hash.map { String(format: "%02x", $0) }.joined()
            print("SHA1 \(data.count) -> \(hex)")
            sendFrame(1, payload: Data(hex.utf8))
            waitingForSha1 = false
            return
        }
        guard opcode == 1, let text = String(data: data, encoding: .utf8) else { return }
        if text.hasPrefix("ADD ") {
            let parts = text.split(separator: " ")
            if parts.count == 3, let a = Int64(parts[1]), let b = Int64(parts[2]) {
                let sum = a + b
                print("\(text) -> \(sum)")
                sendFrame(1, payload: Data("\(sum)".utf8))
            }
        } else if text.hasPrefix("REV ") {
            let rest = String(text.dropFirst(4))
            let revScalars = rest.unicodeScalars.reversed()
            let rev = String(revScalars.map { Character($0) })
            print("\(text) -> \(rev)")
            sendFrame(1, payload: Data(rev.utf8))
        } else if text == "SHA1" {
            waitingForSha1 = true
        } else if text == "BYE" {
            var closePayload = Data([0x03, 0xE8])
            sendFrame(8, payload: closePayload)
            sentClose = true
            closeCodeSent = 1000
        }
    }

    while !finished {
        // read more
        let n = read(sock, &readBuf, readBuf.count)
        if n <= 0 { break }
        buffer.append(contentsOf: readBuf[0..<n])

        while true {
            if buffer.count < 2 { break }
            let b0 = buffer[0]
            let b1 = buffer[1]
            let fin = (b0 & 0x80) != 0
            let opcode = b0 & 0x0F
            let maskBit = (b1 & 0x80) != 0
            var payloadLen = Int(b1 & 0x7F)
            var offset = 2
            if payloadLen == 126 {
                if buffer.count < offset + 2 { break }
                payloadLen = Int(UInt16(buffer[offset]) << 8 | UInt16(buffer[offset+1]))
                offset += 2
            } else if payloadLen == 127 {
                if buffer.count < offset + 8 { break }
                var len64: UInt64 = 0
                for i in 0..<8 { len64 = (len64 << 8) | UInt64(buffer[offset+i]) }
                payloadLen = Int(len64)
                offset += 8
            }
            var maskKey = [UInt8]()
            if maskBit {
                if buffer.count < offset + 4 { break }
                maskKey = Array(buffer[offset..<offset+4])
                offset += 4
            }
            if buffer.count < offset + payloadLen { break }
            var payload = Data(buffer[offset..<offset+payloadLen])
            if maskBit {
                for i in 0..<payload.count {
                    payload[i] ^= maskKey[i % 4]
                }
            }
            // consume frame
            let consumed = offset + payloadLen
            buffer.removeSubrange(0..<consumed)

            // handle opcode
            if opcode == 9 { // ping
                sendFrame(10, payload: payload, mask: true)
                continue
            } else if opcode == 10 {
                continue
            } else if opcode == 8 {
                var code = 0
                var reason = ""
                if payload.count >= 2 {
                    code = Int(payload[0]) << 8 | Int(payload[1])
                    if payload.count > 2 {
                        let reasonData = payload.subdata(in: 2..<payload.count)
                        reason = String(data: reasonData, encoding: .utf8) ?? ""
                    }
                }
                if !sentClose {
                    var closePayload = Data()
                    var c = UInt16(code).bigEndian
                    withUnsafeBytes(of: &c) { closePayload.append(contentsOf: $0) }
                    sendFrame(8, payload: closePayload, mask: true)
                }
                print("closed \(code) \(reason)")
                finished = true
                break
            } else {
                // data frames
                if assemblingOpcode == nil {
                    assemblingOpcode = opcode
                    assemblingData = payload
                } else {
                    assemblingData.append(payload)
                }
                if fin {
                    if let op = assemblingOpcode {
                        handleCompleteMessage(opcode: op, data: assemblingData)
                        assemblingOpcode = nil
                        assemblingData = Data()
                    }
                }
            }
        }
    }
    close(sock)
}

