                    print("closed \(code)")
                } else {
                    print("closed \(code) \(reason)")
                }
                finished = true
                break
            } else {
                if assemblingOpcode == nil {
                    assemblingOpcode = opcode
                    assemblingData = payload
                } else {
                    assemblingData.append(payload)
                }
                if fin {
                    if let op = assemblingOpcode {
                        handleCompleteMessage(opcode: op, data: assemblingData)
                        assemblingOpcode = nil
                        assemblingData = Data()
                    }
                }
            }
        }
    }
    close(sock)
}

import java.io.*;
import java.net.Socket;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.Locale;

public class Main {

    private static final SecureRandom RAND = new SecureRandom();
    private static final String MAGIC = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

    public static void main(String[] args) throws Exception {
        int session = 1;
        for (String urlStr : args) {
            System.out.println("session " + session++);
            handleUrl(urlStr);
        }
    }

    private static void handleUrl(String urlStr) throws Exception {
        URI uri = new URI(urlStr);
        String host = uri.getHost();
        int port = uri.getPort();
        String path = uri.getPath();
        String query = uri.getQuery();
        String requestTarget = path + (query == null ? "" : "?" + query);
        String hostHeader = host + ":" + port;

        try (Socket socket = new Socket(host, port)) {
            socket.setSoTimeout(15000);
            OutputStream out = socket.getOutputStream();
            InputStream in = socket.getInputStream();

            // key
            byte[] keyBytes = new byte[16];
            RAND.nextBytes(keyBytes);
            String keyB64 = Base64.getEncoder().encodeToString(keyBytes);

            // handshake request
            String req = "GET " + requestTarget + " HTTP/1.1\r\n"
                    + "Host: " + hostHeader + "\r\n"
                    + "Upgrade: websocket\r\n"
                    + "Connection: Upgrade\r\n"
                    + "Sec-WebSocket-Key: " + keyB64 + "\r\n"
                    + "Sec-WebSocket-Version: 13\r\n"
                    + "\r\n";
            out.write(req.getBytes(StandardCharsets.ISO_8859_1));
            out.flush();

            // read response headers
            ByteArrayOutputStream all = new ByteArrayOutputStream();
            int b;
            while ((b = in.read()) != -1) {
                all.write(b);
                int sz = all.size();
                if (sz >= 4) {
                    byte[] data = all.toByteArray();
                    if (data[sz - 4] == 13 && data[sz - 3] == 10 && data[sz - 2] == 13 && data[sz - 1] == 10) {
                        break;
                    }
                }
            }
            byte[] respBytes = all.toByteArray();
            int headerEnd = findHeaderEnd(respBytes);
            if (headerEnd < 0) {
                System.out.println("handshake failed: 0 Unknown");
                return;
            }
            byte[] headerBytes = java.util.Arrays.copyOfRange(respBytes, 0, headerEnd + 4);
            byte[] leftover = java.util.Arrays.copyOfRange(respBytes, headerEnd + 4, respBytes.length);

            String headerStr = new String(headerBytes, StandardCharsets.ISO_8859_1);
            String[] lines = headerStr.split("\r\n");
            if (lines.length == 0) {
                System.out.println("handshake failed: 0 Unknown");
                return;
            }
            String statusLine = lines[0];
            String[] statusParts = statusLine.split(" ", 3);
            int code;
            String reason = "";
            if (statusParts.length >= 2) {
                try {
                    code = Integer.parseInt(statusParts[1]);
                } catch (NumberFormatException e) {
                    code = 0;
                }
                if (statusParts.length >= 3) reason = statusParts[2];
                else if (statusParts.length == 2) reason = "";
            } else {
                code = 0;
            }
            if (code != 101) {
                System.out.println("handshake failed: " + code + " " + reason);
                return;
            }
            String acceptHeader = null;
            for (int i = 1; i < lines.length; i++) {
                String line = lines[i];
                int colon = line.indexOf(':');
                if (colon > 0) {
                    String name = line.substring(0, colon).trim();
                    String value = line.substring(colon + 1).trim();
                    if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                        acceptHeader = value;
                    }
                }
            }
            String expectedAccept = computeAccept(keyB64);
            if (acceptHeader == null || !acceptHeader.equals(expectedAccept)) {
                System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                return;
            }

            // start session processing
            ChainInputStream cin = new ChainInputStream(leftover, in);
            processSession(out, cin);
        } catch (IOException e) {
            // connection closed, just go to next
        }
    }

    private static int findHeaderEnd(byte[] data) {
        for (int i = 0; i <= data.length - 4; i++) {
            if (data[i] == 13 && data[i + 1] == 10 && data[i + 2] == 13 && data[i + 3] == 10) {
                return i;
            }
        }
        return -1;
    }

    private static String computeAccept(String keyB64) throws Exception {
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        byte[] hash = sha1.digest((keyB64 + MAGIC).getBytes(StandardCharsets.ISO_8859_1));
        return Base64.getEncoder().encodeToString(hash);
    }

    private static void processSession(OutputStream out, InputStream in) throws Exception {
        boolean closeSent = false;
        boolean awaitingBinary = false;
        boolean inMessage = false;
        int msgOpcode = -1;
        ByteArrayOutputStream msgBuf = null;

        while (true) {
            Frame frame = readFrame(in);
            if (frame == null) break;
            int opcode = frame.opcode;
            byte[] payload = frame.payload;

            if (opcode == 9) { // ping
                sendFrame(out, 10, payload); // pong
                continue;
            }
            if (opcode == 10) { // pong
                continue;
            }
            if (opcode == 8) { // close
                handleClose(out, payload, closeSent);
                if (closeSent) return;
                // if we sent close back, continue to wait for final close?
                // After sending, we still need to read server close
                closeSent = true;
                continue;
            }

            // message fragment
            if (!inMessage) {
                inMessage = true;
                msgOpcode = opcode;
                msgBuf = new ByteArrayOutputStream();
            }
            // continuation or same
            msgBuf.write(payload);
            if (frame.fin) {
                byte[] full = msgBuf.toByteArray();
                if (awaitingBinary) {
                    // binary message for SHA1
                    long len = full.length;
                    MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
                    byte[] digest = sha1.digest(full);
                    String hex = bytesToHex(digest);
                    System.out.println("SHA1 " + len + " -> " + hex);
                    sendText(out, hex);
                    awaitingBinary = false;
                } else {
                    if (msgOpcode == 1) {
                        String cmd = new String(full, StandardCharsets.UTF_8);
                        handleCommand(cmd, out, closeSent);
                        if (cmd.equals("BYE")) {
                            closeSent = true;
                            // continue to read server close
                        }
                        if (cmd.startsWith("SHA1")) {
                            awaitingBinary = true;
                        }
                    } else if (msgOpcode == 2) {
                        // unexpected binary, ignore
                    }
                }
                inMessage = false;
                msgOpcode = -1;
                msgBuf = null;
            }
        }
    }

    private static void handleCommand(String cmd, OutputStream out, boolean closeSent) throws IOException {
        if (cmd.startsWith("ADD ")) {
            String[] parts = cmd.split(" ");
            if (parts.length >= 3) {
                try {
                    long a = Long.parseLong(parts[1]);
                    long b = Long.parseLong(parts[2]);
                    long sum = a + b;
                    String reply = Long.toString(sum);
                    System.out.println(cmd + " -> " + reply);
                    sendText(out, reply);
                } catch (Exception e) {
                    // ignore
                }
            }
        } else if (cmd.startsWith("REV ")) {
            String text = cmd.substring(4);
            String rev = reverseByCodePoint(text);
            String outCmd = "REV " + text;
            System.out.println(outCmd + " -> " + rev);
            sendText(out, rev);
        } else if (cmd.equals("SHA1")) {
            // awaiting binary, no output now
        } else if (cmd.equals("BYE")) {
            sendClose(out, 1000);
            // no print
        }
    }

    private static String reverseByCodePoint(String s) {
        int[] cps = s.codePoints().toArray();
        StringBuilder sb = new StringBuilder();
        for (int i = cps.length - 1; i >= 0; i--) {
            sb.appendCodePoint(cps[i]);
        }
        return sb.toString();
    }

    private static void handleClose(OutputStream out, byte[] payload, boolean alreadySent) throws IOException {
        int code = 0;
        String reason = "";
        if (payload.length >= 2) {
            code = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
            if (payload.length > 2) {
                byte[] reasonBytes = java.util.Arrays.copyOfRange(payload, 2, payload.length);
                reason = new String(reasonBytes, StandardCharsets.UTF_8);
            }
        }
        if (reason.isEmpty()) {
            System.out.println("closed " + code);
        } else {
            System.out.println("closed " + code + " " + reason);
        }
        if (!alreadySent) {
            sendClose(out, code);
        }
    }

    private static Frame readFrame(InputStream in) throws IOException {
        int b0 = in.read();
        if (b0 == -1) return null;
        int b1 = in.read();
        if (b1 == -1) return null;
        int b2 = in.read();
        if (b2 == -1) return null;
        boolean fin = (b0 & 0x80) != 0;
        int opcode = b1 & 0x0F;
        boolean mask = (b2 & 0x80) != 0;
        int payloadLen = b2 & 0x7F;
        if (payloadLen == 126) {
            int hi = in.read();
            int lo = in.read();
            payloadLen = ((hi & 0xFF) << 8) | (lo & 0xFF);
        } else if (payloadLen == 127) {
            long len = 0;
            for (int i = 0; i < 8; i++) {
                int v = in.read();
                if (v == -1) return null;
                len = (len << 8) | (v & 0xFF);
            }
            payloadLen = (int) Math.min(len, Integer.MAX_VALUE);
        }
        byte[] maskKey = null;
        if (mask) {
            maskKey = new byte[4];
            int read = in.read(maskKey);
            if (read < 4) return null;
        }
        byte[] payload = new byte[payloadLen];
        int total = 0;
        while (total < payloadLen) {
            int r = in.read(payload, total, payloadLen - total);
            if (r == -1) break;
            total += r;
        }
        if (mask && maskKey != null) {
            for (int i = 0; i < payload.length; i++) {
                payload[i] ^= maskKey[i % 4];
            }
        }
        return new Frame(fin, opcode, payload);
    }

    private static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        ByteArrayOutputStream frame = new ByteArrayOutputStream();
        frame.write(0x80 | 0); // FIN
        frame.write(opcode);
        int len = payload.length;
        byte[] maskKey = new byte[4];
        RAND.nextBytes(maskKey);
        // ensure not all zero
        boolean allZero = true;
        for (byte b : maskKey) if (b != 0) { allZero = false; break; }
        if (allZero) {
            RAND.nextBytes(maskKey);
        }
        if (len <= 125) {
            frame.write(0x80 | len);
        } else if (len <= 65535) {
            frame.write(0x80 | 126);
            frame.write((len >> 8) & 0xFF);
            frame.write(len & 0xFF);
        } else {
            frame.write(0x80 | 127);
            for (int i = 7; i >= 0; i--) {
                frame.write((len >> (8 * i)) & 0xFF);
            }
        }
        frame.write(maskKey);
        for (int i = 0; i < len; i++) {
            payload[i] ^= maskKey[i % 4];
        }
        frame.write(payload);
        out.write(frame.toByteArray());
        out.flush();
    }

    private static void sendText(OutputStream out, String text) throws IOException {
        byte[] data = text.getBytes(StandardCharsets.UTF_8);
        sendFrame(out, 1, data);
    }

    private static void sendClose(OutputStream out, int code) throws IOException {
        byte[] payload = new byte[2];
        payload[0] = (byte) ((code >> 8) & 0xFF);
        payload[1] = (byte) (code & 0xFF);
        sendFrame(out, 8, payload);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static class Frame {
        boolean fin;
        int opcode;
        byte[] payload;
        Frame(boolean fin, int opcode, byte[] payload) {
            this.fin = fin;
            this.opcode = opcode;
            this.payload = payload;
        }
    }

    private static class ChainInputStream extends InputStream {
        private final ByteArrayInputStream head;
        private final InputStream tail;
        ChainInputStream(byte[] headBytes, InputStream tail) {
            this.head = new ByteArrayInputStream(headBytes);
            this.tail = tail;
        }
        public int read() throws IOException {
            int v = head.read();
            if (v != -1) return v;
            return tail.read();
        }
        public int read(byte[] b, int off, int len) throws IOException {
            int v = head.read(b, off, len);
            if (v > 0) return v;
            if (head.available() == 0) {
                return tail.read(b, off, len);
            }
            return v;
        }
    }
}

