/* ---------- base64 ---------- */
static const char b64_table[] =
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *base64_encode(const unsigned char *in, size_t len) {
    size_t out_len = 4 * ((len + 2) / 3);
    char *out = malloc(out_len + 1);
    size_t i, o = 0;
    for (i = 0; i < len; i += 3) {
        unsigned int v = 0;
        int n = 0;
        for (int j = 0; j < 3; j++) {
            v <<= 8;
            if (i + j < (int)len) v |= in[i + j];
            n++;
        }
        out[o++] = b64_table[(v >> 18) & 0x3F];
        out[o++] = b64_table[(v >> 12) & 0x3F];
        out[o++] = (n > 1) ? b64_table[(v >> 6) & 0x3F] : '=';
        out[o++] = (n > 2) ? b64_table[v & 0x3F] : '=';
    }
    out[out_len] = '\0';
    return out;
}

/* ---------- SHA1 ---------- */
static void sha1_transform(uint32_t state[5], const unsigned char block[64]) {
    uint32_t w[80];
    for (int i = 0; i < 16; i++) {
        w[i] = (block[i*4] << 24) | (block[i*4+1] << 16) | (block[i*4+2] << 8) | block[i*4+3];
    }
    for (int i = 16; i < 80; i++) {
        uint32_t t = w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16];
        w[i] = (t << 1) | (t >> 31);
    }
    uint32_t a = state[0], b = state[1], c = state[2], d = state[3], e = state[4];
    #define ROTL(x,n) (((x) << (n)) | ((x) >> (32-(n))))
    for (int i = 0; i < 80; i++) {
        uint32_t f, k;
        if (i < 20) { f = (b & c) | ((~b) & d); k = 0x5A827999; }
        else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
        else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
        else { f = b ^ c ^ d; k = 0xCA62C1D6; }
        uint32_t temp = ROTL(a,5) + f + e + k + w[i];
        e = d; d = c; c = ROTL(b,30); b = a; a = temp;
    }
    state[0] += a; state[1] += b; state[2] += c; state[3] += d; state[4] += e;
}
static void sha1(const unsigned char *data, size_t len, unsigned char out[20]) {
    uint32_t state[5] = {0x67452301,0xEFCDAB89,0x98BADCFE,0x10325476,0xC3D2E1F0};
    unsigned char buf[64];
    size_t buf_len = 0;
    uint64_t total = 0;
    for (size_t i = 0; i < len; ) {
        size_t to_copy = 64 - buf_len;
        if (i + to_copy > len) to_copy = len - i;
        memcpy(buf + buf_len, data + i, to_copy);
        buf_len += to_copy; i += to_copy; total += to_copy;
        if (buf_len == 64) { sha1_transform(state, buf); buf_len = 0; }
    }
    uint64_t bits = total * 8;
    buf[buf_len++] = 0x80;
    if (buf_len > 56) {
        while (buf_len < 64) buf[buf_len++] = 0;
        sha1_transform(state, buf); buf_len = 0;
    }
    while (buf_len < 56) buf[buf_len++] = 0;
    for (int i = 7; i >= 0; i--) buf[buf_len++] = (bits >> (i*8)) & 0xFF;
    for (int i = 7; i >= 0; i--) buf[buf_len++] = (bits >> (i*8)) & 0xFF;
    sha1_transform(state, buf);
    for (int i = 0; i < 5; i++) {
        out[i*4]   = (state[i] >> 24) & 0xFF;
        out[i*4+1] = (state[i] >> 16) & 0xFF;
        out[i*4+2] = (state[i] >> 8) & 0xFF;
        out[i*4+3] = state[i] & 0xFF;
    }
}

/* ---------- UTF-8 reverse by codepoint ---------- */
static int utf8_decode(const unsigned char *s, size_t len, size_t *pos, uint32_t *cp) {
    unsigned char c = s[*pos];
    if (c < 0x80) { *cp = c; (*pos)++; return 1; }
    if ((c & 0xE0) == 0xC0) {
        if (*pos+1 >= len) return 0;
        *cp = ((c & 0x1F) << 6) | (s[*pos+1] & 0x3F);
        *pos += 2; return 1;
    }
    if ((c & 0xF0) == 0xE0) {
        if (*pos+2 >= len) return 0;
        *cp = ((c & 0x0F) << 12) | ((s[*pos+1] & 0x3F) << 6) | (s[*pos+2] & 0x3F);
        *pos += 3; return 1;
    }
    if ((c & 0xF8) == 0xF0) {
        if (*pos+3 >= len) return 0;
        *cp = ((c & 0x07) << 18) | ((s[*pos+1] & 0x3F) << 12) | ((s[*pos+2] & 0x3F) << 6) | (s[*pos+3] & 0x3F);
        *pos += 4; return 1;
    }
    (*pos)++; return 1;
}
static void utf8_encode(uint32_t cp, char *out, int *outlen) {
    if (cp <= 0x7F) { out[0] = cp; *outlen = 1; }
    else if (cp <= 0x7FF) { out[0] = 0xC0 | (cp>>6); out[1] = 0x80 | (cp&0x3F); *outlen = 2; }
    else if (cp <= 0xFFFF) { out[0] = 0xE0 | (cp>>12); out[1] = 0x80 | ((cp>>6)&0x3F); out[2] = 0x80 | (cp&0x3F); *outlen = 3; }
    else { out[0] = 0xF0 | (cp>>18); out[1] = 0x80 | ((cp>>12)&0x3F); out[2] = 0x80 | ((cp>>6)&0x3F); out[3] = 0x80 | (cp&0x3F); *outlen = 4; }
}
static char *reverse_utf8(const char *in, size_t len, size_t *outlen) {
    uint32_t *cps = malloc(len * sizeof(uint32_t));
    size_t n = 0;
    size_t p = 0;
    uint32_t cp;
    while (p < len) {
        size_t old = p;
        utf8_decode((const unsigned char*)in, len, &p, &cp);
        if (p == old) { p++; }
        cps[n++] = cp;
    }
    char *out = malloc(len * 4 + 1);
    size_t o = 0;
    for (size_t i = n; i > 0; i--) {
        int l;
        utf8_encode(cps[i-1], out + o, &l);
        o += l;
    }
    out[o] = '\0';
    *outlen = o;
    free(cps);
    return out;
}

/* ---------- WebSocket send ---------- */
static int ws_send_frame(int fd, uint8_t opcode, const unsigned char *payload, size_t len) {
    unsigned char hdr[14];
    size_t hlen = 2;
    hdr[0] = 0x80 | (opcode & 0x0F);
    if (len <= 125) {
        hdr[1] = 0x80 | (uint8_t)len;
    } else if (len <= 65535) {
        hdr[1] = 0x80 | 126;
        hdr[2] = (len >> 8) & 0xFF;
        hdr[3] = len & 0xFF;
        hlen = 4;
    } else {
        hdr[1] = 0x80 | 127;
        for (int i = 7; i >= 0; i--) hdr[2 + i] = (len >> (8*i)) & 0xFF;
        hlen = 10;
    }
    unsigned char mask_key[4];
    do { arc4random_buf(mask_key, 4); } while (mask_key[0]==0 && mask_key[1]==0 && mask_key[2]==0 && mask_key[3]==0);
    memcpy(hdr + hlen, mask_key, 4);
    hlen += 4;
    unsigned char *buf = malloc(hlen + len);
    memcpy(buf, hdr, hlen);
    for (size_t i = 0; i < len; i++) buf[hlen + i] = payload[i] ^ mask_key[i % 4];
    size_t sent = 0;
    size_t total = hlen + len;
    while (sent < total) {
        ssize_t s = send(fd, buf + sent, total - sent, 0);
        if (s <= 0) { free(buf); return -1; }
        sent += s;
    }
    free(buf);
    return 0;
}

/* ---------- URL parsing ---------- */
static int parse_ws_url(const char *url, char *host, size_t hlen, int *port, char *path, size_t plen) {
    const char *p = strstr(url, "ws://");
    if (!p) return -1;
    p += 5;
    const char *slash = strchr(p, '/');
    if (!slash) return -1;
    size_t hostlen = slash - p;
    if (hostlen >= hlen) return -1;
    char hostport[256];
    memcpy(hostport, p, hostlen);
    hostport[hostlen] = '\0';
    char *colon = strchr(hostport, ':');
    if (!colon) return -1;
    *colon = '\0';
    strncpy(host, hostport, hlen);
    *port = atoi(colon + 1);
    strncpy(path, slash, plen - 1);
    path[plen - 1] = '\0';
    return 0;
}

