    char *out=malloc(n+1);
    char *o=out;
    for(const char *c=s;c && *c;c++){
        if(*c=='~'){*o++='~';*o++='0';}
        else if(*c=='/'){*o++='~';*o++='1';}
        else *o++=*c;
    }
    *o=0; return out;
}
static char* join_path(const char *base,const char *tok){
    char *etok=escape_pointer(tok);
    size_t bl=strlen(base), tl=strlen(etok);
    char *out=malloc(bl+1+tl+1);
    sprintf(out,"%s/%s",base,etok);
    free(etok);
    return out;
}

/* ---------- JSON parser ---------- */
static JsonValue* parse_string_val(const char **p){
    (*p)++; 
    size_t cap=256,len=0; char *buf=malloc(cap);
    while(**p && **p!='"'){
        if(**p=='\\'){
            (*p)++;
            if(**p=='u'){
                (*p)++;
                int hi=0; for(int i=0;i<4;i++) hi=hi*16+hexval(**p),(*p)++;
                unsigned int cp=hi;
                if(cp>=0xD800 && cp<=0xDBFF && (*p)[0]=='\\' && (*p)[1]=='u'){
                    (*p)+=2; int lo=0; for(int i=0;i<4;i++) lo=lo*16+hexval(**p),(*p)++;
                    cp=0x10000 + ((cp-0xD800)<<10) + (lo-0xDC00);
                }
                utf8_append(&buf,&len,&cap,cp);
            }else{
                char c=*(*p);
                if(c=='n')c='\n'; else if(c=='r')c='\r'; else if(c=='t')c='\t'; else if(c=='b')c='\b'; else if(c=='f')c='\f';
                (*p)++;
                if(len+1>=cap){cap*=2;buf=realloc(buf,cap);}
                buf[len++]=c;
            }
        }else{
            if(len+1>=cap){cap*=2;buf=realloc(buf,cap);}
            buf[len++]=**p; (*p)++;
        }
    }
    if(**p=='"') (*p)++;
    buf[len]=0;
    JsonValue *v=json_new(JV_STRING);
    v->str.str=buf; v->str.len=len;
    return v;
}
static JsonValue* parse_number_val(const char **p){
    char *end;
    double d=strtod(*p,&end);
    *p=end;
    JsonValue *v=json_new(JV_NUMBER);
    v->num_val=d;
    return v;
}
static JsonValue* parse_value(const char **p);
static JsonValue* parse_array(const char **p){
    (*p)++; skip_ws(p);
    JsonValue *v=json_new(JV_ARRAY);
    v->arr.items=NULL; v->arr.count=0; size_t cap=0;
    if(**p!=']'){
        while(1){
            JsonValue *el=parse_value(p);
            if(v->arr.count==cap){cap=cap?cap*2:4; v->arr.items=realloc(v->arr.items,cap*sizeof(JsonValue*));}
            v->arr.items[v->arr.count++]=el;
            skip_ws(p);
            if(**p==','){(*p)++; skip_ws(p); continue;}
            break;
        }
    }
    if(**p==']')(*p)++;
    return v;
}
static JsonValue* parse_object(const char **p){
    (*p)++; skip_ws(p);
    JsonValue *v=json_new(JV_OBJECT);
    v->obj.members=NULL; v->obj.count=0; size_t cap=0;
    if(**p!='}'){
        while(1){
            if(**p!='\"'){ fprintf(stderr,"bad object\n"); exit(1);}
            JsonValue *k=parse_string_val(p);
            char *name=k->str.str;
            free(k);
            skip_ws(p); if(**p!=':'){ fprintf(stderr,"bad object\n"); exit(1);} (*p)++;
            skip_ws(p);
            JsonValue *val=parse_value(p);
            if(v->obj.count==cap){cap=cap?cap*2:4; v->obj.members=realloc(v->obj.members,cap*sizeof(JsonMember));}
            v->obj.members[v->obj.count].name=name;
            v->obj.members[v->obj.count].value=val;
            v->obj.count++;
            skip_ws(p);
            if(**p==','){(*p)++; skip_ws(p); continue;}
            break;
        }
    }
    if(**p=='}')(*p)++;
    return v;
}
static JsonValue* parse_value(const char **p){
    skip_ws(p);
    char c=*(*p);
    if(c=='{') return parse_object(p);
    if(c=='[') return parse_array(p);
    if(c=='"') return parse_string_val(p);
    if(c=='t'){ *p+=4; JsonValue *v=json_new(JV_BOOL); v->bool_val=1; return v; }
    if(c=='f'){ *p+=5; JsonValue *v=json_new(JV_BOOL); v->bool_val=0; return v; }
    if(c=='n'){ *p+=4; JsonValue *v=json_new(JV_NULL); return v; }
    return parse_number_val(p);
}

/* ---------- helpers ---------- */
static JsonValue* find_member(JsonValue *obj, const char *name){
    if(!obj||obj->type!=JV_OBJECT) return NULL;
    for(size_t i=0;i<obj->obj.count;i++) if(strcmp(obj->obj.members[i].name,name)==0) return obj->obj.members[i].value;
    return NULL;
}
static char* decode_pointer_token(const char *tok){
    size_t n=strlen(tok); char *out=malloc(n+1); size_t o=0;
    for(size_t i=0;i<n;i++){
        if(tok[i]=='~' && i+1<n){
            if(tok[i+1]=='0'){ out[o++]='~'; i++; }
            else if(tok[i+1]=='1'){ out[o++]='/'; i++; }
            else out[o++]=tok[i];
        }else out[o++]=tok[i];
    }
    out[o]=0; return out;
}
static JsonValue* resolve_pointer(JsonValue *root, const char *ptr){
    if(!ptr||ptr[0]!='#') return root;
    char *copy=strdup(ptr+1);
    char *tok=strtok(copy,"/");
    JsonValue *cur=root;
    while(tok){
        char *dec=decode_pointer_token(tok);
        if(cur && cur->type==JV_OBJECT) cur=find_member(cur,dec);
        else cur=NULL;
        free(dec);
        tok=strtok(NULL,"/");
    }
    free(copy);
    return cur?cur:root;
}
static int is_integer_num(JsonValue *v){ if(v->type!=JV_NUMBER) return 0; double d=v->num_val; double i; return modf(d,&i)==0; }
static size_t unicode_strlen_utf8(const char *s){
    size_t c=0;
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if((*p&0xC0)!=0x80) c++;
    }
    return c;
}
static int deep_equal(JsonValue *a, JsonValue *b){
    if(!a||!b) return a==b;
    if(a->type!=b->type) return 0;
    switch(a->type){
        case JV_NULL: return 1;
        case JV_BOOL: return a->bool_val==b->bool_val;
        case JV_NUMBER: return a->num_val==b->num_val;
        case JV_STRING: return a->str.len==b->str.len && memcmp(a->str.str,b->str.str,a->str.len)==0;
        case JV_ARRAY:
            if(a->arr.count!=b->arr.count) return 0;
            for(size_t i=0;i<a->arr.count;i++) if(!deep_equal(a->arr.items[i],b->arr.items[i])) return 0;
            return 1;
        case JV_OBJECT:
            if(a->obj.count!=b->obj.count) return 0;
            for(size_t i=0;i<a->obj.count;i++){
                JsonValue *bv=find_member(b,a->obj.members[i].name);
                if(!bv) return 0;
                if(!deep_equal(a->obj.members[i].value,bv)) return 0;
            }
            return 1;
    }
    return 0;
}

/* ---------- error list ---------- */
typedef struct { char *inst; char *schema; } Err;
typedef struct { Err **data; size_t cnt, cap; } ErrList;
static void errlist_init(ErrList *l){ l->data=NULL; l->cnt=l->cap=0; }
static void errlist_add(ErrList *l, const char *inst, const char *schema){
    if(l->cnt==l->cap){ l->cap=l->cap?l->cap*2:64; l->data=realloc(l->data,l->cap*sizeof(Err*)); }
    Err *e=malloc(sizeof(Err));
    e->inst=strdup(inst); e->schema=strdup(schema);
    l->data[l->cnt++]=e;
}
static int err_cmp(const void *a,const void *b){
    Err *ea=*(Err**)a; Err *eb=*(Err**)b;
    int c=strcmp(ea->inst,eb->inst); if(c) return c;
    return strcmp(ea->schema,eb->schema);
}

/* ---------- validation ---------- */
static int schema_accepts(JsonValue *inst, JsonValue *schema, const char *inst_loc, const char *schema_loc, ErrList *tmp, JsonValue *schema_root);
static void validate_node(JsonValue *inst, JsonValue *schema, const char *inst_loc, const char *schema_loc, ErrList *out, JsonValue *schema_root);

static void validate_schema_obj(JsonValue *inst, JsonValue *schema_obj, const char *inst_loc, const char *schema_loc, ErrList *out, JsonValue *schema_root){
    /* $ref */
    JsonValue *refv=find_member(schema_obj,"$ref");
    if(refv && refv->type==JV_STRING){
        char *refstr=refv->str.str;
        JsonValue *target=resolve_pointer(schema_root,refstr);
        if(target) validate_node(inst,target,inst_loc,refstr,out,schema_root);
    }
    /* collect properties set */
    JsonValue *propsv=find_member(schema_obj,"properties");
    char **prop_names=NULL; size_t prop_cnt=0;
    if(propsv && propsv->type==JV_OBJECT){
        prop_cnt=propsv->obj.count;
        prop_names=malloc(prop_cnt*sizeof(char*));
        for(size_t i=0;i<prop_cnt;i++) prop_names[i]=propsv->obj.members[i].name;
    }
    /* iterate members */
    for(size_t i=0;i<schema_obj->obj.count;i++){
        char *key=schema_obj->obj.members[i].name;
        JsonValue *val=schema_obj->obj.members[i].value;
        if(strcmp(key,"$ref")==0) continue;
        if(strcmp(key,"type")==0){
            int ok=0;
            if(val->type==JV_STRING){
                const char *t=val->str.str;
                if(inst->type==JV_NULL && strcmp(t,"null")==0) ok=1;
                else if(inst->type==JV_BOOL && strcmp(t,"boolean")==0) ok=1;
                else if(inst->type==JV_NUMBER && (strcmp(t,"number")==0 || (strcmp(t,"integer")==0 && is_integer_num(inst)))) ok=1;
                else if(inst->type==JV_STRING && strcmp(t,"string")==0) ok=1;
                else if(inst->type==JV_ARRAY && strcmp(t,"array")==0) ok=1;
                else if(inst->type==JV_OBJECT && strcmp(t,"object")==0) ok=1;
            }else if(val->type==JV_ARRAY){
                for(size_t j=0;j<val->arr.count;j++){
                    JsonValue *tv=val->arr.items[j];
                    if(tv->type!=JV_STRING) continue;
                    const char *t=tv->str.str;
                    if(inst->type==JV_NULL && strcmp(t,"null")==0){ ok=1; break; }
                    if(inst->type==JV_BOOL && strcmp(t,"boolean")==0){ ok=1; break; }
                    if(inst->type==JV_NUMBER && (strcmp(t,"number")==0 || (strcmp(t,"integer")==0 && is_integer_num(inst)))){ ok=1; break; }
                    if(inst->type==JV_STRING && strcmp(t,"string")==0){ ok=1; break; }
                    if(inst->type==JV_ARRAY && strcmp(t,"array")==0){ ok=1; break; }
                    if(inst->type==JV_OBJECT && strcmp(t,"object")==0){ ok=1; break; }
                }
            }
            if(!ok){
                char *sl=join_path(schema_loc,"type");
                errlist_add(out,inst_loc,sl); free(sl);
            }
        }else if(strcmp(key,"enum")==0 && val->type==JV_ARRAY){
            int found=0;
            for(size_t j=0;j<val->arr.count;j++) if(deep_equal(inst,val->arr.items[j])){ found=1; break; }
            if(!found){ char *sl=join_path(schema_loc,"enum"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"const")==0){
            if(!deep_equal(inst,val)){ char *sl=join_path(schema_loc,"const"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"minimum")==0 && inst->type==JV_NUMBER){
            if(inst->num_val < val->num_val){ char *sl=join_path(schema_loc,"minimum"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"maximum")==0 && inst->type==JV_NUMBER){
            if(inst->num_val > val->num_val){ char *sl=join_path(schema_loc,"maximum"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"exclusiveMinimum")==0 && inst->type==JV_NUMBER){
            if(!(inst->num_val > val->num_val)){ char *sl=join_path(schema_loc,"exclusiveMinimum"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"exclusiveMaximum")==0 && inst->type==JV_NUMBER){
            if(!(inst->num_val < val->num_val)){ char *sl=join_path(schema_loc,"exclusiveMaximum"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"minLength")==0 && inst->type==JV_STRING){
            if(unicode_strlen_utf8(inst->str.str) < (size_t)val->num_val){ char *sl=join_path(schema_loc,"minLength"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"maxLength")==0 && inst->type==JV_STRING){
            if(unicode_strlen_utf8(inst->str.str) > (size_t)val->num_val){ char *sl=join_path(schema_loc,"maxLength"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"minItems")==0 && inst->type==JV_ARRAY){
            if(inst->arr.count < (size_t)val->num_val){ char *sl=join_path(schema_loc,"minItems"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"maxItems")==0 && inst->type==JV_ARRAY){
            if(inst->arr.count > (size_t)val->num_val){ char *sl=join_path(schema_loc,"maxItems"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"uniqueItems")==0 && val->type==JV_BOOL && val->bool_val && inst->type==JV_ARRAY){
            int dup=0;
            for(size_t a=0;a<inst->arr.count && !dup;a++) for(size_t b=a+1;b<inst->arr.count;b++) if(deep_equal(inst->arr.items[a],inst->arr.items[b])) dup=1;
            if(dup){ char *sl=join_path(schema_loc,"uniqueItems"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"prefixItems")==0 && val->type==JV_ARRAY && inst->type==JV_ARRAY){
            size_t lim=val->arr.count<inst->arr.count?val->arr.count:inst->arr.count;
            for(size_t i=0;i<lim;i++){
                char idxbuf[32]; sprintf(idxbuf,"%zu",i);
                char *il=join_path(inst_loc,idxbuf);
                char *sl=join_path(schema_loc,"prefixItems");
                char *sl2=malloc(strlen(sl)+32); sprintf(sl2,"%s/%zu",sl,i); free(sl);
                validate_node(inst->arr.items[i],val->arr.items[i],il,sl2,out,schema_root);
                free(il); free(sl2);
            }
        }else if(strcmp(key,"items")==0){
            if(inst->type==JV_ARRAY){
                size_t start=0;
                JsonValue *pref=find_member(schema_obj,"prefixItems");
                if(pref && pref->type==JV_ARRAY) start=pref->arr.count;
                for(size_t i=start;i<inst->arr.count;i++){
                    char idxbuf[32]; sprintf(idxbuf,"%zu",i);
                    char *il=join_path(inst_loc,idxbuf);
                    char *sl=join_path(schema_loc,"items");
                    validate_node(inst->arr.items[i],val,il,sl,out,schema_root);
                    free(il); free(sl);
                }
            }
        }else if(strcmp(key,"properties")==0 && inst->type==JV_OBJECT){
            for(size_t i=0;i<val->obj.count;i++){
                char *pname=val->obj.members[i].name;
                JsonValue *pval=val->obj.members[i].value;
                JsonValue *iv=find_member(inst,pname);
                if(iv){
                    char *et=escape_pointer(pname);
                    char *il=join_path(inst_loc,et);
                    char *sl=join_path(schema_loc,"properties");
                    char *sl2=malloc(strlen(sl)+strlen(et)+2); sprintf(sl2,"%s/%s",sl,et); free(sl); free(et);
                    validate_node(iv,pval,il,sl2,out,schema_root);
                    free(il); free(sl2);
                }
            }
        }else if(strcmp(key,"required")==0 && inst->type==JV_OBJECT && val->type==JV_ARRAY){
            for(size_t j=0;j<val->arr.count;j++){
                JsonValue *nv=val->arr.items[j];
                if(nv->type!=JV_STRING) continue;
                if(!find_member(inst,nv->str.str)){
                    char idxbuf[32]; sprintf(idxbuf,"%zu",j);
                    char *sl=join_path(schema_loc,"required");
                    char *sl2=malloc(strlen(sl)+strlen(idxbuf)+2); sprintf(sl2,"%s/%s",sl,idxbuf); free(sl);
                    errlist_add(out,inst_loc,sl2); free(sl2);
                }
            }
        }else if(strcmp(key,"additionalProperties")==0 && inst->type==JV_OBJECT){
            for(size_t i=0;i<inst->obj.count;i++){
                char *iname=inst->obj.members[i].name;
                int isProp=0;
                for(size_t k=0;k<prop_cnt;k++) if(strcmp(prop_names[k],iname)==0){ isProp=1; break; }
                if(isProp) continue;
                char *et=escape_pointer(iname);
                char *il=join_path(inst_loc,et);
                char *sl=join_path(schema_loc,"additionalProperties");
                validate_node(inst->obj.members[i].value,val,il,sl,out,schema_root);
                free(il); free(et); free(sl);
            }
        }else if(strcmp(key,"minProperties")==0 && inst->type==JV_OBJECT){
            if(inst->obj.count < (size_t)val->num_val){ char *sl=join_path(schema_loc,"minProperties"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"maxProperties")==0 && inst->type==JV_OBJECT){
            if(inst->obj.count > (size_t)val->num_val){ char *sl=join_path(schema_loc,"maxProperties"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"allOf")==0 && val->type==JV_ARRAY){
            for(size_t i=0;i<val->arr.count;i++){
                char idxbuf[32]; sprintf(idxbuf,"%zu",i);
                char *sl=join_path(schema_loc,"allOf");
                char *sl2=malloc(strlen(sl)+strlen(idxbuf)+2); sprintf(sl2,"%s/%s",sl,idxbuf); free(sl);
                validate_node(inst,val->arr.items[i],inst_loc,sl2,out,schema_root);
                free(sl2);
            }
        }else if(strcmp(key,"anyOf")==0 && val->type==JV_ARRAY){
            int any=0;
            ErrList tmp; errlist_init(&tmp);
            for(size_t i=0;i<val->arr.count;i++){
                ErrList sub; errlist_init(&sub);
                validate_node(inst,val->arr.items[i],inst_loc,schema_loc,&sub,schema_root);
                if(sub.cnt==0) any=1;
                // discard sub
            }
            if(!any){ char *sl=join_path(schema_loc,"anyOf"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"oneOf")==0 && val->type==JV_ARRAY){
            int cnt=0;
            for(size_t i=0;i<val->arr.count;i++){
                ErrList tmp2; errlist_init(&tmp2);
                int accepts=schema_accepts(inst,val->arr.items[i],inst_loc,schema_loc,&tmp2,schema_root);
                if(accepts) cnt++;
            }
            if(cnt!=1){ char *sl=join_path(schema_loc,"oneOf"); errlist_add(out,inst_loc,sl); free(sl); }
        }else if(strcmp(key,"not")==0){
            ErrList tmp; errlist_init(&tmp);
            int accepts=schema_accepts(inst,val,inst_loc,schema_loc,&tmp,schema_root);
            if(accepts){ char *sl=join_path(schema_loc,"not"); errlist_add(out,inst_loc,sl); free(sl); }
        }
    }
    if(prop_names) free(prop_names);
}
static void validate_node(JsonValue *inst, JsonValue *schema, const char *inst_loc, const char *schema_loc, ErrList *out, JsonValue *schema_root){
    if(!schema) return;
    if(schema->type==JV_BOOL){
        if(!schema->bool_val) errlist_add(out,inst_loc,schema_loc);
        return;
    }
    if(schema->type==JV_OBJECT) validate_schema_obj(inst,schema,inst_loc,schema_loc,out,schema_root);
}
static int schema_accepts(JsonValue *inst, JsonValue *schema, const char *inst_loc, const char *schema_loc, ErrList *tmp, JsonValue *schema_root){
    ErrList el; errlist_init(&el);
    validate_node(inst,schema,inst_loc,schema_loc,&el,schema_root);
    int ok=el.cnt==0;
    return ok;
}

/* ---------- main ---------- */
int main(int argc,char **argv){
    if(argc<2){ fprintf(stderr,"usage\n"); return 1; }
    FILE *f=fopen("schema.json","r"); if(!f){ perror("schema.json"); return 1; }
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET); char *buf=malloc(sz+1); fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    const char *p=buf; JsonValue *schema_root=parse_value(&p);
    FILE *fi=fopen("instances.json","r"); if(!fi){ perror("instances.json"); return 1; }
    fseek(fi,0,SEEK_END); long sz2=ftell(fi); fseek(fi,0,SEEK_SET); char *buf2=malloc(sz2+1); fread(buf2,1,sz2,fi); buf2[sz2]=0; fclose(fi);
    const char *p2=buf2; JsonValue *inst_arr=parse_value(&p2);
    if(!inst_arr||inst_arr->type!=JV_ARRAY){ fprintf(stderr,"instances not array\n"); return 1; }
    int valid=0, invalid=0;
    for(size_t i=0;i<inst_arr->arr.count;i++){
        ErrList el; errlist_init(&el);
        char inst_loc[64]; sprintf(inst_loc,"#/%zu",i);
        validate_node(inst_arr->arr.items[i],schema_root,inst_loc,"#",&el,schema_root);
        if(el.cnt==0){ printf("%zu: valid\n",i); valid++; }
        else{
            qsort(el.data,el.cnt,sizeof(Err*),err_cmp);
            size_t uniq=0;
            for(size_t k=0;k<el.cnt;k++){
                if(k>0 && strcmp(el.data[k]->inst,el.data[uniq-1]->inst)==0 && strcmp(el.data[k]->schema,el.data[uniq-1]->schema)==0) continue;
                if(k!=uniq) el.data[uniq]=el.data[k];
                uniq++;
            }
            printf("%zu: invalid (%zu)\n",i,uniq);
            for(size_t k=0;k<uniq;k++) printf("  %s %s\n",el.data[k]->inst,el.data[k]->schema);
            invalid++;
        }
    }
    printf("valid=%d invalid=%d\n",valid,invalid);
    return 0;
}

import Foundation

// MARK: - Utilities

func detectLineBreak(_ data: Data) -> [UInt8] {
    if data.range(of: Data([13,10])) != nil { return [13,10] }
    return [10]
}
func lineBreakString(_ lb: [UInt8]) -> String {
    return String(bytes: lb, encoding: .utf8) ?? "\n"
}

// quoted string
func quote(_ s: String) -> String {
    var out = "\""
    for scalar in s.unicodeScalars {
        let v = scalar.value
        if v == 92 { out += "\\\\" }
        else if v == 34 { out += "\\\"" }
        else if v == 10 { out += "\\n" }
        else if v == 9 { out += "\\t" }
        else if v < 0x20 || (v >= 0x7f && v <= 0x9f) {
            out += String(format:"\\u%04x", v)
        } else {
            out += String(scalar)
        }
    }
    out += "\""
    return out
}

// CRC-32
struct CRC32 {
    static let table: [UInt32] = {
        var t = [UInt32](repeating:0,count:256)
        for i in 0..<256 {
            var c = UInt32(i)
            for _ in 0..<8 {
                if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1) } else { c >>= 1 }
            }
            t[i] = c
        }
        return t
    }()
    static func crc32(_ data: Data) -> UInt32 {
        var crc: UInt32 = 0xffffffff
        for b in data {
            let idx = Int((crc ^ UInt32(b)) & 0xff)
            crc = CRC32.table[idx] ^ (crc >> 8)
        }
        return crc ^ 0xffffffff
    }
}

// MARK: - Header parsing

func parseHeaderLine(_ line: String, into dict: inout [String:String]) {
    guard let colon = line.firstIndex(of: ":") else { return }
    let name = String(line[..<colon]).trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    var value = String(line[line.index(after: colon)...]).trimmingCharacters(in: .whitespacesAndNewlines)
    dict[name] = value
}

func parseHeaders(data: Data, start: Int, bodyStart: Int, lineBreak: [UInt8]) -> [String:String] {
    let headerData = data[start..<bodyStart]
    guard let headerString = String(data: headerData, encoding: .utf8) else { return [:] }
    let lbStr = lineBreakString(lineBreak)
    let lines = headerString.components(separatedBy: lbStr)
    var dict: [String:String] = [:]
    var current = ""
    for line in lines {
        if line.isEmpty { break }
        if current.isEmpty { current = line }
        else {
            if let first = line.first, first == " " || first == "\t" {
                current += line
            } else {
                parseHeaderLine(current, into: &dict)
                current = line
            }
        }
    }
    if !current.isEmpty { parseHeaderLine(current, into: &dict) }
    return dict
}

// MARK: - Encoded-words

func normalizeCharset(_ raw: String) -> String {
    var c = raw
    if let idx = c.firstIndex(of: "*") { c = String(c[..<idx]) }
    return c.lowercased()
}

func decodeQ(_ s: String) -> Data {
    var bytes = [UInt8]()
    var i = s.startIndex
    while i < s.endIndex {
        let ch = s[i]
        if ch == "_" {
            bytes.append(0x20)
            i = s.index(after: i)
        } else if ch == "=" {
            let next1 = s.index(after: i)
            if next1 < s.endIndex && s.index(after: next1) < s.endIndex {
                let hex = String(s[next1...s.index(after: next1)])
                if let v = UInt8(hex, radix: 16) {
                    bytes.append(v)
                    i = s.index(i, offsetBy: 3)
                    continue
                }
            }
            bytes.append(0x3d)
            i = s.index(after: i)
        } else {
            bytes.append(UInt8(ch.unicodeScalars.first!.value))
            i = s.index(after: i)
        }
    }
    return Data(bytes)
}

func decodeBytesWithCharset(_ data: Data, charset: String) -> String {
    let cs = charset.lowercased()
    if cs == "us-ascii" || cs == "ascii" {
        return String(data: data, encoding: .ascii) ?? ""
    }
    if cs == "utf-8" {
        return String(data: data, encoding: .utf8) ?? ""
    }
    if cs == "iso-8859-1" {
        var s = ""
        for b in data { s.append(UnicodeScalar(b)) }
