            case 0x84: cp = 0x201E
            case 0x85: cp = 0x2026
            case 0x86: cp = 0x2020
            case 0x87: cp = 0x2021
            case 0x88: cp = 0x02C6
            case 0x89: cp = 0x2030
            case 0x8A: cp = 0x0160
            case 0x8B: cp = 0x2039
            case 0x8C: cp = 0x0152
            case 0x8D: cp = 0x008D
            case 0x8E: cp = 0x017D
            case 0x8F: cp = 0x008F
            case 0x90: cp = 0x0090
            case 0x91: cp = 0x2018
            case 0x92: cp = 0x2019
            case 0x93: cp = 0x201C
            case 0x94: cp = 0x201D
            case 0x95: cp = 0x2022
            case 0x96: cp = 0x2013
            case 0x97: cp = 0x2014
            case 0x98: cp = 0x02DC
            case 0x99: cp = 0x2122
            case 0x9A: cp = 0x0161
            case 0x9B: cp = 0x203A
            case 0x9C: cp = 0x0153
            case 0x9D: cp = 0x009D
            case 0x9E: cp = 0x017E
            case 0x9F: cp = 0x0178
