            }
            s.append(Character(UnicodeScalar(cp)!))
        }
        return s
    }
    // fallback
    return String(data: data, encoding: .utf8) ?? ""
}

func decodeEncodedWords(_ s: String) -> String {
    // simple regex based implementation
    let pattern = "=\\?([^?\\s]+)\\?(B|Q)\\?([^?\\s]*?)\\?="
    guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else { return s }
    let ns = s as NSString
    let matches = regex.matches(in: s, range: NSRange(location: 0, length: ns.length))
    var result = ""
    var pos = 0
    var idx = 0
    while pos < s.utf16.count {
        if idx < matches.count {
            let m = matches[idx]
            let range = m.range
            if range.location == pos {
                // collect run
                var runBytes = Data()
                var runCharset = ""
                var currentIdx = idx
                var lastEnd = range.upperBound
                var first = true
                while currentIdx < matches.count {
                    let mm = matches[currentIdx]
                    let r = mm.range
                    if r.location > lastEnd {
                        // check gap spaces/tabs
                        let gap = (s as NSString).substring(with: NSRange(location: lastEnd, length: r.location - lastEnd))
                        if gap.allSatisfy({ $0 == " " || $0 == "\t" }) {
                            // continue
                        } else { break }
                    }
                    let charsetRaw = (s as NSString).substring(with: mm.range(at: 1))
                    let enc = (s as NSString).substring(with: mm.range(at: 2)).uppercased()
                    let txt = (s as NSString).substring(with: mm.range(at: 3))
                    let norm = normalizeCharset(charsetRaw)
                    if first {
                        runCharset = norm
                        first = false
                    } else if normalizeCharset(charsetRaw) != runCharset {
                        break
                    }
                    var bytes = Data()
                    if enc == "B" {
                        if let d = Data(base64Encoded: txt, options: .ignoreUnknownCharacters) { bytes = d }
                    } else {
                        bytes = decodeQ(txt)
                    }
                    runBytes.append(bytes)
                    lastEnd = r.upperBound
                    currentIdx += 1
                }
                let decoded = decodeBytesWithCharset(runBytes, charset: runCharset)
                result += decoded
                pos = lastEnd
                idx = currentIdx
                continue
            }
        }
        // copy char
        let ch = (s as NSString).substring(with: NSRange(location: pos, length: 1))
        result += ch
        pos += 1
    }
    return result
}

// MARK: - Parameter parsing

func parseParameters(_ value: String) -> [(name:String, value:String)] {
    var res: [(String,String)] = []
    let parts = value.split(separator: ";", omittingEmptySubsequences: false)
    for p in parts {
        let s = p.trimmingCharacters(in: .whitespacesAndNewlines)
        if s.isEmpty { continue }
        if let eq = s.firstIndex(of: "=") {
            let name = String(s[..<eq]).trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            var val = String(s[s.index(after: eq)...]).trimmingCharacters(in: .whitespacesAndNewlines)
            if val.hasPrefix("\"") && val.hasSuffix("\"") {
                val = String(val.dropFirst().dropLast())
                val = val.replacingOccurrences(of: "\\\"", with: "\"").replacingOccurrences(of: "\\\\", with: "\\")
            }
            res.append((name,val))
        }
    }
    return res
}

func parseContentType(_ header: String?) -> (type:String, subtype:String, params:[String:String]) {
    guard let h = header else { return ("text","plain",[:]) }
    let parts = parseParameters(h)
    guard let first = parts.first else { return ("text","plain",[:]) }
    var main = first.name
    var params: [String:String] = [:]
    for p in parts.dropFirst() { params[p.name] = p.value }
    if let slash = main.firstIndex(of: "/") {
        let t = String(main[..<slash]).lowercased()
        let sub = String(main[main.index(after: slash)...]).lowercased()
        return (t, sub, params)
    }
    return (main.lowercased(), "", params)
}

// MARK: - Entity model

struct Node {
    var type: String
    var subtype: String
    var isMultipart: Bool
    var parts: [Node] = []
    var charset: String = "us-ascii"
    var cte: String = "7bit"
    var text: String? = nil
    var textChars: Int = 0
    var disposition: String = "-"
    var name: String? = nil
    var size: Int = 0
    var crc32: UInt32 = 0
}

// MARK: - Transfer decoding

func decodeTransfer(_ data: Data, encoding: String) -> Data {
    let enc = encoding.lowercased()
    if enc == "base64" {
        let str = String(data: data, encoding: .ascii) ?? ""
        let filtered = str.filter { $0.isLetter || $0.isNumber || $0 == "+" || $0 == "/" || $0 == "=" }
        return Data(base64Encoded: filtered, options: .ignoreUnknownCharacters) ?? Data()
    }
    if enc == "quoted-printable" {
        var out = Data()
        let bytes = [UInt8](data)
        var i = 0
        var lineEnd = 0
        while i < bytes.count {
            // find line end
            var j = i
            while j < bytes.count && bytes[j] != 10 && bytes[j] != 13 { j += 1 }
            let line = bytes[i..<j]
            // remove trailing spaces/tabs
            var lineTrim = Array(line)
            while let last = lineTrim.last, last == 32 || last == 9 { lineTrim.removeLast() }
            // soft line break
            if let last = lineTrim.last, last == 61 {
                // remove = and join
                lineTrim.removeLast()
                // skip line break
            } else {
                // keep line break
            }
            // decode =XY
            var k = 0
            while k < lineTrim.count {
                if lineTrim[k] == 61 && k+2 < lineTrim.count {
                    let hi = lineTrim[k+1], lo = lineTrim[k+2]
                    let hex = String(format:"%02X", hi) + String(format:"%02X", lo)
                    // Actually need hex digits
                    if let v = UInt8(String(UnicodeScalar(hi)!)+String(UnicodeScalar(lo)!), radix:16) {
                        out.append(v)
                        k += 3
                        continue
                    }
                }
                out.append(lineTrim[k])
                k += 1
            }
            i = j
            if i < bytes.count && (bytes[i]==10 || bytes[i]==13) {
                // keep line break unless soft
                if !(lineTrim.last == 61) {
                    out.append(bytes[i])
                }
                i += 1
                if bytes[i-1]==13 && i < bytes.count && bytes[i]==10 { i += 1 }
            }
        }
        return out
    }
    return data
}

// MARK: - Body start finder

func findHeaderEnd(data: Data, start: Int, end: Int, lineBreak: [UInt8]) -> Int {
    var i = start
    var lineStart = start
    let lb = lineBreak
    while i < end {
        if lb.count == 2 {
            if i+1 < end && data[i]==13 && data[i+1]==10 {
                if lineStart == i { return i+2 }
                lineStart = i+2
                i += 2
            } else { i += 1 }
        } else {
            if data[i]==10 {
                if lineStart == i { return i+1 }
                lineStart = i+1
                i += 1
            } else { i += 1 }
        }
    }
    return end
}

// MARK: - Parse entity

func parseEntity(data: Data, range: Range<Int>, lineBreak: [UInt8]) -> Node {
    let start = range.lowerBound
    let end = range.upperBound
    let bodyStart = findHeaderEnd(data: data, start: start, end: end, lineBreak: lineBreak)
    let headers = parseHeaders(data: data, start: start, bodyStart: bodyStart, lineBreak: lineBreak)
    let ctHeader = headers["content-type"]
    let (typ, sub, ctParams) = parseContentType(ctHeader)
    let cteHeader = headers["content-transfer-encoding"]?.lowercased() ?? "7bit"
    let cte = cteHeader
    var node = Node()
    node.type = typ
    node.subtype = sub
    node.cte = cte
    // disposition
    if let cdHeader = headers["content-disposition"] {
        let cdParts = parseParameters(cdHeader)
        if let first = cdParts.first {
            node.disposition = first.name.lowercased()
        }
        // name extraction simplified
        // filename from params
        var nameFound: String? = nil
        for p in cdParts {
            if p.name == "filename" {
                nameFound = decodeEncodedWords(p.value)
                break
            }
        }
        if nameFound == nil {
            // try content-type name
            if let nameParam = ctParams["name"] {
                nameFound = decodeEncodedWords(nameParam)
            }
        }
        node.name = nameFound
    }
    // charset default
    if typ.lowercased() == "text" {
        node.charset = ctParams["charset"]?.lowercased() ?? "us-ascii"
    }
    // multipart handling
    if typ.lowercased() == "multipart" {
        node.isMultipart = true
        let boundary = ctParams["boundary"] ?? ""
        // parse parts
        var parts: [Node] = []
        var lastPos = bodyStart
        var searchPos = bodyStart
        let b = boundary
        while true {
            // find delimiter
            let delim = "--\(b)"
            guard let rangeDelim = data.range(of: Data(delim.utf8), options: [], in: searchPos..<end) else { break }
            let delimPos = rangeDelim.lowerBound
            // check line start
            if delimPos != bodyStart && data[delimPos-1] != 10 && data[delimPos-1] != 13 { searchPos = delimPos+1; continue }
            // find line end
            var lineEnd = delimPos
            while lineEnd < end && data[lineEnd] != 10 && data[lineEnd] != 13 { lineEnd += 1 }
            // check close
            let lineData = data[delimPos..<lineEnd]
            let lineStr = String(data: lineData, encoding: .utf8) ?? ""
            let isClose = lineStr.hasPrefix("--\(b)--")
            let partRange = lastPos..<delimPos
            if partRange.lowerBound < partRange.upperBound {
                let child = parseEntity(data: data, range: partRange, lineBreak: lineBreak)
                parts.append(child)
            }
            // advance
            var after = lineEnd
            if after < end && data[after]==13 && after+1<end && data[after+1]==10 { after += 2 }
            else if after < end && (data[after]==10 || data[after]==13) { after += 1 }
            if isClose { break }
            lastPos = after
            searchPos = after
        }
        node.parts = parts
        return node
    } else {
        // leaf
        let bodyData = data[bodyStart..<end]
        let decoded = decodeTransfer(bodyData, encoding: cte)
        node.size = decoded.count
        node.crc32 = CRC32.crc32(decoded)
        if typ.lowercased() == "text" && node.disposition != "attachment" {
            // decode charset
            let txt = decodeBytesWithCharset(decoded, charset: node.charset)
            var normalized = txt.replacingOccurrences(of: "\r\n", with: "\n")
            normalized = normalized.replacingOccurrences(of: "\r", with: "\n")
            node.text = normalized
            node.textChars = normalized.unicodeScalars.count
        }
        return node
    }
}

// MARK: - Main

func processFile(at path: String) {
    let url = URL(fileURLWithPath: path)
    guard let data = try? Data(contentsOf: url) else { return }
    let lb = detectLineBreak(data)
    let root = parseEntity(data: data, range: 0..<data.count, lineBreak: lb)
    // headers for From/Subject
    let bodyStart = findHeaderEnd(data: data, start: 0, end: data.count, lineBreak: lb)
    let headers = parseHeaders(data: data, start: 0, bodyStart: bodyStart, lineBreak: lb)
    let fromVal = headers["from"].map { decodeEncodedWords($0) } ?? "-"
    let subjVal = headers["subject"].map { decodeEncodedWords($0) } ?? "-"
    print("== \(url.lastPathComponent)")
    print("From: \(quote(fromVal))")
    print("Subject: \(quote(subjVal))")
    func printNode(_ n: Node, depth: Int) {
        let indent = String(repeating: "  ", count: depth)
        if n.isMultipart {
            print("\(indent)multipart/\(n.subtype) parts=\(n.parts.count)")
            for p in n.parts { printNode(p, depth: depth+1) }
        } else if n.type.lowercased() == "text" && n.disposition != "attachment" {
            print("\(indent)text/\(n.subtype) charset=\(n.charset) cte=\(n.cte) chars=\(n.textChars)")
            if let txt = n.text {
                print("\(indent)  \(quote(txt))")
            }
        } else {
            let nameStr = n.name.map { quote($0) } ?? "-"
            print("\(indent)\(n.type)/\(n.subtype) cte=\(n.cte) disposition=\(n.disposition) name=\(nameStr) size=\(n.size) crc32=\(String(format:"%08x", n.crc32))")
        }
    }
    printNode(root, depth: 0)
}

