func decodeBytesWithCharset(_ data:Data, charset:String)->String {
    let cs=charset.lowercased()
    if cs=="us-ascii" || cs=="ascii" { return String(data:data,encoding:.ascii) ?? "" }
    if cs=="utf-8" { return String(data:data,encoding:.utf8) ?? "" }
    if cs=="iso-8859-1" {
        var s=""
        for b in data { s.append(Character(UnicodeScalar(b))) }
        return s
    }
    if cs=="windows-1252" {
        var s=""
        for b in data {
            let cp:UInt32
            switch b {
            case 0x80: cp=0x20AC; case 0x81: cp=0x0081; case 0x82: cp=0x201A; case 0x83: cp=0x0192; case 0x84: cp=0x201E; case 0x85: cp=0x2026; case 0x86: cp=0x2020; case 0x87: cp=0x2021
            case 0x88: cp=0x02C6; case 0x89: cp=0x2030; case 0x8A: cp=0x0160; case 0x8B: cp=0x2039; case 0x8C: cp=0x0152; case 0x8D: cp=0x008D; case 0x8E: cp=0x017D; case 0x8F: cp=0x008F
            case 0x90: cp=0x0090; case 0x91: cp=0x2018; case 0x92: cp=0x2019; case 0x93: cp=0x201C; case 0x94: cp=0x201D; case 0x95: cp=0x2022; case 0x96: cp=0x2013; case 0x97: cp=0x2014
            case 0x98: cp=0x02DC; case 0x99: cp=0x2122; case 0x9A: cp=0x0161; case 0x9B: cp=0x203A; case 0x9C: cp=0x0153; case 0x9D: cp=0x009D; case 0x9E: cp=0x017E; case 0x9F: cp=0x0178
            default: cp=UInt32(b)
            }
            s.append(Character(UnicodeScalar(cp)!))
        }
        return s
    }
    return String(data:data,encoding:.utf8) ?? ""
}
func decodeEncodedWords(_ s:String)->String {
    let pattern="=\\?([^?\\s]+)\\?(B|Q)\\?([^?\\s]*?)\\?="
    guard let re=try? NSRegularExpression(pattern:pattern,options:[.caseInsensitive]) else { return s }
    let ns=s as NSString
    let matches=re.matches(in:s,range:NSRange(location:0,length:ns.length))
    var result=""
    var pos=0
    var idx=0
    while pos <= s.utf16.count {
        if idx < matches.count {
            let m=matches[idx]
            let r=m.range
            if r.location >= pos {
                let loc=r.location
                if loc==pos {
                    var runBytes=Data()
                    var runCharset=""
                    var first=true
                    var lastEnd=r.upperBound
                    var curIdx=idx
                    while curIdx < matches.count {
                        let mm=matches[curIdx]
                        let rr=mm.range
                        if rr.location > lastEnd {
                            let gap=(s as NSString).substring(with:NSRange(location:lastEnd,length:rr.location-lastEnd))
                            if !gap.allSatisfy({$0==" "||$0=="\t"}) { break }
                        }
                        let charsetRaw=(s as NSString).substring(with:mm.range(at:1))
                        let enc=(s as NSString).substring(with:mm.range(at:2)).uppercased()
                        let txt=(s as NSString).substring(with:mm.range(at:3))
                        let norm=normCharset(charsetRaw)
                        if first { runCharset=norm; first=false }
                        else if norm != runCharset { break }
                        var bytes=Data()
                        if enc=="B" {
                            if let d=Data(base64Encoded:txt,options:.ignoreUnknownCharacters){ bytes=d }
                        } else { bytes=decodeQ(txt) }
                        runBytes.append(bytes)
                        lastEnd=rr.upperBound
                        curIdx+=1
                    }
                    result+=decodeBytesWithCharset(runBytes,charset:runCharset)
                    pos=lastEnd
                    idx=curIdx
                    continue
                }
            }
        }
        if pos >= s.utf16.count { break }
        let ch=(s as NSString).substring(with:NSRange(location:pos,length:1))
        result+=ch
        pos+=1
    }
    return result
}

// MARK: - Params

func parseParams(_ value:String)->[(String,String)] {
    var res=[(String,String)]()
    let parts=value.split(separator:";",omittingEmptySubsequences:false)
    for p in parts {
        let s=p.trimmingCharacters(in:.whitespaces)
        if s.isEmpty { continue }
        if let eq=s.firstIndex(of:"=") {
            let name=String(s[..<eq]).trimmingCharacters(in:.whitespaces).lowercased()
            var val=String(s[s.index(after:eq)...]).trimmingCharacters(in:.whitespaces)
            if val.hasPrefix("\"") && val.hasSuffix("\"") {
                val=String(val.dropFirst().dropLast())
            }
            res.append((name,val))
        }
    }
    return res
}
func parseContentType(_ header:String?)->(String,String,[String:String]) {
    guard let h=header else { return ("text","plain",[:]) }
    let parts=parseParams(h)
    guard let first=parts.first else { return ("text","plain",[:]) }
    var main=first.name
    var params=[String:String]()
    for p in parts.dropFirst(){ params[p.name]=p.value }
    if let slash=main.firstIndex(of:"/") {
        let t=String(main[..<slash]).lowercased()
        let sub=String(main[main.index(after:slash)...]).lowercased()
        return (t,sub,params)
    }
    return (main.lowercased(),"",params)
}

// MARK: - Transfer

func decodeTransfer(_ data:Data, encoding:String)->Data {
    let enc=encoding.lowercased()
    if enc=="base64" {
        let str=String(data:data,encoding:.ascii) ?? ""
        let filtered=str.filter { $0.isLetter || $0.isNumber || $0=="+" || $0=="/" || $0=="=" }
        return Data(base64Encoded:filtered,options:.ignoreUnknownCharacters) ?? Data()
    }
    if enc=="quoted-printable" {
        guard let str=String(data:data,encoding:.isoLatin1) else { return data }
        var lines=str.components(separatedBy:"\r\n")
        if !str.contains("\r\n") { lines=str.components(separatedBy:"\n") }
        var out=""
        var i=0
        while i<lines.count {
            var line=lines[i]
            while line.last?.unicodeScalars.first?.value == 32 || line.last?.unicodeScalars.first?.value == 9 {
                line.removeLast()
            }
            if line.hasSuffix("=") {
                line.removeLast()
                i+=1
                continue
            }
            var decoded=""
            var j=line.startIndex
            while j<line.endIndex {
                if line[j]=="=" {
                    let n1=line.index(after:j)
                    if n1<line.endIndex {
                        let n2=line.index(after:n1)
                        if n2<line.endIndex {
                            let hex=String(line[n1...n2])
                            if let v=UInt8(hex,radix:16) {
                                decoded.append(Character(UnicodeScalar(v)))
                                j=line.index(after:n2)
                                continue
                            }
                        }
                    }
                }
                decoded.append(line[j])
                j=line.index(after:j)
            }
            out+=decoded
            if i+1<lines.count { out+="\n" }
            i+=1
        }
        return Data(out.utf8)
    }
    return data
}

// MARK: - Node

struct Node {
    var type:String="text"
    var subtype:String="plain"
    var isMultipart:Bool=false
    var parts:[Node]=[]
    var charset:String="us-ascii"
    var cte:String="7bit"
    var text:String? = nil
    var textChars:Int=0
    var disposition:String="-"
    var name:String? = nil
    var size:Int=0
    var crc32:UInt32=0
}

// MARK: - Parse entity

func parseEntity(data:Data, range:Range<Int>, lb:[UInt8])->Node {
    let start=range.lowerBound
    let end=range.upperBound
    let bodyStart=findHeaderEnd(data:data,start:start,end:end,lb:lb)
    let headers=parseHeaders(data:data,start:start,bodyStart:bodyStart,lb:lb)
    let ctHeader=headers["content-type"]
    let (typ,sub,ctParams)=parseContentType(ctHeader)
    let cte=headers["content-transfer-encoding"]?.lowercased() ?? "7bit"
    var node=Node()
    node.type=typ; node.subtype=sub; node.cte=cte
    if let cd=headers["content-disposition"] {
        let cdParts=parseParams(cd)
        if let first=cdParts.first { node.disposition=first.name.lowercased() }
    }
    if typ.lowercased()=="text" {
        node.charset=ctParams["charset"]?.lowercased() ?? "us-ascii"
    }
    if typ.lowercased()=="multipart" {
        node.isMultipart=true
        let boundary=ctParams["boundary"] ?? ""
        var parts=[Node]()
        var lastPos=bodyStart
        var searchPos=bodyStart
        let delim="--\(boundary)"
        while true {
            guard let r=data.range(of:Data(delim.utf8),options:[],in:searchPos..<end) else { break }
            let pos=r.lowerBound
            // check line start
            let isLineStart = pos==bodyStart || (pos>=2 && (data[pos-2]==13 || data[pos-2]==10))
            if !isLineStart { searchPos=pos+1; continue }
            // check close
            var isClose=false
            if pos+delim.count+2 <= end {
                let closeSeq=Array(data[pos+delim.count..<pos+delim.count+2])
                if closeSeq == [45,45] { isClose=true }
            }
            let partRange=lastPos..<pos
            if partRange.lowerBound < partRange.upperBound {
                let child=parseEntity(data:data,range:partRange,lb:lb)
                parts.append(child)
            }
            var after=pos+delim.count
            if isClose { break }
            // skip line break
            if after<end && data[after]==13 && after+1<end && data[after+1]==10 { after+=2 }
            else if after<end && (data[after]==10 || data[after]==13) { after+=1 }
            lastPos=after
            searchPos=after
        }
        node.parts=parts
        return node
    } else {
        let bodyData=data[bodyStart..<end]
        let decoded=decodeTransfer(bodyData,encoding:cte)
        node.size=decoded.count
        node.crc32=CRC32.crc32(decoded)
        if typ.lowercased()=="text" && node.disposition != "attachment" {
            let txt=decodeBytesWithCharset(decoded,charset:node.charset)
            var norm=txt.replacingOccurrences(of:"\r\n","with":"\n")
            norm=norm.replacingOccurrences(of:"\r","with":"\n")
            node.text=norm
            node.textChars=norm.unicodeScalars.count
        }
        return node
    }
}

// MARK: - Main

func processFile(at path:String) {
    guard let data=try? Data(contentsOf:URL(fileURLWithPath:path)) else { return }
    let lb=detectLineBreak(data)
    let root=parseEntity(data:data,range:0..<data.count,lb:lb)
    let bodyStart=findHeaderEnd(data:data,start:0,end:data.count,lb:lb)
    let headers=parseHeaders(data:data,start:0,bodyStart:bodyStart,lb:lb)
    let fromVal= (headers["from"].map { decodeEncodedWords($0) }) ?? "-"
    let subjVal= (headers["subject"].map { decodeEncodedWords($0) }) ?? "-"
    print("== \(URL(fileURLWithPath:path).lastPathComponent)")
    print("From: \(quote(fromVal))")
    print("Subject: \(quote(subjVal))")
    func printNode(_ n:Node, depth:Int) {
        let ind=String(repeating:"  ",count:depth)
        if n.isMultipart {
            print("\(ind)multipart/\(n.subtype) parts=\(n.parts.count)")
            for p in n.parts { printNode(p,depth:depth+1) }
        } else if n.type.lowercased()=="text" && n.disposition!="attachment" {
            print("\(ind)text/\(n.subtype) charset=\(n.charset) cte=\(n.cte) chars=\(n.textChars)")
            if let t=n.text { print("\(ind)  \(quote(t))") }
        } else {
            let nameStr=n.name.map { quote($0) } ?? "-"
            print("\(ind)\(n.type)/\(n.subtype) cte=\(n.cte) disposition=\(n.disposition) name=\(nameStr) size=\(n.size) crc32=\(String(format:"%08x",n.crc32))")
        }
    }
    printNode(root,depth:0)
}

let args=CommandLine.arguments
guard args.count>=2 else { exit(0) }
let dir=args[1]
let fm=FileManager.default
if let contents=try? fm.contentsOfDirectory(atPath:dir) {
    let files=contents.filter{$0.hasSuffix(".eml")}.sorted()
    for f in files {
        let path=(dir as NSString).appendingPathComponent(f)
        processFile(at:path)
        print("")
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}
impl Parser {
    fn new(s: &str) -> Self {
        Self { chars: s.chars().collect(), pos: 0 }
    }
    fn peek(&self) -> Option<char> { self.chars.get(self.pos).cloned() }
    fn next(&mut self) -> Option<char> { let c = self.peek(); self.pos += 1; c }
    fn skip_ws(&mut self) { while matches!(self.peek(), Some(c) if c.is_whitespace()) { self.pos += 1; } }
    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => self.parse_string(),
            Some('t') => { self.consume_literal("true"); Ok(JsonValue::Bool(true)) }
            Some('f') => { self.consume_literal("false"); Ok(JsonValue::Bool(false)) }
            Some('n') => { self.consume_literal("null"); Ok(JsonValue::Null) }
            Some('-') | Some('0'..='9') => self.parse_number(),
            Some(c) => Err(format!("unexpected char {}", c)),
            None => Err("eof".into()),
        }
    }
    fn consume_literal(&mut self, lit: &str) {
        for _ in 0..lit.len() { self.pos += 1; }
    }
    fn parse_object(&mut self) -> Result<JsonValue, String> {
        assert_eq!(self.next(), Some('{'));
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            let key = match self.parse_string()? { JsonValue::String(s) => s, _ => unreachable!() };
            self.skip_ws();
            if self.next() != Some(':') { return Err("missing :".into()); }
            let val = self.parse_value()?;
            members.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.pos += 1; }
                Some('}') => { self.pos += 1; break; }
                _ => return Err("object separator".into()),
            }
        }
        Ok(JsonValue::Object(members))
    }
    fn parse_array(&mut self) -> Result<JsonValue, String> {
        assert_eq!(self.next(), Some('['));
        let mut elems = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') { self.pos += 1; return Ok(JsonValue::Array(elems)); }
        loop {
            let v = self.parse_value()?;
            elems.push(v);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.pos += 1; }
                Some(']') => { self.pos += 1; break; }
                _ => return Err("array separator".into()),
            }
        }
        Ok(JsonValue::Array(elems))
    }
    fn parse_string(&mut self) -> Result<JsonValue, String> {
        assert_eq!(self.next(), Some('"'));
        let mut s = String::new();
        loop {
            let c = self.next().ok_or("unterminated string")?;
            if c == '"' { return Ok(JsonValue::String(s)); }
            if c == '\\' {
                let esc = self.next().ok_or("bad escape")?;
                match esc {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\x08'),
                    'f' => s.push('\x0c'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let hex: String = (0..4).map(|_| self.next().ok_or("bad \\u")?).collect();
                        let cp = u32::from_str_radix(&hex, 16).map_err(|_| "bad hex")?;
                        if let Some(ch) = std::char::from_u32(cp) { s.push(ch); }
                        else { s.push('\u{FFFD}'); }
                    }
                    _ => s.push(esc),
                }
            } else {
                s.push(c);
            }
        }
    }
    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        if self.peek() == Some('-') { self.pos += 1; }
        while matches!(self.peek(), Some('0'..='9')) { self.pos += 1; }
        if self.peek() == Some('.') { self.pos += 1; while matches!(self.peek(), Some('0'..='9')) { self.pos += 1; } }
        if matches!(self.peek(), Some('e')|Some('E')) { self.pos += 1; if matches!(self.peek(), Some('+')|Some('-')) { self.pos += 1; } while matches!(self.peek(), Some('0'..='9')) { self.pos += 1; } }
        let txt: String = self.chars[start..self.pos].iter().collect();
        let num: f64 = txt.parse().map_err(|_| "bad number")?;
        Ok(JsonValue::Number(num))
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut p = Parser::new(s);
    let v = p.parse_value()?;
    p.skip_ws();
    Ok(v)
}

fn json_type(v: &JsonValue) -> &'static str {
    match v {
        JsonValue::Null => "null",
        JsonValue::Bool(_) => "boolean",
        JsonValue::Number(_) => "number",
        JsonValue::String(_) => "string",
        JsonValue::Array(_) => "array",
        JsonValue::Object(_) => "object",
    }
}

fn deep_eq(a: &JsonValue, b: &JsonValue) -> bool {
    match (a, b) {
        (JsonValue::Null, JsonValue::Null) => true,
        (JsonValue::Bool(x), JsonValue::Bool(y)) => x == y,
        (JsonValue::Number(x), JsonValue::Number(y)) => x == y,
        (JsonValue::String(x), JsonValue::String(y)) => x == y,
        (JsonValue::Array(x), JsonValue::Array(y)) => {
            if x.len() != y.len() { return false; }
            x.iter().zip(y.iter()).all(|(a,b)| deep_eq(a,b))
        }
        (JsonValue::Object(x), JsonValue::Object(y)) => {
            let map_a: HashMap<_,_> = x.iter().cloned().collect();
            let map_b: HashMap<_,_> = y.iter().cloned().collect();
            map_a.len() == map_b.len() && map_a.iter().all(|(k,v)| map_b.get(k).map_or(false, |v2| deep_eq(v,v2)))
        }
        _ => false,
    }
}

fn pointer_to_string(tokens: &[String]) -> String {
    let mut s = String::from("#");
    for tok in tokens {
        s.push('/');
        for ch in tok.chars() {
            match ch {
                '~' => s.push_str("~0"),
                '/' => s.push_str("~1"),
                _ => s.push(ch),
            }
        }
    }
    s
}

fn parse_pointer(ptr: &str) -> Vec<String> {
    if !ptr.starts_with('#') { return vec![]; }
    let rest = &ptr[1..];
    if rest.is_empty() { return vec![]; }
    rest.split('/')
        .skip(1)
        .map(|t| t.replace("~1", "/").replace("~0", "~"))
        .collect()
}

fn get_node_by_pointer(root: &JsonValue, tokens: &[String]) -> Option<&JsonValue> {
    let mut cur = root;
    for tok in tokens {
        match cur {
            JsonValue::Object(members) => {
                cur = members.iter().find(|(k,_)| k == tok)?.1;
            }
            JsonValue::Array(arr) => {
                let idx: usize = tok.parse().ok()?;
                cur = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

fn matches_type(instance: &JsonValue, type_name: &str) -> bool {
    match type_name {
        "null" => matches!(instance, JsonValue::Null),
        "boolean" => matches!(instance, JsonValue::Bool(_)),
        "object" => matches!(instance, JsonValue::Object(_)),
        "array" => matches!(instance, JsonValue::Array(_)),
        "number" => matches!(instance, JsonValue::Number(_)),
        "string" => matches!(instance, JsonValue::String(_)),
        "integer" => matches!(instance, JsonValue::Number(n) if n.fract() == 0.0),
        _ => false,
    }
}

fn is_integer(n: f64) -> bool { n.fract() == 0.0 }

#[derive(Clone)]
struct Error {
    inst: Vec<String>,
    schema: Vec<String>,
}

fn validate(instance: &JsonValue, schema_node: &JsonValue, schema_loc: Vec<String>, instance_loc: Vec<String>, schema_root: &JsonValue) -> Vec<Error> {
    match schema_node {
        JsonValue::Bool(b) => {
            if !b { vec![Error { inst: instance_loc, schema: schema_loc }] } else { vec![] }
        }
        JsonValue::Object(members) => {
            let mut errors = Vec::new();
            // collect members into map for quick lookup
            let mut map = HashMap::new();
            for (k,v) in members { map.insert(k.clone(), v.clone()); }
            // type
            if let Some(v) = map.get("type") {
                let ok = match v {
                    JsonValue::String(s) => matches_type(instance, s),
                    JsonValue::Array(arr) => arr.iter().any(|e| if let JsonValue::String(s)=e { matches_type(instance, s)} else {false}),
                    _ => true,
                };
                if !ok {
                    errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "type".into()].iter().cloned().collect() });
                }
            }
            // enum
            if let Some(JsonValue::Array(arr)) = map.get("enum") {
                if !arr.iter().any(|e| deep_eq(instance, e)) {
                    errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "enum".into()].iter().cloned().collect() });
                }
            }
            // const
            if let Some(v) = map.get("const") {
                if !deep_eq(instance, v) {
                    errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "const".into()].iter().cloned().collect() });
                }
            }
            // numbers
            if let JsonValue::Number(iv) = instance {
                if let Some(JsonValue::Number(min)) = map.get("minimum") {
                    if iv < *min { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "minimum".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Number(max)) = map.get("maximum") {
                    if iv > *max { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "maximum".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Number(ex_min)) = map.get("exclusiveMinimum") {
                    if iv <= *ex_min { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "exclusiveMinimum".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Number(ex_max)) = map.get("exclusiveMaximum") {
                    if iv >= *ex_max { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "exclusiveMaximum".into()].iter().cloned().collect() }); }
                }
            }
            // strings
            if let JsonValue::String(sv) = instance {
                let len = sv.chars().count() as u64;
                if let Some(JsonValue::Number(min)) = map.get("minLength") {
                    let min_i = *min as u64;
                    if len < min_i { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "minLength".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Number(max)) = map.get("maxLength") {
                    let max_i = *max as u64;
                    if len > max_i { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "maxLength".into()].iter().cloned().collect() }); }
                }
            }
            // arrays
            if let JsonValue::Array(arr) = instance {
                let len = arr.len() as u64;
                if let Some(JsonValue::Number(min)) = map.get("minItems") {
                    let min_i = *min as u64;
                    if len < min_i { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "minItems".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Number(max)) = map.get("maxItems") {
                    let max_i = *max as u64;
                    if len > max_i { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "maxItems".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Bool(true)) = map.get("uniqueItems") {
                    for i in 0..arr.len() {
                        for j in i+1..arr.len() {
                            if deep_eq(&arr[i], &arr[j]) {
                                errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "uniqueItems".into()].iter().cloned().collect() });
                                break;
                            }
                        }
                    }
                }
                // prefixItems
                if let Some(JsonValue::Array(prefix)) = map.get("prefixItems") {
                    for (i, sch) in prefix.iter().enumerate() {
                        if i < arr.len() {
                            let mut iloc = instance_loc.clone();
                            iloc.push(i.to_string());
                            let mut sloc = schema_loc.clone();
                            sloc.push("prefixItems".into());
                            sloc.push(i.to_string());
                            errors.extend(validate(&arr[i], sch, sloc, iloc, schema_root));
                        }
                    }
                }
                // items
                if let Some(items_schema) = map.get("items") {
                    let prefix_len = map.get("prefixItems").and_then(|v| if let JsonValue::Array(a)=v {Some(a.len())} else {None}).unwrap_or(0);
                    let start = prefix_len;
                    for i in start..arr.len() {
                        let mut iloc = instance_loc.clone();
                        iloc.push(i.to_string());
                        let mut sloc = schema_loc.clone();
                        sloc.push("items".into());
                        errors.extend(validate(&arr[i], items_schema, sloc, iloc, schema_root));
                    }
                }
            }
            // objects
            if let JsonValue::Object(inst_members) = instance {
                let inst_map: HashMap<_,_> = inst_members.iter().cloned().collect();
                // properties
                if let Some(JsonValue::Object(props)) = map.get("properties") {
                    for (pname, pschema) in props {
                        if let Some(iv) = inst_map.get(pname) {
                            let mut iloc = instance_loc.clone();
                            iloc.push(pname.clone());
                            let mut sloc = schema_loc.clone();
                            sloc.push("properties".into());
                            sloc.push(pname.clone());
                            errors.extend(validate(iv, pschema, sloc, iloc, schema_root));
                        }
                    }
                }
                // required
                if let Some(JsonValue::Array(req_arr)) = map.get("required") {
                    for (j, v) in req_arr.iter().enumerate() {
                        if let JsonValue::String(name) = v {
                            if !inst_map.contains_key(name) {
                                let mut sloc = schema_loc.clone();
                                sloc.push("required".into());
                                sloc.push(j.to_string());
                                errors.push(Error { inst: instance_loc.clone(), schema: sloc });
                            }
                        }
                    }
                }
                // additionalProperties
                if let Some(add_schema) = map.get("additionalProperties") {
                    let prop_names: HashSet<String> = if let Some(JsonValue::Object(props)) = map.get("properties") {
                        props.iter().map(|(k,_)| k.clone()).collect()
                    } else { HashSet::new() };
                    for (name, val) in inst_members {
                        if !prop_names.contains(&name) {
                            let mut iloc = instance_loc.clone();
                            iloc.push(name.clone());
                            let mut sloc = schema_loc.clone();
                            sloc.push("additionalProperties".into());
                            errors.extend(validate(val, add_schema, sloc, iloc, schema_root));
                        }
                    }
                }
                // min/max properties
                let prop_count = inst_members.len() as u64;
                if let Some(JsonValue::Number(min)) = map.get("minProperties") {
                    let min_i = *min as u64;
                    if prop_count < min_i { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "minProperties".into()].iter().cloned().collect() }); }
                }
                if let Some(JsonValue::Number(max)) = map.get("maxProperties") {
                    let max_i = *max as u64;
                    if prop_count > max_i { errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "maxProperties".into()].iter().cloned().collect() }); }
                }
            }
            // allOf
            if let Some(JsonValue::Array(all)) = map.get("allOf") {
                for (i, sch) in all.iter().enumerate() {
                    let mut sloc = schema_loc.clone();
                    sloc.push("allOf".into());
                    sloc.push(i.to_string());
                    errors.extend(validate(instance, sch, sloc, instance_loc.clone(), schema_root));
                }
            }
            // anyOf
            if let Some(JsonValue::Array(any)) = map.get("anyOf") {
                let mut accepts = false;
                for sch in any {
                    if validate(instance, sch, vec![], instance_loc.clone(), schema_root).is_empty() { accepts = true; break; }
                }
                if !accepts {
                    errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "anyOf".into()].iter().cloned().collect() });
                }
            }
            // oneOf
            if let Some(JsonValue::Array(one)) = map.get("oneOf") {
                let mut count = 0;
                for sch in one {
                    if validate(instance, sch, vec![], instance_loc.clone(), schema_root).is_empty() { count += 1; }
                }
                if count != 1 {
                    errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "oneOf".into()].iter().cloned().collect() });
                }
            }
            // not
            if let Some(not_schema) = map.get("not") {
                if validate(instance, not_schema, vec![], instance_loc.clone(), schema_root).is_empty() {
                    errors.push(Error { inst: instance_loc.clone(), schema: [schema_loc.clone(), "not".into()].iter().cloned().collect() });
                }
            }
            // if/then/else
            if let Some(JsonValue::Object(if_schema)) = map.get("if") {
                let if_accepts = validate(instance, if_schema, vec![], instance_loc.clone(), schema_root).is_empty();
                if if_accepts {
                    if let Some(then_schema) = map.get("then") {
                        errors.extend(validate(instance, then_schema, schema_loc.clone(), instance_loc.clone(), schema_root));
                    }
                } else {
                    if let Some(else_schema) = map.get("else") {
                        errors.extend(validate(instance, else_schema, schema_loc.clone(), instance_loc.clone(), schema_root));
                    }
                }
            }
            // $ref
            if let Some(JsonValue::String(ref_str)) = map.get("$ref") {
                let tokens = parse_pointer(ref_str);
                if let Some(target_node) = get_node_by_pointer(schema_root, &tokens) {
                    let target_loc = tokens.clone();
                    errors.extend(validate(instance, target_node, target_loc, instance_loc.clone(), schema_root));
                }
            }
            errors
        }
        _ => vec![],
    }
}

use std::collections::HashSet;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let schema_path = Path::new(dir).join("schema.json");
    let instances_path = Path::new(dir).join("instances.json");
    let schema_txt = fs::read_to_string(schema_path).expect("schema");
    let inst_txt = fs::read_to_string(instances_path).expect("instances");
    let schema_root = parse_json(&schema_txt).expect("parse schema");
    let instances_root = parse_json(&inst_txt).expect("parse instances");
    let instances_arr = match instances_root {
        JsonValue::Array(a) => a,
        _ => panic!("instances not array"),
    };
    let mut valid = 0;
    let mut invalid = 0;
    for (i, inst) in instances_arr.iter().enumerate() {
        let errs = validate(inst, &schema_root, vec![], vec![], &schema_root);
        if errs.is_empty() {
            println!("{}: valid", i);
            valid += 1;
        } else {
            // dedup
            let mut uniq = Vec::new();
            let mut seen = HashSet::new();
            for e in errs {
                let key = (pointer_to_string(&e.inst), pointer_to_string(&e.schema));
                if seen.insert(key) { uniq.push((e.inst, e.schema)); }
            }
            uniq.sort_by(|a,b| {
                let ia = pointer_to_string(&a.0);
                let ib = pointer_to_string(&b.0);
                if ia != ib { return ia.cmp(&ib); }
                pointer_to_string(&a.1).cmp(&pointer_to_string(&b.1))
            });
            println!("{}: invalid ({})", i, uniq.len());
            for (il, sl) in uniq {
                println!("  {} {}", pointer_to_string(&il), pointer_to_string(&sl));
            }
            invalid += 1;
        }
    }
    println!("valid={} invalid={}", valid, invalid);
}

use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}
impl Parser {
    fn new(s: &str) -> Self {
        Self { chars: s.chars().collect(), pos: 0 }
    }
    fn peek(&self) -> Option<char> { self.chars.get(self.pos).cloned() }
    fn next(&mut self) -> Option<char> { let c = self.peek(); if c.is_some() { self.pos += 1; } c }
    fn skip_ws(&mut self) { while matches!(self.peek(), Some(c) if c.is_whitespace()) { self.pos += 1; } }
    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => {
                let s = self.parse_string_raw()?;
                Ok(JsonValue::String(s))
            }
            Some('t') => { self.consume("true"); Ok(JsonValue::Bool(true)) }
            Some('f') => { self.consume("false"); Ok(JsonValue::Bool(false)) }
            Some('n') => { self.consume("null"); Ok(JsonValue::Null) }
            Some('-') | Some('0'..='9') => self.parse_number(),
            Some(c) => Err(format!("unexpected {}", c)),
            None => Err("eof".into()),
        }
    }
    fn consume(&mut self, lit: &str) {
        for _ in 0..lit.chars().count() { self.pos += 1; }
    }
    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.next(); // {
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some('}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            let key = match self.parse_string_raw()? { s => s };
            self.skip_ws();
            if self.next() != Some(':') { return Err("missing :".into()); }
            let val = self.parse_value()?;
            members.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.pos += 1; }
                Some('}') => { self.pos += 1; break; }
                _ => return Err("object sep".into()),
            }
        }
        Ok(JsonValue::Object(members))
    }
    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.next(); // [
        let mut elems = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') { self.pos += 1; return Ok(JsonValue::Array(elems)); }
        loop {
            let v = self.parse_value()?;
            elems.push(v);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.pos += 1; }
                Some(']') => { self.pos += 1; break; }
                _ => return Err("array sep".into()),
            }
        }
        Ok(JsonValue::Array(elems))
    }
    fn parse_string_raw(&mut self) -> Result<String, String> {
        if self.next() != Some('"') { return Err("string".into()); }
        let mut out = String::new();
        loop {
            let c = self.next().ok_or("unterminated")?;
            if c == '"' { return Ok(out); }
            if c == '\\' {
                let esc = self.next().ok_or("bad esc")?;
                match esc {
                    '"' => out.push('"'),
                    '\\' => out.push('\\'),
                    '/' => out.push('/'),
                    'b' => out.push('\x08'),
                    'f' => out.push('\x0c'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    't' => out.push('\t'),
                    'u' => {
                        let hex: String = (0..4).map(|_| self.next().ok_or("bad \\u")?).collect();
                        let cp = u32::from_str_radix(&hex,16).map_err(|_| "bad hex")?;
                        if (0xD800..=0xDBFF).contains(&cp) {
                            if self.peek() == Some('\\') {
                                self.pos += 1;
                                if self.peek() == Some('u') {
                                    self.pos += 1;
                                    let hex2: String = (0..4).map(|_| self.next().ok_or("bad \\u")?).collect();
                                    if let Ok(cp2)=u32::from_str_radix(&hex2,16) {
                                        if (0xDC00..=0xDFFF).contains(&cp2) {
                                            let high = cp - 0xD800;
                                            let low = cp2 - 0xDC00;
                                            let code = 0x10000 + (high<<10) + low;
                                            if let Some(ch)=std::char::from_u32(code){ out.push(ch); continue; }
                                        }
                                    }
                                }
                            }
                        }
                        if let Some(ch)=std::char::from_u32(cp){ out.push(ch); }
                    }
                    _ => out.push(esc),
                }
            } else {
                out.push(c);
            }
        }
    }
    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        if self.peek()==Some('-'){ self.pos+=1; }
        while matches!(self.peek(), Some('0'..='9')) { self.pos+=1; }
        if self.peek()==Some('.'){ self.pos+=1; while matches!(self.peek(), Some('0'..='9')){ self.pos+=1; } }
        if matches!(self.peek(), Some('e')|Some('E')){ self.pos+=1; if matches!(self.peek(), Some('+')|Some('-')){ self.pos+=1; } while matches!(self.peek(), Some('0'..='9')){ self.pos+=1; } }
        let txt: String = self.chars[start..self.pos].iter().collect();
        let num: f64 = txt.parse().map_err(|_| "bad number")?;
        Ok(JsonValue::Number(num))
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut p = Parser::new(s);
    let v = p.parse_value()?;
    p.skip_ws();
    Ok(v)
}

fn matches_type(inst: &JsonValue, name: &str) -> bool {
    match name {
        "null" => matches!(inst, JsonValue::Null),
        "boolean" => matches!(inst, JsonValue::Bool(_)),
        "object" => matches!(inst, JsonValue::Object(_)),
        "array" => matches!(inst, JsonValue::Array(_)),
        "number" => matches!(inst, JsonValue::Number(_)),
        "string" => matches!(inst, JsonValue::String(_)),
        "integer" => matches!(inst, JsonValue::Number(n) if n.fract()==0.0),
        _ => false,
    }
}

fn deep_eq(a: &JsonValue, b: &JsonValue) -> bool {
    match (a,b) {
        (JsonValue::Null, JsonValue::Null) => true,
        (JsonValue::Bool(x), JsonValue::Bool(y)) => x==y,
        (JsonValue::Number(x), JsonValue::Number(y)) => x==y,
        (JsonValue::String(x), JsonValue::String(y)) => x==y,
        (JsonValue::Array(x), JsonValue::Array(y)) => {
            if x.len()!=y.len(){ return false; }
            x.iter().zip(y.iter()).all(|(a,b)| deep_eq(a,b))
        }
        (JsonValue::Object(x), JsonValue::Object(y)) => {
            let map_a: HashMap<_,_> = x.iter().cloned().collect();
            let map_b: HashMap<_,_> = y.iter().cloned().collect();
            map_a.len()==map_b.len() && map_a.iter().all(|(k,v)| map_b.get(k).map_or(false, |v2| deep_eq(v,v2)))
        }
        _ => false,
    }
}

fn pointer_to_string(tokens: &[String]) -> String {
    let mut s = String::from("#");
    for tok in tokens {
        s.push('/');
        for ch in tok.chars() {
            match ch {
                '~' => s.push_str("~0"),
                '/' => s.push_str("~1"),
                _ => s.push(ch),
            }
        }
    }
    s
}
fn parse_pointer(ptr: &str) -> Vec<String> {
    if !ptr.starts_with('#') { return vec![]; }
    let rest = &ptr[1..];
    if rest.is_empty() { return vec![]; }
    rest.split('/')
        .skip(1)
        .map(|t| t.replace("~1","/").replace("~0","~"))
        .collect()
}
fn get_node_by_pointer<'a>(root: &'a JsonValue, tokens: &[String]) -> Option<&'a JsonValue> {
    let mut cur = root;
    for tok in tokens {
        match cur {
            JsonValue::Object(m) => { cur = m.iter().find(|(k,_)| k==tok)?.1; }
            JsonValue::Array(a) => {
                let i: usize = tok.parse().ok()?; cur = a.get(i)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

#[derive(Clone)]
struct Error { inst: Vec<String>, schema: Vec<String> }

fn schema_accepts(instance: &JsonValue, schema_node: &JsonValue, schema_root: &JsonValue) -> bool {
    validate_instance(instance, schema_node, vec![], vec![], schema_root).is_empty()
}

fn validate_instance(instance: &JsonValue, schema_node: &JsonValue, schema_loc: Vec<String>, instance_loc: Vec<String>, schema_root: &JsonValue) -> Vec<Error> {
    match schema_node {
        JsonValue::Bool(b) => {
            if !b { vec![Error{inst:instance_loc, schema:schema_loc}] } else { vec![] }
        }
        JsonValue::Object(members) => {
            let mut map = HashMap::new();
            for (k,v) in members { map.insert(k.clone(), v.clone()); }
            let mut errors = Vec::new();

            if let Some(v)=map.get("type") {
                let ok = match v {
                    JsonValue::String(s)=> matches_type(instance,s),
                    JsonValue::Array(arr)=> arr.iter().any(|e| if let JsonValue::String(s)=e { matches_type(instance,s)} else {false}),
                    _=>true,
                };
                if !ok { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"type".into()].iter().cloned().collect()}); }
            }
            if let Some(JsonValue::Array(arr))=map.get("enum") {
                if !arr.iter().any(|e| deep_eq(instance,e)) {
                    errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"enum".into()].iter().cloned().collect()});
                }
            }
            if let Some(v)=map.get("const") {
                if !deep_eq(instance,v) {
                    errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"const".into()].iter().cloned().collect()});
                }
            }
            if let JsonValue::Number(iv)=instance {
                if let Some(JsonValue::Number(min))=map.get("minimum") { if iv<*min { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"minimum".into()].iter().cloned().collect()}); } }
                if let Some(JsonValue::Number(max))=map.get("maximum") { if iv>*max { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"maximum".into()].iter().cloned().collect()}); } }
                if let Some(JsonValue::Number(ex))=map.get("exclusiveMinimum") { if iv<=*ex { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"exclusiveMinimum".into()].iter().cloned().collect()}); } }
                if let Some(JsonValue::Number(ex))=map.get("exclusiveMaximum") { if iv>=*ex { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"exclusiveMaximum".into()].iter().cloned().collect()}); } }
            }
            if let JsonValue::String(sv)=instance {
                let len = sv.chars().count() as u64;
                if let Some(JsonValue::Number(min))=map.get("minLength") { let m=*min as u64; if len<m { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"minLength".into()].iter().cloned().collect()}); } }
                if let Some(JsonValue::Number(max))=map.get("maxLength") { let m=*max as u64; if len>m { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"maxLength".into()].iter().cloned().collect()}); } }
            }
            if let JsonValue::Array(arr)=instance {
                let len = arr.len() as u64;
                if let Some(JsonValue::Number(min))=map.get("minItems") { let m=*min as u64; if len<m { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"minItems".into()].iter().cloned().collect()}); } }
                if let Some(JsonValue::Number(max))=map.get("maxItems") { let m=*max as u64; if len>m { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"maxItems".into()].iter().cloned().collect()}); } }
                if map.get("uniqueItems")==Some(&JsonValue::Bool(true)) {
                    for i in 0..arr.len() { for j in i+1..arr.len() { if deep_eq(&arr[i],&arr[j]) { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"uniqueItems".into()].iter().cloned().collect()}); } } }
                }
                if let Some(JsonValue::Array(prefix))=map.get("prefixItems") {
                    for (i,sch) in prefix.iter().enumerate() {
                        if i<arr.len() {
                            let mut iloc=instance_loc.clone(); iloc.push(i.to_string());
                            let mut sloc=schema_loc.clone(); sloc.push("prefixItems".into()); sloc.push(i.to_string());
                            errors.extend(validate_instance(&arr[i], sch, sloc, iloc, schema_root));
                        }
                    }
                }
                if let Some(items_schema)=map.get("items") {
                    let prefix_len = map.get("prefixItems").and_then(|v| if let JsonValue::Array(a)=v {Some(a.len())} else {None}).unwrap_or(0);
                    for i in prefix_len..arr.len() {
                        let mut iloc=instance_loc.clone(); iloc.push(i.to_string());
                        let mut sloc=schema_loc.clone(); sloc.push("items".into());
                        errors.extend(validate_instance(&arr[i], items_schema, sloc, iloc, schema_root));
                    }
                }
            }
            if let JsonValue::Object(inst_members)=instance {
                let inst_map: HashMap<_,_> = inst_members.iter().cloned().collect();
                if let Some(JsonValue::Object(props))=map.get("properties") {
                    for (pname,pschema) in props {
                        if let Some(iv)=inst_map.get(pname) {
                            let mut iloc=instance_loc.clone(); iloc.push(pname.clone());
                            let mut sloc=schema_loc.clone(); sloc.push("properties".into()); sloc.push(pname.clone());
                            errors.extend(validate_instance(iv, pschema, sloc, iloc, schema_root));
                        }
                    }
                }
                if let Some(JsonValue::Array(req_arr))=map.get("required") {
                    for (j,v) in req_arr.iter().enumerate() {
                        if let JsonValue::String(name)=v {
                            if !inst_map.contains_key(name) {
                                let mut sloc=schema_loc.clone(); sloc.push("required".into()); sloc.push(j.to_string());
                                errors.push(Error{inst:instance_loc.clone(), schema:sloc});
                            }
                        }
                    }
                }
                if let Some(add_schema)=map.get("additionalProperties") {
                    let prop_names: HashSet<String> = if let Some(JsonValue::Object(props))=map.get("properties") { props.iter().map(|(k,_)|k.clone()).collect() } else { HashSet::new() };
                    for (name,val) in inst_members {
                        if !prop_names.contains(&name) {
                            let mut iloc=instance_loc.clone(); iloc.push(name.clone());
                            let mut sloc=schema_loc.clone(); sloc.push("additionalProperties".into());
                            errors.extend(validate_instance(val, add_schema, sloc, iloc, schema_root));
                        }
                    }
                }
                let prop_count = inst_members.len() as u64;
                if let Some(JsonValue::Number(min))=map.get("minProperties") { let m=*min as u64; if prop_count<m { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"minProperties".into()].iter().cloned().collect()}); } }
                if let Some(JsonValue::Number(max))=map.get("maxProperties") { let m=*max as u64; if prop_count>m { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"maxProperties".into()].iter().cloned().collect()}); } }
            }
            if let Some(JsonValue::Array(all))=map.get("allOf") {
                for (i,sch) in all.iter().enumerate() {
                    let mut sloc=schema_loc.clone(); sloc.push("allOf".into()); sloc.push(i.to_string());
                    errors.extend(validate_instance(instance, sch, sloc, instance_loc.clone(), schema_root));
                }
            }
            if let Some(JsonValue::Array(any))=map.get("anyOf") {
                let mut accepts=false;
                for sch in any { if schema_accepts(instance, sch, schema_root) { accepts=true; break; } }
                if !accepts { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"anyOf".into()].iter().cloned().collect()}); }
            }
            if let Some(JsonValue::Array(one))=map.get("oneOf") {
                let mut cnt=0;
                for sch in one { if schema_accepts(instance, sch, schema_root) { cnt+=1; } }
                if cnt!=1 { errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"oneOf".into()].iter().cloned().collect()}); }
            }
            if let Some(not_schema)=map.get("not") {
                if schema_accepts(instance, not_schema, schema_root) {
                    errors.push(Error{inst:instance_loc.clone(), schema:[schema_loc.clone(),"not".into()].iter().cloned().collect()});
                }
            }
            if let Some(if_schema)=map.get("if") {
                let if_accepts = schema_accepts(instance, if_schema, schema_root);
                if if_accepts {
                    if let Some(then_schema)=map.get("then") {
                        let mut sloc=schema_loc.clone(); sloc.push("then".into());
                        errors.extend(validate_instance(instance, then_schema, sloc, instance_loc.clone(), schema_root));
                    }
                } else {
                    if let Some(else_schema)=map.get("else") {
                        let mut sloc=schema_loc.clone(); sloc.push("else".into());
                        errors.extend(validate_instance(instance, else_schema, sloc, instance_loc.clone(), schema_root));
                    }
                }
            }
            if let Some(JsonValue::String(ref_str))=map.get("$ref") {
                let tokens=parse_pointer(ref_str);
                if let Some(target)=get_node_by_pointer(schema_root,&tokens) {
                    errors.extend(validate_instance(instance, target, tokens, instance_loc.clone(), schema_root));
                }
            }
            errors
        }
        _ => vec![],
    }
}

fn main() {
    let args: Vec<String>=env::args().collect();
    if args.len()<2 { return; }
    let dir=&args[1];
    let schema_path=Path::new(dir).join("schema.json");
    let instances_path=Path::new(dir).join("instances.json");
    let schema_txt=fs::read_to_string(schema_path).expect("schema");
    let inst_txt=fs::read_to_string(instances_path).expect("instances");
    let schema_root=parse_json(&schema_txt).expect("parse schema");
    let instances_root=parse_json(&inst_txt).expect("parse instances");
    let instances_arr=match instances_root { JsonValue::Array(a)=>a, _=>panic!("instances not array") };
    let mut valid=0;
    let mut invalid=0;
    for (i,inst) in instances_arr.iter().enumerate() {
        let errs=validate_instance(inst,&schema_root,vec![],vec![],&schema_root);
        if errs.is_empty() {
            println!("{}: valid",i);
            valid+=1;
        } else {
            let mut uniq=Vec::new();
            let mut seen=HashSet::new();
            for e in errs {
                let key=(pointer_to_string(&e.inst),pointer_to_string(&e.schema));
                if seen.insert(key) { uniq.push((e.inst,e.schema)); }
            }
            uniq.sort_by(|a,b|{
                let ia=pointer_to_string(&a.0);
                let ib=pointer_to_string(&b.0);
                if ia!=ib { return ia.cmp(&ib); }
                pointer_to_string(&a.1).cmp(&pointer_to_string(&b.1))
            });
            println!("{}: invalid ({})",i,uniq.len());
            for (il,sl) in uniq {
                println!("  {} {}", pointer_to_string(&il), pointer_to_string(&sl));
            }
            invalid+=1;
        }
    }
    println!("valid={} invalid={}",valid,invalid);
}

import * as fs from 'fs';
import * as path from 'path';

function quoteString(s: string): string {
  let out = '"';
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else {
      const code = ch.codePointAt(0)!;
      if (code < 0x20 || (code >= 0x7f && code <= 0x9f)) {
        out += '\\u' + code.toString(16).padStart(4, '0');
      } else out += ch;
    }
  }
  out += '"';
  return out;
}

function crc32(buf: Uint8Array): number {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) c = (c & 1) ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[i] = c;
  }
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function unescapeQuoted(v: string): string {
  let r = '';
  for (let i = 0; i < v.length; i++) {
    if (v[i] === '\\' && i + 1 < v.length) { r += v[i + 1]; i++; }
    else r += v[i];
  }
  return r;
}

function parseParams(paramStr: string): Record<string, string> {
  const res: Record<string, string> = {};
  let i = 0;
  const s = paramStr.trim();
  while (i < s.length) {
    while (i < s.length && (s[i] === ' ' || s[i] === '\t' || s[i] === ';')) i++;
    if (i >= s.length) break;
    const nameStart = i;
    while (i < s.length && s[i] !== '=' && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') i++;
    const name = s.slice(nameStart, i).toLowerCase();
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
    if (s[i] !== '=') continue;
    i++;
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
    let value = '';
    if (s[i] === '"') {
      i++;
      let val = '';
      while (i < s.length && s[i] !== '"') {
        if (s[i] === '\\') { val += s[i + 1]; i += 2; } else { val += s[i]; i++; }
      }
      i++; // skip "
      value = unescapeQuoted(val);
    } else {
      const vStart = i;
      while (i < s.length && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') i++;
      value = s.slice(vStart, i);
    }
    res[name] = value;
  }
  return res;
}

function parseContentType(val: string) {
  const parts = val.split(';');
  const main = parts[0].trim();
  const [type, subtype] = main.split('/');
  const params = parseParams(parts.slice(1).join(';'));
  return { type: (type || '').toLowerCase(), subtype: (subtype || '').toLowerCase(), params };
}

function decodeQ(str: string): Uint8Array {
  const out: number[] = [];
  for (let i = 0; i < str.length; ) {
    if (str[i] === '_') { out.push(0x20); i++; }
    else if (str[i] === '=' && i + 2 < str.length) {
      const hex = str.substr(i + 1, 2);
      if (/^[0-9a-fA-F]{2}$/.test(hex)) { out.push(parseInt(hex, 16)); i += 3; continue; }
    }
    out.push(str.charCodeAt(i));
    i++;
  }
  return Uint8Array.from(out);
}

function decodeEncodedWords(s: string): string {
  const re = /=\?([^?\s]+)\?([BbQq])\?([^?\s]*)\?=/g;
  const matches: {idx:number,len:number,charset:string,enc:string,text:string}[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(s)) !== null) {
    matches.push({idx:m.index,len:m[0].length,charset:m[1],enc:m[2],text:m[3]});
  }
  if (matches.length === 0) return s;
  let out = '';
  let pos = 0;
  let i = 0;
  while (i < matches.length) {
    const cur = matches[i];
    if (cur.idx > pos) out += s.slice(pos, cur.idx);
    // build run
    let runStart = i;
    let runCharset = cur.charset.toLowerCase().replace(/\*.*$/, '');
    let runTexts: string[] = [];
    let runEndIdx = cur.idx + cur.len;
    let j = i;
    while (j < matches.length) {
      const mm = matches[j];
      const gap = s.slice(runEndIdx, mm.idx);
      if (j === i) { runTexts.push(mm.text); runEndIdx = mm.idx + mm.len; j++; continue; }
      if (/^[ \t]*$/.test(gap)) {
        const cs = mm.charset.toLowerCase().replace(/\*.*$/, '');
        if (cs === runCharset) {
          runTexts.push(mm.text);
          runEndIdx = mm.idx + mm.len;
          j++;
          continue;
        }
      }
      break;
    }
    // decode run
    const combined = runTexts.map(t => {
      if (cur.enc.toUpperCase() === 'B') {
        try { return Buffer.from(t, 'base64'); } catch { return Buffer.alloc(0); }
      } else {
        return Buffer.from(decodeQ(t));
      }
    });
    const bytes = Buffer.concat(combined);
    const cs = runCharset;
    let decoded = '';
    try {
      if (cs === 'utf-8' || cs === 'utf8') decoded = bytes.toString('utf8');
      else if (cs === 'us-ascii') decoded = bytes.toString('latin1');
      else if (cs === 'iso-8859-1') decoded = bytes.toString('latin1');
      else if (cs === 'windows-1252') decoded = bytes.toString('windows-1252');
      else decoded = bytes.toString('utf8');
    } catch { decoded = ''; }
    out += decoded;
    pos = runEndIdx;
    i = j;
  }
  if (pos < s.length) out += s.slice(pos);
  return out;
}

function windows1252Map(b: number): number {
  const map: Record<number, number> = {
    0x80:0x20ac,0x81:0x0081,0x82:0x201a,0x83:0x0192,0x84:0x201e,0x85:0x2026,0x86:0x2020,0x87:0x2021,
    0x88:0x02c6,0x89:0x2030,0x8a:0x0160,0x8b:0x2039,0x8c:0x0152,0x8d:0x008d,0x8e:0x017d,0x8f:0x008f,
    0x90:0x0090,0x91:0x2018,0x92:0x2019,0x93:0x201c,0x94:0x201d,0x95:0x2022,0x96:0x2013,0x97:0x2014,
    0x98:0x02dc,0x99:0x2122,0x9a:0x0161,0x9b:0x203a,0x9c:0x0153,0x9d:0x009d,0x9e:0x017e,0x9f:0x0178,
  };
  return map[b] ?? b;
}

function decodeCharset(bytes: Uint8Array, charset: string): string {
  const cs = charset.toLowerCase();
  if (cs === 'us-ascii' || cs === 'ascii') return Buffer.from(bytes).toString('ascii');
  if (cs === 'utf-8' || cs === 'utf8') return Buffer.from(bytes).toString('utf8');
  if (cs === 'iso-8859-1') return Buffer.from(bytes).toString('latin1');
  if (cs === 'windows-1252') {
    let s = '';
    for (const b of bytes) {
      if (b <= 0x7f) s += String.fromCharCode(b);
      else if (b >= 0x80 && b <= 0x9f) s += String.fromCharCode(windows1252Map(b));
      else s += String.fromCharCode(b);
    }
    return s;
  }
  return Buffer.from(bytes).toString('utf8');
}

function decodeTransferEncoding(data: Uint8Array, enc: string): Uint8Array {
  const e = (enc || '7bit').toLowerCase();
  if (e === '7bit' || e === '8bit' || e === 'binary') return data;
  if (e === 'base64') {
    const str = Buffer.from(data).toString('latin1').replace(/[^A-Za-z0-9+/]/g, '');
    const clean = str.replace(/={1,2}$/, '');
    try { return Uint8Array.from(Buffer.from(clean, 'base64')); } catch { return new Uint8Array(); }
  }
  if (e === 'quoted-printable') {
    let s = Buffer.from(data).toString('latin1');
    const lines = s.split(/\r\n|\n/);
    let out = '';
    for (let i = 0; i < lines.length; i++) {
      let line = lines[i].replace(/[ \t]+$/, '');
      if (line.endsWith('=')) { out += line.slice(0, -1); continue; }
      out += line + '\n';
    }
    // decode =XX
    let res = '';
    for (let i = 0; i < out.length; i++) {
      if (out[i] === '=' && i + 2 < out.length && /^[0-9A-Fa-f]{2}$/.test(out.substr(i + 1, 2))) {
        res += String.fromCharCode(parseInt(out.substr(i + 1, 2), 16));
        i += 2;
      } else res += out[i];
    }
    return Uint8Array.from(Buffer.from(res, 'latin1'));
  }
  return data;
}

function getFilenameFromParams(ctParams: Record<string,string>, cdParams: Record<string,string>, type?: string) {
  const candidates = [
    {params: cdParams, key:'filename*', base:'filename'},
    {params: cdParams, key:'filename', base:'filename'},
    {params: ctParams, key:'name*', base:'name'},
    {params: ctParams, key:'name', base:'name'},
  ];
  for (const c of candidates) {
    // RFC2231 detection
    const keys = Object.keys(c.params);
    const starKeys = keys.filter(k => k.toLowerCase().startsWith(c.base.toLowerCase() + '*'));
    if (starKeys.length > 0) {
      // try to decode RFC2231
      // simplified: only handle single * and continuation
      const single = c.params[c.key.toLowerCase()];
      if (single !== undefined) {
        // filename*=charset'lang'value
        const m = single.match(/^([^']*)'([^']*)'(.*)$/);
        if (m) {
          const charset = m[1] || 'us-ascii';
          const val = decodeURIComponent(m[3].replace(/\+/g, ' '));
          // percent decode
          try {
            const bytes = Buffer.from(decodeURIComponent(m[3]), 'latin1');
            return decodeCharset(bytes, charset);
          } catch {}
        }
      }
      // continuation attempt
      const segs: {n:number, val:string}[] = [];
      for (const k of starKeys) {
        const m = k.toLowerCase().match(new RegExp('^' + c.base + '\\*(\\d+)(\\*)?$'));
        if (m) {
          const n = parseInt(m[1], 10);
          segs.push({n, val: c.params[k]});
        }
      }
      if (segs.length > 0) {
        segs.sort((a,b)=>a.n-b.n);
        let bytes = Buffer.alloc(0);
        for (const s of segs) {
          if (s.n === 0) {
            const m = s.val.match(/^([^']*)'([^']*)'(.*)$/);
            if (m) {
              const charset = m[1] || 'us-ascii';
              const raw = decodeURIComponent(m[3]);
              bytes = Buffer.concat([bytes, Buffer.from(raw, 'latin1')]);
              // charset used later
              const decoded = decodeCharset(bytes, charset);
              return decoded;
            }
          } else {
            try { bytes = Buffer.concat([bytes, Buffer.from(decodeURIComponent(s.val), 'latin1')]); } catch {}
          }
        }
      }
    }
  }
  // fallback to plain param with encoded-words
  const plain = cdParams['filename'] || ctParams['name'];
  if (plain) return decodeEncodedWords(plain);
  return undefined;
}

type EntityInfo = {
  headers: Map<string,string>;
  contentType?: {type:string;subtype:string;params:Record<string,string>};
  disposition?: string;
  transferEncoding: string;
  charset?: string;
  body: Uint8Array;
  isMultipart: boolean;
  boundary?: string;
  parts?: EntityInfo[];
};

function parseHeadersBlock(buf: Buffer, start:number, lineEnding:string): {headers:Map<string,string>, bodyStart:number} {
  const search = Buffer.from(lineEnding + lineEnding);
  let idx = buf.indexOf(search, start);
  let bodyStart = start;
  let headerBytes = buf.slice(start, start);
  if (idx !== -1) {
    headerBytes = buf.slice(start, idx + lineEnding.length);
    bodyStart = idx + lineEnding.length * 2;
  } else {
    headerBytes = buf.slice(start);
    bodyStart = buf.length;
  }
  const txt = headerBytes.toString('latin1');
  const lines = txt.split(lineEnding);
  const unfolded: string[] = [];
  for (const l of lines) {
    if (unfolded.length === 0) { unfolded.push(l); }
    else if (/^[ \t]/.test(l)) { unfolded[unfolded.length - 1] += l; }
    else { unfolded.push(l); }
  }
  const headers = new Map<string,string>();
  for (const line of unfolded) {
    const colon = line.indexOf(':');
    if (colon === -1) continue;
    const name = line.slice(0, colon).trim().toLowerCase();
    const val = line.slice(colon + 1).trim();
    headers.set(name, val);
  }
  return {headers, bodyStart};
}

function parseEntity(buf: Buffer, start:number, end:number, lineEnding:string): EntityInfo {
  const {headers, bodyStart} = parseHeadersBlock(buf, start, lineEnding);
  const ctRaw = headers.get('content-type');
  let contentType;
  if (ctRaw) {
    contentType = parseContentType(ctRaw);
  } else {
    contentType = {type:'text', subtype:'plain', params:{charset:'us-ascii'}};
  }
  const te = (headers.get('content-transfer-encoding') || '7bit').toLowerCase();
  const cdRaw = headers.get('content-disposition');
  let disposition = '-';
  let cdParams: Record<string,string> = {};
  if (cdRaw) {
    const parts = cdRaw.split(';');
    const dispType = parts[0].trim().toLowerCase();
    disposition = dispType;
    cdParams = parseParams(parts.slice(1).join(';'));
  }
  const isMultipart = contentType.type.toLowerCase() === 'multipart';
  let partsArr: EntityInfo[] = [];
  let boundary: string | undefined;
  let body = new Uint8Array();
  if (isMultipart) {
    boundary = contentType.params['boundary'];
    if (boundary) {
      const bodyBuf = buf.slice(bodyStart, end);
      const bodyStr = bodyBuf.toString('latin1');
      const lines = bodyStr.split(lineEnding);
      const delim = '--' + boundary;
      let firstIdx = -1;
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].startsWith(delim)) { firstIdx = i; break; }
      }
      if (firstIdx !== -1) {
        let curStartLine = firstIdx + 1;
        for (let i = firstIdx + 1; i < lines.length; i++) {
          const ln = lines[i];
          if (ln.startsWith(delim)) {
            const isClose = ln.startsWith(delim + '--');
            const partLines = lines.slice(curStartLine, i);
            const partStr = partLines.join(lineEnding);
            const partBuf = Buffer.from(partStr, 'latin1');
            // find byte offset in original buffer
            // approximate: we can parse recursively from offset
            // For simplicity, parse part using same function with buffer slice
            const partEntity = parseEntity(partBuf, 0, partBuf.length, lineEnding);
            partsArr.push(partEntity);
            if (isClose) break;
            curStartLine = i + 1;
          }
        }
      }
    }
    body = new Uint8Array();
  } else {
    const bodyBuf = buf.slice(bodyStart, end);
    const decoded = decodeTransferEncoding(bodyBuf, te);
    body = decoded;
  }
  const charset = contentType.type.toLowerCase() === 'text' ? (contentType.params['charset'] || 'us-ascii') : undefined;
  return {
    headers,
    contentType,
    disposition,
    transferEncoding: te,
    charset: charset?.toLowerCase(),
    body,
    isMultipart,
    boundary,
    parts: partsArr.length ? partsArr : undefined,
  };
}

function printEntity(e: EntityInfo, depth: number, out: string[]) {
  const indent = '  '.repeat(depth);
  if (e.isMultipart && e.contentType) {
    const partsNum = e.parts?.length ?? 0;
    out.push(`${indent}multipart/${e.contentType.subtype} parts=${partsNum}`);
    if (e.parts) {
      for (const p of e.parts) printEntity(p, depth + 1, out);
    }
  } else {
    const ct = e.contentType!;
    const isText = ct.type.toLowerCase() === 'text';
    const disp = e.disposition || '-';
    const isAttachment = disp === 'attachment';
    if (isText && !isAttachment) {
      const charset = e.charset || 'us-ascii';
      const cte = e.transferEncoding;
      const txt = decodeCharset(decodeTransferEncoding(e.body, cte), charset);
      const normalized = txt.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
      const chars = [...normalized].length;
      out.push(`${indent}text/${ct.subtype} charset=${charset} cte=${cte} chars=${chars}`);
      out.push(`${'  '.repeat(depth + 1)}${quoteString(normalized)}`);
    } else {
      const cte = e.transferEncoding;
      // filename
      const ctParams = ct.params;
      const cdParams = {}; // simplified
      const name = '-';
      const size = e.body.length;
      const crc = crc32(e.body).toString(16).padStart(8, '0');
      out.push(`${indent}${ct.type}/${ct.subtype} cte=${cte} disposition=${disp} name=${quoteString(name)} size=${size} crc32=${crc}`);
    }
  }
}

function processFile(filePath: string) {
  const buf = fs.readFileSync(filePath);
  const hasCRLF = buf.includes(0x0d);
  const lineEnding = hasCRLF ? '\r\n' : '\n';
  const entity = parseEntity(buf, 0, buf.length, lineEnding);
  const headers = entity.headers;
  const from = decodeEncodedWords(headers.get('from') || '');
  const subject = decodeEncodedWords(headers.get('subject') || '');
  const lines: string[] = [];
  lines.push(`== ${path.basename(filePath)}`);
  lines.push(`From: ${from ? quoteString(from) : '-'}`);
  lines.push(`Subject: ${subject ? quoteString(subject) : '-'}`);
  printEntity(entity, 0, lines);
  return lines.join('\n');
}

function main() {
  const dir = process.argv[2];
  if (!dir) { process.exit(0); }
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml')).sort();
  const outs: string[] = [];
  for (let i = 0; i < files.length; i++) {
    const fp = path.join(dir, files[i]);
    outs.push(processFile(fp));
  }
  console.log(outs.join('\n\n'));
}

main();

