function windows1252Map(b: number): number {
  const map: Record<number, number> = {
    0x80:0x20ac,0x81:0x0081,0x82:0x201a,0x83:0x0192,0x84:0x201e,0x85:0x2026,0x86:0x2020,0x87:0x2021,
    0x88:0x02c6,0x89:0x2030,0x8a:0x0160,0x8b:0x2039,0x8c:0x0152,0x8d:0x008d,0x8e:0x017d,0x8f:0x008f,
    0x90:0x0090,0x91:0x2018,0x92:0x2019,0x93:0x201c,0x94:0x201d,0x95:0x2022,0x96:0x2013,0x97:0x2014,
    0x98:0x02dc,0x99:0x2122,0x9a:0x0161,0x9b:0x203a,0x9c:0x0153,0x9d:0x009d,0x9e:0x017e,0x9f:0x0178,
  };
  return map[b] ?? b;
}

function decodeCharsetBytes(bytes: Uint8Array, charset: string): string {
  const cs = charset.toLowerCase();
  if (cs === 'us-ascii' || cs === 'ascii') {
    return Buffer.from(bytes).toString('ascii');
  }
  if (cs === 'utf-8' || cs === 'utf8') {
    return Buffer.from(bytes).toString('utf8');
  }
  if (cs === 'iso-8859-1') {
    return Buffer.from(bytes).toString('latin1');
  }
  if (cs === 'windows-1252') {
    let s = '';
    for (const b of bytes) {
      if (b <= 0x7f) s += String.fromCharCode(b);
      else if (b >= 0x80 && b <= 0x9f) s += String.fromCharCode(windows1252Map(b));
      else s += String.fromCharCode(b);
    }
    return s;
  }
  return Buffer.from(bytes).toString('utf8');
}

function normalizeCharset(cs: string): string {
  return cs.toLowerCase().replace(/\*.*$/, '');
}

function decodeQ(text: string): Uint8Array {
  const out: number[] = [];
  for (let i = 0; i < text.length; ) {
    const c = text[i];
    if (c === '_') { out.push(0x20); i++; }
    else if (c === '=' && i + 2 < text.length && /^[0-9A-Fa-f]{2}$/.test(text.substr(i + 1, 2))) {
      out.push(parseInt(text.substr(i + 1, 2), 16));
      i += 3;
    } else {
      out.push(text.charCodeAt(i));
      i++;
    }
  }
  return Uint8Array.from(out);
}

function decodeEncodedWords(s: string): string {
  const re = /=\?([^?\s]+)\?(B|b|Q|q)\?([^?\s]*)\?=/g;
  const matches: {start:number,end:number,charset:string,enc:string,text:string}[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(s)) !== null) {
    matches.push({start:m.index,end:m.index+m[0].length,charset:m[1],enc:m[2],text:m[3]});
  }
  if (matches.length === 0) return s;
  let out = '';
  let pos = 0;
  let i = 0;
  while (i < matches.length) {
    const cur = matches[i];
    if (cur.start > pos) {
      out += s.slice(pos, cur.start);
      pos = cur.start;
    }
    const runCharset = normalizeCharset(cur.charset);
    const runBytes: Uint8Array[] = [];
    let runEnd = cur.end;
    let j = i;
    while (j < matches.length) {
      const mm = matches[j];
      if (j === i) {
        runBytes.push(decodeWordBytes(mm));
        runEnd = mm.end;
        j++;
        continue;
      }
      const gap = s.slice(runEnd, mm.start);
      if (/^[ \t]*$/.test(gap)) {
        const cs = normalizeCharset(mm.charset);
        if (cs === runCharset) {
          runBytes.push(decodeWordBytes(mm));
          runEnd = mm.end;
          j++;
          continue;
        }
      }
      break;
    }
    const combined = Buffer.concat(runBytes.map(b=>Buffer.from(b)));
    const decoded = decodeCharsetBytes(combined, runCharset);
    out += decoded;
    pos = runEnd;
    i = j;
  }
  if (pos < s.length) out += s.slice(pos);
  return out;

  function decodeWordBytes(mm: {charset:string,enc:string,text:string}): Uint8Array {
    if (mm.enc.toUpperCase() === 'B') {
      try { return Uint8Array.from(Buffer.from(mm.text, 'base64')); } catch { return new Uint8Array(); }
    } else {
      return decodeQ(mm.text);
    }
  }
}

function percentDecode(str: string): number[] {
  const out: number[] = [];
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%' && i + 2 < str.length && /^[0-9A-Fa-f]{2}$/.test(str.substr(i + 1, 2))) {
      out.push(parseInt(str.substr(i + 1, 2), 16));
      i += 2;
    } else {
      out.push(str.charCodeAt(i));
    }
  }
  return out;
}

function parseParams(paramStr: string): Record<string,string> {
  const res: Record<string,string> = {};
  let i = 0;
  const s = paramStr;
  const n = s.length;
  while (i < n) {
    while (i < n && (s[i] === ' ' || s[i] === '\t' || s[i] === ';')) i++;
    if (i >= n) break;
    const nameStart = i;
    while (i < n && s[i] !== '=' && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') i++;
    const name = s.slice(nameStart, i).toLowerCase();
    while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
    if (s[i] !== '=') continue;
    i++;
    while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
    let value = '';
    if (s[i] === '"') {
      i++;
      let val = '';
      while (i < n && s[i] !== '"') {
        if (s[i] === '\\' && i + 1 < n) { val += s[i + 1]; i += 2; }
        else { val += s[i]; i++; }
      }
      i++; // skip "
      value = val;
    } else {
      const vStart = i;
      while (i < n && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') i++;
      value = s.slice(vStart, i);
    }
    res[name] = value;
  }
  return res;
}

function parseContentType(val: string) {
  const parts = val.split(';');
  const main = parts[0].trim();
  const [type, subtype] = main.split('/');
  const params = parseParams(parts.slice(1).join(';'));
  return { type: (type || '').toLowerCase(), subtype: (subtype || '').toLowerCase(), params };
}

function decodeTransferEncoding(data: Uint8Array, enc: string, lineEnding: string): Uint8Array {
  const e = (enc || '7bit').toLowerCase();
  if (e === '7bit' || e === '8bit' || e === 'binary') return data;
  if (e === 'base64') {
    const str = Buffer.from(data).toString('latin1').replace(/[^A-Za-z0-9+/=]/g, '');
    try { return Uint8Array.from(Buffer.from(str, 'base64')); } catch { return new Uint8Array(); }
  }
  if (e === 'quoted-printable') {
    let s = Buffer.from(data).toString('latin1');
    const lines = s.split(lineEnding);
    let combined = '';
    for (let i = 0; i < lines.length; i++) {
      let line = lines[i].replace(/[ \t]+$/, '');
      const soft = line.endsWith('=');
      if (soft) line = line.slice(0, -1);
      combined += line;
      if (i < lines.length - 1 && !soft) combined += lineEnding;
    }
    const out: number[] = [];
    for (let i = 0; i < combined.length; i++) {
      if (combined[i] === '=' && i + 2 < combined.length && /^[0-9A-Fa-f]{2}$/.test(combined.substr(i + 1, 2))) {
        out.push(parseInt(combined.substr(i + 1, 2), 16));
        i += 2;
      } else {
        out.push(combined.charCodeAt(i));
      }
    }
    return Uint8Array.from(out);
  }
  return data;
}

function getRFC2231Value(params: Record<string,string>, base: string): string | undefined {
  const lowerBase = base.toLowerCase();
  const keys = Object.keys(params).filter(k => k.toLowerCase().startsWith(lowerBase + '*'));
  if (keys.length === 0) return undefined;
  const segs: {num:number; isPercent:boolean; val:string}[] = [];
  for (const k of keys) {
    const lk = k.toLowerCase();
    const m = lk.match(new RegExp('^' + lowerBase + '\\*(\\d+)(\\*)?$'));
    if (m) {
      segs.push({num: parseInt(m[1]), isPercent: !!m[2], val: params[k]});
    } else if (lk === lowerBase + '*') {
      segs.push({num: 0, isPercent: true, val: params[k]});
    }
  }
  if (segs.length === 0) return undefined;
  segs.sort((a,b)=>a.num-b.num);
  let charset = 'us-ascii';
  const bytes: number[] = [];
  for (let i = 0; i < segs.length; i++) {
    const seg = segs[i];
    const val = seg.val;
    if (seg.isPercent) {
      if (i === 0) {
        const m = val.match(/^([^']*)'([^']*)'(.*)$/);
        if (m) {
          charset = m[1] || 'us-ascii';
          const raw = m[3];
          bytes.push(...percentDecode(raw));
        } else {
          bytes.push(...percentDecode(val));
        }
      } else {
        bytes.push(...percentDecode(val));
      }
    } else {
      bytes.push(...Buffer.from(val, 'latin1'));
    }
  }
  return decodeCharsetBytes(Uint8Array.from(bytes), charset);
}

function getFilename(paramsCD: Record<string,string>, paramsCT: Record<string,string>): string | undefined {
  const candidates = [
    {params: paramsCD, base: 'filename', rfc: true},
    {params: paramsCD, base: 'filename', rfc: false},
    {params: paramsCT, base: 'name', rfc: true},
    {params: paramsCT, base: 'name', rfc: false},
  ];
  for (const c of candidates) {
    if (c.rfc) {
      const v = getRFC2231Value(c.params, c.base);
      if (v !== undefined) return v;
    } else {
      const key = c.base.toLowerCase();
      if (c.params[key] !== undefined) {
        return decodeEncodedWords(c.params[key]);
      }
    }
  }
  return undefined;
}

type EntityInfo = {
  headers: Map<string,string>;
  contentType?: {type:string;subtype:string;params:Record<string,string>};
  dispositionType: string;
  dispositionParams: Record<string,string>;
  transferEncoding: string;
  charset?: string;
  bodyRaw: Uint8Array;
  isMultipart: boolean;
  boundary?: string;
  parts?: EntityInfo[];
};

function parseHeadersBlock(buf: Buffer, start: number, lineEnding: string): {headers:Map<string,string>, bodyStart:number} {
  const sep = Buffer.from(lineEnding + lineEnding);
  const idx = buf.indexOf(sep, start);
  let bodyStart: number;
  let headerBytes: Buffer;
  if (idx !== -1) {
    headerBytes = buf.slice(start, idx + lineEnding.length);
    bodyStart = idx + lineEnding.length * 2;
  } else {
    headerBytes = buf.slice(start);
    bodyStart = buf.length;
  }
  const txt = headerBytes.toString('latin1');
  const lines = txt.split(lineEnding);
  const unfolded: string[] = [];
  let cur = '';
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (i === 0) { cur = line; }
    else if (/^[ \t]/.test(line)) { cur += line; }
    else { unfolded.push(cur); cur = line; }
  }
  if (cur) unfolded.push(cur);
  const headers = new Map<string,string>();
  for (const line of unfolded) {
    const colon = line.indexOf(':');
    if (colon === -1) continue;
    const name = line.slice(0, colon).trim().toLowerCase();
    const val = line.slice(colon + 1).trim();
    headers.set(name, val);
  }
  return {headers, bodyStart};
}

function parseEntity(buf: Buffer, start: number, end: number, lineEnding: string): EntityInfo {
  const {headers, bodyStart} = parseHeadersBlock(buf, start, lineEnding);
  const ctRaw = headers.get('content-type');
  let contentType;
  if (ctRaw) contentType = parseContentType(ctRaw);
  else contentType = {type:'text', subtype:'plain', params:{charset:'us-ascii'}};
  const te = (headers.get('content-transfer-encoding') || '7bit').toLowerCase();
  const cdRaw = headers.get('content-disposition');
  let dispositionType = '-';
  let dispositionParams: Record<string,string> = {};
  if (cdRaw) {
    const parts = cdRaw.split(';');
    dispositionType = parts[0].trim().toLowerCase();
    dispositionParams = parseParams(parts.slice(1).join(';'));
  }
  const isMultipart = contentType.type === 'multipart';
  let partsArr: EntityInfo[] = [];
  let boundary: string | undefined;
  let bodyRaw = new Uint8Array();
  if (isMultipart) {
    boundary = contentType.params['boundary'];
    if (boundary) {
      const bodyBuf = buf.slice(bodyStart, end);
      const bodyStr = bodyBuf.toString('latin1');
      const lines = bodyStr.split(lineEnding);
      const delim = '--' + boundary;
      let firstIdx = -1;
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].startsWith(delim)) { firstIdx = i; break; }
      }
      if (firstIdx !== -1) {
        let curLines: string[] = [];
        for (let i = firstIdx + 1; i < lines.length; i++) {
          const ln = lines[i];
          if (ln.startsWith(delim)) {
            const isClose = ln.startsWith(delim + '--');
            const partStr = curLines.join(lineEnding);
            const partBuf = Buffer.from(partStr, 'latin1');
            const partEnt = parseEntity(partBuf, 0, partBuf.length, lineEnding);
            partsArr.push(partEnt);
            curLines = [];
            if (isClose) break;
          } else {
            curLines.push(ln);
          }
        }
      }
    }
    bodyRaw = new Uint8Array();
  } else {
    bodyRaw = buf.slice(bodyStart, end);
  }
  const charset = contentType.type === 'text' ? (contentType.params['charset'] || 'us-ascii') : undefined;
  return {
    headers,
    contentType,
    dispositionType,
    dispositionParams,
    transferEncoding: te,
    charset: charset?.toLowerCase(),
    bodyRaw,
    isMultipart,
    boundary,
    parts: partsArr.length ? partsArr : undefined,
  };
}

function printEntity(e: EntityInfo, depth: number, out: string[]) {
  const indent = '  '.repeat(depth);
  if (e.isMultipart && e.contentType) {
    const partsNum = e.parts?.length ?? 0;
    out.push(`${indent}multipart/${e.contentType.subtype} parts=${partsNum}`);
    if (e.parts) {
      for (const p of e.parts) printEntity(p, depth + 1, out);
    }
  } else {
    const ct = e.contentType!;
    const isText = ct.type.toLowerCase() === 'text';
    const disp = e.dispositionType || '-';
    const isAttachment = disp === 'attachment';
    if (isText && !isAttachment) {
      const charset = e.charset || 'us-ascii';
      const cte = e.transferEncoding;
      const decodedBytes = decodeTransferEncoding(e.bodyRaw, cte, '\n');
      const txt = decodeCharsetBytes(decodedBytes, charset);
      const normalized = txt.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
      const chars = [...normalized].length;
      out.push(`${indent}text/${ct.subtype} charset=${charset} cte=${cte} chars=${chars}`);
      out.push(`${'  '.repeat(depth + 1)}${quoteString(normalized)}`);
    } else {
      const cte = e.transferEncoding;
      const decodedBytes = decodeTransferEncoding(e.bodyRaw, cte, '\n');
      const ctParams = ct.params;
      const nameVal = getFilename(e.dispositionParams, ctParams);
      const nameStr = nameVal !== undefined ? quoteString(nameVal) : '-';
      const size = decodedBytes.length;
      const crc = crc32(decodedBytes).toString(16).padStart(8, '0');
      out.push(`${indent}${ct.type}/${ct.subtype} cte=${cte} disposition=${disp} name=${nameStr} size=${size} crc32=${crc}`);
    }
  }
}

function processFile(filePath: string) {
  const buf = fs.readFileSync(filePath);
  const hasCRLF = buf.includes(0x0d);
  const lineEnding = hasCRLF ? '\r\n' : '\n';
  const entity = parseEntity(buf, 0, buf.length, lineEnding);
  const fromRaw = entity.headers.get('from') || '';
  const subjRaw = entity.headers.get('subject') || '';
  const fromDec = decodeEncodedWords(fromRaw);
  const subjDec = decodeEncodedWords(subjRaw);
  const lines: string[] = [];
  lines.push(`== ${path.basename(filePath)}`);
  lines.push(`From: ${fromRaw ? quoteString(fromDec) : '-'}`);
  lines.push(`Subject: ${subjRaw ? quoteString(subjDec) : '-'}`);
  printEntity(entity, 0, lines);
  return lines.join('\n');
}

function main() {
  const dir = process.argv[2];
  if (!dir) { process.exit(0); }
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml')).sort();
  const outs: string[] = [];
  for (let i = 0; i < files.length; i++) {
    const fp = path.join(dir, files[i]);
    outs.push(processFile(fp));
  }
  console.log(outs.join('\n\n'));
}

main();

import Foundation
import Numerics

typealias Big = BigInt

func pow10(_ e: Int) -> Big {
    if e <= 0 { return Big(1) }
    var r = Big(1)
    for _ in 0..<e { r *= 10 }
    return r
}

func parseDecimal(_ s: String) -> (sign: Int, num: Big, exp: Int) {
    var str = s.trimmingCharacters(in: .whitespacesAndNewlines)
    var sign = 1
    if str.hasPrefix("-") { sign = -1; str.removeFirst() }
    else if str.hasPrefix("+") { str.removeFirst() }
    let parts = str.split(separator: ".", maxSplits: 1, omittingEmptySubsequences: false)
    let intPart = String(parts[0])
    let fracPart = parts.count > 1 ? String(parts[1]) : ""
    let combined = intPart + fracPart
    let numStr = combined.isEmpty ? "0" : combined
    let num = Big(numStr) ?? Big(0)
    return (sign, num, fracPart.count)
}

func roundHalfEven(num: Big, denom: Big) -> Big {
    guard denom != 0 else { return Big(0) }
    let sign = num < 0 ? -1 : 1
    let absNum = num.magnitude
    let q = absNum / denom
    let r = absNum % denom
    let twoR = r * 2
    var res = q
    if twoR > denom {
        res = q + 1
    } else if twoR == denom {
        if q % 2 != 0 { res = q + 1 }
    }
    return sign < 0 ? -res : res
}

func roundAmountToMinor(_ s: String, minor: Int) -> Big {
    let (sign, num, exp) = parseDecimal(s)
    let signedNum = Big(sign) * num * pow10(minor)
    let denom = pow10(exp)
    return roundHalfEven(num: signedNum, denom: denom)
}

struct CurrencyInfo { let code: String; let minor: Int }
struct AccountInfo {
    let code: String
    var balance: Big
    var limit: Big
}

func formatWithCommas(_ v: Big) -> String {
    var s = v.description
    var res = ""
    var count = 0
    for ch in s.reversed() {
        if count > 0 && count % 3 == 0 { res.append(",") }
        res.append(ch)
        count += 1
    }
    return String(res.reversed())
}

func formatBalance(_ bal: Big, minor: Int) -> String {
    if bal == 0 {
        if minor == 0 { return "0" }
        return "0." + String(repeating: "0", count: minor)
    }
    let sign = bal < 0 ? "-" : ""
    let absBal = bal.magnitude
    if minor == 0 {
        return sign + formatWithCommas(absBal)
    } else {
        let powMinor = pow10(minor)
        let intPart = absBal / powMinor
        let fracPart = absBal % powMinor
        let intStr = formatWithCommas(intPart)
        let fracStr = String(fracPart.description)
            .leftPad(toLength: minor, withPad: "0")
        return sign + intStr + "." + fracStr
    }
}

extension String {
    func leftPad(toLength len: Int, withPad pad: String) -> String {
        if self.count >= len { return self }
        return String(repeating: pad, count: len - self.count) + self
    }
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dir = args[1]
let path = URL(fileURLWithPath: dir).appendingPathComponent("ledger.txt").path
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.split(separator: "\n", omittingEmptySubsequences: false)

var currencies: [String: CurrencyInfo] = [:]
var accounts: [String: AccountInfo] = [:]
var rejects: [(Int, String)] = []

for (idx, raw) in lines.enumerated() {
    let lineNo = idx + 1
    let line = raw.trimmingCharacters(in: .whitespaces)
    if line.isEmpty { continue }
    if line.first?.isWhitespace == false, line.hasPrefix("#") { continue }
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    if trimmed.first == "#" { continue }
    let tokens = trimmed.split(whereSeparator: { $0.isWhitespace }).map(String.init)
    guard let cmd = tokens.first else { continue }

    func unknownCheck(_ names: [String]) -> String? {
        for n in names {
            if accounts[n] == nil { return "unknown account \(n)" }
        }
        return nil
    }

    switch cmd {
    case "currency":
        guard tokens.count >= 3, let minor = Int(tokens[2]) else { continue }
        currencies[tokens[1]] = CurrencyInfo(code: tokens[1], minor: minor)

    case "open":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        let code = tokens[2]
        guard let cur = currencies[code] else { continue }
        if accounts[name] != nil {
            rejects.append((lineNo, "REJECT account exists \(name)"))
            continue
        }
        let limitStr = tokens.count >= 4 ? tokens[3] : "0"
        let limit = roundAmountToMinor(limitStr, minor: cur.minor)
        accounts[name] = AccountInfo(code: code, balance: Big(0), limit: limit)

    case "deposit":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        let amountStr = tokens[2]
        if let err = unknownCheck([name]) {
            rejects.append((lineNo, "REJECT \(err)")); continue
        }
        guard let acc = accounts[name] else { continue }
        guard let cur = currencies[acc.code] else { continue }
        let amt = roundAmountToMinor(amountStr, minor: cur.minor)
        if amt <= 0 { rejects.append((lineNo, "REJECT non-positive amount")); continue }
        accounts[name]!.balance += amt

    case "withdraw":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        let amountStr = tokens[2]
        if let err = unknownCheck([name]) {
            rejects.append((lineNo, "REJECT \(err)")); continue
        }
        guard var acc = accounts[name] else { continue }
        guard let cur = currencies[acc.code] else { continue }
        let amt = roundAmountToMinor(amountStr, minor: cur.minor)
        if amt <= 0 { rejects.append((lineNo, "REJECT non-positive amount")); continue }
        let newBal = acc.balance - amt
        if newBal < -acc.limit {
            rejects.append((lineNo, "REJECT insufficient funds \(name)"))
            continue
        }
        acc.balance = newBal
        accounts[name] = acc

    case "transfer":
        guard tokens.count >= 4 else { continue }
        let from = tokens[1], to = tokens[2], amountStr = tokens[3]
        if let err = unknownCheck([from, to]) {
            rejects.append((lineNo, "REJECT \(err)")); continue
        }
        guard let accFrom = accounts[from], let accTo = accounts[to] else { continue }
        if accFrom.code != accTo.code {
            rejects.append((lineNo, "REJECT currency mismatch")); continue
        }
        guard let cur = currencies[accFrom.code] else { continue }
        let amt = roundAmountToMinor(amountStr, minor: cur.minor)
        if amt <= 0 { rejects.append((lineNo, "REJECT non-positive amount")); continue }
        let newBalFrom = accFrom.balance - amt
        if newBalFrom < -accFrom.limit {
            rejects.append((lineNo, "REJECT insufficient funds \(from)")); continue
        }
        accounts[from]!.balance = newBalFrom
        accounts[to]!.balance += amt

    case "convert":
        guard tokens.count >= 5 else { continue }
        let from = tokens[1], to = tokens[2], amountStr = tokens[3], rateStr = tokens[4]
        if let err = unknownCheck([from, to]) {
            rejects.append((lineNo, "REJECT \(err)")); continue
        }
        guard let accFrom = accounts[from], let accTo = accounts[to] else { continue }
        guard let curFrom = currencies[accFrom.code], let curTo = currencies[accTo.code] else { continue }
        let amt = roundAmountToMinor(amountStr, minor: curFrom.minor)
        if amt <= 0 { rejects.append((lineNo, "REJECT non-positive amount")); continue }
        let newBalFrom = accFrom.balance - amt
        if newBalFrom < -accFrom.limit {
            rejects.append((lineNo, "REJECT insufficient funds \(from)")); continue
        }
        let (rSign, rNum, rExp) = parseDecimal(rateStr)
        let signedRNum = Big(rSign) * rNum
        let numerator = amt * signedRNum * pow10(curTo.minor)
        let denominator = pow10(curFrom.minor + rExp)
        let delta = roundHalfEven(num: numerator, denom: denominator)
        accounts[from]!.balance = newBalFrom
        accounts[to]!.balance += delta

    case "interest":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1], rateStr = tokens[2]
        if let err = unknownCheck([name]) {
            rejects.append((lineNo, "REJECT \(err)")); continue
        }
        guard var acc = accounts[name] else { continue }
        let (rSign, rNum, rExp) = parseDecimal(rateStr)
        let signedRNum = Big(rSign) * rNum
        let numerator = acc.balance * signedRNum
        let denominator = pow10(rExp)
        let delta = roundHalfEven(num: numerator, denom: denominator)
        let newBal = acc.balance + delta
        if newBal < -acc.limit {
            rejects.append((lineNo, "REJECT insufficient funds \(name)"))
            continue
        }
        acc.balance = newBal
        accounts[name] = acc

    case "split":
        guard tokens.count >= 4 else { continue }
        let from = tokens[1]
        let amountStr = tokens[2]
        var targets: [(name: String, weight: Big)] = []
        var namesOrder: [String] = [from]
        for i in 3..<tokens.count {
            let tok = tokens[i]
            let parts = tok.split(separator: ":", maxSplits: 1)
            if parts.count == 2 {
                let n = String(parts[0])
                let w = Big(String(parts[1])) ?? Big(0)
                targets.append((n, w))
                namesOrder.append(n)
            }
        }
        if let err = unknownCheck(namesOrder) {
            rejects.append((lineNo, "REJECT \(err)")); continue
        }
        guard let accFrom = accounts[from] else { continue }
        for t in targets {
            guard let accT = accounts[t.name] else { continue }
            if accT.code != accFrom.code {
                rejects.append((lineNo, "REJECT currency mismatch")); continue
            }
        }
        guard let cur = currencies[accFrom.code] else { continue }
        let amt = roundAmountToMinor(amountStr, minor: cur.minor)
        if amt <= 0 { rejects.append((lineNo, "REJECT non-positive amount")); continue }
        let newBalFrom = accFrom.balance - amt
        if newBalFrom < -accFrom.limit {
            rejects.append((lineNo, "REJECT insufficient funds \(from)")); continue
        }
        // distribution
        let totalWeight = targets.map { $0.weight }.reduce(Big(0), +)
        var qVals: [Big] = []
        var rVals: [Big] = []
        var sumQ = Big(0)
        for t in targets {
            let prod = amt * t.weight
            let q = prod / totalWeight
            let r = prod % totalWeight
            qVals.append(q)
            rVals.append(r)
            sumQ += q
        }
        let leftover = amt - sumQ
        var indices = Array(0..<targets.count)
        indices.sort { a, b in
            if rVals[a] != rVals[b] { return rVals[a] > rVals[b] }
            return a < b
        }
        var adds = Array(repeating: Big(0), count: targets.count)
        for i in 0..<Int(leftover) {
            adds[indices[i]] = Big(1)
        }
        // apply
        accounts[from]!.balance = newBalFrom
        for (i, t) in targets.enumerated() {
            let inc = qVals[i] + adds[i]
            accounts[t.name]!.balance += inc
        }

    default:
        break
    }
}

for (ln, msg) in rejects {
    print("line \(ln): \(msg)")
}
print("")
let sortedAccounts = accounts.sorted { $0.key < $1.key }
for (name, acc) in sortedAccounts {
    guard let cur = currencies[acc.code] else { continue }
    let balStr = formatBalance(acc.balance, minor: cur.minor)
    print("\(name) \(acc.code) \(balStr)")
}
print("")
var totals: [String: (sum: Big, count: Int)] = [:]
for (_, acc) in accounts {
    let entry = totals[acc.code] ?? (Big(0), 0)
    totals[acc.code] = (entry.sum + acc.balance, entry.count + 1)
}
for code in totals.keys.sorted() {
    let cur = currencies[code]!
    let sum = totals[code]!.sum
    let cnt = totals[code]!.count
    let sumStr = formatBalance(sum, minor: cur.minor)
    print("total \(code) \(sumStr) (\(cnt) accounts)")
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        Path p = Paths.get(args[0], "program.tern");
        String src = Files.readString(p);
        Lexer lex = new Lexer(src);
        List<Token> tokens = lex.tokenize();
        Parser parser = new Parser(tokens);
        Program prog = parser.parseProgram();
        Interpreter interp = new Interpreter(prog);
        interp.run();
    }

    /* ---------- Lexer ---------- */
    static class Lexer {
        String s; int pos=0, line=1;
        Lexer(String s){this.s=s;}
        List<Token> tokenize(){
            List<Token> out=new ArrayList<>();
            while(pos<s.length()){
                char c=s.charAt(pos);
                if(c==' '||c=='\t'||c=='\r'){pos++; continue;}
                if(c=='\n'){line++;pos++; continue;}
                if(c=='#'){while(pos<s.length() && s.charAt(pos)!='\n')pos++; continue;}
                if(c=='"'){out.add(readString()); continue;}
                if(Character.isDigit(c)){out.add(readInt()); continue;}
                if(Character.isLetter(c)||c=='_'){out.add(readIdent()); continue;}
                out.add(readOp());
            }
            out.add(new Token(TokenType.EOF,"",line));
            return out;
        }
        Token readString(){
            int startLine=line;
            pos++; StringBuilder sb=new StringBuilder();
            while(pos<s.length()){
                char c=s.charAt(pos);
                if(c=='"'){pos++; break;}
                if(c=='\\'){
                    pos++;
                    if(pos>=s.length()) break;
                    char e=s.charAt(pos);
                    if(e=='n') sb.append('\n');
                    else if(e=='t') sb.append('\t');
                    else if(e=='"') sb.append('"');
                    else if(e=='\\') sb.append('\\');
                    else sb.append(e);
                    pos++; continue;
                }
                sb.append(c); pos++;
            }
            return new Token(TokenType.STRING,sb.toString(),startLine);
        }
        Token readInt(){
            int start=pos, startLine=line;
            while(pos<s.length() && Character.isDigit(s.charAt(pos))) pos++;
            String txt=s.substring(start,pos);
            return new Token(TokenType.INT,txt,startLine);
        }
        Token readIdent(){
            int start=pos, startLine=line;
            while(pos<s.length() && (Character.isLetterOrDigit(s.charAt(pos))||s.charAt(pos)=='_')) pos++;
            String txt=s.substring(start,pos);
            TokenType t = keywords.getOrDefault(txt, TokenType.IDENT);
            return new Token(t,txt,startLine);
        }
        Token readOp(){
            int startLine=line;
            char c=s.charAt(pos);
            char n = pos+1<s.length()? s.charAt(pos+1):0;
            String op=""+c;
            if(c=='=' && n=='='){op="==";pos+=2;}
            else if(c=='!' && n=='='){op="!=";pos+=2;}
            else if(c=='<' && n=='='){op="<=";pos+=2;}
            else if(c=='>' && n=='='){op=">=";pos+=2;}
            else {pos++;}
            return new Token(TokenType.OP,op,startLine);
        }
        static final Map<String,TokenType> keywords = new HashMap<>();
        static{keywords.put("let",TokenType.LET);keywords.put("fn",TokenType.FN);keywords.put("if",TokenType.IF);
            keywords.put("else",TokenType.ELSE);keywords.put("while",TokenType.WHILE);keywords.put("for",TokenType.FOR);
            keywords.put("in",TokenType.IN);keywords.put("return",TokenType.RETURN);keywords.put("break",TokenType.BREAK);
            keywords.put("continue",TokenType.CONTINUE);keywords.put("and",TokenType.AND);keywords.put("or",TokenType.OR);
            keywords.put("not",TokenType.NOT);keywords.put("true",TokenType.TRUE);keywords.put("false",TokenType.FALSE);
            keywords.put("nil",TokenType.NIL);}
    }

    enum TokenType { INT, STRING, IDENT, LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE, AND, OR, NOT, TRUE, FALSE, NIL, OP, EOF }
    static class Token { TokenType type; String text; int line; Token(TokenType t,String txt,int l){type=t;text=txt;line=l;} }

    /* ---------- Parser ---------- */
    static class Parser {
        List<Token> t; int i=0;
        Parser(List<Token> t){this.t=t;}
        Token peek(){return t.get(i);}
        Token next(){return t.get(i++);}
        boolean match(TokenType tt){if(peek().type==tt){i++;return true;}return false;}
        boolean matchOp(String op){Token tk=peek(); if(tk.type==TokenType.OP && tk.text.equals(op)){i++;return true;}return false;}
        Token expect(TokenType tt){Token tk=peek(); if(tk.type!=tt) throw new RuntimeException("parse error"); i++; return tk;}
        Program parseProgram(){
            List<Stmt> stmts=new ArrayList<>();
            while(peek().type!=TokenType.EOF) stmts.add(parseStmt());
            return new Program(stmts);
        }
        Stmt parseStmt(){
            Token tk=peek();
            if(tk.type==TokenType.LET){i++; Token id=expect(TokenType.IDENT); expectOp("="); Expr e=parseExpr(0); expectOp(";"); return new LetStmt(id.text,e);}
            if(tk.type==TokenType.FN){i++; Token id=expect(TokenType.IDENT); expectOp("("); List<String> params=parseParams(); expectOp(")"); Block b=parseBlock(); return new FnDeclStmt(id.text,params,b);}
            if(tk.type==TokenType.IF){i++; Expr cond=parseExpr(0); Block thenB=parseBlock(); Stmt elseS=null;
                if(match(TokenType.ELSE)){ if(peek().type==TokenType.IF) elseS=parseStmt(); else elseS=parseBlock(); }
                return new IfStmt(cond,thenB,elseS);}
            if(tk.type==TokenType.WHILE){i++; Expr cond=parseExpr(0); Block b=parseBlock(); return new WhileStmt(cond,b);}
            if(tk.type==TokenType.FOR){i++; Token id=expect(TokenType.IDENT); expect(TokenType.IN); Expr e=parseExpr(0); Block b=parseBlock(); return new ForStmt(id.text,e,b);}
            if(tk.type==TokenType.RETURN){i++; Expr e=null; if(peek().type!=TokenType.OP||!peek().text.equals(";")) e=parseExpr(0); expectOp(";"); return new ReturnStmt(e);}
            if(tk.type==TokenType.BREAK){i++; expectOp(";"); return new BreakStmt();}
            if(tk.type==TokenType.CONTINUE){i++; expectOp(";"); return new ContinueStmt();}
            // assignment or expr stmt
            if(tk.type==TokenType.IDENT && t.get(i+1).type==TokenType.OP && t.get(i+1).text.equals("=")){
                String name=tk.text; i+=2;
                Expr e=parseExpr(0); expectOp(";"); return new AssignStmt(new VarExpr(name),e);}
            // general expression statement possibly with assignment
            Expr left=parseExpr(0);
            if(matchOp("=")){
                Expr right=parseExpr(0); expectOp(";"); return new AssignStmt(left,right);}
            expectOp(";"); return new ExprStmt(left);
        }
        List<String> parseParams(){
            List<String> p=new ArrayList<>();
            if(peek().type==TokenType.IDENT){p.add(peek().text); i++; while(matchOp(",")){p.add(expect(TokenType.IDENT).text);}}
            return p;
        }
        Block parseBlock(){expect(TokenType.OP); // {
            if(peek().text.equals("{")) i++; else { // already consumed?
            }
            // Actually we consumed '{' via expect OP? Let's handle properly
            // Simpler: assume '{' consumed
            List<Stmt> stmts=new ArrayList<>();
            while(!matchOp("}")) stmts.add(parseStmt());
            return new Block(stmts);
        }
        // expression parsing
        Expr parseExpr(int minPrec){
            Expr left=parseUnary();
            while(true){
                Token tk=peek();
                if(tk.type!=TokenType.OP) break;
                String op=tk.text;
                int prec=precOf(op);
                if(prec<minPrec) break;
                i++;
                int nextMin = prec+1; // left assoc
                Expr right=parseExpr(nextMin);
                left=new BinExpr(left,op,right);
            }
            return left;
        }
        Expr parseUnary(){
            Token tk=peek();
            if(tk.type==TokenType.NOT){i++; Expr e=parseUnary(); return new UnaryExpr("not",e);}
            if(tk.type==TokenType.OP && tk.text.equals("-")){i++; Expr e=parseUnary(); return new UnaryExpr("-",e);}
            return parsePrimary();
        }
        Expr parsePrimary(){
            Token tk=peek();
            if(tk.type==TokenType.INT){i++; return new LitExpr(Value.ofInt(Long.parseLong(tk.text)));}
            if(tk.type==TokenType.STRING){i++; return new LitExpr(Value.ofString(tk.text));}
            if(tk.type==TokenType.TRUE){i++; return new LitExpr(Value.ofBool(true));}
            if(tk.type==TokenType.FALSE){i++; return new LitExpr(Value.ofBool(false));}
            if(tk.type==TokenType.NIL){i++; return new LitExpr(Value.nil());}
            if(tk.type==TokenType.IDENT){i++; Expr e=new VarExpr(tk.text); return parsePostfix(e);}
            if(tk.type==TokenType.OP && tk.text.equals("(")){i++; Expr e=parseExpr(0); expectOp(")"); return parsePostfix(e);}
            if(tk.type==TokenType.OP && tk.text.equals("[")){i++; Expr e=parseListLit(); return parsePostfix(e);}
            if(tk.type==TokenType.FN){i++; expectOp("("); List<String> params=parseParams(); expectOp(")"); Block b=parseBlock(); return new LambdaExpr(params,b);}
            throw new RuntimeException("unexpected token "+tk.text);
        }
        Expr parsePostfix(Expr base){
            while(true){
                Token tk=peek();
                if(tk.type==TokenType.OP && tk.text.equals("(")){
                    i++; List<Expr> args=new ArrayList<>();
                    if(!matchOp(")")){args.add(parseExpr(0)); while(matchOp(",")){args.add(parseExpr(0));} expectOp(")");}
                    base=new CallExpr(base,args);
                } else if(tk.type==TokenType.OP && tk.text.equals("[")){
                    i++; Expr idx=parseExpr(0); expectOp("]"); base=new IndexExpr(base,idx);
                } else break;
            }
            return base;
        }
        Expr parseListLit(){
            List<Expr> elems=new ArrayList<>();
            if(!matchOp("]")){elems.add(parseExpr(0)); while(matchOp(",")){elems.add(parseExpr(0));} expectOp("]");}
            return new ListLitExpr(elems);
        }
        int precOf(String op){
            return switch(op){
                case "or" -> 1;
                case "and" -> 2;
                case "==","!=","<",">","<=",">=" -> 3;
                case "+","-" -> 4;
                case "*","/","%" -> 5;
                default -> -1;
            };
        }
        void expectOp(String op){Token tk=next(); if(!(tk.type==TokenType.OP && tk.text.equals(op))) throw new RuntimeException("expected "+op);}
    }

    /* ---------- AST ---------- */
    static class Program { List<Stmt> stmts; Program(List<Stmt> s){stmts=s;} }
    interface Stmt {}
    static class LetStmt implements Stmt { String name; Expr e; LetStmt(String n,Expr e){name=n;this.e=e;} }
    static class FnDeclStmt implements Stmt { String name; List<String> params; Block body; FnDeclStmt(String n,List<String>p,Block b){name=n;params=p;body=b;} }
    static class IfStmt implements Stmt { Expr cond; Block thenB; Stmt elseS; IfStmt(Expr c,Block t,Stmt e){cond=c;thenB=t;elseS=e;} }
    static class WhileStmt implements Stmt { Expr cond; Block body; WhileStmt(Expr c,Block b){cond=c;body=b;} }
    static class ForStmt implements Stmt { String var; Expr iterable; Block body; ForStmt(String v,Expr i,Block b){var=v;iterable=i;body=b;} }
    static class ReturnStmt implements Stmt { Expr e; ReturnStmt(Expr e){this.e=e;} }
    static class BreakStmt implements Stmt {}
    static class ContinueStmt implements Stmt {}
    static class AssignStmt implements Stmt { Expr target; Expr value; AssignStmt(Expr t,Expr v){target=t;value=v;} }
    static class ExprStmt implements Stmt { Expr e; ExprStmt(Expr e){this.e=e;} }
    static class Block { List<Stmt> stmts; Block(List<Stmt> s){stmts=s;} }

    interface Expr {}
    static class VarExpr implements Expr { String name; VarExpr(String n){name=n;} }
    static class LitExpr implements Expr { Value v; LitExpr(Value v){this.v=v;} }
    static class BinExpr implements Expr { Expr l, r; String op; BinExpr(Expr l,String op,Expr r){this.l=l;this.op=op;this.r=r;} }
    static class UnaryExpr implements Expr { String op; Expr e; UnaryExpr(String op,Expr e){this.op=op;this.e=e;} }
    static class CallExpr implements Expr { Expr callee; List<Expr> args; CallExpr(Expr c,List<Expr>a){callee=c;args=a;} }
    static class IndexExpr implements Expr { Expr obj, idx; IndexExpr(Expr o,Expr i){obj=o;idx=i;} }
    static class ListLitExpr implements Expr { List<Expr> elems; ListLitExpr(List<Expr> e){elems=e;} }
    static class LambdaExpr implements Expr { List<String> params; Block body; LambdaExpr(List<String>p,Block b){params=p;body=b;} }

    /* ---------- Values ---------- */
    static abstract class Value { abstract String typeName(); }
    static class IntVal extends Value { long v; IntVal(long v){this.v=v;} String typeName(){return "int";} }
    static class BoolVal extends Value { boolean v; BoolVal(boolean v){this.v=v;} String typeName(){return "bool";} }
    static class StringVal extends Value { String v; StringVal(String v){this.v=v;} String typeName(){return "string";} }
    static class NilVal extends Value { String typeName(){return "nil";} }
    static class ListVal extends Value { List<Value> data=new ArrayList<>(); String typeName(){return "list";} }
    static class FuncVal extends Value { List<String> params; Block body; Scope captured; FuncVal(List<String>p,Block b,Scope c){params=p;body=b;captured=c;} String typeName(){return "function";} }
    static class BuiltinVal extends Value { String name; BuiltinFn fn; BuiltinVal(String n,BuiltinFn f){name=n;fn=f;} String typeName(){return "function";} }

    static Value ofInt(long v){return new IntVal(v);}
    static Value ofBool(boolean v){return new BoolVal(v);}
    static Value ofString(String v){return new StringVal(v);}
    static Value nil(){return new NilVal();}

    /* ---------- Scope ---------- */
    static class Scope { Map<String,Value> vars=new HashMap<>(); Scope parent; Scope(Scope p){parent=p;} }

    /* ---------- Interpreter ---------- */
    static class Interpreter {
        Program prog;
        Scope global;
        Interpreter(Program p){prog=p; global=new Scope(null); initBuiltins();}
        void initBuiltins(){
            putBuiltin("print", (args,sc)->{StringBuilder sb=new StringBuilder(); for(int i=0;i<args.size();i++){ if(i>0) sb.append(' '); sb.append(display(args.get(i),new HashSet<>())); } System.out.println(sb.toString()); return nil();});
            putBuiltin("str", (args,sc)->{ return ofString(display(args.get(0),new HashSet<>()));});
            putBuiltin("type", (args,sc)->{ return ofString(args.get(0).typeName());});
            putBuiltin("len", (args,sc)->{ Value v=args.get(0); if(v instanceof StringVal s) return ofInt(s.v.length()); if(v instanceof ListVal l) return ofInt(l.data.size()); error("bad argument to len"); return nil();});
            putBuiltin("push", (args,sc)->{ ListVal l=(ListVal)args.get(0); l.data.add(args.get(1)); return nil();});
            putBuiltin("pop", (args,sc)->{ ListVal l=(ListVal)args.get(0); if(l.data.isEmpty()) error("bad argument to pop"); return l.data.remove(l.data.size()-1);});
            putBuiltin("range", (args,sc)->{ long a=((IntVal)args.get(0)).v; long b=((IntVal)args.get(1)).v; ListVal lv=new ListVal(); for(long i=a;i<b;i++) lv.data.add(ofInt(i)); return lv;});
            putBuiltin("slice", (args,sc)->{ Value x=args.get(0); long a=((IntVal)args.get(1)).v; long b=((IntVal)args.get(2)).v; if(x instanceof StringVal s){ String str=s.v; String sub=str.substring((int)a,(int)b); return ofString(sub);} ListVal l=(ListVal)x; ListVal out=new ListVal(); for(long i=a;i<b && i<l.data.size();i++) out.data.add(l.data.get((int)i)); return out;});
        }
        void putBuiltin(String name, BuiltinFn fn){global.vars.put(name,new BuiltinVal(name,fn));}
        void run(){ execBlock(prog.stmts, global); }
        void execBlock(List<Stmt> stmts, Scope cur){
            for(Stmt s: stmts) execStmt(s,cur);
        }
        void execStmt(Stmt s, Scope cur){
            if(s instanceof LetStmt ls){ Value v=evalExpr(ls.e,cur); Scope ns=new Scope(cur); ns.vars.put(ls.name,v); cur.vars.put(ls.name,v); }
            else if(s instanceof FnDeclStmt fs){ FuncVal fv=new FuncVal(fs.params,fs.body,cur); cur.vars.put(fs.name,fv); }
            else if(s instanceof IfStmt is){ if(isTruthy(evalExpr(is.cond,cur))) execBlock(is.thenB.stmts, new Scope(cur)); else if(is.elseS!=null){ if(is.elseS instanceof Block b) execBlock(b.stmts,new Scope(cur)); else execStmt(is.elseS,cur);} }
            else if(s instanceof WhileStmt ws){ while(isTruthy(evalExpr(ws.cond,cur))){ try{ execBlock(ws.body.stmts,new Scope(cur)); } catch(ContinueException ce){} catch(BreakException be){ break; } } }
            else if(s instanceof ForStmt fs){ Value it=evalExpr(fs.iterable,cur); if(!(it instanceof ListVal lv)) error("cannot iterate "+it.typeName(), fs); int i=0; while(i<lv.data.size()){ Scope loopScope=new Scope(cur); loopScope.vars.put(fs.var, lv.data.get(i)); try{ execBlock(fs.body.stmts, loopScope); } catch(ContinueException ce){} catch(BreakException be){ break; } i++; } }
            else if(s instanceof ReturnStmt rs){ Value v = rs.e==null? nil(): evalExpr(rs.e,cur); throw new ReturnException(v); }
            else if(s instanceof BreakStmt){ throw new BreakException(); }
            else if(s instanceof ContinueStmt){ throw new ContinueException(); }
            else if(s instanceof AssignStmt as){ Value v=evalExpr(as.value,cur); assignTarget(as.target,v,cur); }
            else if(s instanceof ExprStmt es){ evalExpr(es.e,cur); }
        }
        void assignTarget(Expr target, Value v, Scope cur){
            if(target instanceof VarExpr ve){ Value holder=findVar(ve.name,cur); if(holder==null) error("undefined variable "+ve.name); setVar(ve.name,v,cur); }
            else if(target instanceof IndexExpr ie){ Value obj=evalExpr(ie.obj,cur); Value idxV=evalExpr(ie.idx,cur); if(!(obj instanceof ListVal lv)) error("cannot assign into "+obj.typeName()); if(!(idxV instanceof IntVal iv)) error("cannot index list with "+idxV.typeName()); int i=(int)iv.v; checkIndex(i,lv); lv.data.set(i,v); }
            else { error("invalid assignment target"); }
        }
        Value findVar(String name, Scope cur){ for(Scope s=cur; s!=null; s=s.parent){ if(s.vars.containsKey(name)) return s.vars.get(name);} return null; }
        void setVar(String name, Value v, Scope cur){ for(Scope s=cur; s!=null; s=s.parent){ if(s.vars.containsKey(name)){ s.vars.put(name,v); return; } } error("undefined variable "+name); }
        Value evalExpr(Expr e, Scope cur){
            if(e instanceof LitExpr le){ return le.v; }
