        }
        void assignTarget(Expr target,Value v,Scope cur){
            if(target instanceof VarExpr ve){Value holder=findVar(ve.name,cur);if(holder==null)error("undefined variable "+ve.name,ve.line);setVar(ve.name,v,cur);}
            else if(target instanceof IndexExpr ie){Value obj=evalExpr(ie.obj,cur);Value idxV=evalExpr(ie.idx,cur);if(!(obj instanceof ListVal lv))error("cannot assign into "+obj.typeName(),ie.line);if(!(idxV instanceof IntVal iv))error("cannot index list with "+idxV.typeName(),ie.line);int i=(int)iv.v;checkIndex(i,lv,ie.line);lv.data.set(i,v);}
