        Value findVar(String name,Scope cur){for(Scope s=cur;s!=null;s=s.parent){if(s.vars.containsKey(name))return s.vars.get(name);}return null;}
        void setVar(String name,Value v,Scope cur){for(Scope s=cur;s!=null;s=s.parent){if(s.vars.containsKey(name)){s.vars.put(name,v);return;}}error("undefined variable "+name,1);}
        Value evalExpr(Expr e,Scope cur){
            if(e instanceof LitExpr le){return le.v;}
            if(e instanceof VarExpr ve){Value v=findVar(ve.name,cur);if(v==null)error("undefined variable "+ve.name,ve.line);return v;}
            if(e instanceof UnaryExpr ue){Value v=evalExpr(ue.e,cur);if(ue.op.equals("not"))return ofBool(!isTruthy(v));if(ue.op.equals("-")){if(!(v instanceof IntVal iv))error("cannot apply - to "+v.typeName(),ue.line);long r=-iv.v;checkOverflow(r);return ofInt(r);} }
