            if(op.equals("or")){if(isTruthy(l))return l;return r;}
            if(l instanceof IntVal li && r instanceof IntVal ri){long a=li.v,b=ri.v;switch(op){case"+"->{long res=a+b;checkOverflow(res);return ofInt(res);}case"-"->{long res=a-b;checkOverflow(res);return ofInt(res);}case"*"->{long res=a*b;checkOverflow(res);return ofInt(res);}case"/"->{if(b==0)error("division by zero",line);long res=a/b;checkOverflow(res);return ofInt(res);}case"%"->{if(b==0)error("division by zero",line);long res=a-(a/b)*b;checkOverflow(res);return ofInt(res);}case"=="->return ofBool(a==b);case"!="->return ofBool(a!=b);case"<"->return ofBool(a<b);case">"->return ofBool(a>b);case"<="->return ofBool(a<=b);case">="->return ofBool(a>=b);} }
            if(l instanceof StringVal ls && r instanceof StringVal rs){if(op.equals("+"))return ofString(ls.v+rs.v);if(op.equals("=="))return ofBool(ls.v.equals(rs.v));if(op.equals("!="))return ofBool(!ls.v.equals(rs.v));if(op.equals("<"))return ofBool(ls.v.compareTo(rs.v)<0);if(op.equals(">"))return ofBool(ls.v.compareTo(rs.v)>0);if(op.equals("<="))return ofBool(ls.v.compareTo(rs.v)<=0);if(op.equals(">="))return ofBool(ls.v.compareTo(rs.v)>=0);}
            if(op.equals("+")&&l instanceof ListVal ll && r instanceof ListVal rl){ListVal out=new ListVal();out.data.addAll(ll.data);out.data.addAll(rl.data);return out;}
            if(op.equals("==")||op.equals("!=")){boolean eq=equalsValues(l,r);return op.equals("==")?ofBool(eq):ofBool(!eq);}
