        }
        boolean equalsValues(Value a,Value b){if(a.getClass()!=b.getClass())return false;if(a instanceof IntVal ia && b instanceof IntVal ib)return ia.v==ib.v;if(a instanceof BoolVal ba && b instanceof BoolVal bb)return ba.v==bb.v;if(a instanceof StringVal sa && b instanceof StringVal sb)return sa.v.equals(sb.v);if(a instanceof NilVal)return true;if(a instanceof ListVal la && b instanceof ListVal lb){if(la.data.size()!=lb.data.size())return false;for(int i=0;i<la.data.size();i++)if(!equalsValues(la.data.get(i),lb.data.get(i)))return false;return true;}if(a instanceof FuncVal fa && b instanceof FuncVal fb)return fa==fb;return false;}
        Value callFunc(Value callee,List<Value>args,Scope cur,int line){if(callee instanceof BuiltinVal bv){if(args.size()!=bv.fn.arity())error("expected "+bv.fn.arity()+" arguments, got "+args.size(),line);return bv.fn.apply(args,cur);}if(callee instanceof FuncVal fv){if(args.size()!=fv.params.size())error("expected "+fv.params.size()+" arguments, got "+args.size(),line);Scope ns=new Scope(fv.captured);for(int i=0;i<fv.params.size();i++)ns.vars.put(fv.params.get(i),args.get(i));try{execBlock(fv.body.stmts,ns);return nil();}catch(ReturnException re){return re.value;}}error("cannot call "+callee.typeName(),line);return nil();}
        boolean isTruthy(Value v){if(v instanceof BoolVal b)return b.v;if(v instanceof NilVal)return false;if(v instanceof IntVal i)return i.v!=0;if(v instanceof StringVal s)return s.v.length()>0;if(v instanceof ListVal l)return l.data.size()>0;return true;}
        void checkOverflow(long v){if(v<Long.MIN_VALUE||v>Long.MAX_VALUE)error("integer overflow",1);}
        void checkIndex(int i,int len,int line){if(i<0||i>=len)error("index "+i+" out of range for length "+len,line);}
        String display(Value v,Set<Value>seen,boolean quote){if(v instanceof IntVal i)return Long.toString(i.v);if(v instanceof BoolVal b)return b.v?"true":"false";if(v instanceof NilVal)return "nil";if(v instanceof FuncVal||v instanceof BuiltinVal)return "<fn>";if(v instanceof StringVal s){if(quote)return "\""+escape(s.v)+"\"";return s.v;}if(v instanceof ListVal l){if(seen.contains(l))return "[...]";seen.add(l);StringBuilder sb=new StringBuilder("[");for(int i=0;i<l.data.size();i++){if(i>0)sb.append(", ");Value e=l.data.get(i);if(e instanceof StringVal ss)sb.append("\""+escape(ss.v)+"\"");else sb.append(display(e,seen,true));}sb.append("]");seen.remove(l);return sb.toString();}return "";}
        String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\t","\\t");}
        void error(String msg,int line){System.out.println("error at line "+line+": "+msg);System.exit(0);}
        interface BuiltinFn{int arity();Value apply(List<Value>args,Scope sc);}
    }
    static class ReturnException extends RuntimeException{Value value;ReturnException(Value v){value=v;}}
    static class BreakException extends RuntimeException{}
    static class ContinueException extends RuntimeException{}
}

