typedef struct { char *name; char *value; } Header;
typedef struct { Header *h; int n; int cap; } Headers;

static void headers_init(Headers *hs){hs->h=NULL;hs->n=0;hs->cap=0;}
static void headers_add(Headers *hs,char *name,char *value){
 if(hs->n==hs->cap){hs->cap=hs->cap?hs->cap*2:16;hs->h=realloc(hs->h,hs->cap*sizeof(Header));}
 hs->h[hs->n].name=name;hs->h[hs->n].value=value;hs->n++;
}
static char *headers_get(Headers *hs,const char *name){
 for(int i=0;i<hs->n;i++) if(strcasecmp(hs->h[i].name,name)==0) return hs->h[i].value;
 return NULL;
}
static void headers_free(Headers *hs){for(int i=0;i<hs->n;i++){free(hs->h[i].name);free(hs->h[i].value);}free(hs->h);}

static char *strcasestr_dup(const char *s){char *d=malloc(strlen(s)+1);for(size_t i=0;s[i];i++)d[i]=tolower((unsigned char)s[i]);d[strlen(s)]=0;return d;}

static char *trim_copy(const char *s,int len){
 while(len>0 && isspace((unsigned char)s[0])){s++;len--;}
 while(len>0 && isspace((unsigned char)s[len-1])) len--;
 char *r=malloc(len+1); memcpy(r,s,len); r[len]=0; return r;
}
static char *trim_copy_n(const char *s){return trim_copy(s,strlen(s));}

static int is_line_break(const unsigned char *buf,int pos,int len,int crlf){
 if(crlf){ if(pos+1<len && buf[pos]=='\r' && buf[pos+1]=='\n') return 2; }
 else { if(buf[pos]=='\n') return 1; }
 return 0;
}
static int find_line_end(const unsigned char *buf,int pos,int len,int crlf){
 int lb=is_line_break(buf,pos,len,crlf);
 if(lb) return pos+lb;
 return len;
}

/* headers parsing */
static Headers parse_headers(const unsigned char *buf,int start,int end,int crlf){
 Headers hs; headers_init(&hs);
 int pos=start;
 char *cur_line=NULL; int cur_len=0;
 int in_header=1;
 while(pos<end && in_header){
   int line_start=pos;
   int line_end=find_line_end(buf,pos,end,crlf);
   int line_len=line_end-line_start;
   const unsigned char *line=buf+line_start;
   int is_empty=1; for(int i=0;i<line_len;i++) if(!isspace(line[i])){is_empty=0;break;}
   if(cur_line){
     if(line_len==0 || (line_len>0 && !isspace(line[0]))){
        /* finish previous */
        /* parse cur_line */
        char *colon=strchr(cur_line,':');
        if(colon){
           int nlen=colon-cur_line;
           char *name=trim_copy(cur_line,nlen);
           char *val=trim_copy(colon+1,cur_len-nlen-1);
           headers_add(&hs,name,val);
        }
        free(cur_line); cur_line=NULL; cur_len=0;
     }
   }
   if(line_len==0){
     if(cur_line){ /* finish */ char *colon=strchr(cur_line,':'); if(colon){int nlen=colon-cur_line; char *name=trim_copy(cur_line,nlen); char *val=trim_copy(colon+1,cur_len-nlen-1); headers_add(&hs,name,val);} free(cur_line);}
     in_header=0; break;
   }
   if(!cur_line){
     cur_line=malloc(line_len+1); memcpy(cur_line,line,line_len); cur_line[line_len]=0; cur_len=line_len;
   }else{
     if(line_len>0 && isspace(line[0])){
        cur_line=realloc(cur_line,cur_len+line_len+1);
        memcpy(cur_line+cur_len,line,line_len);
        cur_len+=line_len;
        cur_line[cur_len]=0;
     }else{
        /* new header */
        char *colon=strchr(cur_line,':');
        if(colon){int nlen=colon-cur_line; char *name=trim_copy(cur_line,nlen); char *val=trim_copy(colon+1,cur_len-nlen-1); headers_add(&hs,name,val);}
        free(cur_line);
        cur_line=malloc(line_len+1); memcpy(cur_line,line,line_len); cur_line[line_len]=0; cur_len=line_len;
     }
   }
   pos=line_end;
 }
 if(cur_line){
   char *colon=strchr(cur_line,':');
   if(colon){int nlen=colon-cur_line; char *name=trim_copy(cur_line,nlen); char *val=trim_copy(colon+1,cur_len-nlen-1); headers_add(&hs,name,val);}
   free(cur_line);
 }
 return hs;
}

/* content type parsing */
typedef struct { char *type; char *subtype; char *charset; char *boundary; char *disposition; } CInfo;

static char *lower_dup(const char *s){char *d=strdup(s);for(char *p=d;*p;p++)*p=tolower((unsigned char)*p);return d;}

static void parse_params(const char *value, char **charset, char **boundary, char **disposition){
 *charset=*boundary=*disposition=NULL;
 if(!value) return;
 const char *p=value;
 while(*p && isspace((unsigned char)*p))p++;
 const char *semi=strchr(p,';');
 char *typepart;
 if(semi){typepart=malloc(semi-p+1); memcpy(typepart,p,semi-p); typepart[semi-p]=0; p=semi+1;}
 else {typepart=strdup(p); p="";}
 /* ignore typepart for params */
 free((void*)typepart);
 while(*p){
   while(*p && isspace((unsigned char)*p))p++;
   if(!*p)break;
   const char *name_start=p;
   while(*p && *p!='=' && *p!=';' && !isspace((unsigned char)*p))p++;
   int nlen=p-name_start;
   char *name=malloc(nlen+1); memcpy(name,name_start,nlen); name[nlen]=0;
   while(*p && isspace((unsigned char)*p))p++;
   if(*p=='=')p++;
   while(*p && isspace((unsigned char)*p))p++;
   char *val=NULL;
   if(*p=='"'){
     p++; const char *vstart=p;
     while(*p && *p!='"'){ if(*p=='\\' && *(p+1))p+=2; else p++; }
     int vlen=p-vstart;
     val=malloc(vlen+1); memcpy(val,vstart,vlen); val[vlen]=0;
     if(*p=='"')p++;
   }else{
     const char *vstart=p;
     while(*p && *p!=';' && !isspace((unsigned char)*p))p++;
     int vlen=p-vstart;
     val=malloc(vlen+1); memcpy(val,vstart,vlen); val[vlen]=0;
   }
   char *lname=lower_dup(name);
   if(strcmp(lname,"charset")==0 && !*charset){*charset=lower_dup(val);}
   else if(strcmp(lname,"boundary")==0 && !*boundary){*boundary=strdup(val);}
   else if(strcmp(lname,"filename")==0){/* handled elsewhere */}
   free(name); free(lname); free(val);
   while(*p && *p!=';')p++;
   if(*p==';')p++;
 }
}

/* encoded-word decoding */
static int hexval(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='A'&&c<='F')return c-'A'+10; if(c>='a'&&c<='f')return c-'a'+10; return -1;}
static unsigned char *base64_decode(const char *in,int *outlen){
 int len=strlen(in);
 unsigned char *out=malloc(len*3/4+4); int o=0;
 int buf=0, bits=0;
 for(int i=0;i<len;i++){
   unsigned char c=in[i];
   int v=-1;
   if(c>='A'&&c<='Z')v=c-'A';
   else if(c>='a'&&c<='z')v=c-'a'+26;
   else if(c>='0'&&c<='9')v=c-'0'+52;
   else if(c=='+')v=62;
   else if(c=='/')v=63;
   else continue;
   buf=(buf<<6)|v; bits+=6;
   if(bits>=8){bits-=8; out[o++]= (buf>>bits)&0xFF; buf&= (1<<bits)-1;}
 }
 *outlen=o; return out;
}
static void q_decode(const char *in, unsigned char *out, int *olen){
 int o=0;
 for(int i=0;in[i];i++){
   if(in[i]=='_'){out[o++]=0x20;}
   else if(in[i]=='=' && isxdigit(in[i+1]) && isxdigit(in[i+2])){int h=hexval(in[i+1]); int l=hexval(in[i+2]); out[o++]= (h<<4)|l; i+=2;}
   else out[o++]= (unsigned char)in[i];
 }
 *olen=o;
}
static char *decode_encoded_words(const char *s){
