     }
     /* decode run bytes using charset (simplified: assume utf-8) */
     /* for simplicity copy raw bytes as utf-8 */
     for(int k=0;k<run_bytes_len;k++) out[o++]=run_bytes[k];
     free(run_bytes); free(charset); free(et);
     i=cur;
     continue;
   }
   out[o++]=s[i++];
 }
 out[o]=0;
 return out;
}

/* quoted string escaping */
static char *escape_quoted(const unsigned char *s,int len){
 char *out=malloc(len*6+3); int o=0; out[o++]='"';
 for(int i=0;i<len;i++){
   unsigned char c=s[i];
   if(c=='\\'){out[o++]='\\';out[o++]='\\';}
   else if(c=='"'){out[o++]='\\';out[o++]='"';}
   else if(c=='\n'){out[o++]='\\';out[o++]='n';}
   else if(c=='\t'){out[o++]='\\';out[o++]='t';}
   else if(c<0x20 || (c>=0x7F && c<=0x9F)){
     char buf[7]; sprintf(buf,"\\u%04x",c); for(int k=0;buf[k];k++) out[o++]=buf[k];
   }else out[o++]=c;
 }
 out[o++]='"'; out[o]=0; return out;
}

