static void crc_init(){uint32_t poly=0xEDB88320; for(int i=0;i<256;i++){uint32_t c=i; for(int j=0;j<8;j++) c= c&1 ? poly^(c>>1) : c>>1; crc_table[i]=c;}}
static uint32_t crc32(const unsigned char *data,size_t len){uint32_t c=0xFFFFFFFF; for(size_t i=0;i<len;i++) c=crc_table[(c^data[i])&0xFF] ^ (c>>8); return c^0xFFFFFFFF;}

