typedef struct { char *name; char *value; } Param;
static Param *parse_params(const char *s,int *out_n){
 if(!s){*out_n=0;return NULL;}
 int cap=8; Param *p=malloc(cap*sizeof(Param)); int n=0;
 const char *q=s;
 while(*q){
   while(*q && isspace((unsigned char)*q)) q++;
   if(!*q) break;
   const char *ns=q;
   while(*q && *q!='=' && *q!=';' && !isspace((unsigned char)*q)) q++;
   int nlen=q-ns;
   char *name=malloc(nlen+1); memcpy(name,ns,nlen); name[nlen]=0;
   while(*q && isspace((unsigned char)*q)) q++;
   char *val=NULL;
   if(*q=='='){
     q++;
     while(*q && isspace((unsigned char)*q)) q++;
     if(*q=='"'){
       q++; const char *vs=q;
       while(*q && *q!='"'){ if(*q=='\\' && *(q+1)) q+=2; else q++; }
       int vlen=q-vs;
       val=malloc(vlen+1); memcpy(val,vs,vlen); val[vlen]=0;
       if(*q=='"') q++;
     }else{
       const char *vs=q;
       while(*q && *q!=';' && !isspace((unsigned char)*q)) q++;
       int vlen=q-vs;
       val=malloc(vlen+1); memcpy(val,vs,vlen); val[vlen]=0;
     }
   }
   if(n>=cap){cap*=2;p=realloc(p,cap*sizeof(Param));}
   p[n].name=name; p[n].value=val; n++;
   while(*q && *q!=';') q++;
   if(*q==';') q++;
 }
 *out_n=n; return p;
}

/* base64 */
static int b64val(char c){ if(c>='A'&&c<='Z')return c-'A'; if(c>='a'&&c<='z')return c-'a'+26; if(c>='0'&&c<='9')return c-'0'+52; if(c=='+')return 62; if(c=='/')return 63; return -1; }
static unsigned char *base64_decode(const char *in,int *outlen){
 int len=strlen(in); unsigned char *out=malloc(len*3/4+4); int o=0, buf=0, bits=0;
 for(int i=0;i<len;i++){
   int v=b64val(in[i]); if(v<0) continue;
   buf=(buf<<6)|v; bits+=6; if(bits>=8){bits-=8; out[o++]=(buf>>bits)&0xFF; buf&= (1<<bits)-1;}
   if(in[i]=='=') break;
 }
 *outlen=o; return out;
}

