public class Main {
    static class Entity {
        Map<String,String> headers = new LinkedHashMap<>();
        String type = "text";
        String subtype = "plain";
        Map<String,String> ctypeParams = new HashMap<>();
        Map<String,String> cdispoParams = new HashMap<>();
        String charset = "us-ascii";
        String cte = "7bit";
        String disposition = "-";
        String fileName = "-";
        List<Entity> parts = new ArrayList<>();
        boolean isMultipart = false;
        int bodyStart = -1;
        int bodyLimit = -1;
        byte[] rawBody;
    }

    static class MatchInfo {
        int start, end;
        String charset;
        String encoding;
        String text;
    }

    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        Path dir = Paths.get(args[0]);
        File[] files = dir.toFile().listFiles();
        if (files == null) files = new File[0];
        Arrays.sort(files, Comparator.comparing(File::getName));
        boolean firstFile = true;
        for (File f : files) {
            if (!f.isFile()) continue;
            byte[] data = Files.readAllBytes(f.toPath());
            boolean crlf = containsCRLF(data);
            Entity root = parseEntity(data, 0, data.length, crlf);
            printFile(f.getName(), root);
            if (!firstFile) System.out.println();
            firstFile = false;
        }
    }

    static boolean containsCRLF(byte[] data) {
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] == '\r' && data[i+1] == '\n') return true;
        }
        return false;
    }

    static Entity parseEntity(byte[] data, int start, int limit, boolean crlf) {
        Entity e = new Entity();
        int pos = start;
        String curName = null;
        StringBuilder curVal = new StringBuilder();
        int lineBreak = crlf ? 2 : 1;
        while (pos < limit) {
            int lineStart = pos;
            int lineEnd = findLineEnd(data, pos, limit, crlf);
            if (lineEnd < 0) lineEnd = limit;
            int len = lineEnd - lineStart;
            String line = new String(data, lineStart, len, StandardCharsets.ISO_8859_1);
            pos = lineEnd + (crlf ? 2 : 1);
            if (pos > limit) pos = limit;
            if (len == 0) {
                if (curName != null) {
                    e.headers.put(curName.toLowerCase(), curVal.toString().trim());
                    curName = null;
                }
                e.bodyStart = pos;
                e.bodyLimit = limit;
                break;
            }
            if (curName != null && (line.startsWith(" ") || line.startsWith("\t"))) {
                curVal.append(line);
            } else {
                if (curName != null) {
                    e.headers.put(curName.toLowerCase(), curVal.toString().trim());
                }
                int colon = line.indexOf(':');
                if (colon > 0) {
                    curName = line.substring(0, colon).trim().toLowerCase();
                    String v = line.substring(colon + 1);
                    v = v.replaceAll("^[ \\t]+|[ \\t]+$", "");
                    curVal = new StringBuilder(v);
                } else {
                    curName = null;
                    curVal = new StringBuilder();
                }
            }
        }
        if (curName != null) e.headers.put(curName.toLowerCase(), curVal.toString().trim());
        parseContentType(e);
        parseDisposition(e);
        parseCTE(e);
        if (e.isMultipart) {
            parseMultipart(data, e, crlf);
        }
        return e;
    }

    static int findLineEnd(byte[] data, int pos, int limit, boolean crlf) {
        for (int i = pos; i < limit; i++) {
            if (data[i] == '\n') {
                if (crlf && i > pos && data[i-1] == '\r') return i - 1;
                return i;
            }
            if (!crlf && data[i] == '\r') return i;
        }
        return -1;
    }

    static void parseContentType(Entity e) {
        String ct = e.headers.get("content-type");
        if (ct == null) {
            e.type = "text";
            e.subtype = "plain";
            e.charset = "us-ascii";
            return;
        }
        String s = ct.trim();
        int semi = s.indexOf(';');
        String main = semi >= 0 ? s.substring(0, semi) : s;
        main = main.trim();
        int slash = main.indexOf('/');
        if (slash > 0) {
            e.type = main.substring(0, slash).toLowerCase();
            e.subtype = main.substring(slash + 1).toLowerCase();
        }
        e.isMultipart = e.type.equals("multipart");
        if (semi >= 0) {
            parseParams(s.substring(semi + 1), e.ctypeParams);
        }
        if (e.type.equals("text")) {
            String cs = e.ctypeParams.get("charset");
            if (cs != null) e.charset = cs.toLowerCase();
        }
    }

    static void parseDisposition(Entity e) {
        String cd = e.headers.get("content-disposition");
        if (cd == null) return;
        String s = cd.trim();
        int slash = s.indexOf('/');
        if (slash > 0) {
            e.disposition = s.substring(0, slash).trim().toLowerCase();
        }
        int semi = s.indexOf(';');
        if (semi >= 0) parseParams(s.substring(semi + 1), e.cdispoParams);
    }

    static void parseCTE(Entity e) {
        String cte = e.headers.get("content-transfer-encoding");
        if (cte != null) e.cte = cte.toLowerCase();
    }

    static void parseParams(String s, Map<String,String> map) {
        String[] parts = s.split(";");
        for (String p : parts) {
            p = p.trim();
            if (p.isEmpty()) continue;
            int eq = p.indexOf('=');
            if (eq < 0) continue;
            String name = p.substring(0, eq).trim().toLowerCase();
            String val = p.substring(eq + 1).trim();
            if (val.startsWith("\"")) {
                val = unquote(val);
            }
            map.put(name, val);
        }
    }

    static String unquote(String v) {
        if (v.length() >= 2 && v.startsWith("\"") && v.endsWith("\"")) {
            v = v.substring(1, v.length() - 1);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < v.length(); i++) {
                char c = v.charAt(i);
                if (c == '\\' && i + 1 < v.length()) { sb.append(v.charAt(i + 1)); i++; }
                else sb.append(c);
            }
            return sb.toString();
        }
        return v;
    }

    static void parseMultipart(byte[] data, Entity e, boolean crlf) {
        String boundary = e.ctypeParams.get("boundary");
        if (boundary == null) return;
        int bodyStart = e.bodyStart;
        int limit = e.bodyLimit;
        int pos = bodyStart;
        int first = findDelimiter(data, pos, limit, boundary, crlf, false);
        if (first < 0) return;
        int after = first + lineLength(data, first, crlf) + (crlf ? 2 : 1);
        int curStart = after;
        while (true) {
            int next = findDelimiter(data, curStart, limit, boundary, crlf, false);
            if (next < 0) break;
            boolean closing = isClosing(data, next, boundary);
            Entity part = parseEntity(data, curStart, next, crlf);
            part.fileName = extractFileName(e, part);
            e.parts.add(part);
            if (closing) break;
            curStart = next + lineLength(data, next, crlf) + (crlf ? 2 : 1);
        }
    }

    static int lineLength(byte[] data, int start, boolean crlf) {
        int i = start;
        while (i < data.length && data[i] != '\n' && data[i] != '\r') i++;
        return i - start;
    }

    static int findDelimiter(byte[] data, int start, int limit, String boundary, boolean crlf, boolean closing) {
        String pref = "--" + boundary + (closing ? "--" : "");
        byte[] prefBytes = pref.getBytes(StandardCharsets.ISO_8859_1);
        for (int i = start; i <= limit - prefBytes.length; i++) {
            boolean match = true;
            for (int j = 0; j < prefBytes.length; j++) {
                if (data[i + j] != prefBytes[j]) { match = false; break; }
            }
            if (!match) continue;
            int lineStart = i;
            while (lineStart > start && data[lineStart - 1] != '\n' && data[lineStart - 1] != '\r') lineStart--;
            int lineEnd = i + prefBytes.length;
            while (lineEnd < limit && (data[lineEnd] == ' ' || data[lineEnd] == '\t')) lineEnd++;
            boolean ok = true;
            if (lineEnd < limit && data[lineEnd] != '\n' && data[lineEnd] != '\r') ok = false;
            if (ok) return lineStart;
        }
        return -1;
    }

    static boolean isClosing(byte[] data, int pos, String boundary) {
        String pref = "--" + boundary + "--";
        byte[] prefBytes = pref.getBytes(StandardCharsets.ISO_8859_1);
        for (int i = 0; i < prefBytes.length && pos + i < data.length; i++) {
            if (data[pos + i] != prefBytes[i]) return false;
        }
        return true;
    }

    static String extractFileName(Entity parent, Entity part) {
        String name = findFileName(parent, "content-disposition", "filename");
        if (name == null || name.equals("-")) name = findFileName(parent, "content-type", "name");
        if (name == null) return "-";
