                String txt = new String(dec, getCharset(e.charset));
                txt = txt.replace("\r\n", "\n").replace("\r", "\n");
                decodedText = txt;
                chars = txt.codePointCount(0, txt.length());
            } catch (Exception ex) {}
            System.out.println(pad + "text/" + e.subtype + " charset=" + e.charset + " cte=" + e.cte + " chars=" + chars);
            System.out.println(pad + "  " + quoteString(decodedText));
