    static byte[] decodeTransfer(byte[] data, String enc) {
        if (enc == null) return data;
        switch (enc) {
            case "base64":
                String s = new String(data, StandardCharsets.ISO_8859_1);
                StringBuilder f = new StringBuilder();
                for (char c : s.toCharArray()) {
                    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '=') f.append(c);
                }
                try { return Base64.getDecoder().decode(f.toString()); } catch (Exception ex) { return new byte[0]; }
            case "quoted-printable":
                return decodeQP(data);
            default:
                return data;
        }
    }

    static byte[] decodeQP(byte[] data) {
        String s = new String(data, StandardCharsets.ISO_8859_1);
        String[] lines = s.split("\r\n|\n|\r");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            int end = line.length();
            while (end > 0 && (line.charAt(end - 1) == ' ' || line.charAt(end - 1) == '\t')) end--;
            String stripped = line.substring(0, end);
            boolean soft = stripped.endsWith("=");
            if (soft) stripped = stripped.substring(0, stripped.length() - 1);
            out.append(decodeQPLine(stripped));
            if (!soft && i < lines.length - 1) out.append('\n');
        }
        return out.toString().getBytes(StandardCharsets.ISO_8859_1);
    }

    static String decodeQPLine(String line) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '=' && i + 2 < line.length()) {
                char h1 = line.charAt(i + 1);
                char h2 = line.charAt(i + 2);
                if (isHex(h1) && isHex(h2)) {
                    int v = Integer.parseInt("" + h1 + h2, 16);
                    sb.append((char) v);
                    i += 2;
                    continue;
                }
            }
            sb.append(c);
        }
        return sb.toString();
    }

    static boolean isHex(char c) { return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f'); }

    static String decodeEncodedWords(String s) {
        if (s == null) return "";
        Pattern p = Pattern.compile("=\\?([^\\?\\s]+)\\?(B|Q)\\?([^\\?\\s]*?)\\?=");
        Matcher m = p.matcher(s);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String charset = m.group(1);
            String enc = m.group(2);
            String txt = m.group(3);
            byte[] bytes;
            if (enc.equalsIgnoreCase("B")) {
                bytes = Base64.getDecoder().decode(txt);
            } else {
                bytes = decodeQ(txt);
            }
            String decoded;
            try { decoded = new String(bytes, charset); } catch (Exception e) { decoded = new String(bytes, StandardCharsets.ISO_8859_1); }
            m.appendReplacement(sb, Matcher.quoteReplacement(decoded));
        }
        m.appendTail(sb);
        return sb.toString();
    }

    static byte[] decodeQ(String txt) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (int i = 0; i < txt.length(); i++) {
            char c = txt.charAt(i);
            if (c == '_') baos.write(' ');
            else if (c == '=' && i + 2 < txt.length() && isHex(txt.charAt(i + 1)) && isHex(txt.charAt(i + 2))) {
                int v = Integer.parseInt("" + txt.charAt(i + 1) + txt.charAt(i + 2), 16);
                baos.write(v);
                i += 2;
            } else baos.write(c);
        }
        return baos.toByteArray();
    }

    static String quoteString(String s) {
        if (s == null) s = "";
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) sb.append(String.format("\\u%04x", cp));
            else sb.appendCodePoint(cp);
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }

    static java.nio.charset.Charset getCharset(String name) {
        try { return java.nio.charset.Charset.forName(name); } catch (Exception e) { return StandardCharsets.ISO_8859_1; }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Entity {
        Map<String,String> headers = new LinkedHashMap<>();
        String type = "text";
        String subtype = "plain";
        String charset = "us-ascii";
        String cte = "7bit";
        String disposition = "-";
        String filename = "-";
        boolean isMultipart = false;
        String boundary = null;
        List<Entity> parts = new ArrayList<>();
        int bodyStart = 0;
        int bodyEnd = 0;
    }

    public static void main(String[] args) throws Exception {
        if (args.length == 0) return;
        Path dir = Paths.get(args[0]);
        File[] files = dir.toFile().listFiles();
        if (files == null) files = new File[0];
        Arrays.sort(files, Comparator.comparing(File::getName));
        boolean first = true;
        for (File f : files) {
            if (!f.isFile()) continue;
            byte[] data = Files.readAllBytes(f.toPath());
            boolean crlf = containsCRLF(data);
            String s = new String(data, StandardCharsets.ISO_8859_1);
            Entity root = parseEntity(s, data, 0, s.length(), crlf);
            if (!first) System.out.println();
            first = false;
            System.out.println("== " + f.getName());
            String from = root.headers.get("from");
            String subj = root.headers.get("subject");
            System.out.println("From: " + (from == null ? "-" : quoteString(decodeEncodedWords(from))));
            System.out.println("Subject: " + (subj == null ? "-" : quoteString(decodeEncodedWords(subj))));
            printEntity(root, data, s, crlf, 0);
        }
    }

    static boolean containsCRLF(byte[] d) {
        for (int i = 0; i < d.length - 1; i++) if (d[i] == '\r' && d[i + 1] == '\n') return true;
        return false;
    }

    static Entity parseEntity(String s, byte[] data, int start, int limit, boolean crlf) {
        Entity e = new Entity();
        int pos = start;
        String curName = null;
        StringBuilder curVal = new StringBuilder();
        int bodyStart = start;
        while (pos < limit) {
            int lineEnd = s.indexOf('\n', pos);
            if (lineEnd < 0) lineEnd = limit;
            int contentEnd = lineEnd;
            if (crlf && contentEnd > pos && s.charAt(contentEnd - 1) == '\r') contentEnd--;
            String line = s.substring(pos, contentEnd);
            pos = lineEnd + 1;
            if (line.isEmpty()) {
                if (curName != null) {
                    e.headers.put(curName, curVal.toString().trim());
                    curName = null;
                }
                bodyStart = pos;
                break;
            }
            if (curName != null && (line.startsWith(" ") || line.startsWith("\t"))) {
                curVal.append(line);
            } else {
                if (curName != null) {
                    e.headers.put(curName, curVal.toString().trim());
                }
                int colon = line.indexOf(':');
                if (colon > 0) {
                    curName = line.substring(0, colon).trim().toLowerCase();
                    String v = line.substring(colon + 1);
                    v = v.replaceAll("^[ \\t]+|[ \\t]+$", "");
                    curVal = new StringBuilder(v);
                } else {
                    curName = null;
                    curVal = new StringBuilder();
                }
            }
        }
        if (curName != null) e.headers.put(curName, curVal.toString().trim());
        e.bodyStart = bodyStart;
        e.bodyEnd = limit;

        // content-type
        String ct = e.headers.get("content-type");
        if (ct != null) {
            String[] parts = ct.split(";", 2);
            String main = parts[0].trim();
            int slash = main.indexOf('/');
            if (slash > 0) {
                e.type = main.substring(0, slash).toLowerCase();
                e.subtype = main.substring(slash + 1).toLowerCase();
            }
            e.isMultipart = e.type.equals("multipart");
            if (e.isMultipart) {
                Map<String,String> params = parseParams(parts.length > 1 ? parts[1] : "");
                e.boundary = params.get("boundary");
            }
            if (e.type.equals("text")) {
                Map<String,String> params = parseParams(parts.length > 1 ? parts[1] : "");
                String cs = params.get("charset");
                if (cs != null) e.charset = cs.toLowerCase();
            }
        }
        // cte
        String cte = e.headers.get("content-transfer-encoding");
        if (cte != null) e.cte = cte.toLowerCase();
        // disposition
        String cd = e.headers.get("content-disposition");
        if (cd != null) {
            String[] p = cd.split(";", 2);
            String main = p[0].trim();
            int slash = main.indexOf('/');
            if (slash > 0) e.disposition = main.substring(0, slash).trim().toLowerCase();
            Map<String,String> params = parseParams(p.length > 1 ? p[1] : "");
            // filename extraction simplified
            String fn = params.get("filename");
            if (fn != null) e.filename = decodeEncodedWords(fn);
            else {
                // try content-type name
                if (ct != null) {
                    Map<String,String> ctParams = parseParams(ct.contains(";") ? ct.substring(ct.indexOf(';') + 1) : "");
                    String n = ctParams.get("name");
                    if (n != null) e.filename = decodeEncodedWords(n);
                }
            }
        }
        if (e.isMultipart && e.boundary != null) {
            parseMultipart(e, s, data, crlf);
        }
        return e;
    }

    static Map<String,String> parseParams(String s) {
        Map<String,String> m = new HashMap<>();
        if (s == null || s.isEmpty()) return m;
        String[] parts = s.split(";");
        for (String p : parts) {
            p = p.trim();
            if (p.isEmpty()) continue;
            int eq = p.indexOf('=');
            if (eq < 0) continue;
            String name = p.substring(0, eq).trim().toLowerCase();
            String val = p.substring(eq + 1).trim();
            if (val.startsWith("\"") && val.endsWith("\"")) {
                val = val.substring(1, val.length() - 1);
                val = unescape(val);
            }
            m.put(name, val);
        }
        return m;
    }

    static String unescape(String v) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < v.length(); i++) {
            char c = v.charAt(i);
            if (c == '\\' && i + 1 < v.length()) { sb.append(v.charAt(i + 1)); i++; }
            else sb.append(c);
        }
        return sb.toString();
    }

    static void parseMultipart(Entity e, String s, byte[] data, boolean crlf) {
        String boundary = e.boundary;
        if (boundary == null) return;
        String delim = "--" + boundary;
        int pos = e.bodyStart;
        int limit = e.bodyEnd;
        int lastStart = pos;
        while (pos < limit) {
            int lineStart = pos;
            int lineEnd = s.indexOf('\n', lineStart);
            if (lineEnd < 0) lineEnd = limit;
            int contentEnd = lineEnd;
            if (crlf && contentEnd > lineStart && s.charAt(contentEnd - 1) == '\r') contentEnd--;
            String line = s.substring(lineStart, contentEnd);
            int nextPos = lineEnd + 1;
            if (line.startsWith(delim)) {
                String rest = line.substring(delim.length());
                boolean closing = rest.startsWith("--");
                String after = closing ? rest.substring(2) : rest;
                if (isSpacesTabs(after)) {
                    if (lastStart < lineStart) {
                        Entity part = parseEntity(s, data, lastStart, lineStart, crlf);
                        e.parts.add(part);
                    }
                    if (closing) break;
                    lastStart = nextPos;
                    pos = nextPos;
                    continue;
                }
            }
            pos = nextPos;
        }
    }

    static boolean isSpacesTabs(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != ' ' && c != '\t') return false;
        }
        return true;
    }

    static void printEntity(Entity e, byte[] data, String s, boolean crlf, int indent) {
        String pad = "  ".repeat(indent);
        if (e.isMultipart) {
            System.out.println(pad + "multipart/" + e.subtype + " parts=" + e.parts.size());
            for (Entity p : e.parts) printEntity(p, data, s, crlf, indent + 1);
            return;
        }
        boolean isText = e.type.equals("text");
        boolean isAttachment = e.disposition.equals("attachment");
        if (isText && !isAttachment) {
            byte[] body = getBodyBytes(e, data, s);
            byte[] dec = decodeTransfer(body, e.cte);
            String txt = decodeCharset(dec, e.charset);
            txt = txt.replace("\r\n", "\n").replace("\r", "\n");
            int chars = txt.codePointCount(0, txt.length());
            System.out.println(pad + "text/" + e.subtype + " charset=" + e.charset + " cte=" + e.cte + " chars=" + chars);
            System.out.println(pad + "  " + quoteString(txt));
        } else {
            byte[] body = getBodyBytes(e, data, s);
            byte[] dec = decodeTransfer(body, e.cte);
            CRC32 crc = new CRC32();
            crc.update(dec);
            String crcHex = String.format("%08x", crc.getValue());
            String name = e.filename == null ? "-" : e.filename;
            System.out.println(pad + e.type + "/" + e.subtype + " cte=" + e.cte + " disposition=" + (e.disposition.isEmpty() ? "-" : e.disposition) + " name=" + quoteString(name) + " size=" + dec.length + " crc32=" + crcHex);
        }
    }

    static byte[] getBodyBytes(Entity e, byte[] data, String s) {
        int start = e.bodyStart;
        int end = e.bodyEnd;
        if (start >= end) return new byte[0];
        return Arrays.copyOfRange(data, start, Math.min(end, data.length));
    }

    static byte[] decodeTransfer(byte[] data, String enc) {
        if (enc == null) return data;
        switch (enc) {
            case "base64":
                String str = new String(data, StandardCharsets.ISO_8859_1);
                StringBuilder sb = new StringBuilder();
                for (char c : str.toCharArray()) {
                    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '=') sb.append(c);
                }
                try { return Base64.getDecoder().decode(sb.toString()); } catch (Exception ex) { return new byte[0]; }
            case "quoted-printable":
                return decodeQP(data);
            default:
                return data;
        }
    }

    static byte[] decodeQP(byte[] data) {
        String s = new String(data, StandardCharsets.ISO_8859_1);
        String[] lines = s.split("\r\n|\n|\r");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            int end = line.length();
            while (end > 0 && (line.charAt(end - 1) == ' ' || line.charAt(end - 1) == '\t')) end--;
            String stripped = line.substring(0, end);
            boolean soft = stripped.endsWith("=");
            if (soft) stripped = stripped.substring(0, stripped.length() - 1);
            out.append(decodeQPLine(stripped));
            if (!soft && i < lines.length - 1) out.append('\n');
        }
        return out.toString().getBytes(StandardCharsets.ISO_8859_1);
    }

    static String decodeQPLine(String line) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '=' && i + 2 < line.length() && isHex(line.charAt(i + 1)) && isHex(line.charAt(i + 2))) {
                int v = Integer.parseInt("" + line.charAt(i + 1) + line.charAt(i + 2), 16);
                sb.append((char) v);
                i += 2;
            } else sb.append(c);
        }
        return sb.toString();
    }

    static boolean isHex(char c) { return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f'); }

    static String decodeCharset(byte[] data, String charset) {
        if (charset == null) charset = "us-ascii";
        charset = charset.toLowerCase();
        if (charset.equals("us-ascii") || charset.equals("ascii")) {
            byte[] out = new byte[data.length];
            for (int i = 0; i < data.length; i++) out[i] = (byte)(data[i] & 0x7F);
            return new String(out, StandardCharsets.ISO_8859_1);
        }
        if (charset.equals("utf-8")) {
            return new String(data, StandardCharsets.UTF_8);
        }
        if (charset.equals("iso-8859-1")) {
            return new String(data, StandardCharsets.ISO_8859_1);
        }
        if (charset.equals("windows-1252")) {
            StringBuilder sb = new StringBuilder();
            for (byte b : data) {
                int v = b & 0xFF;
                if (v < 0x80) sb.append((char)v);
                else if (v >= 0x80 && v <= 0x9F) {
                    sb.append(mapWin1252(v));
                } else sb.append((char)v);
            }
            return sb.toString();
        }
        try { return new String(data, java.nio.charset.Charset.forName(charset)); } catch (Exception e) { return new String(data, StandardCharsets.ISO_8859_1); }
    }

    static char mapWin1252(int b) {
        switch (b) {
            case 0x80: return '\u20AC'; case 0x81: return '\u0081'; case 0x82: return '\u201A'; case 0x83: return '\u0192'; case 0x84: return '\u201E'; case 0x85: return '\u2026'; case 0x86: return '\u2020'; case 0x87: return '\u2021'; case 0x88: return '\u02C6'; case 0x89: return '\u2030'; case 0x8A: return '\u0160'; case 0x8B: return '\u2039'; case 0x8C: return '\u0152'; case 0x8D: return '\u008D'; case 0x8E: return '\u017D'; case 0x8F: return '\u008F';
            case 0x90: return '\u0090'; case 0x91: return '\u2018'; case 0x92: return '\u2019'; case 0x93: return '\u201C'; case 0x94: return '\u201D'; case 0x95: return '\u2022'; case 0x96: return '\u2013'; case 0x97: return '\u2014'; case 0x98: return '\u02DC'; case 0x99: return '\u2122'; case 0x9A: return '\u0161'; case 0x9B: return '\u203A'; case 0x9C: return '\u0153'; case 0x9D: return '\u009D'; case 0x9E: return '\u017E'; case 0x9F: return '\u0178';
        }
        return (char)b;
    }

    static String decodeEncodedWords(String s) {
        if (s == null) return "";
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            int start = s.indexOf("=?", i);
            if (start < 0) { out.append(s.substring(i)); break; }
            out.append(s.substring(i, start));
            int q1 = s.indexOf('?', start + 2);
            if (q1 < 0) { i = start + 2; continue; }
            int q2 = s.indexOf('?', q1 + 1);
            if (q2 < 0) { i = start + 2; continue; }
            String charset = s.substring(start + 2, q1);
            String enc = s.substring(q1 + 1, q2);
            int end = s.indexOf("?=", q2 + 1);
            if (end < 0) { i = start + 2; continue; }
            String txt = s.substring(q2 + 1, end);
            // strip *language
            int star = charset.indexOf('*');
            if (star > 0) charset = charset.substring(0, star);
            byte[] bytes;
            if (enc.equalsIgnoreCase("B")) {
                try { bytes = Base64.getDecoder().decode(txt); } catch (Exception e) { bytes = new byte[0]; }
            } else {
                bytes = decodeQ(txt);
            }
            try {
                String decoded = new String(bytes, charset);
                out.append(decoded);
            } catch (Exception e) {
                out.append(new String(bytes, StandardCharsets.ISO_8859_1));
            }
            i = end + 2;
        }
        return out.toString();
    }

    static byte[] decodeQ(String txt) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (int i = 0; i < txt.length(); i++) {
            char c = txt.charAt(i);
            if (c == '_') baos.write(' ');
            else if (c == '=' && i + 2 < txt.length() && isHex(txt.charAt(i + 1)) && isHex(txt.charAt(i + 2))) {
                int v = Integer.parseInt("" + txt.charAt(i + 1) + txt.charAt(i + 2), 16);
                baos.write(v);
                i += 2;
            } else baos.write(c);
        }
        return baos.toByteArray();
    }

    static String quoteString(String s) {
        if (s == null) s = "";
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) sb.append(String.format("\\u%04x", cp));
            else sb.appendCodePoint(cp);
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }
}

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>
#include <inttypes.h>

#define BASE 1000000000U
#define BASE_DIGS 9
#define MAXD 128

typedef struct {
    int sign;               /* 0 = zero, 1 = +, -1 = - */
    int len;
    uint32_t d[MAXD];
} BigInt;

static void bi_zero(BigInt *a){ a->sign=0; a->len=0; }
static void bi_normalize(BigInt *a){
    while(a->len>0 && a->d[a->len-1]==0) a->len--;
    if(a->len==0) a->sign=0;
}
static int bi_is_zero(const BigInt *a){ return a->sign==0; }

static void bi_copy(BigInt *dst,const BigInt *src){
    dst->sign=src->sign; dst->len=src->len;
    memcpy(dst->d,src->d,sizeof(uint32_t)*src->len);
}
static int bi_cmp_abs(const BigInt *a,const BigInt *b){
    if(a->len!=b->len) return a->len>b->len?1:-1;
    for(int i=a->len-1;i>=0;i--) if(a->d[i]!=b->d[i]) return a->d[i]>b->d[i]?1:-1;
    return 0;
}
static int bi_cmp(const BigInt *a,const BigInt *b){
    if(a->sign!=b->sign) return a->sign>b->sign?1:-1;
    if(a->sign==0 && b->sign==0) return 0;
    int c=bi_cmp_abs(a,b);
    return a->sign>0?c:-c;
}
static void bi_neg(BigInt *a){ if(a->sign!=0) a->sign=-a->sign; }

static void bi_add_abs(BigInt *r,const BigInt *a,const BigInt *b){
    int n=a->len>b->len?a->len:b->len;
    if(r->len<n) r->len=n;
    uint64_t carry=0;
    for(int i=0;i<n;i++){
        uint64_t av=i<a->len?a->d[i]:0;
        uint64_t bv=i<b->len?b->d[i]:0;
        uint64_t s=av+bv+carry;
        r->d[i]=(uint32_t)(s%BASE);
        carry=s/BASE;
    }
    int i=n;
    while(carry){
        if(i>=MAXD) break;
        uint64_t s=r->d[i]+carry;
        r->d[i]=(uint32_t)(s%BASE);
        carry=s/BASE;
        i++;
    }
    r->len=n;
    while(i<r->len && r->d[i]==0) r->len--;
    bi_normalize(r);
}
static void bi_sub_abs(BigInt *r,const BigInt *a,const BigInt *b){ /* |a|>=|b| */
    int n=a->len;
    r->len=n;
    int64_t borrow=0;
    for(int i=0;i<n;i++){
        int64_t av=a->d[i];
        int64_t bv=i<b->len?b->d[i]:0;
        int64_t cur=av-borrow-bv;
        if(cur<0){ cur+=BASE; borrow=1; } else borrow=0;
        r->d[i]=(uint32_t)cur;
    }
    bi_normalize(r);
}
static void bi_add_signed(BigInt *r,const BigInt *a,const BigInt *b){
    if(a->sign==0){ bi_copy(r,b); return; }
    if(b->sign==0){ bi_copy(r,a); return; }
    if(a->sign==b->sign){
        r->sign=a->sign;
        bi_add_abs(r,a,b);
        return;
    }
    int cmp=bi_cmp_abs(a,b);
    if(cmp==0){ bi_zero(r); return; }
    if(cmp>0){
        r->sign=a->sign;
        bi_sub_abs(r,a,b);
    }else{
        r->sign=b->sign;
        bi_sub_abs(r,b,a);
    }
}
static void bi_sub_signed(BigInt *r,const BigInt *a,const BigInt *b){
    BigInt nb=*b; bi_neg(&nb);
    bi_add_signed(r,a,&nb);
}

/* multiply by uint64 */
static void bi_mul_u64(BigInt *a,uint64_t m){
    if(m==0 || bi_is_zero(a)){ bi_zero(a); return; }
    __uint128_t carry=0;
    for(int i=0;i<a->len;i++){
        __uint128_t cur=( __uint128_t)a->d[i]*m+carry;
        a->d[i]=(uint32_t)(cur%BASE);
        carry=cur/BASE;
    }
    while(carry){
        if(a->len>=MAXD) break;
        a->d[a->len++]=(uint32_t)(carry%BASE);
        carry/=BASE;
    }
}

/* divide by uint64, returns remainder */
static uint64_t bi_div_u64(BigInt *a,uint64_t d){
    if(d==0) return 0;
    __uint128_t rem=0;
    for(int i=a->len-1;i>=0;i--){
        __uint128_t cur=rem*BASE + a->d[i];
        a->d[i]=(uint32_t)(cur/d);
        rem=cur%d;
    }
    bi_normalize(a);
    return (uint64_t)rem;
}

/* from decimal string */
static void bi_from_str(BigInt *a,const char *s){
    bi_zero(a);
    int i=0, sign=1;
    while(isspace((unsigned char)s[i])) i++;
    if(s[i]=='+'||s[i]=='-'){ if(s[i]=='-') sign=-1; i++; }
    BigInt tmp; bi_zero(&tmp);
    for(; s[i]; i++){
        if(!isdigit((unsigned char)s[i])) continue;
        bi_mul_u64(&tmp,10);
        BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=s[i]-'0';
        BigInt res; bi_add_signed(&res,&tmp,&one);
        bi_copy(&tmp,&res);
    }
    a->sign=sign;
    a->len=tmp.len;
    memcpy(a->d,tmp.d,sizeof(uint32_t)*tmp.len);
    if(a->sign!=0 && bi_is_zero(a)) a->sign=1;
}

/* to decimal string, buffer must be large enough */
static void bi_to_str(const BigInt *a,char *out){
    if(bi_is_zero(a)){ strcpy(out,"0"); return; }
    BigInt tmp=*a;
    char buf[512]; int pos=0;
    if(tmp.sign<0){ *out++='-'; }
    /* copy */
    BigInt c=tmp;
    if(c.sign<0) c.sign=1;
    char rev[512]; int rpos=0;
    if(bi_is_zero(&c)){ rev[rpos++]='0'; }
    else{
        BigInt t=c;
        char digits[512];
        int dpos=0;
        while(!bi_is_zero(&t)){
            uint64_t rem=bi_div_u64(&t,10);
            digits[dpos++]='0'+rem;
        }
        for(int i=dpos-1;i>=0;i--) rev[rpos++]=digits[i];
    }
    rev[rpos]='\0';
    if(tmp.sign<0) *out++='-';
    strcpy(out,rev);
}

/* multiply two big ints (naive) */
static void bi_mul_big(BigInt *r,const BigInt *a,const BigInt *b){
    bi_zero(r);
    if(bi_is_zero(a)||bi_is_zero(b)){ bi_zero(r); return; }
    uint64_t tmp[MAXD*2]={0};
    for(int i=0;i<a->len;i++){
        __uint128_t carry=0;
        for(int j=0;j<b->len;j++){
            __uint128_t cur=tmp[i+j]+(__uint128_t)a->d[i]*b->d[j]+carry;
            tmp[i+j]=(uint64_t)(cur%BASE);
            carry=cur/BASE;
        }
        int k=i+b->len;
        while(carry){ tmp[k]+=(uint64_t)carry; carry/=BASE; k++; }
    }
    int len=0;
    while(len<(int)(sizeof(tmp)/sizeof(tmp[0])) && tmp[len]==0) len++;
    /* find actual length */
    int last=0;
    for(int i=0;i<(int)(sizeof(tmp)/sizeof(tmp[0]));i++) if(tmp[i]) last=i+1;
    r->len=last;
    r->sign=a->sign*b->sign;
    for(int i=0;i<last;i++) r->d[i]=(uint32_t)tmp[i];
    bi_normalize(r);
}

/* round division of |N| by D with half even */
static void bi_round_div(BigInt *res,const BigInt *num,uint64_t d){
    if(bi_is_zero(num)){ bi_zero(res); return; }
    BigInt a=*num;
    if(a.sign<0) a.sign=1;
    uint64_t rem=bi_div_u64(&a,d);
    /* a is quotient */
    /* check remainder */
    __uint128_t twice= (__uint128_t)rem*2;
    int need_up=0;
    if(twice > d) need_up=1;
    else if(twice == d){
        /* even rule */
        /* check if quotient is even */
        int even=1;
        if(a.len>0 && (a.d[0]&1)) even=0;
        /* actually parity of whole number, not just low digit? low digit parity determines evenness in base 1e9? 1e9 is even, so parity depends on low digit */
        if(even) need_up=0; else need_up=1;
    }
    if(need_up){
        BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=1;
        bi_add_signed(&a,&a,&one);
    }
    res->sign=num->sign;
    bi_copy(res,&a);
}

/* ---------- parsing helpers ---------- */
typedef struct { char code[8]; int minor; } Currency;
typedef struct {
    char name[256];
    char code[8];
    BigInt bal;
    BigInt limit;
} Account;

static int find_currency(Currency *cs,int n,const char *code){
    for(int i=0;i<n;i++) if(strcmp(cs[i].code,code)==0) return i;
    return -1;
}
static int find_account(Account *as,int n,const char *name){
    for(int i=0;i<n;i++) if(strcmp(as[i].name,name)==0) return i;
    return -1;
}

/* amount rounding to minor units */
static int amount_round_to_minor(const char *s,int minor,BigInt *out){
    /* parse sign */
    const char *p=s;
    int sign=1;
    while(isspace(*p)) p++;
    if(*p=='-'||*p=='+'){ if(*p=='-') sign=-1; p++; }
    /* split */
    char intpart[256]={0}, fracpart[256]={0};
    int i=0,j=0;
    while(*p && *p!='.' && *p!=' ' && *p!='\t'){ intpart[i++]=*p++; }
    if(*p=='.'){ p++; i=0; while(*p && isdigit(*p) && i<255){ fracpart[i++]=*p++; } }
    int f_len=strlen(fracpart);
    /* build numerator */
    BigInt num; bi_zero(&num);
    if(intpart[0]) bi_from_str(&num,intpart);
    else { num.sign=1; num.len=1; num.d[0]=0; }
    /* append fractional digits */
    for(int k=0;k<f_len;k++){
        bi_mul_u64(&num,10);
        BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=fracpart[k]-'0';
        BigInt tmp; bi_add_signed(&tmp,&num,&one);
        bi_copy(&num,&tmp);
    }
    /* now num is value *10^{f_len} */
    if(f_len<=minor){
        int shift=minor-f_len;
        for(int k=0;k<shift;k++) bi_mul_u64(&num,10);
        /* sign */
        if(sign==-1) bi_neg(&num);
        bi_copy(out,&num);
        return 1;
    }else{
        int k=f_len-minor;
        /* need divide num by 10^k with rounding */
        uint64_t pow10=1;
        for(int t=0;t<k;t++) pow10*=10;
        BigInt tmp=num;
        bi_round_div(&tmp,&tmp,pow10);
        if(sign==-1) bi_neg(&tmp);
        bi_copy(out,&tmp);
        return 1;
    }
}

/* rate parsing to numerator/denominator */
static void parse_rate(const char *s,BigInt *num,int *exp){
    const char *p=s;
    int sign=1;
    while(isspace(*p)) p++;
    if(*p=='-'||*p=='+'){ if(*p=='-') sign=-1; p++; }
    char intpart[256]={0}, fracpart[256]={0};
    int i=0,j=0;
    while(*p && *p!='.' && *p!=' '){ intpart[i++]=*p++; }
    if(*p=='.'){ p++; i=0; while(*p && isdigit(*p) && i<255){ fracpart[i++]=*p++; } }
    int f_len=strlen(fracpart);
    BigInt n; bi_zero(&n);
    if(intpart[0]) bi_from_str(&n,intpart);
    else { n.sign=1; n.len=1; n.d[0]=0; }
    for(int k=0;k<f_len;k++){
        bi_mul_u64(&n,10);
        BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=fracpart[k]-'0';
        BigInt tmp; bi_add_signed(&tmp,&n,&one);
        bi_copy(&n,&tmp);
    }
    if(sign==-1) bi_neg(&n);
    *exp=f_len;
    bi_copy(num,&n);
}

/* format balance */
static void format_balance(char *out,const BigInt *bal,int minor){
    if(bi_is_zero(bal)){ sprintf(out,"0"); if(minor>0) sprintf(out,"0.%0*d",minor,0); return; }
    BigInt a=*bal;
    int neg=a.sign<0;
    if(neg) a.sign=1;
    /* convert to decimal string */
    char dec[1024];
    bi_to_str(&a,dec);
    int len=strlen(dec);
    if(minor==0){
        /* insert commas */
        char tmp[2048]; int t=0;
        if(neg) tmp[t++]='-';
        int cnt=0;
        for(int i=len-1;i>=0;i--){ tmp[t++]=dec[i]; cnt++; if(cnt%3==0 && i>0) tmp[t++]=','; cnt=0; }
        /* reverse */
        int start=neg?1:0;
        int end=t-1;
        char rev[2048]; int r=0;
        if(neg) rev[r++]='-';
        for(int i=end;i>=start;i--) rev[r++]=tmp[i];
        rev[r]='\0';
        strcpy(out,rev);
        return;
    }else{
        /* need fractional */
        /* pad */
        if(len<minor){
            char padded[1024];
            int pad=minor-len;
            memset(padded,'0',pad);
            memcpy(padded+pad,dec,len);
            padded[minor]='\0';
            /* integer part is 0 */
            char intpart[1024]="0";
            char fracpart[1024];
            strcpy(fracpart,padded);
            /* format */
            if(neg){
                char buf[2048]; sprintf(buf,"-0.%s",fracpart);
                strcpy(out,buf);
            }else{
                char buf[2048]; sprintf(buf,"0.%s",fracpart);
                strcpy(out,buf);
            }
            return;
        }else{
            int intlen=len-minor;
            char intpart[1024]; strncpy(intpart,dec,intlen); intpart[intlen]='\0';
            char fracpart[1024]; strncpy(fracpart,dec+intlen,minor); fracpart[minor]='\0';
            /* commas in intpart */
            char intcomm[2048]; int t=0;
            int cnt=0;
            for(int i=intlen-1;i>=0;i--){ intcomm[t++]=intpart[i]; cnt++; if(cnt%3==0 && i>0) intcomm[t++]=','; cnt=0; }
            intcomm[t]='\0';
            /* reverse */
            char intrev[2048]; int r=0;
            for(int i=t-1;i>=0;i--) intrev[r++]=intcomm[i];
            intrev[r]='\0';
            if(neg){
                char buf[4096]; sprintf(buf,"-%s.%s",intrev,fracpart);
                strcpy(out,buf);
            }else{
                char buf[4096]; sprintf(buf,"%s.%s",intrev,fracpart);
                strcpy(out,buf);
            }
            return;
        }
    }
}

/* ---------- main ---------- */
int main(int argc,char *argv[]){
    if(argc<2){ fprintf(stderr,"usage\n"); return 1; }
    FILE *f=fopen(argv[1],"r");
    if(!f){ perror("open"); return 1; }
    char *line=NULL; size_t sz=0;
    ssize_t len;
    int lineno=0;
    Currency curs[1024]; int nc=0;
    Account accs[4096]; int na=0;
    struct {int line; char reason[256];} rej[4096]; int nr=0;

    while((len=getline(&line,&sz,f))!=-1){
        lineno++;
        char *p=line;
        while(*p && isspace(*p)) p++;
        if(*p=='\0' || *p=='\n') continue;
        if(*p=='#') continue;
        /* tokenize */
        char *copy=strdup(line);
        char *tok=strtok(copy," \t\r\n");
        if(!tok){ free(copy); continue; }
        if(strcmp(tok,"currency")==0){
            char *code=strtok(NULL," \t\r\n");
            char *min=strtok(NULL," \t\r\n");
            if(code && min){
                strcpy(curs[nc].code,code);
                curs[nc].minor=atoi(min);
                nc++;
            }
        }else if(strcmp(tok,"open")==0){
            char *name=strtok(NULL," \t\r\n");
            char *code=strtok(NULL," \t\r\n");
            char *lim=strtok(NULL," \t\r\n");
            if(name && code){
                int idx=find_account(accs,na,name);
                if(idx!=-1){
                    char buf[256]; sprintf(buf,"line %d: REJECT account exists %s\n",lineno,name);
                    rej[nr].line=lineno; strcpy(rej[nr].reason,"account exists"); nr++;
                    free(copy); continue;
                }
                int cidx=find_currency(curs,nc,code);
                int minor = cidx!=-1?curs[cidx].minor:0;
                BigInt bal; bi_zero(&bal);
                BigInt limv; bi_zero(&limv);
                if(lim){
                    BigInt tmp; amount_round_to_minor(lim,minor,&tmp);
                    bi_copy(&limv,&tmp);
                }
                strcpy(accs[na].name,name);
                strcpy(accs[na].code,code);
                bi_copy(&accs[na].bal,&bal);
                bi_copy(&accs[na].limit,&limv);
                na++;
            }
        }else if(strcmp(tok,"deposit")==0){
            char *name=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!name||!amt){ free(copy); continue; }
            int idx=find_account(accs,na,name);
            if(idx==-1){ char buf[256]; sprintf(buf,"line %d: REJECT unknown account %s\n",lineno,name); rej[nr].line=lineno; strcpy(rej[nr].reason,"unknown account"); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[idx].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt nb; bi_add_signed(&nb,&accs[idx].bal,&amt_r);
            bi_copy(&accs[idx].bal,&nb);
        }else if(strcmp(tok,"withdraw")==0){
            char *name=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!name||!amt){ free(copy); continue; }
            int idx=find_account(accs,na,name);
            if(idx==-1){ rej[nr].line=lineno; strcpy(rej[nr].reason,"unknown account"); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[idx].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt newbal; bi_sub_signed(&newbal,&accs[idx].bal,&amt_r);
            /* check limit */
            BigInt neg; bi_neg(&newbal); /* -newbal */
            /* limit is max negative allowed */
            BigInt allowed; bi_neg(&accs[idx].limit); /* -limit */
            /* we need newbal >= -limit */
            BigInt diff; bi_sub_signed(&diff,&newbal,&accs[idx].limit); /* newbal - (-limit)? Wait */
            /* Simpler: check if newbal < -limit */
            BigInt minus_limit; bi_neg(&accs[idx].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){
                rej[nr].line=lineno; strcpy(rej[nr].reason,"insufficient funds"); nr++; free(copy); continue;
            }
            bi_copy(&accs[idx].bal,&newbal);
        }else if(strcmp(tok,"transfer")==0){
            char *from=strtok(NULL," \t\r\n");
            char *to=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!from||!to||!amt){ free(copy); continue; }
            int ifrom=find_account(accs,na,from);
            int ito=find_account(accs,na,to);
            if(ifrom==-1){ rej[nr].line=lineno; strcpy(rej[nr].reason,"unknown account"); nr++; free(copy); continue; }
            if(ito==-1){ rej[nr].line=lineno; strcpy(rej[nr].reason,"unknown account"); nr++; free(copy); continue; }
            if(strcmp(accs[ifrom].code,accs[ito].code)!=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"currency mismatch"); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[ifrom].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt newbal; bi_sub_signed(&newbal,&accs[ifrom].bal,&amt_r);
            BigInt minus_limit; bi_neg(&accs[ifrom].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"insufficient funds"); nr++; free(copy); continue; }
            bi_copy(&accs[ifrom].bal,&newbal);
            BigInt nb2; bi_add_signed(&nb2,&accs[ito].bal,&amt_r);
            bi_copy(&accs[ito].bal,&nb2);
        }else if(strcmp(tok,"convert")==0){
            char *from=strtok(NULL," \t\r\n");
            char *to=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            char *rate=strtok(NULL," \t\r\n");
            if(!from||!to||!amt||!rate){ free(copy); continue; }
            int ifrom=find_account(accs,na,from);
            int ito=find_account(accs,na,to);
            if(ifrom==-1){ rej[nr].line=lineno; strcpy(rej[nr].reason,"unknown account"); nr++; free(copy); continue; }
            if(ito==-1){ rej[nr].line=lineno; strcpy(rej[nr].reason,"unknown account"); nr++; free(copy); continue; }
            int cfrom=find_currency(curs,nc,accs[ifrom].code);
            int cto=find_currency(curs,nc,accs[ito].code);
            int minor_from=curs[cfrom].minor;
            int minor_to=curs[cto].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor_from,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt newbal; bi_sub_signed(&newbal,&accs[ifrom].bal,&amt_r);
            BigInt minus_limit; bi_neg(&accs[ifrom].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"insufficient funds"); nr++; free(copy); continue; }
            /* compute conversion */
            BigInt rate_num; int rate_exp;
            parse_rate(rate,&rate_num,&rate_exp);
            BigInt prod; bi_mul_big(&prod,&amt_r,&rate_num);
            /* divide by 10^exp */
            uint64_t pow10=1;
            for(int t=0;t<rate_exp && t<19;t++) pow10*=10;
            BigInt prod_div; bi_round_div(&prod_div,&prod,pow10);
            /* round to target minor */
            /* prod_div is in units of from minor * rate, need to round to target minor */
            /* For simplicity assume rate conversion already yields correct scale */
            /* Now round to target minor units */
            /* We need to convert prod_div to target minor units: prod_div is in from minor units * rate.
