#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>
#include <inttypes.h>
#include <limits.h>

#define BASE 1000000000U
#define BASE_DIGS 9
#define MAXD 256

typedef struct {
    int sign;               /* 0 zero, 1 +, -1 - */
    int len;
    uint32_t d[MAXD];
} BigInt;

static void bi_zero(BigInt *a){ a->sign=0; a->len=0; }
static void bi_normalize(BigInt *a){
    while(a->len>0 && a->d[a->len-1]==0) a->len--;
    if(a->len==0) a->sign=0;
}
static void bi_copy(BigInt *dst,const BigInt *src){
    dst->sign=src->sign; dst->len=src->len;
    if(src->len) memcpy(dst->d,src->d,sizeof(uint32_t)*src->len);
}
static int bi_is_zero(const BigInt *a){ return a->len==0; }
static int bi_cmp_abs(const BigInt *a,const BigInt *b){
    if(a->len!=b->len) return a->len>b->len?1:-1;
    for(int i=a->len-1;i>=0;i--) if(a->d[i]!=b->d[i]) return a->d[i]>b->d[i]?1:-1;
    return 0;
}
static int bi_cmp(const BigInt *a,const BigInt *b){
    if(a->sign==0 && b->sign==0) return 0;
    if(a->sign==0) return b->sign>0? -1:1;
    if(b->sign==0) return a->sign>0? 1:-1;
    if(a->sign!=b->sign) return a->sign>b->sign?1:-1;
    int c=bi_cmp_abs(a,b);
    return a->sign>0?c:-c;
}
static void bi_neg(BigInt *a){ if(a->sign!=0) a->sign=-a->sign; }

static void bi_add_abs(BigInt *r,const BigInt *a,const BigInt *b){
    int n = a->len > b->len ? a->len : b->len;
    if(r->len < n) r->len = n;
    uint64_t carry=0;
    for(int i=0;i<n;i++){
        uint64_t av = i<a->len? a->d[i]:0;
        uint64_t bv = i<b->len? b->d[i]:0;
        uint64_t s = av + bv + carry;
        r->d[i] = (uint32_t)(s % BASE);
        carry = s / BASE;
    }
    int i=n;
    while(carry && i < MAXD){
        uint64_t s = (i<r->len? r->d[i]:0) + carry;
        r->d[i] = (uint32_t)(s % BASE);
        carry = s / BASE;
        i++;
    }
    r->len = i;
    bi_normalize(r);
}
static void bi_sub_abs(BigInt *r,const BigInt *a,const BigInt *b){ /* |a|>=|b| */
    r->len = a->len;
    int64_t borrow=0;
    for(int i=0;i<a->len;i++){
        int64_t av = a->d[i];
        int64_t bv = i<b->len? b->d[i]:0;
        int64_t cur = av - borrow - bv;
        if(cur < 0){ cur += BASE; borrow = 1; } else borrow = 0;
        r->d[i] = (uint32_t)cur;
    }
    bi_normalize(r);
}
static void bi_add_signed(BigInt *r,const BigInt *a,const BigInt *b){
    if(a->sign==0){ bi_copy(r,b); return; }
    if(b->sign==0){ bi_copy(r,a); return; }
    if(a->sign==b->sign){
        r->sign = a->sign;
        bi_add_abs(r,a,b);
        return;
    }
    int cmp = bi_cmp_abs(a,b);
    if(cmp==0){ bi_zero(r); return; }
    if(cmp>0){
        r->sign = a->sign;
        bi_sub_abs(r,a,b);
    }else{
        r->sign = b->sign;
        bi_sub_abs(r,b,a);
    }
}
static void bi_sub_signed(BigInt *r,const BigInt *a,const BigInt *b){
    BigInt nb = *b; bi_neg(&nb);
    bi_add_signed(r,a,&nb);
}

static void bi_mul_u64(BigInt *a,uint64_t m){
    if(m==0 || bi_is_zero(a)){ bi_zero(a); return; }
    __uint128_t carry=0;
    for(int i=0;i<a->len;i++){
        __uint128_t cur = (__uint128_t)a->d[i]*m + carry;
        a->d[i] = (uint32_t)(cur % BASE);
        carry = cur / BASE;
    }
    while(carry){
        if(a->len >= MAXD) break;
        a->d[a->len++] = (uint32_t)(carry % BASE);
        carry /= BASE;
    }
    bi_normalize(a);
}
static uint64_t bi_div_u64(BigInt *a,uint64_t d){
    if(d==0 || bi_is_zero(a)) return 0;
    __uint128_t rem=0;
    for(int i=a->len-1;i>=0;i--){
        __uint128_t cur = rem*BASE + a->d[i];
        a->d[i] = (uint32_t)(cur / d);
        rem = cur % d;
    }
    bi_normalize(a);
    return (uint64_t)rem;
}
static void bi_mul_big(BigInt *r,const BigInt *a,const BigInt *b){
    bi_zero(r);
    if(bi_is_zero(a)||bi_is_zero(b)){ bi_zero(r); return; }
    static uint64_t tmp[2*MAXD];
    memset(tmp,0,sizeof(tmp));
    for(int i=0;i<a->len;i++){
        __uint128_t carry=0;
        for(int j=0;j<b->len;j++){
            __uint128_t cur = tmp[i+j] + (__uint128_t)a->d[i]*b->d[j] + carry;
            tmp[i+j] = (uint64_t)(cur % BASE);
            carry = cur / BASE;
        }
        int k=i+b->len;
        while(carry){
            __uint128_t cur = tmp[k] + carry;
            tmp[k] = (uint64_t)(cur % BASE);
            carry = cur / BASE;
            k++;
        }
    }
    int len=0;
    while(len<2*MAXD && tmp[len]==0) len++;
    int last=len;
    while(last>0 && tmp[last-1]==0) last--;
    r->len = last;
    r->sign = a->sign * b->sign;
    for(int i=0;i<last;i++) r->d[i]=(uint32_t)tmp[i];
    bi_normalize(r);
}
static void bi_from_dec_str_pos(BigInt *a,const char *s){
    bi_zero(a);
    if(!s || *s=='\0') return;
    a->sign=1;
    a->len=0;
    for(;*s; s++){
        if(!isdigit((unsigned char)*s)) continue;
        bi_mul_u64(a,10);
        BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=*s-'0';
        BigInt tmp; bi_add_signed(&tmp,a,&one);
        bi_copy(a,&tmp);
    }
    bi_normalize(a);
}
static void bi_to_dec_str(const BigInt *a,char *out){
    if(bi_is_zero(a)){ strcpy(out,"0"); return; }
    BigInt t=*a;
    if(t.sign<0){ *out++='-'; }
    /* we will build digits */
    char buf[2048];
    int pos=0;
    BigInt c=t;
    if(c.sign<0) c.sign=1;
    if(bi_is_zero(&c)){ buf[pos++]='0'; }
    else{
        char rev[2048];
        int rpos=0;
        BigInt tmp=c;
        if(bi_is_zero(&tmp)){ rev[rpos++]='0'; }
        else{
            char dig[2048];
            int dpos=0;
            while(!bi_is_zero(&tmp)){
                uint64_t rem=bi_div_u64(&tmp,10);
                dig[dpos++]='0'+rem;
            }
            for(int i=dpos-1;i>=0;i--) rev[rpos++]=dig[i];
        }
        rev[rpos]='\0';
        strcpy(buf,rev);
    }
    strcpy(out,buf);
}

/* rounding division of positive big int by uint64 */
static void bi_round_div_u64(BigInt *res,const BigInt *num,uint64_t d){
    if(bi_is_zero(num)){ bi_zero(res); return; }
    BigInt q=*num;
    if(q.sign<0) q.sign=1;
    uint64_t rem=bi_div_u64(&q,d);
    __uint128_t twice = (__uint128_t)rem*2;
    int need_up=0;
    if(twice > d) need_up=1;
    else if(twice == d){
        int even = (q.len==0) || ((q.d[0]&1)==0);
        if(!even) need_up=1;
    }
    if(need_up){
        BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=1;
        bi_add_signed(&q,&q,&one);
    }
    res->sign = num->sign;
    bi_copy(res,&q);
}

/* power of 10 for small exponent */
static uint64_t pow10_u64(int e){
    uint64_t r=1;
    for(int i=0;i<e;i++) r*=10ULL;
    return r;
}

/* amount rounding to minor units */
static void amount_round_to_minor(const char *s,int minor,BigInt *out){
    const char *p=s;
    while(isspace((unsigned char)*p)) p++;
    int sign=1;
    if(*p=='+'||*p=='-'){ if(*p=='-') sign=-1; p++; }
    const char *dot=strchr(p,'.');
    char intpart[512]={0};
    char fracpart[512]={0};
    if(dot){
        size_t ilen=dot-p;
        if(ilen>=sizeof(intpart)) ilen=sizeof(intpart)-1;
        memcpy(intpart,p,ilen);
        strcpy(fracpart,dot+1);
    }else{
        strncpy(intpart,p,sizeof(intpart)-1);
    }
    /* strip spaces */
    char clean[1024];
    int ci=0;
    for(int i=0;intpart[i];i++) if(isdigit((unsigned char)intpart[i])) clean[ci++]=intpart[i];
    clean[ci]='\0';
    char fclean[512];
    int fj=0;
    for(int i=0;fracpart[i];i++) if(isdigit((unsigned char)fracpart[i])) fclean[fj++]=fracpart[i];
    fclean[fj]='\0';
    int f_len=fj;
    char concat[1024];
    strcpy(concat,clean);
    strcat(concat,fclean);
    BigInt num; bi_zero(&num);
    if(concat[0]) bi_from_dec_str_pos(&num,concat);
    else { num.sign=1; num.len=1; num.d[0]=0; }
    if(f_len<=minor){
        int shift=minor-f_len;
        for(int i=0;i<shift;i++) bi_mul_u64(&num,10);
        num.sign=sign;
        bi_copy(out,&num);
        return;
    }else{
        int divpow=f_len-minor;
        uint64_t d=pow10_u64(divpow);
        BigInt tmp; bi_round_div_u64(&tmp,&num,d);
        tmp.sign=sign;
        bi_copy(out,&tmp);
    }
}

/* parse rate to numerator and exponent */
typedef struct { BigInt num; int exp; int sign; } Rate;
static void parse_rate(const char *s,Rate *r){
    const char *p=s;
    while(isspace((unsigned char)*p)) p++;
    int sign=1;
    if(*p=='+'||*p=='-'){ if(*p=='-') sign=-1; p++; }
    const char *dot=strchr(p,'.');
    char intpart[512]={0};
    char fracpart[512]={0};
    if(dot){
        size_t ilen=dot-p;
        if(ilen>=sizeof(intpart)) ilen=sizeof(intpart)-1;
        memcpy(intpart,p,ilen);
        strcpy(fracpart,dot+1);
    }else{
        strncpy(intpart,p,sizeof(intpart)-1);
    }
    char clean[1024]; int ci=0;
    for(int i=0;intpart[i];i++) if(isdigit((unsigned char)intpart[i])) clean[ci++]=intpart[i];
    clean[ci]='\0';
    char fclean[512]; int fj=0;
    for(int i=0;fracpart[i];i++) if(isdigit((unsigned char)fracpart[i])) fclean[fj++]=fracpart[i];
    fclean[fj]='\0';
    char concat[1024];
    strcpy(concat,clean);
    strcat(concat,fclean);
    bi_zero(&r->num);
    if(concat[0]) bi_from_dec_str_pos(&r->num,concat);
    else { r->num.sign=1; r->num.len=1; r->num.d[0]=0; }
    r->num.sign=sign;
    r->exp=fj;
    r->sign=sign;
}

/* formatting balance */
static void format_balance(char *out,const BigInt *bal,int minor){
    if(bi_is_zero(bal)){
        if(minor==0) sprintf(out,"0");
        else sprintf(out,"0.%0*d",minor,0);
        return;
    }
    int neg = bal->sign<0;
    BigInt a=*bal;
    if(neg) a.sign=1;
    char dec[2048];
    bi_to_dec_str(&a,dec);
    int len=strlen(dec);
    char intpart[2048];
    char fracpart[2048];
    if(minor==0){
        strcpy(intpart,dec);
    }else{
        if(len<=minor){
            /* pad */
            memset(fracpart,'0',minor);
            fracpart[minor]='\0';
            int pad=minor-len;
            memmove(fracpart+pad,dec,len);
            strcpy(intpart,"0");
        }else{
            int ilen=len-minor;
            strncpy(intpart,dec,ilen); intpart[ilen]='\0';
            strncpy(fracpart,dec+ilen,minor); fracpart[minor]='\0';
        }
    }
    /* commas */
    char intcomm[4096];
    int t=0;
    int cnt=0;
    for(int i=strlen(intpart)-1;i>=0;i--){
        intcomm[t++]=intpart[i];
        cnt++;
        if(cnt%3==0 && i>0) intcomm[t++]=',';
        cnt=0;
    }
    intcomm[t]='\0';
    char intrev[4096];
    int r=0;
    for(int i=t-1;i>=0;i--) intrev[r++]=intcomm[i];
    intrev[r]='\0';
    if(minor==0){
        if(neg) sprintf(out,"-%s",intrev);
        else sprintf(out,"%s",intrev);
    }else{
        if(neg) sprintf(out,"-%s.%s",intrev,fracpart);
        else sprintf(out,"%s.%s",intrev,fracpart);
    }
}

/* data structures */
typedef struct { char code[8]; int minor; } Currency;
typedef struct {
    char name[256];
    char code[8];
    BigInt bal;
    BigInt limit;
} Account;

static int find_currency(Currency *cs,int n,const char *code){
    for(int i=0;i<n;i++) if(strcmp(cs[i].code,code)==0) return i;
    return -1;
}
static int find_account(Account *as,int n,const char *name){
    for(int i=0;i<n;i++) if(strcmp(as[i].name,name)==0) return i;
    return -1;
}

/* main */
int main(int argc,char *argv[]){
    if(argc<2) return 1;
    char path[4096];
    snprintf(path,sizeof path,"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f){ perror("open"); return 1; }
    char *line=NULL; size_t sz=0;
    ssize_t len;
    int lineno=0;
    Currency curs[1024]; int nc=0;
    Account accs[4096]; int na=0;
    struct {int line; char reason[256];} rej[4096]; int nr=0;

    while((len=getline(&line,&sz,f))!=-1){
        lineno++;
        char *p=line;
        while(*p && isspace((unsigned char)*p)) p++;
        if(*p=='\0' || *p=='\n') continue;
        if(*p=='#') continue;
        char *copy=strdup(line);
        char *tok=strtok(copy," \t\r\n");
        if(!tok){ free(copy); continue; }
        if(strcmp(tok,"currency")==0){
            char *code=strtok(NULL," \t\r\n");
            char *min=strtok(NULL," \t\r\n");
            if(code && min){
                strcpy(curs[nc].code,code);
                curs[nc].minor=atoi(min);
                nc++;
            }
        }else if(strcmp(tok,"open")==0){
            char *name=strtok(NULL," \t\r\n");
            char *code=strtok(NULL," \t\r\n");
            char *lim=strtok(NULL," \t\r\n");
            if(name && code){
                int idx=find_account(accs,na,name);
                if(idx!=-1){
                    char buf[512];
                    snprintf(buf,sizeof buf,"line %d: REJECT account exists %s\n",lineno,name);
                    rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"account exists %s",name); nr++;
                    free(copy); continue;
                }
                int cidx=find_currency(curs,nc,code);
                int minor = cidx!=-1?curs[cidx].minor:0;
                BigInt bal; bi_zero(&bal);
                BigInt limv; bi_zero(&limv);
                if(lim){
                    amount_round_to_minor(lim,minor,&limv);
                }
                strcpy(accs[na].name,name);
                strcpy(accs[na].code,code);
                bi_copy(&accs[na].bal,&bal);
                bi_copy(&accs[na].limit,&limv);
                na++;
            }
        }else if(strcmp(tok,"deposit")==0){
            char *name=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!name||!amt){ free(copy); continue; }
            int idx=find_account(accs,na,name);
            if(idx==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",name); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[idx].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt nb; bi_add_signed(&nb,&accs[idx].bal,&amt_r);
            bi_copy(&accs[idx].bal,&nb);
        }else if(strcmp(tok,"withdraw")==0){
            char *name=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!name||!amt){ free(copy); continue; }
            int idx=find_account(accs,na,name);
            if(idx==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",name); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[idx].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt newbal; bi_sub_signed(&newbal,&accs[idx].bal,&amt_r);
            BigInt minus_limit; bi_neg(&accs[idx].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"insufficient funds %s",accs[idx].name); nr++; free(copy); continue; }
            bi_copy(&accs[idx].bal,&newbal);
        }else if(strcmp(tok,"transfer")==0){
            char *from=strtok(NULL," \t\r\n");
            char *to=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!from||!to||!amt){ free(copy); continue; }
            int ifrom=find_account(accs,na,from);
            if(ifrom==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",from); nr++; free(copy); continue; }
            int ito=find_account(accs,na,to);
            if(ito==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",to); nr++; free(copy); continue; }
            if(strcmp(accs[ifrom].code,accs[ito].code)!=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"currency mismatch"); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[ifrom].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt newbal; bi_sub_signed(&newbal,&accs[ifrom].bal,&amt_r);
            BigInt minus_limit; bi_neg(&accs[ifrom].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"insufficient funds %s",accs[ifrom].name); nr++; free(copy); continue; }
            bi_copy(&accs[ifrom].bal,&newbal);
            BigInt nb2; bi_add_signed(&nb2,&accs[ito].bal,&amt_r);
            bi_copy(&accs[ito].bal,&nb2);
        }else if(strcmp(tok,"convert")==0){
            char *from=strtok(NULL," \t\r\n");
            char *to=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            char *rate=strtok(NULL," \t\r\n");
            if(!from||!to||!amt||!rate){ free(copy); continue; }
            int ifrom=find_account(accs,na,from);
            if(ifrom==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",from); nr++; free(copy); continue; }
            int ito=find_account(accs,na,to);
            if(ito==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",to); nr++; free(copy); continue; }
            int cfrom=find_currency(curs,nc,accs[ifrom].code);
            int cto=find_currency(curs,nc,accs[ito].code);
            int minor_from=curs[cfrom].minor;
            int minor_to=curs[cto].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor_from,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            BigInt newbal; bi_sub_signed(&newbal,&accs[ifrom].bal,&amt_r);
            BigInt minus_limit; bi_neg(&accs[ifrom].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"insufficient funds %s",accs[ifrom].name); nr++; free(copy); continue; }
            Rate rt; parse_rate(rate,&rt);
            BigInt tmp; bi_mul_big(&tmp,&amt_r,&rt.num);
            bi_mul_u64(&tmp, pow10_u64(minor_to));
            int denom_exp = minor_from + rt.exp;
            uint64_t denom = pow10_u64(denom_exp);
            BigInt to_add; bi_round_div_u64(&to_add,&tmp,denom);
            to_add.sign = (amt_r.sign>0?1:-1) * rt.sign;
            if(to_add.sign==0) bi_zero(&to_add);
            BigInt nb; bi_add_signed(&nb,&accs[ito].bal,&to_add);
            bi_copy(&accs[ito].bal,&nb);
            bi_copy(&accs[ifrom].bal,&newbal);
        }else if(strcmp(tok,"interest")==0){
            char *name=strtok(NULL," \t\r\n");
            char *rate=strtok(NULL," \t\r\n");
            if(!name||!rate){ free(copy); continue; }
            int idx=find_account(accs,na,name);
            if(idx==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",name); nr++; free(copy); continue; }
            Rate rt; parse_rate(rate,&rt);
            BigInt bal_abs=*accs[idx].bal;
            if(bal_abs.sign<0) bal_abs.sign=1;
            BigInt rate_abs=rt.num;
            if(rate_abs.sign<0) rate_abs.sign=1;
            BigInt prod; bi_mul_big(&prod,&bal_abs,&rate_abs);
            uint64_t denom=pow10_u64(rt.exp);
            BigInt inc; bi_round_div_u64(&inc,&prod,denom);
            int sign = (accs[idx].bal.sign>=0?1:-1) * rt.sign;
            inc.sign = sign;
            BigInt nb; bi_add_signed(&nb,&accs[idx].bal,&inc);
            bi_copy(&accs[idx].bal,&nb);
        }else if(strcmp(tok,"split")==0){
            char *from=strtok(NULL," \t\r\n");
            char *amt=strtok(NULL," \t\r\n");
            if(!from||!amt){ free(copy); continue; }
            int ifrom=find_account(accs,na,from);
            if(ifrom==-1){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",from); nr++; free(copy); continue; }
            int cidx=find_currency(curs,nc,accs[ifrom].code);
            int minor=curs[cidx].minor;
            BigInt amt_r; amount_round_to_minor(amt,minor,&amt_r);
            if(bi_cmp(&amt_r,&(BigInt){0})<=0){ rej[nr].line=lineno; strcpy(rej[nr].reason,"non-positive amount"); nr++; free(copy); continue; }
            /* parse targets */
            struct { char name[256]; uint64_t w; int order; } targets[256];
            int nt=0;
            uint64_t sumw=0;
            char *tok2;
            while((tok2=strtok(NULL," \t\r\n"))){
                char *sep=strchr(tok2,':');
                if(!sep) continue;
                *sep='\0';
                strcpy(targets[nt].name,tok2);
                targets[nt].w=strtoull(sep+1,NULL,10);
                targets[nt].order=nt;
                sumw+=targets[nt].w;
                nt++;
            }
            if(nt<2){ free(copy); continue; }
            /* unknown accounts in order */
            int bad=0;
            for(int i=0;i<nt;i++){
                if(find_account(accs,na,targets[i].name)==-1){ bad=1; break; }
            }
            if(bad){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"unknown account %s",targets[0].name); nr++; free(copy); continue; }
            /* currency mismatch */
            int mismatch=0;
            for(int i=0;i<nt;i++){
                int idx2=find_account(accs,na,targets[i].name);
                if(strcmp(accs[idx2].code,accs[ifrom].code)!=0){ mismatch=1; break; }
            }
            if(mismatch){ rej[nr].line=lineno; strcpy(rej[nr].reason,"currency mismatch"); nr++; free(copy); continue; }
            /* insufficient funds */
            BigInt newbal; bi_sub_signed(&newbal,&accs[ifrom].bal,&amt_r);
            BigInt minus_limit; bi_neg(&accs[ifrom].limit);
            if(bi_cmp(&newbal,&minus_limit)<0){ rej[nr].line=lineno; snprintf(rej[nr].reason,sizeof rej[nr].reason,"insufficient funds %s",accs[ifrom].name); nr++; free(copy); continue; }
            /* distribute */
            BigInt sum_q; bi_zero(&sum_q);
            struct { BigInt q; uint64_t rem; int order; } dist[256];
            for(int i=0;i<nt;i++){
                int idx2=find_account(accs,na,targets[i].name);
                BigInt prod; bi_copy(&prod,&amt_r);
                bi_mul_u64(&prod,targets[i].w);
                BigInt q; bi_copy(&q,&prod);
                uint64_t rem=bi_div_u64(&q,sumw);
                dist[i].q=* &q;
                dist[i].rem=rem;
                dist[i].order=targets[i].order;
                BigInt tmp; bi_add_signed(&tmp,&sum_q,&q);
                bi_copy(&sum_q,&tmp);
            }
            BigInt leftover_big; bi_sub_signed(&leftover_big,&amt_r,&sum_q);
            char leftstr[256]; bi_to_dec_str(&leftover_big,leftstr);
            unsigned long long leftover= strtoull(leftstr,NULL,10);
            /* sort by remainder desc, order asc */
            int order_idx[256];
            for(int i=0;i<nt;i++) order_idx[i]=i;
            for(int i=0;i<nt-1;i++) for(int j=i+1;j<nt;j++){
                int a=order_idx[i], b=order_idx[j];
                if(dist[a].rem < dist[b].rem || (dist[a].rem==dist[b].rem && dist[a].order>dist[b].order)){
                    int tmpi=order_idx[i]; order_idx[i]=order_idx[j]; order_idx[j]=tmpi;
                }
            }
            for(unsigned long long k=0;k<leftover && k<(unsigned long long)nt;k++){
                int i=order_idx[k];
                BigInt one; bi_zero(&one); one.sign=1; one.len=1; one.d[0]=1;
                bi_add_signed(&dist[i].q,&dist[i].q,&one);
            }
            /* apply */
            bi_copy(&accs[ifrom].bal,&newbal);
            for(int i=0;i<nt;i++){
                int idx2=find_account(accs,na,targets[i].name);
                BigInt nb; bi_add_signed(&nb,&accs[idx2].bal,&dist[i].q);
                bi_copy(&accs[idx2].bal,&nb);
            }
        }
        free(copy);
    }
    free(line); fclose(f);

    for(int i=0;i<nr;i++){
        printf("line %d: REJECT %s\n", rej[i].line, rej[i].reason);
    }
    if(nr>0) printf("\n");
    /* sort accounts */
    for(int i=0;i<na;i++) for(int j=i+1;j<na;j++) if(strcmp(accs[i].name,accs[j].name)>0){ Account t=accs[i]; accs[i]=accs[j]; accs[j]=t; }
    for(int i=0;i<na;i++){
        int cidx=find_currency(curs,nc,accs[i].code);
        int minor = cidx!=-1?curs[cidx].minor:0;
        char balstr[2048];
        format_balance(balstr,&accs[i].bal,minor);
        printf("%s %s %s\n", accs[i].name, accs[i].code, balstr);
    }
    printf("\n");
    /* totals */
    for(int i=0;i<nc;i++){
        BigInt sum; bi_zero(&sum);
        int cnt=0;
        for(int j=0;j<na;j++) if(strcmp(accs[j].code,curs[i].code)==0){
            BigInt tmp; bi_add_signed(&tmp,&sum,&accs[j].bal);
            bi_copy(&sum,&tmp);
            cnt++;
        }
        if(cnt==0) continue;
        char balstr[2048];
        format_balance(balstr,&sum,curs[i].minor);
        printf("total %s %s (%d accounts)\n", curs[i].code, balstr, cnt);
    }
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

type TokenType = 'int'|'string'|'ident'|'keyword'|'op'|'punct'|'eof';
interface Token {
  type: TokenType;
  value?: string;
  name?: string;
  line: number;
}

const KEYWORDS = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  const len = src.length;
  const isSpace = (c:string)=>c===' '||c==='\t'||c==='\r'||c==='\n';
  while (i < len) {
    const c = src[i];
    if (c === '#') {
      while (i < len && src[i] !== '\n') i++;
    } else if (isSpace(c)) {
      if (c === '\n') line++;
      i++;
    } else if (c === '"') {
      i++;
      let str = '';
      let startLine = line;
      while (i < len) {
        const ch = src[i];
        if (ch === '\\') {
          const esc = src[i+1];
          if (esc === 'n') str += '\n';
          else if (esc === 't') str += '\t';
          else if (esc === '"' ) str += '"';
          else if (esc === '\\') str += '\\';
          else str += esc;
          i += 2;
        } else if (ch === '"') {
          i++;
          break;
        } else {
          if (ch === '\n') line++;
          str += ch;
          i++;
        }
      }
      tokens.push({type:'string', value:str, line:startLine});
    } else if (/[0-9]/.test(c)) {
      let start = i;
      while (i < len && /[0-9]/.test(src[i])) i++;
      const num = src.slice(start,i);
      tokens.push({type:'int', value:num, line});
    } else if (/[A-Za-z_]/.test(c)) {
      let start = i;
      while (i < len && /[A-Za-z0-9_]/.test(src[i])) i++;
      const word = src.slice(start,i);
      if (KEYWORDS.has(word)) {
        tokens.push({type:'keyword', name:word, line});
      } else {
        tokens.push({type:'ident', name:word, line});
      }
    } else {
      // operators / punctuation
      const two = src.slice(i,i+2);
      const ops = ['==','!=','<=','>='];
      if (ops.includes(two)) {
        tokens.push({type:'op', value:two, line});
        i+=2;
        continue;
      }
      const one = c;
      const singles = ['=','+','-','*','/','%','<','>','(',')','[',']','{','}',' ,',';'];
      if (singles.includes(one)) {
        if (one==='('||one===')'||one==='['||one===']'||one==='{'||one==='}'||one===','||one===';') {
          tokens.push({type:'punct', value:one, line});
        } else {
          tokens.push({type:'op', value:one, line});
        }
        i++;
        continue;
      }
      // unknown
      i++;
    }
  }
  tokens.push({type:'eof', line});
  return tokens;
}

/* AST */
type Expr = {kind:string, line:number, [k:string]:any};
type Stmt = {kind:string, line:number, [k:string]:any};

class Parser {
  tokens: Token[];
  pos = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  peek(offset=0): Token { return this.tokens[this.pos+offset] ?? {type:'eof',line:1}; }
  consume(): Token { return this.tokens[this.pos++]; }
  match(type:string, value?:string): boolean {
    const t = this.peek();
    if (t.type!==type) return false;
    if (value!==undefined && (t.value!==value && t.name!==value)) return false;
    this.pos++;
    return true;
  }
  expect(type:string, value?:string): Token {
    const t = this.peek();
    if (t.type!==type || (value!==undefined && t.value!==value && t.name!==value)) {
      throw new Error('parse error');
    }
    this.pos++;
    return t;
  }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek().type!=='eof') stmts.push(this.parseStmt());
    return stmts;
  }

  parseStmt(): Stmt {
    const t = this.peek();
    if (t.type==='keyword') {
      if (t.name==='let') {
        this.pos++;
        const id = this.expect('ident');
        this.expect('op','=');
        const e = this.parseExpression();
        this.expect('punct',';');
        return {kind:'let', name:id.name, expr:e, line:id.line};
      }
      if (t.name==='fn') {
        const next = this.peek(1);
        if (next.type==='ident' && this.peek(2).type==='punct' && this.peek(2).value==='(') {
          this.pos++; // fn
          const id = this.expect('ident');
          this.expect('punct','(');
          const params = this.parseParams();
          this.expect('punct',')');
          const block = this.parseBlock();
          return {kind:'fnDecl', name:id.name, params, body:block, line:id.line};
        }
      }
      if (t.name==='if') return this.parseIfStmt();
      if (t.name==='while') {
        this.pos++;
        const cond = this.parseExpression();
        const block = this.parseBlock();
        return {kind:'while', cond, body:block, line:t.line};
      }
      if (t.name==='for') {
        this.pos++;
        const id = this.expect('ident');
        this.expect('keyword','in');
        const expr = this.parseExpression();
        const block = this.parseBlock();
        return {kind:'for', varName:id.name, iterExpr:expr, body:block, line:t.line};
      }
      if (t.name==='return') {
        this.pos++;
        let expr: Expr|undefined;
        if (this.peek().type!=='punct' || this.peek().value!==';') expr = this.parseExpression();
        this.expect('punct',';');
        return {kind:'return', expr, line:t.line};
      }
      if (t.name==='break') { this.pos++; this.expect('punct',';'); return {kind:'break', line:t.line}; }
      if (t.name==='continue') { this.pos++; this.expect('punct',';'); return {kind:'continue', line:t.line}; }
    }
    // expression stmt / assignment
    const startPos = this.pos;
    const left = this.parseExpression();
    if (this.peek().type==='op' && this.peek().value==='=') {
      this.pos++;
      const right = this.parseExpression();
      this.expect('punct',';');
      // assignment
      if (left.kind==='ident') {
        return {kind:'assign', name:left.name, expr:right, line:left.line};
      } else if (left.kind==='index') {
        return {kind:'assignIndex', target:left, expr:right, line:left.line};
      } else {
        // fallback to expr stmt
        this.pos = startPos;
      }
    }
    // not assignment -> expression stmt
    this.expect('punct',';');
    return {kind:'exprStmt', expr:left, line:left.line};
  }

  parseIfStmt(): Stmt {
    this.pos++; // if
    const cond = this.parseExpression();
    const block = this.parseBlock();
    let elseBranch: Stmt|undefined;
    if (this.peek().type==='keyword' && this.peek().name==='else') {
      this.pos++;
      const nxt = this.peek();
      if (nxt.type==='keyword' && nxt.name==='if') {
        elseBranch = this.parseIfStmt();
      } else {
        elseBranch = {kind:'block', stmts:this.parseBlock().stmts, line:nxt.line};
      }
    }
    return {kind:'if', cond, then:block, elseBranch, line:cond.line};
  }

  parseBlock(): {kind:'block', stmts:Stmt[], line:number} {
    this.expect('punct','{');
    const stmts: Stmt[] = [];
    while (!(this.peek().type==='punct' && this.peek().value==='}')) {
      stmts.push(this.parseStmt());
    }
    this.expect('punct','}');
    return {kind:'block', stmts, line:1};
  }

  parseParams(): string[] {
    const params: string[] = [];
    if (this.peek().type==='ident') {
      params.push(this.expect('ident').name);
      while (this.peek().type==='op' && this.peek().value===',') {
        this.pos++;
        params.push(this.expect('ident').name);
      }
    }
    return params;
  }

  parseExpression(): Expr { return this.parseOr(); }
  parseOr(): Expr {
    let left = this.parseAnd();
    while (this.peek().type==='keyword' && this.peek().name==='or') {
      const opTok = this.consume();
      const right = this.parseAnd();
      left = {kind:'binary', op:'or', left, right, line:opTok.line};
    }
    return left;
  }
  parseAnd(): Expr {
    let left = this.parseNot();
    while (this.peek().type==='keyword' && this.peek().name==='and') {
      const opTok = this.consume();
      const right = this.parseNot();
      left = {kind:'binary', op:'and', left, right, line:opTok.line};
    }
    return left;
  }
  parseNot(): Expr {
    if (this.peek().type==='keyword' && this.peek().name==='not') {
      const tok = this.consume();
      const operand = this.parseNot();
      return {kind:'unary', op:'not', operand, line:tok.line};
    }
    return this.parseEquality();
  }
  parseEquality(): Expr {
    let left = this.parseRelational();
    while (this.peek().type==='op' && (this.peek().value==='=='||this.peek().value==='!=')) {
      const opTok = this.consume();
      const right = this.parseRelational();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseRelational(): Expr {
    let left = this.parseAdd();
    while (this.peek().type==='op' && ['<','<=','>','>='].includes(this.peek().value)) {
      const opTok = this.consume();
      const right = this.parseAdd();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseAdd(): Expr {
    let left = this.parseMul();
    while (this.peek().type==='op' && (this.peek().value==='+'||this.peek().value==='-')) {
      const opTok = this.consume();
      const right = this.parseMul();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseMul(): Expr {
    let left = this.parseUnaryMinus();
    while (this.peek().type==='op' && (this.peek().value==='*'||this.peek().value==='/'||this.peek().value==='%')) {
      const opTok = this.consume();
      const right = this.parseUnaryMinus();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseUnaryMinus(): Expr {
    if (this.peek().type==='op' && this.peek().value==='-') {
      const tok = this.consume();
      const operand = this.parseUnaryMinus();
      return {kind:'unary', op:'neg', operand, line:tok.line};
    }
    return this.parsePostfix();
  }
  parsePostfix(): Expr {
    let node = this.parsePrimary();
    while (true) {
      const t = this.peek();
      if (t.type==='punct' && t.value==='(') {
        const line = t.line;
        this.pos++;
        const args: Expr[] = [];
        if (!(this.peek().type==='punct' && this.peek().value===')')) {
          args.push(this.parseExpression());
          while (this.peek().type==='op' && this.peek().value===',') { this.pos++; args.push(this.parseExpression()); }
        }
        this.expect('punct',')');
        node = {kind:'call', callee:node, args, line};
      } else if (t.type==='punct' && t.value==='[') {
        const line = t.line;
        this.pos++;
        const idx = this.parseExpression();
        this.expect('punct',']');
        node = {kind:'index', obj:node, index:idx, line};
      } else break;
    }
    return node;
  }
  parsePrimary(): Expr {
    const t = this.peek();
    if (t.type==='int') { this.pos++; return {kind:'int', value:BigInt(t.value!), line:t.line}; }
    if (t.type==='string') { this.pos++; return {kind:'string', value:t.value!, line:t.line}; }
    if (t.type==='keyword') {
      if (t.name==='true') { this.pos++; return {kind:'bool', value:true, line:t.line}; }
      if (t.name==='false') { this.pos++; return {kind:'bool', value:false, line:t.line}; }
      if (t.name==='nil') { this.pos++; return {kind:'nil', line:t.line}; }
      if (t.name==='fn') {
        this.pos++;
        this.expect('punct','(');
        const params = this.parseParams();
        this.expect('punct',')');
        const block = this.parseBlock();
        return {kind:'fnExpr', params, body:block, line:t.line};
      }
    }
    if (t.type==='ident') { this.pos++; return {kind:'ident', name:t.name!, line:t.line}; }
    if (t.type==='punct' && t.value==='(') {
      this.pos++;
      const e = this.parseExpression();
      this.expect('punct',')');
      return e;
    }
    if (t.type==='punct' && t.value==='[') {
      this.pos++;
      const elems: Expr[] = [];
      if (!(this.peek().type==='punct' && this.peek().value===']')) {
        elems.push(this.parseExpression());
        while (this.peek().type==='op' && this.peek().value===',') { this.pos++; elems.push(this.parseExpression()); }
      }
      this.expect('punct',']');
      return {kind:'listLit', elems, line:t.line};
    }
    throw new Error('unexpected token');
  }
}

/* Runtime */
type ValueType = 'int'|'bool'|'string'|'list'|'function'|'nil';
interface BaseVal {type:ValueType}
interface IntVal extends BaseVal {type:'int'; value:bigint}
interface BoolVal extends BaseVal {type:'bool'; value:boolean}
interface StringVal extends BaseVal {type:'string'; value:string}
interface ListVal extends BaseVal {type:'list'; value:Value[]}
interface FuncVal extends BaseVal {type:'function'; params:string[]; body:any; closure:Scope; isBuiltin?:boolean; builtinName?:string; builtinImpl?:(...args:Value[])=>Value; name?:string}
interface NilVal extends BaseVal {type:'nil'}
type Value = IntVal|BoolVal|StringVal|ListVal|FuncVal|NilVal;

class Scope {
  vars = new Map<string,Value>();
  parent?: Scope;
  constructor(parent?:Scope){ this.parent=parent; }
  lookup(name:string): Value|undefined {
    if (this.vars.has(name)) return this.vars.get(name);
    if (this.parent) return this.parent.lookup(name);
  }
  assign(name:string, val:Value){ 
    let s:Scope=this;
    while(s.parent){ if(s.vars.has(name)){ s.vars.set(name,val); return true;} s=s.parent;}
    if(this.vars.has(name)){ this.vars.set(name,val); return true;}
    // not found
    return false;
  }
  set(name:string,val:Value){ this.vars.set(name,val); }
}

const NIL: NilVal = {type:'nil'};
function makeInt(n:bigint): IntVal { return {type:'int', value:n}; }
function makeBool(b:boolean): BoolVal { return {type:'bool', value:b}; }
function makeString(s:string): StringVal { return {type:'string', value:s}; }
function makeList(a:Value[]): ListVal { return {type:'list', value:a}; }
function makeFunc(params:string[], body:any, closure:Scope, isBuiltin?:boolean, builtinName?:string, builtinImpl?:(...args:Value[])=>Value): FuncVal {
  return {type:'function', params, body, closure, isBuiltin, builtinName, builtinImpl};
}

function truthy(v:Value): boolean {
  if (v.type==='bool') return v.value;
  if (v.type==='nil') return false;
  if (v.type==='int') return v.value!==0n;
  if (v.type==='string') return v.value.length>0;
  if (v.type==='list') return v.value.length>0;
  return true;
}

function formatValue(v:Value, stack:Set<ListVal>=new Set()): string {
  if (v.type==='int') return v.value.toString();
  if (v.type==='bool') return v.value?'true':'false';
  if (v.type==='nil') return 'nil';
  if (v.type==='function') return '<fn>';
  if (v.type==='string') return v.value;
  if (v.type==='list') {
    if (stack.has(v)) return '[...]';
    stack.add(v);
    const parts = v.value.map(el=>formatListElement(el, stack));
    stack.delete(v);
    return '['+parts.join(', ')+']';
  }
  return '';
}
function formatListElement(v:Value, stack:Set<ListVal>): string {
  if (v.type==='string') {
    const esc = v.value.replace(/\\/g,'\\\\').replace(/"/g,'\\"').replace(/\n/g,'\\n').replace(/\t/g,'\\t');
    return `"${esc}"`;
  }
  if (v.type==='list') {
    if (stack.has(v)) return '[...]';
    stack.add(v);
    const parts = v.value.map(el=>formatListElement(el, stack));
    stack.delete(v);
    return '['+parts.join(', ')+']';
  }
  return formatValue(v, stack);
}

class Interpreter {
  scope: Scope;
  output: string[] = [];
  errored = false;
  constructor() {
    const builtinScope = new Scope();
    const defBuiltin = (name:string, impl:(...args:Value[])=>Value) => {
      builtinScope.set(name, makeFunc([], [], new Scope(), true, name, impl));
    };
    defBuiltin('print', (...args:Value[]) => { this.output.push(args.map(a=>formatValue(a)).join(' ')); this.output.push(''); return NIL; });
    defBuiltin('str', (v:Value) => { return makeString(formatValue(v)); });
    defBuiltin('type', (v:Value) => { const names:{[k in ValueType]:string} = {int:'int',bool:'bool',string:'string',list:'list',function:'function',nil:'nil'}; return makeString(names[v.type]); });
    defBuiltin('len', (v:Value) => {
      if (v.type==='string') return makeInt(BigInt(v.value.length));
      if (v.type==='list') return makeInt(BigInt(v.value.length));
      this.runtimeError('bad argument to len', 0);
      return NIL;
    });
    defBuiltin('push', (list:Value, v:Value) => {
      if (list.type!=='list') { this.runtimeError('bad argument to push',0); return NIL; }
      list.value.push(v); return NIL;
    });
    defBuiltin('pop', (list:Value) => {
      if (list.type!=='list' || list.value.length===0) { this.runtimeError('bad argument to pop',0); return NIL; }
      return list.value.pop()!;
    });
    defBuiltin('range', (a:Value,b:Value) => {
      if (a.type!=='int' || b.type!=='int') { this.runtimeError('bad argument to range',0); return NIL; }
      const arr:Value[]=[];
      let i=a.value; const end=b.value;
      if (i < end) { while(i<end){ arr.push(makeInt(i)); i=i+1n; } } else if (i>end){ while(i>end){ arr.push(makeInt(i)); i=i-1n; } }
      return makeList(arr);
    });
    defBuiltin('slice', (x:Value,a:Value,b:Value) => {
      if (a.type!=='int' || b.type!=='int') { this.runtimeError('bad argument to slice',0); return NIL; }
      const ai=Number(a.value), bi=Number(b.value);
      if (x.type==='string') {
        const s=x.value; return makeString(s.slice(ai,bi));
      } else if (x.type==='list') {
        return makeList(x.value.slice(ai,bi));
      } else { this.runtimeError('bad argument to slice',0); return NIL; }
    });
    this.scope = new Scope(builtinScope);
  }

  runtimeError(msg:string, line:number) {
    if (this.errored) return;
    this.errored = true;
    this.output.push(`error at line ${line}: ${msg}`);
  }

  run(stmts: Stmt[]) {
    try { this.execStmts(stmts, this.scope); } catch(e:any){ /* handled */ }
  }

  execStmts(stmts: Stmt[], scope: Scope) {
    for (const s of stmts) {
      if (this.errored) return;
      this.execStmt(s, scope);
    }
  }

  execStmt(s: Stmt, scope: Scope) {
    switch (s.kind) {
      case 'let': {
        const v = this.evalExpr(s.expr, scope);
        scope.set(s.name, v);
        break;
      }
      case 'fnDecl': {
        const func = makeFunc(s.params, s.body, scope);
        scope.set(s.name, func);
        break;
      }
      case 'assign': {
        const v = this.evalExpr(s.expr, scope);
        if (!this.assignVar(s.name, v, scope, s.line)) {
          this.runtimeError(`undefined variable ${s.name}`, s.line);
        }
        break;
      }
      case 'assignIndex': {
        const target = s.target;
        const obj = this.evalExpr(target.obj, scope);
        const idx = this.evalExpr(target.index, scope);
        const val = this.evalExpr(s.expr, scope);
        if (obj.type!=='list') { this.runtimeError(`cannot assign into ${obj.type}`, target.line); return; }
        if (idx.type!=='int') { this.runtimeError(`cannot index list with ${idx.type}`, target.line); return; }
        const i = Number(idx.value);
        if (i<0 || i>=obj.value.length) { this.runtimeError(`index ${i} out of range for length ${obj.value.length}`, target.line); return; }
        obj.value[i]=val;
        break;
      }
      case 'exprStmt': {
        this.evalExpr(s.expr, scope);
        break;
      }
      case 'if': {
        const c = this.evalExpr(s.cond, scope);
        if (truthy(c)) {
          this.execBlock(s.then, scope);
        } else if (s.elseBranch) {
          if (s.elseBranch.kind==='block') this.execBlock(s.elseBranch, scope);
          else this.execStmt(s.elseBranch, scope);
        }
        break;
      }
      case 'while': {
        while (true) {
          const c = this.evalExpr(s.cond, scope);
          if (!truthy(c)) break;
          const loopScope = new Scope(scope);
          try { this.execBlock(s.body, loopScope); } catch(e:any){ if(e==='break') break; if(e==='continue') {/*continue*/} else throw e; }
        }
        break;
      }
      case 'for': {
        const iter = this.evalExpr(s.iterExpr, scope);
        if (iter.type!=='list') { this.runtimeError(`cannot iterate ${iter.type}`, s.line); return; }
        const list = iter.value;
        let i=0;
        while (i < list.length) {
          const loopScope = new Scope(scope);
          loopScope.set(s.varName, list[i]);
          try { this.execBlock(s.body, loopScope); } catch(e:any){ if(e==='break') break; if(e==='continue') {/*continue*/} else throw e; }
          i++;
        }
        break;
      }
      case 'return': {
        const v = s.expr ? this.evalExpr(s.expr, scope) : NIL;
        throw {type:'return', value:v};
      }
      case 'break': throw 'break';
      case 'continue': throw 'continue';
    }
  }

  execBlock(block: {stmts:Stmt[], line:number}, parent:Scope) {
    const scope = new Scope(parent);
    this.execStmts(block.stmts, scope);
  }

  assignVar(name:string, val:Value, scope:Scope, line:number): boolean {
    let s:Scope = scope;
    while (s) {
      if (s.vars.has(name)) { s.vars.set(name,val); return true; }
      s = s.parent!;
    }
    return false;
  }

  evalExpr(e: Expr, scope: Scope): Value {
    switch (e.kind) {
      case 'int': return makeInt(e.value);
      case 'string': return makeString(e.value);
      case 'bool': return makeBool(e.value);
      case 'nil': return NIL;
      case 'ident': {
        const v = scope.lookup(e.name);
        if (!v) { this.runtimeError(`undefined variable ${e.name}`, e.line); return NIL; }
        return v;
      }
      case 'listLit': {
        const elems = e.elems.map(el=>this.evalExpr(el, scope));
        return makeList(elems);
      }
      case 'fnExpr': {
        return makeFunc(e.params, e.body, scope);
      }
      case 'call': {
        const callee = this.evalExpr(e.callee, scope);
        const args = e.args.map(a=>this.evalExpr(a, scope));
        if (callee.type!=='function') { this.runtimeError(`cannot call ${callee.type}`, e.line); return NIL; }
        if (callee.isBuiltin && callee.builtinImpl) {
          if (args.length!==callee.params.length && callee.params.length!==0) {
            // builtins have variable args for print
            if (callee.builtinName==='print') {/* ok */}
            else { this.runtimeError(`expected ${callee.params.length} arguments, got ${args.length}`, e.line); return NIL; }
          }
          try { return callee.builtinImpl(...args); } catch { this.runtimeError(`bad argument to ${callee.builtinName}`, e.line); return NIL; }
        }
        if (args.length!==callee.params.length) { this.runtimeError(`expected ${callee.params.length} arguments, got ${args.length}`, e.line); return NIL; }
        const callScope = new Scope(callee.closure);
        for (let i=0;i<callee.params.length;i++) callScope.set(callee.params[i], args[i]);
        try {
          this.execBlock(callee.body, callScope);
        } catch (ret:any) {
          if (ret && ret.type==='return') return ret.value;
        }
        return NIL;
      }
      case 'index': {
        const obj = this.evalExpr(e.obj, scope);
        const idx = this.evalExpr(e.index, scope);
        if (obj.type==='list') {
          if (idx.type!=='int') { this.runtimeError(`cannot index ${obj.type} with ${idx.type}`, e.line); return NIL; }
          const i=Number(idx.value);
          if (i<0||i>=obj.value.length) { this.runtimeError(`index ${i} out of range for length ${obj.value.length}`, e.line); return NIL; }
          return obj.value[i];
        }
        if (obj.type==='string') {
          if (idx.type!=='int') { this.runtimeError(`cannot index ${obj.type} with ${idx.type}`, e.line); return NIL; }
          const i=Number(idx.value);
          if (i<0||i>=obj.value.length) { this.runtimeError(`index ${i} out of range for length ${obj.value.length}`, e.line); return NIL; }
          return makeString(obj.value[i]);
        }
        this.runtimeError(`cannot index ${obj.type} with ${idx.type}`, e.line);
        return NIL;
      }
      case 'unary': {
        const v = this.evalExpr(e.operand, scope);
        if (e.op==='not') {
          return makeBool(!truthy(v));
        }
        if (e.op==='neg') {
          if (v.type!=='int') { this.runtimeError(`cannot apply - to ${v.type}`, e.line); return NIL; }
          const res = -v.value;
          if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
          return makeInt(res);
        }
        break;
      }
      case 'binary': {
        if (e.op==='and') {
          const left = this.evalExpr(e.left, scope);
          if (!truthy(left)) return left;
          return this.evalExpr(e.right, scope);
        }
        if (e.op==='or') {
          const left = this.evalExpr(e.left, scope);
          if (truthy(left)) return left;
          return this.evalExpr(e.right, scope);
        }
        const left = this.evalExpr(e.left, scope);
        const right = this.evalExpr(e.right, scope);
        switch (e.op) {
          case '==': return makeBool(this.valuesEqual(left,right));
          case '!=': return makeBool(!this.valuesEqual(left,right));
          case '+': {
            if (left.type==='int' && right.type==='int') {
              const res = left.value + right.value;
              if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
              return makeInt(res);
            }
            if (left.type==='string' && right.type==='string') return makeString(left.value+right.value);
            if (left.type==='list' && right.type==='list') return makeList([...left.value, ...right.value]);
            this.runtimeError(`cannot apply + to ${left.type} and ${right.type}`, e.line); return NIL;
          }
          case '-': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply - to ${left.type} and ${right.type}`, e.line); return NIL; }
            const res = left.value - right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '*': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply * to ${left.type} and ${right.type}`, e.line); return NIL; }
            const res = left.value * right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '/': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply / to ${left.type} and ${right.type}`, e.line); return NIL; }
            if (right.value===0n) { this.runtimeError('division by zero', e.line); return NIL; }
            const res = left.value / right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '%': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply % to ${left.type} and ${right.type}`, e.line); return NIL; }
            if (right.value===0n) { this.runtimeError('division by zero', e.line); return NIL; }
            const div = left.value / right.value;
            const res = left.value - div * right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '<': case '<=': case '>': case '>=': {
            if (left.type==='int' && right.type==='int') {
              const cmp = left.value <=> right.value;
              return makeBool(e.op==='<'?cmp<0:e.op==='<= '?cmp<=0:e.op==='>'?cmp>0:cmp>=0);
            }
            if (left.type==='string' && right.type==='string') {
              const cmp = left.value.localeCompare(right.value);
              return makeBool(e.op==='<'?cmp<0:e.op==='<= '?cmp<=0:e.op==='>'?cmp>0:cmp>=0);
            }
            this.runtimeError(`cannot apply ${e.op} to ${left.type} and ${right.type}`, e.line); return NIL;
          }
        }
      }
    }
    return NIL;
  }

  valuesEqual(a:Value,b:Value): boolean {
    if (a.type!==b.type) return false;
    if (a.type==='int') return a.value===b.value;
    if (a.type==='bool') return a.value===b.value;
    if (a.type==='string') return a.value===b.value;
    if (a.type==='nil') return true;
    if (a.type==='function') return a===b;
    if (a.type==='list') {
      if (a.value.length!==b.value.length) return false;
      for (let i=0;i<a.value.length;i++) if (!this.valuesEqual(a.value[i], b.value[i])) return false;
      return true;
    }
    return false;
  }
}

/* main */
function main() {
  const dir = process.argv[2];
  if (!dir) { process.exit(0); }
  const file = path.join(dir, 'program.tern');
  const src = fs.readFileSync(file, 'utf8');
  const tokens = lex(src);
  const parser = new Parser(tokens);
  const stmts = parser.parseProgram();
  const interp = new Interpreter();
  interp.run(stmts);
  for (const line of interp.output) process.stdout.write(line + '\n');
}
main();

import * as fs from 'fs';
import * as path from 'path';

type TokenType = 'int'|'string'|'ident'|'keyword'|'op'|'punct'|'eof';
interface Token {
  type: TokenType;
  value?: string;
  name?: string;
  line: number;
}

const KEYWORDS = new Set(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil']);

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  const len = src.length;
  const isSpace = (c:string)=>c===' '||c==='\t'||c==='\r'||c==='\n';
  while (i < len) {
    const c = src[i];
    if (c === '#') {
      while (i < len && src[i] !== '\n') i++;
    } else if (isSpace(c)) {
      if (c === '\n') line++;
      i++;
    } else if (c === '"') {
      i++;
      let str = '';
      let startLine = line;
      while (i < len) {
        const ch = src[i];
        if (ch === '\\') {
          const esc = src[i+1];
          if (esc === 'n') str += '\n';
          else if (esc === 't') str += '\t';
          else if (esc === '"' ) str += '"';
          else if (esc === '\\') str += '\\';
          else str += esc;
          i += 2;
        } else if (ch === '"') {
          i++;
          break;
        } else {
          if (ch === '\n') line++;
          str += ch;
          i++;
        }
      }
      tokens.push({type:'string', value:str, line:startLine});
    } else if (/[0-9]/.test(c)) {
      let start = i;
      while (i < len && /[0-9]/.test(src[i])) i++;
      const num = src.slice(start,i);
      tokens.push({type:'int', value:num, line});
    } else if (/[A-Za-z_]/.test(c)) {
      let start = i;
      while (i < len && /[A-Za-z0-9_]/.test(src[i])) i++;
      const word = src.slice(start,i);
      if (KEYWORDS.has(word)) {
        tokens.push({type:'keyword', name:word, line});
      } else {
        tokens.push({type:'ident', name:word, line});
      }
    } else {
      const two = src.slice(i,i+2);
      const ops = ['==','!=','<=','>='];
      if (ops.includes(two)) {
        tokens.push({type:'op', value:two, line});
        i+=2;
        continue;
      }
      const one = c;
      const singles = ['=','+','-','*','/','%','<','>','(',')','[',']','{','}',' ,',';'];
      // fix singles
      const singlesSet = new Set(['=','+','-','*','/','%','<','>','(',')','[',']','{','}',' ,',',',';']);
      // actually use proper list
      const properSingles = ['=','+','-','*','/','%','<','>','(',')','[',']','{','}',',',';'];
      if (properSingles.includes(one)) {
        if (one==='('||one===')'||one==='['||one===']'||one==='{'||one==='}'||one===','||one===';') {
          tokens.push({type:'punct', value:one, line});
        } else {
          tokens.push({type:'op', value:one, line});
        }
        i++;
        continue;
      }
      i++;
    }
  }
  tokens.push({type:'eof', line});
  return tokens;
}

/* AST */
type Expr = {kind:string, line:number, [k:string]:any};
type Stmt = {kind:string, line:number, [k:string]:any};

class Parser {
  tokens: Token[];
  pos = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  peek(offset=0): Token { return this.tokens[this.pos+offset] ?? {type:'eof',line:1}; }
  consume(): Token { return this.tokens[this.pos++]; }
  match(type:string, value?:string): boolean {
    const t = this.peek();
    if (t.type!==type) return false;
    if (value!==undefined && (t.value!==value && t.name!==value)) return false;
    this.pos++;
    return true;
  }
  expect(type:string, value?:string): Token {
    const t = this.peek();
    if (t.type!==type || (value!==undefined && t.value!==value && t.name!==value)) {
      throw new Error('parse error');
    }
    this.pos++;
    return t;
  }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek().type!=='eof') stmts.push(this.parseStmt());
    return stmts;
  }

  parseStmt(): Stmt {
    const t = this.peek();
    if (t.type==='keyword') {
      if (t.name==='let') {
        this.pos++;
        const id = this.expect('ident');
        this.expect('op','=');
        const e = this.parseExpression();
        this.expect('punct',';');
        return {kind:'let', name:id.name, expr:e, line:id.line};
      }
      if (t.name==='fn') {
        const next = this.peek(1);
        if (next.type==='ident' && this.peek(2).type==='punct' && this.peek(2).value==='(') {
          this.pos++;
          const id = this.expect('ident');
          this.expect('punct','(');
          const params = this.parseParams();
          this.expect('punct',')');
          const block = this.parseBlock();
          return {kind:'fnDecl', name:id.name, params, body:block, line:id.line};
        }
      }
      if (t.name==='if') return this.parseIfStmt();
      if (t.name==='while') {
        this.pos++;
        const cond = this.parseExpression();
        const block = this.parseBlock();
        return {kind:'while', cond, body:block, line:t.line};
      }
      if (t.name==='for') {
        this.pos++;
        const id = this.expect('ident');
        this.expect('keyword','in');
        const expr = this.parseExpression();
        const block = this.parseBlock();
        return {kind:'for', varName:id.name, iterExpr:expr, body:block, line:t.line};
      }
      if (t.name==='return') {
        this.pos++;
        let expr: Expr|undefined;
        if (this.peek().type!=='punct' || this.peek().value!==';') expr = this.parseExpression();
        this.expect('punct',';');
        return {kind:'return', expr, line:t.line};
      }
      if (t.name==='break') { this.pos++; this.expect('punct',';'); return {kind:'break', line:t.line}; }
      if (t.name==='continue') { this.pos++; this.expect('punct',';'); return {kind:'continue', line:t.line}; }
    }
    const startPos = this.pos;
    const left = this.parseExpression();
    if (this.peek().type==='op' && this.peek().value==='=') {
      this.pos++;
      const right = this.parseExpression();
      this.expect('punct',';');
      if (left.kind==='ident') {
        return {kind:'assign', name:left.name, expr:right, line:left.line};
      } else if (left.kind==='index') {
        return {kind:'assignIndex', target:left, expr:right, line:left.line};
      } else {
        this.pos = startPos;
      }
    }
    this.expect('punct',';');
    return {kind:'exprStmt', expr:left, line:left.line};
  }

  parseIfStmt(): Stmt {
    this.pos++;
    const cond = this.parseExpression();
    const block = this.parseBlock();
    let elseBranch: Stmt|undefined;
    if (this.peek().type==='keyword' && this.peek().name==='else') {
      this.pos++;
      const nxt = this.peek();
      if (nxt.type==='keyword' && nxt.name==='if') {
        elseBranch = this.parseIfStmt();
      } else {
        const blk = this.parseBlock();
        elseBranch = {kind:'block', stmts:blk.stmts, line:blk.line};
      }
    }
    return {kind:'if', cond, then:block, elseBranch, line:cond.line};
  }

  parseBlock(): {kind:'block', stmts:Stmt[], line:number} {
    this.expect('punct','{');
    const stmts: Stmt[] = [];
    while (!(this.peek().type==='punct' && this.peek().value==='}')) {
      stmts.push(this.parseStmt());
    }
    this.expect('punct','}');
    return {kind:'block', stmts, line:1};
  }

  parseParams(): string[] {
    const params: string[] = [];
    if (this.peek().type==='ident') {
      params.push(this.expect('ident').name);
      while (this.peek().type==='op' && this.peek().value===',') {
        this.pos++;
        params.push(this.expect('ident').name);
      }
    }
    return params;
  }

  parseExpression(): Expr { return this.parseOr(); }
  parseOr(): Expr {
    let left = this.parseAnd();
    while (this.peek().type==='keyword' && this.peek().name==='or') {
      const opTok = this.consume();
      const right = this.parseAnd();
      left = {kind:'binary', op:'or', left, right, line:opTok.line};
    }
    return left;
  }
  parseAnd(): Expr {
    let left = this.parseNot();
    while (this.peek().type==='keyword' && this.peek().name==='and') {
      const opTok = this.consume();
      const right = this.parseNot();
      left = {kind:'binary', op:'and', left, right, line:opTok.line};
    }
    return left;
  }
  parseNot(): Expr {
    if (this.peek().type==='keyword' && this.peek().name==='not') {
      const tok = this.consume();
      const operand = this.parseNot();
      return {kind:'unary', op:'not', operand, line:tok.line};
    }
    return this.parseEquality();
  }
  parseEquality(): Expr {
    let left = this.parseRelational();
    while (this.peek().type==='op' && (this.peek().value==='=='||this.peek().value==='!=')) {
      const opTok = this.consume();
      const right = this.parseRelational();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseRelational(): Expr {
    let left = this.parseAdd();
    while (this.peek().type==='op' && ['<','<=','>','>='].includes(this.peek().value)) {
      const opTok = this.consume();
      const right = this.parseAdd();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseAdd(): Expr {
    let left = this.parseMul();
    while (this.peek().type==='op' && (this.peek().value==='+'||this.peek().value==='-')) {
      const opTok = this.consume();
      const right = this.parseMul();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseMul(): Expr {
    let left = this.parseUnaryMinus();
    while (this.peek().type==='op' && (this.peek().value==='*'||this.peek().value==='/'||this.peek().value==='%')) {
      const opTok = this.consume();
      const right = this.parseUnaryMinus();
      left = {kind:'binary', op:opTok.value, left, right, line:opTok.line};
    }
    return left;
  }
  parseUnaryMinus(): Expr {
    if (this.peek().type==='op' && this.peek().value==='-') {
      const tok = this.consume();
      const operand = this.parseUnaryMinus();
      return {kind:'unary', op:'neg', operand, line:tok.line};
    }
    return this.parsePostfix();
  }
  parsePostfix(): Expr {
    let node = this.parsePrimary();
    while (true) {
      const t = this.peek();
      if (t.type==='punct' && t.value==='(') {
        const line = t.line;
        this.pos++;
        const args: Expr[] = [];
        if (!(this.peek().type==='punct' && this.peek().value===')')) {
          args.push(this.parseExpression());
          while (this.peek().type==='op' && this.peek().value===',') { this.pos++; args.push(this.parseExpression()); }
        }
        this.expect('punct',')');
        node = {kind:'call', callee:node, args, line};
      } else if (t.type==='punct' && t.value==='[') {
        const line = t.line;
        this.pos++;
        const idx = this.parseExpression();
        this.expect('punct',']');
        node = {kind:'index', obj:node, index:idx, line};
      } else break;
    }
    return node;
  }
  parsePrimary(): Expr {
    const t = this.peek();
    if (t.type==='int') { this.pos++; return {kind:'int', value:BigInt(t.value!), line:t.line}; }
    if (t.type==='string') { this.pos++; return {kind:'string', value:t.value!, line:t.line}; }
    if (t.type==='keyword') {
      if (t.name==='true') { this.pos++; return {kind:'bool', value:true, line:t.line}; }
      if (t.name==='false') { this.pos++; return {kind:'bool', value:false, line:t.line}; }
      if (t.name==='nil') { this.pos++; return {kind:'nil', line:t.line}; }
      if (t.name==='fn') {
        this.pos++;
        this.expect('punct','(');
        const params = this.parseParams();
        this.expect('punct',')');
        const block = this.parseBlock();
        return {kind:'fnExpr', params, body:block, line:t.line};
      }
    }
    if (t.type==='ident') { this.pos++; return {kind:'ident', name:t.name!, line:t.line}; }
    if (t.type==='punct' && t.value==='(') {
      this.pos++;
      const e = this.parseExpression();
      this.expect('punct',')');
      return e;
    }
    if (t.type==='punct' && t.value==='[') {
      this.pos++;
      const elems: Expr[] = [];
      if (!(this.peek().type==='punct' && this.peek().value===']')) {
        elems.push(this.parseExpression());
        while (this.peek().type==='op' && this.peek().value===',') { this.pos++; elems.push(this.parseExpression()); }
      }
      this.expect('punct',']');
      return {kind:'listLit', elems, line:t.line};
    }
    throw new Error('unexpected token');
  }
}

/* Runtime */
type ValueType = 'int'|'bool'|'string'|'list'|'function'|'nil';
interface BaseVal {type:ValueType}
interface IntVal extends BaseVal {type:'int'; value:bigint}
interface BoolVal extends BaseVal {type:'bool'; value:boolean}
interface StringVal extends BaseVal {type:'string'; value:string}
interface ListVal extends BaseVal {type:'list'; value:Value[]}
interface FuncVal extends BaseVal {type:'function'; params:string[]; body:any; closure:Scope; isBuiltin?:boolean; builtinName?:string; builtinImpl?:(...args:Value[])=>Value; name?:string}
interface NilVal extends BaseVal {type:'nil'}
type Value = IntVal|BoolVal|StringVal|ListVal|FuncVal|NilVal;

class Scope {
  vars = new Map<string,Value>();
  parent?: Scope;
  constructor(parent?:Scope){ this.parent=parent; }
  lookup(name:string): Value|undefined {
    if (this.vars.has(name)) return this.vars.get(name);
    if (this.parent) return this.parent.lookup(name);
  }
  assign(name:string, val:Value){ 
    let s:Scope=this;
    while(s.parent){ if(s.vars.has(name)){ s.vars.set(name,val); return true;} s=s.parent;}
    if(this.vars.has(name)){ this.vars.set(name,val); return true;}
    return false;
  }
  set(name:string,val:Value){ this.vars.set(name,val); }
}

const NIL: NilVal = {type:'nil'};
function makeInt(n:bigint): IntVal { return {type:'int', value:n}; }
function makeBool(b:boolean): BoolVal { return {type:'bool', value:b}; }
function makeString(s:string): StringVal { return {type:'string', value:s}; }
function makeList(a:Value[]): ListVal { return {type:'list', value:a}; }
function makeFunc(params:string[], body:any, closure:Scope, isBuiltin?:boolean, builtinName?:string, builtinImpl?:(...args:Value[])=>Value): FuncVal {
  return {type:'function', params, body, closure, isBuiltin, builtinName, builtinImpl};
}

function truthy(v:Value): boolean {
  if (v.type==='bool') return v.value;
  if (v.type==='nil') return false;
  if (v.type==='int') return v.value!==0n;
  if (v.type==='string') return v.value.length>0;
  if (v.type==='list') return v.value.length>0;
  return true;
}

function formatValue(v:Value, stack:Set<ListVal>=new Set()): string {
  if (v.type==='int') return v.value.toString();
  if (v.type==='bool') return v.value?'true':'false';
  if (v.type==='nil') return 'nil';
  if (v.type==='function') return '<fn>';
  if (v.type==='string') return v.value;
  if (v.type==='list') {
    if (stack.has(v)) return '[...]';
    stack.add(v);
    const parts = v.value.map(el=>formatListElement(el, stack));
    stack.delete(v);
    return '['+parts.join(', ')+']';
  }
  return '';
}
function formatListElement(v:Value, stack:Set<ListVal>): string {
  if (v.type==='string') {
    const esc = v.value.replace(/\\/g,'\\\\').replace(/"/g,'\\"').replace(/\n/g,'\\n').replace(/\t/g,'\\t');
    return `"${esc}"`;
  }
  if (v.type==='list') {
    if (stack.has(v)) return '[...]';
    stack.add(v);
    const parts = v.value.map(el=>formatListElement(el, stack));
    stack.delete(v);
    return '['+parts.join(', ')+']';
  }
  return formatValue(v, stack);
}

class Interpreter {
  scope: Scope;
  output: string[] = [];
  errored = false;
  constructor() {
    const builtinScope = new Scope();
    const defBuiltin = (name:string, impl:(...args:Value[])=>Value) => {
      builtinScope.set(name, makeFunc([], [], new Scope(), true, name, impl));
    };
    defBuiltin('print', (...args:Value[]) => { this.output.push(args.map(a=>formatValue(a)).join(' ')); return NIL; });
    defBuiltin('str', (v:Value) => { return makeString(formatValue(v)); });
    defBuiltin('type', (v:Value) => { const names:{[k in ValueType]:string} = {int:'int',bool:'bool',string:'string',list:'list',function:'function',nil:'nil'}; return makeString(names[v.type]); });
    defBuiltin('len', (v:Value) => {
      if (v.type==='string') return makeInt(BigInt(v.value.length));
      if (v.type==='list') return makeInt(BigInt(v.value.length));
      this.runtimeError('bad argument to len', 0);
      return NIL;
    });
    defBuiltin('push', (list:Value, v:Value) => {
      if (list.type!=='list') { this.runtimeError('bad argument to push',0); return NIL; }
      list.value.push(v); return NIL;
    });
    defBuiltin('pop', (list:Value) => {
      if (list.type!=='list' || list.value.length===0) { this.runtimeError('bad argument to pop',0); return NIL; }
      return list.value.pop()!;
    });
    defBuiltin('range', (a:Value,b:Value) => {
      if (a.type!=='int' || b.type!=='int') { this.runtimeError('bad argument to range',0); return NIL; }
      const arr:Value[]=[];
      let i=a.value; const end=b.value;
      if (i < end) { while(i<end){ arr.push(makeInt(i)); i=i+1n; } }
      return makeList(arr);
    });
    defBuiltin('slice', (x:Value,a:Value,b:Value) => {
      if (a.type!=='int' || b.type!=='int') { this.runtimeError('bad argument to slice',0); return NIL; }
      const ai=Number(a.value), bi=Number(b.value);
      if (x.type==='string') {
        const s=x.value; return makeString(s.slice(ai,bi));
      } else if (x.type==='list') {
        return makeList(x.value.slice(ai,bi));
      } else { this.runtimeError('bad argument to slice',0); return NIL; }
    });
    this.scope = new Scope(builtinScope);
  }

  runtimeError(msg:string, line:number) {
    if (this.errored) return;
    this.errored = true;
    this.output.push(`error at line ${line}: ${msg}`);
  }

  run(stmts: Stmt[]) {
    try { this.execStmts(stmts, this.scope); } catch(e:any){ /* handled */ }
  }

  execStmts(stmts: Stmt[], scope: Scope) {
    for (const s of stmts) {
      if (this.errored) return;
      this.execStmt(s, scope);
    }
  }

  execStmt(s: Stmt, scope: Scope) {
    switch (s.kind) {
      case 'let': {
        const v = this.evalExpr(s.expr, scope);
        scope.set(s.name, v);
        break;
      }
      case 'fnDecl': {
        const func = makeFunc(s.params, s.body, scope);
        scope.set(s.name, func);
        break;
      }
      case 'assign': {
        const v = this.evalExpr(s.expr, scope);
        if (!this.assignVar(s.name, v, scope, s.line)) {
          this.runtimeError(`undefined variable ${s.name}`, s.line);
        }
        break;
      }
      case 'assignIndex': {
        const target = s.target;
        const obj = this.evalExpr(target.obj, scope);
        const idx = this.evalExpr(target.index, scope);
        const val = this.evalExpr(s.expr, scope);
        if (obj.type!=='list') { this.runtimeError(`cannot assign into ${obj.type}`, target.line); return; }
        if (idx.type!=='int') { this.runtimeError(`cannot index list with ${idx.type}`, target.line); return; }
        const i = Number(idx.value);
        if (i<0 || i>=obj.value.length) { this.runtimeError(`index ${i} out of range for length ${obj.value.length}`, target.line); return; }
        obj.value[i]=val;
        break;
      }
      case 'exprStmt': {
        this.evalExpr(s.expr, scope);
        break;
      }
      case 'if': {
        const c = this.evalExpr(s.cond, scope);
        if (truthy(c)) {
          this.execBlock(s.then, scope);
        } else if (s.elseBranch) {
          if (s.elseBranch.kind==='block') this.execBlock(s.elseBranch, scope);
          else this.execStmt(s.elseBranch, scope);
        }
        break;
      }
      case 'while': {
        while (true) {
          const c = this.evalExpr(s.cond, scope);
          if (!truthy(c)) break;
          try { this.execBlock(s.body, scope); } catch(e:any){ if(e==='break') break; if(e==='continue') {/*continue*/} else throw e; }
        }
        break;
      }
      case 'for': {
        const iter = this.evalExpr(s.iterExpr, scope);
        if (iter.type!=='list') { this.runtimeError(`cannot iterate ${iter.type}`, s.line); return; }
        const list = iter.value;
        let i=0;
        while (i < list.length) {
          const loopScope = new Scope(scope);
          loopScope.set(s.varName, list[i]);
          try { this.execBlock(s.body, loopScope); } catch(e:any){ if(e==='break') break; if(e==='continue') {/*continue*/} else throw e; }
          i++;
        }
        break;
      }
      case 'return': {
        const v = s.expr ? this.evalExpr(s.expr, scope) : NIL;
        throw {type:'return', value:v};
      }
      case 'break': throw 'break';
      case 'continue': throw 'continue';
    }
  }

  execBlock(block: {stmts:Stmt[], line:number}, parent:Scope) {
    const scope = new Scope(parent);
    this.execStmts(block.stmts, scope);
  }

  assignVar(name:string, val:Value, scope:Scope, line:number): boolean {
    let s:Scope = scope;
    while (s.parent) {
      if (s.vars.has(name)) { s.vars.set(name,val); return true; }
      s = s.parent!;
    }
    if (s.vars.has(name)) { s.vars.set(name,val); return true; }
    return false;
  }

  evalExpr(e: Expr, scope: Scope): Value {
    switch (e.kind) {
      case 'int': return makeInt(e.value);
      case 'string': return makeString(e.value);
      case 'bool': return makeBool(e.value);
      case 'nil': return NIL;
      case 'ident': {
        const v = scope.lookup(e.name);
        if (!v) { this.runtimeError(`undefined variable ${e.name}`, e.line); return NIL; }
        return v;
      }
      case 'listLit': {
        const elems = e.elems.map(el=>this.evalExpr(el, scope));
        return makeList(elems);
      }
      case 'fnExpr': {
        return makeFunc(e.params, e.body, scope);
      }
      case 'call': {
        const callee = this.evalExpr(e.callee, scope);
        const args = e.args.map(a=>this.evalExpr(a, scope));
        if (callee.type!=='function') { this.runtimeError(`cannot call ${callee.type}`, e.line); return NIL; }
        if (callee.isBuiltin && callee.builtinImpl) {
          if (callee.builtinName!=='print' && args.length!==callee.params.length) {
            this.runtimeError(`expected ${callee.params.length} arguments, got ${args.length}`, e.line); return NIL;
          }
          try { return callee.builtinImpl(...args); } catch { this.runtimeError(`bad argument to ${callee.builtinName}`, e.line); return NIL; }
        }
        if (args.length!==callee.params.length) { this.runtimeError(`expected ${callee.params.length} arguments, got ${args.length}`, e.line); return NIL; }
        const callScope = new Scope(callee.closure);
        for (let i=0;i<callee.params.length;i++) callScope.set(callee.params[i], args[i]);
        try {
          this.execBlock(callee.body, callScope);
        } catch (ret:any) {
          if (ret && ret.type==='return') return ret.value;
        }
        return NIL;
      }
      case 'index': {
        const obj = this.evalExpr(e.obj, scope);
        const idx = this.evalExpr(e.index, scope);
        if (obj.type==='list') {
          if (idx.type!=='int') { this.runtimeError(`cannot index ${obj.type} with ${idx.type}`, e.line); return NIL; }
          const i=Number(idx.value);
          if (i<0||i>=obj.value.length) { this.runtimeError(`index ${i} out of range for length ${obj.value.length}`, e.line); return NIL; }
          return obj.value[i];
        }
        if (obj.type==='string') {
          if (idx.type!=='int') { this.runtimeError(`cannot index ${obj.type} with ${idx.type}`, e.line); return NIL; }
          const i=Number(idx.value);
          if (i<0||i>=obj.value.length) { this.runtimeError(`index ${i} out of range for length ${obj.value.length}`, e.line); return NIL; }
          return makeString(obj.value[i]);
        }
        this.runtimeError(`cannot index ${obj.type} with ${idx.type}`, e.line);
        return NIL;
      }
      case 'unary': {
        const v = this.evalExpr(e.operand, scope);
        if (e.op==='not') {
          return makeBool(!truthy(v));
        }
        if (e.op==='neg') {
          if (v.type!=='int') { this.runtimeError(`cannot apply - to ${v.type}`, e.line); return NIL; }
          const res = -v.value;
          if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
          return makeInt(res);
        }
        break;
      }
      case 'binary': {
        if (e.op==='and') {
          const left = this.evalExpr(e.left, scope);
          if (!truthy(left)) return left;
          return this.evalExpr(e.right, scope);
        }
        if (e.op==='or') {
          const left = this.evalExpr(e.left, scope);
          if (truthy(left)) return left;
          return this.evalExpr(e.right, scope);
        }
        const left = this.evalExpr(e.left, scope);
        const right = this.evalExpr(e.right, scope);
        switch (e.op) {
          case '==': return makeBool(this.valuesEqual(left,right));
          case '!=': return makeBool(!this.valuesEqual(left,right));
          case '+': {
            if (left.type==='int' && right.type==='int') {
              const res = left.value + right.value;
              if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
              return makeInt(res);
            }
            if (left.type==='string' && right.type==='string') return makeString(left.value+right.value);
            if (left.type==='list' && right.type==='list') return makeList([...left.value, ...right.value]);
            this.runtimeError(`cannot apply + to ${left.type} and ${right.type}`, e.line); return NIL;
          }
          case '-': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply - to ${left.type} and ${right.type}`, e.line); return NIL; }
            const res = left.value - right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '*': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply * to ${left.type} and ${right.type}`, e.line); return NIL; }
            const res = left.value * right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '/': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply / to ${left.type} and ${right.type}`, e.line); return NIL; }
            if (right.value===0n) { this.runtimeError('division by zero', e.line); return NIL; }
            const res = left.value / right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '%': {
            if (left.type!=='int' || right.type!=='int') { this.runtimeError(`cannot apply % to ${left.type} and ${right.type}`, e.line); return NIL; }
            if (right.value===0n) { this.runtimeError('division by zero', e.line); return NIL; }
            const div = left.value / right.value;
            const res = left.value - div * right.value;
            if (res < -(1n<<63n) || res > (1n<<63n)-1n) { this.runtimeError('integer overflow', e.line); return NIL; }
            return makeInt(res);
          }
          case '<': case '<=': case '>': case '>=': {
            if (left.type==='int' && right.type==='int') {
              const l = left.value;
              const r = right.value;
              let cmp: number;
              if (l < r) cmp = -1;
              else if (l > r) cmp = 1;
              else cmp = 0;
              const ok = e.op==='<' ? cmp<0 : e.op==='<= '? cmp<=0 : e.op==='>' ? cmp>0 : cmp>=0;
              return makeBool(ok);
            }
            if (left.type==='string' && right.type==='string') {
              const cmp = left.value.localeCompare(right.value);
              const ok = e.op==='<' ? cmp<0 : e.op==='<= '? cmp<=0 : e.op==='>' ? cmp>0 : cmp>=0;
              return makeBool(ok);
            }
            this.runtimeError(`cannot apply ${e.op} to ${left.type} and ${right.type}`, e.line); return NIL;
          }
        }
      }
    }
    return NIL;
  }

  valuesEqual(a:Value,b:Value): boolean {
    if (a.type!==b.type) return false;
    if (a.type==='int') return a.value===b.value;
    if (a.type==='bool') return a.value===b.value;
    if (a.type==='string') return a.value===b.value;
    if (a.type==='nil') return true;
    if (a.type==='function') return a===b;
    if (a.type==='list') {
      if (a.value.length!==b.value.length) return false;
      for (let i=0;i<a.value.length;i++) if (!this.valuesEqual(a.value[i], b.value[i])) return false;
      return true;
    }
    return false;
  }
}

/* main */
function main() {
  const dir = process.argv[2];
  if (!dir) { process.exit(0); }
  const file = path.join(dir, 'program.tern');
  const src = fs.readFileSync(file, 'utf8');
  const tokens = lex(src);
  const parser = new Parser(tokens);
  const stmts = parser.parseProgram();
  const interp = new Interpreter();
  interp.run(stmts);
  for (const line of interp.output) process.stdout.write(line + '\n');
}
main();

import sys, os, math

# ---------- lexer ----------
class Token:
    __slots__ = ('typ','val','line')
    def __init__(self, typ, val, line):
        self.typ = typ; self.val = val; self.line = line

KEYWORDS = {
    'let','fn','if','else','while','for','in','return','break','continue',
    'and','or','not','true','false','nil'
}

def lex(src):
    tokens = []
    i = 0
    line = 1
    n = len(src)
    def add(typ,val):
        tokens.append(Token(typ,val,line))
    while i < n:
        c = src[i]
        if c in ' \t\r':
            i+=1; continue
        if c == '\n':
            line+=1; i+=1; continue
        if c == '#':
            while i<n and src[i]!='\n':
                i+=1
            continue
        if c == '"':
            i+=1; start_line=line
            buf=[]
            while i<n:
                ch=src[i]
                if ch=='\\':
                    i+=1
                    if i>=n: break
                    esc=src[i]
                    if esc=='n': buf.append('\n')
                    elif esc=='t': buf.append('\t')
                    elif esc=='"': buf.append('"')
                    elif esc=='\\': buf.append('\\')
                    else: buf.append(esc)
                    i+=1
                    continue
                if ch=='"':
                    i+=1
                    break
                buf.append(ch)
                i+=1
            add('STRING',''.join(buf))
            continue
        if c.isdigit():
            start=i
            while i<n and src[i].isdigit():
                i+=1
            add('INT',int(src[start:i]))
            continue
        if c.isalpha() or c=='_':
            start=i
            while i<n and (src[i].isalnum() or src[i]=='_'):
                i+=1
            word=src[start:i]
            if word in KEYWORDS:
                add(word,word)
            else:
                add('IDENT',word)
            continue
        # operators
        two=src[i:i+2]
        if two in ('==','!=','<=','>='):
            add('OP',two); i+=2; continue
        if c in '+-*/%<>=()[]{},;':
            add('OP',c); i+=1; continue
        # unknown
        i+=1
    tokens.append(Token('EOF',None,line))
    return tokens

# ---------- parser ----------
class Parser:
    def __init__(self,tokens):
        self.t=tokens; self.pos=0
    def peek(self): return self.t[self.pos]
    def next(self): t=self.t[self.pos]; self.pos+=1; return t
    def match(self,typ,val=None):
        t=self.peek()
        if t.typ==typ and (val is None or t.val==val):
            self.pos+=1; return True
        return False
    def expect(self,typ,val=None):
        t=self.peek()
        if t.typ!=typ or (val is not None and t.val!=val):
            raise SyntaxError('unexpected')
        self.pos+=1; return t
    def is_eof(self): return self.peek().typ=='EOF'

    # ---- program ----
    def parse_program(self):
        stmts=[]
        while not self.is_eof():
            stmts.append(self.parse_stmt())
        return stmts

    # ---- statements ----
    def parse_stmt(self):
        t=self.peek()
        if t.typ=='let':
            self.next()
            name=self.expect('IDENT').val
            self.expect('OP','=')
            expr=self.parse_expr()
            self.expect('OP',';')
            return ('let',name,expr)
        if t.typ=='fn':
            # lookahead for declaration
            # peek next two tokens
            if self.pos+2 < len(self.t):
                t2=self.t[self.pos+1]
                t3=self.t[self.pos+2]
                if t2.typ=='IDENT' and t3.typ=='OP' and t3.val=='(':
                    self.next() # fn
                    name=self.expect('IDENT').val
                    self.expect('OP','(')
                    params=self.parse_params()
                    self.expect('OP',')')
                    body=self.parse_block()
                    return ('fn_decl',name,params,body)
            # expression statement
            expr=self.parse_expr()
            self.expect('OP',';')
            return ('expr',expr)
        if t.typ=='if':
            self.next()
            cond=self.parse_expr()
            then_block=self.parse_block()
            else_branch=None
            if self.match('else',None):
                if self.peek().typ=='if':
                    else_branch=self.parse_stmt()
                else:
                    else_branch=self.parse_block()
            return ('if',cond,then_block,else_branch)
        if t.typ=='while':
            self.next()
            cond=self.parse_expr()
            body=self.parse_block()
            return ('while',cond,body)
        if t.typ=='for':
            self.next()
            var=self.expect('IDENT').val
            self.expect('in',None)
            iterable=self.parse_expr()
            body=self.parse_block()
            return ('for',var,iterable,body)
        if t.typ=='return':
            self.next()
            expr=None
            if not self.match('OP',';'):
                expr=self.parse_expr()
                self.expect('OP',';')
            else:
                # already consumed ;
                pass
            # if we consumed ; in match, need to ensure
            if self.peek().typ=='OP' and self.peek().val==';':
                self.next()
            return ('return',expr)
        if t.typ=='break':
            self.next(); self.expect('OP',';'); return ('break',)
        if t.typ=='continue':
            self.next(); self.expect('OP',';'); return ('continue',)
        # generic: try assignment
        # parse left expression partially
        # we need to be able to backtrack if not assignment
        # simple heuristic: parse expression then check for '='
        # We'll parse expression with our parse_expr which stops before '='
        # Actually parse_expr will consume as much as possible, so we need to peek.
        # We'll attempt to parse left side as expression using parse_expr but with lookahead.
        # Simpler: try to parse as assignment by looking ahead.
        # We'll save position
        save=self.pos
        left=self.parse_expr()
        if self.peek().typ=='OP' and self.peek().val=='=':
            self.next()
            rhs=self.parse_expr()
            self.expect('OP',';')
            return ('assign',left,rhs)
        # not assignment, backtrack
        self.pos=save
        expr=self.parse_expr()
        self.expect('OP',';')
        return ('expr',expr)

    def parse_params(self):
        params=[]
        if self.peek().typ=='OP' and self.peek().val==')':
            return params
        while True:
            name=self.expect('IDENT').val
            params.append(name)
            if not self.match('OP',','):
                break
        return params

    def parse_block(self):
        self.expect('OP','{')
        stmts=[]
        while not (self.peek().typ=='OP' and self.peek().val=='}'):
            stmts.append(self.parse_stmt())
        self.expect('OP','}')
        return ('block',stmts)

    # ---- expressions ----
    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left=self.parse_and()
        while self.match('or',None):
            right=self.parse_and()
            left=('bin','or',left,right)
        return left

    def parse_and(self):
        left=self.parse_not()
        while self.match('and',None):
            right=self.parse_not()
            left=('bin','and',left,right)
        return left

    def parse_not(self):
        if self.match('not',None):
            # allow chaining
            operand=self.parse_not()
            return ('un','not',operand)
        return self.parse_cmp()

    def parse_cmp(self):
        left=self.parse_add()
        while self.peek().typ=='OP' and self.peek().val in ('==','!=','<','<=','>','>='):
            op=self.next().val
            right=self.parse_add()
            left=('bin',op,left,right)
        return left

    def parse_add(self):
        left=self.parse_mul()
        while self.peek().typ=='OP' and self.peek().val in ('+','-'):
            op=self.next().val
            right=self.parse_mul()
            left=('bin',op,left,right)
        return left

    def parse_mul(self):
        left=self.parse_unary()
        while self.peek().typ=='OP' and self.peek().val in ('*','/','%'):
            op=self.next().val
            right=self.parse_unary()
            left=('bin',op,left,right)
        return left

    def parse_unary(self):
        if self.match('OP','-'):
            operand=self.parse_unary()
            return ('un','neg',operand)
        return self.parse_postfix()

    def parse_postfix(self):
        left=self.parse_primary()
        while True:
            if self.match('OP','('):
                args=[]
                if not (self.peek().typ=='OP' and self.peek().val==')'):
                    args.append(self.parse_expr())
                    while self.match('OP',','):
                        args.append(self.parse_expr())
                self.expect('OP',')')
                left=('call',left,args)
            elif self.match('OP','['):
                idx=self.parse_expr()
                self.expect('OP',']')
                left=('index',left,idx)
            else:
                break
        return left

    def parse_primary(self):
        t=self.peek()
        if t.typ=='INT':
            self.next(); return ('lit','int',t.val)
        if t.typ=='STRING':
            self.next(); return ('lit','str',t.val)
        if t.typ=='true': self.next(); return ('lit','bool',True)
        if t.typ=='false': self.next(); return ('lit','bool',False)
        if t.typ=='nil': self.next(); return ('lit','nil',None)
        if t.typ=='IDENT':
            self.next(); return ('var',t.val)
        if t.typ=='OP' and t.val=='(':
            self.next(); e=self.parse_expr(); self.expect('OP',')'); return e
        if t.typ=='OP' and t.val=='[':
            self.next()
            elems=[]
            if not (self.peek().typ=='OP' and self.peek().val==']'):
                elems.append(self.parse_expr())
                while self.match('OP',','):
                    elems.append(self.parse_expr())
            self.expect('OP',']')
            return ('list',elems)
        if t.typ=='fn':
            # anonymous lambda
            self.next()
            self.expect('OP','(')
            params=self.parse_params()
            self.expect('OP',')')
            body=self.parse_block()
            return ('lambda',params,body)
        raise SyntaxError('unexpected token')

# ---------- runtime ----------
MIN_INT = -(1<<63)
MAX_INT = (1<<63)-1

class RuntimeErrorExc(Exception):
    def __init__(self,line,msg):
        self.line=line; self.msg=msg

def trunc_div(a,b):
    if b==0: raise ZeroDivisionError
    q=abs(a)//abs(b)
    if (a<0) ^ (b<0): q=-q
    return q

def check_overflow(v):
    if v<MIN_INT or v>MAX_INT:
        raise RuntimeErrorExc(0,'integer overflow')

class Env:
    def __init__(self,parent=None):
        self.parent=parent
        self.vars={}
    def get(self,name):
        if name in self.vars: return self.vars[name]
        if self.parent: return self.parent.get(name)
        raise RuntimeErrorExc(0,f'undefined variable {name}')
    def set(self,name,val):
        if name in self.vars:
            self.vars[name]=val; return
        if self.parent:
            self.parent.set(name,val); return
        raise RuntimeErrorExc(0,f'undefined variable {name}')
    def declare(self,name,val):
        self.vars[name]=val

class Func:
    __slots__=('params','body','closure')
    def __init__(self,params,body,closure):
        self.params=params; self.body=body; self.closure=closure

def truthy(v):
    if isinstance(v,bool): return v
    if v is None: return False
    if isinstance(v,int): return v!=0
    if isinstance(v,str): return len(v)!=0
    if isinstance(v,list): return len(v)!=0
    return True

def format_value(v,inside_list=False,seen=None):
    if seen is None: seen=set()
    if isinstance(v,list):
        if id(v) in seen:
            return '[...]'
        seen.add(id(v))
        parts=[format_value(e,True,seen) for e in v]
        seen.remove(id(v))
        return '['+', '.join(parts)+']'
    if isinstance(v,str):
        if inside_list:
            s=v.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t')
            return f'"{s}"'
        return v
    if isinstance(v,bool):
        return 'true' if v else 'false'
    if v is None:
        return 'nil'
    if isinstance(v,Func):
        return '<fn>'
    if isinstance(v,int):
        return str(v)
    return str(v)

class Interpreter:
    def __init__(self,stmts):
        self.stmts=stmts
        self.builtins=self.make_builtins()
        self.global_env=Env(parent=self.builtins)
        self.output=[]

    def make_builtins(self):
        env=Env()
        # helpers
        def mk(name,fn): env.declare(name,fn)
        mk('print',self.builtin_print)
        mk('str',self.builtin_str)
        mk('type',self.builtin_type)
        mk('len',self.builtin_len)
        mk('push',self.builtin_push)
        mk('pop',self.builtin_pop)
        mk('range',self.builtin_range)
        mk('slice',self.builtin_slice)
        return env

    # builtins
    def builtin_print(self,args):
        out=' '.join(format_value(a) for a in args)
        self.output.append(out+'\n')
    def builtin_str(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to str')
        return format_value(args[0])
    def builtin_type(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to type')
        v=args[0]
        if isinstance(v,int): return 'int'
        if isinstance(v,bool): return 'bool'
        if isinstance(v,str): return 'string'
        if isinstance(v,list): return 'list'
        if isinstance(v,Func): return 'function'
        if v is None: return 'nil'
        return 'unknown'
    def builtin_len(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to len')
        v=args[0]
        if isinstance(v,str): return len(v)
        if isinstance(v,list): return len(v)
        raise RuntimeErrorExc(0,'bad argument to len')
    def builtin_push(self,args):
        if len(args)!=2: raise RuntimeErrorExc(0,'bad argument to push')
        lst, val = args
        if not isinstance(lst,list): raise RuntimeErrorExc(0,'bad argument to push')
        lst.append(val)
        return None
    def builtin_pop(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to pop')
        lst=args[0]
        if not isinstance(lst,list) or len(lst)==0:
            raise RuntimeErrorExc(0,'bad argument to pop')
        return lst.pop()
    def builtin_range(self,args):
        if len(args)!=2: raise RuntimeErrorExc(0,'bad argument to range')
        a,b=args
        if not isinstance(a,int) or not isinstance(b,int): raise RuntimeErrorExc(0,'bad argument to range')
        res=[]
        if b>a:
            for i in range(a,b):
                res.append(i)
        return res
    def builtin_slice(self,args):
        if len(args)!=3: raise RuntimeErrorExc(0,'bad argument to slice')
        x,a,b=args
        if not isinstance(a,int) or not isinstance(b,int): raise RuntimeErrorExc(0,'bad argument to slice')
        if isinstance(x,str):
            if not (0<=a<=b<=len(x)): raise RuntimeErrorExc(0,'bad argument to slice')
            return x[a:b]
        if isinstance(x,list):
            if not (0<=a<=b<=len(x)): raise RuntimeErrorExc(0,'bad argument to slice')
            return x[a:b][:]
        raise RuntimeErrorExc(0,'bad argument to slice')

    # execution
    def run(self):
        try:
            self.exec_stmts(self.stmts,self.global_env)
        except RuntimeErrorExc as e:
            # print already output
            sys.stdout.write(''.join(self.output))
            sys.stdout.write(f'error at line {e.line}: {e.msg}\n')
            return
        sys.stdout.write(''.join(self.output))

    def exec_stmts(self,stmts,env):
        for s in stmts:
            self.exec_stmt(s,env)

    def exec_stmt(self,s,env):
        typ=s[0]
        if typ=='let':
            _,name,expr=s
            val=self.eval_expr(expr,env)
            env.declare(name,val)
        elif typ=='fn_decl':
            _,name,params,body=s
            fn=Func(params,body,env)
            env.declare(name,fn)
        elif typ=='if':
            _,cond,then_block,else_branch=s
            if truthy(self.eval_expr(cond,env)):
                self.exec_block(then_block,env)
            elif else_branch:
                self.exec_stmt(else_branch,env)
        elif typ=='while':
            _,cond,body=s
            while True:
                if not truthy(self.eval_expr(cond,env)):
                    break
                try:
                    self.exec_block( ('block',[body]) , env)
                except ContinueException:
                    continue
                except BreakException:
                    break
        elif typ=='for':
            _,var,iterable_expr,body=s
            lst=self.eval_expr(iterable_expr,env)
            if not isinstance(lst,list):
                raise RuntimeErrorExc(0,f'cannot iterate {self.type_name(lst)}')
            i=0
            while i < len(lst):
                # fresh scope per iteration
                iter_env=Env(parent=env)
                iter_env.declare(var,lst[i])
                try:
                    self.exec_block(body,iter_env)
                except ContinueException:
                    i+=1
                    continue
                except BreakException:
                    break
                i+=1
        elif typ=='return':
            _,expr=s
            val=None if expr is None else self.eval_expr(expr,env)
            raise ReturnException(val)
        elif typ=='break':
            raise BreakException()
        elif typ=='continue':
            raise ContinueException()
        elif typ=='assign':
            _,left,right=s
            val=self.eval_expr(right,env)
            self.assign_lvalue(left,val,env)
        elif typ=='expr':
            _,expr=s
            self.eval_expr(expr,env)
        else:
            pass

    def exec_block(self,block,env):
        # block is ('block',stmts) or a block node
        if block[0]=='block':
            new_env=Env(parent=env)
            self.exec_stmts(block[1],new_env)
        else:
            # single statement block
            self.exec_stmt(block,env)

    def assign_lvalue(self,node,val,env):
        if node[0]=='var':
            env.set(node[1],val)
        elif node[0]=='index':
            _,obj,idx=node
            objv=self.eval_expr(obj,env)
            idxv=self.eval_expr(idx,env)
            if not isinstance(objv,list):
                raise RuntimeErrorExc(0,f'cannot assign into {self.type_name(objv)}')
            if not isinstance(idxv,int):
                raise RuntimeErrorExc(0,f'cannot index list with {self.type_name(idxv)}')
            if not 0<=idxv<len(objv):
                raise RuntimeErrorExc(0,f'index {idxv} out of range for length {len(objv)}')
            objv[idxv]=val
        else:
            # fallback
            raise RuntimeErrorExc(0,'cannot assign')

    def eval_expr(self,node,env):
        typ=node[0]
        if typ=='lit':
            _,t,v=node
            if t=='int': return v
            if t=='bool': return v
            if t=='str': return v
            if t=='nil': return None
        if typ=='var':
            name=node[1]
            try:
                return env.get(name)
            except:
                raise RuntimeErrorExc(0,f'undefined variable {name}')
        if typ=='un':
            _,op,operand=node
            v=self.eval_expr(operand,env)
            if op=='not':
                return not truthy(v)
            if op=='neg':
                if not isinstance(v,int):
                    raise RuntimeErrorExc(0,f'cannot apply - to {self.type_name(v)}')
                r=-v
                check_overflow(r)
                return r
        if typ=='bin':
            _,op,l,r=node
            left=self.eval_expr(l,env)
            right=self.eval_expr(r,env)
            if op=='or':
                return left if truthy(left) else right
            if op=='and':
                return left if not truthy(left) else right
            # binary ops need both evaluated
            # handle types
            if op in ('+','-','*','/','%'):
                if not isinstance(left,int) or not isinstance(right,int):
                    raise RuntimeErrorExc(0,f'cannot apply {op} to {self.type_name(left)} and {self.type_name(right)}')
                if op=='+': res=left+right
                elif op=='-': res=left-right
                elif op=='*': res=left*right
                elif op== '/':
                    if right==0: raise RuntimeErrorExc(0,'division by zero')
                    res=trunc_div(left,right)
                elif op=='%':
                    if right==0: raise RuntimeErrorExc(0,'division by zero')
                    q=trunc_div(left,right)
                    res=left-q*right
                check_overflow(res)
                return res
            if op in ('==','!='):
                eq=self.values_equal(left,right)
                return eq if op=='==' else not eq
            if op in ('<','<=','>','>='):
                if isinstance(left,int) and isinstance(right,int):
                    pass
                elif isinstance(left,str) and isinstance(right,str):
                    pass
                else:
                    raise RuntimeErrorExc(0,f'cannot apply {op} to {self.type_name(left)} and {self.type_name(right)}')
                if op=='<': return left<right
                if op=='<=': return left<=right
                if op=='>': return left>right
                if op=='>=': return left>=right
        if typ=='call':
            _,func,args=node
            fv=self.eval_expr(func,env)
            argvals=[self.eval_expr(a,env) for a in args]
            if isinstance(fv,Func):
                if len(argvals)!=len(fv.params):
                    raise RuntimeErrorExc(0,f'expected {len(fv.params)} arguments, got {len(argvals)}')
                call_env=Env(parent=fv.closure)
                for p,v in zip(fv.params,argvals):
                    call_env.declare(p,v)
                try:
                    self.exec_block(fv.body,call_env)
                    return None
                except ReturnException as e:
                    return e.value
            # builtin
            if callable(fv):
                # builtins are Python callables
                # they expect args list
                return fv(argvals)
            raise RuntimeErrorExc(0,f'cannot call {self.type_name(fv)}')
        if typ=='index':
            _,obj,idx=node
            ov=self.eval_expr(obj,env)
            iv=self.eval_expr(idx,env)
            if isinstance(ov,list):
                if not isinstance(iv,int): raise RuntimeErrorExc(0,f'cannot index list with {self.type_name(iv)}')
                if not 0<=iv<len(ov): raise RuntimeErrorExc(0,f'index {iv} out of range for length {len(ov)}')
                return ov[iv]
            if isinstance(ov,str):
                if not isinstance(iv,int): raise RuntimeErrorExc(0,f'cannot index string with {self.type_name(iv)}')
                if not 0<=iv<len(ov): raise RuntimeErrorExc(0,f'index {iv} out of range for length {len(ov)}')
                return ov[iv]
            raise RuntimeErrorExc(0,f'cannot index {self.type_name(ov)} with {self.type_name(iv)}')
        if typ=='list':
            elems=[self.eval_expr(e,env) for e in node[1]]
            return elems
        if typ=='lambda':
            _,params,body=node
            return Func(params,body,env)
        raise RuntimeErrorExc(0,'unknown expr')

    def type_name(self,v):
        if isinstance(v,int): return 'int'
        if isinstance(v,bool): return 'bool'
        if isinstance(v,str): return 'string'
        if isinstance(v,list): return 'list'
        if isinstance(v,Func): return 'function'
        if v is None: return 'nil'
        return 'unknown'

    def values_equal(self,a,b):
        if type(a)!=type(b):
            # bool vs int? Different types unequal
            # but Python bool is subclass of int, need careful
            if isinstance(a,bool) and isinstance(b,int): return False
            if isinstance(b,bool) and isinstance(a,int): return False
            return False
        if isinstance(a,int): return a==b
        if isinstance(a,bool): return a==b
        if isinstance(a,str): return a==b
        if a is None: return True
        if isinstance(a,list):
            if len(a)!=len(b): return False
            return all(self.values_equal(x,y) for x,y in zip(a,b))
        if isinstance(a,Func):
            return a is b
        return a==b

class ReturnException(Exception):
    def __init__(self,val): self.value=val
class BreakException(Exception): pass
class ContinueException(Exception): pass

def main():
    if len(sys.argv)<2:
        return
    dir_path=sys.argv[1]
    path=os.path.join(dir_path,'program.tern')
    src=open(path,'r',encoding='utf-8').read()
    tokens=lex(src)
    parser=Parser(tokens)
    stmts=parser.parse_program()
    interp=Interpreter(stmts)
    interp.run()

if __name__=='__main__':
    main()

import sys, os, math

# ---------- lexer ----------
class Token:
    __slots__ = ('typ','val','line')
    def __init__(self, typ, val, line):
        self.typ = typ; self.val = val; self.line = line

KEYWORDS = {
    'let','fn','if','else','while','for','in','return','break','continue',
    'and','or','not','true','false','nil'
}

def lex(src):
    tokens = []
    i = 0
    line = 1
    n = len(src)
    def add(typ,val):
        tokens.append(Token(typ,val,line))
    while i < n:
        c = src[i]
        if c in ' \t\r':
            i+=1; continue
        if c == '\n':
            line+=1; i+=1; continue
        if c == '#':
            while i<n and src[i]!='\n':
                i+=1
            continue
        if c == '"':
            i+=1; start_line=line
            buf=[]
            while i<n:
                ch=src[i]
                if ch=='\\':
                    i+=1
                    if i>=n: break
                    esc=src[i]
                    if esc=='n': buf.append('\n')
                    elif esc=='t': buf.append('\t')
                    elif esc=='"': buf.append('"')
                    elif esc=='\\': buf.append('\\')
                    else: buf.append(esc)
                    i+=1
                    continue
                if ch=='"':
                    i+=1
                    break
                buf.append(ch)
                i+=1
            add('STRING',''.join(buf))
            continue
        if c.isdigit():
            start=i
            while i<n and src[i].isdigit():
                i+=1
            add('INT',int(src[start:i]))
            continue
        if c.isalpha() or c=='_':
            start=i
            while i<n and (src[i].isalnum() or src[i]=='_'):
                i+=1
            word=src[start:i]
            if word in KEYWORDS:
                add(word,word)
            else:
                add('IDENT',word)
            continue
        two=src[i:i+2]
        if two in ('==','!=','<=','>='):
            add('OP',two); i+=2; continue
        if c in '+-*/%<>=()[]{},;':
            add('OP',c); i+=1; continue
        i+=1
    tokens.append(Token('EOF',None,line))
    return tokens

# ---------- parser ----------
class Parser:
    def __init__(self,tokens):
        self.t=tokens; self.pos=0
    def peek(self): return self.t[self.pos]
    def next(self): t=self.t[self.pos]; self.pos+=1; return t
    def match(self,typ,val=None):
        t=self.peek()
        if t.typ==typ and (val is None or t.val==val):
            self.pos+=1; return True
        return False
    def expect(self,typ,val=None):
        t=self.peek()
        if t.typ!=typ or (val is not None and t.val!=val):
            raise SyntaxError('unexpected')
        self.pos+=1; return t
    def is_eof(self): return self.peek().typ=='EOF'

    def parse_program(self):
        stmts=[]
        while not self.is_eof():
            stmts.append(self.parse_stmt())
        return stmts

    def parse_stmt(self):
        t=self.peek()
        if t.typ=='let':
            self.next()
            name=self.expect('IDENT').val
            self.expect('OP','=')
            expr=self.parse_expr()
            self.expect('OP',';')
            return ('let',name,expr)
        if t.typ=='fn':
            # declaration?
            if self.pos+2 < len(self.t):
                t2=self.t[self.pos+1]
                t3=self.t[self.pos+2]
                if t2.typ=='IDENT' and t3.typ=='OP' and t3.val=='(':
                    self.next()
                    name=self.expect('IDENT').val
                    self.expect('OP','(')
                    params=self.parse_params()
                    self.expect('OP',')')
                    body=self.parse_block()
                    return ('fn_decl',name,params,body)
            expr=self.parse_expr()
            self.expect('OP',';')
            return ('expr',expr)
        if t.typ=='if':
            self.next()
            cond=self.parse_expr()
            then_block=self.parse_block()
            else_branch=None
            if self.match('else',None):
                if self.peek().typ=='if':
                    else_branch=self.parse_stmt()
                else:
                    else_branch=self.parse_block()
            return ('if',cond,then_block,else_branch)
        if t.typ=='while':
            self.next()
            cond=self.parse_expr()
            body=self.parse_block()
            return ('while',cond,body)
        if t.typ=='for':
            self.next()
            var=self.expect('IDENT').val
            self.expect('in',None)
            iterable=self.parse_expr()
            body=self.parse_block()
            return ('for',var,iterable,body)
        if t.typ=='return':
            self.next()
            if self.match('OP',';'):
                return ('return',None)
            expr=self.parse_expr()
            self.expect('OP',';')
            return ('return',expr)
        if t.typ=='break':
            self.next(); self.expect('OP',';'); return ('break',)
        if t.typ=='continue':
            self.next(); self.expect('OP',';'); return ('continue',)
        # assignment or expr
        save=self.pos
        left=self.parse_expr()
        if self.peek().typ=='OP' and self.peek().val=='=':
            self.next()
            rhs=self.parse_expr()
            self.expect('OP',';')
            return ('assign',left,rhs)
        self.pos=save
        expr=self.parse_expr()
        self.expect('OP',';')
        return ('expr',expr)

    def parse_params(self):
        params=[]
        if self.peek().typ=='OP' and self.peek().val==')':
            return params
        while True:
            name=self.expect('IDENT').val
            params.append(name)
            if not self.match('OP',','):
                break
        return params

    def parse_block(self):
        self.expect('OP','{')
        stmts=[]
        while not (self.peek().typ=='OP' and self.peek().val=='}'):
            stmts.append(self.parse_stmt())
        self.expect('OP',')' if False else '}')
        # actually '}'
        # we already consumed? Let's just expect '}'
        # The above expect is wrong, fix:
        # We'll just manually check
        # For simplicity, assume correct
        # Re-parse correctly
        # (the parser already consumed '}'? )
        # We'll redo:
        # This function is messy, but works for tests
        # Let's just return
        return ('block',stmts)

    # quick fix for parse_block
    def parse_block_fixed(self):
        self.expect('OP','{')
        stmts=[]
        while not (self.peek().typ=='OP' and self.peek().val=='}'):
            stmts.append(self.parse_stmt())
        self.expect('OP','}')
        return ('block',stmts)

    # replace parse_block with fixed version
    # monkey patch
    parse_block = parse_block_fixed

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left=self.parse_and()
        while self.match('or',None):
            right=self.parse_and()
            left=('bin','or',left,right)
        return left

    def parse_and(self):
        left=self.parse_not()
        while self.match('and',None):
            right=self.parse_not()
            left=('bin','and',left,right)
        return left

    def parse_not(self):
        if self.match('not',None):
            operand=self.parse_not()
            return ('un','not',operand)
        return self.parse_cmp()

    def parse_cmp(self):
        left=self.parse_add()
        while self.peek().typ=='OP' and self.peek().val in ('==','!=','<','<=','>','>='):
            op=self.next().val
            right=self.parse_add()
            left=('bin',op,left,right)
        return left

    def parse_add(self):
        left=self.parse_mul()
        while self.peek().typ=='OP' and self.peek().val in ('+','-'):
            op=self.next().val
            right=self.parse_mul()
            left=('bin',op,left,right)
        return left

    def parse_mul(self):
        left=self.parse_unary()
        while self.peek().typ=='OP' and self.peek().val in ('*','/','%'):
            op=self.next().val
            right=self.parse_unary()
            left=('bin',op,left,right)
        return left

    def parse_unary(self):
        if self.match('OP','-'):
            operand=self.parse_unary()
            return ('un','neg',operand)
        return self.parse_postfix()

    def parse_postfix(self):
        left=self.parse_primary()
        while True:
            if self.match('OP','('):
                args=[]
                if not (self.peek().typ=='OP' and self.peek().val==')'):
                    args.append(self.parse_expr())
                    while self.match('OP',','):
                        args.append(self.parse_expr())
                self.expect('OP',')')
                left=('call',left,args)
            elif self.match('OP','['):
                idx=self.parse_expr()
                self.expect('OP',']')
                left=('index',left,idx)
            else:
                break
        return left

    def parse_primary(self):
        t=self.peek()
        if t.typ=='INT':
            self.next(); return ('lit','int',t.val)
        if t.typ=='STRING':
            self.next(); return ('lit','str',t.val)
        if t.typ=='true': self.next(); return ('lit','bool',True)
        if t.typ=='false': self.next(); return ('lit','bool',False)
        if t.typ=='nil': self.next(); return ('lit','nil',None)
        if t.typ=='IDENT':
            self.next(); return ('var',t.val)
        if t.typ=='OP' and t.val=='(':
            self.next(); e=self.parse_expr(); self.expect('OP',')'); return e
        if t.typ=='OP' and t.val=='[':
            self.next()
            elems=[]
            if not (self.peek().typ=='OP' and self.peek().val==']'):
                elems.append(self.parse_expr())
                while self.match('OP',','):
                    elems.append(self.parse_expr())
            self.expect('OP',']')
            return ('list',elems)
        if t.typ=='fn':
            self.next()
            self.expect('OP','(')
            params=self.parse_params()
            self.expect('OP',')')
            body=self.parse_block()
            return ('lambda',params,body)
        raise SyntaxError('unexpected token')

# ---------- runtime ----------
MIN_INT = -(1<<63)
MAX_INT = (1<<63)-1

class RuntimeErrorExc(Exception):
    def __init__(self,line,msg):
        self.line=line; self.msg=msg

def trunc_div(a,b):
    if b==0: raise ZeroDivisionError
    q=abs(a)//abs(b)
    if (a<0) ^ (b<0): q=-q
    return q

def check_overflow(v):
    if v<MIN_INT or v>MAX_INT:
        raise RuntimeErrorExc(0,'integer overflow')

class Env:
    def __init__(self,parent=None):
        self.parent=parent
        self.vars={}
    def get(self,name):
        if name in self.vars: return self.vars[name]
        if self.parent: return self.parent.get(name)
        raise RuntimeErrorExc(0,f'undefined variable {name}')
    def set(self,name,val):
        if name in self.vars:
            self.vars[name]=val; return
        if self.parent:
            self.parent.set(name,val); return
        raise RuntimeErrorExc(0,f'undefined variable {name}')
    def declare(self,name,val):
        self.vars[name]=val

class Func:
    __slots__=('params','body','closure')
    def __init__(self,params,body,closure):
        self.params=params; self.body=body; self.closure=closure

def truthy(v):
    if isinstance(v,bool): return v
    if v is None: return False
    if isinstance(v,int): return v!=0
    if isinstance(v,str): return len(v)!=0
    if isinstance(v,list): return len(v)!=0
    return True

def format_value(v,inside_list=False,seen=None):
    if seen is None: seen=set()
    if isinstance(v,list):
        if id(v) in seen:
            return '[...]'
        seen.add(id(v))
        parts=[format_value(e,True,seen) for e in v]
        seen.remove(id(v))
        return '['+', '.join(parts)+']'
    if isinstance(v,str):
        if inside_list:
            s=v.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t')
            return f'"{s}"'
        return v
    if isinstance(v,bool):
        return 'true' if v else 'false'
    if v is None:
        return 'nil'
    if isinstance(v,Func):
        return '<fn>'
    if isinstance(v,int):
        return str(v)
    return str(v)

class Interpreter:
    def __init__(self,stmts):
        self.stmts=stmts
        self.builtins=self.make_builtins()
        self.global_env=Env(parent=self.builtins)
        self.output=[]

    def make_builtins(self):
        env=Env()
        def mk(name,fn): env.declare(name,fn)
        mk('print',self.builtin_print)
        mk('str',self.builtin_str)
        mk('type',self.builtin_type)
        mk('len',self.builtin_len)
        mk('push',self.builtin_push)
        mk('pop',self.builtin_pop)
        mk('range',self.builtin_range)
        mk('slice',self.builtin_slice)
        return env

    def builtin_print(self,args):
        out=' '.join(format_value(a) for a in args)
        self.output.append(out+'\n')
    def builtin_str(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to str')
        return format_value(args[0])
    def builtin_type(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to type')
        v=args[0]
        if isinstance(v,int): return 'int'
        if isinstance(v,bool): return 'bool'
        if isinstance(v,str): return 'string'
        if isinstance(v,list): return 'list'
        if isinstance(v,Func): return 'function'
        if v is None: return 'nil'
        return 'unknown'
    def builtin_len(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to len')
        v=args[0]
        if isinstance(v,str): return len(v)
        if isinstance(v,list): return len(v)
        raise RuntimeErrorExc(0,'bad argument to len')
    def builtin_push(self,args):
        if len(args)!=2: raise RuntimeErrorExc(0,'bad argument to push')
        lst, val = args
        if not isinstance(lst,list): raise RuntimeErrorExc(0,'bad argument to push')
        lst.append(val)
        return None
    def builtin_pop(self,args):
        if len(args)!=1: raise RuntimeErrorExc(0,'bad argument to pop')
        lst=args[0]
        if not isinstance(lst,list) or len(lst)==0:
            raise RuntimeErrorExc(0,'bad argument to pop')
        return lst.pop()
    def builtin_range(self,args):
        if len(args)!=2: raise RuntimeErrorExc(0,'bad argument to range')
        a,b=args
        if not isinstance(a,int) or not isinstance(b,int): raise RuntimeErrorExc(0,'bad argument to range')
        res=[]
        if b>a:
            for i in range(a,b):
                res.append(i)
        return res
    def builtin_slice(self,args):
        if len(args)!=3: raise RuntimeErrorExc(0,'bad argument to slice')
        x,a,b=args
        if not isinstance(a,int) or not isinstance(b,int): raise RuntimeErrorExc(0,'bad argument to slice')
        if isinstance(x,str):
            if not (0<=a<=b<=len(x)): raise RuntimeErrorExc(0,'bad argument to slice')
            return x[a:b]
        if isinstance(x,list):
            if not (0<=a<=b<=len(x)): raise RuntimeErrorExc(0,'bad argument to slice')
            return x[a:b][:]
        raise RuntimeErrorExc(0,'bad argument to slice')

    def run(self):
        try:
            self.exec_stmts(self.stmts,self.global_env)
        except RuntimeErrorExc as e:
            sys.stdout.write(''.join(self.output))
            sys.stdout.write(f'error at line {e.line}: {e.msg}\n')
            return
        sys.stdout.write(''.join(self.output))

    def exec_stmts(self,stmts,env):
        for s in stmts:
            self.exec_stmt(s,env)

    def exec_stmt(self,s,env):
        typ=s[0]
        if typ=='let':
            _,name,expr=s
            val=self.eval_expr(expr,env)
            env.declare(name,val)
        elif typ=='fn_decl':
            _,name,params,body=s
            fn=Func(params,body,env)
            env.declare(name,fn)
        elif typ=='if':
            _,cond,then_block,else_branch=s
            if truthy(self.eval_expr(cond,env)):
                self.exec_block(then_block,env)
            elif else_branch:
                if else_branch[0]=='block':
                    self.exec_block(else_branch,env)
                else:
                    self.exec_stmt(else_branch,env)
        elif typ=='while':
            _,cond,body=s
            while True:
                if not truthy(self.eval_expr(cond,env)):
                    break
                try:
                    self.exec_block(body,env)
                except ContinueException:
                    continue
                except BreakException:
                    break
        elif typ=='for':
            _,var,iterable_expr,body=s
            lst=self.eval_expr(iterable_expr,env)
            if not isinstance(lst,list):
                raise RuntimeErrorExc(0,f'cannot iterate {self.type_name(lst)}')
            i=0
            while i < len(lst):
                iter_env=Env(parent=env)
                iter_env.declare(var,lst[i])
                try:
                    self.exec_block(body,iter_env)
                except ContinueException:
                    i+=1
                    continue
                except BreakException:
                    break
                i+=1
        elif typ=='return':
            _,expr=s
            val=None if expr is None else self.eval_expr(expr,env)
            raise ReturnException(val)
        elif typ=='break':
            raise BreakException()
        elif typ=='continue':
            raise ContinueException()
        elif typ=='assign':
            _,left,right=s
            val=self.eval_expr(right,env)
            self.assign_lvalue(left,val,env)
        elif typ=='expr':
            _,expr=s
            self.eval_expr(expr,env)

    def exec_block(self,block,env):
        if block[0]=='block':
            new_env=Env(parent=env)
            self.exec_stmts(block[1],new_env)
        else:
            self.exec_stmt(block,env)

    def exec_stmts_in_env(self,stmts,env):
        for s in stmts:
            self.exec_stmt(s,env)

    def assign_lvalue(self,node,val,env):
        if node[0]=='var':
            env.set(node[1],val)
        elif node[0]=='index':
            _,obj,idx=node
            objv=self.eval_expr(obj,env)
            idxv=self.eval_expr(idx,env)
            if not isinstance(objv,list):
                raise RuntimeErrorExc(0,f'cannot assign into {self.type_name(objv)}')
            if not isinstance(idxv,int):
                raise RuntimeErrorExc(0,f'cannot index list with {self.type_name(idxv)}')
            if not 0<=idxv<len(objv):
                raise RuntimeErrorExc(0,f'index {idxv} out of range for length {len(objv)}')
            objv[idxv]=val

    def eval_expr(self,node,env):
        typ=node[0]
        if typ=='lit':
            _,t,v=node
            if t=='int': return v
            if t=='bool': return v
            if t=='str': return v
            if t=='nil': return None
        if typ=='var':
            name=node[1]
            try:
                return env.get(name)
            except:
                raise RuntimeErrorExc(0,f'undefined variable {name}')
        if typ=='un':
            _,op,operand=node
            v=self.eval_expr(operand,env)
            if op=='not':
                return not truthy(v)
            if op=='neg':
                if not isinstance(v,int):
                    raise RuntimeErrorExc(0,f'cannot apply - to {self.type_name(v)}')
                r=-v
                check_overflow(r)
                return r
        if typ=='bin':
            _,op,l,r=node
            left=self.eval_expr(l,env)
            right=self.eval_expr(r,env)
            if op=='or':
                return left if truthy(left) else right
            if op=='and':
                return left if not truthy(left) else right
            if op=='+':
                if isinstance(left,int) and isinstance(right,int):
                    res=left+right
                    check_overflow(res)
                    return res
                if isinstance(left,str) and isinstance(right,str):
                    return left+right
                if isinstance(left,list) and isinstance(right,list):
                    return left+right
                raise RuntimeErrorExc(0,f'cannot apply + to {self.type_name(left)} and {self.type_name(right)}')
            if op=='-':
                if not isinstance(left,int) or not isinstance(right,int):
                    raise RuntimeErrorExc(0,f'cannot apply - to {self.type_name(left)} and {self.type_name(right)}')
                res=left-right
                check_overflow(res)
                return res
            if op=='*':
                if not isinstance(left,int) or not isinstance(right,int):
                    raise RuntimeErrorExc(0,f'cannot apply * to {self.type_name(left)} and {self.type_name(right)}')
                res=left*right
                check_overflow(res)
                return res
            if op=='/':
                if not isinstance(left,int) or not isinstance(right,int):
                    raise RuntimeErrorExc(0,f'cannot apply / to {self.type_name(left)} and {self.type_name(right)}')
                if right==0:
                    raise RuntimeErrorExc(0,'division by zero')
                res=trunc_div(left,right)
                check_overflow(res)
                return res
            if op=='%':
                if not isinstance(left,int) or not isinstance(right,int):
                    raise RuntimeErrorExc(0,f'cannot apply % to {self.type_name(left)} and {self.type_name(right)}')
                if right==0:
                    raise RuntimeErrorExc(0,'division by zero')
                q=trunc_div(left,right)
                res=left-q*right
                check_overflow(res)
                return res
            if op in ('==','!='):
                eq=self.values_equal(left,right)
                return eq if op=='==' else not eq
            if op in ('<','<=','>','>='):
                if (isinstance(left,int) and isinstance(right,int)) or (isinstance(left,str) and isinstance(right,str)):
                    if op=='<': return left<right
                    if op=='<=': return left<=right
                    if op=='>': return left>right
                    if op=='>=': return left>=right
                raise RuntimeErrorExc(0,f'cannot apply {op} to {self.type_name(left)} and {self.type_name(right)}')
        if typ=='call':
            _,func,args=node
            fv=self.eval_expr(func,env)
            argvals=[self.eval_expr(a,env) for a in args]
            if isinstance(fv,Func):
                if len(argvals)!=len(fv.params):
                    raise RuntimeErrorExc(0,f'expected {len(fv.params)} arguments, got {len(argvals)}')
                call_env=Env(parent=fv.closure)
                for p,v in zip(fv.params,argvals):
                    call_env.declare(p,v)
                try:
                    self.exec_stmts_in_env(fv.body[1],call_env)
                    return None
                except ReturnException as e:
                    return e.value
            if callable(fv):
                return fv(argvals)
            raise RuntimeErrorExc(0,f'cannot call {self.type_name(fv)}')
        if typ=='index':
            _,obj,idx=node
            ov=self.eval_expr(obj,env)
            iv=self.eval_expr(idx,env)
            if isinstance(ov,list):
                if not isinstance(iv,int): raise RuntimeErrorExc(0,f'cannot index list with {self.type_name(iv)}')
                if not 0<=iv<len(ov): raise RuntimeErrorExc(0,f'index {iv} out of range for length {len(ov)}')
                return ov[iv]
            if isinstance(ov,str):
                if not isinstance(iv,int): raise RuntimeErrorExc(0,f'cannot index string with {self.type_name(iv)}')
                if not 0<=iv<len(ov): raise RuntimeErrorExc(0,f'index {iv} out of range for length {len(ov)}')
                return ov[iv]
            raise RuntimeErrorExc(0,f'cannot index {self.type_name(ov)} with {self.type_name(iv)}')
        if typ=='list':
            elems=[self.eval_expr(e,env) for e in node[1]]
            return elems
        if typ=='lambda':
            _,params,body=node
            return Func(params,body,env)
        raise RuntimeErrorExc(0,'unknown expr')

    def type_name(self,v):
        if isinstance(v,int): return 'int'
        if isinstance(v,bool): return 'bool'
        if isinstance(v,str): return 'string'
        if isinstance(v,list): return 'list'
        if isinstance(v,Func): return 'function'
        if v is None: return 'nil'
        return 'unknown'

    def values_equal(self,a,b):
        if type(a)!=type(b):
            if isinstance(a,bool) and isinstance(b,int): return False
            if isinstance(b,bool) and isinstance(a,int): return False
            return False
        if isinstance(a,int): return a==b
        if isinstance(a,bool): return a==b
        if isinstance(a,str): return a==b
        if a is None: return True
        if isinstance(a,list):
            if len(a)!=len(b): return False
            return all(self.values_equal(x,y) for x,y in zip(a,b))
        if isinstance(a,Func):
            return a is b
        return a==b

