import os, sys, zlib, base64
from pathlib import Path

def quote_string(s: str) -> str:
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '\\':
            out.append('\\\\')
        elif ch == '"':
            out.append('\\"')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20 or (0x7F <= o <= 0x9F):
            out.append(f'\\u{o:04x}')
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)

# ---------- charset helpers ----------
def decode_charset(data: bytes, charset: str) -> str:
    cs = charset.lower()
    try:
        if cs == 'us-ascii':
            return data.decode('ascii', errors='replace')
        if cs == 'utf-8':
            return data.decode('utf-8', errors='replace')
        if cs == 'iso-8859-1':
            return data.decode('iso-8859-1', errors='replace')
        if cs == 'windows-1252':
            return data.decode('windows-1252', errors='replace')
    except Exception:
        pass
    # fallback
    try:
        return data.decode('latin-1', errors='replace')
    except Exception:
        return data.decode('utf-8', errors='replace')

# ---------- encoded-word ----------
def _normalize_cs(cs):
    if '*' in cs:
        cs = cs.split('*',1)[0]
    return cs.lower()

def _decode_q_word(txt):
    out = bytearray()
    i = 0
    n = len(txt)
    while i < n:
        c = txt[i]
        if c == '_':
            out.append(0x20)
            i += 1
        elif c == '=' and i+2 < n:
            try:
                out.append(int(txt[i+1:i+3],16))
                i += 3
                continue
            except:
                out.append(ord('='))
                i += 1
        else:
            out.append(ord(c))
            i += 1
    return bytes(out)

def decode_encoded_words(s: str) -> str:
    out = []
    i = 0
    n = len(s)
    while i < n:
        if s[i:i+2] == '=?':
            # try parse one word
            j = i+2
            # charset
            cs_start = j
            while j < n and s[j] != '?' and s[j] not in ' \t':
                j += 1
            if j >= n or s[j] != '?':
                out.append(s[i])
                i += 1
                continue
            charset_raw = s[cs_start:j]
            j += 1
            if j >= n:
                out.append(s[i])
                i += 1
                continue
            enc = s[j]
            j += 1
            if j >= n or s[j] != '?':
                out.append(s[i])
                i += 1
                continue
            j += 1
            txt_start = j
            # find ?=
            k = s.find('?', txt_start)
            if k == -1 or k+1 >= n or s[k+1] != '=':
                out.append(s[i])
                i += 1
                continue
            enc_text = s[txt_start:k]
            word_end = k+2
            # collect run
            run_words = [(charset_raw, enc, enc_text)]
            run_cs = charset_raw
            cur_pos = word_end
            # skip spaces/tabs
            t = cur_pos
            while t < n and s[t] in ' \t':
                t += 1
            while t < n and s[t:t+2] == '=?':
                # parse next
                tj = t+2
                cs2_start = tj
                while tj < n and s[tj] != '?' and s[tj] not in ' \t':
                    tj += 1
                if tj >= n or s[tj] != '?':
                    break
                charset2_raw = s[cs2_start:tj]
                tj += 1
                if tj >= n:
                    break
                enc2 = s[tj]
                tj += 1
                if tj >= n or s[tj] != '?':
                    break
                tj += 1
                txt2_start = tj
                k2 = s.find('?', txt2_start)
                if k2 == -1 or k2+1 >= n or s[k2+1] != '=':
                    break
                enc_text2 = s[txt2_start:k2]
                word_end2 = k2+2
                if _normalize_cs(charset2_raw) == _normalize_cs(run_cs):
                    run_words.append((charset2_raw, enc2, enc_text2))
                    cur_pos = word_end2
                    t = cur_pos
                    while t < n and s[t] in ' \t':
                        t += 1
                    continue
                else:
                    break
            # decode run
            b = bytearray()
            for cr, e, et in run_words:
                if e.lower() == 'b':
                    try:
                        b.extend(base64.b64decode(et, validate=False))
                    except:
                        pass
                else:
                    b.extend(_decode_q_word(et))
            charset_use = run_cs.split('*',1)[0]
            try:
                decoded = b.decode(charset_use, errors='replace')
            except:
                decoded = b.decode('latin-1', errors='replace')
            out.append(decoded)
            i = t
            continue
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)

# ---------- header / content-type parsing ----------
def parse_params(param_str):
    params = {}
    parts = param_str.split(';')
    for p in parts[1:]:
        p = p.strip()
        if not p or '=' not in p:
            continue
        k, v = p.split('=',1)
        k = k.strip().lower()
        v = v.strip()
        if v.startswith('"') and v.endswith('"'):
            v = v[1:-1]
            # unescape \x
            v2 = ''
            i = 0
            while i < len(v):
                if v[i] == '\\' and i+1 < len(v):
                    v2 += v[i+1]
                    i += 2
                else:
                    v2 += v[i]
                    i += 1
            v = v2
        params[k] = v
    return params

def parse_content_type(val):
    if not val:
        return {'type':'text','subtype':'plain','params':{}}
    parts = val.split(';',1)
    media = parts[0].strip()
    if '/' in media:
        typ, sub = media.split('/',1)
    else:
        typ, sub = 'text','plain'
    typ = typ.lower()
    sub = sub.lower()
    params = {}
    if len(parts) > 1:
        params = parse_params(val)
    return {'type':typ,'subtype':sub,'params':params}

def get_headers_and_body_start(lines, start):
    i = start
    raw = []
    while i < len(lines):
        line = lines[i]
        if line == b'':
            body_start = i+1
            break
        raw.append(line)
        i += 1
    else:
        body_start = i
    # unfold
    unfolded = []
    cur = b''
    for line in raw:
        if cur == b'':
            cur = line
        else:
            if line.startswith(b' ') or line.startswith(b'\t'):
                cur += line
            else:
                unfolded.append(cur)
                cur = line
    if cur:
        unfolded.append(cur)
    headers = {}
    for ul in unfolded:
        if b':' not in ul:
            continue
        idx = ul.find(b':')
        name = ul[:idx].decode('ascii', errors='replace')
        value = ul[idx+1:].decode('ascii', errors='replace')
        value = value.strip(' \t')
        headers[name.lower()] = value
    return headers, body_start

def is_delimiter_line(line, b):
    if not line.startswith(b'--' + b):
        return False, False
    rest = line[len(b'--')+len(b):]
    if rest.startswith(b'--'):
        rest2 = rest[2:]
        if rest2 == b'' or set(rest2) <= set(b' \t'):
            return True, True
        return False, False
    if rest == b'' or set(rest) <= set(b' \t'):
        return True, False
    return False, False

def decode_transfer(data: bytes, encoding: str):
    enc = (encoding or '7bit').lower()
    if enc in ('7bit','8bit','binary'):
        return data
    if enc == 'base64':
        # keep only base64 chars
        filt = bytes(c for c in data if c in b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
        # stop at first =
        # simple filter
        try:
            return base64.b64decode(filt, validate=False)
        except:
            return b''
    if enc == 'quoted-printable':
        # data is raw bytes with line breaks
        # split lines
        # we assume data already contains \n line breaks
        # First remove trailing spaces/tabs per line
        # We'll process as text
        try:
            txt = data.decode('latin-1')
        except:
            txt = data.decode('utf-8', errors='replace')
        lines = txt.split('\n')
        # soft line break handling
        merged = []
        buf = ''
        for ln in lines:
            # strip trailing spaces/tabs
            stripped = ln.rstrip(' \t')
            if stripped.endswith('='):
                buf += stripped[:-1]
                continue
            else:
                buf += stripped
                merged.append(buf)
                buf = ''
        if buf:
            merged.append(buf)
        out = bytearray()
        for ln in merged:
            i = 0
            L = len(ln)
            while i < L:
                if ln[i] == '=' and i+2 < L:
                    try:
                        out.append(int(ln[i+1:i+3],16))
                        i += 3
                        continue
                    except:
                        pass
                # literal =
                if ln[i] == '=':
                    out.append(ord('='))
                    i += 1
                    continue
                out.append(ord(ln[i]))
                i += 1
        return bytes(out)
    return data

