#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    s: &'a str,
    pos: usize,
}
impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self { Self { s, pos: 0 } }
    fn peek(&self) -> Option<char> { self.s[self.pos..].chars().next() }
    fn next_char(&mut self) -> Option<char> {
        let ch = self.peek()?;
        let len = ch.len_utf8();
        self.pos += len;
        Some(ch)
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() { self.next_char(); } else { break; }
        }
    }
    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => self.parse_string().map(JsonValue::String),
            Some('t') => { self.expect_literal("true"); Ok(JsonValue::Bool(true)) }
            Some('f') => { self.expect_literal("false"); Ok(JsonValue::Bool(false)) }
            Some('n') => { self.expect_literal("null"); Ok(JsonValue::Null) }
            Some(c) if c == '-' || c.is_ascii_digit() => self.parse_number().map(JsonValue::Number),
            _ => Err(()),
        }
    }
    fn expect_literal(&mut self, lit: &str) -> Result<(), ()> {
        for ch in lit.chars() {
            if self.next_char() != Some(ch) { return Err(()); }
        }
        Ok(())
    }
    fn parse_string(&mut self) -> Result<String, ()> {
        if self.next_char() != Some('"') { return Err(()); }
        let mut out = String::new();
        loop {
            let ch = self.next_char().ok_or(())?;
            if ch == '"' { return Ok(out); }
            if ch == '\\' {
                let esc = self.next_char().ok_or(())?;
                match esc {
                    '"' => out.push('"'),
                    '\\' => out.push('\\'),
                    '/' => out.push('/'),
                    'b' => out.push('\x08'),
                    'f' => out.push('\x0c'),
                    'n' => out.push('\n'),
                    'r' => out.push('\r'),
                    't' => out.push('\t'),
                    'u' => {
                        let mut hex = String::new();
                        for _ in 0..4 { hex.push(self.next_char().ok_or(())?); }
                        let code = u32::from_str_radix(&hex, 16).map_err(|_| ())?;
                        if let Some(c) = std::char::from_u32(code) { out.push(c); } else { return Err(()); }
                    }
                    _ => return Err(()),
                }
            } else {
                out.push(ch);
            }
        }
    }
    fn parse_number(&mut self) -> Result<f64, ()> {
        let start = self.pos;
        if let Some('-') = self.peek() { self.next_char(); }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() { self.next_char(); } else { break; }
        }
        if self.peek() == Some('.') { self.next_char(); while let Some(c)=self.peek(){ if c.is_ascii_digit(){self.next_char();} else {break;}}}
        if let Some(c)=self.peek(){ if c=='e'||c=='E'{ self.next_char(); if let Some(s)=self.peek(){ if s=='+'||s=='-' {self.next_char();}} while let Some(c)=self.peek(){ if c.is_ascii_digit(){self.next_char();} else {break;}}}}
        let num_str = &self.s[start..self.pos];
        num_str.parse::<f64>().map_err(|_|())
    }
    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        if self.next_char()!=Some('{') { return Err(()); }
        self.skip_ws();
        let mut kvs = Vec::new();
        let mut seen = std::collections::HashSet::new();
        if self.peek()==Some('}') { self.next_char(); return Ok(JsonValue::Object(kvs)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            if !seen.insert(key.clone()) { return Err(()); } // duplicate
            self.skip_ws();
            if self.next_char()!=Some(':') { return Err(()); }
            let val = self.parse_value()?;
            kvs.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.next_char(); }
                Some('}') => { self.next_char(); break; }
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Object(kvs))
    }
    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        if self.next_char()!=Some('[') { return Err(()); }
        self.skip_ws();
        let mut arr = Vec::new();
        if self.peek()==Some(']') { self.next_char(); return Ok(JsonValue::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.next_char(); }
                Some(']') => { self.next_char(); break; }
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Array(arr))
    }
}

fn get_json_field(obj: &JsonValue, key: &str) -> Option<&JsonValue> {
    if let JsonValue::Object(kvs) = obj {
        for (k,v) in kvs { if k==key { return Some(v); } }
    }
    None
}

fn base64url_decode(s: &str) -> Result<Vec<u8>, ()> {
    if s.is_empty() { return Err(()); }
    if s.len()%4==1 { return Err(()); }
    for c in s.chars() {
        match c {
            'A'..='Z'|'a'..='z'|'0'..='9'|'-'|'_' => {},
            _ => return Err(()),
        }
    }
    let mut vals = Vec::new();
    for c in s.chars() {
        let v = match c {
            'A'..='Z' => c as u8 - b'A',
            'a'..='z' => c as u8 - b'a' + 26,
            '0'..='9' => c as u8 - b'0' + 52,
            '-' => 62,
            '_' => 63,
            _ => return Err(()),
        };
        vals.push(v);
    }
    let mut out = Vec::new();
    let mut i = 0;
    while i < vals.len() {
        let n = std::cmp::min(4, vals.len() - i);
        let v0 = vals[i];
        let v1 = if i+1 < vals.len() { vals[i+1] } else { 0 };
        let v2 = if i+2 < vals.len() { vals[i+2] } else { 0 };
        let v3 = if i+3 < vals.len() { vals[i+3] } else { 0 };
        match n {
            4 => {
                out.push((v0<<2)|(v1>>4));
                out.push((v1<<4)|(v2>>2));
                out.push((v2<<6)|(v3));
            }
            3 => {
                out.push((v0<<2)|(v1>>4));
                out.push((v1<<4)|(v2>>2));
            }
            2 => {
                out.push((v0<<2)|(v1>>4));
            }
            _ => {}
        }
        i += 4;
    }
    Ok(out)
}

fn sha256(input: &[u8]) -> [u8;32] {
