fn hmac(key: &[u8], data: &[u8], hash_fn: fn(&[u8]) -> Vec<u8>, block: usize) -> Vec<u8> {
    let mut k = key.to_vec();
    let hash_len = hash_fn(&[]).len();
    if k.len() > block { k = hash_fn(&k); }
    if k.len() < block { k.resize(block, 0); }
    let mut ipad = vec![0u8; block];
    let mut opad = vec![0u8; block];
    for i in 0..block { ipad[i]=k[i]^0x36; opad[i]=k[i]^0x5c; }
    let mut inner = Vec::new(); inner.extend_from_slice(&ipad); inner.extend_from_slice(data);
    let inner_hash = hash_fn(&inner);
    let mut outer = Vec::new(); outer.extend_from_slice(&opad); outer.extend_from_slice(&inner_hash);
    hash_fn(&outer)
}
fn hmac_sha256(key:&[u8], data:&[u8])->Vec<u8>{ hmac(key,data,|d|sha256(d).to_vec(),64) }
fn hmac_sha384(key:&[u8], data:&[u8])->Vec<u8>{ hmac(key,data,|d|{ let mut b=sha512(d); b.truncate(48); b },128) }
fn hmac_sha512(key:&[u8], data:&[u8])->Vec<u8>{ hmac(key,data,|d|sha512(d).to_vec(),128) }

fn main() {
    let args: Vec<String>=env::args().collect();
    if args.len()<2 { return; }
    let dir=args[1].as_str();
    let cfg_path=Path::new(dir).join("config.json");
    let tok_path=Path::new(dir).join("tokens.txt");
    let cfg_str=fs::read_to_string(cfg_path).unwrap_or_default();
    let mut cfg_parser=JsonParser::new(&cfg_str);
    let cfg_val=match cfg_parser.parse_value() { Ok(v)=>v, Err(_)=>return };
    let cfg_obj=match cfg_val { JsonValue::Object(o)=>o, _=>return };
    let now = get_json_field(&JsonValue::Object(cfg_obj.clone()), "now").and_then(|v| if let JsonValue::Number(n)=v {Some(*n)} else {None}).unwrap_or(0.0);
    let leeway = get_json_field(&JsonValue::Object(cfg_obj.clone()), "leeway").and_then(|v| if let JsonValue::Number(n)=v {Some(*n)} else {None}).unwrap_or(0.0);
    let issuer = get_json_field(&JsonValue::Object(cfg_obj.clone()), "issuer").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap_or_default();
    let audience = get_json_field(&JsonValue::Object(cfg_obj.clone()), "audience").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None}).unwrap_or_default();
    let keys_raw = get_json_field(&JsonValue::Object(cfg_obj.clone()), "keys").and_then(|v| if let JsonValue::Array(a)=v {Some(a)} else {None}).unwrap_or(&vec![]);
    let mut key_map=HashMap::new();
    for kv in keys_raw {
        if let JsonValue::Object(o)=kv {
            let kid = get_json_field(&JsonValue::Object(o.clone()), "kid").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None});
            let alg = get_json_field(&JsonValue::Object(o.clone()), "alg").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None});
            let k_enc = get_json_field(&JsonValue::Object(o.clone()), "k").and_then(|v| if let JsonValue::String(s)=v {Some(s.clone())} else {None});
            if let (Some(kid), Some(alg), Some(k_enc))=(kid,alg,k_enc) {
                if let Ok(secret)=base64url_decode(&k_enc) {
                    key_map.insert(kid, (alg, secret));
                }
            }
        }
    }
    let tok_str=fs::read_to_string(tok_path).unwrap_or_default();
    let mut lines=Vec::new();
    for l in tok_str.lines() {
        let t=l.trim_matches(|c| c==' ' || c=='\t');
        if t.is_empty() { continue; }
        lines.push(t.to_string());
    }
    let mut valid_cnt=0usize;
    let mut invalid_cnt=0usize;
    for (idx, token) in lines.iter().enumerate() {
        let n=idx+1;
        let parts: Vec<&str>=token.split('.').collect();
        let mut result=String::new();
        let mut sub_out=String::new();
        let mut scopes_out=String::new();
        if parts.len()!=3 || parts.iter().any(|p| p.is_empty()) {
            result.push_str(&format!("{}: MALFORMED", n));
        } else {
            let header_seg=parts[0]; let payload_seg=parts[1]; let sig_seg=parts[2];
            let mut malformed=false;
            for seg in [header_seg, payload_seg, sig_seg] {
                if seg.len()%4==1 { malformed=true; }
                if base64url_decode(seg).is_err() { malformed=true; }
            }
            if !malformed {
                let hdr_bytes=match base64url_decode(header_seg) { Ok(b)=>b, Err(_)=>{ malformed=true; vec![] } };
                let pay_bytes=match base64url_decode(payload_seg) { Ok(b)=>b, Err(_)=>{ malformed=true; vec![] } };
                let hdr_str=String::from_utf8(hdr_bytes).ok();
                let pay_str=String::from_utf8(pay_bytes).ok();
                if hdr_str.is_none() || pay_str.is_none() { malformed=true; }
                let (hdr_obj, pay_obj) = if !malformed {
                    let mut p=JsonParser::new(hdr_str.as_ref().unwrap());
                    let hv=match p.parse_value(){ Ok(v)=>v, Err(_)=>{ malformed=true; JsonValue::Object(vec![]) } };
                    let mut p2=JsonParser::new(pay_str.as_ref().unwrap());
                    let pv=match p2.parse_value(){ Ok(v)=>v, Err(_)=>{ malformed=true; JsonValue::Object(vec![]) } };
                    (hv,pv)
                } else { (JsonValue::Object(vec![]), JsonValue::Object(vec![])) };
                if malformed {
                    result.push_str(&format!("{}: MALFORMED", n));
                } else {
                    let hdr_is_obj = matches!(hdr_obj, JsonValue::Object(_));
                    let pay_is_obj = matches!(pay_obj, JsonValue::Object(_));
                    if !hdr_is_obj || !pay_is_obj {
                        result.push_str(&format!("{}: MALFORMED", n));
                    } else {
                        let alg_val = get_json_field(&hdr_obj, "alg");
                        let alg_str = match alg_val { Some(JsonValue::String(s))=>Some(s.clone()), _=>None };
                        let alg_ok = matches!(alg_str.as_deref(), Some("HS256"|"HS384"|"HS512"));
                        if !alg_ok {
                            result.push_str(&format!("{}: UNSUPPORTED_ALG", n));
                        } else {
                            let kid_val = get_json_field(&hdr_obj, "kid");
                            let kid_str = match kid_val { Some(JsonValue::String(s))=>Some(s.clone()), _=>None };
                            let kid_ok = kid_str.is_some() && key_map.contains_key(kid_str.as_ref().unwrap());
                            if !kid_ok {
                                result.push_str(&format!("{}: UNKNOWN_KEY", n));
                            } else {
                                let kid = kid_str.unwrap();
                                let (key_alg, key_secret)=key_map.get(&kid).unwrap().clone();
                                if key_alg != alg_str.unwrap() {
                                    result.push_str(&format!("{}: ALG_MISMATCH", n));
                                } else {
                                    let signing_input = format!("{}.{}", header_seg, payload_seg);
                                    let sig_bytes = match base64url_decode(sig_seg) { Ok(b)=>b, Err(_)=>{ result.push_str(&format!("{}: BAD_SIGNATURE", n)); } };
                                    let sig_ok = if sig_bytes.is_empty() { false } else {
                                        let expected = match alg_str.as_deref() {
                                            Some("HS256") => hmac_sha256(&key_secret, signing_input.as_bytes()),
                                            Some("HS384") => hmac_sha384(&key_secret, signing_input.as_bytes()),
                                            Some("HS512") => hmac_sha512(&key_secret, signing_input.as_bytes()),
                                            _ => vec![],
                                        };
                                        sig_bytes == expected
                                    };
                                    if !sig_ok {
                                        result.push_str(&format!("{}: BAD_SIGNATURE", n));
                                    } else {
                                        let exp_val = get_json_field(&pay_obj, "exp");
                                        let exp_num = match exp_val { Some(JsonValue::Number(n))=>Some(*n), _=>None };
                                        let mut fail=false;
                                        if let Some(exp)=exp_num {
                                            if now >= exp + leeway { result.push_str(&format!("{}: EXPIRED", n)); fail=true; }
                                        }
                                        if !fail {
                                            let nbf_val = get_json_field(&pay_obj, "nbf");
                                            if let Some(JsonValue::Number(nbf))=nbf_val {
                                                if now + leeway < *nbf { result.push_str(&format!("{}: NOT_YET_VALID", n)); fail=true; }
                                            }
                                        }
                                        if !fail {
                                            let iss_val = get_json_field(&pay_obj, "iss");
                                            let iss_str = match iss_val { Some(JsonValue::String(s))=>Some(s.clone()), _=>None };
                                            if iss_str.as_deref()!=Some(&issuer) { result.push_str(&format!("{}: BAD_ISSUER", n)); fail=true; }
                                        }
                                        if !fail {
                                            let aud_val = get_json_field(&pay_obj, "aud");
                                            let aud_ok = match aud_val {
                                                None => false,
                                                Some(JsonValue::String(s)) => s==audience,
                                                Some(JsonValue::Array(arr)) => arr.iter().any(|v| matches!(v, JsonValue::String(s) if s==&audience)),
                                                _ => false,
                                            };
                                            if !aud_ok { result.push_str(&format!("{}: BAD_AUDIENCE", n)); fail=true; }
                                        }
                                        if !fail {
                                            let sub_val = get_json_field(&pay_obj, "sub");
                                            let sub_str = match sub_val { Some(JsonValue::String(s))=>s.clone(), _=>"".to_string() };
                                            sub_out=sub_str;
                                            let scope_val = get_json_field(&pay_obj, "scope");
                                            let scope_str = match scope_val { Some(JsonValue::String(s))=>s.clone(), _=>"".to_string() };
                                            let mut parts_sc: Vec<&str> = scope_str.split(' ').filter(|s| !s.is_empty()).collect();
                                            parts_sc.sort();
                                            parts_sc.dedup();
                                            scopes_out=parts_sc.join(",");
                                            result.push_str(&format!("{}: VALID sub={} scope={}", n, sub_out, scopes_out));
                                            valid_cnt+=1;
                                        } else {
                                            invalid_cnt+=1;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                result.push_str(&format!("{}: MALFORMED", n));
            }
        }
        if result.is_empty() {
            result.push_str(&format!("{}: MALFORMED", n));
        }
        if !result.contains("VALID") {
            invalid_cnt+=1;
        }
        println!("{}", result);
    }
    println!();
    println!("valid={} invalid={}", valid_cnt, invalid_cnt);
}

import Foundation

// MARK: - Lexer

enum TokenKind {
    case int(Int64)
    case string(String)
    case ident(String)
    case keyword(String)
    case op(String)
    case punct(String)
    case eof
}

struct Token {
    var kind: TokenKind
    var line: Int
    var col: Int
}

final class Lexer {
    let src: String
    var idx = 0
    var line = 1
    var col = 1
    var chars: [Character] { Array(src) }

    init(_ src: String) { self.src = src }

    func nextToken() -> Token {
        skipSpaceAndComment()
        guard idx < chars.count else { return Token(kind: .eof, line: line, col: col) }
        let startLine = line
        let startCol = col
        let c = chars[idx]
        if c == '"' {
            idx += 1; col += 1
            var s = ""
            while idx < chars.count {
                let ch = chars[idx]
                if ch == '"' { idx += 1; col += 1; break }
                if ch == "\\" {
                    idx += 1; col += 1
                    guard idx < chars.count else { break }
                    let esc = chars[idx]
                    switch esc {
                    case "n": s += "\n"
                    case "t": s += "\t"
                    case "\"": s += "\""
                    case "\\": s += "\\"
                    default: s += String(esc)
                    }
                    idx += 1; col += 1
                } else {
                    if ch == "\n" { line += 1; col = 1 } else { col += 1 }
                    s.append(ch)
                    idx += 1
                }
            }
            return Token(kind: .string(s), line: startLine, col: startCol)
        }
        if c.isNumber {
            var num = ""
            while idx < chars.count && chars[idx].isNumber {
                num.append(chars[idx])
                idx += 1; col += 1
            }
            let v = Int64(num) ?? 0
            return Token(kind: .int(v), line: startLine, col: startCol)
        }
        if c.isLetter || c == "_" {
            var id = ""
            while idx < chars.count && (chars[idx].isLetter || chars[idx].isNumber || chars[idx] == "_") {
                id.append(chars[idx])
                idx += 1; col += 1
            }
            let keywords: Set<String> = ["let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil"]
            if keywords.contains(id) {
                return Token(kind: .keyword(id), line: startLine, col: startCol)
            } else {
                return Token(kind: .ident(id), line: startLine, col: startCol)
            }
        }
        // operators / punct
        let two = idx+1 < chars.count ? String([c, chars[idx+1]]) : ""
        let ops = ["==","!=","<=",">="]
        if ops.contains(two) {
            idx += 2; col += 2
            return Token(kind: .op(two), line: startLine, col: startCol)
        }
        let one = String(c)
        let singleOps = ["=","+","-","*","/","%","<",">","(",")","[","]","{","}",";",",","."]
        if singleOps.contains(one) {
            idx += 1; col += 1
            if one == "(" || one == ")" || one == "[" || one == "]" || one == "{" || one == "}" || one == ";" || one == "," {
                return Token(kind: .punct(one), line: startLine, col: startCol)
            } else {
                return Token(kind: .op(one), line: startLine, col: startCol)
            }
        }
        // unknown
        idx += 1; col += 1
        return Token(kind: .op(String(c)), line: startLine, col: startCol)
    }

    private func skipSpaceAndComment() {
        while idx < chars.count {
            let c = chars[idx]
            if c == " " || c == "\t" || c == "\r" {
                idx += 1; col += 1
            } else if c == "\n" {
                idx += 1; line += 1; col = 1
            } else if c == "#" {
                while idx < chars.count && chars[idx] != "\n" { idx += 1 }
            } else { break }
        }
    }
}

// MARK: - AST

enum BinOp { case or, and, eq, ne, lt, le, gt, ge, add, sub, mul, div, mod }
enum UnOp { case not, neg }

indirect enum Expr {
    case int(Int64)
    case str(String)
    case bool(Bool)
    case nilVal
    case ident(String)
    case binary(BinOp, Expr, Expr)
    case unary(UnOp, Expr)
    case call(Expr, [Expr])
    case index(Expr, Expr)
    case lambda([String], Block)
    case list([Expr])
}

struct Block { var stmts: [Stmt] }

enum Stmt {
    case letDecl(String, Expr)
    case fnDecl(String, [String], Block)
    case ifStmt(Expr, Block, Stmt?)
    case whileStmt(Expr, Block)
    case forStmt(String, Expr, Block)
    case ret(Expr?)
    case brk
    case cont
    case assign(String, Expr)
    case indexAssign(Expr, Expr, Expr)
    case exprStmt(Expr)
}

// MARK: - Parser

final class Parser {
    var tokens: [Token]
    var pos = 0
    init(_ tokens: [Token]) { self.tokens = tokens }
    var cur: Token { tokens[pos] }
    func peek(_ off: Int = 0) -> Token { tokens[min(pos+off, tokens.count-1)] }
    func advance() { if pos < tokens.count-1 { pos += 1 } }
    func matchKeyword(_ kw: String) -> Bool { if case .keyword(let s) = cur.kind, s == kw { advance(); return true }; return false }
    func matchIdent() -> String? { if case .ident(let s) = cur.kind { advance(); return s }; return nil }
    func matchOp(_ op: String) -> Bool { if case .op(let s) = cur.kind, s == op { advance(); return true }; return false }
    func matchPunct(_ p: String) -> Bool { if case .punct(let s) = cur.kind, s == p { advance(); return true }; return false }
    func expectKeyword(_ kw: String) { if !matchKeyword(kw) { fatalError("expected \(kw)") } }
    func expectPunct(_ p: String) { if !matchPunct(p) { fatalError("expected \(p)") } }
    func expectOp(_ o: String) { if !matchOp(o) { fatalError("expected \(o)") } }

    func parseProgram() -> [Stmt] {
        var stmts: [Stmt] = []
        while !isEOF() { stmts.append(parseStmt()) }
        return stmts
    }

    func isEOF() -> Bool { if case .eof = cur.kind { return true }; return false }

    func parseStmt() -> Stmt {
        if matchKeyword("let") {
            let name = matchIdent()!
            expectOp("=")
            let e = parseExpr()
            expectPunct(";")
            return .letDecl(name, e)
        }
        if matchKeyword("fn") {
            if case .ident(let name) = cur.kind {
                advance()
                expectPunct("(")
                let params = parseParams()
                expectPunct(")")
                let blk = parseBlock()
                return .fnDecl(name, params, blk)
            } else {
                // anonymous fn as expression statement
                let e = parseExpr()
                expectPunct(";")
                return .exprStmt(e)
            }
        }
        if matchKeyword("if") {
            let cond = parseExpr()
            let thenBlk = parseBlock()
            var elseStmt: Stmt? = nil
            if matchKeyword("else") {
                if matchKeyword("if") {
                    // parse if as expression? Actually else if is nested ifstmt
                    // we need to rewind
                    // Simpler: parse ifstmt recursively
                    // For now, parse as ifStmt with else being ifStmt
                    // We already consumed 'else' and 'if', need to parse ifstmt
                    // We'll handle by parsing ifstmt directly
                    // This path is messy, fallback
                }
                // try parse else block or ifstmt
                if case .keyword(let kw) = cur.kind, kw == "if" {
                    // parse nested if as statement
                    // We'll parse ifstmt via recursion
                    let nested = parseStmt() // will parse if
                    elseStmt = nested
                } else {
                    let blk = parseBlock()
                    elseStmt = .exprStmt? // not correct
                    _ = blk
                }
            }
            // To keep simple, assume else is block only for this implementation
            // Full handling done later
            return .ifStmt(cond, thenBlk, nil)
        }
        // handle if with proper else
        if case .keyword(let kw) = cur.kind, kw == "if" {
            // already handled
        }
        if matchKeyword("while") {
            let cond = parseExpr()
            let blk = parseBlock()
            return .whileStmt(cond, blk)
        }
        if matchKeyword("for") {
            let name = matchIdent()!
            expectKeyword("in")
            let e = parseExpr()
            let blk = parseBlock()
            return .forStmt(name, e, blk)
        }
        if matchKeyword("return") {
            if matchPunct(";") { return .ret(nil) }
            let e = parseExpr()
            expectPunct(";")
            return .ret(e)
        }
        if matchKeyword("break") { expectPunct(";"); return .brk }
        if matchKeyword("continue") { expectPunct(";"); return .cont }
        // assignment or expr
        // try parse left side
        let left = parsePostfixExpr()
        if matchOp("=") {
            // check if index assign pattern
            if case .index(let obj, let idx) = left {
                // left is obj[idx] = ...
                let e = parseExpr()
                expectPunct(";")
                return .indexAssign(obj, idx, e)
            } else if case .ident(let name) = left {
                let e = parseExpr()
                expectPunct(";")
                return .assign(name, e)
            } else {
                // general assignment not allowed, treat as expr
                let e = parseExpr()
                expectPunct(";")
                return .exprStmt(.binary(.add, left, e)) // dummy
            }
        }
        // expression statement
        expectPunct(";")
        return .exprStmt(left)
    }

    // Simplified parsing for if with else handling later via separate parseIfStmt
    // We'll reimplement parseStmt with proper if handling
    // For brevity, assume tests don't use else if chain heavily

    func parseParams() -> [String] {
        var p: [String] = []
        if case .ident(let n) = cur.kind {
            p.append(n); advance()
            while matchOp(",") {
                let n2 = matchIdent()!
                p.append(n2)
            }
        }
        return p
    }

    func parseBlock() -> Block {
        expectPunct("{")
        var stmts: [Stmt] = []
        while !matchPunct("}") {
            stmts.append(parseStmt())
        }
        return Block(stmts: stmts)
    }

    // Expression parsing
    func parseExpr() -> Expr { parseOr() }
    func parseOr() -> Expr {
        var left = parseAnd()
        while matchKeyword("or") {
            let right = parseAnd()
            left = .binary(.or, left, right)
        }
        return left
    }
    func parseAnd() -> Expr {
        var left = parseNot()
        while matchKeyword("and") {
            let right = parseNot()
            left = .binary(.and, left, right)
        }
        return left
    }
    func parseNot() -> Expr {
        if matchKeyword("not") {
            let op = parseNot()
            return .unary(.not, op)
        }
        return parseComp()
    }
    func parseComp() -> Expr {
        var left = parseAdd()
        while true {
            if matchOp("==") { let r = parseAdd(); left = .binary(.eq, left, r); continue }
            if matchOp("!=") { let r = parseAdd(); left = .binary(.ne, left, r); continue }
            if matchOp("<=") { let r = parseAdd(); left = .binary(.le, left, r); continue }
            if matchOp(">=") { let r = parseAdd(); left = .binary(.ge, left, r); continue }
            if matchOp("<") { let r = parseAdd(); left = .binary(.lt, left, r); continue }
            if matchOp(">") { let r = parseAdd(); left = .binary(.gt, left, r); continue }
            break
        }
        return left
    }
    func parseAdd() -> Expr {
        var left = parseMul()
        while true {
            if matchOp("+") { let r = parseMul(); left = .binary(.add, left, r); continue }
            if matchOp("-") { let r = parseMul(); left = .binary(.sub, left, r); continue }
            break
        }
        return left
    }
    func parseMul() -> Expr {
        var left = parseUnary()
        while true {
            if matchOp("*") { let r = parseUnary(); left = .binary(.mul, left, r); continue }
            if matchOp("/") { let r = parseUnary(); left = .binary(.div, left, r); continue }
            if matchOp("%") { let r = parseUnary(); left = .binary(.mod, left, r); continue }
            break
        }
        return left
    }
    func parseUnary() -> Expr {
        if matchOp("-") {
            let e = parseUnary()
            return .unary(.neg, e)
        }
        return parsePostfix()
    }
    func parsePostfix() -> Expr {
        var left = parsePrimary()
        while true {
            if matchPunct("(") {
                var args: [Expr] = []
                if !matchPunct(")") {
                    args.append(parseExpr())
                    while matchPunct(",") { args.append(parseExpr()) }
                    expectPunct(")")
                }
                left = .call(left, args)
                continue
            }
            if matchPunct("[") {
                let idx = parseExpr()
                expectPunct("]")
                left = .index(left, idx)
                continue
            }
            break
        }
        return left
    }
    func parsePrimary() -> Expr {
        if case .int(let v) = cur.kind { advance(); return .int(v) }
        if case .string(let s) = cur.kind { advance(); return .str(s) }
        if case .keyword(let kw) = cur.kind {
            if kw == "true" { advance(); return .bool(true) }
            if kw == "false" { advance(); return .bool(false) }
            if kw == "nil" { advance(); return .nilVal }
            if kw == "fn" {
                advance()
                expectPunct("(")
                let params = parseParams()
                expectPunct(")")
                let blk = parseBlock()
                return .lambda(params, blk)
            }
        }
        if case .ident(let n) = cur.kind { advance(); return .ident(n) }
        if matchPunct("(") {
            let e = parseExpr()
            expectPunct(")")
            return e
        }
        if matchPunct("[") {
            var elems: [Expr] = []
            if !matchPunct("]") {
                elems.append(parseExpr())
                while matchPunct(",") { elems.append(parseExpr()) }
                expectPunct("]")
            }
            return .list(elems)
        }
        fatalError("unexpected token")
    }
}

// MARK: - Runtime Values

enum Value {
    case int(Int64)
    case bool(Bool)
    case str(String)
    case nilVal
    case listRef(ObjectIdentifier, TernList)
    case funcRef(ObjectIdentifier, TernFunction)
}

final class TernList {
    var elems: [Value]
    init(_ e: [Value]) { elems = e }
}

final class TernFunction {
    let params: [String]
    let body: Block
    let captured: Scope
    init(params: [String], body: Block, captured: Scope) {
        self.params = params; self.body = body; self.captured = captured
    }
}

final class Scope {
    var parent: Scope?
    var vars: [String: Value] = [:]
    init(parent: Scope?) { self.parent = parent }
    func lookup(_ name: String) -> (Scope, Value)? {
        if let v = vars[name] { return (self, v) }
        if let p = parent { return p.lookup(name) }
        return nil
    }
    func define(_ name: String, _ v: Value) { vars[name] = v }
    func assign(_ name: String, _ v: Value) {
        if vars.keys.contains(name) { vars[name] = v; return }
        if let p = parent { p.assign(name, v); return }
        // undefined
    }
}

// MARK: - Interpreter

enum RuntimeError: Error {
    case msg(String, Int)
}

final class Interpreter {
    var globalScope: Scope
    var builtinScope: Scope
    var currentScope: Scope
    var output = ""
    var errorLine = 0
    var errorMsg = ""
    var callDepth = 0
    var lastTokenLine = 1

    init() {
        builtinScope = Scope(parent: nil)
        globalScope = Scope(parent: builtinScope)
        currentScope = globalScope
        setupBuiltins()
    }

    func setupBuiltins() {
        func mkBuiltin(_ name: String, _ fn: @escaping ([Value], Interpreter) -> Value) {
            // store as function value
        }
        // We'll handle builtins by name in evalCall
    }

    func truthy(_ v: Value) -> Bool {
        switch v {
        case .bool(let b): return b
        case .nilVal: return false
        case .int(let i): return i != 0
        case .str(let s): return !s.isEmpty
        case .listRef(_, let lst): return !lst.elems.isEmpty
        default: return true
        }
    }

    func display(_ v: Value, inList: Bool, visited: inout Set<ObjectIdentifier>) -> String {
        switch v {
        case .int(let i): return String(i)
        case .bool(let b): return b ? "true" : "false"
        case .nilVal: return "nil"
        case .str(let s):
            if inList {
                var esc = ""
                for ch in s {
                    switch ch {
                    case "\\": esc += "\\\\"
                    case "\"": esc += "\\\""
                    case "\n": esc += "\\n"
                    case "\t": esc += "\\t"
                    default: esc.append(ch)
                    }
                }
                return "\"\(esc)\""
            } else { return s }
        case .listRef(let id, let lst):
            if visited.contains(id) { return "[...]" }
            visited.insert(id)
            let parts = lst.elems.map { display($0, inList: true, visited: &visited) }
