        }
    }

    func execBlock(_ blk: Block, scope: Scope) -> ExecResult {
        for s in blk.stmts {
            let r = execStmt(s, scope: scope)
            switch r {
            case .returnValue(let v): return .returnValue(v)
            case .breakLoop: return .breakLoop
            case .continueLoop: return .continueLoop
            default: break
            }
        }
