            expectPunct(";")
            return .letDecl(n,e)
        }
        if matchKeyword("fn") {
            // fn decl?
            let save = p
            if case .ident = peek(1).kind, case .punct(let pp)=peek(2).kind, pp=="(" {
                advance() // fn
                let n = matchIdent()!
                expectPunct("(")
                let params = parseParams()
                expectPunct(")")
                let blk = parseBlock()
                return .fnDecl(n,params,blk)
            }
            p = save
        }
        if matchKeyword("if") { return parseIfStmt() }
        if matchKeyword("while") {
            let c = parseExpr()
            let b = parseBlock()
            return .whileStmt(c,b)
        }
        if matchKeyword("for") {
            let n = matchIdent()!
            expectKeyword("in")
            let e = parseExpr()
            let b = parseBlock()
            return .forStmt(n,e,b)
        }
        if matchKeyword("return") {
            if matchPunct(";") { return .ret(nil) }
            let e = parseExpr(); expectPunct(";"); return .ret(e)
        }
        if matchKeyword("break") { expectPunct(";"); return .brk }
        if matchKeyword("continue") { expectPunct(";"); return .cont }
        // try assignable
        let start = p
        let left = parseAssignable()
        if matchOp("=") {
            let right = parseExpr()
            expectPunct(";")
            // validate left
            if case .ident(let n,_) = left {
                return .assign(n,right)
            } else if case .index(let o,let idx,_) = left {
                // left was index expression, we need to reconstruct
                // left is already index node
                return .indexAssign(o, idx, right, cur.line)
            } else {
                // fallback
                p = start
                let e = parseExpr(); expectPunct(";"); return .exprStmt(e)
            }
        } else {
            p = start
            let e = parseExpr(); expectPunct(";"); return .exprStmt(e)
        }
    }
    func parseIfStmt()->Stmt {
        expectKeyword("if")
        let c = parseExpr()
        let thenB = parseBlock()
        var elseS:Stmt? = nil
        if matchKeyword("else") {
            if matchKeyword("if") {
                // backtrack one
                p -= 1
                elseS = parseIfStmt()
            } else {
                let b = parseBlock()
                elseS = .blockStmt(b)
            }
        }
        return .ifStmt(c,thenB,elseS)
    }
    func parseBlock()->Block {
        expectPunct("{")
        var stmts:[Stmt]=[]
        while !matchPunct("}") { stmts.append(parseStmt()) }
        return Block(stmts:stmts)
    }
    func parseParams()->[String] {
        var ps:[String]=[]
        if case .ident(let n)=cur.kind { ps.append(n); advance(); while matchOp(",") { ps.append(matchIdent()!)} }
        return ps
    }
    // expr
    func parseExpr()->Expr { parseOr() }
    func parseOr()->Expr { var l=parseAnd(); while matchKeyword("or"){ let r=parseAnd(); l=.binary(.or,l,r,cur.line)}; return l }
    func parseAnd()->Expr { var l=parseNot(); while matchKeyword("and"){ let r=parseNot(); l=.binary(.and,l,r,cur.line)}; return l }
    func parseNot()->Expr { if matchKeyword("not"){ let e=parseNot(); return .unary(.not,e,cur.line)}; return parseComp() }
    func parseComp()->Expr { var l=parseAdd(); while true { if matchOp("=="){ let r=parseAdd(); l=.binary(.eq,l,r,cur.line); continue } if matchOp("!="){ let r=parseAdd(); l=.binary(.ne,l,r,cur.line); continue } if matchOp("<="){ let r=parseAdd(); l=.binary(.le,l,r,cur.line); continue } if matchOp(">="){ let r=parseAdd(); l=.binary(.ge,l,r,cur.line); continue } if matchOp("<"){ let r=parseAdd(); l=.binary(.lt,l,r,cur.line); continue } if matchOp(">"){ let r=parseAdd(); l=.binary(.gt,l,r,cur.line); continue } break }; return l }
    func parseAdd()->Expr { var l=parseMul(); while true { if matchOp("+"){ let r=parseMul(); l=.binary(.add,l,r,cur.line); continue } if matchOp("-"){ let r=parseMul(); l=.binary(.sub,l,r,cur.line); continue } break }; return l }
    func parseMul()->Expr { var l=parseUnary(); while true { if matchOp("*"){ let r=parseUnary(); l=.binary(.mul,l,r,cur.line); continue } if matchOp("/"){ let r=parseUnary(); l=.binary(.div,l,r,cur.line); continue } if matchOp("%"){ let r=parseUnary(); l=.binary(.mod,l,r,cur.line); continue } break }; return l }
    func parseUnary()->Expr { if matchOp("-"){ let e=parseUnary(); return .unary(.neg,e,cur.line)}; return parsePostfix() }
    func parsePostfix()->Expr { var l=parsePrimary(); while true { if matchPunct("("){ var args:[Expr]=[]; if !matchPunct(")") { args.append(parseExpr()); while matchPunct(","){ args.append(parseExpr()) }; expectPunct(")") }; l=.call(l,args,cur.line); continue } if matchPunct("["){ let idx=parseExpr(); expectPunct("]"); l=.index(l,idx,cur.line); continue } break }; return l }
    func parsePrimary()->Expr {
        if case .int(let v)=cur.kind { let l=cur.line; advance(); return .int(v,l) }
        if case .string(let s)=cur.kind { let l=cur.line; advance(); return .str(s,l) }
        if case .keyword(let k)=cur.kind {
            if k=="true"{ advance(); return .bool(true,cur.line) }
            if k=="false"{ advance(); return .bool(false,cur.line) }
            if k=="nil"{ advance(); return .nilV(cur.line) }
            if k=="fn" {
                advance(); expectPunct("("); let ps=parseParams(); expectPunct(")"); let b=parseBlock(); return .lambda(ps,b,cur.line)
            }
        }
        if case .ident(let n)=cur.kind { let l=cur.line; advance(); return .ident(n,l) }
        if matchPunct("("){ let e=parseExpr(); expectPunct(")"); return e }
        if matchPunct("["){
            var elems:[Expr]=[]
            if !matchPunct("]"){ elems.append(parseExpr()); while matchPunct(","){ elems.append(parseExpr()) }; expectPunct("]") }
            return .list(elems,cur.line)
        }
        fatalError("unexpected")
    }
    func parseAssignable()->Expr {
        let prim = parsePrimary()
        var curE = prim
        while true {
            if matchPunct("("){ var args:[Expr]=[]; if !matchPunct(")") { args.append(parseExpr()); while matchPunct(","){ args.append(parseExpr()) }; expectPunct(")") }; curE=.call(curE,args,cur.line); continue }
            if matchPunct("["){ let idx=parseExpr(); expectPunct("]"); curE=.index(curE,idx,cur.line); continue }
            break
        }
        return curE
    }
}

// MARK: - Runtime
enum Value {
    case int(Int64)
    case bool(Bool)
    case str(String)
    case nilV
    case listRef(ObjectIdentifier,TernList)
    case funcRef(ObjectIdentifier,TernFunction)
}
final class TernList { var elems:[Value]; init(_ e:[Value]){ elems=e } }
final class TernFunction { let params:[String]; let body:Block; let captured:Scope; init(p:[String],b:Block,c:Scope){params=p;body=b;captured=c} }
final class Scope { var parent:Scope?; var vars:[String:Value]=[:]; init(_ p:Scope?){parent=p} func lookup(_ n:String)->(Scope,Value)? { if let v=vars[n]{return (self,v)}; if let p=parent{return p.lookup(n)}; return nil } func define(_ n:String,_ v:Value){vars[n]=v} }

final class Interpreter {
    var global:Scope; var builtin:Scope; var cur:Scope
    init(){ builtin=Scope(nil); global=Scope(builtin); cur=global }
    func truthy(_ v:Value)->Bool {
        switch v { case .bool(let b):return b; case .nilV:return false; case .int(let i):return i!=0; case .str(let s):return !s.isEmpty; case .listRef(_,let l):return !l.elems.isEmpty; default:return true }
    }
    func typeName(_ v:Value)->String {
        switch v { case .int:return "int"; case .bool:return "bool"; case .str:return "string"; case .nilV:return "nil"; case .listRef:return "list"; case .funcRef:return "function" }
    }
    func display(_ v:Value,inList:Bool,visited:inout Set<ObjectIdentifier>)->String {
        switch v {
        case .int(let i):return String(i)
        case .bool(let b):return b?"true":"false"
        case .nilV:return "nil"
        case .str(let s):
            if inList {
                var e=""; for ch in s { switch ch { case "\\":e+="\\\\"; case "\"":e+="\\\"" ; case "\n":e+="\\n"; case "\t":e+="\\t"; default:e.append(ch)}}
                return "\"\(e)\""
            } else { return s }
        case .listRef(let id,let lst):
            if visited.contains(id){ return "[...]" }
            visited.insert(id)
            let parts=lst.elems.map{ display($0,inList:true,visited:&visited) }
            visited.remove(id)
            return "["+parts.joined(separator:", ")+"]"
        case .funcRef:return "<fn>"
        }
    }
    func error(_ msg:String,line:Int){ print("error at line \(line): \(msg)"); exit(0) }

    func eval(_ e:Expr,scope:Scope)->Value {
        switch e {
        case .int(let v,_):return .int(v)
        case .str(let s,_):return .str(s)
        case .bool(let b,_):return .bool(b)
        case .nilV:return .nilV
        case .ident(let n,_):
            if let (_,v)=scope.lookup(n){ return v } else { error("undefined variable \(n)",line:1) }
        case .unary(let op,let sub,let line):
            let v=eval(sub,scope:scope)
            switch op {
            case .not: return .bool(truthy(v))
            case .neg:
                if case .int(let i)=v { if i==Int64.min { error("integer overflow",line:line)} return .int(-i) } else { error("cannot apply - to \(typeName(v))",line:line) }
            }
        case .binary(let op,let l,let r,let line):
            if op==.or {
                let lv=eval(l,scope:scope); if truthy(lv){ return lv }; return eval(r,scope:scope)
            }
            if op==.and {
                let lv=eval(l,scope:scope); if !truthy(lv){ return lv }; return eval(r,scope:scope)
            }
            let lv=eval(l,scope:scope); let rv=eval(r,scope:scope)
            return evalBin(op,lv,rv,line)
        case .call(let c,let args,let line):
            let cv=eval(c,scope:scope)
            var ev=[Value](); for a in args { ev.append(eval(a,scope:scope)) }
            return callVal(cv,args:ev,scope:scope,line:line)
        case .index(let o,let i,let line):
            let ov=eval(o,scope:scope); let iv=eval(i,scope:scope)
            return indexVal(ov,iv,line)
        case .lambda(let p,let b,_):
            let fn=TernFunction(p:p,b:b,captured:scope); return .funcRef(ObjectIdentifier(fn),fn)
        case .list(let es,_):
            var vs=[Value](); for e in es { vs.append(eval(e,scope:scope)) }; let lst=TernList(vs); return .listRef(ObjectIdentifier(lst),lst)
        }
    }
    func evalBin(_ op:BinOp,_ a:Value,_ b:Value,_ line:Int)->Value {
        switch op {
        case .eq,.ne:
            let eq=valuesEqual(a,b); return .bool(op==.eq?eq:!eq)
        case .lt,.le,.gt,.ge:
            if case .int(let x)=a, case .int(let y)=b {
                let r=compare(x,y); return .bool(compareRes(r,op))
            }
            if case .str(let x)=a, case .str(let y)=b {
                let r=x.compare(y)==.orderedAscending ? -1 : (x.compare(y)==.orderedDescending ? 1 : 0)
                return .bool(compareRes(r,op))
            }
            error("cannot apply \(opSym(op)) to \(typeName(a)) and \(typeName(b))",line:line)
        case .add:
            if case .int(let x)=a, case .int(let y)=b { let (r,o)=x.addingReportingOverflow(y); if o{ error("integer overflow",line:line)}; return .int(r) }
            if case .str(let x)=a, case .str(let y)=b { return .str(x+y) }
            if case .listRef(_,let la)=a, case .listRef(_,let lb)=b { let nl=TernList(la.elems+lb.elems); return .listRef(ObjectIdentifier(nl),nl) }
            error("cannot apply + to \(typeName(a)) and \(typeName(b))",line:line)
        case .sub:
            if case .int(let x)=a, case .int(let y)=b { let (r,o)=x.subtractingReportingOverflow(y); if o{ error("integer overflow",line:line)}; return .int(r) }
            error("cannot apply - to \(typeName(a)) and \(typeName(b))",line:line)
        case .mul:
            if case .int(let x)=a, case .int(let y)=b { let (r,o)=x.multipliedReportingOverflow(by:y); if o{ error("integer overflow",line:line)}; return .int(r) }
            error("cannot apply * to \(typeName(a)) and \(typeName(b))",line:line)
        case .div:
            if case .int(let x)=a, case .int(let y)=b { if y==0{ error("division by zero",line:line)}; if x==Int64.min && y==-1{ error("integer overflow",line:line)}; return .int(x/y) }
            error("cannot apply / to \(typeName(a)) and \(typeName(b))",line:line)
        case .mod:
            if case .int(let x)=a, case .int(let y)=b { if y==0{ error("division by zero",line:line)}; let q=x/y; return .int(x - q*y) }
            error("cannot apply % to \(typeName(a)) and \(typeName(b))",line:line)
        default: return .nilV
        }
    }
    func compare(_ a:Int64,_ b:Int64)->Int { a<b ? -1 : a>b ? 1 : 0 }
    func compareRes(_ r:Int,_ op:BinOp)->Bool {
        switch op { case .lt:return r<0; case .le:return r<=0; case .gt:return r>0; case .ge:return r>=0; default:false }
    }
    func opSym(_ op:BinOp)->String {
        switch op { case .add:"+"; case .sub:"-"; case .mul:"*"; case .div:"/"; case .mod:"%"; case .eq:"=="; case .ne:"!="; case .lt:"<"; case .le:"<="; case .gt:">"; case .ge:">="; default:"?" }
    }
    func valuesEqual(_ a:Value,_ b:Value)->Bool {
        switch (a,b) {
        case (.int(let x),.int(let y)):return x==y
        case (.bool(let x),.bool(let y)):return x==y
        case (.str(let x),.str(let y)):return x==y
        case (.nilV,.nilV):return true
        case (.listRef(_,let la),.listRef(_,let lb)):
            if la.elems.count!=lb.elems.count { return false }
            for i in 0..<la.elems.count { if !valuesEqual(la.elems[i],lb.elems[i]) { return false } }
            return true
        case (.funcRef(let id1,_),.funcRef(let id2,_)):return id1==id2
        default:false
        }
    }
    func indexVal(_ o:Value,_ i:Value,_ line:Int)->Value {
        guard case .int(let ii)=i else { error("cannot index \(typeName(o)) with \(typeName(i))",line:line) }
        switch o {
        case .str(let s):
            if ii<0 || ii>=Int64(s.count){ error("index \(ii) out of range for length \(s.count)",line:line) }
            let idx=s.index(s.startIndex,offsetBy:Int(ii)); return .str(String(s[idx]))
        case .listRef(_,let lst):
            if ii<0 || ii>=Int64(lst.elems.count){ error("index \(ii) out of range for length \(lst.elems.count)",line:line) }
            return lst.elems[Int(ii)]
        default:
            error("cannot index \(typeName(o)) with \(typeName(i))",line:line)
        }
    }
    func callVal(_ callee:Value,args:[Value],scope:Scope,line:Int)->Value {
        // builtin by name?
        // try function ref
        switch callee {
        case .funcRef(_,let fn):
            if args.count!=fn.params.count { error("expected \(fn.params.count) arguments, got \(args.count)",line:line) }
            let ns=Scope(fn.captured)
            for (p,v) in zip(fn.params,args){ ns.define(p,v) }
            let saved=cur; cur=ns
            let res=execBlock(fn.body,scope:ns)
            cur=saved
            return res ?? .nilV
        default:
            // try builtin by name lookup? For calls via ident we need name
            error("cannot call \(typeName(callee))",line:line)
        }
    }
    // builtin dispatch via name lookup in eval for ident calls
    func builtin(_ name:String,args:[Value],line:Int)->Value {
        switch name {
        case "print":
            var vis=Set<ObjectIdentifier>(); let parts=args.map{ display($0,inList:false,visited:&vis) }; print(parts.joined(separator:" ")); return .nilV
        case "str":
            if args.count!=1 { error("expected 1 arguments, got \(args.count)",line:line) }
            var vis=Set<ObjectIdentifier>(); return .str(display(args[0],inList:false,visited:&vis))
        case "type":
            if args.count!=1 { error("expected 1 arguments, got \(args.count)",line:line) }
            return .str(typeName(args[0]))
        case "len":
            if args.count!=1 { error("expected 1 arguments, got \(args.count)",line:line) }
            switch args[0] { case .str(let s):return .int(Int64(s.count)); case .listRef(_,let l):return .int(Int64(l.elems.count)); default: error("bad argument to len",line:line) }
        case "push":
            if args.count!=2 { error("expected 2 arguments, got \(args.count)",line:line) }
            if case .listRef(_,let l)=args[0]{ l.elems.append(args[1]); return .nilV }; error("bad argument to push",line:line)
        case "pop":
            if args.count!=1 { error("expected 1 arguments, got \(args.count)",line:line) }
            if case .listRef(_,let l)=args[0]{ if l.elems.isEmpty{ error("bad argument to pop",line:line)}; return l.elems.removeLast() }; error("bad argument to pop",line:line)
        case "range":
            if args.count!=2 { error("expected 2 arguments, got \(args.count)",line:line) }
            if case .int(let a)=args[0], case .int(let b)=args[1] {
                var e=[Value](); var i=a; while i<b { e.append(.int(i)); i+=1 }; let lst=TernList(e); return .listRef(ObjectIdentifier(lst),lst)
            }
            error("bad argument to range",line:line)
        case "slice":
            if args.count!=3 { error("expected 3 arguments, got \(args.count)",line:line) }
            let obj=args[0]; guard case .int(let a)=args[1], case .int(let b)=args[2] else { error("bad argument to slice",line:line) }
            switch obj {
            case .str(let s):
                let st=max(0,min(a,Int64(s.count))); let en=max(0,min(b,Int64(s.count))); if st>=en{ return .str("") }
                let si=s.index(s.startIndex,offsetBy:Int(st)); let ei=s.index(s.startIndex,offsetBy:Int(en)); return .str(String(s[si..<ei]))
            case .listRef(_,let l):
                let st=max(0,min(a,Int64(l.elems.count))); let en=max(0,min(b,Int64(l.elems.count))); if st>=en{ let nl=TernList([]); return .listRef(ObjectIdentifier(nl),nl) }
                let sl=Array(l.elems[Int(st)..<Int(en)]); let nl=TernList(sl); return .listRef(ObjectIdentifier(nl),nl)
            default: error("bad argument to slice",line:line)
            }
        default:
            error("cannot call \(name)",line:line)
        }
    }

    enum ExecRes { case normal, ret(Value), brk, cont }
    func execStmt(_ s:Stmt,scope:Scope)->ExecRes {
        switch s {
        case .letDecl(let n,let e):
            scope.define(n,eval(e,scope:scope)); return .normal
        case .fnDecl(let n,let p,let b):
            let fn=TernFunction(p:p,b:b,captured:scope); scope.define(n,.funcRef(ObjectIdentifier(fn),fn)); return .normal
        case .ifStmt(let c,let tb,let es):
            if truthy(eval(c,scope:scope)) { return execBlock(tb,scope:Scope(scope)) } else if let es=es { return execStmt(es,scope) } else { return .normal }
        case .whileStmt(let c,let b):
            while true { if !truthy(eval(c,scope:scope)) { break }; let r=execBlock(b,scope:Scope(scope)); if case .ret(let v)=r { return .ret(v) }; if case .brk=r { break } }
            return .normal
        case .forStmt(let n,let e,let b):
            let v=eval(e,scope:scope); guard case .listRef(_,let lst)=v else { error("cannot iterate \(typeName(v))",line:1) }
            var i=0; while i < lst.elems.count { let ns=Scope(scope); ns.define(n,lst.elems[i]); let r=execBlock(b,scope:ns); if case .ret(let v)=r { return .ret(v) }; if case .brk=r { break }; i+=1 }
            return .normal
        case .ret(let e):
            let v=e.map{ eval($0,scope:scope) } ?? .nilV; return .ret(v)
        case .brk: return .brk
        case .cont: return .cont
        case .assign(let n,let e):
            let v=eval(e,scope:scope); if let (sc,_)=scope.lookup(n){ sc.vars[n]=v } else { error("undefined variable \(n)",line:1) }; return .normal
        case .indexAssign(let o,let i,let v,let line):
            let ov=eval(o,scope:scope); let iv=eval(i,scope:scope); let vv=eval(v,scope:scope)
            if case .listRef(_,let lst)=ov, case .int(let ii)=iv {
                if ii<0 || ii>=Int64(lst.elems.count){ error("index \(ii) out of range for length \(lst.elems.count)",line:line) }
                lst.elems[Int(ii)]=vv; return .normal
            }
            error("cannot assign into \(typeName(ov))",line:line)
        case .exprStmt(let e):
            // handle builtin calls via ident
            if case .ident(let n,_)=e { /* builtin handled in eval */ }
            _ = eval(e,scope:scope); return .normal
        case .blockStmt(let b):
            return execBlock(b,scope:scope)
        }
    }
    func execBlock(_ b:Block,scope:Scope)->ExecRes {
        for st in b.stmts { let r=execStmt(st,scope:scope); switch r { case .ret(let v):return .ret(v); case .brk:return .brk; case .cont:return .cont; default:break } }
        return .normal
    }
    func run(_ stmts:[Stmt]) {
        for st in stmts { _ = execStmt(st,scope:global) }
    }
}

// MARK: - Main
let args = CommandLine.arguments
let dir = args.count > 1 ? args[1] : "."
let path = "\(dir)/program.tern"
let src = try! String(contentsOfFile: path, encoding: .utf8)
let lexer = Lexer(src)
var toks:[Token]=[]
var lexTok = lexer.next()
while true { toks.append(lexTok); if case .eof = lexTok.kind { break }; lexTok = lexer.next() }
let parser = Parser(toks)
let prog = parser.parseProgram()
let interp = Interpreter()
interp.run(prog)

use std::collections::HashMap;
use std::fs;
use std::path::Path;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug, PartialEq, Eq)]
struct BigInt {
    sign: i8,
    limbs: Vec<u32>,
}
impl BigInt {
    fn zero() -> Self { Self { sign: 0, limbs: vec![] } }
    fn is_zero(&self) -> bool { self.limbs.is_empty() || (self.limbs.len() == 1 && self.limbs[0]==0) }
    fn normalize(mut self) -> Self {
        while let Some(&0) = self.limbs.last() { self.limbs.pop(); }
        if self.limbs.is_empty() { self.sign = 0; }
        self
    }
    fn from_str_unscaled(s: &str) -> Self {
        let s = s.trim();
        if s.is_empty() { return Self::zero(); }
        let mut limbs = Vec::new();
        let mut i = s.len();
        while i>0 {
            let start = i.saturating_sub(9).max(0);
            let chunk = &s[start..i];
            let v = chunk.parse::<u32>().unwrap_or(0);
            limbs.push(v);
            i = start;
        }
        while limbs.len()>1 && *limbs.last().unwrap()==0 { limbs.pop(); }
        Self { sign:1, limbs }
    }
    fn parse_scaled(s: &str, scale: usize) -> Self {
        let s = s.trim();
        let (sign, rest) = if s.starts_with('-') { (-1, &s[1..]) } else if s.starts_with('+') { (1, &s[1..]) } else { (1, s) };
        let parts: Vec<&str> = rest.split('.').collect();
        let int_part = parts.get(0).unwrap_or(&"");
        let frac_part = parts.get(1).unwrap_or(&"");
        let mut frac = frac_part.to_string();
        if frac.len() < scale { frac.push_str(&"0".repeat(scale-frac.len())); }
        else if frac.len() > scale { frac.truncate(scale); }
        let combined = format!("{}{}", int_part, frac);
        let mut bi = Self::from_str_unscaled(&combined);
        if bi.is_zero() { bi.sign = 0; } else { bi.sign = sign; }
        bi
    }
    fn mul_small(mut self, m: u64) -> Self {
        if self.is_zero() || m==0 { return Self::zero(); }
        let mut carry: u128 = 0;
        for limb in &mut self.limbs {
            let prod = *limb as u128 * m as u128 + carry;
            *limb = prod as u32;
            carry = prod / BASE as u128;
        }
        while carry>0 { self.limbs.push(carry as u32); carry/=BASE as u128; }
        self.normalize()
    }
    fn add_small(mut self, add: u64) -> Self {
        let mut carry = add as u128;
        for limb in &mut self.limbs {
            let sum = *limb as u128 + carry;
            *limb = sum as u32;
            carry = sum / BASE as u128;
            if carry==0 { break; }
        }
        while carry>0 { self.limbs.push(carry as u32); carry/=BASE as u128; }
        self.normalize()
    }
    fn is_odd(&self) -> bool { self.limbs.get(0).map_or(false, |v| v & 1 == 1) }
    fn div_small(self, divisor: u64) -> (Vec<u32>, u64) {
        if self.is_zero() { return (vec![],0); }
        let mut rem: u128 = 0;
        let mut q = Vec::with_capacity(self.limbs.len());
        for &limb in self.limbs.iter().rev() {
            let cur = rem * BASE as u128 + limb as u128;
            let qq = cur / divisor as u128;
            rem = cur % divisor as u128;
            q.push(qq as u32);
        }
        q.reverse();
        while q.len()>1 && *q.last().unwrap()==0 { q.pop(); }
        (q, rem as u64)
    }
    fn div_round_half_even_small(self, divisor: u64) -> Self {
        if self.is_zero() { return self; }
        let sign = self.sign;
        let (q_l, rem) = self.div_small(divisor);
        let mut q = Self { sign:1, limbs: q_l };
        let two = rem as u128 * 2;
        let d = divisor as u128;
        if two > d { q = q.add_small(1); }
        else if two == d && q.is_odd() { q = q.add_small(1); }
        q.sign = if q.is_zero() {0} else {sign};
        q.normalize()
    }
    fn round_to_scale(mut self, from_scale: usize, to_scale: usize) -> Self {
        if from_scale == to_scale { return self; }
        if from_scale < to_scale {
            let f = pow10_usize(to_scale - from_scale);
            return self.mul_small(f);
        }
        let diff = from_scale - to_scale;
        let divisor = pow10_usize(diff);
        self.div_round_half_even_small(divisor)
    }
}
fn pow10_usize(e: usize) -> u64 { 10u64.pow(e as u32) }

fn big_mul(a: &BigInt, b: &BigInt) -> BigInt {
    if a.is_zero() || b.is_zero() { return BigInt::zero(); }
    let sign = a.sign * b.sign;
    let mut res = vec![0u64; a.limbs.len() + b.limbs.len()];
    for (i, &al) in a.limbs.iter().enumerate() {
        let mut carry: u128 = 0;
        for (j, &bl) in b.limbs.iter().enumerate() {
            let idx = i + j;
            let cur = res[idx] as u128 + al as u128 * bl as u128 + carry;
            res[idx] = cur as u64;
            carry = cur / BASE as u128;
        }
        let mut k = i + b.limbs.len();
        while carry>0 {
            let cur = res[k] as u128 + carry;
            res[k] = cur as u64;
            carry = cur / BASE as u128;
            k += 1;
        }
    }
    let limbs = res.into_iter().map(|x| x as u32).collect();
    BigInt { sign, limbs }.normalize()
}

fn format_commas(s: &str) -> String {
    let mut out = String::new();
    let mut cnt = 0;
    for c in s.chars().rev() {
        if cnt>0 && cnt%3==0 { out.push(','); }
        out.push(c);
        cnt+=1;
    }
    out.chars().rev().collect::<String>()
}

fn format_balance(bi: &BigInt, minor: u8) -> String {
    if bi.is_zero() {
        if minor==0 { return "0".to_string(); }
        return format!("0.{:0>width$}", "", width = minor as usize);
    }
    let sign_str = if bi.sign < 0 { "-" } else { "" };
    let (q, r) = bi.div_small(pow10_usize(minor as usize));
    let int_str = if q.is_empty() { "0".to_string() } else {
        let s = big_to_string(&q);
        format_commas(&s)
    };
    if minor==0 {
        format!("{}{}", sign_str, int_str)
    } else {
        let rem_str = big_to_string_small(r, minor as usize);
        format!("{}.{}", sign_str, int_str, rem_str)
    }
}
fn big_to_string(limbs: &[u32]) -> String {
    if limbs.is_empty() { return "0".to_string(); }
    let mut s = String::new();
    for (i, &limb) in limbs.iter().rev().enumerate() {
        if i==0 { s.push_str(&limb.to_string()); }
        else { s.push_str(&format!("{:09}", limb)); }
    }
    s
}
fn big_to_string_small(v: u64, width: usize) -> String {
    let s = v.to_string();
    if s.len() >= width { s } else { format!("{:0>width$}", s, width=width) }
}

#[derive(Clone)]
struct Account {
    currency: String,
    balance: BigInt,
    limit: BigInt,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = Path::new(dir).join("ledger.txt");
    let txt = fs::read_to_string(path).unwrap_or_default();
    let mut currencies: HashMap<String, u8> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejects: Vec<(usize,String)> = Vec::new();

    for (i, line) in txt.lines().enumerate() {
        let line_no = i+1;
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let cmd = tokens[0];
        match cmd {
            "currency" => {
                if tokens.len()>=3 { let code=tokens[1].to_string(); let mu=tokens[2].parse::<u8>().unwrap_or(0); currencies.insert(code, mu); }
            }
            "open" => {
                if tokens.len()<3 { continue; }
                let name = tokens[1].to_string();
                if accounts.contains_key(&name) {
                    rejects.push((line_no, format!("line {}: REJECT account exists {}", line_no, name)));
                    continue;
                }
                let code = tokens[2].to_string();
                let minor = *currencies.get(&code).unwrap_or(&0);
                let limit = if tokens.len()>=4 {
                    let v = BigInt::parse_scaled(tokens[3], 8).round_to_scale(8, minor as usize);
                    v
                } else { BigInt::zero() };
                accounts.insert(name, Account { currency: code, balance: BigInt::zero(), limit });
            }
            "deposit" => {
                if tokens.len()<3 { continue; }
                let name = tokens[1].to_string();
                let amt_str = tokens[2];
                let acc = match accounts.get(&name) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, name))); continue; } };
                let minor = *currencies.get(&acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8).round_to_scale(8, minor as usize);
                if amt.sign <=0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                let mut a = accounts.get_mut(&name).unwrap();
                a.balance = add_big(&a.balance, &amt);
            }
            "withdraw" => {
                if tokens.len()<3 { continue; }
                let name = tokens[1].to_string();
                let amt_str = tokens[2];
                let acc = match accounts.get(&name) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, name))); continue; } };
                let minor = *currencies.get(&acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8).round_to_scale(8, minor as usize);
                if amt.sign <=0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                if !enough(&acc.balance, &amt, &acc.limit) { rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, name))); continue; }
                let a = accounts.get_mut(&name).unwrap();
                a.balance = sub_big(&a.balance, &amt);
            }
            "transfer" => {
                if tokens.len()<4 { continue; }
                let from = tokens[1].to_string();
                let to = tokens[2].to_string();
                let amt_str = tokens[3];
                // unknown check
                let from_acc = match accounts.get(&from) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, from))); continue; } };
                let to_acc = match accounts.get(&to) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, to))); continue; } };
                if from_acc.currency != to_acc.currency { rejects.push((line_no, format!("line {}: REJECT currency mismatch", line_no))); continue; }
                let minor = *currencies.get(&from_acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8).round_to_scale(8, minor as usize);
                if amt.sign <=0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                if !enough(&from_acc.balance, &amt, &from_acc.limit) { rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, from))); continue; }
                let from_mut = accounts.get_mut(&from).unwrap();
                from_mut.balance = sub_big(&from_mut.balance, &amt);
                let to_mut = accounts.get_mut(&to).unwrap();
                to_mut.balance = add_big(&to_mut.balance, &amt);
            }
            "convert" => {
                if tokens.len()<5 { continue; }
                let from = tokens[1].to_string();
                let to = tokens[2].to_string();
                let amt_str = tokens[3];
                let rate_str = tokens[4];
                let from_acc = match accounts.get(&from) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, from))); continue; } };
                let to_acc = match accounts.get(&to) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, to))); continue; } };
                let minor_from = *currencies.get(&from_acc.currency).unwrap_or(&0);
                let minor_to = *currencies.get(&to_acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8).round_to_scale(8, minor_from as usize);
                if amt.sign <=0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                if !enough(&from_acc.balance, &amt, &from_acc.limit) { rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, from))); continue; }
                let rate_num = BigInt::parse_scaled(rate_str, 12);
                let prod = big_mul(&amt, &rate_num);
                // divide by 1e12 then round to minor_to
                let prod_scaled = prod.div_round_half_even_small(pow10_usize(12));
                let target_amt = prod_scaled.round_to_scale(0, minor_to as usize);
                // update
                let from_mut = accounts.get_mut(&from).unwrap();
                from_mut.balance = sub_big(&from_mut.balance, &amt);
                let to_mut = accounts.get_mut(&to).unwrap();
                to_mut.balance = add_big(&to_mut.balance, &target_amt);
            }
            "interest" => {
                if tokens.len()<3 { continue; }
                let name = tokens[1].to_string();
                let rate_str = tokens[2];
                let acc = match accounts.get(&name) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, name))); continue; } };
                let minor = *currencies.get(&acc.currency).unwrap_or(&0);
                let rate_num = BigInt::parse_scaled(rate_str, 12);
                let prod = big_mul(&acc.balance, &rate_num);
                let inc = prod.div_round_half_even_small(pow10_usize(12)).round_to_scale(0, minor as usize);
                let a = accounts.get_mut(&name).unwrap();
                a.balance = add_big(&a.balance, &inc);
            }
            "split" => {
                if tokens.len()<4 { continue; }
                let from = tokens[1].to_string();
                let amt_str = tokens[2];
                let from_acc = match accounts.get(&from) { Some(a)=>a.clone(), None=>{ rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, from))); continue; } };
                let minor_from = *currencies.get(&from_acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8).round_to_scale(8, minor_from as usize);
                if amt.sign <=0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                if !enough(&from_acc.balance, &amt, &from_acc.limit) { rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, from))); continue; }
                // parse targets
                let mut targets = Vec::new();
                let mut ok = true;
                for tok in &tokens[3..] {
                    let parts: Vec<&str> = tok.split(':').collect();
                    if parts.len()!=2 { ok=false; break; }
                    let tname = parts[0].to_string();
                    let w: u64 = parts[1].parse().unwrap_or(0);
                    if !accounts.contains_key(&tname) { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, tname))); ok=false; break; }
                    let tacc = accounts.get(&tname).unwrap();
                    if tacc.currency != from_acc.currency { rejects.push((line_no, format!("line {}: REJECT currency mismatch", line_no))); ok=false; break; }
                    targets.push((tname,w));
                }
                if !ok { continue; }
                let w_sum: u128 = targets.iter().map(|(_,w)| *w as u128).sum();
                if w_sum==0 { continue; }
                let mut shares = Vec::new();
                let mut total_q: u128 = 0;
                for (tname,w) in &targets {
                    let prod = amt.mul_small(*w);
                    let (q_l, rem) = prod.div_small(w_sum as u64);
                    let q_big = BigInt { sign:1, limbs: q_l }.normalize();
                    shares.push((tname.clone(), q_big, rem));
                    // sum
                }
                // distribute remainder
                let mut leftover = amt.clone();
                // subtract sum of q
                // compute sum q
                let sum_q = shares.iter().fold(BigInt::zero(), |acc,(_,q,_)| add_big(&acc, q));
                // leftover = amt - sum_q
                let left = sub_big(&amt, &sum_q);
                // distribute
                let mut left_val = if left.is_zero() { 0 } else { left.limbs[0] as u128 }; // small
                // sort by remainder desc then order
                let mut order: Vec<usize> = (0..targets.len()).collect();
                order.sort_by(|&i,&j| {
                    let ri = shares[i].2;
                    let rj = shares[j].2;
                    if ri!=rj { rj.cmp(&ri) } else { i.cmp(&j) }
                });
                let mut extra = vec![0u32; targets.len()];
                let mut left_u = left_val;
                for idx in order {
                    if left_u==0 { break; }
                    extra[idx]=1;
                    left_u-=1;
                }
                // apply
                let from_mut = accounts.get_mut(&from).unwrap();
                from_mut.balance = sub_big(&from_mut.balance, &amt);
                for (i,(tname,_,_)) in targets.iter().enumerate() {
                    let q = &shares[i].1;
                    let add_amt = if extra[i]>0 { add_big(q, &BigInt::from_i64(1)) } else { q.clone() };
                    let t_mut = accounts.get_mut(tname).unwrap();
                    t_mut.balance = add_big(&t_mut.balance, &add_amt);
                }
            }
            _ => {}
        }
    }

    for (ln, msg) in &rejects { println!("{}", msg); }
    if !rejects.is_empty() { println!(); }
    let mut accs: Vec<(&String, &Account)> = accounts.iter().collect();
    accs.sort_by_key(|(k,_)| *k);
    for (name, acc) in accs {
        let minor = *currencies.get(&acc.currency).unwrap_or(&0);
        let bal_str = format_balance(&acc.balance, minor);
        println!("{} {} {}", name, acc.currency, bal_str);
    }
    println!();
    let mut totals: HashMap<String, (BigInt, usize)> = HashMap::new();
    for acc in accounts.values() {
        let entry = totals.entry(acc.currency.clone()).or_insert((BigInt::zero(),0));
        entry.0 = add_big(&entry.0, &acc.balance);
        entry.1 += 1;
    }
    let mut tot_vec: Vec<(String, BigInt, usize)> = totals.into_iter().collect();
    tot_vec.sort_by(|a,b| a.0.cmp(&b.0));
    for (code, sum, cnt) in tot_vec {
        let minor = *currencies.get(&code).unwrap_or(&0);
        let sum_str = format_balance(&sum, minor);
        println!("total {} {} ({} accounts)", code, sum_str, cnt);
    }
}

fn add_big(a: &BigInt, b: &BigInt) -> BigInt {
    if a.is_zero() { return b.clone(); }
    if b.is_zero() { return a.clone(); }
    // simple addition of magnitudes assuming same sign for now
    // For our usage signs are compatible
    let sign = a.sign;
    let mut limbs = Vec::new();
    let max_len = a.limbs.len().max(b.limbs.len());
    let mut carry: u128 = 0;
    for i in 0..max_len {
        let av = *a.limbs.get(i).unwrap_or(&0) as u128;
        let bv = *b.limbs.get(i).unwrap_or(&0) as u128;
        let sum = av + bv + carry;
        limbs.push(sum as u32);
        carry = sum / BASE as u128;
    }
    while carry>0 { limbs.push(carry as u32); carry/=BASE as u128; }
    BigInt { sign, limbs }.normalize()
}
fn sub_big(a: &BigInt, b: &BigInt) -> BigInt {
    // assume a >= b in magnitude for our usage
    let mut limbs = a.limbs.clone();
    let mut borrow: i128 = 0;
    for i in 0..limbs.len() {
        let bv = *b.limbs.get(i).unwrap_or(&0) as i128;
        let cur = limbs[i] as i128 - borrow - bv;
        if cur < 0 { limbs[i] = (cur + BASE as i128) as u32; borrow = 1; } else { limbs[i] = cur as u32; borrow = 0; }
    }
    BigInt { sign: a.sign, limbs }.normalize()
}
fn enough(balance: &BigInt, amt: &BigInt, limit: &BigInt) -> bool {
    // balance - amt >= -limit  => balance + limit >= amt
    let bal_plus_lim = add_big(balance, limit);
    // compare
    cmp_big(&bal_plus_lim, amt) >= 0
}
fn cmp_big(a: &BigInt, b: &BigInt) -> i32 {
    if a.is_zero() && b.is_zero() { return 0; }
    let la = a.limbs.len();
    let lb = b.limbs.len();
    if la != lb { return la.cmp(&lb) as i32; }
    for i in (0..la).rev() {
        if a.limbs[i] != b.limbs[i] { return a.limbs[i].cmp(&b.limbs[i]) as i32; }
    }
    0
}
impl BigInt {
    fn from_i64(v: i64) -> Self {
        if v==0 { return Self::zero(); }
        let sign = if v<0 { -1 } else { 1 };
        let mut limbs = Vec::new();
        let mut x = v.abs() as u64;
        while x>0 { limbs.push((x % BASE as u64) as u32); x/=BASE as u64; }
        Self { sign, limbs }.normalize()
    }
}

use std::collections::HashMap;
use std::fs;
use std::path::Path;

const BASE: u32 = 1_000_000_000;

#[derive(Clone, Debug)]
struct BigInt {
    sign: i8, // -1,0,1
    limbs: Vec<u32>, // little endian base 1e9
}
impl BigInt {
    fn zero() -> Self { Self { sign: 0, limbs: vec![] } }
    fn is_zero(&self) -> bool { self.sign == 0 || self.limbs.is_empty() }
    fn normalize(mut self) -> Self {
        while let Some(&0) = self.limbs.last() { self.limbs.pop(); }
        if self.limbs.is_empty() { self.sign = 0; }
        self
    }
    fn from_u64(mut v: u64) -> Self {
        if v == 0 { return Self::zero(); }
        let mut limbs = Vec::new();
        while v > 0 { limbs.push((v % BASE as u64) as u32); v /= BASE as u64; }
        Self { sign: 1, limbs }
    }
    fn from_str_unscaled(s: &str) -> Self {
        if s.is_empty() { return Self::zero(); }
        let mut limbs = Vec::new();
        let bytes = s.as_bytes();
        let mut i = bytes.len();
        while i > 0 {
            let start = i.saturating_sub(9).max(0);
            let chunk = &s[start..i];
            let v: u32 = chunk.parse().unwrap_or(0);
            limbs.push(v);
            i = start;
        }
        Self { sign: 1, limbs }.normalize()
    }
    fn parse_scaled(s: &str, scale: usize) -> Self {
        let s = s.trim();
        if s.is_empty() { return Self::zero(); }
        let (sign, rest) = if s.starts_with('-') { (-1, &s[1..]) } else if s.starts_with('+') { (1, &s[1..]) } else { (1, s) };
        let mut parts = rest.split('.');
        let int_part = parts.next().unwrap_or("");
        let frac_part = parts.next().unwrap_or("");
        let mut frac = frac_part.to_string();
        if frac.len() < scale { frac.push_str(&"0".repeat(scale - frac.len())); }
        else if frac.len() > scale { frac.truncate(scale); }
        let combined = if int_part.is_empty() { "0".to_string() } else { int_part.to_string() } + &frac;
        let mut bi = Self::from_str_unscaled(&combined);
        if bi.is_zero() { bi.sign = 0; } else { bi.sign = sign; }
        bi
    }
    fn abs(&self) -> Self { Self { sign: if self.sign < 0 { 1 } else { self.sign }, limbs: self.limbs.clone() } }
    fn neg(&self) -> Self { if self.is_zero() { self.clone() } else { Self { sign: -self.sign, limbs: self.limbs.clone() } } }
    fn magnitude_cmp(a: &[u32], b: &[u32]) -> std::cmp::Ordering {
        let la = a.len(); let lb = b.len();
        if la != lb { return la.cmp(&lb); }
        for i in (0..la).rev() {
            if a[i] != b[i] { return a[i].cmp(&b[i]); }
        }
        std::cmp::Ordering::Equal
    }
    fn add_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
        let n = a.len().max(b.len());
        let mut res = vec![0; n + 1];
        let mut carry: u128 = 0;
        for i in 0..n {
            let av = *a.get(i).unwrap_or(&0) as u128;
            let bv = *b.get(i).unwrap_or(&0) as u128;
            let sum = av + bv + carry;
            res[i] = sum as u32;
            carry = sum / BASE as u128;
        }
        if carry > 0 { res[n] = carry as u32; }
        else { res.pop(); }
        res
    }
    fn sub_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
        // assume a >= b
        let mut res = a.to_vec();
        let mut borrow: i128 = 0;
        for i in 0..res.len() {
            let bv = *b.get(i).unwrap_or(&0) as i128;
            let cur = res[i] as i128 - borrow - bv;
            if cur < 0 { res[i] = (cur + BASE as i128) as u32; borrow = 1; } else { res[i] = cur as u32; borrow = 0; }
        }
        while res.last().map_or(false, |&x| x == 0) { res.pop(); }
        res
    }
    fn add(&self, other: &Self) -> Self {
        if self.is_zero() { return other.clone(); }
        if other.is_zero() { return self.clone(); }
        if self.sign == other.sign {
            let limbs = Self::add_mag(&self.limbs, &other.limbs);
            Self { sign: self.sign, limbs }.normalize()
        } else {
            let ord = Self::magnitude_cmp(&self.limbs, &other.limbs);
            if ord == std::cmp::Ordering::Equal { return Self::zero(); }
            if ord == std::cmp::Ordering::Greater {
                let limbs = Self::sub_mag(&self.limbs, &other.limbs);
                Self { sign: self.sign, limbs }.normalize()
            } else {
                let limbs = Self::sub_mag(&other.limbs, &self.limbs);
                Self { sign: other.sign, limbs }.normalize()
            }
        }
    }
    fn sub(&self, other: &Self) -> Self { self.add(&other.neg()) }
    fn mul_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
        if a.is_empty() || b.is_empty() { return vec![]; }
        let mut res = vec![0u128; a.len() + b.len()];
        for (i, &av) in a.iter().enumerate() {
            let mut carry: u128 = 0;
            for (j, &bv) in b.iter().enumerate() {
                let idx = i + j;
                let cur = res[idx] + av as u128 * bv as u128 + carry;
                res[idx] = cur % BASE as u128;
                carry = cur / BASE as u128;
            }
            let mut k = i + b.len();
            while carry > 0 {
                let cur = res[k] + carry;
                res[k] = cur % BASE as u128;
                carry = cur / BASE as u128;
                k += 1;
            }
        }
        let mut limbs = res.into_iter().map(|x| x as u32).collect::<Vec<_>>();
        while limbs.last().map_or(false, |&x| x == 0) { limbs.pop(); }
        limbs
    }
    fn mul(&self, other: &Self) -> Self {
        if self.is_zero() || other.is_zero() { return Self::zero(); }
        let sign = self.sign * other.sign;
        let limbs = Self::mul_mag(&self.limbs, &other.limbs);
        Self { sign, limbs }.normalize()
    }
    fn mul_small(&self, m: u64) -> Self {
        if self.is_zero() || m == 0 { return Self::zero(); }
        let mut carry: u128 = 0;
        let mut limbs = Vec::with_capacity(self.limbs.len() + 2);
        for &limb in &self.limbs {
            let cur = limb as u128 * m as u128 + carry;
            limbs.push(cur as u32);
            carry = cur / BASE as u128;
        }
        while carry > 0 { limbs.push(carry as u32); carry /= BASE as u128; }
        Self { sign: self.sign, limbs }.normalize()
    }
    fn div_small(&self, divisor: u64) -> (Self, u64) {
        if self.is_zero() { return (Self::zero(), 0); }
        let mut rem: u128 = 0;
        let mut q_limbs = Vec::with_capacity(self.limbs.len());
        for &limb in self.limbs.iter().rev() {
            let cur = rem * BASE as u128 + limb as u128;
            let q = cur / divisor as u128;
            rem = cur % divisor as u128;
            q_limbs.push(q as u32);
        }
        q_limbs.reverse();
        while q_limbs.last().map_or(false, |&x| x == 0) { q_limbs.pop(); }
        let q = Self { sign: self.sign, limbs: q_limbs }.normalize();
        (q, rem as u64)
    }
    fn div_round_half_even_small(self, divisor: u64) -> Self {
        if self.is_zero() { return self; }
        let sign = self.sign;
        let (q, rem) = self.div_small(divisor);
        let mut q2 = q;
        let two_rem = rem as u128 * 2;
        let d = divisor as u128;
        if two_rem > d {
            q2 = q2.add_small(1);
        } else if two_rem == d && q2.is_odd() {
            q2 = q2.add_small(1);
        }
        let sign2 = if q2.is_zero() { 0 } else { sign };
        Self { sign: sign2, limbs: q2.limbs }.normalize()
    }
    fn add_small(&self, add: u64) -> Self {
        if self.is_zero() { return Self::from_u64(add); }
        let mut limbs = self.limbs.clone();
        let mut carry = add as u128;
        for limb in &mut limbs {
            let sum = *limb as u128 + carry;
            *limb = sum as u32;
            carry = sum / BASE as u128;
            if carry == 0 { break; }
        }
        while carry > 0 { limbs.push(carry as u32); carry /= BASE as u128; }
        Self { sign: self.sign, limbs }.normalize()
    }
    fn is_odd(&self) -> bool { self.limbs.get(0).map_or(false, |v| v & 1 == 1) }
    fn to_u64(&self) -> Option<u64> {
        if self.limbs.len() > 2 { return None; }
        let mut v: u128 = 0;
        for (i, &limb) in self.limbs.iter().rev().enumerate() {
            v += limb as u128 * (BASE as u128).pow(i as u32);
        }
        if v > u64::MAX as u128 { None } else { Some(v as u64) }
    }
}

fn pow10_u64(e: usize) -> u64 { 10u64.pow(e as u32) }

fn format_commas(s: &str) -> String {
    let mut out = String::new();
    let mut cnt = 0;
    for c in s.chars().rev() {
        if cnt > 0 && cnt % 3 == 0 { out.push(','); }
        out.push(c);
        cnt += 1;
    }
    out.chars().rev().collect()
}

fn big_to_decimal_string(bi: &BigInt) -> String {
    if bi.is_zero() { return "0".to_string(); }
    let limbs = &bi.limbs;
    let mut s = String::new();
    for (i, &limb) in limbs.iter().rev().enumerate() {
        if i == 0 { s.push_str(&limb.to_string()); } else { s.push_str(&format!("{:09}", limb)); }
    }
    s
}

fn format_balance(bi: &BigInt, minor: u8) -> String {
    if bi.is_zero() {
        if minor == 0 { return "0".to_string(); }
        return format!("0.{}", "0".repeat(minor as usize));
    }
    let sign_str = if bi.sign < 0 { "-" } else { "" };
    let s = big_to_decimal_string(&bi.abs());
    if minor == 0 {
        return format!("{}{}", sign_str, format_commas(&s));
    }
    let m = minor as usize;
    let padded = if s.len() >= m { s } else { format!("{:0>width$}", s, width = m) };
    let (int_part, frac_part) = if padded.len() > m {
        let idx = padded.len() - m;
        ( &padded[..idx], &padded[idx..] )
    } else {
        ("0", &padded)
    };
    let int_fmt = format_commas(int_part);
    format!("{}.{}", sign_str, int_fmt, frac_part)
}

#[derive(Clone)]
struct Account {
    currency: String,
    balance: BigInt,
    limit: BigInt,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 { return; }
    let path = Path::new(&args[1]).join("ledger.txt");
    let txt = fs::read_to_string(path).unwrap_or_default();

    let mut currencies: HashMap<String, u8> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejects: Vec<(usize, String)> = Vec::new();

    for (i, line) in txt.lines().enumerate() {
        let line_no = i + 1;
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let tokens: Vec<&str> = line.split_whitespace().collect();
        let cmd = tokens[0];
        match cmd {
            "currency" => {
                if tokens.len() >= 3 {
                    let code = tokens[1].to_string();
                    let mu: u8 = tokens[2].parse().unwrap_or(0);
                    currencies.insert(code, mu);
                }
            }
            "open" => {
                if tokens.len() < 3 { continue; }
                let name = tokens[1].to_string();
                if accounts.contains_key(&name) {
                    rejects.push((line_no, format!("line {}: REJECT account exists {}", line_no, name)));
                    continue;
                }
                let code = tokens[2].to_string();
                let minor = *currencies.get(&code).unwrap_or(&0);
                let limit = if tokens.len() >= 4 {
                    let v = BigInt::parse_scaled(tokens[3], 8);
                    // round to minor
                    if minor as usize < 8 {
                        let div = pow10_u64(8 - minor as usize);
                        v.div_round_half_even_small(div)
                    } else { v }
                } else { BigInt::zero() };
                accounts.insert(name, Account { currency: code, balance: BigInt::zero(), limit });
            }
            "deposit" => {
                if tokens.len() < 3 { continue; }
                let name = tokens[1].to_string();
                let amt_str = tokens[2];
                let acc = match accounts.get(&name) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, name))); continue; } };
                let minor = *currencies.get(&acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8);
                let amt_r = if minor as usize < 8 { amt.div_round_half_even_small(pow10_u64(8 - minor as usize)) } else { amt };
                if amt_r.sign <= 0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                let a = accounts.get_mut(&name).unwrap();
                a.balance = a.balance.add(&amt_r);
            }
            "withdraw" => {
                if tokens.len() < 3 { continue; }
                let name = tokens[1].to_string();
                let amt_str = tokens[2];
                let acc = match accounts.get(&name) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, name))); continue; } };
                let minor = *currencies.get(&acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8);
                let amt_r = if minor as usize < 8 { amt.div_round_half_even_small(pow10_u64(8 - minor as usize)) } else { amt };
                if amt_r.sign <= 0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                // insufficient funds
                let new_bal = acc.balance.sub(&amt_r);
                let min_bal = acc.limit.neg();
                if new_bal.sign < 0 && acc.limit.sign > 0 {
                    // compare magnitude
                }
                // check balance + limit >= amt
                let bal_plus_lim = acc.balance.add(&acc.limit);
                if bal_plus_lim.cmp(&amt_r) < std::cmp::Ordering::Equal && bal_plus_lim.sign <= 0 {
                    // fallback simple check
                }
                // proper check: balance - amt >= -limit
                let allowed = acc.balance.add(&acc.limit);
                if allowed.cmp(&amt_r) < std::cmp::Ordering::Equal {
                    // need more precise compare
                }
                // use direct comparison
                let need = amt_r;
                let avail = acc.balance.add(&acc.limit);
                if avail.cmp(&need) < std::cmp::Ordering::Equal {
                    // Actually compare magnitudes
                }
                // Simpler: compute new balance and check >= -limit
                let new_balance = acc.balance.sub(&amt_r);
                let lower = acc.limit.neg();
                if new_balance.cmp(&lower) < std::cmp::Ordering::Equal {
                    rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, name)));
                    continue;
                }
                let a = accounts.get_mut(&name).unwrap();
                a.balance = a.balance.sub(&amt_r);
            }
            "transfer" => {
                if tokens.len() < 4 { continue; }
                let from = tokens[1].to_string();
                let to = tokens[2].to_string();
                let amt_str = tokens[3];
                let from_acc = match accounts.get(&from) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, from))); continue; } };
                let to_acc = match accounts.get(&to) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, to))); continue; } };
                if from_acc.currency != to_acc.currency { rejects.push((line_no, format!("line {}: REJECT currency mismatch", line_no))); continue; }
                let minor = *currencies.get(&from_acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8);
                let amt_r = if minor as usize < 8 { amt.div_round_half_even_small(pow10_u64(8 - minor as usize)) } else { amt };
                if amt_r.sign <= 0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                let new_bal = from_acc.balance.sub(&amt_r);
                let lower = from_acc.limit.neg();
                if new_bal.cmp(&lower) < std::cmp::Ordering::Equal {
                    rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, from)));
                    continue;
                }
                let f = accounts.get_mut(&from).unwrap();
                f.balance = f.balance.sub(&amt_r);
                let t = accounts.get_mut(&to).unwrap();
                t.balance = t.balance.add(&amt_r);
            }
            "convert" => {
                if tokens.len() < 5 { continue; }
                let from = tokens[1].to_string();
                let to = tokens[2].to_string();
                let amt_str = tokens[3];
                let rate_str = tokens[4];
                let from_acc = match accounts.get(&from) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, from))); continue; } };
                let to_acc = match accounts.get(&to) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, to))); continue; } };
                let minor_from = *currencies.get(&from_acc.currency).unwrap_or(&0);
                let minor_to = *currencies.get(&to_acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8);
                let amt_r = if minor_from as usize < 8 { amt.div_round_half_even_small(pow10_u64(8 - minor_from as usize)) } else { amt };
                if amt_r.sign <= 0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                let new_bal = from_acc.balance.sub(&amt_r);
                let lower = from_acc.limit.neg();
                if new_bal.cmp(&lower) < std::cmp::Ordering::Equal {
                    rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, from)));
                    continue;
                }
                let rate_num = BigInt::parse_scaled(rate_str, 12);
                let k = (minor_from as usize + 12).saturating_sub(minor_to as usize);
                let numerator = amt_r.mul(&rate_num);
                let target_amt = if k > 0 { numerator.div_round_half_even_small(pow10_u64(k)) } else { numerator };
                let f = accounts.get_mut(&from).unwrap();
                f.balance = f.balance.sub(&amt_r);
                let t = accounts.get_mut(&to).unwrap();
                t.balance = t.balance.add(&target_amt);
            }
            "interest" => {
                if tokens.len() < 3 { continue; }
                let name = tokens[1].to_string();
                let rate_str = tokens[2];
                let acc = match accounts.get(&name) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, name))); continue; } };
                let rate_num = BigInt::parse_scaled(rate_str, 12);
                let prod = acc.balance.mul(&rate_num);
                let inc = prod.div_round_half_even_small(pow10_u64(12));
                let a = accounts.get_mut(&name).unwrap();
                a.balance = a.balance.add(&inc);
            }
            "split" => {
                if tokens.len() < 4 { continue; }
                let from = tokens[1].to_string();
                let amt_str = tokens[2];
                let from_acc = match accounts.get(&from) { Some(a) => a.clone(), None => { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, from))); continue; } };
                let minor_from = *currencies.get(&from_acc.currency).unwrap_or(&0);
                let amt = BigInt::parse_scaled(amt_str, 8);
                let amt_r = if minor_from as usize < 8 { amt.div_round_half_even_small(pow10_u64(8 - minor_from as usize)) } else { amt };
                if amt_r.sign <= 0 { rejects.push((line_no, format!("line {}: REJECT non-positive amount", line_no))); continue; }
                let new_bal = from_acc.balance.sub(&amt_r);
                let lower = from_acc.limit.neg();
                if new_bal.cmp(&lower) < std::cmp::Ordering::Equal {
                    rejects.push((line_no, format!("line {}: REJECT insufficient funds {}", line_no, from)));
                    continue;
                }
                // parse targets and check unknown / currency
                let mut targets = Vec::new();
                let mut ok = true;
                for tok in &tokens[3..] {
                    let parts: Vec<&str> = tok.split(':').collect();
                    if parts.len() != 2 { ok = false; break; }
                    let tname = parts[0].to_string();
                    let w: u64 = parts[1].parse().unwrap_or(0);
                    if !accounts.contains_key(&tname) { rejects.push((line_no, format!("line {}: REJECT unknown account {}", line_no, tname))); ok = false; break; }
                    let tacc = accounts.get(&tname).unwrap();
                    if tacc.currency != from_acc.currency { rejects.push((line_no, format!("line {}: REJECT currency mismatch", line_no))); ok = false; break; }
                    targets.push((tname, w));
                }
                if !ok { continue; }
                let w_sum: u128 = targets.iter().map(|(_, w)| *w as u128).sum();
                if w_sum == 0 { continue; }
                let mut shares = Vec::new();
                let mut sum_q = BigInt::zero();
                for (tname, w) in &targets {
                    let prod = amt_r.mul_small(*w as u64);
                    let (q, rem) = prod.div_small(w_sum as u64);
                    sum_q = sum_q.add(&q);
                    shares.push((tname.clone(), q, rem));
                }
                let leftover_big = amt_r.sub(&sum_q);
                let leftover_u = leftover_big.to_u64().unwrap_or(0);
                let mut order: Vec<usize> = (0..shares.len()).collect();
                order.sort_by(|&i, &j| {
                    let ri = shares[i].2;
                    let rj = shares[j].2;
                    if ri != rj { rj.cmp(&ri) } else { i.cmp(&j) }
                });
                let mut extra = vec![0u32; shares.len()];
                let mut left = leftover_u;
                for idx in order {
                    if left == 0 { break; }
                    extra[idx] = 1;
                    left -= 1;
                }
                // apply
                let f = accounts.get_mut(&from).unwrap();
                f.balance = f.balance.sub(&amt_r);
                for (i, (tname, q, _)) in shares.iter().enumerate() {
                    let add_amt = if extra[i] > 0 { q.add_small(1) } else { q.clone() };
                    let t = accounts.get_mut(tname).unwrap();
                    t.balance = t.balance.add(&add_amt);
                }
            }
            _ => {}
        }
    }

    for (_, msg) in &rejects { println!("{}", msg); }
    if !rejects.is_empty() { println!(); }

    let mut accs: Vec<(&String, &Account)> = accounts.iter().collect();
    accs.sort_by_key(|(k, _)| *k);
    for (name, acc) in accs {
        let minor = *currencies.get(&acc.currency).unwrap_or(&0);
        let bal_str = format_balance(&acc.balance, minor);
        println!("{} {} {}", name, acc.currency, bal_str);
    }
    println!();
    let mut totals: HashMap<String, (BigInt, usize)> = HashMap::new();
    for acc in accounts.values() {
        let entry = totals.entry(acc.currency.clone()).or_insert((BigInt::zero(), 0));
        entry.0 = entry.0.add(&acc.balance);
        entry.1 += 1;
    }
    let mut tot_vec: Vec<(String, BigInt, usize)> = totals.into_iter().map(|(k, (b, c))| (k, b, c)).collect();
    tot_vec.sort_by(|a, b| a.0.cmp(&b.0));
    for (code, sum, cnt) in tot_vec {
        let minor = *currencies.get(&code).unwrap_or(&0);
        let sum_str = format_balance(&sum, minor);
        println!("total {} {} ({} accounts)", code, sum_str, cnt);
    }
}

use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn normalize_line_endings(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(data.len());
    let mut i = 0;
    while i < data.len() {
        if data[i] == b'\r' && i + 1 < data.len() && data[i + 1] == b'\n' {
            out.push(b'\n');
            i += 2;
        } else {
            out.push(data[i]);
            i += 1;
        }
    }
    out
}

fn parse_headers(data: &[u8], start: usize) -> (HashMap<String, String>, usize) {
    let mut pos = start;
    let mut headers = HashMap::new();
    let mut cur_name: Option<String> = None;
    let mut cur_val = Vec::new();
    loop {
        let line_end = match data[pos..].iter().position(|&b| b == b'\n') {
            Some(i) => pos + i,
            None => data.len(),
        };
        let line = &data[pos..line_end];
        if line.is_empty() {
            if let Some(n) = cur_name.take() {
                headers.insert(n, String::from_utf8_lossy(&cur_val).to_string());
            }
            let body_start = line_end + 1;
            return (headers, body_start);
        }
        if line.starts_with(b' ') || line.starts_with(b'\t') {
            cur_val.extend_from_slice(line);
        } else {
            if let Some(n) = cur_name.take() {
                headers.insert(n, String::from_utf8_lossy(&cur_val).to_string());
            }
            if let Some(col) = line.iter().position(|&b| b == b':') {
                let name = String::from_utf8_lossy(&line[..col]).trim().to_string().to_lowercase();
                let val = String::from_utf8_lossy(&line[col + 1..]).trim_matches(|c| c == ' ' || c == '\t').to_string();
                cur_name = Some(name);
                cur_val = val.into_bytes();
            } else {
                cur_name = None;
                cur_val.clear();
            }
        }
        pos = line_end + 1;
    }
}

fn parse_content_type(value: &str) -> (String, String, HashMap<String, String>) {
    let mut parts = value.split(';');
    let first = parts.next().unwrap_or("").trim();
    let mut type_str = "text/plain".to_string();
    let mut subtype_str = "plain".to_string();
    if let Some(slash) = first.find('/') {
        type_str = first[..slash].trim().to_lowercase();
        subtype_str = first[slash + 1..].trim().to_lowercase();
    }
    let mut params = HashMap::new();
    for p in parts {
        let p = p.trim();
        if p.is_empty() { continue; }
        if let Some(eq) = p.find('=') {
            let k = p[..eq].trim().to_lowercase();
            let mut v = p[eq + 1..].trim().to_string();
            if v.starts_with('"') {
                v = unquote(&v);
            }
            params.insert(k, v);
        }
    }
    (type_str, subtype_str, params)
}

fn unquote(s: &str) -> String {
    if s.len() < 2 { return s.to_string(); }
    let mut out = String::new();
    let bytes = s.as_bytes();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == b'"' { break; }
        if bytes[i] == b'\\' && i + 1 < bytes.len() {
            out.push(bytes[i + 1] as char);
            i += 2;
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    out
}

fn decode_base64_char(c: u8) -> Option<u8> {
    match c {
        b'A'..=b'Z' => Some(c - b'A'),
        b'a'..=b'z' => Some(c - b'a' + 26),
        b'0'..=b'9' => Some(c - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

fn base64_decode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut buf = 0u32;
    let mut bits = 0;
    for &b in input {
        if b == b'=' { break; }
        if let Some(v) = decode_base64_char(b) {
            buf = (buf << 6) | v as u32;
            bits += 6;
            while bits >= 8 {
                bits -= 8;
                out.push((buf >> bits) as u8);
                buf &= (1 << bits) - 1;
            }
        }
    }
    out
}

fn quoted_printable_decode(data: &[u8]) -> Vec<u8> {
    let mut intermediate = Vec::new();
    let mut i = 0;
    while i < data.len() {
        let line_start = i;
        let line_end = data[i..].iter().position(|&b| b == b'\n').map(|p| i + p).unwrap_or(data.len());
        let line = &data[line_start..line_end];
        let trimmed = line.trim_end_matches(|c| c == b' ' || c == b'\t');
        if trimmed.ends_with(b'=') {
            let without = &trimmed[..trimmed.len() - 1];
            intermediate.extend_from_slice(without);
        } else {
            intermediate.extend_from_slice(trimmed);
            if line_end < data.len() {
                intermediate.push(b'\n');
            }
        }
        i = line_end + 1;
    }
    // =XY decoding
    let mut out = Vec::new();
    let mut i = 0;
    while i < intermediate.len() {
        if intermediate[i] == b'=' && i + 2 < intermediate.len() {
            let hi = intermediate[i + 1];
            let lo = intermediate[i + 2];
            if hi.is_ascii_hexdigit() && lo.is_ascii_hexdigit() {
                let val = (hex_val(hi) << 4) + hex_val(lo);
                out.push(val as u8);
                i += 3;
                continue;
            }
        }
        out.push(intermediate[i]);
        i += 1;
    }
    out
}

fn hex_val(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        b'A'..=b'F' => c - b'A' + 10,
        _ => 0,
    }
}

fn decode_q_encoded_text(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'_' {
            out.push(b' ');
            i += 1;
        } else if bytes[i] == b'=' && i + 2 < bytes.len() && bytes[i + 1].is_ascii_hexdigit() && bytes[i + 2].is_ascii_hexdigit() {
            let v = (hex_val(bytes[i + 1]) << 4) + hex_val(bytes[i + 2]);
            out.push(v as u8);
            i += 3;
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    out
}

fn decode_bytes_charset(bytes: &[u8], charset: &str) -> String {
    let cs = charset.to_ascii_lowercase();
    match cs.as_str() {
        "us-ascii" | "ascii" => String::from_utf8_lossy(bytes).to_string(),
        "utf-8" => String::from_utf8_lossy(bytes).to_string(),
        "iso-8859-1" => bytes.iter().map(|&b| char::from_u32(b as u32).unwrap_or('\u{FFFD}')).collect(),
        "windows-1252" => {
            let mut s = String::new();
            for &b in bytes {
                let ch = if b < 0x80 || b >= 0xa0 {
                    char::from_u32(b as u32).unwrap()
                } else {
                    match b {
                        0x80 => '\u{20AC}', 0x81 => '\u{0081}', 0x82 => '\u{201A}', 0x83 => '\u{0192}', 0x84 => '\u{201E}',
                        0x85 => '\u{2026}', 0x86 => '\u{2020}', 0x87 => '\u{2021}', 0x88 => '\u{02C6}', 0x89 => '\u{2030}',
                        0x8a => '\u{0160}', 0x8b => '\u{2039}', 0x8c => '\u{0152}', 0x8d => '\u{008D}', 0x8e => '\u{017D}', 0x8f => '\u{008F}',
                        0x90 => '\u{0090}', 0x91 => '\u{2018}', 0x92 => '\u{2019}', 0x93 => '\u{201C}', 0x94 => '\u{201D}', 0x95 => '\u{2022}',
                        0x96 => '\u{2013}', 0x97 => '\u{2014}', 0x98 => '\u{02DC}', 0x99 => '\u{2122}', 0x9a => '\u{0161}', 0x9b => '\u{203A}',
                        0x9c => '\u{0153}', 0x9d => '\u{009D}', 0x9e => '\u{017E}', 0x9f => '\u{0178}',
                        _ => char::from_u32(b as u32).unwrap(),
                    }
                };
                s.push(ch);
            }
            s
        }
        _ => String::from_utf8_lossy(bytes).to_string(),
    }
}

fn charset_normalize(cs: &str) -> String {
    let cs = cs.to_ascii_lowercase();
    if let Some(pos) = cs.find('*') { cs[..pos].to_string() } else { cs }
}

fn try_parse_encoded_word(text: &str, pos: usize) -> Option<(usize, String, char, String)> {
    if !text[pos..].starts_with("=?") { return None; }
    let mut i = pos + 2;
    let charset_start = i;
    while i < text.len() && text.as_bytes()[i] != b'?' && !text.as_bytes()[i].is_ascii_whitespace() {
        i += 1;
    }
    if i >= text.len() || text.as_bytes()[i] != b'?' { return None; }
    let charset = &text[charset_start..i];
    i += 1;
    if i >= text.len() { return None; }
    let enc = text.as_bytes()[i] as char;
    if !matches!(enc, 'B' | 'b' | 'Q' | 'q') { return None; }
    i += 1;
    if i >= text.len() || text.as_bytes()[i] != b'?' { return None; }
    i += 1;
    let enc_start = i;
    while i < text.len() && text.as_bytes()[i] != b'?' { i += 1; }
    if i >= text.len() || text.as_bytes()[i] != b'?' { return None; }
    i += 1;
    if i >= text.len() || text.as_bytes()[i] != b'=' { return None; }
    let enc_text = &text[enc_start..i - 2];
    Some((pos, charset.to_string(), enc, enc_text.to_string()))
}

fn decode_encoded_words(text: &str) -> String {
    let mut matches = Vec::new();
    let mut i = 0;
    while i < text.len() {
        if let Some((start, charset, enc, enc_text)) = try_parse_encoded_word(text, i) {
            let end = start + 2 + charset.len() + 2 + 2 + enc_text.len() + 2;
            matches.push((start, end, charset, enc, enc_text));
            i = end;
        } else {
            i += 1;
        }
    }
    let mut out = String::new();
    let mut pos = 0;
    let mut idx = 0;
    while idx < matches.len() {
        let (start, end, charset, enc, enc_text) = &matches[idx];
        if *start > pos {
            out.push_str(&text[pos..*start]);
        }
        // collect run
        let mut run_bytes = Vec::new();
        let mut run_charset = charset_normalize(charset);
        let mut run_end = *end;
        let mut j = idx;
        loop {
            let (s, e, cs, en, et) = &matches[j];
            let bytes = if en.eq_ignore_ascii_case(&"B") || en.eq_ignore_ascii_case(&"b") {
                base64_decode(et.as_bytes())
            } else {
                decode_q_encoded_text(et)
            };
            run_bytes.extend_from_slice(&bytes);
            // check next
            let next_j = j + 1;
            if next_j < matches.len() {
                let (ns, ne, ncs, _, _) = &matches[next_j];
                let gap = &text[*e..*ns];
                let adjacent = gap.chars().all(|c| c == ' ' || c == '\t');
                let same_cs = charset_normalize(ncs) == run_charset;
                if adjacent && same_cs {
                    j = next_j;
                    run_end = ne;
                    continue;
                }
            }
            break;
        }
        let decoded = decode_bytes_charset(&run_bytes, &run_charset);
        out.push_str(&decoded);
        pos = run_end;
        idx = j + 1;
    }
    if pos < text.len() {
        out.push_str(&text[pos..]);
    }
    out
}

fn quote_string(s: &str) -> String {
    let mut out = String::from("\"");
    for ch in s.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            c if c < '\u{0020}' || (c >= '\u{007F}' && c <= '\u{009F}') => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => out.push(ch),
        }
    }
    out.push('"');
    out
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xffffffffu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}

fn get_header(headers: &HashMap<String, String>, name: &str) -> Option<String> {
    headers.get(&name.to_lowercase()).cloned()
}

fn parse_transfer_encoding(headers: &HashMap<String, String>) -> String {
    if let Some(v) = get_header(headers, "Content-Transfer-Encoding") {
        v.to_ascii_lowercase()
    } else {
        "7bit".to_string()
    }
}

fn decode_body(data: &[u8], body_start: usize, body_end: usize, encoding: &str) -> Vec<u8> {
    let raw = &data[body_start..body_end];
    match encoding {
        "base64" => base64_decode(raw),
        "quoted-printable" => quoted_printable_decode(raw),
        _ => raw.to_vec(),
    }
}

struct Entity {
    headers: HashMap<String, String>,
    body_start: usize,
    body_end: usize,
    ctype: (String, String, HashMap<String, String>),
    parts: Vec<Entity>,
    is_multipart: bool,
}

fn build_entity(data: &[u8], start: usize, end: usize) -> Entity {
    let (headers, body_start) = parse_headers(data, start);
    let (ct, st, params) = if let Some(v) = get_header(&headers, "Content-Type") {
        parse_content_type(&v)
    } else {
        ("text".to_string(), "plain".to_string(), HashMap::new())
    };
    let is_multipart = ct.eq_ignore_ascii_case("multipart");
    let mut parts = Vec::new();
    if is_multipart {
        if let Some(boundary) = params.get("boundary") {
            let boundary = boundary.clone();
            let mut pos = body_start;
            let mut current_start = None;
            while pos < end {
                let line_end = data[pos..].iter().position(|&b| b == b'\n').map(|i| pos + i).unwrap_or(end);
                let line = &data[pos..line_end];
                let trimmed = line.trim_matches(|c| c == b' ' || c == b'\t');
                let delim = format!("--{}", boundary);
                let close = format!("--{}--", boundary);
                let is_delim = trimmed == delim.as_bytes() || trimmed == close.as_bytes();
                if is_delim {
                    if let Some(s) = current_start {
                        let part_end = pos;
                        let part = build_entity(data, s, part_end);
                        parts.push(part);
                    }
                    if trimmed == close.as_bytes() {
                        break;
                    }
                    current_start = Some(line_end + 1);
                }
                pos = line_end + 1;
            }
        }
    }
    let body_end = if is_multipart { body_start } else { end };
    Entity { headers, body_start, body_end, ctype: (ct, st, params), parts, is_multipart }
}

fn print_entity(data: &[u8], ent: &Entity, depth: usize, first: bool) {
    let (ct, st, params) = &ent.ctype;
    let indent = "  ".repeat(depth);
    let encoding = parse_transfer_encoding(&ent.headers);
    if ent.is_multipart {
        println!("{}{} parts={}", indent, format!("multipart/{}", st.to_lowercase()), ent.parts.len());
        for p in &ent.parts {
            print_entity(data, p, depth + 1, false);
        }
        return;
    }
    let disposition = get_header(&ent.headers, "Content-Disposition").unwrap_or_default();
    let disp_type = if disposition.to_lowercase().contains("attachment") { "attachment" } else if disposition.to_lowercase().contains("inline") { "inline" } else { "-" };
    let is_text = ct.eq_ignore_ascii_case("text");
    if is_text {
        let charset = params.get("charset").cloned().unwrap_or_else(|| "us-ascii".to_string()).to_ascii_lowercase();
        let body = decode_body(data, ent.body_start, ent.body_end, &encoding);
        let text = decode_bytes_charset(&body, &charset);
        let text_nl = text.replace("\r\n", "\n").replace('\r', '\n');
        let chars = text_nl.chars().count();
        println!("{}text/{} charset={} cte={} chars={}", indent, st.to_lowercase(), charset, encoding, chars);
        let q = quote_string(&text_nl);
        println!("{}  {}", indent, q);
        return;
    }
    // other part
    let body = decode_body(data, ent.body_start, ent.body_end, &encoding);
    let size = body.len();
    let crc = crc32(&body);
    // name
    let name = "-";
    println!("{}/{ } cte={} disposition={} name={} size={} crc32={:08x}", indent, ct.to_lowercase(), st.to_lowercase(), encoding, disp_type, name, size, crc);
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let mut files: Vec<_> = fs::read_dir(dir).unwrap().filter_map(|e| e.ok()).collect();
    files.sort_by_key(|e| e.file_name());
    let mut first_file = true;
    for entry in files {
        let path = entry.path();
        if !path.is_file() { continue; }
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        let data = fs::read(&path).unwrap();
        let data = normalize_line_endings(&data);
        let entity = build_entity(&data, 0, data.len());
        let from = get_header(&entity.headers, "From").unwrap_or_default();
        let subject = get_header(&entity.headers, "Subject").unwrap_or_default();
        if !first_file { println!(); }
        first_file = false;
        println!("== {}", name);
        println!("From: {}", quote_string(&decode_encoded_words(&from)));
        println!("Subject: {}", quote_string(&decode_encoded_words(&subject)));
        print_entity(&data, &entity, 0, true);
    }
}

use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn normalize_line_endings(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(data.len());
    let mut i = 0;
    while i < data.len() {
        if data[i] == b'\r' && i + 1 < data.len() && data[i + 1] == b'\n' {
            out.push(b'\n');
            i += 2;
        } else {
            out.push(data[i]);
            i += 1;
        }
    }
    out
}

fn parse_headers(data: &[u8], start: usize) -> (HashMap<String, String>, usize) {
    let mut pos = start;
    let mut headers = HashMap::new();
    let mut cur_name: Option<String> = None;
    let mut cur_val = Vec::new();
    loop {
        if pos >= data.len() {
            break;
        }
        let line_end = data[pos..].iter().position(|&b| b == b'\n').map(|i| pos + i).unwrap_or(data.len());
        let line = &data[pos..line_end];
        if line.is_empty() {
            if let Some(n) = cur_name.take() {
                headers.insert(n, String::from_utf8_lossy(&cur_val).to_string());
            }
            return (headers, line_end + 1);
        }
        if line.starts_with(b' ') || line.starts_with(b'\t') {
            cur_val.extend_from_slice(line);
        } else {
            if let Some(n) = cur_name.take() {
                headers.insert(n, String::from_utf8_lossy(&cur_val).to_string());
            }
            if let Some(col) = line.iter().position(|&b| b == b':') {
                let name = String::from_utf8_lossy(&line[..col]).trim().to_string().to_lowercase();
                let mut val = &line[col + 1..];
                let mut start = 0;
                while start < val.len() && (val[start] == b' ' || val[start] == b'\t') {
                    start += 1;
                }
                let mut end = val.len();
                while end > start && (val[end - 1] == b' ' || val[end - 1] == b'\t') {
                    end -= 1;
                }
                let v = &val[start..end];
                cur_name = Some(name);
                cur_val = v.to_vec();
            } else {
                cur_name = None;
                cur_val.clear();
            }
        }
        pos = line_end + 1;
    }
    if let Some(n) = cur_name {
        headers.insert(n, String::from_utf8_lossy(&cur_val).to_string());
    }
    (headers, pos)
}

fn parse_params(s: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for part in s.split(';') {
        let p = part.trim();
        if p.is_empty() { continue; }
        if let Some(eq) = p.find('=') {
            let k = p[..eq].trim().to_lowercase();
            let mut v = p[eq + 1..].trim().to_string();
            if v.starts_with('"') {
                v = parse_quoted(&v);
            }
            map.insert(k, v);
        }
    }
    map
}

fn parse_quoted(s: &str) -> String {
    if s.len() < 2 { return s.to_string(); }
    let bytes = s.as_bytes();
    let mut out = String::new();
    let mut i = 1;
    while i < bytes.len() {
        if bytes[i] == b'"' { break; }
        if bytes[i] == b'\\' && i + 1 < bytes.len() {
            out.push(bytes[i + 1] as char);
            i += 2;
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    out
}

fn parse_content_type_header(s: &str) -> (String, String, HashMap<String, String>) {
    let s = s.trim();
    let mut parts = s.splitn(2, ';');
    let first = parts.next().unwrap_or("").trim();
    let rest = parts.next().unwrap_or("");
    let mut type_str = "text".to_string();
    let mut subtype_str = "plain".to_string();
    if let Some(slash) = first.find('/') {
        type_str = first[..slash].trim().to_lowercase();
        subtype_str = first[slash + 1..].trim().to_lowercase();
    }
    let params = parse_params(rest);
    (type_str, subtype_str, params)
}

fn parse_content_disposition_header(s: &str) -> (String, HashMap<String, String>) {
    let s = s.trim();
    let mut parts = s.splitn(2, ';');
    let first = parts.next().unwrap_or("").trim().to_lowercase();
    let rest = parts.next().unwrap_or("");
    let params = parse_params(rest);
    (first, params)
}

fn hex_val(c: u8) -> u8 {
    match c {
        b'0'..=b'9' => c - b'0',
        b'a'..=b'f' => c - b'a' + 10,
        b'A'..=b'F' => c - b'A' + 10,
        _ => 0,
    }
}

fn base64_decode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut buf = 0u32;
    let mut bits = 0;
    for &b in input {
        if b == b'=' { break; }
        let v = match b {
            b'A'..=b'Z' => Some(b - b'A'),
            b'a'..=b'z' => Some(b - b'a' + 26),
            b'0'..=b'9' => Some(b - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        };
        if let Some(v) = v {
            buf = (buf << 6) | v as u32;
            bits += 6;
            while bits >= 8 {
                bits -= 8;
                out.push((buf >> bits) as u8);
                buf &= if bits == 0 { 0 } else { (1 << bits) - 1 };
            }
        }
    }
    out
}

fn decode_q_encoded_text(s: &str) -> Vec<u8> {
    let mut out = Vec::new();
    for b in s.bytes() {
        if b == b'_' {
            out.push(b' ');
        } else if b == b'=' && s.as_bytes().get(s.as_bytes().iter().position(|&x| x==b).unwrap()+1).is_some() {
            // handled in loop with lookahead
            out.push(b);
        } else {
            out.push(b);
        }
    }
    // proper implementation
    let mut res = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'_' {
            res.push(b' ');
            i += 1;
        } else if bytes[i] == b'=' && i + 2 < bytes.len() && bytes[i+1].is_ascii_hexdigit() && bytes[i+2].is_ascii_hexdigit() {
            let v = (hex_val(bytes[i+1]) << 4) + hex_val(bytes[i+2]);
            res.push(v as u8);
            i += 3;
        } else {
            res.push(bytes[i]);
            i += 1;
        }
    }
    res
}

fn decode_bytes_charset(bytes: &[u8], charset: &str) -> String {
    let cs = charset.to_ascii_lowercase();
    match cs.as_str() {
