struct Token { kind: TokenKind, line: usize }

struct Lexer { src: Vec<char>, pos: usize, line: usize }
impl Lexer {
    fn new(s:String)->Self{Self{src:s.chars().collect(),pos:0,line:1}}
    fn peek(&self)->Option<char>{self.src.get(self.pos).copied()}
    fn next(&mut self)->Option<char>{let c=self.peek(); if let Some(ch)=c{self.pos+=1; if ch=='\n'{self.line+=1}};c}
