}

/* AST */
#[derive(Debug,Clone)]
enum Expr{Int(i64),Str(String),Bool(bool),Nil,Ident(String,usize),Unary{op:UnOp,expr:Box<Expr>,line:usize},Binary{op:BinOp,left:Box<Expr>,right:Box<Expr>,line:usize},Call{callee:Box<Expr>,args:Vec<Expr>,line:usize},Index{obj:Box<Expr>,idx:Box<Expr>,line:usize},Lambda{params:Vec<String>,body:Vec<Stmt>,line:usize},List(Vec<Expr>)}
