/* Parser */
struct Parser{ tokens:Vec<Token>, pos:usize }
impl Parser{
    fn new(toks:Vec<Token>)->Self{Self{tokens:toks,pos:0}}
    fn peek(&self)->&Token{&self.tokens[self.pos]}
    fn next(&mut self)->Token{let t=self.tokens[self.pos].clone();self.pos+=1;t}
    fn expect(&mut self,k:TokenKind)->Token{let t=self.next();if !matches_kind(&t.kind,&k){panic!("unexpected")}t}
    fn parse_program(&mut self)->Vec<Stmt>{let mut s=Vec::new();while self.peek().kind!=TokenKind::Eof{s.push(self.parse_stmt())}s}
    fn parse_stmt(&mut self)->Stmt{
