    fn parse_fn_def(&mut self)->Stmt{self.next();let name=self.parse_ident();self.expect_kind(TokenKind::LParen);let params=self.parse_params();self.expect_kind(TokenKind::RParen);let body=self.parse_block();Stmt::FnDef{name,params,body,line:0}}
    fn parse_if(&mut self)->Stmt{self.next();let c=self.parse_expr();let t=self.parse_block();let e=self.parse_else_opt();Stmt::If{cond:c,then_block:t,else_block:e,line:0}}
    fn parse_else_opt(&mut self)->Option<Box<IfElse>>{if matches!(&self.peek().kind,TokenKind::KwElse){self.next();if matches!(&self.peek().kind,TokenKind::KwIf){let s=self.parse_if();Some(Box::new(IfElse::If(s)))}else{let b=self.parse_block();Some(Box::new(IfElse::Block(b)))}}else{None}}
    fn parse_block(&mut self)->Vec<Stmt>{self.expect_kind(TokenKind::LBrace);let mut s=Vec::new();while !matches!(&self.peek().kind,TokenKind::RBrace){s.push(self.parse_stmt())}self.expect_kind(TokenKind::RBrace);s}
    fn parse_params(&mut self)->Vec<String>{let mut p=Vec::new();if !matches!(&self.peek().kind,TokenKind::RParen){p.push(self.parse_ident());while matches!(&self.peek().kind,TokenKind::Comma){self.next();p.push(self.parse_ident())}}p}
    fn parse_ident(&mut self)->String{match self.next().kind{TokenKind::Ident(s)=>s,_=>panic!()}}
    fn parse_expr(&mut self)->Expr{self.parse_or()}
    fn parse_or(&mut self)->Expr{let mut l=self.parse_and();while matches!(&self.peek().kind,TokenKind::OpOr){let line=self.peek().line;self.next();let r=self.parse_and();l=Expr::Binary{op:BinOp::Or,left:Box::new(l),right:Box::new(r),line}}l}
