    fn parse_mul(&mut self)->Expr{let mut l=self.parse_unary();loop{match &self.peek().kind{TokenKind::OpStar=>{let line=self.peek().line;self.next();let r=self.parse_unary();l=Expr::Binary{op:BinOp::Star,left:Box::new(l),right:Box::new(r),line}},TokenKind::OpSlash=>{let line=self.peek().line;self.next();let r=self.parse_unary();l=Expr::Binary{op:BinOp::Slash,left:Box::new(l),right:Box::new(r),line}},TokenKind::OpPercent=>{let line=self.peek().line;self.next();let r=self.parse_unary();l=Expr::Binary{op:BinOp::Percent,left:Box::new(l),right:Box::new(r),line}},_=>break}}l}
    fn parse_unary(&mut self)->Expr{match &self.peek().kind{TokenKind::OpNot=>{let line=self.peek().line;self.next();let e=self.parse_unary();Expr::Unary{op:UnOp::Not,expr:Box::new(e),line}},TokenKind::OpMinus=>{let line=self.peek().line;self.next();let e=self.parse_unary();Expr::Unary{op:UnOp::Minus,expr:Box::new(e),line}},_=>self.parse_postfix()}}
