    fn parse_args(&mut self)->Vec<Expr>{let mut a=Vec::new();if !matches!(&self.peek().kind,TokenKind::RParen){a.push(self.parse_expr());while matches!(&self.peek().kind,TokenKind::Comma){self.next();a.push(self.parse_expr())}}a}
    fn parse_opt_expr_before_semi(&mut self)->Option<Expr>{if matches!(&self.peek().kind,TokenKind::Semi){None}else{Some(self.parse_expr())}}
    fn expect_kind(&mut self,k:TokenKind)->Token{let t=self.next();if !matches_kind(&t.kind,&k){panic!("expected")}t}
    fn expr_to_target(&self,e:Expr)->AssignTarget{match e{Expr::Ident(n,_)=>AssignTarget::Ident(n,0),Expr::Index{obj,idx,line}=>AssignTarget::Index{obj:*obj,idx:*idx,line},_=>panic!()}}
