fn matches_kind(a:&TokenKind,b:&TokenKind)->bool{std::mem::discriminant(a)==std::mem::discriminant(b)}

/* Runtime */
#[derive(Debug,Clone)]enum Value{Int(i64),Bool(bool),Str(String),List(Rc<RefCell<Vec<Value>>>),Func(Func),Nil}
#[derive(Debug,Clone)]struct Func{params:Vec<String>,body:Vec<Stmt>,captured:Rc<RefCell<Scope>>}
#[derive(Debug)]struct Scope{vars:HashMap<String,Value>,parent:Option<Rc<RefCell<Scope>>>}
impl Scope{fn new(parent:Option<Rc<RefCell<Scope>>>)->Self{Self{vars:HashMap::new(),parent}}fn get(&self,name:&str)->Option<Value>{if let Some(v)=self.vars.get(name){Some(v.clone())}else{self.parent.as_ref()?.borrow().get(name)}}fn set(&mut self,name:&str,val:Value){self.vars.insert(name.to_string(),val)}fn find_mut(&mut self,name:&str)->Option<Rc<RefCell<Scope>>>{if self.vars.contains_key(name){Some(Rc::new(RefCell::new(Scope{vars:HashMap::new(),parent:None})))}else{self.parent.as_ref().and_then(|p|p.borrow_mut().find_mut(name))}}}

struct Interpreter{scope:Rc<RefCell<Scope>>,builtins:HashMap<String,Value>,out:String,error:Option<(usize,String)>}
impl Interpreter{
