    fn init_builtins(&mut self){
        let s=self.scope.clone();
        let make_fn=|params,body|Value::Func(Func{params,body,captured:s.clone()});
        // print
        let print_fn=Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()});
        // we will handle builtins specially in eval
        self.builtins.insert("print".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("str".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("type".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("len".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("push".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("pop".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("range".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
        self.builtins.insert("slice".to_string(),Value::Func(Func{params:vec![],body:vec![],captured:self.scope.clone()}));
    }
    fn run(&mut self,stmts:&[Stmt]){for s in stmts{self.exec_stmt(s, &mut Control::Normal); if self.error.is_some(){break}}}
    fn exec_stmt(&mut self,stmt:&Stmt,ctrl:&mut Control){
        match stmt{Stmt::Let{ name,expr,line:_ }=>{let v=self.eval_expr(expr);self.scope.borrow_mut().set(name,v)},
        Stmt::FnDef{ name, params, body, line:_ }=>{let f=Value::Func(Func{params:params.clone(),body:body.clone(),captured:self.scope.clone()});self.scope.borrow_mut().set(name,f)},
