        Stmt::While{cond,body,line:_ }=>{loop{let c=self.eval_expr(cond);if !self.is_truthy(&c){break}self.with_new_scope(|sc|{self.scope=Rc::new(RefCell::new(Scope{vars:HashMap::new(),parent:Some(sc.clone())}));for s in body{self.exec_stmt(s,ctrl);if matches!(ctrl,Control::Break){break}if matches!(ctrl,Control::Continue){break}}if matches!(ctrl,Control::Break){self.scope=sc;break}if matches!(ctrl,Control::Continue){self.scope=sc;continue}self.scope=sc})}},
        Stmt::For{var,iter,body,line:_ }=>{let v=self.eval_expr(iter);if let Value::List(rc)=v{let lst=rc.borrow();let len=lst.len();let mut i=0usize;loop{if i>=len{break}let val=lst[i].clone();self.with_new_scope(|sc|{let mut ns=Scope::new(Some(sc.clone()));ns.set(var,val);self.scope=Rc::new(RefCell::new(ns));for s in body{self.exec_stmt(s,ctrl);if matches!(ctrl,Control::Break){self.scope=sc;break}if matches!(ctrl,Control::Continue){}}self.scope=sc});i+=1}},
        Stmt::Return{expr,line:_ }=>{let v=if let Some(e)=expr{self.eval_expr(e)}else{Value::Nil};*ctrl=Control::Return(v)},
        Stmt::Break{..}=>{*ctrl=Control::Break},
        Stmt::Continue{..}=>{*ctrl=Control::Continue},
        Stmt::Assign{target,expr,line:_ }=>{let v=self.eval_expr(expr);match target{AssignTarget::Ident(n,_)=>{self.assign_var(n,v)},AssignTarget::Index{obj,idx,line:_ }=>{let o=self.eval_expr(obj);let i=self.eval_expr(idx);self.assign_index(o,i,v)}},
