    }
}
    fn with_new_scope<F>(&mut self,f:F) where F:FnOnce(Rc<RefCell<Scope>>)->(){let old=self.scope.clone();f(old.clone())}
    fn eval_expr(&mut self,e:&Expr)->Value{match e{Expr::Int(n)=>Value::Int(*n),Expr::Str(s)=>Value::Str(s.clone()),Expr::Bool(b)=>Value::Bool(*b),Expr::Nil=>Value::Nil,Expr::Ident(n,_)=>{self.lookup_var(n)},Expr::Unary{op,expr,line:_ }=>{let v=self.eval_expr(expr);match op{UnOp::Not=>Value::Bool(!self.is_truthy(&v)),UnOp::Minus=>{if let Value::Int(i)=v{Value::Int(-i)}else{self.error("cannot apply - to "+type_name(&v));Value::Nil}}}},
