    if(t->kind==TK_IDENT){ Expr *e=new_expr(EX_VAR); e->var=strdup(t->text); tok_pos++; return e; }
    if(t->kind==TK_LPAREN){ tok_pos++; Expr *e=parse_expr(); expect(TK_RPAREN); Expr *g=new_expr(EX_GROUP); g->group=e; return g; }
    if(t->kind==TK_LBRACK){ tok_pos++; Expr *e=new_expr(EX_LIST); e->cnt=0; e->items=NULL; if(cur()->kind!=TK_RBRACK){ do{ Expr *it=parse_expr(); e->items=realloc(e->items,sizeof(Expr*)*(e->cnt+1)); e->items[e->cnt++]=it; } while(consume_kind(TK_COMMA)); } expect(TK_RBRACK); return e; }
    if(t->kind==TK_FN){
        tok_pos++; expect(TK_LPAREN);
        char **params=NULL; size_t pcnt=0;
        if(cur()->kind==TK_IDENT){ do{ params=realloc(params,sizeof(char*)*(pcnt+1)); params[pcnt++]=strdup(cur()->text); tok_pos++; } while(consume_kind(TK_COMMA)); }
        expect(TK_RPAREN);
        StmtList *body=parse_block();
        Expr *e=new_expr(EX_LAMBDA); e->params=params; e->pcnt=pcnt; e->lambda.body=body; return e;
    }
    error_at(t->line,"syntax");
    return NULL;
}
Expr* parse_postfix(){
    Expr *e=parse_primary();
    while(1){
        if(cur()->kind==TK_LPAREN){
            tok_pos++; Expr **args=NULL; size_t argc=0;
            if(cur()->kind!=TK_RPAREN){ do{ Expr *a=parse_expr(); args=realloc(args,sizeof(Expr*)*(argc+1)); args[argc++]=a; } while(consume_kind(TK_COMMA)); }
            expect(TK_RPAREN);
            Expr *c=new_expr(EX_CALL); c->callee=e; c->args=args; c->argc=argc; e=c;
        } else if(cur()->kind==TK_LBRACK){
            int line=cur()->line; tok_pos++; Expr *idx=parse_expr(); expect(TK_RBRACK);
            Expr *i=new_expr(EX_INDEX); i->obj=e; i->idx=idx; i->line=line; e=i;
        } else break;
    }
    return e;
}
Expr* parse_unary(){
    if(cur()->kind==TK_NOT){ int line=cur()->line; tok_pos++; Expr *e=new_expr(EX_UN); e->op=TK_NOT; e->un.e=parse_unary(); e->line=line; return e; }
    if(cur()->kind==TK_MINUS){ int line=cur()->line; tok_pos++; Expr *e=new_expr(EX_UN); e->op=TK_MINUS; e->un.e=parse_postfix(); e->line=line; return e; }
    return parse_postfix();
}
Expr* parse_mul(){
    Expr *l=parse_unary();
    while(cur()->kind==TK_STAR||cur()->kind==TK_SLASH||cur()->kind==TK_PERCENT){
        int op=cur()->kind; int line=cur()->line; tok_pos++;
        Expr *r=parse_unary();
        Expr *e=new_expr(EX_BIN); e->bin.op=op; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_add(){
    Expr *l=parse_mul();
    while(cur()->kind==TK_PLUS||cur()->kind==TK_MINUS){
        int op=cur()->kind; int line=cur()->line; tok_pos++;
        Expr *r=parse_mul();
        Expr *e=new_expr(EX_BIN); e->bin.op=op; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_cmp(){
    Expr *l=parse_add();
    while(cur()->kind==TK_EQEQ||cur()->kind==TK_NEQ||cur()->kind==TK_LT||cur()->kind==TK_GT||cur()->kind==TK_LTE||cur()->kind==TK_GTE){
        int op=cur()->kind; int line=cur()->line; tok_pos++;
        Expr *r=parse_add();
        Expr *e=new_expr(EX_BIN); e->bin.op=op; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_and(){
    Expr *l=parse_cmp();
    while(cur()->kind==TK_AND){
        int line=cur()->line; tok_pos++;
        Expr *r=parse_cmp();
        Expr *e=new_expr(EX_BIN); e->bin.op=TK_AND; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_or(){
    Expr *l=parse_and();
    while(cur()->kind==TK_OR){
        int line=cur()->line; tok_pos++;
        Expr *r=parse_and();
        Expr *e=new_expr(EX_BIN); e->bin.op=TK_OR; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_expr(){ return parse_or(); }

/* statement parsing */
StmtList* stmtlist_new(){ StmtList *sl=malloc(sizeof(StmtList)); sl->items=NULL; sl->cnt=0; sl->cap=0; return sl; }
void stmtlist_add(StmtList *sl, Stmt *s){ if(sl->cnt==sl->cap){ sl->cap=sl->cap?sl->cap*2:8; sl->items=realloc(sl->items,sizeof(Stmt*)*sl->cap);} sl->items[sl->cnt++]=s; }

StmtList* parse_block(){
    expect(TK_LBRACE);
    StmtList *sl=stmtlist_new();
    while(cur()->kind!=TK_RBRACE && cur()->kind!=TK_EOF){
        Stmt *s=parse_stmt(); if(s) stmtlist_add(sl,s);
    }
    expect(TK_RBRACE);
    return sl;
}
Stmt* parse_stmt(){
    int line=cur()->line;
    if(cur()->kind==TK_LET){
        tok_pos++; char *name=strdup(cur()->text); tok_pos++; expect(TK_ASSIGN); Expr *e=parse_expr(); expect(TK_SEMI);
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_LET; s->line=line; s->let.name=name; s->let.expr_val = (Value){0}; return s;
    }
    if(cur()->kind==TK_FN){
        tok_pos++; char *name=strdup(cur()->text); tok_pos++; expect(TK_LPAREN);
        char **params=NULL; size_t pcnt=0;
        if(cur()->kind==TK_IDENT){ do{ params=realloc(params,sizeof(char*)*(pcnt+1)); params[pcnt++]=strdup(cur()->text); tok_pos++; } while(consume_kind(TK_COMMA)); }
        expect(TK_RPAREN);
        StmtList *body=parse_block();
        Func *f=malloc(sizeof(Func)); f->is_builtin=0; f->capture=NULL; f->params=params; f->param_cnt=pcnt; f->body=body; f->builtin=NULL;
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_FN_DECL; s->line=line; s->fndecl.name=name; s->fndecl.fn=f; return s;
    }
    if(cur()->kind==TK_IF){
        tok_pos++; Expr *cond=parse_expr(); StmtList *thenb=parse_block(); StmtList *elseb=NULL;
        if(consume_kind(TK_ELSE)){ if(cur()->kind==TK_IF) { /* nested */ } else { elseb=parse_block(); } }
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_IF; s->line=line; s->iff.then_block=thenb; s->iff.else_block=elseb; return s;
    }
    if(cur()->kind==TK_WHILE){
        tok_pos++; Expr *cond=parse_expr(); StmtList *body=parse_block();
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_WHILE; s->line=line; s->wh.body=body; return s;
    }
    if(cur()->kind==TK_FOR){
        tok_pos++; char *var=strdup(cur()->text); tok_pos++; expect(TK_IN); Expr *listex=parse_expr(); StmtList *body=parse_block();
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_FOR; s->line=line; s->for_.var=var; s->for_.body=body; return s;
    }
    if(cur()->kind==TK_RETURN){ tok_pos++; Expr *e=NULL; if(cur()->kind!=TK_SEMI) e=parse_expr(); expect(TK_SEMI); Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_RETURN; s->line=line; return s; }
    if(cur()->kind==TK_BREAK){ tok_pos++; expect(TK_SEMI); Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_BREAK; s->line=line; return s; }
    if(cur()->kind==TK_CONTINUE){ tok_pos++; expect(TK_SEMI); Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_CONTINUE; s->line=line; return s; }
    /* expression or assignment */
    Expr *left=parse_expr();
    if(cur()->kind==TK_ASSIGN){
        int aline=cur()->line; tok_pos++; Expr *right=parse_expr(); expect(TK_SEMI);
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_ASSIGN; s->line=line; s->assign.target=...; return s;
    }
    expect(TK_SEMI);
    Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_EXPR; s->line=line; s->expr.expr=left; return s;
    return NULL;
}

