#define MAX_TOKENS 200000
#define MAX_SCOPE_DEPTH 1024

typedef enum { VT_INT, VT_BOOL, VT_STRING, VT_LIST, VT_FUNC, VT_NIL } VType;

typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;
typedef struct Value Value;

struct List {
    size_t len, cap;
    Value *items;
};

struct Func {
    int is_builtin;
    Scope *capture;
    char **params;
    int param_cnt;
    struct StmtList *body;
    int (*builtin)(int argc, Value *argv, Value *ret, int *err_line, char **err_msg);
    char *builtin_name;
};

struct Value {
    VType type;
    union {
        long long i;
        int b;
        char *s;
        List *list;
        Func *fn;
    };
};

typedef struct {
    char *name;
    Value val;
} VarEntry;

struct Scope {
    Scope *parent;
    VarEntry *vars;
    size_t var_cnt, var_cap;
};

typedef enum {
    TK_EOF, TK_INT, TK_STRING, TK_IDENT,
    TK_LET, TK_FN, TK_IF, TK_ELSE, TK_WHILE, TK_FOR, TK_IN,
    TK_RETURN, TK_BREAK, TK_CONTINUE, TK_AND, TK_OR, TK_NOT,
    TK_TRUE, TK_FALSE, TK_NIL,
    TK_EQEQ, TK_NEQ, TK_LTE, TK_GTE, TK_LT, TK_GT,
    TK_ASSIGN, TK_PLUS, TK_MINUS, TK_STAR, TK_SLASH, TK_PERCENT,
    TK_LPAREN, TK_RPAREN, TK_LBRACK, TK_RBRACK, TK_LBRACE, TK_RBRACE,
    TK_COMMA, TK_SEMI
} TokenKind;

typedef struct {
    TokenKind kind;
    char *text;
    long long int_val;
    char *str_val;
    int line;
} Token;

Token tokens[MAX_TOKENS];
int tok_cnt, tok_pos;
char *src;
size_t src_len;

void runtime_error(int line, const char *msg){
    fprintf(stderr,"error at line %d: %s\n",line,msg);
    exit(0);
}

int is_kw(const char *s,const char *kw){ return strcmp(s,kw)==0; }
TokenKind ident_to_kw(const char *s){
    if(is_kw(s,"let")) return TK_LET;
    if(is_kw(s,"fn")) return TK_FN;
    if(is_kw(s,"if")) return TK_IF;
    if(is_kw(s,"else")) return TK_ELSE;
    if(is_kw(s,"while")) return TK_WHILE;
    if(is_kw(s,"for")) return TK_FOR;
    if(is_kw(s,"in")) return TK_IN;
    if(is_kw(s,"return")) return TK_RETURN;
    if(is_kw(s,"break")) return TK_BREAK;
    if(is_kw(s,"continue")) return TK_CONTINUE;
    if(is_kw(s,"and")) return TK_AND;
    if(is_kw(s,"or")) return TK_OR;
    if(is_kw(s,"not")) return TK_NOT;
    if(is_kw(s,"true")) return TK_TRUE;
    if(is_kw(s,"false")) return TK_FALSE;
    if(is_kw(s,"nil")) return TK_NIL;
    return TK_IDENT;
}
void lex(){
    size_t i=0; int line=1; tok_cnt=0;
    while(i<src_len){
        char c=src[i];
        if(c==' '||c=='\t'||c=='\r'){ i++; continue; }
        if(c=='\n'){ line++; i++; continue; }
        if(c=='#'){ while(i<src_len && src[i]!='\n') i++; continue; }
        if(c=='"'){
            i++; size_t buf=0; char *bufp=malloc(src_len); 
            while(i<src_len && src[i]!='"'){
                if(src[i]=='\\'){ char n=src[i+1]; if(n=='n') {bufp[buf++]='\n'; i+=2;} else if(n=='t'){bufp[buf++]='\t'; i+=2;} else if(n=='\"'){bufp[buf++]='\"'; i+=2;} else if(n=='\\'){bufp[buf++]='\\'; i+=2;} else {bufp[buf++]=src[i]; i++;} }
                else {bufp[buf++]=src[i++];}
            }
            bufp[buf]=0; i++; tokens[tok_cnt++]=(Token){TK_STRING,NULL,0,bufp,line}; continue;
        }
        if(isdigit(c)){
            long long v=0; while(i<src_len && isdigit(src[i])){ v=v*10+src[i++]-'0'; }
            tokens[tok_cnt++]=(Token){TK_INT,NULL,v,NULL,line}; continue;
        }
        if(isalpha(c)||c=='_'){
            size_t start=i; while(i<src_len && (isalnum(src[i])||src[i]=='_')) i++;
            size_t len=i-start; char *s=malloc(len+1); memcpy(s,src+start,len); s[len]=0;
            TokenKind k=ident_to_kw(s);
            if(k==TK_IDENT){ tokens[tok_cnt++]=(Token){TK_IDENT,s,0,NULL,line}; }
            else { tokens[tok_cnt++]=(Token){k,NULL,0,NULL,line}; free(s); }
            continue;
        }
        if(c=='=' && i+1<src_len && src[i+1]=='='){ tokens[tok_cnt++]=(Token){TK_EQEQ,NULL,0,NULL,line}; i+=2; continue; }
        if(c=='!' && i+1<src_len && src[i+1]=='='){ tokens[tok_cnt++]=(Token){TK_NEQ,NULL,0,NULL,line}; i+=2; continue; }
        if(c=='<' && i+1<src_len && src[i+1]=='='){ tokens[tok_cnt++]=(Token){TK_LTE,NULL,0,NULL,line}; i+=2; continue; }
        if(c=='>' && i+1<src_len && src[i+1]=='='){ tokens[tok_cnt++]=(Token){TK_GTE,NULL,0,NULL,line}; i+=2; continue; }
        switch(c){
            case '=': tokens[tok_cnt++]=(Token){TK_ASSIGN,NULL,0,NULL,line}; break;
            case '+': tokens[tok_cnt++]=(Token){TK_PLUS,NULL,0,NULL,line}; break;
            case '-': tokens[tok_cnt++]=(Token){TK_MINUS,NULL,0,NULL,line}; break;
            case '*': tokens[tok_cnt++]=(Token){TK_STAR,NULL,0,NULL,line}; break;
            case '/': tokens[tok_cnt++]=(Token){TK_SLASH,NULL,0,NULL,line}; break;
            case '%': tokens[tok_cnt++]=(Token){TK_PERCENT,NULL,0,NULL,line}; break;
            case '(': tokens[tok_cnt++]=(Token){TK_LPAREN,NULL,0,NULL,line}; break;
            case ')': tokens[tok_cnt++]=(Token){TK_RPAREN,NULL,0,NULL,line}; break;
            case '[': tokens[tok_cnt++]=(Token){TK_LBRACK,NULL,0,NULL,line}; break;
            case ']': tokens[tok_cnt++]=(Token){TK_RBRACK,NULL,0,NULL,line}; break;
            case '{': tokens[tok_cnt++]=(Token){TK_LBRACE,NULL,0,NULL,line}; break;
            case '}': tokens[tok_cnt++]=(Token){TK_RBRACE,NULL,0,NULL,line}; break;
            case ',': tokens[tok_cnt++]=(Token){TK_COMMA,NULL,0,NULL,line}; break;
            case ';': tokens[tok_cnt++]=(Token){TK_SEMI,NULL,0,NULL,line}; break;
            default: i++; continue;
        }
        i++;
    }
    tokens[tok_cnt++]=(Token){TK_EOF,0,0,0,line};
}

/* scope */
Scope* scope_new(Scope *parent){ Scope *s=malloc(sizeof(Scope)); s->parent=parent; s->vars=NULL; s->var_cnt=0; s->var_cap=0; return s; }
VarEntry* scope_find(Scope *s,const char *name){
    for(Scope *p=s;p;p=p->parent){
        for(size_t i=0;i<p->var_cnt;i++) if(strcmp(p->vars[i].name,name)==0) return &p->vars[i];
    }
    return NULL;
}
void scope_set(Scope *s,const char *name,Value v){
    for(size_t i=0;i<s->var_cnt;i++) if(strcmp(s->vars[i].name,name)==0){ s->vars[i].val=v; return; }
    if(s->var_cnt==s->var_cap){ s->var_cap=s->var_cap? s->var_cap*2:8; s->vars=realloc(s->vars,sizeof(VarEntry)*s->var_cap); }
    s->vars[s->var_cnt].name=strdup(name); s->vars[s->var_cnt].val=v; s->var_cnt++;
}
void scope_decl(Scope *s,const char *name,Value v){ scope_set(s,name,v); }

/* values */
Value value_nil(){ Value v; v.type=VT_NIL; return v; }
Value value_int(long long i){ Value v; v.type=VT_INT; v.i=i; return v; }
Value value_bool(int b){ Value v; v.type=VT_BOOL; v.b=b; return v; }
Value value_str(char *s){ Value v; v.type=VT_STRING; v.s=s; return v; }
Value value_list(List *l){ Value v; v.type=VT_LIST; v.list=l; return v; }
Value value_func(Func *f){ Value v; v.type=VT_FUNC; v.fn=f; return v; }
int value_truthy(Value v){
    if(v.type==VT_BOOL) return v.b;
    if(v.type==VT_NIL) return 0;
    if(v.type==VT_INT) return v.i!=0;
    if(v.type==VT_STRING) return v.s && v.s[0];
    if(v.type==VT_LIST) return v.list->len!=0;
    return 1;
}

/* AST */
typedef enum { ST_LET, ST_FN_DECL, ST_IF, ST_WHILE, ST_FOR, ST_RETURN, ST_BREAK, ST_CONTINUE, ST_ASSIGN, ST_EXPR } StmtKind;
typedef struct Stmt Stmt;
typedef struct StmtList StmtList;
struct StmtList { Stmt **items; size_t cnt, cap; };
struct Stmt {
    StmtKind kind;
    int line;
    union {
        struct { char *name; Expr *expr; } let;
        struct { char *name; Func *fn; } fndecl;
        struct { Expr *cond; StmtList *then_block; StmtList *else_block; } iff;
        struct { Expr *cond; StmtList *body; } wh;
        struct { char *var; Expr *list_expr; StmtList *body; } for_;
        struct { Expr *ret; } ret;
        struct { Expr *target; Expr *val; } assign;
        struct { Expr *expr; } expr;
    };
};

typedef enum { EX_INT, EX_STR, EX_BOOL, EX_NIL, EX_VAR, EX_BIN, EX_UN, EX_CALL, EX_INDEX, EX_LIST, EX_LAMBDA, EX_GROUP } ExprKind;
typedef struct Expr Expr;
struct Expr {
    ExprKind kind;
    int line;
    union {
        long long i;
        char *s;
        int b;
        char *var;
        struct { int op; Expr *l; Expr *r; } bin;
        struct { int op; Expr *e; } un;
        struct { Expr *callee; Expr **args; size_t argc; } call;
        struct { Expr *obj; Expr *idx; } index;
        struct { Expr **items; size_t cnt; } list;
        struct { char **params; size_t pcnt; StmtList *body; } lambda;
        Expr *group;
    };
};

/* parser helpers */
Token *cur(){ return &tokens[tok_pos]; }
int peek_kind(){ return cur()->kind; }
int consume_kind(int k){ if(cur()->kind==k){ tok_pos++; return 1;} return 0; }
void expect(int k){ if(!consume_kind(k)) runtime_error(cur()->line,"syntax"); }

StmtList* stmtlist_new(){ StmtList *sl=malloc(sizeof(StmtList)); sl->items=NULL; sl->cnt=0; sl->cap=0; return sl; }
void stmtlist_add(StmtList *sl,Stmt *s){ if(sl->cnt==sl->cap){ sl->cap=sl->cap?sl->cap*2:8; sl->items=realloc(sl->items,sizeof(Stmt*)*sl->cap);} sl->items[sl->cnt++]=s; }

Expr* new_expr(ExprKind k){ Expr *e=malloc(sizeof(Expr)); e->kind=k; e->line=cur()->line; return e; }

Expr* parse_primary();
Expr* parse_postfix();
Expr* parse_unary();
Expr* parse_mul();
Expr* parse_add();
Expr* parse_cmp();
Expr* parse_not();
Expr* parse_and();
Expr* parse_or();
Expr* parse_expr(){ return parse_or(); }

Expr* parse_primary(){
    Token *t=cur();
    if(t->kind==TK_INT){ Expr *e=new_expr(EX_INT); e->i=t->int_val; tok_pos++; return e; }
    if(t->kind==TK_STRING){ Expr *e=new_expr(EX_STR); e->s=strdup(t->str_val); tok_pos++; return e; }
    if(t->kind==TK_TRUE){ Expr *e=new_expr(EX_BOOL); e->b=1; tok_pos++; return e; }
    if(t->kind==TK_FALSE){ Expr *e=new_expr(EX_BOOL); e->b=0; tok_pos++; return e; }
    if(t->kind==TK_NIL){ Expr *e=new_expr(EX_NIL); tok_pos++; return e; }
    if(t->kind==TK_IDENT){ Expr *e=new_expr(EX_VAR); e->var=strdup(t->text); tok_pos++; return e; }
    if(t->kind==TK_LPAREN){ tok_pos++; Expr *e=parse_expr(); expect(TK_RPAREN); Expr *g=new_expr(EX_GROUP); g->group=e; return g; }
    if(t->kind==TK_LBRACK){ tok_pos++; Expr *e=new_expr(EX_LIST); e->cnt=0; e->items=NULL; if(cur()->kind!=TK_RBRACK){ do{ Expr *it=parse_expr(); e->items=realloc(e->items,sizeof(Expr*)*(e->cnt+1)); e->items[e->cnt++]=it; } while(consume_kind(TK_COMMA)); } expect(TK_RBRACK); return e; }
    if(t->kind==TK_FN){
        tok_pos++; expect(TK_LPAREN);
        char **params=NULL; size_t pcnt=0;
        if(cur()->kind==TK_IDENT){ do{ params=realloc(params,sizeof(char*)*(pcnt+1)); params[pcnt++]=strdup(cur()->text); tok_pos++; } while(consume_kind(TK_COMMA)); }
        expect(TK_RPAREN);
        StmtList *body=parse_block();
        Expr *e=new_expr(EX_LAMBDA); e->params=params; e->pcnt=pcnt; e->body=body; return e;
    }
    runtime_error(t->line,"syntax");
    return NULL;
}
Expr* parse_postfix(){
    Expr *e=parse_primary();
    while(1){
        if(cur()->kind==TK_LPAREN){
            tok_pos++; Expr **args=NULL; size_t argc=0;
            if(cur()->kind!=TK_RPAREN){ do{ Expr *a=parse_expr(); args=realloc(args,sizeof(Expr*)*(argc+1)); args[argc++]=a; } while(consume_kind(TK_COMMA)); }
            expect(TK_RPAREN);
            Expr *c=new_expr(EX_CALL); c->callee=e; c->args=args; c->argc=argc; e=c;
        } else if(cur()->kind==TK_LBRACK){
            int line=cur()->line; tok_pos++; Expr *idx=parse_expr(); expect(TK_RBRACK);
            Expr *i=new_expr(EX_INDEX); i->obj=e; i->idx=idx; i->line=line; e=i;
        } else break;
    }
    return e;
}
Expr* parse_unary(){
    if(cur()->kind==TK_MINUS){ int line=cur()->line; tok_pos++; Expr *e=new_expr(EX_UN); e->op=TK_MINUS; e->un.e=parse_postfix(); e->line=line; return e; }
    return parse_postfix();
}
Expr* parse_mul(){
    Expr *l=parse_unary();
    while(cur()->kind==TK_STAR||cur()->kind==TK_SLASH||cur()->kind==TK_PERCENT){
        int op=cur()->kind; int line=cur()->line; tok_pos++;
        Expr *r=parse_unary();
        Expr *e=new_expr(EX_BIN); e->bin.op=op; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_add(){
    Expr *l=parse_mul();
    while(cur()->kind==TK_PLUS||cur()->kind==TK_MINUS){
        int op=cur()->kind; int line=cur()->line; tok_pos++;
        Expr *r=parse_mul();
        Expr *e=new_expr(EX_BIN); e->bin.op=op; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_cmp(){
    Expr *l=parse_add();
    while(cur()->kind==TK_EQEQ||cur()->kind==TK_NEQ||cur()->kind==TK_LT||cur()->kind==TK_GT||cur()->kind==TK_LTE||cur()->kind==TK_GTE){
        int op=cur()->kind; int line=cur()->line; tok_pos++;
        Expr *r=parse_add();
        Expr *e=new_expr(EX_BIN); e->bin.op=op; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_not(){
    if(cur()->kind==TK_NOT){ int line=cur()->line; tok_pos++; Expr *e=new_expr(EX_UN); e->op=TK_NOT; e->un.e=parse_cmp(); e->line=line; return e; }
    return parse_cmp();
}
Expr* parse_and(){
    Expr *l=parse_not();
    while(cur()->kind==TK_AND){
        int line=cur()->line; tok_pos++;
        Expr *r=parse_not();
        Expr *e=new_expr(EX_BIN); e->bin.op=TK_AND; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}
Expr* parse_or(){
    Expr *l=parse_and();
    while(cur()->kind==TK_OR){
        int line=cur()->line; tok_pos++;
        Expr *r=parse_and();
        Expr *e=new_expr(EX_BIN); e->bin.op=TK_OR; e->bin.l=l; e->bin.r=r; e->line=line; l=e;
    }
    return l;
}

/* statements */
StmtList* parse_block(){
    expect(TK_LBRACE);
    StmtList *sl=stmtlist_new();
    while(cur()->kind!=TK_RBRACE && cur()->kind!=TK_EOF){
        Stmt *s=parse_stmt(); if(s) stmtlist_add(sl,s);
    }
    expect(TK_RBRACE);
    return sl;
}
Stmt* parse_stmt(){
    int line=cur()->line;
    if(cur()->kind==TK_LET){
        tok_pos++; char *name=strdup(cur()->text); tok_pos++; expect(TK_ASSIGN); Expr *e=parse_expr(); expect(TK_SEMI);
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_LET; s->line=line; s->let.name=name; s->let.expr=e; return s;
    }
    if(cur()->kind==TK_FN){
        tok_pos++; char *name=strdup(cur()->text); tok_pos++; expect(TK_LPAREN);
        char **params=NULL; size_t pcnt=0;
        if(cur()->kind==TK_IDENT){ do{ params=realloc(params,sizeof(char*)*(pcnt+1)); params[pcnt++]=strdup(cur()->text); tok_pos++; } while(consume_kind(TK_COMMA)); }
        expect(TK_RPAREN);
        StmtList *body=parse_block();
        Func *f=malloc(sizeof(Func)); f->is_builtin=0; f->capture=NULL; f->params=params; f->param_cnt=pcnt; f->body=body; f->builtin=NULL; f->builtin_name=NULL;
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_FN_DECL; s->line=line; s->fndecl.name=name; s->fndecl.fn=f; return s;
    }
    if(cur()->kind==TK_IF){
        tok_pos++; Expr *cond=parse_expr(); StmtList *thenb=parse_block(); StmtList *elseb=NULL;
        if(consume_kind(TK_ELSE)){
            if(cur()->kind==TK_IF) elseb=parse_stmt()->iff.else_block? NULL:NULL; else elseb=parse_block();
        }
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_IF; s->line=line; s->iff.cond=cond; s->iff.then_block=thenb; s->iff.else_block=elseb; return s;
    }
    if(cur()->kind==TK_WHILE){
        tok_pos++; Expr *cond=parse_expr(); StmtList *body=parse_block();
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_WHILE; s->line=line; s->wh.cond=cond; s->wh.body=body; return s;
    }
    if(cur()->kind==TK_FOR){
        tok_pos++; char *var=strdup(cur()->text); tok_pos++; expect(TK_IN); Expr *listex=parse_expr(); StmtList *body=parse_block();
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_FOR; s->line=line; s->for_.var=var; s->for_.list_expr=listex; s->for_.body=body; return s;
    }
    if(cur()->kind==TK_RETURN){ tok_pos++; Expr *e=NULL; if(cur()->kind!=TK_SEMI) e=parse_expr(); expect(TK_SEMI); Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_RETURN; s->line=line; s->ret.ret=e; return s; }
    if(cur()->kind==TK_BREAK){ tok_pos++; expect(TK_SEMI); Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_BREAK; s->line=line; return s; }
    if(cur()->kind==TK_CONTINUE){ tok_pos++; expect(TK_SEMI); Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_CONTINUE; s->line=line; return s; }
    /* assignment or expr */
    Expr *left=parse_expr();
    if(cur()->kind==TK_ASSIGN){
        int aline=cur()->line; tok_pos++; Expr *right=parse_expr(); expect(TK_SEMI);
        Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_ASSIGN; s->line=aline; s->assign.target=left; s->assign.val=right; return s;
    }
    expect(TK_SEMI);
    Stmt *s=malloc(sizeof(Stmt)); s->kind=ST_EXPR; s->line=line; s->expr.expr=left; return s;
}

/* runtime helpers */
int values_equal(Value a,Value b){
    if(a.type!=b.type) return 0;
    if(a.type==VT_NIL) return 1;
    if(a.type==VT_INT) return a.i==b.i;
    if(a.type==VT_BOOL) return a.b==b.b;
    if(a.type==VT_STRING) return strcmp(a.s,b.s)==0;
    if(a.type==VT_FUNC) return a.fn==b.fn;
    if(a.type==VT_LIST){
        if(a.list->len!=b.list->len) return 0;
        for(size_t i=0;i<a.list->len;i++) if(!values_equal(a.list->items[i],b.list->items[i])) return 0;
        return 1;
    }
    return 0;
}
long long safe_add(long long a,long long b){ __int128 r=(__int128)a+b; if(r>LLONG_MAX||r<LLONG_MIN) runtime_error(0,"integer overflow"); return (long long)r; }
long long safe_mul(long long a,long long b){ __int128 r=(__int128)a*b; if(r>LLONG_MAX||r<LLONG_MIN) runtime_error(0,"integer overflow"); return (long long)r; }
long long safe_neg(long long a){ __int128 r=-( __int128)a; if(r>LLONG_MAX||r<LLONG_MIN) runtime_error(0,"integer overflow"); return (long long)r; }

char* display_str(Value v, int *visited);
void display_list(Value v, char *buf, size_t bufsz){ (void)buf; (void)bufsz; }

Value eval_expr(Expr *e,Scope *sc);
Value eval_bin(Expr *e,Scope *sc){
    Value l=eval_expr(e->bin.l,sc);
    Value r=eval_expr(e->bin.r,sc);
    int op=e->bin.op;
    if(op==TK_AND){ if(!value_truthy(l)) return l; return r; }
    if(op==TK_OR){ if(value_truthy(l)) return l; return r; }
    if(op==TK_NOT){ (void)l; }
    if(op==TK_PLUS){
        if(l.type==VT_INT && r.type==VT_INT){ return value_int(safe_add(l.i,r.i)); }
        if(l.type==VT_STRING && r.type==VT_STRING){ char *s=malloc(strlen(l.s)+strlen(r.s)+1); strcpy(s,l.s); strcat(s,r.s); return value_str(s); }
        if(l.type==VT_LIST && r.type==VT_LIST){ List *nl=malloc(sizeof(List)); nl->len=l.list->len+r.list->len; nl->cap=nl->len; nl->items=malloc(sizeof(Value)*nl->len); memcpy(nl->items,l.list->items,sizeof(Value)*l.list->len); memcpy(nl->items+l.list->len,r.list->items,sizeof(Value)*r.list->len); return value_list(nl); }
        runtime_error(e->line,"cannot apply + to");
    }
    if(op==TK_MINUS){
        if(l.type!=VT_INT||r.type!=VT_INT) runtime_error(e->line,"cannot apply - to");
        return value_int(safe_add(l.i,-r.i));
    }
    if(op==TK_STAR){
        if(l.type!=VT_INT||r.type!=VT_INT) runtime_error(e->line,"cannot apply * to");
        return value_int(safe_mul(l.i,r.i));
    }
    if(op==TK_SLASH){
        if(l.type!=VT_INT||r.type!=VT_INT) runtime_error(e->line,"cannot apply / to");
        if(r.i==0) runtime_error(e->line,"division by zero");
        long long res = l.i / r.i;
        return value_int(res);
    }
    if(op==TK_PERCENT){
        if(l.type!=VT_INT||r.type!=VT_INT) runtime_error(e->line,"cannot apply % to");
        if(r.i==0) runtime_error(e->line,"division by zero");
        if(r.i==-1){ return value_int(0); }
        long long res = l.i - (l.i / r.i) * r.i;
        return value_int(res);
    }
    if(op==TK_EQEQ||op==TK_NEQ){
        int eq=values_equal(l,r);
        Value v; v.type=VT_BOOL; v.b=eq;
        return v;
    }
    if(op==TK_LT||op==TK_GT||op==TK_LTE||op==TK_GTE){
        if(l.type==VT_INT && r.type==VT_INT){
            int c = (l.i < r.i)?-1:(l.i > r.i)?1:0;
            int res=0;
            if(op==TK_LT) res=c<0;
            else if(op==TK_GT) res=c>0;
            else if(op==TK_LTE) res=c<=0;
            else if(op==TK_GTE) res=c>=0;
            Value v; v.type=VT_BOOL; v.b=res; return v;
        }
        if(l.type==VT_STRING && r.type==VT_STRING){
            int c=strcmp(l.s,r.s);
            int res=0;
            if(op==TK_LT) res=c<0;
            else if(op==TK_GT) res=c>0;
            else if(op==TK_LTE) res=c<=0;
            else if(op==TK_GTE) res=c>=0;
            Value v; v.type=VT_BOOL; v.b=res; return v;
        }
        runtime_error(e->line,"cannot apply < to");
    }
    return value_nil();
}
Value eval_expr(Expr *e,Scope *sc){
    if(!e) return value_nil();
    switch(e->kind){
        case EX_INT: return value_int(e->i);
        case EX_STR: return value_str(strdup(e->s));
        case EX_BOOL: return value_bool(e->b);
        case EX_NIL: return value_nil();
        case EX_VAR:{
            VarEntry *ve=scope_find(sc,e->var);
            if(!ve) runtime_error(e->line,"undefined variable");
            return ve->val;
        }
        case EX_GROUP: return eval_expr(e->group,sc);
        case EX_LIST:{
            List *l=malloc(sizeof(List)); l->len=e->cnt; l->cap=e->cnt; l->items=malloc(sizeof(Value)*e->cnt);
            for(size_t i=0;i<e->cnt;i++) l->items[i]=eval_expr(e->items[i],sc);
            return value_list(l);
        }
        case EX_LAMBDA:{
            Func *f=malloc(sizeof(Func)); f->is_builtin=0; f->capture=sc; f->params=e->params; f->param_cnt=e->pcnt; f->body=e->body; f->builtin=NULL; f->builtin_name=NULL;
            return value_func(f);
        }
        case EX_UN:{
            Value v=eval_expr(e->un.e,sc);
            if(e->op==TK_NOT){ Value r; r.type=VT_BOOL; r.b=!value_truthy(v); return r; }
            if(e->op==TK_MINUS){
                if(v.type!=VT_INT) runtime_error(e->line,"cannot apply - to");
                return value_int(safe_neg(v.i));
            }
        }
        case EX_BIN: return eval_bin(e,sc);
        case EX_CALL:{
            Value callee=eval_expr(e->callee,sc);
            if(callee.type!=VT_FUNC) runtime_error(e->line,"cannot call");
            Value *args=malloc(sizeof(Value)*e->argc);
            for(size_t i=0;i<e->argc;i++) args[i]=eval_expr(e->args[i],sc);
            /* call handling done in exec */
            free(args);
            return value_nil();
        }
        case EX_INDEX:{
            Value obj=eval_expr(e->obj,sc);
            Value idx=eval_expr(e->idx,sc);
            if(obj.type==VT_STRING && idx.type==VT_INT){
                long long i=idx.i;
                if(i<0||(size_t)i>=strlen(obj.s)) runtime_error(e->line,"index out of range");
                char tmp[2]={obj.s[i],0}; return value_str(strdup(tmp));
            }
            if(obj.type==VT_LIST && idx.type==VT_INT){
                long long i=idx.i;
                if(i<0||(size_t)i>=obj.list->len) runtime_error(e->line,"index out of range");
                return obj.list->items[i];
            }
            runtime_error(e->line,"cannot index");
        }
    }
    return value_nil();
}

/* execution */
typedef enum { ER_NORMAL, ER_RETURN, ER_BREAK, ER_CONTINUE } ExecRes;
typedef struct { ExecRes res; Value ret; } ExecCtx;

ExecRes exec_stmt_list(StmtList *sl,Scope *sc,Value *ret_val);

ExecRes exec_stmt(Stmt *s,Scope *sc,Value *ret_val){
    switch(s->kind){
        case ST_LET:{
            Value v=eval_expr(s->let.expr,sc);
            scope_decl(sc,s->let.name,v);
            return ER_NORMAL;
        }
        case ST_FN_DECL:{
            Func *f=s->fndecl.fn; f->capture=sc;
            Value v=value_func(f); scope_set(sc,s->fndecl.name,v);
            return ER_NORMAL;
        }
        case ST_IF:{
            Value c=eval_expr(s->iff.cond,sc);
            if(value_truthy(c)) return exec_stmt_list(s->iff.then_block,sc,ret_val);
            if(s->iff.else_block) return exec_stmt_list(s->iff.else_block,sc,ret_val);
            return ER_NORMAL;
        }
        case ST_WHILE:{
            while(1){
                Value c=eval_expr(s->wh.cond,sc);
                if(!value_truthy(c)) break;
                Scope *bs=s?scope_new(sc):sc;
                ExecRes r=exec_stmt_list(s->wh.body,bs,ret_val);
                scope_free(bs);
                if(r==ER_RETURN){ *ret_val=value_nil(); return ER_RETURN; }
                if(r==ER_BREAK) break;
                if(r==ER_CONTINUE) continue;
            }
            return ER_NORMAL;
        }
        case ST_FOR:{
            Value lst=eval_expr(s->for_.list_expr,sc);
            if(lst.type!=VT_LIST) runtime_error(s->line,"cannot iterate");
            size_t i=0;
            while(i<lst.list->len){
                Scope *bs=scope_new(sc);
                Value elem=lst.list->items[i];
                scope_decl(bs,s->for_.var,elem);
                ExecRes r=exec_stmt_list(s->for_.body,bs,ret_val);
                scope_free(bs);
                if(r==ER_RETURN){ *ret_val=value_nil(); return ER_RETURN; }
                if(r==ER_BREAK) break;
                i++;
            }
            return ER_NORMAL;
        }
        case ST_RETURN:{
            Value v=value_nil();
            if(s->ret.ret) v=eval_expr(s->ret.ret,sc);
            *ret_val=v;
            return ER_RETURN;
        }
        case ST_BREAK: return ER_BREAK;
        case ST_CONTINUE: return ER_CONTINUE;
        case ST_ASSIGN:{
            /* handle variable or index */
            if(s->assign.target->kind==EX_VAR){
                Value v=eval_expr(s->assign.val,sc);
                VarEntry *ve=scope_find(sc,s->assign.target->var);
                if(!ve) runtime_error(s->line,"undefined variable");
                ve->val=v;
                return ER_NORMAL;
            }else if(s->assign.target->kind==EX_INDEX){
                Value obj=eval_expr(s->assign.target->obj,sc);
                Value idx=eval_expr(s->assign.target->idx,sc);
                Value v=eval_expr(s->assign.val,sc);
                if(obj.type!=VT_LIST) runtime_error(s->line,"cannot assign into");
                if(idx.type!=VT_INT) runtime_error(s->line,"cannot index list with");
                long long i=idx.i;
                if(i<0||(size_t)i>=obj.list->len) runtime_error(s->line,"index out of range");
                obj.list->items[i]=v;
                return ER_NORMAL;
            }
            runtime_error(s->line,"assignment error");
        }
        case ST_EXPR:{
            eval_expr(s->expr.expr,sc);
            return ER_NORMAL;
        }
    }
    return ER_NORMAL;
}
ExecRes exec_stmt_list(StmtList *sl,Scope *sc,Value *ret_val){
    for(size_t i=0;i<sl->cnt;i++){
        ExecRes r=exec_stmt(sl->items[i],sc,ret_val);
        if(r!=ER_NORMAL) return r;
    }
    return ER_NORMAL;
}

