    if(argc<2){ fprintf(stderr,"usage\n"); return 1; }
    FILE *f=fopen(argv[1],"rb"); if(!f){ perror("open"); return 1; }
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET); src=malloc(sz+1); fread(src,1,sz,f); src[sz]=0; fclose(f);
