}

import Foundation

// MARK: - CRC32
struct CRC32 {
    static let table: [UInt32] = {
        var t = [UInt32](repeating: 0, count: 256)
        for i in 0..<256 {
            var c = UInt32(i)
            for _ in 0..<8 {
                if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1) } else { c >>= 1 }
            }
            t[i] = c
        }
        return t
    }()
    static func crc32(_ data: [UInt8]) -> UInt32 {
        var crc: UInt32 = 0xffffffff
        for b in data {
            crc = table[Int((crc ^ UInt32(b)) & 0xff)] ^ (crc >> 8)
        }
        return crc ^ 0xffffffff
    }
    static func crc32(_ data: Data) -> UInt32 {
        return crc32([UInt8](data))
    }
}

// MARK: - Adler-32
func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for v in data {
        a = (a + UInt32(v)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

// MARK: - Bit reader
struct BitReader {
    let data: Data
    var pos: Int = 0
    var bitBuf: UInt64 = 0
    var bitCnt: Int = 0
    init(_ data: Data) { self.data = data }
    mutating func fill(_ n: Int) {
        while bitCnt < n && pos < data.count {
            bitBuf |= UInt64(data[pos]) << bitCnt
            bitCnt += 8
            pos += 1
        }
    }
    mutating func readBits(_ n: Int) -> Int {
        fill(n)
        let v = Int(bitBuf & ((1 << n) - 1))
        bitBuf >>= n
        bitCnt -= n
        return v
    }
    mutating func align() {
        bitCnt = 0
        bitBuf = 0
        if pos < data.count {
            let rem = pos % 1
            // just drop bits
        }
        // move to next byte
        if bitCnt > 0 {
            pos += 1
            bitCnt = 0
            bitBuf = 0
        }
    }
}

// MARK: - DEFLATE
enum BlockType { case stored, fixed, dynamic }

struct InflateResult {
    var output: Data
    var blocks: [BlockType]
}

func inflateZlib(_ data: Data) -> InflateResult? {
    guard data.count >= 6 else { return nil }
