// MARK: - PNG parsing
struct ChunkInfo {
    let type: String
    let data: Data
    let index: Int
}

func parsePNG(_ data: Data) -> (chunks: [ChunkInfo], ihdr: Data?, idat: Data, plte: Data?, trns: Data?, errorChunk: (Int,String)?) {
    guard data.count >= 8 else { return ([], nil, Data(), nil, nil, nil) }
    let sig: [UInt8] = [0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A]
    if ![UInt8](data.prefix(8)].elementsEqual(sig) { return ([], nil, Data(), nil, nil, nil) }
    var offset = 8
    var idx = 1
    var chunks: [ChunkInfo] = []
    var ihdr: Data? = nil
    var idat = Data()
    var plte: Data? = nil
    var trns: Data? = nil
    var errorChunk: (Int,String)? = nil
    while offset + 8 <= data.count {
        let length = Int(data[offset]) << 24 | Int(data[offset+1]) << 16 | Int(data[offset+2]) << 8 | Int(data[offset+3])
        let typeBytes = data.subdata(in: offset+4..<offset+8)
        let type = String(bytes: [UInt8](typeBytes), encoding: .ascii) ?? ""
        let dataStart = offset+8
        let dataEnd = dataStart + length
        guard dataEnd + 4 <= data.count else { break }
        let chunkData = data.subdata(in: dataStart..<dataEnd)
        let crcStart = dataEnd
        let crcVal = Int(data[crcStart]) << 24 | Int(data[crcStart+1]) << 16 | Int(data[crcStart+2]) << 8 | Int(data[crcStart+3])
        // compute crc
        var crcBuf = Data()
        crcBuf.append(contentsOf: [UInt8](typeBytes))
        crcBuf.append(chunkData)
        let calc = CRC32.crc32(crcBuf)
        if Int(calc) != crcVal {
            errorChunk = (idx, type)
            break
        }
        let ci = ChunkInfo(type: type, data: chunkData, index: idx)
        chunks.append(ci)
        if type == "IHDR" { ihdr = chunkData }
        else if type == "IDAT" { idat.append(chunkData) }
        else if type == "PLTE" { plte = chunkData }
        else if type == "tRNS" { trns = chunkData }
        offset = dataEnd + 4
        idx += 1
        if type == "IEND" { break }
    }
    return (chunks, ihdr, idat, plte, trns, errorChunk)
}

// MARK: - Helpers
func readU32(_ d: Data, _ off: Int) -> UInt32 {
    let b = [UInt8](d[off..<off+4])
    return UInt32(b[0])<<24 | UInt32(b[1])<<16 | UInt32(b[2])<<8 | UInt32(b[3])
}

