fn crc32_table() -> [u32; 256] {
    let mut t = [0u32; 256];
    for i in 0..256 {
        let mut c = i as u32;
        for _ in 0..8 {
            c = if c & 1 != 0 { CRC_POLY ^ (c >> 1) } else { c >> 1 };
        }
        t[i] = c;
    }
    t
}
fn crc32(data: &[u8], table: &[u32; 256]) -> u32 {
    let mut c = 0xffffffffu32;
