    }
    !c
}

fn paeth(a: i32, b: i32, c: i32) -> i32 {
    let p = a + b - c;
    let pa = (p - a).abs();
    let pb = (p - b).abs();
    let pc = (p - c).abs();
    if pa <= pb && pa <= pc { a } else if pb <= pc { b } else { c }
}

struct BitReader<'a> {
    data: &'a [u8],
    byte_pos: usize,
    bit_pos: u8,
}
impl<'a> BitReader<'a> {
    fn new(data: &'a [u8]) -> Self { Self { data, byte_pos: 0, bit_pos: 0 } }
    fn read_bit(&mut self) -> Option<u8> {
        if self.byte_pos >= self.data.len() { return None; }
        let b = (self.data[self.byte_pos] >> (7 - self.bit_pos)) & 1;
        self.bit_pos += 1;
        if self.bit_pos == 8 { self.bit_pos = 0; self.byte_pos += 1; }
        Some(b as u8)
    }
    fn read_bits(&mut self, n: usize) -> Option<u32> {
        let mut v = 0u32;
        for _ in 0..n { v = (v << 1) | self.read_bit()? as u32; }
        Some(v)
    }
    fn align(&mut self) {
        if self.bit_pos != 0 { self.bit_pos = 0; self.byte_pos += 1; }
    }
    fn remaining_bytes(&self) -> usize { self.data.len().saturating_sub(self.byte_pos) }
}

