        next_code[bits] = code;
    }
    let mut res = Vec::new();
    for (sym, &len) in lengths.iter().enumerate() {
        if len == 0 { continue; }
        let bits = len as usize;
        let code = next_code[bits];
        next_code[bits] += 1;
        res.push((code as u32, bits as u8));
