    let table = crc32_table();
    for path in files {
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let data = fs::read(&path).unwrap_or_default();
        println!("== {}", name);
        if data.len() < 8 || &data[0..8] != PNG_SIG {
            // still try
        }
        let mut chunk_types = Vec::new();
        let mut chunk_idx = 0usize;
        let mut pos = 8usize;
        let mut crc_error = None;
        let mut ihdr = None;
        let mut plte_data = Vec::new();
        let mut trns_data = Vec::new();
        let mut idat_data = Vec::new();
        let mut chunks_for_output = Vec::new();
        while pos + 8 <= data.len() {
            chunk_idx += 1;
            if pos + 8 > data.len() { break; }
            let len = u32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize;
            pos += 4;
            let typ = &data[pos..pos+4];
            let typ_str = String::from_utf8_lossy(typ).to_string();
            pos += 4;
            let data_start = pos;
            let data_end = (pos + len).min(data.len());
            let chunk_data = &data[data_start..data_end];
            pos = data_end;
            if pos + 4 > data.len() { break; }
            let crc_read = u32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
            pos += 4;
            let mut crc_buf = Vec::with_capacity(4+len);
            crc_buf.extend_from_slice(typ);
            crc_buf.extend_from_slice(chunk_data);
            let crc_calc = crc32(&crc_buf, &table);
            if crc_calc != crc_read {
                crc_error = Some((chunk_idx, typ_str.clone()));
                break;
            }
            chunks_for_output.push(typ_str.clone());
            match typ_str.as_str() {
                "IHDR" => {
                    if len >= 13 {
                        let w = u32::from_be_bytes([chunk_data[0], chunk_data[1], chunk_data[2], chunk_data[3]]) as u32;
