                "tRNS" => trns_data = chunk_data.to_vec(),
                "IDAT" => idat_data.extend_from_slice(chunk_data),
                _ => {}
            }
            if typ_str == "IEND" { break; }
        }
        if let Some((n, t)) = crc_error {
            println!("error: CRC mismatch in chunk {} {}", n, t);
            continue;
        }
        if ihdr.is_none() {
            // no IHDR
            continue;
        }
        let (width, height, bit_depth, color_type) = ihdr.unwrap();
        // chunk list with runs
        let mut chunk_out = String::new();
        let mut i = 0;
        while i < chunks_for_output.len() {
            let t = &chunks_for_output[i];
            let mut cnt = 1;
            while i + cnt < chunks_for_output.len() && chunks_for_output[i + cnt] == t { cnt += 1; }
            if cnt > 1 { chunk_out.push_str(&format!("{}*{}", t, cnt)); } else { chunk_out.push_str(t); }
            if i + cnt < chunks_for_output.len() { chunk_out.push(' '); }
