let builtinScalars: Set<String> = ["int32","int64","uint32","uint64","sint32","sint64","bool","string","bytes","fixed32","fixed64","sfixed32","sfixed64"]

func lowerCamel(_ s: String) -> String {
    var parts = s.split(separator: "_", omittingEmptySubsequences: false)
