    }
    return res
}

func decodeVarint(_ data: [UInt8], _ offset: inout Int) -> UInt64 {
    var result: UInt64 = 0
    var shift = 0
    while true {
        guard offset < data.count else { break }
        let b = UInt64(data[offset]); offset += 1
        result |= (b & 0x7F) << shift
        if (b & 0x80) == 0 { break }
        shift += 7
    }
    return result
}

func zigZag(_ n: UInt64) -> Int64 { let v = Int64(n); return (v >> 1) ^ - (v & 1) }

func base64Encode(_ data: Data) -> String { data.base64EncodedString() }

func jsonEscape(_ s: String) -> String {
    var out = ""
    for u in s.unicodeScalars {
        switch u.value {
        case 0x08: out += "\\b"
        case 0x09: out += "\\t"
        case 0x0A: out += "\\n"
        case 0x0C: out += "\\f"
        case 0x0D: out += "\\r"
        case 0x22: out += "\\\""
        case 0x5C: out += "\\\\"
        case 0x20..<0x20: out += String(format:"\\u%04x", u.value)
        default: out.append(Character(u))
        }
    }
    return out
}

struct DecodedField {
