            } else { res += String(p) }
        }
    }
    return res
}
func decodeVarint(_ data: [UInt8], _ off: inout Int) -> UInt64 {
    var r: UInt64 = 0; var shift = 0
    while true {
        guard off < data.count else { break }
        let b = UInt64(data[off]); off += 1
        r |= (b & 0x7F) << shift
        if (b & 0x80) == 0 { break }
        shift += 7
    }
    return r
}
func zigZag(_ n: UInt64) -> Int64 { let v = Int64(n); return (v >> 1) ^ - (v & 1) }
func jsonEscape(_ s: String) -> String {
    var out = ""
    for u in s.unicodeScalars {
        switch u.value {
        case 0x08: out += "\\b"
        case 0x09: out += "\\t"
        case 0x0A: out += "\\n"
        case 0x0C: out += "\\f"
        case 0x0D: out += "\\r"
        case 0x22: out += "\\\""
        case 0x5C: out += "\\\\"
        default:
            if u.value < 0x20 {
                out += String(format:"\\u%04x", u.value)
            } else {
                out.append(Character(u))
            }
        }
    }
    return out
}

// ---------- decoding ----------
struct DecodedField {
    let def: FieldDef
    var scalarValue: Any?
    var scalarOccurred = false
    var messageValue: DecodedMessage?
    var messageOccurred = false
    var repeated: [Any] = []
    var map: [String:Any] = [:]
}
class DecodedMessage {
    var fields: [Int:DecodedField] = [:]
    var oneofSel: [String:Int] = [:]
}

func skipUnknown(wire: Int, data: [UInt8], off: inout Int, fieldNum: Int) {
    switch wire {
    case 0: _ = decodeVarint(data, &off)
    case 1: off += 8
    case 2:
        let len = Int(decodeVarint(data, &off)); off += len
    case 5: off += 4
    case 3:
        while off < data.count {
            let key = Int(decodeVarint(data, &off))
            let w = key & 7
            let fn = key >> 3
            if w == 4 && fn == fieldNum { break }
            skipUnknown(wire: w, data: data, off: &off, fieldNum: fn)
        }
    default: break
    }
}

func decodeScalar(typeName: String, wire: Int, data: [UInt8], off: inout Int) -> Any {
    switch typeName {
    case "int32":
        let v = decodeVarint(data, &off)
        return Int32(bitPattern: UInt32(v & 0xffffffff))
    case "uint32":
        return UInt32(decodeVarint(data, &off))
    case "sint32":
        let v = decodeVarint(data, &off); return Int32(zigZag(v))
    case "int64":
        let v = decodeVarint(data, &off); return Int64(bitPattern: v)
    case "uint64":
        return decodeVarint(data, &off)
    case "sint64":
        let v = decodeVarint(data, &off); return zigZag(v)
    case "bool":
        return decodeVarint(data, &off) != 0
    case "fixed32":
        let v = data[off..<off+4].withUnsafeBytes { $0.load(as: UInt32.self) }; off += 4; return UInt32(littleEndian: v)
    case "sfixed32":
        let v = data[off..<off+4].withUnsafeBytes { $0.load(as: Int32.self) }; off += 4; return Int32(littleEndian: v)
    case "fixed64":
        let v = data[off..<off+8].withUnsafeBytes { $0.load(as: UInt64.self) }; off += 8; return UInt64(littleEndian: v)
    case "sfixed64":
        let v = data[off..<off+8].withUnsafeBytes { $0.load(as: Int64.self) }; off += 8; return Int64(littleEndian: v)
    case "string":
        let l = Int(decodeVarint(data, &off)); let b = data[off..<off+l]; off += l; return String(bytes: b, encoding: .utf8) ?? ""
    case "bytes":
        let l = Int(decodeVarint(data, &off)); let b = Data(data[off..<off+l]); off += l; return b.base64EncodedString()
    default: return 0
    }
}

func wireForType(_ t: String) -> Int {
    switch t {
    case "int32","uint32","sint32","int64","uint64","sint64","bool": return 0
    case "fixed32","sfixed32": return 5
    case "fixed64","sfixed64": return 1
    default: return 2
    }
}

func decodeMessageDef(_ def: MessageDef, data: [UInt8], limit: Int, messages: [String:MessageDef], enums: [String:EnumDef]) -> DecodedMessage {
    let msg = DecodedMessage()
    var off = 0
    let end = limit
    while off < end {
        let key = Int(decodeVarint(data, &off))
        let fieldNum = key >> 3
        let wire = key & 7
        guard let fdef = def.fieldsByNumber[fieldNum] else { skipUnknown(wire: wire, data: data, off: &off, fieldNum: fieldNum); continue }
        if fdef.isMap {
            guard wire == 2 else { continue }
            let len = Int(decodeVarint(data, &off))
            let entryEnd = off + len
            var mapKey: String? = nil
            var mapVal: Any? = nil
            var eoff = off
            while eoff < entryEnd {
                let ekey = Int(decodeVarint(data, &eoff))
                let efn = ekey >> 3
                let ewire = ekey & 7
                if efn == 1 {
                    if fdef.mapKeyType == "string" {
                        let l = Int(decodeVarint(data, &eoff)); let b = data[eoff..<eoff+l]; eoff += l; mapKey = String(bytes: b, encoding: .utf8) ?? ""
                    } else {
                        let v = decodeVarint(data, &eoff); mapKey = String(v)
                    }
                } else if efn == 2 {
                    let vt = fdef.mapValueType!
                    if builtinScalars.contains(vt) {
                        mapVal = decodeScalar(typeName: vt, wire: ewire, data: data, off: &eoff)
                    } else if messages[vt] != nil {
                        let subLen = Int(decodeVarint(data, &eoff))
                        let subData = Array(data[eoff..<eoff+subLen])
                        eoff += subLen
                        let subMsg = decodeMessageDef(messages[vt]!, data: subData, limit: subData.count, messages: messages, enums: enums)
                        mapVal = subMsg
                    } else if enums[vt] != nil {
                        let ev = Int(decodeVarint(data, &eoff)); mapVal = ev
                    } else { mapVal = 0 }
                } else { skipUnknown(wire: ewire, data: data, off: &eoff, fieldNum: efn) }
            }
            off = entryEnd
            if let k = mapKey, let v = mapVal {
                if msg.fields[fieldNum] == nil { msg.fields[fieldNum] = DecodedField(def: fdef) }
                msg.fields[fieldNum]!.map[k] = v
            }
            continue
        }
        if let oname = fdef.oneofName {
            msg.oneofSel[oname] = fieldNum
        }
        // decode value
        if fdef.isRepeated {
            if wire == 2 {
                // packed
                let plen = Int(decodeVarint(data, &off))
                let pEnd = off + plen
                while off < pEnd {
                    let ev = decodeScalar(typeName: fdef.typeName, wire: wireForType(fdef.typeName), data: data, off: &off)
                    if msg.fields[fieldNum] == nil { msg.fields[fieldNum] = DecodedField(def: fdef) }
                    msg.fields[fieldNum]!.repeated.append(ev)
                }
            } else {
                let ev = decodeScalar(typeName: fdef.typeName, wire: wire, data: data, off: &off)
                if msg.fields[fieldNum] == nil { msg.fields[fieldNum] = DecodedField(def: fdef) }
                msg.fields[fieldNum]!.repeated.append(ev)
            }
        } else {
            // singular
            if messages[fdef.typeName] != nil {
                // message
                let len = Int(decodeVarint(data, &off))
                let subData = Array(data[off..<off+len])
                off += len
                let subMsg = decodeMessageDef(messages[fdef.typeName]!, data: subData, limit: subData.count, messages: messages, enums: enums)
                if msg.fields[fieldNum] == nil { msg.fields[fieldNum] = DecodedField(def: fdef) }
                if msg.fields[fieldNum]!.messageOccurred {
                    // merge
                    let existing = msg.fields[fieldNum]!.messageValue!
                    for (k,v) in subMsg.fields { existing.fields[k] = v }
                }
                msg.fields[fieldNum]!.messageValue = subMsg
                msg.fields[fieldNum]!.messageOccurred = true
            } else if enums[fdef.typeName] != nil {
                let v = Int(decodeVarint(data, &off))
                if msg.fields[fieldNum] == nil { msg.fields[fieldNum] = DecodedField(def: fdef) }
                msg.fields[fieldNum]!.scalarValue = v
                msg.fields[fieldNum]!.scalarOccurred = true
            } else {
                let v = decodeScalar(typeName: fdef.typeName, wire: wire, data: data, off: &off)
                if msg.fields[fieldNum] == nil { msg.fields[fieldNum] = DecodedField(def: fdef) }
                msg.fields[fieldNum]!.scalarValue = v
                msg.fields[fieldNum]!.scalarOccurred = true
            }
        }
    }
    return msg
}

func jsonValue(_ v: Any, typeName: String?, enums: [String:EnumDef]) -> String {
    if let i = v as? Int {
        if let tn = typeName, ["int64","uint64","sint64","fixed64","sfixed64"].contains(tn) {
            return "\"\(i)\""
        } else { return "\(i)" }
    }
    if let u = v as? UInt {
        if let tn = typeName, ["int64","uint64","sint64","fixed64","sfixed64"].contains(tn) {
            return "\"\(u)\""
        } else { return "\(u)" }
    }
    if let b = v as? Bool { return b ? "true" : "false" }
    if let s = v as? String {
        if typeName == "bytes" { return "\"\(s)\"" }
        if typeName == "string" { return "\"\(jsonEscape(s))\"" }
        return "\"\(jsonEscape(s))\""
    }
    if let dm = v as? DecodedMessage {
        return messageToJSON(dm, messages: [:], enums: enums)
    }
    return "null"
}

func messageToJSON(_ msg: DecodedMessage, messages: [String:MessageDef], enums: [String:EnumDef]) -> String {
    var parts: [String] = []
    let sorted = msg.fields.keys.sorted()
    for fn in sorted {
        guard let df = msg.fields[fn] else { continue }
        let fdef = df.def
        let jname = lowerCamel(fdef.name)
        if fdef.isMap {
            if df.map.isEmpty { continue }
            let keys = df.map.keys.sorted()
            let kvs = keys.map { k -> String in
                let v = df.map[k]!
                let vs: String
                if let dm = v as? DecodedMessage {
                    vs = messageToJSON(dm, messages: messages, enums: enums)
                } else if let en = enums[fdef.mapValueType ?? ""], let rev = en.reverse {
                    if let name = rev[Int(v as? Int ?? 0)] { vs = "\"\(name)\"" } else { vs = "\(v)" }
                } else {
                    vs = jsonValue(v, typeName: fdef.mapValueType, enums: enums)
                }
                return "\"\(jsonEscape(k))\":\(vs)"
            }.joined(separator: ",")
            parts.append("\"\(jname)\":{\(kvs)}")
            continue
        }
        if fdef.isRepeated {
            let arr = df.repeated.map { jsonValue($0, typeName: fdef.typeName, enums: enums) }.joined(separator: ",")
            parts.append("\"\(jname)\":[\(_arr)]")
            continue
        }
        // singular
        let occurred = df.scalarOccurred || df.messageOccurred
        if !occurred { continue }
        if !fdef.isOptional && fdef.oneofName == nil {
            // default omission
            if let sv = df.scalarValue {
                var isDefault = false
                if let i = sv as? Int { isDefault = i == 0 }
                if let b = sv as? Bool { isDefault = !b }
                if let s = sv as? String { isDefault = s.isEmpty }
                if isDefault { continue }
            }
        }
        if df.messageOccurred {
            let sub = messageToJSON(df.messageValue!, messages: messages, enums: enums)
            parts.append("\"\(jname)\":\(sub)")
        } else if df.scalarOccurred {
            let sv = df.scalarValue!
            var out: String
            if let en = enums[fdef.typeName], let rev = en.reverse {
                if let name = rev[Int(sv as? Int ?? 0)] { out = "\"\(name)\"" } else { out = "\(sv)" }
            } else {
                out = jsonValue(sv, typeName: fdef.typeName, enums: enums)
            }
            parts.append("\"\(jname)\":\(out)")
        }
    }
    return "{\(parts.joined(separator: ","))}"
}

