let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dir = args[1]
let schemaURL = URL(fileURLWithPath: dir).appendingPathComponent("schema.proto")
let binURL = URL(fileURLWithPath: dir).appendingPathComponent("messages.bin")
let schemaText = try! String(contentsOf: schemaURL, encoding: .utf8)
let (messages, enums, rootName) = parseSchema(schemaText)
guard let rootName = rootName, let rootDef = messages[rootName] else { exit(0) }
let binData = try! Data(contentsOf: binURL)
var binBytes = [UInt8](binData)
var idx = 0
var outputs: [String] = []
while idx < binBytes.count {
    let len = Int(decodeVarint(binBytes, &idx))
    guard idx + len <= binBytes.count else { break }
    let slice = Array(binBytes[idx..<idx+len])
    idx += len
    let decoded = decodeMessageDef(rootDef, data: slice, limit: slice.count, messages: messages, enums: enums)
    let json = messageToJSON(decoded, messages: messages, enums: enums)
    outputs.append(json)
}
print(outputs.joined(separator: "\n"))

