static int br_need(BitReader *br,int n){
    while(br->bits < n){
        if(br->pos >= br->in_len) return 0;
        br->bitbuf |= (uint32_t)br->in[br->pos++] << br->bits;
        br->bits += 8;
    }
    return 1;
}
static uint32_t br_get(BitReader *br,int n){
    if(!br_need(br,n)) return 0;
    uint32_t v = br->bitbuf & ((1U<<n)-1);
    br->bitbuf >>= n;
    br->bits -= n;
    return v;
}
static void br_align(BitReader *br){
    if(br->bits) { br->bitbuf >>= (br->bits & 7); br->bits &= ~7; }
