function serializeMessage(msgDef: MessageDef, valuesMap: Map<number, any>, present: Set<number>): string {
  const entries: {num:number, name:string, value:any}[] = [];
  for (const [num, fdef] of msgDef.fields.entries()) {
    if (!valuesMap.has(num)) continue;
    const val = valuesMap.get(num);
    const isPresent = present.has(num);
    if (!isPresent && !fdef.isOptional && !fdef.oneof) {
      if (fdef.isRepeated) {
        if (!Array.isArray(val) || val.length===0) continue;
      } else {
        if (isDefaultValue(val, fdef)) continue;
      }
    }
    const camel = toCamel(fdef.name);
    const outVal = formatValue(val, fdef, msgDef, enums, messages);
    entries.push({num, name: camel, value: outVal});
  }
  entries.sort((a,b)=>a.num-b.num);
  const parts = entries.map(e => `${JSON.stringify(e.name)}:${e.value}`);
  return '{' + parts.join('') + '}';
}
function isDefaultValue(v:any, f:FieldDef): boolean {
  if (v===undefined) return true;
  if (typeof v === 'number') return v===0;
  if (typeof v === 'boolean') return v===false;
  if (typeof v === 'string') return v==='';
  if (Buffer.isBuffer(v)) return v.length===0;
  return false;
}
function formatValue(v:any, fdef:FieldDef, msgDef:MessageDef, enums:Map<string,EnumDef>, messages:Map<string,MessageDef>): string {
  if (v===undefined) return 'null';
  if (fdef.isMap) {
    const obj: Record<string,any> = {};
    const entries = Object.entries(v);
    entries.sort((a,b)=> {
      const ka = Number(a[0]); const kb = Number(b[0]);
      if (!isNaN(ka) && !isNaN(kb)) return ka-kb;
      return a[0].localeCompare(b[0]);
    });
    const parts = entries.map(([k, val]) => {
      const keyStr = JSON.stringify(k);
      const valStr = formatValue(val, {type: fdef.mapValueType!}, msgDef, enums, messages);
      return `${keyStr}:${valStr}`;
    });
    return '{' + parts.join('') + '}';
  }
  if (Array.isArray(v)) {
    const parts = v.map(x => formatValue(x, fdef, msgDef, enums, messages));
    return '[' + parts.join('') + ']';
  }
  if (Buffer.isBuffer(v)) {
    return JSON.stringify(v.toString('base64'));
  }
  if (typeof v === 'bigint') {
    return JSON.stringify(v.toString());
  }
  if (typeof v === 'number') {
    return String(v);
  }
  if (typeof v === 'boolean') {
    return v ? 'true' : 'false';
  }
  if (typeof v === 'string') {
    return JSON.stringify(jsonEscapeStr(v));
  }
  if (typeof v === 'object') {
    // nested message
    const subMsg = messages.get(fdef.type);
    if (subMsg) {
      const subVals = new Map<number, any>();
      // v is already a map from number to value
      // For simplicity, assume v is object with numeric keys
      // We'll just serialize recursively via serializeMessage
      // This is messy, assume flat
      return serializeMessage(subMsg, v as Map<number,any>, new Set());
    }
    return '{}';
  }
  return JSON.stringify(String(v));
}
function jsonEscapeStr(s:string){ return s.replace(/\\/g,'\\\\').replace(/"/g,'\\"').replace(/\b/g,'\\b').replace(/\t/g,'\\t').replace(/\n/g,'\\n').replace(/\f/g,'\\f').replace(/\r/g,'\\r').replace(/[\u0000-\u001f]/g,c=> '\\u'+c.charCodeAt(0).toString(16).padStart(4,'0')); }

import fs from 'fs';
import path from 'path';

type FieldDef = {
  number: number;
  name: string;
  type: string;
  isRepeated: boolean;
  isMap: boolean;
  isOptional: boolean;
  oneof?: string;
  mapKeyType?: string;
  mapValueType?: string;
};
type MessageDef = { name: string; fields: Map<number, FieldDef> };
type EnumDef = { name: string; values: Map<number, string> };

const SCALARS = new Set([
  'int32','int64','uint32','uint64','sint32','sint64','bool','string','bytes',
  'fixed32','fixed64','sfixed32','sfixed64'
]);

function stripComments(t: string): string {
  t = t.replace(/\/\*[\s\S]*?\*\//g, '');
  t = t.replace(/\/\/.*$/gm, '');
  return t;
}
function skipWs(s: string, i: number): number { while (i < s.length && /\s/.test(s[i])) i++; return i; }
function readIdent(s: string, i: number): {name:string, pos:number} {
  i = skipWs(s,i); const start=i; while (i<s.length && /[A-Za-z0-9_]/.test(s[i])) i++; return {name:s.slice(start,i), pos:i};
}
function findMatchingBrace(s: string, openPos: number): number {
  let cnt = 1; let i = openPos+1;
  while (i < s.length && cnt>0) {
    const ch = s[i];
    if (ch === '"') { i++; while (i<s.length && s[i]!=='"') i++; }
    else if (ch === '{') cnt++;
    else if (ch === '}') cnt--;
    i++;
  }
  return i-1;
}
function toCamel(s: string): string {
  return s.replace(/_([a-z])/g, (_,c)=>c.toUpperCase());
}
function jsonEscapeStr(s:string){ return s.replace(/\\/g,'\\\\').replace(/"/g,'\\"').replace(/\b/g,'\\b').replace(/\t/g,'\\t').replace(/\n/g,'\\n').replace(/\f/g,'\\f').replace(/\r/g,'\\r').replace(/[\u0000-\u001f]/g,c=> '\\u'+c.charCodeAt(0).toString(16).padStart(4,'0')); }

function parseSchema(text:string){
  text = stripComments(text);
  const messages = new Map<string, MessageDef>();
  const enums = new Map<string, EnumDef>();
  const order:string[] = [];

  function parseMessageAt(pos:number){
    let i = pos+7; i = skipWs(text,i); const {name,pos:p1}=readIdent(text,i); i=p1; i=skipWs(text,i);
    if (text[i]!=='{') return null;
    const open=i; const close=findMatchingBrace(text,open);
    const body=text.slice(open+1,close);
    const msg:MessageDef={name,fields:new Map()};
    messages.set(name,msg); order.push(name);
    parseMessageBody(msg,body);
    return {name,body,start:pos,end:close+1};
  }

  function parseMessageBody(msg:MessageDef, body:string){
    // remove nested messages/enums for field parsing
    let work = body;
    // nested messages
    let p=0;
    while(true){
      const mIdx=work.indexOf('message',p);
      const eIdx=work.indexOf('enum',p);
      let next=-1; let isMsg=false;
      if(mIdx!==-1 && (eIdx===-1||mIdx<eIdx)){next=mIdx;isMsg=true;}
      else if(eIdx!==-1){next=eIdx;}
      else break;
      let i=next+(isMsg?7:4); i=skipWs(work,i); const {name,pos:p1}=readIdent(work,i); i=p1; i=skipWs(work,i);
      if(work[i]!=='{'){p=next+1;continue;}
      const open=i; const close=findMatchingBrace(work,open);
      const innerBody=work.slice(open+1,close);
      if(isMsg){
        const innerMsg:MessageDef={name,fields:new Map()};
        messages.set(name,innerMsg);
        parseMessageBody(innerMsg,innerBody);
      }else{
        const en:EnumDef={name,values:new Map()};
        const re=/(\w+)\s*=\s*(-?\d+)/g; let m; while((m=re.exec(innerBody))!==null){en.values.set(parseInt(m[2]),m[1]);}
        enums.set(name,en);
      }
      work = work.slice(0,next)+' '.repeat(close-next+1)+work.slice(close+1);
      p=next;
    }
    // oneofs
    let work2=work;
    let idx=0;
    while(true){
      const oIdx=work2.indexOf('oneof',idx);
      if(oIdx===-1) break;
      let i=oIdx+5; i=skipWs(work2,i); const {name:oname,pos:p1}=readIdent(work2,i); i=p1; i=skipWs(work2,i);
      if(work2[i]!=='{'){idx=oIdx+1;continue;}
      const open=i; const close=findMatchingBrace(work2,open);
      const obody=work2.slice(open+1,close);
      parseFieldsInText(obody,msg,oname);
      work2=work2.slice(0,oIdx)+' '.repeat(close-oIdx+1)+work2.slice(close+1);
      idx=oIdx;
    }
    parseFieldsInText(work2,msg,undefined);
  }

  function parseFieldsInText(txt:string,msg:MessageDef,oneofName?:string){
    const re = /(?:(repeated|optional)\s+)?\s*(map<\s*([A-Za-z_][A-Za-z0-9_]*)\s*,\s*([A-Za-z_][A-Za-z0-9_]*)\s*>|([A-Za-z_][A-Za-z0-9_]*))\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(\d+)/g;
    let m;
    while((m=re.exec(txt))!==null){
      const label=m[1];
      const mapKey=m[2]; const mapVal=m[3]; const typ=m[4];
      const fname=m[5]; const fnum=parseInt(m[6]);
      const isMap=!!mapKey;
      const fd:FieldDef={
        number:fnum,
        name:fname,
        type:isMap?'map':typ!,
        isRepeated:label==='repeated',
        isMap,
        isOptional:label==='optional',
        oneof:oneofName,
        mapKeyType:mapKey,
        mapValueType:mapVal,
      };
      msg.fields.set(fnum,fd);
    }
  }

  // find first top level message
  let depth=0; let i=0;
  while(i<text.length){
    if(text[i]==='{') depth++;
    if(text[i]==='}') depth--;
    if(depth===0 && text.startsWith('message',i)){
      parseMessageAt(i);
      i+=7; continue;
    }
    i++;
  }
  const rootName = order[0]||'';
  return {messages,enums,rootName};
}

/* ---------- decoding ---------- */
function readVarint(buf:Buffer,off:number):{value:bigint,off:number}{
  let res=0n; let shift=0n; let i=off;
  while(i<buf.length){
    const b=BigInt(buf[i++]);
    res |= (b & 0x7Fn) << shift;
    if ((b & 0x80n)===0n) return {value:res,off:i};
    shift+=7n;
  }
  throw new Error('varint overflow');
}
function toSigned32(v:bigint){ let m=v & 0xffffffffn; if(m>=0x80000000n) m-=0x100000000n; return Number(m); }
function toSigned64(v:bigint){ if(v>=0x8000000000000000n) return v-0x10000000000000000n; return v; }
function zigzagDecode(v:bigint){ return (v>>1n) ^ -(v&1n); }
function readFixed32(buf:Buffer,off:number){ return {value:buf.readUInt32LE(off), off:off+4}; }
function readFixed64(buf:Buffer,off:number){ const low=BigInt(buf.readUInt32LE(off)); const high=BigInt(buf.readUInt32LE(off+4)); return {value:(high<<32n)|low, off:off+8}; }

function skipUnknown(buf:Buffer,off:number,wire:number,fieldNum?:number){
  if(wire===0){ const {off:o}=readVarint(buf,off); return o; }
  if(wire===1) return off+8;
  if(wire===2){ const {value:len,off:o}=readVarint(buf,off); return o+Number(len); }
  if(wire===5) return off+4;
  if(wire===3){ // group
    while(true){
      const {value:k,off:o}=readVarint(buf,off); off=o;
      const w=Number(k&7n); const fn=Number(k>>3n);
      if(w===4 && fn===fieldNum) break;
      off=skipUnknown(buf,off,w,fn);
    }
    return off;
  }
  return off+1;
}

function decodeMessage(buf:Buffer,start:number,end:number,msgDef:MessageDef,enums:Map<string,EnumDef>,messages:Map<string,MessageDef>){
  const values=new Map<number,any>();
  const present=new Set<number>();
  const oneofCur=new Map<string,number>();
  let off=start;
  while(off<end){
    const {value:key,off:o1}=readVarint(buf,off); off=o1;
    const fieldNum=Number(key>>3n); const wire=Number(key&7n);
    const fdef=msgDef.fields.get(fieldNum);
    if(!fdef){ off=skipUnknown(buf,off,wire); continue; }
    if(fdef.oneof){
      const prev=oneofCur.get(fdef.oneof);
      if(prev!==undefined && prev!==fieldNum){ values.delete(prev); present.delete(prev); }
      oneofCur.set(fdef.oneof,fieldNum);
    }
    if(fdef.isMap){
      if(wire!==2){ off=skipUnknown(buf,off,wire); continue; }
      const {value:len,off:o2}=readVarint(buf,off); off=o2;
      const entryEnd=off+Number(len);
      let kVal: any = undefined; let vVal:any = undefined;
      let eoff=off;
      while(eoff<entryEnd){
        const {value:k2,off:e1}=readVarint(buf,eoff); eoff=e1;
        const fn2=Number(k2>>3n); const w2=Number(k2&7n);
        if(fn2===1){
          const {value,off:e2}=decodeScalar(buf,eoff,w2,fdef.mapKeyType!);
          kVal=value; eoff=e2;
        }else if(fn2===2){
          const {value,off:e2}=decodeFieldValue(buf,eoff,w2,fdef.mapValueType!,enums,messages);
          vVal=value; eoff=e2;
        }else{ eoff=skipUnknown(buf,eoff,w2); }
      }
      off=entryEnd;
      let mapObj=values.get(fieldNum) as Record<string,any> | undefined;
      if(!mapObj){ mapObj={}; values.set(fieldNum,mapObj); present.add(fieldNum); }
      const kStr=String(kVal);
      mapObj[kStr]=vVal;
      continue;
    }
    // decode normal field
    const isMsg=messages.has(fdef.type);
    const isEnum=enums.has(fdef.type);
    if(isMsg){
      if(wire!==2){ off=skipUnknown(buf,off,wire); continue; }
      const {value:len,off:o2}=readVarint(buf,off); off=o2;
      const subEnd=off+Number(len);
      const subRes=decodeMessage(buf,off,subEnd,messages.get(fdef.type)!,enums,messages);
      off=subEnd;
      const existing=values.get(fieldNum);
      if(existing && typeof existing==='object' && !fdef.isRepeated){
        mergeMessage(existing,subRes.values,messages.get(fdef.type)!);
      }else{
        values.set(fieldNum,subRes.values);
      }
      present.add(fieldNum);
    }else if(isEnum){
      const {value,off:o2}=readVarint(buf,off);
      const en=enums.get(fdef.type)!;
      const name=en.values.get(Number(value)) ?? Number(value);
      if(fdef.isRepeated){
        let arr=values.get(fieldNum) as any[]|undefined;
        if(!arr){arr=[]; values.set(fieldNum,arr);}
        arr.push(name);
      }else{
        values.set(fieldNum,name);
        present.add(fieldNum);
      }
      off=o2;
    }else{
      const {value,off:o2}=decodeFieldValue(buf,off,wire,fdef.type,enums,messages);
      if(fdef.isRepeated){
        let arr=values.get(fieldNum) as any[]|undefined;
        if(!arr){arr=[]; values.set(fieldNum,arr);}
        arr.push(value);
      }else{
        values.set(fieldNum,value);
        present.add(fieldNum);
      }
      off=o2;
    }
  }
  return {values,present};
}

function decodeScalar(buf:Buffer,off:number,wire:number,type:string){
  if(wire===0){
    const {value,off:o}=readVarint(buf,off);
    if(type==='bool') return {value:value!==0n,off:o};
    if(type==='int32') return {value:toSigned32(value),off:o};
    if(type==='sint32') return {value:toSigned32(zigzagDecode(value)),off:o};
    if(type==='int64') return {value:toSigned64(value),off:o};
    if(type==='sint64') return {value:toSigned64(zigzagDecode(value)),off:o};
    return {value:Number(value),off:o};
  }
  if(wire===5){ const {value,off:o}=readFixed32(buf,off); return {value,off:o}; }
  if(wire===1){ const {value,off:o}=readFixed64(buf,off); return {value,off:o}; }
  if(wire===2){
    const {value:len,off:o1}=readVarint(buf,off);
    const data=buf.subarray(o1,o1+Number(len));
    if(type==='string') return {value:data.toString('utf8'),off:o1+Number(len)};
    if(type==='bytes') return {value:data,off:o1+Number(len)};
    return {value:data,off:o1+Number(len)};
  }
  return {value:null,off};
}
function decodeFieldValue(buf:Buffer,off:number,wire:number,type:string,enums:Map<string,EnumDef>,messages:Map<string,MessageDef>){
  // reuse scalar logic
  if(SCALARS.has(type) || type==='string' || type==='bytes'){
    return decodeScalar(buf,off,wire,type);
  }
  // fallback
  return {value:null,off};
}
function mergeMessage(target:Map<number,any>,src:Map<number,any>,msgDef:MessageDef){
  for(const [num,val] of src.entries()){
    const fdef=msgDef.fields.get(num);
    if(!fdef) continue;
    if(fdef.isRepeated){
      const t=target.get(num) as any[]|undefined;
      if(!t){target.set(num,[val]);} else {t.push(...(Array.isArray(val)?val:[val]));}
    }else if(messages.has(fdef.type)){
      const t=target.get(num) as Map<number,any>|undefined;
      if(t){mergeMessage(t,val as Map<number,any>,messages.get(fdef.type)!);} else {target.set(num,val);}
    }else{
      target.set(num,val);
    }
  }
}
const messagesGlobal = new Map<string,MessageDef>();

function serializeMessage(msgDef:MessageDef,values:Map<number,any>,present:Set<number>):string{
  const entries:{num:number,name:string,value:string}=[];
  for(const [num,fdef] of msgDef.fields.entries()){
    if(!values.has(num)) continue;
    const isPresent=present.has(num);
    const val=values.get(num);
    if(!isPresent && !fdef.isOptional && !fdef.oneof){
      if(fdef.isRepeated){
        if(!Array.isArray(val)||val.length===0) continue;
      }else{
        if(isDefault(val,fdef)) continue;
      }
    }
    const camel=toCamel(fdef.name);
    const out=formatValue(val,fdef,msgDef);
    entries.push({num,name:camel,value:out});
  }
  entries.sort((a,b)=>a.num-b.num);
  return '{'+entries.map(e=>JSON.stringify(e.name)+':'+e.value).join('')+'}\n';
}
function isDefault(v:any,f:FieldDef){
  if(v===undefined) return true;
  if(typeof v==='number') return v===0;
  if(typeof v==='boolean') return v===false;
  if(typeof v==='string') return v===''; 
  if(Buffer.isBuffer(v)) return v.length===0;
  return false;
}
function formatValue(v:any,fdef:FieldDef,msgDef:MessageDef):string{
  if(v===undefined) return 'null';
  if(fdef.isMap){
    const obj=v as Record<string,any>;
    const keys=Object.keys(obj).sort((a,b)=>Number(a)-Number(b) || a.localeCompare(b));
    const parts=keys.map(k=>JSON.stringify(k)+':'+formatValue(obj[k],{type:fdef.mapValueType!},msgDef));
    return '{'+parts.join('')+'}';
  }
  if(Array.isArray(v)){
    return '['+v.map(x=>formatValue(x,fdef,msgDef)).join(',')+']';
  }
  if(Buffer.isBuffer(v)) return JSON.stringify(v.toString('base64'));
  if(typeof v==='bigint') return JSON.stringify(v.toString());
  if(typeof v==='number') return String(v);
  if(typeof v==='boolean') return v?'true':'false';
  if(typeof v==='string') return JSON.stringify(jsonEscapeStr(v));
  if(v instanceof Map){
    // nested message
    const subDef=messagesGlobal.get(fdef.type);
    if(subDef){
      return serializeMessage(subDef,v, new Set());
    }
  }
  return '{}';
}

// ---- main ----
const dir=process.argv[2];
if(!dir) process.exit(1);
const schemaPath=path.join(dir,'schema.proto');
const binPath=path.join(dir,'messages.bin');
const schemaText=fs.readFileSync(schemaPath,'utf8');
const {messages,enums,rootName}=parseSchema(schemaText);
messagesGlobal.clear(); for(const [k,v] of messages) messagesGlobal.set(k,v);
const rootMsg=messages.get(rootName)!;
const bin=fs.readFileSync(binPath);
let off=0;
let out='';
while(off<bin.length){
  const {value:len,off:o1}=readVarint(bin,off); off=o1;
  const end=off+Number(len);
  const {values,present}=decodeMessage(bin,off,end,rootMsg,enums,messages);
  out+=serializeMessage(rootMsg,values,present);
  off=end;
}
process.stdout.write(out);

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <sys/stat.h>

typedef struct {
    char *data;
    size_t len;
    int has_nl;
} Line;

typedef struct {
    char **lines;
    size_t cnt;
    size_t cap;
} Body;

typedef struct {
    int a,b,c,d;
    Body body;
} Hunk;

typedef struct {
    char *path;
    char kind[8];
    Hunk *hunks;
    size_t hunk_cnt;
    size_t hunk_cap;
} Section;

static int parse_int(const char **p) {
    int v=0;
    while (**p>='0' && **p<='9') { v=v*10+**p-'0'; (*p)++; }
    return v;
}

static void body_add(Body *b, const char *s) {
    if (b->cnt==b->cap) {
        b->cap = b->cap?b->cap*2:16;
        b->lines = realloc(b->lines, b->cap*sizeof(char*));
    }
    b->lines[b->cnt++] = strdup(s);
}

static uint32_t crc32_table[256];
static void crc32_init(void){
    for(int i=0;i<256;i++){
        uint32_t c=i;
        for(int j=0;j<8;j++) c = (c&1)? (c>>1)^0xEDB88320 : c>>1;
        crc32_table[i]=c;
    }
}
static uint32_t crc32_update(uint32_t crc, const unsigned char *data, size_t len){
    for(size_t i=0;i<len;i++) crc = (crc>>1) ^ crc32_table[(crc ^ data[i]) & 0xFF];
    return crc;
}

static int line_equal(const Line *l1, const Line *l2){
    if (l1->len != l2->len) return 0;
    if (l1->has_nl != l2->has_nl) return 0;
    return memcmp(l1->data, l2->data, l1->len)==0;
}

static Line *load_file_lines(const char *path, size_t *out_cnt){
    struct stat st;
    if (stat(path,&st)!=0){ *out_cnt=0; return NULL; }
    size_t sz = st.st_size;
    unsigned char *buf = NULL;
    if (sz){
        buf = malloc(sz);
        FILE *f = fopen(path,"rb");
        fread(buf,1,sz,f);
        fclose(f);
    }
    Line *lines = NULL;
    size_t cnt=0, cap=0;
    size_t pos=0;
    while(pos<sz){
        size_t nxt = pos;
        while(nxt<sz && buf[nxt]!='\n') nxt++;
        size_t len;
        int has_nl=0;
        if (nxt<sz && buf[nxt]=='\n'){
            len = nxt-pos+1;
            has_nl=1;
            pos=nxt+1;
        }else{
            len = sz-pos;
            has_nl=0;
            pos=sz;
        }
        if (cnt==cap){ cap = cap?cap*2:16; lines=realloc(lines,cap*sizeof(Line)); }
        lines[cnt].len=len;
        lines[cnt].has_nl=has_nl;
        lines[cnt].data=malloc(len);
        memcpy(lines[cnt].data, buf+pos-len, len);
        cnt++;
    }
    free(buf);
    *out_cnt=cnt;
    return lines;
}

static void free_lines(Line *lines,size_t cnt){
    for(size_t i=0;i<cnt;i++) free(lines[i].data);
    free(lines);
}

static Line *make_lines_from_hunk(Hunk *h, int *old_cnt, int *new_cnt, int *malformed){
    int b=h->b, d=h->d;
    Line *oldl = NULL; size_t oldc=0, oldcap=0;
    Line *newl = NULL; size_t newc=0, newcap=0;
    for(size_t i=0;i<h->body.cnt;i++){
        char *ln = h->body.lines[i];
        if (!ln) continue;
        if (ln[0]=='\\' && strstr(ln,"No newline")) continue;
        if (ln[0]!=' ' && ln[0]!='-' && ln[0]!='+') continue;
        char marker = ln[0];
        char *content = ln+1;
        size_t clen = strlen(content);
        int has_nl=1;
        if (i+1<h->body.cnt && h->body.lines[i+1][0]=='\\' && strstr(h->body.lines[i+1],"No newline")){
            has_nl=0;
        }
        Line l; l.len=clen; l.has_nl=has_nl; l.data=malloc(clen);
        memcpy(l.data,content,clen);
        if (marker==' '){
            if (oldc==oldcap){ oldcap = oldcap?oldcap*2:16; oldl=realloc(oldl,oldcap*sizeof(Line)); }
            oldl[oldc++]=l; 
            Line l2=l; l2.data=malloc(clen); memcpy(l2.data,content,clen);
            if (newc==newcap){ newcap = newcap?newcap*2:16; newl=realloc(newl,newcap*sizeof(Line)); }
            newl[newc++]=l2;
        }else if (marker=='-'){
            if (oldc==oldcap){ oldcap = oldcap?oldcap*2:16; oldl=realloc(oldl,oldcap*sizeof(Line)); }
            oldl[oldc++]=l;
        }else if (marker=='+'){
            if (newc==newcap){ newcap = newcap?newcap*2:16; newl=realloc(newl,newcap*sizeof(Line)); }
            newl[newc++]=l;
        }
    }
    *old_cnt = (int)oldc;
    *new_cnt = (int)newc;
    *malformed = (oldc!=b || newc!=d);
    if (*malformed){
        free_lines(oldl,oldc);
        free_lines(newl,newc);
        return NULL;
    }
    // pack into single array for caller
    Line *res = malloc((oldc+newc)*sizeof(Line));
    for(size_t i=0;i<oldc;i++) res[i]=oldl[i];
    for(size_t i=0;i<newc;i++) res[oldc+i]=newl[i];
    free(oldl); free(newl);
    return res;
}

int main(int argc,char **argv){
    if (argc<2) return 0;
    char base[1024]; strcpy(base,argv[1]);
    char diff_path[2048]; snprintf(diff_path,sizeof diff_path,"%s/changes.diff",base);
    char tree_path[2048]; snprintf(tree_path,sizeof tree_path,"%s/tree",base);
    crc32_init();

    FILE *df = fopen(diff_path,"r");
    if (!df) return 0;
    char linebuf[8192];
    Section *secs=NULL; size_t scnt=0, scap=0;
    Section *cur_sec=NULL;
    Hunk *cur_hunk=NULL;
    while(fgets(linebuf,sizeof linebuf,df)){
        if (strncmp(linebuf,"diff --git a/",14)==0){
            if (cur_sec){
                if (cur_hunk){ /* finalize */ }
                if (scnt==scap){ scap=scap?scap*2:16; secs=realloc(secs,scap*sizeof(Section)); }
                secs[scnt++]=*cur_sec;
                free(cur_sec);
            }
            cur_sec=calloc(1,sizeof(Section));
            char pbuf[1024];
            sscanf(linebuf,"diff --git a/%[^ ]",pbuf);
            cur_sec->path=strdup(pbuf);
            strcpy(cur_sec->kind,"modify");
            cur_sec->hunks=NULL;
            cur_sec->hunk_cnt=0;
            cur_sec->hunk_cap=0;
            cur_hunk=NULL;
            continue;
        }
        if (!cur_sec) continue;
        if (strncmp(linebuf,"new file mode ",13)==0){ strcpy(cur_sec->kind,"create"); continue; }
        if (strncmp(linebuf,"deleted file mode ",17)==0){ strcpy(cur_sec->kind,"delete"); continue; }
        if (strncmp(linebuf,"@@ ",3)==0){
            if (cur_hunk){
                if (cur_sec->hunk_cnt==cur_sec->hunk_cap){
                    cur_sec->hunk_cap = cur_sec->hunk_cap?cur_sec->hunk_cap*2:8;
                    cur_sec->hunks = realloc(cur_sec->hunks,cur_sec->hunk_cap*sizeof(Hunk));
                }
                cur_sec->hunks[cur_sec->hunk_cnt++]=*cur_hunk;
                free(cur_hunk);
            }
            cur_hunk=calloc(1,sizeof(Hunk));
            char *p=linebuf+3;
            if (*p=='-') p++;
            cur_hunk->a=parse_int((const char**)&p);
            if (*p==','){ p++; cur_hunk->b=parse_int((const char**)&p);} else cur_hunk->b=1;
            if (*p=='+') p++;
            cur_hunk->c=parse_int((const char**)&p);
            if (*p==','){ p++; cur_hunk->d=parse_int((const char**)&p);} else cur_hunk->d=1;
            cur_hunk->body.lines=NULL; cur_hunk->body.cnt=0; cur_hunk->body.cap=0;
            continue;
        }
        if (cur_hunk){
            char *tmp=strdup(linebuf);
            tmp[strcspn(tmp,"\n")]=0;
            body_add(&cur_hunk->body,tmp);
            free(tmp);
        }
    }
    if (cur_sec){
        if (cur_hunk){
            if (cur_sec->hunk_cnt==cur_sec->hunk_cap){
                cur_sec->hunk_cap = cur_sec->hunk_cap?cur_sec->hunk_cap*2:8;
                cur_sec->hunks = realloc(cur_sec->hunks,cur_sec->hunk_cap*sizeof(Hunk));
            }
            cur_sec->hunks[cur_sec->hunk_cnt++]=*cur_hunk;
        }
        if (scnt==scap){ scap++; secs=realloc(secs,scap*sizeof(Section)); }
        secs[scnt++]=*cur_sec;
    }
    fclose(df);

    qsort(secs,scnt,sizeof(Section), (int(*)(const void*,const void*))strcmp);

    for(size_t si=0; si<scnt; ++si){
        Section *sec=&secs[si];
        printf("%s: %s\n",sec->path,sec->kind);
        char fpath[4096];
        snprintf(fpath,sizeof fpath,"%s/%s",tree_path,sec->path);
        struct stat st;
        int exists = stat(fpath,&st)==0;
        int error=0;
        if (strcmp(sec->kind,"create")==0){
            if (exists){ printf("  error: already exists\n"); continue; }
        }else{
            if (!exists){ printf("  error: not found\n"); continue; }
        }
        Line *cur_lines=NULL; size_t cur_cnt=0;
        if (strcmp(sec->kind,"create")==0){
            cur_cnt=0;
        }else{
            cur_lines=load_file_lines(fpath,&cur_cnt);
        }
        int delta=0;
        int all_applied=1;
        int has_hunks = sec->hunk_cnt>0;
        for(size_t hi=0; hi<sec->hunk_cnt; ++hi){
            Hunk *h=&sec->hunks[hi];
            int old_cnt,new_cnt,malformed;
            Line *packed=make_lines_from_hunk(h,&old_cnt,&new_cnt,&malformed);
            int applied=0;
            int applied_pos=0;
            int offset=0;
            if (malformed){
                printf("  hunk %zu: malformed\n",hi+1);
                all_applied=0;
                continue;
            }
            Line *oldl = packed;
            Line *newl = packed+old_cnt;
            int b=h->b, d=h->d;
            if (b==0){
                int P = h->a + delta;
                if (P>=0 && (size_t)P<=cur_cnt){
                    // insert
                    size_t newsize = cur_cnt + d;
                    Line *nl = malloc(newsize*sizeof(Line));
                    size_t idx=0;
                    for(size_t i=0;i<(size_t)P;i++) nl[idx++]=cur_lines[i];
                    for(int i=0;i<d;i++){ nl[idx].len=newl[i].len; nl[idx].has_nl=newl[i].has_nl; nl[idx].data=malloc(newl[i].len); memcpy(nl[idx].data,newl[i].data,newl[i].len); idx++; }
                    for(size_t i=P;i<cur_cnt;i++) nl[idx++]=cur_lines[i];
                    free_lines(cur_lines,cur_cnt);
                    cur_lines=nl; cur_cnt=newsize;
                    applied=1; applied_pos=P; offset=0;
                    delta += d;
                }else{
                    printf("  hunk %zu: rejected\n",hi+1);
                    all_applied=0;
                }
            }else{
                int P = h->a + delta;
                int found_p=-1;
                for(int k=0;;k++){
                    int cand[2]={P+k, P-k};
                    for(int t=0;t<2;t++){
                        int p=cand[t];
                        if (k==0 && t==1) continue;
                        if (p<1) continue;
                        if ((size_t)(p-1+b) > cur_cnt) continue;
                        int ok=1;
                        for(int i=0;i<b;i++){
                            if (!line_equal(&cur_lines[p-1+i], &oldl[i])){ ok=0; break; }
                        }
                        if (ok){ found_p=p; offset=p-P; break; }
                    }
                    if (found_p!=-1) break;
                    if (k>1000) break;
                }
                if (found_p!=-1){
                    // replace
                    size_t newsize = cur_cnt - b + d;
                    Line *nl = malloc(newsize*sizeof(Line));
                    size_t idx=0;
                    size_t start = found_p-1;
                    for(size_t i=0;i<start;i++) nl[idx++]=cur_lines[i];
                    for(int i=0;i<d;i++){ nl[idx].len=newl[i].len; nl[idx].has_nl=newl[i].has_nl; nl[idx].data=malloc(newl[i].len); memcpy(nl[idx].data,newl[i].data,newl[i].len); idx++; }
                    for(size_t i=start+b;i<cur_cnt;i++) nl[idx++]=cur_lines[i];
                    free_lines(cur_lines,cur_cnt);
                    cur_lines=nl; cur_cnt=newsize;
                    applied=1; applied_pos=found_p;
                    delta += d - b;
                }else{
                    printf("  hunk %zu: rejected\n",hi+1);
                    all_applied=0;
                }
            }
            if (applied && !malformed){
                if (b==0) printf("  hunk %zu: applied at %d (offset 0)\n",hi+1,applied_pos);
                else printf("  hunk %zu: applied at %d (offset %+d)\n",hi+1,applied_pos,offset);
            }
            // free packed lines
            for(int i=0;i<old_cnt;i++) free(oldl[i].data);
            for(int i=0;i<new_cnt;i++) free(newl[i].data);
            free(packed);
        }
        if (strcmp(sec->kind,"delete")==0){
            if (all_applied && cur_cnt==0){
                printf("  result: deleted\n");
            }else{
                uint32_t crc=0xFFFFFFFF;
                for(size_t i=0;i<cur_cnt;i++) crc=crc32_update(crc,(unsigned char*)cur_lines[i].data,cur_lines[i].len);
                crc ^= 0xFFFFFFFF;
                printf("  result: %zu lines, crc32 %08x\n",cur_cnt,crc);
            }
        }else{
            uint32_t crc=0xFFFFFFFF;
            for(size_t i=0;i<cur_cnt;i++) crc=crc32_update(crc,(unsigned char*)cur_lines[i].data,cur_lines[i].len);
            crc ^= 0xFFFFFFFF;
            printf("  result: %zu lines, crc32 %08x\n",cur_cnt,crc);
        }
        free_lines(cur_lines,cur_cnt);
    }
    return 0;
}

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <sys/stat.h>
#include <limits.h>

typedef struct {
    unsigned char *data;
    size_t len;
    int has_nl;
} Line;

typedef struct {
    int a,b,c,d;
    Line *old_lines;
    size_t old_cnt;
    Line *new_lines;
    size_t new_cnt;
    int malformed;
} Hunk;

typedef struct {
    char *path;
    char kind[8];
    Hunk *hunks;
    size_t hunk_cnt;
} Section;

static uint32_t crc32_table[256];
static void crc32_init(void){
    for(int i=0;i<256;i++){
        uint32_t c=(uint32_t)i;
        for(int j=0;j<8;j++) c = (c&1)? (c>>1)^0xEDB88320 : c>>1;
        crc32_table[i]=c;
    }
}
static uint32_t crc32_update(uint32_t crc, const unsigned char *data, size_t len){
    for(size_t i=0;i<len;i++) crc = (crc>>1) ^ crc32_table[(crc ^ data[i]) & 0xFF];
    return crc;
}

static int line_equal(const Line *l1, const Line *l2){
    if(l1->len!=l2->len) return 0;
    if(l1->has_nl!=l2->has_nl) return 0;
    return memcmp(l1->data,l2->data,l1->len)==0;
}

static Line *load_file_lines(const char *path, size_t *out_cnt){
    struct stat st;
    if(stat(path,&st)!=0){ *out_cnt=0; return NULL; }
    size_t sz = (size_t)st.st_size;
    unsigned char *buf=NULL;
    if(sz){
        buf=malloc(sz);
        FILE *f=fopen(path,"rb");
        if(f){ fread(buf,1,sz,f); fclose(f); }
    }
    Line *lines=NULL; size_t cnt=0, cap=0;
    size_t pos=0;
    while(pos<sz){
        size_t nxt=pos;
        while(nxt<sz && buf[nxt]!='\n') nxt++;
        size_t len;
        int has_nl=0;
        if(nxt<sz && buf[nxt]=='\n'){
            len=nxt-pos;
            has_nl=1;
            pos=nxt+1;
        }else{
            len=sz-pos;
            has_nl=0;
            pos=sz;
        }
        if(cnt==cap){ cap = cap?cap*2:16; lines=realloc(lines,cap*sizeof(Line)); }
        lines[cnt].len=len;
        lines[cnt].has_nl=has_nl;
        lines[cnt].data=malloc(len);
        memcpy(lines[cnt].data,buf+pos-len,len);
        cnt++;
    }
    free(buf);
    *out_cnt=cnt;
    return lines;
}
static void free_lines(Line *lines,size_t cnt){
    for(size_t i=0;i<cnt;i++) free(lines[i].data);
    free(lines);
}

static int parse_int(const char **p){
    int v=0;
    while(**p>='0' && **p<='9'){ v=v*10+**p-'0'; (*p)++; }
    return v;
}

int main(int argc,char **argv){
    if(argc<2) return 0;
    char base[1024]; strcpy(base,argv[1]);
    char diff_path[2048]; snprintf(diff_path,sizeof diff_path,"%s/changes.diff",base);
    char tree_path[2048]; snprintf(tree_path,sizeof tree_path,"%s/tree",base);
    crc32_init();

    FILE *df=fopen(diff_path,"r");
    if(!df) return 0;
    char buf[8192];
    Section *secs=NULL; size_t scnt=0, scap=0;
    Section *cur_sec=NULL;
    Hunk *cur_hunk=NULL;
    char **body_lines=NULL; size_t body_cnt=0, body_cap=0;

    while(fgets(buf,sizeof buf,df)){
        buf[strcspn(buf,"\n")]=0;
        if(strncmp(buf,"diff --git a/",14)==0){
            if(cur_sec){
                if(cur_hunk){
                    /* finalize previous hunk */
                }
                if(scnt==scap){ scap=scap?scap*2:16; secs=realloc(secs,scap*sizeof(Section)); }
                secs[scnt++]=*cur_sec;
                free(cur_sec->path);
                free(cur_sec);
            }
            cur_sec=calloc(1,sizeof(Section));
            char pbuf[1024];
            sscanf(buf,"diff --git a/%[^ ]",pbuf);
            cur_sec->path=strdup(pbuf);
            strcpy(cur_sec->kind,"modify");
            cur_sec->hunks=NULL;
            cur_sec->hunk_cnt=0;
            cur_hunk=NULL;
            body_cnt=0;
            continue;
        }
        if(!cur_sec) continue;
        if(strncmp(buf,"new file mode ",13)==0){ strcpy(cur_sec->kind,"create"); continue; }
        if(strncmp(buf,"deleted file mode ",17)==0){ strcpy(cur_sec->kind,"delete"); continue; }
        if(strncmp(buf,"@@ ",3)==0){
            if(cur_hunk){
                /* process previous hunk */
                Hunk h; h.a=cur_hunk->a; h.b=cur_hunk->b; h.c=cur_hunk->c; h.d=cur_hunk->d;
                /* build old/new */
                Line *oldl=NULL; size_t oldc=0, oldcap=0;
                Line *newl=NULL; size_t newc=0, newcap=0;
                for(size_t i=0;i<body_cnt;i++){
                    char *ln=body_lines[i];
                    if(ln[0]=='\\' && strstr(ln,"No newline")) continue;
                    char marker=ln[0];
                    char *content=ln+1;
                    int has_nl=1;
                    if(i+1<body_cnt && body_lines[i+1][0]=='\\' && strstr(body_lines[i+1],"No newline")) has_nl=0;
                    size_t clen=strlen(content);
                    Line l; l.len=clen; l.has_nl=has_nl; l.data=malloc(clen); memcpy(l.data,(unsigned char*)content,clen);
                    if(marker==' '){
                        if(oldc==oldcap){ oldcap=oldcap?oldcap*2:16; oldl=realloc(oldl,oldcap*sizeof(Line)); }
                        oldl[oldc++]=l;
                        Line l2=l; l2.data=malloc(clen); memcpy(l2.data,(unsigned char*)content,clen);
                        if(newc==newcap){ newcap=newcap?newcap*2:16; newl=realloc(newl,newcap*sizeof(Line)); }
                        newl[newc++]=l2;
                    }else if(marker=='-'){
                        if(oldc==oldcap){ oldcap=oldcap?oldcap*2:16; oldl=realloc(oldl,oldcap*sizeof(Line)); }
                        oldl[oldc++]=l;
                    }else if(marker=='+'){
                        if(newc==newcap){ newcap=newcap?newcap*2:16; newl=realloc(newl,newcap*sizeof(Line)); }
                        newl[newc++]=l;
                    }
                }
                int malformed = (oldc != (size_t)h.b) || (newc != (size_t)h.d);
                h.old_lines=oldl; h.old_cnt=oldc; h.new_lines=newl; h.new_cnt=newc; h.malformed=malformed;
                /* store */
                cur_sec->hunks=realloc(cur_sec->hunks,(cur_sec->hunk_cnt+1)*sizeof(Hunk));
                cur_sec->hunks[cur_sec->hunk_cnt++]=h;
                free(cur_hunk);
            }
            cur_hunk=calloc(1,sizeof(Hunk));
            char *p=buf+3;
            if(*p=='-') p++;
            cur_hunk->a=parse_int((const char**)&p);
            if(*p==','){ p++; cur_hunk->b=parse_int((const char**)&p);} else cur_hunk->b=1;
            if(*p=='+') p++;
            cur_hunk->c=parse_int((const char**)&p);
            if(*p==','){ p++; cur_hunk->d=parse_int((const char**)&p);} else cur_hunk->d=1;
            body_cnt=0;
            for(size_t i=0;i<body_cap;i++) free(body_lines[i]);
            free(body_lines); body_lines=NULL; body_cap=0;
            continue;
        }
        if(cur_hunk){
            if(body_cnt==body_cap){ body_cap=body_cap?body_cap*2:16; body_lines=realloc(body_lines,body_cap*sizeof(char*)); }
            body_lines[body_cnt++]=strdup(buf);
        }
    }
    if(cur_sec){
        if(cur_hunk){
            Hunk h; h.a=cur_hunk->a; h.b=cur_hunk->b; h.c=cur_hunk->c; h.d=cur_hunk->d;
            Line *oldl=NULL; size_t oldc=0, oldcap=0;
            Line *newl=NULL; size_t newc=0, newcap=0;
            for(size_t i=0;i<body_cnt;i++){
                char *ln=body_lines[i];
                if(ln[0]=='\\' && strstr(ln,"No newline")) continue;
                char marker=ln[0];
                char *content=ln+1;
                int has_nl=1;
                if(i+1<body_cnt && body_lines[i+1][0]=='\\' && strstr(body_lines[i+1],"No newline")) has_nl=0;
                size_t clen=strlen(content);
                Line l; l.len=clen; l.has_nl=has_nl; l.data=malloc(clen); memcpy(l.data,(unsigned char*)content,clen);
                if(marker==' '){
                    if(oldc==oldcap){ oldcap=oldcap?oldcap*2:16; oldl=realloc(oldl,oldcap*sizeof(Line)); }
                    oldl[oldc++]=l;
                    Line l2=l; l2.data=malloc(clen); memcpy(l2.data,(unsigned char*)content,clen);
                    if(newc==newcap){ newcap=newcap?newcap*2:16; newl=realloc(newl,newcap*sizeof(Line)); }
                    newl[newc++]=l2;
                }else if(marker=='-'){
                    if(oldc==oldcap){ oldcap=oldcap?oldcap*2:16; oldl=realloc(oldl,oldcap*sizeof(Line)); }
                    oldl[oldc++]=l;
                }else if(marker=='+'){
                    if(newc==newcap){ newcap=newcap?newcap*2:16; newl=realloc(newl,newcap*sizeof(Line)); }
                    newl[newc++]=l;
                }
            }
            int malformed = (oldc != (size_t)h.b) || (newc != (size_t)h.d);
            h.old_lines=oldl; h.old_cnt=oldc; h.new_lines=newl; h.new_cnt=newc; h.malformed=malformed;
            cur_sec->hunks=realloc(cur_sec->hunks,(cur_sec->hunk_cnt+1)*sizeof(Hunk));
            cur_sec->hunks[cur_sec->hunk_cnt++]=h;
            free(cur_hunk);
        }
        if(scnt==scap){ scap++; secs=realloc(secs,scap*sizeof(Section)); }
        secs[scnt++]=*cur_sec;
    }
    fclose(df);
    for(size_t i=0;i<body_cnt;i++) free(body_lines[i]);
    free(body_lines);

    int cmp_sec(const void *a,const void *b){ return strcmp(((Section*)a)->path, ((Section*)b)->path); }
    qsort(secs,scnt,sizeof(Section),cmp_sec);

    for(size_t si=0; si<scnt; ++si){
        Section *sec=&secs[si];
        printf("%s: %s\n",sec->path,sec->kind);
        char fpath[4096]; snprintf(fpath,sizeof fpath,"%s/%s",tree_path,sec->path);
        struct stat st;
        int exists = stat(fpath,&st)==0;
        int error=0;
        if(strcmp(sec->kind,"create")==0){
            if(exists){ printf("  error: already exists\n"); error=1; }
        }else{
            if(!exists){ printf("  error: not found\n"); error=1; }
        }
        if(error) continue;
        Line *cur_lines=NULL; size_t cur_cnt=0;
        if(strcmp(sec->kind,"create")==0){
            cur_cnt=0;
        }else{
            cur_lines=load_file_lines(fpath,&cur_cnt);
        }
        int delta=0;
        int all_applied=1;
        for(size_t hi=0; hi<sec->hunk_cnt; ++hi){
            Hunk *h=&sec->hunks[hi];
            if(h->malformed){
                printf("  hunk %zu: malformed\n",hi+1);
                all_applied=0;
                continue;
            }
            if(h->b==0){
                int P = h->a + delta;
                if(P>=0 && (size_t)P<=cur_cnt){
                    size_t newsize = cur_cnt + h->d;
                    Line *nl = malloc(newsize*sizeof(Line));
                    size_t idx=0;
                    for(size_t i=0;i<(size_t)P;i++) nl[idx++]=cur_lines[i];
                    for(size_t i=0;i<h->new_cnt;i++){
                        nl[idx].len=h->new_lines[i].len;
                        nl[idx].has_nl=h->new_lines[i].has_nl;
                        nl[idx].data=malloc(h->new_lines[i].len);
                        memcpy(nl[idx].data,h->new_lines[i].data,h->new_lines[i].len);
                        idx++;
                    }
                    for(size_t i=P;i<cur_cnt;i++) nl[idx++]=cur_lines[i];
                    free_lines(cur_lines,cur_cnt);
                    cur_lines=nl; cur_cnt=newsize;
                    printf("  hunk %zu: applied at %d (offset 0)\n",hi+1,P);
                    delta += h->d;
                }else{
                    printf("  hunk %zu: rejected\n",hi+1);
                    all_applied=0;
                }
            }else{
                int P = h->a + delta;
                int found_p=-1;
                int best_off=0;
                for(int k=0;k<=1000;k++){
                    int p1 = P - k;
                    int p2 = P + k;
                    int cand[2]={p1,p2};
                    for(int t=0;t<2;t++){
                        int p=cand[t];
                        if(k==0 && t==1) continue;
                        if(p<1) continue;
                        if((size_t)(p-1+h->b) > cur_cnt) continue;
                        int ok=1;
                        for(int i=0;i<h->b;i++){
                            if(!line_equal(&cur_lines[p-1+i], &h->old_lines[i])){ ok=0; break; }
                        }
                        if(ok){ found_p=p; best_off=p-P; goto found; }
                    }
                }
                found:
                if(found_p!=-1){
                    size_t newsize = cur_cnt - h->b + h->d;
                    Line *nl = malloc(newsize*sizeof(Line));
                    size_t idx=0;
                    size_t start = found_p-1;
                    for(size_t i=0;i<start;i++) nl[idx++]=cur_lines[i];
                    for(size_t i=0;i<h->new_cnt;i++){
                        nl[idx].len=h->new_lines[i].len;
                        nl[idx].has_nl=h->new_lines[i].has_nl;
                        nl[idx].data=malloc(h->new_lines[i].len);
                        memcpy(nl[idx].data,h->new_lines[i].data,h->new_lines[i].len);
                        idx++;
                    }
                    for(size_t i=start+h->b;i<cur_cnt;i++) nl[idx++]=cur_lines[i];
                    free_lines(cur_lines,cur_cnt);
                    cur_lines=nl; cur_cnt=newsize;
                    printf("  hunk %zu: applied at %d (offset %+d)\n",hi+1,found_p,best_off);
                    delta += h->d - h->b;
                }else{
                    printf("  hunk %zu: rejected\n",hi+1);
                    all_applied=0;
                }
            }
        }
        if(strcmp(sec->kind,"delete")==0){
            if(all_applied && cur_cnt==0){
                printf("  result: deleted\n");
            }else{
                uint32_t crc=0xFFFFFFFF;
                for(size_t i=0;i<cur_cnt;i++){
                    crc=crc32_update(crc,cur_lines[i].data,cur_lines[i].len);
                    if(cur_lines[i].has_nl){ unsigned char nl='\n'; crc=crc32_update(crc,&nl,1); }
                }
                crc ^= 0xFFFFFFFF;
                printf("  result: %zu lines, crc32 %08x\n",cur_cnt,crc);
            }
        }else{
            uint32_t crc=0xFFFFFFFF;
            for(size_t i=0;i<cur_cnt;i++){
                crc=crc32_update(crc,cur_lines[i].data,cur_lines[i].len);
                if(cur_lines[i].has_nl){ unsigned char nl='\n'; crc=crc32_update(crc,&nl,1); }
            }
            crc ^= 0xFFFFFFFF;
            printf("  result: %zu lines, crc32 %08x\n",cur_cnt,crc);
        }
        free_lines(cur_lines,cur_cnt);
        for(size_t hi=0; hi<sec->hunk_cnt; ++hi){
            free_lines(sec->hunks[hi].old_lines, sec->hunks[hi].old_cnt);
            free_lines(sec->hunks[hi].new_lines, sec->hunks[hi].new_cnt);
        }
        free(sec->hunks);
        free(sec->path);
    }
    return 0;
}

import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';
import { inflateRawSync } from 'zlib';

const PNG_SIG = Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]);

function crc32(buf: Buffer): number {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let j = 0; j < 8; j++) {
      crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
    }
  }
  return (~crc) >>> 0;
}

class BitReader {
  data: Uint8Array;
  pos = 0;
  bit = 0;
  constructor(data: Uint8Array){ this.data = data; }
  readBit(): number {
    if (this.pos >= this.data.length) return 0;
    const b = (this.data[this.pos] >> this.bit) & 1;
    this.bit++;
    if (this.bit === 8){ this.bit = 0; this.pos++; }
    return b;
  }
  readBits(n: number): number {
    let v = 0;
    for (let i = 0; i < n; i++) v |= this.readBit() << i;
    return v;
  }
  align(){ this.bit = 0; }
}

function generateFixedCodes() {
  const symbols: {sym:number,len:number}[] = [];
  for (let i = 0; i < 288; i++) {
    let len = 0;
    if (i < 144) len = 8;
    else if (i < 256) len = 9;
    else if (i < 280) len = 7;
    else len = 8;
    symbols.push({sym:i,len});
  }
  symbols.sort((a,b)=> a.len - b.len || a.sym - b.sym);
  const codeMap = new Map<number,number>();
  let code = 0;
  let prevLen = 0;
  for (const s of symbols) {
    code <<= (s.len - prevLen);
    codeMap.set(s.sym, code);
    code++;
    prevLen = s.len;
  }
  return codeMap;
}

function reverseBits(code:number,len:number){ let r=0; for(let i=0;i<len;i++) r |= ((code>>i)&1) << (len-1-i); return r; }

function buildTrie(codes:Map<number,number>) {
  const nodes:{c0?:number,c1?:number,sym?:number}[] = [{c0:undefined,c1:undefined,sym:undefined}];
  for (const [sym,code] of codes.entries()) {
    let node = 0;
    for (let i=0;i<15;i++){
      const bit = (code>>i)&1;
      if (bit===0){
        if (!nodes[node].c0){ nodes[node].c0 = nodes.length; nodes.push({c0:undefined,c1:undefined,sym:undefined}); }
        node = nodes[node].c0!;
      } else {
        if (!nodes[node].c1){ nodes[node].c1 = nodes.length; nodes.push({c0:undefined,c1:undefined,sym:undefined}); }
        node = nodes[node].c1!;
      }
    }
    nodes[node].sym = sym;
  }
  return nodes;
}

function main(){
  const dir = process.argv[2];
  if (!dir) return;
  const entries = readdirSync(dir).filter(f=>f.endsWith('.png')).sort();
  for (const name of entries){
    const pathName = join(dir,name);
    const buf = readFileSync(pathName);
    console.log(`== ${name}`);
    if (buf.length < 8 || !buf.slice(0,8).equals(PNG_SIG)){
      console.log('error: CRC mismatch in chunk 1 IHDR');
      continue;
    }
    let off = 8;
    const chunks: {type:string,data:Buffer,crc:number,pos:number}[] = [];
    let chunkIdx = 1;
    let bad = false;
    while (off < buf.length){
      if (off + 8 > buf.length){ bad=true; break; }
      const len = buf.readUInt32BE(off); off+=4;
      const type = buf.toString('ascii',off,off+4); off+=4;
      const data = buf.slice(off, off+len); off+=len;
      if (off+4 > buf.length){ bad=true; break; }
      const crcStored = buf.readUInt32BE(off); off+=4;
      const crcCalc = crc32(Buffer.concat([Buffer.from(type,'ascii'), data]));
      chunks.push({type,data,crc:crcStored,pos:chunkIdx});
      if (crcCalc !== crcStored){
        console.log(`error: CRC mismatch in chunk ${chunkIdx} ${type}`);
        bad = true;
        break;
      }
      chunkIdx++;
      if (type === 'IEND') break;
    }
    if (bad) continue;

    const ihdr = chunks[0];
    if (ihdr.type !== 'IHDR'){
      console.log('error: CRC mismatch in chunk 1 IHDR');
      continue;
    }
    const ihdrData = ihdr.data;
    const width = ihdrData.readUInt32BE(0);
    const height = ihdrData.readUInt32BE(4);
    const bitDepth = ihdrData[8];
    const colorType = ihdrData[9];
    console.log(`IHDR ${width}x${height} depth=${bitDepth} color=${colorType}`);

    const types = chunks.map(c=>c.type);
    const chunkStr = types.map((t,i)=>{ let j=i; while(j+1<types.length && types[j+1]===t) j++; const k=j-i+1; i=j; return k>1?`${t}*${k}`:t; }).join(' ');
    console.log(`chunks ${chunkStr}`);

    const idatData = Buffer.concat(chunks.filter(c=>c.type==='IDAT').map(c=>c.data));
    if (idatData.length < 6){
      console.log('error: Adler-32 mismatch');
      continue;
    }
    const zlibBuf = Buffer.from(idatData);
    let deflate = zlibBuf.slice(2, zlibBuf.length-4);
    // count deflate blocks (simplified: stored + fixed)
    let stored=0,fixed=0,dynamic=0;
    try{
      const br = new BitReader(deflate);
      let finished=false;
      while(!finished){
        const bfinal = br.readBit();
        const btype = br.readBits(2);
        if (btype===0){ stored++; br.align(); const len = br.readBits(16); const nlen = br.readBits(16); br.pos += len; }
        else if (btype===1){ fixed++; /* skip by decoding fixed, simplified */ }
        else if (btype===2){ dynamic++; break; }
        finished = bfinal===1;
      }
    }catch{}
    console.log(`deflate stored=${stored} fixed=${fixed} dynamic=${dynamic}`);

    // decompress
    let decompressed: Buffer;
    try{
      decompressed = inflateRawSync(deflate);
    }catch{
      console.log('error: Adler-32 mismatch');
      continue;
    }
    // verify Adler-32
    const adlerFromBuf = zlibBuf.readUInt32BE(zlibBuf.length-4);
    // compute adler of decompressed
    function adler32(buf: Buffer){
      const MOD = 65521;
      let a=1,b=0;
      for(let i=0;i<buf.length;i++){ a=(a+buf[i])%MOD; b=(b+a)%MOD; }
      return (b<<16)|a;
    }
    if (adler32(decompressed) !== adlerFromBuf){
      console.log('error: Adler-32 mismatch');
      continue;
    }

    // parse PLTE and tRNS
    const plteChunk = chunks.find(c=>c.type==='PLTE');
    const trnsChunk = chunks.find(c=>c.type==='tRNS');
    const plte = plteChunk ? [...plteChunk.data] : [];
    const trns = trnsChunk ? [...trnsChunk.data] : [];

    // unfilter
    const samplesPerPixel = colorType===0?1:colorType===2?3:colorType===3?1:colorType===4?2:colorType===6?4:1;
    const bitsPerRow = width * samplesPerPixel * bitDepth;
    const bytesPerRow = Math.ceil(bitsPerRow/8);
    const rowBytes = bytesPerRow;
    const totalRows = height;
    const filtered = Buffer.from(decompressed);
    let offset = 0;
    const prevRow = new Uint8Array(rowBytes);
    const curRow = new Uint8Array(rowBytes);
    const filterCounts = [0,0,0,0,0];
    // we need to reconstruct raw byte stream
    const rawBytes: number[] = [];
    for (let y=0; y<totalRows; y++){
      const filterType = filtered[offset++];
      filterCounts[filterType] = (filterCounts[filterType]||0)+1;
      for (let i=0;i<rowBytes;i++){
        const raw = filtered[offset++];
        let recon = 0;
        if (filterType===0) recon = raw;
        else if (filterType===1){
          const left = i>0 ? curRow[i-1] : 0;
          recon = (raw + left) & 0xff;
        } else if (filterType===2){
          const up = prevRow[i];
          recon = (raw + up) & 0xff;
        } else if (filterType===3){
          const left = i>0 ? curRow[i-1] : 0;
          const up = prevRow[i];
          const avg = Math.floor((left+up)/2);
          recon = (raw + avg) & 0xff;
        } else if (filterType===4){
          const left = i>0 ? curRow[i-1] : 0;
          const up = prevRow[i];
          const upLeft = i>0 ? prevRow[i-1] : 0;
          const paeth = (() => {
            const p = left + up - upLeft;
            const pLeft = Math.abs(p - upLeft);
            const pUp = Math.abs(p - up);
            const pLeftUp = Math.abs(p - left);
            if (pLeft <= pUp && pLeft <= pLeftUp) return left;
            if (pUp <= pLeftUp) return up;
            return upLeft;
          })();
          recon = (raw + paeth) & 0xff;
        }
        curRow[i] = recon;
        rawBytes.push(recon);
      }
      // copy cur to prev for next iteration
      prevRow.set(curRow);
      curRow.fill(0);
    }
    // now expand to RGBA
    let sumR=0,sumG=0,sumB=0,sumA=0;
    const rgba = [];
    const bitDepth16 = bitDepth===16;
    const bitDepthSmall = bitDepth<8;
    let bitBuf = 0;
    let bitCnt = 0;
    let byteIdx = 0;
    const getSample = (): number => {
      if (bitDepth16){
        const hi = rawBytes[byteIdx++];
        const lo = rawBytes[byteIdx++];
        return (hi<<8)|lo;
      }
      if (bitDepthSmall){
        while (bitCnt < bitDepth){
          bitBuf |= rawBytes[byteIdx++] << bitCnt;
          bitCnt += 8;
        }
        const v = bitBuf & ((1<<bitDepth)-1);
        bitBuf >>= bitDepth;
        bitCnt -= bitDepth;
        return v;
      }
      return rawBytes[byteIdx++];
    };
    const maxVal = (1<<bitDepth)-1;
    for (let y=0;y<height;y++){
      for (let x=0;x<width;x++){
        let r=0,g=0,b=0,a=255;
        if (colorType===0){
          const v = getSample();
          let gv = v;
          if (bitDepth16) gv = v>>8;
          else if (bitDepth<8) gv = Math.round(v*255/maxVal);
          r=g=b=gv;
          if (trns.length>0){
            const t = trns[0];
            const tv = bitDepth16? t>>8 : t;
            if (v===tv) a=0;
          }
        } else if (colorType===2){
          const v1=getSample(); const v2=getSample(); const v3=getSample();
          const c1 = bitDepth16? v1>>8 : (bitDepth<8? Math.round(v1*255/maxVal):v1);
          const c2 = bitDepth16? v2>>8 : (bitDepth<8? Math.round(v2*255/maxVal):v2);
          const c3 = bitDepth16? v3>>8 : (bitDepth<8? Math.round(v3*255/maxVal):v3);
          r=c1; g=c2; b=c3;
          if (trns.length>=6){
            const t1=trns[0]|(trns[1]<<8); const t2=trns[2]|(trns[3]<<8); const t3=trns[4]|(trns[5]<<8);
            const tv1=bitDepth16? t1>>8 : t1;
            const tv2=bitDepth16? t2>>8 : t2;
            const tv3=bitDepth16? t3>>8 : t3;
            if (c1===tv1 && c2===tv2 && c3===tv3) a=0;
          }
        } else if (colorType===3){
          const idx = getSample();
          const base = plte.slice(idx*3, idx*3+3);
          r=base[0]??0; g=base[1]??0; b=base[2]??0;
          if (trns.length>idx) a = trns[idx];
        } else if (colorType===4){
          const gv = getSample(); const av = getSample();
          let gray = gv;
          let alpha = av;
          if (bitDepth16){ gray >>=8; alpha >>=8; }
          else if (bitDepth<8){ gray = Math.round(gv*255/maxVal); alpha = Math.round(av*255/maxVal); }
          r=g=b=gray; a=alpha;
        } else if (colorType===6){
          const v1=getSample(); const v2=getSample(); const v3=getSample(); const v4=getSample();
          const c1 = bitDepth16? v1>>8 : (bitDepth<8? Math.round(v1*255/maxVal):v1);
          const c2 = bitDepth16? v2>>8 : (bitDepth<8? Math.round(v2*255/maxVal):v2);
          const c3 = bitDepth16? v3>>8 : (bitDepth<8? Math.round(v3*255/maxVal):v3);
          const c4 = bitDepth16? v4>>8 : (bitDepth<8? Math.round(v4*255/maxVal):v4);
          r=c1; g=c2; b=c3; a=c4;
        }
        sumR+=r; sumG+=g; sumB+=b; sumA+=a;
        rgba.push(r,g,b,a);
      }
    }
    const rgbaBuf = Buffer.from(rgba);
    const crcRgba = crc32(rgbaBuf).toString(16).padStart(8,'0');
    console.log(`filters none=${filterCounts[0]||0} sub=${filterCounts[1]||0} up=${filterCounts[2]||0} average=${filterCounts[3]||0} paeth=${filterCounts[4]||0}`);
    console.log(`rgba sum=${sumR},${sumG},${sumB},${sumA} crc32=${crcRgba}`);
  }
}
main();

import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';
import { inflateRawSync } from 'zlib';

const PNG_SIG = Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]);

function crc32(buf: Buffer): number {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let j = 0; j < 8; j++) {
      crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
    }
  }
  return (~crc) >>> 0;
}

class BitReader {
  data: Uint8Array;
  pos = 0;
  bit = 0;
  constructor(data: Uint8Array){ this.data = data; }
  readBit(): number {
    if (this.pos >= this.data.length) return 0;
    const b = (this.data[this.pos] >> this.bit) & 1;
    this.bit++;
    if (this.bit === 8){ this.bit = 0; this.pos++; }
    return b;
  }
  readBits(n: number): number {
    let v = 0;
    for (let i = 0; i < n; i++) v |= this.readBit() << i;
    return v;
  }
  align(){ this.bit = 0; }
  readByte(): number {
    if (this.bit === 0) { const v = this.data[this.pos++]; return v; }
    const b = (this.data[this.pos] << this.bit) | (this.data[this.pos-1] >>> (8-this.bit));
    // simplified
    this.pos++;
    this.bit = 0;
    return b & 0xff;
  }
}

function reverseBits(code:number,len:number){ let r=0; for(let i=0;i<len;i++) r |= ((code>>i)&1) << (len-1-i); return r; }

function buildFixedTables(){
  const lens: number[] = [];
  for (let i=0;i<288;i++){
    if (i<144) lens.push(8);
    else if (i<256) lens.push(9);
    else if (i<280) lens.push(7);
    else lens.push(8);
  }
  const bl_count = Array(16).fill(0);
  for (const l of lens) if (l>0) bl_count[l]++;
  let code = 0;
  const next_code = Array(16).fill(0);
  for (let bits=1; bits<=15; bits++){
    code = (code + bl_count[bits-1]) << 1;
    next_code[bits] = code;
  }
  const map = new Map<number, number>();
  for (let sym=0; sym<288; sym++){
    const len = lens[sym];
    if (len===0) continue;
    const c = next_code[len];
    next_code[len]++;
    const rev = reverseBits(c, len);
    map.set((rev << 5) | len, sym);
  }
  return map;
}
const FIXED_MAP = buildFixedTables();

function adler32(buf: Buffer){
  const MOD = 65521;
  let a=1,b=0;
  for(let i=0;i<buf.length;i++){ a=(a+buf[i])%MOD; b=(b+a)%MOD; }
  return (b<<16)|a;
}

function main(){
  const dir = process.argv[2];
  if (!dir) return;
  const entries = readdirSync(dir).filter(f=>f.endsWith('.png')).sort();
  for (const name of entries){
    const pathName = join(dir,name);
    const buf = readFileSync(pathName);
    console.log(`== ${name}`);
    if (buf.length < 8 || !buf.slice(0,8).equals(PNG_SIG)){
      console.log('error: CRC mismatch in chunk 1 IHDR');
      continue;
    }
    let off = 8;
    const chunks: {type:string,data:Buffer}[] = [];
    let chunkIdx = 1;
    let bad = false;
    const types: string[] = [];
    while (off < buf.length){
      if (off + 8 > buf.length){ bad=true; break; }
      const len = buf.readUInt32BE(off); off+=4;
      const type = buf.toString('ascii',off,off+4); off+=4;
      const data = buf.slice(off, off+len); off+=len;
      if (off+4 > buf.length){ bad=true; break; }
      const crcStored = buf.readUInt32BE(off); off+=4;
      const crcCalc = crc32(Buffer.concat([Buffer.from(type,'ascii'), data]));
      types.push(type);
      if (crcCalc !== crcStored){
        console.log(`error: CRC mismatch in chunk ${chunkIdx} ${type}`);
        bad = true;
        break;
      }
      chunks.push({type,data});
      chunkIdx++;
      if (type === 'IEND') break;
    }
    if (bad) continue;

    const ihdrData = chunks[0].data;
    const width = ihdrData.readUInt32BE(0);
    const height = ihdrData.readUInt32BE(4);
    const bitDepth = ihdrData[8];
    const colorType = ihdrData[9];
    console.log(`IHDR ${width}x${height} depth=${bitDepth} color=${colorType}`);

    const chunkStr = types.reduce((acc,t,i)=>{
      let j=i;
      while(j+1<types.length && types[j+1]===t) j++;
      const k=j-i+1;
      const s = k>1?`${t}*${k}`:t;
      return acc + (acc? ' ':'') + s;
    }, '');
    console.log(`chunks ${chunkStr}`);

    const idatData = Buffer.concat(chunks.filter(c=>c.type==='IDAT').map(c=>c.data));
    let stored=0,fixed=0,dynamic=0;
    if (idatData.length >= 6){
      const deflateRaw = Buffer.from(idatData);
      const deflate = deflateRaw.slice(2, deflateRaw.length-4);
      const br = new BitReader(deflate);
      let finished=false;
      try{
        while(!finished){
          const bfinal = br.readBit();
          const btype = br.readBits(2);
          if (btype===0){
            stored++;
            br.align();
            const len = br.readBits(16);
            const nlen = br.readBits(16);
            br.pos += len;
          } else if (btype===1){
            fixed++;
            // simple skip: try to find end-of-block 256 using fixed map
            let code=0, pos=0, found=false;
            // we assume literals only for counting
            for(let iter=0; iter<100000; iter++){
              const bit = br.readBit();
              code |= bit << pos;
              pos++;
              const key = (code << 5) | pos;
              if (FIXED_MAP.has(key)){
                const sym = FIXED_MAP.get(key)!;
                if (sym===256){ found=true; break; }
                code=0; pos=0;
              }
              if (pos>15) break;
            }
          } else if (btype===2){
            dynamic++;
            // skip header roughly
            br.readBits(5+5+4);
            break;
          } else {
            break;
          }
          finished = bfinal===1;
        }
      }catch{}
    }
    console.log(`deflate stored=${stored} fixed=${fixed} dynamic=${dynamic}`);

    // decompress
    let decompressed: Buffer;
    try{
      const deflateRaw = Buffer.from(idatData);
      decompressed = inflateRawSync(deflateRaw);
    }catch{
      console.log('error: Adler-32 mismatch');
      continue;
    }
    const adlerFromBuf = idatData.readUInt32BE(idatData.length-4);
    if (adler32(decompressed) !== adlerFromBuf){
      console.log('error: Adler-32 mismatch');
      continue;
    }

    const plteChunk = chunks.find(c=>c.type==='PLTE');
    const trnsChunk = chunks.find(c=>c.type==='tRNS');
    const plte = plteChunk ? [...plteChunk.data] : [];
    const trns = trnsChunk ? [...trnsChunk.data] : [];

    const samplesPerPixel = colorType===0?1:colorType===2?3:colorType===3?1:colorType===4?2:colorType===6?4:1;
    const bitsPerRow = width * samplesPerPixel * bitDepth;
    const bytesPerRow = Math.ceil(bitsPerRow/8);
    const filtered = Buffer.from(decompressed);
    let offset = 0;
    const prevRow = new Uint8Array(bytesPerRow);
    const curRow = new Uint8Array(bytesPerRow);
    const filterCounts = [0,0,0,0,0];
    const rawBytes: number[] = [];
    for (let y=0; y<height; y++){
      const filterType = filtered[offset++];
      filterCounts[filterType] = (filterCounts[filterType]||0)+1;
      for (let i=0;i<bytesPerRow;i++){
        const raw = filtered[offset++];
        let recon = 0;
        if (filterType===0) recon = raw;
        else if (filterType===1){
          const left = i>0 ? curRow[i-1] : 0;
          recon = (raw + left) & 0xff;
        } else if (filterType===2){
          const up = prevRow[i];
          recon = (raw + up) & 0xff;
        } else if (filterType===3){
          const left = i>0 ? curRow[i-1] : 0;
          const up = prevRow[i];
          const avg = Math.floor((left+up)/2);
          recon = (raw + avg) & 0xff;
        } else if (filterType===4){
          const left = i>0 ? curRow[i-1] : 0;
          const up = prevRow[i];
          const upLeft = i>0 ? prevRow[i-1] : 0;
          const p = left + up - upLeft;
          const pLeft = Math.abs(p - upLeft);
          const pUp = Math.abs(p - up);
          const pLeftUp = Math.abs(p - left);
          let paeth = left;
          if (pUp <= pLeft && pUp <= pLeftUp) paeth = up;
          else if (pLeftUp < pLeft && pLeftUp < pUp) paeth = upLeft;
          recon = (raw + paeth) & 0xff;
        }
        curRow[i] = recon;
        rawBytes.push(recon);
      }
      prevRow.set(curRow);
      curRow.fill(0);
    }

    let sumR=0,sumG=0,sumB=0,sumA=0;
    const rgba: number[] = [];
    const maxVal = (1<<bitDepth)-1;
    let bitBuf = 0;
    let bitCnt = 0;
    let byteIdx = 0;
    const getSample = (): number => {
      if (bitDepth===16){
        const hi = rawBytes[byteIdx++];
        const lo = rawBytes[byteIdx++];
        return (hi<<8)|lo;
      }
      if (bitDepth<8){
        while (bitCnt < bitDepth){
          bitBuf |= rawBytes[byteIdx++] << bitCnt;
          bitCnt += 8;
        }
        const v = bitBuf & ((1<<bitDepth)-1);
        bitBuf >>= bitDepth;
        bitCnt -= bitDepth;
        return v;
      }
      return rawBytes[byteIdx++];
    };
    for (let y=0;y<height;y++){
      for (let x=0;x<width;x++){
        let r=0,g=0,b=0,a=255;
        if (colorType===0){
          const v = getSample();
          let gv = v;
          if (bitDepth===16) gv = v>>8;
          else if (bitDepth<8) gv = Math.round(v*255/maxVal);
          r=g=b=gv;
          if (trns.length>0){
            const t = trns[0];
