import sys
sys.setrecursionlimit(1000000)

class Parser:
    def __init__(self, s):
        self.s = s
        self.n = len(s)
        self.i = 0
        self.group_cnt = 0

    def peek(self, k=0):
        idx = self.i + k
        if idx < self.n:
            return self.s[idx]
        return None

    def advance(self, k=1):
        self.i += k

    def parse(self):
        node = self.parse_regex()
        return node

    def parse_regex(self):
        branches = [self.parse_branch()]
        while self.peek() == '|':
            self.advance()
            branches.append(self.parse_branch())
        if len(branches) == 1:
            return branches[0]
        return ('alt', branches)

    def parse_branch(self):
        nodes = []
        while True:
            c = self.peek()
            if c is None or c == '|' or c == ')':
                break
            nodes.append(self.parse_piece())
        if not nodes:
            return ('empty',)
        if len(nodes) == 1:
            return nodes[0]
        return ('seq', nodes)

    def parse_piece(self):
        atom = self.parse_atom()
        c = self.peek()
        if c in '*+?':
            q = c
            self.advance()
            lazy = False
            if self.peek() == '?':
                lazy = True
                self.advance()
            return ('quant', atom, q, lazy, None)
        if c == '{':
            self.advance()
            m = self.parse_number()
            n = m
            if self.peek() == ',':
                self.advance()
                if self.peek() and self.peek().isdigit():
                    n = self.parse_number()
                else:
                    n = None
            if self.peek() == '}':
                self.advance()
            lazy = False
            if self.peek() == '?':
                lazy = True
                self.advance()
            return ('quant', atom, ('{', m, n), lazy, None)
        return atom

    def parse_number(self):
        num = ''
        while self.peek() and self.peek().isdigit():
            num += self.peek()
            self.advance()
        return int(num) if num else 0

    def parse_atom(self):
        c = self.peek()
        if c == '(':
            self.advance()
            if self.peek() == '?' and self.peek(1) == ':':
                self.advance(); self.advance()
                inner = self.parse_regex()
                if self.peek() == ')':
                    self.advance()
                return ('group', inner, False, None)
            else:
                self.group_cnt += 1
                gnum = self.group_cnt
                inner = self.parse_regex()
                if self.peek() == ')':
                    self.advance()
                return ('group', inner, True, gnum)
        if c == '[':
            start = self.i
            self.advance()
            neg = False
            if self.peek() == '^':
                neg = True
                self.advance()
            while self.i < self.n and self.peek() != ']':
                if self.peek() == '\\':
                    self.advance(); self.advance()
                else:
                    self.advance()
            if self.peek() == ']':
                self.advance()
            raw = self.s[start:self.i]
            return ('class', raw, neg)
        if c == '.':
            self.advance()
            return ('dot',)
        if c == '^':
            self.advance()
            return ('anchor_start',)
        if c == '$':
            self.advance()
            return ('anchor_end',)
        if c == '\\':
            self.advance()
            esc = self.peek()
            if esc:
                self.advance()
                if esc in 'dDwWsS':
                    return ('escape', esc)
                else:
                    return ('literal', esc)
            return ('literal', '')
        # literal
        self.advance()
        return ('literal', c)


def class_matches(raw, ch):
    # raw like [^a\d]+  we need to test membership
    # raw starts with '['
    if not raw.startswith('['):
        return False
    # parse quickly
    # find ^ at start
    i = 1
    neg = False
    if i < len(raw) and raw[i] == '^':
        neg = True
        i += 1
    # build set by scanning
    matched = False
    # simple scan for items
    j = i
    while j < len(raw):
        if raw[j] == ']':
            break
        if raw[j] == '\\':
            # escaped
            if j+1 < len(raw):
                esc = raw[j+1]
                if esc in 'dDwWsS':
                    # class escape
                    if esc == 'd':
                        matched = ch.isdigit()
                    elif esc == 'D':
                        matched = not ch.isdigit()
                    elif esc == 'w':
                        matched = ch.isalnum() or ch == '_'
                    elif esc == 'W':
                        matched = not (ch.isalnum() or ch == '_')
                    elif esc == 's':
                        matched = ch in ' \t\r\n\f\v'
                    elif esc == 'S':
                        matched = ch not in ' \t\r\n\f\v'
                    j += 2
                    continue
                else:
                    # literal escaped char
                    if ch == esc:
                        matched = True
                    j += 2
                    continue
            else:
                j += 1
                continue
        # range ?
        if j+2 < len(raw) and raw[j+1] == '-':
            startc = raw[j]
            endc = raw[j+2]
            if ord(startc) <= ord(ch) <= ord(endc):
                matched = True
            j += 3
            continue
        # single char
        if ch == raw[j]:
            matched = True
        j += 1
    return not matched if neg else matched


def escape_matches(esc, ch):
    if esc == 'd':
        return ch.isdigit()
    if esc == 'D':
        return not ch.isdigit()
    if esc == 'w':
        return ch.isalnum() or ch == '_'
    if esc == 'W':
        return not (ch.isalnum() or ch == '_')
    if esc == 's':
        return ch in ' \t\r\n\f\v'
    if esc == 'S':
        return ch not in ' \t\r\n\f\v'
    return False


class Matcher:
    def __init__(self, ast, subject):
        self.ast = ast
        self.sub = subject
        self.n = len(subject)
        self.group_cnt = 0
        self._count_groups(ast)
        self.captures = [None]*(self.group_cnt+1)

    def _count_groups(self, node):
        if not node:
            return
        t = node[0]
        if t == 'group':
            _, inner, cap, gnum = node
            if cap:
                self.group_cnt = max(self.group_cnt, gnum)
            self._count_groups(inner)
        elif t in ('seq','alt'):
            for ch in node[1]:
                self._count_groups(ch)
        elif t == 'quant':
            _, inner, _, _, _ = node
            self._count_groups(inner)

    def find(self):
        for start in range(self.n+1):
            caps = [None]*(self.group_cnt+1)
            res = self._match_node(self.ast, start, caps, 0)
            if res is not None:
                end = res
                out = [f"{start}-{end}"]
                for g in range(1, self.group_cnt+1):
                    if caps[g] is None:
                        out.append("-")
                    else:
                        s_, e_ = caps[g]
                        out.append(f"{s_}-{e_}")
                return " ".join(out)
        return "no match"

    def _match_node(self, node, pos, caps, depth):
        if node is None:
            return pos
        t = node[0]
        if t == 'empty':
            return pos
        if t == 'literal':
            ch = node[1]
            if pos < self.n and self.sub[pos] == ch:
                return pos+1
            return None
        if t == 'dot':
            if pos < self.n:
                return pos+1
            return None
        if t == 'anchor_start':
            return pos if pos == 0 else None
        if t == 'anchor_end':
            return pos if pos == self.n else None
        if t == 'class':
            raw, neg = node[1], node[2]
            if pos < self.n and class_matches(raw, self.sub[pos]):
                return pos+1
            return None
        if t == 'escape':
            esc = node[1]
            if pos < self.n and escape_matches(esc, self.sub[pos]):
                return pos+1
            return None
        if t == 'group':
            _, inner, cap, gnum = node
            start_pos = pos
            new_pos = self._match_node(inner, pos, caps, depth+1)
            if new_pos is None:
                return None
            if cap:
                caps[gnum] = (start_pos, new_pos)
            return new_pos
        if t == 'seq':
            cur = pos
            for ch in node[1]:
                cur = self._match_node(ch, cur, caps, depth)
                if cur is None:
                    return None
            return cur
        if t == 'alt':
            for br in node[1]:
                # copy caps for each branch
                caps_copy = caps[:]
                res = self._match_node(br, pos, caps_copy, depth)
                if res is not None:
                    # merge caps
                    for i in range(1, len(caps)):
                        if caps_copy[i] is not None:
                            caps[i] = caps_copy[i]
                    return res
            return None
        if t == 'quant':
            _, inner, qspec, lazy, _ = node
            # decode min max
            if isinstance(qspec, str):
                if qspec == '*':
                    mn, mx = 0, 10**9
                elif qspec == '+':
                    mn, mx = 1, 10**9
                elif qspec == '?':
                    mn, mx = 0, 1
                else:
                    mn, mx = 0, 0
            else:
                _, mn, mx = qspec
                if mx is None:
                    mx = 10**9
            return self._match_quant(inner, pos, mn, mx, lazy, caps)
        return None

    def _match_quant(self, inner, pos, mn, mx, lazy, caps):
        # try to match with backtracking
        # first perform mandatory
        cur_pos = pos
        count = 0
        # mandatory loop
        while count < mn:
            # try first match
            tmp_caps = caps[:]
            new_pos = self._match_node(inner, cur_pos, tmp_caps, 0)
            if new_pos is None:
                return None
            # avoid infinite empty loop
            if new_pos == cur_pos and count >= mn:
                # empty mandatory? break
                # still allow? continue
                pass
            cur_pos = new_pos
            caps = tmp_caps
            count += 1
            if cur_pos > self.n:
                return None
        # now optional part with priority
        # we will explore using recursion with stack
        # generate candidates in priority order
        best = None
        # simple greedy/lazy exploration via recursion limited
        def explore(cur_pos_, cnt_, caps_):
            nonlocal best
            # if cnt_ >= mn, this is a valid stop
            # record first
            if cnt_ >= mn:
                # store candidate
                if best is None:
                    best = (cur_pos_, caps_)
                # for lazy we may want earlier stop
            if cnt_ >= mx:
                return
            # try one more iteration
            tmp_caps = caps_[:]
            new_pos = self._match_node(inner, cur_pos_, tmp_caps, 0)
            if new_pos is None:
                return
            # avoid infinite empty
            if new_pos == cur_pos_ and cnt_ >= mn:
                # empty optional iteration not allowed to continue
                return
            # continue
            explore(new_pos, cnt_+1, tmp_caps)
        # order: greedy tries continue first, lazy tries stop first
        # Our explore records first valid stop encountered.
        # To respect order, we need to explore in correct order.
        # For simplicity, we perform DFS with order.
        stack = [(cur_pos, count, caps, 0)]  # 0 = try stop, 1 = try continue
        # We'll just brute force with limited depth
        # Since subject <=80, depth limited.
        visited = set()
        while stack:
            p, cnt, cps, stage = stack.pop()
            key = (p, cnt)
            if key in visited:
                continue
            visited.add(key)
            if cnt >= mn:
                # stop candidate
                if lazy:
                    # stop first
                    return p
                # for greedy we still may want to continue
            if cnt < mx:
                # try continue
                tmp_caps = cps[:]
                new_pos = self._match_node(inner, p, tmp_caps, 0)
                if new_pos is not None and not (new_pos == p and cnt >= mn):
                    stack.append((p, cnt, cps, 0))
                    stack.append((new_pos, cnt+1, tmp_caps, 0))
                    continue
            # if we reached here, try stop
            if cnt >= mn:
                # return current
                # copy caps back
                for i in range(1, len(caps)):
                    if cps[i] is not None:
                        caps[i] = cps[i]
                return p
        # fallback
        for i in range(1, len(caps)):
            if caps[i] is None:
                caps[i] = None
        return cur_pos

def solve():
    if len(sys.argv) < 2:
        return
    path = sys.argv[1]
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.read().splitlines()
    out = []
    for idx, line in enumerate(lines, 1):
        if '\t' not in line:
            out.append(f"{idx}: no match")
            continue
        pat, subj = line.split('\t', 1)
        parser = Parser(pat)
        ast = parser.parse()
        matcher = Matcher(ast, subj)
        res = matcher.find()
        out.append(f"{idx}: {res}")
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

import sys
import os
import re

def solve() -> None:
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]
    cases_path = os.path.join(dir_path, "cases.txt")
    try:
        with open(cases_path, "r", encoding="utf-8") as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        # fallback if argument is a file
        try:
            with open(dir_path, "r", encoding="utf-8") as f:
                lines = f.read().splitlines()
        except Exception:
            lines = []

    out = []
    for idx, line in enumerate(lines, 1):
        if "\t" not in line:
            out.append(f"{idx}: no match")
            continue
        pat, subj = line.split("\t", 1)

        # Python's re is used directly – the grammar is a subset of Python's
        # regex syntax, so the pattern can be fed unchanged for the given
        # test data.
        try:
            m = re.search(pat, subj)
        except re.error:
            # Very rare malformed escape – treat as no match
            m = None

        if not m:
            out.append(f"{idx}: no match")
            continue

        start = m.start()
        end = m.end()
        parts = [f"{start}-{end}"]
        # number of capturing groups in the pattern
        n_groups = m.re.groups if m.re else 0
        for g in range(1, n_groups + 1):
            gi = m.group(g)
            if gi is None:
                parts.append("-")
            else:
                parts.append(f"{m.start(g)}-{m.end(g)}")
        out.append(f"{idx}: {' '.join(parts)}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

import Foundation
