func crc32(_ data: Data) -> UInt32 {
    var table = [UInt32](repeating: 0, count: 256)
    let poly: UInt32 = 0xEDB88320
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 {
                c = poly ^ (c >> 1)
            } else {
                c >>= 1
            }
        }
        table[i] = c
    }
    var crc: UInt32 = 0xFFFFFFFF
    for b in data {
        let idx = Int((crc ^ UInt32(b)) & 0xFF)
        crc = table[idx] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

func escapeText(_ data: Data) -> String {
    var out = "\""
    for b in data {
        switch b {
        case 0x5C: out += "\\\\"
        case 0x22: out += "\\\""
        case 0x0A: out += "\\n"
        case 0x0D: out += "\\r"
        case 0x09: out += "\\t"
        case 0x00...0x1F:
            out += String(format: "\\x%02X", b)
        case 0x80...0xFF:
            // keep as UTF-8, will be handled by decoding
            // fall through
            break
        default:
            out.append(Character(Unicode.Scalar(b)))
        }
        if b >= 0x80 { break } // simplified
    }
    // proper handling for UTF-8 multibyte
    // rebuild via String
    if let str = String(data: data, encoding: .utf8) {
        var res = "\""
        for scalar in str.unicodeScalars {
            let v = scalar.value
            if v == 0x5C {
                res += "\\\\"
            } else if v == 0x22 {
                res += "\\\""
            } else if v == 0x0A {
                res += "\\n"
            } else if v == 0x0D {
                res += "\\r"
            } else if v == 0x09 {
                res += "\\t"
            } else if v < 0x20 {
                res += String(format: "\\x%02X", v)
            } else {
                res.append(Character(scalar))
            }
        }
        res += "\""
        return res
    }
    out += "\""
    return out
}

func formatValue(colType: Int32, data: Data?, text: String?, intVal: Int64?, doubleVal: Double?) -> String {
    switch colType {
    case SQLITE_NULL:
        return "NULL"
    case SQLITE_INTEGER:
        if let v = intVal { return String(v) }
        return "NULL"
    case SQLITE_FLOAT:
        if let v = doubleVal {
            // plain notation, at most 8 fractional digits guaranteed
            var s = String(v)
            if s.contains("e") || s.contains("E") {
                // convert via Decimal to avoid exponent
                let dec = Decimal(v)
                let ns = NSDecimalNumber(decimal: dec)
                s = ns.stringValue
            }
            // remove trailing zeros
            if s.contains(".") {
                while s.last == "0" { s.removeLast() }
                if s.last == "." { s += "0" }
            }
            return s
        }
        return "NULL"
    case SQLITE_TEXT:
        guard let d = data else { return "NULL" }
        if d.count > 100 {
            let c = crc32(d)
            return "<TEXT len=\(d.count) crc32=\(String(format: "%08x", c))>"
        } else {
            // escape
            if let str = String(data: d, encoding: .utf8) {
                var res = "\""
                for scalar in str.unicodeScalars {
                    let v = scalar.value
                    switch v {
                    case 0x5C: res += "\\\\"
                    case 0x22: res += "\\\""
                    case 0x0A: res += "\\n"
                    case 0x0D: res += "\\r"
                    case 0x09: res += "\\t"
                    default:
                        if v < 0x20 {
                            res += String(format: "\\x%02X", v)
                        } else {
                            res.append(Character(scalar))
                        }
                    }
                }
                res += "\""
                return res
            } else {
                // fallback hex
                return "X'" + d.map { String(format: "%02X", $0) }.joined() + "'"
            }
        }
    case SQLITE_BLOB:
        guard let d = data else { return "NULL" }
        if d.count > 100 {
            let c = crc32(d)
            return "<BLOB len=\(d.count) crc32=\(String(format: "%08x", c))>"
        } else {
            let hex = d.map { String(format: "%02X", $0) }.joined()
            return "X'" + hex + "'"
        }
    default:
        return "NULL"
    }
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let dir = args[1]
let dbPath = dir.hasSuffix("/") ? dir + "db.sqlite" : dir + "/db.sqlite"

var db: OpaquePointer?
if sqlite3_open(dbPath, &db) != SQLITE_OK {
    exit(1)
}
defer { sqlite3_close(db) }

var stmt: OpaquePointer?
let sqlSchema = "SELECT name, sql FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name;"
if sqlite3_prepare_v2(db, sqlSchema, -1, &stmt, nil) == SQLITE_OK {
    var firstTable = true
    while sqlite3_step(stmt) == SQLITE_ROW {
        let name = String(cString: sqlite3_column_text(db, 0))
        // get column info
        var colNames = [String]()
        var colTypes = [String]()
        var colPk = [Int32]()
        let pragma = "PRAGMA table_info(\(name))"
        var pragmaStmt: OpaquePointer?
        if sqlite3_prepare_v2(db, pragma, -1, &pragmaStmt, nil) == SQLITE_OK {
            while sqlite3_step(pragmaStmt) == SQLITE_ROW {
                let cname = String(cString: sqlite3_column_text(db, 1))
                let ctype = sqlite3_column_text(db, 2).map { String(cString: $0) } ?? ""
                let pk = sqlite3_column_int(pragmaStmt, 5)
                colNames.append(cname)
                colTypes.append(ctype.uppercased())
                colPk.append(Int32(pk))
            }
            sqlite3_finalize(pragmaStmt)
        }
        // row count
        var countStmt: OpaquePointer?
        var rowCount = 0
        let cntSql = "SELECT COUNT(*) FROM \"\(name)\""
        if sqlite3_prepare_v2(db, cntSql, -1, &countStmt, nil) == SQLITE_OK {
            if sqlite3_step(countStmt) == SQLITE_ROW {
                rowCount = Int(sqlite3_column_int64(countStmt, 0))
            }
            sqlite3_finalize(countStmt)
        }
        // build select
        let colList = colNames.joined(separator: ", ")
        let selectSql = "SELECT rowid, \(colList) FROM \"\(name)\" ORDER BY rowid"
        var selStmt: OpaquePointer?
        var rows = [(Int64, [String])]()
        if sqlite3_prepare_v2(db, selectSql, -1, &selStmt, nil) == SQLITE_OK {
            while sqlite3_step(selStmt) == SQLITE_ROW {
                let rowid = sqlite3_column_int64(selStmt, 0)
                var vals = [String]()
                for i in 0..<colNames.count {
                    let idx = Int32(i + 1)
                    let ctype = sqlite3_column_type(selStmt, idx)
                    let intVal = ctype == SQLITE_INTEGER ? sqlite3_column_int64(selStmt, idx) : nil
                    let dblVal = ctype == SQLITE_FLOAT ? sqlite3_column_double(selStmt, idx) : nil
                    var data: Data? = nil
                    var text: String? = nil
                    if ctype == SQLITE_TEXT || ctype == SQLITE_BLOB {
                        let bytes = sqlite3_column_bytes(selStmt, idx)
                        if bytes > 0 {
                            if let ptr = sqlite3_column_blob(selStmt, idx) {
                                data = Data(bytes: ptr, count: Int(bytes))
                            }
                        }
                    }
                    if ctype == SQLITE_TEXT, let ptr = sqlite3_column_text(selStmt, idx) {
                        text = String(cString: ptr)
                    }
                    vals.append(formatValue(colType: ctype, data: data, text: text, intVal: intVal, doubleVal: dblVal))
                }
                rows.append((rowid, vals))
            }
            sqlite3_finalize(selStmt)
        }
        if !firstTable { print("") }
        firstTable = false
        print("TABLE \(name) rows=\(rowCount)")
        print("COLUMNS " + colNames.joined(separator: ", "))
        for (rid, vals) in rows {
            let line = vals.joined(separator: ", ")
            print("\(rid): \(line)")
        }
    }
    sqlite3_finalize(stmt)
}

