#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef void* pcre;
typedef pcre (*pcre_compile_t)(const char *, int, const char **, int *, const unsigned char *);
typedef int (*pcre_exec_t)(pcre *, void *, const char *, int, int, int, int *, int, int);
typedef void (*pcre_free_t)(void *);
typedef int (*pcre_info_t)(pcre *, int, void *, int *);

static void *pcre_lib = NULL;
static pcre_compile_t pcre_compile_f = NULL;
static pcre_exec_t pcre_exec_f = NULL;
static pcre_free_t pcre_free_f = NULL;
static pcre_info_t pcre_info_f = NULL;

static int load_pcre(void){
    if(pcre_lib) return 1;
    const char *names[] = {"libpcre.dylib","libpcre-8.dylib","libpcre.1.dylib",NULL};
    for(int i=0; names[i]; i++){
        pcre_lib = dlopen(names[i], RTLD_LAZY);
        if(pcre_lib) break;
    }
    if(!pcre_lib) return 0;
    pcre_compile_f = (pcre_compile_t)dlsym(pcre_lib,"pcre_compile");
    pcre_exec_f = (pcre_exec_t)dlsym(pcre_lib,"pcre_exec");
    pcre_free_f = (pcre_free_t)dlsym(pcre_lib,"pcre_free");
    pcre_info_f = (pcre_info_t)dlsym(pcre_lib,"pcre_info");
    return pcre_compile_f && pcre_exec_f;
}

int main(int argc,char **argv){
    if(argc<2){fprintf(stderr,"usage\n");return 1;}
    FILE *f=fopen(argv[1],"r");
    if(!f){perror("open");return 1;}
    if(!load_pcre()){
        fprintf(stderr,"pcre not found\n");return 1;
    }
    char line[4096];
    int lineno=0;
    while(fgets(line,sizeof(line),f)){
        lineno++;
        char *tab=strchr(line,'\t');
        if(!tab) continue;
        *tab='\0';
        char *pat=line;
        char *subj=tab+1;
        subj[strcspn(subj,"\r\n")]=0;

        const char *err=NULL;
        int erroff=0;
        pcre *re = pcre_compile_f(pat,0,&err,&erroff,NULL);
        int has_match=0;
        int m_start=-1,m_end=-1;
        int g_start[64]={0},g_end[64]={0};
        int g_set[64]={0};
        int capture_cnt=0;
        if(re){
            int info=0;
            if(pcre_info_f) pcre_info_f(re, 2, &info, NULL); /* PCRE_INFO_CAPTURECOUNT = 2 */
            capture_cnt = info;
            int slen=strlen(subj);
            int ovec[256];
            for(int start=0; start<=slen && !has_match; start++){
                int rc=pcre_exec_f(re,NULL,subj,slen,start,0x08,ovec,256,0); /* 0x08 = PCRE_ANCHORED */
                if(rc>=0){
                    m_start=ovec[0];
                    m_end=ovec[1];
                    has_match=1;
                    for(int i=1;i<=capture_cnt && i<rc;i++){
                        int s=ovec[2*i];
                        int e=ovec[2*i+1];
                        if(s>=0){
                            g_start[i-1]=s;
                            g_end[i-1]=e;
                            g_set[i-1]=1;
                        }else{
                            g_set[i-1]=0;
                        }
                    }
                    /* groups not returned stay unset */
                }
            }
            pcre_free_f(re);
        }
        if(!has_match){
            printf("%d: no match\n",lineno);
        }else{
            printf("%d: %d-%d",lineno,m_start,m_end);
            for(int i=0;i<capture_cnt;i++){
                if(g_set[i]) printf(" %d-%d",g_start[i],g_end[i]);
                else printf(" -");
            }
            printf("\n");
        }
    }
    fclose(f);
    return 0;
}

