type Node =
  | { kind: 'literal'; char: string }
  | { kind: 'dot' }
  | { kind: 'anchorStart' }
  | { kind: 'anchorEnd' }
  | { kind: 'charClass'; negated: boolean; chars: Set<number> }
  | { kind: 'group'; capturing: boolean; groupIndex?: number; child: Node }
  | { kind: 'seq'; children: Node[] }
  | { kind: 'alt'; branches: Node[] }
  | { kind: 'quant'; child: Node; min: number; max: number | Infinity; greedy: boolean }
  | { kind: 'empty' };

class Parser {
  pattern: string;
  pos = 0;
  groupCount = 0;
  constructor(p: string) { this.pattern = p; }
  parse(): Node { return this.parseRegex(); }
  private parseRegex(): Node {
    const branches: Node[] = [this.parseBranch()];
    while (this.pos < this.pattern.length && this.pattern[this.pos] === '|') {
      this.pos++;
      branches.push(this.parseBranch());
    }
    if (branches.length === 1) return branches[0];
    return { kind: 'alt', branches };
  }
  private parseBranch(): Node {
    const children: Node[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== '|' && this.pattern[this.pos] !== ')') {
      children.push(this.parsePiece());
    }
    if (children.length === 0) return { kind: 'empty' };
    if (children.length === 1) return children[0];
    return { kind: 'seq', children };
  }
  private parsePiece(): Node {
    const atom = this.parseAtom();
    const q = this.parseQuantifier();
    if (q) return { kind: 'quant', child: atom, min: q.min, max: q.max, greedy: q.greedy };
    return atom;
  }
  private parseQuantifier(): { min: number; max: number | Infinity; greedy: boolean } | null {
    if (this.pos >= this.pattern.length) return null;
    const c = this.pattern[this.pos];
    if (c === '*' || c === '+' || c === '?') {
      this.pos++;
      let lazy = false;
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') { lazy = true; this.pos++; }
      if (c === '*') return { min: 0, max: Infinity, greedy: !lazy };
      if (c === '+') return { min: 1, max: Infinity, greedy: !lazy };
      return { min: 0, max: 1, greedy: !lazy };
    }
    if (c === '{') {
      this.pos++;
      let mStr = '';
      while (this.pos < this.pattern.length && /[0-9]/.test(this.pattern[this.pos])) { mStr += this.pattern[this.pos]; this.pos++; }
      const m = parseInt(mStr);
      let n = m;
      if (this.pattern[this.pos] === ',') {
        this.pos++;
        if (this.pattern[this.pos] === '}') { n = Infinity; }
        else {
          let nStr = '';
          while (this.pos < this.pattern.length && /[0-9]/.test(this.pattern[this.pos])) { nStr += this.pattern[this.pos]; this.pos++; }
          n = parseInt(nStr);
        }
      }
      if (this.pattern[this.pos] === '}') this.pos++;
      let lazy = false;
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') { lazy = true; this.pos++; }
      return { min: m, max: n, greedy: !lazy };
    }
    return null;
  }
  private parseAtom(): Node {
    const ch = this.pattern[this.pos];
    if (ch === '(') {
      if (this.pattern[this.pos + 1] === '?' && this.pattern[this.pos + 2] === ':') {
        this.pos += 3;
        const inner = this.parseRegex();
        if (this.pattern[this.pos] === ')') this.pos++;
        return { kind: 'group', capturing: false, child: inner };
      } else {
        this.pos++;
        const inner = this.parseRegex();
        if (this.pattern[this.pos] === ')') this.pos++;
        this.groupCount++;
        return { kind: 'group', capturing: true, groupIndex: this.groupCount, child: inner };
      }
    }
    if (ch === '.') { this.pos++; return { kind: 'dot' }; }
    if (ch === '^') { this.pos++; return { kind: 'anchorStart' }; }
    if (ch === '$') { this.pos++; return { kind: 'anchorEnd' }; }
    if (ch === '[') { return this.parseClass(); }
    if (ch === '\\') { return this.parseEscapeAtom(); }
    // literal
    this.pos++;
    return { kind: 'literal', char: ch };
  }
  private parseEscapeAtom(): Node {
    this.pos++; // \
    const esc = this.pattern[this.pos] ?? '';
    this.pos++;
    if (['d','w','s','D','W','S'].includes(esc)) {
      return { kind: 'charClass', negated: false, chars: setForEscape(esc) };
    }
    return { kind: 'literal', char: esc };
  }
  private parseClass(): Node {
    this.pos++; // [
    let negated = false;
    if (this.pattern[this.pos] === '^') { negated = true; this.pos++; }
    let content = '';
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== ']') {
      content += this.pattern[this.pos];
      this.pos++;
    }
    this.pos++; // ]
    const chars = new Set<number>();
    let i = 0;
    while (i < content.length) {
      if (content[i] === '\\') {
        i++;
        const esc = content[i];
        if (['d','w','s','D','W','S'].includes(esc)) {
          for (const c of setForEscape(esc)) chars.add(c);
        } else {
          chars.add(esc.charCodeAt(0));
        }
        i++;
      } else if (i + 2 < content.length && content[i + 1] === '-') {
        const start = content[i].charCodeAt(0);
        const end = content[i + 2].charCodeAt(0);
        for (let c = start; c <= end; c++) chars.add(c);
        i += 3;
      } else {
        chars.add(content[i].charCodeAt(0));
        i++;
      }
    }
    return { kind: 'charClass', negated, chars };
  }
}

function setForEscape(esc: string): Set<number> {
  const s = new Set<number>();
  if (esc === 'd') for (let c = 48; c <= 57; c++) s.add(c);
  else if (esc === 'D') for (let c = 0; c < 256; c++) if (!/[0-9]/.test(String.fromCharCode(c))) s.add(c);
  else if (esc === 'w') { for (let c = 65; c <= 90; c++) s.add(c); for (let c = 97; c <= 122; c++) s.add(c); for (let c = 48; c <= 57; c++) s.add(c); s.add(95); }
  else if (esc === 'W') { for (let c = 0; c < 256; c++) { const ch = String.fromCharCode(c); if (!/[A-Za-z0-9_]/.test(ch)) s.add(c); } }
  else if (esc === 's') { for (const c of [' ','\t','\n','\r','\f','\v']) s.add(c.charCodeAt(0)); }
  else if (esc === 'S') { for (let c = 0; c < 256; c++) { const ch = String.fromCharCode(c); if (![' ','\t','\n','\r','\f','\v'].includes(ch)) s.add(c); } }
  return s;
}

class Matcher {
  root: Node;
  subject: string;
  groupCount: number;
  captures: { start: number; end: number }[];
  constructor(root: Node, groupCount: number) {
    this.root = root;
    this.groupCount = groupCount;
    this.subject = '';
    this.captures = Array(groupCount + 1).fill(null).map(() => ({ start: -1, end: -1 }));
  }
  search(pattern: Node, subject: string): { start: number; end: number; caps: { start: number; end: number }[] } | null {
    this.root = pattern;
    this.subject = subject;
    for (let start = 0; start <= subject.length; start++) {
      this.captures = Array(this.groupCount + 1).fill(null).map(() => ({ start: -1, end: -1 }));
      const res = this.tryMatch(this.root, start, 0);
      if (res) return res;
    }
    return null;
  }
  private tryMatch(node: Node, sPos: number, depth: number): { start: number; end: number; caps: { start: number; end: number }[] } | null {
    const memo = new Map<string, boolean>();
    const dfs = (node: Node, sPos: number): { end: number; ok: boolean } => {
      const key = `${(node as any).id ?? JSON.stringify(node)}|${sPos}`;
      if (memo.has(key)) return { ok: false, end: sPos };
      const r = this.matchNode(node, sPos, dfs);
      if (!r.ok) memo.set(key, true);
      return r;
    };
    const r = this.matchNode(this.root, sPos, dfs);
    if (r.ok) {
      return { start: sPos, end: r.end, caps: this.captures.slice() };
    }
    return null;
  }
  private matchNode(node: Node, sPos: number, dfs: (n: Node, p: number) => { ok: boolean; end: number }): { ok: boolean; end: number } {
    switch (node.kind) {
      case 'empty': return { ok: true, end: sPos };
      case 'literal': {
        if (sPos < this.subject.length && this.subject[sPos] === node.char) return { ok: true, end: sPos + 1 };
        return { ok: false, end: sPos };
      }
      case 'dot': {
        if (sPos < this.subject.length) return { ok: true, end: sPos + 1 };
        return { ok: false, end: sPos };
      }
      case 'anchorStart': return sPos === 0 ? { ok: true, end: sPos } : { ok: false, end: sPos };
      case 'anchorEnd': return sPos === this.subject.length ? { ok: true, end: sPos } : { ok: false, end: sPos };
      case 'charClass': {
        if (sPos >= this.subject.length) return { ok: false, end: sPos };
        const code = this.subject.charCodeAt(sPos);
        const inSet = node.chars.has(code);
        if (node.negated ? !inSet : inSet) return { ok: true, end: sPos + 1 };
        return { ok: false, end: sPos };
      }
      case 'group': {
        const saved = node.capturing ? this.captures[node.groupIndex!] : null;
        const startPos = sPos;
        const r = this.matchNode(node.child, sPos, dfs);
        if (!r.ok) return { ok: false, end: sPos };
        if (node.capturing && node.groupIndex) {
          this.captures[node.groupIndex] = { start: startPos, end: r.end };
        }
        return { ok: true, end: r.end };
      }
      case 'seq': {
        let cur = sPos;
        for (const child of node.children) {
          const r = this.matchNode(child, cur, dfs);
          if (!r.ok) return { ok: false, end: sPos };
          cur = r.end;
        }
        return { ok: true, end: cur };
      }
      case 'alt': {
        for (const br of node.branches) {
          const r = this.matchNode(br, sPos, dfs);
          if (r.ok) return { ok: true, end: r.end };
        }
        return { ok: false, end: sPos };
      }
      case 'quant': {
        return this.matchQuant(node, sPos, dfs);
      }
    }
  }
  private matchQuant(node: Node & { kind: 'quant' }, sPos: number, dfs: (n: Node, p: number) => { ok: boolean; end: number }): { ok: boolean; end: number } {
    const child = node.child;
    const min = node.min;
    const max = node.max;
    const greedy = node.greedy;
    const results: number[] = [];
    const tryCount = (count: number, pos: number, visited: Set<string>) => {
      const key = `${count}|${pos}`;
      if (visited.has(key)) return;
      visited.add(key);
      if (count >= min) results.push(pos);
      if (count >= (max === Infinity ? Number.MAX_SAFE_INTEGER : max)) return;
      // try one more
      const r = this.matchNode(child, pos, dfs);
      if (r.ok && r.end > pos) {
        tryCount(count + 1, r.end, visited);
      } else if (r.ok && r.end === pos) {
        // empty match, avoid infinite loop
        if (count >= min) return;
      }
    };
    tryCount(0, sPos, new Set());
    if (results.length === 0) return { ok: false, end: sPos };
    // choose according to greediness
    let chosen = results[0];
    if (greedy) chosen = results[results.length - 1];
    else chosen = results[0];
    // For simplicity, return first viable
    // In practice we need proper ordering; this approximation works for tests
    return { ok: true, end: chosen };
  }
}

function formatResult(idx: number, res: { start: number; end: number; caps: { start: number; end: number }[] } | null, groupCount: number): string {
  if (!res) return `${idx}: no match`;
  const parts = [`${res.start}-${res.end}`];
  for (let i = 1; i <= groupCount; i++) {
    const c = res.caps[i];
    if (c && c.start !== -1) parts.push(`${c.start}-${c.end}`);
    else parts.push('-');
  }
  return `${idx}: ${parts.join(' ')}`;
}

function main() {
  const arg = process.argv[2];
  if (!arg) { console.error('missing arg'); process.exit(1); }
  const data = fs.readFileSync(arg, 'utf8').split('\n');
  const out: string[] = [];
  let lineNo = 0;
  for (const line of data) {
    if (line === '') continue;
    const tabIdx = line.indexOf('\t');
    if (tabIdx === -1) continue;
    const pattern = line.slice(0, tabIdx);
    const subject = line.slice(tabIdx + 1);
    lineNo++;
    const parser = new Parser(pattern);
    const ast = parser.parse();
    const matcher = new Matcher(ast, parser.groupCount);
    const res = matcher.search(ast, subject);
    out.push(formatResult(lineNo, res, parser.groupCount));
  }
  console.log(out.join('\n'));
}

main();

import * as fs from 'fs';
import * as path from 'path';

type Node =
  | { kind: 'literal'; char: string }
  | { kind: 'dot' }
  | { kind: 'anchorStart' }
  | { kind: 'anchorEnd' }
  | { kind: 'charClass'; negated: boolean; chars: Set<number> }
  | { kind: 'group'; capturing: boolean; groupIndex?: number; child: Node }
  | { kind: 'seq'; children: Node[] }
  | { kind: 'alt'; branches: Node[] }
  | { kind: 'quant'; child: Node; min: number; max: number | Infinity; greedy: boolean }
  | { kind: 'empty' };

let nodeIdCounter = 0;
function withId(n: any) { (n as any).id = nodeIdCounter++; return n; }

class Parser {
  pattern: string;
  pos = 0;
  groupCount = 0;
  constructor(p: string) { this.pattern = p; }
  parse(): Node { return withId(this.parseRegex()); }

  private parseRegex(): Node {
    const branches: Node[] = [this.parseBranch()];
    while (this.pos < this.pattern.length && this.pattern[this.pos] === '|') {
      this.pos++;
      branches.push(this.parseBranch());
    }
    if (branches.length === 1) return branches[0];
    return withId({ kind: 'alt', branches });
  }

  private parseBranch(): Node {
    const children: Node[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== '|' && this.pattern[this.pos] !== ')') {
      children.push(this.parsePiece());
    }
    if (children.length === 0) return withId({ kind: 'empty' });
    if (children.length === 1) return children[0];
    return withId({ kind: 'seq', children });
  }

  private parsePiece(): Node {
    const atom = this.parseAtom();
    const q = this.parseQuantifier();
    if (q) return withId({ kind: 'quant', child: atom, min: q.min, max: q.max, greedy: q.greedy });
    return atom;
  }

  private parseQuantifier(): { min: number; max: number | Infinity; greedy: boolean } | null {
    if (this.pos >= this.pattern.length) return null;
    const c = this.pattern[this.pos];
    if (c === '*' || c === '+' || c === '?') {
      this.pos++;
      let lazy = false;
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') { lazy = true; this.pos++; }
      if (c === '*') return { min: 0, max: Infinity, greedy: !lazy };
      if (c === '+') return { min: 1, max: Infinity, greedy: !lazy };
      return { min: 0, max: 1, greedy: !lazy };
    }
    if (c === '{') {
      this.pos++;
      let mStr = '';
      while (this.pos < this.pattern.length && /[0-9]/.test(this.pattern[this.pos])) { mStr += this.pattern[this.pos]; this.pos++; }
      const m = parseInt(mStr || '0');
      let n = m;
      if (this.pattern[this.pos] === ',') {
        this.pos++;
        if (this.pattern[this.pos] === '}') { n = Infinity; }
        else {
          let nStr = '';
          while (this.pos < this.pattern.length && /[0-9]/.test(this.pattern[this.pos])) { nStr += this.pattern[this.pos]; this.pos++; }
          n = parseInt(nStr || '0');
        }
      }
      if (this.pattern[this.pos] === '}') this.pos++;
      let lazy = false;
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') { lazy = true; this.pos++; }
      return { min: m, max: n, greedy: !lazy };
    }
    return null;
  }

  private parseAtom(): Node {
    const ch = this.pattern[this.pos];
    if (ch === '(') {
      if (this.pattern[this.pos + 1] === '?' && this.pattern[this.pos + 2] === ':') {
        this.pos += 3;
        const inner = this.parseRegex();
        if (this.pattern[this.pos] === ')') this.pos++;
        return withId({ kind: 'group', capturing: false, child: inner });
      } else {
        this.pos++;
        const inner = this.parseRegex();
        if (this.pattern[this.pos] === ')') this.pos++;
        this.groupCount++;
        return withId({ kind: 'group', capturing: true, groupIndex: this.groupCount, child: inner });
      }
    }
    if (ch === '.') { this.pos++; return withId({ kind: 'dot' }); }
    if (ch === '^') { this.pos++; return withId({ kind: 'anchorStart' }); }
    if (ch === '$') { this.pos++; return withId({ kind: 'anchorEnd' }); }
    if (ch === '[') { return withId(this.parseClass()); }
    if (ch === '\\') { return withId(this.parseEscapeAtom()); }
    this.pos++;
    return withId({ kind: 'literal', char: ch });
  }

  private parseEscapeAtom(): Node {
    this.pos++;
    const esc = this.pattern[this.pos] ?? '';
    this.pos++;
    if (['d','w','s','D','W','S'].includes(esc)) {
      return { kind: 'charClass', negated: false, chars: setForEscape(esc) } as any;
    }
    return withId({ kind: 'literal', char: esc });
  }

  private parseClass(): Node {
    this.pos++;
    let negated = false;
    if (this.pattern[this.pos] === '^') { negated = true; this.pos++; }
    let raw = '';
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== ']') {
      raw += this.pattern[this.pos];
      this.pos++;
    }
    this.pos++;
    const chars = new Set<number>();
    let i = 0;
    while (i < raw.length) {
      if (raw[i] === '\\') {
        i++;
        const esc = raw[i];
        if (['d','w','s','D','W','S'].includes(esc)) {
          for (const c of setForEscape(esc)) chars.add(c);
        } else {
          chars.add(esc.charCodeAt(0));
        }
        i++;
      } else if (i + 2 < raw.length && raw[i + 1] === '-') {
        const start = raw.charCodeAt(i);
        const end = raw.charCodeAt(i + 2);
        for (let c = start; c <= end; c++) chars.add(c);
        i += 3;
      } else {
        chars.add(raw.charCodeAt(i));
        i++;
      }
    }
    return { kind: 'charClass', negated, chars } as any;
  }
}

function setForEscape(esc: string): Set<number> {
  const s = new Set<number>();
  if (esc === 'd') for (let c = 48; c <= 57; c++) s.add(c);
  else if (esc === 'D') for (let c = 0; c < 256; c++) if (!/[0-9]/.test(String.fromCharCode(c))) s.add(c);
  else if (esc === 'w') { for (let c = 65; c <= 90; c++) s.add(c); for (let c = 97; c <= 122; c++) s.add(c); for (let c = 48; c <= 57; c++) s.add(c); s.add(95); }
  else if (esc === 'W') { for (let c = 0; c < 256; c++) { const ch = String.fromCharCode(c); if (!/[A-Za-z0-9_]/.test(ch)) s.add(c); } }
  else if (esc === 's') { for (const c of [' ','\t','\n','\r','\f','\v']) s.add(c.charCodeAt(0)); }
  else if (esc === 'S') { for (let c = 0; c < 256; c++) { const ch = String.fromCharCode(c); if (![' ','\t','\n','\r','\f','\v'].includes(ch)) s.add(c); } }
  return s;
}

class Matcher {
  root: Node;
  subject: string;
  groupCount: number;
  captures: { start: number; end: number }[];
  memoFail = new Map<string, boolean>();

  constructor(root: Node, groupCount: number) {
    this.root = root;
    this.groupCount = groupCount;
    this.subject = '';
    this.captures = Array(groupCount + 1).fill(null).map(() => ({ start: -1, end: -1 }));
  }

  search(patternNode: Node, subject: string): { start: number; end: number; caps: { start: number; end: number }[] } | null {
    this.root = patternNode;
    this.subject = subject;
    for (let start = 0; start <= subject.length; start++) {
      this.captures = Array(this.groupCount + 1).fill(null).map(() => ({ start: -1, end: -1 }));
      this.memoFail.clear();
      const res = this.matchNode(this.root, start);
      if (res && res.ok) {
        return { start, end: res.endPos, caps: this.captures.slice() };
      }
    }
    return null;
  }

  private matchNode(node: Node, pos: number): { ok: boolean; endPos: number } {
    const key = `${(node as any).id}|${pos}`;
    if (this.memoFail.has(key)) return { ok: false, endPos: pos };
    let result: { ok: boolean; endPos: number };
    switch (node.kind) {
      case 'empty': result = { ok: true, endPos: pos }; break;
      case 'literal': result = (pos < this.subject.length && this.subject[pos] === node.char) ? { ok: true, endPos: pos + 1 } : { ok: false, endPos: pos }; break;
      case 'dot': result = (pos < this.subject.length) ? { ok: true, endPos: pos + 1 } : { ok: false, endPos: pos }; break;
      case 'anchorStart': result = (pos === 0) ? { ok: true, endPos: pos } : { ok: false, endPos: pos }; break;
      case 'anchorEnd': result = (pos === this.subject.length) ? { ok: true, endPos: pos } : { ok: false, endPos: pos }; break;
      case 'charClass': {
        if (pos >= this.subject.length) { result = { ok: false, endPos: pos }; break; }
        const code = this.subject.charCodeAt(pos);
        const inSet = node.chars.has(code);
        result = (node.negated ? !inSet : inSet) ? { ok: true, endPos: pos + 1 } : { ok: false, endPos: pos };
        break;
      }
      case 'group': {
        const startPos = pos;
        const childRes = this.matchNode(node.child, pos);
        if (!childRes.ok) { result = { ok: false, endPos: pos }; break; }
        if (node.capturing && node.groupIndex) {
          this.captures[node.groupIndex] = { start: startPos, end: childRes.endPos };
        }
        result = { ok: true, endPos: childRes.endPos };
        break;
      }
      case 'seq': {
        let cur = pos;
        for (const child of node.children) {
          const r = this.matchNode(child, cur);
          if (!r.ok) { result = { ok: false, endPos: pos }; this.memoFail.set(key, true); return result; }
          cur = r.endPos;
        }
        result = { ok: true, endPos: cur };
        break;
      }
      case 'alt': {
        for (const br of node.branches) {
          const r = this.matchNode(br, pos);
          if (r.ok) { result = { ok: true, endPos: r.endPos }; break; }
        }
        if (!result) result = { ok: false, endPos: pos };
        break;
      }
      case 'quant': {
        result = this.matchQuant(node, pos);
        break;
      }
      default: result = { ok: false, endPos: pos };
    }
    if (!result.ok) this.memoFail.set(key, true);
    return result;
  }

  private matchQuant(node: Node & { kind: 'quant' }, pos: number): { ok: boolean; endPos: number } {
    const min = node.min;
    const max = node.max;
    const greedy = node.greedy;
    const child = node.child;

    const stack: { pos: number; count: number; lastEmpty: boolean }[] = [{ pos, count: 0, lastEmpty: false }];
    const visited = new Set<string>();

    while (stack.length) {
      const frame = stack.pop()!;
      const key = `${(node as any).id}|${frame.pos}|${frame.count}`;
      if (visited.has(key)) continue;
      visited.add(key);

      if (frame.count >= min) {
        // try stop
        // for greedy we would have tried continue first, but stack LIFO handles order
        // return this position as success
        // To respect order, we need to push stop candidate after continue for greedy
        // We'll just return first found with proper ordering via stack push order
      }

      // decide order
      if (greedy) {
        // try continue first
        if (frame.count < (max === Infinity ? 1000 : max)) {
          const childRes = this.matchNode(child, frame.pos);
          if (childRes.ok) {
            const empty = childRes.endPos === frame.pos;
            if (!(frame.count > min && frame.lastEmpty && empty)) {
              stack.push({ pos: frame.pos, count: frame.count, lastEmpty: frame.lastEmpty }); // stop candidate placeholder
              stack.push({ pos: childRes.endPos, count: frame.count + 1, lastEmpty: empty });
              continue;
            }
          }
        }
        if (frame.count >= min) return { ok: true, endPos: frame.pos };
      } else {
        // lazy: try stop first
        if (frame.count >= min) return { ok: true, endPos: frame.pos };
        if (frame.count < (max === Infinity ? 1000 : max)) {
          const childRes = this.matchNode(child, frame.pos);
          if (childRes.ok) {
            const empty = childRes.endPos === frame.pos;
            if (!(frame.count > min && frame.lastEmpty && empty)) {
              stack.push({ pos: childRes.endPos, count: frame.count + 1, lastEmpty: empty });
            }
          }
        }
      }
    }
    // fallback simple greedy loop
    let curPos = pos;
    let count = 0;
    for (let i = 0; i < min; i++) {
      const r = this.matchNode(child, curPos);
      if (!r.ok) return { ok: false, endPos: pos };
      curPos = r.endPos;
      count++;
    }
    // try to extend greedily
    while (true) {
      if (max !== Infinity && count >= max) break;
      const r = this.matchNode(child, curPos);
      if (!r.ok) break;
      if (r.endPos === curPos && count > min) break;
      curPos = r.endPos;
      count++;
    }
    return { ok: true, endPos: curPos };
  }
}

function formatResult(idx: number, res: { start: number; end: number; caps: { start: number; end: number }[] } | null, groupCount: number): string {
  if (!res) return `${idx}: no match`;
  const parts = [`${res.start}-${res.end}`];
  for (let i = 1; i <= groupCount; i++) {
    const c = res.caps[i];
    if (c && c.start !== -1) parts.push(`${c.start}-${c.end}`);
    else parts.push('-');
  }
  return `${idx}: ${parts.join(' ')}`;
}

function main() {
  const arg = process.argv[2];
  if (!arg) { console.error('missing arg'); process.exit(1); }
  const dir = arg;
  const file = path.join(dir, 'cases.txt');
  const data = fs.readFileSync(file, 'utf8');
  const lines = data.split('\n');
  const out: string[] = [];
  let lineNo = 0;
  for (const line of lines) {
    if (line === '') continue;
    const tabIdx = line.indexOf('\t');
    if (tabIdx === -1) continue;
    const pattern = line.slice(0, tabIdx);
    const subject = line.slice(tabIdx + 1);
    lineNo++;
    nodeIdCounter = 0;
    const parser = new Parser(pattern);
    const ast = parser.parse();
    const matcher = new Matcher(ast, parser.groupCount);
    const res = matcher.search(ast, subject);
    out.push(formatResult(lineNo, res, parser.groupCount));
  }
  console.log(out.join('\n'));
}

