static uint32_t crc_table[256];
static void crc32_init(void){
    for(int i=0;i<256;i++){
        uint32_t c=i;
        for(int j=0;j<8;j++) c = (c>>1) ^ (c&1 ? 0xEDB88320U : 0);
        crc_table[i]=c;
    }
}
static uint32_t crc32_calc(const unsigned char *data, size_t len){
    uint32_t crc=0xFFFFFFFFU;
    for(size_t i=0;i<len;i++) crc = (crc>>8) ^ crc_table[(crc ^ data[i]) & 0xFF];
    return crc ^ 0xFFFFFFFFU;
}

static void escape_text(const unsigned char *s, size_t len, char *out, size_t outsz){
    size_t pos=0;
    out[pos++]='"';
    for(size_t i=0;i<len && pos+4<outsz;i++){
        unsigned char c=s[i];
        if(c=='\\'){ out[pos++]='\\'; out[pos++]='\\'; }
        else if(c=='"'){ out[pos++]='\\'; out[pos++]='"'; }
        else if(c=='\n'){ out[pos++]='\\'; out[pos++]='n'; }
        else if(c=='\r'){ out[pos++]='\\'; out[pos++]='r'; }
        else if(c=='\t'){ out[pos++]='\\'; out[pos++]='t'; }
        else if(c<0x20 || c>0x7E){
            pos+= snprintf(out+pos, outsz-pos, "\\x%02X", c);
        }else{
            out[pos++]=c;
        }
    }
    out[pos++]='"';
    out[pos]=0;
}

static void format_real(double v, char *buf, size_t sz){
    char tmp[128];
    snprintf(tmp, sizeof tmp, "%.15f", v);
    char *p=tmp;
    while(*p && (*p=='-'||*p=='0'||*p=='.'||isdigit(*p))) p++;
    p--;
    while(p>tmp && *p=='0') p--;
    if(*p=='.') p++;
    *++p=0;
    strncpy(buf, tmp, sz);
}

