import Foundation

indirect enum Node {
    case literal(UInt8)
    case dot
    case anchorStart
    case anchorEnd
    case charClass(Set<UInt8>, inverted: Bool)
    case group(Node, capturing: Bool, groupIndex: Int)
    case concat([Node])
    case alternation([Node])
    case quantifier(Node, min: Int, max: Int?, lazy: Bool)
    case empty
}

struct Parser {
    let s: String
    var idx: String.Index
    var groupCounter = 0
    init(_ s: String) { self.s = s; self.idx = s.startIndex }
    var atEnd: Bool { idx >= s.endIndex }
    var cur: Character { atEnd ? "\0" : s[idx] }
    mutating func advance() { if !atEnd { idx = s.index(after: idx) } }
    mutating func peek() -> Character { cur }
    mutating func peekNext() -> Character {
        let n = s.index(after: idx)
        return n < s.endIndex ? s[n] : "\0"
    }
    mutating func consume(_ c: Character) { if cur == c { advance() } }
    mutating func parseRegex() -> Node {
        let branch = parseBranch()
        var branches = [branch]
        while !atEnd && cur == "|" {
            advance()
            branches.append(parseBranch())
        }
        return branches.count == 1 ? branch : .alternation(branches)
    }
    mutating func parseBranch() -> Node {
        var nodes: [Node] = []
        while !atEnd && cur != "|" && cur != ")" {
            nodes.append(parsePiece())
        }
        if nodes.isEmpty { return .empty }
        if nodes.count == 1 { return nodes[0] }
        return .concat(nodes)
    }
    mutating func parsePiece() -> Node {
        let atom = parseAtom()
        if let q = parseQuantifierAfterAtom() {
            return .quantifier(atom, min: q.min, max: q.max, lazy: q.lazy)
        }
        return atom
    }
    mutating func parseAtom() -> Node {
        guard !atEnd else { return .empty }
        let c = cur
        switch c {
        case "(":
            advance()
            var capturing = true
            var groupIdx = -1
            if cur == "?" {
                let nxt = s.index(after: idx)
                if nxt < s.endIndex && s[nxt] == ":" {
                    advance(); advance()
                    capturing = false
                } else {
                    // unsupported, treat as literal
                }
            }
            let inner = parseRegex()
            if !atEnd && cur == ")" { advance() }
            if capturing {
                groupCounter += 1
                groupIdx = groupCounter
            }
            return .group(inner, capturing: capturing, groupIndex: groupIdx)
        case ".":
            advance(); return .dot
        case "^":
            advance(); return .anchorStart
        case "$":
            advance(); return .anchorEnd
        case "[":
            return parseCharClass()
        case "\\":
            return parseEscape()
        default:
            advance(); return .literal(UInt8(c.unicodeScalars.first!.value))
        }
    }
    mutating func parseEscape() -> Node {
        advance()
        guard !atEnd else { return .empty }
        let c = cur; advance()
        switch c {
        case "d": return .charClass(Set(48...57), inverted: false)
        case "w": return .charClass(Set(65...90).union(97...122).union(48...57).union([95]), inverted: false)
        case "s": return .charClass(Set([32,9,10,13,12,11]), inverted: false)
        case "D": return .charClass(Set(48...57), inverted: true)
        case "W": return .charClass(Set(65...90).union(97...122).union(48...57).union([95]), inverted: true)
        case "S": return .charClass(Set([32,9,10,13,12,11]), inverted: true)
        default:
            return .literal(UInt8(c.unicodeScalars.first!.value))
        }
    }
    mutating func parseCharClass() -> Node {
        advance() // [
        var inverted = false
        if !atEnd && cur == "^" { inverted = true; advance() }
        var allowed = Set<UInt8>()
        while !atEnd && cur != "]" {
            if cur == "\\" {
                advance()
                guard !atEnd else { break }
                let esc = cur; advance()
                switch esc {
                case "d": allowed.formUnion(48...57)
                case "w": allowed.formUnion(65...90); allowed.formUnion(97...122); allowed.formUnion(48...57); allowed.insert(95)
                case "s": allowed.formUnion([32,9,10,13,12,11])
                case "D": break
                case "W": break
                case "S": break
                default: if let v = esc.unicodeScalars.first { allowed.insert(UInt8(v.value)) }
                }
            } else if let nextIdx = s.index(after: idx), s.index(after: nextIdx) < s.endIndex {
                // possible range a-b
                let first = cur
                let second = s.index(after: idx)
                let third = s.index(after: second)
                if s[second] == "-" && s[third] != "]" {
                    let start = UInt8(first.unicodeScalars.first!.value)
                    let endC = s[third]
                    let end = UInt8(endC.unicodeScalars.first!.value)
                    if start <= end {
                        for v in start...end { allowed.insert(v) }
                    }
                    idx = s.index(after: third)
                    continue
                }
            }
            if let v = cur.unicodeScalars.first { allowed.insert(UInt8(v.value)) }
            advance()
        }
        if !atEnd && cur == "]" { advance() }
        return .charClass(allowed, inverted: inverted)
    }
    mutating func parseQuantifierAfterAtom() -> (min:Int,max:Int?,lazy:Bool)? {
        guard !atEnd else { return nil }
        var min = 0, maxOpt: Int? = nil, lazy = false
        if cur == "*" {
            advance()
            if !atEnd && cur == "?" { lazy = true; advance() }
            min = 0; maxOpt = nil
            return (min,maxOpt,lazy)
        } else if cur == "+" {
            advance()
            if !atEnd && cur == "?" { lazy = true; advance() }
            min = 1; maxOpt = nil
            return (min,maxOpt,lazy)
        } else if cur == "?" {
            advance()
            if !atEnd && cur == "?" { lazy = true; advance() }
            min = 0; maxOpt = 1
            return (min,maxOpt,lazy)
        } else if cur == "{" {
            advance()
            var num = ""
            while !atEnd && cur.isNumber { num.append(cur); advance() }
            guard let m = Int(num) else { return nil }
            min = m
            if !atEnd && cur == "," {
                advance()
                var num2 = ""
                while !atEnd && cur.isNumber { num2.append(cur); advance() }
                if num2.isEmpty {
                    maxOpt = nil
                } else if let n = Int(num2) { maxOpt = n }
                else { maxOpt = nil }
            } else {
                maxOpt = m
            }
            if !atEnd && cur == "}" { advance() }
            if !atEnd && cur == "?" { lazy = true; advance() }
            return (min,maxOpt,lazy)
        }
        return nil
    }
}

struct Matcher {
    let subject: [UInt8]
    let len: Int
    let node: Node
    let groupCount: Int
    init(subject: String, node: Node, groupCount: Int) {
        self.subject = Array(subject.utf8)
        self.len = self.subject.count
        self.node = node
        self.groupCount = groupCount
    }
    typealias Captures = [(start:Int?, end:Int?)]
    func matchAll(_ node: Node, pos: Int, captures: Captures) -> [(Int, Captures)] {
        switch node {
        case .empty:
            return [(pos, captures)]
        case .literal(let v):
            if pos < len && subject[pos] == v { return [(pos+1, captures)] }
            return []
        case .dot:
            if pos < len { return [(pos+1, captures)] }
            return []
        case .anchorStart:
            return pos == 0 ? [(pos, captures)] : []
        case .anchorEnd:
            return pos == len ? [(pos, captures)] : []
        case .charClass(let set, let inv):
            if pos < len {
                let ch = subject[pos]
                let ok = set.contains(ch)
                if inv ? !ok : ok { return [(pos+1, captures)] }
            }
            return []
        case .group(let inner, let capturing, let gid):
            var res: [(Int, Captures)] = []
            let innerRes = matchAll(inner, pos, captures)
            for (np, cap) in innerRes {
                var newCap = cap
                if capturing && gid > 0 {
                    if newCap.count <= gid { newCap.append(contentsOf: Array(repeating: (nil,nil), count: gid - newCap.count + 1)) }
                    newCap[gid-1] = (pos, np)
                }
                res.append((np, newCap))
            }
            return res
        case .concat(let nodes):
            var curPos = pos
            var curCaps = captures
            var results: [(Int, Captures)] = []
            func dfs(_ i: Int, _ p: Int, _ c: Captures) {
                if i == nodes.count {
                    results.append((p, c))
                    return
                }
                let sub = matchAll(nodes[i], p, c)
                for (np, nc) in sub {
                    dfs(i+1, np, nc)
                }
            }
            dfs(0, pos, captures)
            return results
        case .alternation(let branches):
            var out: [(Int, Captures)] = []
            for b in branches {
                out.append(contentsOf: matchAll(b, pos, captures))
            }
            return out
        case .quantifier(let inner, let min, let max, let lazy):
            return matchQuantifier(inner, min: min, max: max, lazy: lazy, pos: pos, captures: captures)
        }
    }
    func matchQuantifier(_ inner: Node, min: Int, max: Int?, lazy: Bool, pos: Int, captures: Captures) -> [(Int, Captures)] {
        var results: [(Int, Captures)] = []
        var stack: [(pos:Int, k:Int, caps:Captures, lastEmpty:Bool)] = [(pos,0,captures,false)]
        var visited = Set<String>()
        while !stack.isEmpty {
            let (curPos,k,caps,lastEmpty) = stack.removeLast()
            let key = "\(curPos)-\(k)-\(lastEmpty)"
            if visited.contains(key) { continue }
            visited.insert(key)
            if k >= min {
                if lazy {
                    results.append((curPos,caps))
                }
            }
            // try extend
            let canExtend = (max == nil || k < max)
            if canExtend && !(k > min && lastEmpty) {
                let innerMatches = matchAll(inner, curPos, caps)
                for (np,nc) in innerMatches {
                    let empty = np == curPos
                    if k < min || !(k > min && empty) {
                        stack.append((np, k+1, nc, empty))
                    }
                }
            }
            if k >= min && !lazy {
                results.append((curPos,caps))
            }
        }
        // deduplicate preserving order
        var seen = Set<String>()
        var uniq: [(Int, Captures)] = []
        for r in results {
            let s = "\(r.0)-\(r.1.map{"\($0.0 ?? -1)-\($0.1 ?? -1)"}.joined(separator:"|"))"
            if !seen.contains(s) { seen.insert(s); uniq.append(r) }
        }
        return uniq
    }
    func findFirstMatch() -> (start:Int,end:Int,caps:[(Int?,Int?)])? {
        var allCaptures = Array(repeating: (nil as Int?, nil as Int?), count: groupCount+1)
        for start in 0...len {
            let capsInit = Array(repeating: (nil as Int?, nil as Int?), count: groupCount+1)
            let matches = matchAll(node, start, capsInit)
            if let first = matches.first {
                let end = first.0
                var caps = Array(repeating: (nil as Int?, nil as Int?), count: groupCount+1)
                for i in 1...groupCount {
                    if i-1 < first.1.count { caps[i] = first.1[i-1] }
                }
                return (start,end,caps)
            }
        }
        return nil
    }
}

func countGroups(_ node: Node) -> Int {
    switch node {
    case .group(let inner, let capturing, _):
        let innerCount = countGroups(inner)
        return capturing ? innerCount + 1 : innerCount
    case .concat(let nodes), .alternation(let nodes):
        return nodes.reduce(0) { $0 + countGroups($1) }
    case .quantifier(let inner, _, _, _):
        return countGroups(inner)
    default: return 0
    }
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(0) }
let path = args[1]
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.split(separator: "\n", omittingEmptySubsequences: false)
var outLines: [String] = []
var lineNo = 1
for raw in lines {
    let line = String(raw)
    if line.isEmpty { continue }
    if let tabIdx = line.firstIndex(of: "\t") {
        let pattern = String(line[..<tabIdx])
        let subject = String(line[line.index(after: tabIdx)...])
        var parser = Parser(pattern)
        let ast = parser.parseRegex()
        let gcount = countGroups(ast)
        let matcher = Matcher(subject: subject, node: ast, groupCount: gcount)
        if let m = matcher.findFirstMatch() {
            var parts: [String] = ["\(lineNo): \(m.start)-\(m.end)"]
            for i in 1...gcount {
                let c = m.caps[i]
                if let s = c.0, let e = c.1 {
                    parts.append("\(s)-\(e)")
                } else {
                    parts.append("-")
                }
            }
            outLines.append(parts.joined(separator: " "))
        } else {
            outLines.append("\(lineNo): no match")
        }
    }
    lineNo += 1
}
print(outLines.joined(separator: "\n"))

import Foundation

// ---------- AST ----------
indirect enum Node {
    case literal(UInt8)
    case dot
    case anchorStart
    case anchorEnd
    case charClass(Set<UInt8>, inverted: Bool)
    case group(Node, capturing: Bool, groupIndex: Int)
    case concat([Node])
    case alternation([Node])
    case quantifier(Node, min: Int, max: Int?, lazy: Bool)
    case empty
}

// ---------- Parser ----------
struct Parser {
    let chars: [Character]
    var i: Int = 0
    var groupCount = 0

    init(_ s: String) { self.chars = Array(s); self.i = 0 }

    mutating func parse() -> Node { parseRegex() }

    mutating func parseRegex() -> Node {
        let first = parseBranch()
        var branches = [first]
        while i < chars.count && chars[i] == "|" {
            i += 1
            branches.append(parseBranch())
        }
        return branches.count == 1 ? first : .alternation(branches)
    }

    mutating func parseBranch() -> Node {
        var nodes: [Node] = []
        while i < chars.count {
            let c = chars[i]
            if c == "|" || c == ")" { break }
            nodes.append(parsePiece())
        }
        if nodes.isEmpty { return .empty }
        if nodes.count == 1 { return nodes[0] }
        return .concat(nodes)
    }

    mutating func parsePiece() -> Node {
        let atom = parseAtom()
        if let q = parseQuantifier() {
            return .quantifier(atom, min: q.min, max: q.max, lazy: q.lazy)
        }
        return atom
    }

    mutating func parseAtom() -> Node {
        guard i < chars.count else { return .empty }
        let c = chars[i]
        switch c {
        case "(":
            i += 1
            var capturing = true
            if i + 1 < chars.count && chars[i] == "?" && chars[i+1] == ":" {
                capturing = false
                i += 2
            }
            let inner = parseRegex()
            if i < chars.count && chars[i] == ")" { i += 1 }
            if capturing {
                groupCount += 1
                return .group(inner, capturing: true, groupIndex: groupCount)
            } else {
                return .group(inner, capturing: false, groupIndex: 0)
            }
        case ".":
            i += 1; return .dot
        case "^":
            i += 1; return .anchorStart
        case "$":
            i += 1; return .anchorEnd
        case "[":
            return parseCharClass()
        case "\\":
            return parseEscape()
        default:
            // literal
            i += 1
            return .literal(UInt8(c.unicodeScalars.first!.value))
        }
    }

    mutating func parseQuantifier() -> (min:Int,max:Int?,lazy:Bool)? {
        guard i < chars.count else { return nil }
        let c = chars[i]
        if c == "*" {
            i += 1
            let lazy = i < chars.count && chars[i] == "?" ? (i+=1; true) : false
            return (0, nil, lazy)
        }
        if c == "+" {
            i += 1
            let lazy = i < chars.count && chars[i] == "?" ? (i+=1; true) : false
            return (1, nil, lazy)
        }
        if c == "?" {
            i += 1
            let lazy = i < chars.count && chars[i] == "?" ? (i+=1; true) : false
            return (0, 1, lazy)
        }
        if c == "{" {
            i += 1
            var num = ""
            while i < chars.count && chars[i].isNumber { num.append(chars[i]); i+=1 }
            guard let m = Int(num) else { return nil }
            var maxV: Int? = nil
            if i < chars.count && chars[i] == "," {
                i += 1
                var num2 = ""
                while i < chars.count && chars[i].isNumber { num2.append(chars[i]); i+=1 }
                if num2.isEmpty { maxV = nil } else { maxV = Int(num2) }
            } else {
                maxV = m
            }
            if i < chars.count && chars[i] == "}" { i += 1 }
            let lazy = i < chars.count && chars[i] == "?" ? (i+=1; true) : false
            return (m, maxV, lazy)
        }
        return nil
    }

    mutating func parseEscape() -> Node {
        i += 1
        guard i < chars.count else { return .empty }
        let c = chars[i]; i += 1
        switch c {
        case "d": return .charClass(digitsSet, inverted:false)
        case "w": return .charClass(wordSet, inverted:false)
        case "s": return .charClass(spaceSet, inverted:false)
        case "D": return .charClass(digitsSet, inverted:true)
        case "W": return .charClass(wordSet, inverted:true)
        case "S": return .charClass(spaceSet, inverted:true)
        default:
            return .literal(UInt8(c.unicodeScalars.first!.value))
        }
    }

    mutating func parseCharClass() -> Node {
        i += 1 // '['
        var inverted = false
        if i < chars.count && chars[i] == "^" { inverted = true; i += 1 }
        var allowed = Set<UInt8>()
        while i < chars.count && chars[i] != "]" {
            if chars[i] == "\\" {
                i += 1
                guard i < chars.count else { break }
                let esc = chars[i]; i += 1
                switch esc {
                case "d": allowed.formUnion(digitsSet)
                case "w": allowed.formUnion(wordSet)
                case "s": allowed.formUnion(spaceSet)
                case "D": break
                case "W": break
                case "S": break
                default:
                    allowed.insert(UInt8(esc.unicodeScalars.first!.value))
                }
            } else {
                // range ?
                if i + 2 < chars.count && chars[i+1] == "-" && chars[i+2] != "]" {
                    let sChar = chars[i]
                    let eChar = chars[i+2]
                    let sVal = UInt8(sChar.unicodeScalars.first!.value)
                    let eVal = UInt8(eChar.unicodeScalars.first!.value)
                    if sVal <= eVal {
                        for v in sVal...eVal { allowed.insert(v) }
                    }
                    i += 3
                    continue
                } else {
                    allowed.insert(UInt8(chars[i].unicodeScalars.first!.value))
                    i += 1
                }
            }
        }
        if i < chars.count && chars[i] == "]" { i += 1 }
        return .charClass(allowed, inverted: inverted)
    }
}

let digitsSet: Set<UInt8> = Set(48...57)
let wordSet: Set<UInt8> = Set(65...90).union(97...122).union(48...57).union([95])
let spaceSet: Set<UInt8> = [32,9,10,13,12,11]

// ---------- Normalisation ----------
func normalize(_ node: Node) -> Node {
    switch node {
    case .quantifier(let inner, let min, let max, let lazy):
        let innerN = normalize(inner)
        if case .quantifier(let inner2, _, _, _) = innerN {
            // merge nested quantifiers -> collapse to *
            return .quantifier(inner2, min: 0, max: nil, lazy: lazy)
        }
        return .quantifier(innerN, min: min, max: max, lazy: lazy)
    case .group(let inner, let cap, let idx):
        return .group(normalize(inner), capturing: cap, groupIndex: idx)
    case .concat(let nodes):
        return .concat(nodes.map { normalize($0) })
    case .alternation(let branches):
        return .alternation(branches.map { normalize($0) })
    default:
        return node
    }
}

// ---------- Matcher ----------
struct Matcher {
    let subject: [UInt8]
    let len: Int
    let root: Node
    let groupCount: Int

    init(subject: String, root: Node, groupCount: Int) {
        self.subject = Array(subject.utf8)
        self.len = subject.utf8.count
        self.root = normalize(root)
        self.groupCount = groupCount
    }

    func charMatches(_ node: Node, pos: Int) -> Bool {
        switch node {
        case .literal(let v):
            return pos < len && subject[pos] == v
        case .dot:
            return pos < len
        case .charClass(let set, let inv):
            guard pos < len else { return false }
            let ch = subject[pos]
            let ok = set.contains(ch)
            return inv ? !ok : ok
        default:
            return false
        }
    }

    // backtracking with memoised dead states
    func findFirst() -> (start:Int,end:Int,caps:[(Int?,Int?)])? {
        var dead = Set<String>()
        for start in 0...len {
            let capsInit = Array(repeating: (nil as Int?, nil as Int?), count: groupCount+1)
            if let res = dfs(node: root, pos: start, posStart: start, caps: capsInit, dead: &dead) {
                return res
            }
        }
        return nil
    }

    private func dfs(node: Node, pos: Int, posStart: Int, caps: [(Int?,Int?)], dead: inout Set<String>) -> (start:Int,end:Int,caps:[(Int?,Int?)])? {
        let key = "\(nodeDescription(node))-\(pos)"
        if dead.contains(key) { return nil }
        switch node {
        case .empty:
            return (posStart, pos, caps)
        case .literal(let v), .dot, .charClass:
            // handled by caller
            return nil
        case .anchorStart:
            return pos == 0 ? (posStart, pos, caps) : nil
        case .anchorEnd:
            return pos == len ? (posStart, pos, caps) : nil
        case .group(let inner, let capturing, let gid):
            if let r = dfs(node: inner, pos: pos, posStart: posStart, caps: caps, dead: &dead) {
                var newCaps = caps
                if capturing && gid > 0 {
                    if newCaps.count <= gid { newCaps.append(contentsOf: Array(repeating: (nil,nil), count: gid - newCaps.count +1)) }
                    newCaps[gid] = (posStart, r.end)
                }
                return (r.start, r.end, newCaps)
            }
            dead.insert(key)
            return nil
        case .concat(let nodes):
            var curPos = pos
            var curCaps = caps
            var curStart = posStart
            for n in nodes {
                if let r = dfs(node: n, pos: curPos, posStart: curStart, caps: curCaps, dead: &dead) {
                    curPos = r.end
                    curCaps = r.caps
                    curStart = r.start
                } else {
                    dead.insert(key)
                    return nil
                }
            }
            return (posStart, curPos, curCaps)
        case .alternation(let branches):
            for b in branches {
                if let r = dfs(node: b, pos: pos, posStart: posStart, caps: caps, dead: &dead) {
                    return r
                }
            }
            dead.insert(key)
            return nil
        case .quantifier(let inner, let min, let max, let lazy):
            return matchQuantifier(inner: inner, min: min, max: max, lazy: lazy, pos: pos, posStart: posStart, caps: caps, dead: &dead)
        }
    }

    private func matchQuantifier(inner: Node, min: Int, max: Int?, lazy: Bool, pos: Int, posStart: Int, caps: [(Int?,Int?)], dead: inout Set<String>) -> (start:Int,end:Int,caps:[(Int?,Int?)])? {
        var curPos = pos
        var curCaps = caps
        var count = 0
        var lastEmpty = false
        // mandatory part
        while count < min {
            guard let r = tryInner(inner, curPos, curCaps) else {
                dead.insert("quant-\(innerDescription(inner))-\(pos)")
                return nil
            }
            if r.empty && count > 0 { break } // optional empty stop
            curPos = r.newPos
            curCaps = r.newCaps
            count += 1
            lastEmpty = r.empty
        }
        // try to produce match in priority order
        func attempt() -> (start:Int,end:Int,caps:[(Int?,Int?)])? {
            if count >= min {
                // success
                return (posStart, curPos, curCaps)
            }
            return nil
        }
        if lazy {
            if let r = attempt() { return r }
        }
        // try extend
        var stack: [(Int,Int,[(Int?,Int?)],Bool)] = []
        var pPos = curPos
        var pCount = count
        var pCaps = curCaps
        var pLastEmpty = lastEmpty
        while true {
            if pCount >= min {
                if !lazy {
                    return (posStart, pPos, pCaps)
                }
            }
            if max != nil && pCount >= max! { break }
            if pCount > min && pLastEmpty { break }
            guard let r = tryInner(inner, pPos, pCaps) else { break }
            if r.empty && pCount > min { break }
            pPos = r.newPos
            pCaps = r.newCaps
            pCount += 1
            pLastEmpty = r.empty
            if lazy {
                // try stop before extending further
                if pCount >= min {
                    return (posStart, pPos, pCaps)
                }
            }
        }
        if lazy {
            if pCount >= min { return (posStart, pPos, pCaps) }
        }
        // fallback
        if count >= min { return (posStart, curPos, curCaps) }
        return nil
    }

    private func tryInner(_ inner: Node, _ pos: Int, _ caps: [(Int?,Int?)]) -> (newPos:Int,newCaps:[(Int?,Int?)],empty:Bool)? {
        // simple try for one atom
        var tmpCaps = caps
        var curPos = pos
        switch inner {
        case .literal(let v):
            if pos < len && subject[pos] == v { curPos +=1; return (curPos,tmpCaps,false) }
            return nil
        case .dot:
            if pos < len { curPos +=1; return (curPos,tmpCaps,false) }
            return nil
        case .charClass(let set, let inv):
            if pos < len {
                let ch = subject[pos]
                let ok = set.contains(ch)
                if inv ? !ok : ok { curPos +=1; return (curPos,tmpCaps,false) }
            }
            return nil
        case .group(let gInner, let capturing, let gid):
            // recurse one step for group? simplify
            if let r = dfs(node: gInner, pos: pos, posStart: pos, caps: tmpCaps, dead: &Set<String>()) {
                // we need end pos
                return (r.end, tmpCaps, r.end == pos)
            }
            return nil
        default:
            // fallback generic
            return nil
        }
    }

    private func nodeDescription(_ node: Node) -> String {
        switch node {
        case .literal(let v): return "lit\(v)"
        case .dot: return "dot"
        case .anchorStart: return "as"
        case .anchorEnd: return "ae"
        case .charClass: return "cc"
        case .group: return "grp"
        case .concat: return "cat"
        case .alternation: return "alt"
        case .quantifier: return "q"
        case .empty: return "emp"
        }
    }
    private func innerDescription(_ node: Node) -> String { nodeDescription(node) }
}

