guard args.count >= 2 else { exit(0) }
let path = args[1]
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.split(separator: "\n", omittingEmptySubsequences: false)
var out: [String] = []
var lineNo = 1
for raw in lines {
    let line = String(raw)
    if line.isEmpty { lineNo += 1; continue }
    if let tab = line.firstIndex(of: "\t") {
        let pattern = String(line[..<tab])
        let subject = String(line[line.index(after: tab)...])
        var parser = Parser(pattern)
        let ast = parser.parse()
        let gcount = parser.groupCount
        let matcher = Matcher(subject: subject, root: ast, groupCount: gcount)
        if let m = matcher.findFirst() {
            var parts = ["\(lineNo): \(m.start)-\(m.end)"]
            for i in 1...gcount {
                let c = m.caps[i]
                if let s = c.0, let e = c.1 { parts.append("\(s)-\(e)") } else { parts.append("-") }
            }
            out.append(parts.joined(separator: " "))
        } else {
            out.append("\(lineNo): no match")
        }
    }
    lineNo += 1
}
print(out.joined(separator: "\n"))

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(HashMap<String, Value>),
}

struct JsonParser<'a> {
    s: &'a str,
    pos: usize,
}
impl<'a> JsonParser<'a> {
    fn new(s: &'a str) -> Self { Self { s, pos: 0 } }
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            let c = self.s.as_bytes()[self.pos] as char;
            if c == ' ' || c == '\n' || c == '\r' || c == '\t' { self.pos += 1; } else { break; }
        }
    }
    fn peek(&self) -> Option<char> {
        if self.pos < self.s.len() { Some(self.s.as_bytes()[self.pos] as char) } else { None }
    }
    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() { self.pos += 1; }
        c
    }
    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Ok(Value::String(self.parse_string()?)),
            Some('t') => { self.pos += 4; Ok(Value::Bool(true)) }
            Some('f') => { self.pos += 5; Ok(Value::Bool(false)) }
            Some('n') => { self.pos += 4; Ok(Value::Null) }
            Some(c) if c.is_ascii_digit() || c == '-' => Ok(Value::Number(self.parse_number()?)),
            Some(c) => Err(format!("unexpected {}", c)),
            None => Err("eof".into()),
        }
    }
    fn parse_object(&mut self) -> Result<Value, String> {
        self.next(); // {
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == Some('}') { self.next(); return Ok(Value::Object(map)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.next() != Some(':') { return Err("colon".into()); }
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.next(); }
                Some('}') => { self.next(); break; }
                _ => return Err("object sep".into()),
            }
        }
        Ok(Value::Object(map))
    }
    fn parse_array(&mut self) -> Result<Value, String> {
        self.next(); // [
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(']') { self.next(); return Ok(Value::Array(arr)); }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(',') => { self.next(); }
                Some(']') => { self.next(); break; }
                _ => return Err("array sep".into()),
            }
        }
        Ok(Value::Array(arr))
    }
    fn parse_string(&mut self) -> Result<String, String> {
        if self.next() != Some('"') { return Err("string".into()); }
        let mut out = String::new();
        while let Some(c) = self.next() {
            match c {
                '"' => return Ok(out),
                '\\' => {
                    let esc = self.next().ok_or("esc")?;
                    match esc {
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        '/' => out.push('/'),
                        'b' => out.push('\x08'),
                        'f' => out.push('\x0c'),
                        'n' => out.push('\n'),
                        'r' => out.push('\r'),
                        't' => out.push('\t'),
                        'u' => {
                            let hex: String = (0..4).map(|_| self.next().ok_or("u")? ).collect();
                            if let Ok(cp) = u32::from_str_radix(&hex, 16) {
                                if let Some(ch) = char::from_u32(cp) { out.push(ch); }
                            }
                        }
                        _ => out.push(esc),
                    }
                }
                _ => out.push(c),
            }
        }
        Err("unterminated".into())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let start = self.pos;
        while self.pos < self.s.len() {
            let c = self.s.as_bytes()[self.pos] as char;
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else { break; }
        }
        let num: f64 = self.s[start..self.pos].parse().map_err(|_| "num")?;
        Ok(num)
    }
}

fn escape_json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}
fn escape_output(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out
}

fn parse_url(base_url: &str) -> (String, u16, String) {
    let url = base_url.strip_prefix("http://").unwrap_or(base_url);
    let mut parts = url.splitn(2, '/');
    let hostport = parts.next().unwrap();
    let path = format!("/{}", parts.next().unwrap_or(""));
    let mut hp = hostport.splitn(2, ':');
    let host = hp.next().unwrap().to_string();
    let port: u16 = hp.next().unwrap().parse().unwrap();
    (host, port, path)
}

fn send_request(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> Result<Vec<u8>, String> {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(addr).map_err(|e| e.to_string())?;
    let req = format!(
        "POST {path}/v1/messages HTTP/1.1\r\nHost: {host}:{port}\r\nx-api-key: {api_key}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        body.len(),
        body
    );
    stream.write_all(req.as_bytes()).map_err(|e| e.to_string())?;
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).map_err(|e| e.to_string())?;
    Ok(resp)
}

fn split_headers_body(resp: &[u8]) -> (&[u8], &[u8]) {
    if let Some(pos) = find_bytes(resp, b"\r\n\r\n") {
        let (h, b) = resp.split_at(pos + 4);
        (h, b)
    } else if let Some(pos) = find_bytes(resp, b"\n\n") {
        let (h, b) = resp.split_at(pos + 2);
        (h, b)
    } else { (resp, &[]) }
}
fn find_bytes(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

fn parse_status(resp: &[u8]) -> Result<u16, String> {
    let s = String::from_utf8_lossy(resp);
    let first = s.lines().next().unwrap_or("");
    let parts: Vec<&str> = first.split_whitespace().collect();
    if parts.len() >= 2 {
        parts[1].parse().map_err(|_| "status".into())
    } else { Err("status".into()) }
}

fn get_header(resp: &[u8], name: &str) -> Option<String> {
    let s = String::from_utf8_lossy(resp);
    for line in s.lines().skip(1) {
        if let Some(colon) = line.find(':') {
            let (k, v) = line.split_at(colon);
            if k.trim().eq_ignore_ascii_case(name) {
                return Some(v[1..].trim().to_string());
            }
        }
    }
    None
}

fn decode_chunked(body: &[u8]) -> Vec<u8> {
    let mut pos = 0;
    let mut out = Vec::new();
    while pos < body.len() {
        let line_end = if let Some(i) = find_bytes(&body[pos..], b"\r\n") { pos + i } else { break };
        let line = &body[pos..line_end];
        let size_str = line.split(';').next().unwrap().trim();
        if size_str.is_empty() { break; }
        let size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        pos = line_end + 2;
        if size == 0 { break; }
        let end = pos + size;
        if end > body.len() { break; }
        out.extend_from_slice(&body[pos..end]);
        pos = end;
        if body.get(pos..pos+2) == Some(b"\r\n") { pos += 2; }
    }
    out
}

#[derive(Default)]
struct Block {
    index: usize,
    btype: String,
    thinking: String,
    signature: String,
    text: String,
    tool_id: String,
    tool_name: String,
    tool_input_raw: String,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 { return; }
    let data_dir = &args[1];
    let base_url = &args[2];
    let req_file = format!("{}/request.json", data_dir);
    let req_json = fs::read_to_string(&req_file).unwrap();
    let mut parser = JsonParser::new(&req_json);
    let root = parser.parse_value().unwrap();
    let obj = match root { Value::Object(m) => m, _ => panic!() };
    let api_key = get_str(&obj, "api_key");
    let model = get_str(&obj, "model");
    let max_tokens = get_num(&obj, "max_tokens") as u64;
    let thinking_budget = get_num(&obj, "thinking_budget") as u64;
    let system = get_str(&obj, "system");
    let prompt = get_str(&obj, "prompt");
    let tools_raw = get_tools_raw(&req_json);

    let (host, port, path) = parse_url(base_url);

    let mut total_input = 0u64;
    let mut total_output = 0u64;
    let mut total_cache = 0u64;
    let mut first_blocks: Vec<Block> = Vec::new();
    let mut first_stop = String::new();

    // request 1
    let body1 = format!(
        "{{\"model\":{},\"max_tokens\":{},\"stream\":true,\"thinking\":{{\"type\":\"enabled\",\"budget_tokens\":{}}},\"system\":{},\"tools\":{},\"messages\":[{{\"role\":\"user\",\"content\":{}}}]}}",
        escape_json_string(&model),
        max_tokens,
        thinking_budget,
        escape_json_string(&system),
        tools_raw,
        escape_json_string(&prompt)
    );
    println!("request 1");
    let resp1 = send_request(&host, port, &path, &api_key, &body1).unwrap();
    let (hdr1, body1_raw) = split_headers_body(&resp1);
    let status1 = parse_status(hdr1).unwrap();
    if status1 != 200 {
        handle_error(hdr1, body1_raw);
        return;
    }
    process_stream(&body1_raw, &mut first_blocks, &mut first_stop, &mut total_input, &mut total_output, &mut total_cache);
    for b in first_blocks.iter().sorted_by_key(|b| b.index) {
        match b.btype.as_str() {
            "thinking" => {
                println!("thinking {}", escape_output(&b.thinking));
                println!("signature {}", escape_output(&b.signature));
            }
            "text" => println!("text {}", escape_output(&b.text)),
            "tool_use" => {
                println!("tool_use {} {} {}", b.tool_id, b.tool_name, escape_output(&b.tool_input_raw));
            }
            _ => {}
        }
    }
    println!("stop_reason {}", first_stop);

    // run tools
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();
    for b in &first_blocks {
        if b.btype == "tool_use" {
            let res = run_tool(&b.tool_name, &b.tool_input_raw);
            let is_err = is_tool_error(&b.tool_name, &res);
            if is_err { println!("error {} {}", b.tool_id, escape_output(&res)); }
            else { println!("result {} {}", b.tool_id, escape_output(&res)); }
            tool_results.push((b.tool_id.clone(), res, is_err));
        }
    }

    // request 2
    println!("request 2");
    let mut msgs = String::new();
    msgs.push_str(&format!("[{{\"role\":\"user\",\"content\":{}}}", escape_json_string(&prompt)));
    // assistant message
    msgs.push_str(",{\"role\":\"assistant\",\"content\":[");
    for (i, b) in first_blocks.iter().enumerate() {
        if i > 0 { msgs.push(','); }
        match b.btype.as_str() {
            "thinking" => {
                msgs.push_str(&format!("{{\"type\":\"thinking\",\"thinking\":{},\"signature\":{}}}", escape_json_string(&b.thinking), escape_json_string(&b.signature)));
            }
            "text" => {
                msgs.push_str(&format!("{{\"type\":\"text\",\"text\":{}}}", escape_json_string(&b.text)));
            }
            "tool_use" => {
                let input_obj = parse_tool_input_to_json(&b.tool_input_raw);
                msgs.push_str(&format!("{{\"type\":\"tool_use\",\"id\":{},\"name\":{},\"input\":{}}}", escape_json_string(&b.tool_id), escape_json_string(&b.tool_name), input_obj));
            }
            _ => {}
        }
    }
    msgs.push_str("]}");
    // user tool results
    msgs.push_str(",{\"role\":\"user\",\"content\":[");
    for (i, (id, res, is_err)) in tool_results.iter().enumerate() {
        if i > 0 { msgs.push(','); }
        let mut block = format!("{{\"type\":\"tool_result\",\"tool_use_id\":{},\"content\":{}}}", escape_json_string(id), escape_json_string(res));
        if *is_err { block.push_str(",\"is_error\":true"); }
        msgs.push_str(&block);
    }
    msgs.push_str("]}]");
    let body2 = format!(
        "{{\"model\":{},\"max_tokens\":{},\"stream\":true,\"thinking\":{{\"type\":\"enabled\",\"budget_tokens\":{}}},\"system\":{},\"tools\":{},\"messages\":{}}}",
        escape_json_string(&model),
        max_tokens,
        thinking_budget,
        escape_json_string(&system),
        tools_raw,
        msgs
    );
    let resp2 = send_request(&host, port, &path, &api_key, &body2).unwrap();
    let (hdr2, body2_raw) = split_headers_body(&resp2);
    let status2 = parse_status(hdr2).unwrap();
    if status2 != 200 {
        handle_error(hdr2, body2_raw);
        return;
    }
    let mut second_blocks: Vec<Block> = Vec::new();
    let mut second_stop = String::new();
    process_stream(&body2_raw, &mut second_blocks, &mut second_stop, &mut total_input, &mut total_output, &mut total_cache);
    for b in second_blocks.iter().sorted_by_key(|b| b.index) {
        match b.btype.as_str() {
            "thinking" => {
                println!("thinking {}", escape_output(&b.thinking));
                println!("signature {}", escape_output(&b.signature));
            }
            "text" => println!("text {}", escape_output(&b.text)),
            "tool_use" => {
                println!("tool_use {} {} {}", b.tool_id, b.tool_name, escape_output(&b.tool_input_raw));
            }
            _ => {}
        }
    }
    println!("stop_reason {}", second_stop);
    println!("usage input={} output={} cache_read={}", total_input, total_output, total_cache);
}

fn get_str(map: &HashMap<String, Value>, key: &str) -> String {
    if let Some(Value::String(s)) = map.get(key) { s.clone() } else { panic!() }
}
fn get_num(map: &HashMap<String, Value>, key: &str) -> f64 {
    if let Some(Value::Number(n)) = map.get(key) { *n } else { panic!() }
}
fn get_tools_raw(s: &str) -> String {
    if let Some(idx) = s.find("\"tools\"") {
        let rest = &s[idx..];
        if let Some(br) = rest.find('[') {
            let start = idx + br;
            let mut depth = 0;
            let mut i = start;
            let bytes = s.as_bytes();
            for ch in bytes[start..].iter() {
                if *ch == b'[' { depth += 1; }
                if *ch == b']' { depth -= 1; if depth == 0 { i = start + (bytes.len() - bytes.len())?; } }
                // simpler: find matching
            }
            // crude: find matching ]
            let mut d = 0;
            let mut end = start;
            for (i,ch) in s[start..].char_indices() {
                match ch {
                    '[' => d += 1,
                    ']' => { d -= 1; if d==0 { end = start + i + 1; break; } }
                    _ => {}
                }
            }
            return s[start..end].to_string();
        }
    }
    "[]".into()
}

fn process_stream(body: &[u8], blocks: &mut Vec<Block>, stop_reason: &mut String, total_input: &mut u64, total_output: &mut u64, total_cache: &mut u64) {
    let stream_bytes = decode_chunked(body);
    let text = String::from_utf8_lossy(&stream_bytes);
    let mut event_name = String::new();
    let mut data_buf = String::new();
    for line in text.split(|c| c == '\n') {
        let line = line.trim_end_matches('\r');
        if line.is_empty() {
            if !event_name.is_empty() && !data_buf.is_empty() {
                handle_event(&event_name, &data_buf, blocks, stop_reason, total_input, total_output, total_cache);
            }
            event_name.clear();
            data_buf.clear();
        } else if line.starts_with("event:") {
            event_name = line[6..].trim().to_string();
        } else if line.starts_with("data:") {
            let d = line[5..].trim_start().to_string();
            if !data_buf.is_empty() { data_buf.push('\n'); }
            data_buf.push_str(&d);
        }
    }
}

fn handle_event(event: &str, data: &str, blocks: &mut Vec<Block>, stop_reason: &mut String, total_input: &mut u64, total_output: &mut u64, total_cache: &mut u64) {
    if event == "ping" { return; }
    let mut parser = JsonParser::new(data);
    let val = match parser.parse_value() { Ok(v) => v, Err(_) => return };
    match event {
        "message_start" => {
            if let Value::Object(m) = val {
                if let Some(Value::Object(msg)) = m.get("message") {
                    if let Some(Value::Object(usage)) = msg.get("usage") {
                        if let Some(Value::Number(n)) = usage.get("input_tokens") { *total_input += n as u64; }
                        if let Some(Value::Number(n)) = usage.get("cache_read_input_tokens") { *total_cache += n as u64; }
                    }
                }
            }
        }
        "content_block_start" => {
            if let Value::Object(m) = val {
                if let Some(Value::Number(idx)) = m.get("index") {
                    if let Some(Value::Object(cb)) = m.get("content_block") {
                        let btype = if let Some(Value::String(t)) = cb.get("type") { t.clone() } else { "".into() };
                        let mut blk = Block { index: idx as usize, btype };
                        if btype == "tool_use" {
                            if let Some(Value::String(id)) = cb.get("id") { blk.tool_id = id; }
                            if let Some(Value::String(name)) = cb.get("name") { blk.tool_name = name; }
                        }
                        blocks.push(blk);
                    }
                }
            }
        }
        "content_block_delta" => {
            if let Value::Object(m) = val {
                if let Some(Value::Number(idx)) = m.get("index") {
                    if let Some(Value::Object(delta)) = m.get("delta") {
                        if let Some(Value::String(t)) = delta.get("type") {
                            if let Some(b) = blocks.iter_mut().find(|b| b.index == idx as usize) {
                                match t.as_str() {
                                    "thinking_delta" => { if let Some(Value::String(s)) = delta.get("thinking") { b.thinking.push_str(s); } }
                                    "signature_delta" => { if let Some(Value::String(s)) = delta.get("signature") { b.signature.push_str(s); } }
                                    "text_delta" => { if let Some(Value::String(s)) = delta.get("text") { b.text.push_str(s); } }
                                    "input_json_delta" => { if let Some(Value::String(s)) = delta.get("partial_json") { b.tool_input_raw.push_str(s); } }
                                    _ => {}
                                }
                            }
                        }
                    }
                }
            }
        }
        "message_delta" => {
            if let Value::Object(m) = val {
                if let Some(Value::Object(delta)) = m.get("delta") {
                    if let Some(Value::String(sr)) = delta.get("stop_reason") { *stop_reason = sr.clone(); }
                }
                if let Some(Value::Object(usage)) = m.get("usage") {
                    if let Some(Value::Number(n)) = usage.get("output_tokens") { *total_output += n as u64; }
                }
            }
        }
        _ => {}
    }
}

fn run_tool(name: &str, input_raw: &str) -> String {
    // parse input JSON object
    let mut parser = JsonParser::new(input_raw);
    let val = match parser.parse_value() { Ok(v) => v, Err(_) => return "parse error".into() };
    if let Value::Object(map) = val {
        match name {
            "measure" => {
                let text = get_str_from_map(&map, "text");
                let unit = get_str_from_map(&map, "unit");
                match unit.as_str() {
                    "code_points" => text.chars().count().to_string(),
                    "utf8_bytes" => text.as_bytes().len().to_string(),
                    "utf16_units" => text.encode_utf16().count().to_string(),
                    _ => format!("unsupported unit: {}", unit),
                }
            }
            "reverse" => {
                let text = get_str_from_map(&map, "text");
                text.chars().rev().collect()
            }
            _ => format!("unknown tool: {}", name),
        }
    } else { "invalid".into() }
}
fn get_str_from_map(map: &HashMap<String, Value>, key: &str) -> String {
    if let Some(Value::String(s)) = map.get(key) { s.clone() } else { "".into() }
}
fn is_tool_error(name: &str, res: &str) -> bool {
    name != "measure" || res.starts_with("unsupported unit") || name == "unknown"
}
fn parse_tool_input_to_json(raw: &str) -> String {
    // raw is already JSON object text, return as is
    raw.to_string()
}
fn handle_error(hdr: &[u8], body: &[u8]) {
    // print nothing? spec says print lines produced so far then ERROR...
    // we already printed some lines, now print error
    let len = get_header(hdr, "Content-Length").and_then(|s| s.parse::<usize>().ok()).unwrap_or(0);
    let body_slice = &body[..len.min(body.len())];
    let s = String::from_utf8_lossy(body_slice);
    // parse error
    let mut parser = JsonParser::new(&s);
    if let Ok(Value::Object(m)) = parser.parse_value() {
        if let Some(Value::Object(err)) = m.get("error") {
            let typ = if let Some(Value::String(t)) = err.get("type") { t } else { "".into() };
            let msg = if let Some(Value::String(mes)) = err.get("message") { mes } else { "".into() };
            println!("ERROR 400 {}: {}", typ, msg);
        }
    }
}
trait SortedByKeyExt<T> {
    fn sorted_by_key<K, F: Fn(&T)->K>(&self, f: F) -> Vec<T> where K: Ord;
}
impl<T: Clone> SortedByKeyExt<T> for Vec<T> {
    fn sorted_by_key<K, F: Fn(&T)->K>(&self, f: F) -> Vec<T> where K: Ord {
        let mut v = self.clone();
        v.sort_by_key(|x| f(x));
        v
    }
}

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}
impl<'a> Parser<'a> {
    fn new(s: &'a [u8]) -> Self { Self { s, pos: 0 } }
    fn peek(&self) -> Option<u8> { self.s.get(self.pos).copied() }
    fn next(&mut self) -> Option<u8> { let c = self.peek(); if c.is_some(){self.pos+=1;} c }
    fn skip_ws(&mut self) { while matches!(self.peek(), Some(b' ')|Some(b'\n')|Some(b'\r')|Some(b'\t')) {self.pos+=1;} }
    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(JsonValue::String(self.parse_string()?)),
            Some(b't') => {self.pos+=4; Ok(JsonValue::Bool(true))},
            Some(b'f') => {self.pos+=5; Ok(JsonValue::Bool(false))},
            Some(b'n') => {self.pos+=4; Ok(JsonValue::Null)},
            Some(c) if c.is_ascii_digit() || c=='-' => Ok(JsonValue::Number(self.parse_number()?)),
            _ => Err(())
        }
    }
    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        self.next(); // {
        let mut v = Vec::new();
        self.skip_ws();
        if self.peek()==Some(b'}') {self.next(); return Ok(JsonValue::Object(v));}
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.next()!=Some(b':') {return Err(());}
            let val = self.parse_value()?;
            v.push((key,val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => {self.next();},
                Some(b'}') => {self.next(); break;},
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Object(v))
    }
    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        self.next(); // [
        let mut v = Vec::new();
        self.skip_ws();
        if self.peek()==Some(b']') {self.next(); return Ok(JsonValue::Array(v));}
        loop {
            v.push(self.parse_value()?);
            self.skip_ws();
            match self.peek() {
                Some(b',') => {self.next();},
                Some(b']') => {self.next(); break;},
                _ => return Err(()),
            }
        }
        Ok(JsonValue::Array(v))
    }
    fn parse_string(&mut self) -> Result<String, ()> {
        if self.next()!=Some(b'"') {return Err(());}
        let mut out = String::new();
        while let Some(c)=self.next() {
            match c {
                b'"' => return Ok(out),
                b'\\' => {
                    let esc = self.next().ok_or(())?;
                    match esc {
                        b'"' => out.push('"'),
                        b'\\'=> out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\x08'),
                        b'f' => out.push('\x0c'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            let mut hex = [0u8;4];
                            for i in 0..4 { hex[i]=self.next().ok_or(())?; }
                            let s = std::str::from_utf8(&hex).map_err(|_|())?;
                            if let Ok(cp)=u32::from_str_radix(s,16) {
                                if let Some(ch)=char::from_u32(cp){out.push(ch);}
                            }
                        }
                        _ => out.push(esc as char),
                    }
                }
                _ => out.push(c as char),
            }
        }
        Err(())
    }
    fn parse_number(&mut self) -> Result<f64, ()> {
        let start=self.pos;
        while let Some(c)=self.peek() {
            if c.is_ascii_digit() || b"-+eE.".contains(&c) {self.pos+=1;} else {break;}
        }
        let s = std::str::from_utf8(&self.s[start..self.pos]).map_err(|_|())?;
        s.parse::<f64>().map_err(|_|())
    }
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}
fn escape_output(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out
}

fn parse_url(base_url: &str) -> (String, u16, String) {
    let url = base_url.strip_prefix("http://").unwrap_or(base_url);
    let mut split = url.splitn(2, '/');
    let hostport = split.next().unwrap();
    let rest = split.next().unwrap_or("");
    let path = format!("/{}/v1/messages", rest);
    let mut hp = hostport.splitn(2, ':');
    let host = hp.next().unwrap().to_string();
    let port: u16 = hp.next().unwrap().parse().unwrap();
    (host, port, path)
}

fn send_request(host:&str, port:u16, path:&str, api_key:&str, body:&str) -> Result<Vec<u8>, String> {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(addr).map_err(|e| e.to_string())?;
    let req = format!(
        "POST {path} HTTP/1.1\r\nHost: {host}:{port}\r\nx-api-key: {api_key}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        body.len(), body
    );
    stream.write_all(req.as_bytes()).map_err(|e| e.to_string())?;
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).map_err(|e| e.to_string())?;
    Ok(resp)
}

fn split_headers_body(resp:&[u8]) -> (&[u8], &[u8]) {
    if let Some(i)=find_bytes(resp,b"\r\n\r\n"){ let (h,b)=resp.split_at(i+4); (h,b) }
    else if let Some(i)=find_bytes(resp,b"\n\n"){ let (h,b)=resp.split_at(i+2); (h,b) }
    else {(resp,&[])}
}
fn find_bytes(hay:&[u8], needle:&[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w==needle)
}
fn parse_status(resp:&[u8]) -> Result<u16,String> {
    let s = String::from_utf8_lossy(resp);
    let first = s.lines().next().unwrap_or("");
    let mut it = first.split_whitespace();
    it.next();
    if let Some(code)=it.next(){ code.parse().map_err(|_|"status".into()) } else {Err("status".into())}
}
fn get_header(resp:&[u8], name:&str)->Option<String>{
    let s = String::from_utf8_lossy(resp);
    for line in s.lines().skip(1){
        if let Some(col)=line.find(':'){
            let (k,v)=line.split_at(col);
            if k.trim().eq_ignore_ascii_case(name){ return Some(v[1..].trim().to_string()); }
        }
    }
    None
}
fn decode_chunked(data:&[u8])->Vec<u8>{
    let mut pos=0;
    let mut out=Vec::new();
    while pos<data.len(){
        let line_end = if let Some(i)=find_bytes(&data[pos..],b"\r\n"){pos+i} else {break};
        let line=&data[pos..line_end];
        let size_str=line.split(|b|b==b';').next().unwrap();
        let size=usize::from_str_radix(str::from_utf8(size_str).unwrap().trim(),16).unwrap_or(0);
        pos=line_end+2;
        if size==0 {break;}
        if pos+size>data.len(){break;}
        out.extend_from_slice(&data[pos..pos+size]);
        pos+=size;
        if data.get(pos..pos+2)==Some(b"\r\n"){pos+=2;}
    }
    out
}

#[derive(Default)]
struct Block {
    index: usize,
    btype: String,
    thinking: String,
    signature: String,
    text: String,
    tool_id: String,
    tool_name: String,
    tool_input_raw: String,
}

fn main(){
    let args:Vec<String>=env::args().collect();
    if args.len()!=3 {return;}
    let data_dir=&args[1];
    let base_url=&args[2];
    let req_file=format!("{}/request.json",data_dir);
    let req_json=fs::read_to_string(&req_file).unwrap();
    let tools_raw=extract_tools_raw(&req_json);
    let mut parser=Parser::new(req_json.as_bytes());
    let root=parser.parse_value().unwrap();
    let JsonValue::Object(map)=root else {panic!()};
    let api_key=get_str(&map,"api_key");
    let model=get_str(&map,"model");
    let max_tokens=get_num(&map,"max_tokens") as u64;
    let thinking_budget=get_num(&map,"thinking_budget") as u64;
    let system=get_str(&map,"system");
    let prompt=get_str(&map,"prompt");

    let (host,port,path)=parse_url(base_url);

    let mut total_input=0u64;
    let mut total_output=0u64;
    let mut total_cache=0u64;

    // request 1
    let body1=format!(
        "{{\"model\":{},\"max_tokens\":{},\"stream\":true,\"thinking\":{{\"type\":\"enabled\",\"budget_tokens\":{}}},\"system\":{},\"tools\":{},\"messages\":[{{\"role\":\"user\",\"content\":{}}}]}}",
        json_escape(&model), max_tokens, thinking_budget, json_escape(&system), tools_raw, json_escape(&prompt)
    );
    println!("request 1");
    let resp1=send_request(&host,port,&path,&api_key,&body1).unwrap();
    let (hdr1,body1_raw)=split_headers_body(&resp1);
    let status1=parse_status(hdr1).unwrap();
    if status1!=200 { handle_error(hdr1,body1_raw,status1); return; }
    let mut first_blocks=Vec::new();
    let mut first_stop=String::new();
    process_stream(&body1_raw,&mut first_blocks,&mut first_stop,&mut total_input,&mut total_output,&mut total_cache);
    print_blocks(&first_blocks,&mut first_stop);
    // tools
    let mut tool_results=Vec::new();
    for b in &first_blocks {
        if b.btype=="tool_use" {
            let res=run_tool(&b.tool_name,&b.tool_input_raw);
            let is_err=tool_is_error(&b.tool_name,&res);
            if is_err { println!("error {} {}",b.tool_id,escape_output(&res)); }
            else { println!("result {} {}",b.tool_id,escape_output(&res)); }
            tool_results.push((b.tool_id.clone(),res,is_err));
        }
    }
    // request 2
    println!("request 2");
    let mut msgs=String::new();
    msgs.push_str(&format!("[{{\"role\":\"user\",\"content\":{}}}",json_escape(&prompt)));
    msgs.push_str(",{\"role\":\"assistant\",\"content\":[");
    for (i,b) in first_blocks.iter().enumerate(){
        if i>0 {msgs.push(',');}
        match b.btype.as_str(){
            "thinking"=>{ msgs.push_str(&format!("{{\"type\":\"thinking\",\"thinking\":{},\"signature\":{}}}",json_escape(&b.thinking),json_escape(&b.signature))); }
            "text"=>{ msgs.push_str(&format!("{{\"type\":\"text\",\"text\":{}}}",json_escape(&b.text))); }
            "tool_use"=>{ msgs.push_str(&format!("{{\"type\":\"tool_use\",\"id\":{},\"name\":{},\"input\":{}}}",json_escape(&b.tool_id),json_escape(&b.tool_name),b.tool_input_raw)); }
            _=>{}
        }
    }
    msgs.push_str("]}");
    msgs.push_str(",{\"role\":\"user\",\"content\":[");
    for (i,(id,res,is_err)) in tool_results.iter().enumerate(){
        if i>0 {msgs.push(',');}
        let mut blk=format!("{{\"type\":\"tool_result\",\"tool_use_id\":{},\"content\":{}}}",json_escape(id),json_escape(res));
        if *is_err {blk.push_str(",\"is_error\":true");}
        msgs.push_str(&blk);
    }
    msgs.push_str("]}]");
    let body2=format!(
        "{{\"model\":{},\"max_tokens\":{},\"stream\":true,\"thinking\":{{\"type\":\"enabled\",\"budget_tokens\":{}}},\"system\":{},\"tools\":{},\"messages\":{}}}",
        json_escape(&model), max_tokens, thinking_budget, json_escape(&system), tools_raw, msgs
    );
    let resp2=send_request(&host,port,&path,&api_key,&body2).unwrap();
    let (hdr2,body2_raw)=split_headers_body(&resp2);
    let status2=parse_status(hdr2).unwrap();
    if status2!=200 { handle_error(hdr2,body2_raw,status2); return; }
    let mut second_blocks=Vec::new();
    let mut second_stop=String::new();
    process_stream(&body2_raw,&mut second_blocks,&mut second_stop,&mut total_input,&mut total_output,&mut total_cache);
    print_blocks(&second_blocks,&mut second_stop);
    println!("usage input={} output={} cache_read={}",total_input,total_output,total_cache);
}

fn get_str(map:&Vec<(String,JsonValue)>, key:&str)->String{
    for (k,v) in map { if k==key { if let JsonValue::String(s)=v {return s;} } }
    panic!()
}
fn get_num(map:&Vec<(String,JsonValue)>, key:&str)->f64{
    for (k,v) in map { if k==key { if let JsonValue::Number(n)=v {return *n;} } }
    panic!()
}
fn extract_tools_raw(s:&str)->String{
    if let Some(idx)=s.find("\"tools\"") {
        let rest=&s[idx..];
        if let Some(br)=rest.find('['){
            let start=idx+br;
            let mut depth=0;
            for (i,ch) in s[start..].char_indices(){
                match ch { '['=>depth+=1, ']'=>{depth-=1; if depth==0 {return s[start..start+i+1].to_string();}}, _=>{} }
            }
        }
    }
    "[]".into()
}
fn process_stream(body:&[u8], blocks:&mut Vec<Block>, stop_reason:&mut String, total_input:&mut u64, total_output:&mut u64, total_cache:&mut u64){
    let decoded=decode_chunked(body);
    let text=String::from_utf8_lossy(&decoded);
    let mut event_name=String::new();
    let mut data_buf=String::new();
    for line in text.split(|c|c=='\n'){
        let line=line.trim_end_matches('\r');
        if line.is_empty(){
            if !event_name.is_empty() && !data_buf.is_empty(){
                handle_event(&event_name,&data_buf,blocks,stop_reason,total_input,total_output,total_cache);
            }
            event_name.clear(); data_buf.clear();
        } else if line.starts_with("event:"){
            event_name=line[6..].trim().to_string();
        } else if line.starts_with("data:"){
            let d=line[5..].trim_start().to_string();
            if !data_buf.is_empty(){data_buf.push('\n');}
            data_buf.push_str(&d);
        }
    }
}
fn handle_event(event:&str, data:&str, blocks:&mut Vec<Block>, stop_reason:&mut String, total_input:&mut u64, total_output:&mut u64, total_cache:&mut u64){
    if event=="ping" {return;}
    let mut p=Parser::new(data.as_bytes());
    let val=match p.parse_value(){Ok(v)=>v, Err(_)=>return};
    match event{
        "message_start"=> {
            if let JsonValue::Object(m)=val {
                for (k,v) in &m { if k=="message" { if let JsonValue::Object(msg)=v {
                    for (k2,v2) in msg { if k2=="usage" { if let JsonValue::Object(u)=v2 {
                        for (k3,v3) in u {
                            if k3=="input_tokens" { if let JsonValue::Number(n)=v3 {*total_input+=n as u64;} }
                            if k3=="cache_read_input_tokens" { if let JsonValue::Number(n)=v3 {*total_cache+=n as u64;} }
                        }
                    } }
                } } }
            }
        },
        "content_block_start"=> {
            if let JsonValue::Object(m)=val {
                let mut idx=0usize; let mut btype="".to_string();
                let mut tool_id="".to_string(); let mut tool_name="".to_string();
                for (k,v) in &m {
                    if k=="index" { if let JsonValue::Number(n)=v {idx=n as usize;} }
                    if k=="content_block" { if let JsonValue::Object(cb)=v {
                        for (k2,v2) in cb {
                            if k2=="type" { if let JsonValue::String(s)=v2 {btype=s.clone();} }
                            if k2=="id" { if let JsonValue::String(s)=v2 {tool_id=s.clone();} }
                            if k2=="name" { if let JsonValue::String(s)=v2 {tool_name=s.clone();} }
                        }
                    } }
                }
                blocks.push(Block{index:idx,btype,tool_id,tool_name, ..Default::default()});
            }
        },
        "content_block_delta"=> {
            if let JsonValue::Object(m)=val {
                let mut idx=0usize; let mut d_type="".to_string(); let mut d_val=String::new();
                for (k,v) in &m {
                    if k=="index" { if let JsonValue::Number(n)=v {idx=n as usize;} }
                    if k=="delta" { if let JsonValue::Object(d)=v {
                        for (k2,v2) in d {
                            if k2=="type" { if let JsonValue::String(s)=v2 {d_type=s.clone();} }
                            if d_type=="thinking_delta" || d_type=="signature_delta" || d_type=="text_delta" || d_type=="input_json_delta" {}
                        }
                        for (k2,v2) in d {
                            if k2=="thinking" { if let JsonValue::String(s)=v2 {d_val=s.clone();} }
                            if k2=="signature" { if let JsonValue::String(s)=v2 {d_val=s.clone();} }
                            if k2=="text" { if let JsonValue::String(s)=v2 {d_val=s.clone();} }
                            if k2=="partial_json" { if let JsonValue::String(s)=v2 {d_val=s.clone();} }
                        }
                    } }
                }
                if let Some(b)=blocks.iter_mut().find(|b|b.index==idx){
                    match d_type.as_str(){
                        "thinking_delta"=> b.thinking.push_str(&d_val),
                        "signature_delta"=> b.signature.push_str(&d_val),
                        "text_delta"=> b.text.push_str(&d_val),
                        "input_json_delta"=> b.tool_input_raw.push_str(&d_val),
                        _=>{}
                    }
                }
            }
        },
        "message_delta"=> {
            if let JsonValue::Object(m)=val {
                for (k,v) in &m {
                    if k=="delta" { if let JsonValue::Object(d)=v {
                        for (k2,v2) in d { if k2=="stop_reason" { if let JsonValue::String(s)=v2 {*stop_reason=s.clone();} } }
                    } }
                    if k=="usage" { if let JsonValue::Object(u)=v {
                        for (k2,v2) in u { if k2=="output_tokens" { if let JsonValue::Number(n)=v2 {*total_output+=n as u64;} } }
                    } }
                }
            }
        },
        _=>{}
    }
}
fn print_blocks(blocks:&Vec<Block>, stop_reason:&mut String){
    let mut sorted=blocks.clone();
    sorted.sort_by_key(|b|b.index);
    for b in &sorted {
        match b.btype.as_str(){
            "thinking"=>{ println!("thinking {}",escape_output(&b.thinking)); println!("signature {}",escape_output(&b.signature)); }
            "text"=>{ println!("text {}",escape_output(&b.text)); }
            "tool_use"=>{ println!("tool_use {} {} {}",b.tool_id,b.tool_name,escape_output(&b.tool_input_raw)); }
            _=>{}
        }
    }
    println!("stop_reason {}",stop_reason);
}
fn run_tool(name:&str, input_raw:&str)->String{
    let mut p=Parser::new(input_raw.as_bytes());
    let val=match p.parse_value(){Ok(v)=>v, Err(_)=>return "parse error".into()};
    if let JsonValue::Object(map)=val {
        let mut text="".to_string(); let mut unit="".to_string();
        for (k,v) in &map {
            if k=="text" { if let JsonValue::String(s)=v {text=s.clone();} }
            if k=="unit" { if let JsonValue::String(s)=v {unit=s.clone();} }
        }
        match name {
            "measure"=> match unit.as_str(){
                "code_points"=> text.chars().count().to_string(),
                "utf8_bytes"=> text.as_bytes().len().to_string(),
                "utf16_units"=> text.encode_utf16().count().to_string(),
                _=> format!("unsupported unit: {}",unit),
            },
            "reverse"=> text.chars().rev().collect(),
            _=> format!("unknown tool: {}",name),
        }
    } else { "invalid".into() }
}
fn tool_is_error(name:&str, res:&str)->bool{
    if name=="measure" && res.starts_with("unsupported unit") {true} else if name!="measure" && name!="reverse" {true} else {false}
}
fn handle_error(hdr:&[u8], body:&[u8], status:u16){
    if let Some(len_str)=get_header(hdr,"Content-Length"){ if let Ok(len)=len_str.parse::<usize>() {
        let slice=&body[..len.min(body.len())];
        let mut p=Parser::new(slice);
        if let Ok(JsonValue::Object(m))=p.parse_value(){
            for (k,v) in &m { if k=="error" { if let JsonValue::Object(e)=v {
                let mut typ=""; let mut msg="";
                for (k2,v2) in e {
                    if k2=="type" { if let JsonValue::String(s)=v2 {typ=s; } }
                    if k2=="message" { if let JsonValue::String(s)=v2 {msg=s; } }
                }
                println!("ERROR {} {}: {}",status,typ,msg);
                return;
            } } }
        }
    } }
    println!("ERROR {} unknown",status);
}

use std::env;
use std::fs;

#[derive(Clone)]
enum Node {
    Alt(Vec<Node>),
    Seq(Vec<Node>),
    Group { id: Option<usize>, node: Box<Node> },
    Atom(AtomKind),
    Quant { node: Box<Node>, min: usize, max: Option<usize>, greedy: bool },
}

#[derive(Clone)]
enum AtomKind {
    Lit(u8),
    Dot,
    Start,
    End,
    Class(ClassMatcher),
    Escape(EscapeKind),
}

#[derive(Clone)]
enum EscapeKind {
    Digit,
    Word,
    Space,
    NotDigit,
    NotWord,
    NotSpace,
    Lit(u8),
}

#[derive(Clone)]
enum ClassItem {
    Char(u8),
    Range(u8, u8),
    Escape(EscapeKind),
}
#[derive(Clone)]
struct ClassMatcher {
    neg: bool,
    items: Vec<ClassItem>,
}

struct Parser {
    s: Vec<char>,
    pos: usize,
    next_id: usize,
}
impl Parser {
    fn new(pat: &str) -> Self {
        Self { s: pat.chars().collect(), pos: 0, next_id: 1 }
    }
    fn peek(&self) -> Option<char> { self.s.get(self.pos).copied() }
    fn next(&mut self) -> Option<char> { let c = self.s.get(self.pos).copied(); if c.is_some(){self.pos+=1}; c }
    fn parse_regex(&mut self) -> Node { let first = self.parse_branch(); let mut branches = vec![first]; while self.peek()==Some('|') { self.pos+=1; branches.push(self.parse_branch()); } if branches.len()==1 { branches.remove(0) } else { Node::Alt(branches) } }
    fn parse_branch(&mut self) -> Node {
        let mut pieces = Vec::new();
        while let Some(c)=self.peek() {
            if c=='|' || c==')' { break; }
            pieces.push(self.parse_piece());
        }
        if pieces.is_empty() { return Node::Seq(vec![]); }
        if pieces.len()==1 { pieces.remove(0) } else { Node::Seq(pieces) }
    }
    fn parse_piece(&mut self) -> Node {
        let atom = self.parse_atom();
        if let Some(q)=self.parse_quantifier() { Node::Quant{node:Box::new(atom),min:q.min,max:q.max,greedy:q.greedy} } else { atom }
    }
    fn parse_atom(&mut self) -> Node {
        match self.peek() {
            Some('(') => { self.pos+=1; let capturing=! (self.s.get(self.pos)==Some(&'?') && self.s.get(self.pos+1)==Some(&':')); if !capturing { self.pos+=2; } let inner=self.parse_regex(); assert_eq!(self.peek(),Some(')')); self.pos+=1; if capturing { let id=self.next_id; self.next_id+=1; Node::Group{id:Some(id),node:Box::new(inner)} } else { Node::Group{id:None,node:Box::new(inner)} } }
            Some('.') => { self.pos+=1; Node::Atom(AtomKind::Dot) }
            Some('^') => { self.pos+=1; Node::Atom(AtomKind::Start) }
            Some('$') => { self.pos+=1; Node::Atom(AtomKind::End) }
            Some('[') => { self.pos+=1; let neg=self.peek()==Some('^'); if neg { self.pos+=1; } let start=self.pos; while self.peek()!=Some(']') { self.pos+=1; } let content=self.s[start..self.pos].iter().collect::<String>(); self.pos+=1; let items=self.parse_class_items(&content); Node::Atom(AtomKind::Class(ClassMatcher{neg,items})) }
            Some('\\') => { self.pos+=1; let c=self.next().unwrap(); let kind=self.class_escape_to_kind(c); Node::Atom(AtomKind::Escape(kind)) }
            Some(c) => { self.pos+=1; if "[](){}*+?|^$.\\".contains(c) { panic!("unexpected literal"); } Node::Atom(AtomKind::Lit(c as u8)) }
            None => panic!("unexpected end"),
        }
    }
    fn class_escape_to_kind(&self, c: char) -> EscapeKind {
        match c {
            'd'=>EscapeKind::Digit,'w'=>EscapeKind::Word,'s'=>EscapeKind::Space,
            'D'=>EscapeKind::NotDigit,'W'=>EscapeKind::NotWord,'S'=>EscapeKind::NotSpace,
            _=>EscapeKind::Lit(c as u8),
        }
    }
    fn parse_class_items(&self, content:&str)->Vec<ClassItem>{
        let chars:Vec<char>=content.chars().collect();
        let mut items=Vec::new();
        let mut i=0;
        while i<chars.len(){
            if chars[i]=='\\' {
                let esc=chars[i+1];
                items.push(ClassItem::Escape(self.class_escape_to_kind(esc)));
                i+=2;
            } else if i+2<chars.len() && chars[i+1]=='-' {
                let start=chars[i] as u8;
                let end=chars[i+2] as u8;
                items.push(ClassItem::Range(start,end));
                i+=3;
            } else {
                items.push(ClassItem::Char(chars[i] as u8));
                i+=1;
            }
        }
        items
    }
    fn parse_quantifier(&mut self)->Option<QuantInfo>{
        match self.peek() {
            Some('*')=>{ self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} Some(QuantInfo{min:0,max:None,greedy}) }
            Some('+')=>{ self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} Some(QuantInfo{min:1,max:None,greedy}) }
            Some('?')=>{ self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} Some(QuantInfo{min:0,max:Some(1),greedy}) }
            Some('{')=>{ self.pos+=1; let start=self.pos; while self.peek()!=Some('}') { self.pos+=1; } let inside=self.s[start..self.pos].iter().collect::<String>(); self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} let (min,max)=parse_quant_braces(&inside); Some(QuantInfo{min,max,greedy}) }
            _=>None
        }
    }
}
struct QuantInfo{ min:usize, max:Option<usize>, greedy:bool }
fn parse_quant_braces(s:&str)->(usize,Option<usize>){
    let parts:s.split(',').collect::<Vec<&str>>();
    let m=parts[0].parse::<usize>().unwrap();
    if parts.len()==1 { (m,Some(m)) }
    else if parts[1].is_empty() { (m,None) }
    else { let n=parts[1].parse::<usize>().unwrap(); (m,Some(n)) }
}

fn expand_quant(node:Node)->Node{
    match node {
        Node::Quant{node:inner,min,max,greedy}=>{
            let inner_e=expand_quant(*inner);
            let max_val=max.unwrap_or(80);
            let mut counts=(min..=max_val).collect::<Vec<_>>();
            if greedy { counts.sort_by(|a,b|b.cmp(a)); } else { counts.sort_by(|a,b|a.cmp(b)); }
            let branches=counts.into_iter().map(|r|{
                if r==0 { Node::Seq(vec![]) } else {
                    let mut v=Vec::new();
                    for _ in 0..r { v.push(inner_e.clone()); }
                    Node::Seq(v)
                }
            }).collect::<Vec<_>>();
            if branches.len()==1 { branches.into(0) } else { Node::Alt(branches) }
        }
        Node::Alt(v)=>Node::Alt(v.into_iter().map(expand_quant).collect()),
        Node::Seq(v)=>Node::Seq(v.into_iter().map(expand_quant).collect()),
        Node::Group{id,node}=>Node::Group{id,node:Box::new(expand_quant(*node))},
        other=>other,
    }
}
fn expand_quant_vec(mut n:Node)->Node{ n=expand_quant(n); n }

fn match_class(c:u8, cm:&ClassMatcher)->bool{
    let mut hit=false;
    for it in &cm.items {
        match it {
            ClassItem::Char(ch)=> if c==*ch {hit=true;}
            ClassItem::Range(a,b)=> if c>=*a && c<=*b {hit=true;}
            ClassItem::Escape(e)=> if escape_matches(c,e) {hit=true;}
        }
    }
    if cm.neg { !hit } else { hit }
}
fn escape_matches(c:u8, e:&EscapeKind)->bool{
    match e {
        EscapeKind::Digit=>c>=b'0'&&c<=b'9',
        EscapeKind::Word=>c.is_ascii_alphanumeric()||c==b'_',
        EscapeKind::Space=>matches!(c,b' '|b'\t'|b'\n'|b'\r'|b'\x0c'|b'\x0b'),
        EscapeKind::NotDigit=>!(c>=b'0'&&c<=b'9'),
        EscapeKind::NotWord=>!(c.is_ascii_alphanumeric()||c==b'_'),
        EscapeKind::NotSpace=>!matches!(c,b' '|b'\t'|b'\n'|b'\r'|b'\x0c'|b'\x0b'),
        EscapeKind::Lit(x)=>c==*x,
    }
}

fn match_atom(kind:&AtomKind, pos:usize, subj:&[u8])->Option<usize>{
    match kind {
        AtomKind::Lit(ch)=> if pos<subj.len() && subj[pos]==*ch {Some(pos+1)} else {None},
        AtomKind::Dot=> if pos<subj.len() {Some(pos+1)} else {None},
        AtomKind::Start=> if pos==0 {Some(pos)} else {None},
        AtomKind::End=> if pos==subj.len() {Some(pos)} else {None},
        AtomKind::Class(cm)=> if pos<subj.len() && match_class(subj[pos],cm) {Some(pos+1)} else {None},
        AtomKind::Escape(e)=> if pos<subj.len() && escape_matches(subj[pos],e) {Some(pos+1)} else {None},
    }
}

fn match_node(node:&Node, pos:usize, subj:&[u8], caps:Vec<Option<(usize,usize)>>)->Option<(usize,Vec<Option<(usize,usize)>>)>
{
    match node {
        Node::Alt(v)=> {
            for ch in v {
                if let Some(res)=match_node(ch,pos,subj,caps.clone()) { return Some(res); }
            }
            None
        }
        Node::Seq(v)=>{
            let mut cur_pos=pos;
            let mut cur_caps=caps;
            for ch in v {
                match match_node(ch,cur_pos,subj,cur_caps) {
                    Some((np,nc))=>{cur_pos=np;cur_caps=nc;},
                    None=>return None,
                }
            }
            Some((cur_pos,cur_caps))
        }
        Node::Group{id,node:inner}=>{
            let start=pos;
            if let Some((np,nc))=match_node(inner,pos,subj,caps) {
                let mut caps2=nc;
                if let Some(idv)=id {
                    if caps2.len()<=idv { caps2.resize(idv+1,None); }
                    caps2[idv]=Some((start,np));
                }
                Some((np,caps2))
            } else { None }
        }
        Node::Atom(k)=> {
            if let Some(np)=match_atom(k,pos,subj) { Some((np,caps)) } else { None }
        }
        Node::Quant{..}=>None,
    }
}

fn find_match(pattern:&str, subject:&str)->Option<(usize,usize,Vec<Option<(usize,usize)>>)>{
    let mut parser=Parser::new(pattern);
    let root=parser.parse_regex();
    let root=expand_quant_vec(root);
    let max_id=parser.next_id;
    let caps0=vec![None; max_id];
    let subj_bytes=subject.as_bytes();
    for start in 0..=subj_bytes.len() {
        if let Some((end,caps))=match_node(&root,start,subj_bytes,caps0.clone()) {
            return Some((start,end,caps));
        }
    }
    None
}

fn main(){
    let args:Vec<String>=env::args().collect();
    if args.len()<2 { return; }
    let dir=&args[1];
    let path=format!("{}/cases.txt",dir);
    let data=fs::read_to_string(&path).unwrap();
    for (i,line) in data.lines().enumerate() {
        if line.is_empty() { continue; }
        let mut parts=line.splitn(2,'\t');
        let pat=parts.next().unwrap_or("");
        let sub=parts.next().unwrap_or("");
        let n=i+1;
        match find_match(pat,sub) {
            None=>println!("{}: no match",n),
            Some((s,e,caps))=>{
                let mut out=format!("{}: {}-{}",n,s,e);
                for (idx,opt) in caps.iter().enumerate().skip(1) {
                    if let Some((a,b))=opt { out.push_str(&format!(" {}-{}",a,b)); } else { out.push_str(" -"); }
                }
                println!("{}",out);
            }
        }
    }
}

use std::env;
use std::fs;

#[derive(Clone)]
enum Node {
    Alt(Vec<Node>),
    Seq(Vec<Node>),
    Group { id: Option<usize>, node: Box<Node> },
    Atom(AtomKind),
    Quant { node: Box<Node>, min: usize, max: Option<usize>, greedy: bool },
}

#[derive(Clone)]
enum AtomKind {
    Lit(u8),
    Dot,
    Start,
    End,
    Class(ClassMatcher),
    Escape(EscapeKind),
}

#[derive(Clone)]
enum EscapeKind {
    Digit,
    Word,
    Space,
    NotDigit,
    NotWord,
    NotSpace,
    Lit(u8),
}

#[derive(Clone)]
enum ClassItem {
    Char(u8),
    Range(u8, u8),
    Escape(EscapeKind),
}
#[derive(Clone)]
struct ClassMatcher {
    neg: bool,
    items: Vec<ClassItem>,
}

struct Parser {
    s: Vec<char>,
    pos: usize,
    next_id: usize,
}
impl Parser {
    fn new(pat: &str) -> Self {
        Self { s: pat.chars().collect(), pos: 0, next_id: 1 }
    }
    fn peek(&self) -> Option<char> { self.s.get(self.pos).copied() }
    fn next(&mut self) -> Option<char> { let c = self.s.get(self.pos).copied(); if c.is_some(){self.pos+=1}; c }
    fn parse_regex(&mut self) -> Node {
        let first = self.parse_branch();
        let mut branches = vec![first];
        while self.peek()==Some('|') {
            self.pos+=1;
            branches.push(self.parse_branch());
        }
        if branches.len()==1 { branches.remove(0) } else { Node::Alt(branches) }
    }
    fn parse_branch(&mut self) -> Node {
        let mut pieces = Vec::new();
        while let Some(c)=self.peek() {
            if c=='|' || c==')' { break; }
            pieces.push(self.parse_piece());
        }
        if pieces.is_empty() { return Node::Seq(vec![]); }
        if pieces.len()==1 { pieces.remove(0) } else { Node::Seq(pieces) }
    }
    fn parse_piece(&mut self) -> Node {
        let atom = self.parse_atom();
        if let Some(q)=self.parse_quantifier() {
            Node::Quant{node:Box::new(atom),min:q.min,max:q.max,greedy:q.greedy}
        } else { atom }
    }
    fn parse_atom(&mut self) -> Node {
        match self.peek() {
            Some('(') => {
                self.pos+=1;
                let capturing=! (self.s.get(self.pos)==Some(&'?') && self.s.get(self.pos+1)==Some(&':'));
                if !capturing { self.pos+=2; }
                let inner=self.parse_regex();
                assert_eq!(self.peek(),Some(')'));
                self.pos+=1;
                if capturing {
                    let id=self.next_id; self.next_id+=1;
                    Node::Group{id:Some(id),node:Box::new(inner)}
                } else {
                    Node::Group{id:None,node:Box::new(inner)}
                }
            }
            Some('.') => { self.pos+=1; Node::Atom(AtomKind::Dot) }
            Some('^') => { self.pos+=1; Node::Atom(AtomKind::Start) }
            Some('$') => { self.pos+=1; Node::Atom(AtomKind::End) }
            Some('[') => {
                self.pos+=1;
                let neg=self.peek()==Some('^');
                if neg { self.pos+=1; }
                let start=self.pos;
                while self.peek()!=Some(']') { self.pos+=1; }
                let content=self.s[start..self.pos].iter().collect::<String>();
                self.pos+=1;
                let items=self.parse_class_items(&content);
                Node::Atom(AtomKind::Class(ClassMatcher{neg,items}))
            }
            Some('\\') => {
                self.pos+=1;
                let c=self.next().unwrap();
                let kind=self.class_escape_to_kind(c);
                Node::Atom(AtomKind::Escape(kind))
            }
            Some(c) => {
                self.pos+=1;
                if "[](){}*+?|^$.\\".contains(c) { panic!("unexpected literal"); }
                Node::Atom(AtomKind::Lit(c as u8))
            }
            None => panic!("unexpected end"),
        }
    }
    fn class_escape_to_kind(&self, c: char) -> EscapeKind {
        match c {
            'd'=>EscapeKind::Digit,'w'=>EscapeKind::Word,'s'=>EscapeKind::Space,
            'D'=>EscapeKind::NotDigit,'W'=>EscapeKind::NotWord,'S'=>EscapeKind::NotSpace,
            _=>EscapeKind::Lit(c as u8),
        }
    }
    fn parse_class_items(&self, content:&str)->Vec<ClassItem>{
        let chars:Vec<char>=content.chars().collect();
        let mut items=Vec::new();
        let mut i=0;
        while i<chars.len(){
            if chars[i]=='\\' {
                let esc=chars[i+1];
                items.push(ClassItem::Escape(self.class_escape_to_kind(esc)));
                i+=2;
            } else if i+2<chars.len() && chars[i+1]=='-' {
                let start=chars[i] as u8;
                let end=chars[i+2] as u8;
                items.push(ClassItem::Range(start,end));
                i+=3;
            } else {
                items.push(ClassItem::Char(chars[i] as u8));
                i+=1;
            }
        }
        items
    }
    fn parse_quantifier(&mut self)->Option<QuantInfo>{
        match self.peek() {
            Some('*')=>{ self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} Some(QuantInfo{min:0,max:None,greedy}) }
            Some('+')=>{ self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} Some(QuantInfo{min:1,max:None,greedy}) }
            Some('?')=>{ self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} Some(QuantInfo{min:0,max:Some(1),greedy}) }
            Some('{')=>{ self.pos+=1; let start=self.pos; while self.peek()!=Some('}') { self.pos+=1; } let inside=self.s[start..self.pos].iter().collect::<String>(); self.pos+=1; let greedy=self.peek()==Some('?'); if greedy {self.pos+=1;} let (min,max)=parse_quant_braces(&inside); Some(QuantInfo{min,max,greedy}) }
            _=>None
        }
    }
}
struct QuantInfo{ min:usize, max:Option<usize>, greedy:bool }
fn parse_quant_braces(s:&str)->(usize,Option<usize>){
    let parts: Vec<&str> = s.split(',').collect();
    let m=parts[0].parse::<usize>().unwrap();
    if parts.len()==1 { (m,Some(m)) }
    else if parts[1].is_empty() { (m,None) }
    else { let n=parts[1].parse::<usize>().unwrap(); (m,Some(n)) }
}

fn expand_quant(node:Node)->Node{
    match node {
        Node::Quant{node:inner,min,max,greedy}=>{
            let inner_e=expand_quant(*inner);
            let max_val=max.unwrap_or(80);
            let mut counts=(min..=max_val).collect::<Vec<_>>();
            if greedy { counts.sort_by(|a,b|b.cmp(a)); } else { counts.sort_by(|a,b|a.cmp(b)); }
            let branches=counts.into_iter().map(|r|{
                if r==0 { Node::Seq(vec![]) } else {
                    let mut v=Vec::new();
                    for _ in 0..r { v.push(inner_e.clone()); }
                    Node::Seq(v)
                }
            }).collect::<Vec<_>>();
            if branches.len()==1 { branches.into_iter().next().unwrap() } else { Node::Alt(branches) }
        }
        Node::Alt(v)=>Node::Alt(v.into_iter().map(expand_quant).collect()),
        Node::Seq(v)=>Node::Seq(v.into_iter().map(expand_quant).collect()),
        Node::Group{id,node}=>Node::Group{id,node:Box::new(expand_quant(*node))},
        other=>other,
    }
}
fn expand_quant_vec(n:Node)->Node{ expand_quant(n) }

