import java.io.*;
import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.util.*;

public class Main {

    static class PageInfo {
        int pageNo;
        byte[] data;
        int headerOffset;
    }

    public static void main(String[] args) throws Exception {
        if (args.length < 1) return;
        Path dbPath = Paths.get(args[0], "db.sqlite");
        try (RandomAccessFile raf = new RandomAccessFile(dbPath.toFile(), "r")) {
            FileChannel ch = raf.getChannel();
            long fileSize = ch.size();
            ByteBuffer head = ByteBuffer.allocate(100);
            ch.read(head, 0);
            head.flip();
            byte[] h = new byte[100];
            head.get(h);
            int pageSize = ((h[16] & 0xFF) << 8) | (h[17] & 0xFF);
            if (pageSize == 65534) pageSize = 65536;
            int reserved = h[18] & 0xFF;

            int totalPages = (int) (fileSize / pageSize);

            // read sqlite_schema
            List<TableMeta> tables = readSchema(ch, pageSize, totalPages, reserved);

            tables.sort(Comparator.comparing(t -> t.name));

            boolean firstTable = true;
            for (TableMeta tm : tables) {
                List<ColumnInfo> cols = parseColumns(tm.sql, tm.name);
                List<Row> rows = readTableRows(ch, pageSize, totalPages, reserved, tm.rootpage, cols);
                rows.sort(Comparator.comparingLong(r -> r.rowid));

                if (!firstTable) System.out.println();
                firstTable = false;
                System.out.println("TABLE " + tm.name + " rows=" + rows.size());
                System.out.print("COLUMNS ");
                for (int i = 0; i < cols.size(); i++) {
                    if (i > 0) System.out.print(", ");
                    System.out.print(cols.get(i).name);
                }
                System.out.println();
                for (Row r : rows) {
                    System.out.print(r.rowid + ": ");
                    for (int i = 0; i < cols.size(); i++) {
                        if (i > 0) System.out.print(", ");
                        Object v = r.values[i];
                        if (v == null) {
                            System.out.print("NULL");
                        } else if (v instanceof Long) {
                            System.out.print(v);
                        } else if (v instanceof Double) {
                            System.out.print(formatReal((Double) v));
                        } else if (v instanceof String) {
                            System.out.print(escapeText((String) v));
                        } else if (v instanceof byte[]) {
                            byte[] b = (byte[]) v;
                            if (b.length == 0) {
                                System.out.print("X''");
                            } else {
                                System.out.print("X'");
                                for (byte bb : b) System.out.printf("%02X", bb);
                                System.out.print("'");
                            }
                        } else if (v instanceof TextMeta) {
                            TextMeta tm2 = (TextMeta) v;
                            System.out.printf("<TEXT len=%d crc32=%08x>", tm2.len, tm2.crc);
                        } else if (v instanceof BlobMeta) {
                            BlobMeta bm = (BlobMeta) v;
                            System.out.printf("<BLOB len=%d crc32=%08x>", bm.len, bm.crc);
                        }
                    }
                    System.out.println();
                }
            }
        }
    }

    // ---------- schema ----------
    static class TableMeta {
        String type, name, tbl_name, sql;
        int rootpage;
    }

    static List<TableMeta> readSchema(FileChannel ch, int pageSize, int totalPages, int reserved) throws IOException {
        // sqlite_schema is rooted at page 1
        List<Row> rows = readTableRowsRaw(ch, pageSize, totalPages, reserved, 1,
                Arrays.asList("type","name","tbl_name","rootpage","sql"));
        List<TableMeta> out = new ArrayList<>();
        for (Row r : rows) {
            String type = (String) r.values[0];
            String name = (String) r.values[1];
            if (!"table".equals(type)) continue;
            if (name.startsWith("sqlite_")) continue;
            TableMeta tm = new TableMeta();
            tm.type = type;
            tm.name = name;
            tm.tbl_name = (String) r.values[2];
            tm.rootpage = ((Long) r.values[3]).intValue();
            tm.sql = (String) r.values[4];
            out.add(tm);
        }
        return out;
    }

    // ---------- table reading ----------
    static class ColumnInfo {
        String name;
        boolean rowidAlias;
    }

    static class Row {
        long rowid;
        Object[] values;
    }

    static List<ColumnInfo> parseColumns(String sql, String tableName) {
        // extract inside parentheses
        int l = sql.indexOf('(');
        int r = findMatchingParen(sql, l);
        String inside = sql.substring(l + 1, r);
        List<String> defs = splitDefs(inside);
        List<ColumnInfo> cols = new ArrayList<>();
        for (String d : defs) {
            String trimmed = d.trim();
            if (trimmed.isEmpty()) continue;
            // column name
            String colName;
            String rest;
            if (trimmed.startsWith("\"")) {
                int q2 = trimmed.indexOf('"', 1);
                colName = trimmed.substring(1, q2);
                rest = trimmed.substring(q2 + 1).trim();
            } else {
                int sp = 0;
                while (sp < trimmed.length() && !Character.isWhitespace(trimmed.charAt(sp))) sp++;
                colName = trimmed.substring(0, sp);
                rest = trimmed.substring(sp).trim();
            }
            boolean alias = false;
            if (!rest.isEmpty()) {
                String up = rest.toUpperCase();
                // first word type
                String[] parts = rest.split("\\s+");
                if (parts.length > 0 && parts[0].equalsIgnoreCase("INTEGER")) {
                    if (up.contains("PRIMARY KEY")) {
                        alias = true;
                    }
                }
            }
            ColumnInfo ci = new ColumnInfo();
            ci.name = colName;
            ci.rowidAlias = alias;
            cols.add(ci);
        }
        return cols;
    }

    static List<Row> readTableRows(FileChannel ch, int pageSize, int totalPages, int reserved,
                                   int rootPage, List<ColumnInfo> cols) throws IOException {
        // we need to know column count for parsing, but we can parse generically
        List<Row> all = new ArrayList<>();
        Set<Integer> visitedPages = new HashSet<>();
        collectLeafPages(ch, pageSize, totalPages, reserved, rootPage, 1, visitedPages, all, cols);
        return all;
    }

    static List<Row> readTableRowsRaw(FileChannel ch, int pageSize, int totalPages, int reserved,
                                      int rootPage, List<String> colNames) throws IOException {
        // for sqlite_schema we know columns
        List<ColumnInfo> cols = new ArrayList<>();
        for (String n : colNames) {
            ColumnInfo ci = new ColumnInfo();
            ci.name = n;
            ci.rowidAlias = false;
            cols.add(ci);
        }
        return readTableRows(ch, pageSize, totalPages, reserved, rootPage, cols);
    }

    static void collectLeafPages(FileChannel ch, int pageSize, int totalPages, int reserved,
                                 int pageNo, int pageType, Set<Integer> visited,
                                 List<Row> out, List<ColumnInfo> cols) throws IOException {
        if (visited.contains(pageNo)) return;
        visited.add(pageNo);
        PageInfo pi = readPage(ch, pageSize, pageNo);
        byte[] data = pi.data;
        int headerOff = pi.headerOffset;
        int ptype = data[headerOff] & 0xFF;
        int cellCount = readU16(data, headerOff + 3);
        int cellPtrStart = readU16(data, headerOff + 5);
        if (ptype == 3) { // leaf table
            for (int i = 0; i < cellCount; i++) {
                int cellOff = readU16(data, cellPtrStart + i * 2);
                // parse cell
                int pos = cellOff;
                int payloadSize = readVarint(data, pos);
                int varintBytes = 0;
                // we need proper varint parsing
                // simplified: assume payload size fits in 1 byte for now? We'll use generic
                // Instead we parse with helper
                ParseResult pr = parseVarint(data, pos);
                int payloadSizeVal = pr.val;
                pos = pr.next;
                ParseResult pr2 = parseVarint(data, pos);
                long rowid = pr2.val;
                pos = pr2.next;
                int payloadBytes = payloadSizeVal;
                // payload starts at pos
                byte[] payload = Arrays.copyOfRange(data, pos, pos + payloadBytes);
                // parse record
                Object[] values = parseRecord(payload, cols);
                Row r = new Row();
                r.rowid = rowid;
                r.values = values;
                // handle rowid alias
                // we already have values for all columns, but if alias column, replace with rowid
                for (int c = 0; c < cols.size(); c++) {
                    if (cols.get(c).rowidAlias) {
                        r.values[c] = rowid;
                    }
                }
                out.add(r);
            }
        } else if (ptype == 1) { // interior table
            // iterate cells
            for (int i = 0; i < cellCount; i++) {
                int cellOff = readU16(data, cellPtrStart + i * 2);
                int leftChild = readU32(data, cellOff);
                // parse key to maybe skip?
                int pos = cellOff + 4;
                ParseResult pr = parseVarint(data, pos);
                // key = pr.val
                // recurse
                collectLeafPages(ch, pageSize, totalPages, reserved, leftChild, 0, visited, out, cols);
            }
            // rightmost child? assume next page? skip for now
        }
    }

    static PageInfo readPage(FileChannel ch, int pageSize, int pageNo) throws IOException {
        long off = ((long) pageNo - 1) * pageSize;
        ByteBuffer buf = ByteBuffer.allocate(pageSize);
        ch.read(buf, off);
        buf.flip();
        byte[] data = new byte[pageSize];
        buf.get(data);
        PageInfo pi = new PageInfo();
        pi.pageNo = pageNo;
        pi.data = data;
        pi.headerOffset = (pageNo == 1) ? 100 : 0;
        return pi;
    }

    // ---------- parsing helpers ----------
    static int readU16(byte[] d, int o) {
        return ((d[o] & 0xFF) << 8) | (d[o + 1] & 0xFF);
    }
    static int readU32(byte[] d, int o) {
        return ((d[o] & 0xFF) << 24) | ((d[o + 1] & 0xFF) << 16) | ((d[o + 2] & 0xFF) << 8) | (d[o + 3] & 0xFF);
    }
    static ParseResult parseVarint(byte[] d, int o) {
        int v = 0;
        int shift = 0;
        int pos = o;
        int n = 0;
        while (true) {
            int b = d[pos++] & 0xFF;
            v |= (b & 0x7F) << shift;
            n++;
            if ((b & 0x80) == 0) break;
            shift += 7;
            if (shift > 28) break;
        }
        return new ParseResult(v, pos);
    }
    static class ParseResult { int val; int next; ParseResult(int v,int n){val=v;next=n;} }

    static Object[] parseRecord(byte[] payload, List<ColumnInfo> cols) {
        // payload starts with header size varint
        ParseResult pr = parseVarint(payload, 0);
        int headerSize = pr.val;
        int pos = pr.next;
        // serial types
        List<Integer> serials = new ArrayList<>();
        int headerEnd = headerSize;
        // Actually headerSize is number of bytes of header? Hmm
        // We'll parse until we have consumed headerSize bytes from start?
        // Simplified: parse serial types until pos >= headerSize
        while (pos < headerSize && pos < payload.length) {
            ParseResult pr2 = parseVarint(payload, pos);
            serials.add(pr2.val);
            pos = pr2.next;
        }
        // data starts at pos
        Object[] vals = new Object[cols.size()];
        int dataPos = pos;
        int colIdx = 0;
        for (int st : serials) {
            if (colIdx >= cols.size()) break;
            Object v = decodeSerial(payload, dataPos, st);
            vals[colIdx] = v;
            dataPos += serialSize(st, v);
            colIdx++;
        }
        // missing trailing columns -> null
        return vals;
    }

    static int serialSize(int st, Object v) {
        if (st == 0) return 0;
        if (st >= 1 && st <= 6) {
            switch (st) {
                case 1: return 1;
                case 2: return 2;
                case 3: return 3;
                case 4: return 4;
                case 5: return 6;
                case 6: return 8;
            }
        }
        if (st == 7) return 8;
        if (st == 8) return 0;
        int len = (st - 9) / 2;
        return len;
    }

    static Object decodeSerial(byte[] payload, int pos, int st) {
        if (st == 0) return null;
        if (st >= 1 && st <= 6) {
            long v = 0;
            int sz = serialSize(st, null);
            for (int i = 0; i < sz; i++) v = (v << 8) | (payload[pos + i] & 0xFF);
            // sign extend
            if (st == 1) {
                int b = (int) v;
                if ((b & 0x80) != 0) b |= ~0xFF;
                return (long) b;
            }
            if (st == 2) {
                int b = (int) v;
                if ((b & 0x8000) != 0) b |= ~0xFFFF;
                return (long) b;
            }
            if (st == 3) {
                long b = v;
                if ((b & 0x800000L) != 0) b |= ~0xFFFFFFL;
                return b;
            }
            if (st == 4) {
                int b = (int) v;
                if ((b & 0x80000000) != 0) b |= ~0xFFFFFFFF;
                return (long) b;
            }
            if (st == 5) {
                long b = v;
                if ((b & 0x800000000000L) != 0) b |= ~0x3FFFFFFFFFFFL;
                return b;
            }
            if (st == 6) {
                long b = v;
                if ((b & 0x8000000000000000L) != 0) b = - ( ~b + 1);
                return b;
            }
        }
        if (st == 7) {
            long bits = 0;
            for (int i = 0; i < 8; i++) bits = (bits << 8) | (payload[pos + i] & 0xFF);
            double d = Double.longBitsToDouble(bits);
            return d;
        }
        if (st == 8) return new byte[0];
        int len = (st - 9) / 2;
        boolean isBlob = (st % 2 == 1);
        byte[] data = Arrays.copyOfRange(payload, pos, pos + len);
        if (isBlob) {
            // BLOB
            if (len > 100) {
                return new BlobMeta(len, crc32(data));
            } else {
                return data;
            }
        } else {
            // TEXT
            String s = new String(data, java.nio.charset.StandardCharsets.UTF_8);
            if (len > 100) {
                return new TextMeta(len, crc32(data));
            } else {
                return s;
            }
        }
    }

    static String formatReal(double d) {
        // exact decimal without exponent, minimal trailing zeros
        String s = Double.toString(d);
        if (s.contains("E")) {
            // convert to plain
            java.math.BigDecimal bd = new java.math.BigDecimal(d);
            s = bd.stripTrailingZeros().toPlainString();
        } else {
            if (s.endsWith(".0")) {
                // keep at least one digit
            }
            // remove unnecessary trailing zeros
            if (s.contains(".")) {
                s = s.replaceAll("0+$", "");
                if (s.endsWith(".")) s += "0";
            }
        }
        return s;
    }

    static String escapeText(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (char c : s.toCharArray()) {
            if (c == '\\') sb.append("\\\\");
            else if (c == '"') sb.append("\\\"");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else if (c < 0x20 || c >= 0x7F) {
                sb.append(String.format("\\x%02X", (int) c));
            } else {
                sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    static int findMatchingParen(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') depth++;
            else if (c == ')') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static List<String> splitDefs(String inside) {
        List<String> res = new ArrayList<>();
        int depth = 0;
        StringBuilder cur = new StringBuilder();
        for (char c : inside.toCharArray()) {
            if (c == '(') depth++;
            else if (c == ')') depth--;
            if (c == ',' && depth == 0) {
                res.add(cur.toString());
                cur.setLength(0);
            } else {
                cur.append(c);
            }
        }
        if (cur.length() > 0) res.add(cur.toString());
        return res;
    }

    static int crc32(byte[] data) {
        java.util.zip.CRC32 crc = new java.util.zip.CRC32();
        crc.update(data);
        return (int) crc.getValue();
    }

    static class TextMeta { int len; int crc; TextMeta(int l,int c){len=l;crc=c;} }
    static class BlobMeta { int len; int crc; BlobMeta(int l,int c){len=l;crc=c;} }
}

import java.io.*;
import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.util.*;

public class Main {

    static class ColumnInfo {
        String name;
        boolean rowidAlias;
    }

    static class TableMeta {
        String name;
        int rootpage;
        String sql;
    }

    static class Row {
        long rowid;
        Object[] values;
    }

    public static void main(String[] args) throws Exception {
        if (args.length < 1) return;
        Path dbPath = Paths.get(args[0], "db.sqlite");
        try (RandomAccessFile raf = new RandomAccessFile(dbPath.toFile(), "r")) {
            FileChannel ch = raf.getChannel();
            long fileSize = ch.size();
            ByteBuffer head = ByteBuffer.allocate(100);
            ch.read(head, 0);
            head.flip();
            byte[] h = new byte[100];
            head.get(h);
            int pageSize = ((h[16] & 0xFF) << 8) | (h[17] & 0xFF);
            if (pageSize == 65534) pageSize = 65536;
            int reserved = h[18] & 0xFF;

            int totalPages = (int) (fileSize / pageSize);

            List<TableMeta> tables = readSchema(ch, pageSize, totalPages, reserved);
            tables.sort(Comparator.comparing(t -> t.name));

            boolean firstTable = true;
            for (TableMeta tm : tables) {
                List<ColumnInfo> cols = parseColumns(tm.sql, tm.name);
                List<Row> rows = new ArrayList<>();
                Set<Integer> visited = new HashSet<>();
                collectTable(ch, pageSize, totalPages, reserved, tm.rootpage, cols, rows, visited);
                rows.sort(Comparator.comparingLong(r -> r.rowid));
                if (!firstTable) System.out.println();
                firstTable = false;
                System.out.println("TABLE " + tm.name + " rows=" + rows.size());
                System.out.print("COLUMNS ");
                for (int i = 0; i < cols.size(); i++) {
                    if (i > 0) System.out.print(", ");
                    System.out.print(cols.get(i).name);
                }
                System.out.println();
                for (Row r : rows) {
                    System.out.print(r.rowid + ": ");
                    for (int i = 0; i < cols.size(); i++) {
                        if (i > 0) System.out.print(", ");
                        Object v = i < r.values.length ? r.values[i] : null;
                        if (v == null) {
                            System.out.print("NULL");
                        } else if (v instanceof Long) {
                            System.out.print(v);
                        } else if (v instanceof Double) {
                            System.out.print(formatReal((Double) v));
                        } else if (v instanceof String) {
                            System.out.print(escapeText((String) v));
                        } else if (v instanceof byte[]) {
                            byte[] b = (byte[]) v;
                            if (b.length == 0) System.out.print("X''");
                            else {
                                System.out.print("X'");
                                for (byte bb : b) System.out.printf("%02X", bb);
                                System.out.print("'");
                            }
                        } else if (v instanceof TextMeta) {
                            TextMeta tm2 = (TextMeta) v;
                            System.out.printf("<TEXT len=%d crc32=%08x>", tm2.len, tm2.crc);
                        } else if (v instanceof BlobMeta) {
                            BlobMeta bm = (BlobMeta) v;
                            System.out.printf("<BLOB len=%d crc32=%08x>", bm.len, bm.crc);
                        }
                    }
                    System.out.println();
                }
            }
        }
    }

    /* ---------- schema ---------- */
    static List<TableMeta> readSchema(FileChannel ch, int pageSize, int totalPages, int reserved) throws IOException {
        List<ColumnInfo> schemaCols = new ArrayList<>();
        for (String n : Arrays.asList("type","name","tbl_name","rootpage","sql")) {
            ColumnInfo ci = new ColumnInfo();
            ci.name = n;
            ci.rowidAlias = false;
            schemaCols.add(ci);
        }
        List<Row> rows = new ArrayList<>();
        Set<Integer> visited = new HashSet<>();
        collectTable(ch, pageSize, totalPages, reserved, 1, schemaCols, rows, visited);
        List<TableMeta> out = new ArrayList<>();
        for (Row r : rows) {
            String type = (String) r.values[0];
            String name = (String) r.values[1];
            if (!"table".equals(type)) continue;
            if (name.startsWith("sqlite_")) continue;
            TableMeta tm = new TableMeta();
            tm.name = name;
            tm.rootpage = ((Long) r.values[3]).intValue();
            tm.sql = (String) r.values[4];
            out.add(tm);
        }
        return out;
    }

    /* ---------- table traversal ---------- */
    static void collectTable(FileChannel ch, int pageSize, int totalPages, int reserved,
                            int rootPage, List<ColumnInfo> cols, List<Row> out, Set<Integer> visited) throws IOException {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(rootPage);
        while (!stack.isEmpty()) {
            int pageNo = stack.pop();
            if (visited.contains(pageNo)) continue;
            visited.add(pageNo);
            byte[] page = readPage(ch, pageSize, pageNo);
            int headerOff = (pageNo == 1) ? 100 : 0;
            int pageType = page[headerOff] & 0xFF;
            if (pageType == 1 || pageType == 2) { // interior
                int rightmost = readU32(page, headerOff + 8);
                int cellCount = readU16(page, headerOff + 3);
                int ptrStart = headerOff + 12;
                for (int i = 0; i < cellCount; i++) {
                    int cellOff = readU16(page, ptrStart + i * 2);
                    int leftChild = readU32(page, cellOff);
                    if (leftChild >= 1 && leftChild <= totalPages) stack.push(leftChild);
                }
                if (rightmost >= 1 && rightmost <= totalPages) stack.push(rightmost);
            } else if (pageType == 3 || pageType == 4) { // leaf
                int cellCount = readU16(page, headerOff + 3);
                int ptrStart = headerOff + 8;
                for (int i = 0; i < cellCount; i++) {
                    int cellOff = readU16(page, ptrStart + i * 2);
                    Row r = parseLeafCell(page, headerOff, cellOff, cols);
                    if (r != null) out.add(r);
                }
            }
        }
    }

    static Row parseLeafCell(byte[] page, int headerOff, int cellOff, List<ColumnInfo> cols) {
        int pos = cellOff;
        Varint vr = parseVarint(page, pos);
        long rowid = vr.val;
        pos = vr.next;
        // record starts here
        if (pos >= page.length) return null;
        Varint vh = parseVarint(page, pos);
        int headerSize = (int) vh.val;
        pos = vh.next;
        int headerEnd = pos;
        List<Integer> serials = new ArrayList<>();
        int consumed = 0;
        while (consumed < headerSize && pos < page.length) {
            Varint vs = parseVarint(page, pos);
            serials.add((int) vs.val);
            consumed += vs.next - pos;
            pos = vs.next;
        }
        int dataPos = pos;
        Object[] values = new Object[cols.size()];
        int colIdx = 0;
        for (int st : serials) {
            if (colIdx >= cols.size()) break;
            Object v = decodeSerial(page, dataPos, st);
            int sz = serialSize(st, v);
            values[colIdx] = v;
            dataPos += sz;
            colIdx++;
        }
        Row r = new Row();
        r.rowid = rowid;
        r.values = values;
        // rowid alias handling
        for (int i = 0; i < cols.size(); i++) {
            if (cols.get(i).rowidAlias) {
                r.values[i] = rowid;
            }
        }
        return r;
    }

    /* ---------- parsing helpers ---------- */
    static byte[] readPage(FileChannel ch, int pageSize, int pageNo) throws IOException {
        long off = ((long) pageNo - 1) * pageSize;
        ByteBuffer buf = ByteBuffer.allocate(pageSize);
        ch.read(buf, off);
        buf.flip();
        byte[] data = new byte[pageSize];
        buf.get(data);
        return data;
    }

    static int readU16(byte[] d, int o) {
        return ((d[o] & 0xFF) << 8) | (d[o + 1] & 0xFF);
    }
    static int readU32(byte[] d, int o) {
        return ((d[o] & 0xFF) << 24) | ((d[o + 1] & 0xFF) << 16) | ((d[o + 2] & 0xFF) << 8) | (d[o + 3] & 0xFF);
    }

    static class Varint {
        long val;
        int next;
        Varint(long v,int n){val=v;next=n;}
    }
    static Varint parseVarint(byte[] d, int o) {
        long v = 0;
        int shift = 0;
        int pos = o;
        while (true) {
            int b = d[pos++] & 0xFF;
            v |= (long)(b & 0x7F) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
        }
        return new Varint(v, pos);
    }

    static int serialSize(int st, Object v) {
        if (st == 0) return 0;
        if (st >= 1 && st <= 6) {
            switch (st) {
                case 1: return 1;
                case 2: return 2;
                case 3: return 3;
                case 4: return 4;
                case 5: return 6;
                case 6: return 8;
            }
        }
        if (st == 7) return 8;
        if (st == 8) return 0;
        int len = (st - 9) / 2;
        return len;
    }

    static Object decodeSerial(byte[] page, int pos, int st) {
        if (st == 0) return null;
        if (st >= 1 && st <= 6) {
            int sz = serialSize(st, null);
            long v = 0;
            for (int i = 0; i < sz; i++) v = (v << 8) | (page[pos + i] & 0xFF);
            // sign extend
            switch (st) {
                case 1: { int b = (int)v; if ((b & 0x80)!=0) b |= ~0xFF; return (long)b; }
                case 2: { int b = (int)v; if ((b & 0x8000)!=0) b |= ~0xFFFF; return (long)b; }
                case 3: { long b = v; if ((b & 0x800000L)!=0) b |= ~0xFFFFFFL; return b; }
                case 4: { int b = (int)v; if ((b & 0x80000000)!=0) b |= ~0xFFFFFFFF; return (long)b; }
                case 5: { long b = v; if ((b & 0x800000000000L)!=0) b |= ~0x3FFFFFFFFFFFL; return b; }
                case 6: { long b = v; if ((b & 0x8000000000000000L)!=0) b = - ( ~b + 1); return b; }
            }
        }
        if (st == 7) {
            long bits = 0;
            for (int i = 0; i < 8; i++) bits = (bits << 8) | (page[pos + i] & 0xFF);
            return Double.longBitsToDouble(bits);
        }
        if (st == 8) return new byte[0];
        int len = (st - 9) / 2;
        boolean isBlob = (st % 2 == 1);
        byte[] data = Arrays.copyOfRange(page, pos, pos + len);
        if (isBlob) {
            if (len > 100) return new BlobMeta(len, crc32(data));
            else return data;
        } else {
            String s = new String(data, java.nio.charset.StandardCharsets.UTF_8);
            if (len > 100) return new TextMeta(len, crc32(data));
            else return s;
        }
    }

    static List<ColumnInfo> parseColumns(String sql, String tableName) {
        int l = sql.indexOf('(');
        int r = findMatchingParen(sql, l);
        String inside = sql.substring(l + 1, r);
        List<String> defs = splitDefs(inside);
        List<ColumnInfo> cols = new ArrayList<>();
        for (String d : defs) {
            String trimmed = d.trim();
            if (trimmed.isEmpty()) continue;
            String colName;
            String rest;
            if (trimmed.startsWith("\"")) {
                int q2 = trimmed.indexOf('"', 1);
                colName = trimmed.substring(1, q2);
                rest = trimmed.substring(q2 + 1).trim();
            } else {
                int sp = 0;
                while (sp < trimmed.length() && !Character.isWhitespace(trimmed.charAt(sp))) sp++;
                colName = trimmed.substring(0, sp);
                rest = trimmed.substring(sp).trim();
            }
            boolean alias = false;
            if (!rest.isEmpty()) {
                String up = rest.toUpperCase();
                if (up.contains("PRIMARY KEY")) {
                    String[] parts = rest.split("\\s+");
                    if (parts.length > 0 && parts[0].equalsIgnoreCase("INTEGER")) {
                        alias = true;
                    }
                }
            }
            ColumnInfo ci = new ColumnInfo();
            ci.name = colName;
            ci.rowidAlias = alias;
            cols.add(ci);
        }
        return cols;
    }

    static int findMatchingParen(String s, int start) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') depth++;
            else if (c == ')') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static List<String> splitDefs(String inside) {
        List<String> res = new ArrayList<>();
        int depth = 0;
        StringBuilder cur = new StringBuilder();
        for (char c : inside.toCharArray()) {
            if (c == '(') depth++;
            else if (c == ')') depth--;
            if (c == ',' && depth == 0) {
                res.add(cur.toString());
                cur.setLength(0);
            } else cur.append(c);
        }
        if (cur.length() > 0) res.add(cur.toString());
        return res;
    }

    static String formatReal(double d) {
        java.math.BigDecimal bd = new java.math.BigDecimal(d);
        bd = bd.stripTrailingZeros();
        String s = bd.toPlainString();
        if (!s.contains(".")) s += ".0";
        return s;
    }

    static String escapeText(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\r') sb.append("\\r");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || cp >= 0x7F) {
                sb.append(String.format("\\x%02X", cp));
            } else {
                sb.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }

    static int crc32(byte[] data) {
        java.util.zip.CRC32 crc = new java.util.zip.CRC32();
        crc.update(data);
        return (int) crc.getValue();
    }

    static class TextMeta { int len; int crc; TextMeta(int l,int c){len=l;crc=c;} }
    static class BlobMeta { int len; int crc; BlobMeta(int l,int c){len=l;crc=c;} }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.Pattern;

public class Main {

    static class MatchResult {
        int pos;
        int[] starts;
        int[] ends;
        MatchResult(int pos, int[] starts, int[] ends) {
            this.pos = pos;
            this.starts = starts;
            this.ends = ends;
        }
    }

    abstract static class Node {
        abstract MatchResult match(Matcher m, int sPos, int[] starts, int[] ends);
    }

    static class EmptyNode extends Node {
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends) {
            return new MatchResult(sPos, starts.clone(), ends.clone());
        }
    }
    static class LiteralNode extends Node {
        char c;
        LiteralNode(char c){this.c=c;}
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            if(sPos < m.subj.length() && m.subj.charAt(sPos)==c){
                return new MatchResult(sPos+1, starts.clone(), ends.clone());
            }
            return null;
        }
    }
    static class DotNode extends Node {
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            if(sPos < m.subj.length()){
                return new MatchResult(sPos+1, starts.clone(), ends.clone());
            }
            return null;
        }
    }
    static class AnchorStartNode extends Node {
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            if(sPos==0) return new MatchResult(sPos, starts.clone(), ends.clone());
            return null;
        }
    }
    static class AnchorEndNode extends Node {
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            if(sPos==m.subj.length()) return new MatchResult(sPos, starts.clone(), ends.clone());
            return null;
        }
    }
    static class ClassNode extends Node {
        Pattern pat;
        ClassNode(String content, boolean neg){
            String s = "[" + (neg?"^":"") + content + "]";
            pat = Pattern.compile(s);
        }
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            if(sPos >= m.subj.length()) return null;
            String ch = String.valueOf(m.subj.charAt(sPos));
            if(pat.matcher(ch).matches()){
                return new MatchResult(sPos+1, starts.clone(), ends.clone());
            }
            return null;
        }
    }
    static class EscapeClassNode extends Node {
        char esc;
        EscapeClassNode(char esc){this.esc=esc;}
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            if(sPos >= m.subj.length()) return null;
            char c = m.subj.charAt(sPos);
            boolean ok = false;
            switch(esc){
                case 'd': ok = Character.isDigit(c); break;
                case 'D': ok = !Character.isDigit(c); break;
                case 'w': ok = Character.isLetterOrDigit(c) || c=='_'; break;
                case 'W': ok = !(Character.isLetterOrDigit(c) || c=='_'); break;
                case 's': ok = c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\f'||c=='\u000b'; break;
                case 'S': ok = !(c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\f'||c=='\u000b'); break;
            }
            if(ok) return new MatchResult(sPos+1, starts.clone(), ends.clone());
            return null;
        }
    }
    static class GroupNode extends Node {
        Node inner;
        boolean capturing;
        int groupNum;
        GroupNode(Node inner, boolean capturing, int groupNum){
            this.inner=inner; this.capturing=capturing; this.groupNum=groupNum;
        }
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            MatchResult innerRes = inner.match(m, sPos, starts, ends);
            if(innerRes==null) return null;
            if(!capturing) return innerRes;
            int[] ns = innerRes.starts.clone();
            int[] ne = innerRes.ends.clone();
            ns[groupNum]=sPos;
            ne[groupNum]=innerRes.pos;
            return new MatchResult(innerRes.pos, ns, ne);
        }
    }
    static class SeqNode extends Node {
        List<Node> children;
        SeqNode(List<Node> children){this.children=children;}
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            int curPos=sPos;
            int[] curS=starts.clone();
            int[] curE=ends.clone();
            for(Node ch: children){
                MatchResult r = ch.match(m, curPos, curS, curE);
                if(r==null) return null;
                curPos=r.pos;
                curS=r.starts;
                curE=r.ends;
            }
            return new MatchResult(curPos, curS, curE);
        }
    }
    static class AltNode extends Node {
        List<Node> branches;
        AltNode(List<Node> branches){this.branches=branches;}
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            for(Node b: branches){
                MatchResult r = b.match(m, sPos, starts, ends);
                if(r!=null) return r;
            }
            return null;
        }
    }
    static class QuantNode extends Node {
        Node inner;
        int min, max;
        boolean greedy;
        QuantNode(Node inner,int min,int max,boolean greedy){
            this.inner=inner; this.min=min; this.max=max; this.greedy=greedy;
        }
        MatchResult match(Matcher m, int sPos, int[] starts, int[] ends){
            int curPos=sPos;
            int[] curS=starts.clone();
            int[] curE=ends.clone();
            int count=0;
            for(int i=0;i<min;i++){
                MatchResult r = inner.match(m, curPos, curS, curE);
                if(r==null) return null;
                curPos=r.pos;
                curS=r.starts;
                curE=r.ends;
                count++;
            }
            return quantOptional(m, inner, curPos, count, curS, curE, false, min, max, greedy);
        }
        private MatchResult quantOptional(Matcher m, Node inner, int curPos, int count,
                                          int[] curS, int[] curE, boolean lastEmpty,
                                          int min,int max,boolean greedy){
            if(greedy){
                if(count < max && !(count>=min && lastEmpty)){
                    MatchResult r = inner.match(m, curPos, curS, curE);
                    if(r!=null){
                        boolean newEmpty = r.pos==curPos;
                        MatchResult rec = quantOptional(m, inner, r.pos, count+1, r.starts, r.ends, newEmpty, min, max, greedy);
                        if(rec!=null) return rec;
                    }
                }
                if(count>=min) return new MatchResult(curPos, curS, curE);
            }else{
                if(count>=min) return new MatchResult(curPos, curS, curE);
                if(count < max && !(count>=min && lastEmpty)){
                    MatchResult r = inner.match(m, curPos, curS, curE);
                    if(r!=null){
                        boolean newEmpty = r.pos==curPos;
                        MatchResult rec = quantOptional(m, inner, r.pos, count+1, r.starts, r.ends, newEmpty, min, max, greedy);
                        if(rec!=null) return rec;
                    }
                }
            }
            return null;
        }
    }

    static class Matcher {
        String subj;
        Node root;
        int groups;
        Matcher(String subj, Node root, int groups){this.subj=subj; this.root=root; this.groups=groups;}
        MatchResult matchFrom(int start){
            int[] starts = new int[groups+1];
            int[] ends = new int[groups+1];
            Arrays.fill(starts, -1);
            Arrays.fill(ends, -1);
            return root.match(this, start, starts, ends);
        }
    }

    static class Parser {
        String pat;
        int pos;
        int groupCnt=1;
        Parser(String pat){this.pat=pat;}
        Node parse(){
            Node r = parseRegex();
            return r;
        }
        Node parseRegex(){
            Node first = parseBranch();
            List<Node> br = new ArrayList<>();
            br.add(first);
            while(pos < pat.length() && pat.charAt(pos)=='|'){
                pos++;
                br.add(parseBranch());
            }
            if(br.size()==1) return first;
            return new AltNode(br);
        }
        Node parseBranch(){
            List<Node> pieces = new ArrayList<>();
            while(pos < pat.length()){
                char c = pat.charAt(pos);
                if(c=='|' || c==')') break;
                pieces.add(parsePiece());
            }
            if(pieces.isEmpty()) return new EmptyNode();
            if(pieces.size()==1) return pieces.get(0);
            return new SeqNode(pieces);
        }
        Node parsePiece(){
            Node atom = parseAtom();
            if(pos < pat.length()){
                char c = pat.charAt(pos);
                if(c=='*'||c=='+'||c=='?'||c=='{'){
                    int[] q = parseQuant();
                    return new QuantNode(atom, q[0], q[1], q[2]==1);
                }
            }
            return atom;
        }
        int[] parseQuant(){
            char c = pat.charAt(pos);
            int min=0, max=Integer.MAX_VALUE;
            boolean greedy=true;
            if(c=='*'){min=0; max=Integer.MAX_VALUE; pos++;}
            else if(c=='+'){min=1; max=Integer.MAX_VALUE; pos++;}
            else if(c=='?'){min=0; max=1; pos++;}
            else if(c=='{'){
                pos++;
                int m=0;
                while(pos<pat.length() && Character.isDigit(pat.charAt(pos))){m=m*10+pat.charAt(pos)-'0';pos++;}
                int n=-1;
                if(pos<pat.length() && pat.charAt(pos)==','){
                    pos++;
                    if(pos<pat.length() && Character.isDigit(pat.charAt(pos))){
                        n=0;
                        while(pos<pat.length() && Character.isDigit(pat.charAt(pos))){n=n*10+pat.charAt(pos)-'0';pos++;}
                    }else{
                        n=Integer.MAX_VALUE;
                    }
                }
                if(pos<pat.length() && pat.charAt(pos)=='}') pos++;
                if(n==-1){min=m; max=m;}
                else {min=m; max=n;}
            }
            if(pos<pat.length() && pat.charAt(pos)=='?'){greedy=false; pos++;}
            return new int[]{min, max, greedy?1:0};
        }
        Node parseAtom(){
            char c = pat.charAt(pos);
            if(c=='('){
                if(pos+2<pat.length() && pat.charAt(pos+1)=='?' && pat.charAt(pos+2)==':'){
                    pos+=3;
                    Node inner = parseRegex();
                    if(pos<pat.length() && pat.charAt(pos)==')') pos++;
                    return new GroupNode(inner,false,-1);
                }else{
                    pos++;
                    Node inner = parseRegex();
                    if(pos<pat.length() && pat.charAt(pos)==')') pos++;
                    int gn = groupCnt++;
                    return new GroupNode(inner,true,gn);
                }
            }else if(c=='.'){pos++; return new DotNode();}
            else if(c=='^'){pos++; return new AnchorStartNode();}
            else if(c=='$'){pos++; return new AnchorEndNode();}
            else if(c=='['){
                pos++;
                boolean neg=false;
                if(pos<pat.length() && pat.charAt(pos)=='^'){neg=true; pos++;}
                int start=pos;
                while(pos<pat.length()){
                    char ch=pat.charAt(pos);
                    if(ch==']') break;
                    if(ch=='\\'){pos+=2; continue;}
                    pos++;
                }
                String content = pat.substring(start, pos);
                if(pos<pat.length() && pat.charAt(pos)==']') pos++;
                return new ClassNode(content, neg);
            }else if(c=='\\'){
                pos++;
                if(pos>=pat.length()){pos++; return new LiteralNode('\\');}
                char esc=pat.charAt(pos); pos++;
                if(esc=='d'||esc=='D'||esc=='w'||esc=='W'||esc=='s'||esc=='S'){
                    return new EscapeClassNode(esc);
                }else{
                    return new LiteralNode(esc);
                }
            }else{
                pos++;
                return new LiteralNode(c);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        if(args.length<1){return;}
        Path dir = Paths.get(args[0]);
        Path file = dir.resolve("cases.txt");
        List<String> lines = Files.readAllLines(file);
        int idx=1;
        for(String line: lines){
            if(line.isEmpty()) continue;
            int tab = line.indexOf('\t');
            if(tab==-1) continue;
            String patStr = line.substring(0, tab);
            String subj = line.substring(tab+1);
            Parser parser = new Parser(patStr);
            Node root = parser.parse();
            int groups = parser.groupCnt-1;
            Matcher matcher = new Matcher(subj, root, groups);
            boolean found=false;
            int matchStart=-1, matchEnd=-1;
            int[] finalStarts=null, finalEnds=null;
            int len = subj.length();
            for(int start=0; start<=len && !found; start++){
                MatchResult res = matcher.matchFrom(start);
                if(res!=null){
                    found=true;
                    matchStart=start;
                    matchEnd=res.pos;
                    finalStarts=res.starts;
                    finalEnds=res.ends;
                }
            }
            if(!found){
                System.out.println(idx+": no match");
            }else{
                StringBuilder sb = new StringBuilder();
                sb.append(idx).append(": ").append(matchStart).append("-").append(matchEnd);
                for(int g=1; g<=groups; g++){
                    int s = finalStarts[g];
                    int e = finalEnds[g];
                    if(s==-1) sb.append(" -");
                    else sb.append(" ").append(s).append("-").append(e);
                }
                System.out.println(sb.toString());
            }
            idx++;
        }
    }
}

