        GroupNode(Node inner, boolean capturing, int groupNum){
            this.inner = inner; this.capturing = capturing; this.groupNum = groupNum;
        }
        MatchResult match(MatcherContext ctx, int pos, int[] starts, int[] ends){
            int[] ns = starts.clone();
            int[] ne = ends.clone();
            MatchResult r = inner.match(ctx, pos, ns, ne);
            if(r == null) return null;
            if(capturing){
                ns[groupNum] = pos;
                ne[groupNum] = r.pos;
            }
