/* main */
int main(int argc,char *argv[]){
    if(argc!=3){ return 0; }
    const char *data_dir=argv[1];
    const char *base_url=argv[2];
    ReqCfg cfg={0};
    load_request_cfg(data_dir,&cfg);
    char host[256]; int port; char path_prefix[512];
    parse_base_url(base_url,host,&port,path_prefix);
    char full_path[1024];
    snprintf(full_path,sizeof(full_path),"%s/v1/messages",path_prefix);
    /* build request 1 body */
    char *sys_esc=json_escape_str(cfg.system);
    char *prompt_esc=json_escape_str(cfg.prompt);
    DynBuf body; db_init(&body);
    db_append_str(&body,"{");
    db_append_str(&body,"\"model\":\""); db_append_str(&body,cfg.model); db_append_str(&body,"\",");
    db_append_str(&body,"\"max_tokens\":"); char buf[64]; snprintf(buf,sizeof(buf),"%lld",cfg.max_tokens); db_append_str(&body,buf); db_append_str(&body,",");
    db_append_str(&body,"\"stream\":true,");
    db_append_str(&body,"\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":"); snprintf(buf,sizeof(buf),"%lld",cfg.thinking_budget); db_append_str(&body,buf); db_append_str(&body,"},");
    db_append_str(&body,"\"system\":"); db_append_str(&body,sys_esc); db_append_str(&body,",");
    db_append_str(&body,"\"tools\":"); db_append_str(&body,cfg.tools_raw); db_append_str(&body,",");
    db_append_str(&body,"\"messages\":[{\"role\":\"user\",\"content\":"); db_append_str(&body,prompt_esc); db_append_str(&body,"}]");
    db_append_str(&body,"}");
    free(sys_esc); free(prompt_esc);
    /* send request 1 */
    int s=connect_host(host,port);
    char req_hdr[4096];
    snprintf(req_hdr,sizeof(req_hdr),
        "POST %s HTTP/1.1\r\nHost: %s:%d\r\nContent-Length: %zu\r\nx-api-key: %s\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nConnection: close\r\n\r\n",
        full_path,host,port,body.len,cfg.api_key);
    write(s,req_hdr,strlen(req_hdr));
    write(s,body.data,body.len);
    /* read response */
    char hdr_buf[8192]; ssize_t n=0; size_t hdr_len=0;
    while(1){ ssize_t r=read(s,hdr_buf+hdr_len,1); if(r<=0) break; hdr_len+=r; if(hdr_len>=4 && memcmp(hdr_buf+hdr_len-4,"\r\n\r\n",4)==0) break; }
    int status=0; sscanf(hdr_buf,"%*s %d", &status);
    /* read rest */
    DynBuf resp; db_init(&resp);
    char tmp[4096];
    while(1){ ssize_t r=read(s,tmp,sizeof(tmp)); if(r<=0) break; db_append(&resp,tmp,r); }
    close(s);
    /* process */
    ReplyState rs1; rs_init(&rs1);
    if(status==200){
        size_t sse_len;
        char *sse=decode_chunked(resp.data,resp.len,&sse_len);
        parse_sse(sse,sse_len,&rs1);
        free(sse);
    }
    /* output */
    printf("request 1\n");
    for(size_t i=0;i<rs1.nblocks;i++){
        Block *b=&rs1.blocks[i];
        if(b->type==0){
            char *e=escape_output(b->thinking);
            printf("thinking %s\n",e); free(e);
            e=escape_output(b->signature);
            printf("signature %s\n",e); free(e);
        }else if(b->type==1){
            char *e=escape_output(b->text);
            printf("text %s\n",e); free(e);
        }else if(b->type==2){
            /* id and name need to be extracted from start event? We didn't capture. For demo assume empty */
            printf("tool_use %s %s %s\n","", "", b->tool_input_raw?b->tool_input_raw:"");
        }
    }
    printf("stop_reason %s\n", rs1.stop_reason);
    /* usage will be printed later */
    free(body.data);
    return 0;
}

