typedef struct {char *data;size_t len;size_t cap;} DynBuf;
static void db_init(DynBuf*b){b->data=NULL;b->len=0;b->cap=0;}
static void db_append(DynBuf*b,const char*s,size_t n){if(b->len+n>b->cap){size_t nc=b->cap?b->cap*2:1024;while(nc<b->len+n)nc*=2;b->data=realloc(b->data,nc);b->cap=nc;}memcpy(b->data+b->len,s,n);b->len+=n;}
static void db_append_str(DynBuf*b,const char*s){db_append(b,s,strlen(s));}

static char *strndup_s(const char *s,size_t n){char *p=malloc(n+1);memcpy(p,s,n);p[n]=0;return p;}

static char *json_unescape(const char *s,size_t len){
    char *out=malloc(len+1);size_t oi=0;
    for(size_t i=0;i<len;){
        if(s[i]!='\\'){out[oi++]=s[i++];continue;}
        i++;
        if(i>=len)break;
        char c=s[i++];
        switch(c){
            case '"':out[oi++]='"';break;
            case '\\':out[oi++]='\\';break;
            case '/':out[oi++]='/';break;
            case 'b':out[oi++]='\b';break;
            case 'f':out[oi++]='\f';break;
            case 'n':out[oi++]='\n';break;
            case 'r':out[oi++]='\r';break;
            case 't':out[oi++]='\t';break;
            case 'u':{
                if(i+4>len){out[oi++]='?';break;}
                unsigned int cp=0;for(int k=0;k<4;k++){char h=s[i+k];cp=cp*16+(isdigit(h)?h-'0':tolower(h)-'a'+10);}i+=4;
                if(cp>=0xD800&&cp<=0xDBFF&&i+6<=len&&s[i]=='\\'&&s[i+1]=='u'){
                    i+=2;unsigned int cp2=0;for(int k=0;k<4;k++){char h=s[i+k];cp2=cp2*16+(isdigit(h)?h-'0':tolower(h)-'a'+10);}i+=4;
                    cp=0x10000+((cp-0xD800)<<10)+(cp2-0xDC00);
                }
                if(cp<=0x7F){out[oi++]=(char)cp;}
                else if(cp<=0x7FF){out[oi++]=(char)(0xC0|cp>>6);out[oi++]=(char)(0x80|cp&0x3F);}
                else if(cp<=0xFFFF){out[oi++]=(char)(0xE0|cp>>12);out[oi++]=(char)(0x80|((cp>>6)&0x3F));out[oi++]=(char)(0x80|cp&0x3F);}
                else {out[oi++]=(char)(0xF0|cp>>18);out[oi++]=(char)(0x80|((cp>>12)&0x3F));out[oi++]=(char)(0x80|((cp>>6)&0x3F));out[oi++]=(char)(0x80|cp&0x3F);}
                break;
            }
            default:out[oi++]=c;break;
        }
    }
    out[oi]=0;return out;
}

static const char *find_key(const char *json,const char *key){
    char pat[128];snprintf(pat,sizeof(pat),"\"%s\"",key);
    const char *p=strstr(json,pat);if(!p)return NULL;
    p=strchr(p,'"');if(!p)return NULL;p=strchr(p,':');if(!p)return NULL;p++;while(*p&&isspace((unsigned char)*p))p++;return p;
}
static long long find_int(const char *json,const char *key){
    const char *p=find_key(json,key);if(!p)return 0;char *end;long long v=strtoll(p,&end,10);return v;
}
static char *find_string_unescaped(const char *json,const char *key){
    const char *p=find_key(json,key);if(!p||*p!='"')return NULL;p++;
    const char *start=p;size_t len=0;int esc=0;
    while(*p){if(!esc&&*p=='"')break;if(*p=='\\'&&!esc)esc=1;else esc=0;p++;len++;}
    char *raw=strndup_s(start,len);char *un=json_unescape(raw,len);free(raw);return un;
}

static char *escape_output(const char *s){
    DynBuf b;db_init(&b);
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if(*p=='\\')db_append_str(&b,"\\\\");
        else if(*p=='\n')db_append_str(&b,"\\n");
        else if(*p=='\r')db_append_str(&b,"\\r");
        else if(*p=='\t')db_append_str(&b,"\\t");
        else {char c[2]={*p,0};db_append_str(&b,c);}
    }
    char *out=malloc(b.len+1);memcpy(out,b.data,b.len);out[b.len]=0;free(b.data);return out;
}
static char *json_escape_str(const char *s){
    DynBuf b;db_init(&b);db_append_str(&b,"\"");
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        switch(*p){
            case '"':db_append_str(&b,"\\\"");break;
            case '\\':db_append_str(&b,"\\\\");break;
            case '\b':db_append_str(&b,"\\b");break;
            case '\f':db_append_str(&b,"\\f");break;
            case '\n':db_append_str(&b,"\\n");break;
            case '\r':db_append_str(&b,"\\r");break;
            case '\t':db_append_str(&b,"\\t");break;
            default:if(*p<0x20){char tmp[7];snprintf(tmp,sizeof(tmp),"\\u%04x",*p);db_append_str(&b,tmp);}else{char c[2]={*p,0};db_append_str(&b,c);}
        }
    }
    db_append_str(&b,"\"");
    char *out=malloc(b.len+1);memcpy(out,b.data,b.len);out[b.len]=0;free(b.data);return out;
}

/* UTF helpers */
static size_t utf8_codepoint_count(const char *s){size_t cnt=0;for(const unsigned char *p=(const unsigned char*)s;*p;p++){if((*p&0xC0)!=0x80)cnt++;}return cnt;}
static size_t utf16_units(const char *s){size_t cnt=0;const unsigned char *p=(const unsigned char*)s;while(*p){unsigned int cp;size_t bytes=0;if((*p&0x80)==0){cp=*p;bytes=1;}else if((*p&0xE0)==0xC0){cp=(*p&0x1F)<<6| (p[1]&0x3F);bytes=2;}else if((*p&0xF0)==0xE0){cp=(*p&0x0F)<<12| (p[1]&0x3F)<<6| (p[2]&0x3F);bytes=3;}else if((*p&0xF8)==0xF0){cp=(*p&0x07)<<18| (p[1]&0x3F)<<12| (p[2]&0x3F)<<6| (p[3]&0x3F);bytes=4;}else{bytes=1;cp=*p;}cnt+=(cp>0xFFFF)?2:1;p+=bytes;}return cnt;}
static char *reverse_codepoints(const char *s){
    size_t cap=256,n=0;struct{unsigned int cp;size_t bytes;} *cps=malloc(cap*sizeof(*cps));
    const unsigned char *p=(const unsigned char*)s;
    while(*p){unsigned int cp;size_t bytes=0;if((*p&0x80)==0){cp=*p;bytes=1;}else if((*p&0xE0)==0xC0){cp=(*p&0x1F)<<6|(p[1]&0x3F);bytes=2;}else if((*p&0xF0)==0xE0){cp=(*p&0x0F)<<12|(p[1]&0x3F)<<6|(p[2]&0x3F);bytes=3;}else if((*p&0xF8)==0xF0){cp=(*p&0x07)<<18|(p[1]&0x3F)<<12|(p[2]&0x3F)<<6|(p[3]&0x3F);bytes=4;}else{bytes=1;cp=*p;}if(n>=cap){cap*=2;cps=realloc(cps,cap*sizeof(*cps));}cps[n].cp=cp;cps[n].bytes=bytes;n++;p+=bytes;}
    DynBuf out;db_init(&out);
    for(size_t i=n;i>0;i--){unsigned int cp=cps[i-1].cp;if(cp<=0x7F){char c=cp;db_append(&out,&c,1);}else if(cp<=0x7FF){unsigned char b[2]={0xC0|cp>>6,0x80|cp&0x3F};db_append(&out,(char*)b,2);}else if(cp<=0xFFFF){unsigned char b[3]={0xE0|cp>>12,0x80|((cp>>6)&0x3F),0x80|cp&0x3F};db_append(&out,(char*)b,3);}else{unsigned char b[4]={0xF0|cp>>18,0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|cp&0x3F};db_append(&out,(char*)b,4);}}
    char *res=malloc(out.len+1);memcpy(res,out.data,out.len);res[out.len]=0;free(out.data);free(cps);return res;
}

/* socket */
static int connect_host(const char *host,int port){
    struct addrinfo hints={0},*res;hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char portstr[16];snprintf(portstr,sizeof(portstr),"%d",port);
    if(getaddrinfo(host,portstr,&hints,&res)!=0)return -1;
    int s=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(s<0){freeaddrinfo(res);return -1;}
    if(connect(s,res->ai_addr,res->ai_addrlen)!=0){close(s);freeaddrinfo(res);return -1;}
    freeaddrinfo(res);return s;
}
static void parse_base_url(const char *base_url,char *host,int *port,char *path){
    const char *p=strstr(base_url,"://");if(p)p+=3;else p=base_url;
    const char *slash=strchr(p,'/');size_t hlen=slash?(size_t)(slash-p):strlen(p);
    char hostport[256];strncpy(hostport,p,hlen);hostport[hlen]=0;
    char *colon=strchr(hostport,':');if(colon){*colon=0;strcpy(host,hostport);*port=atoi(colon+1);}else{strcpy(host,hostport);*port=80;}
    if(slash)strcpy(path,slash);else strcpy(path,"");
}

/* config */
typedef struct{char api_key[512];char model[256];long long max_tokens;long long thinking_budget;char system[8192];char prompt[8192];char tools_raw[8192];}ReqCfg;
static int load_request_cfg(const char *dir,ReqCfg *cfg){
    char path[1024];snprintf(path,sizeof(path),"%s/request.json",dir);
    FILE *f=fopen(path,"rb");if(!f)return 0;fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);char *buf=malloc(sz+1);fread(buf,1,sz,f);buf[sz]=0;fclose(f);
    char *v;
    v=find_string_unescaped(buf,"api_key");if(v){strcpy(cfg->api_key,v);free(v);}
    v=find_string_unescaped(buf,"model");if(v){strcpy(cfg->model,v);free(v);}
    cfg->max_tokens=find_int(buf,"max_tokens");
    cfg->thinking_budget=find_int(buf,"thinking_budget");
    v=find_string_unescaped(buf,"system");if(v){strcpy(cfg->system,v);free(v);}
    v=find_string_unescaped(buf,"prompt");if(v){strcpy(cfg->prompt,v);free(v);}
    const char *tok=strstr(buf,"\"tools\"");if(tok){const char *b=strchr(tok,'[');if(b){const char *e=b;int d=0;while(*e){if(*e=='[')d++;if(*e==']'){d--;if(d==0)break;}e++;}size_t l=e-b+1;if(l<sizeof(cfg->tools_raw)){memcpy(cfg->tools_raw,b,l);cfg->tools_raw[l]=0;}}}
    free(buf);return 1;
}

/* blocks */
typedef struct{int index;int type;char *thinking;char *signature;char *text;char *tool_id;char *tool_name;char *tool_input_raw;}Block;
static void block_init(Block*b){memset(b,0,sizeof(*b));b->type=-1;}
typedef struct{Block *blocks;size_t nblocks;size_t capblocks;long long input_tokens;long long cache_read;long long output_tokens;char stop_reason[64];}ReplyState;
static void rs_init(ReplyState*rs){rs->blocks=NULL;rs->nblocks=0;rs->capblocks=0;rs->input_tokens=0;rs->cache_read=0;rs->output_tokens=0;rs->stop_reason[0]=0;}
static Block*rs_get_block(ReplyState*rs,int idx){for(size_t i=0;i<rs->nblocks;i++)if(rs->blocks[i].index==idx)return &rs->blocks[i];if(rs->nblocks>=rs->capblocks){rs->capblocks=rs->capblocks?rs->capblocks*2:8;rs->blocks=realloc(rs->blocks,rs->capblocks*sizeof(Block));}Block*b=&rs->blocks[rs->nblocks++];block_init(b);b->index=idx;return b;}

static void process_event(ReplyState*rs,const char*event_type,const char*json){
    if(strcmp(event_type,"message_start")==0){long long it=find_int(json,"input_tokens");long long cr=find_int(json,"cache_read_input_tokens");if(it)rs->input_tokens+=it;if(cr)rs->cache_read+=cr;}
    else if(strcmp(event_type,"content_block_start")==0){int idx=(int)find_int(json,"index");Block*b=rs_get_block(rs,idx);char *typ=find_string_unescaped(json,"type");if(typ){if(strcmp(typ,"thinking")==0)b->type=0;else if(strcmp(typ,"text")==0)b->type=1;else if(strcmp(typ,"tool_use")==0)b->type=2;free(typ);}if(b->type==0){b->thinking=malloc(1);b->thinking[0]=0;b->signature=malloc(1);b->signature[0]=0;}if(b->type==1){b->text=malloc(1);b->text[0]=0;}if(b->type==2){b->tool_id=malloc(1);b->tool_id[0]=0;b->tool_name=malloc(1);b->tool_name[0]=0;b->tool_input_raw=malloc(1);b->tool_input_raw[0]=0;}}
    else if(strcmp(event_type,"content_block_delta")==0){int idx=(int)find_int(json,"index");Block*b=rs_get_block(rs,idx);char *th=find_string_unescaped(json,"thinking");if(th&&b->type==0){size_t o=strlen(b->thinking);size_t n=strlen(th);b->thinking=realloc(b->thinking,o+n+1);strcat(b->thinking,th);free(th);}char *sg=find_string_unescaped(json,"signature");if(sg&&b->type==0){size_t o=strlen(b->signature);size_t n=strlen(sg);b->signature=realloc(b->signature,o+n+1);strcat(b->signature,sg);free(sg);}char *txt=find_string_unescaped(json,"text");if(txt&&b->type==1){size_t o=strlen(b->text);size_t n=strlen(txt);b->text=realloc(b->text,o+n+1);strcat(b->text,txt);free(txt);}char *pj=find_string_unescaped(json,"partial_json");if(pj&&b->type==2){size_t o=strlen(b->tool_input_raw);size_t n=strlen(pj);b->tool_input_raw=realloc(b->tool_input_raw,o+n+1);strcat(b->tool_input_raw,pj);free(pj);}}
    else if(strcmp(event_type,"message_delta")==0){char *sr=find_string_unescaped(json,"stop_reason");if(sr){strncpy(rs->stop_reason,sr,sizeof(rs->stop_reason)-1);free(sr);}long long ot=find_int(json,"output_tokens");if(ot)rs->output_tokens+=ot;}
}

static void parse_sse(const char *data,size_t len,ReplyState*rs){
    const char *p=data;const char *end=data+len;char event_name[128]={0};DynBuf dbuf;db_init(&dbuf);
    while(p<end){const char *line_end=strchr(p,'\n');if(!line_end)line_end=end;size_t linelen=line_end-p;char line[4096];if(linelen>=sizeof(line))linelen=sizeof(line)-1;memcpy(line,p,linelen);line[linelen]=0;if(linelen&&line[linelen-1]=='\r')line[linelen-1]=0;
        if(line[0]==':'){}
        else if(strncmp(line,"event:",6)==0){const char *v=line+6;while(*v&&isspace((unsigned char)*v))v++;strncpy(event_name,v,sizeof(event_name)-1);}
        else if(strncmp(line,"data:",5)==0){const char *v=line+5;while(*v&&isspace((unsigned char)*v))v++;db_append(&dbuf,v,strlen(v));db_append(&dbuf,"\n",1);}
        else if(line[0]==0){if(event_name[0]&&dbuf.len>0){char *json_str=malloc(dbuf.len+1);memcpy(json_str,dbuf.data,dbuf.len);json_str[dbuf.len]=0;while(dbuf.len&&(json_str[dbuf.len-1]=='\n'||json_str[dbuf.len-1]=='\r'))json_str[--dbuf.len]=0;process_event(rs,event_name,json_str);free(json_str);dbuf.len=0;free(dbuf.data);dbuf.data=NULL;dbuf.cap=0;event_name[0]=0;}}
        p=line_end+1;}
    free(dbuf.data);
}
static char *decode_chunked(const char *data,size_t len,size_t *out_len){
    DynBuf out;db_init(&out);const unsigned char *p=(const unsigned char*)data;const unsigned char *end=p+len;
    while(p<end){const unsigned char *e=strchr(p,'\n');if(!e)break;size_t szlen=e-p;char szbuf[64];if(szlen>=sizeof(szbuf))szlen=sizeof(szbuf)-1;memcpy(szbuf,p,szlen);szbuf[szlen]=0;if(szlen&&szbuf[szlen-1]=='\r')szbuf[szlen-1]=0;char *semi=strchr(szbuf,';');if(semi)*semi=0;unsigned long sz=strtoul(szbuf,NULL,16);p=e+1;if(sz==0)break;if(p+sz>end)break;db_append(&out,(const char*)p,sz);p+=sz;if(p+2<=end&&p[0]=='\r'&&p[1]=='\n')p+=2;}
    *out_len=out.len;char *res=malloc(out.len+1);memcpy(res,out.data,out.len);res[out.len]=0;free(out.data);return res;
}

/* send request */
static int send_http(const char *host,int port,const char *path,const char *body,const char *api_key,ReplyState *rs){
    int s=connect_host(host,port);if(s<0)return 0;
    char hdr[4096];int blen=strlen(body);snprintf(hdr,sizeof(hdr),"POST %s HTTP/1.1\r\nHost: %s:%d\r\nContent-Length: %d\r\nx-api-key: %s\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nConnection: close\r\n\r\n",path,host,port,blen,api_key);
    write(s,hdr,strlen(hdr));write(s,body,blen);
    char buf[8192];size_t hdr_len=0;while(1){ssize_t r=read(s,buf+hdr_len,1);if(r<=0)break;hdr_len+=r;if(hdr_len>=4&&memcmp(buf+hdr_len-4,"\r\n\r\n",4)==0)break;}
    int status=0;sscanf(buf,"%*s %d",&status);
    DynBuf resp;db_init(&resp);char tmp[4096];while(1){ssize_t r=read(s,tmp,sizeof(tmp));if(r<=0)break;db_append(&resp,tmp,r);}close(s);
    if(status!=200){printf("ERROR %d\n",status);free(resp.data);return 0;}
    size_t sse_len;char *sse=decode_chunked(resp.data,resp.len,&sse_len);parse_sse(sse,sse_len,rs);free(sse);free(resp.data);return 1;
}

/* tool execution */
static char *run_tool(const char *name,const char *input_json,int *is_err){
    *is_err=0;
    if(strcmp(name,"measure")==0){
        char *txt=find_string_unescaped(input_json,"text");
        char *unit=find_string_unescaped(input_json,"unit");
        if(!txt||!unit){if(txt)free(txt);if(unit)free(unit);*is_err=1;return strdup("error");}
        long long len=0;
        if(strcmp(unit,"code_points")==0)len=utf8_codepoint_count(txt);
        else if(strcmp(unit,"utf8_bytes")==0)len=strlen(txt);
        else if(strcmp(unit,"utf16_units")==0)len=utf16_units(txt);
        else {*is_err=1;char *r=malloc(64);snprintf(r,64,"unsupported unit: %s",unit);free(txt);free(unit);return r;}
        char *out=malloc(32);snprintf(out,32,"%lld",len);free(txt);free(unit);return out;
    }else if(strcmp(name,"reverse")==0){
        char *txt=find_string_unescaped(input_json,"text");if(!txt)return strdup("");
        char *rev=reverse_codepoints(txt);free(txt);return rev;
    }else{
        *is_err=1;char *r=malloc(64);snprintf(r,64,"unknown tool: %s",name);return r;
    }
}

