use std::env;
use std::fs::File;
use std::io::Read;
use std::path::Path;

fn read_varint(data: &[u8], mut pos: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut shift = 0;
    let mut len = 0;
    loop {
        if pos >= data.len() { break; }
        let b = data[pos];
        pos += 1;
        len += 1;
        result |= ((b & 0x7F) as u64) << shift;
        if b & 0x80 == 0 { break; }
        shift += 7;
    }
    (result, len)
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xffffffff;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}

fn escape_text(s: &[u8]) -> String {
    let mut out = String::new();
    out.push('"');
    for &b in s {
        match b {
            b'\\' => out.push_str("\\\\"),
            b'"' => out.push_str("\\\""),
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            b'\t' => out.push_str("\\t"),
            0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{:02X}", b)),
        }
    }
    out.push('"');
    out
}

fn format_value(serial: u64, data: &[u8], is_real: bool) -> String {
    if serial == 0 {
        return "NULL".to_string();
    }
    if is_real {
        // real is stored as f64
        if data.len() < 8 { return "NULL".to_string(); }
        let mut bytes = [0u8;8];
        bytes.copy_from_slice(&data[..8]);
        let v = f64::from_be_bytes(bytes);
        // format with enough precision, plain notation
        let s = format!("{:.17}", v);
        let s = s.trim_end_matches('0');
        if s.ends_with('.') { s.to_string() + "0" } else { s.to_string() }
    } else if serial <= 6 {
        // integer
        let size = match serial {
            1 => 1,2=>2,3=>3,4=>4,5=>6,6=>8,_=>1
        };
        let mut n: i128 = 0;
        for &b in &data[..size] {
            n = (n << 8) | b as i128;
        }
        // sign extend
        let bits = size as u32 * 8;
        if bits < 128 {
            let sign = 1i128 << (bits - 1);
            if n & sign != 0 {
                n -= 1i128 << bits;
            }
        }
        n.to_string()
    } else {
        // blob / text
        let len = if serial % 2 == 0 { serial as usize / 2 } else { (serial as usize - 1) / 2 };
        let bytes = &data[..len.min(data.len())];
        if serial % 2 == 1 {
            // text
            if bytes.len() <= 100 {
                escape_text(bytes)
            } else {
                format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc32(bytes))
            }
        } else {
            // blob
            if bytes.len() <= 100 {
                let mut hex = String::from("X'");
                for b in bytes { hex.push_str(&format!("{:02X}", b)); }
                hex.push('\'');
                hex
            } else {
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc32(bytes))
            }
        }
    }
}

struct PageInfo {
    data: Vec<u8>,
    page_size: usize,
}

fn get_page(file: &[u8], page_num: usize, page_size: usize) -> &[u8] {
    let start = (page_num - 1) * page_size;
    let end = start + page_size;
    &file[start..end.min(file.len())]
}

fn parse_page_header(page: &[u8]) -> (u8, u16, u16, u16, u8) {
    let page_type = page[0];
    let first_freeblock = u16::from_be_bytes([page[1], page[2]]);
    let cell_count = u16::from_be_bytes([page[3], page[4]]);
    let start = u16::from_be_bytes([page[5], page[6]]);
    let frag = page[7];
    (page_type, first_freeblock, cell_count, start, frag)
}

fn parse_leaf_cells(page: &[u8], page_size: usize) -> Vec<(i64, Vec<u8>)> {
    let (_pt, _ff, cell_count, _start, _frag) = parse_page_header(page);
    let mut cells = Vec::new();
    for i in 0..cell_count as usize {
        let ptr_off = 8 + i * 2;
        if ptr_off + 2 > page.len() { break; }
        let off = u16::from_be_bytes([page[ptr_off], page[ptr_off + 1]]) as usize;
        if off >= page_size { continue; }
        let cell_slice = &page[off..];
        let (payload_size, len1) = read_varint(cell_slice, 0);
        let pos1 = len1;
        if pos1 >= cell_slice.len() { continue; }
        let (rowid, len2) = read_varint(cell_slice, pos1);
        let pos2 = pos1 + len2;
        let payload_len = payload_size as usize;
        let payload_start = pos2;
        let payload_end = (off + payload_start + payload_len).min(page_size);
        let payload_bytes = if payload_end > off + payload_start {
            page[off + payload_start..payload_end].to_vec()
        } else { Vec::new() };
        cells.push((rowid as i64, payload_bytes));
    }
    cells
}

fn parse_record(payload: &[u8], col_count: usize) -> Vec<Option<String>> {
    if payload.is_empty() { return vec![None; col_count]; }
    let (header_size, hlen) = read_varint(payload, 0);
    let mut pos = hlen;
    let header_end = pos + header_size as usize;
    let mut serials = Vec::new();
    while pos < header_end && serials.len() < col_count {
        let (s, l) = read_varint(payload, pos);
        serials.push(s);
        pos += l;
    }
    let data_start = header_end;
    let data = &payload[data_start..];
    let mut values = Vec::new();
    let mut off = 0;
    for &s in &serials {
        if s == 0 {
            values.push(None);
            continue;
        }
        if s <= 6 {
            let sz = match s {1=>1,2=>2,3=>3,4=>4,5=>6,6=>8,_=>1};
            let bytes = &data[off..off+sz];
            off += sz;
            // interpret as integer, we will format later
            let mut v = Vec::new();
            v.extend_from_slice(bytes);
            // pad to 8 for formatting
            while v.len() < 8 { v.push(0); }
            values.push(Some(format_value(s, &v, false)));
        } else if s == 7 {
            values.push(Some("X''".to_string()));
        } else {
            let len = if s % 2 == 0 { s as usize / 2 } else { (s as usize - 1)/2 };
            let bytes = &data[off..off+len];
            off += len;
            let is_text = s % 2 == 1;
            values.push(Some(format_value(s, bytes, false)));
        }
    }
    // pad missing columns
    while values.len() < col_count {
        values.push(None);
    }
    values
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = &args[1];
    let path = Path::new(dir).join("db.sqlite");
    let mut file = File::open(&path).expect("open");
    let mut buf = Vec::new();
    file.read_to_end(&mut buf).expect("read");
    if buf.len() < 100 { return; }
    let page_size = {
        let v = u16::from_be_bytes([buf[16], buf[17]]) as usize;
        if v == 1 { 65536 } else { v }
    };
    let reserved = u16::from_be_bytes([buf[20], buf[21]]) as usize;

    // read sqlite_schema
    let schema_page = get_page(&buf, 1, page_size);
    // page 1 header is 100 bytes, data starts at 100
    let page1_data = &schema_page[100..];
    // for simplicity, assume sqlite_schema root page is 1 and we can parse it as leaf
    // We'll just scan for CREATE TABLE statements in the file to get tables
    // Simpler: parse sqlite_schema via brute force leaf parsing
    let cells = parse_leaf_cells(page1_data, page_size);
    let mut tables_meta = Vec::new();
    for (rowid, payload) in cells {
        // parse record for sqlite_schema
        let vals = parse_record(&payload, 5);
        // type, name, tbl_name, rootpage, sql
        let typ = vals[0].as_deref().unwrap_or("");
        if typ != "table" { continue; }
        let name = vals[1].as_deref().unwrap_or("").to_string();
        if name.starts_with("sqlite_") { continue; }
        let rootpage_str = vals[3].as_deref().unwrap_or("0");
        let rootpage: u32 = rootpage_str.parse().unwrap_or(0);
        let sql = vals[4].as_deref().unwrap_or("").to_string();
        tables_meta.push((name, rootpage, sql));
    }
    tables_meta.sort_by(|a,b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let mut first = true;
    for (tname, rootpage, sql) in tables_meta {
        // parse columns from CREATE TABLE
        let cols = parse_columns_from_sql(&sql);
        // collect rows
        let rows = collect_table_rows(&buf, page_size, reserved, rootpage, &cols);
        // output
        if !first { println!(); }
        first = false;
        println!("TABLE {} rows={}", tname, rows.len());
        print!("COLUMNS ");
        for (i,c) in cols.iter().enumerate() {
            if i>0 { print!(", "); }
            print!("{}", c);
        }
        println!();
        for (rowid, vals) in rows {
            print!("{}: ", rowid);
            for (i,v) in vals.iter().enumerate() {
                if i>0 { print!(", "); }
                print!("{}", v);
            }
            println!();
        }
    }
}

fn parse_columns_from_sql(sql: &str) -> Vec<String> {
    let lower = sql.to_lowercase();
    if let Some(idx) = lower.find("create table") {
        let rest = &sql[idx+12..];
        let mut i = 0;
        while i < rest.len() && rest.as_bytes()[i].is_ascii_whitespace() { i+=1; }
        // skip table name
        let mut j = i;
        while j < rest.len() && !rest.as_bytes()[j].is_ascii_whitespace() && rest.as_bytes()[j] != '(' {
            j+=1;
        }
        // find '('
        if let Some(p) = rest[j..].find('(') {
            let after = &rest[j+p+1..];
            // find matching ')'
            let mut depth = 1;
            let mut end = 0;
            for (k,ch) in after.char_indices() {
                if ch=='(' { depth+=1; }
                if ch==')' { depth-=1; if depth==0 { end=k; break; } }
            }
            let defs = &after[..end];
            // split by commas not in parens
            let mut cols = Vec::new();
            let mut cur = String::new();
            let mut d = 0;
            for ch in defs.chars() {
                if ch=='(' { d+=1; }
                if ch==')' { d-=1; }
                if ch==',' && d==0 {
                    let col = parse_column_name(&cur);
                    cols.push(col);
                    cur.clear();
                } else {
                    cur.push(ch);
                }
            }
            if !cur.trim().is_empty() {
                let col = parse_column_name(&cur);
                cols.push(col);
            }
            return cols;
        }
    }
    Vec::new()
}

fn parse_column_name(def: &str) -> String {
    let t = def.trim();
    let mut chars = t.chars();
    if let Some('"') = chars.clone().next() {
        // quoted
        let mut s = String::new();
        let mut in_q = false;
        for c in t.chars() {
            if c=='"' { in_q=!in_q; continue; }
            if in_q { s.push(c); }
        }
        s
    } else {
        // first token
        let mut name = String::new();
        for c in t.chars() {
            if c.is_ascii_whitespace() { break; }
            name.push(c);
        }
        name
    }
}

fn collect_table_rows(buf: &[u8], page_size: usize, _reserved: usize, rootpage: u32, cols: &[String]) -> Vec<(i64, Vec<String>)> {
    // simplified: assume leaf page
    let page_num = rootpage as usize;
    if page_num == 0 { return Vec::new(); }
    let page = get_page(buf, page_num, page_size);
    let cells = parse_leaf_cells(page, page_size);
    let mut rows = Vec::new();
    for (rowid, payload) in cells {
        let vals = parse_record(&payload, cols.len());
        let mut out_vals = Vec::new();
        for (i, v_opt) in vals.iter().enumerate() {
            if let Some(v) = v_opt {
                out_vals.push(v.clone());
            } else {
                out_vals.push("NULL".to_string());
            }
        }
        // pad
        while out_vals.len() < cols.len() {
            out_vals.push("NULL".to_string());
        }
        rows.push((rowid, out_vals));
    }
    rows.sort_by_key(|x| x.0);
    rows
}

use std::env;
use std::fs::File;
use std::io::Read;
use std::path::Path;

fn read_varint(data: &[u8], mut pos: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut shift = 0;
    let mut len = 0;
    loop {
        let b = data[pos];
        pos += 1;
        len += 1;
        result |= ((b & 0x7F) as u64) << shift;
        if b & 0x80 == 0 { break; }
        shift += 7;
    }
    (result, len)
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xffffffff;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xedb88320; } else { crc >>= 1; }
        }
    }
    !crc
}

fn escape_text(s: &[u8]) -> String {
    let mut out = String::new();
    out.push('"');
    for &b in s {
        match b {
            b'\\' => out.push_str("\\\\"),
            b'"' => out.push_str("\\\""),
            b'\n' => out.push_str("\\n"),
            b'\r' => out.push_str("\\r"),
            b'\t' => out.push_str("\\t"),
            0x20..=0x7e => out.push(b as char),
            _ => out.push_str(&format!("\\x{:02X}", b)),
        }
    }
    out.push('"');
    out
}

fn format_value(serial: u64, data: &[u8]) -> String {
    if serial == 0 { return "NULL".to_string(); }
    if serial >= 9 {
        let len = if serial % 2 == 0 { serial as usize / 2 } else { (serial as usize - 1) / 2 };
        let bytes = &data[..len.min(data.len())];
        if serial % 2 == 1 {
            if bytes.len() <= 100 { escape_text(bytes) }
            else { format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc32(bytes)) }
        } else {
            if bytes.len() <= 100 {
                let mut hex = String::from("X'");
                for b in bytes { hex.push_str(&format!("{:02X}", b)); }
                hex.push('\'');
                hex
            } else {
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc32(bytes))
            }
        }
    } else if serial <= 6 {
        let sz = match serial {1=>1,2=>2,3=>3,4=>4,5=>6,6=>8,_=>1};
        let bytes = &data[..sz.min(data.len())];
        let mut n: i128 = 0;
        for &b in bytes { n = (n << 8) | b as i128; }
        let bits = sz as u32 * 8;
        if bits < 128 && bits > 0 {
            let sign = 1i128 << (bits - 1);
            if n & sign != 0 { n -= 1i128 << bits; }
        }
        n.to_string()
    } else {
        "NULL".to_string()
    }
}

fn get_page(file: &[u8], page_num: usize, page_size: usize) -> &[u8] {
    let start = (page_num - 1) * page_size;
    let end = (start + page_size).min(file.len());
    &file[start..end]
}

fn parse_page_header(page: &[u8]) -> (u8, u16, u16, u16) {
    let page_type = page[0];
    let cell_count = u16::from_be_bytes([page[3], page[4]]);
    let cell_start = u16::from_be_bytes([page[5], page[6]]) as usize;
    (page_type, cell_count, cell_start, 0)
}

fn parse_leaf_cells(page: &[u8], page_size: usize) -> Vec<(i64, Vec<u8>)> {
    let (page_type, cell_count, _) = parse_page_header(page);
    if page_type != 0x0d { return Vec::new(); }
    let mut cells = Vec::new();
    for i in 0..cell_count as usize {
        let ptr_off = 8 + i * 2;
        if ptr_off + 2 > page.len() { break; }
        let off = u16::from_be_bytes([page[ptr_off], page[ptr_off + 1]]) as usize;
        if off >= page_size { continue; }
        let cell_slice = &page[off..];
        let (payload_size, len1) = read_varint(cell_slice, 0);
        let pos1 = len1;
        if pos1 >= cell_slice.len() { continue; }
        let (rowid, len2) = read_varint(cell_slice, pos1);
        let pos2 = pos1 + len2;
        let payload_len = payload_size as usize;
        let payload_start = off + pos2;
        let payload_end = (payload_start + payload_len).min(page_size);
        let payload_bytes = if payload_end > payload_start {
            page[payload_start..payload_end].to_vec()
        } else { Vec::new() };
        cells.push((rowid as i64, payload_bytes));
    }
    cells
}

fn parse_record(payload: &[u8], col_count: usize) -> Vec<Option<String>> {
    if payload.is_empty() { return vec![None; col_count]; }
    let (header_size, hlen) = read_varint(payload, 0);
    let mut pos = hlen;
    let header_end = pos + header_size as usize;
    let mut serials = Vec::new();
    while pos < header_end && serials.len() < col_count {
        let (s, l) = read_varint(payload, pos);
        serials.push(s);
        pos += l;
    }
    let data_start = header_end;
    let data = &payload[data_start..];
    let mut values = Vec::new();
    let mut off = 0;
    for &s in &serials {
        if s == 0 { values.push(None); continue; }
        if s <= 6 {
            let sz = match s {1=>1,2=>2,3=>3,4=>4,5=>6,6=>8,_=>1};
            let bytes = &data[off..off+sz.min(data.len()-off)];
            off += sz;
            values.push(Some(format_value(s, bytes)));
        } else {
            let len = if s % 2 == 0 { s as usize / 2 } else { (s as usize - 1)/2 };
            let bytes = &data[off..off+len.min(data.len()-off)];
            off += len;
            values.push(Some(format_value(s, bytes)));
        }
    }
    while values.len() < col_count { values.push(None); }
    values
}

fn collect_table_rows(buf: &[u8], page_size: usize, rootpage: u32, cols: usize) -> Vec<(i64, Vec<String>)> {
    let mut rows = Vec::new();
    let mut stack = vec![rootpage as usize];
    while let Some(pn) = stack.pop() {
        if pn == 0 { continue; }
        let page = get_page(buf, pn, page_size);
        if page.len() < 8 { continue; }
        let page_type = page[0];
        let cell_count = u16::from_be_bytes([page[3], page[4]]) as usize;
        match page_type {
            0x0d => {
                for i in 0..cell_count {
                    let ptr_off = 8 + i * 2;
                    if ptr_off + 2 > page.len() { break; }
                    let off = u16::from_be_bytes([page[ptr_off], page[ptr_off + 1]]) as usize;
                    if off >= page_size { continue; }
                    let cell_slice = &page[off..];
                    let (payload_size, len1) = read_varint(cell_slice, 0);
                    let pos1 = len1;
                    if pos1 >= cell_slice.len() { continue; }
                    let (rowid, len2) = read_varint(cell_slice, pos1);
                    let pos2 = pos1 + len2;
                    let payload_start = off + pos2;
                    let payload_len = payload_size as usize;
                    let payload_end = (payload_start + payload_len).min(page_size);
                    let payload_bytes = if payload_end > payload_start {
                        page[payload_start..payload_end].to_vec()
                    } else { Vec::new() };
                    let vals = parse_record(&payload_bytes, cols);
                    let mut out = Vec::new();
                    for v in vals { out.push(v.unwrap_or_else(|| "NULL".to_string())); }
                    while out.len() < cols { out.push("NULL".to_string()); }
                    rows.push((rowid as i64, out));
                }
            }
            0x05 => {
                for i in 0..cell_count {
                    let ptr_off = 8 + i * 2;
                    if ptr_off + 2 > page.len() { break; }
                    let off = u16::from_be_bytes([page[ptr_off], page[ptr_off + 1]]) as usize;
                    if off >= page_size { continue; }
                    let cell_slice = &page[off..];
                    let (_, len1) = read_varint(cell_slice, 0);
                    let pos1 = len1;
                    if pos1 >= cell_slice.len() { continue; }
                    let (child, _) = read_varint(cell_slice, pos1);
                    stack.push(child as usize);
                }
            }
            _ => {}
        }
    }
    rows.sort_by_key(|x| x.0);
    rows
}

fn parse_columns_from_sql(sql: &str) -> Vec<String> {
    let lower = sql.to_lowercase();
    if let Some(idx) = lower.find("create table") {
        let rest = &sql[idx+12..];
        let mut i = 0;
        while i < rest.len() && rest.as_bytes()[i].is_ascii_whitespace() { i+=1; }
        let mut j = i;
        while j < rest.len() && !rest.as_bytes()[j].is_ascii_whitespace() && rest.as_bytes()[j] != b'(' {
            j+=1;
        }
        if let Some(p) = rest[j..].find('(') {
            let after = &rest[j+p+1..];
            let mut depth = 1;
            let mut end = 0;
            for (k,ch) in after.char_indices() {
                if ch=='(' { depth+=1; }
                if ch==')' { depth-=1; if depth==0 { end=k; break; } }
            }
            let defs = &after[..end];
            let mut cols = Vec::new();
            let mut cur = String::new();
            let mut d = 0;
            for ch in defs.chars() {
                if ch=='(' { d+=1; }
                if ch==')' { d-=1; }
                if ch==',' && d==0 {
                    let col = parse_column_name(&cur);
                    cols.push(col);
                    cur.clear();
                } else { cur.push(ch); }
            }
            if !cur.trim().is_empty() { cols.push(parse_column_name(&cur)); }
            return cols;
        }
    }
    Vec::new()
}

fn parse_column_name(def: &str) -> String {
    let t = def.trim();
    let mut chars = t.chars();
    if let Some('"') = chars.clone().next() {
        let mut s = String::new();
        let mut in_q = false;
        for c in t.chars() {
            if c=='"' { in_q=!in_q; continue; }
            if in_q { s.push(c); }
        }
        s
    } else {
        let mut name = String::new();
        for c in t.chars() {
            if c.is_ascii_whitespace() { break; }
            name.push(c);
        }
        name
    }
}

