    for(int i=0;i<timecnt2;i++) tz->type_idx[i]=buf[off2+44+timecnt2*8+i];
    tz->offs=malloc(sizeof(int)*typecnt2);
    tz->isdst=malloc(typecnt2);
    tz->abbr_idx=malloc(typecnt2);
    int64_t p = off2+44 + timecnt2*8 + timecnt2;
    for(int i=0;i<typecnt2;i++){
        int32_t off = be32s(buf+p); p+=4;
        tz->offs[i]=off;
        tz->isdst[i]=buf[p++];
        tz->abbr_idx[i]=buf[p++];
    }
    tz->abbrs=malloc(charcnt2+1);
    memcpy(tz->abbrs,buf+p,charcnt2); tz->abbrs[charcnt2]=0;
    tz->last_trans = tz->trans[timecnt2-1];
    int64_t data_end = p+charcnt2;
    int64_t nl = data_end;
    while(nl<sz && buf[nl]!='\n') nl++;
    if(nl<sz){
        nl++;
        int64_t st=nl;
        while(nl<sz && buf[nl]!='\n') nl++;
        int len=(int)(nl-st);
        if(len>0){
            char *str=malloc(len+1); memcpy(str,buf+st,len); str[len]=0;
            int i=0;
            parse_name_str(str,&i,tz->std_name);
            int sign_present=0;
            int sign=1;
            if(str[i]=='+'||str[i]=='-'){ sign_present=1; sign=str[i]=='+'?1:-1; i++; }
            tz->std_off = parse_offset_signed(str,&i,sign_present);
            if(isalpha((unsigned char)str[i])||str[i]=='<'){
                tz->has_dst=1;
                parse_name_str(str,&i,tz->dst_name);
                if(str[i]=='+'||str[i]=='-'||isdigit((unsigned char)str[i])){
                    int sp=0; if(str[i]=='+'||str[i]=='-'){sp=1;i++;}
                    tz->dst_off = parse_offset_signed(str,&i,sp);
                }else{
                    tz->dst_off = tz->std_off + 3600;
                }
                if(str[i]==','){
                    i++;
                    if(str[i]=='M'){
                        i++;
                        tz->start_month=0; while(isdigit((unsigned char)str[i])){tz->start_month=tz->start_month*10+str[i]-'0';i++;}
                        if(str[i]=='.'){i++; tz->start_week=0; while(isdigit((unsigned char)str[i])){tz->start_week=tz->start_week*10+str[i]-'0';i++;}
                        if(str[i]=='.'){i++; tz->start_wday=0; while(isdigit((unsigned char)str[i])){tz->start_wday=tz->start_wday*10+str[i]-'0';i++;}
                        if(str[i]=='/'){i++; tz->start_sec=parse_offset_signed(str,&i,0);} else tz->start_sec=7200;
                        }
                    }
                    if(str[i]==','){i++; if(str[i]=='M'){
                        i++; tz->end_month=0; while(isdigit((unsigned char)str[i])){tz->end_month=tz->end_month*10+str[i]-'0';i++;}
                        if(str[i]=='.'){i++; tz->end_week=0; while(isdigit((unsigned char)str[i])){tz->end_week=tz->end_week*10+str[i]-'0';i++;}
                        if(str[i]=='.'){i++; tz->end_wday=0; while(isdigit((unsigned char)str[i])){tz->end_wday=tz->end_wday*10+str[i]-'0';i++;}
                        if(str[i]=='/'){i++; tz->end_sec=parse_offset_signed(str,&i,0);} else tz->end_sec=7200;
                    }}
                }
            }
            tz->has_posix=1;
            free(str);
        }
    }
    free(buf);
    return tz;
}

static void tz_offset_for_t(Tz *tz,int64_t t,int *off,char *abbr){
    if(tz->timecnt==0){
        *off=tz->offs[0]; strcpy(abbr, tz->abbrs + tz->abbr_idx[0]); return;
    }
    if(t < tz->trans[0]){
        *off=tz->offs[0]; strcpy(abbr, tz->abbrs + tz->abbr_idx[0]); return;
    }
    if(t <= tz->last_trans){
        int lo=0,hi=tz->timecnt-1,ans=0;
        while(lo<=hi){int mid=(lo+hi)/2; if(tz->trans[mid]<=t){ans=mid; lo=mid+1;} else hi=mid-1;}
        int type=tz->type_idx[ans];
        *off=tz->offs[type];
        strcpy(abbr, tz->abbrs + tz->abbr_idx[type]);
        return;
    }
    if(tz->has_posix){
        int isdst = posix_is_dst(tz,t);
        if(isdst){ *off=tz->dst_off; strcpy(abbr,tz->dst_name); }
        else { *off=tz->std_off; strcpy(abbr,tz->std_name); }
    }else{
        int type=tz->type_idx[tz->timecnt-1];
        *off=tz->offs[type];
        strcpy(abbr, tz->abbrs + tz->abbr_idx[type]);
    }
}

static void fmt_offset(char *out,int off){
    int sec = abs(off);
    int h = sec/3600; sec%=3600; int m=sec/60; sec%=60;
    char sign = off>=0?'+':'-';
    if(sec==0) sprintf(out,"%c%02d:%02d",sign,h,m);
    else sprintf(out,"%c%02d:%02d:%02d",sign,h,m,sec);
}

int main(int argc,char **argv){
    if(argc<2) return 0;
    char dir[1024]; strcpy(dir,argv[1]);
    char qpath[2048]; snprintf(qpath,sizeof qpath,"%s/queries.txt",dir);
    FILE *qf=fopen(qpath,"r"); if(!qf) return 0;
    char line[1024];
    Tz *cache[256]; char cache_name[256][256]; int cache_cnt=0;
    while(fgets(line,sizeof line,qf)){
        line[strcspn(line,"\r\n")]=0;
        if(line[0]==0) continue;
        char cmd[16], fname[256], arg[256];
        sscanf(line,"%15s %255s %255s",cmd,fname,arg);
        Tz *tz=NULL;
        for(int i=0;i<cache_cnt;i++) if(strcmp(cache_name[i],fname)==0){tz=cache[i];break;}
        if(!tz){
            char p[2048]; snprintf(p,sizeof p,"%s/%s",dir,fname);
            tz=load_tz(p);
            strcpy(cache_name[cache_cnt++],fname); cache[cache_cnt-1]=tz;
        }
        if(strcmp(cmd,"UTC")==0){
            int64_t t=atoll(arg);
            int off; char abbr[64];
            tz_offset_for_t(tz,t,&off,abbr);
            int64_t tloc=t+off;
            int y; unsigned mo,d; int h,mi,s;
            unix_to_civil(tloc,&y,&mo,&d,&h,&mi,&s);
            char offs[16]; fmt_offset(offs,off);
            printf("%s -> %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,y,mo,d,h,mi,s,offs,abbr);
        }else if(strcmp(cmd,"LOCAL")==0){
            int y,m,d,h,mi,s;
            sscanf(arg,"%d-%d-%dT%d:%d:%d",&y,&m,&d,&h,&mi,&s);
            int64_t C=civil_to_unix(y,m,d,h,mi,s);
            int found=0;
            int64_t best_t[2]; int best_off[2]; char best_abbr[2][64];
            int cnt=0;
            int cand_offs[256]; int cand_cnt=0;
            for(int i=0;i<tz->typecnt;i++) cand_offs[cand_cnt++]=tz->offs[i];
            if(tz->has_posix){ cand_offs[cand_cnt++]=tz->std_off; cand_offs[cand_cnt++]=tz->dst_off; }
            for(int k=0;k<cand_cnt;k++){
                int off=cand_offs[k];
                int64_t t=C - off;
                int off2; char abbr[64];
                tz_offset_for_t(tz,t,&off2,abbr);
                if(off2==off){
                    best_t[cnt]=t; best_off[cnt]=off2; strcpy(best_abbr[cnt],abbr); cnt++; if(cnt==2) break;
                }
            }
            if(cnt==1){
                char offs[16]; fmt_offset(offs,best_off[0]);
                printf("%s -> %lld %s %s\n",line,(long long)best_t[0],offs,best_abbr[0]);
            }else if(cnt==2){
                char o1[16],o2[16]; fmt_offset(o1,best_off[0]); fmt_offset(o2,best_off[1]);
                printf("%s -> %lld %s %s | %lld %s %s\n",line,(long long)best_t[0],o1,best_abbr[0],(long long)best_t[1],o2,best_abbr[1]);
            }else{
                int64_t gap_t=0; int gap_off=0; char gap_abbr[64]={0}; int gap_found=0;
                for(int i=0;i<tz->timecnt;i++){
                    int64_t tr=tz->trans[i];
                    int type_before=(i==0)?0:tz->type_idx[i-1];
                    int off_before=tz->offs[type_before];
                    int type_after=tz->type_idx[i];
                    int off_after=tz->offs[type_after];
                    if(off_after>off_before){
                        int64_t start=C? tr+off_before : 0;
                        int64_t end=tr+off_after;
                        if(C>=tr+off_before && C<tr+off_after){
                            gap_t=C - off_before;
                            int off2; char abbr[64];
                            tz_offset_for_t(tz,gap_t,&off2,abbr);
                            gap_off=off2; strcpy(gap_abbr,abbr);
                            gap_found=1; break;
                        }
                    }
                }
                if(!gap_found && tz->has_posix){
                    for(int yy=1800;yy<=2399 && !gap_found;yy++){
                        int64_t s=posix_transition(tz,yy,1);
                        int64_t e=posix_transition(tz,yy,0);
                        int off_before=tz->std_off;
                        int off_after=tz->dst_off;
                        if(off_after>off_before){
                            int64_t start_wall=s+off_before;
                            int64_t end_wall=s+off_after;
                            if(C>=start_wall && C<end_wall){
                                gap_t=C - off_before;
                                int off2; char abbr[64];
                                tz_offset_for_t(tz,gap_t,&off2,abbr);
                                gap_off=off2; strcpy(gap_abbr,abbr);
                                gap_found=1; break;
                            }
                        }
                    }
                }
                if(gap_found){
                    int64_t tloc=gap_t+gap_off;
                    int y2; unsigned mo2,d2; int h2,mi2,s2;
                    unix_to_civil(tloc,&y2,&mo2,&d2,&h2,&mi2,&s2);
                    char offs[16]; fmt_offset(offs,gap_off);
                    printf("%s -> GAP %lld %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",
                        line,(long long)gap_t,y2,mo2,d2,h2,mi2,s2,offs,gap_abbr);
                }else{
                    printf("%s -> GAP %lld %s %s\n",line,(long long)0,"?","?");
                }
            }
        }
    }
    fclose(qf);
    return 0;
}

use std::env;
use std::fs;
use std::path::Path;

#[derive(Clone, Copy, Debug)]
struct Rule {
    month: u8,
    week: u8,
    weekday: u8,
    time_sec: i32,
}

#[derive(Debug)]
struct TzInfo {
    trans_times: Vec<i64>,
    trans_type_idx: Vec<u8>,
    type_offsets: Vec<i32>,
    type_abbrev: Vec<String>,
    // footer
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start_rule: Option<Rule>,
    end_rule: Option<Rule>,
    last_trans: i64,
}

fn days_from_civil(y: i32, m: u32, d: u32) -> i64 {
    let y = y as i64;
    let m = m as i64;
    let d = d as i64;
    let y_adj = if m <= 2 { y - 1 } else { y };
    let era = if y_adj >= 0 { y_adj } else { y_adj - 399 } / 400;
    let yoe = y_adj - era * 400;
    let doy = (153 * (m + if m > 2 { -3 } else { 9 }) + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}
fn civil_to_unix(y: i32, m: u32, d: u32, hh: u32, mm: u32, ss: u32) -> i64 {
    let days = days_from_civil(y, m, d);
    days * 86400 + hh as i64 * 3600 + mm as i64 * 60 + ss as i64
}
fn civil_from_days(z: i64) -> (i32, u32, u32) {
    let mut z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (yoe * 365 + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = mp + if mp < 10 { 3 } else { -9 };
    let y = y + if m <= 2 { 1 } else { 0 };
    (y as i32, m as u32, d as u32)
}
fn unix_to_civil(ts: i64) -> (i32, u32, u32, u32, u32, u32) {
    let days = ts.div_euclid(86400);
    let secs = ts.rem_euclid(86400) as u64;
    let (y, m, d) = civil_from_days(days);
    let hh = (secs / 3600) as u32;
    let mm = ((secs % 3600) / 60) as u32;
    let ss = (secs % 60) as u32;
    (y, m, d, hh, mm, ss)
}
fn format_offset(off: i32) -> String {
    let sign = if off >= 0 { '+' } else { '-' };
    let a = off.abs() as i64;
    let h = a / 3600;
    let m = (a % 3600) / 60;
    let s = a % 60;
    if s != 0 {
        format!("{sign}{h:02}:{m:02}:{s:02}")
    } else {
        format!("{sign}{h:02}:{m:02}")
    }
}
fn days_in_month(y: i32, m: u32) -> u32 {
    match m {
        1 => 31,
        2 => if (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0) { 29 } else { 28 },
        3 => 31,
        4 => 30,
        5 => 31,
        6 => 30,
        7 => 31,
        8 => 31,
        9 => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _ => 31,
    }
}
fn nth_weekday_day(y: i32, m: u32, week: u8, weekday: u8) -> u32 {
    if week == 5 {
        let last = days_in_month(y, m);
        let days_last = days_from_civil(y, m, last);
        let w_last = ((days_last + 4).rem_euclid(7)) as u8;
        let delta = (w_last as i32 - weekday as i32 + 7).rem_euclid(7) as u32;
        last - delta as u32
    } else {
        let days_first = days_from_civil(y, m, 1);
        let w_first = ((days_first + 4).rem_euclid(7)) as u8;
        let delta = (weekday as i32 - w_first as i32 + 7).rem_euclid(7) as u32;
        1 + delta + (week as u32 - 1) * 7
    }
}
fn rule_to_utc(tz: &TzInfo, year: i32, rule: &Rule, is_start: bool) -> i64 {
    let day = nth_weekday_day(year, rule.month as u32, rule.week, rule.weekday);
    let local_ts = civil_to_unix(year, rule.month as u32, day, 0, 0, 0) + rule.time_sec as i64;
    let off = if is_start { tz.std_offset } else { tz.dst_offset.unwrap_or(tz.std_offset + 3600) };
    local_ts + off as i64
}

fn parse_name(bytes: &[u8], mut i: usize) -> (String, usize) {
    if bytes[i] == b'<' {
        let start = i + 1;
        while i < bytes.len() && bytes[i] != b'>' { i += 1; }
        let name = String::from_utf8_lossy(&bytes[start..i]).to_string();
        i += 1;
        (name, i)
    } else {
        let start = i;
        while i < bytes.len() && (bytes[i] as char).is_ascii_alphabetic() { i += 1; }
        (String::from_utf8_lossy(&bytes[start..i]).to_string(), i)
    }
}
fn parse_offset_bytes(bytes: &[u8], mut i: usize) -> (i32, usize) {
    let sign = if bytes[i] == b'-' { -1 } else { 1 };
    i += 1;
    let mut num = String::new();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let h: i64 = num.parse().unwrap_or(0);
    let mut m = 0i64;
    let mut s = 0i64;
    if i < bytes.len() && bytes[i] == b':' {
        i += 1;
        let mut ns = String::new();
        while i < bytes.len() && bytes[i].is_ascii_digit() { ns.push(bytes[i] as char); i += 1; }
        m = ns.parse().unwrap_or(0);
        if i < bytes.len() && bytes[i] == b':' {
            i += 1;
            let mut ns2 = String::new();
            while i < bytes.len() && bytes[i].is_ascii_digit() { ns2.push(bytes[i] as char); i += 1; }
            s = ns2.parse().unwrap_or(0);
        }
    }
    let secs = sign * (h * 3600 + m * 60 + s) as i32;
    (secs, i)
}
fn parse_rule_bytes(bytes: &[u8], mut i: usize) -> (Rule, usize) {
    // M m . w . d [/time]
    assert_eq!(bytes[i], b'M');
    i += 1;
    let mut num = String::new();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let month = num.parse::<u8>().unwrap();
    assert_eq!(bytes[i], b'.'); i += 1;
    num.clear();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let week = num.parse::<u8>().unwrap();
    assert_eq!(bytes[i], b'.'); i += 1;
    num.clear();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let weekday = num.parse::<u8>().unwrap();
    let mut time_sec = 2 * 3600;
    if i < bytes.len() && bytes[i] == b'/' {
        i += 1;
        let (off, ni) = parse_offset_bytes(bytes, i);
        time_sec = off;
        i = ni;
    }
    (Rule { month, week, weekday, time_sec }, i)
}
fn parse_posix(s: &str) -> (String, i32, Option<String>, Option<i32>, Option<Rule>, Option<Rule>) {
    let b = s.as_bytes();
    let mut i = 0;
    let (std_name, ni) = parse_name(b, i); i = ni;
    let (std_off, ni) = parse_offset_bytes(b, i); i = ni;
    let mut dst_name = None;
    let mut dst_off = None;
    if i < b.len() {
        let c = b[i];
        if c.is_ascii_alphabetic() || c == b'<' {
            let (name, ni2) = parse_name(b, i); dst_name = Some(name); i = ni2;
            if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
                let (off, ni2) = parse_offset_bytes(b, i); dst_off = Some(off); i = ni2;
            }
        }
    }
    let mut start_rule = None;
    let mut end_rule = None;
    if i < b.len() && b[i] == b',' {
        i += 1;
        let (r, ni2) = parse_rule_bytes(b, i); start_rule = Some(r); i = ni2;
        if i < b.len() && b[i] == b',' {
            i += 1;
            let (r2, ni2) = parse_rule_bytes(b, i); end_rule = Some(r2); i = ni2;
        }
    }
    (std_name, std_off, dst_name, dst_off, start_rule, end_rule)
}

fn load_tz(path: &Path) -> TzInfo {
    let data = fs::read(path).unwrap();
    // find second TZif header
    let mut hdr = 0;
    for i in 1..data.len().saturating_sub(4) {
        if &data[i..i+4] == b"TZif" {
            hdr = i;
            break;
        }
    }
    let cnt_off = hdr + 20;
    let mut counts = [0i32;6];
    for j in 0..6 {
        counts[j] = i32::from_be_bytes(data[cnt_off + j*4..cnt_off + j*4 +4].try_into().unwrap());
    }
    let timecnt = counts[3] as usize;
    let typecnt = counts[4] as usize;
    let charcnt = counts[5] as usize;
    let mut off = hdr + 44;
    let mut trans_times = Vec::new();
    for _ in 0..timecnt {
        let v = i64::from_be_bytes(data[off..off+8].try_into().unwrap());
        trans_times.push(v);
        off += 8;
    }
    let mut trans_type = Vec::new();
    for _ in 0..timecnt {
        trans_type.push(data[off]);
        off += 1;
    }
    let mut type_offsets = Vec::new();
    let mut type_isdst = Vec::new();
    let mut type_abbrev_idx = Vec::new();
    for _ in 0..typecnt {
        let offs = i32::from_be_bytes(data[off..off+4].try_into().unwrap());
        let isdst = data[off+4];
        let abbr = data[off+5];
        type_offsets.push(offs);
        type_isdst.push(isdst);
        type_abbrev_idx.push(abbr);
        off += 6;
    }
    // abbrevs
    let mut abbrevs = Vec::new();
    let mut start = off;
    let end_abbr = off + charcnt;
    while start < end_abbr {
        if let Some(pos) = data[start..end_abbr].iter().position(|&b| b == 0) {
            let s = String::from_utf8_lossy(&data[start..start+pos]).to_string();
            abbrevs.push(s);
            start += pos + 1;
        } else {
            break;
        }
    }
    // footer
    let mut foot_start = off;
    while foot_start < data.len() && data[foot_start] != b'\n' { foot_start += 1; }
    foot_start += 1;
    let mut foot_end = foot_start;
    while foot_end < data.len() && data[foot_end] != b'\n' { foot_end += 1; }
    let tz_str = String::from_utf8_lossy(&data[foot_start..foot_end]).to_string();
    let (std_name, std_off, dst_name_opt, dst_off_opt, start_rule_opt, end_rule_opt) = parse_posix(&tz_str);
    let dst_offset = dst_off_opt.or_else(|| if dst_name_opt.is_some() { Some(std_off + 3600) } else { None });
    // build type abbrev strings
    let mut type_abbrev = Vec::new();
    for idx in type_abbrev_idx {
        let s = if (idx as usize) < abbrevs.len() { abbrevs[idx as usize].clone() } else { String::new() };
        type_abbrev.push(s);
    }
    let last_trans = *trans_times.last().unwrap_or(&i64::MIN);
    TzInfo {
        trans_times,
        trans_type_idx: trans_type,
        type_offsets,
        type_abbrev,
        std_name,
        std_offset: std_off,
        dst_name: dst_name_opt,
        dst_offset,
        start_rule: start_rule_opt,
        end_rule: end_rule_opt,
        last_trans,
    }
}

fn get_offset_info(tz: &TzInfo, t: i64) -> (i32, String) {
    if !tz.trans_times.is_empty() {
        if t < tz.trans_times[0] {
            let off = tz.type_offsets[0];
            let ab = tz.type_abbrev[0].clone();
            return (off, ab);
        }
        if t <= tz.last_trans {
            let idx = tz.trans_times.partition_point(|&x| x <= t);
            let ti = tz.trans_type_idx[idx - 1] as usize;
            let off = tz.type_offsets[ti];
            let ab = tz.type_abbrev[ti].clone();
            return (off, ab);
        }
    }
    // footer
    if tz.dst_name.is_some() {
        let (_, _, _, _, start_rule, end_rule) = parse_posix(&format!("{} {}", tz.std_name, tz.std_offset)); // dummy
        // we already have rules
        let year = {
            let (y,_,_,_,_,_) = unix_to_civil(t);
            y
        };
        let mut dst_active = false;
        if let (Some(sr), Some(er)) = (&tz.start_rule, &tz.end_rule) {
            for y_off in [-1,0,1] {
                let ytry = year + y_off;
                let start_utc = rule_to_utc(tz, ytry, sr, true);
                let end_utc = rule_to_utc(tz, ytry, er, false);
                if t >= start_utc && t < end_utc {
                    dst_active = true;
                    break;
                }
            }
        }
        if dst_active {
            let off = tz.dst_offset.unwrap_or(tz.std_offset + 3600);
            let ab = tz.dst_name.clone().unwrap_or_default();
            return (off, ab);
        }
    }
    (tz.std_offset, tz.std_name.clone())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = Path::new(&args[1]);
    let queries_path = dir.join("queries.txt");
    let queries = fs::read_to_string(&queries_path).unwrap();
    let mut tz_map = std::collections::HashMap::new();
    for entry in fs::read_dir(dir).unwrap() {
        let p = entry.unwrap().path();
        if let Some(name) = p.file_name().and_then(|s| s.to_str()) {
            if name.ends_with(".tzif") {
                let tz = load_tz(&p);
                tz_map.insert(name.to_string(), tz);
            }
        }
    }
    let mut out = Vec::new();
    for line in queries.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.split_whitespace().collect();
        let qtype = parts[0];
        let file = parts[1];
        let rest = parts[2..].join(" ");
        let tz = tz_map.get(file).expect("tz missing");
        if qtype == "UTC" {
            let t: i64 = rest.parse().unwrap();
            let (off, abbr) = get_offset_info(tz, t);
            let local_sec = t - off as i64;
            let (y,m,d,hh,mm,ss) = unix_to_civil(local_sec);
            let local_str = format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y,m,d,hh,mm,ss);
            let off_str = format_offset(off);
            out.push(format!("{} -> {}{} {}", line, local_str, off_str, abbr));
        } else {
            // LOCAL
            let (y,m,d,hh,mm,ss) = {
                let s = rest;
                let date = &s[0..10];
                let time = &s[11..19];
                let y: i32 = date[0..4].parse().unwrap();
                let m: u32 = date[5..7].parse().unwrap();
                let d: u32 = date[8..10].parse().unwrap();
                let hh: u32 = time[0..2].parse().unwrap();
                let mm: u32 = time[3..5].parse().unwrap();
                let ss: u32 = time[6..8].parse().unwrap();
                (y,m,d,hh,mm,ss)
            };
            let local_ts = civil_to_unix(y,m,d,hh,mm,ss);
            // candidate offsets
            let mut cand_offsets = Vec::new();
            for &o in &tz.type_offsets { cand_offsets.push(o); }
            cand_offsets.push(tz.std_offset);
            if let Some(doff) = tz.dst_offset { cand_offsets.push(doff); }
            cand_offsets.sort();
            cand_offsets.dedup();
            let mut sols = Vec::new();
            for &off in &cand_offsets {
                let t_candidate = local_ts + off as i64;
                let (off2, _) = get_offset_info(tz, t_candidate);
                if off2 == off {
                    sols.push((t_candidate, off));
                }
            }
            if sols.is_empty() {
                // gap detection
                let mut found = false;
                // check tz transitions
                for i in 0..tz.trans_times.len() {
                    let t_trans = tz.trans_times[i];
                    let type_before_idx = if i==0 {0} else { tz.trans_type_idx[i-1] as usize };
                    let type_after_idx = tz.trans_type_idx[i] as usize;
                    let off_before = tz.type_offsets[type_before_idx];
                    let off_after = tz.type_offsets[type_after_idx];
                    if off_after < off_before {
                        let start_local = t_trans - off_before as i64;
                        let end_local = t_trans - off_after as i64;
                        if local_ts >= start_local && local_ts < end_local {
                            let t_gap = local_ts + off_before as i64;
                            let (off_act, abbr) = get_offset_info(tz, t_gap);
                            let local_sec = t_gap - off_act as i64;
                            let (y2,m2,d2,hh2,mm2,ss2) = unix_to_civil(local_sec);
                            let local_str = format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y2,m2,d2,hh2,mm2,ss2);
                            let off_str = format_offset(off_act);
                            out.push(format!("{} -> GAP {} {}{} {}", line, t_gap, local_str, off_str, abbr));
                            found = true;
                            break;
                        }
                    }
                }
                if !found {
                    // footer start
                    if let (Some(sr), Some(er)) = (&tz.start_rule, &tz.end_rule) {
                        // try years around
                        let year_guess = y;
                        for y_off in -2..=2 {
                            let yr = year_guess + y_off;
                            let start_utc = rule_to_utc(tz, yr, sr, true);
                            let off_before = tz.std_offset;
                            let off_after = tz.dst_offset.unwrap_or(tz.std_offset + 3600);
                            let start_local = start_utc - off_before as i64;
                            let end_local = start_utc - off_after as i64;
                            if local_ts >= start_local && local_ts < end_local {
                                let t_gap = local_ts + off_before as i64;
                                let (off_act, abbr) = get_offset_info(tz, t_gap);
                                let local_sec = t_gap - off_act as i64;
                                let (y2,m2,d2,hh2,mm2,ss2) = unix_to_civil(local_sec);
                                let local_str = format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y2,m2,d2,hh2,mm2,ss2);
                                let off_str = format_offset(off_act);
                                out.push(format!("{} -> GAP {} {}{} {}", line, t_gap, local_str, off_str, abbr));
                                found = true;
                                break;
                            }
                        }
                    }
                }
                if !found {
                    // fallback
                    out.push(format!("{} -> GAP {} {}", line, local_ts, ""));
                }
                continue;
            }
            sols.sort_by_key(|x| x.0);
            if sols.len() == 1 {
                let (t_c, off) = sols[0];
                let (_, abbr) = get_offset_info(tz, t_c);
                let off_str = format_offset(off);
                out.push(format!("{} -> {} {} {}", line, t_c, off_str, abbr));
            } else {
                let mut parts = Vec::new();
                for (t_c, off) in &sols {
                    let (_, abbr) = get_offset_info(tz, *t_c);
                    let off_str = format_offset(*off);
                    parts.push(format!("{} {} {}", t_c, off_str, abbr));
                }
                out.push(format!("{} -> {}", line, parts.join(" | ")));
            }
        }
    }
    for l in out { println!("{}", l); }
}

use std::env;
use std::fs;
use std::path::Path;

#[derive(Clone, Copy, Debug)]
struct Rule {
    month: u8,
    week: u8,
    weekday: u8,
    time_sec: i32,
}

struct TzInfo {
    trans_times: Vec<i64>,
    trans_type_idx: Vec<u8>,
    type_offsets: Vec<i32>,
    type_abbrev: Vec<String>,
    std_offset: i32,
    dst_offset: Option<i32>,
    std_name: String,
    dst_name: Option<String>,
    start_rule: Option<Rule>,
    end_rule: Option<Rule>,
    last_trans: i64,
}

/* ---------- civil <-> unix ---------- */
fn days_from_civil(y: i32, m: u32, d: u32) -> i64 {
    let y = y as i64;
    let m = m as i64;
    let d = d as i64;
    let y_adj = if m <= 2 { y - 1 } else { y };
    let era = if y_adj >= 0 { y_adj } else { y_adj - 399 } / 400;
    let yoe = y_adj - era * 400;
    let doy = (153 * (m + if m > 2 { -3 } else { 9 }) + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}
fn civil_to_unix(y: i32, m: u32, d: u32, hh: u32, mm: u32, ss: u32) -> i64 {
    days_from_civil(y, m, d) * 86400 + hh as i64 * 3600 + mm as i64 * 60 + ss as i64
}
fn civil_from_days(z: i64) -> (i32, u32, u32) {
    let mut z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (yoe * 365 + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = mp + if mp < 10 { 3 } else { -9 };
    let y = y + if m <= 2 { 1 } else { 0 };
    (y as i32, m as u32, d as u32)
}
fn unix_to_civil(ts: i64) -> (i32, u32, u32, u32, u32, u32) {
    let days = ts.div_euclid(86400);
    let secs = ts.rem_euclid(86400) as u64;
    let (y, m, d) = civil_from_days(days);
    let hh = (secs / 3600) as u32;
    let mm = ((secs % 3600) / 60) as u32;
    let ss = (secs % 60) as u32;
    (y, m, d, hh, mm, ss)
}
fn days_in_month(y: i32, m: u32) -> u32 {
    match m {
        1 => 31,
        2 => if (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0) { 29 } else { 28 },
        3 => 31,
        4 => 30,
        5 => 31,
        6 => 30,
        7 => 31,
        8 => 31,
        9 => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _ => 31,
    }
}
fn nth_weekday_day(y: i32, m: u32, week: u8, weekday: u8) -> u32 {
    if week == 5 {
        let last = days_in_month(y, m);
        let days_last = days_from_civil(y, m, last);
        let w_last = ((days_last + 4).rem_euclid(7)) as u8;
        let delta = (w_last as i32 - weekday as i32 + 7).rem_euclid(7) as u32;
        last - delta
    } else {
        let days_first = days_from_civil(y, m, 1);
        let w_first = ((days_first + 4).rem_euclid(7)) as u8;
        let delta = (weekday as i32 - w_first as i32 + 7).rem_euclid(7) as u32;
        1 + delta + (week as u32 - 1) * 7
    }
}
fn rule_to_utc(year: i32, rule: &Rule, offset: i32) -> i64 {
    let day = nth_weekday_day(year, rule.month as u32, rule.week, rule.weekday);
    let local_ts = civil_to_unix(year, rule.month as u32, day, 0, 0, 0) + rule.time_sec as i64;
    local_ts - offset as i64
}
fn format_offset(off: i32) -> String {
    let sign = if off >= 0 { '+' } else { '-' };
    let a = off.abs() as i64;
    let h = a / 3600;
    let m = (a % 3600) / 60;
    let s = a % 60;
    if s != 0 {
        format!("{sign}{h:02}:{m:02}:{s:02}")
    } else {
        format!("{sign}{h:02}:{m:02}")
    }
}

/* ---------- parsing helpers ---------- */
fn parse_name(bytes: &[u8], mut i: usize) -> (String, usize) {
    if bytes[i] == b'<' {
        let start = i + 1;
        while i < bytes.len() && bytes[i] != b'>' { i += 1; }
        let name = String::from_utf8_lossy(&bytes[start..i]).to_string();
        i += 1;
        (name, i)
    } else {
        let start = i;
        while i < bytes.len() && (bytes[i] as char).is_ascii_alphabetic() { i += 1; }
        (String::from_utf8_lossy(&bytes[start..i]).to_string(), i)
    }
}
fn parse_offset_bytes(bytes: &[u8], mut i: usize) -> (i32, usize) {
    let mut sign = 1;
    if bytes[i] == b'+' || bytes[i] == b'-' {
        if bytes[i] == b'-' { sign = -1; }
        i += 1;
    }
    let mut num = String::new();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let h: i64 = num.parse().unwrap_or(0);
    let mut m = 0i64;
    let mut s = 0i64;
    if i < bytes.len() && bytes[i] == b':' {
        i += 1;
        let mut ns = String::new();
        while i < bytes.len() && bytes[i].is_ascii_digit() { ns.push(bytes[i] as char); i += 1; }
        m = ns.parse().unwrap_or(0);
        if i < bytes.len() && bytes[i] == b':' {
            i += 1;
            let mut ns2 = String::new();
            while i < bytes.len() && bytes[i].is_ascii_digit() { ns2.push(bytes[i] as char); i += 1; }
            s = ns2.parse().unwrap_or(0);
        }
    }
    let secs = sign * (h * 3600 + m * 60 + s) as i32;
    (secs, i)
}
fn parse_rule_bytes(bytes: &[u8], mut i: usize) -> (Rule, usize) {
    // M m . w . d [/time]
    i += 1; // M
    let mut num = String::new();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let month = num.parse::<u8>().unwrap();
    i += 1; // .
    num.clear();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let week = num.parse::<u8>().unwrap();
    i += 1; // .
    num.clear();
    while i < bytes.len() && bytes[i].is_ascii_digit() { num.push(bytes[i] as char); i += 1; }
    let weekday = num.parse::<u8>().unwrap();
    let mut time_sec = 2 * 3600;
    if i < bytes.len() && bytes[i] == b'/' {
        i += 1;
        let (off, ni) = parse_offset_bytes(bytes, i);
        time_sec = off;
        i = ni;
    }
    (Rule { month, week, weekday, time_sec }, i)
}
fn parse_posix(s: &str) -> (String, i32, Option<String>, Option<i32>, Option<Rule>, Option<Rule>) {
    let b = s.as_bytes();
    let mut i = 0;
    let (std_name, ni) = parse_name(b, i); i = ni;
    let (std_off_parsed, ni) = parse_offset_bytes(b, i); i = ni;
    let std_off = -std_off_parsed; // local - UTC
    let mut dst_name = None;
    let mut dst_off_parsed = None;
    if i < b.len() {
        let c = b[i];
        if c.is_ascii_alphabetic() || c == b'<' {
            let (name, ni2) = parse_name(b, i); dst_name = Some(name); i = ni2;
            if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
                let (off, ni2) = parse_offset_bytes(b, i); dst_off_parsed = Some(off); i = ni2;
            }
        }
    }
    let dst_off = match dst_off_parsed {
        Some(v) => Some(-v),
        None => if dst_name.is_some() { Some(std_off + 3600) } else { None },
    };
    let mut start_rule = None;
    let mut end_rule = None;
    if i < b.len() && b[i] == b',' {
        i += 1;
        let (r, ni2) = parse_rule_bytes(b, i); start_rule = Some(r); i = ni2;
        if i < b.len() && b[i] == b',' {
            i += 1;
            let (r2, ni2) = parse_rule_bytes(b, i); end_rule = Some(r2); i = ni2;
        }
    }
    (std_name, std_off, dst_name, dst_off, start_rule, end_rule)
}

/* ---------- load tz ---------- */
fn load_tz(path: &Path) -> TzInfo {
    let data = fs::read(path).unwrap();
    let mut positions = Vec::new();
    for i in 0..data.len().saturating_sub(3) {
        if &data[i..i+4] == b"TZif" {
            positions.push(i);
        }
    }
    let hdr = *positions.get(1).unwrap_or(&0);
    let cnt_start = hdr + 20;
    let mut counts = [0i32;6];
    for j in 0..6 {
        counts[j] = i32::from_be_bytes(data[cnt_start + j*4..cnt_start + j*4 +4].try_into().unwrap());
    }
    let timecnt = counts[3] as usize;
    let typecnt = counts[4] as usize;
    let charcnt = counts[5] as usize;
    let mut pos = hdr + 44;
    let mut trans_times = Vec::new();
    for _ in 0..timecnt {
        let v = i64::from_be_bytes(data[pos..pos+8].try_into().unwrap());
        trans_times.push(v);
        pos += 8;
    }
    let mut trans_type = Vec::new();
    for _ in 0..timecnt {
        trans_type.push(data[pos]);
        pos += 1;
    }
    let mut type_offsets = Vec::new();
    let mut type_abbrev_idx = Vec::new();
    for _ in 0..typecnt {
        let offs = i32::from_be_bytes(data[pos..pos+4].try_into().unwrap());
        let abbr = data[pos+5] as usize;
        type_offsets.push(offs);
        type_abbrev_idx.push(abbr);
        pos += 6;
    }
    let abbrev_bytes = &data[pos..pos+charcnt];
    let mut abbrevs = Vec::new();
    let mut i = 0;
    while i < charcnt {
        let start = i;
        while i < charcnt && abbrev_bytes[i] != 0 { i += 1; }
        let s = String::from_utf8_lossy(&abbrev_bytes[start..i]).to_string();
        abbrevs.push(s);
        i += 1;
    }
    pos += charcnt;
    // footer
    let mut foot_start = pos;
    while foot_start < data.len() && data[foot_start] != b'\n' { foot_start += 1; }
    foot_start += 1;
    let mut foot_end = foot_start;
    while foot_end < data.len() && data[foot_end] != b'\n' { foot_end += 1; }
    let tz_str = String::from_utf8_lossy(&data[foot_start..foot_end]).to_string();
    let (std_name, std_off, dst_name_opt, dst_off_opt, start_rule_opt, end_rule_opt) = parse_posix(&tz_str);
    let mut type_abbrev = Vec::new();
    for idx in type_abbrev_idx {
        let s = if idx < abbrevs.len() { abbrevs[idx].clone() } else { String::new() };
        type_abbrev.push(s);
    }
    let last_trans = *trans_times.last().unwrap_or(&i64::MIN);
    TzInfo {
        trans_times,
        trans_type_idx: trans_type,
        type_offsets,
        type_abbrev,
        std_offset: std_off,
        dst_offset: dst_off_opt,
        std_name,
        dst_name: dst_name_opt,
        start_rule: start_rule_opt,
        end_rule: end_rule_opt,
        last_trans,
    }
}

/* ---------- offset lookup ---------- */
fn is_dst_active(tz: &TzInfo, t: i64) -> bool {
    if tz.dst_name.is_none() || tz.start_rule.is_none() || tz.end_rule.is_none() {
        return false;
    }
    let year = unix_to_civil(t).0;
    let std_off = tz.std_offset;
    let dst_off = tz.dst_offset.unwrap_or(std_off + 3600);
    for y in (year - 2)..=(year + 2) {
        let start_utc = rule_to_utc(y, tz.start_rule.as_ref().unwrap(), std_off);
        for ey in [y, y + 1] {
            let end_utc = rule_to_utc(ey, tz.end_rule.as_ref().unwrap(), dst_off);
            if end_utc > start_utc && t >= start_utc && t < end_utc {
                return true;
            }
        }
    }
    false
}
fn get_offset_info(tz: &TzInfo, t: i64) -> (i32, String) {
    if !tz.trans_times.is_empty() {
        if t < tz.trans_times[0] {
            return (tz.type_offsets[0], tz.type_abbrev[0].clone());
        }
        if t <= tz.last_trans {
            let idx = tz.trans_times.partition_point(|&x| x <= t);
            let ti = tz.trans_type_idx[idx - 1] as usize;
            return (tz.type_offsets[ti], tz.type_abbrev[ti].clone());
        }
    }
    // footer
    if tz.dst_name.is_some() && is_dst_active(tz, t) {
        let off = tz.dst_offset.unwrap_or(tz.std_offset + 3600);
        let ab = tz.dst_name.clone().unwrap_or_default();
        return (off, ab);
    }
    (tz.std_offset, tz.std_name.clone())
}

/* ---------- main ---------- */
fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return; }
    let dir = Path::new(&args[1]);
    let queries_path = dir.join("queries.txt");
    let queries = fs::read_to_string(&queries_path).unwrap();
    let mut tz_map = std::collections::HashMap::new();
    for entry in fs::read_dir(dir).unwrap() {
        let p = entry.unwrap().path();
        if let Some(name) = p.file_name().and_then(|s| s.to_str()) {
            if name.ends_with(".tzif") {
                let tz = load_tz(&p);
                tz_map.insert(name.to_string(), tz);
            }
        }
    }
    let mut out = Vec::new();
    for line in queries.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        let parts: Vec<&str> = line.split_whitespace().collect();
        let qtype = parts[0];
        let file = parts[1];
        let rest = parts[2..].join(" ");
        let tz = tz_map.get(file).expect("tz missing");
        if qtype == "UTC" {
            let t: i64 = rest.parse().unwrap();
            let (off, abbr) = get_offset_info(tz, t);
            let local_sec = t + off as i64;
            let (y,m,d,hh,mm,ss) = unix_to_civil(local_sec);
            let local_str = format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y,m,d,hh,mm,ss);
            let off_str = format_offset(off);
            out.push(format!("{} -> {}{} {}", line, local_str, off_str, abbr));
        } else {
            // LOCAL
            let s = rest;
            let date = &s[0..10];
            let time = &s[11..19];
            let y: i32 = date[0..4].parse().unwrap();
            let m: u32 = date[5..7].parse().unwrap();
            let d: u32 = date[8..10].parse().unwrap();
            let hh: u32 = time[0..2].parse().unwrap();
            let mm: u32 = time[3..5].parse().unwrap();
            let ss: u32 = time[6..8].parse().unwrap();
            let local_ts = civil_to_unix(y,m,d,hh,mm,ss);
            let mut cand_offsets = Vec::new();
            cand_offsets.extend(tz.type_offsets.iter().cloned());
            cand_offsets.push(tz.std_offset);
            if let Some(doff) = tz.dst_offset { cand_offsets.push(doff); }
            cand_offsets.sort();
            cand_offsets.dedup();
            let mut sols = Vec::new();
            for &off in &cand_offsets {
                let t_candidate = local_ts - off as i64;
                let (off2, _) = get_offset_info(tz, t_candidate);
                if off2 == off {
                    sols.push((t_candidate, off));
                }
            }
            if !sols.is_empty() {
                sols.sort_by_key(|x| x.0);
                sols.dedup_by_key(|x| x.0);
                if sols.len() == 1 {
                    let (t_c, off) = sols[0];
                    let (_, abbr) = get_offset_info(tz, t_c);
                    let off_str = format_offset(off);
                    out.push(format!("{} -> {} {} {}", line, t_c, off_str, abbr));
                } else {
                    let mut parts_out = Vec::new();
                    for (t_c, off) in &sols {
                        let (_, abbr) = get_offset_info(tz, *t_c);
                        let off_str = format_offset(*off);
                        parts_out.push(format!("{} {} {}", t_c, off_str, abbr));
                    }
                    out.push(format!("{} -> {}", line, parts_out.join(" | ")));
                }
                continue;
            }
            // gap detection
            let mut gap_found = false;
            // check tzif transitions
            for i in 0..tz.trans_times.len() {
                let t_trans = tz.trans_times[i];
                let old_type = if i == 0 { 0 } else { tz.trans_type_idx[i-1] as usize };
                let new_type = tz.trans_type_idx[i] as usize;
                let old_off = tz.type_offsets[old_type];
                let new_off = tz.type_offsets[new_type];
                if new_off > old_off {
                    let start_local = t_trans + old_off as i64;
                    let end_local = t_trans + new_off as i64;
                    if local_ts > start_local && local_ts < end_local {
                        let t_gap = local_ts - old_off as i64;
                        let (off_act, abbr) = get_offset_info(tz, t_gap);
                        let local_sec2 = t_gap + off_act as i64;
                        let (y2,m2,d2,hh2,mm2,ss2) = unix_to_civil(local_sec2);
                        let local_str = format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y2,m2,d2,hh2,mm2,ss2);
                        let off_str = format_offset(off_act);
                        out.push(format!("{} -> GAP {} {}{} {}", line, t_gap, local_str, off_str, abbr));
                        gap_found = true;
                        break;
                    }
                }
            }
            if !gap_found && tz.start_rule.is_some() {
                let year_guess = y;
                let std_off = tz.std_offset;
                let dst_off = tz.dst_offset.unwrap_or(std_off + 3600);
                for y_off in -2..=2 {
                    let yr = year_guess + y_off;
                    if let Some(sr) = &tz.start_rule {
                        let start_utc = rule_to_utc(yr, sr, std_off);
                        let old_off = std_off;
                        let new_off = dst_off;
                        if new_off > old_off {
                            let start_local = start_utc + old_off as i64;
                            let end_local = start_utc + new_off as i64;
                            if local_ts > start_local && local_ts < end_local {
                                let t_gap = local_ts - old_off as i64;
                                let (off_act, abbr) = get_offset_info(tz, t_gap);
                                let local_sec2 = t_gap + off_act as i64;
                                let (y2,m2,d2,hh2,mm2,ss2) = unix_to_civil(local_sec2);
                                let local_str = format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y2,m2,d2,hh2,mm2,ss2);
                                let off_str = format_offset(off_act);
                                out.push(format!("{} -> GAP {} {}{} {}", line, t_gap, local_str, off_str, abbr));
                                gap_found = true;
                                break;
                            }
                        }
                    }
                }
            }
            if !gap_found {
                out.push(format!("{} -> GAP {} {}", line, local_ts, ""));
            }
        }
    }
    for l in out { println!("{}", l); }
}
